QuestTraduttoreQuestIT = QuestTraduttoreQuestIT or {}
local T = QuestTraduttoreQuestIT

T[2] = {
  title = "Artiglio di Sharptalon",
  desc = "Il possente ippogrifo Sharptalon è stato ucciso, e l'artiglio della bestia abbattuta è la testimonianza della tua vittoria. Senani Thunderheart, all'Avamposto di Splintertree, sarà senza dubbio interessata a vedere questo trofeo come prova delle tue imprese.",
  obj = "Porta Sharptalon's Claw a Senani Thunderheart, all'Avamposto di Splintertree, in Ashenvale.",
  progress = "Sì, possente $C, ho percepito il tuo arrivo. Immagino che tu abbia altre notizie da riferirmi sulla tua caccia?",
  reward = "Davvero notevole, $N... l'artiglio di Sharptalon non dev'essere stato facile da ottenere! La Caccia di Ashenvale ti sta andando bene!$B$BDa tempo Sharptalon terrorizzava i peoni degli accampamenti di taglialegna vicini al suo percorso, quando cercavano di arrivare fin qui all'Avamposto di Splintertree. Non appena si saprà che sei $Gstato:stata; tu ad abbattere la bestia, di sicuro attorno ai fuochi e nelle segherie di tutta Ashenvale risuoneranno molti canti trascinanti sul tuo coraggio!",
  en_title = "Sharptalon's Claw",
  en_obj = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[10] = {
  title = "La Redenzione di Scrimshank",
  desc = "Oh, è una cosa terribile! Ho mandato il mio miglior assistente, l'Aiuto Topografo Scrimshank, nel deserto a sud-est di qui. È una zona che chiamiamo Abisso Golaperta. Be', è scomparso, e il suo ultimo rapporto parlava di altri di quegli strani insetti lì dov'era lui. Possibile che ormai abbiano infestato due grandi regioni del deserto?$B$BHo bisogno che tu vada nell'Abisso Golaperta a cercare Scrimshank, per favore! Oppure... trova almeno la sua attrezzatura da topografo. Temo che del poveraccio non sia rimasto altro.",
  obj = "Scopri che fine ha fatto Junior Surveyor Scrimshank e porta lui o la sua attrezzatura da topografo a Senior Surveyor Fizzledowser a Gadgetzan.",
  progress = "Allora, che notizie mi porti? Hai l'aria di chi ha affrontato una bella battaglia... Scrimshank è vivo?",
  reward = "Era un bravo goblin, il giovane Scrimshank. Speriamo che, per quello che è riuscito a registrare con la sua attrezzatura da topografo, non sia morto invano.$B$BA quanto pare, con questi insetti abbiamo per le mani una bella grana. Sono fin troppo astuti, e le ricerche fatte finora sembrano indicare che potrebbero addirittura essere sotto il controllo di terzi! Se è così, allora si mette male non solo per Gadgetzan, ma per tutto il deserto!",
}
T[17] = {
  title = "Reagenti da Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, i cappelli di fungo magenta. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.$B$BTrova i grappoli di cappelli magenta e portamene una dozzina. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.$B$BFallo per me, e ti preparerò al volo una dose di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Cap a Ghak Healtouch, a Thelsamar.",
  progress = "Ti sei $Gprocurato:procurata; i cappelli di fungo magenta che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!",
  reward = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! Studiare questi cappelli sarà interessante, puoi giurarci!$B$BE ora, come promesso, goditi un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...$B$BSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.",
}
T[19] = {
  title = "Tharil'zun",
  desc = "I Blackrock Outrunners e Renegades tendono imboscate tra qui e il Mastio di Stonewatch. Il capo degli Outrunners è un orco di nome Tharil'zun — quell'orco lo vogliamo. Portami la testa di Tharil'zun!",
  obj = "Porta Tharil'zun's Head a Marshal Marris, a Redridge.",
  progress = "La pressione degli orchi di Blackrock è sempre alta. Ma almeno ci hai liberati di Tharil'zun?",
  reward = "Tharil'zun era un orco feroce e astuto. Ben fatto — di sicuro non è stato facile abbatterlo. Ecco la tua ricompensa, $N.",
  en_title = "Tharil'zun",
  en_obj = "Bring Tharil'zun's Head to Marshal Marris in Redridge.",
}
T[20] = {
  title = "La Minaccia Blackrock",
  desc = "Gli orchi Blackrock sono arrivati dalle Burning Steppes e hanno occupato il Mastio di Stonewatch, a nord. Da lì saccheggiano le zone a nord di Lakeshire e costringono i cittadini a restare in paese, chiusi come bestie in un recinto.$B$BAiutaci a liberare Lakeshire da questa minaccia. Uccidi questi orchi Blackrock e portami dieci delle loro Asce Usurate come prova.$B$BI Blackrock ci minacciano da nord, ma ci sono arrivate segnalazioni di altri orchi nell'angolo sud-orientale di Redridge. Se ne trovi laggiù, da' la caccia anche a loro.",
  obj = "Porta 10 Battleworn Axe a Marshal Marris, a Lakeshire.",
  progress = "Hai ucciso degli orchi, $N? Se è così, fammi vedere...",
  reward = "Sono un bel po' di orchi in meno di cui preoccuparsi, grazie.",
  en_title = "Blackrock Menace",
  en_obj = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.",
}
T[23] = {
  title = "La Zampa di Ursangous",
  desc = "La zampa del possente orso Ursangous è il tuo trofeo per questa parte della Caccia di Ashenvale. Sulla zampa c'è un piccolo emblema a quarto di luna; il significato dell'emblema resta un mistero.$B$BLa zampa va portata a Senani Thunderheart all'Avamposto di Splintertree, per dimostrare che hai battuto la possente creatura e completato questa parte della caccia.",
  obj = "Porta Ursangous's Paw a Senani Thunderheart all'Avamposto di Splintertree, in Ashenvale.",
  progress = "Ah — $N — stavo giusto pensando a te! Come va la caccia?",
  reward = "Ah, la zampa di Ursangous! La tua abilità è notevole, $C; ha fatto molte vittime. La mezzaluna sulla sua zampa è senza dubbio il segno che era stato addestrato dagli elfi della notte che si aggirano furtivi per Ashenvale. Ursangous è... era uno degli orsi più possenti che si potessero trovare da queste parti. Aver battuto una creatura simile è la prova della tua volontà e della tua determinazione.$B$BI tuoi antenati ne sarebbero fieri!",
  en_title = "Ursangous's Paw",
  en_obj = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[24] = {
  title = "Testa di Shadumbra",
  desc = "Shadumbra, un tempo veloce, ora giace immobile mentre rivendichi la vittoria su di lei. La testa della nightsaber uccisa è un degno trofeo per questo scontro della Caccia di Ashenvale. Senani Thunderheart, all'Avamposto di Splintertree, vorrà vedere un trofeo simile per riconoscerti il merito di questa parte della Caccia di Ashenvale.",
  obj = "Porta Shadumbra's Head a Senani Thunderheart all'Avamposto di Splintertree, in Ashenvale.",
  progress = "Ben $Gritrovato:ritrovata;, $N! Sei $Gvenuto:venuta; a mostrarmi le prove della tua caccia?",
  reward = "Una vittoria per $N nella Caccia di Ashenvale! Ben fatto — la testa di Shadumbra è senza dubbio un degno trofeo per uno scontro così notevole.$B$BLa ferocia di Shadumbra era nota in tutto l'avamposto. Ogni viaggio verso ovest, soprattutto a piedi per raggiungere la Spiaggia di Zoram, era pieno di pericoli a causa di quella tigre. Grazie a te, il pericolo è diminuito.",
  en_title = "Shadumbra's Head",
  en_obj = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[25] = {
  title = "Stallo a Stonetalon",
  desc = "Se vuoi renderti utile, perché non fai qualcosa per la situazione vicino al Sentiero di Talondeep?$B$BI trasporti tra Ashenvale e Stonetalon sono fermi perché il lago si è animato e attacca tutto ciò che gli si avvicina... cioè chiunque passi sul sentiero. Dare una bella batosta agli elementali dell'acqua va bene, ma sarebbe ancora più utile se qualcuno andasse in ricognizione al gazebo sul Lago Mystral — quello da cui si vede bene l'avamposto dell'Alleanza.$B$BTe la senti di renderti utile?",
  obj = "Elimina 12 Befouled Water Elemental al Lago Mystral, dritto a est del Sentiero di Talondeep e a sud-ovest dell'Avamposto di Splintertree.$B$BVa' a dare un'occhiata al gazebo sul Lago Mystral, quello che domina l'avamposto dell'Alleanza lì vicino.$B$BTorna da Mastok Wrilehiss all'Avamposto di Splintertree, in Ashenvale.",
  progress = "Già di ritorno? Com'è la situazione là fuori — tutto sistemato, grazie a te?",
  reward = "Già, ho sentito che qualcuno ha messo a soqquadro quel lago come un turbine di polvere che attraversa le Barrens. E da quel che si dice, forse potremmo allestire là fuori un punto d'osservazione per tenere d'occhio i nostri amici dell'Alleanza. Sempre che riusciamo a tenerlo nascosto...$B$BSembra che alla fine ti sia $Greso:resa; parecchio utile; i trasporti tra qui e Stonetalon dovrebbero avere vita più facile. Prendi questo — te lo meriti.",
  en_title = "Stonetalon Standstill",
  en_obj = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.$B$BScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.$B$BReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[26] = {
  title = "Una Lezione da Imparare",
  desc = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.$B$BÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "Salute a te, giovane $Gdruido:druida;; è giunto il momento che tu conosca la nostra forma acquatica. Ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.$B$BDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.$B$BTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[27] = {
  title = "Una Lezione da Imparare",
  desc = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.$B$BÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "Salute a te, giovane $Gdruido:druida;; è giunto il momento che tu conosca la nostra forma acquatica. Ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.$B$BDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.$B$BTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[28] = {
  title = "Prova del Lago",
  desc = "Per la tua prima prova, cerca nelle profondità del Lago Elune'ara una Bolla del Santuario. Si deteriora in fretta, quindi portala subito al Santuario di Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.$B$BHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.$B$BBuona fortuna, $N.",
  obj = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.$B$BPoi, per completare la prova, devi parlare con Tajarri al santuario.",
  progress = "Per completare la Prova del Lago devi usare la Bolla del Santuario entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.",
  reward = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Il Custode Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[29] = {
  title = "Prova del Lago",
  desc = "Per la tua prima prova, cerca nelle profondità del Lago Elune'ara una Bolla del Santuario. Si deteriora in fretta, quindi portala subito al Santuario di Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.$B$BHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.$B$BBuona fortuna, $N.",
  obj = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.$B$BPoi, per completare la prova, devi parlare con Tajarri al santuario.",
  progress = "Per completare la Prova del Lago devi usare la Bolla del Santuario entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.",
  reward = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Il Custode Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[30] = {
  title = "Prova del Leone Marino",
  desc = "Per la seconda prova ti serviranno le due metà che formano il Pendente del Leone Marino. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a tutte e due queste qualità per incarnare l'aspetto della loro forma acquatica.$B$BParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.$B$BForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino al Santuario di Remulos.$B$BPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.",
  progress = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai completato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.$B$BRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua forma acquatica.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[31] = {
  title = "Aquatic Form",
  desc = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Turak Runetotem, a Thunder Bluff. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.$B$BArrivederci, giovane $Gdruido:druida;. Parleremo ancora.",
  obj = "Torna a Thunder Bluff e mostra il Pendant of the Sea Lion a Turak Runetotem.",
  progress = "La notizia del tuo ritorno a Thunder Bluff ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua forma acquatica.$B$BHai il Pendente del Leone Marino?",
  reward = "Davvero notevole, $N. I tuoi antenati sarebbero fieri dei tuoi progressi! Sei $Gpronto:pronta; a imparare la tua forma acquatica, ed è un piacere per me insegnartela.$B$BInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.",
}
T[32] = {
  title = "L'Ascesa dei Silithid",
  desc = "Ecco il tuo rapporto. Ti consiglio vivamente di portarlo a qualcuno che di queste cose abbia una conoscenza pratica.$B$BConosco uno studioso troll, un certo Zilzibin Drumlore. Ha passato molto tempo a studiare le forme di vita che appartengono solo all'ecologia di Azeroth; e per giunta è uno storico! Se vuoi qualcuno che ti aiuti a capire cos'è esattamente questa minaccia e come fermarla, dai questo rapporto a lui. Avremo bisogno di tutto l'aiuto possibile.$B$BZil abita in una casa al secondo livello del Corso, a Orgrimmar.",
  obj = "Porta l'Insect Analysis Report a Zilzibin Drumlore a Orgrimmar.",
  progress = "Mi dispiace, non ti conosco... ma a quanto vedo tu almeno hai sentito parlare di me. Allora, in cosa posso aiutarti? Hai qualcosa per me?",
  reward = "Questo rapporto... ho già avuto a che fare con queste bestie. Fizzledowser è stato saggio a mandare questo rapporto, e te, da me.$B$BQueste creature divoreranno in fretta il deserto di Tanaris; sono niente meno che uno dei pericoli più grandi che tutti noi dovremo mai affrontare. Impara bene questo nome, $N: silithid. Gli insetti di cui si parla qui sono i silithid, e sono gli strumenti di una delle più gravi minacce che incombono tanto sull'Orda quanto sull'Alleanza.$B$BSe solo fossimo stati abbastanza svegli da capirlo prima.",
}
T[34] = {
  title = "Un Ospite Sgradito",
  desc = "Un'altra volta il mio giardino è stato calpestato e saccheggiato. E so bene chi è il bruto che lo fa. È quel maledetto cinghiale, quello che il Maresciallo Marris ha preso a chiamare Mangiabulbi.$B$BAdesso non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutti rovinati da quel solo cinghiale minaccioso. Metti fine a quella peste! Mostrami la sua zanna e ti ricompenserò volentieri. Sembra che passi il tempo a grufolare nel campo a sud-ovest di Lakeshire, ma ogni tanto se ne viene fin qui e mi entra in giardino.",
  obj = "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.",
  progress = "Mangiabulbi ne combina ancora delle sue, o sei $Griuscito:riuscita; a liberare Lakeshire da quella peste una volta per tutte?",
  reward = "Finalmente la minaccia è sepolta! Grazie, $N, mi hai reso un gran servizio. Questa stagione il giardino sarà in piena fioritura!",
  en_title = "An Unwelcome Guest",
  en_obj = "Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.",
}
T[48] = {
  title = "Dolce Ambra",
  desc = "Nella terra a sud, dove le liane si torcono e strisciano,$Bc'è un pozzo nascosto, dove acque profonde scorrono.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Acqua Sorgiva Sacra.",
  obj = "Porta dell'Holy Spring Water a Grimbooze Thunderbrew.",
  progress = "Hic! Ah ah! Vuoi il bis?$B$BNella terra a sud, dove le liane si torcono e strisciano,$Bc'è un pozzo nascosto, dove acque profonde scorrono.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Acqua Sorgiva Sacra.",
  reward = "Hic! Ah ah!",
  en_title = "Sweet Amber",
  en_obj = "Bring Holy Spring Water to Grimbooze Thunderbrew.",
}
T[49] = {
  title = "Dolce Ambra",
  desc = "L'ambra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  obj = "Grimbooze Thunderbrew vuole un Sack of Barley, un Sack of Rye e un Sack of Corn.",
  progress = "Un bis? Ma certo!$B$BL'ambra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  reward = "Hic! Ah ah!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.",
}
T[50] = {
  title = "Dolce Ambra",
  desc = "Mescolerò e mescolerò finché avremo il mosto,$Be sarà la nostra scorta privata, ben nascosta.$BUn alambicco va forgiato con un metallo forte:$Bportami del Truesilver per finire questa canzone.",
  obj = "Grimbooze Thunderbrew vuole del Truesilver.",
  progress = "Un bis per te? Ma certo, $Gamico:amica;!$B$BMescolerò e mescolerò finché avremo il mosto,$Be sarà la nostra scorta privata, ben nascosta.$BUn alambicco va forgiato con un metallo forte:$Bportami del Truesilver per finire questa canzone.",
  reward = "Hic! Ah ah!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants Truesilver.",
}
T[51] = {
  title = "Dolce Ambra",
  desc = "Non ancora filtrato, ma appena distillato,$Bcome terra non seminata che attende, già arata.$BOra preparerò il nostro mucchio di carbone:$Bportami un ramo di sicomoro, è la tua prossima missione.",
  obj = "Porta un Sycamore Branch a Grimbooze Thunderbrew.",
  progress = "Un bis? Per te, questo e altro!$B$BNon ancora filtrato, ma appena distillato,$Bcome terra non seminata che attende, già arata.$BOra preparerò il nostro mucchio di carbone:$Bportami un ramo di sicomoro, è la tua prossima missione.",
  reward = "Hic! Ah ah!",
  en_title = "Sweet Amber",
  en_obj = "Bring a Sycamore Branch to Grimbooze Thunderbrew.",
}
T[53] = {
  title = "Dolce Ambra",
  desc = "Un liquido dolce, limpido come le lacrime di un bambino,$Bcol passare degli anni prende un bel colore d'ambra profondo.$BMa prima di ubriacarci fino in fondo,$Bva costruita una botte di quercia carbonizzata.",
  obj = "Porta a Grimbooze Thunderbrew un Bundle of Charred Oak.",
  progress = "Certo che te la ricanto, $Gamico:amica;!$B$BUn liquido dolce, limpido come le lacrime di un bambino,$Bcol passare degli anni prende un bel colore d'ambra profondo.$BMa prima di ubriacarci fino in fondo,$Bva costruita una botte di quercia carbonizzata.",
  reward = "Invecchiato nella botte, filtrato nel carbone,$Bti passa sulle labbra e dritto nell'anima scende.$BAllora beviamo, facciamo un brindisi a te,$Be già che ci siamo a me, Grimbooze Thunderbrew!",
  en_title = "Sweet Amber",
  en_obj = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.",
}
T[55] = {
  title = "Morbent Fel",
  desc = "Morbent Fel si nasconde nella sua tana, la casa appollaiata in cima alla collina a est, che domina il cimitero di Raven Hill. Il suo tempo in questa terra sta per finire...$B$BUsa l'Anatema di Morbent contro di lui. Annullerà le sue magie protettive.$B$BUccidilo. Uccidilo, e salvaci dalla sua malvagità. Sii lo strumento della mia vendetta, e $Gun eroe:un'eroina; di Duskwood!",
  obj = "Usa Morbent's Bane su Morbent Fel, uccidi Morbent Fel, poi riporta Morbent's Bane a Sven, al suo accampamento.",
  progress = "Morbent Fel è stato sconfitto?!",
  reward = "Morbent Fel è stato sconfitto. I cavalieri oscuri sono ancora in libertà, ma una piccola parte di quel che speravo contro ogni speranza si è avverata.$B$BHai fatto l'impossibile, e le tue imprese vivranno per sempre nelle leggende di Duskwood.$B$BVa', $N. E forse, un giorno, il destino ti riporterà da me...",
  en_title = "Morbent Fel",
  en_obj = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.",
}
T[56] = {
  title = "I Guardiani della Notte",
  desc = "Come Comandante dei Guardiani della Notte, ho giurato di proteggere i cittadini di Darkshire. Stormwind ha ritirato le guardie che aveva di stanza qui, lasciandoci a cavarcela da soli.$B$BSe ti senti all'altezza del compito, ci serve il tuo aiuto! Aiuta i Guardiani della Notte addentrandoti nei Giardini Tranquilli, appena a sud di Darkshire, e uccidendo 8 Guerrieri Scheletrici e 6 Maghi Scheletrici. La minaccia dei non morti va fermata!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 8 Skeletal Warrior e 6 Skeletal Mage.",
  progress = "Vedo che sei $Gtornato:tornata;, $N. Se vuoi dimostrare di essere utile ai Guardiani della Notte, torna da me quando avrai ucciso 8 Guerrieri Scheletrici e 6 Maghi Scheletrici.",
  reward = "Ottimo, $N. Per il servizio reso alla gente di Darkshire sarai $Gricompensato:ricompensata;.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.",
}
T[57] = {
  title = "I Guardiani della Notte",
  desc = "$N, mi arrivano segnalazioni di un'infestazione di non morti nella foresta! Se te la senti, va' al cimitero di Raven Hill e uccidi 15 di quegli immondi Demoni Scheletrici e 15 Orrori Scheletrici. Ci sono segnalazioni di scheletri anche appena a sud di Darkshire, nel Cimitero Parcosereno e nei dintorni. I non morti vanno cacciati da Duskwood!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 15 Skeletal Fiend e 15 Skeletal Horror.",
  progress = "Torna da me quando avrai ucciso 15 Demoni Scheletrici e 15 Orrori Scheletrici, $N.",
  reward = "La gente di Darkshire ti ringrazia, $N. Hai dimostrato di essere $Gun grande alleato:una grande alleata; dei Guardiani della Notte.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.",
}
T[58] = {
  title = "I Guardiani della Notte",
  desc = "La situazione a Raven Hill è ancora grave. La sicurezza di Darkshire è nelle tue mani, $N. Non ho abbastanza Watcher per tenere il paese al sicuro. Abbiamo bisogno che tu parta ancora una volta per Raven Hill e liberi il mausoleo orientale da 20 Spargipiaga!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 20 Plague Spreader nel mausoleo orientale di Raven Hill.",
  progress = "Mi serve il tuo aiuto, $N. Va' al cimitero a nord-ovest e libera il mausoleo orientale da 20 Spargipiaga.$B$BTorna da me quando avrai finito.",
  reward = "A nome della gente di Darkshire e come Capo dei Guardiani della Notte, ti ringrazio, $N, per il tuo coraggio e la tua dedizione. Che la Luce illumini il tuo cammino.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.",
}
T[63] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Lungo la costa di Silverpine, a ovest del Sepulcher, troverai un santuario che la piaga ha corrotto. Gli spiriti del luogo non parlano più al nostro popolo, e toccherà a te sconfiggere la manifestazione e purificare la pozza.$B$BPrendi i bracciali dell'elementale, insieme alle gocce rimaste della pozione di Brine, e mettili sul braciere. Il rituale dovrebbe bastare a evocare uno spirito puro con cui potrai comunicare.$B$BPortami la prova che il compito è stato svolto, e ti ricompenserò con il tuo totem.",
  obj = "Sconfiggi la Corrupt Manifestation of Water e metti i Corrupt Manifestation's Bracers insieme alle Remaining Drops of Purest Water sul Brazier of Everfount, nella Silverpine Forest.",
  progress = "Il braciere riflette ancora la luce dei dintorni, e la fiamma si sposta leggermente mentre ti avvicini.$B$BLa corruzione sulle colline sembra essersi tenuta a distanza, e a parte i componenti mancanti il braciere sembra pronto per il rituale che evocherà una manifestazione purificata dell'acqua.",
  reward = "Metti i bracciali sul braciere, poi versi nella fiamma le gocce rimaste della pozione di Brine. Le gocce crepitano quando toccano la fiamma, e cominci a recitare le semplici parole che ti ha insegnato Islen...",
  en_title = "Call of Water",
  en_obj = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.",
}
T[66] = {
  title = "La Leggenda di Stalvan",
  desc = "Ieri notte un orribile turbamento mi ha attraversato le vene. Ho sentito che mia nipote, Alyssa, era in grave pericolo. Ho consultato le carte e la Morte mi ha fissata dal tavolo.$B$BDopo un lungo viaggio in una trance oscura sono riuscita a scoprire un indizio su questo mistero terrificante. Mi è giunto un nome, il nome di Stalvan.$B$BCerca il Cancelliere al Municipio e vedi se riesci a scoprire di più su questo personaggio. Temo per tutti noi.",
  obj = "Cerca Clerk Daltry al Municipio di Darkshire.",
  reward = "Ah, quindi ti manda Madame Eva. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Seek out the Clerk Daltry in the Darkshire Town Hall.",
}
T[67] = {
  title = "La Leggenda di Stalvan",
  desc = "Stalvan, eh? Fammi controllare il registro del paese.$B$BStalvan. . .Stalvan. . .vediamo. Ah, eccolo! Ho la scheda di un certo Stalvan Mistmantle. L'ultimo indirizzo registrato è la Scuola di Moonbrook. Accidenti, è proprio roba vecchia!$B$BMi fai un favore, $Gamico:amica;? Se ti capita di andare a Moonbrook, fammi sapere se trovi qualcosa di nuovo su questo tizio. Mi piace tenere le schede in ordine.",
  obj = "Va' alla Scuola di Moonbrook e riporta a Clerk Daltry ogni informazione aggiornata su Stalvan.",
  reward = "Il vecchio baule cigola mentre si apre. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.",
}
T[68] = {
  title = "La Leggenda di Stalvan",
  desc = "Nel vecchio baule trovi una Lettera Polverosa Mai Spedita.",
  obj = "Porta la Dusty Unsent Letter a Clerk Daltry.",
  progress = "Ah, mi ricordo di te. Sei $Gquello:quella; che chiedeva di quel tale Stalvan. L'hai poi trovato quel che cercavi?",
  reward = "Interessante. Quindi quel tipo a Moonbrook ci ha passato davvero un po' di tempo. È piuttosto strano che la lettera non sia mai stata consegnata. In ogni caso, aggiorno il registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Dusty Unsent Letter to Clerk Daltry.",
}
T[69] = {
  title = "La Leggenda di Stalvan",
  desc = "Oh cielo! Dev'essermi sfuggito la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo a metà. Sembra che fosse diretto alla Lion's Pride Inn, a Goldshire. Faresti bene a controllare là, $N.",
  obj = "Va' a Lion's Pride Inn e vedi se lì qualcuno ha sentito il nome Stalvan.",
  reward = "Stalvan? Mi dice proprio qualcosa.",
  en_title = "The Legend of Stalvan",
  en_obj = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.",
}
T[70] = {
  title = "La Leggenda di Stalvan",
  desc = "Il nome Stalvan mi dice qualcosa. Ora ricordo.$B$BMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di un riparo per la notte. Verso lo scoccare della mezzanotte l'uomo scese di corsa le scale urlando, il volto pallido di paura. Ancora in camicia da notte, sparì nel diluvio.$B$BNella fretta dimenticò le sue lettere nella cassa al piano di sopra. Non tornò mai a riprenderle. Ne resta una di quel tale Stalvan, indirizzata al Distretto dei Canali di Stormwind. Serviti pure.",
  obj = "Recupera Stalvan's Undelivered Letter dalla cassa e consegnala a Canal District, a Stormwind.",
  progress = "Che c'hai lì? Fammi dare un'occhiata. . .",
  reward = "Hai un bel coraggio a portare questa roba qui.",
  en_title = "The Legend of Stalvan",
  en_obj = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.",
}
T[72] = {
  title = "La Leggenda di Stalvan",
  desc = "Mio padre è stato il custode della tenuta molto prima di me. È toccato a lui pulire il sangue dopo il massacro. Ma questo non c'entra.$B$BGli ultimi fondi del patrimonio dei Flintridge si sono prosciugati. Ora anche le ultime cose di famiglia finiscono all'asta. Colpa degli avvoltoi del fisco. Se proprio muori dalla voglia di saperne di più, immagino che tu sia $Glibero:libera; di frugare in questa roba. Chissà cosa potresti trovare.",
  obj = "Fruga tra le cose imballate in cerca di un indizio.",
  reward = "Fai scivolare via piano il coperchio della cassa. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Search through the packed up possessions for a clue.",
}
T[74] = {
  title = "La Leggenda di Stalvan",
  desc = "Dentro la cassa trovi oggetti di ogni tipo: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni libri vecchi. Quasi in fondo, sotto un vaso di ceramica, scopri una Pagina di Diario Stracciata.",
  obj = "La Torn Journal Page che hai scoperto ti dà il prossimo indizio.",
  progress = "Cos'hai lì? Non ci vedo. Ho la vista molto debole. Mettimela tra le mani.",
  reward = "Riesco a malapena a distinguere quelle lettere. Ma quella calligrafia mi ricorda qualcosa che ho visto una volta, prima che la mia vista si facesse così debole.",
  en_title = "The Legend of Stalvan",
  en_obj = "The Torn Journal page you discovered provides your next clue.",
}
T[75] = {
  title = "La Leggenda di Stalvan",
  desc = "Quando sono venuto a stare qui, nella cassa al piano di sopra c'era un fascio di pergamene. Le ho guardate una volta appena arrivato, ma ho lasciato perdere quando la nebbia mi è calata sugli occhi.$B$BFa' un favore a un vecchio quasi cieco e controlla la cassa di sopra: magari c'è qualcosa che ti aiuta a scoprire di più su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.",
  obj = "Marshal Haggard vuole che tu controlli la cassa di sopra per trovare la Faded Journal Page.",
  progress = "L'hai trovata quella pagina di cui ti ho parlato, $N?",
  reward = "L'hai trovata!",
  en_title = "The Legend of Stalvan",
  en_obj = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.",
}
T[77] = {
  title = "Una Situazione Appiccicosa",
  desc = "Possiedo gli imballaggi originali per il vino che cerca Dran Droffers. Ti aiuterò a confezionare il vino per lo scontroso padre di Malton... al prezzo di altre due bottiglie del suddetto vino. Si trovano in alcune casse nella base abbandonata dell'Orda vicino al Tumulo Strisciante.$B$BSarà un compito arduo, vale a dire; troverai sostanze viscide e melme immonde appiccicate alle rovine; si dice che le guidi una sorta di melma suprema. In ogni caso, procurati il vino e torna qui da me per l'imballaggio.",
  obj = "Recupera 10 bottiglie di Hinterlands Honey Ripple dalle casse sparse intorno alla base abbandonata dell'Orda a Skulk Rock.",
  progress = "Confido che tu sia $Ggiunto:giunta; qui al nostro accampamento per consegnare le bottiglie di vino indispensabili al compito che ci attende, giusto?",
  reward = "Eseguito egregiamente, $N. Sono lieto che tu abbia avuto la lungimiranza di non rovinare la delicatezza del vino. Non c'è niente di peggio del bouquet di un vino sballottato senza motivo.$B$BCi vorrà un momento perché la magia si compia su questo prezioso carico. A dire il vero, non c'entra nessuna magia; ho soltanto degli imballaggi vuoti di Vino Dolce degli Hinterlands. Il nostro inganno trasformerà queste bottiglie in un tesoro alcolico senza tempo.$B$BAvanti — alla gloria del buon bere!",
}
T[78] = {
  title = "La Leggenda di Stalvan",
  desc = "Conosco qualcuno che potrebbe darti una mano. Ai tempi in cui guidavo la Guardia di Stormwind, andavamo a bere alla Scarlet Raven Tavern di Darkshire. Il Locandiere del posto, Smitts, era un vero esperto delle leggende locali. Mostragli questa pagina e senti cos'ha da dire.",
  obj = "Porta la Faded Journal Page a Tavernkeep Smitts.",
  progress = "Ti manda il Maresciallo Haggard? E dirlo subito, no?$B$BAh, il buon vecchio Haggard. Povero diavolo, fra non molto sarà cieco del tutto. Comunque, fammi vedere cos'hai lì.",
  reward = "Per la Luce! Eccome se la riconosco, quella calligrafia.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Faded Journal Page to Tavernkeep Smitts.",
}
T[79] = {
  title = "La Leggenda di Stalvan",
  desc = "Ho seguito per anni la leggenda di quel tale Stalvan. Quando, qualche anno fa, hanno massacrato quei nobili in visita, sono andato a indagare insieme a Haggard. Ho trovato queste pagine infangate, ma non siamo mai riusciti a collegare la calligrafia a quel pazzo nel bosco. Le prove che hai raccolto dimostrano la sua colpa. Porta subito questa pagina alla Comandante Ebonlocke e raccontale quello che hai scoperto!",
  obj = "Porta la pagina infangata a Commander Ebonlocke.",
  progress = "Sarà meglio che sia importante, $C. Fammi vedere cos'hai e raccontami la tua storia. Ma per la Luce, fa' in fretta. La difesa di Darkshire è la mia priorità numero uno. Non ho tempo da sprecare in piste che non portano a niente.",
  reward = "Però, hai dimostrato di essere $Gun bel detective:una bella detective;, $C.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the muddy page to Commander Ebonlocke.",
}
T[80] = {
  title = "La Leggenda di Stalvan",
  desc = "Quel viscido di Stalvan lo tengo d'occhio da parecchio. Ma se questa pagina è stata scritta dalla stessa mano, la sua colpa è provata al di là di ogni dubbio.$B$BIn tanti anni passati a tenere il Registro Cittadino, il Cancelliere Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questa pagina e guarda se la scrittura corrisponde a quella della firma sul registro.",
  obj = "Mostra la Bloodstained Journal Page a Clerk Daltry.",
  progress = "Di nuovo qui, $N? Cos'hai questa volta?",
  reward = "Ma certo! La scrittura di questa pagina corrisponde davvero a quella delle firme sul registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Show Clerk Daltry the Bloodstained Journal Page.",
}
T[81] = {
  title = "Consegna del Vino",
  desc = "Ho avuto l'ulteriore premura di mettere al sicuro nel barile non solo il vino confezionato di Dran, ma anche le bottiglie in più di cui si sta appropriando. Per quanto io non tenga Dran in gran conto, non c'è niente di peggio di un vino sballottato. Non c'è di che.$B$BOra, consegna codesto barile a Dran Droffers, nel suo emporio di recuperi a Orgrimmar. E di grazia, porgi i miei più calorosi saluti a Malton; fagli sapere che, se mai avesse sete di buon bere e di compagni di bevute ancora migliori, la sua visita ci onorerebbe.",
  obj = "Consegna il barile a Dran Droffers, a Orgrimmar.",
  progress = "Se non sei qui per comprare, e non sei qui per consegnare, allora mi stai facendo perdere tempo! Sarà meglio che tu ce l'abbia, quel vino!",
  reward = "Bene, vediamo cosa c'è in questo barile!$B$BSì, sì, pare che ci sia tutto. Ecco il tuo compenso per il pacco, bel lavoro. Io ci farò cinque volte tanto quando lo venderò alla taverna! Ar ar!$B$BQueste bottiglie in più di Vino Dolce degli Hinterlands le terrò da parte per un'occasione speciale. Mi sa che ne berrò un po' con lo champagne. Lo chiamerò... champivino.",
}
T[82] = {
  title = "Indagine sull'Antro Venefico",
  desc = "Dunque, questi rapporti sugli insetti... quello che sappiamo è che stanno prosciugando le pozze d'acqua che c'erano dove adesso c'è l'Antro Venefico. Quello che NON sappiamo è, be', tutto il resto.$B$BPer prima cosa scopriamo chi è il nostro nemico! Voglio che tu vada nell'Antro Venefico e stacchi qualche pezzo a quelle bestiole. Prendine cinque dai Centipaar che stanno lì e portali all'Alchimista Pestlezugg, così ci armeggia un po' lui. Con lui sul caso, scopriremo cosa sono!",
  obj = "Porta cinque Centipaar Insect Parts dal Noxious Lair ad Alchemist Pestlezugg a Gadgetzan.",
  progress = "Sei l'Aiuto $GTopografo:Topografa; $N, giusto? Presto, su, la situazione è gravissima! Ce le hai le parti di insetto che secondo Fizzledowser dovevi portare?!",
  reward = "Ottimo lavoro — comincio subito ad analizzarle! Una cosa però posso dirtela fin d'ora... non somigliano a nessuna forma di insetto che io abbia mai visto. È quasi come se questi insetti fossero controllati da una forza esterna o qualcosa del genere.$B$BDevi andare subito a parlare con Fizzledowser; a quanto pare c'è un'emergenza per cui gli serve il tuo aiuto, e di corsa! Non ne sono sicuro, ma credo che c'entrino altri insetti nel deserto di Tanaris!",
}
T[90] = {
  title = "Kebab Speziati di Lupo",
  desc = "I Kebab Speziati di Lupo sono il piatto forte della casa! Certo che posso fartene un po'. Ma prima mi servono gli ingredienti. Portami 10 Costati di Lupo e delle Erbe Aromatiche di Stormwind. Di lupi qui nella foresta ce ne sono tanti, di sicuro trovare i Costati non sarà un problema. Per le erbe, cerca Felicia Gump nel suo negozio di fiori nel quartiere dei canali di Stormwind.",
  obj = "Raccogli 10 Lean Wolf Flank e le Stormwind Seasoning Herbs, poi torna da Chef Grual, a Darkshire.",
  progress = "Sei già $Griuscito:riuscita; a trovare 10 Costati di Lupo? E le erbe di Felicia, a Stormwind?",
  reward = "Ottimo lavoro, $N! Goditi la prelibatezza chiamata Kebab Speziato di Lupo!",
  en_title = "Seasoned Wolf Kabobs",
  en_obj = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.",
}
T[91] = {
  title = "La Legge di Solomon",
  desc = "Un nemico di Stormwind si è stabilito nelle colline orientali di Redridge. Questo perfido malfattore usa l'Arcano per seminare terrore e sofferenza nel nostro paese e tra la nostra gente. Si fa chiamare Morganth e porta avanti i suoi loschi affari.$B$BMorganth ora controlla lo Shadowhide Gnoll Clan e gli fa eseguire i suoi ordini. Come stabilito dalla Legge di Lakeshire, aiutare un criminale del Regno è punibile con la morte.$B$BQuesti gnoll ignobili vanno uccisi!$B$BConsegnami 10 Pendenti degli Shadowhide e sarai $Gricompensato:ricompensata;.",
  obj = "Porta 10 Shadowhide Pendant a Bailiff Conacher, nel Municipio di Lakeshire.",
  progress = "Consegnami 10 Pendenti degli Shadowhide e sarai $Gricompensato:ricompensata;.",
  reward = "La Corte di Lakeshire riconosce il tuo impegno per la giustizia, $N. Facendo rispettare le leggi del Regno hai contribuito a difendere la giustizia di questa terra.",
  en_title = "Solomon's Law",
  en_obj = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.",
}
T[94] = {
  title = "Un Occhio Vigile",
  desc = "Il mio rivale, Morganth, è un mago malvagio di grande potere che vive nella Torre di Ilgalar, a Redridge. Ho messo a punto un modo per spiarlo, l'Occhio di Azora, e ora posso osservarlo da lontano.$B$BMa per studiare i suoi pensieri... mi serve altro aiuto.$B$BSe te la senti, porta il mio Glifo di Azora alla Torre di Ilgalar. Posalo sulla Statua del Leone vicino alla torre.$B$BQuando sarà fatto, il potere di Azora concederà visioni dei piani futuri di Morganth.",
  obj = "Porta il Glyph of Azora alla Lion Statue vicino alla Torre di Ilgalar, a Redridge.",
  progress = "Questa Statua del Leone sta qui da decenni, e veglia solitaria sulla famigerata Torre di Ilgalar.$B$BAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...",
  reward = "Posi il Glifo di Azora sulla pietra. Vi aderisce da solo... e ne senti uscire la voce incorporea di Theocritus:$B$BTi sono grato, giovane $N. Ora puoi parlarmi attraverso questo Glifo, e potrei avere altri incarichi per te... dopo aver sondato i pensieri del mio rivale.",
  en_title = "A Watchful Eye",
  en_obj = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.",
}
T[95] = {
  title = "La Vendetta di Sven",
  desc = "Un tempo mandavo avanti una delle fattorie a sud-est... finché i Dark Rider del Deadwind Pass non piombarono sulla mia fattoria e massacrarono la mia famiglia mentre ero via!$B$BAl mio ritorno vidi una figura in ombra aggirarsi furtiva vicino al fienile, mentre seppelliva qualcosa. Fuggì prima che potessi prenderlo, e non potevo attardarmi perché ero alle calcagna dei Dark Rider. Così non ho mai scoperto cosa fosse nascosto.$B$BSe riesci a trovare quel che quella figura ha seppellito, te ne sarei grato. Il nascondiglio è dietro il vecchio ceppo vicino al fienile.",
  obj = "Va' alla Fattoria di Sven e trova cosa è stato sepolto dietro il vecchio ceppo.",
  reward = "Qui c'è un cumulo di terra, ammucchiato in fretta come se qualcuno avesse avuto bisogno di nascondere qualcosa... senza molto tempo per farlo.",
  en_title = "Sven's Revenge",
  en_obj = "Go to Sven's Farm and find what was buried behind the old stump.",
}
T[96] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Prendi frammento. Prendi frammento e dai vita.$B$BDai vita e capisci. Capisci che acqua è vita... corruzione ferma vita.$B$BTu proteggi e dai vita con potere di acqua.",
  obj = "Porta lo Shard of Water a Islen Waterseer, nelle Barrens.",
  progress = "Sei $Gtornato:tornata;. Splendido!$B$BCom'è andato il tuo viaggio a Silverpine? Ci hai messo molto?$B$BÈ difficile per me capire se laggiù hai avuto successo, perché gran parte di quella terra è ormai corrotta. Il suo fetore soffoca qualunque bene tu possa aver fatto. Ma i piccoli successi a volte sono importanti quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te, e per tutti gli sciamani.",
  reward = "Questa è la prova che ti avevo chiesto. Hai fatto un buon lavoro, $N.$B$BSono lieta di essere la prima a congratularmi con te e a darti questo... il tuo totem dell'acqua.$B$BUsalo bene, e buona fortuna.$B$BLa tua prossima prova non arriverà prima di un po' di tempo, quindi impara bene le tue lezioni. L'acqua pura non solo ridà la vita a chi è ferito, ma può avere molti altri effetti. Ti consiglio di cercare un istruttore di sciamani quando hai tempo. Potrebbe avere altri incantesimi da insegnarti.",
  en_title = "Call of Water",
  en_obj = "Bring the Shard of Water to Islen Waterseer in the Barrens.",
}
T[97] = {
  title = "La Leggenda di Stalvan",
  desc = "Fa' sapere subito alla Comandante Ebonlocke che la calligrafia corrisponde, $N! I suoi sospetti erano giusti!",
  obj = "Riferisci la notizia a Commander Ebonlocke.",
  progress = "Sì, $N?",
  reward = "Lo sapevo! Ottimo lavoro, $N.",
  en_title = "The Legend of Stalvan",
  en_obj = "Report the news to Commander Ebonlocke.",
}
T[98] = {
  title = "La Leggenda di Stalvan",
  desc = "Stalvan Mistmantle ha condotto una vita di depravazione. Vittime innocenti sono morte per mano sua. È senza dubbio colpevole di innumerevoli delitti. Ora quel folle minaccia Darkshire. Solo la Luce sa quali atti sordidi stia tramando. Va' alla sua casetta appena a nord del paese, $C, e giustizia Stalvan, una volta per tutte.$B$BA cose fatte, va' da Madame Eva e mostrale l'anello di famiglia di Stalvan. In fondo è stata la sua premonizione a portare a questa scoperta raccapricciante. Ma grazie a lei Darkshire è più sicura.",
  obj = "Uccidi Stalvan Mistmantle e mostra a Madame Eva l'anello di famiglia di Stalvan.",
  progress = "Sì, $N?",
  reward = "Lo so, $N: Stalvan è morto. Ho sentito un'onda di speranza attraversare la foresta corrotta. Una volta per tutte, Duskwood è libera dalla sua sete di sangue. La mia gioia è offuscata dal pensiero di chi è caduto preda di quella bestia orribile. Ciò nonostante, sei $Gun:una; $C $Gcoraggioso:coraggiosa; e $Gastuto:astuta;.",
  en_title = "The Legend of Stalvan",
  en_obj = "Kill Stalvan Mistmantle and show Madame Eva his family ring.",
}
T[100] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Mentre pronunci le ultime parole della formula, esplode un lampo di luce. Il suono delle gocce d'acqua che colpiscono la fiamma si è spento, e i tuoi sensi vengono sopraffatti mentre gli spiriti corrotti intorno a te vengono distrutti.",
  obj = "Parla con la Minor Manifestation of Water, nella Silverpine Forest.",
  reward = "Grazie a te. Grazie agli sciamani.$B$BLa corruzione si ritira, ma la vita continua a spegnersi. Tocca a sciamani proteggere vita.",
  en_title = "Call of Water",
  en_obj = "Speak to the Minor Manifestation of Water in Silverpine Forest.",
}
T[101] = {
  title = "Il Totem del Castigo",
  desc = "Mentre la corruzione mistica si insinua nella foresta, il bisogno di proteggersi è innegabile, $N. I venti mi sussurrano e parlano di un grande pericolo che ti attende paziente in un futuro non lontano.$B$BSe vuoi proteggerti, nobile $C, portami 10 zanne di ghoul, 10 dita di scheletro e 5 fiale di veleno di ragno. Per te incanterò un Totem del Castigo che ferirà chi tenta di farti violenza.",
  obj = "Porta 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom a Madame Eva, a Darkshire.",
  progress = "Portami 10 zanne di ghoul, 10 dita di scheletro e 5 fiale di veleno di ragno. Per te incanterò un Totem del Castigo che ferirà chi tenta di farti violenza.",
  reward = "Molto saggio da parte tua, $N. Questo Totem del Castigo ti aiuterà a proteggerti dal male che si annida per tutta Azeroth e oltre. Quando ti senti $Gminacciato:minacciata;, stringi questo totem e trova conforto nella sua aura magica. Sii $Gcoraggioso:coraggiosa;, gentile $C. Ti servirà tutto il coraggio che riesci a raccogliere, perché vedo molto sangue nel tuo futuro.",
  en_title = "The Totem of Infliction",
  en_obj = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.",
}
T[105] = {
  title = "Ahimè, Andorhal",
  desc = "Ahimè, è giunta l'ora di attaccare Andorhal e scacciare il lich che la controlla!$B$BÈ fra le rovine della città che il lich — Araj l'Evocatore — esercita il suo dominio. Lo sorvegliano numerose creature del Flagello che circondano i resti del centro cittadino, e la scorta personale di guardiani al suo diretto servizio è temibile. Avrai bisogno di molti alleati anche solo per sperare di affrontarlo con successo.$B$BDistruggi Araj, $N, e portami come prova una scheggia del suo filatterio!",
  obj = "Porta Araj's Phylactery Shard a High Executor Derrington al Bulwark, nelle Western Plaguelands.",
  progress = "Il compito ti è stato affidato, $N. Hai con te una scheggia del filatterio del lich, come prova che l'hai portato a termine?",
  reward = "Ce l'hai fatta! Araj... il lich è finalmente sconfitto!$B$BOggi hai reso un servizio immenso all'Orda, $N. Il tuo coraggio e la tua perseveranza dimostrano cosa significa essere un vero eroe. Ti prego — accetta questo come segno, perché tutti vedano e sappiano che hai dato all'Orda una vittoria che resterà nei secoli!",
}
T[110] = {
  title = "Analisi delle Parti di Insetto",
  desc = "Mi prenderò un po' di tempo per dare un'occhiata all'attrezzatura da topografo di Scrimshank... e anche per mettere in ordine i suoi effetti personali. Ho la strana sensazione, qui dietro le orecchie, che questa non sarà l'ultima perdita che questi insetti ci faranno subire.$B$BVorrei che passassi dall'Alchimista Pestlezugg per vedere se ha avuto modo di esaminare le parti di insetto che gli abbiamo mandato. Se sono pronte, portamele.",
  obj = "Passa da Alchemist Pestlezugg a Gadgetzan per la sua analisi delle parti di insetto.",
  reward = "Sì, ho i risultati proprio qui. Sono... inquietanti, a dir poco.$B$BIl nostro sospetto iniziale, che gli insetti siano controllati da una forza esterna, crediamo sia corretto. Se è così, allora abbiamo a che fare con una forza ignota non solo molto potente, ma anche maligna. Questi insetti sono stati trasformati in devastatori allo stato puro. Non ho mai visto niente del genere.",
}
T[111] = {
  title = "Parla con la Nonna",
  desc = "Ti prego, $N, parla con mia Nonna. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.$B$BÈ in casa nostra, a est di qui.",
  obj = "Parla con Gramma Stonefield.",
  progress = "Non vedo l'ora di sapere come reagiranno i miei amici!$B$BNon se lo aspetteranno mai",
  reward = "Finché le nostre famiglie si fanno la guerra, Tommy Joe e Maybell non hanno molto futuro, ma... forse possiamo farli stare insieme almeno per un po'.$B$BMmm, cosa possiamo fare...",
}
T[113] = {
  title = "Analisi delle Parti di Insetto",
  desc = "Il Topografo Capo Fizzledowser deve vedere subito questo rapporto. Anzi... deve vederlo chiunque sappia leggere. Siamo di fronte a una minaccia grave e seria non solo per Tanaris e Gadgetzan ma, se nessuno la ferma, per tutto il Kalimdor meridionale. Accidenti, è ben possibile che minacci perfino l'intera Azeroth; questa cosa non ha dato alcun segno di volersi placare.$B$BFatti fare da Fizzledowser un duplicato del rapporto, da distribuire liberamente alla tua fazione. Tutti devono sapere di questa minaccia!",
  obj = "Consegna l'Insect Analysis Report a Senior Surveyor Fizzledowser a Gadgetzan. Assicurati che ti dia una copia del rapporto, come ha chiesto Alchemist Pestlezugg.",
  progress = "Allora, Aiuto $GTopografo:Topografa; $N, il vecchio Pestlezugg ce l'ha pronto quel rapporto?",
  reward = "Grazie per aver consegnato il rapporto, Aiuto $GTopografo:Topografa; $N; ecco la tua paga per il diligente servizio reso alla Gadgetzan Water Company.$B$BDi solito non mi entusiasma dare via senza riserve le nostre preziose informazioni a chi altrimenti le pagherebbe in moneta sonante, ma conosco Pestlezugg da parecchi anni ormai. Se lui raccomanda di farlo sapere a tutti, allora così sia. Dammi un momento e te ne faccio una copia.",
}
T[115] = {
  title = "Magia delle Ombre",
  desc = "Gli orchi Blackrock hanno arruolato dei maghi d'ombra per sostenere i loro attacchi a Redridge, e si sono portati dietro strumenti di potere oscuro — i globi della mezzanotte. Questi globi hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere dal conflitto questi oggetti corrotti dai demoni.$B$BTrova i globi della mezzanotte sui maghi d'ombra Blackrock che uccidi e portameli. Li farò distruggere: questo mondo sarebbe un posto migliore senza di loro!",
  obj = "Porta 3 Midnight Orb a Marshal Marris, a Lakeshire.",
  progress = "Come va lo scontro con i maghi d'ombra? Li hai trovati i globi della mezzanotte?",
  reward = "Grazie, $N. Li manderò subito a distruggere.",
  en_title = "Shadow Magic",
  en_obj = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.",
}
T[126] = {
  title = "Ululati sulle Colline",
  desc = "$N, gli gnoll sono ancora là fuori. Sento i loro latrati mentre cacciano sulle colline sopra Lakeshire. E un ululato è più forte degli altri — Ghignolungo, il loro capo.$B$BUccidi Ghignolungo e disperdi il suo branco! Portami la sua zampa come prova.$B$BE sta' $Gattento:attenta;, perché questo gnoll non è il loro capo per caso. Non è un Meticcio qualsiasi...",
  obj = "Porta Yowler's Paw a Verner Osgood, a Lakeshire.",
  progress = "Ghignolungo è una creatura pericolosa, $N. Se non sei $Gpronto:pronta; ad affrontarlo, capisco.",
  reward = "Grazie ancora per l'aiuto. L'esercito di Stormwind è così impegnato con gli orchi che non ha le truppe per proteggere Redridge dalle minacce locali come gli gnoll.",
  en_title = "Howling in the Hills",
  en_obj = "Bring Yowler's Paw to Verner Osgood in Lakeshire.",
}
T[127] = {
  title = "Vendere Pesce",
  desc = "Il Lago Everstill è famoso per i suoi persici sole maculati. C'è sempre richiesta... e io sono a corto!$B$BPortamene una partita di 10 e te li pagherò bene. Se non sai pescare, allora... magari puoi prenderli dai murloc!",
  obj = "Porta 10 Spotted Sunfish a Dockmaster Baren, a Lakeshire.",
  progress = "Hai un po' di persici sole per me, eh?",
  reward = "Un piacere far affari con te, $Gsocio:socia;!",
  en_title = "Selling Fish",
  en_obj = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.",
}
T[128] = {
  title = "Taglia sui Blackrock",
  desc = "Il Blackrock Clan va distrutto. Il Nemico ha invaso le nostre terre. Queste montagne ricadono sotto il diritto sovrano del Re di Stormwind. Le nostre fonti ci dicono che i capi di ogni unità del Clan sono chiamati Campioni. Li trovi nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.$B$BIl Magistrato Solomon vuole morti questi bruti immondi. Uccidi 15 Campioni Blackrock e torna da me.",
  obj = "Uccidi 15 Blackrock Champion e Guard Howe, a Lakeshire, ti ricompenserà.",
  progress = "Torna quando avrai ucciso 15 Campioni Blackrock.",
  reward = "Vedo che hai combattuto valorosamente contro il Blackrock Clan, $C. Hai reso davvero un grande servizio alla nostra cittadina.",
  en_title = "Blackrock Bounty",
  en_obj = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.",
}
T[133] = {
  title = "Effigie per i Ghoul",
  desc = "Vivo così lontano dalla protezione del paese che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Anzi, proprio ieri un branco di Masticatori d'Ossa picchiava contro i muri di casa mia!$B$BVoglio fare un'effigie — una specie di \"spaventapasseri\" per i Ghoul. Per farla mi servono delle Costole di Ghoul. Puoi prenderle ai Mangiatori di Carne, ai Masticatori d'Ossa, ai Mangiatori di Cervelli, ai Marci e agli Spargipiaga.$B$BPortami le costole e ti ripagherò con qualche moneta.",
  obj = "Raccogli 7 Ghoul Rib e portale ad Abercrombie, alla sua baracca.",
  progress = "Mi sembra di sentire un branco di Ghoul che sgattaiola dietro casa — meglio che tiri su in fretta quell'effigie! Me le hai prese quelle Costole di Ghoul?",
  reward = "Ah, grazie. Faranno proprio al caso mio!",
  en_title = "Ghoulish Effigy",
  en_obj = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.",
}
T[134] = {
  title = "Ogre Ladri",
  desc = "Qualche settimana fa stavo raccogliendo erbe lontano da casa, e una banda di ogre mi ha assalito! Sono scappato, e ho dovuto abbandonare una cassa di attrezzi e di erbe preziose.$B$BDopo avermi cacciato, gli ogre sono tornati impettiti al tumulo degli ogre nel sud di Duskwood. Sono sicuro che la mia cassa è da qualche parte vicino al tumulo.$B$BTi prego, $N, recuperamela, perché mi manca tantissimo.",
  obj = "Riporta Abercrombie's Crate ad Abercrombie.",
  progress = "Ce l'hai la mia cassa? Se sì, allora ti prego... dammela subito!",
  reward = "Grazie al Negrom-... be', grazie a TE, $N! Ti sei $Gguadagnato:guadagnata; la ricompensa e anche di più.$B$BAha! Felice! Notti felici in arrivo!!",
  en_title = "Ogre Thieves",
  en_obj = "Return Abercrombie's Crate to Abercrombie.",
}
T[148] = {
  title = "Rifornimenti da Darkshire",
  desc = "Oh, cosa può fare un povero vecchio? Mi servono dei rifornimenti da Darkshire, ma il villaggio è così lontano e io sono così vecchio e malandato... non ce la farei mai a fare il viaggio.$B$BPuoi andare a Darkshire e portarmi del Filo di Capelli Spettrali? Te lo può dare Madame Eva, a casa sua, sulla piazza di Darkshire.",
  obj = "Parla con Madame Eva.",
  reward = "Ah, ti serve del Filo di Capelli Spettrali, vero? Temo di non averne, ma posso fartene un po'... se mi procuri tu i capelli di fantasma.",
  en_title = "Supplies from Darkshire",
  en_obj = "Speak with Madame Eva.",
}
T[149] = {
  title = "Filo di Capelli Spettrali",
  desc = "C'è un povero spirito triste, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di Darkshire.$B$BTieni, prendi questo Pettine Spettrale e chiedi a Blind Mary di pettinarsi. Poi riportami il pettine e ne ricaverò i Capelli Spettrali che mi servono per il filo.$B$BE sta' $Gattento:attenta;, perché adesso vicino a quella casa si annidano cose oscure...",
  obj = "Porta lo Spectral Comb a Blind Mary.",
  progress = "<Singhiozzo> Oh, ti prego, non guardarmi! Mi sono strappata questi occhi con le mie mani, eppure sento ancora il tuo sguardo!$B$BSono orrenda! Orrenda! Ti prego, distogli lo sguardo!!",
  reward = "Cos'è questo? Un pettine? È bellissimo! E scivola tra i miei capelli come se non fossero l'orrore rigido e stopposo che sono.$B$BOh, se solo avessi uno specchio...",
  en_title = "Ghost Hair Thread",
  en_obj = "Bring the Spectral Comb to Blind Mary.",
}
T[154] = {
  title = "Restituisci il Pettine",
  desc = "NO!!!!!$B$BPrendilo, portami via questo pettine!$B$BSono un mostro, e nessuno mi troverà mai più bella!",
  obj = "Riporta il Ghost Hair Comb a Madame Eva, a Darkshire.",
  progress = "Sento che hai visto Blind Mary. Hai il mio Pettine...?",
  reward = "Con questo posso fare un rocchetto di Filo di Capelli Spettrali, e mi avanzeranno anche alcuni capelli. Ecco qualche moneta per quelli in più.",
  en_title = "Return the Comb",
  en_obj = "Return the Ghost Hair Comb to Madame Eva in Darkshire.",
}
T[156] = {
  title = "Raccogli i Fiori Marci",
  desc = "Se mi porti dei fiori marci, posso prepararti una dose di zombie juice.$B$BI fiori marci crescono in posti strani. In particolare, pare che si trovino dentro i teschi degli Orrori Scheletrici e dei Demoni Scheletrici... non che io mi sia mai avvicinato abbastanza da guardare!$B$BIl Cimitero di Raven Hill e i Giardini Tranquilli pullulano di quegli scheletri. Tanto vale farli fuori mentre cerchi i fiori marci. La città di Darkshire te ne sarebbe grata.",
  obj = "Raccogli 8 Rot Blossom e portali a Tavernkeep Smitts, a Darkshire.",
  progress = "Ciao, $N. Hai già quei fiori marci per me?",
  reward = "Bene, hai preso i fiori marci. E dirò ad Althea Ebonlocke dei Guardiani della Notte che hai fatto fuori degli scheletri.$B$BTenere al sicuro la gente di Darkshire è un compito gravoso per i Guardiani della Notte, e sapere che anche altri aiutano ad arginare la marea di mostri a Duskwood è davvero una buona notizia.",
  en_title = "Gather Rot Blossoms",
  en_obj = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.",
}
T[157] = {
  title = "Consegna il Filo",
  desc = "Ecco il tuo filo, $N. Ha mille usi, dal legare gli spiriti maligni al cucire la vita negli oggetti inanimati.",
  obj = "Porta il Ghost Hair Thread ad Abercrombie, nella sua baracca a nord del Cimitero di Raven Hill.",
  progress = "Devo tendere il Filo di Capelli Spettrali lungo la porta e le finestre per tenere fuori gli spiriti indesiderati. Me l'hai preso?",
  reward = "Splendido! Andrà benissimo...$B$BTieni, $Gcaro:cara; $N, prendi questo come pagamento per la tua nobile azione.",
  en_title = "Deliver the Thread",
  en_obj = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.",
}
T[158] = {
  title = "Zombie Juice",
  desc = "Mi serve una bottiglia di un certo liquore — Zombie Juice. L'Oste Smitts, alla Scarlet Raven Tavern di Darkshire, dovrebbe averne.$B$BE fa' in fretta, ti prego, $N. Queste notti si fanno fredde, e mi serve quella bevanda per rimettermi il fuoco nelle vene!",
  obj = "Parla con Tavernkeep Smitts.",
  reward = "Ti serve dello Zombie Juice, eh? Hmm... è roba forte — non me lo chiede quasi nessuno.",
  en_title = "Zombie Juice",
  en_obj = "Speak with Tavernkeep Smitts.",
}
T[159] = {
  title = "Consegna del Succo",
  desc = "Ecco il tuo Zombie Juice...$B$B...e sta' $Gattento:attenta; con questa roba. È così forte che potrebbe resuscitare i morti!",
  obj = "Porta la Bottle of Zombie Juice ad Abercrombie, nella sua baracca.",
  progress = "Mi serve quello Zombie Juice per scaldarmi in queste notti fredde e buie. Me l'hai preso?",
  reward = "Mille grazie, $N. Scaldi il cuore di un vecchio con la tua stupid-... voglio dire... con la tua gentilezza!$B$BEcco a te, $Gamico:amica;. Prendi questo come segno della mia gratitudine.",
  en_title = "Juice Delivery",
  en_obj = "Bring the Zombie Juice to Abercrombie at his shack.",
}
T[160] = {
  title = "Un Biglietto per il Sindaco",
  desc = "Porta questo biglietto a Ello Ebonlocke, il Sindaco di Darkshire.$B$BIo e lui siamo vecchi amici... e quando lo leggerà e scoprirà quel che hai fatto per me... sono sicuro che sarà felice quanto me! Ahahaha!",
  obj = "Porta la lettera di Abercrombie a Ello Ebonlocke, Sindaco di Darkshire.",
  progress = "Abercrombie...? Non conosco nessuno con questo nome. Dici di avere una lettera per me da parte di questo tale Abercrombie?$B$BBe', allora fammela vedere...",
  reward = "<Ello guarda la lettera...>$B$BChe lingua è questa? Sembra antica... non riesco a leggerla.",
  en_title = "Note to the Mayor",
  en_obj = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.",
}
T[162] = {
  title = "L'Ascesa dei Silithid",
  desc = "Ti consiglio vivamente di portare questo rapporto a qualcuno che di queste cose abbia una conoscenza pratica.$B$BConosco una studiosa elfa della notte, una certa Gracina Spiritmight. Ha passato molto tempo a studiare le forme di vita che appartengono solo all'ecologia di Azeroth; e per giunta è una storica! Se vuoi qualcuno che ti aiuti a capire cos'è esattamente questa minaccia, e soprattutto come fermarla, dai il rapporto a lei. L'aiuto ci servirà.$B$BL'ultima volta che ne ho sentito parlare, viveva nel Tempio della Luna, a Darnassus.",
  obj = "Porta l'Insect Analysis Report a Gracina Spiritmight a Darnassus.",
  progress = "Pace e tranquillità siano con te, $Gstraniero:straniera;. Perché mi hai cercata, quest'oggi?",
  reward = "Questo rapporto... noi elfi della notte conosciamo il terrore di cui parla. Fizzledowser è stato saggio a mandare questo rapporto, e te, da me.$B$BQueste creature divoreranno in fretta il deserto di Tanaris; sono niente meno che uno dei pericoli più grandi che tutti noi dovremo mai affrontare. Impara bene questo nome, $N: silithid. Gli insetti di cui si parla qui sono i silithid, e sono gli strumenti di una delle più gravi minacce che incombono tanto sull'Orda quanto sull'Alleanza.$B$BSe solo fossimo stati abbastanza svegli da capirlo prima.",
}
T[164] = {
  title = "Consegne per Sven",
  desc = "Conosci Sven? Ecco un uomo che fa l'opera della Luce! Lui e i suoi seguaci hanno un accampamento all'estremità nord-occidentale di Duskwood.$B$BPurtroppo sono così pochi che non possono permettersi nemmeno di privarsi di un uomo per andare a prendere i rifornimenti in città. Glieli porteresti tu, questi rifornimenti?",
  obj = "Consegna i rifornimenti a Sven.",
  progress = "Sembri $Grobusto:robusta;, $C. Sei $Gvenuto:venuta; a unirti alla nostra lotta?",
  reward = "Questi rifornimenti saranno utilissimi. L'aiuto della famiglia Carevin è sempre gradito. Ecco qualcosina per il disturbo.",
  en_title = "Deliveries to Sven",
  en_obj = "Deliver the supplies to Sven.",
}
T[165] = {
  title = "L'Eremita",
  desc = "C'era un vecchio che veniva in paese piuttosto spesso a comprare provviste, ma è da parecchio che non lo vedo. Se ricordo bene, vive in una baracca che domina il cimitero di Raven Hill. Forse dovresti andare a vedere se è successo qualcosa.",
  obj = "Va' a vedere come sta il vecchio nella baracca vicino al cimitero di Raven Hill.",
  reward = "Elaine Carevin? Eheh, oh sì... i Carevin, certo.$B$BNo, non c'è niente che non va, ma adesso per me è dura andare in paese. Le strade sono pericolose e non ringiovanisco di certo. Magari puoi fare qualche favore a un vecchio?",
  en_title = "The Hermit",
  en_obj = "Check on the old man in the shack near Raven Hill cemetery.",
}
T[166] = {
  title = "La Defias Brotherhood",
  desc = "Ti resta un solo compito da portare a termine. Edwin VanCleef deve essere assassinato. Per quanto mi rattristi condannare a morte un uomo, il bene superiore della gente di Westfall vuole che VanCleef trovi il riposo eterno, una volta per tutte. A cosa fatta, portami la testa di quel furfante.",
  obj = "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.",
  progress = "Come va la caccia a Edwin VanCleef?",
  reward = "$N, il tuo coraggio è notevole. La People's Militia ti ringrazia per il servizio reso alla gente di Westfall. La morte di VanCleef segna l'inizio della fine per la Defias Brotherhood. Speriamo che presto la pace torni a benedire le pianure di questa bella terra.$B$BTi rendo onore, $GSignore:Signora;!",
  en_title = "The Defias Brotherhood",
  en_obj = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.",
}
T[167] = {
  title = "Oh, Fratello...",
  desc = "Eravamo in fondo a una miniera enorme a Westfall, nascosta sotto un fienile a Moonbrook. Non ho idea di dove siano sbucati quei ladracci puzzolenti. Comunque, la galleria ci è crollata addosso. Io ne sono uscito, ma gli altri... be'... degli altri non si è più saputo nulla.$B$BTu hai l'aria di poter avere più fortuna, là dentro. Se potessi cercare mio fratello, te ne sarei grato. Portava sempre con sé il suo Distintivo della Lega degli Esploratori. Se non riesci a trovarlo, almeno quel distintivo mi darebbe un po' di pace.",
  obj = "Porta Foreman Thistlenettle's Explorers' League Badge a Wilder Thistlenettle, a Stormwind.",
  progress = "Hai trovato qualche traccia di mio fratello? C'è ancora speranza dopo tutto questo tempo?",
  reward = "I miei sospetti erano fondati. Povero fratello mio... Be', grazie per aver dato una risposta a questo mistero, anche se è una risposta amara.",
  en_title = "Oh Brother. . .",
  en_obj = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",
}
T[168] = {
  title = "Raccogliere Ricordi",
  desc = "Molti dei miei amici sono morti in quel giorno orribile in cui la galleria della miniera è crollata. Se le tue avventure dovessero portarti in quell'ala della miniera a Moonbrook, ti prego, tieni gli occhi aperti per qualsiasi segno che possa identificarli. Se ti capita di trovare qualcuno dei loro Tesserini dei Minatori, riportameli e farò in modo che le loro famiglie trovino una risposta a questo terribile incidente.",
  obj = "Recupera 4 Miners' Union Card e riportale a Wilder Thistlenettle, a Stormwind.",
  progress = "Sei $Griuscito:riuscita; a recuperare qualche Tesserino dei Minatori dei miei vecchi compagni di lavoro?",
  reward = "Grazie di averli raccolti, $N. Il tuo impegno aiuterà a dare pace ai morti dopo questa tragedia. Mi occuperò io di avvisare le famiglie.",
  en_title = "Collecting Memories",
  en_obj = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",
}
T[169] = {
  title = "Ricercato: Gath'Ilzogg",
  desc = "Ricercato! Gath'Ilzogg, Capo degli attacchi Blackrock al Mastio di Stonewatch e delle incursioni contro la cittadina di Lakeshire.$B$BGath'Ilzogg è estremamente pericoloso. Si dice sia rintanato nel forte appena conquistato, a tramare altri crimini del clan Blackrock contro l'umanità. L'infestazione degli orchi va soffocata a ogni costo. Sarà data una generosa ricompensa a qualunque anima coraggiosa consegni la testa di Gath'Ilzogg al Magistrato Solomon.",
  obj = "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon, a Lakeshire, per la ricompensa.",
  progress = "Che cos'hai lì, $R?",
  reward = "Splendido lavoro, $N! Gath'Ilzogg ha guidato quei bruti in battaglia, uccidendo molti umani innocenti. Giustizia è fatta. È il primo passo per riprendere il forte in nome del regno di Stormwind!",
  en_title = "Wanted: Gath'Ilzogg",
  en_obj = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.",
}
T[171] = {
  title = "$GUn Tutore:Una Tutrice; dell'Alleanza",
  desc = "Sei $Gstato:stata; così gentile con me, $N. Non avrei mai sognato di divertirmi così tanto durante la Settimana dei Bambini. Grazie. Non voglio essere triste per quello che mi è successo e tutto il resto: i miei mi hanno sempre detto di non lasciarmi abbattere dalle cose brutte che succedono. Sai, da grande voglio essere un eroe... proprio come te.$B$BMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, e dirò alla matrona che persona fantastica sei!",
  obj = "Riporta il tuo protetto all'orfanotrofio di Stormwind consegnando lo Human Orphan Whistle a Orphan Matron Nightingale, nel Cathedral District.",
  progress = "È un piacere rivederti, $N. Hai portato a termine i compiti di cui ti sei $Gfatto:fatta; carico durante la Settimana dei Bambini?",
  reward = "Che il cielo ti benedica, $N. Hai fatto per Randis più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei una stella splendente nei cieli dell'Alleanza.$B$BTi prego, se riesci a trovare un po' di tempo, torna a trovarci. So che a Randis farebbe piacere, e anche a me.$B$BRandis si è divertito tantissimo con te, $N. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.",
  en_title = "A Warden of the Alliance",
  en_obj = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.",
}
T[172] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.$B$BForza, $N, usa il fischietto e conosci il tuo protetto! Sono $Gsicuro:sicura; che il bambino non vedrà l'ora di conoscerti.",
  obj = "Usa l'Orcish Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Zug zug! Mi chiamo Grunth, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. La mia matrona dice che sono morti con onore in battaglia. Sono contento di conoscerti.$B$BSpero che faremo un sacco di cose insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco.",
  en_title = "Children's Week",
  en_obj = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[173] = {
  title = "Worgen nei Boschi",
  desc = "L'oscurità sembra attirata inesorabilmente da Duskwood. La missione del Maestro Carevin è scacciare il male e l'eresia. È grazie ai nostri sforzi che la gente di Darkshire resta al sicuro.$B$BTi credi $Gdegno:degna; di unirti a noi?$B$BUna volta la pensavo come te. Deluso dall'inerzia dei Guardiani della Notte, mi sono unito al Maestro Carevin. Se vuoi dimostrare il tuo valore, non sarà con le parole.$B$BMetti alla prova le tue capacità contro i worgen Mistici delle Ombre Nightbane nel Boschetto di Brightwood — luminoso, ah! — e nel Frutteto Marcio.",
  obj = "Uccidi 6 worgen Nightbane Shadow Weaver per Calor, a Darkshire.",
  progress = "$N, come va la caccia?",
  reward = "Notevole, $N. Sembra che tu sia capace di cavartela da $Gsolo:sola;. Forse per $Guno:una; con le tue capacità si può trovare una sfida più adatta.$B$BÈ curioso, però... I worgen sembravano comparire dal nulla. Ma d'altronde, con tutte le altre creature strane che hanno varcato i nostri confini, immagino sia solo una preoccupazione fra tante.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.",
}
T[174] = {
  title = "Guarda le Stelle",
  desc = "Il mio amico gnomo, Cog, ha promesso di aiutarmi a costruire un congegno che mi permetta di scrutare le stelle. Esiste una verità, oltre la magia, che può spiegare la strana trasformazione della foresta.$B$BPortami un tubo di bronzo fatto da un ingegnere esperto. È il primo passo, secondo il progetto di Cog.",
  obj = "Viktori Prism'Antras di Darkshire vuole che tu gli porti un Bronze Tube.",
  progress = "Hai già trovato un ingegnere esperto che faccia un tubo di bronzo?",
  reward = "È perfetto, $N. Il primo passo è compiuto!",
  en_title = "Look To The Stars",
  en_obj = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.",
}
T[175] = {
  title = "Guarda le Stelle",
  desc = "Secondo lo schema di Cog, ora mi serve un modo per riflettere la luce. Ricordo una donna di nome Mary che da queste parti era diventata famosa perché portava sempre con sé uno specchio. Magari potresti rintracciare Mary e chiederle se ci presta una superficie riflettente per questo progetto? Credo che un tempo vivesse nella parte meridionale di Duskwood. . .",
  obj = "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.",
  reward = "Ma sì, un tempo avevo uno specchio.",
  en_title = "Look To The Stars",
  en_obj = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.",
}
T[177] = {
  title = "Guarda le Stelle",
  desc = "Lo specchio era uno dei miei tesori più belli, fino a. . .quell'incidente. Dopo quel che è successo l'ho buttato dietro il fienile. Là dietro si aggirava un Ghoul Folle. Forse l'ha raccolto lui. Si dice che quella bestia diabolica si trovi nel Cimitero Parcosereno.",
  obj = "Recupera Blind Mary's Looking Glass dall'Insane Ghoul e portalo a Viktori, a Darkshire.",
  progress = "Ho mostrato a Cog i primi pezzi della nostra macchina per osservare le stelle. È rimasto colpito. Ti è capitato di trovare un congegno riflettente?",
  reward = "Magnifico! Andrà a meraviglia. Mille grazie!",
  en_title = "Look To The Stars",
  en_obj = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.",
}
T[178] = {
  title = "Il Recupero di Theocritus",
  desc = "<Senti una voce incorporea...>$B$BNon ti allarmare. Sono Theocritus, Alto Mago della Torre di Azora, nell'Elwynn Forest. Il pendente che hai in mano è un mezzo di comunicazione tra gli Gnoll Shadowhide e il loro padrone, Morganth.$B$BDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi pendenti. Se senti questo messaggio, allora il mio incantesimo ha funzionato.$B$BPortami questo pendente e ti ricompenserò per il servizio.",
  obj = "Porta il Faded Shadowhide Pendant a Theocritus the Mage.",
  progress = "Ti ho parlato attraverso un pendente, dici? Hmm... dallo a me, così posso studiarlo.",
  reward = "Ti sono grato, $N. Quel messaggio l'ho mandato ai Pendenti degli Shadowhide settimane fa e lo credevo un fallimento. Ma pare che l'incantesimo abbia raggiunto almeno qualche pendente, dopo un notevole ritardo.$B$BCol tempo spero di imparare a mandare un attacco attraverso i pendenti, per immobilizzare gli Gnoll Shadowhide che li portano.$B$BMa prima che sia possibile, temo che servano ancora molte ricerche.",
  en_title = "Theocritus' Retrieval",
  en_obj = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.",
}
T[180] = {
  title = "Ricercato: Tenente Fangore",
  desc = "Ricercato: Tenente Fangore$B$BCapo riconosciuto dello Shadowhide Gnoll Clan, al servizio del nemico della Cittadina e del Regno, Morganth. Per mandato del Magistrato Solomon, questo ignobile traditore di Stormwind deve morire. Mostra la sua zampa al Magistrato come prova della sua morte.",
  obj = "Uccidi Lieutenant Fangore e torna da Magistrate Solomon, a Lakeshire, con la sua zampa.",
  progress = "Che notizie porti davanti alla Corte?",
  reward = "Dunque il malvagio Tenente Fangore è morto? Finalmente ci siamo liberati di quella creatura immonda. Sei molto $Gcoraggioso:coraggiosa;, $C. La Cittadina di Lakeshire ti ringrazia per il tuo aiuto.",
  en_title = "Wanted: Lieutenant Fangore",
  en_obj = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.",
}
T[181] = {
  title = "Guarda le Stelle",
  desc = "Ora manca solo un pezzo per completare questo congegno. Il progetto di Cog prevede una specie di lente. L'unica lente abbastanza grande che io conosca sarà molto difficile da procurare.$B$BC'è un ogre di nome Zzarc'Vul che vive nel tumulo del sud di Duskwood. Se ci riesci, portami il suo monocolo e lo userò come lente!",
  obj = "Trova Zzarc'Vul nel tumulo degli ogre, nel sud di Duskwood, e porta il suo monocolo a Viktori, a Darkshire.",
  progress = "Sei $Griuscito:riuscita; a convincere Zzarc'Vul a prestarci il suo monocolo per il nostro esperimento?",
  reward = "Finalmente! Il congegno per osservare le stelle è completo! Grazie, $N. Ora posso continuare le mie ricerche. . .",
  en_title = "Look To The Stars",
  en_obj = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.",
}
T[185] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Quando ero solo una ragazzina, mio padre mi insegnò l'arte della caccia alla tigre.$B$BI felini giovani sono molto più facili da seguire e da uccidere. Per questo cominceremo con qualcosa di semplice. Spesso si trovano giovani tigri vicino all'accampamento della spedizione.$B$BMetti alla prova la tua abilità nel seguire le tracce e vedi se riesci a cacciare qualcuna di queste bestie.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Young Stranglethorn Tiger.",
  progress = "Non me la sento di addestrarti oltre, $N, finché non avrai dimostrato di saper uccidere prima le tigri più giovani.",
  reward = "Ben fatto, $N. Sei $Gpronto:pronta; per il passo successivo.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.",
}
T[186] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Stai imparando, $C. Ora mettiamo alla prova la tua abilità con i felini adulti. Stavolta uccidi 10 Tigri di Stranglethorn.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Stranglethorn Tiger.",
  progress = "Se aspiri a sfide più grandi, devi prima dimostrare quanto vali con il compito che hai davanti. Torna da me dopo aver ucciso 10 Tigri di Stranglethorn.",
  reward = "Sono colpita, $C. Stai facendo davvero buoni progressi.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.",
}
T[187] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Ora alzerò la posta e metterò davvero alla prova la tua abilità. Dimostrami che sai uccidere 10 Tigri Anziane di Stranglethorn. Se ci riesci, sarai $Gpronto:pronta; per la tua sfida finale, prima che io ti proclami $Gmaestro cacciatore:maestra cacciatrice; di tigri alla presenza del Maestro Nesingwary.$B$BLe Tigri Anziane di Stranglethorn non sono solo le più difficili da trovare, ma anche le più feroci da affrontare.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Elder Stranglethorn Tiger.",
  progress = "Devi uccidere 10 Tigri Anziane di Stranglethorn prima che io ti affidi la sfida finale, quella che stabilirà se sei $Gun vero maestro:una vera maestra; nella caccia alla tigre.",
  reward = "Davvero notevole. Credo che tu sia quasi $Gpronto:pronta;.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.",
}
T[188] = {
  title = "Maestria nella Caccia alla Tigre",
  desc = "Ecco la sfida finale che ti propongo. Da settimane seguiamo le tracce di una tigre sfuggente. Chiamiamo quella bestia Sin'Dall. Vediamo se riesci a fare ciò che $Gnessun altro:nessun'altra; $R ha mai fatto prima: stanare e uccidere Sin'Dall. Portami la sua zampa come prova della tua impresa.$B$BRintracciarla non sarà un compito facile.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida Sin'Dall e torni con la sua zampa.",
  progress = "Come procede la caccia a Sin'Dall?",
  reward = "Davvero notevole, non c'è che dire! Sei $Gun vero Maestro Cacciatore di Tigri:una vera Maestra Cacciatrice di Tigri;, $N!",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.",
}
T[189] = {
  title = "Orecchie dei Bloodscalp",
  desc = "Maledetti troll! Stanno facendo fuori i nostri agenti nella giungla! Ho già perso un bel po' delle mie guardie migliori negli scontri con loro. I costi si accumulano! Come lo spiego al Barone Revilgaz?$B$BUn'azione decisa... Pensa, Kebok... non ti hanno messo al posto che occupi oggi per startene con le mani in mano... Ci sono! Tu... $N, giusto? Mi aiuterai, vero? C'è da guadagnarci!$B$BFacciamo così... tu mi porti le orecchie di quindici Troll Bloodscalp, e io ti ricompenso bene.",
  obj = "Procurati 15 Bloodscalp Ear e riportale a Kebok, a Booty Bay.",
  progress = "È andata bene, spero? Sono dappertutto, quei troll. Sudici diavoli.$B$BOh, sì, a proposito! Dillo anche ai tuoi amici, eh? Ci farebbe comodo parecchio aiuto!",
  reward = "Oh, eccellente, eccellente. Questo aiuterà un po', per il momento...$B$B<La sua voce si spegne mentre borbotta di margini di profitto e di costi...>$B$BCosa? Sei ancora qui? Una ricompensa? Ah, giusto... certo, ecco, prendi questo... dovrebbe bastare e avanzare.",
  en_title = "Bloodscalp Ears",
  en_obj = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.",
}
T[190] = {
  title = "Maestria nella Caccia alla Pantera",
  desc = "Se vuoi partecipare alla caccia con questo gruppo di assi che Hemet ha radunato, dovrai dimostrare di essere $Gun abile cacciatore:un'abile cacciatrice; di pantere. Cominceremo con qualcosa di semplice — non preoccuparti. Vediamo se riesci a uccidere 10 giovani pantere, per cominciare.$B$BRintracciarle è solo metà della sfida...",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Young Panther.",
  progress = "Un vero cacciatore di pantere sarebbe sul campo, a braccare la sua preda. Mostra un po' di impegno per il tuo obiettivo, $C, e torna là fuori.",
  reward = "Un buon inizio, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.",
}
T[191] = {
  title = "Maestria nella Caccia alla Pantera",
  desc = "Ora sei $Gpronto:pronta; ad alzare il livello. Se vuoi dimostrarti $Gdegno:degna; di frequentare gente del calibro di questi esperti di caccia grossa, dovrai dimostrare di saper uccidere 10 pantere.$B$BQuei bestioni sono più resistenti. Non sono facili come quelle giovani che uccidevi prima.",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Panther.",
  progress = "Va' a uccidere 10 pantere! Facci vedere cosa sai fare!",
  reward = "Esecuzione perfetta, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.",
}
T[192] = {
  title = "Maestria nella Caccia alla Pantera",
  desc = "Ora viene la parte difficile. Un vero cacciatore di pantere può dimostrare la sua abilità abbattendo le Pantere Shadowmaw, le più letali di Stranglethorn. Dimostraci che sai uccidere 10 di queste bestie.$B$BSe pensi che sia difficile seguirne le tracce, aspetta di provare a ucciderne una...",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Shadowmaw Panther.",
  progress = "Che ci fai qui, $N! Dovresti strisciare fra i cespugli e cercare di uccidere 10 Pantere Shadowmaw. Non ti credevi $Gun cacciatore:una cacciatrice; di grossa selvaggina?",
  reward = "Hai fatto un buon lavoro, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.",
}
T[193] = {
  title = "Maestria nella Caccia alla Pantera",
  desc = "Hai quasi dimostrato di essere $Gun maestro:una maestra; nella caccia alla pantera. Una pantera di nome Bhag'thera si aggira per la giungla. Finora Bhag'thera è sfuggito al nostro gruppo. Vediamo se con la tua abilità riesci a uccidere il grande Bhag'thera.$B$BPortami la Zanna di Bhag'thera e ti sarai $Gguadagnato:guadagnata; il mio rispetto!",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu gli porti la Fang of Bhag'thera.",
  progress = "Bhag'thera può rivelarsi una bestia sfuggente. Come procede la caccia?",
  reward = "Dunque il grande Bhag'thera è morto! Alla tua salute, $N. Sei davvero $Gun:una; $C possente!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.",
}
T[194] = {
  title = "Maestria nella Caccia al Raptor",
  desc = "Allora pensi che le tue abilità di caccia siano in forma smagliante? Posso metterle alla prova in un attimo. Addentrati in quella giungla e uccidi 10 Raptor di Stranglethorn. Vedremo quanto vali davvero come $Gcacciatore:cacciatrice; di grossa selvaggina.$B$BE no, non ti dirò dove trovarli! Scovare le bestie è metà della sfida.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Stranglethorn Raptor.",
  progress = "Non ho mai visto un cacciatore abbattere qualcosa standosene accanto al falò. Avevi intenzione di uccidere quei Raptor di Stranglethorn o speravi che morissero di vecchiaia?",
  reward = "Ben fatto, $Gvecchio mio:mia signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.",
}
T[195] = {
  title = "Maestria nella Caccia al Raptor",
  desc = "Ora alziamo il livello della sfida e vediamo se sei all'altezza. Avventurati nella giungla e abbatti 10 di quei dannati Raptor Lashtail. Vediamo cosa sai fare!",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Lashtail Raptor.",
  progress = "Un vero cacciatore si concentra sulla sua preda. Tu, $Gamico mio:amica mia;, sembri più $Ginteressato:interessata; a chiacchierare attorno al falò. Ora fila là fuori e uccidi 10 Lashtail, prima che ci vada io a ripulire l'intera dannata giungla in una sola battuta di caccia.",
  reward = "Ecco come si appende un trofeo o due sopra il caro vecchio camino! Bella caccia, $N!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.",
}
T[196] = {
  title = "Maestria nella Caccia al Raptor",
  desc = "Vediamo come te la cavi con la prossima sfida. Là fuori c'è una razza di raptor molto astuta. Li chiamiamo Inseguitori della Giungla. Sono molto più difficili da scovare e da uccidere delle altre razze con cui hai tentato la fortuna finora. Uccidi 10 Inseguitori della Giungla e ti darò una soffiata sulla caccia migliore di tutte.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Jungle Stalker.",
  progress = "Bah! Che ci fai lì senza far niente, $N! Un vero cacciatore di grossa selvaggina non si arrende mai quando ha la preda nel mirino. Quegli Inseguitori della Giungla non verranno di corsa a questo fuoco per buttarcisi dentro. $GChe ragazzo sciocco:Che ragazza sciocca;.",
  reward = "Oh oh!! Ecco $Gun vero sterminatore:una vera sterminatrice; di raptor! Ben fatto, $Gvecchio mio:bella signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Jungle Stalkers.",
}
T[197] = {
  title = "Maestria nella Caccia al Raptor",
  desc = "Visto che nella giungla ti sei $Gdimostrato:dimostrata; così intraprendente, lascia che ti parli di un raptor feroce che nemmeno io sono riuscito a uccidere. Ajeck, qui presente, chiama Tethis questo astuto raptor.$B$BSe vuoi dimostrare di essere $Gun vero maestro:una vera maestra;, uccidi Tethis e portami il suo artiglio. Sarebbe un'impresa che nessun altro cacciatore di grossa selvaggina ha mai compiuto.",
  obj = "Hemet Nesingwary vuole che tu uccida Tethis, un raptor sfuggente e pericoloso di Stranglethorn.",
  progress = "Come procede la caccia a Tethis? Hai seguito le sue tracce fin qui all'accampamento, eh?",
  reward = "$GMaestro:Maestra; $N, $Glo sterminatore:la sterminatrice; di raptor!$B$BSuona bene, eh?",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.",
}
T[198] = {
  title = "Rifornimenti per il Soldato Thorsen",
  desc = "Mmh. Sì, in effetti avrei qualcosa da farti fare. Il Tenente Doren e i suoi seguaci, su a nord, hanno bisogno dei soliti rifornimenti da parte nostra.$B$BNon sono stati consegnati, e con i troll all'attacco mi serve qualcuno che se ne occupi. L'accampamento di Doren si trova a nord-ovest della strada, all'ingresso di Stranglethorn da Duskwood. Consegna i rifornimenti al Soldato Thorsen; se non è nell'accampamento, starà pattugliando la zona a sud. Se ne occuperà lui.$B$BBada, se fallisci, dovrai risarcirmi.",
  obj = "Consegna le Miscellaneous Goblin Supplies a Private Thorsen.",
  progress = "Sì? Cosa vuoi? Oh, i rifornimenti dei goblin. Strano vedere $Gun:una; $R che li consegna, di solito mandano uno dei loro. Non importa... non li hai toccati, vero? Bene, bene... non vorremmo che succedesse qualcosa alle nostre mine, oh no.",
  reward = "Queste mine ci aiuteranno a difenderci da quell'animale di Kurzen e dai suoi uomini. Grazie per averle portate. Se cerchi altro lavoro, probabilmente posso trovarti qualcosa da fare. E non dovrai avere a che fare con quei goblin, eh?",
  en_title = "Supplies to Private Thorsen",
  en_obj = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.",
}
T[200] = {
  title = "Herod l'Allibratore",
  desc = "Se Kurzen conosce il segreto di Thorsen, allora abbiamo una spia tra noi. Dobbiamo scoprire come è trapelato il segreto!$B$BIl contatto di Thorsen nell'accampamento di Kurzen era Herod l'Allibratore. Herod è l'ufficiale della logistica di Kurzen e sa tutto su come funziona l'Insediamento di Kurzen. Se riesci a prendere gli appunti o i registri di Herod, forse potremo scoprire come è stato smascherato Thorsen.$B$BQuando eravamo ancora con Kurzen, l'ufficio dell'Allibratore era all'ultimo piano dell'unica casa a due piani dell'accampamento. I suoi registri sono probabilmente ancora lì.",
  obj = "Trova Bookie Herod's Records.",
  reward = "Questi sono gli appunti e i registri di Herod l'Allibratore.$B$BTra questi ci sono: un elenco delle provviste dell'accampamento, richieste di materiali da parte del Colonnello Kurzen e varie lettere e altra corrispondenza.",
  en_title = "Bookie Herod",
  en_obj = "Find Bookie Herod's Records.",
}
T[201] = {
  title = "Indaga sull'Accampamento",
  desc = "Mi è giunta voce di un gruppo di cacciatori che si è accampato a monte del campo minerario della Venture Company sul Lago Nazferiti. Ora, di solito non me ne importerebbe, ma, per quanto sembri improbabile, ho sentito che tra quei cacciatori c'è Hemet Nesingwary. Ha di certo le conoscenze giuste, se capisci cosa intendo, e la prudenza non è mai troppa.$B$BPerché non vai a dare un'occhiata all'accampamento, $N, a vedere cosa stanno combinando?",
  obj = "Trova l'accampamento dei cacciatori e riferisci la sua posizione a Krazek, a Booty Bay.",
  progress = "Allora? Hai avuto fortuna nel trovare l'accampamento?",
  reward = "Mmm, quindi le mie informazioni erano corrette, come al solito. Interessante. Be', non credo che rischino di interferire con i nostri affari, ma forse hanno bisogno di qualcuno dei nostri eccellenti prodotti. Mmm...",
  en_title = "Investigate the Camp",
  en_obj = "Find the hunters' camp and report its location to Krazek in Booty Bay.",
}
T[202] = {
  title = "Il Colonnello Kurzen",
  desc = "Hai dato prova di te più e più volte, e la tua intraprendenza sembra rivaleggiare perfino con quella di Kurzen in persona. Potresti essere la salvezza della nostra banda di ribelli... se riesci a misurarti con Kurzen e a prevalere!$B$BComanda i suoi uomini dal fondo del Deposito. Devi entrare in quella caverna, farti strada tra i suoi difensori e affrontare Kurzen e i suoi capi.$B$BAddio, $N. La mia speranza, e il destino dei miei uomini, vengono con te.",
  obj = "Uccidi 6 Kurzen Elite e 4 Kurzen Subchief, e porta Kurzen's Head a Lieutenant Doren, al Rebel Camp.",
  progress = "Oso sperare che Kurzen e i suoi difensori siano morti, $N?",
  reward = "Non osavo credere ai rapporti, ma ci porti la prova che... Kurzen e i suoi capi sono stati sconfitti. Ci hai salvato!$B$BQueste giungle sono piene di minacce di ogni tipo, ma nessuna aveva l'intelletto crudele di Kurzen. Ora che non c'è più, possiamo tutti respirare più tranquilli.",
  en_title = "Colonel Kurzen",
  en_obj = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.",
}
T[203] = {
  title = "La Seconda Ribellione",
  desc = "Stiamo combattendo una battaglia persa contro il Colonnello Kurzen. Non solo è un tattico brillante, ma ci supera di numero almeno 10 a 1! Per sopravvivere dobbiamo usare contro di lui le sue stesse tattiche clandestine.$B$BEntra nel suo accampamento a est e uccidi i suoi uomini. Tanti. E vattene prima che i rinforzi riescano a chiuderti in trappola.",
  obj = "Uccidi 15 Kurzen Jungle Fighter.$B$BTorna da Sergeant Yohwa, al Rebel Camp.",
  progress = "Spero che la tua caccia sia andata a buon fine, $N. Senza il tuo aiuto non resisteremo a lungo contro di lui.",
  reward = "Ben fatto. La perdita di quei Combattenti della Giungla allenterà un po' la pressione sul nostro accampamento.$B$BMa ora che hai avuto un assaggio delle forze che affrontiamo, vuoi ancora schierarti dalla nostra parte??",
  en_title = "The Second Rebellion",
  en_obj = "Kill 15 Kurzen Jungle Fighters.$B$BReturn to Sergeant Yohwa at the Rebel Camp.",
}
T[204] = {
  title = "Cattiva Medicina",
  desc = "Per avere una possibilità contro Kurzen, dobbiamo neutralizzare chi lo sostiene con le cure. Si è circondato di un gran numero di Guaritori che curano le sue truppe con i Medicinali della Giungla e avvelenano i nostri combattenti con gli Estratti di Felce Velenosa.$B$BCi servono quei rimedi per curare la nostra gente, e ci serve un campione di quegli estratti da studiare, per riuscire a preparare rimedi nostri. Cerca entrambi nell'Insediamento di Kurzen — i suoi Guaritori avranno i rimedi, e gli estratti saranno probabilmente stipati in qualche cassa di rifornimenti dell'accampamento.",
  obj = "Porta 7 Jungle Remedy e 1 Venom Fern Extract a Sergeant Yohwa, al Rebel Camp.",
  progress = "Aspetto quei rimedi e quell'estratto, $N.",
  reward = "Ben fatto, $N. Grazie a questi rimedi molti più di noi resteranno vivi e in grado di combattere. E gli estratti ci aiuteranno a preparare rimedi nostri.",
  en_title = "Bad Medicine",
  en_obj = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.",
}
T[205] = {
  title = "Stregoneria Troll",
  desc = "Mentre studio le leggende che hai recuperato, raccogli per me degli strumenti della malvagia magia troll. Entra nel territorio dei troll Skullsplitter, un'altra tribù che vive lontano, a sud, e procurati dei Feticci degli Skullsplitter dai loro Stregoni e Mystic.",
  obj = "Porta 4 Skullsplitter Fetish a Brother Nimetz, al Rebel Camp.",
  progress = "Hai quei feticci, $N? Potrebbero custodire il segreto della decadenza di Kurzen... devo saperlo!",
  reward = "Grazie. Studierò questi feticci e vedrò se custodiscono il segreto della caduta di Kurzen nel male.",
  en_title = "Troll Witchery",
  en_obj = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.",
}
T[206] = {
  title = "Mai'Zoth",
  desc = "Kurzen sarà anche morto, ma... ciò che lo ha spinto al male vive ancora! Con i miei studi ho scoperto questo: un Mago Ogre — Mai'Zoth — vive in un Tumulo degli Ogre tra le montagne orientali di Stranglethorn. Si dice che usi una magia capace di controllare la mente, e non ho dubbi che sia stato lui a corrompere Kurzen.$B$BSe Mai'Zoth resterà in vita, il suo male potrebbe influenzare altri, e perfino far emergere un altro Kurzen.$B$BUccidilo, e portami il suo Occhio della Mente, l'artefatto che usa per corrompere gli altri.",
  obj = "Porta il Mind's Eye a Brother Nimetz, al Rebel Camp.",
  progress = "Ti do la mia benedizione. La forza di Mai'Zoth è pari solo alla sua malvagità.",
  reward = "Aha! Ce l'hai fatta! Sei una grande forza del bene, $N, e che la tua forza non si affievolisca mai!$B$BStudierò questo Occhio della Mente e stabilirò se può essere usato per il bene. Altrimenti... dovrà essere distrutto.",
  en_title = "Mai'Zoth",
  en_obj = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.",
}
T[207] = {
  title = "Il Mistero di Kurzen",
  desc = "Un tempo il Colonnello Kurzen era un uomo grande e nobile — devo scoprire cosa lo ha fatto sprofondare nella depravazione! Forse è sotto l'influsso della magia troll. Per averne conferma, devo studiare alcune delle loro leggende.$B$BCi sono 4 tavolette nascoste tra le rovine troll di Stranglethorn. Devo vedere cosa c'è scritto su queste tavolette! Trascrivi i loro segni e riportami le trascrizioni.$B$BLa prima tavoletta è nelle Rovine di Bal'lal, la seconda nella Scogliera Immonda, e la terza e la quarta nelle Rovine di Zul'Kunda.",
  obj = "Trova le 4 tavolette e riporta le loro leggende a Brother Nimetz.",
  progress = "$N! Hai le leggende troll? Devo conoscere i loro segreti!",
  reward = "Grazie, $N. Studierò queste leggende per vedere se c'è qualche legame tra i troll e il male che si è impadronito del Colonnello Kurzen.",
  en_title = "Kurzen's Mystery",
  en_obj = "Find the 4 tablets and bring their legends back to Brother Nimetz.",
}
T[208] = {
  title = "Cacciatore di Grossa Selvaggina",
  desc = "$N, sei $Gun cacciatore degno:una cacciatrice degna; della nostra compagnia. Dai campi di battaglia di Lordaeron alla giungla più profonda, raramente ho visto un'abilità con le armi pari a quella che hai dimostrato.$B$BHai ucciso la feroce Sin'Dall, lo sfuggente Bag'thera e l'infido Tethis. Ma il vero premio è la testa di Re Bangalash. Quella tigre bianca è il motivo per cui sono qui. È da un bel po' di tempo che ho messo gli occhi su di lui. Uccidi Re Bangalash e avrai dimostrato che la tua abilità di caccia non è seconda a nessuno.",
  obj = "Hemet Nesingwary vuole che tu gli porti la testa di King Bangalash, la grande tigre bianca.",
  progress = "Vedo che sei $Gtornato:tornata;, $Gvecchio mio:ragazza mia;. Re Bangalash mi ha costretto molte volte a tornare all'accampamento strisciando. Tieni duro.",
  reward = "Accidenti, ottimo lavoro! Benone! Congratulazioni, $N, per essere $Griuscito:riuscita; dove altri hanno fallito.$B$BSono onorato di annoverarti tra i compagni della nostra grande squadra di caccia. Nessuno dubiterà mai della tua abilità nella caccia e nel seguire le tracce!$B$BAlla tua salute, perbacco! Alla salute!",
  en_title = "Big Game Hunter",
  en_obj = "Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.",
}
T[209] = {
  title = "Zanne degli Skullsplitter",
  desc = "Uccidere abbastanza tigri da sostenere l'esportazione di zanne di tigre verso le isole dei South Seas è costoso e difficile. Per fortuna abbiamo messo a punto una tecnica che ci permette di prendere dei comuni oggetti simili a corna e trasformarli in falsi impossibili da scoprire.$B$BLa cosa più somigliante che abbiamo trovato, incredibilmente, sono le zanne dei troll Skullsplitter.$B$BEhi, prima che tu dica qualcosa: occhio non vede, cuore non duole, giusto? Portamene un bel po', così possiamo metterci al lavoro sulla spedizione del mese!",
  obj = "Procura 18 Skullsplitter Tusk e riportali a Kebok.",
  progress = "Tipi tosti, eh? Allora, hai avuto fortuna? Scusa se sembro impaziente, ma questa faccenda è stata una grossa spina nel fianco! Allora?",
  reward = "Ah, ottimo lavoro, ottimo lavoro! Uff, anche se avresti potuto pulire meglio il — Be', non importa, non importa! Grazie, $N: grazie al tuo aiuto la nostra attività vedrà di sicuro aumentare produzione e rendimento! Bene, bene, e ora passiamo ad altro...",
  en_title = "Skullsplitter Tusks",
  en_obj = "Acquire 18 Skullsplitter Tusks and return them to Kebok.",
}
T[210] = {
  title = "La Cucina di Krazek",
  desc = "All'accampamento cucino quasi sempre io. Ed era un gran lavoro, finché non ho comprato una pentola da cucina meccanica da un mercante goblin di Booty Bay. La pentola è una meraviglia! Mi ha fatto risparmiare ore e ore... finché non si è rotta!$B$BPuoi riportare la pentola al goblin per me, così la aggiusta? Si chiama Krazek.",
  obj = "Porta Krazek's Crock Pot al goblin Krazek.",
  progress = "Salve! Mi hai portato qualcosa?",
  reward = "Ah, capisco, è una Pentola a Pressione di Krazek! Un lavoro geniale, ma ogni tanto può rompersi una molla o saltare un ingranaggio. Vediamo cosa c'è che non va in questa...$B$BAha! Il caricatore a vapore è arrugginito, ha una guarnizione a snodo incrinata e al fobulatore mancano dei denti. Mi sorprende che la pentola riuscisse anche solo a far bollire una rapa in questo stato!$B$BSe posso aggiustarla? Certo che posso aggiustarla!$B$BMa c'è un prezzo. Oh sì, c'è sempre un prezzo...",
  en_title = "Krazek's Cookery",
  en_obj = "Bring Krazek's Crock Pot to Krazek the goblin.",
}
T[211] = {
  title = "Ahimè, Andorhal",
  desc = "Ahimè, è giunta l'ora di attaccare Andorhal e scacciare il lich che la controlla!$B$BÈ fra le rovine della città che il lich — Araj l'Evocatore — esercita il suo dominio. Lo sorvegliano numerose creature del Flagello che circondano i resti del centro cittadino, e la scorta personale di guardiani al suo diretto servizio è temibile. Avrai bisogno di molti alleati anche solo per sperare di affrontarlo con successo.$B$BDistruggi Araj, $N, e portami come prova una scheggia del suo filatterio!",
  obj = "Porta Araj's Phylactery Shard a Commander Ashlam Valorfist a Chillwind Camp, nelle Western Plaguelands.",
  progress = "Il compito ti è stato affidato, $N. Hai con te una scheggia del filatterio del lich, come prova che l'hai portato a termine?",
  reward = "Ce l'hai fatta! Araj... il lich è finalmente sconfitto!$B$BOggi hai reso un servizio immenso all'Alleanza, $N. Il tuo coraggio e la tua perseveranza dimostrano cosa significa essere un vero eroe. Ti prego — accetta questo come segno, perché tutti vedano e sappiano che hai dato all'Alleanza una vittoria che resterà nei secoli!",
}
T[212] = {
  title = "Un Piatto da Servire Freddo",
  desc = "Uno dei miei piatti più famosi è il Basilisco Ghiacciato in Vinaigrette al Lime. Ma il problema è che... la carne è impossibile da tenere fresca, e stasera devo servire il piatto per il compleanno di un nobile!$B$BQuindi, se riesci a portarmi in fretta un Cosciotto di Basilisco Ghiacciato da un Basilisco Occhiofreddo appena ucciso, ti dovrò un banchetto da re!$B$BSi sa che i Basilischi Occhiofreddo si aggirano lungo le dune della spiaggia nel nord-ovest di Stranglethorn, quindi hai molta strada da fare. E fa' presto!",
  obj = "Uccidi un Cold Eye Basilisk, prendi un Chilled Basilisk Haunch e riportalo ad Angus Stern, al Blue Recluse.$B$B<Per riuscire in questa missione non devi liberare il tuo spirito.>",
  progress = "$N! Hai quel cosciotto? Devo cominciare presto a prepararlo, o il banchetto sarà rovinato!",
  reward = "Ah, questo andrà benissimo! Mille, mille grazie!$B$BOra, se vuoi scusarmi, devo tagliare, marinare e guarnire il cosciotto per il banchetto.",
  en_title = "A Meal Served Cold",
  en_obj = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.",
}
T[213] = {
  title = "Acquisizione Ostile",
  desc = "Stavolta l'ha fatta grossa! Già era abbastanza grave che Gelriz scalzasse con la forza i magnati nominati dai principi del commercio, ora cerca pure di mettersi in mezzo agli affari del pirata più famigerato!$B$BRevilgaz non lo tollererà, e mi ha detto di occuparmi del problema a modo mio.$B$BA modo mio? Furto. I geologi della Venture Co. vicino al Lago Nazferiti sono molto interessati a quegli strani cristalli blu che trovano nelle miniere. Portami dei campioni della pietra presi dai loro geologi; non m'importa cosa dovrai fare per procurarteli.",
  obj = "Recupera 8 Tumbled Crystal e riportali a Kebok, a Booty Bay.",
  progress = "Mi servono quelle pietre, $N. Con ogni mezzo! Fallo e basta, risparmiami i dettagli!$B$BContano i risultati, $N, niente di più, niente di meno.",
  reward = "Affascinante. Che i cristalli siano stati levigati con questo procedimento può solo significare che intendono usarli come una specie di combustibile o come qualche altro catalizzatore. Di più non so. Bisognerà spedire dei campioni al Chimico Capo Gigglefont.",
  en_title = "Hostile Takeover",
  en_obj = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.",
}
T[214] = {
  title = "Bandane di Seta Rossa",
  desc = "Non è un segreto che il segno distintivo della Defias Gang siano le Bandane Rosse. Ma abbiamo scoperto che il materiale di cui sono fatte indica il grado di chi le porta.$B$BDetto questo, voglio che tu elimini quanti più Defias di alto grado puoi. I membri di grado più alto si troveranno senz'altro nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Bandane di Seta Rossa come prova della loro morte e ti ricompenserò. Buona fortuna, $N.",
  obj = "Scout Riell, alla Torre di Sentinel Hill, vuole che le porti 10 Red Silk Bandana.",
  progress = "Stai riprendendo la nostra terra alla banda dei Defias? Se è così, mostrami 10 Bandane di Seta Rossa come prova.",
  reward = "Ben fatto, $N! A nome della People's Militia ti rendo onore per il tuo impegno. Presto restituiremo questa terra alla gente, con l'aiuto di anime coraggiose come te.",
  en_title = "Red Silk Bandanas",
  en_obj = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.",
}
T[215] = {
  title = "Segreti della Giungla",
  desc = "Grazie per avermi salvato, $N. So cosa può sembrare, ma... lasciami spiegare.$B$BIl Tenente Doren mi aveva incaricato di arruolarmi di nuovo tra gli uomini di Kurzen, per spiarli e portare ai ribelli informazioni di cui hanno un disperato bisogno. Quello che hai visto qui era, credevo, la mia occasione per infiltrarmi nell'Insediamento di Kurzen. Mi sbagliavo, e grazie ancora per avermi salvato.$B$BEra una missione segretissima, quindi non devi dirlo a nessuno. Ma se parli con Doren, te lo spiegherà lui.",
  obj = "Parla con Lieutenant Doren, al Rebel Camp.",
  reward = "Sì, quello che ti ha detto Thorsen è vero. Devi essere $Gdiscreto:discreta; su questa faccenda. Un tempo noi ribelli eravamo ferocemente leali al Colonnello Kurzen. Ma la corruzione di Kurzen era tale che la nostra passione si è trasformata in rabbia. Se si venisse a sapere che di recente il Soldato Thorsen ha avuto a che fare con gli uomini di Kurzen, una notte si ritroverebbe con la gola tagliata.$B$BPer quanto ne so, solo il Sergente Yohwa, Thorsen e io eravamo al corrente della missione di Thorsen. Ma dev'esserci qualcun altro. Un traditore.",
  en_title = "Jungle Secrets",
  en_obj = "Speak with Lieutenant Doren at the Rebel Camp.",
}
T[216] = {
  title = "Tra l'Incudine e i Thistlefur",
  desc = "I mezzorsi Thistlefur minacciano la nostra espansione! Il Villaggio dei Thistlefur, a est di qui, blocca la via tra noi e l'Avamposto di Splintertree. È un percorso che aggirerebbe il villaggio di Astranaar; senza di esso, diamo all'Alleanza una via di espansione in più.$B$B$N, non possiamo permettere... un divario nelle vie di espansione!$B$BVa' al Villaggio dei Thistlefur e dirada i mezzorsi. Riceverai un compenso per questo incarico, ma soprattutto farai il tuo dovere per l'Orda!",
  obj = "Abbatti 12 Thistlefur Avenger e 12 Thistlefur Shaman; la maggior parte si trova a est della Spiaggia di Zoram, nel Villaggio dei Thistlefur. Fatto questo, torna da Karang Amakkar all'Avamposto di Zoram'gar, in Ashenvale.",
  progress = "Hai portato la battaglia ai Thistlefur? Con una via libera tra le nostre basi, le nostre possibilità di prenderci tutta Ashenvale aumentano moltissimo.",
  reward = "Ben fatto, $C, ben fatto! Continuerò a mandare forze a diradare i mezzorsi, ma almeno posso contare su un'altra via, libera dagli impicci dell'Alleanza. La conquista di Ashenvale da parte dell'Orda è ormai in pieno svolgimento!$B$BOggi ti sei $Gguadagnato:guadagnata; la paga, $Geroe:eroina;. Ti rendo onore!",
  en_title = "Between a Rock and a Thistlefur",
  en_obj = "Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.",
}
T[219] = {
  title = "Disperso in Combattimento",
  desc = "Finalmente, amici dell'Alleanza!$B$BAiuto... vi prego...$B$BL'ultima cosa che ricordo è che quegli Orchi immondi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un brutto colpo alla testa e poi è stato tutto buio. Adesso mi tengono prigioniero in questa grotta. Aiutatemi, sono ferito gravemente.$B$BMi servirà aiuto per tornare in paese... vi prego... siete la mia ultima speranza...",
  obj = "Proteggi Corporal Keeshan nel viaggio di ritorno a Redridge.",
  progress = "Sì?",
  reward = "Hai servito bene il Regno, $C. Grazie per aver aiutato il Caporale Keeshan a fuggire da quei temuti Orchi Blackrock. Sarai $Gricompensato:ricompensata; per il coraggio che hai dimostrato oggi.",
  en_title = "Missing In Action",
  en_obj = "Protect Corporal Keeshan on the journey back to Redridge.",
}
T[220] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Islen avrà un ultimo compito per te prima di ricompensarti con il tuo prossimo totem. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque sia.$B$BOra va' e trovala. Ci rivedremo, un giorno.",
  obj = "Porta la Vial of Purest Water a Islen Waterseer, nelle Barrens.",
  progress = "Salve di nuovo, $N. Ti trovo bene.$B$BCosa ti riporta da me così presto?",
  reward = "Ah, una fiala d'acqua creata e benedetta da Brine, e raccolta da te, nientemeno.$B$BIl liquido di questa fiala sarà fondamentale per creare una sapta per te, ma servirà anche per un altro compito.$B$BLa sapta che creerò per te andrà usata per vedere gli spiriti dell'acqua al santuario della Silverpine Forest, a sud dell'Undercity. Le gocce rimaste... be', delle gocce rimaste ti parlerò se ti senti $Gpronto:pronta;.$B$BSei $Gpronto:pronta; per un altro viaggio, $N?",
  en_title = "Call of Water",
  en_obj = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.",
}
T[221] = {
  title = "Worgen nei Boschi",
  desc = "Avrai notato qualche worgen più grosso che si aggira con i Mistici delle Ombre nei boschi, no? Da quel che abbiamo visto, sono questi Emissari Oscuri a formare il grosso dei worgen.$B$BNelle mie perlustrazioni ho notato anche che hanno invaso il Frutteto Marcio, a sud-ovest del paese. Questi worgen sono un po' più coriacei di quelli che hai affrontato l'ultima volta.$B$BSta' in guardia.",
  obj = "Uccidi 12 worgen Nightbane Dark Runner per Calor, a Darkshire.",
  progress = "Già di ritorno, $N? Spero che tu non sia $Gvenuto:venuta; a dirmi che hai rinunciato.",
  reward = "Te la sei cavata bene contro gli Emissari Oscuri, $N. Ma sembra che il loro numero sia inesauribile. Ogni volta che facciamo progressi, ne spuntano altri a riempire i ranghi.$B$BQual è il potere maligno che li attira qui? Perché sono venuti a turbare la nostra terra infelice...$B$BIo ripongo la mia fiducia nel Maestro Carevin. Di sicuro andrà a fondo della questione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.",
}
T[222] = {
  title = "Worgen nei Boschi",
  desc = "Quel che hai fatto finora mi ha convinto che sei $Gpronto:pronta; ad affrontare i worgen più duri che infestano i boschi.$B$BFra i worgen che hanno fatto di questi boschi la loro nuova casa, gli Zannavile e i Corrotti si sono rivelati i più pericolosi. Si sono sistemati vicino ad alcune caverne e nella miniera a sud.$B$BDa lontano si vede perfino la luce dei loro falò...",
  obj = "Uccidi 8 worgen Nightbane Vile Fang e 8 Nightbane Tainted One per Calor, a Darkshire.",
  progress = "Bestie che mettono paura, vero? Ma non temere, $N: chi sta dalla parte della Luce non cadrà mai!",
  reward = "$N, a dirti la verità non credevo che saresti $Garrivato:arrivata; fin qui, ma è chiaro che sei $Gun:una; $C con cui fare i conti. Anzi, se vuoi unirti ufficialmente alla lotta del Maestro Carevin, ti scriverò volentieri una lettera di raccomandazione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.",
}
T[223] = {
  title = "Worgen nei Boschi",
  desc = "Ecco qua, $N. Porta questo messaggio al Maestro Carevin.$B$B<Tira fuori in fretta un pezzo di pergamena sbiadita e te lo porge.>$B$BAncora qualcuno come te, e saremo più numerosi dei Guardiani della Notte! Forse allora potremmo portare a termine il lavoro che oggi mandiamo avanti in pochi.",
  obj = "Porta Calor's Note a Jonathan Carevin.",
  progress = "Sì, che c'è? Fa' in fretta, ho questioni urgenti di cui occuparmi.",
  reward = "Scusa l'accoglienza fredda, $N, ma come avrai capito sono un uomo estremamente occupato. Vedo che hai fatto colpo su Calor — e ti assicuro che non è cosa da poco — e che ti ha dato la sua raccomandazione.$B$BIn giro c'è gente poco raccomandabile, $N, e ci serve l'aiuto di tutti quelli che hanno dimostrato il proprio valore. Combattiamo contro i demoni, i non morti e chi dà loro aiuto. Sii vigile, sta' $Gattento:attenta;, e non fidarti di nessuno che non aiuti la nostra causa.$B$BGloria nella Luce.",
  en_title = "Worgen in the Woods",
  en_obj = "Bring Calor's note to Jonathan Carevin.",
}
T[225] = {
  title = "La Tomba Consunta",
  desc = "Sulla lapide consunta si legge soltanto:$B$BMORGAN LADIMORE$B$B<Guardando meglio, noti che la terra sopra la tomba è stata smossa di recente, e che una buona parte è stata spostata...>",
  obj = "Parla con Sirra Von'Indi, a Darkshire.",
  reward = "Morgan Ladimore?$B$BAhh, sì, certo. La sua è una storia lunga e dolorosa. Lo conoscevo, be', prima che partisse per la guerra, ma è stata l'ultima volta che l'ho visto. Era un uomo nobile e buono, ma ha fatto una brutta fine.$B$BAspetta, qui dovrei avere qualcosa che racconta la storia meglio dei miei ricordi...",
  en_title = "The Weathered Grave",
  en_obj = "Speak with Sirra Von'Indi in Darkshire.",
}
T[226] = {
  title = "Lupi alle Calcagna",
  desc = "Io e Sven abbiamo giorni pericolosi davanti, con il Negromante a est e tutto il resto. E qui fuori, soli come siamo, il cibo dobbiamo cacciarcelo da noi. Sembra che ogni volta che torno all'accampamento con addosso un po' di carne, dalla foresta sbuchino metalupi affamati o rabbiosi in cerca di un boccone. Inutile dirlo: vivere qui fuori è un mestiere pericoloso!$B$BMa se ci liberassi da un po' di quei lupi, per noi sarebbe più facile. Si aggirano soprattutto a nord e a est di qui, vicino al fiume.",
  obj = "Uccidi 12 Starving Dire Wolf e 8 Rabid Dire Wolf, poi torna da Lars all'Accampamento di Sven, al confine occidentale di Duskwood.",
  progress = "Sei ancora a caccia di lupi...?",
  reward = "Oh, bene. Hai diradato parecchio quel branco, e senza quei lupi alle calcagna possiamo concentrarci su Morbent Fel.$B$BTieni, prendi un po' di questi Fagotti Lampeggianti. Li fanno in città, e molti sono stati donati a Sven per aiutarlo nella sua causa.",
  en_title = "Wolves at Our Heels",
  en_obj = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.",
}
T[227] = {
  title = "Morgan Ladimore",
  desc = "<Fruga tra gli scaffali e ne tira fuori un libro rilegato in pelle.>$B$BSe vuoi saperne di più, potresti chiedere ad Althea: è lei che si è occupata dei... guai... con lui, ultimamente.",
  obj = "Parla con Commander Althea Ebonlocke, a Darkshire.",
  reward = "Morgan Ladimore? Mai sentito...$B$BOh, intendi Mor'Ladim! Non hai sentito la storia, immagino?$B$BBe', te la faccio breve. Un non morto errante che si fa chiamare Mor'Ladim si aggira per Duskwood. Da quel che abbiamo capito, sembra essere il corpo non morto di Morgan Ladimore, che a quanto pare tu conosci. Ci sta dando problemi di ogni tipo: attacca i Guardiani di pattuglia e uccide la gente.$B$B<Ti squadra.>$B$BSembri abbastanza capace: forse potresti dargli pace tu.",
  en_title = "Morgan Ladimore",
  en_obj = "Speak with Commander Althea Ebonlocke in Darkshire.",
}
T[228] = {
  title = "Mor'Ladim",
  desc = "Da quel che mi dicono i miei esploratori, Mor'Ladim vaga per tutta Duskwood, seguendo un percorso strano e tortuoso attraverso il cimitero. L'abbiamo sepolto oltre la casa sulla collina: sai dov'è?$B$BNon c'è niente che io possa fare per aiutarti, ma ti auguro buona fortuna.",
  obj = "Uccidi Mor'Ladim, poi porta il suo teschio a Commander Althea Ebonlocke, a Darkshire.",
  progress = "Non ti biasimo se hai difficoltà con lui, $N. Mor'Ladim ci è già costato alcuni dei nostri Watcher più forti.",
  reward = "L'hai ucciso? Non è cosa da poco, $N! A nome della gente di Darkshire e dei Guardiani della Notte, ti ringrazio.$B$BAh... c'è però una piccola questione...",
  en_title = "Mor'Ladim",
  en_obj = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.",
}
T[229] = {
  title = "La Figlia Sopravvissuta",
  desc = "Avrei dovuto dirtelo prima...$B$BCome dire...$B$BMorgan può anche aver creduto che la sua famiglia fosse tutta morta, ma in realtà sua figlia Sarah Ladimore adesso è una Watcher. L'hanno sempre tormentata le... circostanze... della morte del padre. Forse potresti andare tu a darle la notizia.",
  obj = "Parla con Watcher Sarah Ladimore, a Darkshire.",
  reward = "Sì? Mio padre...$B$B<Abbassa lo sguardo.>$B$BVorrei... aver potuto fare qualcosa per lui... Se solo gli avessi parlato prima che...",
  en_title = "The Daughter Who Lived",
  en_obj = "Speak with Watcher Sarah Ladimore in Darkshire.",
}
T[230] = {
  title = "Accampamento di Sven",
  desc = "Scavando nel cumulo, trovi un piccolo libro sporco di terra.$B$BIl libro non ha titolo, ma... contiene informazioni che Sven vorrebbe sapere.",
  obj = "Porta il Book from Sven's Farm a Sven.",
  progress = "Hai trovato cosa?? Ti prego, fammelo vedere...",
  reward = "<Sven legge le pagine del libro, poi lo chiude di colpo.>$B$BQuella figura in ombra che ho visto ha assistito alla morte della mia famiglia! Ci sono domande che vorrei fare a quell'uomo... se solo sapessi chi era!",
  en_title = "Sven's Camp",
  en_obj = "Bring the Book from Sven's Farm to Sven.",
}
T[231] = {
  title = "L'Amore di una Figlia",
  desc = "Tieni, prendi questo e posalo sulla sua tomba. Forse... in qualche modo saprà che sto bene, e che nessuno di noi lo ritiene responsabile di quel che è successo.$B$B<Adesso ha le lacrime agli occhi, mentre si sfila un anello dalla mano destra e te lo preme fra le mani.>$B$BE... grazie, $N.",
  obj = "Porta l'anello di Sarah Ladimore alla tomba di Morgan Ladimore.",
  progress = "Lasciami in pace...",
  reward = "<Una voce spettrale risuona nel vento...>$B$BQuesto è...? Sarah? Può essere che sia ancora viva? Mi si toglie un peso dalle spalle...$B$B$N. Prendi la mia spada, Archeus. Ora che la mia anima trova pace, non mi serve più. Fu forgiata per fare del bene e, anche se io mi sono dimostrato indegno di impugnarla, forse tu, con essa, porterai avanti la Luce.$B$BLys, amore mio...",
  en_title = "A Daughter's Love",
  en_obj = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.",
}
T[232] = {
  title = "Una Commissione per la Speziale Zinge",
  desc = "La Royal Apothecary Society ha bisogno del tuo aiuto. Ascolta bene, e dal mio piano potremmo trarre profitto tutti e due.$B$BLo Speziale Keever, nella stanza accanto, sarà anche... tocco... ma le sue ricerche potrebbero dare frutti, se a portarle avanti fosse un ricercatore capace. Per fortuna, io sono proprio una ricercatrice del genere. Voglio che porti questo ordine d'acquisto ad Alessandro Luca, il proprietario di Cianfrusaglie della Luna Blu; ti darà un'attrezzatura per le analisi. Quando ce l'hai, riportamela e ti spiegherò il tuo compito nei dettagli.",
  obj = "Porta Zinge's Purchase Order ad Alessandro Luca a Undercity.",
  progress = "Sì, e in che cosa posso esserti utile? Sei qui per affari della Royal Apothecary Society, o sei $Gvenuto:venuta; soltanto a rallegrarmi la giornata?",
  reward = "Ah, a Zinge serve un'attrezzatura, dunque? Mi rattrista che Zinge non scelga di onorarmi con la sua dolce presenza.$B$BMolto bene, lascia che ti procuri un'attrezzatura.",
}
T[238] = {
  title = "Una Commissione per la Speziale Zinge",
  desc = "L'attrezzatura è pronta, $N. Di sicuro la Speziale Zinge la vorrà il prima possibile. Portagliela senza indugio, e falle sapere che metterò il costo dell'attrezzatura sul conto della Society. Inoltre, ti prego di porgerle i miei più calorosi saluti.$B$BBe', non restare lì $Gimpalato:impalata;. È questa la vita di un semplice corriere, no?",
  obj = "Porta il Field Testing Kit ad Apothecary Zinge a Undercity.",
  progress = "Sì, anch'io trovo Luca inquietante quanto lo trovi tu. Non importa — dammi l'attrezzatura per i campionamenti sul campo. Dovrò modificarla un po' perché rilevi i materiali di base giusti.$B$BCe l'hai, l'attrezzatura, vero?",
  reward = "Bene — mi fa piacere lavorare con qualcuno che si fa un punto d'onore di non farmi perdere tempo.$B$BQuando avrò fatto qualche modifica a questa attrezzatura, sarai $Gpronto:pronta; a partire per il lavoro sul campo. La userai per raccogliere dei dati essenziali per il compito che ci aspetta.$B$BMi basterà un momento per finire le modifiche. Mentre aspetti, ti conviene cominciare a pensare a cosa vuoi portarti nel deserto.$B$BSì, ho detto il deserto.",
}
T[243] = {
  title = "Sul Campo",
  desc = "Andrai nel deserto di Tanaris, a verificare la consistenza dei tessuti dei basilischi, degli scorpid e delle iene che ci vivono. Procurati dei campioni di tessuto e usali con il kit per le analisi che porti con te; metti in conto che una buona parte dei campioni non supererà la prova. Mi servono otto campioni accettabili per ogni tipo di creatura.$B$BInoltre, i goblin di Gadgetzan hanno una fonte di energia che va usata con questo genere di kit modificato. Parla con l'Ingegnere Capo Bilgewhizzle e procuratene una per il kit.$B$BTorna da me solo quando ci sarai $Griuscito:riuscita;.",
  obj = "Parla con Chief Engineer Bilgewhizzle a Gadgetzan per avere una fonte di energia per il kit per le analisi.",
  reward = "Ah, le nostre fonti di energia modello 4711-FTZ! Di solito le usiamo per alimentare i pozzi d'acqua, ma GRAZIE AI VILI NOMADI, in questo momento di fonti di energia ne abbiamo fin troppe.$B$BCerto, posso procurarti una fonte di energia per quel losco esperimento scientifico, qualunque sia, che credi di tenermi nascosto. Mica sarà gratis, però, $R. A Gadgetzan niente è gratis.",
}
T[245] = {
  title = "Minacce a Otto Zampe",
  desc = "Salve, $C. Avrai visto quei ragni che si sono impadroniti del confine occidentale, no? Quelle minacce a otto zampe sono troppo per noi, e la Comandante non ha uomini a sufficienza da mandare così lontano da Darkshire.$B$BMi dispiace chiedertelo, ma sembri in grado di occupartene. Non posso prometterti niente di grande valore, ma posso ricompensarti se ci aiuti a stanare quegli insetti immondi.$B$BAh, e un consiglio: se puoi, evita il loro veleno.",
  obj = "Uccidi 15 Pygmy Venom Web Spider, poi torna a riferire a Watcher Dodds, a Duskwood.",
  progress = "Faresti meglio a stare $Gattento:attenta; con quei ragni: ci ho rimesso qualche uomo, e credimi, non è un bello spettacolo un uomo appeso a testa in giù nelle loro ragnatele dopo che il veleno ha cominciato ad ammorbidirlo.$B$BNon vorrei vederti diventare il pranzo di uno di quegli insetti.",
  reward = "Ah! Sei $Gtornato:tornata;. E a quanto pare non troppo $Gmalconcio:malconcia;. Naturalmente, $N, i Guardiani della Notte ti sono grati per il tuo lavoro, e una ricompensa te l'avevo promessa, quindi eccola.",
  en_title = "Eight-Legged Menaces",
  en_obj = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.",
}
T[247] = {
  title = "La Caccia È Conclusa",
  reward = "$N, hai ucciso tutte e tre le bestie che compongono la Caccia di Ashenvale. Mi hai portato prove sufficienti della loro fine; la tua forza e la tua tenacia sono fuori discussione. Nelle tue vene scorre il sangue di $Gun cacciatore:una cacciatrice;, e meriti ogni elogio!$B$BTi prego, accetta questo ninnolo in segno di congratulazioni per le grandi imprese che hai compiuto oggi ad Ashenvale per l'Orda. Che i tuoi antenati veglino su di te!",
  en_title = "The Hunt Completed",
}
T[248] = {
  title = "Guardare Più Lontano",
  desc = "Ho tenuto d'occhio la Torre di Ilgalar, e percepisco che Morganth è in conflitto con gli Orchi del Mastio di Stonewatch. Non conosco il motivo della loro contesa, ma tu puoi aiutarmi a sciogliere il mistero.$B$BPrendi un altro Glifo di Azora, poi sali in cima alla torre di guardia ancora intatta accanto al Mastio di Stonewatch.$B$BTrova un oggetto adatto su cui posare il Glifo. Una cassa o un vaso — un posto dove il glifo non venga notato — farà al caso mio.",
  obj = "Sali sulla torre di guardia intatta accanto allo Stonewatch Keep.$B$BTrova un contenitore adatto dove mettere il Glyph of Azora.",
  progress = "Questo vaso un tempo conteneva un liquore dall'odore disgustoso, ma ora giace vuoto e dimenticato su un paio di barili.",
  reward = "È un recipiente adatto per il Glifo di Azora, e permette a Theocritus di sondare le menti di chi sta nel Mastio di Stonewatch.",
  en_title = "Looking Further",
  en_obj = "Climb the intact watch tower beside Stonewatch Keep.$B$BFind a suitable container to place the Glyph of Azora.",
}
T[249] = {
  title = "Morganth",
  desc = "Dopo averlo osservato a lungo, ho scoperto i piani di Morganth.$B$BCerca la Falce di Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains, e il regno di Stormwind, sentiranno la sua oscura potenza.$B$BNon sono pronto a misurarmi con Morganth, ma temo che vada affrontato ora. Quindi devi entrare tu nella Torre di Ilgalar e affrontare Morganth.$B$BSconfiggilo e portami il suo Pendente dell'Ombra. Se lo farai, il regno ti dovrà molto.",
  obj = "Sconfiggi Morganth.$B$BPorta il suo Pendant of Shadow a Theocritus, alla Torre di Azora, nell'Elwynn Forest.",
  progress = "Sbrigati, $N, prima che il potere di Morganth si diffonda come temo!",
  reward = "Ben fatto, $N. Sconfiggendo lo stregone Morganth hai salvato Stormwind da un grave pericolo.$B$BTi offro questa ricompensa con umiltà. E ti augurerei pace, se questi fossero tempi di pace.$B$BInvece ti auguro fortuna nelle tue prove, e vittoria negli scontri che verranno.",
  en_title = "Morganth",
  en_obj = "Defeat Morganth.$B$BBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.",
}
T[251] = {
  title = "Traduci il Biglietto di Abercrombie",
  desc = "Porta il biglietto che mi hai dato a Sirra Von'Indi. È molto dotto in lingue e arti antiche — se qualcuno qui può tradurre questo messaggio, è lui.",
  obj = "Porta la Letter to Ello a Sirra Von'Indi.",
  progress = "Un biglietto di Abercrombie l'eremita, eh? Non lo conosco, ma se vive laggiù al cimitero, una cosa la so: il cervello gli è marcito!",
  reward = "<Sirra comincia a tradurre il biglietto...>",
  en_title = "Translate Abercrombie's Note",
  en_obj = "Bring the Letter to Ello to Sirra Von'Indi.",
}
T[252] = {
  title = "La Traduzione per Ello",
  desc = "Oh cielo! Se quel che c'è scritto su questo biglietto è vero, allora Abercrombie ha fatto qualcosa di... indicibile.$B$BFaresti meglio a riportare il biglietto tradotto a Ello.$B$BE fallo in fretta, perché temo che una sciagura avanzi già a passi pesanti verso il nostro paese...",
  obj = "Porta la Translated Letter a Lord Ello Ebonlocke",
  progress = "Ah, il biglietto è tradotto? Ti prego, fammelo vedere...",
  reward = "<Ello legge la lettera... e sbianca in volto. Poi ti guarda...>$B$BForse hai aiutato Abercrombie per gentilezza, ma quel che hai fatto ha condannato il nostro paese.$B$B<Ello si perde nei suoi pensieri...>",
  en_title = "Translation to Ello",
  en_obj = "Bring the Translated Letter to Lord Ello Ebonlocke",
}
T[253] = {
  title = "La Sposa dell'Imbalsamatore",
  desc = "L'Imbalsamatore è un nome che ricorre in una delle nostre storie per bambini. Era un alchimista gentile, impazzito per la morte della moglie, Eliza. Per riportarla in vita usò la magia oscura e mise il proprio cuore nel petto della sposa morta.$B$BQuesto fece rivivere Eliza... ma la maledisse, dandole fame di carne umana, e l'Imbalsamatore fu costretto a tenerla sepolta.$B$BIl suo cuore è il suo potere. Trova la tomba della moglie, recupera il cuore e portamelo mentre ancora batte. Fa' questo e il suo potere sarà spezzato.",
  obj = "Trova la tomba di Eliza. Recupera da lei The Embalmer's Heart, poi torna da Ello Ebonlocke.",
  progress = "L'hai già trovata la tomba di Eliza? Ce l'hai il cuore dell'Imbalsamatore?",
  reward = "Ce l'hai fatta! La magia dentro il suo cuore sarà una difesa contro il male dell'Imbalsamatore, e un'egida potente sul paese di Darkshire.$B$BHai fatto una grande cosa per la nostra gente, $N. Il tuo nome resterà per sempre nei nostri annali.",
  en_title = "Bride of the Embalmer",
  en_obj = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.",
}
T[254] = {
  title = "Scavare nella Terra",
  reward = "Scavi nella terra in parte smossa sopra la tomba... e trovi i resti di una bara.$B$BDentro la bara senti le vibrazioni del raschiare di dita artigliate e il digrignare di denti marci...$B$BVuoi aprire la bara e recuperare il cuore dell'Imbalsamatore?",
  en_title = "Digging Through the Dirt",
}
T[261] = {
  title = "Lungo il Sentiero Scarlatto",
  desc = "Sarò franco. Siamo in guerra con il Flagello. È un male che corrompe la nostra gente e infetta la nostra terra. Deve essere fermato prima che ci travolga e trascini il nostro mondo nell'ombra. Noi della Crociata Scarlatta abbiamo giurato di combattere il Flagello anima e corpo.$B$BSe sei con noi, allora fatti coraggio e dimostra la tua lealtà — distruggi i devastatori non morti di Desolace, nella Valle delle Ossa, a sud.$B$BFallo, e la Crociata ti accoglierà a braccia aperte.",
  obj = "Distruggi 30 Undead Ravager, poi torna da Brother Anton, a Nijel's Point.",
  progress = "Il Flagello diventa più potente a ogni giorno che passa. Se desideri davvero fermarne l'avanzata, allora dimostramelo.",
  reward = "Hai dimostrato la tua determinazione, e la Crociata Scarlatta ti elogia.$B$BSe non ti tiri indietro davanti a un giusto massacro, allora forse il tuo cammino è insieme a noi...",
  en_title = "Down the Scarlet Path",
  en_obj = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.",
}
T[262] = {
  title = "La Figura in Ombra",
  desc = "Devo sapere chi era l'individuo che ho visto nascondersi nell'ombra la notte in cui hanno ucciso la mia famiglia!$B$BTi prego, $N, hai dimostrato di essere $Gpieno:piena; di risorse. Ti prego, trova quella figura in ombra. Devo sapere che segreti nasconde!$B$BNon ho indizi che tu non conosca già, ma tieni — prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in paese saprà risalire da questo libro al suo proprietario.",
  obj = "Prendi il libro che hai trovato alla fattoria di Sven e mostralo alla gente di Darkshire.",
  progress = "Se hai qualcosa che appartiene alla figura in ombra che cerchi, fammelo vedere. Forse riuscirò a leggere qualcosa del suo proprietario.",
  reward = "Hmm... Qualcuno ha maneggiato questo libro di recente, qualcuno mosso dalla vendetta. Ma le tracce che vi sono rimaste, almeno quelle del proprietario originale, sono deboli.$B$BQuello che posso dirti, però, è che il proprietario originale di questo libro non è di Darkshire.",
  en_title = "The Shadowy Figure",
  en_obj = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.",
}
T[265] = {
  title = "La Ricerca nell'Ombra Continua",
  desc = "Ecco, ti restituisco il libro, $N, e ti auguro buona fortuna per la tua ricerca. Se chiedi in giro per il paese, forse qualcuno potrà darti altri indizi.$B$BE te ne do ancora uno — anche se l'autore di questo libro non è di Darkshire, il libro è stato comprato qui.",
  obj = "Scopri se qualcun altro in paese ha indizi sulla figura in ombra.",
  progress = "A volte vendo libri con le pagine bianche a studiosi e maghi, o a chiunque voglia tenere un diario.$B$BRicordo bene tutti quelli a cui ho venduto un libro negli ultimi mesi...",
  reward = "Ah, sì. Questo libro l'ho venduto un mese fa a un individuo losco. Non mi ha detto come si chiamava, ma era un tipo nervoso e agitato, che si guardava sempre alle spalle.$B$BSpero che ti sia d'aiuto...",
  en_title = "The Shadowy Search Continues",
  en_obj = "See if other townsfolk have clues about the shadowy figure.",
}
T[266] = {
  title = "Informati alla Locanda",
  desc = "Ecco il tuo libro, e buona fortuna per le tue indagini.$B$BPotresti allargare la ricerca alla locanda. Se la persona che cerchi ha passato del tempo in paese, è probabile che qualcuno l'abbia vista lì.",
  obj = "Cerca nella locanda indizi sulla figura in ombra.",
  progress = "La Scarlet Raven non lavora più come una volta, ma qualche viaggiatore di passaggio capita ancora.$B$BSe sai descrivermi la persona che cerchi, magari me la ricordo.",
  reward = "Oh sì, questo libro me lo ricordo. Il suo proprietario ha preso una stanza per qualche giorno, e passava le notti al bancone a scrivere.$B$BHa lasciato il paese in fretta, borbottando di essere braccato da... qualcosa. L'ultima volta che l'ho visto andava a ovest, fuori dal paese, in cerca di un nuovo posto dove nascondersi.$B$BIl primo posto che si incontra andando a ovest è Raven Hill...",
  en_title = "Inquire at the Inn",
  en_obj = "Search the inn for clues about the shadowy figure.",
}
T[268] = {
  title = "Torna da Sven",
  desc = "Il libro che hai trovato era scritto solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono fuggito là...$B$BTieni. Porta a Sven il mio diario completo. Racconta più nel dettaglio quel che è successo alla sua fattoria.$B$BAnche se in queste settimane questo diario è stato la mia unica compagnia, se cederlo mi risparmia di dover affrontare Sven e la sua ira, lo faccio volentieri!",
  obj = "Torna da Sven con Jitters' Completed Journal.",
  progress = "Hai scoperto chi era la Figura in Ombra?",
  reward = "Questo diario mi spiega molte cose, e mi indica la strada per combattere i cavalieri oscuri! Ho visto questi cavalieri a Duskwood, e li ho visti parlare con il mago Morbent Fel, alla Magione Desolata.",
  en_title = "Return to Sven",
  en_obj = "Return to Sven with Jitters' completed journal.",
}
T[269] = {
  title = "In Cerca di Saggezza",
  desc = "Va' nella città di Stormwind e parla con il Vescovo Farthing, nella Cattedrale della Luce. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.$B$BAnche se Stormwind ha abbandonato Darkshire, Farthing è un'anima buona e molto saggia. Potrebbe aiutarti nella tua impresa per salvarci.$B$BLa tua missione è pericolosa, ma sbrigati, $N. Ora dopo ora, le ombre di Duskwood si fanno sempre più cupe.",
  obj = "Consegna Jitters' Completed Journal a Bishop Farthing, a Stormwind.",
  progress = "Riposati, $Gfratello:sorella;. Vedo che hai viaggiato a lungo, e che porti un peso gravoso. Sai dirmi cos'è che getta quell'ombra scura su di te?",
  reward = "<Dopo aver letto il diario e aver ascoltato le tue intenzioni...>$B$BUna corruzione maligna ha messo radici nella già tormentata Duskwood. Ringrazio la Luce che ad affrontarla ci sia $Gun eroe:un'eroina; come te.$B$BMa prima devi prepararti alla prova che ti aspetta... perché il Negromante Morbent Fel è immensamente potente, e si è cinto di incantesimi oscuri che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma che quelle protezioni non possono fermare.",
  en_title = "Seeking Wisdom",
  en_obj = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.",
}
T[270] = {
  title = "La Flotta Maledetta",
  desc = "Anni fa la Third Fleet di Kul'Tiras affondò lungo le coste delle Wetlands, una distesa di paludi a nord del regno nanico di Ironforge. Su una delle navi c'era un carico di Ferro Lightforge.$B$BQuesto metallo è prezioso per noi, perché gli oggetti che se ne ricavano colpiscono con la verità sacra. Se devi affrontare Morbent Fel, ti servirà un'arma così.$B$BVa' a Menethil Harbor e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può trovare, lui saprà dove cercare.",
  obj = "Va' a Menethil Harbor, nelle Wetlands, e parla con Glorin Steelbrow.",
  reward = "Il Ferro Lightforge è un metallo prezioso, ma da quel che dici la tua è un'impresa disperata. Hai fatto molta strada, $GFratello:Sorella;. Con un po' di fortuna, potresti trovare proprio quel che cerchi!$B$BE se il ferro lo trovi, so chi può farne un'arma contro questo Negromante di cui parli, a Duskwood.",
  en_title = "The Doomed Fleet",
  en_obj = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.",
}
T[272] = {
  title = "Prova del Leone Marino",
  desc = "Per la seconda prova ti serviranno le due metà che formano il Pendente del Leone Marino. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a tutte e due queste qualità per incarnare l'aspetto della loro forma acquatica.$B$BParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.$B$BForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino al Santuario di Remulos.$B$BPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.",
  progress = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai completato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.$B$BRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua forma acquatica.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[275] = {
  title = "Pustole sulla Terra",
  desc = "Non so perché, ma nelle Wetlands cresce un'infezione. Le Aberrazioni delle Paludi si sono levate. Sono pustole malate e febbricitanti sulla terra, e perché la febbre passi devono essere eliminate e lasciate sprofondare di nuovo nelle paludi.$B$BLe Aberrazioni delle Paludi si trascinano tra i corsi d'acqua delle Wetlands.",
  obj = "Uccidi 12 Fen Creeper, poi torna da Rethiel the Greenwarden, nelle Wetlands.",
  progress = "Le Wetlands piangono ancora, e le Aberrazioni delle Paludi ancora infuriano. Torna da me quando il tuo compito sarà finito.",
  reward = "I tuoi sforzi hanno dato sollievo a questa terra, e per questo ti concederò un dono.",
  en_title = "Blisters on The Land",
  en_obj = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[276] = {
  title = "Zampe che Calpestano",
  desc = "Gli Gnoll Mosshide vivono in pace nelle Wetlands da molti anni, ma ora il loro numero cresce. Le loro zampe calpestano i cespugli e i fiori della palude, e le loro asce immonde tagliano troppo legno per alimentare i fuochi.$B$BNon sono più in equilibrio con la terra. Perché le Wetlands sopravvivano, il numero degli Gnoll va ridotto.$B$BUccidi 15 Gnoll Mosshide e 10 Meticci Mosshide. Dai loro la caccia a sud, vicino alla porta Nanica di Algaz. Quando l'avrai fatto, torna da me.",
  obj = "Uccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel, poi torna da Rethiel the Greenwarden, nelle Wetlands.",
  progress = "Il tuo compito ti aspetta ancora, giovane $C.",
  reward = "Riducendo il numero degli Gnoll, ti sei $Gpreso:presa; cura della salute delle Wetlands. Anche se in passato la mia fiducia nella tua gente è stata messa a dura prova, $R, può ancora essere ristabilita.",
  en_title = "Tramping Paws",
  en_obj = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[277] = {
  title = "Il Tabù del Fuoco",
  desc = "I Mosshide tagliano gli alberi delle Wetlands, e usano la carne degli alberi per scaldarsi con il fuoco. Non sopporterò più questo dolore!$B$BPriva i Mosshide delle loro rozze pietre focaie, gli arnesi con cui accendono il fuoco. Le pietre focaie le portano tutti i Mosshide, tranne gli gnoll Mosshide e i meticci Mosshide, che sono più piccoli.",
  obj = "Porta 9 Crude Flint a Rethiel the Greenwarden.",
  progress = "Hai gli arnesi del fuoco degli Gnoll?",
  reward = "... grazie. Frantumerò queste pietre focaie e le getterò in mare, perché non siano mai più usate per bruciare legno vivo.",
  en_title = "Fire Taboo",
  en_obj = "Bring Rethiel the Greenwarden 9 Crude Flints.",
}
T[279] = {
  title = "Artigli dal Profondo",
  desc = "I Murloc stanno strisciando fuori dalle acque profonde e costruiscono i loro villaggi sulla costa. Molestano i nostri pescatori e i nostri mercanti, e vanno fermati.$B$BUno di questi Murloc, Gobbler, si muove furtivo insieme ad altri Murloc Bluegill e assale i mercanti lungo la strada, per poi ritirarsi sempre al sicuro nelle vicine capanne dei Murloc. I nostri mercanti sono in pericolo, e siamo disposti a pagare per proteggerli.$B$BGobbler si aggira nell'insenatura del fiume a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.",
  obj = "Uccidi 12 Bluegill Murloc.$B$BUccidi Gobbler e prendi la sua testa.$B$BPorta Gobbler's Head a Karl Boran, a Menethil Harbor.",
  progress = "I nostri mercanti non saranno al sicuro finché non ci saremo liberati di Gobbler e di quei Murloc.",
  reward = "Ah, ben fatto, $N.$B$BAccetta questo come compenso per aver onorato il tuo contratto con i Merchant Marines.",
  en_title = "Claws from the Deep",
  en_obj = "Kill 12 Bluegill Murlocs.$B$BSlay Gobbler and take his head.$B$BBring Gobbler's Head to Karl Boran in Menethil Harbor.",
}
T[281] = {
  title = "Recuperare la Merce",
  desc = "Non molto tempo fa un mercantile, la Blind Princess, è stato assalito dai Murloc. Anche se la nave è riuscita a fuggire intatta, gran parte del carico è stata trascinata in mare da quelle creature, compresa una preziosissima statuetta di Terenas Menethil. Vogliamo che quella statuetta venga recuperata.$B$BCerca casse, barili e altre tracce del carico perduto nelle capanne dei Murloc sulla costa. Trova la Statuetta di Menethil e riportamela.",
  obj = "Cerca nelle casse e nei barili degli accampamenti dei Murloc sulla costa.",
  reward = "Questa cassa è coperta di graffi di artigli e di segni lasciati dall'acqua. Forzandola si scopre paglia fradicia e marcia, come se dentro fosse stato riposto qualcosa di valore. Frughi tra la paglia...$B$B...e trovi una bracciata di bottiglie rosse.",
  en_title = "Reclaiming Goods",
  en_obj = "Search the crates and barrels at the coastal Murloc camps.",
}
T[284] = {
  title = "La Ricerca Continua",
  desc = "Perlustri a fondo questo gruppo di capanne dei Murloc e non trovi traccia della Statuetta di Menethil.$B$BForse una delle due capanne vicine, a nord e a nord-est, avrà altri indizi.",
  obj = "Cerca la Menethil Statuette.",
  reward = "Questo barile è quasi intatto. Lo forzi...$B$B...e ti assale l'odore pungente del formaggio. È un po' bagnato, ma ancora buono!",
  en_title = "The Search Continues",
  en_obj = "Search for the Menethil Statuette.",
}
T[285] = {
  title = "Cerca in Altre Capanne",
  desc = "Questo gruppo di capanne dei Murloc, dopo un'ispezione accurata, non rivela nulla.$B$B...ma sei $Gcerto:certa; che il prossimo indizio che troverai sarà quello buono.$B$BIn una delle capanne a nord ci deve essere la Statuetta di Menethil!",
  obj = "Continua a cercare la Menethil Statuette nelle capanne dei Murloc.",
  reward = "Questo barile è mezzo sepolto tra il fango e l'erba...",
  en_title = "Search More Hovels",
  en_obj = "Continue searching the Murloc hovels for the Menethil Statuette.",
}
T[286] = {
  title = "Riporta la Statuetta",
  desc = "Dopo aver liberato il barile dal fango e averlo aperto, trovi una statuina argentea avvolta nella paglia fine. Raffigura un giovane Paladino dai capelli lunghi con il martello sollevato.$B$BDeve essere la Statuetta di Menethil! Ora devi riportarla a Karl Boran, a Menethil Harbor.",
  obj = "Porta la Menethil Statuette a Karl Boran.",
  progress = "Hai la statuetta?",
  reward = "Il capitano della Blind Princess sarà sollevato nel sapere che questo carico prezioso è stato recuperato. Questo compenso per i servizi resi te lo sei proprio meritato.$B$BFa piacere vedere gente affidabile come te, soprattutto in tempi difficili come questi.",
  en_title = "Return the Statuette",
  en_obj = "Bring Karl Boran the Menethil Statuette.",
}
T[288] = {
  title = "La Third Fleet",
  desc = "Un tempo ero Primo Ufficiale sulla Wave Mistress, nave di linea della Third Fleet di Kul Tiras. La Flotta Dannata. Dannata, perché nel suo ultimo viaggio la flotta fu attaccata dai Draghi Rossi. Draghi controllati dagli Orchi!$B$BNon avevamo scampo contro quel fuoco di drago... e la nostra flotta fu bruciata e affondata al largo di questa costa qui. Sono l'unico sopravvissuto di quelle povere navi...$B$B...Oh, la testa mi martella e mi pulsa! Mi ci vuole un altro bicchiere, se voglio tenere a bada i postumi della sbornia e continuare il racconto.",
  obj = "Compra un Flagon of Mead per First Mate Fitzsimmons.",
  progress = "Oh, ho una sete tremenda! Non offriresti da bere a questo povero, patetico scemo?",
  reward = "Ah! Questo sì che ci voleva, e mi scioglie la lingua. Grazie, socio!",
  en_title = "The Third Fleet",
  en_obj = "Buy First Mate Fitzsimmons a Flagon of Mead.",
}
T[289] = {
  title = "L'Equipaggio Maledetto",
  desc = "<Rinfrancato, Fitzsimmons riprende il racconto...>$B$BSono l'unico sopravvissuto della sventurata Third Fleet di Kul Tiras, naufragata al largo della costa a nord. Ma anche se sono l'unico membro della flotta che ancora respira, non sono l'unico che ancora cammina! Perché su una delle nostre navi era nascosto un tesoro grande e terribile, e il suo potere sinistro tiene le anime dei miei fratelli intrappolate negli scafi marcescenti delle navi.$B$BMa se riesci a liberare qualcuno dei miei fratelli, forse potrai spezzare la loro maledizione.",
  obj = "Uccidi 13 Cursed Sailor, 5 Cursed Marine e First Mate Snellig. Porta Snellig's Snuffbox a First Mate Fitzsimmons, a Menethil Harbor.",
  progress = "Nei miei sogni, a volte sento i gemiti dei miei fratelli dannati! Ti prego, $Gbuon signore:buona signora;, liberali dalle catene e fa' tacere le loro grida.",
  reward = "Ti ringrazio, $N. E con me ti ringraziano anche i miei fratelli maledetti.",
  en_title = "The Cursed Crew",
  en_obj = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.",
}
T[290] = {
  title = "Spezzare la Maledizione",
  desc = "Per spezzare la maledizione e liberare tutti i miei fratelli, quella... cosa... stivata sulla mia nave va recuperata e purificata! Non so cosa fosse, ma so che era custodita al sicuro nel forziere della nave, su cui vegliava il Capitano Halyndor.$B$BIl mio vecchio capitano mi appare ancora in sogno. So che si aggira sulla mia nave condannata, l'Intrepid. Prendi la chiave da lui e usala per aprire il forziere dell'Intrepid.$B$BPoi, quando avrai la cosa maledetta, portala al sacerdote Glorin Steelbrow, in città.",
  obj = "Prendi l'Intrepid Strongbox Key da Captain Halyndor.$B$BUsa la chiave per aprire l'Intrepid's Locked Strongbox.",
  progress = "Questa cassa è chiusa saldamente a chiave.",
  reward = "La chiave è arrugginita, ma entra nella serratura alla perfezione.",
  en_title = "Lifting the Curse",
  en_obj = "Get the Intrepid Strongbox Key from Captain Halyndor.$B$BUse the key to open the Intrepid's Locked Strongbox.",
}
T[292] = {
  title = "L'Occhio di Paleth",
  desc = "Aperta la cassa, compare una sfera annerita che pulsa di una luce sinistra. È il tesoro di cui parlava Fitzsimmons: un Occhio di Paleth Maledetto.$B$BPorta l'Occhio di Paleth Maledetto al sacerdote nano Glorin Steelbrow, a Menethil Harbor. Chiedigli come togliere la maledizione dall'Occhio.",
  obj = "Porta il Cursed Eye of Paleth a Glorin Steelbrow.",
  progress = "Quell'ubriacone di Fitzsimmons ti manda da me? Be', puoi dirgli che di birra non me ne avanza. Dovrà andare a elemosinare da qualcun altro!",
  reward = "Un Occhio di Paleth? Incredibile! Mmh... c'è qualcosa che non va in questo. L'hai trovato su uno di quei relitti? Be', questo spiega tutto! Ma... non sapevo che ne avessero uno sulla Third Fleet...$B$BNon c'è da stupirsi che Fitzsimmons fosse così spaventato. Con un Occhio di Paleth Maledetto c'è poco da ridere.",
  en_title = "The Eye of Paleth",
  en_obj = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.",
}
T[293] = {
  title = "Purificare l'Occhio",
  desc = "Non riesco a togliere la maledizione dall'Occhio di Paleth. Gli Occhi furono creati da Sacerdoti Umani, quindi dovrai andare a Stormwind a cercare qualcuno che possa aiutarti. Parla con l'Arcivescovo Benedictus. È a capo della Cattedrale della Luce di Stormwind. Lui può aiutarti.$B$BLo spero, per il tuo bene.",
  obj = "Porta il Cursed Eye of Paleth ad Archbishop Benedictus. Benedictus si trova in Cathedral of Light, nella città di Stormwind.",
  progress = "Che sfera è quella che hai? Sembra... insozzata.",
  reward = "Un Occhio di Paleth. Ma questo ha visto molto dolore... deve essere stato testimone di una tragedia terribile, terribile.$B$BLascia che lo purifichi, perché gli Occhi furono creati per risplendere, e i loro poteri possono essere molto pericolosi se corrotti come questo.",
  en_title = "Cleansing the Eye",
  en_obj = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.",
}
T[294] = {
  title = "La Vendetta di Ormer",
  desc = "La situazione è grave, questo è certo. Quando abbiamo portato alla luce queste ossa abbiamo attirato i Raptor. Quelle bestie immonde hanno ucciso i miei compagni e hanno intrappolato quassù me, Merrin e il povero Prospettore.$B$BAiuta a ripulire le Wetlands da questi Raptor, $N. I Raptor Chiazzati e gli Stridenti Chiazzati sono appena a Ovest del promontorio, laggiù. Uccidine 10 per tipo, se ci riesci.$B$BSarà un buon inizio per la vendetta che ho in mente per loro.",
  obj = "Ormer Ironbraid, al Sito di Scavo di Whelgar, vuole che tu uccida 10 Mottled Screecher e 10 Mottled Raptor.",
  progress = "Uccidi 10 Raptor Chiazzati e 10 Stridenti Chiazzati, $N. I miei colleghi non meritavano la sorte che è toccata loro. È ora di pareggiare i conti.",
  reward = "Uccidere è un mestiere sporco, ma hai fatto bene il tuo lavoro, $N. Se non fossi costretto a restare con il Prospettore e Merrin, sarei laggiù a versare sangue al tuo fianco.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.",
}
T[295] = {
  title = "La Vendetta di Ormer",
  desc = "Ora è il momento di far pentire davvero quei terribili Raptor della loro sete di sangue. Proprio là sotto ci sono decine di Mietisauri Chiazzati e di Boccaguzza Chiazzati. Fagliela pagare a quelle schifose creature uccidendone 10 di ciascuna specie!",
  obj = "Ormer Ironbraid vuole che tu uccida 10 raptor Mottled Scytheclaw e 10 raptor Mottled Razormaw, e che poi torni da lui al Sito di Scavo di Whelgar.",
  progress = "Voglio che quei Mietisauri Chiazzati e quei Boccaguzza Chiazzati paghino per quello che hanno fatto. Ne hai già uccisi 10 di ciascuna specie?",
  reward = "Hai fatto un lavoro coi fiocchi a far piazza pulita di quei Raptor, $N!",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.",
}
T[296] = {
  title = "La Vendetta di Ormer",
  desc = "Mentre eri laggiù ho notato che uno di quei mostri spiccava sugli altri. Era più grosso e più minaccioso. Scommetto che è stato lui a guidare gli altri fin qui, a portare scompiglio nel sito di scavo.$B$BTi chiedo ora un ultimo compito, $N. Fa' in modo che Sarltooth sia assicurato alla giustizia. E vista la gravità dei suoi crimini, in questo caso giustizia vuol dire morte! Portami uno dei suoi artigli come prova della sua morte.",
  obj = "Ormer Ironbraid, al Sito di Scavo di Whelgar, vuole che tu uccida Sarltooth e che, a compito eseguito, torni da lui con uno dei suoi artigli.",
  progress = "Sarltooth è morto? Hai riscattato la memoria dei caduti?",
  reward = "Grazie, $N. Quello che hai fatto qui non sarà dimenticato. Molti Nani innocenti sono morti in questo scavo, mentre facevano solo il loro lavoro. La vendetta che hai portato a quelle creature malvagie dovrebbe spingerle a pensarci due volte prima di attaccare ancora i sudditi di Re Magni.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",
}
T[299] = {
  title = "Riportare alla Luce il Passato",
  desc = "Poco prima dell'invasione ho portato alla luce una grande tavoletta chiamata Pietra di Goaz. Il testo tradotto si interrompe in 4 punti. Parla di un \"piano divino\" e di una \"profezia funesta\".$B$BTemo che ci resti poco tempo. Sono troppo vecchio per scendere ad affrontare quelle bestie. Ma tu sei forte.$B$BSetaccia il sito di scavo e riporta alla luce i 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru. Cercali negli artefatti antichi o dove il terreno è smosso. Portameli, così potrò cominciare a svelare il mistero!",
  obj = "Prospector Whelgar vuole che tu setacci il sito di scavo in cerca dei 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru.",
  progress = "Hai già riportato alla luce i quattro frammenti, $N? Ados, Modr, Golm e Neru...",
  reward = "Ah, la Pietra di Goaz è completa! Ottimo lavoro, $N. Davvero ottimo. Ora posso continuare la delicata traduzione di questa scrittura dei Titani. Riesco già a distinguere parole nuove! Mmh... qui dice: \"Dei Antichi... Incatenati Sotto la Terra\". È l'inizio di qualcosa di epico.",
  en_title = "Uncovering the Past",
  en_obj = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.",
}
T[303] = {
  title = "La Guerra dei Dark Iron",
  desc = "La guerra infuria sia in patria sia all'estero. Mentre possenti soldati Nani danno la vita in territori lontani nel nome dell'Alleanza, le nostre terre cadono preda delle malefatte dei Nani Dark Iron. Hanno devastato il Viadotto di Thandol. Dun Modr è caduta poco dopo.$B$BDevi radunare le forze e ricacciare indietro il fronte. Se riesci a uccidere 15 Nani Dark Iron, 5 Perforatori, 5 Sabotatori e 5 Demolitori, la riserva potrebbe arrivare in tempo per completare l'offensiva.$B$BOra fa' presto!",
  obj = "Motley Garmason, a Dun Modr, vuole che tu uccida 15 Dark Iron Dwarf, 5 Dark Iron Tunneler, 5 Dark Iron Saboteur e 5 Dark Iron Demolitionist.",
  progress = "Roggo non è riuscito a contattare le forze di riserva. Dobbiamo tenere sotto pressione quell'accampamento Dark Iron, $C. Adesso torna là fuori e fa' il tuo dovere verso Re Magni!",
  reward = "Hai eseguito bene i tuoi ordini, $C. Ti sei $Gdimostrato:dimostrata; $Gun soldato valoroso:una soldatessa valorosa; e $Gun leale servitore:una leale servitrice; di Re Magni, e per questo ti rendo onore! Grazie alla pressione che hai esercitato sull'accampamento Dark Iron, ora abbiamo qualche possibilità di cacciarli dalle nostre terre per sempre... se solo arrivasse quella maledetta riserva...",
  en_title = "The Dark Iron War",
  en_obj = "Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.",
}
T[304] = {
  title = "Un Compito Tetro",
  desc = "Molti dei miei soldati sono morti nella battaglia di Dun Modr. Mio fratello ha perso la vita quando è stato distrutto il Ponte Ovest sul Viadotto di Thandol. Già, i nani Dark Iron sono una razza diabolica. Da quello che Roggo è riuscito a scoprire, il capo di questa banda di bruti nelle Wetlands è uno stregone di nome Balgaras l'Infetto. Però è un gran codardo. Manda i suoi soldati a fare il lavoro sporco e resta inafferrabile, lontano dal pericolo.$B$BSe riesci a trovare quel verme senza spina dorsale, uccidilo e portami il suo orecchio. Ti ricompenserò, $C.",
  obj = "Uccidi Balgaras the Foul e porta il suo orecchio a Longbraid the Grim, fuori da Dun Modr.",
  progress = "Sei già $Griuscito:riuscita; a trovare Balgaras l'Infetto, $C? Ci sfugge da parecchio tempo.",
  reward = "Balgaras l'Infetto è finalmente morto. La sua morte non riporterà indietro i tanti nani innocenti uccisi senza motivo per mano sua, ma aiuterà a ridare un po' di serenità a chi è sopravvissuto. Con Balgaras morto, quel che resta della feccia Dark Iron non dovrebbe darci troppi problemi. Ora dobbiamo spazzarla via prima che mandino da queste parti un nuovo capo.$B$BHai fatto un buon lavoro, $C.",
  en_title = "A Grim Task",
  en_obj = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.",
}
T[305] = {
  title = "In Cerca della Squadra di Scavo",
  desc = "Oh, cielo, devi essere $Gl'esploratore:l'esploratrice; che Longbraid aveva promesso di mandare! Non puoi immaginare quanto sono stato in pena.$B$BMia moglie, Merrin, mi manda lettere ogni settimana da un mese. Fa parte della squadra di scavo di Whelgar. Ma sono passate quasi due settimane dall'ultima lettera. Dev'essere successo qualcosa!$B$BLongbraid aveva detto che avrebbe mandato un esploratore a controllare, se non avessimo avuto presto notizie della squadra. Immagino che $Gquell'esploratore:quell'esploratrice; sia tu, $N. Trova Merrin al sito di scavo, a est!",
  obj = "Tarrel Rockweaver vuole che tu raggiunga Excavation Site e contatti Merrin Rockweaver.",
  reward = "Oh, grazie al cielo, sei qui!",
  en_title = "In Search of The Excavation Team",
  en_obj = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.",
}
T[306] = {
  title = "In Cerca della Squadra di Scavo",
  desc = "È stato orribile! Stavamo portando alla luce alcuni artefatti rari e abbiamo cominciato a trovare queste ossa enormi.$B$BPrima che ci rendessimo conto di cosa stava succedendo, questi Raptor Chiazzati hanno invaso il sito di scavo. Molte vite sono andate perdute.$B$BOrmer — così coraggioso — ha salvato il Prospettore e me. Ci ha difesi mentre correvamo al riparo. Ora siamo intrappolati. E tutto il nostro duro lavoro è andato in rovina.$B$BEcco, riporta questo biglietto al mio caro Tarrel. Gli spiegherà la situazione.",
  obj = "Torna da Tarrel Rockweaver con il biglietto di Merrin.",
  progress = "Sei $Griuscito:riuscita; a trovare Merrin? Ha mandato qualche notizia?",
  reward = "Che notizie orribili! Almeno tre di loro sono sopravvissuti. Ma quando finirà questa mattanza? Sogno il giorno in cui i sudditi di Re Magni potranno vivere senza paura.",
  en_title = "In Search of The Excavation Team",
  en_obj = "Return to Tarrel Rockweaver with Merrin's note.",
}
T[321] = {
  title = "Ferro Lightforge",
  desc = "I relitti al largo di questa costa sono la sventurata Third Fleet di Kul'Tiras, bruciata e affondata dai Draghi Rossi durante l'ultima Grande Guerra.$B$BLa flotta veniva da Lordaeron, ma con lei c'era una nave, un vascello da guerra elfico: la Flying Osprey. Trasportava un carico di Ferro Lightforge e si era unita alla Third Fleet per avere protezione. Ironia della sorte, è affondata per colpa degli stessi draghi...$B$BBasta con la storia. La Flying Osprey è naufragata a sud di Menethil Harbor. Se trovi lì il Ferro Lightforge, portamelo.",
  obj = "Cerca tra i relitti della Flying Osprey, nelle Wetlands.",
  reward = "Questa cassa è impregnata d'acqua e le fiancate sono rotte. Molti segni di artigli rovinano l'interno e l'esterno della cassa... come se dei Murloc ci avessero frugato dentro e ne avessero rubato il tesoro.$B$BMa infilato in fondo alla cassa c'è un solo Lingotto Lightforge. Purtroppo ne serviranno molti altri per avere metallo a sufficienza da forgiare un'arma.",
  en_title = "Lightforge Iron",
  en_obj = "Search the wreckage of The Flying Osprey in the Wetlands.",
}
T[322] = {
  title = "L'Arma Benedetta",
  desc = "Nel Distretto dei Nani di Stormwind c'è un armaiolo nano che sa lavorare il ferro lightforge. Si chiama Grimand Elmore.$B$BHo messo in una cassa il ferro che hai trovato. Portala a Grimand e raccontagli la tua storia. Sono sicuro che darà una mano a chi è impegnato in un'impresa come la tua, e ti forgerà un'arma — un'arma che farà preoccupare perfino Morbent Fel!",
  obj = "Porta la Crate of Lightforge Ingots a Grimand Elmore, a Stormwind.",
  progress = "In cosa posso mettere la mia arte al tuo servizio, $C?",
  reward = "Quella sì che è una bella storia. E ferro lightforge! Sono anni che non mi capita tra le mani un metallo simile. Sarà un onore lavorarlo di nuovo. E dovrai tornare da me più avanti a raccontarmi la tua battaglia contro il Negromante.$B$BMa non corriamo troppo. Prima, la tua arma contro Morbent Fel...",
  en_title = "Blessed Arm",
  en_obj = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.",
}
T[323] = {
  title = "Dimostra il Tuo Valore",
  desc = "Morbent Fel è un negromante, e un alleato dei cavalieri oscuri. Ti metterei contro il potere di Morbent Fel, ma non ti manderò contro quel mostro immondo senza prima conoscere la tua forza.$B$BIl tuo coraggio me l'hai già dimostrato, ma se vuoi davvero affrontare il negromante, allora devi dimostrare la tua abilità contro i suoi servi.",
  obj = "Uccidi 15 Skeletal Raider, 3 Skeletal Healer e 3 Skeletal Warder, poi torna da Sven.",
  progress = "Combatti con forza, $N. E non disperare, perché la disperazione è l'arma più grande del male.",
  reward = "La tua abilità in combattimento, $N, è fuori discussione. La tua determinazione potrebbe ancora aiutarci a farla finita con Morbent Fel!",
  en_title = "Proving Your Worth",
  en_obj = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.",
}
T[324] = {
  title = "I Lingotti Perduti",
  desc = "Hai preso l'unico lingotto lightforge dalla cassa impregnata d'acqua: è chiaro che i murloc hanno rubato il resto. Dai la caccia ai murloc predoni vicino al relitto della Flying Osprey per recuperare il ferro lightforge perduto.",
  obj = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.",
  progress = "L'hai trovato il ferro lightforge che ti serve?",
  reward = "Ah, li hai trovati! E adesso battiamo questo ferro lightforge fino a farne qualcosa di utile, eh?",
  en_title = "The Lost Ingots",
  en_obj = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[325] = {
  title = "Armi in Pugno",
  desc = "Ecco l'arma contro quel mostro di cui parlavi. Sei $Gpronto:pronta;, $N. Buona fortuna, e non vedo l'ora di sentire il racconto delle tue gloriose gesta!",
  obj = "Porta Morbent's Bane a Sven, a Duskwood.",
  progress = "Salve, $N. Non sei $Gstato:stata; via molto, ma vedo nei tuoi occhi un fuoco che prima non c'era.",
  reward = "Ah, questa ti proteggerà da quel mostro di Morbent Fel! Ben fatto!$B$BSei $Gpronto:pronta;. Morbent Fel cadrà.",
  en_title = "Armed and Ready",
  en_obj = "Bring Morbent's Bane to Sven in Duskwood.",
}
T[328] = {
  title = "La Chiave Nascosta",
  desc = "Anche se in questi registri non si trova alcun accenno al Soldato Thorsen, nella rilegatura di uno dei libri contabili di Herod è nascosta una piccola chiave d'ottone.$B$BE, studiando meglio i suoi appunti, tra le varie carte si trovano alcuni riferimenti a un \"forziere blindato\". Il forziere si trova da qualche parte nel Deposito — il complesso di caverne in fondo all'Insediamento di Kurzen.$B$BSe si trova questo forziere blindato, e se la piccola chiave d'ottone riesce ad aprirlo, forse si svelerà il mistero di come è stato scoperto Thorsen.",
  obj = "Usa la Small Brass Key per aprire Bookie Herod's Strongbox.",
  progress = "Il forziere è cerchiato di bronzo, molto robusto e molto pesante.",
  reward = "Una volta aperto il forziere, si capisce che è qui che Herod custodisce le monete e gli oggetti di maggior valore.",
  en_title = "The Hidden Key",
  en_obj = "Use the Small Brass Key to open Bookie Herod's Strongbox.",
}
T[329] = {
  title = "La Spia Smascherata!",
  desc = "Tra gli oggetti di valore del forziere c'è un biglietto infangato e scarabocchiato. Anche se è a malapena leggibile, sembra una tabella di marcia del Soldato Thorsen. Descrive nei dettagli i suoi percorsi di pattuglia, con chi parla e come passa il tempo con i ribelli. È firmato con una sola lettera: -M.$B$BMa chiunque abbia scritto questo biglietto deve essere stato molto vicino a Thorsen. Chiunque abbia scritto questo biglietto è il traditore all'interno del campo dei ribelli.",
  obj = "Porta il Muddy Note a Lieutenant Doren, al Rebel Camp.",
  progress = "Hai scoperto chi conosceva il segreto di Thorsen? C'è un traditore tra noi?",
  reward = "Grazie, $N. Questo biglietto è l'indizio che ci serve per stanare il traditore!",
  en_title = "The Spy Revealed!",
  en_obj = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.",
}
T[330] = {
  title = "I Turni di Pattuglia",
  desc = "Il biglietto che mi hai dato è firmato con una \"-M\"... non so cosa possa significare.$B$BMa... il biglietto dice anche che la settimana scorsa questa persona era di pattuglia con Thorsen. Quindi chiunque abbia fatto la pattuglia con Thorsen la settimana scorsa dev'essere il traditore!$B$BVa' dal Caporale Sethman. Si occupa dei turni di pattuglia e può dirti chi era con Thorsen.",
  obj = "Parla con Corporal Sethman.",
  reward = "Oh, sì, posso controllare. Vediamo... la settimana scorsa c'era...$B$B...ma guarda, in turno con Thorsen c'era il Soldato Merle. Hanno fatto gli stessi orari di pattuglia per tutta la settimana scorsa.",
  en_title = "Patrol Schedules",
  en_obj = "Speak with Corporal Sethman.",
}
T[331] = {
  title = "Rapporto a Doren",
  desc = "Il Tenente Doren voleva che tornassi a fargli rapporto con quelle informazioni sulle pattuglie?",
  obj = "Parla con Lieutenant Doren.",
  reward = "Mi addolora scoprire che è stato Merle a tradirci. È sempre stato un soldato coraggioso, e credevo che avesse un cuore leale. Ma è un gran sollievo averlo smascherato — con una spia come lui tra noi... non resisteremmo a lungo contro il Colonnello Kurzen.",
  en_title = "Report to Doren",
  en_obj = "Speak with Lieutenant Doren.",
}
T[335] = {
  title = "Un Intruglio per Nobili",
  desc = "Ser Wishock sta facendo parecchio rumore in seno all'House of Nobles. È venuto a sapere del nostro piccolo \"locale\" quaggiù e fa pressioni perché si apra un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma mi servirà il tuo aiuto.$B$BC'è un fiore che cresce nel Giardino di Stalvan, alle porte di Darkshire. Questo fiorellino bianco si chiama Lacrima di Tilloa. Mi servirà anche una Radice Muschiata, che si trova solo ai piedi delle cascate, molto più in basso della Diga di Stonewrought, nelle Wetlands.",
  obj = "Zardeth of the Black Claw vuole che tu gli porti una Tear of Tilloa da Darkshire e una Musquash Root dalle Wetlands.",
  progress = "Presto Wishock avrà abbastanza appoggi da crearci molti guai. Sei già $Griuscito:riuscita; a procurarti la Lacrima di Tilloa o la Radice Muschiata?",
  reward = "Magnifico! Questi sì che sono campioni di qualità!",
  en_title = "A Noble Brew",
  en_obj = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.",
}
T[336] = {
  title = "Un Intruglio per Nobili",
  desc = "Lord Wishock, come tutti gli uomini, ha le sue debolezze. Nel suo caso, è il debole per l'alcol. L'ipocrisia è sbalorditiva. Quello sciocco da quattro soldi passa le giornate a cercare di far chiudere la nostra piccola \"taverna\", e le notti al piano di sopra, ad accumulare un conto che non paga mai. Bene, vediamo se a Wishock piace questo intruglio speciale che ho preparato per lui: la birra scura Black Claw. Dà una bella botta, $N.$B$BPortagliela e vedi se gli piace. Quasi sicuramente quel vecchio idiota gironzola nella Sala dei Supplicanti.",
  obj = "Porta la Black Claw Stout a Lord Baurles K. Wishock in Hall of Petitioners.",
  progress = "Non vedi che sono occupato? Devono ascoltare le mie parole! Io sono molto importante per il futuro di questo Regno!$B$BOh... cos'hai lì? Ma sembra una bevanda rinfrescante...",
  reward = "Ah, grazie di avermi portato questa birra scura dall'aria così invitante, servo. Ecco una moneta di rame per te. Ora togliti di torno e lasciami gustare la mia bevanda!",
  en_title = "A Noble Brew",
  en_obj = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.",
}
T[337] = {
  title = "Un Vecchio Libro di Storia",
  desc = "Anche se la copertina di questo libro è rovinata dai graffi e incrostata di fango, sul dorso si legge ancora \"La Storia di Stormwind\". Aprendolo, sulla prima pagina si vede chiaramente il sigillo della Biblioteca di Stormwind.$B$BSembra che qualcuno abbia preso in prestito questo libro e non l'abbia mai restituito...",
  obj = "Restituisci il libro: The History of Stormwind, alla Biblioteca di Stormwind.",
  progress = "Ooh! Cos'è quel vecchio libro che hai lì? Posso vederlo??",
  reward = "Oh cielo! Questo libro manca da questi scaffali da prima della ricostruzione di Stormwind, anni fa. Andrà restaurato, ovviamente, è messo male, ma sarà un onore metterlo nella nostra raccolta di libri rari.$B$BGrazie, $Gsignore:signora;. Prendi questo, è il compenso per aver riportato il libro!",
  en_title = "An Old History Book",
  en_obj = "Return the book: The History of Stormwind, to the Stormwind Library.",
}
T[338] = {
  title = "I Colli Verdi di Stranglethorn",
  desc = "Il Maestro Nesingwary si arrabbierà tantissimo se lo scopre!$B$BMi aveva affidato la correzione delle bozze del suo romanzo, I Colli Verdi di Stranglethorn. Andava tutto bene, ma una forte raffica di vento ha attraversato l'accampamento e ha sparpagliato le pagine dappertutto!$B$BHo recuperato quasi tutte le pagine, ma molte sono ancora sparse per la giungla. Raccogli le pagine per completare ciascuno dei quattro capitoli.$B$BTi aiuterò a metterle in ordine. Riportami i capitoli quando li avrai tutti e quattro.",
  obj = "Raccogli le pagine mancanti del manoscritto di The Green Hills of Stranglethorn. Quando tutti e quattro i capitoli saranno completi, riportali a Barnil.",
  progress = "Hai già rimesso insieme i capitoli, $N?",
  reward = "Mi hai proprio risparmiato un mucchio di guai, $N! Non so come ringraziarti. Ormai manca poco e vedremo il libro del Maestro Nesingwary nelle biblioteche di tutto il mondo!",
  en_title = "The Green Hills of Stranglethorn",
  en_obj = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.",
}
T[339] = {
  title = "Capitolo I",
  desc = "Il Capitolo I era davvero avvincente! Il Maestro Nesingwary descrive l'ambientazione della storia e parla dei suoi compagni di caccia, compreso me!$B$BMa non è questo il punto. Vediamo quali pagine mancano ancora. Sembra che le pagine 1, 4, 6 e 8 siano ancora là fuori, da qualche parte nella giungla!",
  obj = "Porta le pagine 1, 4, 6 e 8 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot, per completare il Capitolo I.",
  progress = "Non è che per caso sei $Griuscito:riuscita; a trovare le pagine 1, 4, 6 e 8? Ci servono solo quelle quattro per ricomporre il Capitolo I.",
  reward = "Finalmente! Il Capitolo I è completo!",
  en_title = "Chapter I",
  en_obj = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.",
}
T[340] = {
  title = "Capitolo II",
  desc = "Il Capitolo II era pieno zeppo di storie emozionanti di caccia alla pantera e alla tigre. Mi prenderei a calci per aver lasciato volar via le pagine!$B$BSembra che io sia riuscito a recuperare tutte le pagine, tranne la 10, la 11, la 14 e la 16.",
  obj = "Porta le pagine 10, 11, 14 e 16 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot, per completare il Capitolo II.",
  progress = "Ci servono ancora le pagine 10, 11, 14 e 16 per completare il Capitolo II, $N.",
  reward = "Il Capitolo II è finalmente completo! Ben fatto!",
  en_title = "Chapter II",
  en_obj = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.",
}
T[341] = {
  title = "Capitolo III",
  desc = "Il Capitolo III era il mio preferito. Racconta la prima preda di Sir Erlgadin e Lady Rouack con un fucile nanico. E la fine del Capitolo III, accidenti, che suspense!$B$BMi sembra che ci servano ancora le pagine 18, 20, 21 e 24 per finire il capitolo. Quelle pagine sono là fuori, da qualche parte...",
  obj = "Porta le pagine 18, 20, 21 e 24 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot, per completare il Capitolo III.",
  progress = "Hai avuto fortuna con le pagine 18, 20, 21 o 24? Sono le uniche che ci servono per ricomporre il Capitolo III.",
  reward = "Uff! Ottimo lavoro, $N. Il Capitolo III è di nuovo tutto intero!",
  en_title = "Chapter III",
  en_obj = "Bring pages 18, 20, 21 and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.",
}
T[342] = {
  title = "Capitolo IV",
  desc = "Ah, il Capitolo IV: il gran finale! E che finale è stato!$B$BCi mancano solo tre pagine per questo capitolo. Ci servono le pagine 25, 26 e 27 per ricomporre il Capitolo IV.",
  obj = "Porta le pagine 25, 26 e 27 di The Green Hills of Stranglethorn di Nesingwary a Barnil Stonepot, per completare il Capitolo IV.",
  progress = "Ci servono solo tre pagine per finire il Capitolo IV, $N. Hai già le pagine 25, 26 o 27?",
  reward = "Magnifico! Ora il Capitolo IV è pronto!",
  en_title = "Chapter IV",
  en_obj = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.",
}
T[343] = {
  title = "A Proposito di Fortezza",
  desc = "Terrò un discorso sulla Fortezza dello Spirito, e vorrei recitare dei passi da un certo libro di metallurgia — \"Le tensioni del ferro\". Una copia di questo libro dovrebbe essere nella Biblioteca Reale, dentro il Mastio di Stormwind. Puoi recuperarmela? Se lo fai, che le benedizioni della Luce siano con te!$B$BLa Biblioteca Reale è molto grande, ma il bibliotecario capo, Milton Sheaf, conosce ogni scaffale come se fosse suo figlio. Parla con lui, il libro te lo troverà.",
  obj = "Va' in Royal Library, dentro il Mastio di Stormwind, e parla con Milton Sheaf. Può trovarti il libro di metallurgia che serve a Brother Kristoff per il suo discorso.",
  reward = "Metallurgia? Ah sì, abbiamo molti libri sull'argomento, e siamo felici di aiutare Fratello Kristoff con il suo discorso! Ora... qual era il libro preciso che serviva al buon fratello?",
  en_title = "Speaking of Fortitude",
  en_obj = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.",
}
T[344] = {
  title = "Fratello Paxton",
  desc = "Le tensioni del ferro? Sì, lo conosco. Un libro niente male, scritto dal minatore nano Margulf Blaggon qualche decennio fa. Ha passato quasi tutto il suo tempo nelle profondità delle montagne di Khaz Modan, a scavare minerale. Un tipo sveglio!$B$BMa dov'ero rimasto? Ah sì, Le tensioni del ferro! Temo che il libro sia stato spostato all'Abbazia di Northshire. Il custode della biblioteca dell'abbazia, Fratello Paxton, voleva farne una copia per i suoi scaffali.$B$BMa è successo mesi fa. Mi chiedo perché ci stia mettendo tanto...",
  obj = "Parla con Brother Paxton, all'Abbazia di Northshire.",
  reward = "Il signor Sheaf si chiede dove sia finito il suo libro? Be', è un po' imbarazzante. Il libro ce l'ho io, ma sto ancora facendo la mia copia e non sono proprio pronto a restituire l'originale!",
  en_title = "Brother Paxton",
  en_obj = "Speak with Brother Paxton in the Northshire Abbey.",
}
T[345] = {
  title = "Rifornimenti di Inchiostro",
  desc = "Volevo finire la mia copia delle Tensioni del ferro, ma...$B$BBe', vedi, l'inchiostro per i libri che copio me lo faccio da solo. È una mia ricetta: non cola e non sbava, e asciuga molto in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi la copiatura, e non ho avuto modo di farne dell'altro!$B$BPer farne ancora mi serve del Minerale di Ferro di Rethban dalle Redridge Mountains. Il mio fornitore abituale è il Caposquadra Oslow, a Lakeshire.",
  obj = "Parla con Foreman Oslow, a Lakeshire, e chiedigli del Minerale di Ferro di Rethban.",
  reward = "Ti serve cosa?? Forse non l'hai notato, ma siamo impegnati a rinforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Minerale di Ferro di Rethban, dovrai procurartelo da $Gsolo:sola;!",
  en_title = "Ink Supplies",
  en_obj = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.",
}
T[346] = {
  title = "Torna da Kristoff",
  desc = "Ora che ho finito di copiare il libro, ecco l'originale delle Tensioni del ferro. Grazie della pazienza e, se vedi Milton, digli per favore che mi dispiace per il lungo ritardo.",
  obj = "Torna da Brother Kristoff, in Cathedral Square. Dagli il libro Le tensioni del ferro.",
  progress = "Sei $Griuscito:riuscita; a trovare il libro?",
  reward = "È proprio quello! Grazie, $N. Che la Luce splenda radiosa sul tuo corpo e sul tuo spirito!",
  en_title = "Return to Kristoff",
  en_obj = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.",
}
T[347] = {
  title = "Minerale di Rethban",
  desc = "Il Minerale di Rethban prende il nome dall'uomo che per primo lo trovò, Bart Rethban. Fuso non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che certi scrivani usano nelle loro tinture. Si trova nelle Caverne di Rethban, a nord di qui.$B$BDi solito ne abbiamo un po' in magazzino, ma siamo troppo occupati a prepararci agli attacchi degli Orchi per raccoglierne. E poi... adesso nelle Caverne di Rethban vivono gli Gnoll di Redridge, e sono i loro Sgobboni a raccogliere il minerale.$B$BQuindi, se te ne serve, dovrai procurartelo da $Gsolo:sola;.",
  obj = "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton, alla Biblioteca di Northshire.",
  progress = "Ce l'hai il Minerale di Rethban?",
  reward = "Oh, splendido! Posso usare questo minerale per fare la mia tintura, e poi finire di copiare Le tensioni del ferro.$B$BGrazie, $N!",
  en_title = "Rethban Ore",
  en_obj = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.",
}
T[348] = {
  title = "Febbre di Stranglethorn",
  desc = "Sto male... così... tanto m-m-male...$B$B...ho preso la Febbre di Stranglethorn... virus m-m-mortale...$B$B...l'unica cura... è... è... mangiare il cuore di M-m-m-m-mokk il Selvaggio... sfuggente bestia bianca...$B$B...Lo stregone Unbagwa... l'unico che può e-e-evocarlo...$B$B...cerca Unbagwa nella grotta nascosta sul capo meridionale...$B$B...fa' presto... sto morendo... morendo...",
  obj = "Trova Witch Doctor Unbagwa e fagli evocare Mokk the Savage. Porta l'Heart of Mokk a Fin Fizracket.",
  progress = "...mamma?$B$B...che freddo...$B$B...sto andando nel Twisting Nether... t-t-t-tienimi, mamma...",
  reward = "...sento tornare le forze...$B$BDove sono? A Booty Bay? Oh, cielo! Ho fatto un sogno stranissimo...$B$B...la debolezza non mi ha ancora lasciato del tutto...",
  en_title = "Stranglethorn Fever",
  en_obj = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.",
}
T[349] = {
  title = "Febbre di Stranglethorn",
  desc = "Testo temporaneo 02 — descrizione",
  obj = "Testo temporaneo 02 — registro",
  progress = "Stregone Unbagwa sapere cosa piacere a Mokk il Selvaggio. Sì, sì!$B$BIo parlare con spiriti e fare venire lui, io fare.$B$BMa anche altre bestie-gorilla piacere parlare con spiriti. Tu proteggere Stregone Unbagwa e io fare venire lui da te.$B$BStregone Unbagwa volere prima qualcosa. Tu portare 10 Zanne di Gorilla e io cominciare parlare con spiriti!",
  reward = "A Stregone Unbagwa piacere Zanne di Gorilla! Per te io parlare con spiriti. Fare venire Mokk il Selvaggio.$B$BMa tu proteggere Stregone Unbagwa da altre bestie-gorilla, o niente Mokk per te!",
  en_title = "Stranglethorn Fever",
  en_obj = "Speak with Witch Doctor Unbagwa.",
}
T[350] = {
  title = "Rivolgiti a un Vecchio Amico",
  desc = "Che Marzon sia in contatto con un membro dei Defias e abbia legami con Lescovar...$B$BOra che hai ucciso VanCleef e Thredd, sarà difficile assicurare Lescovar alla giustizia come merita: le tue prove non valgono niente senza le loro testimonianze. E questo senza nemmeno considerare che Lescovar è un nobile e ha ottimi agganci. Di fatto questo lo mette al di sopra della legge.$B$BTi servirà altro aiuto. Mi ripugna farlo, ma conosco qualcuno che ci darà una mano. Trias lo trovi nel Quartiere Commerciale della città.",
  obj = "Parla con Elling Trias, a Stormwind.",
  reward = "Stai scherzando? Shaw vuole di nuovo il mio aiuto? Ma che faccia tosta...$B$BLa Defias Brotherhood, dici? Be', sei proprio $Gportatore:portatrice; di notizie meravigliose, eh? Adesso mi dirai che Deathwing è ancora vivo e sta attaccando la città.$B$BVa bene, raccontami tutto dall'inizio. E non tralasciare niente che ti sembri poco importante. Devo sapere tutto.",
  en_title = "Look to an Old Friend",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[351] = {
  title = "Trova OOX-17/TN!",
  desc = "Hai portato alla luce una specie di strano congegno di metallo a forma di uovo. Armeggi con una delle sue manopole e l'uovo prende vita, aprendosi in una specie di marchingegno robotico gnomesco! Dall'interno dell'uovo robotico prende vita una voce gracchiante.$B$B\"Mi chiamo Oglethorpe, e il mio robot viaggiatore è scomparso! Ti ricompenserò se lo recuperi! Per favore, porta questo segnalatore al robot. Ottimo, ora ho calcolato le coordinate per te! È precipitato vicino all'Abisso Golaperta, a Tanaris!\"",
  obj = "Porta l'OOX-17/TN Distress Beacon al robot viaggiatore di Oglethorpe.",
  progress = "A quanto pare hai trovato il relitto di... un pollo robotico? La voce dall'interno dell'uovo torna a gracchiare:$B$B\"Sì, ottimo lavoro! Questo è proprio il mio robot viaggiatore, anche se i miei sensori indicano che gli serve una scossa d'avviamento prima di poter tornare in volo a Booty Bay per le riparazioni. Forza, metti il segnalatore dentro il rover. Al resto penserà il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot viaggiatore.$B$BDall'interno del robot si sentono ronzii e sibili mentre fatica a rimettersi in piedi. Quando il robot ha preso vita, si sente ancora una volta la voce di Oglethorpe, ma stavolta dall'interno del robot:$B$B\"OOX-17/TN almeno funziona, ma ha bisogno di grosse riparazioni! È decisamente troppo pesante perché tu possa trasportarlo... ma credo di avere un'idea. Te la senti di badargli ancora un po'?\"",
}
T[373] = {
  title = "La Lettera Mai Spedita",
  desc = "Perquisendo Edwin VanCleef, tra le altre cose trovi una lettera mai spedita. È indirizzata a Baros Alexston, l'Architetto Cittadino di Stormwind, Municipio, Piazza della Cattedrale.$B$BSembra scritta e sigillata di recente.",
  obj = "Consegna la Lettera per l'Architetto Cittadino a Baros Alexston, a Stormwind.",
  progress = "Sì? C'è qualcosa in cui posso aiutarti?",
  reward = "Edwin VanCleef, dici? Mi sarei aspettato più facilmente una lettera da mia nonna morta... Quindi l'hai ucciso? Perdonami se lo dico, ma sono un po' sorpreso. Da giovane era un combattente senza pari. Vediamo cosa sente il bisogno di scrivermi dopo tutti questi anni.$B$B<Baros scorre la lettera.>$B$BEdwin... Vedo che gli anni non ti hanno cambiato di una virgola, idealista come sempre, e romantico. Non gli importa chi fa soffrire, $N. La vendetta lo ha divorato. D'altronde, non sono sicuro di potergliene fare una colpa.",
  en_title = "The Unsent Letter",
  en_obj = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.",
}
T[377] = {
  title = "Delitto e Castigo",
  desc = "Come se trascurare gli abitanti di Duskwood non bastasse, ora l'House of Nobles sputa in faccia al Darkshire Council con la decisione di imprigionare Dextren Ward a Stormwind invece di decapitare quel criminale, come vuole la sentenza di Lord Ebonlocke.$B$BWard è stato colto a vendere a Morbent Fel i cadaveri del cimitero, un crimine punibile con la morte. Eppure Stormwind lo rivendica come proprio prigioniero.$B$BAssassina Ward nello Stormwind Stockade — portami la sua mano — e ti ricompenserò.",
  obj = "Councilman Millstipe, di Darkshire, vuole che gli porti la mano di Dextren Ward.",
  progress = "Finché a un profanatore di cadaveri come Dextren Ward è concesso vivere, la giustizia resta tradita. Torna da me quando la condanna a morte di Lord Ebonlocke sarà eseguita su quel sacrilego di Ward. Daremo alle famiglie dei morti la pace che meritano e, meglio ancora, manderemo un messaggio chiaro all'House of Nobles di Stormwind.",
  reward = "Così Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Ce ne siamo liberati, di quella feccia, dico io. E complimenti a te, $Gamico mio:amica mia;! Non solo hai dato alle famiglie dei morti la serenità che meritano, ma hai mandato un messaggio pungente a quei burocrati corrotti dell'House of Nobles. Stormwind deve farsi carico dei bisogni della gente di Duskwood, o ci libereremo dalla loro tirannia.",
  en_title = "Crime and Punishment",
  en_obj = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",
}
T[378] = {
  title = "Una Furia Profonda",
  desc = "Hai dimostrato la tua lealtà a Re Magni, $C. E il tuo odio per la feccia dei Dark Iron è grande quanto il mio.$B$BC'è un compito che vorrei portare a termine io stesso, ma l'onore mi obbliga a restare con Longbraid. Roggo però ha raccolto informazioni che provano che Kam Deepfury è stato tra i cospiratori dell'attacco al Thandol Span. È per i piani di Deepfury che Longbraid ha perso i suoi cari.$B$BDeepfury è trattenuto per ragioni politiche nello Stormwind Stockade. Lo voglio morto, $N. Per Longbraid! Portami la sua testa!",
  obj = "Motley Garmason vuole che gli porti la testa di Kam Deepfury a Dun Modr.",
  progress = "Non lascerò che la sciocca burocrazia degli Umani si intrometta nelle questioni dei Nani, $N. È provato che Kam Deepfury ha cospirato nell'attacco al Thandol Span. La brava gente di Re Magni ha perso la vita per l'inganno di Deepfury. Agli Umani magari basta lasciar marcire Deepfury nello Stockade, ma io non dormirò sonni tranquilli finché Deepfury non sarà ucciso.",
  reward = "Così Kam Deepfury ha finalmente provato cosa vuol dire finire nelle mani della Morte? Bene. Se lo merita, quella feccia codarda dei Dark Iron. Hai fatto bene, $C. Le vittime dell'attacco al Thandol Span erano solo vittime in un mondo lacerato da guerra e disordini. Le loro famiglie potranno trovare pace sapendo che Deepfury ha avuto la punizione che meritava. La morte del fratello di Longbraid è stata vendicata.",
  en_title = "The Fury Runs Deep",
  en_obj = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.",
}
T[379] = {
  title = "Placa Quella Sete",
  desc = "Vuoi una fonte di energia. Per quella posso aiutarti. Sai cosa voglio io? Voglio qualcosa da bere! Portami cinque Otri d'Acqua Wastewander e ti darò la 4711-FTZ.$B$BOra... indovina dove si trovano gli Otri d'Acqua Wastewander! Perché non vai da uno dei nomadi Wastewander a est di qui e gliene chiedi uno. Poi fammi sapere com'è andata.",
  obj = "Porta 5 Wastewander Water Pouches a Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Allora, i nomadi te li hanno ceduti \"volontariamente\", quegli otri d'acqua?",
  reward = "Perfetto, la fonte di energia è tua. Però non è proprio progettata per un kit scientifico come quello, quindi avrai solo un tempo limitato prima che tutti i dati che raccogli facciano bum!$B$BQuando avrai raccolto tutto quello che ti serve per quello che stai facendo, qualunque cosa sia, portami tutto e spegnerò la fonte come si deve. Avrai al massimo due ore per fare quello che devi fare.$B$BSe non ce la fai in tempo, posso sempre venderti un'altra fonte di energia per riprovare. Hai capito bene — venderti!",
}
T[386] = {
  title = "Chi la Fa l'Aspetti...",
  desc = "Targorr il Terrificante serviva agli ordini di Gath'Ilzogg come Boia supremo. I suoi metodi erano spietati perfino per dei sudici orchi. Uomini che si erano battuti con coraggio per difendere il Regno venivano torturati per un suo capriccio. Ora è rinchiuso nello Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili burocrati ha bloccato la sua esecuzione. Sono sicuro che sotto c'è un imbroglio.$B$BElimina Targorr il Terrificante, $N. Va' allo Stockade e decapitalo, prima che l'inganno ci travolga.",
  obj = "Porta la testa di Targorr the Dread a Guard Berton, a Lakeshire.",
  progress = "Sei già $Gstato:stata; a Stormwind, allo Stockade? Temo che l'imbroglio che ha tenuto in vita Targorr il Terrificante così a lungo finirà per rimetterlo in libertà. È stato condannato a morte, $N, non a fare da pedina politica per il capriccio di un nobile.",
  reward = "Targorr il Terrificante ha finalmente incontrato il suo destino. Da parte mia sono contento di sapere che la bestia ora sa cosa vuol dire finire nella morsa spietata della Morte. Hai fatto bene, $N. A volte la giustizia più vera si trova solo fuori dal tribunale e oltre lo sguardo offuscato della politica.",
  en_title = "What Comes Around...",
  en_obj = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",
}
T[387] = {
  title = "Sedare la Rivolta",
  desc = "La rivolta va sedata! Mi serve il tuo aiuto. Se si sparge la voce che la prigione è in mano ai detenuti, perdo il posto! Se questo non è un imbroglio, allora non ne ho mai visti. Ma adesso quello che conta è piegare questi prigionieri, per la sicurezza di Stormwind.$B$BLa pena per l'insurrezione è la morte. Uccidi qualcuno di questi degenerati! Dovrebbe bastare a riportare le cose sotto controllo.",
  obj = "Warden Thelwater, di Stormwind, vuole che tu uccida 10 Defias Prisoner, 8 Defias Convict e 8 Defias Insurgent nello Stockade.",
  progress = "Lo Stockade è ancora in mano loro! Bisogna far capire a questi Ratti dei Defias che le loro azioni non saranno tollerate. Adesso torna laggiù e usa la forza!",
  reward = "Nello Stockade ti sei $Gbattuto:battuta; con valore, $N. È evidente che il problema è più grande di noi due. Ma hai fatto un buon lavoro, e di questo ti sono grato.",
  en_title = "Quell The Uprising",
  en_obj = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.",
}
T[388] = {
  title = "Il Colore del Sangue",
  desc = "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un bravo ragazzo. Aveva appena 14 anni. Quando l'esercito è stato mandato al fronte, Mac ha preso le armi per difendere la città. Faceva la guardia nello Stockade, dove è rinchiusa la banda dei Defias. Mac ha rimproverato alcuni prigionieri perché strappavano le coperte di lana per farne sciarpe, il simbolo della loro banda. Per questo Mac è stato pugnalato alle spalle.$B$BVoglio vendetta. Portami 10 delle loro preziose Bandane di Lana. Sono del colore del sangue.",
  obj = "Nikova Raskol, di Stormwind, vuole che tu raccolga 10 Red Wool Bandana.",
  progress = "Vedo che sei $Gtornato:tornata;, $C. Hai già raccolto 10 Bandane di Lana Rossa da quella Feccia dei Defias nello Stockade?",
  reward = "Quindi queste bandane — luridi simboli di corruzione — sono ciò per cui il mio Mac è dovuto morire? Che spreco. Che tragico sacrificio.$B$BMa ahimè, non posso tornare al passato. Sappi solo, $N, che con quello che hai fatto hai reso giustizia alla mia famiglia.",
  en_title = "The Color of Blood",
  en_obj = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.",
}
T[389] = {
  title = "Bazil Thredd",
  desc = "VanCleef e io eravamo membri della Stonemasons Guild. Il nostro progetto principale era ricostruire Stormwind dopo la Guerra.$B$BQuando abbiamo finito il nostro lavoro, ci hanno imbrogliati. I nobili si sono rifiutati di pagarci per l'opera. Ad alcuni degli Stonemasons più anziani sono stati offerti incarichi di governo, ma VanCleef ha rifiutato il suo per lealtà verso tutti gli Stonemasons. Ha guidato una rivolta e ha lasciato la città, giurando vendetta.$B$BIl suo luogotenente, Bazil Thredd, potrebbe sapere di più sui piani di VanCleef. È tenuto prigioniero nello Stockade.",
  obj = "Parla con Warden Thelwater, nello Stockade.",
  reward = "Che diamine vuoi, per la Luce? Non vedi che qui siamo in piena crisi?$B$BBazil Thredd?! Perché mai vorresti parlare con quel bastardo? E come faccio a sapere che non sei $Guno:una; dei suoi compari, $Gvenuto:venuta; quaggiù a dare una mano alla sua maledetta rivolta? Se non fossero aperte tutte quelle dannate celle, ti ci butterei dentro per un po'!",
  en_title = "Bazil Thredd",
  en_obj = "Speak with Warden Thelwater in the Stockade.",
}
T[391] = {
  title = "I Tumulti nello Stockade",
  desc = "Mettiamo subito in chiaro una cosa, $N: non mi fido di te. Ma, stando così le cose, probabilmente non farai la differenza.$B$BAllora si fa così: scendi laggiù e fatti la tua chiacchierata con Thredd. Se sei davvero dalla nostra parte, uccidilo e portami la sua testa a lavoro finito. E se si scopre che sei dalla sua parte, e non torni su... quando ti troveremo, morirai insieme al resto dei vermi.",
  obj = "Uccidi Bazil Thredd e riporta la sua testa a Warden Thelwater, allo Stockade.",
  progress = "O mi porti la testa di Thredd, o prendo la tua: intesi, $N?",
  reward = "Senza Thredd a guidarli, i tumulti saranno più facili da controllare, speriamo. Vedremo.$B$BDevo dire che, dopo mezz'ora, non mi aspettavo proprio che tornassi su, ma a quanto pare ti avevo giudicato male.$B$BImmagino, allora, che da lui tu non abbia cavato molto di utile? Ma sulle attività di Thredd so un paio di cose che potrebbero interessarti.",
  en_title = "The Stockade Riots",
  en_obj = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.",
}
T[392] = {
  title = "Lo Strano Visitatore",
  desc = "Nei primi anni di prigionia Thredd non ha mai ricevuto visite. Immaginavo che non servisse più alla Brotherhood, e che quindi l'avessero abbandonato.$B$BPoi, qualche mese fa, è cambiato tutto: ha cominciato a ricevere visite regolari... una volta, forse due alla settimana. Era un uomo strano — uno di quelli silenziosi. Avevo i miei sospetti, ma i suoi documenti erano tutti in regola.$B$BSecondo i documenti si chiamava Maelik; ecco la sua descrizione. Non credo che verrà più a trovare Thredd.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Baros Alexston, a Stormwind.",
  progress = "Sì, $N? Cos'hai trovato?",
  reward = "Hmm. Maelik? No, il nome non mi dice niente, e nemmeno questa descrizione. Ma potrebbe essere chiunque! Un ex Stonemason, uno della Defias Brotherhood... Però, se ha i buoni agganci che dice Thelwater, forse qualcun altro potrebbe riconoscerlo. Fammi pensare.",
  en_title = "The Curious Visitor",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.",
}
T[393] = {
  title = "L'Ombra del Passato",
  desc = "Non ne ho davvero idea, $N. C'è qualcun altro che potrebbe aiutarti, e si dà il caso che mi debba un favore per — be', lasciamo perdere. Il Maestro Mathias Shaw dello SI:7 lo trovi nella caserma della Città Vecchia. Shaw tiene d'occhio quasi tutti i traffici loschi o sottobanco della città.$B$BSe c'è qualcuno che lo sa, è lui.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Master Mathias Shaw, a Stormwind.",
  progress = "Salve. In cosa posso esserti utile, $C?",
  reward = "Cosa? Cos'è questo? Sì, credo di sapere chi è quest'uomo, ma il suo nome non è Maelik. Gli assassini portano molti nomi e molte maschere, e se ne sbarazzano quando non servono più. È noto anche con un altro alias, Marzon; anche se di sicuro nemmeno quello è il suo vero nome.$B$BIn ogni caso è un assassino, e io so parecchio di lui.$B$BAl momento Marzon è al soldo di Ser Gregor Lescovar, un nobile di dubbia fama, persino per la corrotta nobiltà di Stormwind.",
  en_title = "Shadow of the Past",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.",
}
T[394] = {
  title = "La Testa della Bestia",
  desc = "Trova Shaw nella Città Vecchia. Fagli sapere che la minaccia di Lescovar è stata sventata e raccontagli che ruolo hai avuto nelle trame del nobile contro la città. Sono sicuro che sarà fiero di avere $Gun altro eroe:un'altra eroina; tra i cittadini di Stormwind.$B$BCon ogni probabilità ti manderà a incontrare il Principe o qualche altro nobile. Non montarti la testa, $N. I nobili possono credere quanto vogliono di comandare la città, ma certe cose restano fuori dalla loro portata.",
  obj = "Parla con Mathias Shaw, a Stormwind.",
  reward = "È morto, dunque? La tua giustizia è stata rapida, $N. Prego la Luce di non diventare mai la tua preda!$B$B<Ride e ti dà una pacca sulla spalla.>$B$BNon è una critica, $N. Come potrei, io che sono il maestro di tutti gli assassini? Ma in verità hai reso un grande servizio alla gente di Stormwind, e di questo ti ringrazio.",
  en_title = "The Head of the Beast",
  en_obj = "Speak to Mathias Shaw in Stormwind.",
}
T[395] = {
  title = "La Fine della Brotherhood",
  desc = "Ah, quasi dimenticavo. Alexston è passato mentre eri via, voleva parlarti. Di sicuro vuole riferire ai nobili quel che è successo con la Defias Brotherhood.$B$BUn consiglio, $N: se qualcuno dovesse chiedere, io riferirei tutti i particolari tranne il fatto che è stata la tua mano a uccidere Lescovar. Fidati. Sono... pratico... di come vanno certe cose.$B$BE quanto a Trias, be', non parlarne con nessuno... mai... se puoi evitarlo.",
  obj = "Parla con Baros Alexston, a Stormwind.",
  reward = "È bello vederti, $N. Ho sentito che Ser Gregor Lescovar è stato trovato morto non molto tempo fa.$B$BPare che la tua missione sia riuscita. Ti sono grato di aver salvato me, e molti altri, dalla vendetta di VanCleef.",
  en_title = "Brotherhood's End",
  en_obj = "Speak with Baros Alexston in Stormwind.",
}
T[396] = {
  title = "Udienza dal Re",
  desc = "Ho preparato un rapporto per il Re. Credo che debba essere tu a consegnarglielo, insieme al resoconto di quel che hai scoperto. Non preoccuparti: non c'è dubbio che ti loderà per aver fatto il tuo dovere verso la gente di Stormwind.$B$BLa tua udienza è fissata a breve, quindi faresti meglio a sbrigarti: c'è un bel pezzo di strada fino al Mastio di Stormwind.",
  obj = "Consegna il Report on the Defias Brotherhood di Baros Alexston a King Varian Wrynn, nel Mastio di Stormwind.",
  progress = "$N, giusto? Baros Alexston mi ha avvisato che saresti $Gvenuto:venuta;. Devo dire che sono molto interessata a quel che hai da raccontare.",
  reward = "Meriti lode per il servizio che hai reso a Stormwind, $N. Se VanCleef avesse avuto successo nelle sue macchinazioni, avrebbe senza dubbio fatto un danno considerevole al regno — cosa che ovviamente dobbiamo evitare.$B$BPrendi questo, $C, come segno della riconoscenza del Re. Mi dispiace solo che non possa consegnartelo di persona, ma è via per una missione diplomatica e non tornerà per un po'.",
  en_title = "An Audience with the King",
  en_obj = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.",
}
T[397] = {
  title = "Ci Hai Servito Bene",
  desc = "Mi dicono che Ser Wishock ha gradito la sua bevanda.$B$BCi hai servito bene, $N. Grazie a te gli Stregoni di Stormwind potranno praticare le nostre arti senza essere disturbati. Per il tuo impegno ho preparato un dono speciale per te. Parla con il mio servo, Zggi, e prenditi la ricompensa.",
  obj = "Parla con Zggi, il servo di Zardeth of the Black Claw, per ritirare la ricompensa.",
  reward = "Padrone dice dare dono a $N. Zggi vuole tenere bel dono ma Zggi sa che non deve tradire Padrone.",
  en_title = "You Have Served Us Well",
  en_obj = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.",
}
T[401] = {
  title = "Aspetta che Sirra Finisca",
  desc = "Ho quasi finito di tradurre quel biglietto. Se torni fra qualche istante, dovrei aver terminato.",
  obj = "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.",
  reward = "Ecco fatto. È tradotto...$B$B<L'aria si fa pesante, come se una cortina nera e spessa calasse sulla terra...>",
  en_title = "Wait for Sirra to Finish",
  en_obj = "Wait a moment, then speak with Sirra Von'Indi again.",
}
T[434] = {
  title = "L'Attacco!",
  desc = "Dopo che avrò messo addosso a Spybot il travestimento, andrà a parlare con Lescovar. Le guardie dovrebbero lasciarlo passare senza problemi.$B$BMentre tu mi procuravi il materiale, io ho pensato a far sapere a Marzon che era ora che lui e Lescovar si rivedessero. Gli ho anche fatto arrivare qualche informazione falsa.$B$BLescovar congederà le guardie e aspetterà Marzon qui fuori in giardino. Quando li senti parlare dei Defias, entra in azione. Devi ucciderli tutti e due prima che le guardie tornino! Quando hai finito, parla con Trias.",
  obj = "Resta nel giardino finché Lord Gregor Lescovar e Marzon the Silent Blade non hanno finito di parlare. Poi uccidili tutti e due e torna da Elling Trias, a Stormwind.",
  progress = "Sì, $N? Le cose vanno bene con Tyrion? Mi ha messo al corrente della situazione e l'ho aiutato a ingannare Marzon perché andasse al castello.$B$BMarzon è stato una spina nel fianco di molte persone a Stormwind, e parecchie di loro sono miei cari amici. Nessuno tocca i miei amici... non se sa cosa gli conviene.$B$BÈ solo un peccato che nel frattempo io stia facendo indirettamente un favore a Shaw e allo SI:7. Pazienza, non tutti i piani sono perfetti.",
  reward = "Quindi è fatta? Bene. Grazie mille per la tua discrezione, $N. Hai dimostrato il tuo valore più di una volta. Non mancherò di tenere d'occhio te e i tuoi progressi nell'Alleanza.$B$BMi raccomando, tieni la fedina pulita.",
  en_title = "The Attack!",
  en_obj = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.",
}
T[442] = {
  title = "Assalto all'Isola di Fenris",
  desc = "È giunto il momento di assaltare la roccaforte del Flagello in Silverpine: l'Isola di Fenris.$B$BDevi tornare sull'Isola e distruggere Thule Ravenclaw. Voglio la sua testa!$B$BQuesta missione è tanto pericolosa quanto vitale, $N. Non devi fallire.",
  obj = "Porta Thule's Head a High Executor Hadrec, al Sepulcher.",
  progress = "Non si può permettere al Flagello di restare in Silverpine, $N. Torna da me quando avrai la prova della morte di Thule.",
  reward = "La morte di Thule Ravenclaw non è stata cosa da poco, $N. Renferrel mi dice che le energie liberate quando hai distrutto Thule si sono sentite fin qui, al Sepulcher.$B$BLe tue azioni risuonano tra le file dei Reietti. Per noi vali sempre di più.",
  en_title = "Assault on Fenris Isle",
  en_obj = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.",
}
T[453] = {
  title = "Trovare la Figura in Ombra",
  desc = "Buona fortuna, $N. Spero che tu trovi quel tipo, e spero che tu lo trovi vivo.$B$BSe ha lasciato Darkshire, dove era al sicuro, potrebbe diventare preda delle bestie delle terre selvagge.",
  obj = "Trova la Shadowy Figure. I tuoi indizi:$B$BNon è di Darkshire.$B$BÈ una persona nervosa e agitata.$B$BHa lasciato Darkshire ed è andato a ovest.",
  progress = "Chi sei?? Lasciami in pace!",
  reward = "<Jitters sospira...>$B$BSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?$B$BBe', se hai letto quel diario... allora sai solo metà della storia!",
  en_title = "Finding the Shadowy Figure",
  en_obj = "Find the Shadowy Figure.  Your clues:$B$BHe is not native to Darkshire.$B$BHe is a nervous, jittery person.$B$BHe left Darkshire and headed west.",
}
T[455] = {
  title = "Il Varco di Algaz",
  desc = "Gli orchi del clan Dragonmaw hanno un rifugio nelle Wetlands. E adesso si sono spinti fino a Dun Algaz! Non possiamo lasciare che si attestino qui, o Loch Modan resterà tagliato fuori da Menethil Harbor, il nostro porto e la nostra roccaforte nelle Wetlands.$B$BApriti un varco attraverso Dun Algaz fino alle Wetlands, dall'altra parte, e già che ci sei uccidi qualche orco! Presentati a Valstag Ironjaw, a Menethil Harbor.$B$BPer arrivare a Menethil, attraversa Dun Algaz, poi prendi la strada verso nord e al bivio gira a ovest.$B$BContiamo su di te, $N. Non fallire.",
  obj = "Attraversa Dun Algaz.$B$BUccidi 8 Dragonmaw Scout e 6 Dragonmaw Grunt.$B$BPresentati a Valstag Ironjaw, a Menethil Harbor.",
  progress = "Vieni da Loch Modan? Com'è la situazione con gli orchi alla Porta di Algaz?",
  reward = "Il tuo rapporto è pieno di brutte notizie!$B$BVedo che i Dragonmaw stanno avanzando in forze su Algaz. Di solito i Dragonmaw se ne stanno nascosti sulle colline. Cosa li abbia spinti a riversarsi su Algaz resta un mistero...$B$BGrazie, $N. E probabilmente ci servirà il tuo aiuto per sistemare questi orchi.",
  en_title = "The Algaz Gauntlet",
  en_obj = "Traverse Dun Algaz.$B$BKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.$B$BReport to Valstag Ironjaw in Menethil Harbor.",
}
T[463] = {
  title = "Il Greenwarden",
  desc = "Hai sentito parlare del Greenwarden? Non è che lo stai cercando, vero? Be', se è così, secondo me sei $Gpazzo:pazza;, ma chi sono io per impedire a $Gun folle:una folle; di andarsi a cercare la morte?$B$BSe cerchi quella bestia, ho sentito dire che sta nella palude, a est della strada dove si biforca per Dun Modr. Se ne sta in agguato là in mezzo ai crocolisk... e a cose peggiori!$B$BE lascia qui i tuoi soldi. Dove vai non ti serviranno... e non vorrai mica che il vecchio Greenie si scheggi un dente sul tuo oro mentre ti spezza in due con un morso, vero?",
  obj = "Trova il Greenwarden.",
  reward = "Le radici e le felci parlano bene di te, $Gpiccolo:piccola;. Ho molti nomi, ma rispondo solo a pochi. Tu però puoi chiamarmi Rethiel.$B$BE devi prestare ascolto... perché queste terre piangono per ferite infette, e vorrei affidare a te il compito di sanarle.",
  en_title = "The Greenwarden",
  en_obj = "Find the Greenwarden.",
}
T[464] = {
  title = "Stendardi di Guerra",
  desc = "Il clan orchesco Dragonmaw fu quasi distrutto alla fine della Seconda Guerra, dopo che perse il controllo dei suoi draghi rossi addomesticati. I draghi non erano molto contenti dei loro vecchi padroni, e diedero ai Dragonmaw una caccia feroce. I pochi rimasti fuggirono da Grim Batol e si rifugiarono sulle Montagne a est dello Scavo di Whelgar.$B$BOra hanno ripreso forza e hanno un accampamento a nord-est di Menethil.$B$BVogliamo che tu attacchi quell'accampamento. Raccogli e portami i loro stendardi di guerra come prova.",
  obj = "Porta 8 Dragonmaw War Banner a Captain Stoutfist.",
  progress = "Hai attaccato l'accampamento dei Dragonmaw?",
  reward = "Hai combattuto bene, $N. I Dragonmaw non sono la minaccia che erano quando avevano i draghi, ma restano avversari feroci.$B$BI Dragonmaw sono guidati da Nek'rosh, figlio di Nekros, che anni fa era a capo dei Dragonmaw. Nekros usò una magia potente per domare i Draghi Rossi, ma quando quella magia gli venne meno... i draghi non furono contenti.$B$BNekros fu ucciso, e suo figlio ha giurato vendetta contro i draghi che uccisero suo padre.",
  en_title = "War Banners",
  en_obj = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.",
}
T[465] = {
  title = "La Mossa di Nek'rosh",
  desc = "Mentre combattevi i Dragonmaw, abbiamo scoperto qualcos'altro dei loro piani.$B$BNek'rosh ha costruito delle catapulte e vuole assediare Menethil! E con i combattimenti a Dun Algaz siamo di fatto tagliati fuori dai rinforzi!$B$BDevi eliminare quelle catapulte. Sono nell'accampamento dei Dragonmaw.$B$BEcco, prendi quest'esca da fuoco. Apriti la strada fino alle catapulte e usala per dar loro fuoco.$B$BE quando l'avrai fatto, trova e uccidi Nek'rosh. Dobbiamo abbattere questa bestia dei Dragonmaw... tagliandole la testa.",
  obj = "Distruggi le Dragonmaw Catapult.",
  progress = "La prima catapulta è davanti a te. Le darai fuoco?",
  reward = "Metti un po' di esca sulla catapulta, poi fai scoccare una scintilla.$B$BLa fiamma divampa e si propaga in fretta!",
  en_title = "Nek'rosh's Gambit",
  en_obj = "Destroy the Dragonmaw catapults.",
}
T[468] = {
  title = "Presentati al Montanaro Rockgar",
  desc = "Il Montanaro Rockgar cerca volontari per una missione attraverso Dun Algaz, fin dentro le Wetlands.$B$BSe vuoi bagnarti gli stivali in quella contea fradicia a nord, parla con Rockgar a Dun Algaz. Dun Algaz è più a nord lungo la strada, oltre la torre di guardia.",
  obj = "Parla con Mountaineer Rockgar.",
  reward = "Salve, $C! Sei qui per la missione di ricognizione, vero? Benissimo!$B$BSpero che il tuo equipaggiamento sia in buone condizioni, perché questa missione \"di ricognizione\" si è trasformata in qualcosa di più sporco...",
  en_title = "Report to Mountaineer Rockgar",
  en_obj = "Speak with Mountaineer Rockgar.",
}
T[469] = {
  title = "Consegna Quotidiana",
  desc = "Salve, $Gviaggiatore:viaggiatrice;!$B$BNon è che per caso stai andando verso Menethil? Se no, ti consiglio di fare comunque una sosta lì, perché è un buon posto per fare acquisti, e anche per bersi una pinta e rilassarsi.$B$BAllora, se per caso stai andando proprio da quelle parti, non ti dispiacerebbe portare questo fascio di pelli di crocolisk a James Halloran, il conciatore?$B$BLo farei io, ma mia moglie è di pessimo umore ultimamente, e vorrei rimandare il più possibile il momento di affrontarla.",
  obj = "Consegna il Bundle of Crocolisk Skins a James Halloran, il conciatore, a Menethil Harbor.",
  progress = "Salve, $C. Ti interessa un paio di stivali? O magari delle pelli conciate di fresco?",
  reward = "Mmh, questo viene da Einar, giusto? È quasi una settimana che non mi porta le pelli di persona. Di sicuro ha qualche screzio con la moglie!$B$BForse prima o poi manderò mia moglie a parlare con Sida...",
  en_title = "Daily Delivery",
  en_obj = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.",
}
T[470] = {
  title = "A Frugare nella Melma",
  desc = "Durante la mia visita settimanale al Sepolcro di Ironbeard sono stata attaccata da orribili melme gocciolanti! Naturalmente sono andata nel panico.$B$BHo tirato la mia borsa addosso a una di loro, ma non è servito a niente! La melma se l'è risucchiata... Per fortuna mi ha dato abbastanza tempo per scappare.$B$BLa brutta notizia è che mi serve davvero il contenuto della borsa!$B$BNon so a quale melma ho tirato la borsa: erano tutte identiche! Il Sepolcro di Ironbeard è a nord-est di qui, vicino a Dun Modr. Grazie infinite!",
  obj = "Una delle melme del Sepolcro di Ironbeard ha la borsa di Sida, recuperala e riportagliela a Menethil Harbor.",
  progress = "Hai trovato la mia borsa?",
  reward = "Oh, grazie, $N! Temevo che fosse persa per sempre!$B$B<Svuota in fretta sul terreno il contenuto della borsa ricoperta di melma, poi lo raccoglie.>$B$BMmh, a me questo non serve più a molto, ma lavalo bene e sono sicura che potrai farne buon uso.",
  en_title = "Digging Through the Ooze",
  en_obj = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.",
}
T[471] = {
  title = "I Doveri dell'Apprendista",
  desc = "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolisk giganti delle Wetlands. Quando non è tornato, sono andato a cercarlo... Diciamo che non è stato un bello spettacolo.$B$BLa levatrice dice che potrebbe cavarsela, ma intanto a me servono ancora le pelli!$B$B...Se ti va di ucciderne qualcuno in più, di quei bruti, non avrei niente in contrario, dopo quello che hanno fatto. I crocolisk li trovi a nord lungo la costa, oltre le capanne dei murloc.",
  obj = "Raccogli 6 Giant Crocolisk Skin e portale a James Halloran, a Menethil Harbor.",
  progress = "Il mio apprendista è come un figlio per me. Sarà dura per lui vivere con una gamba sola.$B$BAh, $N, come va? Hai le mie pelli?",
  reward = "Mmh... Non è che ti interesserebbe diventare il mio apprendista, vero?$B$BAh! No, sto scherzando. Sei troppo $Gvecchio:vecchia;, tanto per cominciare. E poi — a vederti, sembra che tu abbia altre ambizioni nella vita. Comunque, le pelli che mi hai procurato sono ottime, e saprò farne buon uso.",
  en_title = "Apprentice's Duties",
  en_obj = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",
}
T[472] = {
  title = "La Caduta di Dun Modr",
  desc = "Dun Modr è caduta in mano ai Nani Dark Iron!$B$BLe mie ferite sono gravi, $C. Gran parte del reggimento è stata uccisa! I bruti Dark Iron ci hanno attaccati prima che potessimo riorganizzarci dopo l'imboscata del Thandol Span.$B$BIl nostro comandante, Longbraid, ha suonato il corno della ritirata. Mentre lasciavamo la città sono stato colpito alla schiena da un'ascia vagante. Poi tutto si è fatto nero.$B$BMi sono svegliato qui a Menethil, ma temo per i miei compagni d'arme. Dentro di me arde ancora la speranza. Forse Longbraid è ancora vivo! Vedi se riesci a trovarlo vicino a Dun Modr, $R!",
  obj = "Cerca Longbraid vicino alla città di Dun Modr.",
  reward = "Quale $C $Gcoraggioso:coraggiosa; porta notizie da Menethil? Ah, ti chiamano $N.$B$BPorti speranza in una situazione senza speranza. È davvero una buona notizia che il giovane Harlo sia sopravvissuto. Mentre fuggiva è stato ferito gravemente. Abbiamo avuto appena il tempo di mandarlo via in groppa all'unico destriero sopravvissuto del reggimento.$B$BMa ora ci troviamo in una situazione pericolosa. Dun Modr è caduta e siamo solo l'ombra del grande reggimento che eravamo.",
  en_title = "Fall of Dun Modr",
  en_obj = "Search for Longbraid near the town of Dun Modr.",
}
T[473] = {
  title = "Presentati al Capitano Stoutfist",
  desc = "$N. Il clan orchesco Dragonmaw sta mostrando la sua forza non solo ad Algaz. Il Capitano Stoutfist ha chiesto di parlare con chi è disposto a dare una mano contro questi orchi. È dentro la fortezza, nella sala di guerra.",
  obj = "Parla con Captain Stoutfist.",
  reward = "$N. Valstag mi ha riferito i tuoi successi passati con gli Orchi Dragonmaw a Dun Algaz. Sei $Gun:una; $R di valore.$B$BE ho un compito per te.",
  en_title = "Report to Captain Stoutfist",
  en_obj = "Speak with Captain Stoutfist.",
}
T[474] = {
  title = "Sconfiggi Nek'rosh",
  desc = "Ora che le catapulte sono state bruciate, trova e uccidi il Capotribù Nek'rosh.",
  obj = "Uccidi Chieftain Nek'rosh$B$BPorta Nek'rosh's Head a Captain Stoutfist.",
  progress = "Hai ucciso Nek'rosh?",
  reward = "Ben fatto, e con fegato, $N. Hai inferto un colpo decisivo al clan di orchi Dragonmaw. Forse non si riprenderanno mai. E la distruzione di quelle catapulte ha messo al sicuro Menethil Harbor.$B$BSei $Gun:una; $R di valore, e il regno di Ironforge ricompensa chi lo serve bene.",
  en_title = "Defeat Nek'rosh",
  en_obj = "Kill Chieftain Nek'rosh$B$BBring Nek'rosh's Head to Captain Stoutfist.",
}
T[480] = {
  title = "Il Tessitore",
  desc = "Un arcimago di grande potere sta sovrintendendo alla riattivazione del nodo di energia ley. Con i progressi che hanno fatto, la nostra unica speranza di fermarli è ucciderlo. Sarà difficile: senza dubbio è protetto da molti altri maghi e guardiani.$B$BDevi andare, e devi eliminarlo in fretta. Quando sarà morto, recuperami il suo bastone. Va', ora.",
  obj = "Uccidi l'arcimago di Dalaran, poi recupera il suo bastone per Shadow Priest Allister, al Sepulcher.",
  progress = "Presto, il tempo stringe, $N!",
  reward = "La magia dei maghi si dissolve e le energie ley tornano a sopirsi. I tuoi sforzi hanno dato frutto, $N, e abbiamo inferto un duro colpo ai nostri nemici e agli arroganti maghi di Dalaran.$B$BDobbiamo però restare vigili, sapendo che quella fonte di energia è così a portata di mano... Bisognerà fare piani per il futuro.",
  en_title = "The Weaver",
  en_obj = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.",
}
T[484] = {
  title = "Pelli di Giovani Crocolisk",
  desc = "Sono James Halloran, il conciatore. Le mie pelli di crocolisk conciate sono ricercate ovunque, e le spedizioni partono in nave per i porti di tutto il mondo.$B$BHai conosciuto Einar? È uno dei cacciatori che mi portano le pelli di crocolisk.$B$BSono un po' a corto delle pelli più morbide, quelle che vengono dai crocolisk giovani.$B$BVisto che ne ho poche, ti pagherò profumatamente per una pila di quelle pelli. I crocolisk giovani li trovi nelle paludi appena fuori città.",
  obj = "Procura 4 Young Crocolisk Skin a James Halloran, a Menethil Harbor.",
  progress = "$N, giusto? Hai le mie pelli?",
  reward = "Hai fatto un bel lavoro, $N. La qualità di queste pelli è ottima. Devo metterle in conciatura il prima possibile. Oh, ma prima di farlo, c'è un altro lavoro da sbrigare, e credo che potresti occupartene tu.",
  en_title = "Young Crocolisk Skins",
  en_obj = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.",
}
T[485] = {
  title = "Trova OOX-09/HL!",
  desc = "Hai scoperto una specie di strano congegno di metallo a forma di uovo. Appena armeggi con una delle sue manopole, l'uovo prende vita e si apre, trasformandosi in una specie di marchingegno robotico gnomesco! Dall'interno dell'uovo robotico gracchia una voce.$B$B\"Mi chiamo Oglethorpe Obnoticus e il mio robot a ritorno automatico si è schiantato! Ti ricompenserò se lo recuperi; per favore, porta questo segnalatore al robot!\"$B$B\"Ho appena calcolato per te le coordinate del robot; si è schiantato alla sorgente del fiume, vicino al Tumulo Strisciante!\"",
  obj = "Porta l'OOX-09/HL Distress Beacon al robot a ritorno automatico di Oglethorpe, alla sorgente del fiume negli Hinterlands, vicino a Skulk Rock.",
  progress = "Sembra che tu abbia scoperto il relitto di... un pollo robotico? La voce dall'interno dell'uovo gracchia di nuovo:$B$B\"Sì, ottimo lavoro! Questo è proprio il mio robot a ritorno automatico, anche se i miei sensori indicano che ha bisogno di una spinta per ripartire prima di poter tornare in volo a Booty Bay per le riparazioni. Coraggio, metti il segnalatore dentro il rover — al resto penserà il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore d'emergenza... dentro il pollo... il robot a ritorno automatico.$B$BDall'interno del robot si sentono ronzii e sibili mentre cerca a fatica di rimettersi in piedi. Quando il robot si rianima, si sente di nuovo la voce di Oglethorpe, ma ora dall'interno del robot:$B$B\"Almeno OOX-09/HL funziona, ma ha bisogno di grosse riparazioni! È troppo pesante perché tu possa portarlo... ma credo di avere un'idea. Te la senti di sorvegliarlo ancora un po'?\"",
}
T[495] = {
  title = "La Corona della Volontà",
  desc = "Mug'Thol e la sua banda da guerra di ogre erano stati mandati ad Alterac a recuperare la Corona della Volontà per Lady Sylvanas. Purtroppo, invece di riportarla, quell'idiota ha deciso di provarsela... Immagino che gli ogre non sappiano resistere a niente che brilli e luccichi.$B$BI suoi pasticci, però, sono diventati un discreto problema. La Corona della Volontà gli ha permesso di resistere alla possessione che gli era stata imposta perché servisse Lady Sylvanas.$B$BLa Signora Oscura vuole una punizione esemplare, va' a Tarren Mill, a Hillsbrad, e presentati a Melisara, la mia luogotenente.",
  obj = "Presentati a Melisara a Tarren Mill, nelle Hillsbrad Foothills.",
  reward = "Ti manda Sharlindra? Molto bene, allora, vedrai che non perdo molto tempo in chiacchiere inutili.$B$BMug'Thol è una seccatura, e ce ne occuperemo in fretta, a fondo e senza incidenti.",
}
T[496] = {
  title = "Elisir della Sofferenza",
  desc = "Ah, un altro giorno miserabile a Tarren Mill. Tutta quest'aria pulita mi mette di pessimo umore, $N.$B$BPrima riusciamo ad appestare gli umani di qui, meglio è. Ho condotto studi approfonditi sui possibili agenti letali da usare nei miei intrugli, ma non ho il tempo di raccoglierli tutti.$B$BSe vuoi renderti utile, procurami quanto segue: 10 Lingue d'Orso Grigio e l'Icore di Camminatore, rarissimo e difficile da trovare. Troverai sia gli orsi sia gli striscianti appena fuori Tarren Mill.",
  obj = "Apothecary Lydon, a Tarren Mill, vuole 10 Gray Bear Tongue e un po' di Creeper Ichor.",
  progress = "Vedo che sei $Gtornato:tornata;. Spero che tu sia $Griuscito:riuscita; a raccogliere gli agenti che mi servono. Un altro giorno senza morti mi metterà di un umore nerissimo.",
  reward = "Questi esemplari sono perfetti. Be', $N, sei $Griuscito:riuscita; a portarmi un pizzico di gioia in questa ennesima giornata miserabile. Apprezzo i tuoi sforzi.",
  en_title = "Elixir of Suffering",
  en_obj = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.",
}
T[498] = {
  title = "Il Salvataggio",
  desc = "Io e altri guerrieri siamo stati mandati dal Capoguerra a recuperare un oggetto a Durnholde e a indagare su questo cosiddetto Syndicate.$B$BSiamo andati a Durnholde a dare un'occhiata, ma siamo stati colti di sorpresa da un gran numero di umani. Abbiamo combattuto con coraggio, ma erano talmente tanti che ci hanno sconfitti. Ne hanno fatti prigionieri alcuni, ma io sono riuscito a fuggire.$B$BDurnholde è poco a sud-est di qui, oltre il fiume. Drull e Tog'thar sono prigionieri lì, devi andare a liberarli.",
  obj = "Krusk, a Tarren Mill, vuole che tu liberi Drull e Tog'thar dal Forte Durnholde.",
  progress = "Devi fare in fretta, $C. Mi vengono i brividi a pensare a cosa gli umani staranno facendo a Drull e Tog'thar.",
  reward = "Quindi gli umani pensavano di trasformare i nostri guerrieri in schiavi, eh? Gliela faremo vedere!$B$BA quanto pare hanno portato Gol'dir, il nostro capo, in un altro posto. Dobbiamo trovarlo e salvarlo. Ma per ora non abbiamo idea di dove sia...$B$BQuando avremo una pista, non mancherò di dirtelo, $N.",
  en_title = "The Rescue",
  en_obj = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.",
}
T[499] = {
  title = "Elisir della Sofferenza",
  desc = "Mi basterà un attimo per mescolare questi ingredienti e ricavarne quello che ho battezzato Elisir della Sofferenza.$B$BEcco fatto! Ah, niente rallegra una giornata cupa in queste miserabili colline come portare un po' di sofferenza nel mondo.$B$BVediamo se la nostra pozioncina fa l'effetto voluto.$B$BFa' assaggiare alla mia assistente Umpi quel che la Signora Oscura ha in serbo per gli umani e per il Flagello.",
  obj = "Dai l'Elixir of Suffering a Umpi.",
  progress = "Cra cra!",
  reward = "Craaa!",
  en_title = "Elixir of Suffering",
  en_obj = "Give Umpi the Elixir of Suffering.",
}
T[500] = {
  title = "Taglia sui Crushridge",
  desc = "Gli ogre Crushridge hanno scavato un tumulo di ogre sulle Alterac Mountains, vicino alla città in rovina di Alterac. E i miei esploratori mi dicono che hanno occupato anche quelle rovine.$B$BNon possiamo lasciare che si mettano comodi lassù: se pensano di essere al sicuro dove sono, il loro prossimo passo sarà scendere sulle colline, e allora ce li ritroveremo proprio davanti alla porta di casa!$B$BVa' a nord, nelle Alterac Mountains, e dai la caccia agli ogre. Portami le Nocche Sporche che hanno con sé e ti guadagnerai una bella taglia.",
  obj = "Raccogli 9 Dirty Knucklebones dai Crushridge Ogre nelle Alterac Mountains. Portali a Marshal Redpath, a Southshore.",
  progress = "$N, stai ancora dando la caccia agli ogre? Hai le nocche che ti avevo chiesto di raccogliere?",
  reward = "Molto bene, $N. Devi aver fatto a pezzi un bel mucchio di ogre per raccogliere tutte queste nocche.$B$BQuesto dovrebbe tenerceli lontani. Almeno per un po'.",
  en_title = "Crushridge Bounty",
  en_obj = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.",
}
T[501] = {
  title = "Elisir del Dolore",
  desc = "Oh, $N... i fiori sbocciano a Hillsbrad e l'aria è così fresca e frizzante. Non posso fare a meno di crogiolarmi nella tristezza di tutto questo. Guardo fuori dalla mia finestra lercia e sogno il giorno in cui la nostra Nuova Piaga porterà a questo mondo la morte che merita.$B$BPer quanto mi piacerebbe starmene seduto a rimuginare tutto il giorno, il mio dovere verso la Signora Oscura mi chiama. Mi aiuti? Le mie ricerche mi fanno credere che con il sangue di un Puma potrei preparare il più splendido degli intrugli di morte. Portamene un po' e ci divertiremo un pochino.",
  obj = "Porta 10 fiale di Mountain Lion Blood ad Apothecary Lydon, a Tarren Mill.",
  progress = "Mi ricordo di te, $N. Dovevi aiutarmi a preparare il mio ultimo elisir. Mi serve quel sangue prima di poter portare agli abitanti di Hillsbrad la mia personalissima dose di infelicità.",
  reward = "Che raccolta superba, $N.",
  en_title = "Elixir of Pain",
  en_obj = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.",
}
T[502] = {
  title = "Elisir del Dolore",
  desc = "Ah, non c'è niente di meglio dell'odore del sangue fresco tra le colline!$B$BOra mescoliamo un po' di questo e un pizzico di quello e che il vero divertimento cominci! Quel che ho creato con questo sangue mi piace chiamarlo Elisir del Dolore. Se i miei calcoli sono giusti, questo intruglio potrebbe essere l'inizio di qualcosa di molto bello per Lady Sylvanas. Ma ci serve una prova.$B$BPorta questo elisir alla fattoria più a nord dei Campi di Hillsbrad, a sud-ovest. Vediamo come piace questo \"bocconcino\" a Stanley, il cagnolino del Contadino Ray.",
  obj = "Fa' bere l'Elixir of Pain a Stanley.",
  progress = "Bau?",
  reward = "Versi un po' di elisir nella mano e la porgi davanti al muso di Stanley.",
  en_title = "Elixir of Pain",
  en_obj = "Feed the Elixir of Pain to Stanley.",
}
T[503] = {
  title = "Gol'dir",
  desc = "Da quel che capisco dai documenti che hai recuperato, Gol'dir è tenuto prigioniero in una grande base del Syndicate a nord, molto probabilmente nelle Alterac Mountains. È in prigionia da fin troppo tempo e va liberato.",
  obj = "Libera Gol'dir, poi torna da Krusk, a Tarren Mill.",
  progress = "Dammi la chiave, $C, apro io la serratura.",
  reward = "Grazie, $N. Ho guidato io la spedizione da Durotar agli ordini del Capoguerra, ma come vedi i nostri piani sono andati un po' storti. Mi hanno tenuto prigioniero qui in questa città, costringendomi a lavorare, a trasportare pesi, a scavare...$B$BQuel che ho sofferto però non conta. C'è un'informazione importante che devi consegnare a chi guida il nostro gruppo adesso.",
  en_title = "Gol'dir",
  en_obj = "Free Gol'dir then return to Krusk in Tarren Mill.",
}
T[504] = {
  title = "Guerrafondai Crushridge",
  desc = "Ora che hai avuto un assaggio degli ogre Crushridge, voglio che tu gliele dia di santa ragione...$B$BEntra nelle Rovine di Alterac e cerca i Guerrafondai Crushridge. Voglio che tu ne abbatta un buon numero — è l'unico modo perché quei bruti imparino a stare lontani dal territorio dell'Alleanza.",
  obj = "Uccidi 15 Crushridge Warmonger, poi torna da Marshal Redpath, a Southshore.",
  progress = "Hai altri Guerrafondai da uccidere, $N. Dovresti essere su in montagna a svolgere il tuo compito, non quaggiù con l'arma riposta.",
  reward = "Molto bene. Ecco la tua ricompensa.$B$BE mentre davi la caccia a quei Guerrafondai, com'era la città di Alterac? Sarà in cattive condizioni, immagino. Gli ogre non sono noti per la loro pulizia.$B$BPer fortuna, i tuoi sforzi aiuteranno a tenerli lontani da Southshore.",
  en_title = "Crushridge Warmongers",
  en_obj = "Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.",
}
T[505] = {
  title = "Gli Assassini del Syndicate",
  desc = "Sono il nuovo magistrato di Southshore, nominato di recente dopo l'assassinio del magistrato precedente. Gli assassini non sono mai stati trovati, ma grazie alle nostre indagini siamo quasi certi che siano stati assoldati dal Syndicate — una banda di ladri guidata da nobili malvagi dell'ormai caduto regno di Alterac.$B$BIl Syndicate ha un accampamento a nord di Tarren Mill, in mano all'Orda, e i nostri ultimi indizi portavano a quell'accampamento. Uccidi i membri del Syndicate che trovi laggiù.",
  obj = "Uccidi 12 Syndicate Footpad e 8 Syndicate Thief, poi torna da Magistrate Henry Maleb, a Southshore.",
  progress = "Hai eliminato quei delinquenti del Syndicate, vero?",
  reward = "Grazie, $N. Anche se forse sono ancora in giro, speriamo che alcuni dei ladri e dei briganti che hai ucciso fossero i responsabili della morte dell'ultimo magistrato. Ma anche se non lo fossero, il Syndicate porta corruzione in questa terra ed è una macchia sulla razza umana.$B$BA Southshore la loro morte è la benvenuta.",
  en_title = "Syndicate Assassins",
  en_obj = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.",
}
T[506] = {
  title = "L'Eredità di Blackmoore",
  desc = "Un giorno o due fa ho ricevuto la visita del capo di questo Syndicate. Si chiama Aliden Perenolde e si proclama signore di queste terre. Mi ha confidato il suo piano: prendere come schiavi gli orchi che gli si oppongono, proprio come avevano progettato suo padre e il suo mentore, l'odiato Blackmoore.$B$BPiù importante ancora: si è portato dietro la sua amante, una ragazzina esile di nome Elysa. Al collo aveva il pendaglio che il Capoguerra desidera.$B$BOra va', io me la caverò da solo, dopo aver sistemato le mie faccende qui.",
  obj = "Porta a Krusk, a Tarren Mill, le informazioni raccolte da Gol'dir.",
  reward = "Che sfacciataggine, questi umani arroganti! Mostreremo loro che gli orchi non si piegheranno mai al loro volere!$B$BOra questa sarà la nostra missione, oltre a recuperare il monile che il Capoguerra desidera. Sembra che portando a termine l'una porteremo a termine anche l'altra.",
  en_title = "Blackmoore's Legacy",
  en_obj = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.",
}
T[507] = {
  title = "Ser Aliden Perenolde",
  desc = "È chiaro che Perenolde va ucciso e che il mondo va liberato dalla sua sozzura. Il suo maniero si trova un bel pezzo a nord di qui, sulle rive del Lago Lordamere. Fa' il tuo dovere, $N, poi recupera il pendaglio che il Capoguerra desidera e torna qui.",
  obj = "Uccidi Lord Aliden Perenolde e chiedi alla sua amante, Elysa, del pendaglio di Taretha.",
  progress = "C-cosa vuoi?",
  reward = "No, no, ti prego, non farmi del male! Non ho mai voluto fare del male alla tua gente, mi ha tenuta qui contro la mia volontà! Ti prego... risparmiami!",
  en_title = "Lord Aliden Perenolde",
  en_obj = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.",
}
T[508] = {
  title = "Il Dono di Taretha",
  desc = "Il pendaglio? Certo che puoi averlo... Prendilo! Non voglio più niente che me lo ricordi... ti prego, ti prego, vattene in pace...",
  obj = "Porta il pendaglio di Taretha a Krusk, a Tarren Mill.",
  progress = "Sei $Gtornato:tornata;, $N. Hai buone notizie?",
  reward = "È strano che il Capoguerra si spenda tanto per una cosa così piccola. Non pretendo di capirlo, ma lo seguirò, qualunque cosa ordini. Hai fatto bene, $N, e di sicuro il Capoguerra sarà contento di sapere del tuo successo.",
  en_title = "Taretha's Gift",
  en_obj = "Return Taretha's pendant to Krusk in Tarren Mill.",
}
T[509] = {
  title = "Elisir dell'Agonia",
  desc = "Un altro giorno, un altro elisir da preparare. Se dipendesse da me, lascerei che i patetici umani e il Flagello se la sbrigassero tra loro. Sembrano già decisi ad ammazzarsi a vicenda.$B$BPurtroppo la nostra Signora Oscura vuole accelerare un pochino il processo, e allora perché non passare queste giornate tetre spargendo un po' di morte e di malattia per queste terre?$B$BEcco il piano, $N: va' alla Cascina dei Nethander, a sud di Tarren Mill e a est del fiume e di Southshore. Raccogli per me 6 Fiori di Mudsnout nel campo, per il mio prossimo elisir.",
  obj = "Porta 6 Mudsnout Blossom ad Apothecary Lydon, a Tarren Mill.",
  progress = "Hai avuto fortuna alla Cascina dei Nethander?",
  reward = "Ah, l'orribile tanfo dei Fiori di Mudsnout. Almeno quei luridi Gnoll servono a qualcosa.",
  en_title = "Elixir of Agony",
  en_obj = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.",
}
T[510] = {
  title = "Piani Futuri",
  desc = "Tra questi documenti c'è una lista di rifornimenti richiesti. Comprende oggetti comuni (cibo, armi, vestiti) e attrezzatura più insolita (maschere, olio, veleno).$B$BMa a colpire di più è l'urgenza della richiesta — questi rifornimenti servivano a breve per portare a termine quella che nel documento viene descritta come una \"missione importante contro Southshore.\"",
  obj = "Porta i Foreboding Plans a Magistrate Maleb, a Southshore.",
  progress = "$N, sembri in ansia. C'è qualcosa che vuoi dirmi?",
  reward = "<Maleb legge i documenti.>$B$BSono molto preoccupanti, $N. Dalle informazioni di questi documenti, e dalle azioni passate del Syndicate, dobbiamo presumere che quella banda di tagliagole abbia dichiarato guerra a Southshore.",
  en_title = "Foreboding Plans",
  en_obj = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.",
}
T[511] = {
  title = "Lettera Codificata",
  desc = "Una delle lettere su questo tavolo è cifrata e indecifrabile.",
  obj = "Porta la Cleverly Encrypted Letter a Loremaster Dibbs, a Southshore.",
  progress = "Sì, $Gsignore:signora;? Hai bisogno di me per qualcosa?",
  reward = "Che cos'è? Aspetta un momento... fammi dare un'occhiata più da vicino.$B$B...$B$BHm, non ho mai visto questo tipo di cifratura, ma devo ammettere che le mie conoscenze in quel campo non sono affatto complete.",
  en_title = "Encrypted Letter",
  en_obj = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.",
}
T[512] = {
  title = "Morti Nobili",
  desc = "Temo che i capi del Syndicate vogliano la rovina di Southshore. Dobbiamo colpire duramente questi capi prima che i loro piani si realizzino.$B$BEntra nelle rovine di Strahnbrad, nelle Alterac Mountains a nord. Pensiamo che il Syndicate usi la zona come quartier generale.$B$BSappiamo che questa banda di tagliagole è guidata da ex nobili di Alterac. Potrebbero nascondersi fingendosi normali agenti del Syndicate, ma capirai di aver ucciso un nobile dall'anello con sigillo che porta.$B$BPortami quegli anelli con sigillo.",
  obj = "Porta 7 Alterac Signet Ring a Magistrate Maleb, a Southshore.",
  progress = "Hai dato la caccia al Syndicate? Hai quegli anelli?",
  reward = "Privare il Syndicate dei suoi nobili gli toglierà la capacità di agire con decisione, e lo ridurrà a nient'altro che una banda di delinquenti.$B$BServi bene la tua Alleanza, $N.",
  en_title = "Noble Deaths",
  en_obj = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.",
}
T[513] = {
  title = "Elisir dell'Agonia",
  desc = "Proprio quando pensavo che sarebbe passato un altro giorno senza un briciolo di gioia, mi hai portato quei magnifici Fiori di Mudsnout.$B$BPrima li ridurrò in un bel composto. Poi ci servirà che il Maestro Speziale Faranell, nell'Undercity, ci applichi sopra il suo colloide di decomposizione, e allora sì che ci divertiremo davvero!$B$BTieni, prendi questo Composto di Mudsnout e portalo di corsa al Maestro Faranell, $N.",
  obj = "Porta il Mudsnout Composite a Master Apothecary Faranell, nell'Undercity.",
  progress = "Non vedi che sono occupato, $C? La Signora Oscura pretende una nuova piaga prima che l'avanzata del Flagello da Northrend ci travolga. E con la minaccia umana che incalza da sud, il tempo diventa la mia merce più preziosa. Spero per te che sia importante!",
  reward = "Ti manda lo Speziale Lydon? Ah, potevi dirlo subito!$B$BNonostante il carattere tetro, lo Speziale Lydon è uno dei nostri membri più devoti e capaci.$B$BQuel brav'uomo ci manda del Composto di Mudsnout! Adesso ho capito cosa sta combinando il nostro amico a Hillsbrad. E il suo modo di ragionare mi piace. La Signora Oscura sarebbe assai colpita dai progressi che sta facendo verso la nuova piaga.",
  en_title = "Elixir of Agony",
  en_obj = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.",
}
T[514] = {
  title = "Lettera per Stormpike",
  desc = "Ho un collega a Ironforge che forse può aiutare a decifrare questa lettera. Va' alla biblioteca nella Sala degli Esploratori, a Ironforge, e parla con il Prospettore Stormpike. Digli che ti mando io e mostragli la lettera. Se a nord della Blackrock Spire c'è qualcuno in grado di leggerla, è lui.",
  obj = "Porta la Cleverly Encrypted Letter a Prospector Stormpike, a Ironforge.",
  progress = "Ti ha mandato Dibbs, da Southshore? Come se la passa quel vecchio topo di biblioteca?",
  reward = "Ah, una cifratura! Una mia specialità. Vediamo un po'...",
  en_title = "Letter to Stormpike",
  en_obj = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.",
}
T[515] = {
  title = "Elisir dell'Agonia",
  desc = "Un composto di mudsnout? Assolutamente geniale! Come mai non ci ho pensato io?$B$BLascia che aggiunga il mio colloide di decomposizione a questo intruglio diabolico.$B$BPer attivare gli agenti contaminanti di questa miscela di mudsnout, a Lydon serviranno una pozione forte di sangue di troll, e poi scaglie di daggerspine e occhi di torn fin dalla costa meridionale di Hillsbrad. Saprà lui cosa fare, una volta che gli avrai portato tutti i reagenti. E, oh, quanto sono impaziente di sapere come andrà il suo esperimento!",
  obj = "Porta la Mudsnout Mixture, una Strong Troll's Blood Potion, 5 Daggerspine Scale e 5 Torn Fin Eye ad Apothecary Lydon, a Tarren Mill.",
  progress = "Che piacere rivederti, $N. Mi stavo annoiando terribilmente. Non una sola cosa divertente da fare, a parte avvelenare e infettare Umpi e poi rianimarla... ancora e ancora e ancora.$B$BCom'è andato il viaggio all'Undercity? Hai avuto la fortuna di massacrare qualche umano lungo la strada?",
  reward = "L'emozione di questo esperimento mi fa girare la testa! Mi sei $Gstato:stata; di grande aiuto, $N. Insieme spargeremo morte e malattia su questa terra!",
  en_title = "Elixir of Agony",
  en_obj = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.",
}
T[516] = {
  title = "La Grotta di Beren",
  desc = "Mi sono arrivati rapporti su un gruppo di non morti che si sta asserragliando per preparare un attacco contro di noi. Forti di questa informazione, possiamo ribaltare la situazione e attaccarli per primi, stroncando sul nascere il loro piccolo piano.$B$BPurtroppo le mie informazioni sono frammentarie, a dir poco. Pare che si nascondano in un luogo noto come Grotta di Beren. La posizione esatta non si conosce, ma sembra si tratti di un antro fra le colline, vicino a una sacca di maghi di Dalaran.$B$BConfido nella tua intraprendenza. Trovali e annientali.",
  obj = "Individua la Grotta di Beren, poi uccidi 6 Ravenclaw Drudger e 6 Ravenclaw Guardian, e torna da Shadow Priest Allister, al Sepulcher.",
  progress = "Hai già individuato la loro base, $N? Il tempo stringe!",
  reward = "Se i nostri esploratori e i nostri agenti continueranno a procurarci informazioni preziose come questa, ripuliremo le nostre terre dal Flagello del Re dei Lich in men che non si dica.",
  en_title = "Beren's Peril",
  en_obj = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",
}
T[517] = {
  title = "Elisir dell'Agonia",
  desc = "Questo nuovo elisir è finalmente pronto per la prova. Ma perché sprecare una piaga tanto buona e tanto contagiosa su una semplice rana o su un cane? Divertiamoci sul serio, nel nome di Lady Sylvanas.$B$BScendi a Dun Garok. Sai, la caserma dove sgattaiolano quei sudici nanetti. Rubami un barile della loro Shindigger Stout. Quando avrò quel barile, tu e io faremo una gran festa, $N.",
  obj = "Porta un Keg of Shindigger Stout ad Apothecary Lydon, a Tarren Mill.",
  progress = "Certe volte mi annoio talmente qui a Tarren Mill che mi metto ad aprire il barattolo di formaldeide e lascio che il delizioso aroma si spanda nell'aria. Però Umpi si innervosisce un po'.$B$BAllora, sei $Griuscito:riuscita; a procurarti un barile dai Nani? Giuro che se devo fissare questo elisir letale un altro giorno senza usarlo su qualcuno mi metto a urlare.",
  reward = "Finalmente! Ora siamo pronti all'azione!",
  en_title = "Elixir of Agony",
  en_obj = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.",
}
T[518] = {
  title = "La Corona della Volontà",
  desc = "Mug'Thol e i suoi ogre Crushridge hanno invaso le rovine di Alterac. Sarà difficile infliggergli una punizione seria senza prima sfoltire il numero degli ogre.$B$BDopo averli indeboliti, procederemo.$B$BChiaro? Bene. Ora va'.",
  obj = "Uccidi 14 Crushridge Mauler per Melisara, a Tarren Mill.",
  progress = "Noto che il tuo compito non è finito, $N. Devo informare Sharlindra della tua incompetenza?",
  reward = "Il sangue degli ogre fa fiorire di rosso la neve, ma non possiamo fermarci finché lo spirito e il numero dei Crushridge non saranno stati schiacciati e pestati nella terra e nella neve.",
  en_title = "The Crown of Will",
  en_obj = "Kill 10 Crushridge Maulers for Melisara in Tarren Mill.",
}
T[519] = {
  title = "La Corona della Volontà",
  desc = "Targ, Muckrake e Glommus sono i luogotenenti di Mug'Thol. Gli sono fedeli, anche se chissà cosa spinge un ogre alla fedeltà.$B$BPortami le loro teste, $N, e poi non resterà che staccare la testa di Mug'Thol, corona compresa.",
  obj = "Uccidi Targ, Muckrake e Glommus e porta le loro teste a Melisara, a Tarren Mill.",
  progress = "Voglio le loro teste, $N, non scuse.",
  reward = "...e io che pensavo che gli ogre puzzassero già abbastanza.$B$BQuando mi porterai la testa di Mug'Thol, le farò infilzare tutte e quattro su delle picche sopra Alterac. Un monumento adatto a chi va contro la volontà della Signora Oscura.",
  en_title = "The Crown of Will",
  en_obj = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.",
}
T[520] = {
  title = "La Corona della Volontà",
  desc = "Ora che i luogotenenti di Mug'Thol sono morti, non resta che uccidere Mug'Thol e recuperare la Corona della Volontà. Non ho dubbi che non vorrà separarsene. Probabilmente ti starà anche aspettando, vista la... dipartita... dei suoi compagni.$B$BTrova Mug'Thol e portami la sua testa e la Corona. La resistenza dei Crushridge sarà finita.",
  obj = "Uccidi Mug'Thol e riporta la sua testa con la Crown of Will a Melisara, a Tarren Mill.",
  progress = "Tre teste le ho, me ne serve una quarta. Sarà quella di Mug'Thol, o sarà la tua, $N. Te lo prometto.",
  reward = "Hai fatto bene il tuo dovere, $N. La testa di Mug'Thol ornerà la vetta più alta delle rovine di Alterac, e la Guardiamorte spazzerà sottoterra quel che resta dei Crushridge.",
  en_title = "The Crown of Will",
  en_obj = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.",
}
T[521] = {
  title = "La Corona della Volontà",
  desc = "Non resta che consegnare la Corona della Volontà a Sharlindra, nell'Undercity. Farà in modo che venga consegnata a Lady Sylvanas. Ti sconsiglio di pensare di usarla per i tuoi scopi, $N: la sorte di Mug'Thol dovrebbe bastare come esempio.",
  obj = "Consegna la Crown of Will a Sharlindra, nell'Undercity.",
  progress = "Sì? Hai qualcosa da riferire?",
  reward = "Dunque è questa la reliquia che l'ogre usava per sottrarsi alla volontà della Signora Oscura...$B$BStrano che una cosa così semplice possa avere un potere tanto grande. E finire in mani così goffe. Ben fatto, $N: consegnerò la corona a Lady Sylvanas, e farò in modo che venga a sapere della tua impresa.",
  en_title = "The Crown of Will",
  en_obj = "Deliver the Crown of Will to Sharlindra in the Undercity.",
}
T[522] = {
  title = "Contratto dell'Assassino",
  desc = "Questo è un contratto per l'assassinio del Magistrato Henry Maleb. È stato chiuso con ceralacca rossa e timbrato con un anello con sigillo inconfondibile.",
  obj = "Porta l'Assassin's Contract a Magistrate Maleb, a Southshore.",
  progress = "Sei senza fiato! Hai qualcosa da riferire?",
  reward = "<Maleb esamina il contratto.>$B$BQuesto spiega l'ultimo attacco a Southshore. Il Syndicate deve volere la mia testa, proprio come voleva quella del magistrato precedente!",
  en_title = "Assassin's Contract",
  en_obj = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.",
}
T[523] = {
  title = "La Fine del Barone",
  desc = "Il contratto che hai recuperato è firmato dal Barone Vardus, un nobile dell'ex regno di Alterac, noto per il suo cuore di ghiaccio e i suoi metodi brutali. Non mi sorprende che dietro a tutto questo ci fosse uno come il Barone.$B$BTrova quest'uomo. Trovalo, e consegnalo alla giustizia. Deve trovarsi in uno dei covi del Syndicate — forse tra le rovine di Strahnbrad, o forse nella valle a nord delle rovine.",
  obj = "Porta l'Head of Baron Vardus a Magistrate Maleb, a Southshore.",
  progress = "Il Barone Vardus non può pensare che Southshore gli permetta di mandarci contro i suoi delinquenti impunemente. Voglio la sua testa!",
  reward = "Grazie, $N. La mia testa riposa un po' più tranquilla, sapendo che quel furfante ha perso la sua.",
  en_title = "Baron's Demise",
  en_obj = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.",
}
T[524] = {
  title = "Elisir dell'Agonia",
  desc = "Qui accanto i Guardiamorte tengono in ostaggio alcuni contadini catturati. La Gran Esecutrice Darthalia sospettava che tra loro si nascondesse uno degli strateghi militari di Stormwind. A quanto pare il tizio è stato trovato morto nelle Plaguelands ieri notte. Darthalia, che ha sempre un occhio di riguardo per me, ha deciso di lasciare i prigionieri a mia disposizione.$B$BCredo sia ora di dare una bella festa a quei contadini. Sarà uno spasso!$B$BPosa questo barile infetto sul tappeto nella loro stanza. Birra appestata per tutti!",
  obj = "Posa il Tainted Keg sul tappeto, per i contadini prigionieri.",
  progress = "Dal tappeto sale un odore di muffa.",
  reward = "Posi il barile infetto sul tappeto polveroso.",
  en_title = "Elixir of Agony",
  en_obj = "Place the Tainted Keg on the rug for the captured farmers.",
}
T[525] = {
  title = "Altri Misteri",
  desc = "Ho decifrato la lettera, ma non so cosa pensarne. L'hai trovata tra dei ladri, sulle colline ai piedi delle montagne di Alterac? Molto strano...$B$BDovresti portarla al magistrato di Southshore. Anche se questa lettera è criptica, la sua è la città più vicina ad Alterac; se si sta preparando una minaccia, dovrebbe saperlo.",
  obj = "Porta la Decrypted Letter a Magistrate Maleb, a Southshore.",
  progress = "$N. Sei $Gandato:andata; di nuovo in giro per colline e montagne? Che notizie porti?",
  reward = "<Maleb legge la lettera.>$B$BQuesta è la traduzione di una lettera che hai trovato in un accampamento del Syndicate? Non l'ha scritta un ladro, e nemmeno un nobile di Alterac.$B$BSembra che il Syndicate abbia legami con un'altra potenza, e rabbrividisco al pensiero di quale possa essere.",
  en_title = "Further Mysteries",
  en_obj = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.",
}
T[526] = {
  title = "Lingotti Lightforge",
  desc = "In quella cassa avrai anche trovato un lingotto lightforge, ma non basta per forgiare niente di decente!$B$BDovresti tornare là e cercarne altri. Magari i murloc intorno a quel relitto ne hanno qualcuno addosso.",
  obj = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.",
  progress = "L'hai trovato il ferro lightforge che ti serve?",
  reward = "Ah, li hai trovati! E adesso battiamo questo ferro lightforge fino a farne qualcosa di utile, eh?",
  en_title = "Lightforge Ingots",
  en_obj = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[527] = {
  title = "La Battaglia di Hillsbrad",
  desc = "Sull'attenti quando ti rivolgi a me, $C.$B$BSono sotto il comando diretto di Varimathras. Dobbiamo reprimere l'infestazione umana finché i nostri speziali non avranno sviluppato la nuova piaga.$B$BSecondo le nostre informazioni, la città di Hillsbrad è vulnerabile a un attacco. Il tuo primo incarico ha lo scopo di sabotare i loro rifornimenti di cibo e le loro infrastrutture.$B$BVa' a ovest. Saccheggia le fattorie più a nord dei Campi di Hillsbrad. Assicurati che vengano giustiziati anche i proprietari, il Contadino Ray e il Contadino Getz.",
  obj = "Uccidi 6 Hillsbrad Farmhand, 6 Hillsbrad Farmer, Farmer Ray e Farmer Getz, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "In qualità di Gran Esecutrice di Tarren Mill, sotto il comando diretto di Varimathras e della Signora Oscura, sei $Gtenuto:tenuta; a obbedire ai miei ordini.$B$BForse prendi questa guerra con l'Alleanza alla leggera? Se è così dovrei decapitarti qui e ora. Altrimenti va' a ovest, alla città di Hillsbrad, e da' battaglia agli umani, come ti è stato ordinato.$B$BPuoi andare.",
  reward = "Riposo, $C. Vedo che sei $Gtornato:tornata; dalla battaglia. Le mie fonti riferiscono che ti sei $Gbattuto:battuta; bene sul fronte di Hillsbrad.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.",
}
T[528] = {
  title = "La Battaglia di Hillsbrad",
  desc = "La notizia dell'attacco alle fattorie del nord ha gettato la gente del posto nel panico. Ottimo.$B$BI nostri Inseguitori della Morte riferiscono che i contadini fuggono verso i campi nel sud di Hillsbrad. Gli sciocchi credono di potersi nascondere nei frutteti e sfuggire alla loro fine.$B$BDimostra che si sbagliano, $N. Torna ai Campi di Hillsbrad e stana quei contadini tremanti. Sterminali in nome della nostra Signora Oscura.$B$BPuoi andare!",
  obj = "Uccidi 15 Hillsbrad Peasant, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Hai i tuoi ordini, $C. Smettila di gingillarti qui a Tarren Mill quando c'è del lavoro da fare altrove.",
  reward = "La morsa della morte si stringe intorno alla città di Hillsbrad. La battaglia procede bene.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.",
}
T[529] = {
  title = "La Battaglia di Hillsbrad",
  desc = "Gli umani di Hillsbrad oppongono una resistenza inattesa. A quanto pare, il problema è che il fabbro del paese sta armando la popolazione. Dobbiamo tagliare tutte le linee di rifornimento.$B$BLa tua missione sarà giustiziare il Fabbro Verringtan. Uccidi anche i suoi apprendisti. Già che ci sei, porta via dalle loro scorte un carico di ferro. I rifornimenti ci torneranno utili quando avremo finito di conquistare Hillsbrad e cominceremo a radere al suolo Southshore.",
  obj = "Uccidi Blacksmith Verringtan e 4 Hillsbrad Apprentice Blacksmith.$B$BRecupera un carico di ferro e torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a eseguire gli ordini, $C? Ti sei $Gsbarazzato:sbarazzata; di Verringtan e dei suoi aiutanti? E dov'è quel carico di ferro?",
  reward = "Missione compiuta, $C. E portata a termine con grande abilità, aggiungerei.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.$B$BRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.",
}
T[532] = {
  title = "La Battaglia di Hillsbrad",
  desc = "La città di Hillsbrad è allo sbando e crediamo che cadrà presto. Dobbiamo però continuare a essere spietati finché la feccia umana non sarà spazzata via da queste colline per sempre.$B$BNonostante le perdite enormi, gli umani fanno quadrato intorno a chi li guida e continuano a combattere. Dobbiamo eliminare il loro capo, il Magistrato Burnside, e con lui il consiglio cittadino. Distruggi anche il loro venerato documento politico, il Proclama di Hillsbrad. E già che ci sei, ruba il registro della città.",
  obj = "Uccidi Magistrate Burnside e 5 Hillsbrad Councilman. Distruggi l'Hillsbrad Proclamation. Ruba l'Hillsbrad Town Registry. Poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Che notizie porti?",
  reward = "La voce delle tue gloriose imprese a Hillsbrad si è sparsa in fretta. Hai fatto un buon lavoro, $C.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.",
}
T[533] = {
  title = "Infiltrazione",
  desc = "Finalmente cominciamo a sentire voci e dicerie e a trovare prove di dove si trovi Gol'dir. Gli umani lo spostano di continuo, ma stiamo restringendo il campo e ci concentriamo sul grande accampamento del Syndicate appena a nord di qui.$B$BVacci, $N, e riporta tutte le informazioni su cui riesci a mettere le mani.",
  obj = "Recupera informazioni su dove si trovi Gol'dir per Krusk, a Tarren Mill.",
  progress = "Hai trovato qualcosa? Temo che le speranze per Gol'dir si riducano di giorno in giorno...",
  reward = "Finalmente sappiamo dove tengono Gol'dir. L'accampamento in questione non è lontano da qui, e speriamo che non siano preparati come la prima volta, quando ci hanno catturati.",
  en_title = "Infiltration",
  en_obj = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.",
}
T[535] = {
  title = "Valik",
  desc = "Urrgh... Ferito, morente e davanti al nemico.$B$BSenza dubbio mi ucciderai comunque, ma se mi porti un po' di birra scura di Southshore — quelli come te bevono, vero? — ti dirò quello che vuoi sapere.",
  obj = "Porta un boccale di Southshore Stout a Valik, nell'accampamento del Syndicate.",
  progress = "Mi hai portato qualcosa da bere o sei solo $Gtornato:tornata; a finire il lavoro?",
  reward = "Vista la mia morte imminente, credo di poter dire tranquillamente che questa è la cosa più dolce che abbia mai assaggiato... Ecco, prendi questo, da morto non mi servirà a niente.$B$BBe', avanti, fallo!",
  en_title = "Valik",
  en_obj = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.",
}
T[536] = {
  title = "Giù Lungo la Costa",
  desc = "Trasferito dalla guardia cittadina di Stormwind a Southshore, una città che a vederla dovrebbe essere abbandonata... Puzza di porto giorno e notte.$B$BPer non parlare del vecchio Redpath... Vuole che mi occupi dei murloc. Ah!$B$BRiesco a malapena a trovare la forza di spingermi fino a qualche branco di quei pesci troppo cresciuti giù lungo la Riva Occidentale. Se ci andassi tu al posto mio e te ne occupassi, te ne sarei riconoscente.",
  obj = "Uccidi 10 Torn Fin Tidehunter e 10 Torn Fin Oracle per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Un'altra birra, per favore, l'ultima sembra essere sparita!$B$BPer la Luce, quanto devo restare ancora bloccato qui?$B$BOh, sei tu, $N. Li hai già uccisi quei murloc?",
  reward = "Spero che basti a convincere Redpath che ho — ah! — eseguito i suoi ordini e liberato Southshore dalla terribile e orribile minaccia dei temutissimi murloc! Perché non può esserci male peggiore delle devastazioni dei pesci troppo cresciuti!",
  en_title = "Down the Coast",
  en_obj = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.",
}
T[537] = {
  title = "Il Consiglio Oscuro",
  desc = "La lettera che mi hai portato è stata scritta da un essere che si fa chiamare Nagaz, un membro dell'Argus Wake. Non so cosa sia questo Argus Wake, ma se hanno stretto un'alleanza con il Syndicate, devono essere una minaccia.$B$BVoglio che tu trovi Nagaz e i Maghi dell'Ombra di Argus nominati in quella lettera. Voglio che tu li trovi, e li uccida.$B$BCerca nelle Uplands, dove il Syndicate è più forte. Le Uplands sono a nord di Strahnbrad.$B$BCon un po' di fortuna, troverai lì questi emissari dell'Argus Wake.",
  obj = "Uccidi 4 Argus Shadow Mage.$B$BPorta l'Head of Nagaz a Magistrate Maleb, a Southshore.",
  progress = "Hai trovato gli emissari dell'Argus Wake?",
  reward = "Ben fatto, $N. L'Argus Wake non sembra un gruppo che vorremmo alla guida del Syndicate.$B$BE anche se qui hai distrutto il loro capo, Nagaz era solo il servitore di qualcun altro. L'Argus Wake potrebbe avere radici profonde in tutto il continente di Azeroth.$B$BO perfino nel mondo intero.",
  en_title = "Dark Council",
  en_obj = "Kill 4 Argus Shadow Mages.$B$BBring the Head of Nagaz to Magistrate Maleb in Southshore.",
}
T[538] = {
  title = "Southshore",
  desc = "$N. Se non ti dispiace fare un lungo viaggio, ho un compito per te: aiutare di nuovo Stormwind a riempire la sua biblioteca.$B$BIl vecchio regno di Alterac, caduto dopo la grande guerra, possedeva una grande raccolta di libri. È una tragedia che la città sia in rovina, ma è ancora più tragico che tutto il suo sapere sia andato perduto! Dobbiamo recuperare quel che possiamo.$B$BSouthshore è il paese più vicino alle Rovine d'Alterac. Va' là e parla con l'Erudito Dibbs. Saprà indicarti la strada per le rovine e dirti quali libri potresti trovarci.",
  obj = "Parla con Loremaster Dibbs, a Southshore.",
  reward = "Ah sì, mi ricordo di Milton. Un topo di biblioteca, non c'è dubbio. Benedett'uomo.$B$BE ha ragione. Le Rovine d'Alterac custodiscono ancora un patrimonio di sapere che rischia di andare perduto!$B$BOra ad Alterac vivono gli ogre, e a loro della cultura importa ben poco.",
  en_title = "Southshore",
  en_obj = "Speak with Loremaster Dibbs in Southshore.",
}
T[539] = {
  title = "La Battaglia di Hillsbrad",
  desc = "Il Registro della Città di Hillsbrad indica che la Miniera di Azureload è sotto il controllo dell'Alleanza. Non solo: la miniera è una delle principali fonti di minerale di ferro per le armerie dell'Alleanza.$B$BAnche se abbiamo inferto un colpo decisivo alla città di Hillsbrad, l'Alleanza continua a sostenere e a proteggere con accanimento la Miniera di Azureload.$B$BLa miniera si trova proprio a sud di Hillsbrad. Va' là e uccidi il caposquadra, un umano di nome Bonds. Uccidi anche i suoi minatori. Così l'Alleanza riceverà un messaggio chiaro.",
  obj = "Uccidi Foreman Bonds e 10 Hillsbrad Miner, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Ti sono stati dati ordini precisi: attaccare la Miniera di Azureload. Spero per te che i motivi per cui bighelloni a Tarren Mill siano buoni, o ti decapiterò per tradimento.",
  reward = "La Signora Oscura sarà contenta quando saprà di avere una nuova miniera con cui armare i suoi soldati.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.",
}
T[540] = {
  title = "Preservare il Sapere",
  desc = "Quegli ogre bestiali ora abitano tra le rovine di Alterac, e rabbrividisco al pensiero di cosa stiano facendo dei preziosi libri rimasti là. Devi recuperare quel che puoi!$B$BEntra nelle Rovine d'Alterac e cerca i tomi saccheggiati dagli ogre. Prendi tutto quel che riesci a trovare e portamelo, ma cerca anche un libro in particolare: Il Braccio di Gri'lek. Contiene antiche tradizioni dei troll che devo studiare, e le Rovine d'Alterac sono l'ultimo luogo noto in cui se ne trovasse una copia intatta.",
  obj = "Porta 5 Recovered Tome e il Worn Leather Book che contiene Il Braccio di Gri'lek a Loremaster Dibbs, a Southshore.",
  progress = "Vorrei poter cercare anch'io tra le rovine, ma temo che queste vecchie ossa non mi reggerebbero nella salita su per le montagne. Comunque, come procede la tua caccia al sapere, $N?",
  reward = "Oh, li hai trovati! Splendido! Devo cominciare subito a studiare il Braccio di Gri'lek!",
  en_title = "Preserving Knowledge",
  en_obj = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.",
}
T[541] = {
  title = "La Battaglia di Hillsbrad",
  desc = "I nani aiutano gli umani? Maledetti quei piccoli esseri immondi.$B$BMetteremo alla prova la forza della cosiddetta Alleanza. Vedremo quanta voglia hanno quegli spacca-caviglie di aiutare gli umani, una volta assaggiata la nostra ira. Sappiamo esattamente dov'è la loro roccaforte in questo territorio.$B$BHanno messo su una caserma nell'Hillsbrad sud-orientale, lungo il Muro di Thoradin: si chiama Dun Garok. L'ultima missione di questa battaglia è assediare Dun Garok, $C. Il Capitano Ironhill, il loro capo, deve morire.",
  obj = "Va' a Dun Garok, uccidi 10 Dun Garok Mountaineer, 8 Dun Garok Rifleman, 4 Dun Garok Priest e Captain Ironhill, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Dun Garok è un ostacolo troppo grande per te, $C? E io che pensavo ti fossi $Gdistinto:distinta; valorosamente a Hillsbrad.$B$BSe non sei all'altezza della missione che ti è stata assegnata, ne troverò un altro capace di ottenere risultati migliori. Quanto a te, be', sono certa che alla Signora Oscura servano sempre altri becchini nelle Tirisfal Glades.",
  reward = "Le tue azioni sul campo di battaglia meritano i più alti elogi.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.",
}
T[542] = {
  title = "Ritorno da Milton",
  desc = "Mi serve un po' di tempo per studiare il libro che mi hai portato, il Braccio di Gri'lek, anche se sono sicuro che Milton non veda l'ora di aggiungere gli altri libri recuperati alla collezione di Stormwind.$B$BEccoti i libri che hai raccolto nelle Rovine d'Alterac, impacchettati e catalogati. Riportali a Milton Sheaf, a Stormwind, e sono sicuro che te ne sarà grato.",
  obj = "Porta i Tomes of Alterac a Milton Sheaf, a Stormwind.",
  progress = "$N, sei $Gtornato:tornata;! Com'è andata la tua incursione ad Alterac? Hai riportato qualcosa?",
  reward = "Perbacco! Ma guarda qui! Non posso credere che siano sopravvissuti alla rovina di Alterac. E a tutti quegli ogre!$B$BGrazie, $N. Grazie di cuore! Hai contribuito a preservare il sapere degli umani, e accresci la grandezza della Biblioteca Reale di Stormwind.",
  en_title = "Return to Milton",
  en_obj = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.",
}
T[543] = {
  title = "Il Diadema di Perenolde",
  desc = "Il Diadema di Perenolde è un antico cimelio dei \"nobili\" Perenolde — la famiglia che regnava su Alterac prima che quel regno cadesse in rovina. Si dice che sia stato realizzato da mastri gioiellieri di Ironforge e incastonato con gli smeraldi più pregiati.$B$BQuando Alterac fu distrutta il Diadema andò perduto, ma corre voce che un Mago Ogre, Grel'borg l'Avaro, l'abbia trovato e ora vaghi per le Rovine d'Alterac in cerca di altri tesori.$B$BVorremmo che lo recuperassi per noi.",
  obj = "Porta la Perenolde Tiara a Remington Ridgewell, a Stormwind.",
  progress = "Salve, $N. Cerca di non calpestarmi i risvolti dei pantaloni. Questo completo è appena stato fatto su misura.",
  reward = "Ah, è splendido. Andrà pulito, naturalmente, ma ti sei davvero $Gsuperato:superata;, $N. Farò preparare il diadema perché venga sistemato al più presto nella nostra collezione.$B$BConverrai, ne sono certo, che la nostra gratitudine è grande quanto la nostra collezione.",
  en_title = "The Perenolde Tiara",
  en_obj = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.",
}
T[544] = {
  title = "Irruzione in Prigione",
  desc = "Sono venuto a Tarren Mill per fare ricerche, ma adesso devo risolvere una crisi. Vedi, quattro Reietti sono fuggiti dall'Undercity qualche mese fa. Hanno voltato le spalle ai loro fratelli, ma, cosa ancora peggiore... hanno derubato la Signora Oscura.$B$BQuesti ladri sono entrati in una cripta sorvegliata e hanno rubato quattro manufatti, oggetti che servivano ai nostri speziali per certi studi. Sylvanas vuole indietro quei manufatti.$B$BI ladri sono fuggiti dall'Undercity a Dalaran, e quei maghi li hanno messi in quarantena nel Campo di Internamento di Lordamere.",
  obj = "Trova i traditori e recupera i loro manufatti, poi torna da Magus Voidglare, a Tarren Mill.",
  progress = "Hai trovato i ladri? E, cosa più importante, hai trovato quel che hanno rubato?",
  reward = "Hai reso un grande servizio ai Reietti, $N. Questi manufatti ci sono mancati molto.$B$BEd è un piacere sapere che Kegan e gli altri traditori hanno avuto ciò che meritavano.",
  en_title = "Prison Break In",
  en_obj = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.",
}
T[545] = {
  title = "Le Pattuglie di Dalaran",
  desc = "I maghi di Dalaran hanno costruito una vasta cupola magica intorno al cuore della loro città. C'è chi crede fosse per proteggersi dalle violenze di questi tempi, e chi dice che volessero solo la solitudine, per studiare e tramare.$B$BA me non importa quale fosse il motivo. Mi importa invece che le periferie in rovina della loro città, fuori dalla cupola, possano nascondere preziosi tesori magici.$B$BMa la zona è pattugliata dai maghi e dai loro schiavi elementali.$B$BQuindi dagli la caccia, e torna quando il loro numero sarà ridotto a sufficienza.",
  obj = "Uccidi 6 Dalaran Summoner e 12 Elemental Slave, poi torna da Magus Voidglare, a Tarren Mill.",
  progress = "Hai già diradato le pattuglie di Dalaran intorno alle loro rovine?",
  reward = "Molto bene. Quelle rovine adesso dovrebbero essere abbastanza sicure da esplorare, se si sta attenti.$B$BGrazie, $N.",
  en_title = "Dalaran Patrols",
  en_obj = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.",
}
T[546] = {
  title = "Souvenir di Morte",
  desc = "Ho sentito che Darthalia ti ha arruolato per far guerra agli umani di Hillsbrad. Che invidia...$B$BMentre tu te ne vai in giro a divertirti — ammazzare umani, saccheggiare la città, terrorizzare gente innocente — io sono costretto a stare di guardia qui a Tarren Mill.$B$BMagari avrai pietà di un vecchio Guardiamorte come me? Vedi, io colleziono teschi umani. E tu combatterai contro gli umani ancora per un bel po'. Nel corso della tua lunga battaglia portamene 30, e farò in modo che ne valga la pena.",
  obj = "Deathguard Samsa, a Tarren Mill, vuole 30 Hillsbrad Human Skull.",
  progress = "Allora, torna $Gil fortunato:la fortunata; $N? Quanti umani hai massacrato oggi? Centinaia, spero!$B$BHai qualche teschio per me?",
  reward = "Teschi preziosi! Che meraviglia! Ti devo quel che ho promesso, $N!",
  en_title = "Souvenirs of Death",
  en_obj = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.",
}
T[547] = {
  title = "La Spada di Humbert",
  desc = "La Gran Esecutrice Darthalia mi ha mandato a sorvegliare Dun Garok da lontano. Mi ero accampato appena fuori vista. Ma la mattina, quando ho dovuto far bollire l'acqua, mi sono allontanato a raccogliere legna.$B$BQuando sono tornato al campo, la mia roba era sparita.$B$BA quanto pare erano passati di lì degli esploratori nani di Dun Garok e se l'erano portata via. Mi serve la mia spada! Se riesci a riprendermela te ne sarei molto riconoscente. Ci sono così tanti nani là... sarà piuttosto difficile trovare lo sporco ladruncolo che l'ha rubata.",
  obj = "Recupera la spada di Deathguard Humbert a Dun Garok e riportagliela a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a recuperare la mia spada, $N? La Gran Esecutrice Darthalia mi impiccherà alle travi, se scopre la mia leggerezza.",
  reward = "L'hai trovata!$B$BAh, mi sento di nuovo intero con la mia preziosa spada in mano. Grazie mille!",
  en_title = "Humbert's Sword",
  en_obj = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.",
}
T[549] = {
  title = "RICERCATI: Personale del Syndicate",
  desc = "Per ordine di Lady Sylvanas, tutti i membri dell'organizzazione nota come Syndicate sono ricercati, e li si vuole morti. Chi verrà preso in custodia o catturato sarà giustiziato sommariamente. Risulta che al momento si stiano radunando tra le rovine del Forte Durnholde, a sud-est di Tarren Mill.$B$BChiunque porterà la prova delle proprie imprese alla Gran Esecutrice Darthalia riceverà una lauta ricompensa.",
  obj = "Uccidi 10 Syndicate Rogue e 10 Syndicate Watchman. Torna da High Executor Darthalia, a Tarren Mill, per la ricompensa.",
  progress = "Non hai niente di meglio da fare che startene qui davanti a me, $C? In qualità di Gran Esecutrice ho faccende più urgenti che fissare il tuo volto in putrefazione.",
  reward = "Eccellente, $C. Di questo passo la peste del Syndicate sarà spazzata via da questa terra in men che non si dica.",
  en_title = "WANTED: Syndicate Personnel",
  en_obj = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.",
}
T[550] = {
  title = "La Battaglia di Hillsbrad",
  desc = "Poiché hai combattuto con tanto valore e tanta tenacia nella battaglia di Hillsbrad, ho scritto questo encomio, in cui esalto le tue prodezze in combattimento perché l'alto comando ne prenda atto.$B$BPorta questo encomio sigillato a Varimathras, nell'Undercity. Va' con orgoglio, $C.",
  obj = "Porta Darthalia's Sealed Commendation a Varimathras, nell'Undercity.",
  progress = "Cosa porta $Gun:una; $C fin nell'Undercity dal campo di battaglia?",
  reward = "Quindi sei tu $Gil famigerato:la famigerata; $C che ha inferto un colpo tanto decisivo alle forze dell'Alleanza nelle Hillsbrad Foothills? La voce delle tue gloriose imprese è arrivata in fretta all'Undercity.$B$BHai un bel futuro nei ranghi della Signora Oscura, se continui a mostrare questa capacità di comando e questa perizia in battaglia.$B$BAnche se la nostra minaccia principale è l'esercito del Flagello del Re dei Lich che scende da nord, il \"problema\" umano continua a intralciare i nostri piani di battaglia. Tu però hai dimostrato che gli umani possono cadere, e cadranno.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.",
}
T[551] = {
  title = "La Cartapecora Stregata",
  desc = "Su questa pergamena c'è un incantesimo che la rende indecifrabile. Ma una parola in cima al foglio si può leggere:$B$B$B      Nagaz",
  obj = "Porta l'Ensorcelled Parchment a Loremaster Dibbs, a Southshore.",
  progress = "Oh. Hai qualcosa che vorresti farmi vedere? Qualche frammento di sapere raccolto su in montagna, spero...",
  reward = "Altri appunti cifrati?$B$BVorrei avere il talento per decifrare tutti gli strani scritti che arrivano giù da Alterac. Ma temo di non avere le conoscenze necessarie.",
  en_title = "The Ensorcelled Parchment",
  en_obj = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.",
}
T[552] = {
  title = "La Vendetta di Helcular",
  desc = "Il Maestro Helcular aveva quasi completato la sua trasformazione in Lich quando un gruppo di umani inferociti scoprì la sua tana rituale sulle colline e lo uccise brutalmente. Come se non bastasse, ne seppellirono il cadavere nel cimitero di Southshore.$B$BUna simile mancanza di rispetto per il grande mago è inaccettabile. Come suo apprendista, farò in modo che la pioggia della vendetta si abbatta sulla città di Southshore.$B$BPrima ci servirà la Bacchetta di Helcular. Gli Yeti hanno invaso la sua tana rituale. Senza dubbio ce l'ha una di quelle bestie.",
  obj = "Recupera Helcular's Rod dagli Yeti e riportala a Novice Thaivand, a Tarren Mill.",
  progress = "Hai già recuperato la Bacchetta di Helcular? Ci sono così tanti Yeti in questa regione che sarà molto difficile trovarla. Ma dobbiamo averla per andare avanti.",
  reward = "L'hai trovata! Ottimo, $N!",
  en_title = "Helcular's Revenge",
  en_obj = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.",
}
T[553] = {
  title = "La Vendetta di Helcular",
  desc = "Tieni, prendi la Verga di Helcular. Ti servirà.$B$BHelcular preparò 3 pire cerimoniali come parte del suo incantesimo più potente. La Fiamma di Azel e la Fiamma di Veraz si trovano nell'Antro del Contrafforte. La Fiamma di Uzel si trova in una grotta sopra le caverne, più a nord tra le montagne.$B$BLa Verga di Helcular va caricata con ognuna delle tre fiamme. Una volta completato il rituale, conficca la verga nella tomba di Helcular a Southshore, la cittadina umana a sud, piena di guardie. La vendetta sarà nostra!",
  obj = "Carica la Rod of Helcular con i poteri della Flame of Azel, della Flame of Veraz e della Flame of Uzel.$B$BConficca la verga carica in Helcular's Grave, a Southshore.",
  progress = "La tomba di Helcular brulica di un'energia mistica.",
  reward = "Dal terreno sale un gran rombo.",
  en_title = "Helcular's Revenge",
  en_obj = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.$B$BDrive the charged rod into Helcular's grave in Southshore.",
}
T[554] = {
  title = "La Decifrazione di Stormpike",
  desc = "Il Prospettore Stormpike è un maestro della decrittazione e della decifrazione. Se gli porti la pergamena che hai trovato, con un po' di fortuna riuscirà a darle un senso. Stormpike al momento sta studiando nel quartier generale dei Prospettori, a Ironforge.$B$BE quando lo vedi digli che hai parlato con me — ultimamente gli sto mandando parecchio lavoro.",
  obj = "Porta l'Ensorcelled Parchment a Prospector Stormpike, a Ironforge.",
  progress = "Altre interruzioni?$B$BAh, questa pergamena è coperta da un incantesimo molto intricato, tessuto con finezza. Posso districarlo, naturalmente, ma ci vorrà tempo. E il tempo per me è molto prezioso...$B$BForse te la compro e basta?",
  reward = "Una decisione saggia. Non credo che esista un altro studioso oltre a me con le capacità per tradurre questa pergamena. E se il suo contenuto si rivelerà interessante, non temere. Ti manderò a chiamare.",
  en_title = "Stormpike's Deciphering",
  en_obj = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.",
}
T[555] = {
  title = "Zuppa Cremosa di Tartaruga",
  desc = "Se c'è una cosa che imparerai di Southshore, è che qui abbiamo una delle cucine migliori a nord di Stormwind!$B$BPrendi per esempio la mia ricetta segreta della Zuppa di Tartaruga. Ho visto gente venire perfino da Darkshire solo per gustarsene una scodella. A proposito, ultimamente non riesco più a prepararla. Prima salivo io stesso oltre Dalaran, fino al Lago Lordamere, a cacciare le Tartarabbia, ma adesso è troppo pericoloso. Se mi porti un po' di Carne di Tartaruga dalle Tartarabbia a nord e delle Spezie Esotiche, te la preparo in un attimo!",
  obj = "Porta 10 Turtle Meat e delle Soothing Spices a Chef Jessen, a Southshore.",
  progress = "Hai avuto fortuna con gli ingredienti? Te lo dico io, questo territorio non è più il posto tranquillo di una volta. Ah, se solo non ci fossero mai stati questi disordini...",
  reward = "Saranno tutti contenti: la Zuppa Cremosa di Tartaruga dello Chef Jessen torna in tavola!",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.",
}
T[556] = {
  title = "Emblemi di Pietra",
  desc = "I maghi di Dalaran hanno un talento notevole: la dimestichezza con gli elementali, creature potenti che vengono da altre dimensioni. I maghi usano emblemi magici per controllare questi elementali. Magus Voidglare vorrebbe studiarne qualcuno.$B$BEntra nei territori dei maghi di Dalaran, a ovest di Hillsbrad, e raccogli gli emblemi.$B$BPuoi trovarli addosso a qualunque cittadino di Dalaran, ma ti consiglio di andare a caccia al campo di internamento. È più sicuro di Dalaran stessa.",
  obj = "Porta 10 Worn Stone Token a Keeper Bel'varil, a Tarren Mill.",
  progress = "Hai gli Emblemi di Pietra Consunti, $N? Il Magus non vede l'ora di svelarne i segreti.",
  reward = "Questi andranno benissimo. Anche se la loro magia sembra svanita, è meglio che i primi esperimenti del Magus si facciano su esemplari inerti come questi.$B$BGrazie, $N.",
  en_title = "Stone Tokens",
  en_obj = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.",
}
T[557] = {
  title = "Bracciali del Vincolo",
  desc = "Il Magus sarà impegnato a studiare gli emblemi di pietra che hai raccolto, ma so che prima o poi vorrà anche degli esemplari della loro controparte: i bracciali del vincolo. Vengono stretti ai polsi degli elementali veri e propri e li legano al servizio del mago.$B$BDa' la caccia agli elementali tra le rovine di Dalaran e raccogli i loro Bracciali Vincolanti di Terra, e il Magus ne sarà contento.",
  obj = "Porta 4 Bracers of Earth Binding a Keeper Bel'varil, a Tarren Mill.",
  progress = "Salve, $N. Gli elementali sono una preda difficile, ma so che sei all'altezza del compito. Hai quei bracciali del vincolo?",
  reward = "Li hai trovati. Immagino che gli elementali a cui li hai tolti fossero d'accordo?$B$BHm... la morte non mi ha solo fermato il cuore, a quanto pare mi ha anche tolto il senso dei tempi comici.$B$BBe', grazie, $N. Servi bene il Magus, e quindi la Signora Oscura.",
  en_title = "Bracers of Binding",
  en_obj = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.",
}
T[558] = {
  title = "Autografo di Jaina",
  desc = "Dicono che Lady Jaina Proudmoore, a Theramore, sia una delle più grandi eroine che l'Alleanza abbia mai avuto. Da grande voglio essere un eroe dell'Alleanza anch'io!$B$BConosci Jaina, $N? Mi faresti un favore, per piacere? Potresti procurarmi il suo autografo? Non so come chiederglielo, e probabilmente sarebbe troppo occupata per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lei! Scommetto che a te l'autografo lo darebbe subito!$B$BPer piacere?",
  obj = "Raggiungi Theramore e cerca di ottenere l'autografo di Lady Jaina Proudmoore per il tuo protetto.",
  progress = "Un giorno voglio essere un eroe proprio come Jaina... be', un eroe maschio, cioè.",
  reward = "WOW! Mi hai procurato l'autografo di Lady Jaina! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stata fantastica, e magari un giorno la ringrazierò di persona... quando diventerò un eroe dell'Alleanza!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.",
  en_title = "Jaina's Autograph",
  en_obj = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.",
}
T[559] = {
  title = "La Prova di Farren",
  desc = "Ci credi, $N? A Redpath non sono bastati tutti i murloc che abbiamo ucciso — oh, su, non fare $Gil modesto:la modesta;, anche tu ci hai messo del tuo. Adesso vuole che gli porti le prove delle uccisioni, e mi tocca mozzare teste di murloc fredde e viscide da sottoporre alla sua approvazione.",
  obj = "Raccogli 10 Murloc Head dai murloc di Western Strand per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Le hai prese quelle teste per me, $N?",
  reward = "Oh, per l'Amor della Luce... stanno gocciolando per terra.$B$BIo quelle cose non sopporto di toccarle. Il pesce va benissimo, ma quando mette le gambe e comincia a camminare... Non mangio pesce da settimane, credimi, e a Southshore questo vuol dire non mangiare granché.",
  en_title = "Farren's Proof",
  en_obj = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.",
}
T[560] = {
  title = "La Prova di Farren",
  desc = "Sai, $N, preferirei proprio non prendere queste teste... Visto che ormai le hai in mano tu, ti spiacerebbe consegnarle a Redpath per me?",
  obj = "Consegna il Sack of Murloc Heads a Marshal Redpath, a Southshore.",
  progress = "Salve, $Gcittadino:cittadina;. Sei $Gvenuto:venuta; a prestare il tuo braccio alla difesa di Southshore?",
  reward = "Sei $Gil galoppino:la galoppina; di Farren, eh?$B$BSe hai aiutato Farren a procurarsi queste teste, allora grazie. Per restare al sicuro, Southshore ha bisogno di gente che lavori sodo e non si risparmi.",
  en_title = "Farren's Proof",
  en_obj = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.",
}
T[561] = {
  title = "La Prova di Farren",
  desc = "Per favore, fa' sapere al Tenente Orinelle che vorrei che concentrasse i suoi sforzi sui naga che infestano la Riva Orientale. Quando avrà dei risultati, digli di venire a farmi rapporto di persona.",
  obj = "Parla con Lieutenant Farren Orinelle, a Southshore.",
  reward = "I naga, eh? Redpath deve aver appena ricevuto le mie stesse informazioni... Ah! Non sarà lui a prendersi una promozione grazie alla mia fatica. Lascia che ti spieghi.",
  en_title = "Farren's Proof",
  en_obj = "Speak with Lieutenant Farren Orinelle in Southshore.",
}
T[562] = {
  title = "Verso Stormwind!",
  desc = "Il mio vecchio mentore nella guardia cittadina di Stormwind mi ha mandato un messaggio: l'alto comando dell'Alleanza comincia a preoccuparsi per la minaccia dei naga. Da quel che ha sentito, ci sono buone possibilità di promozione — o almeno di trasferimento — per chi si dimostra utile su questo fronte.$B$BC'è solo un piccolo problema... Con i naga non ce la faccio, $N. Oh, certo, saprei sedare una rissa da taverna o portare via un mendicante molesto, ma i naga sono troppo per me. Devi aiutarmi, $N!",
  obj = "Uccidi 10 Daggerspine Shorehunter e 10 Daggerspine Siren per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Ho una lettera pronta da mandare al Maggiore Samuelson, a Stormwind. Mi servono solo i risultati.",
  reward = "Con i naga sconfitti a Southshore, il trasferimento è praticamente mio. Rivedrò Stormwind... via da questo porto dimenticato dalla Luce.",
  en_title = "Stormwind Ho!",
  en_obj = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.",
}
T[563] = {
  title = "Trasferimento",
  desc = "Non dovrebbe essere un problema far leggere il mio rapporto. Il nuovo capitano della guardia, il Maggiore Samuelson, era il mio mentore quando ero di stanza a Stormwind. Dovrebbe bastargli e avanzare come scusa per farmi trasferire di nuovo in città. Ho bisogno però che gli porti tu il mio rapporto... non vorrei che il vecchio Redpath se ne accorgesse.",
  obj = "Consegna Farren's Report a Major Samuelson, al Mastio di Stormwind.",
  progress = "Salve, $Gcittadino:cittadina;. La guardia cittadina di Stormwind può esserti utile?",
  reward = "Cos'è questo? Ah... così il mio attento allievo si è dedicato al problema dei naga a Southshore. Grazie di avermelo portato, ne terrò senz'altro conto quando rivedrò le assegnazioni del personale il mese prossimo.",
  en_title = "Reassignment",
  en_obj = "Deliver Farren's report to Major Samuelson in Stormwind Keep.",
}
T[564] = {
  title = "Una Minaccia Costosa",
  desc = "Non c'è niente che mi dà più sui nervi che perdere 'sti bei cavalli. E credimi, ne abbiamo persi un bel po', tra quelle pesti di non morti, quella dannata banda del Syndicate e tutti gli altri buoni a niente che ficcano il naso da 'ste parti.$B$BMa giuro sulla tomba del mio vecchio nonno che per i nostri cavalli non c'è minaccia peggiore di quei Puma lassù ad Alterac. Sempre giù dalle colline a complicarmi la vita!$B$BTi credi $Gun eroe:un'eroina;? E allora va' a fare qualcosa!",
  obj = "Darren Malvew, a Southshore, vuole che tu uccida 8 Mountain Lion e 10 Hulking Mountain Lion.",
  progress = "I Puma ci ammazzano i cavalli a destra e a manca e tu te ne stai qui a chiacchierare del tempo e compagnia bella.$B$BDovrei proprio andarmi a cercare $Gun eroe vero:un'eroina vera;. Più ammazzare e meno parlare.",
  reward = "Questa sì che è una bella notizia! Avrei dovuto trovarmi $Gun eroe di guerra coi fiocchi:un'eroina di guerra coi fiocchi; fin dal primo giorno, per sistemare quelle bestiacce. Il tuo papà sarebbe stato fiero di te, $N.",
  en_title = "Costly Menace",
  en_obj = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.",
}
T[565] = {
  title = "Il Mantello di Pelliccia di Yeti di Bartolo",
  desc = "Io, il grande Bartolo, ti confezionerò il Mantello di Pelliccia di Yeti famoso in tutto il mondo e rinomato in tutta l'Alleanza!$B$BGira il mondo e trovati un mantello migliore, ti sfido. Oh, aspetta, cosa dici, $Gpiccolo:piccola; $R? \"Bartolo, non c'è mantello più bello!\" Sì, sì! Questo l'ho già sentito.$B$BA Bartolo servono un Rotolo di Woolen Cloth, un Mantello di Collealto fatto da un abile conciatore, del Filo Pregiato e della Pelliccia di Yeti, naturalmente! Portami queste cose e sarai $Gun cliente soddisfatto:una cliente soddisfatta;!",
  obj = "Porta a Bartolo Ginsetti, a Southshore, un Bolt of Woolen Cloth, un Hillman's Cloak, del Fine Thread e 10 ciuffi di Yeti Fur.",
  progress = "Allora sei $Gtornato:tornata; dal grande Bartolo. Forse hai finito di raccogliere i materiali per il tuo Mantello di Pelliccia di Yeti? O magari ti piace soltanto crogiolarti nella grandezza di me, Bartolo!",
  reward = "Ora tocca al grande Bartolo fare le sue magie! Non mi serve il bastone di un mago né la verga di un incantatore. Perché io, il grande Bartolo, faccio magie con un semplice ago e un filo!",
  en_title = "Bartolo's Yeti Fur Cloak",
  en_obj = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.",
}
T[566] = {
  title = "RICERCATO: Barone Vardus",
  desc = "Per ordine della Gran Esecutrice Darthalia, l'umano noto come Barone Vardus è ricercato per crimini contro i Reietti. Vardus è noto come membro di alto rango dell'organizzazione chiamata Syndicate.$B$BÈ stato avvistato l'ultima volta nelle Uplands, nelle Alterac Mountains, a nord di Tarren Mill.$B$BLo si vuole morto. Porta la prova della sua morte alla Gran Esecutrice Darthalia per riscuotere la ricompensa.",
  obj = "Uccidi Baron Vardus e consegna la sua testa a High Executor Darthalia, a Tarren Mill.",
  progress = "Ah, $N. Forse sei $Gvenuto:venuta; a riscuotere la taglia sulla testa del Barone Vardus?",
  reward = "Un lavoro produttivo il tuo, $N. Con il Barone Vardus morto, il numero dei capi del Syndicate diminuisce. La loro resistenza e il loro fastidio avranno vita breve.",
  en_title = "WANTED: Baron Vardus",
  en_obj = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.",
}
T[567] = {
  title = "Pericolosi!",
  desc = "Pericolosi!$B$BI seguenti umani di Hillsbrad sono stati giudicati pericolosi e la Gran Esecutrice Darthalia ha messo una taglia sulla loro testa:$B$BCancelliere Horrace Whitesteed. Ricercato per l'omicidio del Guardiamorte Toma.$B$BCittadino Wilkes. Ricercato per l'omicidio dello Speziale Eli.$B$BMinatore Hackett. Ricercato per l'omicidio dell'Inseguitore della Morte Fry.$B$BContadina Kalaba. Ricercata per l'imboscata ai rifornimenti provenienti dall'Undercity.$B$BSi nascondono tutti e sarà difficile trovarli. Chi porterà notizia della loro morte riceverà una ricompensa.",
  obj = "High Executor Darthalia, a Tarren Mill, offre una taglia su Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett e Farmer Kalaba.",
  progress = "Sì?",
  reward = "Sei $Gun bel cacciatore:una bella cacciatrice; di taglie, $C. Ben fatto.",
  en_title = "Dangerous!",
  en_obj = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",
}
T[568] = {
  title = "La Difesa di Grom'gol",
  desc = "Throm'ka, $C!$B$BArrivi a Grom'gol proprio al momento giusto. Come comandante del campo base del Capoguerra qui nella giungla, l'onore mi impone di garantire la sicurezza di tutti i membri dell'Orda. La nostra missione di mantenere sicura la via dei rifornimenti per Stonard è ostacolata da alcuni degli abitanti del posto.$B$BTi affido il compito di sfoltire la popolazione di raptor fuori da Grom'gol. Quando avrai fatto progressi significativi, torna a fare rapporto da me per un nuovo incarico.",
  obj = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 15 Lashtail Raptor.",
  progress = "I nostri rifornimenti sono ancora ostacolati dai raptor del posto, $C.",
  reward = "Hai compiuto il tuo dovere con onore, $C.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.",
}
T[569] = {
  title = "La Difesa di Grom'gol",
  desc = "Quando siamo arrivati in questa giungla non avevamo intenzione di fare guerra alle tribù del posto. La nostra missione di rifornire Stonard ha la massima priorità. Ma sono sorte delle complicazioni. Una banda di ogre del posto ha occupato le Rovine di Mizjah, a sud-est di Grom'gol. Nonostante gli avvertimenti, continuano a tendere agguati alle nostre carovane di rifornimenti.$B$BTi affido il compito di occuparti di questi ogre poco collaborativi.$B$BVa' alle rovine e cerca di cacciarli dalla zona. Se non altro, sarà un messaggio chiaro.",
  obj = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 10 Mosh'Ogg Brute e 5 Mosh'Ogg Witch Doctor.",
  progress = "Hai fatto progressi con gli ogre delle Rovine di Mizjah, $C?",
  reward = "Ben fatto. Hai servito il Capoguerra con onore.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.",
}
T[570] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Il potere della magia della giungla va compreso e poi imbrigliato dall'Orda. Finora i miei rituali hanno avuto successo. Posso lanciare incantamenti molto potenti. Per te, $Gvaloroso:valorosa; $C, creerò un oggetto davvero speciale.$B$BPortami degli artigli di Pantera Shadowmaw e una zanna di Tigressa. Non va bene una zanna qualsiasi. Deve essere in condizioni perfette.$B$BLe bestie si aggirano in tutta la giungla, ma ne troverai alcune qui vicino, appena oltre il fiume, di fronte alle Rovine di Mizjah, a sud-est.",
  obj = "Far Seer Mok'thardin, al campo base di Grom'gol, vuole 8 Shadowmaw Claw e una Pristine Tigress Fang.",
  progress = "Che notizie porti?",
  reward = "La tua conoscenza della giungla è grande, $N. Questi esemplari saranno perfetti. Ringrazierò gli spiriti per aver sacrificato bestie così belle alla causa dell'Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.",
}
T[571] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Quello che mi serve adesso sarà molto difficile da procurare.$B$BPer tenere insieme tutte queste piume, gli artigli e la zanna perfetta, mi serve un legame magico. Va bene solo un tendine di gorilla anziano.$B$BPotrai trovarlo soltanto su un Gorilla Anziano di Mistvale. Si sa che vanno in cerca di cibo a est di Booty Bay.$B$BIl tendine deve essere perfetto. Potresti doverne uccidere parecchi prima di trovare esattamente quello che mi serve, ma la caccia ne varrà la pena.",
  obj = "Porta un Aged Gorilla Sinew a Far Seer Mok'thardin, a Grom'gol.",
  progress = "La fortuna è stata dalla tua parte, $N? Sei $Griuscito:riuscita; a procurarti un tendine di gorilla anziano?",
  reward = "Un tendine davvero perfetto, $N. I tuoi sforzi saranno presto ripagati.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.",
}
T[572] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Le cose che hai raccolto dalle bestie feline della Vale sono solo il primo requisito per un potente oggetto incantato. Questi ninnoli della giungla, uniti al mio rituale sciamanico, ti daranno uno strumento molto utile per aiutare l'Orda e il Capoguerra.$B$BMa ora devi raccogliere per me delle Penne d'Inseguitore della Giungla. Per tradizione, le bestie portano le piume sulle fasce che hanno al braccio. Troverai una tribù di questi raptor proprio a sud di Grom'gol, non lontano dalla grande arena.",
  obj = "Porta 10 Jungle Stalker Feather a Far Seer Mok'thardin, al campo base di Grom'gol.",
  progress = "La tua raccolta ha dato frutti?",
  reward = "Eccellente. Le preparerò subito.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.",
}
T[573] = {
  title = "L'Incantamento di Mok'thardin",
  desc = "Manca solo un ultimo reagente per completare l'incantamento.$B$BA sud, verso la costa occidentale, in alto sopra le scogliere, si trova una Sorgente Sacra. Questa sorgente è oggetto di grande contesa tra studiosi di religione e di misticismo. Ogni razza di Azeroth sostiene che le acque della sorgente siano state rese divine per il proprio popolo.$B$BL'ultima cosa che ti chiedo: portami dell'Acqua Sorgiva Sacra. Ma fa' attenzione. Una spedizione di esploratori naga è avanzata fino alla sorgente. Dovrai occuparti anche di loro.",
  obj = "Far Seer Mok'thardin, di Grom'gol, ha bisogno di Holy Spring Water. Vuole anche che tu uccida 10 Naga Explorer.",
  progress = "Sono quasi pronto a completare l'incantamento. Hai fatto quanto ti ho chiesto?",
  reward = "Con questa Acqua Sorgiva Sacra il girocollo cerimoniale è pronto per l'incantamento.$B$BPortalo con orgoglio, $N, in nome del Capoguerra e in difesa della possente Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.",
}
T[574] = {
  title = "Forze Speciali",
  desc = "Ora che molte delle sue truppe regolari sono state decimate, devi affrontare le sue forze meglio addestrate. Quando non sono nelle terre selvagge a massacrare i nostri soldati ribelli, si trovano in fondo all'Insediamento di Kurzen, in una caverna che chiamano il Deposito.$B$BConosco di persona molti soldati di Kurzen, e so che sono abili, leali e crudeli. Non è un compito facile quello che ti affido, $N.$B$BDopo averli sconfitti, fai rapporto al Tenente Doren, il mio ufficiale superiore. Vorrà sentire il resoconto direttamente da te.",
  obj = "Uccidi 10 Kurzen Commando e 6 Kurzen Headshrinker.$B$BFai rapporto a Lieutenant Doren, al Rebel Camp.",
  progress = "La Sergente Yohwa mi dice che sei abile e $Gcoraggioso:coraggiosa;, $C. Hai qualcosa da riferire?",
  reward = "$N. La Sergente Yohwa si fidava delle tue capacità, e io mi fido di lei. La sconfitta che hai inflitto alle forze di Kurzen è quasi più di quanto osassimo sperare. Temevo che noi ribelli fossimo soli, e da soli non avremmo mai potuto tenere testa alla genialità del Colonnello.$B$BForse c'è ancora speranza di sopravvivere.",
  en_title = "Special Forces",
  en_obj = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.$B$BReport to Lieutenant Doren at the Rebel Camp.",
}
T[575] = {
  title = "Domanda e Offerta",
  desc = "\"Il miglior pellettiere dei South Seas e dei mondi vecchi e nuovi.\" È così che mi chiamano. Io! Drizzlik! Il miglior pellet... Ehm. Bene.$B$BI miei articoli in pelle sono noti in lungo e in largo come i più raffinati, la scelta degli intenditori!$B$BHo appena ricevuto un ordine dal Direttore Riddlevox della Tinkers' Union per una dozzina dei suoi stivali preferiti della linea Excelsior. I nostri più venduti, a dire il vero.$B$BPer cominciare con la forma di base, mi servono pelli di crocolisco, prese dai crocolischi lungo il fiume, nel nord di Stranglethorn.",
  obj = "Porta 2 Large River Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "La mia attrezzatura è pronta, $N, mi servono solo quelle pelli. Non vogliamo far aspettare Riddlevox, questo è certo.$B$BNon è una buona idea, per nessuno, lasciare insoddisfatto il capo inventore della Tinkers' Union.",
  reward = "Queste pelli dovrebbero andare. La loro qualità non conta troppo, visto che formeranno lo strato interno degli stivali, ma è comunque importante che siano comode.$B$BSe sono un po' troppo rigide, userò del sangue di tigre per ammorbidirle. Trucchi del mestiere, sai?",
  en_title = "Supply and Demand",
  en_obj = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.",
}
T[576] = {
  title = "Apri l'Occhio",
  desc = "Alt! Chi va là?$B$BArgh, senza il mio speciale occhio incantato non servo a niente. Già era abbastanza brutto aver perso gli occhi in battaglia! Ma per un colpo di fortuna abbiamo attraccato a Menethil, e un mago girovago ha incantato uno speciale occhio di vetro che mi ha fatto tornare a vedere.$B$BIeri notte, mentre uscivo, mi sono fatto assalire da un gruppo di Bloodsail Buccaneers. Mi hanno preso l'occhio, sì! Pare che quei tizi siano arrivati fino a Booty Bay.$B$BAiuti un vecchio lupo di mare a riavere il suo occhio?",
  obj = "Dizzy One-Eye, a Booty Bay, vuole che tu recuperi il suo occhio dai Bloodsail Buccaneers.",
  progress = "Ahoy, $Gragazzo mio:ragazza mia;! Forse non ci vedo, ma ti sento l'odore da un capo all'altro del porto.$B$BMi servirebbe proprio il mio occhio. Il capitano mi farà passare sotto la chiglia quando scoprirà che la mia pupilla è nelle mani di quegli sporchi Bloodsail Buccaneers.$B$BA cosa serve una vedetta che non ci vede? La coffa era la mia casa... senza i miei fanali, se mi va bene, mi toccherà strofinare la sentina.",
  reward = "Corpo di mille balene e balene di mille corpi! Hai trovato il mio bell'occhio! Vediamo se entra ancora.$B$B$N in vista! Perbacco, ci vedo!!",
  en_title = "Keep An Eye Out",
  en_obj = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.",
}
T[577] = {
  title = "Montaggio Richiesto",
  desc = "Be', ho messo a punto la forma di base degli stivali, e stanno venendo bene, ma le pelli che mi hai portato non basteranno per gli strati interni.$B$B\"Cosa facciamo, Drizzlik?\" È senz'altro la domanda che hai sulle labbra, e be', che fortuna che tu stia parlando con Drizzlik, perché ora ti dirà lui cosa faremo!$B$BGli strati interni non si vedranno mai davvero, quindi prenderemo delle pelli più spesse ed economiche dai crocolischi intorno al Lago Nazferiti per imbottire gli stivali.",
  obj = "Porta 5 Snapjaw Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "Stivali di cuoio Excelsior di Drizzlik, lavorazione finissima, stivali al cento per cento in pelle di crocolisco d'acqua salata di alta qualità. Non ce n'è di migliori!$B$BDifficile battere una descrizione così entusiasta, vero?$B$BA meno che, forse, tu non abbia quelle pelli per me?",
  reward = "I miei stivali... sono come le salsicce, $N. Bell'aspetto, ottimo sapore. Ti dico che sono pieni solo degli ingredienti e delle carni migliori, e tu li mangi, e ti piacciono.$B$BÈ più sicuro — e più piacevole — se ti fidi di me e non indaghi troppo su cosa c'è davvero dentro.",
  en_title = "Some Assembly Required",
  en_obj = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.",
}
T[578] = {
  title = "La Pietra delle Maree",
  desc = "Se sull'isola ci sono davvero un mago goblin e degli elementali dell'acqua, potrebbe significare che la Pietra delle Maree può essere mia!$B$BVoglio che tu trovi quest'isola infestata... e scopra cosa sta succedendo. Ah, e se per caso vuoi saperne di più sulla Pietra delle Maree, porta questo biglietto alla Biblioteca di Stormwind: dovrebbero riuscire a trovarti una copia del libro in cui ho letto per la prima volta la leggenda.$B$BPossibile che Gazban abbia davvero scoperto la Pietra...?",
  obj = "Trova l'isola infestata per Baron Revilgaz, a Booty Bay.",
  progress = "I troll possedevano davvero oggetti magici straordinari, $N. E ora, forse, ho l'occasione di aggiungerne uno alla mia vasta collezione. Hai scoperto da dove viene la voce?",
  reward = "Allora le storie erano vere! Incredibile!$B$BPerò dovremo trovare un modo per vincere la maledizione della Pietra delle Maree, se vogliamo recuperarla. La maledizione è una faccenda magica: ci servirà l'aiuto di uno di quei maghi.",
  en_title = "The Stone of the Tides",
  en_obj = "Find the haunted island for Baron Revilgaz in Booty Bay.",
}
T[580] = {
  title = "Il Grog Perduto di Whiskey Slim",
  desc = "Stavamo brindando a più non posso al largo delle Scogliere del Belvedere, con le vecchie Hinterlands appena in lontananza. Pensavo che il mare ci inghiottiva tutti interi.$B$BIl vecchio Slim sa tutto sul coraggio in bottiglia! Il capitano aveva una cassa di Porto Pupellyverbos che avevamo requisito a un corsaro diretto a Stormwind.$B$BCosì, quando è arrivata quella tempesta al largo delle Hinterlands, mi sono buttato sul grog. Un'onda grossa ci ha colpiti e ha fatto volare fuori bordo quelle bottiglie. Il capitano mi farà assaggiare il gatto a nove code, se non mi aiuti a riprenderle!",
  obj = "Whiskey Slim, a Booty Bay, vuole che tu gli porti le bottiglie di Pupellyverbos Port che ha perso.",
  progress = "Che mi venga un colpo! Sto quasi finendo l'alcol! Il capitano leverà l'ancora e il vecchio Slim resterà a secco come il Tanaris Desert. E quando scoprirà che manca il suo porto... accidenti!",
  reward = "Corpo di mille balene! Hai trovato il grog del capitano!$B$BTi devo un grosso favore, $Gamico:amica;.$B$BPare che fuori si stia preparando una tempesta. Forse mi terrò al caldo con una di queste bottiglie mentre aspettiamo che passi...",
  en_title = "Whiskey Slim's Lost Grog",
  en_obj = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.",
}
T[581] = {
  title = "Alla Ricerca di Yenniku",
  desc = "Una sventura, c'è. Una sventura sul figlio più giovane del mio capo, Yenniku. Come vuole un'usanza del nostro popolo, fu affidato ai Troll Gurubashi di Zul'Gurub, ma dopo che la mia tribù, la tribù Darkspear, se ne andò con l'orco Thrall, il povero Yenniku per noi fu perduto. Dalla lontana Orgrimmar mi hanno rimandato a Stranglethorn a cercare il figlio del mio capo.$B$BE credo che sia nelle mani della tribù Bloodscalp.$B$BSe vuoi aiutarmi, dai la caccia ai Bloodscalp. Li trovi a nord. Raccogli le loro zanne e torna da me.",
  obj = "Porta 9 Bloodscalp Tusk a Nimboya, al Grom'gol Base Camp.",
  progress = "$C. Mostrami che la tribù Bloodscalp è diventata tua preda.$B$BMostrami i tuoi trofei.",
  reward = "Sono buone zanne, $N. Dimostri di avere la forza per dare la caccia ai Bloodscalp.$B$BE questo è un bene, perché non hai ancora finito di cacciarli.",
  en_title = "Hunt for Yenniku",
  en_obj = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.",
}
T[582] = {
  title = "A Caccia di Teste",
  desc = "Dobbiamo scoprire se Yenniku è morto.$B$BUccidi i Cacciatori di Teste Bloodscalp e prendi i loro Teschi Rimpiccioliti. Devi raccogliere molte, molte teste, e io le esaminerò per assicurarmi che tra queste non ci sia quella di Yenniku.$B$BE se Yenniku è stato ucciso dai Bloodscalp, che una maledizione di 600 anni si abbatta sullo spirito del loro capo, Gan'zulah!$B$BVa', $N. Troverai molti Cacciatori di Teste presso le rovine di Zuuldaia e Zul'Kunda, lungo la costa a nord.",
  obj = "Porta 20 Shrunken Head a Nimboya, al Grom'gol Base Camp.",
  progress = "$N. Temo per il figlio del nostro capo. Hai le teste rimpicciolite da farmi esaminare?",
  reward = "Grazie, $N. Esaminerò queste teste per assicurarmi che il povero Yenniku sia stato risparmiato dall'ascia del cacciatore di teste.",
  en_title = "Headhunting",
  en_obj = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.",
}
T[583] = {
  title = "Benvenuti nella Giungla",
  desc = "$GBenvenuto:Benvenuta; a Stranglethorn!$B$BForse non lo sai, ma quel nano laggiù è l'unico e inimitabile Hemet Nesingwary, famoso eroe di guerra dell'Alleanza e maestro della caccia grossa. Non è tipo da accogliere estranei nel suo accampamento, ma dall'aspetto si direbbe che tu ne abbia viste parecchie, $C.$B$BAnche il Maestro Nesingwary è un veterano di molte battaglie, e ha un debole per chi è un eroe come lui.$B$BVa' a parlargli. Forse può darti qualche consiglio di caccia.",
  obj = "Parla con Hemet Nesingwary.",
  reward = "Proprio un piacere fare la tua conoscenza, $N. Era da un po' che non vedevo $Gun:una; $C da queste parti.$B$BMi sono unito a questa spedizione per un solo scopo: cacciare una bestia grande e sfuggente. Visto che sei una specie di $Geroe:eroina;, sono disposto a farti partecipare alla caccia, ma prima devi dimostrare quanto vali.$B$BTi insegnerò l'arte di uccidere i raptor. Ajeck ti addestrerà nella caccia alla tigre. E Sir Erlgadin è un maestro nel seguire le tracce delle pantere.$B$BDimostra la tua abilità e ti farò partecipare alla grande caccia.",
  en_title = "Welcome to the Jungle",
  en_obj = "Speak with Hemet Nesingwary",
}
T[584] = {
  title = "Le Teste del Clan Bloodscalp",
  desc = "Yenniku non era tra le teste, e ne ringrazio il Grande Serpente. Ma non abbiamo fatto passi avanti per trovarlo.$B$BDobbiamo conoscere la verità, e temo che la conoscano solo il capo dei Bloodscalp e il suo stregone. Sono nemici della tribù Darkspear e non parleranno di loro spontanea volontà, quindi dovremo strappare la verità dalle loro labbra morte!$B$BPortami le teste di Gan'zulah e di Nezzliok l'Infame e mettile in questo calderone.$B$BSi trovano nel cuore di Zul'Kunda. Porta le loro teste... poi li faremo parlare.",
  obj = "Porta Gan'zulah's Head e Nezzliok's Head al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Il brodo verdastro nel calderone ribolle.",
  reward = "Metti le teste di Gan'zulah e di Nezzliok nel calderone...",
  en_title = "Bloodscalp Clan Heads",
  en_obj = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.",
}
T[585] = {
  title = "A Colloquio con Nezzliok",
  desc = "<La testa di Nezzliok parla.>$B$BÈ vero. So dove è stato portato il figlio dei Darkspear. Mi hai sconfitto e hai incatenato il mio spirito, ma non dirò nulla senza un'offerta che mi plachi!$B$BI Bloodscalp sono in guerra con gli Skullsplitter. Per guadagnarti il mio favore, ruba agli Skullsplitter 3 dei teschi che tengono come trofei e mettili qui con noi, così che il mio spirito abbia degli schiavi nel Nether. Un teschio deve venire dal loro mucchio di trofei a Balia'mah, un altro da Ziata'jai e l'ultimo da Zul'Mamwe.",
  obj = "Porta un Balia'mah Trophy, un Ziata'jai Trophy e un Zul'Mamwe Trophy al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Attendo i teschi...",
  reward = "Sì. Mi saranno utili. Quando il mio spirito sarà liberato, entrerò nel Nether con tre ottimi servitori!$B$BSei $Gun:una; $R che fa onore al suo clan, e hai saputo placarmi.",
  en_title = "Speaking with Nezzliok",
  en_obj = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[586] = {
  title = "A Colloquio con Gan'zulah",
  desc = "<La testa di Gan'zulah parla.>$B$BTi maledico! E maledico i tuoi antenati!!$B$BSolo il sangue e la vendetta possono placare la mia rabbia, quindi se è questo che desideri, allora... fai così:$B$BGettati nel cuore degli Skullsplitter, a est. Uccidi i più feroci tra loro e, se sopravvivi... va' a infrangerti contro il loro capo, Ana'thek il Crudele. Ah! Portami la sua armatura in frantumi, se ci riesci!$B$BChe ti strappi gli arti e ti lasci a marcire, pasto per i necrofagi.",
  obj = "Uccidi 8 Skullsplitter Hunter, 6 Skullsplitter Headhunter e 4 Skullsplitter Berserker.$B$BPorta la Broken Armor of Ana'thek al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Anche se la mia carne si stacca bollendo dal teschio, sento ancora l'odore della tua paura.$B$BAh! Non porterai mai a termine il mio compito...",
  reward = "Non voglio crederci, ma non posso negare ciò che hai fatto. E la mia rabbia si placa, ora che Ana'thek è stato sconfitto.$B$BLa tua potenza ti porterà a grandi imprese, $N. Ma un giorno... ti rivedrò nel Nether, e misureremo di nuovo le nostre forze.$B$BTi aspetterò.",
  en_title = "Speaking with Gan'zulah",
  en_obj = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.$B$BBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[587] = {
  title = "Una Presa di Tabacco",
  desc = "Ah, la vita di mare. Non ti dirò mica che è la bella vita, ma è la mia vita.$B$BQuando arrivo in porto mi piace trovarmi una buona bottiglia di grog e del tabacco da fiuto di qualità. Brutte abitudini, ma cos'è un pirata senza i suoi vizi, giusto?$B$BQuindi puoi immaginare quanto ci sono rimasto male quando ho scoperto che l'erborista qui in città l'ha finito. Dice che il suo carico è stato dirottato da quei maledetti Incursori dei Bloodsail.$B$BScommetto che $Gun:una; $C $Gimpavido:impavida; come te potrebbe convincerli a dividere la merce, eh?",
  obj = "Deeg, a Booty Bay, vuole che tu gli porti 15 porzioni di Snuff.",
  progress = "Hai avuto fortuna con la merce, $Gcompagno:compagna;?",
  reward = "Ottimo lavoro, $N! E proprio prima che io debba salpare! Non so come ringraziarti, $Gvecchio amico mio:vecchia amica mia;.",
  en_title = "Up to Snuff",
  en_obj = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.",
}
T[588] = {
  title = "Il Destino di Yenniku",
  desc = "<Nezzliok parla.>$B$BHai placato me e il mio capo, quindi ti dirò ciò che cerchi di scoprire...$B$BIl giovane Yenniku è perduto per il suo clan.$B$BÈ stato preso dallo stregone Zanzil l'Errante. Ora Zanzil lo controlla anima e corpo, e solo la magia più potente potrebbe liberarlo.$B$BUna magia che tu non possiedi, $C.$B$BForse i tuoi alleati Darkspear possono offrire una speranza di salvezza per Yenniku. Ma ne dubito.",
  obj = "Parla con Kin'weelay.",
  reward = "Zanzil l'Errante??$B$BSe Yenniku è prigioniero di quel troll, uno stregone vile e potente, allora temo che resti solo una debole speranza. Debole. E minuscola come il più piccolo degli insetti.$B$BMa è pur sempre una speranza.",
  en_title = "The Fate of Yenniku",
  en_obj = "Speak with Kin'weelay.",
}
T[589] = {
  title = "I Cristalli Risonanti",
  desc = "Le leggende parlano di un gioiello nascosto nel profondo del cuore di Stranglethorn. Lo chiamiamo l'Occhio della Mente, e ha grandi poteri. Se riuscirai a ottenere questo Occhio, forse potremo usarlo per riportare il perduto Yenniku fuori dall'oscurità.$B$BConsulterò gli spiriti della giungla per trovare l'Occhio della Mente. Nel frattempo, tu entra nella Miniera di Crystalvein, a sud-est di qui, e raccogli delle Schegge Blu Pulsanti dai Basilischi Ironjaw. Le schegge sono rare, ma ci servirà la loro magia per piegare l'Occhio della Mente alla nostra volontà.",
  obj = "Porta 3 Pulsing Blue Shard a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Hai le schegge, $N? Mi servono per il mio rituale finale, quando avremo l'Occhio della Mente.",
  reward = "Ben fatto, $N. Queste schegge sono ben formate. Già le sento cantare per me.$B$BE mentre eri via, ho parlato con gli spiriti della giungla. So dove si trova l'Occhio della Mente...$B$B...E chi lo custodisce.",
  en_title = "The Singing Crystals",
  en_obj = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.",
}
T[591] = {
  title = "L'Occhio della Mente",
  desc = "L'Occhio della Mente è nelle mani di un mago ogre, a est di qui, nel profondo del tumulo degli ogre Mosh'Ogg. Si chiama Mai'Zoth. Lo conosco da quando i Darkspear vivevano a Stranglethorn — è crudele, e la sua magia è potente.$B$BE se ha l'Occhio della Mente, la sua magia sarà ancora più forte.$B$BDevi affrontare Mai'Zoth e strappargli l'Occhio della Mente. È un compito pericoloso, ma è l'unica speranza che abbiamo di salvare Yenniku.",
  obj = "Porta il Mind's Eye a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Salute, $N. Gli spiriti cantano lodi al tuo coraggio, eppure non mi raccontano nulla della tua impresa contro Mai'Zoth.$B$BHai l'Occhio?",
  reward = "Hai recuperato l'occhio! La tua potenza è leggendaria, $N!$B$BE per prendere l'Occhio devi aver sconfitto Mai'Zoth e averlo mandato nel Nether. Ecco perché prima gli spiriti non volevano nominarlo.$B$BÈ un bene che abbia lasciato il mondo della carne e delle ossa, ma ora che si trova nel regno degli spiriti... temo che darà inizio a un nuovo dominio.$B$BMa a questo penseremo un'altra volta. Ora devo celebrare un rituale per piegare l'Occhio della Mente ai nostri scopi...",
  en_title = "The Mind's Eye",
  en_obj = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.",
}
T[592] = {
  title = "Salvare Yenniku",
  desc = "Ho trasformato l'Occhio della Mente in una Gemma dell'Anima. Il suo scopo è duplice: devi usarla per stordire Yenniku e, una volta stordito, posargliela sulla testa per imprigionarne l'anima.$B$BPoi porta la gemma a Nimboya.$B$BYenniku vive con Zanzil l'Errante, alle Rovine di Aboraz, lungo il Lido Cristallino, nel lontano Capo di Stranglethorn.",
  obj = "Porta la Filled Soul Gem a Nimboya.",
  progress = "$N. Kin'weelay mi ha detto che sei $Gpartito:partita; per catturare Yenniku.$B$BÈ vero? L'hai preso?",
  reward = "Ce l'hai fatta! Hai liberato Yenniku dalla volontà di Zanzil e hai portato a termine la missione che credevo così disperata.$B$BLa nostra tribù ricorderà il tuo nome nei canti, $N, e incideremo la tua storia nella pietra perché viva per sempre.",
  en_title = "Saving Yenniku",
  en_obj = "Bring the Filled Soul Gem to Nimboya.",
}
T[593] = {
  title = "Riempire la Gemma dell'Anima",
  progress = "Yenniku è in piedi davanti a te, stordito, con la mente altrove...",
  reward = "Posi la Gemma dell'Anima sulla sua fronte. Rabbrividisce mentre la sua anima viene risucchiata, lasciandosi dietro il corpo, un guscio vuoto senza mente.",
  en_title = "Filling the Soul Gem",
}
T[594] = {
  title = "Messaggio in Bottiglia",
  desc = "Il biglietto, scritto con una calligrafia piuttosto buona, dice:$B$BA chiunque possa aiutarmi —$B$BTi prego, ho un disperato bisogno di aiuto. Un grande Skymane mi tiene prigioniera su un'isola dei South Seas.$B$BLe stelle, di notte, mi sono sconosciute e nascoste dagli alberi della giungla, ma nei giorni più limpidi vedo le Rive Selvagge a nord-ovest, e quelle che sembrano grandi navi a vela a sud-ovest.$B$BTi supplico, $Gmio salvatore:mia salvatrice;, ti prego, aiutami.",
  obj = "Trova chi ha scritto il messaggio in bottiglia.",
  reward = "Sei $Gvenuto:venuta; a liberarmi?",
  en_title = "Message in a Bottle",
  en_obj = "Find the author of the message in a bottle.",
}
T[595] = {
  title = "I Bloodsail Buccaneers",
  desc = "Hai proprio voglia di lavorare, $Gcompagno:compagna;. Non so perché $Gun:una; $C $R di terraferma voglia aiutare i Blackwater Raiders, ma non ti manderò via.$B$BLa nostra nave è appena attraccata qui a Booty Bay, e si dice che i nostri rivali — quei maledetti, sporchi Bloodsail Buccaneers — siano stati avvistati in tutta la Stranglethorn meridionale.$B$BI ragazzi sono tutti troppo presi dal grog e dalle donne! Mi serve un esploratore.$B$BControlla l'insenatura appena a nord di Booty Bay, lungo la Costa Selvaggia, e vedi cosa trovi.",
  obj = "First Mate Crazz vuole che tu controlli l'insenatura a nord di Booty Bay.",
  reward = "Sopra il barile trovi una mappa con un testo scritto in fretta, insieme a qualche moneta.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "First Mate Crazz wants you to check the cove north of Booty Bay.",
}
T[596] = {
  title = "Collane d'Ossa Insanguinate",
  desc = "Sono stato mandato a Grom'gol per aiutare Nimboya nella sua missione, ma... anch'io ho le mie ragioni per essere qui.$B$BLa tribù Bloodscalp è nemica della nostra tribù. Raccogliere trofei dei nostri nemici ci dà potere su di loro. Puoi aiutare la nostra tribù dando la caccia ai nostri nemici.$B$BVivono a nord. Uccidi i troll Bloodscalp e prendi le loro collane d'ossa insanguinate. Raccoglile in gran numero, e la tua ricompensa sarà grande.",
  obj = "Porta 25 Bloody Bone Necklace a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Un giorno i Bloodscalp saranno schiacciati dai Darkspear! Hai le collane del nostro nemico destinato alla rovina?",
  reward = "Ah, molto bene. Le farò bollire, le prosciugherò, e gli spiriti dei loro proprietari si indeboliranno mentre riduco in poltiglia le loro collane!$B$BEcco, $N. Questo ripagherà il mio debito con te.",
  en_title = "Bloody Bone Necklaces",
  en_obj = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.",
}
T[597] = {
  title = "I Bloodsail Buccaneers",
  desc = "La mappa mostra Booty Bay con una \"X\" rossa disegnata esattamente nel punto in cui ti trovi.$B$BIl testo scarabocchiato dice:$B$B\"Voi uomini dovete allestire un accampamento in questo punto e restare in silenzio. Aspettate il segnale dal posto di comando meridionale prima di attaccare. Se qualcuno si avvicina, uccidetelo.\"",
  obj = "Riferisci le tue scoperte a First Mate Crazz, a Booty Bay.",
  reward = "Certo che mi ricordo di te, $C. Di ritorno dalla ricognizione, vedo...",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report your findings to First Mate Crazz in Booty Bay.",
}
T[598] = {
  title = "Collana d'Ossa Divise",
  desc = "Ora che hai raccolto i trofei dei Bloodscalp, ho un altro compito per te. La tribù di troll Skullsplitter vive a sud-est, e da anni siamo in guerra con loro. Anche se i Darkspear non vivono più a Stranglethorn, siamo ancora legati al nostro conflitto con gli Skullsplitter.$B$BQuindi, dai loro la caccia. Raccogli le loro Collane d'Ossa Divise e torna da me. Aiutaci nella nostra guerra, e ti guadagnerai l'amicizia dei Darkspear.",
  obj = "Porta 25 Split Bone Necklace a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Gli Skullsplitter malediranno il giorno in cui ci hanno trascinati in guerra! Hai completato il tuo compito?",
  reward = "Grande è la tua forza, se hai ottenuto queste collane, $N. Gli Skullsplitter cadono davanti a te come giovani alberelli schiacciati a terra da un Basilisco!$B$BLe tue imprese sono una benedizione per noi.",
  en_title = "Split Bone Necklace",
  en_obj = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.",
}
T[599] = {
  title = "I Bloodsail Buccaneers",
  desc = "Corpo di mille balene! Quindi i Bloodsail Buccaneers stanno preparando una specie di attacco a Booty Bay? Ma che faccia tosta, quelle canaglie. Booty Bay sarà sempre in mano ai Blackwater Raiders!$B$BÈ una faccenda più grossa di quanto pensassi. Riferisci subito quello che hai scoperto al Comandante della Flotta Seahorn! Il vecchio lupo di mare è da qualche parte in città...",
  obj = "Riferisci a Fleet Master Seahorn dell'attacco che i Bloodsail stanno preparando.",
  reward = "I Bloodsail Buccaneers attaccano Booty Bay? Tanto varrebbe che si buttassero giù dalla Scogliera Altosguardo. Comunque, portandomi questa informazione hai reso un grande servizio alla mia flotta di bucanieri. I Blackwater Raiders ti ringraziano.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report the planned Bloodsail attack to Fleet Master Seahorn.",
}
T[600] = {
  title = "L'Estrazione Mineraria della Venture Company",
  desc = "La Venture Company ha una serie di attività in tutta Stranglethorn che impediscono ai goblin che lavorano sodo, come me, di guadagnarsi onestamente il loro oro! Ti prego, devi aiutarmi!$B$BLa Venture Company sta scavando vicino alla Miniera di Crystalvein, a nord. Non riescono a entrare nella miniera per via di tutti quei basilischi, ma estraggono comunque Cristalli Risonanti dalle colline intorno.$B$BPrendi i loro cristalli e fagli vedere che la giungla non è roba loro.$B$BE... ehm... portami quei cristalli come prova!",
  obj = "Porta 10 Singing Blue Crystal a Crank Fizzlebub, a Booty Bay.",
  progress = "Hai quei cristalli?? Mi servono!!$B$BCioè... ho bisogno di sapere che la malvagia Venture Company sta perdendo terreno a Stranglethorn. Perché, sai, noi gente onesta dobbiamo pur campare!",
  reward = "Ottimo! Magnifico! Posso ricavarci un bel gruzzolo!!$B$BQuella Venture Company ha proprio scelto la giungla sbagliata in cui scavare, eh? Staremmo tutti meglio se se ne andassero da qui.$B$BGrazie, $N. Oggi hai compiuto una buona azione.",
  en_title = "Venture Company Mining",
  en_obj = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.",
}
T[601] = {
  title = "Elementali dell'Acqua",
  desc = "Gli elementali dell'acqua sono stati senza dubbio evocati da Gazban, il mago goblin che si dice abbia scoperto la Pietra delle Maree. Come forse sai, la Pietra delle Maree maledice chi la porta, facendolo svanire e ricomparire...$B$BForse possiamo trovare un modo per contrastare la maledizione. Possiamo far analizzare a un mago di Dalaran il residuo magico di uno dei bracciali degli elementali dell'acqua. Ho bisogno che torni sull'isola e recuperi qualche campione.",
  obj = "Procura 6 Water Elemental Bracers per Baron Revilgaz, a Booty Bay.",
  progress = "Com'è andata, $N?",
  reward = "Mmh, non ho l'occhio esperto per capire se qualcuno di questi bracciali servirà a qualcosa, ma sono sicuro che almeno uno potrà aiutarci. Portali a Dalaran e falli esaminare da un mago.$B$BDopotutto, non posso certo lasciare Booty Bay solo per chiacchierare con quei noiosi vecchi maghi.$B$BNon che io sia preoccupato che qualcuno provi a farsi largo a gomitate per diventare il nuovo barone. Nessuno si mette contro Revilgaz e resta vivo per raccontarlo.",
  en_title = "Water Elementals",
  en_obj = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.",
}
T[602] = {
  title = "Analisi Magica",
  desc = "A quanto ho sentito, i maghi di Dalaran sono impegnati a ricostruire la loro città distrutta; sono sicuro che ne troverai uno disposto a dedicare un po' di tempo a esaminare i bracciali. Se c'è una cosa che so dei maghi, è che non resistono a un enigma magico.$B$BPrendi la borsa di bracciali degli elementali dell'acqua e vedi se riescono a fare luce sulla maledizione della Pietra. Cerca in particolare l'Arcimago Ansirem Runeweaver. Ho già avuto a che fare con lui, e la sua conoscenza è vasta.",
  obj = "Porta la Bag of Water Elemental Bracers ad Archmage Ansirem Runeweaver, a Dalaran.",
  progress = "Se non ti dispiace, in questo momento sono piuttosto occupato.",
  reward = "La Pietra delle Maree? Molto interessante. Forse ti sorprenderà sapere che ho scritto un tomo — diversi anni fa — sulle leggende del Gurubashi Empire. Della Pietra so parecchio.$B$BAlmeno uno di questi bracciali sembra avere un residuo magico che posso analizzare.$B$BVediamo cosa riesco a vedere...",
  en_title = "Magical Analysis",
  en_obj = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.",
}
T[603] = {
  title = "La Chiave di Ansirem",
  desc = "Il mago che possiede la Pietra ne amplifica il potere attraverso una specie di punto focale... un altare di qualche tipo. Dovresti riuscire a spezzarlo sovraccaricandolo.$B$BGuarda caso, so proprio cosa serve: un antico pugnale, un'altra reliquia troll. C'è solo un... piccolo problema.$B$BVedi, ho trovato il pugnale durante le mie ricerche a Stranglethorn, ma l'ho dato a mia figlia Catelyn, una testa calda, che è scappata a Booty Bay per fare la pirata.",
  obj = "Parla con Catelyn, a Booty Bay.",
  reward = "Il mio pugnale? Cosa sei, $Gun comico:una comica;?$B$BCosa? Vuoi solo sentirmi ripetere come sono passata dall'essere la miglior combattente al coltello di Booty Bay allo zimbello di tutta la pirateria!$B$BHo perso un duello al coltello con uno dei Bloodsail Buccaneers — una manica di gran bastardi, quelli! — e lui si è preso la mia lama come bottino.$B$BNon è che una combattente al coltello possa tirare avanti solo con gli insulti e la lingua tagliente...",
  en_title = "Ansirem's Key",
  en_obj = "Talk to Catelyn in Booty Bay.",
}
T[604] = {
  title = "I Bloodsail Buccaneers",
  desc = "Crazz parla molto bene della tua dedizione ai Blackwater Raiders. Ti affiderò una missione della massima importanza per la flotta.$B$BInfiltrati nel cosiddetto posto di comando meridionale che i Bloodsail Buccaneers hanno allestito sulle Rive Selvagge. Fai irruzione nell'accampamento. Portami le loro carte nautiche insieme ai loro ordini scritti. Vedremo esattamente cosa stanno tramando quei farabutti.",
  obj = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida 10 Bloodsail Swashbuckler e riporti le Bloodsail Charts e i Bloodsail Orders.",
  progress = "Ahoy, $N. Che notizie porti dall'accampamento dei Bloodsail a sud?",
  reward = "Perfetto, $N. Ora che conosciamo il loro piano, è solo questione di tempo.$B$BE pensare che quegli sciocchi hanno gettato l'ancora proprio al largo del capo...",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.",
}
T[605] = {
  title = "Schegge Blu Risonanti",
  desc = "I Cristalli Risonanti esistono solo a Stranglethorn, e per certa gente valgono parecchio. Io quei cristalli riesco a piazzarli, ma quella maledetta Venture Company rende difficile a un onesto imprenditore come me raccoglierne anche solo uno!$B$BVorrei assumerti.$B$BI basilischi di Stranglethorn mangiano il cristallo. È questo che dà loro la pelle indurita, e a volte se ne può ricavare cristallo di discreta qualità.$B$BPuoi prenderlo da qualsiasi basilisco, ma quelli meno cattivi stanno lungo le rive a sud di Zul'Kunda, a nord.",
  obj = "Porta 10 Singing Crystal Shard a Crank Fizzlebub.",
  progress = "Hai già quelle schegge? Ti darò una bella fetta dei profitti!",
  reward = "Aha! Queste andranno benissimo, $N. Sì, proprio benissimo!$B$BEcco la tua parte, e... è stato un piacere fare affari con te.",
  en_title = "Singing Blue Shards",
  en_obj = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.",
}
T[606] = {
  title = "Spaventare Tremarella",
  desc = "Se c'è una cosa che non sopporto, è la gente che non paga i debiti di gioco! E sono in tanti a dovermi dei soldi. Pensi di potermi aiutare a riscuotere?$B$BPer cominciare, c'è \"Tremarella\" Phillipe, giù ai moli. Mi deve parecchio dopo la partita della settimana scorsa e voglio quello che mi spetta! Ma per averlo dovremo spaventarlo.$B$BEsci dalla città e dai la caccia ai Gorilla Anziani di Mistvale. Procurati un bell'assortimento di frattaglie, poi portale a Tremarella. Non fargli capire che vengono da un animale; lascia che pensi al peggio.",
  obj = "Porta 5 Mistvale Giblets a \"Shaky\" Phillipe, a Booty Bay.",
  progress = "Ehi! Non mi piace come mi guardi, $Gsignore:signora;.",
  reward = "Argh! Dove le hai prese? No, non dirmelo. Non voglio saperlo!$B$BChi ti manda? Lupo di Mare?",
  en_title = "Scaring Shaky",
  en_obj = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.",
}
T[607] = {
  title = "Torna da MacKinley",
  desc = "Ecco, prendi questo sacchetto e dallo a Lupo di Mare. E digli che avevo intenzione di ripagarlo! Lo giuro!!$B$BMi sono solo ubriacato un po' e mi sono perso per strada, e... sai com'è. Capirà — non c'è bisogno di passare alle maniere forti!",
  obj = "Porta Shaky's Payment a \"Sea Wolf\" MacKinley.",
  progress = "Ehilà, $N. Hai riscosso il pagamento di Tremarella?",
  reward = "Eh eh, ben fatto! E quando hai mostrato a Tremarella quelle frattaglie, quanto ha tremato?$B$BAh! Gli si legge tutto in faccia, e quando gioco a carte con lui non posso fare a meno di vincere!$B$BGrazie per l'aiuto, $N. Ora tocca a te ricevere la paga...",
  en_title = "Return to MacKinley",
  en_obj = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.",
}
T[608] = {
  title = "I Bloodsail Buccaneers",
  desc = "Maledetta la sfacciataggine di Firallon! Non saprebbe guidare una barchetta attraverso il Lago di Cristallo, figurarsi un'intera flotta contro di noi.$B$BI Bloodsail Buccaneers pagheranno per la loro imprudenza. Ora che conosciamo il loro piano d'attacco, possiamo contrattaccare prima ancora che se ne rendano conto.$B$BMa perché mandare l'intera flotta a fare il lavoro di un solo gruppo di coraggiosi avventurieri? $N, porta alcuni dei tuoi compagni più abili al punto di sbarco di Firallon e assassina i capi dei Bloodsail. La loro flotta affonderà poco dopo...",
  obj = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida Captain Stillwater, Captain Keelhaul e Fleet Master Firallon.",
  progress = "Qual è il problema, $N? Dobbiamo attaccare prima che lo facciano i Bloodsail Buccaneers!",
  reward = "Ah, che grande giorno per i Blackwater Raiders! Tre urrà per te, $N!",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.",
}
T[609] = {
  title = "Debiti Voodoo",
  desc = "La mia lista si sta accorciando, ma c'è ancora gente che mi deve dei soldi.$B$BPoi ci sono Maury \"Piede Torto\" Wilkins, Jon-Jon il Corvo e Chucky \"Mani di Burro\".$B$BI debiti di questi cani rognosi sono scaduti da mesi, e pensavo che avessero lasciato la città per non pagare! Poi ho sentito che sono maledetti e stregati e che ora vagano tra le rovine nella giungla. Ma non m'importa che fine abbiano fatto — voglio quello che è mio!$B$BSono alle Rovine di Aboraz e alle Rovine di Jubuwal, a nord-est di qui. Trovali e riscuoti.",
  obj = "Porta Maury's Clubbed Foot, Jon-Jon's Golden Spyglass e Chucky's Huge Ring a \"Sea Wolf\" MacKinley, a Booty Bay.",
  progress = "$N, hai trovato quei tre cani? Hai riscosso i loro oggetti di valore?",
  reward = "Ottimo! Posso spuntare un buon prezzo per questi, soprattutto per quello che c'è dentro il piede di Maury! Grazie mille, $N!$B$BSpero che quei tre abbiano imparato la lezione: non scommettere mai qualcosa che non puoi permetterti di perdere.$B$BE forse per loro è troppo tardi, ma... dovrebbero scegliere con più attenzione con chi giocare d'azzardo.",
  en_title = "Voodoo Dues",
  en_obj = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.",
}
T[610] = {
  title = "\"Pretty Boy\" Duncan",
  desc = "Ti ha mandato mio PADRE? Pensavo che quel vecchio brontolone avesse già rinunciato a me.$B$BNon è davvero colpa sua se sono scappata, solo che non avrebbe dovuto aspettarsi che accettassi di vivere una vita noiosa, a leggere libri ammuffiti e a frequentare maghi canuti, impettiti e barbosi!$B$BSe ti serve il mio pugnale, dovrai riprenderlo a \"Pretty Boy\" Duncan, uno dei Bloodsail Buccaneers. Piantagli qualcosa tra le spalle e sono sicura che te lo darà.",
  obj = "Prendi Catelyn's Blade a \"Pretty Boy\" Duncan.",
  progress = "Non ero mai stata battuta prima, sai, $N? Certo, qualche taglio l'avevo preso, in un duello al coltello non si può evitare, ma lui mi ha colpita di lato alla testa e mi ha fatto perdere i sensi. Quando mi sono ripresa, la mia lama era sparita.$B$BPer quanto il mio soprannome possa far pensare il contrario, mi serve comunque un coltello per combattere, e per me deve essere quello.",
  reward = "Hai battuto Duncan? Allora non sei $Gcosì inesperto:così inesperta; come sembravi a prima vista.$B$BImmagino che questo voglia dire anche che non dovrei sfidarti a duello tanto presto!",
  en_title = "\"Pretty Boy\" Duncan",
  en_obj = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.",
}
T[611] = {
  title = "La Maledizione delle Maree",
  desc = "Quindi cerchi una specie di altare? Be', io non sono un'esperta di rovine troll come mio padre, ma ho sentito parlare di una città troll sommersa vicino a quell'isola che stai cercando. Forse dovresti provare lì.$B$BMi hai riportato il coltello, quindi immagino che tu possa prenderlo in prestito... ma quando hai finito lo rivoglio!",
  obj = "Distruggi l'Altar of the Tides con Catelyn's Blade, uccidi Gazban e riporta la Stone of the Tides e Catelyn's Blade a Baron Revilgaz.",
  progress = "Hai recuperato la Pietra delle Maree per me, $N? Ho già fatto spazio e ho comprato un bel piedistallo apposta.",
  reward = "Straordinario! La Pietra delle Maree! Avrà un posto d'onore nella mia collezione di antichi manufatti troll. Hai visto come sembra quasi che una marea sia intrappolata nella sua superficie? Magnifico!",
  en_title = "The Curse of the Tides",
  en_obj = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.",
}
T[613] = {
  title = "Scassinare il Piede di Maury",
  desc = "Maledizione! Quel mozzo di Maury ha messo un lucchetto al suo piede, e non riesco ad aprirlo! Il suo bottino è dentro il piede, ed è quello che mi deve!$B$BDobbiamo trovare la chiave per aprire il lucchetto. Si sapeva che Maury giocava d'azzardo con gli ogre Mosh'Ogg, nel loro tumulo a nord-est. E mi ha raccontato, quando era ancora vivo, che l'ultima volta che era andato al tumulo l'avevano cacciato via perché aveva vinto troppo. Forse gli Ogre di laggiù hanno la sua chiave.$B$BMa se ce l'hanno, potresti dover ucciderne un bel po' per trovare quello giusto...",
  obj = "Porta Maury's Key a \"Sea Wolf\" Mackinley, a Booty Bay.",
  progress = "Ohilà, $N! Hai già trovato la Chiave di Maury?",
  reward = "L'hai trovata! Grazie mille, $N. Mi sei $Gstato:stata; di grande aiuto!$B$BEcco qua — te lo sei $Gguadagnato:guadagnata;!",
  en_title = "Cracking Maury's Foot",
  en_obj = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.",
}
T[614] = {
  title = "Il Forziere del Capitano",
  desc = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.$B$BFinché...$B$BQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il Forziere del Capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!$B$BHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.",
  obj = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.",
  progress = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!",
  reward = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.$B$BMa la mia vendetta non è completa...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[615] = {
  title = "La Sciabola del Capitano",
  desc = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.$B$BStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.$B$BAffronta Negolash e riportami la mia sciabola!$B$BParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[616] = {
  title = "L'Isola Infestata",
  desc = "Il Barone Revilgaz mi ha chiesto di tenere le orecchie aperte per le voci su cose strane e fuori posto a Booty Bay e a Stranglethorn. Di solito non do molto peso alle storie di fantasmi, ma alla taverna ho sentito dei marinai parlare di un'isola infestata al largo della costa. Elementali dell'acqua e un fantasma goblin che delira, dicono.$B$BSe vai a parlare con Revilgaz, potresti riferirgli questa storia?",
  obj = "Parla con Baron Revilgaz, a Booty Bay.",
  reward = "Interessante. Tempo fa, mi pare di ricordare di aver letto un libro che suggeriva...$B$BAh, certo, era una leggenda troll. Se quello che riferisce Krazek è vero, forse presto potrò aggiungere la Pietra delle Maree alla mia collezione di manufatti e reliquie antiche.",
  en_title = "The Haunted Isle",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[617] = {
  title = "Akiris a Mazzi",
  desc = "Cerchi lavoro, $N? Potrei averne un po', se te la senti di affrontare una piccola sfida.$B$BHo un amico, Groy, che fa soldi a palate vendendo quella che i naga chiamano canna di akiris: è una specie di pregiata canna marina. Non so bene a cosa serva, ma paga bene per i mazzi di quella roba.$B$BPortami dieci steli di quella roba, e faremo affari. I naga sono stati visti l'ultima volta lungo la spiaggia a nord di qui.",
  obj = "Porta 10 Akiris Reed a Privateer Bloads, a Booty Bay.",
  progress = "Se non hai affari da fare con me, allora circola, $N.",
  reward = "Ben fatto, $N. Dieci steli di canna di akiris non erano poi una sfida così grande, eh? Senza offesa per i naga, ma ehi, tutti devono pur campare.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.",
}
T[618] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Ali di Condor alla Griglia. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di ali di condor. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.$B$BUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.",
  progress = "Hai recuperato la mia sciabola, $N?",
  reward = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha cambiato in meglio la mia sorte, puoi starne certo!$B$BGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[619] = {
  title = "Attirare Negolash",
  progress = "È una scialuppa di salvataggio abbandonata. Sulla fiancata, in vernice graffiata e sbiadita, sono dipinte le parole:$B$B\"Smotts' Revenge\"",
  reward = "Ammucchi cibo e bevande sulla zattera...",
  en_title = "Enticing Negolash",
}
T[620] = {
  title = "La Fascia con il Monogramma",
  desc = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.",
  obj = "Riporta la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Hai affari da trattare con me?",
  reward = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!$B$BSono contento che quel lurido farabutto sia morto: Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
}
T[621] = {
  title = "Il Segreto di Zanzil",
  desc = "Zanzil l'Errante vive con i suoi seguaci nelle Rovine di Jubuwai e di Aboraz, a nord-est di Booty Bay. È stato esiliato dalla sua tribù. Perché? Be'...$B$BZanzil conosce dei metodi per piegare la mente degli altri, e i suoi capi lo temono. Sui suoi seguaci usa una miscela di piante della giungla che ne sopprime la volontà e ne rafforza il corpo.$B$BLa sua miscela varrebbe molto per chi vuole controllare gli altri.$B$BPortami dei campioni della sua miscela, e troverò il modo di usarli.",
  obj = "Porta 12 campioni di Zanzil's Mixture a Crank Fizzlebub, a Booty Bay.",
  progress = "Hai i campioni della Mistura di Zanzil??",
  reward = "Ah, molto bene! Ecco la tua paga.$B$BEd ecco un piccolo extra... per la tua discrezione.",
  en_title = "Zanzil's Secret",
  en_obj = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
}
T[622] = {
  title = "Torna dal Caporale Kaleb",
  desc = "Mentre eri via ho aggiustato la pentola che mi hai portato. Ci ho perfino aggiunto un fischietto a vapore in più, e guarda! C'è un nuovo trinciatore sul fondo che taglia anche le ossa delle gambe!$B$BSì, sì, la Pentola a Pressione di Krazek soddisfa il cuoco al cento per cento! Sono sicuro che il suo proprietario sarà contento.",
  obj = "Porta Krazek's Fixed Pot a Corporal Kaleb, a Rebel Camp.",
  progress = "Salve, $N. Sei $Garrivato:arrivata; fino a Booty Bay? Il goblin Krazek ha aggiustato la mia pentola??",
  reward = "È aggiustata! Fantastico, ora posso mettermi a preparare la cena! Grazie mille, $N.$B$BSpero che a Booty Bay sia andato tutto bene. Quel posto può diventare parecchio pericoloso, e... ho sentito dire che a volte i goblin trascinano i marinai ubriachi sulle loro navi di schiavi e li portano chissà dove... a fare chissà cosa...",
  en_title = "Return to Corporal Kaleb",
  en_obj = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.",
}
T[623] = {
  title = "Akiris a Mazzi",
  desc = "$N, visto che sei qui: mentre eri via mi è arrivato un messaggio da Groy. Dice di essere soddisfatto dell'ultimo carico che gli è arrivato, e ha un cliente che ne vuole subito dell'altro.$B$BIo non andrò a Theramore prima di una settimana, ma se te la senti di fare il viaggio, non vedo perché tu non possa portargli la roba al posto mio.$B$BHai voglia di avventura? Lo sai dov'è il Dustwallow Marsh, vero? Però fa' attenzione: Theramore può essere pericolosa se sei del giro sbagliato.",
  obj = "Porta un Bundle of Akiris Reeds a Privateer Groy, a Theramore.",
  progress = "Sì?",
  reward = "Cosa?! Ho cose molto migliori da fare che parlare con gente come te, $C. Fa' che ne valga la pena o levati di torno.$B$BEh? Ti manda Bloads, eh? Be', che mi hai portato?$B$B<Il Corsaro Groy esamina con cura il mazzo.>$B$BNiente male, niente male davvero. Un altro mazzo renderà il mio cliente molto contento.$B$BImmagino che la tua prossima domanda riguarderà i soldi, eh, $C? Certo che sì!$B$BEcco, prendi queste monete e un consiglio: sparisci dai miei moli.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.",
}
T[624] = {
  title = "L'Indovinello di Cortello",
  desc = "Un ponte adorno, da molti passanti calcato$BA est di Deadwind e a sud di Redridge situato$BLà sotto qualcosa ti aspetta, lo sai$BChi lo chiama traccia, chi indizio: vedrai$BLì resterà per infiniti domani$BAttendendo nella Swamp of Sorrows, tra i pantani",
  obj = "Risolvi l'indovinello!",
  reward = "La pergamena fradicia contiene il prossimo indizio...",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[625] = {
  title = "L'Indovinello di Cortello",
  desc = "In Kalimdor ti attendono luoghi lontani$BDove il pericolo ha reso speranze e destini vani$BA est delle Barrens il clima è impietoso$BNel Dustwallow Marsh tutto è cupo e insidioso$BMa per chi supera la prova un indizio c'è$BIn una grotta a sud-ovest, che aspetta te",
  obj = "Risolvi l'indovinello!",
  reward = "Trovi una pergamena ammuffita.",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[626] = {
  title = "L'Indovinello di Cortello",
  desc = "A Lordaeron! Grande terra di tormento$BDove prodi soldati si battono con la morte a ogni momento$BAttraversa i grandi disordini con coraggio$BLà troverai la fine di questo viaggio$BLungo la costa delle Hinterlands, ai piedi delle grandi cascate$BSott'acqua il tuo tesoro ti chiama dalle onde agitate!",
  obj = "Risolvi l'indovinello!",
  reward = "Apri il forziere e scopri...",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[627] = {
  title = "Un Favore per Krazek",
  desc = "C'è una grotta di montagna nella Gola dei Drywhisker, molto più a nord, negli Arathi Highlands. In quella grotta c'è un minerale raro: la sanguinite. La sanguinite di questa grotta non è della qualità migliore, ma anche quella di bassa qualità ha valore... per chi sa come usarla.$B$BNe vorrei un po'.$B$BIo aggiusto la tua pentola, ma mentre ci lavoro... portami dei campioni di sanguinite. Portamene abbastanza e ti darò anche un premio in più.$B$BAh, e se non hai la capacità di estrarla... trova qualcuno che ce l'ha!",
  obj = "Porta 4 carichi di Lesser Bloodstone Ore a Krazek, a Booty Bay.",
  progress = "Salve, $N. Hai avuto fortuna con la sanguinite?",
  reward = "Ah, splendido! Mi hai fatto proprio un bel favore.$B$BEcco il tuo compenso...",
  en_title = "Favor for Krazek",
  en_obj = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.",
}
T[628] = {
  title = "Excelsior",
  desc = "Finito l'interno, non resta che aggiungere lo strato esterno. Per questo uso solo le migliori pelli di coccodrillo anziano. Sono più resistenti e sono una tela migliore — per così dire — per aggiungere i disegni e le rifiniture che distinguono la linea Excelsior di Drizzlik.$B$BPerò è difficile trovare la pelle perfetta: l'unica adatta al mio progetto è quella di un crocolisco anziano d'acqua salata. Gli esemplari anziani escono solo per difendere gli altri coccodrilli d'acqua salata, quindi potresti doverne uccidere qualcuno per farne uscire uno.",
  obj = "Porta un Elder Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "Ho letto da qualche parte che i crocolischi d'acqua salata si stanno lentamente estinguendo... brutte notizie per i miei affari, no?$B$BComunque, spero che tu abbia quella pelle di crocolisco anziano d'acqua salata per me!",
  reward = "Grande! Grazie al tuo aiuto evaderò questo ordine e lo spedirò al Direttore Riddlevox con la prossima nave per Undermine. Addirittura in anticipo!$B$BPer tutto il tuo duro lavoro, ecco: ne ho fatti alcuni in più, quindi prendine un paio. Offre Drizzlik.$B$BE ricorda: non c'è stivale più raffinato di uno della linea Excelsior di Drizzlik!",
  en_title = "Excelsior",
  en_obj = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.",
}
T[629] = {
  title = "La Scogliera Immonda",
  desc = "Tanto tempo fa, un violento scossone della terra fece sprofondare un'antica città troll sotto le acque della Costa Selvaggia, a nord-ovest. Chiamiamo quel luogo la Scogliera Immonda, perché ora nelle rovine della città vivono i murloc, che attaccano chiunque si avvicini.$B$BTra quelle rovine c'è una vecchia tavoletta che narra l'antica storia di Gri'lek, un eroe delle leggende troll. La storia è sacra per la tribù Darkspear, e anche se la tavoletta è troppo grande per essere spostata, ne voglio un frammento da custodire come reliquia nella nostra nuova casa a Orgrimmar.",
  obj = "Porta un Tablet Shard a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Attendo la Scheggia di Tavoletta, $N.",
  reward = "Bene. Quando tornerò a Orgrimmar metterò questo frammento in un luogo sacro. Ci ricorderà la potenza e l'onore di Gri'lek.$B$BGrazie, $N. Le tue azioni sono il segno di un'amicizia sempre più forte con la tribù Darkspear.",
  en_title = "The Vile Reef",
  en_obj = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.",
}
T[630] = {
  title = "Messaggio in Bottiglia",
  desc = "$N, ripongo la mia fiducia in te e in chiunque tu riesca a radunare per liberarmi. Il grande Re Mukla degli Skymane è il mio carceriere. Comanda le bestie di quest'isola, e mi tengono qui contro la mia volontà con questa catena. Se riesci a ucciderlo e a trovare la chiave di questo ceppo, ti sarò molto debitrice.$B$BLo sento spesso dalla parte sud-orientale dell'isola, ma ti prego, fa' attenzione: non è uno da prendere alla leggera.",
  obj = "Uccidi King Mukla e torna da Princess Poobah con la Shackle Key per liberarla.",
  progress = "Ringrazio i miei antenati perché qualcuno è venuto ad aiutarmi. Hai la chiave che mi libererà?",
  reward = "$N, mi hai salvata da un grande disonore. Se fosse in mio potere, ti offrirei un posto nella mia tribù. Ma per ora posso offrirti solo questo pegno, per il coraggio e la nobiltà che hai dimostrato.",
  en_title = "Message in a Bottle",
  en_obj = "Slay King Mukla and return to Princess Poobah with the Key to free her.",
}
T[631] = {
  title = "Il Viadotto di Thandol",
  desc = "Un'esplosione tremenda è rimbombata tra le colline. È stato orribile, te lo dico io!$B$BBravi soldati sono morti difendendo il Viadotto di Thandol. Longbraid dice che, prima che sia finita, ci vendicheremo dei Dark Iron.$B$BSiamo messi malissimo, però, e di rinforzi non se ne vedono. Longbraid ha mandato il vecchio Rustlocke a esplorare il ponte orientale, per vedere se riuscivamo a metterlo in sicurezza.$B$BÈ successo giorni fa. Con Dun Modr sotto assedio, non abbiamo abbastanza uomini per andarlo a cercare.$B$BForse tu puoi trovarlo...",
  obj = "Rhag Garmason vuole che tu trovi Ol' Rustlocke.",
  reward = "Frughi il piccolo cadavere del nano. Sull'elmo c'è un'incisione che si legge chiaramente: Ebenezer Rustlocke.",
  en_title = "The Thandol Span",
  en_obj = "Rhag Garmason wants you to locate Ol' Rustlocke.",
}
T[632] = {
  title = "Il Viadotto di Thandol",
  desc = "Sembra che il povero vecchio Rustlocke sia finito in un'imboscata dei Dark Iron. Noti una pergamena accanto al suo pugno serrato.$B$BRiferisci la triste notizia a Rhag Garmason e mostragli quello che hai trovato.",
  obj = "Torna da Rhag Garmason e mostragli la pergamena che hai trovato sul cadavere di Rustlocke.",
  progress = "Qualche traccia del vecchio Rustlocke, $N?",
  reward = "Oh cielo, la notizia è grave...",
  en_title = "The Thandol Span",
  en_obj = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.",
}
T[633] = {
  title = "Il Viadotto di Thandol",
  desc = "Santo cielo, no! Povero Rustlocke. È davvero una gran tragedia.$B$BNon dobbiamo permettere che sia morto invano. Questa pergamena che hai scoperto dice che Kam Deepfury, la mente dietro il primo attacco, ha fatto nascondere una scorta di esplosivi appena oltre il Viadotto di Thandol, negli Arathi Highlands.$B$BSe quegli esplosivi arrivano al ponte, la nostra principale via di rifornimento verso nord sarà tagliata! La scorta va distrutta, $N! Torna da me quando la missione sarà compiuta.$B$BSei la nostra unica speranza.",
  obj = "Distruggi la Cache of Explosives.",
  progress = "La scorta di esplosivi va distrutta!",
  reward = "Il ponte che ci resta è salvo! Hai reso un grande servizio a Re Magni e alla gente di Khaz Modan.$B$BOra, se solo riuscissimo a resistere finché non arrivano i rinforzi...",
  en_title = "The Thandol Span",
  en_obj = "Destroy the cache of explosives.",
}
T[634] = {
  title = "Appello all'Alleanza",
  desc = "Ti chiedo ancora un piccolo favore, $C. Attendiamo le riserve di Ironforge. Roggo però sa di un campo dell'Alleanza a nord, negli Arathi Highlands, a Refuge Pointe.$B$BVa' laggiù e cerca la Capitana Nials. Chiedi alla brava Capitana se l'Alleanza può concederci qualche soldato per aiutarci a riprendere Dun Modr e il Viadotto di Thandol.",
  obj = "Cerca Captain Nials a Refuge Pointe.",
  reward = "Le mie condoglianze vanno a Longbraid e ai suoi coraggiosi soldati. La notizia della tragedia del Viadotto di Thandol e della caduta di Dun Modr mi pesa sul cuore.$B$BMa Stromgarde è caduta! Per questo siamo qui, a Refuge Pointe. Ci troviamo a dover riconquistare la nostra grande città.$B$BL'onore e il dovere ci impongono di non lasciare gli Highlands finché Stromgarde non tornerà a innalzare il possente stendardo del Re. Manderò a dire a Longbraid che dovrà cavarsela da solo...",
  en_title = "Plea To The Alliance",
  en_obj = "Seek out Captain Nials at Refuge Pointe.",
}
T[635] = {
  title = "Il Cristallo nelle Montagne",
  desc = "Questo frammento pulsa mentre lo tieni in mano...$B$BDal frammento avverti una specie di supplica, come se qualcuno cercasse di comunicare, qualcuno che ha disperatamente bisogno del tuo aiuto.$B$BNella tua mente appare una visione — le montagne settentrionali di Arathi, e un cristallo splendente che spunta dalla terra.$B$BTi senti $Gattratto:attratta; da quel luogo.",
  obj = "Trova il cristallo della tua visione.",
  reward = "Questo cristallo pulsa, come se dentro vi fosse intrappolata una forza viva.",
  en_title = "Crystal in the Mountains",
  en_obj = "Find the crystal from your vision.",
}
T[637] = {
  title = "Lettera di Sully Balloo",
  desc = "La busta, fradicia e segnata dalla guerra, si sfalda tra le tue mani, e tra le dita ti restano alcune pagine di una lettera, scritta con estrema cura.$B$BLa lettera è indirizzata a una certa Signora Sara Balloo di Ironforge e comincia con le parole \"Mia cara Sara....\"",
  obj = "Consegna Sully Balloo's Letter a Sara Balloo.",
  progress = "Hai l'aria di chi ha viaggiato a lungo e ne ha passate tante nella sua vita, $C. I tempi in cui viviamo mettono a dura prova l'anima. Che notizie mi porti adesso?",
  reward = "Dici di aver visto il mio Sully intrappolato sotto le acque gelide? Dimmi che non è vero!$B$BFammi leggere quel che ha scritto....",
  en_title = "Sully Balloo's Letter",
  en_obj = "Deliver Sully Balloo's Letter to Sara Balloo.",
}
T[638] = {
  title = "Trollbane",
  desc = "Con Thoras Trollbane morto e Stromgarde in rovina, Vol'jin ci ha ordinato di fare di tutto per sottrarre agli umani la leggendaria spada Trol'kalar, così da poterla usare nelle prossime battaglie contro i troll di Zul'Gurub.$B$BZengu, uno dei nostri cacciatori più esperti, è stato mandato a Hammerfall, nel nord-est degli Arathi Highlands, per occuparsi di procurarla.",
  obj = "Va' a Hammerfall, negli Arathi Highlands, e parla con Zengu.",
  reward = "Come va, $C? Il compito che Vol'jin ci ha affidato sarà difficile, e qualunque aiuto tu possa darci sarà gradito e necessario.",
  en_title = "Trollbane",
  en_obj = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.",
}
T[639] = {
  title = "Sigillo di Strom",
  desc = "In tempi antichi, i troll combatterono contro l'Arathorian Empire e contro il più abile dei nostri avversari, Lord Ignaeus di Strom, detto Trollbane. Cavalcava in battaglia brandendo Trol'kalar — ammazzatroll, nella loro antica lingua.$B$BMa ora i figli di Trollbane sono indeboliti, e la loro roccaforte è andata in rovina.$B$BLa spada è protetta da diversi sigilli, divisi tra i sopravvissuti di Stromgarde, e dobbiamo recuperarli.$B$BIl primo l'ha preso il Syndicate; dovrebbe averlo uno dei loro uomini a Stromgarde.",
  obj = "Procura il Sigil of Strom per Zengu, a Hammerfall.",
  progress = "Hai già trovato il primo sigillo? Molto probabilmente ce l'ha addosso uno degli agenti del Syndicate a Stromgarde.",
  reward = "Eccellente, mon. È un buon inizio per raccogliere i sigilli che ci serviranno per togliere Trol'kalar dalla tomba di Trollbane.",
  en_title = "Sigil of Strom",
  en_obj = "Get the Sigil of Strom for Zengu in Hammerfall.",
}
T[640] = {
  title = "Il Sigillo Spezzato",
  desc = "La tomba di Thoras Trollbane è protetta da tre sigilli; il primo l'hai recuperato dal Syndicate. Gli altri due saranno più difficili da prendere, perché sono in mano alla milizia di Stromgarde, ben trincerata.$B$BIl sigillo di Thoradin è stato diviso in undici pezzi dal figlio di Thoras, Galen, e distribuito tra i difensori di Stromgarde. Recupera i pezzi e portali a Tor'gan, lo sciamano troll: sarà in grado di ricomporli nel sigillo completo.",
  obj = "Recupera gli 11 Sigil Fragment dai difensori di Stromgarde e portali a Tor'gan, a Hammerfall.",
  progress = "Throm'ka, $C. Zengu mi ha detto che avevi bisogno del mio aiuto?",
  reward = "Ah, hai bisogno che ricomponga questo sigillo? Non dovrebbe essere troppo difficile... tutti i pezzi sembrano esserci, e la struttura magica sarà facile da ricostruire.$B$BForse ti conviene chiudere gli occhi.",
  en_title = "The Broken Sigil",
  en_obj = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.",
}
T[641] = {
  title = "Sigillo di Thoradin",
  desc = "La ricostruzione è riuscita alla perfezione. Ora il sigillo può servire a spezzare il suggello sulla tomba di Trollbane. Riportalo a Zengu; di sicuro ha altri compiti per te.",
  obj = "Porta il Sigil of Thoradin ricomposto a Zengu, a Hammerfall.",
  progress = "$N! Hai il secondo sigillo?",
  reward = "Siamo a metà strada per poter togliere Trol'kalar dalla tomba di Trollbane. Non sappiamo con precisione dove sia il terzo sigillo, perché chi lo custodisce sembra spostarsi parecchio per l'Arathi, ma ho fiducia che riuscirai a trovarlo.",
  en_title = "Sigil of Thoradin",
  en_obj = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.",
}
T[642] = {
  title = "La Principessa Intrappolata",
  desc = "Mi chiamo Myzrael. Sono una principessa della terra, e i miei carcerieri, i giganti, mi hanno intrappolata nelle profondità delle Arathi Highlands. Questi frammenti di cristallo sono l'unico modo che ho per parlare con il mondo di superficie.$B$BTi prego, aiutami. I Coboldi Drywhisker, alleati dei giganti, hanno un frammento come questo nella Gola dei Drywhisker, a est. Per alimentare il gruppo di frammenti, devi raccogliere dai coboldi i Grani di Myzrael e applicarli su di esso.$B$BTi supplico, $N, aiutami!",
  obj = "Raccogli 12 Mote of Myzrael, poi portali agli Iridescent Shards nella Gola dei Drywhisker.",
  progress = "Questo gruppo di frammenti somiglia molto ai Frammenti di Myzrael. Ma in loro non pulsa la stessa sensazione di sicurezza.",
  reward = "Ah! Hai attivato questi frammenti. Mi sento già più me stessa!$B$BMa ahimè, sono ancora lontana dall'essere libera...",
  en_title = "The Princess Trapped",
  en_obj = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.",
}
T[643] = {
  title = "Sigillo di Arathor",
  desc = "Anche se a malapena si può dire che controllino Stromgarde, figurarsi tutti gli Arathi Highlands, il principe umano fa trottare i resti della sua cavalleria per le campagne. Non capisco perché lo faccia, ma chi capisce come ragionano gli umani, eh?$B$BQualunque sia il suo motivo, la cosa più importante è che ha dato uno dei sigilli al Tenente Valorcall, il capo della loro cavalleria. Trovalo e riportami il suo sigillo.",
  obj = "Recupera il Sigil of Arathor e riportalo a Zengu, a Hammerfall.",
  progress = "Non sarà facile rintracciare Valorcall, $N. A cavallo copre grandi distanze in fretta. Ciononostante, il suo sigillo ci serve.",
  reward = "Perdere il capo della cavalleria sarà un duro colpo per i difensori di Stromgarde. Meglio ancora, significa che ci manca un solo sigillo per poter avere Trol'kalar tutta per noi.",
  en_title = "Sigil of Arathor",
  en_obj = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.",
}
T[644] = {
  title = "Sigillo di Trollbane",
  desc = "L'ultimo dei sigilli necessari per aprire la tomba di Thoras Trollbane lo custodisce di persona suo figlio. Vive nel cuore di Stromgarde, in una cappella dei quartieri in mano alla milizia. Il Principe Galen è ben protetto, ed è lui stesso un guerriero tutt'altro che scarso, quindi questo compito potrebbe rivelarsi molto difficile.",
  obj = "Uccidi Prince Galen Trollbane e porta il Sigil of Trollbane a Zengu, a Hammerfall.",
  progress = "Sei $Gtornato:tornata;, $N. La stirpe di Ignaeus Trollbane è spezzata?",
  reward = "Che giornata, $C. Il sangue di Trollbane non perseguiterà più la mia gente, e i sigilli necessari per prendere Trol'kalar sono in nostro possesso. Presto, molto presto, colpiremo gli odiati troll di Zul'Gurub.",
  en_title = "Sigil of Trollbane",
  en_obj = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.",
}
T[645] = {
  title = "Trol'kalar",
  desc = "Cos'è questo? Riuniti, i quattro sigilli si sono fusi in un unico sigillo. Non c'è dubbio che potrà spezzare le protezioni poste sulla tomba di Trollbane.$B$BI resti di Trollbane sono sepolti nel Santuario, dietro la cappella di Stromgarde. Recupera Trol'kalar.",
  obj = "Recupera Trol'kalar dalla tomba di Trollbane, a Stromgarde.",
  progress = "Le incisioni nella pietra sulla facciata della tomba di Trollbane corrispondono alle linee luminose del Sigillo di Ignaeus...",
  reward = "Mentre fai combaciare le linee sulla facciata della tomba di Trollbane con quelle luminose del Sigillo di Ignaeus, un lampo di luce consuma il Sigillo, e la leggendaria spada Trol'kalar si libera dalla stretta delle mani di pietra.",
  en_title = "Trol'kalar",
  en_obj = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.",
}
T[646] = {
  title = "Trol'kalar",
  desc = "La luce svanisce lentamente: la spada Trol'kalar, custodita in un fodero di pietra, è stata liberata.",
  obj = "Consegna Sheathed Trol'kalar a Zengu, a Hammerfall.",
  progress = "$N! Hai preso la spada?",
  reward = "Per generazioni le forze di Strom e di Arathor hanno devastato i troll. Ora la loro arma più potente è nelle nostre mani. Non avanzeremo più a passo di lumaca nelle foreste afose di Zul'Gurub.$B$BIl tuo aiuto è stato prezioso, $N, e i troll Darkspear ti sono debitori.$B$BMi assicurerò che la spada venga consegnata a Nimboya, a Grom'gol.",
  en_title = "Trol'kalar",
  en_obj = "Deliver Trol'kalar to Zengu in Hammerfall.",
}
T[647] = {
  title = "Il Torcibudella di MacKreel",
  desc = "Ieri sera ho alzato un po' troppo il gomito con il vecchio Torcibudella! Longbraid mi staccherebbe la testa se sapesse che sono crollato durante il turno di guardia.$B$BLa zucca mi fa un male cane. Mi è sembrato che una brigata intera di macchine d'assedio mi passasse sopra la testa, con tutto quel rimbombo.$B$BOh, guarda che ora! Avevo promesso al Mastro Birraio Bilger, a Southshore, che gli avrei ripagato il debito mandandogli un po' di Torcibudella.$B$BMa mancano solo 15 minuti alla scadenza! Gli porteresti questa partita, per favore? E sbrigati!",
  obj = "Porta MacKreel's Moonshine a Brewmeister Bilger, a Southshore.",
  progress = "Che mi racconti di bello, $R?",
  reward = "Ah, niente di meglio del Torcibudella di Foggy MacKreel per scaldarsi in una giornata fredda! E io che pensavo che quel furfantello sarebbe stato di nuovo in ritardo con i pagamenti. Grazie, $Gamico:amica;! Grazie mille davvero!",
  en_title = "MacKreel's Moonshine",
  en_obj = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.",
}
T[648] = {
  title = "Salva OOX-17/TN!",
  desc = "La voce dello gnomo gracchia ancora una volta dal robot:$B$B\"Devo spostare OOX-17/TN in un posto aperto e sicuro, così potrà iniziare una lunga procedura di decollo. Ha un sistema di occultamento integrato, ma da qui mi serve tempo per rimetterlo in funzione. Ho bisogno che tu scorti il robot da dove si trova adesso fino, diciamo, al Porto di Steamwheedle! Dovrebbe essere il posto perfetto, e la strada abbastanza lunga, per rimettere tutto in funzione!\"$B$B\"Scortalo sano e salvo fino al porto, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — chiudo!\"",
  obj = "Scorta OOX-17/TN fino a Steamwheedle Port, poi presentati da Oglethorpe Obnoticus a Booty Bay.",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-17/TN! Non so nemmeno da dove cominciare per ringraziarti del tuo aiuto! La mia serie di robot viaggiatori ha bisogno di altri sviluppi, ma recuperandolo mi hai risparmiato innumerevoli ore di ricostruzione, oltre a molte monete d'oro in costi di ricablaggio!$B$BTi prego, scegli pure uno di questi oggetti che ho qui. Spero che ne farai buon uso. Grazie ancora del tuo generoso aiuto, io e i miei robot ti siamo debitori!",
}
T[649] = {
  title = "Recupero del Vino",
  desc = "Ho del lavoro di recupero per te, e se sei $Gun appassionato:un'appassionata; del buon vino come me, allora adorerai questo compito. Vino!$B$BÈ roba da bere, $Gscemo:scema;.$B$BIn un avamposto abbandonato dell'Orda c'è una scorta di Vino Dolce degli Hinterlands di quando erano ancora in attività. Non si trova più del vino così buono in giro! Uno degli sciocchi soci di Malton sa come si fa, quindi andrai là fuori e mi porterai una cassa di vino confezionato, e altre due per la mia collezione personale! Parla con Malton, ti spiegherà tutti i dettagli.",
  obj = "Parla con Malton Droffers, a Orgrimmar.",
  reward = "Ah già, il vino che vuole papà! Vuole venderlo a una taverna qui a Orgrimmar, ma ci faremo più soldi se è nella sua confezione originale. Conosco uno che può fare il lavoro, e sta negli Hinterlands, dove c'è il vino. Però è, ehm, un alto elfo.$B$BBe', è un alto elfo buono, visto che non fa parte dell'Alleanza. Be', più che un alto elfo buono è un alto elfo ubriaco. Adora, ma proprio ADORA l'alcol.",
}
T[650] = {
  title = "Recupero del Vino",
  desc = "L'elfo con cui devi parlare è Gilveradin Sunchaser. Riconosce qualsiasi vino, annata compresa, solo dall'odore! Può confezionare il vino che ci serve, quindi dovrai parlare con lui. Ci servono sei bottiglie da confezionare, due per papà, e quante ne vorrà lui... e credimi, ne vorrà. Quando avrai confezionato il vino e preso le due bottiglie di papà, torna qui!$B$BL'accampamento di Gilveradin è vicino a un qualche rifugio degli alti elfi negli Hinterlands, e quegli alti elfi non sono buoni. Fidati.",
  obj = "Parla con Gilveradin Sunchaser; il suo accampamento si trova negli Hinterlands.",
  reward = "Ah, dunque conosci Malton? È un mio vecchio compagno di bevute. Vedi, ho trovato qualcosa che va oltre i confini di trattati e alleanze artificiali — l'alcol. Se tutti placassimo la nostra sete con le sue beate virtù, staremmo tutti molto meglio nello spirito.$B$BAhimè, qualcosa mi dice che non sei qui in visita per conoscere le virtù redentrici dell'alcol, o sbaglio.",
}
T[651] = {
  title = "Pietre del Legame",
  desc = "Quattro Pietre del Vincolo sono sparse per Arathi. Queste pietre mi tengono inchiodata sotto terra.$B$BPer sbloccarle devi sbloccare la più forte: la Pietra del Vincolo Interno. E per farlo devi raccogliere le chiavi dalle altre tre.$B$BQueste pietre sono sorvegliate da guardiani, ma se sei $Gastuto:astuta;, o $Gfortunato:fortunata;, potresti trovare il modo di scacciarli.",
  obj = "Raccogli la Burning Key, la Cresting Key e la Thundering Key dalla Stone of West Binding, dalla Stone of East Binding e dalla Stone of Outer Binding.$B$BPortale alla Stone of Inner Binding.",
  progress = "Questa è la Pietra del Vincolo Interno. È la più forte delle pietre del vincolo, e va sbloccata perché le altre si aprano.",
  reward = "<Myzrael parla attraverso la pietra.>$B$BCe l'hai fatta! Hai aperto le Pietre del Vincolo! Sento allentarsi le catene che mi stringono, e la libertà si fa sempre più vicina.$B$BSei $Gun nobile:una nobile; $C, $N. $GIl mio salvatore:La mia salvatrice;!",
  en_title = "Stones of Binding",
  en_obj = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.$B$BBring them to the Stone of Inner Binding.",
}
T[652] = {
  title = "Spezzare la Chiave di Volta",
  desc = "Aprire le Pietre del Vincolo ha allentato molto la mia prigionia, ma una serratura mi tiene ancora in catene. È la Chiave di Volta che vedi in questo cerchio di pietre. E la chiave è in mano a uno dei miei carcerieri, il guardiano di pietra Fozruk.$B$BDevi prendere a Fozruk quella chiave, che i guardiani di pietra chiamano Verga dell'Ordine, e usarla per aprire la Chiave di Volta.$B$B$N, hai fatto così tanto per aiutarmi. Ancora un piccolo sforzo... e la mia gratitudine scuoterà le fondamenta stesse della terra!",
  obj = "Trova e uccidi Fozruk. Porta il Rod of Order alla Keystone, nelle Arathi Highlands.",
  progress = "La Chiave di Volta è carica di un'enorme energia geomantica.",
  reward = "Inserisci la verga nella chiave di volta. E sotto di te si avverte un fremito...",
  en_title = "Breaking the Keystone",
  en_obj = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.",
}
T[653] = {
  title = "Gli Alleati di Myzrael",
  desc = "<Myzrael parla.>$B$BLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.$B$BMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.$B$BParla con Gerrig Bonegrip. Si trova a Ironforge, in una bottega della Caverna Sperduta. Lui sa come evocarmi.",
  obj = "Parla con Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.",
  reward = "La Signora mi ha annunciato il tuo arrivo, $C. Sei $Gil benvenuto:la benvenuta; nella mia dimora, perché tu, come me, servi una causa più alta.",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[654] = {
  title = "Campionamento sul Campo a Tanaris",
  desc = "Appena attivi la fonte di energia, il kit per le analisi sul campo comincia a brillare e a vibrare. A quanto pare funziona come previsto.$B$BStando all'Ingegnere Capo Bilgewhizzle, ora hai due ore per raccogliere nel deserto di Tanaris i dati che ti servono. Se non li raccogli entro due ore, tutti i dati andranno persi e dovrai comprare da lui un'altra fonte di energia.$B$BTorna da lui quando avrai portato a termine il compito.",
  obj = "Procurati campioni accettabili di 8 basilischi, 8 iene e 8 scorpioni. Riporta il Field Testing Kit a Chief Engineer Bilgewhizzle a Gadgetzan prima che la fonte di energia si esaurisca.",
  progress = "Allora, hai preso tutto quello che ti serviva? Se non ce l'hai fatta e l'energia si esaurisce, tutto quello che c'è dentro sarà da buttare e dovrai ricominciare da capo.$B$BEhi, non aspettarti comprensione da me; a me importa solo che la Gadgetzan Water Company faccia profitti, e se questo vuol dire venderti fonti di energia finché non potremo permetterci di importare l'acqua dalle sorgenti gelide di Dun Morogh, così sia!",
  reward = "Va bene allora, mi ci vorrà solo un secondo per togliere la fonte di energia. Dopo, del kit potrai fare quello che ti pare, senza più doverti preoccupare di perdere i dati che contiene.",
}
T[655] = {
  title = "Hammerfall",
  desc = "Lo vedo ancora chiaro, come fosse ieri... Tanti anni senza speranza, con legno e acciaio a legarmi a questo luogo terribile. Poi finalmente, finalmente! Ecco il Capoguerra. Doomhammer nella sua armatura color mezzanotte, il martello da guerra alzato al cielo.$B$BFu... troppo terribile... Che il colpo di un codardo abbattesse il nostro più grande eroe. Lo caricò alle spalle a cavallo, e poi la sua lancia lo trafisse... Caddi in ginocchio. Che speranza c'era? Che speranza c'è...",
  obj = "Parla con Tor'gan, a Hammerfall.",
  reward = "Ah, parli di Gor'mul. Sì, da quello che dice, pare che non si sia mai ripreso dalla morte di Doomhammer.$B$BGor'mul era prigioniero qui quando Thrall e Orgrim combatterono per liberare il campo, ma mentre la terra tremava e i nostri fratelli fuggivano, lui fu lasciato indietro. Ha vagato da solo e smarrito per anni, senza meta né speranza, finché non siamo tornati a stabilirci qui a Hammerfall.",
  en_title = "Hammerfall",
  en_obj = "Speak with Tor'gan in Hammerfall.",
}
T[656] = {
  title = "Evocare la Principessa",
  desc = "Devi sconfiggere Myzrael prima che diventi più forte. Altrimenti, quando avrà raccolto abbastanza potere, sfiderà i suoi carcerieri! C'è chi pensa di poterla controllare, ma se si può controllare, perché mai i giganti l'avrebbero incatenata??$B$BLogica da pazzi, eh?$B$BPer sconfiggerla, evocala ai Frammenti di Myzrael, dove le hai parlato la prima volta. Sconfiggila e raccogli le sue Catene Oniriche, poi legale ai Frammenti di Myzrael.$B$BFallo, e sarà di nuovo intrappolata.",
  obj = "Va' agli Shards of Myzrael, evocala e sconfiggila.$B$BRaccogli le sue Eldritch Shackles e legale agli Shards of Myzrael.",
  progress = "I Frammenti di Myzrael ora sono stranamente silenziosi.",
  reward = "Mentre le catene arcane vengono poste intorno ai Frammenti, dal profondo si leva un lamento disumano. All'urlo segue un ruggito.$B$BI Frammenti di Myzrael non suscitano più il senso di calore e di sicurezza di un tempo. Ora pulsano di una minaccia aperta... come se la cosa sotto di loro nutrisse rancore verso la superficie.",
  en_title = "Summoning the Princess",
  en_obj = "Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.",
}
T[657] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "<Quae comincia a sfogliare la cartella.>$B$BQuesto sì che è interessante. Pare che lo Speziale Jorell stia lavorando a esperimenti letali qui a Go'Shek. Non so cosa c'entri con Hillsbrad, ma a Phin non piacerebbe se lo lasciassimo continuare.$B$BAbbiamo avuto uno scontro con degli orchi mentre eri via, e non sono in condizioni di aiutare Kinelory. Se te la senti, le servirà protezione quando scenderà alla fattoria a rubare tutte le ricerche che Jorell non ha ancora mandato a Tarren Mill.",
  obj = "Parla con Kinelory.",
  reward = "Se questo dà pace a Phin, distruggerò ogni singolo Reietto di persona. Ha fatto tanto per noi dopo la piaga. Non avremmo mai pensato di ritrovare amici o famiglia.$B$BQuando sei $Gpronto:pronta;, fammelo sapere. Cominciamo subito.",
  en_title = "Hints of a New Plague?",
  en_obj = "Speak to Kinelory.",
}
T[658] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "Allora, Phin ti ha mandato a controllare come stiamo? Non mi sorprende — si preoccupa troppo.$B$BTeniamo d'occhio la fattoria da giorni, e Kin sostiene di aver visto un corriere uscire da quella casetta a sud non molto tempo fa.$B$BParla tanto, ma quando siamo in zone pericolose mi fido sempre del suo fiuto.$B$BNon è che per caso sei $Gbravo:brava; a seguire le tracce? Crediamo che il corriere stia portando appunti a Tarren Mill. Se riuscissimo a mettere le mani su quei documenti, forse capiremmo qualcosa di quel che sta succedendo a Hillsbrad.",
  obj = "Trova la Forsaken Courier e porta il suo Sealed Folder a Quae, vicino alla Fattoria di Go'Shek.",
  progress = "Grazie dell'aiuto nella ricerca di quel corriere, $N.$B$BMentre eri via, Kin ha visto uno speziale uscire dalla stessa casa qui a sud. Sono convinta che stiano tramando qualcosa — mi serve solo una prova prima che facciamo qualche colpo di testa.$B$BHai avuto fortuna?",
  reward = "Ottimo!$B$BVediamo di cosa si tratta...",
  en_title = "Hints of a New Plague?",
  en_obj = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.",
}
T[659] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "Salve, e ben $Gincontrato:incontrata;, $N. Guido un gruppo di avventurieri che indaga su strani fatti in questa zona.$B$BMio cugino, a Hillsbrad, ha dovuto abbattere di recente il suo cane Stanley perché l'animale era cresciuto misteriosamente fino a diventare enorme e attaccava con ferocia chiunque gli si avvicinasse.$B$BCredo che di mezzo ci siano i non morti, e stiamo cercando prove che lo dimostrino.$B$BDue miei compagni, Quae e Kinelory, sono andati alla Fattoria di Go'Shek, nelle Arathi Highlands, e non si fanno vivi da giorni. Me li trovi? Comincio a preoccuparmi.",
  obj = "Trova Quae e Kinelory vicino alla Fattoria di Go'Shek, nelle Arathi Highlands.",
  reward = "Cerca di fare meno rumore possibile, $Gviaggiatore:viaggiatrice;.$B$BGli orchi non la prendono bene quando li si spia, e in questa fattoria c'è più di quel che sembra.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.",
}
T[660] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "Bene, $N. Io sono pronta, se lo sei tu.$B$BAndiamo?",
  obj = "Proteggi Kinelory finché non torna da Quae.",
  progress = "Il tempo delle chiacchiere è finito. Proteggi Kinelory, se ti importa qualcosa della gente di Hillsbrad.",
  reward = "Ci hai reso un grande servizio, $N. Grazie.$B$BSpero che Kin non ti abbia dato troppi grattacapi laggiù. È molto amichevole, ma sa essere altrettanto letale quando le sei $Gnemico:nemica;.",
  en_title = "Hints of a New Plague?",
  en_obj = "Protect Kinelory until she returns to Quae.",
}
T[661] = {
  title = "Indizi di una Nuova Piaga?",
  desc = "Ho visto Kinelory ridotta molto peggio di così dopo una notte in taverna. Si vede che l'hai protetta bene.$B$BQueste cose che ha riportato dalla fattoria dovrebbero almeno dare a Phin un'idea di quel che sta succedendo qui in Arathi. Giusto per essere sicuri che non ci siano rappresaglie dopo il vostro attacco, ci fermeremo qui ancora un po'. Te la sentiresti di tornare a Southshore e parlare con Phin?",
  obj = "Trova Phin Odelic, a Southshore.",
  reward = "Allora, i due piantagrane stanno bene dopotutto? Ahah, sono contento di saperlo. Ti ringrazio per avermi portato notizie di dove sono e di come stanno — mi fa molto piacere che siano ancora vivi; come amici e compagni di viaggio quei due sono insostituibili.$B$BMa... è più importante ringraziarti come si deve per il tuo aiuto. Tieni. Prendi questo, insieme ai ringraziamenti del mio gruppo.$B$BCon un po' di fortuna capiremo cosa stanno combinando i Reietti e metteremo fine a tutto questo.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Phin Odelic in Southshore.",
}
T[662] = {
  title = "Recupero in Acque Profonde",
  desc = "O'Breen ha guidato le navi nella baia. Eravamo certi che il tesoro si trovasse qui. La Harbinger ha attraccato senza problemi, ma mentre la Maiden's Folly e la Spirit of Silverpine si avvicinavano, la marea ha cominciato ad abbassarsi. La cosa più strana che abbia mai visto!$B$BQuelle due navi si sono arenate contro qualcosa... una specie di tempio nella scogliera. Sono affondate così in fretta, è stata una vera tragedia.$B$BPrima di partire dobbiamo recuperare i loro Diari di bordo e le loro Carte nautiche. Non possiamo lasciare quelle informazioni a occhi indiscreti!",
  obj = "First Mate Nilzlix vuole che tu recuperi le Carte nautiche e i Diari di bordo della Maiden's Folly e della Spirit of Silverpine.",
  progress = "Come va la missione di ricerca e recupero, $N? Dobbiamo proprio riavere quei Diari di bordo e quelle Carte nautiche della Maiden's Folly e della Spirit of Silverpine.$B$BSe le informazioni di quelle fonti cadessero in mano al nemico, il Comandante della Flotta Seahorn ci farebbe camminare sull'asse.$B$BSempre che riusciamo a uscire da questo pasticcio...",
  reward = "Sapere che queste informazioni sono al sicuro darà un po' di sollievo al comando di Booty Bay. Ben fatto, $N.",
  en_title = "Deep Sea Salvage",
  en_obj = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.",
}
T[663] = {
  title = "Terra in Vista!",
  desc = "Lolo vede $Gun piccolo:una piccola; $R! Sempre di vedetta, Lolo è!$B$B$GBenvenuto:Benvenuta; alla Baia di Faldir. Il Capitano O'Breen ha detto che saremmo rimasti qui solo poche ore. Giusto il tempo di recuperare il tesoro e tornare a Booty Bay.$B$BMa Lolo pensa che resteremo qui molto più a lungo. Abbiamo perso le altre due navi della nostra formazione. Povera Spirit of Silverpine, povera Maiden's Folly. In fondo al mare ora riposano!$B$BLolo ti consiglia di parlare con il Capitano O'Breen, se pensi di fermarti da queste parti.",
  obj = "Parla con Captain O'Breen, alla Baia di Faldir.",
  reward = "Ahoy, $Gcompagno:compagna;.$B$BÈ stato un disastro terribile. Seahorn mi toglierà la nave, se scopre cos'è successo.$B$BUno degli aggeggi del Professore indicava che il tesoro perduto era vicino a questa baia. Ho portato la Harbinger all'attracco e ho fatto segno alla Spirit of Silverpine e alla Maiden's Folly di fare lo stesso.$B$BPoi il mare ha brontolato. La marea si è abbassata e le due navi si sono schiantate contro la scogliera.$B$BNon è solo una scogliera. Laggiù c'è qualcosa...$B$BAiuta il mio equipaggio e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Land Ho!",
  en_obj = "Talk to Captain O'Breen in Faldir's Cove.",
}
T[664] = {
  title = "Dispiaceri Affogati",
  desc = "Argh, che vita orribile. Adesso dovrei trovarmi in una tomba d'acqua, non seduto qui accanto al fuoco a respirare aria fresca.$B$BL'equipaggio ha fatto di tutto per salvare la mia bella Maiden's Folly. Benedetti ragazzi, anime buone.$B$BO'Breen è arrivato a riva sano e salvo, ma noi non siamo stati così fortunati. Il mare ci è crollato sotto, lo giuro.$B$BUn attimo prima galleggiamo e un attimo dopo l'acqua entra a fiotti. E quelle bestie! Hanno ucciso tutti i sopravvissuti. Orribile feccia naga. Ho perso i sensi e mi sono ritrovato qui, salvo.$B$BVoglio vedere quelle bestie morte.",
  obj = "Captain Steelgut, alla Baia di Faldir, vuole che tu uccida 10 Daggerspine Raider e 3 Daggerspine Sorceress.",
  progress = "Bah, forse dovrei andare io stesso a uccidere quella feccia naga. È evidente che tu non lo farai.$B$BForse posso trovarti dei ferri da maglia, così hai qualcosa da fare.",
  reward = "Bel lavoro là fuori, $N.$B$BQuella feccia ha avuto quello che si meritava. Anche se niente mi restituirà la mia nave o il mio equipaggio, la morte di quei naga mi dà un po' di conforto.",
  en_title = "Drowned Sorrows",
  en_obj = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.",
}
T[665] = {
  title = "Tesoro Sommerso",
  desc = "Ora che siamo Blackwater Raiders a tutti gli effetti, è nostro compito aiutare il signor O'Breen a trovare il tesoro elfico perduto.$B$BÈ quasi impossibile trovare le gemme nel buio del mare senza aiuto. Il dottore ha costruito degli occhialini che serviranno allo scopo. Ha bisogno che vengano caricati con l'energia della pietra incantata che si trova nella grotta, appena su per la collina.$B$BMa la grotta è maledetta! Quando ci avviciniamo, ci tendono un'imboscata. Difendimi e riuscirò a imbrigliare negli occhialini l'energia della pietra.",
  obj = "Scorta Professor Phizzlethorpe alla grotta e riportalo indietro.",
  progress = "Non è il momento di chiacchierare! Gli occhialini devono essere caricati con il potere della pietra!",
  reward = "Adesso gli occhialini funzionano alla perfezione! Ben fatto, $N.",
  en_title = "Sunken Treasure",
  en_obj = "Escort Professor Phizzlethorpe to the cave and back.",
}
T[666] = {
  title = "Tesoro Sommerso",
  desc = "Il tesoro è rimasto sul fondo del mare così a lungo che le gemme si sono calcificate in una spessa pietra. Ma il potere racchiuso in questi occhialini ti permetterà di trovarle facilmente.$B$BUn pizzico di ingegno gnomesco fa miracoli!$B$BQuindi prendi in prestito gli Occhialini della Caccia alle Gemme, $N, e vedi se riesci a raccogliere un po' del tesoro perduto per il Capitano O'Breen.$B$BCi andrei a nuoto io stesso, ma... ehm... be', ho importanti faccende scientifiche da sbrigare quassù, sulla terraferma sicura e asciutta... ehm, sì.",
  obj = "Doctor Draxlegauge, alla Baia di Faldir, vuole che tu raccolga 10 Elven Gem e che restituisca i Goggles of Gem Hunting quando hai finito.",
  progress = "Come sono andati gli occhialini? Ha funzionato tutto a dovere? Se serve, si possono fare delle regolazioni.$B$BAh, e quando hai finito mi servono indietro quegli occhialini. Sono sicuro che il Capitano O'Breen troverà molti modi di usarli più avanti.",
  reward = "Magnifico, $N! Il Capitano sarà molto contento! E aspetta che la notizia arrivi al Comandante della Flotta Seahorn!",
  en_title = "Sunken Treasure",
  en_obj = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.",
}
T[667] = {
  title = "Morte dal Profondo",
  desc = "Si mette male. Sembra che i Daggerspine si stiano radunando per un attacco.$B$BI naga sono noti per la loro spietatezza in battaglia. Continueranno ad attaccare finché non sarò morto.$B$BNon considero la mia vita più preziosa di quella dei miei uomini, ma devi aiutarmi a difendermi. L'equipaggio non riuscirà a tornare a Booty Bay senza la mia conoscenza dei mari.$B$BI naga arriveranno dal mare. Ho bisogno che resti quassù con me a respingere l'attacco. Mettiti al cannone e ricacciali indietro.$B$BSei $Gpronto:pronta;, $N?",
  obj = "Proteggi Shakes O'Breen durante l'attacco.",
  reward = "Siamo sopravvissuti all'attacco!$B$BNon ce l'avremmo mai fatta senza di te, $N.$B$BSalperemo appena la marea salirà. Se non fossi $Gun eroe:un'eroina; così promettente, ti offrirei un posto nel mio equipaggio. Ma vedo che hai cose più grosse a cui pensare.$B$BAnche se sei $Gun:una; $R $Gmingherlino:mingherlina;...",
  en_title = "Death From Below",
  en_obj = "Protect Shakes O'Breen during the attack.",
}
T[668] = {
  title = "Tesoro Sommerso",
  desc = "Non facciamo aspettare il Capitano O'Breen. Vorrà vedere queste gemme con i suoi occhi. Dopotutto, è per questo che siamo qui!$B$BE dopo qualche settimana passata in compagnia di questi pirati, io e il professore ci siamo resi conto che la cosa peggiore per la nostra salute è farci trovare con il loro tesoro in mano.$B$BTieni, $N, portale a O'Breen.",
  obj = "Porta le Elven Gems a Captain O'Breen.",
  progress = "Ahoy, $C. Cosa ti porta sul ponte di comando?",
  reward = "Allora quei piccoli gnomi si sono dimostrati utili, dopotutto? Lo sapevo che c'era un motivo per tenerci intorno quei mezzi tappi!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Elven Gems to Captain O'Breen.",
}
T[669] = {
  title = "Tesoro Sommerso",
  desc = "Il Comandante della Flotta Seahorn vorrà sapere subito della nostra scoperta.$B$BMa come vedi, non siamo nella posizione di andarcene da qui. Non solo la marea è troppo bassa, ma quelle maledette creature che abbiamo disturbato tengono d'occhio ogni nostro movimento.$B$BPuoi rendere un grande servizio ai Blackwater Raiders se riesci a far sapere al Comandante della Flotta Seahorn, a Booty Bay, che abbiamo scoperto il tesoro e che stiamo lavorando per recuperarne altro. Portagli questo campione come prova.",
  obj = "Porta il Sample Elven Gem a Fleet Master Seahorn, a Booty Bay.",
  progress = "Cosa ti porta a Booty Bay, $C?",
  reward = "Ah, ci si può sempre fidare del buon vecchio Shakes O'Breen! Sapevo che era il Capitano giusto per la missione!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.",
}
T[670] = {
  title = "Tesoro Sommerso",
  desc = "Ehi, $N, mi sembri il tipo avventuroso. La mia flotta è bloccata a Booty Bay finché non riusciamo a rifornirci.$B$BQui e altrove bollono in pentola cose grosse, e devo far arrivare della corrispondenza segretissima a Shakes O'Breen, che è bloccato al largo della costa di Arathi.$B$BPosso fidarmi di te per consegnare questo messaggio al sicuro e in tutta riservatezza?",
  obj = "Consegna Seahorn's Sealed Letter a Shakes O'Breen, negli Arathi Highlands.",
  progress = "Allora, Seahorn è rimasto colpito? Scommetto che il suo sorriso andava da Booty Bay fino a Ratchet.",
  reward = "Grazie per aver affrontato un viaggio così lungo e pericoloso. I Blackwater Raiders ti sono grati.",
  en_title = "Sunken Treasure",
  en_obj = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.",
}
T[671] = {
  title = "Magie Immonde",
  desc = "Ho avvertito qualcosa di strano nell'aria... una sensazione che mi cova nel sangue. Avevo i miei sospetti. Sono partito per trovare l'origine del mio disagio e ho scoperto a ovest, nel Maniero di Northfold, le tracce residue di un'evocazione demoniaca. Man mano che mi avvicinavo, il sangue ha cominciato a ribollirmi e la rabbia dentro di me è cresciuta.$B$BA terra ho notato un amuleto di sanguinaria, che si usa per favorire le evocazioni demoniache. Quello che ho trovato però era esaurito. Me ne servirà un altro da esaminare, ma non oso tornare al maniero. Puoi portarmene qualcuno?",
  obj = "Procura 10 Bloodstone Amulet per Tor'gan, a Hammerfall.",
  progress = "Nelle mie vene scorre ancora sangue un tempo maledetto, $N. Se qualcuno... qualcosa sta evocando demoni, va fermato.",
  reward = "Mi ci vorrà un po' di tempo per accertare le vere intenzioni del Syndicate, ma il loro evidente legame con la magia oscura e demoniaca mi preoccupa. Ti farò sapere appena ne saprò di più.",
  en_title = "Foul Magics",
  en_obj = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.",
}
T[672] = {
  title = "Risollevare lo Spirito",
  desc = "Abbiamo cercato di farlo ambientare, di tirargli su il morale, raccontandogli della nostra potente città di Orgrimmar, a Kalimdor, ma niente riusciva a smuoverlo.$B$BRacconti del nostro giovane Capoguerra, Thrall, che porta l'armatura e il martello di Orgrim... ma forse... Forse! Una dimostrazione della magia sciamanica che abbiamo ritrovato da poco gli darebbe nuova speranza. Vale la pena tentare!$B$BUn piccolo oggetto che potremmo fare per lui, sì... Portami degli occhi di raptor, e vedrò cosa posso fare.",
  obj = "Procura 10 Highland Raptor Eye dagli Highland Strider e dagli Highland Thrasher per Tor'gan, a Hammerfall.",
  progress = "Creerò un amuleto che darà a Gor'mul un po' della forza dei raptor. Forse risveglierà una fiamma dentro di lui...",
  reward = "Eccellente. Gli spiriti dei raptor che hanno dato questi occhi presteranno la loro forza a chi porterà questo amuleto.",
  en_title = "Raising Spirits",
  en_obj = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.",
}
T[673] = {
  title = "Magie Immonde",
  desc = "Non ho dubbi che dentro le mura di Stromgarde viva un potente stregone. Di tanto in tanto, con una reliquia magica arcana, questo stregone evoca terribili demoni in gran numero. Dobbiamo eliminare la fonte del suo potere.$B$BTrova lo stregone e uccidilo. Portami qualunque oggetto magico gli trovi addosso, e farò in modo di distruggerlo e di impedire che il suo potere venga usato ancora per portare la corruzione in questa terra.",
  obj = "Recupera il Befouled Bloodstone Orb di Marez Cowl e portalo a Tor'gan, a Hammerfall.",
  progress = "Il bruciore nel mio sangue... cresce ogni giorno. Lo stregone va fermato.",
  reward = "Le mie notti inquiete diventeranno sonni tranquilli quando avrò distrutto questo globo. Grazie, $N. È un agghiacciante ricordo del terribile potere che i demoni avevano sugli orchi prima che Hellscream li liberasse dalla loro maledizione.",
  en_title = "Foul Magics",
  en_obj = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",
}
T[674] = {
  title = "Risollevare lo Spirito",
  desc = "Ecco, porta questo amuleto a Gor'mul, e vedi se la forza dei raptor riesce a risvegliare la fiamma del guerriero che un tempo gli ardeva nelle vene.",
  obj = "Dai il Raptor Talon Amulet a Gor'mul.",
  progress = "Che speranza c'è, quando la mano di un codardo può uccidere il più possente tra i possenti? Che speranza c'è, dimmelo tu!",
  reward = "Cos'è questo? Osso levigato. Che me ne faccio di un osso levigato? Un ninnolo riporterà l'Orda alla sua gloria?",
  en_title = "Raising Spirits",
  en_obj = "Give the Raptor Talon Amulet to Gor'mul.",
}
T[675] = {
  title = "Risollevare lo Spirito",
  desc = "<Gor'mul getta l'amuleto a terra.>$B$BTi ha mandato Tor'gan, vero? Pah! Non capisco perché provi pietà per me. La pietà mi è stata negata quando non mi è stato permesso di morire in battaglia con il mio Capoguerra. Che colpo crudele mi ha inflitto il destino...",
  obj = "Parla con Tor'gan.",
  reward = "Vedo che non ha funzionato. Eppure sento che, mostrandogli il potere degli sciamani, alla fine restituiremo a Gor'mul la fierezza di un tempo. L'amuleto non era abbastanza potente da mostrargli il nostro nuovo potere.",
  en_title = "Raising Spirits",
  en_obj = "Speak with Tor'gan.",
}
T[676] = {
  title = "Il Martello Potrebbe Cadere",
  desc = "Deboli... tutti quanti. Tu, $C, cos'hai da guardare? Ti credi $Gqualcuno di speciale:qualcuna di speciale;, eh? Perché non lo dimostri?$B$BL'avamposto di Hammerfall, in Arathi, è sotto attacco. Se non mandiamo aiuto presto, la loro fine è vicina.$B$BMa prima di correre via, forse ti conviene mettere alla prova le tue capacità. A nord-est di Stromgarde, in Arathi, c'è un tumulo di ogre abitato dalla tribù Boulderfist. Quando te la saprai cavare con gli ogre e gli scagnozzi che ci sono là, va' a rapporto da Drum Fel, a Hammerfall.",
  obj = "Uccidi 8 Boulderfist Ogre e 10 Boulderfist Enforcer, poi trova Drum Fel all'avamposto di Hammerfall, nelle Arathi Highlands.",
  progress = "Non ho tempo di affilare la mia ascia, figuriamoci di lasciare l'avamposto per uccidere quelle bestie che vogliono uccidere la mia gente.$B$BNon sembri avere l'esperienza di un soldato semplice, figuriamoci quella di $Gun vero e proprio:una vera e propria; $C. Cosa vuoi, $N?",
  reward = "Allora, ti credi abbastanza forte da aiutare Hammerfall? E sia.$B$BO Tallow ti ha mandato a quel tumulo di ogre sperando che ti facessi ammazzare, o ti crede abbastanza forte da aiutarci. In un modo o nell'altro adesso sei qui, e a me servono altri soldati nella lotta contro questi attacchi continui.$B$BSe hai intenzione di fermarti a Hammerfall, riposati e torna a parlarmi quando sei $Gpronto:pronta;. Di battaglie da combattere ce n'è in abbondanza.",
  en_title = "The Hammer May Fall",
  en_obj = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.",
}
T[677] = {
  title = "Chiamata alle Armi",
  desc = "I troll Witherbark e gli ogre Boulderfist di Arathi collaborano per cacciarci da questa terra, ma non cadremo per mano loro, né di nessun altro. Li uccideremo e mostreremo loro che anche noi abbiamo una casa qui.$B$BI troll ci hanno voltato le spalle; gli ogre ci userebbero come cibo e come giaciglio, se glielo permettessimo — tutto questo non accadrà.$B$BCominciamo attaccando i troll Witherbark a sud di qui. Fanne strage, e torna solo quando i loro accampamenti saranno intrisi di sangue.",
  obj = "Uccidi 10 Witherbark Axe Thrower, 10 Witherbark Headhunter e 8 Witherbark Witch Doctor, e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Se non hai ancora portato a termine il mio compito, forse sei $Gun vigliacco:una vigliacca; nell'animo, oltre che $Gun principiante:una principiante; in guerra.",
  reward = "I segni della guerra sono sui tuoi abiti, e il sudore ti gocciola dalla fronte. Bene, davvero molto bene.",
  en_title = "Call to Arms",
  en_obj = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.",
}
T[678] = {
  title = "Chiamata alle Armi",
  desc = "La tua forza è evidente, $N. Ora vediamo come te la cavi contro un vero nemico.$B$BI Boulderfist hanno una tana a sud-ovest di qui, verso il ponte dei nani, e, se non mi sbaglio, i picchiatori e i maghi che ci vivono saranno per te una sfida più grande — finora lo sono stati per noi.$B$BUccidine quanti più puoi e vieni da me in carne e ossa se ci riesci, o in spirito se fallisci. In entrambi i casi loderò la tua tenacia in battaglia.",
  obj = "Uccidi 10 Boulderfist Brute e 4 Boulderfist Magus, e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Esiti. Perché? Finora hai dimostrato grande forza, $N. Non deludermi proprio adesso.",
  reward = "Sei forte come un kodo, e la tua sete di battaglia fa onore al tuo popolo.",
  en_title = "Call to Arms",
  en_obj = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.",
}
T[679] = {
  title = "Chiamata alle Armi",
  desc = "La testa della bestia è pronta per essere mozzata... con grande forza, $N. Hai dato ogni prova di poterci aiutare a sferrare questo potente colpo finale. I capi di questi attacchi hanno fatto la loro tana tra le rovine di Stromgarde, simbolo lampante della fragilità umana.$B$BTrova e uccidi quei signori Boulderfist e i loro sciamani tirapiedi, che vorrebbero cacciarci da queste terre.",
  obj = "Uccidi 15 Boulderfist Shaman e 10 Boulderfist Lord e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Vedo che alla fine il tuo coraggio vacilla. A quanto pare il mio istinto su di te non sbagliava: la tua forza non è niente in confronto alla tua spavalderia.$B$BTorna da me quando la testa della bestia sarà stata mozzata, o non tornare mai più.",
  reward = "Fai onore al tuo popolo, $N. La minaccia si è molto ridotta, e sono certo che cominceremo a prosperare qui nelle Highlands.",
  en_title = "Call to Arms",
  en_obj = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.",
}
T[680] = {
  title = "La Vera Minaccia",
  desc = "Servi bene mio marito, $C, ma lui non sa perché Hammerfall è sotto attacco.$B$BOr'Kalar, la pedina di Mug'thol a Stromgarde, odia profondamente mio marito, che anni fa lo ha sconfitto, e non desidera altro che vederlo morto.$B$BLe mie divinazioni mi dicono che Or'Kalar ha teso una trappola a mio marito, perciò gli ho nascosto i segni della presenza dell'ogre.$B$BSe mio marito scoprisse dove si trova l'ogre, si precipiterebbe là come uno sciocco. Per questo vorrei chiederti di aiutarmi a uccidere la creatura.",
  obj = "Uccidi Or'Kalar e porta Or'Kalar's Head a Korin Fel, all'avamposto di Hammerfall.",
  progress = "Vicino alla Torre di Arathor — è lì che troverai Or'Kalar. La sua morte fermerà gli attacchi a Hammerfall e proteggerà la vita di mio marito.$B$BVedo nei tuoi occhi che mi credi debole — persino senza onore — per il mio silenzio. Un giorno imparerai cosa significa amare come amo io. Forse allora capirai che esiste un altro tipo di forza e di onore.$B$BNel frattempo, fa' come ti chiedo e uccidi Or'Kalar.",
  reward = "Mi hai reso un grande servizio, $N. Sappi che grazie alle tue azioni la vita di mio marito e la sicurezza di Hammerfall sono salve per un altro giorno. Ti prego, accetta questo come ricompensa per il tuo coraggio.",
  en_title = "The Real Threat",
  en_obj = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.",
}
T[681] = {
  title = "Maniero di Northfold",
  desc = "Stiamo combattendo una guerra per Stromgarde, e la stiamo perdendo. Gli ogre, il Syndicate e noi ci siamo spartiti la nostra città, un tempo grandiosa, e le fazioni si combattono fra loro in uno stallo sanguinoso.$B$BMa le nostre forze si assottigliano, mentre il nemico si fa più forte.$B$BCi serve aiuto dalla città di Southshore, ma è difficile ricevere rifornimenti finché il Syndicate controlla il territorio che ci separa.$B$BVa' alla base del Syndicate nel Maniero di Northfold e uccidili. Allora, forse, la pressione sui nostri convogli di rifornimenti diminuirà e ne arriveranno di più.",
  obj = "Uccidi 10 Syndicate Highwayman e 6 Syndicate Mercenary.$B$BTorna da Captain Nials, a Refuge Pointe.",
  progress = "$N, ogni ora che passa il nostro controllo su Stromgarde si fa più precario. Devi sbrigarti, o la nostra città cadrà di sicuro.",
  reward = "Molto bene, $N. Con la morte di quei membri del Syndicate dovremmo ricevere più facilmente i rifornimenti da Southshore.$B$BForse c'è ancora speranza per la nostra causa.",
  en_title = "Northfold Manor",
  en_obj = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.$B$BReturn to Captain Nials at Refuge Pointe.",
}
T[682] = {
  title = "Distintivi di Stromgarde",
  desc = "A Stromgarde il Syndicate combatte contro il nostro contingente di miliziani. Per spingere la marmaglia a battersi contro le nostre truppe, più disciplinate, i capi del Syndicate hanno messo una taglia sui nostri soldati: pagano in oro ogni Distintivo di Stromgarde preso ai miliziani uccisi.$B$BVogliamo recuperare quei distintivi — non possiamo permettere a quei tagliagole di strappare trofei ai nostri coraggiosi caduti!$B$BEntra nella zona di Stromgarde controllata dal Syndicate e dai loro la caccia per riprendere i nostri distintivi.",
  obj = "Porta gli Stromgarde Badge a Captain Nials, a Refuge Pointe.",
  progress = "Hai recuperato qualche Distintivo di Stromgarde, $N? Il Syndicate deve imparare che non può trarre profitto dai nostri morti.",
  reward = "Grazie, $N. Comunicheremo alle famiglie di questi soldati che i loro cari sono morti in battaglia.$B$BSarà una notizia dura da portare, ma è meglio che restare nell'incertezza per una persona cara scomparsa.",
  en_title = "Stromgarde Badges",
  en_obj = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.",
}
T[683] = {
  title = "La Supplica di Sara Balloo",
  desc = "$N, ho solo una piccola richiesta da farti.$B$BPorta questo biglietto che ho preparato al nostro grande sovrano di Ironforge, Re Magni Bronzebeard. È un compito da poco per una persona come te, che finora ha dato grandi prove di valore per la causa dell'Alleanza.$B$BPresentarmi davanti al Re nello stato di dolore in cui sono non gioverebbe alla mia causa. Sono certa che capisci.",
  obj = "Porta il biglietto di Sara Balloo a King Magni Bronzebeard, a Ironforge.",
  progress = "Quindi sei tu $N, $Gil:la; $C? Le notizie del tuo contributo all'Alleanza sono arrivate piuttosto lontano, lo sai?$B$BPer quale faccenda ti presenti oggi davanti a me?",
  reward = "Mi basterà un momento per scorrere questa lettera...",
  en_title = "Sara Balloo's Plea",
  en_obj = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.",
}
T[684] = {
  title = "Ricercata! Marez Cowl",
  desc = "È stata messa una taglia sulla testa di Marez Cowl, consigliera di alto rango e agente del Syndicate. È stata vista l'ultima volta nel territorio di Stromgarde controllato dal Syndicate.$B$BLa taglia si può riscuotere dalla Capitana Nials.$B$BAttenzione: Marez è una Strega abile e astuta, nota per i suoi traffici con i demoni. Si raccomanda la massima prudenza a chi le dà la caccia.",
  obj = "Porta Marez's Head a Captain Nials, a Refuge Pointe.",
  progress = "Salve, $C. Hai un rapporto da fare?",
  reward = "Hai abbattuto Marez Cowl? Ben fatto, $N. Davvero ben fatto!$B$BMarez minacciava i nostri difensori di Stromgarde, e si dice che facesse da tramite tra il Syndicate e un altro potere, più oscuro. Siamo lieti di sapere che non userà più i suoi poteri contro di noi.",
  en_title = "Wanted!  Marez Cowl",
  en_obj = "Bring Marez's head to Captain Nials at Refuge Pointe.",
}
T[685] = {
  title = "Ricercati! Otto e Falconcrest",
  desc = "La Stromgarde Militia ha messo una taglia sulla testa di Ser Falconcrest e della sua guardia del corpo, Otto. Falconcrest guida le operazioni del Syndicate nelle Arathi Highlands, e la sua morte le metterebbe in grave difficoltà.$B$BLa sua guardia del corpo, Otto, pur non essendo un obiettivo strategico, è un avversario feroce e ha ucciso decine dei nostri difensori.$B$BLe taglie si possono riscuotere dalla Capitana Nials.",
  obj = "Porta Otto's Head e Falconcrest's Head a Captain Nials, a Refuge Pointe.",
  progress = "Salve. Hai un rapporto da presentare?",
  reward = "Falconcrest e Otto? Magnifico!$B$BEcco la tua ricompensa, $N. La pago volentieri.",
  en_title = "Wanted!  Otto and Falconcrest",
  en_obj = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.",
}
T[686] = {
  title = "Il Tributo di un Re",
  desc = "Non mi aspetto che brave nane come la Signora Balloo capiscano perché gli orrori della guerra vadano sopportati per il bene più grande del nostro popolo. La perdita di suo marito, e quella di ogni nano che combatte nel nome dell'Alleanza, mi grava pesantemente sull'anima.$B$BNon posso riportare indietro suo marito dal Twisting Nether, ma posso rendergli omaggio.$B$BCommissionerò al Gran Scalpellino Marblesten un memoriale per Sully Balloo.$B$BVa' subito ad avvisarlo, $C. Il mio incarico è nelle tue mani.",
  obj = "King Magni Bronzebeard vuole che tu parli con Grand Mason Marblesten.",
  reward = "Quindi ti manda Re Magni Bronzebeard in persona?$B$BPerbacco! Dev'essere una cosa importante!",
  en_title = "A King's Tribute",
  en_obj = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.",
}
T[687] = {
  title = "Theldurin the Lost",
  desc = "Theldurin the Lost un tempo era un membro del nostro ordine, il Martello del Crepuscolo. Ma ha perso il senno e ha disprezzato i nostri insegnamenti. E prima di fuggire da noi, ha rubato la pergamena di Myzrael! Non siamo riusciti a prenderlo, ma si dice che si nasconda nei Badlands, farfugliando come un pazzo.$B$BPer riportare la Signora da noi, devi trovare la pergamena. E per farlo, devi trovare Theldurin.",
  obj = "Trova Theldurin the Lost.",
  reward = "Ciao. Ciao, ciao ciao ciao ciao CIAO!$B$BMi dispiace — un momento, no, non mi dispiace! Non essere scortese!$B$BOh no... questi erano discorsi da pazzo.$B$BMa... a volte essere pazzo è il mio unico conforto.",
  en_title = "Theldurin the Lost",
  en_obj = "Find Theldurin the Lost.",
}
T[688] = {
  title = "Gli Alleati di Myzrael",
  desc = "<Myzrael parla.>$B$BLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.$B$BMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.$B$BParla con Zaruk, a Hammerfall. Lui sa come evocarmi.",
  obj = "Parla con Zaruk, a Hammerfall.",
  reward = "$GBenvenuto:Benvenuta;, $C. La Signora mi ha informato del tuo arrivo, e se dobbiamo riportarla in superficie, abbiamo molto di cui parlare...",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Zaruk in Hammerfall.",
}
T[689] = {
  title = "Il Tributo di un Re",
  desc = "Quindi il nostro buon Re vuole un memoriale in onore di un soldato di nome Sully Balloo? E tu dici che il poveretto è morto durante la tragedia del Thandol Span?$B$BBah, ci sarà mai pace su Azeroth?$B$BComunque, ogni incarico del Re è della massima importanza. Per fare un'opera davvero epica e duratura voglio lavorare con una delle pietre migliori che ci siano. Va' alla Collina di Darrow, a Hillsbrad, e raccogli per me un po' di Granito d'Alterac.",
  obj = "Grand Mason Marblesten, a Ironforge, vuole 5 Alterac Granite.",
  progress = "$N, $N, $N! Dimmi che hai abbastanza Granito d'Alterac perché io possa cominciare il mio capolavoro in onore di Sully Balloo.",
  reward = "Perfetto! Meglio di quanto potessi immaginare!$B$BE di immaginazione ne ho parecchia, sai...",
  en_title = "A King's Tribute",
  en_obj = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.",
}
T[690] = {
  title = "La Richiesta di Malin",
  desc = "Salve, $N. Hai l'aria di $Gun avventuriero:un'avventuriera;, e io ho un compito di cui qualcuno deve occuparsi.$B$BL'Arcimago Trelane, il mio primo maestro, è fuggito da Stromgarde, nelle Arathi Highlands, non molto tempo fa, e mi ha chiesto di aiutarlo a recuperare alcune delle cose che ha lasciato lì.$B$BLa città è stata assediata e lui ha tentato di difendere la Torre di Arathor, ma invano. Ho già degli agenti nelle Highlands, ma mi hanno chiesto di mandare altro aiuto. Ti interessa?",
  obj = "Trova Skuerto a Refuge Pointe, nelle Arathi Highlands.",
  reward = "Allora, ti manda Malin? Non m'importa neanche se Muradin è risorto dai morti e t'ha portato qui di volata su un drago. Ho da fare! Se ti serve qualcosa, parla con Kryten.",
  en_title = "Malin's Request",
  en_obj = "Find Skuerto at Refuge Pointe in the Arathi Highlands.",
}
T[691] = {
  title = "Vale Tanto Oro Quanto Pesa",
  desc = "L'Arcimago Malin ha mandato qui me e Skuerto a raccogliere reagenti per lui. Non sapevo proprio come avrei fatto a procurarmi queste cose, ma ora che sei qui credo che il mio problema sia risolto.$B$BEcco cosa mi serve: zanne dei Witherbark, sacche di medicine dei Witherbark e un coltello da cacciatore delle ombre.$B$BPotresti trovarmeli? I Witherbark vivono nel sud-est di Arathi.",
  obj = "Trova 10 Witherbark Tusk, 4 Witherbark Medicine Pouch e uno Shadow Hunter Knife per Apprentice Kryten, a Refuge Pointe.",
  progress = "Hai avuto fortuna finora, $N?$B$B<Kryten prende qualche appunto sul suo diario mentre legge.>$B$BSe le mie ricerche sono corrette, le zanne dovrebbero venire da qualunque troll Witherbark. Le sacche di medicine vengono dagli stregoni Witherbark, e i più forti tra i cacciatori delle ombre Witherbark dovrebbero portare il coltello speciale che ricevono dopo aver completato i riti di passaggio. Non c'è modo di sapere quali cacciatori delle ombre abbiano il coltello finché non li affronti.",
  reward = "Incredibile! Capisco perché Malin ti ha chiesto di unirti a noi — davvero un ottimo lavoro!$B$BDi questo passo, Skuerto e io torneremo a Stormwind in un attimo.$B$BCredo che il mio compagno nano sia tornato dalla ricognizione del Fortilizio dei Boulderfist; va' a parlargli quando sei $Gpronto:pronta;.$B$BSembrava che avesse avuto una piccola zuffa con gli ogre. Ma non dirglielo: è molto suscettibile alle critiche sulle sue capacità di esploratore.",
  en_title = "Worth Its Weight in Gold",
  en_obj = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.",
}
T[692] = {
  title = "I Frammenti Perduti",
  desc = "La Pergamena di Myzrael... la Pergamena di Myzrael?! Non ti conviene! La sua magia può trascinare Myzrael nel mondo di superficie, e se lo fai, siamo nei guai!$B$BOppure... forse è troppo tardi. Forse è già libera. Forse sta solo raccogliendo le forze prima di scatenarsi su di noi. Se è così, allora ti SERVIRÀ la pergamena!$B$B...peccato che sia distrutta. Degli elementali infuriati l'hanno rubata e fatta a pezzi, e ora si contendono i frammenti.$B$BMa se riesci a raccogliere quei frammenti, forse possiamo aggiustarla...",
  obj = "Porta il Torn Scroll Fragment, il Crumpled Scroll Fragment e il Singed Scroll Fragment a Theldurin the Lost.",
  progress = "Hai trovato quei frammenti?!?! Ti servirà la Pergamena di Myzrael se vuoi intrappolarla di nuovo, prima che sia troppo tardi!",
  reward = "Ah, li hai trovati! Ottimo lavoro, $N! Potrebbero essere l'unica possibilità che abbiamo contro la malvagità di Myzrael!$B$BFammi solo trovare il mio cricchetto per rattoppi e vedere se riesco a riattaccare questi frammenti...",
  en_title = "The Lost Fragments",
  en_obj = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.",
}
T[693] = {
  title = "Bacchetta in Pugno",
  desc = "Ehi, $N. Scusa se prima ho tagliato corto con te... e no, non è una battuta.$B$BHo scoperto dov'è finito il primo oggetto di Trelane: ce l'ha Kor'gresh, al Fortilizio dei Boulderfist. E da come tirava raffiche di ghiaccio ai suoi per tenerli in riga, dev'essere lì lì per capire come usarne tutti i poteri.$B$BIl Fortilizio dei Boulderfist è a sud di qui, e poi a est del Thandol Span. Trova l'ogre e riprenditi quella bacchetta.$B$BMentre sei via, vedo un po' cosa fare con Stromgarde.",
  obj = "Trova Trelane's Wand of Invocation e riportala a Skuerto, a Refuge Pointe.",
  progress = "Il nostro obiettivo è la bacchetta, $N. Per ora pensa solo a quella.",
  reward = "Magnifico, $N. Un oggetto recuperato, e secondo la mia lista ne mancano altri tre. Gli altri tre oggetti sono tutti a Stromgarde.$B$BRiposati e recupera le forze — la prossima fase del mio piano richiederà un po' più di tempo e di impegno. Torna da me dopo aver mangiato un pasto caldo e aver riposato un po'.",
  en_title = "Wand over Fist",
  en_obj = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.",
}
T[694] = {
  title = "Le Difese di Trelane",
  desc = "Ti sei $Griposato:riposata;?$B$BEcco il prossimo passo: ci sono ogre tutto intorno alla Torre di Arathor, a Stromgarde. Dovremo attivare le difese della torre, se vuoi avere una possibilità contro di loro e arrivare $Gvivo:viva; fino agli oggetti. Per farlo ci servono delle gemme a cui gli sciamani Boulderfist si sono affezionati. Le hanno prese dalla torre, ma non resteranno a lungo in mano loro.$B$BProcurati una di quelle gemme e portala a Kryten — conosce l'incantesimo che la farà funzionare come una chiave.",
  obj = "Trova un'Azure Agate e portala ad Apprentice Kryten, a Refuge Pointe.",
  progress = "$N, eccoti di nuovo. Hai già trovato un'agata azzurra?",
  reward = "Mi stupisci, $N. Ancora un ottimo lavoro.$B$BDammi un momento per lanciare sulla gemma l'incantesimo adatto, e sarai $Gpronto:pronta;.",
  en_title = "Trelane's Defenses",
  en_obj = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.",
}
T[695] = {
  title = "L'Incantesimo dell'Apprendista",
  desc = "Ecco a te, $N. Per attivare le difese della torre basta premere la gemma contro uno dei piedistalli vicino alla sua base. Usala quando sarai $Gpronto:pronta; a entrare nella torre per trovare gli altri oggetti di Trelane.$B$BBuona fortuna. Aspetterò il tuo ritorno qui all'accampamento. Ah, e parla con Skuerto prima di partire. Ti darà il resto dei dettagli che ti servono.",
  obj = "Parla con Skuerto.",
  reward = "Bene, bene.$B$BSe non ci sono altri ritardi, che ne dici di cominciare?",
  en_title = "An Apprentice's Enchantment",
  en_obj = "Speak to Skuerto.",
}
T[696] = {
  title = "Attacco alla Torre",
  desc = "Ecco cosa cerchi: il filatterio di Trelane, la sfera di Trelane e l'agata ardente di Trelane.$B$BTutti e tre dovrebbero trovarsi in alcuni forzieri dentro la torre, e non dovresti avere problemi ad aprirli da $Gsolo:sola;; devi solo fare attenzione agli ogre.$B$BLe difese della torre non li sistemeranno da sole: dovrai tenere le armi pronte. Se quegli ogre scoprono che sei lì a derubarli, te la faranno pagare cara.$B$BSta' $Gattento:attenta;, e buona fortuna.",
  obj = "Trova Trelane's Phylactery, Trelane's Orb e Trelane's Ember Agate, e riportali a Skuerto, a Refuge Pointe.",
  progress = "Fai questo, e sono sicuro che Malin sarà più che soddisfatto di te.",
  reward = "Malin non avrebbe potuto chiedere a una persona più degna di venire qui ad aiutarci, $N. Hai fatto un lavoro magnifico!$B$BSarà contento di vedere che la nostra missione è stata un successo travolgente.",
  en_title = "Attack on the Tower",
  en_obj = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.",
}
T[697] = {
  title = "La Richiesta di Malin",
  desc = "Porta questa lettera a Stormwind e fai sapere a Malin che Kryten e io torneremo presto a casa. Ti ricompenserà bene per averci aiutato qui, $N, non ne ho alcun dubbio.$B$BFa' buon viaggio.",
  obj = "Porta la Sealed Letter to Archmage Malin nel Mage Quarter di Stormwind.",
  progress = "Sì? Hai un'aria vagamente familiare. Chiedo scusa, ma ci siamo già conosciuti? Ho così tanto da fare che mi sfugge tutto.",
  reward = "<L'Arcimago Malin apre la lettera e sgrana gli occhi.>$B$BPer la Luce, ce l'hai fatta. Meraviglioso. Trelane sarà contentissimo. Di certo Kryten e Skuerto sono entusiasti quanto me all'idea che gli oggetti siano in viaggio verso Stormwind.$B$BGrazie, $N. Ti prego, prendi questo: ti aiuterà nei tuoi viaggi.",
  en_title = "Malin's Request",
  en_obj = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.",
}
T[698] = {
  title = "Scorte Insufficienti",
  desc = "Sto cercando di mettere insieme un po' di provviste per il nostro avamposto vicino alla spiaggia, a est — Tok'Kar fa quel che può, ma tra i turni di guardia e il cucinare per i suoi soldati non gli resta molto tempo durante il giorno.$B$BA loro piace cucinare un po' di carne di dentesega quando possono, ma non ho avuto tempo di mandargli un altro carico. Ti spiacerebbe dargli una mano?$B$BI dentesega giovani non sono saporiti come quelli più vecchi, quindi lasciali stare; dagli un anno o due per crescere del tutto.",
  obj = "Porta 8 Unprepared Sawtooth Flank a Tok'Kar, nella Swamp of Sorrows.",
  progress = "Lok'tar, $C. Attraversare le paludi non è un rischio da prendere alla leggera. Hai coraggio a metterti alla prova qui.",
  reward = "Ah! Magnifico. Carne fresca per il fuoco di stasera. Grazie, $N.$B$BHai reso le prossime notti più sopportabili. Il fuoco arde luminoso, e avremo la pancia piena.$B$BÈ una piacevole sorpresa che sia tu a portarci un carico; Dar non è l'orco più bello che si sia mai visto, ma almeno il suo carattere puzza molto meno del suo odore.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.",
}
T[699] = {
  title = "Scorte Insufficienti",
  desc = "Con la minaccia dei murloc lungo la costa, siamo di stanza qui per proteggere Stonard — o dare l'allarme, se le forze sono troppo grandi — da ogni minaccia in arrivo. Non ci lascia molto tempo per rilassarci, e un altro po' di aiuto ci farebbe comodo, se puoi.$B$BGli artigli dei lutiani dentesega, se preparati a dovere, diventano ottime armi. Portami un po' dei loro artigli, e farò in modo che tu venga $Gricompensato:ricompensata; con una delle nostre armi, per ringraziarti della carne fresca e della buona compagnia.",
  obj = "Porta 6 Sawtooth Snapper Claw a Tok'Kar, nella Swamp of Sorrows.",
  progress = "Buon idromele, un fuoco caldo, un esercito di orchi e un arsenale di armi... è tutto quello che ci serve davvero qui sulla costa. Non mi pento del mio posto qui a proteggere Stonard, ma sarebbe bello se un giorno potessimo avere una tana, o almeno una torre.",
  reward = "Mi fa piacere vederti $Gvivo:viva; e in salute, $N.$B$BQuesti artigli andranno benissimo. Più armi abbiamo pronte contro gli attacchi, meglio sarà per noi.$B$BMi metterò al lavoro sulla tua arma il prima possibile. Ci vorrà poco. Sono diventato piuttosto abile e veloce nel fabbricarle.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.",
}
T[700] = {
  title = "Il Tributo di un Re",
  desc = "Ah, che bella pietra viene da Lordaeron. Che peccato che quella terra sia così allo sfascio.$B$BMa il Memoriale è venuto proprio bene! Credo che il Re ne sarà molto soddisfatto.$B$BOra, per favore, fai sapere a Sua Maestà che il Memoriale è finito, come richiesto.",
  obj = "Fa' rapporto a King Magni Bronzebeard.",
  reward = "Il granito sembra ben poca cosa in confronto alla vita di un grande nano. Ma nessun nano durerà in eterno su questo pianeta.$B$BSperiamo soltanto che il memoriale resti a ricordo per chi calcherà la grande Azeroth del futuro. Non dimentichiamo che è per loro che soldati coraggiosi come Sully Balloo hanno dato la vita con tanto valore.",
  en_title = "A King's Tribute",
  en_obj = "Report to King Magni Bronzebeard.",
}
T[701] = {
  title = "L'Astuzia del Raptor",
  desc = "Con qualche altro oggetto potrò creare qualcosa che infonderà in Gor'mul l'astuzia del raptor! Con il potere del raptor che gli scorre dentro, Gor'mul conoscerà il nostro nuovo potere e riscoprirà il guerriero che dorme in lui!$B$BMi serviranno dei cuori di raptor per creare l'oggetto e l'incantesimo.",
  obj = "Procura 12 Raptor Heart dagli Highland Fleshstalker per Tor'gan.",
  progress = "Ho fatto tutti i preparativi: mi mancano solo i cuori di raptor.",
  reward = "Sì, questi andranno benissimo. Trasferirò il loro potere e lo spirito dei raptor in questo globo. Il globo infonderà in Gor'mul la forza ardente e l'intelligenza del raptor.",
  en_title = "Guile of the Raptor",
  en_obj = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.",
}
T[702] = {
  title = "L'Astuzia del Raptor",
  desc = "Prendi questo globo e usa la sua energia per dare a Gor'mul l'essenza del raptor. Di sicuro gli rinvigorirà lo spirito e darà un nuovo scopo alla sua vita. Quando sarà tornato quello di prima, potremo spiegargli come sta oggi l'Orda, e avremo l'aiuto di un grande guerriero nelle nostre battaglie senza fine.",
  obj = "Dai Tor'gan's Orb a Gor'mul.",
  progress = "Sei $Gtornato:tornata; di nuovo, eh? In effetti, ora non potrei desiderare niente di meglio che altra pietà da parte di Tor'gan.$B$BCosa mi porti stavolta? Un pezzo di spago dai colori vivaci, forse? O una corda per mettere fine a questa mia infelicità...",
  reward = "Almeno stavolta mi porti qualcosa di interessante. Emana uno strano potere...",
  en_title = "Guile of the Raptor",
  en_obj = "Give Tor'gan's Orb to Gor'mul.",
}
T[703] = {
  title = "Ali di Condor alla Griglia",
  desc = "Oh sì, le mie ali di condor alla griglia piacciono a tutti! La salsa è ricca e la carne è saporita. E il profumo farà accorrere gli affamati da miglia di distanza!$B$BHo tutto quello che mi serve per prepararne una bella scorta. Tutto... tranne le ali di condor!$B$BSe ne vuoi un po', procurami le ali di condor. Portamene abbastanza e magari ti darò anche la ricetta!",
  obj = "Porta 4 Buzzard Wing a Rigglefuzz.",
  progress = "Salve, $N. Mi hai portato le mie ali?",
  reward = "Ah, mi metto subito al lavoro su quelle ali. Mi sembra già di sentirne il sapore!$B$BEd ecco la ricetta, nel caso volessi prepararle da te!",
  en_title = "Barbecued Buzzard Wings",
  en_obj = "Bring 4 Buzzard Wings to Rigglefuzz.",
}
T[704] = {
  title = "La Sorte di Agmond",
  desc = "L'ultimo rapporto che ho ricevuto da Agmond è preoccupante, e ancora di più ora che è morto! Diceva che i suoi scavatori avevano portato alla luce delle \"urne antiche\" nel sito di scavo fuori Uldaman. Temo che le urne trovate in quel sito abbiano aizzato i trogg, proprio come gli idoli che ho trovato qui.$B$BMi servono quelle urne per i nostri studi. Va' al sito di Uldaman, raccogli le urne, poi torna da me.",
  obj = "Porta 4 Carved Stone Urn a Prospector Ironband, a Loch Modan.",
  progress = "Hai trovato quelle urne, $N? Dobbiamo scoprire il legame tra loro e i trogg!",
  reward = "Ben fatto! Con fortuna e diligenza scopriremo qualunque legame ci sia tra i trogg e questi antichi manufatti.$B$BHai reso un grande servizio ai Prospettori, $N. I tuoi sforzi non saranno dimenticati. E nemmeno Agmond.",
  en_title = "Agmond's Fate",
  en_obj = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.",
}
T[705] = {
  title = "A Caccia di Perle",
  desc = "I Badlands sono un posto duro, pieno di predatori feroci e di necrofagi sfrontati. Fa paura, soprattutto a un goblin piccolo e basso come me. Per sopravvivere devo essere furbo!$B$BConosco la ricetta delle bombe lampo. Le uso per mettere in fuga gli animali. Ma sto finendo uno degli ingredienti: la polvere di perle blu frantumate. Procuramene un po' e ti ripagherò della fatica.$B$BEh, e spero che tu abbia un buon paio di stivali. Le Perle Blu che mi servono si trovano nei molluschi della Scogliera Infame.$B$BGià, la Scogliera Infame, a Stranglethorn!",
  obj = "Porta 9 Blue Pearl a Rigglefuzz, nei Badlands.",
  progress = "Hai preso le mie perle? Sono quasi a corto di bombe lampo!",
  reward = "Andranno benissimo! Devo solo ridurle in polvere... poi mescolarle con un po' di questo e un po' di quello.$B$BAttenti, necrofagi! Preparatevi a restare accecati!",
  en_title = "Pearl Diving",
  en_obj = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.",
}
T[706] = {
  title = "Incantamenti di Fuoco Ardente",
  desc = "Come apprendista di Feranor Steeltoe, ho imparato la sua tecnica speciale per infondere nelle armi incantamenti di fuoco. L'ultima volta che ho avuto sue notizie, lavorava in una fucina con una compagnia di cacciatori, su a Lordaeron.$B$BNon posso dirti troppi dettagli sul procedimento, ma posso dirti che richiede il sangue del cuore ancora pulsante di un raro cucciolo di drago nero. Non ho molto da fare mentre aspetto notizie da Ironforge. Se mi porti il cuore di uno dei cuccioli della Piana di Lethlor, ti mostrerò la mia abilità!",
  obj = "Procura un Black Drake's Heart per Sigrun Ironhew.",
  progress = "Come va la caccia, $C?",
  reward = "Ah sì, questo andrà benissimo. Permetterà alle tue armi di colpire con un calore rovente!",
  en_title = "Fiery Blaze Enchantments",
  en_obj = "Acquire a Black Drake's Heart for Sigrun Ironhew.",
}
T[707] = {
  title = "Ironband Ha Bisogno di Te!",
  desc = "$N. Ho ricevuto rapporti dal Prospettore Ironband, dal suo sito di scavo a Loch Modan — gli serve qualcuno che si muova per un altro dei nostri scavi.$B$BNon ho altri dettagli, ma se hai voglia di sgranchirti le gambe va' a parlare con Ironband.",
  obj = "Parla con Prospector Ironband, agli Scavi di Ironband, a Loch Modan.",
  reward = "Quindi ti manda Stormpike, eh? Bene.$B$BHo un bel compito per te...",
  en_title = "Ironband Wants You!",
  en_obj = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.",
}
T[708] = {
  title = "La Scatola Nera",
  desc = "La superficie di questa scatola nera di metallo è tutta butterata, come se fosse stata immersa nell'acido — deve essere rimasta a lungo nello stomaco del condor gigante.$B$BRigirando la scatola, trovi un simbolo impresso sul fondo. Sotto il simbolo ci sono le parole:$B$B\"Macchina #19 — Ironforge Siege Brigade\"",
  obj = "Porta la Corroded Black Box a Hall of Arms, a Ironforge.",
  en_title = "The Black Box",
  en_obj = "Take the Corroded Black Box to the Hall of Arms in Ironforge.",
}
T[709] = {
  title = "Rimedio alla Sventura",
  desc = "Oh cielo! Oh cielo! Si avvicina una sventura. Ascoltami bene! Una sventura!$B$BNo, non posso parlarne... non posso pronunciare i loro nomi, o potrebbero sentirmi! Ma se scopriamo, sì, se scopriamo di più su di loro... allora forse possiamo capire come sventare i loro piani!$B$BForse.$B$BVa' a Uldaman. No! L'ho detto! Devi trovare... trovare la tavoletta di... Ryun'eh. Sì, trovala! E non farmi pronunciare di nuovo quel nome!$B$BÈ nel profondo di quel luogo, in un antico forziere. È lì che si nasconde... in un forziere costruito prima di qualunque opera dei nani.",
  obj = "Porta la Tablet of Ryun'eh a Theldurin the Lost.",
  progress = "Hai trovato la tavoletta? Deve contenere dei segreti! Segreti per salvarci!",
  reward = "Oh, la fortuna è dalla nostra! Grazie! Forse possiamo ancora salvarci!",
  en_title = "Solution to Doom",
  en_obj = "Bring the Tablet of Ryun'eh to Theldurin the Lost.",
}
T[710] = {
  title = "Studio degli Elementi: La Roccia",
  desc = "Qui nelle Badlands mi sono fermato a lavorare al mio ultimo progetto: i miei ceppi di vincolo elementale.$B$BUna volta completati, permetteranno ai maghi di evocare elementali ancora più potenti, da usare per compiti ancora più grandi. Per cominciare, mi servono dei piccoli frammenti di pietra per provare alcuni dei miei nuovi incantesimi offensivi e qualche aggeggio che ho assemblato.$B$BI frammenti si raccolgono facilmente dagli elementali minori della roccia, a ovest di qui. Potresti portarmene un po'?",
  obj = "Trova 10 Small Stone Shard e portali a Lotwil Veriatus, nelle Badlands.",
  progress = "Questa zona è perfetta per — Potresti tenermi fermi questi per un momento? Sì, proprio così, lungo la normale del vettore. Allora, cosa stavo... Ah, sì. Perfetta per provare il mio ultimo progetto. Le materie prime, lo spazio aperto... cosa potrebbe chiedere di più un praticante delle arti intelligente e illuminato?",
  reward = "Andranno benissimo, $N. Grazie. Mmh, un po' più di sabbia di quanto mi aspettassi. Dovrò correggere il coefficiente di attrito. No, aspetta; con l'olio del freddo dovrebbe restare comunque trascurabile.$B$B<Borbottando tra sé, Lotwil mette un pugno nel palmo dell'altra mano e li fissa come affascinato.>",
  en_title = "Study of the Elements: Rock",
  en_obj = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.",
}
T[711] = {
  title = "Studio degli Elementi: La Roccia",
  desc = "$N, ti sei già $Gdimostrato:dimostrata; più capace di tutti i miei apprendisti messi insieme.$B$BI prossimi pezzi che mi servono richiedono un po' più di forza. Se stai $Gattento:attenta;, puoi trovare dei grandi lastroni di pietra addosso agli elementali della roccia. Il loro corpo è più forte e più grande, e quindi è più facile che abbia pezzi abbastanza grandi per le mie prove. Li trovi più a ovest di qui, o a sud-est, lungo i margini delle montagne.$B$BFa' con calma; mi ci vorrà un po' per provare questi pezzi più piccoli che mi hai portato.",
  obj = "Porta 3 Large Stone Slab a Lotwil Veriatus, nelle Badlands.",
  progress = "Sono molto soddisfatto, $N. I miei incantesimi hanno agito sui pezzi più piccoli esattamente come avevo previsto. Se questo esperimento riuscirà come prevedo, gli elementali che potrò controllare faranno sfigurare qualunque cosa sia mai stata evocata prima.",
  reward = "$N, semplicemente incredibile! Avrei pensato che ci volesse mezza dozzina di tauren per portarmi tutta questa roba.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.",
}
T[712] = {
  title = "Studio degli Elementi: La Roccia",
  desc = "$N, mi serve un ultimo componente dagli elementali qui nelle Badlands: i bracciali vincolanti di roccia degli elementali di roccia superiori. Secondo i miei calcoli, quei bracciali dovrebbero bastare a misurare la forza dei miei ceppi.$B$BI miei tentativi di scrutare gli elementali di roccia superiori ne hanno mostrato un gruppo a sud-ovest di qui, vicino ad alcuni ogre, se ricordo bene.$B$BPortamene 5, giusto per averne di scorta. Servo è famoso per smarrire i miei reagenti e le mie ricerche.",
  obj = "Porta 5 Bracers of Rock Binding a Lotwil Veriatus, nelle Badlands.",
  progress = "Le lastre di pietra che hai trovato erano perfette, $N. Lucien riporterà quelle in più a Kharanos quando avremo finito qui. Dopotutto, potrebbero servire ancora.$B$BPer esempio, sarebbero un'ottima base per un comodo rifugio, quando comincerò a studiare un approccio multidisciplinare agli esplosivi ad alto potenziale...$B$B<La voce di Lotwil si spegne mentre torna al suo esperimento.>",
  reward = "$N, hai mai pensato di diventare assistente di ricerca? No? Non so proprio cosa farò qui senza le tue capacità. Intelligenza, curiosità e forza — tutto in un unico pacchetto.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.",
}
T[713] = {
  title = "Vince Chi Resta Freddo",
  desc = "Lascia che ti dica una cosa sull'Olio del Freddo: non c'è niente di meglio per impedire a un motore o a degli ingranaggi di surriscaldarsi.$B$BLe sue proprietà refrigeranti sono straordinarie, e come lubrificante dura come nessun altro. E non è tutto: aiuta anche a mantenere gli incantamenti sugli oggetti magici.$B$BMe ne serve una fiala per aumentare la capacità magica dei miei ceppi e renderli abbastanza potenti da impedire al nostro amico evocato di ucciderci tutti.$B$BBro'kin, un mio amico goblin, può insegnarti a prepararlo. Si trova ad Alterac.",
  obj = "Trova del Frost Oil e portalo a Lotwil Veriatus, nelle Badlands.",
  progress = "Hai trovato l'olio che mi serve? Mi sarebbe davvero utile se riuscissi a trovarne un po'.",
  reward = "Stupendo! Dovrebbe essere il refrigerante perfetto per i miei nuovi bracciali. Se gli incantamenti non dureranno un secolo, darò tutti i miei averi a Servo.$B$BTutti i maghi dell'Assembly resteranno a bocca aperta quando avrò finito, $N. Aspetta e vedrai.",
  en_title = "Coolant Heads Prevail",
  en_obj = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.",
}
T[714] = {
  title = "Giro... Cosa?",
  desc = "$N, hai fatto il tuo lavoro ben oltre ogni aspettativa.$B$B<Lotwil è chiaramente distratto dal suo lavoro.>$B$BSe mai ci incontreremo a Kharanos, vieni pure a chiedere lavoro.$B$BOps! Presto, prendi il... sì, quello. Grazie.$B$BOra mi serve solo un'altra cosa. È un pezzo piccolo, ma piuttosto cruciale, temo: un gyrochronatom.$B$BSe potessi andarne a prendere uno e portarmelo, dovrei essere pronto a completare il lavoro.",
  obj = "Porta un Gyrochronatom a Lotwil Veriatus, nelle Badlands.",
  progress = "Sì, sì, sì. Solo un momento.$B$B<Lotwil continua a lavorare a una specie di congegno.>",
  reward = "AH!$B$B<Lotwil ti strappa di mano il gyrochronatom.>$B$BPerfetto... ho quasi finito. No, davvero. ORA ho quasi finito. Questo progetto è la mia massima priorità... al momento. Lascia che lo metta al suo posto, e potrai vedere con i tuoi occhi cosa mi hai aiutato a creare. Mi ci vorrà solo qualche altro minuto... forse... magari di più. Be', forse molto di più. Vedremo...",
  en_title = "Gyro... What?",
  en_obj = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.",
}
T[715] = {
  title = "Pietra Liquida",
  desc = "Credo che gli oggetti che hai procurato per Lotwil saranno l'ultimo dei nostri problemi, $N. D'altra parte, ti sei $Gdimostrato:dimostrata; più che abile nelle scienze che Lotwil considera sacre, quindi che ne dici di darmi una mano?$B$BMi servono una pozione dell'invisibilità e una pozione di cura; tutte e due potrebbero tornare utili molto presto, se lui ci riesce.$B$BIn cambio ti darò questa ricetta per una pozione che ho messo a punto mentre imparavo da Lotwil. È basata su alcune delle ricerche che sta facendo qui nelle Badlands.",
  obj = "Porta una Healing Potion e una Lesser Invisibility Potion a Lucien Tosselwrench, nelle Badlands.",
  progress = "Sta per finire. E a te, come vanno le cose?",
  reward = "SÌ!$B$BCioè, grazie, $N. Queste saranno utili per viaggiare attraverso le Badlands.",
  en_title = "Liquid Stone",
  en_obj = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.",
}
T[716] = {
  title = "La pietra è meglio della stoffa",
  desc = "So quanto può essere tirchio Lotwil, $N, quindi lascia che ti prepari qualcosa per tutto il disturbo. Magari ti aiuterà perfino a proteggerti dall'imminente atrocità che è l'ultima invenzione di Lotwil.$B$BHo lavorato con tutte le pietre in più che hai raccolto per lui, e posso farti dei bei bracciali che potrebbero servirti. Incantati, naturalmente.$B$BMi servono solo dei bracciali di bronzo decorati fatti da un fabbro, così posso completare i bracciali che sto preparando per te.",
  obj = "Porta dei Patterned Bronze Bracers a Lucien Tosselwrench, nelle Badlands.",
  progress = "Non aspetterei troppo a procurarti quel bracciale, $N.$B$BChissà cosa succederà adesso?",
  reward = "Ecco qua, $N. Provali.",
  en_title = "Stone Is Better than Cloth",
  en_obj = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.",
}
T[717] = {
  title = "Tremori della Terra",
  desc = "Ormai è evidente che non possiamo garantire che Blacklash e Hematus restino imprigionati a Lethlor. Il fatto che dei draghi neri si siano stabiliti lì, e che gli ogre siano riusciti a rubare il Simbolo, indica che bisognerà prendere misure più drastiche.$B$BLa prigione dei draghi è sostenuta da tre pietre runiche che si possono recuperare solo usando il Simbolo della Terra. Quelle pietre runiche possono poi servire a spezzare il sigillo che li tiene prigionieri.$B$B$N... fa' che i loro sogni siano eterni.",
  obj = "Usa il Sign of the Earth per attivare il Pillar of Amethyst, il Pillar of Opal e il Pillar of Diamond e ottenere l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.$B$BMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Garek.",
  progress = "Magie e poteri potenti hanno retto la prigione dei draghi per tanto tempo, ma non possiamo lasciare nemmeno la minima possibilità che Blacklash e Hematus vengano liberati.",
  reward = "Il Kirin Tor non dovrà più preoccuparsi dei prigionieri di Lethlor. Tornerò a riferire il successo al mio maestro. Krasus sarà senza dubbio soddisfatto.",
  en_title = "Tremors of the Earth",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.",
}
T[718] = {
  title = "Miraggi",
  desc = "Nella fretta di lasciare il sito di scavo di Uldaman, siamo stati costretti ad abbandonare molti carri e casse di provviste lungo la strada. Gli ogre del Camp Kosh si sono gettati sulla nostra attrezzatura abbandonata come avvoltoi su una carcassa in putrefazione. E non hanno nemmeno un odore migliore. Delle carcasse, intendo.$B$BComunque, hanno preso il carro che trasportava tutte le nostre armi e roba simile... quindi — be', è un po' imbarazzante — non siamo riusciti a procurarci da mangiare.$B$BQui siamo un po' nei guai, pensi di poterci aiutare?",
  obj = "Recupera la Supply Crate per Sigrun Ironhew.",
  progress = "Il deserto è un brutto posto dove avere fame, $Gamico mio:amica mia;, te lo dico io.$B$BEhi... cos'è quello laggiù...",
  reward = "Grazie mille, $N. Mentre eri via, io... ehm... ho mandato giù un boccone di sabbia. Era...$B$BBe', basta così: stasera usciamo a procurarci del cibo. Mangeremo come re!",
  en_title = "Mirages",
  en_obj = "Retrieve the Supply Crate for Sigrun Ironhew.",
}
T[719] = {
  title = "Un Nano e i Suoi Attrezzi",
  desc = "Ehi, $N. Sta' $Gattento:attenta; da queste parti. Ci sono nani Dark Iron dappertutto — sembravano del clan Shadowforge.$B$BHanno appena attaccato il sito di scavo dove lavoravo — hanno ucciso quasi tutti, compreso il mio capo, Hammertoe. Ho salvato la pelle per un pelo.$B$BIl sito è appena a nord di qui, e sto cercando un modo per riprenderci un po' delle nostre provviste, soprattutto il mio piccone portafortuna.$B$BTe la senti di darmi una mano? Uno di quei maledetti Dark Iron deve avere il mio piccone! Potrebbe essere uno qualunque di loro.",
  obj = "Trova Ryedol's Lucky Pick e riportalo a Prospector Ryedol, a sud del Sito di Scavo di Hammertoe.",
  progress = "Non so cosa cercassero gli Shadowforge, ma di sicuro avevano uno scopo.",
  reward = "Sei $Gil mio salvatore:la mia salvatrice;, $C. Sono contento che qualcuno abbia dato una lezione o due a quegli Shadowforge. Grazie per l'aiuto.",
  en_title = "A Dwarf and His Tools",
  en_obj = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.",
}
T[720] = {
  title = "Un Segno di Speranza",
  desc = "<Sulla mappa c'è un testo scarabocchiato col gesso.>$B$B\"Ryedol,$Bmi stanno portando a Uldaman. Manda aiuto.$B— Hammertoe\"",
  obj = "Trova Prospector Ryedol e digli che Hammertoe Grez è vivo.",
  reward = "Hammertoe è vivo?! È incredibile, $N!",
  en_title = "A Sign of Hope",
  en_obj = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.",
}
T[721] = {
  title = "Un Segno di Speranza",
  desc = "$N, riesci a trovarlo? Riesci a trovare Hammertoe a Uldaman?$B$BSe quei luridi Shadowforge lo tengono in ostaggio per scoprire cosa sa degli scavi dei titani, allora tutta Ironforge potrebbe essere in guai grossi.$B$BÈ da tanto tempo che quei Dark Iron cercano magie per costruire golem più potenti. Anche Hammertoe faceva lo stesso, certo, ma solo per fermarli.$B$BProbabilmente lo tengono in vita finché non scoprono quello che sa. Devi sbrigarti, se vuoi salvarlo!",
  obj = "Trova Hammertoe Grez a Uldaman.",
  reward = "Sì? Mi dispiace... <coff> Mi sento così debole. Puoi avvicinarti, $C?$B$BTi manda Ryedol? Sia lodato Muradin, quel ragazzo non è lento di comprendonio come pensavo una volta. <coff>",
  en_title = "A Sign of Hope",
  en_obj = "Find Hammertoe Grez in Uldaman.",
}
T[722] = {
  title = "L'Amuleto dei Segreti",
  desc = "Hai coraggio... <coff>... a venire a Uldaman per me, $C.$B$BSe sei davvero qui per aiutare... il vecchio Hammertoe, allora... <coff>... devi trovare... il mio amuleto.$B$BCe l'ha Deepshadow... Magregan Deepshadow. È da queste parti... di sicuro tra le rovine. Quell'amuleto li porterà... <coff>... dritti alle pergamene, se nessuno lo ferma. Tocca a te, $N. Ti prego... prendi quell'amuleto.$B$BLe pergamene aiuteranno di sicuro i Dark Iron a creare golem ancora più potenti. Lo so e basta. Me lo sento nelle ossa.",
  obj = "Trova Hammertoe's Amulet e riportalo a Hammertoe, a Uldaman.",
  progress = "Il clan Shadowforge... <coff> è pericoloso. Sta' $Gattento:attenta;. <coff> Devi trovare l'amuleto.",
  reward = "Ah! <coff coff>$B$BLo sapevo che avresti trovato il mio amuleto, $N.$B$B<ansima> Ben fatto davvero, $N. <coff>",
  en_title = "Amulet of Secrets",
  en_obj = "Find Hammertoe's Amulet and return it to him in Uldaman.",
}
T[723] = {
  title = "Un Cercatore di Fede",
  desc = "<Hammertoe si stringe le ferite e si prende un momento per ricomporsi prima di parlare di nuovo.>$B$BTrova Ryedol, $N. Portagli il mio amuleto. <coff coff> Lui... <coff> saprà cosa fare. Sa che cercavo le origini del nostro popolo, e lui... <coff>... sa che la mia missione era anche fermare il clan Shadowforge. Non devono trovare le pergamene... <coff>",
  obj = "Porta Hammertoe's Amulet a Prospector Ryedol, nelle Badlands.",
  progress = "Direi che è stata una brutta giornata, ma queste sono le Badlands: ogni giorno è una brutta giornata.",
  reward = "L'amuleto di Hammertoe? Credo che il mio morale fosse più alto quando lo credevo morto. Saperlo per certo non fa che peggiorare il dolore. Questo amuleto era l'opera di tutta la sua vita. Non posso lasciare che sia morto invano.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.",
}
T[724] = {
  title = "Un Cercatore di Fede",
  desc = "Va bene, va bene... chi potrebbe sapere cosa fare?$B$BLo Storico Karnik! Ma certo!$B$BÈ a Ironforge. Lui potrà aiutarci. Lui e Hammertoe lavoravano insieme per trovare i manufatti perduti di Uldaman.$B$BSembra che gli Shadowforge abbiano scoperto che quei due ne sapevano più di quanto lasciassero intendere.$B$BRacconta a Karnik cos'è successo a Hammertoe e dagli l'amuleto — ti dirà lui cosa bisogna fare dopo.",
  obj = "Porta Hammertoe's Amulet a Historian Karnik, a Ironforge.",
  progress = "Ah, sì. $GUn altro viaggiatore:Un'altra viaggiatrice; che cerca qualcosa dai nani.$B$B$GSignore:Signora;, sono davvero spiacente, ma adesso non ho tempo di rispondere a domande inutili.",
  reward = "Oh! Be', questa è tutta un'altra faccenda. Probabilmente non ti rendi ancora conto della gravità della cosa, vero?$B$BLa morte di Hammertoe mi addolora profondamente, ma se ti ha mandato qui con il suo amuleto, allora aveva capito cosa c'è in gioco.$B$BPiangeremo la sua morte più tardi.$B$BLascia che ti mostri uno dei motivi per cui questo amuleto è così prezioso.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.",
}
T[725] = {
  title = "Avvisare di una Minaccia",
  desc = "$N, corri a cercare il Consigliere Belgrum il più in fretta possibile. Digli quello che hai visto e chiedigli come vuole che procediamo. Questo biglietto gli spiegherà il resto.$B$BNel frattempo, dedicherò un po' di tempo a parlare con lo spirito di Hammertoe. Forse sa qualcosa che ci aiuterà a fermare le attività di quei cretini degli Shadowforge nelle Badlands. Possiamo solo pregare.",
  obj = "Trova Advisor Belgrum e consegnagli il suo biglietto.",
  progress = "Mm? Sì, $C.",
  reward = "Ah, notizie dallo Storico Karnik. Ottimo.$B$BPer le sue faccende ho sempre tempo.$B$B<Il Consigliere Belgrum apre il biglietto e comincia a leggere.>",
  en_title = "Passing Word of a Threat",
  en_obj = "Find Advisor Belgrum and give him his note.",
}
T[726] = {
  title = "Avvisare di una Minaccia",
  desc = "<Il Consigliere Belgrum arriva in fondo al biglietto, e per un attimo spalanca gli occhi.>$B$BOhi, queste sono notizie funeste.$B$B$N, ti prego, torna dallo Storico Karnik e digli che, per autorità del re, deve servirsi di queste informazioni e agire con rapidità e decisione. Deve fermare le attività degli Shadowforge nelle Badlands.",
  obj = "Parla con Historian Karnik.",
  reward = "Stai trattando questa faccenda con un'urgenza che mi aspetterei dal re in persona, $N.$B$BD'accordo, allora. So io cosa metterà in ginocchio gli Shadowforge.$B$BLa loro presenza a Uldaman si può rallentare se li colpiamo nella loro base operativa: la Fortezza di Angor.",
  en_title = "Passing Word of a Threat",
  en_obj = "Speak to Historian Karnik.",
}
T[727] = {
  title = "A Ironforge per il Compendio di Yagyin",
  desc = "La Tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!$B$BVa' da Gerrig Bonegrip. Ha una bottega a Ironforge, nella Caverna Sperduta. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli il Compendio di Yagyin... e portalo a me!",
  obj = "Dai il Sigil of the Hammer a Gerrig Bonegrip, a Forlorn Cavern di Ironforge.",
  progress = "Salve. $GBenvenuto:Benvenuta; nella mia bottega, ma fa' attenzione a quello che tocchi.$B$BIl sapere può essere letale.",
  reward = "Oh. Salve, $Gfratello:sorella;.$B$BE lode a coloro che dimorano nel profondo.",
  en_title = "To Ironforge for Yagyin's Digest",
  en_obj = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[728] = {
  title = "All'Undercity per il Compendio di Yagyin",
  desc = "La tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!$B$BVa' dal Custode Bel'dugur, nell'Undercity di Lordaeron. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli il Compendio di Yagyin... e portalo a me!",
  obj = "Porta il Sigil of the Hammer a Keeper Bel'dugur, nell'Undercity.",
  progress = "Ah, vedo che abbiamo $Gun:una; $C zelante. Sei qui per imparare dalla mia collezione? Bene!$B$BMa attenzione: come il sapere dà potere ai forti... così fa impazzire i deboli.",
  reward = "Sii $Gdiscreto:discreta; con i tuoi segni, $C. C'è chi non crede nella giustezza del nostro giuramento.$B$BE c'è chi vorrebbe vederci fallire, se sapesse di noi.$B$BDobbiamo sempre essere prudenti. E vigili. E pazienti.",
  en_title = "To the Undercity for Yagyin's Digest",
  en_obj = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.",
}
T[732] = {
  title = "Tremori della Terra",
  desc = "Sigrun mi ha detto che gli sei $Gstato:stata; di grande aiuto. Forse potrei chiedere il tuo aiuto anch'io. Mi ha mandato qui il mio maestro, Krasus del Kirin Tor, per porre fine ai guai che si stanno preparando nella Piana di Lethlor.$B$BNon posso rivelare la natura esatta del mio incarico qui, né i compiti che devo svolgere, ma stai $Gcerto:certa; che è di vitale importanza.$B$BUna banda di ogre nomadi, che a volte si vedono vicino al Camp Boff, ha rubato un oggetto chiamato Simbolo della Terra; devo averlo. Portamelo, e ti dirò di più.",
  obj = "Recupera il Sign of the Earth per Garek.",
  progress = "La banda nomade di ogre si sposta tra i suoi accampamenti in tutte le Badlands; il calore che sale dalla terra arida e i venti vorticosi renderanno difficile seguirne le tracce. Ho sentito che a volte passano per il Camp Boff. Se ti sei $Gperso:persa;, potresti cercare lì.",
  reward = "Con il Simbolo mi porti buone notizie, $N. Il Simbolo della Terra fu creato dai nani Dark Iron della Fortezza di Angor per imprigionare due degli spietati luogotenenti di Deathwing, i gemelli Blacklash e Hematus.",
  en_title = "Tremors of the Earth",
  en_obj = "Retrieve the Sign of the Earth for Garek.",
}
T[733] = {
  title = "Arrangiarsi",
  desc = "Qui sarà dura andare avanti, se non riesco a racimolare un po' di materiali per costruire delle difese e altre cose necessarie. Ho notato che gli ogre della zona sembrano ben forniti di rottami metallici. Forse le storie sulle macchine d'assedio nelle Badlands non erano poi così lontane dal vero...$B$BComunque, il Prospettore si sta preoccupando per lo stato del nostro piccolo accampamento, quindi vorrei mettermi al lavoro presto, se posso.$B$BL'accampamento principale degli ogre è alla Grotta dei Dustbelch, un bel tratto di cammino a ovest di qui.",
  obj = "Procura 7 pezzi di Scrap Metal per Sigrun.",
  progress = "Be', ho fatto quel che potevo con quello che avevo, ma... non è molto. Hai trovato altri materiali?",
  reward = "È un inizio, $N, e dovrà bastare finché non avremo notizie da Ironforge o dalla Lega degli Esploratori.$B$BOra, se solo trovassi un po' di sale da qualche parte per la mia tinozza da tempra...",
  en_title = "Scrounging",
  en_obj = "Get 7 pieces of Scrap Metal for Sigrun.",
}
T[734] = {
  title = "Sarà Dura",
  desc = "Meraviglioso, meraviglioso.$B$B<Lotwil alza lo sguardo su di te per un momento, prima di tornare ai suoi ceppi.>$B$BVa' a parlare con Lucien, $N. Mi serve un ingranaggio #5. Me lo porti, vero?",
  obj = "Parla con Lucien Tosselwrench, nelle Badlands.",
  reward = "Un Ingranaggio #5, eh? Già, questo non promette niente di buono.",
  en_title = "This Is Going to Be Hard",
  en_obj = "Speak to Lucien Tosselwrench in the Badlands.",
}
T[735] = {
  title = "La Stella, la Mano e il Cuore",
  desc = "Il Compendio di Yagyin, eh? Stai fondando un nuovo capitolo del nostro ordine, da qualche parte? Lascia stare, non sta a me chiederlo.$B$BTi aiuterò, perché ne ho una copia in più. Dobbiamo aiutarci a vicenda, no? È così che prosperiamo.$B$BMi servono tre oggetti di potere. Portameli e ti darò il compendio.$B$BNon pronuncerò i loro nomi. Potrebbero esserci orecchie in ascolto. Ma ecco, te li scrivo.",
  obj = "Porta gli oggetti elencati nella Bonegrip's Note a Gerrig Bonegrip, a Ironforge.",
  progress = "Hai le reliquie che ti ho chiesto?",
  reward = "Sei $Gpieno:piena; di risorse, $C. Se il tuo compito è davvero fondare un nuovo capitolo del nostro ordine, credo che lo guiderai bene.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.",
}
T[736] = {
  title = "La Stella, la Mano e il Cuore",
  desc = "Ti serve il Compendio di Yagyin? Il tuo piano, quindi, è radunare un altro gregge? Ma certo... e certo che ti aiuterò, $Gfratello:sorella;.$B$BMa anche tu devi aiutare me.$B$BMi servono tre oggetti di potere. Portameli e il compendio sarà tuo.$B$BNon posso pronunciare i nomi di questi oggetti, ma li scriverò.$B$BProcurami gli oggetti di questa lista. Se ci riesci, allora sei davvero $Gdegno:degna; di aprire un tuo capitolo del nostro ordine.",
  obj = "Porta gli oggetti elencati nella Bel'dugur's Note a Keeper Bel'dugur, nell'Undercity.",
  progress = "Come procede la tua missione, $C?",
  reward = "Mi hai davvero colpito! Devi avere grande abilità, o grande fortuna, per aver ottenuto queste reliquie. In ogni caso, sei una risorsa preziosa per noi.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.",
}
T[737] = {
  title = "Il Sapere Proibito",
  desc = "Ho il compendio per te, $N. Non c'è bisogno che ti dica di averne gran cura. E di tenerlo lontano da mani ostili.$B$BQuesto libro racchiude molte verità...$B$B...E la verità può bruciare.",
  obj = "Porta Yagyin's Digest a Theldurin.",
  progress = "Oh! Sei $Gstato:stata; via a lungo. Hai preso il compendio?",
  reward = "Ce l'hai! Oh, un barlume di speranza!$B$BI tuoi sforzi potrebbero ancora salvarci, $N. Dovrebbero farti un monumento! Dovrebbero costruirti un santuario! Che il tuo nome sia lodato finché i tuoi nipoti non avranno nipoti!$B$BA meno che... LORO non vengano liberati e risalgano in superficie. Se succede, puoi scordarti i figli.$B$BSe LORO vengono liberati, siamo tutti cibo per i vermi.",
  en_title = "Forbidden Knowledge",
  en_obj = "Bring Yagyin's Digest to Theldurin.",
}
T[738] = {
  title = "Trova Agmond",
  desc = "Il Prospettore Agmond dirigeva i nostri siti di scavo nei Badlands, a sud-ovest. Dico \"dirigeva\" perché... be', non ho sue notizie da settimane. Ho bisogno che tu trovi Agmond, così potrò avere il suo rapporto.$B$BL'ultima volta che ne ho avuto notizie, Agmond era al sito di scavo più a sud dei Badlands — un piccolo cantiere oltre la Fortezza di Angor. Io comincerei a cercarlo da lì.",
  obj = "Trova Agmond.",
  reward = "Questo scheletro dev'essere ciò che resta dello sfortunato Agmond. Il suo corpo è spezzato e malridotto, e le sue ossa sono state spolpate.",
  en_title = "Find Agmond",
  en_obj = "Find Agmond.",
}
T[739] = {
  title = "Murdaloc",
  desc = "Le tracce di Agmond arrivano da ovest. Dalle strisciate di sangue sulla roccia e sulla sabbia si capisce facilmente che il nano si è trascinato per un bel tratto.$B$BE qui è morto.$B$BOsservando da vicino, si vede la parola \"Murdaloc\" scarabocchiata alla meglio su un tratto di arenaria dei Badlands.$B$BScarabocchiata accanto alla mano senza vita di Agmond.",
  obj = "Uccidi l'assassino di Agmond, Murdaloc.$B$BUccidi 12 Stonevault Bonesnapper.$B$BFai rapporto a Prospector Ironband, a Loch Modan.",
  progress = "Hai notizie sulla sorte di Agmond? L'hai trovato?",
  reward = "È una notizia amara, $N. Ma Agmond aveva un braccio forte e un colpo di martello feroce, e una testa dura come poche! Anche se è stato ucciso da quei maledetti trogg, sono sicuro che ne ha trascinati parecchi con sé.",
  en_title = "Murdaloc",
  en_obj = "Slay Agmond's killer, Murdaloc.$B$BSlay 12 Stonevault Bonesnappers.$B$BReport to Prospector Ironband in Loch Modan.",
}
T[762] = {
  title = "Un Ambasciatore del Male",
  desc = "L'Ambasciatore Infernus è stato mandato alla Fortezza di Angor da Ragnaros in persona per sorvegliare gli Shadowforge che cercano i manufatti perduti a Uldaman.$B$BHa già causato perdite enormi al nostro popolo, ma è evidente che la situazione è peggiorata. Non oso immaginare quanti manufatti riuscirebbero a trovare e a usare contro Ironforge.$B$BIl nostro obiettivo è semplice, $C. Torna nelle Badlands e distruggi l'Ambasciatore Infernus. Una volta eliminata la minaccia, torna dal Consigliere Belgrum con una prova della tua vittoria.$B$BOra è nelle tue mani.",
  obj = "Uccidi Ambassador Infernus alla Fortezza di Angor e porta una prova della sua morte ad Advisor Belgrum, a Ironforge.",
  progress = "Il tempo stringe, $N. Ragnaros non aspetterà che siamo pronti.",
  reward = "$N, la tua dedizione a Ironforge e al popolo dei nani è indiscutibile. Ti ringrazio per il tuo aiuto in questa faccenda.$B$BManderò notizia allo Storico Karnik per informarlo che ce l'hai fatta, e farò anche mandare aiuti nelle Badlands il prima possibile, per contribuire a recuperare il sito di scavo. Grazie ancora.$B$BPrima che tu vada, c'è un'altra cosa che vorrei chiederti in nome di Re Bronzebeard.",
  en_title = "An Ambassador of Evil",
  en_obj = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.",
}
T[777] = {
  title = "Sarà Dura",
  desc = "Ok, ecco qua.$B$BIo sarò laggiù... al riparo.$B$BSe vuoi, raggiungimi.",
  obj = "Porta il Cog #5 a Lotwil Veriatus.",
  progress = "<Senza alzare gli occhi dai ceppi, Lotwil tende una mano e agita le dita con impazienza.>$B$BL'ingranaggio, $N, l'ingranaggio!",
  reward = "Ah, perfetto. Sta' indietro mentre mi preparo a fare di nuovo la storia!$B$B<Lotwil continua a lavorare febbrilmente.>",
  en_title = "This Is Going to Be Hard",
  en_obj = "Bring Cog #5 to Lotwil Veriatus.",
}
T[778] = {
  title = "Sarà Dura",
  desc = "Ahah! Fatto! I ceppi sono pronti!$B$BÈ il momento, Lucien. È il momento, Servo!$B$BSei $Gpronto:pronta; ad assistere alla fusione perfetta di alchimia, ingegneria e arcano, $N?$B$BOra evocherò un potente elementale. Questo è un giorno rivoluzionario per tutti noi.",
  obj = "Sconfiggi il Fam'retor Guardian e riporta Lotwil's Shackles of Elemental Binding a Lotwil Veriatus.",
  progress = "Non proprio il risultato che mi aspettavo. Potresti recuperare i miei ceppi?",
  reward = "Grazie, $N. È stata una dura prova, vero?$B$BNon sono sicuro di cosa possa essere andato storto. Meno male che le mie magie erano qui e hanno aiutato a rimandare la creatura nel suo piano d'origine.$B$BForse un piccolo segno di gratitudine per tutto il tuo duro lavoro...",
  en_title = "This Is Going to Be Hard",
  en_obj = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.",
}
T[779] = {
  title = "Sigillo della Terra",
  progress = "Qui c'è il Sigillo della Terra, con tre nicchie incassate per la Pietra Runica d'Ametista, la Pietra Runica con Opale e la Pietra Runica di Diamante.",
  reward = "Mentre metti le Pietre Runiche negli incavi corrispondenti, un violento boato scuote la terra e il Sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[782] = {
  title = "Alleanze Spezzate",
  desc = "Dall'alleanza dell'Orda con il drago Deathwing durante la Seconda Guerra, sappiamo che due dei suoi luogotenenti, Blacklash e Hematus, furono imprigionati nella Piana di Lethlor, lontano a est. Dobbiamo mettere a tacere i nostri depravati alleati di un tempo per restituire l'onore all'Orda!$B$BAbbiamo assoldato Tho'grun e la sua banda di mercenari ogre perché ci aiutassero a ottenere il Simbolo della Terra, una chiave necessaria per aprire la prigione dei draghi. Ma Tho'grun ci ha traditi: ci ha sopraffatti e l'ha tenuto per sé. Va' al Camp Boff e riprendilo!",
  obj = "Uccidi Boss Tho'grun e porta il Sign of the Earth a Gorn, a Kargath.",
  progress = "Il tradimento di Tho'grun... c'è da stupirsi se gli ogre non fanno più parte dell'Orda? Sarò lieto di vederlo morto e di riavere il Simbolo della Terra.$B$BSe non l'hai ancora tolto di mezzo, non perdere tempo e va' al Camp Boff. Si trova a sud-est di Kargath.",
  reward = "Con Tho'grun morto, e il suo cadavere spolpato dai venti del deserto e dalle poiane in cerca di carcasse, gli ogre saranno nel caos. Anche se è una piccola vittoria, porterà a una ben più grande$B$BOra il Simbolo della Terra è nelle nostre mani, e possiamo aprire la prigione dei draghi neri a Lethlor. Li libereremo dalla loro prigionia senza fine, anche se per andare incontro alla rovina!",
  en_title = "Broken Alliances",
  en_obj = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.",
}
T[785] = {
  title = "Un'Alleanza Strategica",
  desc = "Thrall è un capo saggio e nobile come pochi. La sua tenacia sul campo di battaglia è pari solo al suo tatto diplomatico.$B$BI Troll Darkspear si sono rivelati alleati preziosissimi per la gente orchesca. Per lealtà e per onore abbiamo giurato con loro un patto di protezione.$B$BIl Capoguerra ha dato ordine di accertarsi che nessuna minaccia diretta incomba sui nostri amici Darkspear di Sen'jin Village. Uno dei loro esploratori più fidati, Lar Prowltusk, tiene d'occhio il loro fianco occidentale.$B$BCerca Lar e dagli tutto l'aiuto che serve.",
  obj = "Cerca Lar Prowltusk sul fianco occidentale di Sen'jin Village.",
}
T[793] = {
  title = "Alleanze Spezzate",
  desc = "Il Sigillo della Terra è tenuto chiuso da tre pietre runiche, custodite nei Pilastri di Diamante, di Opale e di Ametista, nella Piana di Lethlor. Con il Simbolo della Terra potrai rimuovere le pietre runiche e aprire il Sigillo della Terra.$B$BMa sta' $Gattento:attenta;, $N: i draghi neri Blacklash e Hematus non sono da prendere alla leggera. Assicurati che muoiano e riportami i loro ceppi.$B$BPer raggiungere la gola, va' all'estremità orientale delle Badlands. Ma fa' attenzione, perché la gola è la dimora di innumerevoli draghi.",
  obj = "Usa il Sign of the Earth per attivare il Pillar of Diamond, il Pillar of Opal e il Pillar of Amethyst e ottenere la Diamond Runestone, l'Opal Runestone e l'Amethyst Runestone.$B$BMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Gorn.",
  progress = "Ci sono pochi nemici più letali della stirpe dei draghi, e pochi draghi hanno combattuto con la ferocia di Blacklash e Hematus.",
  reward = "Il dragonflight nero continua ad allearsi con gli orchi rinnegati Blackrock, ed entrambi vanno rimessi in riga, o eliminati. Con Blacklash e Hematus morti, possiamo volgere la nostra attenzione a ovest, verso la Blackrock Spire.",
  en_title = "Broken Alliances",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.",
}
T[795] = {
  title = "Sigillo della Terra",
  progress = "Qui c'è il Sigillo della Terra, con tre nicchie incassate per la Pietra Runica d'Ametista, la Pietra Runica con Opale e la Pietra Runica di Diamante.",
  reward = "Mentre metti le Pietre Runiche negli incavi corrispondenti, un violento boato scuote la terra e il Sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[822] = {
  title = "Il Barile Vuoto di Chen",
  desc = "Roba buona, quella stormstout, eh?$B$BHo un'altra ricetta che ho imparato da Chen. Ti interessa? Non ci vuole molto a prepararla, e potrebbe tornarti utile se hai intenzione di vivere altre avventure.$B$BPortami 5 ghiandole elettriche da un pelletempesta qualsiasi, 1 ghiandola salivare di falco del tuono dai falchi del tuono superiori e un fegato di kodo da uno qualsiasi dei kodo delle Barrens.$B$BCome ti ho detto, questa roba ha una bella botta: è la birra dei trogg di cui ti avevo parlato.",
  obj = "Porta 5 Lightning Gland, 1 Thunderhawk Saliva Gland e 1 Kodo Liver a Brewmaster Drohn, a Ratchet.",
  progress = "Ti stai dando da fare per trovare quegli ingredienti, $N?",
  reward = "Ahah! Lo sapevo che non avresti resistito a un po' di questa birra. Torna quando vuoi se te ne serve altra, $N. Basta che mi porti altri ingredienti come quelli che ti ho fatto raccogliere.",
  en_title = "Chen's Empty Keg",
  en_obj = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.",
}
T[824] = {
  title = "Je'neu del Circolo della Terra",
  desc = "Il Circolo della Terra è un gruppo sciamanico che si dedica a studiare e preservare gli elementi. Su vecchi dèi folli, antiche leggende e tradizioni hanno dimenticato più cose di quante la maggior parte degli studiosi ne saprà mai.$B$BPer tua fortuna, conosco qualcuno del Circolo della Terra qui in Ashenvale. Va' all'Avamposto di Zoram'gar, sulla costa della Spiaggia di Zoram; mostra a Je'neu Sancrea quello che hai trovato. Se c'è qualcuno che può capire il significato di quel globo, è lui.",
  obj = "Porta il Befouled Water Globe a Je'neu Sancrea all'Avamposto di Zoram'gar, in Ashenvale.",
  progress = "Ah, salve. Passo molto tempo a studiare l'acqua — tutti gli elementi, a dire il vero — tanto che a volte non mi accorgo nemmeno di chi mi sta intorno.$B$BC'è qualcosa in cui posso aiutarti?",
  reward = "Questo globo... è davvero inquietante. Molti degli elementali più potenti ricevono potere ed energia attraverso congegni simili. Trovarne uno quasi intatto come questo è una cosa — trovarlo così corrotto è un'altra.$B$BFarò in modo che il Circolo della Terra studi questo globo come si deve. Forse possiamo mettere fine a questa corruzione degli elementi. Ti prego — accetta questo come giusto compenso per aver portato il globo all'attenzione del Circolo della Terra.",
  en_title = "Je'neu of the Earthen Ring",
  en_obj = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
}
T[836] = {
  title = "Salva OOX-09/HL!",
  desc = "La voce dello gnomo gracchia di nuovo dal robot:$B$B\"Devo portare OOX-09/HL in un posto aperto e sicuro, così che possa cominciare una lunga procedura di decollo. Ha un sistema di occultamento incorporato, ma da qui mi serve tempo per rimetterlo in funzione. Scorta il robot da dov'è adesso fino, diciamo, alla riva oltre la Scogliera Altosguardo! Dovrebbe essere il posto perfetto, e il tragitto abbastanza lungo, per riattivare tutto!\"$B$B\"Scortalo sano e salvo fino alla riva, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — passo e chiudo!\"",
  obj = "Scorta OOX-09/HL fino alla riva oltre Overlook Cliff, poi fai rapporto a Oglethorpe Obnoticus a Booty Bay.",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-09/HL! Non so nemmeno da dove cominciare per ringraziarti del tuo aiuto! La mia serie di robot a ritorno automatico ha bisogno di altro sviluppo, ma recuperandolo mi hai risparmiato ore e ore di lavoro per ricostruirlo, e anche un bel po' di monete d'oro in costi di fabbricazione!$B$BPer favore, scegli pure uno di questi oggetti che ho qui. Grazie ancora per il tuo generoso aiuto, $N, io e i miei robot siamo in debito con te!",
}
T[838] = {
  title = "Scholomance",
  desc = "Sull'isola di Caer Darrow sorge Scholomance — una scuola che fa da roccaforte al Flagello. Il nostro nemico vive lì dentro, libero di portare avanti al sicuro le ricerche che accrescono il suo potere. Una porta sbarra la strada e, per quanto ci proviamo, senza la chiave giusta non si entra.$B$BLo Speziale Dithers conosce bene Scholomance e ha un'idea su come procurarsi una chiave. Mi hai dimostrato di valere, di essere $Guno:una; che le cose le porta a termine; ora affido a te questo compito. Parlane con lui.",
  obj = "Parla con Apothecary Dithers al Bulwark, nelle Western Plaguelands.",
  reward = "Sì, $C, il Gran Esecutore mi ha accennato che potresti essere la persona di cui fidarsi per la faccenda della chiave. Ho dedicato buona parte dei miei ultimi studi a Scholomance, e credo di conoscere un modo per procurartene una che ti faccia passare dalla porta principale quando vuoi.$B$BNon sarà un compito facile, ma compiti così lo sono di rado. Hai tutta l'aria di chi lo sa per esperienza.",
}
T[843] = {
  title = "La Riconquista di Gann",
  desc = "In solitudine percorro queste strade.$B$BI nani di Bael Modan non mostrano rispetto per la mia terra. Esplosioni tremende scavano buchi profondi nel terreno, mentre macchine rumorose fanno a pezzi le colline. Le terre che un tempo davano casa e sostentamento alla mia tribù ora brulicano di nani che distruggono tutto.$B$BI tentativi di arrivare a una soluzione diplomatica sono falliti. È il momento di un'azione decisiva.$B$BCaccia i nani dallo scavo di Bael Modan con la forza e portami il diario del loro capo, il Prospettore Khazgorm.",
  obj = "Gann Stonespire vuole che tu uccida 15 Bael'dun Excavator e 5 Bael'dun Foreman.$B$BPorta Khazgorm's Journal a Gann Stonespire.",
  progress = "Molti tauren innocenti hanno perso la vita o sono stati cacciati dalla terra dei loro avi quando sono arrivati i nani di Bael Modan. La mia terra va riconquistata!",
  reward = "Khazgorm ha avuto la sorte che si meritava. Non provo rimorso per quello sciocco. Era un infedele in queste terre.$B$BChe la sua morte serva da monito a tutti quelli che minacciano di sconvolgere il nostro modo di vivere.$B$BOra lasciami un momento per studiare il diario del nano...",
  en_title = "Gann's Reclamation",
  en_obj = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$B$BBring Khazgorm's Journal to Gann Stonespire.",
}
T[846] = {
  title = "La Vendetta di Gann",
  desc = "È chiaro che il cercatore contava sugli esplosivi e su quei veicoli rumorosi per fare a pezzi il terreno. C'è da aspettarsi che presto prenda il comando un nuovo caposquadra.$B$BVoglio ripagare i nani con la loro stessa moneta. Secondo questi piani, se combiniamo nitroglicerina con pasta di legno e nitrato di sodio possiamo creare una carica esplosiva. Si sa che i fucilieri, i soldati e gli ufficiali della Fortezza hanno il materiale.$B$BRaccogli questi materiali e portameli. Fabbricherò una carica che i nani non dimenticheranno!",
  obj = "Gann Stonespire vuole che tu gli porti 6 fiale di Nitroglycerin, 6 fasci di Wood Pulp e 6 campioni di Sodium Nitrate.",
  progress = "Vedo che sei $Gtornato:tornata;, $N.$B$BAnche se la morte di Khazgorm ritarderà un po' gli scavi nelle terre dei miei avi, non metterà certo fine del tutto alla distruzione.$B$BLa Fortezza di Bael Modan è una minaccia militare sempre più grande. Costruita per difendere il sito di scavo, ora è pronta anche ad attaccare.$B$BSe hai gli ingredienti che ti ho chiesto, posso fabbricare una carica che farà riflettere quei nani frettolosi su quello che stanno facendo qui nelle Barrens.",
  reward = "Vedo che sai darti da fare, $C.$B$BPresto, senza dubbio, avremo per quei nani la sorpresa che si meritano.",
  en_title = "Revenge of Gann",
  en_obj = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.",
}
T[847] = {
  title = "L'Astuzia del Raptor",
  desc = "Questo... questo potere... È questo il potere degli sciamani che Tor'gan ha cercato di mostrarmi? Devo ammettere che è interessante. Di' a Tor'gan che mi ha convinto... per il momento. Ascolterò quello che ha da dire.",
  obj = "Parla con Tor'gan.",
  reward = "Quando l'incantesimo svanirà, parlerò con Gor'mul. Ti ringrazio per avermi aiutato a riportare Gor'mul nel mondo dei vivi. Non ho dubbi che anche lui ti sia molto grato.",
  en_title = "Guile of the Raptor",
  en_obj = "Speak with Tor'gan.",
}
T[849] = {
  title = "La Vendetta di Gann",
  desc = "Seguendo i piani di Khazgorm non dovrebbe essere un problema fabbricare una carica esplosiva$B$BAh, ecco fatto.$B$BOra, $N, ti affiderò un incarico speciale. Prendi questo candelotto esplosivo e usalo per far saltare la macchina volante a Bael Modan.$B$BLa macchina volante non è solo un pezzo fondamentale dell'infrastruttura del sito, ma serve anche come arma da guerra. E soprattutto è un simbolo di potere e un insulto alla memoria della mia tribù.$B$BRendimi fiero portando a termine questa impresa eroica, e sarai $Gricompensato:ricompensata;.",
  obj = "Distruggi la macchina volante a Bael Modan e torna da Gann Stonespire.",
  progress = "Una volta distrutta la macchina volante dei nani, proverò la dolce soddisfazione della vendetta.",
  reward = "Ben fatto, $N! Che a Thunder Bluff tu sia $Gonorato:onorata; come chi difende le terre sacre dei tauren e come $Gcampione:campionessa; della tribù perduta.",
  en_title = "Revenge of Gann",
  en_obj = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.",
}
T[857] = {
  title = "La Lacrima delle Lune",
  desc = "Il potere era mio! Proprio nelle mie mani! E lo rivoglio! Lo rivoglio, ti dico!$B$BQuegli sporchi scavatori l'hanno portata alla luce... così bella, era. Chiamata Lacrima delle Lune, è stata la prima grande scoperta che abbiamo fatto a Bael Modan.$B$BDoveva essere mia! Mia, ti dico!$B$BIl Generale Twinbraid è diventato geloso del potere che mi dava. L'ha chiusa a chiave nella Fortezza. Maledetta, l'ha chiamata! Che sciocco!$B$BAltri la volevano e bisognava fermarli! Quel bastardo di Twinbraid mi ha cacciato via.$B$BOra lo rivoglio. Lo rivoglio, ti dico!",
  obj = "Feegly the Exiled vuole che tu recuperi per lui la Tear of the Moons.",
  progress = "Dov'è la Lacrima delle Lune? Mi serve adesso! Mi serve, ti dico!",
  reward = "Finalmente il potere è di nuovo mio! Mio, ti dico!",
  en_title = "The Tear of the Moons",
  en_obj = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.",
}
T[862] = {
  title = "Stufato di Ratto di Fossa",
  desc = "$GUn:Una; $C come te deve avere parecchia fame qui nelle Barrens. Io muoio di fame tutto il giorno.$B$BFacciamo così: ti preparo un bello stufato. Mi servono solo un po' di ratti di fossa.$B$BPare che quei sudici nani di Bael Modan siano infestati dal banchetto preferito da tutti. Ora scendi a sud fino a Bael Modan e riportami un po' di ratti di fossa.$B$BNon puoi dirti $Gun avventuriero esperto:un'avventuriera esperta; finché non hai passato un po' di tempo ad ammazzare ratti! Ah!",
  obj = "Porta 8 Dig Rat a Grub, a est del Crossroads.",
  progress = "Hai già fatto fuori abbastanza ratti di fossa, $N?",
  reward = "Di solito non mi piace mangiare questi roditori quando sono così... così... maturi. Mi piace lasciarli marcire per qualche settimana, per far uscire davvero il sapore. Ma sembri così $Gaffamato:affamata;.$B$BLascia che ti prepari un po' di Stufato di Ratto di Fossa. Ah, ecco fatto.$B$BEcco a te!",
  en_title = "Dig Rat Stew",
  en_obj = "Bring 8 Dig Rats to Grub east of the Crossroads.",
}
T[864] = {
  title = "Ritorno dalla Speziale Zinge",
  desc = "\"Ecco qua, la fonte di energia è stata tolta senza danni e i dati sono salvi. Be', buon viaggio e tutto il resto. Spero che il tuo losco esperimento scientifico ti sia riuscito, e via dicendo.\"$B$BIl goblin ti volta le spalle per occuparsi delle richieste della Gadgetzan Water Company. Metti al sicuro l'attrezzatura per le analisi sigillata in vista del viaggio di ritorno a Undercity. Lì la Speziale Zinge aspetta te e l'attrezzatura per le analisi da campo sigillata.",
  obj = "Porta il Sealed Field Testing Kit ad Apothecary Zinge a Undercity.",
  progress = "$GBentornato:Bentornata;. O almeno, $Gbentornato:bentornata; se sei $Gtornato:tornata; con un'attrezzatura per le analisi sigillata. Altrimenti fingerò di non notare la tua totale incompetenza e ti risparmierò la mia ira finché non avrai fatto ciò che ti è stato ordinato e portato a termine il mio incarico.",
  reward = "Analizzerò subito questi dati. Forse, alla fine, la follia di Keever si rivelerà il mio genio.$B$BQuanto a te... mi sei utile, e io ricompenso piuttosto bene chi continua a essere utile. Prendi questo oggetto, queste monete e, cosa più importante, il mio ringraziamento.$B$BRipassa da me di tanto in tanto — scommetto che la nostra collaborazione a questo progetto non è finita.",
}
T[866] = {
  title = "Campioni di Radice",
  desc = "Le erbe delle Barrens non sono proprio come quelle di altre terre. Le loro proprietà sono quasi le stesse, ma l'acqua delle oasi di qui altera le piante: sono appena un po' diverse.$B$BVoglio studiare quelle differenze... per vedere se si possono sfruttare!$B$BSe te ne intendi di erbalismo, raccogli campioni di radice dalle erbe che trovi nelle Barrens. Portami questi campioni, così posso confrontarli con le erbe di altre regioni.",
  obj = "Porta 8 Root Sample a Mebok Mizzyrix, a Ratchet.",
  progress = "Ciao, $N. Hai raccolto quei campioni di radice?",
  reward = "Sì sì, questi sono molto belli! Da queste radici coltiverò degli esemplari e li studierò. Spero di scoprirne proprietà nuove. Proprietà nascoste, preziose...!$B$BE non preoccuparti — se le trovo, sarai $Gil primo:la prima; a saperlo. Perché mi servirà qualcuno che ne raccolga altri!",
  en_title = "Root Samples",
  en_obj = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.",
}
T[868] = {
  title = "Caccia alle Uova",
  desc = "Ehi, $N. Io è stato mandato al Crossroads a sorvegliare la terra e a prendere nota di quello che ci succede, per i miei padroni a Orgrimmar.$B$BTra le cose che studio ci sono quelle creature simili a insetti che vivono a sud, nel Campo dei Giganti. Sappiamo poco di quelle creature, e io ci tiene a scoprire di più. Sembrano avere una loro intelligenza, più di qualunque animale normale.$B$BPrendi questo artiglio scavatore e raccogli qualche uovo delle creature dai loro cumuli, ma sta' $Gattento:attenta;: se le allarmi, ti attaccano.",
  obj = "Porta 12 Silithid Egg e il Digging Claw a Korran, al Crossroads.",
  progress = "Sta' $Gattento:attenta; con le uova che trovi, $N. Se si rompono, per me loro non è buone a niente.",
  reward = "Sono soddisfatto di te, $N. Le uova e l'attrezzo. Ben fatto.$B$BE come ricompensa...",
  en_title = "Egg Hunt",
  en_obj = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",
}
T[873] = {
  title = "Isha Awak",
  desc = "Il grande Isha Awak è signore di queste acque. Grande è la sua forza, e solenne il suo orgoglio. Gli umani sulla costa lo temono, perché ne ha divorati molti.$B$BMa io non lo temo. Sono grata che sia qui. È una sfida degna, e una nobile preda.$B$BSe sei $Gpronto:pronta;, allora nuota al largo e cerca Isha Awak, la Rovina degli Abissi.$B$BIl suo spirito dimora nel suo cuore, e sentirne il battito è conoscere il proprio destino.",
  obj = "Porta l'Heart of Isha Awak a Mahren Skyseer.",
  progress = "Non temere le acque, $R.",
  reward = "Ora sei una cosa sola con Isha Awak, $N. Il suo spirito è con te. È in agguato nei tuoi occhi...$B$BOcchi che, un giorno, impareranno a vedere.",
  en_title = "Isha Awak",
  en_obj = "Bring the Heart of Isha Awak to Mahren Skyseer.",
}
T[874] = {
  title = "Mahren Skyseer",
  desc = "Hai cacciato le bestie delle Barrens. Il tuo spirito è forte. Ma un cacciatore deve essere sempre pronto. Un vero cacciatore sa inseguire la preda per qualunque sentiero. Montagne e paludi non $Glo:la; faranno vacillare.$B$BE nemmeno il mare.$B$BTrova mia sorella, Mahren. Caccia le grandi bestie d'acqua lungo la costa. Sarà lei a insegnarti a conoscerle.$B$BMa sta' $Gattento:attenta; mentre la cerchi, perché la costa delle Barrens è in mano agli umani.",
  obj = "Parla con Mahren Skyseer.",
  reward = "Ti manda mio fratello, vero? Allora devi esserti $Gguadagnato:guadagnata; la sua stima. Se hai ottenuto il rispetto di Jorn, hai anche il mio.$B$BSei $Gpronto:pronta; a spingerti più avanti sulla via del cacciatore?",
  en_title = "Mahren Skyseer",
  en_obj = "Speak with Mahren Skyseer.",
}
T[878] = {
  title = "Tribù in Guerra",
  desc = "Devi colpire i miei nemici. <grugnito> Devi aiutare Mangletooth e i Razormane indebolendo i Bristleback. Tutte e due le tribù sono molto spirituali — legate alla terra e al suo potere. <grugnito> Ci dà forza in ogni cosa... soprattutto in guerra.$B$BSe vuoi scoprire chi causa davvero a Thork <grugnito> e all'Orda tanto tormento, allora aiuta Mangletooth! Attacca i capi spirituali dei Bristleback a nord; indeboliscili, così i Razormane potranno sconfiggerli e dominare le Barrens.",
  obj = "Uccidi 6 Bristleback Water Seeker, 12 Bristleback Thornweaver e 12 Bristleback Geomancer, poi torna da Mangletooth a Camp Taurajo, nelle Barrens.",
  progress = "Altre informazioni <grugnito> per l'Orda quando avrai ucciso i saggi dei Bristleback, $R. <grugnito> Non un momento prima! Mangletooth non è uno sciocco.",
  reward = "Sì, sì... pieno di gioia perché finalmente <grugnito> i Bristleback conoscono il dolore della mia tribù, $R. Così dovrei sentirmi, ma <grugnito> non è così.$B$BTu aiuti la tua gente e loro ti onorano. Mangletooth aiuta la sua gente, e loro che fanno? Gli voltano le spalle. Lo dimenticano e lo lasciano marcire in gabbia!$B$BIo li aiuto perfino da chiuso dietro le sbarre, e loro non mandano nessuno a salvarmi!",
  en_title = "Tribes at War",
  en_obj = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.",
}
T[879] = {
  title = "Tradimento dall'Interno",
  desc = "Tre della mia tribù sono usciti dal Kraul per guidare le incursioni contro l'Orda, $R. <grugnito> Sono spietati e astuti, e se li sconfiggi, allora il tuo Crossroads e perfino gran parte delle Barrens conosceranno la pace... <grugnito> almeno da parte della tribù Razormane. <grugnito>$B$BNak, Kuz e Lok Cacciaorchi sono quelli che cerchi. Sono nell'estremo sud delle Barrens. Uno è un incantatore, un altro un segugio, e il loro capo, quello che chiamano Cacciaorchi, <grugnito> un guerriero. Uccidili, $R, come hanno ucciso me.",
  obj = "Uccidi Nak, Kuz e Lok Orcbane e porta i loro teschi a Mangletooth, a Camp Taurajo, nelle Barrens.",
  progress = "Come va la tua caccia, $R? <grugnito>$B$BThork crede di sapere la verità su chi guida le incursioni contro la sua gente, <grugnito> ma scoprirà quanto si sbaglia, se ci riesci.$B$BLa mia morte è inevitabile, ma tu hai inflitto un grande dolore ai miei nemici, quindi Mangletooth non rimpiange nulla. <grugnito>",
  reward = "È fatta, allora. Meglio che finisca così, dice Mangletooth. <grugnito> Avrebbero dovuto <grugnito> assicurarsi che fossi morto quando mi hanno voltato le spalle, invece di lasciarmi <grugnito> qui in questa gabbia maledetta.$B$BResta un solo incarico da portare a termine, $R.",
  en_title = "Betrayal from Within",
  en_obj = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.",
}
T[883] = {
  title = "Lakota'mani",
  desc = "Lo Zoccolo di Lakota'mani è un simbolo della forza del grande kodo.",
  obj = "Porta l'Hoof of Lakota'mani a Jorn, a Camp Taurajo.",
  progress = "$N, quando ti sei $Gavvicinato:avvicinata; ho visto un potere nuovo nel tuo passo. Dimmi — il tuo spirito ha incontrato il grande Lakota'mani?",
  reward = "Lakota'mani nella nostra lingua si chiama \"Scuotiterra\", e i suoi passi sono come tuoni che si addensano. Ora è con te, e il suo coraggio si mescola al tuo. Insieme non c'è scontro che non possiate affrontare.$B$BCammina a testa alta, $N. Cammina a testa alta, Scuotiterra.",
  en_title = "Lakota'mani",
  en_obj = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.",
}
T[884] = {
  title = "Owatanka",
  desc = "Al tocco, dalla spina della coda di Owatanka volano scintille.",
  obj = "Porta Owatanka's Tailspike a Jorn, a Camp Taurajo.",
  progress = "$N, c'è un potere nuovo dietro i tuoi occhi! Hai incontrato il possente Owatanka, non è vero?",
  reward = "Il sauro del tuono Owatanka è chiamato \"Fulmine Azzurro\" dai tauren, perché in lui c'è una velocità che la sua mole non lascerebbe immaginare. Si dice che un fulmine abbia colpito Fulmine Azzurro molto tempo fa e che, nutrita dall'ira del cielo, l'energia della grande bestia sia senza limiti.$B$BChe la sua energia scorra in te, $N. Ora, infatti, tieni il passo di Owatanka.",
  en_title = "Owatanka",
  en_obj = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.",
}
T[885] = {
  title = "Washte Pawne",
  desc = "La piuma di Washte Pawne fa male al tatto.",
  obj = "Porta Washte Pawne's Feather a Jorn Skyseer, a Camp Taurajo.",
  progress = "C'è una nuova determinazione dentro di te, $N. Una determinazione nata dal dolore...$B$BTi pesa la morte di Washte Pawne?",
  reward = "Il falco del tuono è una bestia rara delle Barrens, e la sua morte può presagire grande fortuna, o grande rovina.$B$BMa Washte Pawne, chiamato \"Mordispirito\" in Taurahe, non può portare né l'una né l'altra... o tutte e due.$B$BIl dolore che hai provato cacciando Mordispirito è la fitta che provano tutti quelli che ottengono molto a caro prezzo. Il bruciore che hai sentito è il dolore del rimpianto.$B$BMa vedo che l'hai vinto. Hai imparato che il rimpianto diventa saggezza, e che dal dolore nasce la forza.$B$BHai imparato molto, $N.",
  en_title = "Washte Pawne",
  en_obj = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.",
}
T[893] = {
  title = "Armi Preferite",
  desc = "I verrospini Razormane a sud, oltre il Campo dei Giganti, non hanno fabbri esperti, da quel che mi risulta, ma a quanto pare hanno cominciato a mettere a punto armi più robuste. Vorrei mettere le mani su qualche tipo diverso, per imparare le loro tecniche, se possibile.$B$BSe vuoi fare onore all'Orda, allora portami degli esemplari delle loro armi. Trovami un pugnale dai loro predatori, una bacchetta dai loro veggenti e uno scudo dai loro guerrieri furiosi. Andrà benissimo!",
  obj = "Porta un Razormane Backstabber, un Charred Razormane Wand e un Razormane War Shield a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.",
  progress = "Anch'io dubito che quei patetici verrospini possano raggiungere un qualche livello di abilità nell'arte del fabbro, ma faccio come comanda il Capoguerra, e imparerò quello che posso sulla tribù Razormane.$B$BHo avuto incarichi più umili di questo, e li svolgo volentieri se servono al popolo degli orchi.",
  reward = "Esemplari eccellenti, davvero eccellenti.$B$BI verrospini sono più avanti di quanto mi aspettassi.$B$BEcco, $C, prendi questo e togliti di mezzo. È meglio che dia un'occhiata più attenta a queste armi. Potremmo aver sottovalutato il nemico, ed è il tipo di errore che non possiamo permetterci.",
  en_title = "Weapons of Choice",
  en_obj = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[897] = {
  title = "Il Falciatore",
  desc = "Questa strana creatura simile a un insetto sembra fuori dall'ordine naturale, come se non appartenesse alle Barrens.",
  obj = "Porta l'Harvester's Head a Jorn Skyseer.",
  progress = "Sembravi $Gturbato:turbata;, $N. Come vanno le tue lezioni nelle Barrens? Hai trovato qualcosa che ti inquieta?",
  reward = "Non so dire nulla della natura di questa bestia, perché il suo spirito è fuggito. Ma come avevi intuito, non appartiene alle Barrens. Temo che possa annunciare un futuro cupo per la nostra gente...$B$BMa per ora preparati, e speriamo che il tempo sciolga il mistero di questa creatura.",
  en_title = "The Harvester",
  en_obj = "Bring the Harvester's Head to Jorn Skyseer.",
}
T[906] = {
  title = "Tradimento dall'Interno",
  desc = "Porta la testa di Lok a Thork, al Crossroads, $R. <grugnito> Dovrebbe capire cos'è successo alla mia tribù senza bisogno di parole — ah, non che crederebbe mai che Mangletooth abbia dato una mano <grugnito> in cose del genere. Ma sono sicuro che ti ricompenserà per aver compiuto un'impresa simile. <grugnito>$B$BContinuerò a benedirti con il potere di Agamaggan finché resterò in questa gabbia, $R. Fino ad allora, addio.",
  obj = "Porta Lok's Skull a Thork, al Crossroads, nelle Barrens.",
  progress = "Sì, che c'è?",
  reward = "Hai trovato il capo dei Razormane e l'hai ucciso con le tue mani, $N? Straordinario.$B$BMi mancano le parole, ma non la gratitudine. La gente del Crossroads farebbe bene a rispettare la tua forza.$B$BDevo ammetterlo: credevo che il capo di queste incursioni contro le nostre linee di rifornimento fosse un altro verrospino. Grazie ancora, $N.",
  en_title = "Betrayal from Within",
  en_obj = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.",
}
T[908] = {
  title = "Tra le Rovine",
  desc = "Il Martello del Crepuscolo si è insediato nelle Rovine di Moonshrine delle Blackfathom Deeps. La sua presenza non può che costringere gli elementi a lavorare contro di noi. Se non lo fermiamo, questa regione sarà sua per sempre.$B$B$N, va' a Blackfathom e trova la pietra profonda delle rovine; dovrebbe essere lì vicino, nell'acqua. Dentro c'è un nucleo profondo — un congegno che, letto come si deve, racconta la storia di tutta l'attività elementale. Se riesco ad averlo, io e il Circolo della Terra forse potremo fare qualcosa per fermarlo!",
  obj = "Porta il Fathom Core a Je'neu Sancrea all'Avamposto di Zoram'gar, in Ashenvale.",
  progress = "Sei $Griuscito:riuscita; a individuare il nucleo profondo? Senza quello, non avremo idea di cosa stia combinando esattamente il Martello del Crepuscolo laggiù.",
  reward = "È esattamente quello che mi serve! Un nucleo profondo è una fonte incredibile di informazioni, da cui potremo ricavare molto di buono. Qualunque cosa stia combinando il Martello del Crepuscolo là dentro — e credimi quando dico che non è niente di buono — io e i miei compagni ora la scopriremo.$B$BOggi hai fatto un buon lavoro; il Circolo della Terra ti guarda con favore per l'aiuto che ci hai dato. Hai aiutato anche tutta l'Orda, e di questo dovresti andare $Gfiero:fiera;.",
}
T[909] = {
  title = "Barone Aquanis",
  desc = "L'elementale dell'acqua sconfitto ha lasciato uno strano globo d'acqua. Ne deduci che in qualche modo l'oggetto dava energia alla bestia. Dentro il globo sciaborda un'acqua dall'aspetto putrido. Il globo in sé sembra immune a qualsiasi forza fisica.$B$BSe c'è qualcuno che può venire a capo di questo oggetto, è Je'neu Sancrea del Circolo della Terra. Si trova all'Avamposto di Zoram'gar dell'Orda, in Ashenvale.",
  obj = "Porta lo Strange Water Globe a Je'neu Sancrea, all'Avamposto di Zoram'gar, in Ashenvale.",
  progress = "Ah, ciao di nuovo, $N. Stavo giusto leggendo le onde del mare, come faccio sempre. Cosa ti porta all'avamposto?",
  reward = "Questo... questo è proprio un bel ritrovamento, $N.$B$BDici di averlo preso al Barone Aquanis, a Blackfathom? Il Barone Aquanis è considerato da tempo una potenza elementale corrotta; questo globo dimostrerà che cosa esattamente lo abbia corrotto. Non sarebbe una sorpresa scoprire che è stato il Martello del Crepuscolo, ma i nostri studi mostreranno anche come ci sono riusciti.$B$BHai fatto bene a portarmelo. Ecco — prendi questo, con i più calorosi saluti del Circolo della Terra.",
}
T[910] = {
  title = "Giù al Porto",
  desc = "Ho sentito racconti sulle grandi navi che fanno la spola tra Ratchet e Booty Bay! Sarebbe fantastico navigare sull'oceano e combattere in tante grandi battaglie navali. Forse da grande sarò un possente marinaio dell'Orda! Sì!$B$BMi porteresti a vedere il porto di Ratchet, per piacere? Prometto che non entrerò in acqua e non combinerò guai: voglio solo vedere le navi grandi e sentire l'odore dell'acqua salata! Sì!",
  obj = "Porta il tuo protetto al porto di Ratchet, nelle Barrens.",
  progress = "Siamo arrivati?",
  reward = "Wow, l'oceano è ENORME! C'erano anche tanti gabbiani e roba del genere: è rumoroso e movimentato proprio come pensavo. E ci sono pure dei pirati qui vicino: troppo forte!$B$BGrazie di avermi portato a Ratchet, $N. È stato fantastico!",
  en_title = "Down at the Docks",
  en_obj = "Take your ward to the docks of Ratchet in the Barrens.",
}
T[911] = {
  title = "La Porta della Frontiera",
  desc = "Dicono che Ashenvale sia la nuova frontiera, e che il Bastione di Mor'shan, nelle Barrens, ne sia la porta. Sarebbe fantastico essere un pioniere e ricavare tutto quello che ti serve dalle terre selvagge! Dicono che sarà lì che l'Orda e l'Alleanza si scontreranno di più in futuro, e io voglio esserci, $N!$B$BMi porteresti al Bastione di Mor'shan, così vedo com'è la frontiera, per piacere? Voglio vedere dove l'Orda sta cacciando via quei puzzolenti elfi della notte!",
  obj = "Porta il tuo protetto al Bastione di Mor'shan, nella parte settentrionale delle Barrens, poco prima di entrare ad Ashenvale.",
  progress = "Siamo arrivati?",
  reward = "Wow, è ad Ashenvale che si vivono le vere avventure! Hai mai combattuto ad Ashenvale, $N? Quando da grande diventerò un eroe, voglio venire ad Ashenvale a combattere per la gloria dell'Orda!$B$BGrazie di avermi portato alla frontiera, $N. Sei $Gil migliore:la migliore;!",
  en_title = "Gateway to the Frontier",
  en_obj = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.",
}
T[912] = {
  title = "Travestimento da Trogg Stonesplinter",
}
T[914] = {
  title = "I Capi dei Fang",
  desc = "I druidi delle Wailing Caverns, i Druids of the Fang, sono un'aberrazione. Facevano parte di un ordine di nobili druidi il cui piano era guarire le Barrens, ma ora cercano di rimodellare quella terra a immagine dei loro sogni contorti.$B$BI Druids of the Fang hanno quattro capi, e ognuno possiede una gemma di sogno. Ancora adesso i loro volti mi perseguitano! Sconfiggi i capi e portami le loro gemme, e le Barrens potranno conoscere di nuovo la pace.$B$BVa', $N. Li troverai in agguato nel profondo delle Wailing Caverns.",
  obj = "Porta la Gem of Cobrahn, la Gem of Anacondra, la Gem of Pythas e la Gem of Serpentis a Nara Wildmane, a Thunder Bluff.",
  progress = "I ricordi dei miei incubi mi perseguitano, $N. Hai sconfitto i capi dei fang e preso le loro gemme?",
  reward = "Ce l'hai fatta, $N. Hai ucciso i capi dei Druids of the Fang. I miei sogni ora sono liberi dai loro volti malvagi, e hai contribuito a salvare le Barrens da un futuro maledetto.$B$BTi ringrazio, $N. Ti ringrazio a nome mio, dei druidi di Thunder Bluff e di questa terra.",
  en_title = "Leaders of the Fang",
  en_obj = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",
}
T[915] = {
  title = "Tu Gridi, Io Grido...",
  desc = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Gelato alla Fragola di Tigule e Foror! È il mio gelato preferito in tutto il mondo!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Gelato alla Fragola di Tigule e Foror??!?!",
  obj = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!",
  reward = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!$B$BGrazie mille, $N: è la cosa più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[925] = {
  title = "Impronta di Zoccolo di Cairne",
  desc = "Dicono che Cairne Bloodhoof sia uno dei più grandi eroi che l'Orda abbia mai visto. Da grande voglio essere un eroe dell'Orda anch'io!$B$BConosci Cairne, $N? Mi faresti un favore, per piacere? Potresti procurarmi l'impronta del suo zoccolo? Non so come chiederglielo, e probabilmente sarebbe troppo occupato per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lui! Scommetto che a te l'impronta la darebbe subito!$B$BPer piacere?",
  obj = "Raggiungi Thunder Bluff e cerca di ottenere l'impronta dello zoccolo di Cairne Bloodhoof per il tuo protetto.",
  progress = "Quando gli orchi erano soli e senza amici, i tauren li accolsero in una terra sconosciuta e condivisero tutto con loro senza chiedere niente in cambio. Questo è onore, $N.",
  reward = "WOW! Mi hai procurato l'impronta dello zoccolo di Cairne! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stato fantastico, lo sapevo! Magari un giorno lo ringrazierò di persona... quando diventerò un eroe dell'Orda!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.",
  en_title = "Cairne's Hoofprint",
  en_obj = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.",
}
T[936] = {
  title = "Aiutare l'Arcidruido Runetotem",
  desc = "Scusami, $C, ma vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Thunder Bluff è molto interessato a trovare avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.$B$BTi prego — se ti interessa, parla direttamente con lui sull'Altura degli Anziani, dentro Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem, a Thunder Bluff.",
  reward = "Salve, $C; sono lieto che tu voglia aiutare la nostra ricerca. C'è molto da fare, e ti renderei un cattivo servizio se ti dicessi che questo lavoro non è pericoloso. Spero che questo non ti spaventi... ma, a giudicare dal tuo aspetto, direi che col pericolo hai già avuto a che fare.",
}
T[939] = {
  title = "Il Flauto di Xavaric",
  desc = "Esamini il semplice flauto di legno che hai raccolto dopo aver sconfitto Xavaric.$B$BIl legno nodoso è solido al tatto, ma mentre te lo rigiri fra le mani sembra che le spirali e i motivi della superficie comincino a girare e a muoversi. All'improvviso, provi un senso di terrore...$B$BScuoti la testa, $Gsicuro:sicura; che la mente ti stia giocando qualche scherzo.$B$BÈ possibile che altri satiri abbiano con sé indizi su ciò che hai trovato. Porta quello che hai scoperto alla druida, Eridan Bluewind, che vive nel sud di Felwood.",
  obj = "Porta il Flute of Xavaric e 5 campioni di Jadefire Felbind a Eridan Bluewind, nel sud di Felwood.",
  progress = "Che succede, $C? Hai l'aria preoccupata.",
  reward = "Sento la sofferenza degli antichi, $N...$B$BTenere in mano questi oggetti è quasi insopportabile...",
}
T[943] = {
  title = "Il Prospettore Distratto",
  desc = "Ora il fossile originale ce l'ha il Prospettore Whelgar, ai suoi scavi nelle Wetlands. Quando ho scoperto la Pietra di Relu, ero convinto che fosse la chiave per svelare il mistero del fossile.$B$BMentre ero in viaggio per incontrare Whelgar, sono stato attaccato dai raptor e la reliquia è andata persa. Non so quale di quelle bestie chiazzate abbia ingoiato la reliquia, ma se riesci a recuperarla potrò scatenare il potere di questi artefatti.$B$BPortami sia la Pietra di Relu sia il fossile originale che ha lui.",
  obj = "Archaeologist Flagongut, a Menethil Harbor, vuole che tu gli porti la Stone of Relu e Flagongut's Fossil.",
  progress = "Con la Pietra di Relu riuscirò a liberare i segreti nascosti del mio fossile e anche del fossile di Remtravel, quello di Darkshore, $N.",
  reward = "Ottimo, $N!$B$BOra vediamo se riesco a usare la pietra per decifrare i poteri dei fossili.",
  en_title = "The Absent Minded Prospector",
  en_obj = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.",
}
T[959] = {
  title = "Problemi ai Moli",
  desc = "Ops!$B$BC'è stato un piccolo incidente, come vedi! Il carico che è arrivato stamattina da Booty Bay era enorme. Enorme, ti dico! Non ho mai visto tante casse. Be', cercavo di sbrigarmi e ho cominciato a scaricare un po' più di quanto riuscissi a reggere. Ed è lì che è venuto giù tutto.$B$BPrima che capissi cosa stava succedendo, ho visto quella peste di Magglish il Pazzo scappare via con una bottiglia di porto di 99 anni. L'ho inseguito fino alle Wailing Caverns. Là dentro non ci entravo di sicuro.$B$BMagari tu sei abbastanza $Gcoraggioso:coraggiosa; da trovarlo?",
  obj = "Crane Operator Bigglefuzz, a Ratchet, vuole che tu recuperi la bottiglia di 99-Year-Old Port da Mad Magglish, che si nasconde nelle Wailing Caverns.",
  progress = "Il capo del molo mi sta addosso da quando Magglish il Pazzo è scappato con quel porto di 99 anni. A quanto pare quella bottiglia era un regalo per Gazlowe niente meno che dal Barone Revilgaz in persona.$B$BSe sei abbastanza $Gcoraggioso:coraggiosa; e paziente da cercare Magglish il Pazzo e recuperare quella bottiglia, farò in modo che tu abbia una bella ricompensa.",
  reward = "Magnifico! E proprio mentre stavo per perdere il lavoro! Farò in modo che Gazlowe riceva subito questo regalo.$B$BGrazie, $N. Ben fatto, ti dico!",
  en_title = "Trouble at the Docks",
  en_obj = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",
}
T[962] = {
  title = "Bocciolo di Serpente",
  desc = "La Royal Apothecary Society, con sede nella grande Undercity di Lordaeron, mi ha mandata qui per un incarico ben preciso, $N. Forse vuoi aiutare me e, di conseguenza, la Signora Oscura, nel nostro impegno per la causa dei Reietti.$B$BDi recente ho studiato un raro esemplare di flora chiamato Bocciolo di Serpente. Credo che in quantità maggiori questa erba abbia un grande potenziale.$B$BPurtroppo il Bocciolo di Serpente si trova solo nei recessi più bui delle Wailing Caverns, un sistema di grotte pericoloso che si trova nelle Barrens.",
  obj = "Apothecary Zamah, a Thunder Bluff, vuole che tu raccolga 10 Serpentbloom.",
  progress = "Non vedo l'ora di scoprire se riesci a raccogliere abbastanza Boccioli di Serpente nelle Wailing Caverns. Ho mandato molti a eseguire i miei ordini, ma nessuno è tornato.",
  reward = "Ah, splendidi esemplari. Hai fatto un ottimo lavoro, $N.",
  en_title = "Serpentbloom",
  en_obj = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
}
T[964] = {
  title = "Frammenti Scheletrici",
  desc = "La chiave di Scholomance si chiama Chiave Scheletrica. Va forgiata con i resti di uno scheletro — di parecchi, in realtà — e indurita solo con i metalli più resistenti, dentro uno stampo adatto. A farla funzionare, alla fine, sarà un sigillo di potere di un essere che per natura può aprire il portale di Scholomance.$B$BMa una cosa alla volta, $N. Per forgiare la chiave ci serviranno dei frammenti scheletrici. Gli scheletri dentro Andorhal dovrebbero darci quello che ci serve, ma potrebbero andare bene anche quelli fuori dalle mura.",
  obj = "Porta 15 Skeletal Fragments ad Apothecary Dithers al Bulwark, nelle Western Plaguelands.",
  progress = "Uccidine tanti e uccidine spesso, $C — ci servirà una bella scorta di frammenti scheletrici adatti per fare lo strato esterno della chiave. Non la chiamano Chiave Scheletrica per niente, sai.",
  reward = "Questi andranno bene, $N! Ora tocca a me — infonderò in questi frammenti una tempra adatta, che permetterà loro di resistere all'intensa forgiatura che prima o poi dovranno subire.$B$BIl prossimo passo sarà procurarsi uno stampo adatto per la chiave. Conosco un fabbro goblin a Tanaris che in passato ha fatto stampi per oggetti altrettanto macabri. Serve chi di solito servono i goblin — il miglior offerente.",
}
T[969] = {
  title = "Che la Fortuna Sia con Te",
  desc = "Ah, mi basta guardarti per capirlo — tu vuoi farti un amuleto portafortuna. Mau'ari lo sa sempre!$B$BA sud troverai un canyon, e dei giganti fatti di ghiaccio massiccio. Certe volte i giganti se li portano addosso, ma i frammenti te li puoi sempre raccogliere da te nel canyon. Questi frammenti hanno un forte potere riflettente.$B$BPortami 10 frammenti frostmaul, e il mio amuleto portafortuna sarà tuo.",
  obj = "Raccogli 10 Frostmaul Shards per Witch Doctor Mau'ari a Everlook.",
  progress = "Portami i frammenti, e ti dico di più!",
  reward = "Ahh, sì... Adesso ti faccio l'amuleto. Aspetta e vedrai!",
}
T[970] = {
  title = "La Torre di Althalaxx",
  desc = "La lettera di Balthule è allarmante. Questo Cult of the Dark Strand è una spina nel fianco che va tolta. Da qualche tempo tengo a bada un po' di quella feccia del Dark Strand, a nord-est di qui, a Ordil'Aran. Uno di loro possiede una gemma dell'anima che, credo, racchiude il segreto del potere del culto.$B$BPortamela, e riuscirò a decifrare i segreti che contiene.",
  obj = "Procurati una Glowing Soul Gem e portala a Delgren the Purifier, a Maestra's Post.",
  progress = "Hai recuperato quella gemma dell'anima?",
  reward = "Hmm, questa pietra dell'anima è stregata da una magia oscura. Vediamo cosa c'è intrappolato dentro, che ne dici?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.",
}
T[971] = {
  title = "Conoscenza nelle Deeps",
  desc = "Come forse saprai, io colleziono sapere. Sapere antico. Sapere potente. Sapere che apre porte, e sapere che può risvegliare Coloro Che Dormono.$B$BCorre voce che un antico frammento di sapere, il Manoscritto di Lorgalis, si trovi in fondo alle Blackfathom Deeps, in Ashenvale. Quel luogo è l'antica dimora di elfi morti da tempo. Elfi che possedevano una grande conoscenza, prima che la loro città cadesse in rovina.$B$BCerca il manoscritto nelle Blackfathom Deeps. Fallo, e non me ne dimenticherò. Nemmeno dopo... i giorni della fine.",
  obj = "Porta il Lorgalis Manuscript a Gerrig Bonegrip, nella Forlorn Cavern a Ironforge.",
  progress = "Il viaggio fino ad Ashenvale è lungo, e il tuo compito non è facile. Ma se mi porti il manoscritto, $N... allora la tua ricompensa sarà grande.",
  reward = "Hai trovato il manoscritto! Che giorno di gioia! Se ne faranno copie da distribuire, e l'antica conoscenza di Lorgalis sarà finalmente nota ai miei fratelli e alle mie sorelle!$B$BQuello che hai fatto per noi vale più di quanto immagini, $N. Ma spero che questo dono ti mostri la gratitudine che riserviamo ai nostri alleati.",
  en_title = "Knowledge in the Deeps",
  en_obj = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",
}
T[972] = {
  title = "Sapta d'Acqua",
  reward = "Prendi la sapta d'acqua e trova la pozza d'acqua corrotta a Silverpine, $N. Ho molta fiducia nelle tue capacità.",
  en_title = "Water Sapta",
}
T[973] = {
  title = "La Torre di Althalaxx",
  desc = "Ilkrud Magthrull. Sì, so chi è. È un potente stregone orco che dimora al Santuario dello Sfregio Rovente, un luogo di grande malvagità nel sud-ovest di Ashenvale.$B$BFinora è stato poco più di una seccatura e non me ne sono occupato, ma pare che sia giunta la sua ora.",
  obj = "Porta Ilkrud Magthrull's Tome a Delgren the Purifier, a Maestra's Post.",
  progress = "Sembri un po' $Gscosso:scossa;, $N. Stai bene?",
  reward = "Oggi hai fatto una grande cosa, $N. Dovresti essere molto $Gfiero:fiera; di te per aver tenuto testa a uno stregone così potente.$B$BOra vediamo cosa possiamo imparare dagli scritti di Ilkrud.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.",
}
T[974] = {
  title = "Alla Ricerca della Fonte",
  desc = "Le sorgenti calde di qui per me sono un mistero. Da dove viene il calore?$B$BVedendo quanto sono vicine le pozze al Rilievo del Magma Colante, mi chiedo proprio se non c'entri qualcosa il vulcano. Ho costruito un termometro per misurare le temperature sul vulcano, e vorrei trovarne il punto più caldo. Dà le misure in gradi Kraklenheit!$B$BEcco, prendilo, e misura la temperatura sul rilievo ogni volta che vedi un punto caldo!",
  obj = "Krakle, a Un'Goro Crater, vuole che trovi la zona più calda di Fire Plume Ridge.$B$BOgni volta che trovi un punto caldo, fai clic destro su Krakle's Thermometer per controllare la temperatura. Continua a cercare finché non trovi il più caldo.",
  progress = "Ci andrei io, ma... ho un po' paura degli elementali del fuoco che ci sono là!",
  reward = "Sì, qui vedo chiaramente la correlazione fra la temperatura del vulcano e le sorgenti calde. Dovrò ricontrollare che le mie equazioni siano esatte, ma a quanto pare la distanza e la velocità con cui si trasmette il calore... Mmm...",
}
T[975] = {
  title = "Cassa di Mau'ari",
  desc = "Ora, prima di darti quest'amuleto, è meglio che ti spiego come si usa.$B$BSe ti porti dietro l'amuleto, vedrai che certi oggetti cadranno dalle creature che combatti. Se non hai l'amuleto con te, non li troverai. Capito?$B$BQuesti oggetti speciali li riconoscerai dal nome — si chiamano E'ko. Se ne trovi qualcuno, portalo alla vecchia Mau'ari, e lei ti dà una mano.$B$BAspetta qui mentre ti sistemo l'amuleto.",
  obj = "Parla di nuovo con Witch Doctor Mau'ari fra un momento per ricevere l'amuleto portafortuna.",
  reward = "Eccolo, $N. Ricorda, te lo devi portare dietro. Perché non torni nelle terre selvagge, a vedere cosa ci trovi?",
}
T[976] = {
  title = "Rifornimenti per Auberdine",
  desc = "Delgren mi ha chiesto di consegnare messaggi e rifornimenti alla Sentinella Starbreeze ad Auberdine, ma non me la sento di partire da solo. Nemici pericolosi si aggirano per la foresta, e non voglio rischiare che questi rifornimenti e queste informazioni finiscano nelle mani sbagliate.$B$BSe tu e altri faceste da scorta, potrei partire subito. Con la vostra protezione non ho dubbi che riusciremo a portare questi beni al sicuro fino ad Auberdine.",
  obj = "Parla con Delgren the Purifier a Maestra's Post dopo aver portato Feero sano e salvo attraverso l'Ashenvale Forest.",
  progress = "Le Sentinelle hanno grande bisogno di rifornimenti per rafforzarsi a Darkshore.",
  reward = "Oggi hai fatto un buon lavoro, $C. Gli oggetti che abbiamo mandato in aiuto ad Auberdine serviranno subito ad affrontare le minacce oscure che infestano la foresta.$B$BPrendi questi, con la mia sincera gratitudine.",
  en_title = "Supplies to Auberdine",
  en_obj = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.",
}
T[977] = {
  title = "Siamo Arrivati, Yeti?",
  desc = "Ora che ho quello che mi serve per coprire le parti meccaniche mobili, mi manca solo un'altra cosa. Anzi, due. Due corna!$B$BI patriarchi e le matriarche ice thistle hanno le corna più grandi, quindi ovviamente sono quelle che voglio. Quel tipo di yeti vive in una grotta a sud-est. Lì ce ne sono in abbondanza; non dovresti avere problemi a trovarli.$B$BRicorda, voglio solo quelle più belle — niente corna rovinate o spezzate, per favore!",
  obj = "Raccogli 2 Pristine Yeti Horns per Umi Rumplesnicker a Everlook.",
  progress = "Ho quasi finito di attaccare la pelliccia, $N. Per favore, torna presto con quelle corna!",
  reward = "Non vedo l'ora di farlo vedere ai miei amici! Ora aspetta solo un momento, mentre attacco queste...$B$BPerfetto!",
}
T[978] = {
  title = "Wildkin Toccati dalla Luna",
  desc = "Le penne di Wildkin delle Hinterlands sembrano contenere tracce di proprietà magiche. Questi poteri... non sembra che siano le creature a servirsene, è più come se fossero semplicemente innati nella specie — parte della sua stessa essenza.$B$BDurante i miei studi ho sentito che una numerosa popolazione di wildkin abita le terre innevate di Winterspring. Che queste creature abbiano gli stessi poteri? Ti prego, aiutami a trovare una risposta, $N. Vai a Winterspring e raccogli le penne cadute a terra, poi torna da me.",
  obj = "Raccogli 10 Moontouched Feathers a Winterspring, poi torna da Erelas Ambersky a Rut'theran Village.",
  progress = "Da dove possono aver avuto origine questi poteri? Credo che siamo sulla strada giusta per trovare la risposta, $N.",
  reward = "Ora posso confrontare le penne... Vediamo...",
}
T[979] = {
  title = "Trova Ranshalla",
  desc = "Sì, sì, queste penne sembrano avere lo stesso incantesimo che avevo notato prima... Non so con certezza cosa potremmo trovare, ma ti esorto a continuare a cercare risposte, $N.$B$BUna mia collega è andata da poco a Winterspring per osservare i wildkin del posto, nel loro habitat. Perché non la raggiungi e vedi cos'ha scoperto?",
  obj = "Trova Ranshalla nella parte orientale di Winterspring.",
  reward = "Ciao! Ti manda Erelas? Ottimo, mi stavo giusto preparando a salire alle grotte, e un po' di compagnia non mi dispiace.",
}
T[980] = {
  title = "Le Nuove Sorgenti",
  desc = "Dunque, ho sentito parlare di altre sorgenti calde in un posto chiamato Winterspring, molto a nord di qui. La cosa strana è che nei dintorni non c'è nemmeno un vulcano. Interessante, lo so.$B$BBe', se vuoi saperne di più, dovresti andare a Winterspring e parlare con una mia amica. Si chiama Donova Snowden, e al momento sta vicino alle sorgenti calde di lì.$B$BGrazie ancora per avermi aiutato con il termometro! A presto!",
  obj = "Raggiungi Winterspring e parla con Donova Snowden.",
  reward = "Ciao, $N. Sì, quello che ti ha detto Krakle è vero...",
}
T[981] = {
  title = "La Torre di Althalaxx",
  desc = "Per tutto il lavoro che hai fatto, meriti una bella ricompensa. Torna da Delgren e digli che Athrikus Narassin giace senza vita per mano tua, e che il Cult of the Dark Strand è sconfitto e disperso.",
  obj = "Parla con Delgren the Purifier, a Maestra's Post.",
  reward = "Sapevo che saresti $Gstato:stata; all'altezza, $N.$B$BSento che grandi imprese ti attendono, e che raddrizzerai molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, $N, e anche questo dono.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Talk to Delgren the Purifier at Maestra's Post.",
}
T[992] = {
  title = "Il Rilevamento Idrico di Gadgetzan",
  desc = "Alla Gadgetzan Water Company c'è un posto libero da aiuto topografo temporaneo, se ti interessa!$B$BCon i nomadi che si prendono tutti i nostri pozzi, dobbiamo sfruttare altre fonti d'acqua libere! Di acqua nel deserto ce n'è, ma solo per chi è abbastanza furbo da fare prima i rilevamenti.$B$BPrendi questo aggeggio da rabdomante e preleva un campione d'acqua dalla pozza vicino all'Osservatorio di Sandsorrow. È proprio sotto gli occhi dei troll di quelle parti. Quando hai finito, riportami l'aggeggio pieno!",
  obj = "Usa l'Untapped Dowsing Widget vicino alla pozza d'acqua presso l'Osservatorio di Sandsorrow. Una volta raccolto il campione, riporta il Tapped Dowsing Widget a Senior Surveyor Fizzledowser a Gadgetzan.",
  progress = "$GBentornato:Bentornata;, Aiuto $GTopografo:Topografa; $N! Hai già portato a termine il tuo incarico?",
  reward = "Cosa sento? Ti ha teso un agguato una specie di schifezza strisciante dal brutto mojo? Oh, questo non promette niente di buono per la Gadgetzan Water Company, proprio no...$B$BMi sa che avrei dovuto dirti dei rapporti che ci arrivano su certe pazzesche creature-insetto che a quanto pare si stanno succhiando tutta l'acqua del deserto. All'inizio pensavo fosse solo una panzana. Di guai con i nomadi ne abbiamo già abbastanza così; pensavo fosse un'altra delle loro bravate. Be', almeno adesso lo sappiamo!",
}
T[994] = {
  title = "Fuga con la Forza",
  desc = "E va bene, $N, useremo la forza. Usciamo di qui appena sei $Gpronto:pronta;. Ci faremo largo combattendo fino alla strada — Grimclaw dovrebbe essere ancora lì. Arrivati là, ci separiamo.$B$BTerenthis vorrà sentire subito la tua versione dei fatti, quindi va' ad Auberdine dopo che saremo usciti.",
  obj = "Proteggi Volcor finché non arrivate alla strada, poi parla con Terenthis, ad Auberdine.",
  reward = "$N! Sono lieto di vedere che sei $Gtornato:tornata; e che ce l'hai fatta. Il tuo aiuto a Volcor mi fa credere che riusciremo a superare le sfide che ci attendono qui a Darkshore e altrove.",
  en_title = "Escape Through Force",
  en_obj = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",
}
T[996] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[998] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[1000] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una landa desolata e proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido Hamuul Runetotem, sull'Altura degli Anziani di Thunder Bluff, per maggiori informazioni!",
  obj = "Parla con Arch Druid Hamuul Runetotem, sull'Elder Rise di Thunder Bluff, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salve, $C.$B$BSono lieto di vedere che gente come te si interessa al benessere della natura; i racconti delle tue grandi imprese ti precedono, e qui sei $Gbenvenuto:benvenuta;. Vederti davanti a me mi dà fiducia che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade va al di là delle divisioni razziali e politiche. Tienilo a mente mentre lavori per il Circle, e ti andrà bene.",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1004] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una landa desolata e proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido Hamuul Runetotem, sull'Altura degli Anziani di Thunder Bluff, per maggiori informazioni!",
  obj = "Parla con Arch Druid Hamuul Runetotem, sull'Elder Rise di Thunder Bluff, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salve, $C.$B$BSono lieto di vedere che gente come te si interessa al benessere della natura; i racconti delle tue grandi imprese ti precedono, e qui sei $Gbenvenuto:benvenuta;. Vederti davanti a me mi rende fiducioso: il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade va al di là delle divisioni razziali e politiche. Tienilo a mente mentre lavori per il Circle, e ti andrà bene.",
}
T[1009] = {
  title = "Ruuzel",
  desc = "Temo che i segreti dell'antica statuetta resteranno per sempre nascosti, a meno che tu non trovi la chiave della sua antica serratura.$B$BQuella chiave è un anello, l'Anello di Zoram. Apparteneva a chi governava questa città, prima che le onde della Grande Separazione la sommergessero.$B$BPer anni l'anello è rimasto perduto, ma i naga l'hanno ritrovato di recente.$B$BLa loro condottiera, Ruuzel, vive su un'isola all'estremità settentrionale di Zoram. Ti prego, $N, recupera l'anello per me!",
  obj = "Porta il Ring of Zoram a Talen, vicino alla Spiaggia di Zoram.",
  progress = "Si dice che l'Anello di Zoram sia la chiave di qualsiasi serratura della città. Ce l'hai, $N?",
  reward = "Hai trovato l'anello! Grazie, $N. Prendi questo come pagamento, e sappi che quel che hai fatto oggi resterà per sempre nella mia memoria.",
  en_title = "Ruuzel",
  en_obj = "Bring the Ring of Zoram to Talen near the Zoram Strand.",
}
T[1011] = {
  title = "Le Malattie dei Reietti",
  desc = "I Reietti, il braccio non morto dell'Orda, si sono insinuati ad Ashenvale e si aggirano tra le nostre rovine e i nostri tumuli. Crediamo che il loro scopo sia diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne la conferma!$B$BI Reietti hanno un accampamento a sud di qui, vicino all'Eremo di Dor'Danil, dove preparano veleni e malattie e li mettono in bottiglie. Fatti strada combattendo fin dentro quell'accampamento e ruba una bottiglia di malattia. Torna con una di quelle bottiglie. La analizzerò e ne scoprirò lo scopo.",
  obj = "Porta una Bottle of Disease a Kayneth Stillwind, a Forest Song.",
  progress = "Hai trovato l'accampamento, $N? Hai una bottiglia di malattia?",
  reward = "Molto bene, $N. Ora... l'analisi del contenuto di questa bottiglia rivelerà gli scopi dei Reietti!",
  en_title = "Forsaken Diseases",
  en_obj = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.",
}
T[1012] = {
  title = "Druidi Impazziti",
  desc = "Mentre lottavo con i veleni dei Reietti, ho avuto una visione. Ho visto i druidi dell'Eremo di Dor'danil, avvelenati... assassinati dai non morti! Ora sono spettri erranti, strappati ai loro corpi e impazziti.$B$BPerché un giorno gli spiriti dei druidi trovino pace, devi entrare nell'Eremo di Dor'danil e distruggere quelli che un tempo erano i suoi grandi capi: Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak.$B$BFallo, poi torna da me.",
  obj = "Uccidi i druidi: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; poi torna da Kayneth Stillwind, a Forest Song.",
  progress = "L'angoscia dei druidi di Dor'danil perseguita ancora i miei sogni, $N. Devi distruggere i loro capi!",
  reward = "Ho sentito l'angoscia dell'Eremo di Dor'danil attenuarsi, e ho capito che avevi portato a termine il tuo compito.$B$BÈ stato un lavoro ingrato, $N, perché gli spiriti che hai distrutto erano soltanto vittime del male dei Reietti. Ma ora che sono stati distrutti, speriamo che gli altri spiriti impazziti trovino pace.",
  en_title = "Insane Druids",
  en_obj = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",
}
T[1013] = {
  title = "Il Libro di Ur",
  desc = "$N, Shadowfang Keep custodisce un libro, il Libro di Ur, che nella mia collezione sarebbe un pezzo di gran pregio. Ur era un grande mago di Dalaran prima dell'arrivo del Flagello, e i suoi studi su altri mondi sono di grande valore per... certi ambienti tra i Reietti.$B$BEntra a Shadowfang Keep e trova il libro. Portamelo, e farò sapere alla nostra Signora Oscura del servizio che hai reso...",
  obj = "Porta il Book of Ur a Keeper Bel'dugur, all'Apothecarium, nell'Undercity.",
  progress = "Hai trovato il libro, $N?",
  reward = "Molto bene. Questo libro sarà un'ottima aggiunta alle mie raccolte delle opere di Ur. Il suo sapere era grande, ma la sua coscienza gli impedì di arrivare al vero potere. E così, quando venne il Flagello e la sua forza fu messa alla prova, non resse.$B$BNoi Reietti non possiamo permetterci una debolezza simile, se vogliamo sopravvivere...$B$B...Se vogliamo conquistare.",
  en_title = "The Book of Ur",
  en_obj = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",
}
T[1014] = {
  title = "Arugal Deve Morire",
  desc = "Arugal si trova ancora a Shadowfang Keep. Non possiamo rivendicare Silverpine come roccaforte strategica per la Signora Oscura finché Arugal non sarà ucciso.$B$BMi occuperò io di sradicare la sua magia, $N. Ma lascio a te il compito di dare ad Arugal la morte che tanto si merita.$B$BVa' a Shadowfang Keep e metti fine una volta per tutte agli incantesimi immondi di Arugal. Portami la testa di quel vile mago!",
  obj = "Uccidi Arugal e porta la sua testa a Dalar Dawnweaver, al Sepulcher.",
  progress = "Con la morte di Arugal rafforzeremo la presa della Signora Oscura su Lordaeron.",
  reward = "La Silverpine Forest è finalmente libera dalla morsa di quel miserabile di Arugal. Hai reso un grande servizio alla Signora Oscura, $N. La tua tenacia sarà ricompensata.",
  en_title = "Arugal Must Die",
  en_obj = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",
}
T[1015] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!",
  obj = "Parla con Arch Druid Fandral Staghelm, al Cenarion Enclave di Darnassus, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io abbia voglia di essere scocciato da gente come te, $C? Aspetta — lascia che interrompa i compiti importanti che svolgo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il bene di Darnassus — anzi, di tutta Teldrassil — deve venire dopo un gingillo per la tua collezione.$B$BQuegli sciocchi del Moonglade mi fanno perdere tempo con le loro richieste di aiuto, e ora devo sopportare anche questo?",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1016] = {
  title = "Bracciali Elementali",
  desc = "Prendi questa pergamena divinatoria — può rivelare chi ha creato questi elementali. Ma ti servirà qualcosa che appartenga a loro, da usare come reagente per concentrare la magia della pergamena — i loro bracciali dovrebbero andare benissimo.$B$BQualche bracciale intatto preso dalle creature dovrebbe bastare. Gli altri bracciali non ci serviranno, ma forse per un mercante varranno qualcosa, se vuoi venderli. Quando hai i bracciali intatti, prova a usare la pergamena. Torna da me con il risultato e vedremo come procedere.",
  obj = "Raccogli 5 Intact Elemental Bracer e usa su di essi la Divining Scroll. Poi porta la Divined Scroll a Sentinel Velene Starstrike al Rifugio di Silverwind.",
  progress = "Visto che per uccidere gli elementali devi distruggere i loro bracciali, sarà probabilmente difficile trovare proprio quelli che contengono le informazioni di cui la pergamena divinatoria ha bisogno. Puoi scambiare bracciali con altri per ottenere quelli che ti servono, o forse hai già il foglio con il responso?",
  reward = "Ben fatto, $N, questo dovrebbe darci le informazioni che ci servono per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie i nostri specchi d'acqua di elementali corrotti? La corruzione di Ashenvale e di altre terre mi rivolta lo stomaco già di suo — sapere che un mago fa di tutto per devastare ancora di più queste terre mi disgusta oltre ogni dire. Gliela faremo pagare.",
  en_title = "Elemental Bracers",
  en_obj = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.",
}
T[1017] = {
  title = "Il Mago Evocatore",
  desc = "C'è un solo mago non morto nelle Barrens capace di profanare tutti questi elementali dell'acqua. Ed è anche l'unico abbastanza folle da provarci. Probabilmente Sarilus Foulborne se ne sta in cima al Picco di Dreadmist, a ridere di me.$B$B$N, devi entrare in territorio nemico e distruggere quel farabutto. Ne ho abbastanza della sua idiozia, e dobbiamo mostrargli cosa succede a chi infastidisce le Sentinelle.$B$BDistruggilo e portami la sua testa. Fa' attenzione, però: l'Orda potrebbe essere in cerca di te.",
  obj = "Uccidi Sarilus Foulborne e porta la sua testa a Sentinel Velene Starstrike, al Rifugio di Silverwind.",
  progress = "È fatta? Sarilus Foulborne è morto?",
  reward = "Ora posso vedere quel sorriso ripugnante sparire per sempre dalla sua faccia. Hai fatto davvero un ottimo lavoro, $N. Prendi questa, la Luce di Elune, e bevine quando tutto sembra perduto e la morte è vicina. Potrebbe salvarti, se la Dea vorrà.",
  en_title = "Mage Summoner",
  en_obj = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.",
}
T[1018] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una landa desolata e proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido Hamuul Runetotem, sull'Altura degli Anziani di Thunder Bluff, per maggiori informazioni!",
  obj = "Parla con Arch Druid Hamuul Runetotem, sull'Elder Rise di Thunder Bluff, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salve, $C.$B$BSono lieto di vedere che gente come te si interessa al benessere della natura; i racconti delle tue grandi imprese ti precedono, e qui sei $Gbenvenuto:benvenuta;. Vederti davanti a me mi dà fiducia che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade va al di là delle divisioni razziali e politiche. Tienilo a mente mentre lavori per il Circle, e ti andrà bene.",
}
T[1019] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!",
  obj = "Parla con Arch Druid Fandral Staghelm, al Cenarion Enclave di Darnassus, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io abbia voglia di essere scocciato da gente come te, $C? Aspetta — lascia che interrompa i compiti importanti che svolgo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il bene di Darnassus — anzi, di tutta Teldrassil — deve venire dopo un gingillo per la tua collezione.$B$BQuegli sciocchi del Moonglade mi fanno perdere tempo con le loro richieste di aiuto, e ora devo sopportare anche questo?",
}
T[1021] = {
  title = "Satiro Immondo! Driadi in Pericolo!",
  desc = "Ascolta, non so chi sei, ma mi serve il tuo aiuto. Le mie sorelle sono andate a riprendere il Ramo di Cenarius ai satiri. Hanno detto che sarebbero tornate presto, ma sono passati due giorni interi!$B$B$N, devi trovarle! Cercavano le rovine di un tempio degli elfi della notte a Xavian, a nord-est. Non so cosa pensare. Cerca Anilia, era lei a guidarle nella ricerca.",
  obj = "Trova Anilia, a Xavian.",
  reward = "A giudicare dalla ferita aperta nel fianco, Anilia è in punto di morte.",
  en_title = "Vile Satyr! Dryads in Danger!",
  en_obj = "Find Anilia in Xavian.",
}
T[1022] = {
  title = "La Valle degli Ululati",
  desc = "Anche se abbiamo dedicato molte risorse e molti sforzi a scacciare dal Felwood, a nord, i demoni rimasti, i successi sono stati pochi. Siamo riusciti a tenere gran parte della presenza demoniaca lontana da Ashenvale.$B$BA nord, vicino al confine del Felwood, il santuario in rovina di Mel'Thandris è stato occupato da misteriosi uomini-lupo. I loro richiami agghiaccianti hanno fatto sì che la zona venisse chiamata Valle degli Ululati. Il Tomo di Mel'Thandris custodito nel santuario potrebbe far luce sul motivo per cui questi uomini-lupo sono arrivati.",
  obj = "Va' a Howling Vale e studia il Tome of Mel'Thandris, poi torna da Sentinel Melyria Frostshadow, al Santuario di Aessina.",
  progress = "Il tomo del santuario è un oggetto misterioso. Non è un libro nel senso comune. I fogli del tomo furono benedetti da Mel'Thandris in persona, e le sue pagine registrano gli eventi importanti.$B$BPer me è difficile da spiegare. Se vai al santuario, capirai.",
  reward = "Il Tomo di Mel'Thandris funziona in modi strani. Gli eventi che registra, gli eventi che mostra... Nessuno capisce davvero perché faccia quello che fa.$B$BResta però chiaro che ciò che ha ricevuto la Sacerdotessa Starsong — questa Falce di Elune — merita ulteriori indagini.",
  en_title = "The Howling Vale",
  en_obj = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.",
}
T[1023] = {
  title = "La Purificazione di Raene",
  desc = "Mentre frughi tra le cose di Teronis, trovi un diario ancora in buone condizioni.$B$BPrendi il diario e lasci il corpo di Teronis com'è.$B$BNon resta che trovare la gemma che Teronis stava cercando. Raene ha detto che si trova in zona. Forse ce l'hanno i murloc...",
  obj = "Trova la Glowing Gem e torna da Raene Wolfrunner ad Astranaar con Teronis' Journal.",
  progress = "Ah, $Gbentornato:bentornata;, $N.",
  reward = "È terribile, $N. Teronis è morto?!$B$BVerrà il tempo del lutto, ma per ora dobbiamo concentrare i nostri sforzi. Manderò alcune Sentinelle a recuperare il corpo di Teronis appena possibile.$B$BHai il diario di Teronis e la gemma che stava cercando. Pensi di essere in grado di portare a termine il suo compito? Dormirei molto più tranquilla sapendo che la sua morte non è stata vana.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.",
}
T[1024] = {
  title = "La Purificazione di Raene",
  desc = "La ricerca dovrai farla da $Gsolo:sola;, ma da quel che ha annotato Teronis sembra che il prossimo passo sia trovare gli altri pezzi della verga creata da Dartol. Io comincerei andando al pozzo lunare a est del Lago Iris. Quando sei $Gpronto:pronta;, segui la strada e gira a nord quando arrivi a un piccolo spiazzo dove sedersi, sulla sinistra.$B$BLì c'è una driade di nome Shael'dryn, che saprà guidarti meglio di me. Cercala.$B$BTieni la gemma con te — a Shael'dryn servirà, se deve aiutarti a ricreare la verga.",
  obj = "Trova Shael'dryn al pozzo lunare a nord-est.",
  progress = "Salve. Come stai?",
  reward = "Oh, ti manda Raene? Allora dev'essere davvero grave. In cosa posso aiutarti?",
  en_title = "Raene's Cleansing",
  en_obj = "Find Shael'dryn at the moonwell to the northeast.",
}
T[1025] = {
  title = "Una Difesa Aggressiva",
  desc = "Prima che tu vada al pozzo lunare, ho un altro incarico che aiuterà la gente di Ashenvale, se vuoi metterti alla prova.$B$BLungo la strada che va a est, prima del Fiume Falfarren, i mezzorsi attaccano i viaggiatori. Le loro menti torturate si nutrono di paura e la loro fame si sazia del sangue degli innocenti.$B$BAiuta le Sentinelle a proteggere queste terre mostrando a quei mostri la stessa pietà che hanno mostrato alla nostra gente.$B$BCredo che i loro accampamenti siano a sud della strada... sta' $Gattento:attenta;.",
  obj = "Uccidi 1 Foulweald Den Watcher, 2 Foulweald Ursa, 10 Foulweald Totemic e 12 Foulweald Warrior, poi torna da Raene Wolfrunner ad Astranaar.",
  progress = "I mezzorsi non sono sempre stati nostri nemici, $N. Ma i tempi cambiano, e qui, in questi boschi oscuri, non è più tempo di pace.",
  reward = "Hai fatto un buon lavoro, $N. Grazie.",
  en_title = "An Aggressive Defense",
  en_obj = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.",
}
T[1026] = {
  title = "La Purificazione di Raene",
  desc = "Vorrei che le tue notizie fossero migliori.$B$BRaene ha ragione: conosco la creazione di Dartol e i treant della zona — o almeno li conoscevo. Ora sono stati corrotti, la loro natura è stata stravolta.$B$BSe il tuo scopo è trovare il prossimo pezzo della verga, dovrai trovare la chiave per aprire la cassa in cui si trova.$B$BLa chiave di legno è addosso a uno dei treant a nord-est di qui, vicino a Felwood. Quando l'avrai, cerca una piccola radura a ovest della strada, vicino al confine di Felwood... la cassa dovrebbe essere nascosta da quelle parti.",
  obj = "Trova la Wooden Key e un pezzo della Verga di Dartol prima di tornare da Shael'dryn, al pozzo lunare.",
  progress = "Mi addolora tanto che i treant siano stati corrotti. Vorrei poter fare di più per aiutarli.",
  reward = "Sono contenta di rivederti, $N.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.",
}
T[1027] = {
  title = "La Purificazione di Raene",
  desc = "L'ultimo pezzo della verga è stato affidato ai druidi di Dor'danil perché lo custodissero. Non ho idea di dove l'abbiano nascosto. Mi dispiace, non posso aiutarti oltre.$B$BPosso solo dirti di seguire la strada che porta verso le Barrens. I druidi si erano rifugiati a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi di recente... è una cosa a cui non mi piace pensare troppo.$B$BQuando trovi l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.",
  obj = "Trova l'ultimo pezzo della Verga di Dartol e torna da Shael'dryn, al pozzo lunare.",
  progress = "Hai trovato l'ultimo pezzo della verga, $N?",
  reward = "Hai trovato l'ultimo pezzo? Che bello per te... e per Raene.$B$BA questo punto dovremo pensare a ripararla, no?",
  en_title = "Raene's Cleansing",
  en_obj = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.",
}
T[1028] = {
  title = "La Purificazione di Raene",
  desc = "Ecco la verga completa, $N. Ricostruirla è stato semplice... la parte difficile sarà trovare il santuario che ha il potere di ricaricarla.$B$BCon un po' di concentrazione e di impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già fatto tanto.$B$BVa' a sud-est di qui — i sentieri sono pochissimi, quindi fa' attenzione — e tieni lo sguardo rivolto a nord. Il santuario è nascosto tra le montagne che circondano questa radura.$B$BUna volta lì, posa la verga nel santuario... il resto è magia. Eheh.",
  obj = "Trova il santuario nascosto e incanta di nuovo la Verga di Dartol.",
  progress = "Percepisci una forza sottile ma potente nel santuario e negli alberi intorno.$B$BCominci a posare la verga nel santuario e intorno a te si leva un lieve ronzio mentre il santuario inizia a brillare...",
  reward = "Quando il bagliore si spegne, vedi la verga di nuovo incantata nella conca del santuario.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the hidden shrine and re-enchant Dartol's Rod.",
}
T[1029] = {
  title = "La Purificazione di Raene",
  desc = "Ti consiglio di cercare Raene e di farle sapere che la verga è pronta. Sono sicura che saprà dirti qual è il prossimo passo.$B$BBuona fortuna, $N.",
  obj = "Torna da Raene Wolfrunner, ad Astranaar.",
  reward = "Hai ricreato la verga che Teronis era partito a cercare? È una notizia meravigliosa.$B$BTeronis sarebbe fiero di vedere che la sua impresa continua anche dopo la sua tragica fine.",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Raene Wolfrunner in Astranaar.",
}
T[1030] = {
  title = "La Purificazione di Raene",
  desc = "Ahimè, non sono del tutto sicura di cosa avesse in mente di fare dopo.$B$BSe quel che diceva sul potere della verga è vero, allora ti permetterà di assumere tutt'altra forma. Quale forma, non lo so.$B$BForse voleva usarne i poteri per avvicinarsi ai mezzorsi corrotti, ma anche le creature non corrotte lo avrebbero fatto a pezzi, se non fosse stato prudente. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un mezzorso al riparo dagli effetti del Vilmuschio.$B$BIo comincerei la ricerca a sud-est del Lago Mystral.",
  obj = "Trova un mezzorso non corrotto e, usando il potere di Dartol's Rod of Transformation, parlagli.",
  reward = "Sì, sì... sei $Guno:una; della mia specie, ma ancora $Gintegro:integra;. Ancora $Gpuro:pura;.$B$BNon so come tu sia $Gsfuggito:sfuggita; alle atrocità che gli elfi della notte hanno inflitto alla nostra gente, ma sono lieto di sapere che non sono più solo.$B$BLa corruzione scorre ormai nelle vene dei nostri simili, giovane, una corruzione che gli orgogliosi elfi della notte hanno fatto ricadere su di noi. Sono loro ad aver fatto questo alla nostra gente... Sono loro che incolpo per essere stato cacciato dalla mia tribù.$B$BDi notte vedo ancora i fuochi da campo ardere nel buio.",
  en_title = "Raene's Cleansing",
  en_obj = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.",
}
T[1031] = {
  title = "Il Ramo di Cenarius",
  desc = "Anilia ti posa le mani sulle spalle e ti attira a sé. Ansimando, indica l'arco a nord, prima che i suoi occhi si chiudano e l'ultimo respiro affannoso le lasci il corpo. \"L'ha preso lui... Geltharis...\" In cuor tuo sai che l'ultimo desiderio di Anilia è rivedere il Ramo di Cenarius nelle mani delle driadi.",
  obj = "Uccidi Geltharis e riporta il Branch of Cenarius a Illiyana, al Santuario di Aessina.",
  progress = "Le hai trovate? Cos'ha detto Anilia? Dov'è?",
  reward = "Anilia è morta? No... non può essere! Solo ieri correvamo e giocavamo insieme nei boschi.$B$BImmagino che quei giorni siano finiti...",
  en_title = "The Branch of Cenarius",
  en_obj = "Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.",
}
T[1032] = {
  title = "Strage di Satiri!",
  desc = "Non riesco a credere che Anilia non ci sia più... Giocavamo sempre insieme nelle foreste. Mi sento quasi... triste.$B$BSo una cosa che potrebbe farmi stare meglio. Ti prego, uccidi i satiri che mi hanno portato via Anilia! Portami le loro corna come prova di quel che hai fatto e avrai per sempre la mia gratitudine.",
  obj = "Porta 16 Satyr Horns a Illiyana, al Santuario di Aessina.",
  progress = "Ti prego, aiutami a vendicare la morte di Anilia.",
  reward = "Grazie, gentile $R. Lo spirito di mia sorella è confortato da quel che hai fatto.",
  en_title = "Satyr Slaying!",
  en_obj = "Bring 16 Satyr Horns to Illiyana in Forest Song.",
}
T[1033] = {
  title = "La Lacrima di Elune",
  desc = "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato il male che scorre in mia figlia. Dobbiamo trovare una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da provare, nel caso il primo fallisse.$B$BLa Lacrima di Elune è un tipo di pietra che si trova in un solo posto: l'isola del Lago Iris, a est di Astranaar. Orendil ha detto che la pietra lava via la corruzione... ti prego, $N, portami la Lacrima di Elune e prega che ponga fine alla malattia di mia figlia!",
  obj = "Porta Elune's Tear a Pelturas ad Astranaar.",
  progress = "$N, hai trovato il Lago Iris? Hai la Lacrima?",
  reward = "Oh, l'hai trovata! Metterò la lacrima in uno stufato e pregherò che la guarisca.$B$BGrazie! Grazie, $N!",
  en_title = "Elune's Tear",
  en_obj = "Bring Elune's Tear to Pelturas in Astranaar.",
}
T[1034] = {
  title = "Le Rovine di Polvere Stellare",
  desc = "La Lacrima di Elune ha lavato via una parte del male di mia figlia. I suoi incubi si sono attenuati e ringrazio la dea per la sua benedizione. Ma... la febbre infuria ancora dentro di lei.$B$BOrendil mi ha parlato di una polvere gelida che si trova tra le Rovine di Polvere Stellare. Forse placherà la febbre di Relara. Raccogline un po', poi torna da me, ti prego.$B$BLe Rovine di Polvere Stellare si trovano a sud, $N. Che Elune affretti il tuo cammino.",
  obj = "Porta 5 Handful of Stardust a Pelturas ad Astranaar.",
  progress = "Hai già la Polvere Stellare, $N?",
  reward = "Hai raccolto la polvere! Ne farò un impacco — dovrebbe far scendere la febbre di Relara.$B$BGrazie ancora, $N. Senza il tuo aiuto mia figlia morirebbe di sicuro.",
  en_title = "The Ruins of Stardust",
  en_obj = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.",
}
T[1035] = {
  title = "Il Lago Cielinfranto",
  desc = "La febbre di Relara è passata, ma è ancora molto debole. Non credo che il tempo da solo le restituirà le forze che ha perso. Credo che serva il potere di una pietra di luna.$B$BUn tempo raccoglievamo pietre di luna al Lago Cielinfranto, a sud-est... finché non sono arrivati gli Shadethicket.$B$BIl loro capo, un Oracolo Shadethicket, ha raccolto tutte le pietre di luna cadute e se le tiene strette. Ora devi recuperarne una dall'Oracolo.$B$BE per farlo, temo che dovrai ucciderlo.",
  obj = "Recupera una Fallen Moonstone dallo Shadethicket Oracle, poi portala a Pelturas ad Astranaar.",
  progress = "Hai affrontato l'Oracolo Shadethicket, $N? Se sì, dammi la pietra di luna caduta, ti prego. A Relara restano le forze per pochi respiri!",
  reward = "Oh, $N, hai salvato mia figlia! So che il potere della pietra di luna le ridarà le forze!$B$BNon potrò mai ripagarti del tutto per l'aiuto che mi hai dato, ma... ti prego, prendi questo. A parte Relara, è la cosa più cara che ho.",
  en_title = "Fallen Sky Lake",
  en_obj = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.",
}
T[1036] = {
  title = "Alt Là, Canaglia",
  desc = "$N... sì, ho sentito parlare di te. Ho sentito che non sei $Gamico:amica; di Booty Bay — proprio come noi Bloodsail Buccaneers. Il Comandante della Flotta Firallon cerca $Guomini:donne; forti e $Gvigorosi:vigorose; proprio come te per una missione speciale.$B$BSe ti interessa, va' alla Crimson Veil e parlagli sottocoperta. È ancorata al largo della Costa Selvaggia, a est di qui, accanto alla Riptide e alla Damsel's Luck.",
  obj = "Parla con Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.",
  reward = "Alt là, canaglia. Mi dicono che sei il tipo da qualche losco affare. Be', se non sei $Gamico:amica; di Booty Bay, allora potresti avere un posto speciale tra i Bloodsail Buccaneers.$B$BArrrrr...",
  en_title = "Avast Ye, Scallywag",
  en_obj = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.",
}
T[1037] = {
  title = "Velinde Starsong",
  desc = "Velinde Starsong mi ha preceduta qui nell'Ashenvale Forest. All'inizio sembrava che avesse la situazione del Felwood sotto controllo, ma a poco a poco la sua azione ha cominciato a vacillare. Un giorno è semplicemente sparita.$B$BMi hanno mandata qui a continuare il suo lavoro. Temo però di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle Sentinelle, conosce altri dettagli sulla sua scomparsa che a me non sono stati riferiti.$B$BDi sicuro capirà l'importanza di simili informazioni.",
  obj = "Parla con Thyn'tel Bladeweaver, a Warrior's Terrace, a Darnassus.",
  reward = "Velinde Starsong? Che la sacerdotessa sia sparita tempo fa lo sanno quasi di sicuro tutti. Quanto ad altri dettagli sulle circostanze della sua partenza... mi servirebbe una buona ragione per rivelare simili informazioni.",
  en_title = "Velinde Starsong",
  en_obj = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.",
}
T[1038] = {
  title = "Gli Effetti Personali di Velinde",
  desc = "Il Tomo di Mel'Thandris ti ha mostrato questo? Immagino che non ci sia niente di male nel lasciarti esaminare le sue cose. Questa chiave ti permetterà di aprire la cassa in cui abbiamo riposto i suoi averi, nella camerata delle Sentinelle. Teneva un diario dei suoi incarichi: se c'è qualcosa da scoprire, verrà da lì.$B$BDevo dirti che le Sentinelle credono che avesse le sue ragioni per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.",
  obj = "Cerca il diario nella cassa di Velinde, poi riportalo insieme alla chiave a Thyn'tel Bladeweaver, a Darnassus.",
  progress = "Cos'hai scoperto?",
  reward = "A quanto pare la scomparsa di Velinde è più inquietante di quanto sembrasse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse ci sarebbe utile metterci in contatto con lei.$B$B$N, visto che hai dimostrato un interesse personale in questa faccenda, vorrei chiedere il tuo aiuto.",
  en_title = "Velinde's Effects",
  en_obj = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.",
}
T[1039] = {
  title = "Il Porto delle Barrens",
  desc = "Ratchet è l'unico porto delle Barrens. Con ogni probabilità Velinde ha trovato a Ratchet una nave mercantile che la portasse alla Baia dei Blackwater, ad Azeroth. Abbiamo pochi rapporti con i goblin che gestiscono il porto, ma il capo del molo dovrebbe avere informazioni sull'andirivieni dei passeggeri.$B$BSegui la strada a sud-est attraverso Ashenvale e ti ritroverai nelle Barrens. Guarda dove metti i piedi, $N: guerrieri dell'Orda pattugliano quelle terre. Al porto, però, sarai al sicuro.",
  obj = "Parla con Wharfmaster Dizzywig, a Ratchet.",
  reward = "$R, eh? Devo ammettere che da queste parti non ne capitano molti come te. Cerchi qualcuno, eh? Dammi solo un momento, sono sicuro di averlo scritto in uno dei miei registri.$B$BDi gente però ne passa parecchia, quindi dammi un attimo.",
  en_title = "The Barrens Port",
  en_obj = "Speak with Wharfmaster Dizzywig in Ratchet.",
}
T[1040] = {
  title = "Passaggio per Booty Bay",
  desc = "Ah, sì, finalmente l'ho trovato. Dovevi dirmi che era passata di qui così tanto tempo fa. Vediamo.$B$BVelinde. Ha prenotato un passaggio per Booty Bay sulla Black Osprey. Qui non c'è scritto niente in contrario, quindi direi che sia arrivata in porto senza problemi.$B$BOltre a questo non posso esserti di grande aiuto, ma mi ha chiesto dei viaggi via terra dall'altra parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che sta a Booty Bay. Può darsi che questa Velinde abbia viaggiato con lui.$B$BOra circola. Non ho tutto il giorno per te.",
  obj = "Prendi una nave per Booty Bay e parla con Caravaneer Ruzzgot.",
  reward = "Sì? Be', non mi sembri il tipo con merce da spedire, quindi o cerchi lavoro con la mia carovana — e di lavoro adesso non ce n'è — o probabilmente stai parlando con il goblin sbagliato.$B$BAllora, quale delle due?",
  en_title = "Passage to Booty Bay",
  en_obj = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.",
}
T[1041] = {
  title = "La Strada della Carovana",
  desc = "A quanto pare su di te mi sbagliavo, e non è una cosa che capiti tutti i giorni.$B$BGuarda caso mi ricordo di questa Velinde che cerchi. Non capita tutti i giorni che una sacerdotessa elfa della notte voglia viaggiare con una carovana vecchia e sporca — ma perfetta per le tue spedizioni! — come la mia.$B$BCi siamo separati lungo la strada verso nord, lei era diretta a Darkshire. Il cancelliere di là tiene registri di ogni genere. Potrebbe sapere qualcosa di utile.$B$BFa' attenzione nella giungla: è un posto letale anche nei periodi migliori.",
  obj = "Parla con Clerk Daltry, a Darkshire.",
  reward = "Con tutte le stranezze degli ultimi anni, cerco di tenere registri il più possibile accurati sui forestieri. Non si sa mai quando possano tornare utili... anche se di solito, quando succede, non è per faccende piacevoli. Non che voglia insinuare nulla su questa Velinde che cerchi.",
  en_title = "The Caravan Road",
  en_obj = "Speak with Clerk Daltry in Darkshire.",
}
T[1042] = {
  title = "La Famiglia Carevin",
  desc = "No, non ho alcuna traccia di una Velinde Starsong che abbia soggiornato a Darkshire... anche se, se posso permettermi, faccio fatica a immaginare una sacerdotessa elfa della notte che prende una stanza alla locanda, mi spiego?$B$BDi questi uomini-lupo che hai nominato, però, ho sentito parlare. Proprio l'altro giorno Calor è arrivato in città con una filza delle loro teste. Lavora con la famiglia Carevin. Cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è lui il capofamiglia.",
  obj = "Parla con Jonathan Carevin, a Darkshire.",
  reward = "Sono tempi oscuri. Da ogni ramo che oscilla si sussurrano brutte notizie, e sotto ogni pietra si annida il male.$B$BE in tempi simili $Guno sconosciuto:una sconosciuta; entra in casa mia e chiede dei worgen... Non chiederò scusa per i miei sospetti, voglio solo risposte.$B$BE risposte avrò.",
  en_title = "The Carevin Family",
  en_obj = "Speak with Jonathan Carevin in Darkshire.",
}
T[1043] = {
  title = "La Falce di Elune",
  desc = "La tua storia sembra vera... Non capisco del tutto le tue ragioni, ma se quel che hai da fare qui a Duskwood comporta liberare la foresta dai worgen, pochi o tanti che siano, allora posso rinunciare a capire, purché ci siano risultati.$B$BA sud c'è una miniera invasa dai worgen... Sono comparsi dal nulla, ma da quel che sappiamo è lì che sono stati visti per la prima volta.$B$BFa' quel che devi, ma se trovi qualcosa di importante, ti chiedo di condividerlo con me. Accetteremo qualsiasi aiuto nella nostra guerra contro il male.",
  obj = "Cerca tracce della Scythe of Elune, poi torna da Jonathan Carevin, a Darkshire.",
  progress = "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e l'ingegno ancora più vicino, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.",
  reward = "È una storia interessante quella che racconti, $N. Anche se l'influenza della famiglia Carevin non è tale da permetterci di trovare la radice di questi guai e di porvi fine una volta per tutte, faremo il possibile per contenere il numero dei worgen a Duskwood.$B$BHo già dato ordine a Calor di farne la sua priorità assoluta.",
  en_title = "The Scythe of Elune",
  en_obj = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.",
}
T[1044] = {
  title = "Interrogativi Risolti",
  desc = "Terremo a freno il problema dei worgen, non preoccuparti. Questo male che la tua amica ha portato nei nostri boschi verrà contenuto, e non le porto rancore per quel che ha fatto. In questi tempi accadono cose strane, $N, e l'oscurità non conosce tregua.$B$BNon ti tratterrò oltre. Immagino che ci siano altri che dovrebbero sapere quel che hai trovato nelle miniere di Duskwood.",
  obj = "Torna da Thyn'tel Bladeweaver, a Darnassus.",
  reward = "Dunque questo è il destino di Velinde? La somma sacerdotessa sarà dispiaciuta nel saperlo: erano buone amiche prima della sua scomparsa. Eppure la Falce di Elune le è stata di certo concessa in dono dalla nostra dea, e mi inquieta che non sia più nelle mani delle serve di Elune.$B$BMa questa è un'altra faccenda, per un'altra volta. Ti devo un ringraziamento non da poco per quel che hai fatto.",
  en_title = "Answered Questions",
  en_obj = "Return to Thyn'tel Bladeweaver in Darnassus.",
}
T[1045] = {
  title = "La Purificazione di Raene",
  desc = "Gli elfi della notte sono antichi come il tempo, ma la loro arroganza distrugge il loro stesso mondo. E ora distrugge anche le nostre vite. Ma ormai non si può più controllare...$B$BIncolpo gli elfi di molte cose, ma restiamo comunque responsabili delle nostre azioni. Anche senza la corruzione, siamo capaci di mali terribili.$B$BRan Bloodtooth è uno di questi mali. Assetato di potere, pieno di brame... la corruzione non ha fatto che renderlo più forte. Il mio odio per gli elfi brucia, ma non auguro il male ai loro figli, quindi tocca a noi tenere a freno i nostri.",
  obj = "Uccidi Ran Bloodtooth e 4 Bloodtooth Guard, poi torna da Krolg, vicino al Lago Mystral.",
  progress = "Hai già ucciso Ran, $Gamico mio:amica mia;?$B$BNemmeno gli elfi della notte meritano davvero la sua ira. Il suo odio brucia ancora più forte del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.",
  reward = "Hai fatto un buon lavoro, $Gamico mio:amica mia;.$B$BLa foresta è ancora corrotta, ma almeno sappiamo di aver fatto la nostra piccola parte per riportarla all'antica gloria. Se vorrai tornare a trovarmi, mi farebbe piacere la compagnia di uno dei miei.$B$BStammi bene. Forse le nostre tribù si incontreranno di nuovo in tempi meno violenti.",
  en_title = "Raene's Cleansing",
  en_obj = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.",
}
T[1046] = {
  title = "La Purificazione di Raene",
  desc = "Torna dalla tua tribù e racconta loro la vittoria che hai ottenuto qui.$B$BMostra loro il tuo trofeo e crogiolati nella gloria...",
  obj = "Porta Ran Bloodtooth's Skull e Dartol's Rod of Transformation a Raene Wolfrunner, ad Astranaar.",
  progress = "Le Sentinelle fanno quel che possono qui ad Ashenvale, ma è grazie a gente come te se abbiamo guadagnato terreno.",
  reward = "Dunque questo è il teschio della più feroce minaccia dei mezzorsi di Ashenvale?$B$BSono più che soddisfatta delle tue capacità, $N. Le Sentinelle non potranno mai ringraziarti abbastanza. Spero che in futuro potremo contare ancora su di te per aiutare la nostra gente.$B$BMetterò questo teschio e la Verga di Dartol in un luogo d'onore, perché tutti li vedano.$B$BTeronis ne sarebbe fiero. Grazie ancora.",
  en_title = "Raene's Cleansing",
  en_obj = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.",
}
T[1047] = {
  title = "La Nuova Frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una landa desolata e proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'Arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!",
  obj = "Parla con Arch Druid Fandral Staghelm, al Cenarion Enclave di Darnassus, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io abbia voglia di essere scocciato da gente come te, $C? Aspetta — lascia che interrompa i compiti importanti che svolgo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il bene di Darnassus — anzi, di tutta Teldrassil — deve venire dopo un gingillo per la tua collezione.$B$BQuegli sciocchi di Moonglade mi fanno perdere tempo con le loro richieste di aiuto, e ora devo sopportare anche questo?",
}
T[1048] = {
  title = "Nello Scarlet Monastery",
  desc = "Mentre la Signora Oscura si occupa della pressante questione dell'avanzata del Re dei Lich a nord, io faccio in modo che le questioni più vicine a casa vengano sistemate come si deve.$B$BNon c'è dubbio che i parassiti umani che si fanno chiamare Crociata Scarlatta si stiano rivelando la spina nel fianco più dolorosa, qui in patria. Le Tirisfal Glades brulicano letteralmente di quelle piccole formiche rosse.$B$BVa' al Monastery, $C, e annienta la Grande Inquisitrice Whitemane e i suoi luogotenenti più alti in grado.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Varimathras, nell'Undercity.",
  progress = "Forse non sono stato abbastanza esplicito nei miei ordini, $C. Voglio la Grande Inquisitrice Whitemane morta, una volta per tutte. E già che ci sei, elimina anche i suoi pezzi grossi.$B$BUccidi quel fanatico, il Comandante Scarlatto Mograine. Annienta Herod, il Campione Scarlatto. E massacra il Maestro dei Segugi Loksey, e anche i suoi luridi cagnacci.$B$BOra vattene!",
  reward = "Hai servito bene la Signora Oscura, $C. Non era cosa da poco, quello che ti ho chiesto.$B$BLa tua lealtà verso i Reietti è stata notata. E la tua tenacia in combattimento sarà ricordata.",
  en_title = "Into The Scarlet Monastery",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",
}
T[1049] = {
  title = "Compendio del Caduto",
  desc = "Il Circolo della Terra aveva intenzioni pure nei confronti dei nostri fratelli appestati. Ma chi può conoscere le motivazioni di chi sussurra all'orecchio dell'Elder Council?$B$BI Reietti con cui ci siamo alleati hanno un passato intriso di inganni. Il nostro patto è stato troppo frettoloso. Forse Cairne avrebbe fatto bene a dare ascolto agli avvertimenti di Orgrimmar.$B$BNel profondo dello Scarlet Monastery si trova il Compendio del Caduto, sorvegliato da folli fanatici umani. Il loro metodo nasce dalla follia, ma le loro ricerche potrebbero rivelarsi utili.",
  obj = "Recupera il Compendium of the Fallen dal Monastery nelle Tirisfal Glades e torna da Sage Truthseeker, a Thunder Bluff.",
  progress = "Cairne è un capo coraggioso e nobile, e gli affiderei la mia stessa vita. Ma in questo clima politico sono altri quelli di cui non mi fido.$B$BQuando avrò modo di raccogliere tutte le conoscenze disponibili, potrò consigliare saggiamente il Capotribù.$B$BHai avuto modo di andare nelle Tirisfal Glades? Allo Scarlet Monastery? Il Compendio del Caduto è solo un pezzo di questo complicato rompicapo...",
  reward = "Il Compendio del Caduto! Cominciavo a chiedermi se quel libro esistesse davvero!$B$BHai servito bene i tauren di Thunder Bluff, $N. La tua dedizione non sarà dimenticata.",
  en_title = "Compendium of the Fallen",
  en_obj = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",
}
T[1050] = {
  title = "Mitologia dei Titani",
  desc = "Il futuro è inevitabile! Ci gettiamo verso il futuro come gocce di pioggia che cadono nel Great Sea.$B$BMa forse, studiando il passato, possiamo sapere cosa aspettarci ed essere più preparati all'ignoto.$B$BPrima che terribili sventure si abbattessero su Lordaeron, c'era un bastione del sapere nascosto nelle Tirisfal Glades. Si dice che un libro intitolato Mitologia dei Titani fosse custodito nella biblioteca del vecchio Monastery.$B$BPortamelo, e forse insieme potremo svelare i segreti del passato!",
  obj = "Recupera Mythology of the Titans dal Monastery e portalo a Librarian Mae Paledust, a Ironforge.",
  progress = "Il Monastery era un seminario per Paladini in addestramento. Un tempo roccaforte della Luce, è caduto nelle mani dei folli fanatici della Crociata Scarlatta.$B$BLa Crociata riteneva nobile il proprio scopo: purificare la terra dalla piaga dei non morti. Ma la follia ha corrotto la sua missione, e ora è nemica di tutti.$B$BPortami la Mitologia dei Titani, così potrò studiarla e custodirla qui a Ironforge.$B$BLe sale corrotte del Monastery non sono il posto per un tesoro storico simile.",
  reward = "Hai salvato il testo sacro!$B$BIl tuo viaggio è stato lungo e recuperare il libro non è stato certo un compito facile. Ma i nani di Ironforge trarranno beneficio dal tuo successo.$B$BGrazie, $N, a nome della Lega degli Esploratori.",
  en_title = "Mythology of the Titans",
  en_obj = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",
}
T[1051] = {
  title = "La Vendetta di Vorrel",
  desc = "Anche se la mia volontà è libera, non posso più servire la Signora Oscura. Sento che il mio tempo su Azeroth è giunto alla fine. La mia forza vitale è in frantumi.$B$BÈ stato l'Interrogatore Vishas a ridurmi così! Mi ha torturato per settimane! Mi ha preso la fede nuziale e l'ha data a sua moglie. Quel bastardo!$B$BVendetta... voglio vendetta!$B$BQuello stolto pieno di sé si vantava della sua preziosa moglie, Nancy, che viveva sulle rive del Lago Lordamere. Trova quella donnaccia, uccidila e riporta la mia fede nuziale a mia moglie, Monika, a Tarren Mill.$B$BRispetta le mie ultime volontà...",
  obj = "Riporta la fede nuziale di Vorrel Sengutz a Monika Sengutz, a Tarren Mill.",
  progress = "Cosa vuoi, $Gstraniero:straniera;?",
  reward = "Vorrel ha avuto un'esistenza così travagliata. E che buon compagno era...$B$BMaledetti quei luridi umani!$B$BVorrel non c'è più, e non godrà mai più della non morte. Almeno posso trovare conforto nella vendetta che hai compiuto in suo nome. Per questo ti ringrazio.$B$BOra lasciami al mio lutto...",
  en_title = "Vorrel's Revenge",
  en_obj = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",
}
T[1052] = {
  title = "Lungo il Sentiero Scarlatto",
  desc = "Noi della Crociata Scarlatta rivendichiamo roccaforti da Hearthglen fino alle Tirisfal Glades. Siamo molto fieri dei nostri bastioni di purificazione in tutta Lordaeron.$B$BHai dimostrato il tuo valore contro i non morti di Desolace. Ma la vera minaccia della piaga si trova a Lordaeron.$B$BVa' nella cittadina di Southshore, negli Eastern Kingdoms. Cerca un crociato di nome Raleigh the Devout. Dagli questa lettera di encomio con il mio sigillo e ti accompagnerà a un posto d'onore nel nostro Scarlet Monastery.",
  obj = "Porta la Letter of Commendation di Brother Anton a Raleigh the Devout, a Southshore.",
  progress = "Chi va là? Che cosa vuoi da me?",
  reward = "Fratello Anton diffonde ancora la parola della Crociata Scarlatta? Oh, cielo...",
  en_title = "Down the Scarlet Path",
  en_obj = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.",
}
T[1053] = {
  title = "Nel Nome della Luce",
  desc = "Un tempo servivo la Crociata Scarlatta con onore, lealtà e orgoglio. Credevo che la sua causa fosse nobile: liberare Azeroth dai non morti.$B$BMa durante il tempo che ho passato al Monastery, nelle Tirisfal Glades, mi sono reso conto che stavano perdendo il contatto con la realtà. Ora pensano che chiunque non indossi il tabarro della Crociata sia appestato. Uomini e donne innocenti sono stati torturati perché, a quanto si diceva, erano appestati.$B$BLa Crociata Scarlatta deve essere schiacciata nel nome della Luce. Tu, $N, devi distruggere questo regime folle.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Raleigh the Devout, a Southshore.",
  progress = "La corruzione nel Monastery non finirà finché non saranno eliminati i suoi capi di grado più alto.$B$BNel nome della Luce, uccidi la Grande Inquisitrice Whitemane, il Comandante Scarlatto Mograine, Herod, il Campione Scarlatto, e il Maestro dei Segugi Loksey. Una volta caduti loro, forse la vera causa potrà riaccendersi. Fino ad allora, chiunque incroci il cammino della Crociata è in pericolo.$B$BParti da Southshore e fa' che accada!",
  reward = "Anche se i discepoli della Luce non gioiscono mai della perdita di vite, dobbiamo accettare che a volte questi sacrifici siano necessari per il bene superiore del Regno e del pianeta.$B$BCon le tue imprese nel Monastery hai risparmiato molte vite innocenti, $N. Rendo omaggio alla tua tenacia.",
  en_title = "In the Name of the Light",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",
}
T[1054] = {
  title = "Ridurre la Minaccia",
  desc = "Subito a nord di Astranaar ci sono i mezzorsi Thistlefur. I miei esploratori riferiscono che il loro numero è cresciuto molto negli ultimi mesi. Se diventano troppi, potrebbero trovare il coraggio di attaccare Astranaar direttamente.$B$BUccidine quanti più puoi, ma portami il teschio del loro capotribù come prova che i loro piani sono stati stroncati... per ora.$B$BIo resterò qui ad Astranaar e aspetterò tue notizie. Che Elune sia con te.",
  obj = "Porta Dal Bloodclaw's Skull a Raene Wolfrunner, ad Astranaar.",
  progress = "La corruzione dei mezzorsi ha ridotto Ashenvale all'ombra della sua antica gloria.",
  reward = "Ben fatto, $N.$B$BI mezzorsi ci minacciano di continuo. Speriamo che questo li tenga a bada ancora per un po'.",
  en_title = "Culling the Threat",
  en_obj = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.",
}
T[1055] = {
  title = "La Purificazione di Raene",
  desc = "La verga, ora completa, è nelle tue mani. Shael'dryn vorrà sapere del tuo successo.",
  obj = "Torna da Shael'dryn, al pozzo lunare.",
  reward = "Ce l'hai fatta, $N! Ben fatto!",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Shael'dryn at the moonwell.",
}
T[1057] = {
  title = "Riconquistare la Valle Bruciata",
  desc = "Proteggo gli spiriti della foresta, quindi puoi senz'altro immaginare perché sono allarmato.$B$BHai attraversato queste montagne per raggiungere questo picco. Di certo hai visto lo scempio che si è abbattuto su questa terra. L'avidità ha portato alla distruzione di queste colline sacre.$B$BLa Valle Bruciata, a sud, è stata data alle fiamme dall'avida armata meccanizzata degli industriali. Peggio ancora, le Bloodfury che hanno invaso la zona non ci lasciano entrare per avviare la rinascita della valle.$B$BScaccia le miserabili arpie, $N!",
  obj = "Keeper Albagorm, su Stonetalon Peak, vuole che tu uccida 7 Bloodfury Harpy, 7 Bloodfury Ambusher, 7 Bloodfury Slayer e 7 Bloodfury Roguefeather.",
  progress = "C'è molto lavoro da fare prima che la Valle Bruciata possa tornare la foresta rigogliosa che era un tempo.$B$BRipulisci la zona da quelle minacce immonde, $N! Solo allora potremo cominciare a riprenderci ciò che appartiene alla natura.",
  reward = "Ora che le Bloodfury hanno subito una perdita così grande, forse il vero lavoro di risanamento della terra può cominciare...",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
}
T[1058] = {
  title = "La Magia della Foresta di Jin'Zil",
  desc = "Così emozionato sono!$B$BTre gabbiette per tre elfetti! Ma cosa ne facciamo dei nostri cari amici amanti degli alberi? Ma sì, diamogli un assaggio di... come la chiamano... magia della foresta!$B$BMi servirà un bel mucchio di linfa di Stonetalon. Da quei felini orrendi portami dei baffi del crepuscolo. Qui ci vogliono un sacco di occhi di corsiero, naturalmente — gli occhi non bastano mai. Ah, e non dimentichiamo, una preziosa scaglia di drago fatato.$B$BCorri allo Stonetalon Peak, $N, così posso preparare un po' di magia della foresta!",
  obj = "Witch Doctor Jin'Zil, a Malaka'jin, vuole 5 porzioni di Stonetalon Sap, 5 Twilight Whisker, 30 Courser Eye e un Fey Dragon Scale.",
  progress = "Guarda i nostri poveri amici elfi. Tutti in gabbia, senza una foresta in cui sgambettare!$B$BAllora, sei $Griuscito:riuscita; a trovarmi un po' di linfa? E i baffi dei corridori del crepuscolo? Non è che per caso hai addosso quella scaglia di drago fatato?$B$BE occhi! Mi serviranno tanti occhi! Non si può proprio mescolare un intruglio di magia della foresta bello forte senza una buona dose di occhi!",
  reward = "Oh, come saranno felici queste ninfette dei boschi! Le faremo sentire proprio a casa con questo intruglio speciale!",
  en_title = "Jin'Zil's Forest Magic",
  en_obj = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",
}
T[1059] = {
  title = "Riconquistare la Valle Bruciata",
  desc = "Le Bloodfury sono state sottomesse. Ma si riorganizzeranno molto presto, se non si fa qualcosa.$B$BMolto a sud delle Barrens si estende una terra conosciuta come Thousand Needles. Se in Thousand Needles viaggi verso ovest finché non raggiungi il limitare della foresta rigogliosa di Feralas, troverai un druido di nome Falfindel Waywarder.$B$BQuesto druido grande e saggio è capace di evocare grandi spiriti della foresta, che possono aiutarci a riconquistare la Valle Bruciata.$B$BFagli sapere che abbiamo bisogno di aiuto! Cercalo subito!",
  obj = "Raggiungi Falfindel Waywarder al confine tra Thousand Needles e Feralas.",
  reward = "Il Custode Albagorm ha agito con saggezza mandandoti qui con tanta urgenza.$B$BVediamo se riusciamo a chiamare dalla grande foresta un aiuto che raggiunga la Valle Bruciata prima che sia troppo tardi.",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",
}
T[1066] = {
  title = "Sangue di Innocenti",
  desc = "Creerò una tossina che prosciughi la violenza di quelli della Venture Company, rendendoli deboli e docili. Dovrebbe risolvere il problema dell'Orda a Stonetalon, no?$B$BMa per creare la tossina mi servirà il sangue di innocenti, un ingrediente difficile da procurarsi.$B$BPer fortuna il Syndicate, un gruppo di briganti umani di questa zona, si serve di maghi dell'ombra... e quei maghi raccolgono sangue innocente per i loro scopi poco raccomandabili.$B$BPuoi trovare i maghi dell'ombra del Syndicate al Forte Durnholde, a sud-est.",
  obj = "Porta 5 Vial of Innocent Blood ad Apothecary Lydon, a Tarren Mill.",
  progress = "Hai trovato i Maghi dell'Ombra del Syndicate e hai recuperato da loro il sangue?",
  reward = "Molto bene! Immagino che il Syndicate ti abbia dato poco filo da torcere, no?$B$BCome ho detto, il sangue di innocenti non è una cosa facile da procurarsi. Per nostra fortuna, i maghi dell'ombra del Syndicate hanno fatto il lavoro difficile al posto nostro.$B$BOra aspetta un momento, mentre preparo il mio intruglio...",
  en_title = "Blood of Innocents",
  en_obj = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.",
}
T[1067] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Ecco la tossina. Se la usi contro la Venture Company dovrebbe dare risultati favorevoli, forse perfino contagiosi. Devo dire che è piuttosto entusiasmante vedere il mio lavoro applicato sul campo!$B$BMa prima di usarla, portala alla Speziale Zamah. Deve trovare un modo per diffondere la tossina, così che abbia il massimo effetto.",
  obj = "Porta Lydon's Toxin ad Apothecary Zamah, a Thunder Bluff.",
  progress = "Sei $Gtornato:tornata;, $N. Porti aiuto da parte dello Speziale Lydon?",
  reward = "Una tossina dello Speziale Lydon? Molto bene. Se conosco bene Lydon, questa tossina sarà piuttosto efficace contro la Venture Company...",
  en_title = "Return to Thunder Bluff",
  en_obj = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.",
}
T[1068] = {
  title = "I Segatronchi",
  desc = "C'è un legame tra la magia spirituale degli sciamani e la magia naturale dei druidi. È per questo che noi sciamani possiamo sentire la supplica degli spiriti di Stonetalon. Molti dei loro sussurri mi sfuggono, ma un messaggio, una visione, è chiara...$B$BHo avuto la visione di due macchine a forma d'uomo nella Landa di Windshear, a nord-ovest della Valle di Greatwood, che abbattevano alberi a una velocità impossibile. Queste bestie di metallo vanno fermate!$B$BNella mia visione, le macchine erano marchiate con simboli strani:$B$BXT:4 e XT:9.",
  obj = "Distruggi i segatronchi XT:4 e XT:9, poi torna da Seereth Stonebreak, al confine tra le Stonetalon Mountains e le Barrens.",
  progress = "Gli spiriti degli alberi gemono per la perdita dei loro fratelli, $N. Devi distruggere i segatronchi XT:4 e XT:9, o temo che Stonetalon non sarà mai risanata.",
  reward = "La distruzione delle macchine XT:4 e XT:9 ha placato molti degli spiriti di Stonetalon, $N. Speriamo che la Venture Company, ora che le ha perse, se ne vada da queste montagne.$B$BPerché se non lo farà, temo che le atrocità subite da questo luogo impallidiranno davanti a ciò che verrà.",
  en_title = "Shredding Machines",
  en_obj = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.",
}
T[1070] = {
  title = "Di Guardia a Stonetalon",
  desc = "Salve, $N.$B$BA giudicare dal tuo aspetto, hai una gran voglia di girare il mondo. Sei mai $Gstato:stata; alle Stonetalon Mountains? È una terra flagellata dalla Venture Co. e da altri nemici degli elfi della notte.$B$BDi recente la Sentinella Wolfrunner ha mandato là la mia amica Kaela Shadowspear a indagare su quel che sta accadendo a quella terra, ma non ho ancora sue notizie. Sono ancora più preoccupata perché l'Alleanza ha mandato con lei un mago gnomo... segno di guai, di sicuro.$B$BPotresti trovarla e poi tornare a riferirmi?",
  obj = "Trova Kaela Shadowspear, che sorveglia dall'alto la valle all'ingresso di Windshear Crag, nelle Stonetalon Mountains.",
  reward = "Ah, sei $Gvenuto:venuta; da Ashenvale per volere di Tara — quanto mi mancano lei, la mia terra e i miei amici. Deve cavarsela bene con le Sentinelle, se può permettersi di assoldare avventurieri per altri incarichi. Sono orgogliosa di lei.$B$BÈ un piacere conoscerti, $N.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.",
}
T[1071] = {
  title = "La Tregua di uno Gnomo",
  desc = "Vedi, $N, sono membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio obiettivo... anzi, il mio DOVERE! è mostrare agli elfi della notte che un misto di magia, miscele e meccanismi può aiutare a salvare le loro foreste.$B$BMa è una guerra dura, e sembra che i goblin si riproducano come conigli. Non ho nemmeno avuto il tempo di costruire le mie ultime invenzioni!$B$BMi serve un po' di tempo per pianificare e organizzarmi. Ma per riuscirci ho bisogno che tu tenga a bada i goblin nella Landa di Windshear, a est...",
  obj = "Uccidi 10 Venture Co. Logger e 10 Venture Co. Deforester, poi torna da Gaxim Rustfizzle a Stonetalon.",
  progress = "Come va la battaglia dalle tue parti, $N?",
  reward = "Grazie mille del tuo aiuto, $N. Sei $Gtornato:tornata; giusto in tempo, tra l'altro.$B$BCredo di avere un piano perfetto... esplosivi. No, quello non è il piano, ma ne fa parte.$B$BVedi, sto usando esplosivi ad alto potenziale — non preoccuparti, non sono pericolosi come pensano tutti — per spaventare i goblin e farli arretrare un po'. Riesco a spingerli dove voglio con qualche detonazione ben piazzata lungo i bordi delle montagne, ma da qualche giorno sono a corto di scorte...",
  en_title = "A Gnome's Respite",
  en_obj = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.",
}
T[1072] = {
  title = "Un Vecchio Collega",
  desc = "Il congegno a cui penso è la mia versione più avanzata finora. Ma servirà una pozione speciale perché funzioni. Tanto vale prendere la roba buona, visto che questa missione potrebbe essere la tua ultima.$B$BE per questo ci serviranno esplosivi potenti: il Nitromirglyceronium.$B$BL'unico che sa fare l'NG-5 è un mio vecchio amico: Lomac Gearstrip. Cercalo a Tinker Town.$B$BTu convincilo a farcene un po', di NG-5, e io mi metto al lavoro sulla disposizione dei miei congegni.",
  obj = "Parla con Lomac Gearstrip a Ironforge.",
  reward = "Ahhh... Ti manda Gaxim, eh? E come faccio a sapere che non mi stai mentendo?! Mmh? Mmh...?",
  en_title = "An Old Colleague",
  en_obj = "Speak to Lomac Gearstrip in Ironforge.",
}
T[1073] = {
  title = "Incapacità + Sostanze Chimiche = Divertimento",
  desc = "Ahahah... ti serve il Nitromirglyceronium per impedire a dei goblin di distruggere una foresta?!$B$BNon mi importa se conosci Gaxim o no... ti do la roba solo per vedere te o loro esplodere in mille pezzettini.$B$BC'è un problema, però: sono a secco.$B$BMa facciamo così: tu mi porti le pozioni giuste e io te ne preparo subito un po'.$B$BIl minimo che puoi fare è dimostrare di avere un po' di abilità come alchimista, prima che io ti regali un campione della mia più grande creazione.",
  obj = "Porta 4 Minor Mana Potion e 2 Elixir of Minor Fortitude a Lomac Gearstrip, a Ironforge.",
  progress = "Non posso fare Nitromirglyceronium se non ho le pozioni... sono essenziali per prepararlo.",
  reward = "Andranno benissimo.$B$BSe non sapessi come stanno le cose, $Gstraniero:straniera;, direi che te ne intendi di alchimia. Bene, bene... il mondo non è fatto solo di spade e stregoneria, sai?",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.",
}
T[1074] = {
  title = "Incapacità + Sostanze Chimiche = Divertimento",
  desc = "Eccoti $Gservito:servita;, $Gstraniero:straniera;. Stacci $Gattento:attenta;, però... è roba instabile.$B$BSe sei davvero $Gun amico:un'amica; di Gaxim, salutamelo. Se non lo sei, divertiti a farti saltare in aria.",
  obj = "Riporta il Nitromirglyceronium a Gaxim Rustfizzle, a Stonetalon.",
  progress = "Ah, che bello, sei $Gtornato:tornata;.",
  reward = "Hai svolto il tuo compito alla perfezione, $N.$B$BL'NG-5 è il componente indispensabile della ricetta per far detonare i carri di dinamite.$B$BCosa? Sì, dinamite... carri interi. È la distrazione perfetta, te lo dico io... aspetta e vedrai.",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.",
}
T[1075] = {
  title = "Una Pergamena da Mauren",
  desc = "Bene, passiamo alla parte del mio piano sulla detonazione a distanza... oh, non te l'ho ancora spiegata, vero?$B$BAllora, in breve è così: con un po' di magia posso fare in modo che gli esplosivi saltino mentre tu non sei nei paraggi. Sto mettendo insieme un congegno che ti permetterà di premere un solo pulsante e far esplodere l'NG-5 quando sarai $Gpronto:pronta;.$B$BMa mi serve un incantesimo da un amico a Stormwind — si chiama Collin Mauren. Lo trovi nel quartiere dei maghi, laggiù. È umano, quindi non dovrebbe essere difficile da notare.",
  obj = "Trova Collin Mauren a Stormwind.",
  reward = "Dunque, questo incantesimo che ti serve; uno che ti permetta di far detonare esplosivi a distanza... mmm.",
  en_title = "A Scroll from Mauren",
  en_obj = "Find Collin Mauren in Stormwind.",
}
T[1076] = {
  title = "Diavoli a Westfall",
  desc = "Ah, forse ci sono. Un incantesimo di messaggio... credo sia questo l'effetto che cerca.$B$BDovrò creare una pergamena con l'incantesimo impresso sopra. Per farlo mi serviranno i resti di un diavolo di polvere.$B$BMentre raccolgo gli altri componenti, perché non vai a Westfall a cercare una di quelle creature immonde? Sono pericolose, ma sono sicuro che non sia niente che tu non sappia affrontare, se sei $Gdisposto:disposta; a sottoporti a uno degli esperimenti di Gaxim.$B$BMi troverai qui al tuo ritorno.",
  obj = "Porta Dust Devil Debris a Collin Mauren, a Stormwind.",
  progress = "Salve, $N. Hai trovato il componente che mi serve?",
  reward = "Dammi solo qualche istante e la tua pergamena sarà pronta.",
  en_title = "Devils in Westfall",
  en_obj = "Bring Dust Devil Debris to Collin Mauren in Stormwind.",
}
T[1077] = {
  title = "Consegna Speciale per Gaxim",
  desc = "Ecco a te, $N. Questa dovrebbe andare benissimo.$B$BMi raccomando, porta i miei saluti a Gaxim quando lo rivedrai. Non vedo l'ora di sentirmi raccontare questa avventura, quando sarà conclusa.$B$BStammi bene.",
  obj = "Porta la Scroll of Messaging a Gaxim Rustfizzle, a Stonetalon.",
  progress = "Ahah! Sei $Gtornato:tornata;! Ce l'hai? Hai l'incantesimo?",
  reward = "È perfetto, $N! Ben fatto.$B$BQuesto incantesimo, mescolato all'NG-5, ci darà l'esplosivo a distanza perfetto.$B$BRiusciremo a creare la distrazione perfetta per te, così potrai intrufolarti e rubare le lettere e i progetti tecnici della Venture Co.$B$BQuesto rallenterà di sicuro il loro disboscamento.",
  en_title = "Special Delivery for Gaxim",
  en_obj = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.",
}
T[1078] = {
  title = "Recupero per Mauren",
  desc = "I viaggiatori continuano a chiedermi delle Stonetalon Mountains. Pare sia una meta molto ambita da chi cerca l'avventura — non importa se cerchi wyvern, elementali o se hai affari con la Venture Co.$B$BNella Valle Bruciata, nel cuore di Stonetalon, c'era una specie di basilischi le cui scaglie, ridotte in polvere, erano un reagente meraviglioso per certi incantesimi che ho creato.$B$BSe quei basilischi vivono ancora, mi piacerebbe molto avere qualcuna delle loro scaglie.$B$BFa' con calma, non c'è fretta, ma posso pagare bene.",
  obj = "Porta 8 Crystalized Scales a Collin Mauren, a Stormwind.",
  progress = "Salve di nuovo, $N.$B$BSei già $Gtornato:tornata; dalla Valle di Stonetalon con quelle scaglie?",
  reward = "È perfetto, $N. Grazie infinite.$B$BForse un giorno, in futuro, potrò aiutarti come tu hai aiutato me.",
  en_title = "Retrieval for Mauren",
  en_obj = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.",
}
T[1079] = {
  title = "Operazioni Segrete — Alpha",
  desc = "Ci siamo, $N. Presta molta attenzione. I congegni sono finiti e pronti all'uso.$B$BPrendi queste pagine — ti diranno di più sui detonatori e sugli esplosivi, e su dove piazzarli.$B$BRicorda, il successo della tua missione non dipende da quanta distruzione provochi. Il successo del Piano Alpha dipende da te: devi riportare i progetti tecnici della Venture Co. che si trovano dentro la segheria a sud del Lago di Cragpool.",
  obj = "Recupera i Venture Co. Engineering Plans dalla segheria nel Windshear Crag.",
  progress = "Hai preso i progetti, $N?",
  reward = "Davvero straordinario! È un colpo enorme per la Venture Co.$B$BRiusciremo a trovare i punti deboli delle loro macchine e anche a incorporare i loro progetti nelle nostre creazioni. Questa sì che è una giornata meravigliosa.",
  en_title = "Covert Ops - Alpha",
  en_obj = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.",
}
T[1080] = {
  title = "Operazioni Segrete — Beta",
  desc = "Il Piano Beta è proprio come il Piano Alpha, $N.$B$BCreiamo una distrazione e poi rubiamo le loro preziose lettere.$B$BL'importante è prendere le lettere... ricordatelo.$B$BLe pagine che ti ho già dato ti diranno dove piazzare gli esplosivi. Tu torna qui $Gvivo:viva; e con quelle lettere...",
  obj = "Recupera le Venture Co. Letters dalla Miniera di Windshear, all'estremità est del Windshear Crag.",
  progress = "Com'è andata, $N?",
  reward = "Incredibile, $N! Kaela e le Sentinelle saranno felicissime. Con la tua abilità e le mie creazioni, siamo inarrestabili.",
  en_title = "Covert Ops - Beta",
  en_obj = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.",
}
T[1081] = {
  title = "L'Accoglienza di Tyrande",
  desc = "$N, non ho dubbi che Tyrande Whisperwind in persona vorrebbe ringraziarti per aver preso parte a questa missione.$B$BA prima vista può non sembrare, ma quello che hai contribuito a mettere in moto potrebbe benissimo rafforzare la nostra posizione nelle Stonetalon Mountains.$B$BSe ti consideri $Gnostro alleato:nostra alleata; contro queste atrocità, va' da Tyrande nel Tempio della Luna, a Darnassus.",
  obj = "Trova Tyrande Whisperwind a Darnassus.",
  reward = "Salve, $N. Sì, ho già sentito il tuo nome e, per quanto tu sia ancora nel pieno della giovinezza, sono lieta di vedere la strada che ti sei $Gtracciato:tracciata;.$B$BMi faresti un grande onore se accettassi questo dono come segno della mia riconoscenza.",
  en_title = "Reception from Tyrande",
  en_obj = "Find Tyrande Whisperwind in Darnassus.",
}
T[1082] = {
  title = "Aggiornamento per la Sentinella Thenysil",
  desc = "$N, hai compiuto una grande azione dando una mano qui.$B$BLe Sentinelle di Ashenvale ti ricompenseranno bene se le informerai che Gaxim e io siamo vivi. Di' loro che siamo sulla buona strada per fermare la Venture Co. e risanare queste terre.$B$BTrova Tara Thenysil ad Astranaar; sarà contenta di vedere che sei $Gtornato:tornata; con buone notizie.",
  obj = "Torna da Sentinel Thenysil, ad Ashenvale.",
  reward = "Grazie, $N. Hai reso un servizio alle Sentinelle.$B$BSono felice di sapere che Kaela... e persino Gaxim, stanno bene.$B$BTi sei $Gguadagnato:guadagnata; la nostra stima.",
  en_title = "Update for Sentinel Thenysil",
  en_obj = "Return to Sentinel Thenysil in Ashenvale.",
}
T[1083] = {
  title = "Spiriti Infuriati",
  desc = "Non so con certezza cosa abbia fatto la Venture Co. alla Valle, ma è evidente che è stata sopraffatta dalle creature del posto.$B$BHanno dato fuoco alla foresta e hanno usato i loro ordigni di distruzione per devastare la Valle il più possibile.$B$BMa nella loro ignoranza hanno liberato anche qualcos'altro: spiriti ardenti, elementali di fiamma, pietra e rabbia.$B$BLa terra non ha speranza di vedere il sorriso di Elune finché queste creature vagano libere.$B$BPortami le loro braci fumanti, come prova che ne hai ridotto il numero.",
  obj = "Porta a Kaela Shadowspear, a Stonetalon, 8 Smoldering Embers presi dagli elementali del fuoco a Charred Vale.",
  progress = "La prima volta che ho visto la Valle Bruciata ho quasi pianto, $N.",
  reward = "I resti del nostro nemico... la tua forza ci è molto utile, $N. Grazie.",
  en_title = "Enraged Spirits",
  en_obj = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.",
}
T[1084] = {
  title = "Antichi Feriti",
  desc = "Mi sembra evidente che i protettori della Valle — i treant — c'entrino qualcosa con il fatto che la Venture Co. sia stata respinta. Purtroppo, anche quei guardiani, un tempo gloriosi, ora sono corrotti.$B$BGaxim pensa che la loro corruzione sia in qualche modo legata alle armi che i goblin hanno usato durante la ritirata.$B$BGli ho detto che avrei raccolto un campione da un treant ferito e gliel'avrei lasciato studiare, per capire se è vero.$B$BPortami un po' di quelle schegge, così lo gnomo potrà dirmi di più...",
  obj = "Porta un pezzo di Corroded Shrapnel a Kaela Shadowspear, a Stonetalon.",
  progress = "Ho la sensazione che Gaxim troverà un uso per quelle schegge, a prescindere da come la Venture Co. le ha usate in passato.",
  reward = "Grazie, $N.$B$BQuesto dovrebbe bastare e avanzare perché Gaxim capisca come i treant sono stati corrotti. Glielo porterò subito.",
  en_title = "Wounded Ancients",
  en_obj = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.",
}
T[1085] = {
  title = "Di Guardia a Stonetalon",
  desc = "La situazione qui a Stonetalon è evidentemente grave, se un elfo della notte e uno gnomo lavorano insieme.$B$BLa Venture Co. ha devastato queste terre e ho passato quasi tutto il mio tempo a mettere fine alla distruzione.$B$BNon giudicare Gaxim troppo in fretta: sa bene che dobbiamo collaborare.$B$BSe vuoi aiutarci, comincia col parlare con Gaxim.$B$BMi dispiace di non poterti ancora rimandare da Tara con buone notizie. Forse presto.",
  obj = "Parla con Gaxim.",
  reward = "Infida... infida e pericolosa, ecco com'è questa terra.$B$BMa io sono qui per mostrare agli elfi della notte che con l'aiuto della cara vecchia ingegneria e un pizzico di magia è un po' più sicura.$B$BVedi, rinunciare del tutto alla magia non aiuterà gli elfi della notte — ne hanno bisogno. Il mondo ne ha bisogno. E se ci metti anche ingegneria e alchimia, non puoi sbagliare. Le possibilità sono infinite.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Speak to Gaxim.",
}
T[1086] = {
  title = "L'Aeroporto delle Macchine Volanti",
  desc = "La tossina è pronta. Non resta che consegnarla. Sei tu, $N, a doverlo fare.$B$BLa Venture Company deve pur avere un modo per mandare messaggi e carichi leggeri tra il suo quartier generale e le sue attività a Stonetalon. Probabilmente è un piccolo porto aereo — non abbastanza grande per uno zeppelin, ma forse per una macchina volante. Devi cercare nelle zone di Stonetalon controllate dalla Venture Company e trovare questo porto aereo, se esiste. Se lo trovi, metti lì la tossina.$B$BMettila, e corri via.",
  obj = "Porta il Toxic Fogger al porto aereo della Venture Co., poi torna da Apothecary Zamah.",
  progress = "Devi trovare l'aeroporto della Venture Company, se esiste, $N.",
  reward = "Hai trovato il porto? Ben fatto, $N! Sono certa che i goblin siano rimasti piuttosto sorpresi dalla tua consegna! Speriamo che quella tossina trovi la strada per il loro quartier generale.$B$BHai servito bene il tuo popolo, e ti consiglio di ignorare qualunque senso di colpa tu possa provare per aver avvelenato la Venture Company. Si meritano ben di peggio.$B$BE se c'è un briciolo di saggezza che i Reietti possono insegnare ai loro alleati, è questo:$B$BNon evitare le strade oscure... se quelle strade portano alla vittoria.",
  en_title = "The Flying Machine Airport",
  en_obj = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.",
}
T[1087] = {
  title = "L'Eredità di Cenarius",
  desc = "Non puoi immaginare l'odio che provo per questa terra miserabile. La genia di Cenarius e i druidi kaldorei sul picco usano i loro patetici poteri per soffocare il flusso della magia, persino così a sud dei loro patetici possedimenti... le loro amate foreste.$B$BVorrei poter tornare a Jaedenar ed esultare nel flusso della magia, ma il mio padrone non mi permetterà di tornare finché il mio lavoro non sarà finito.$B$BSono certa che tu non ami gli elfi della notte e i loro alleati più di quanto li ami io. Aiutami, e potremo ottenere entrambi quello che vogliamo.",
  obj = "Uccidi 4 Son of Cenarius, 4 Daughter of Cenarius e 4 Cenarion Botanist per Braelyn Firehand, vicino al Sun Rock Retreat.",
  progress = "Qui, incanalare la magia è come tirare su acqua da un pozzo con un secchio pieno di buchi.",
  reward = "Già lo sento... sì... un potere così dolce... la piena che irrompe. I kaldorei sono sciocchi a disprezzare i doni di questo mondo, a rifiutare lo scorrere della magia mentre fluisce cantando nelle tue vene.$B$BChe pallida farsa è la vita senza il suo abbraccio ardente!",
  en_title = "Cenarius' Legacy",
  en_obj = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.",
}
T[1088] = {
  title = "Ordanus",
  desc = "Credevano di poter fermare il flusso della magia. Si sbagliavano. Credevano di poter nascondere Ordanus, ma avrò la sua testa!$B$BLa magia mi concede la vera vista. Sì... eccolo là. Un crocevia... In cima a un grande albero, nell'Ashenvale Forest. Un nome... Raynewood. Uno dei figli più antichi del dio della foresta. Lo hanno portato via dal picco prima che potessi trovarlo, ma il suo tempo sta per finire.$B$BPortamela, e condividerò con te un dono potente.",
  obj = "Porta Ordanus' Head a Braelyn Firehand, vicino a Sun Rock Retreat.",
  progress = "Quando il mio padrone mi ha mandata al picco di Stonetalon, pensavo che mi sarebbe bastato fare scempio degli elfi della notte che brulicavano tra le sacre rovine del nostro antico tempio di Azshara, profanandone la sacralità con il loro tocco... ma Ordanus mi era sfuggito.",
  reward = "Ho conosciuto Ordanus, un tempo, molto tempo fa. Aveva l'arroganza della sua specie, e si teneva al di sopra perfino degli Alti Nobili.$B$BOra la sua testa non sta più così in alto, vero, $N?$B$BTi ho promesso una ricompensa, e l'avrai. Vieni da me.",
  en_title = "Ordanus",
  en_obj = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.",
}
T[1089] = {
  title = "La Tana",
  desc = "I druidi hanno costruito la Tana dell'Artiglio su Stonetalon Peak, dove custodiscono molti oggetti potenti.$B$BHanno ideato un sistema complesso per impedire che finiscano nelle mani sbagliate.$B$BPer fortuna, sono riuscita a... estrarre qualche dettaglio da uno di loro.$B$BAll'ingresso della Tana troverai la Chiave del Custode del Portale, nascosta in una piccola lanterna —con quella potrai aprire i nascondigli sparsi per la Tana. Gli oggetti di quei nascondigli ti permetteranno di aprire il loro tesoro, che si trova in una delle aree centrali.",
  obj = "Raggiungi il Den su Stonetalon Peak. Usando la Gatekeeper's Key, procurati gli oggetti nascosti dei druidi. Usa quegli oggetti per aprire il Talon Den Hoard.",
  progress = "Tre serrature sono scolpite nella pietra.",
  reward = "Mentre le tre chiavi scivolano nelle rispettive aperture, in mezzo alla luce splendente compaiono diversi oggetti.",
  en_title = "The Den",
  en_obj = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. ",
}
T[1090] = {
  title = "Gli Ordini di Gerenzo",
  desc = "Sai, un tempo ero la seconda persona più importante di questo cantiere. È cambiato tutto quando Gerenzo ha preso il comando. Ha licenziato il mio capo, Ziz Fizziks, e mi ha spedito a lavorare giù nelle miniere. Ziz però mi ha detto di restare qui e raccogliere informazioni. Il suo nuovo capo ci pagherà bene se riusciamo a scoprire quali sono i piani di Gerenzo.$B$BComunque, quello che so è che Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde-oro. Posso procurarti un campione da portare a Ziz, ma dovrai fare attenzione alle pattuglie mentre lo prendo.",
  obj = "Prendi il minerale misterioso da Piznik dopo che ha finito di estrarlo.",
  reward = "Grazie, $N. Per un attimo si è messa un po' male e probabilmente abbiamo attirato fin troppa attenzione su di noi.$B$BLa cosa importante, però, è che abbiamo il campione di minerale, e dovremmo portarlo a Ziz il prima possibile.",
  en_title = "Gerenzo's Orders",
  en_obj = "Get the mysterious ore from Piznik after he finishes mining it.",
}
T[1091] = {
  title = "L'Aggiornamento di Kaela",
  desc = "$N, porta queste lettere a Kaela. Sono sicuro che vorrà saperlo. O almeno lo vorranno le Sentinelle.$B$BMi raccomando, raccontale che successo abbiamo avuto e che non ce l'avremmo fatta senza un po' di magia.",
  obj = "Porta le Venture Co. Letters a Kaela Shadowspear.",
  progress = "Sì, $N? Cosa posso fare per te?",
  reward = "Questo è davvero interessante.$B$BTu e Gaxim avete fatto un ottimo lavoro, $N. Grazie.",
  en_title = "Kaela's Update",
  en_obj = "Bring the Venture Co. Letters to Kaela Shadowspear.",
}
T[1092] = {
  title = "Gli Ordini di Gerenzo",
  desc = "Credo che farei meglio a pensare ad andarmene anch'io. Non ci vorrà molto perché la voce di quello che è successo qui arrivi ai piani alti, e di sicuro non sarebbero contenti di rivedermi.$B$BSgattaiolerò via e raggiungerò Ziz. Speriamo che riesca a trovarmi un nuovo lavoro!$B$BProverò a sistemare un po' questo pasticcio, ma tu porta subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale della Landa di Windshear. Buona fortuna.",
  obj = "Consegna l'Unidentified Ore a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Ahhh, sapevo di aver fatto la cosa giusta a dire a Piznik di rimanere lì. Sono sicuro che gli ingegneri di Undermine saranno molto interessati a dare un'occhiata a questo...$B$BNaturalmente vorrò tenerne un pezzetto per me, ma occhio non vede, cuore non duole, no?",
  en_title = "Gerenzo's Orders",
  en_obj = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1093] = {
  title = "Super Mietitore 6000",
  desc = "Terribile quello che la Venture Company ha fatto qui, eh? Ma cosa avevano in testa? Una compagnia di goblin che assume uno gnomo!$B$BPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto subito dopo che mi avevano cacciato!$B$BMi dice che hanno costruito una macchina taglialegna enorme, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo — maledetto gnomo — mi vuole morto appena mi vede... magari potresti rubare tu i progetti per me? Dovresti riuscire a trovarli addosso a uno dei loro operatori.",
  obj = "Procura i Super Reaper 6000 Blueprints a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Spero che, una volta convinto della mia lealtà — be', per quanto lo si possa convincere... onore da goblin, sai com'è? — non si faccia problemi a sfruttare il mio genio, che è piuttosto notevole.",
  reward = "Ehi, è quello che penso? Ottimo!$B$BAllora, vediamo. Uff... come dovrei capirci qualcosa... non riesco proprio a capire come ragionano gli gnomi. Ti dirò, mi stupisce che siano riusciti a costruire la ruota, figurarsi quelle macchine volanti che gli piacciono tanto.",
  en_title = "Super Reaper 6000",
  en_obj = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.",
}
T[1094] = {
  title = "Altre Istruzioni",
  desc = "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi buttavano fuori dalla porta... documenti interni della Venture Company, qualche manuale, roba tecnica... Ah, e naturalmente i progetti del Super Mietitore 6000.$B$BSputtervalve si è stabilito a Ratchet, nelle Barrens. Non dovresti far fatica a trovarlo: è un tipetto verde.",
  obj = "Consegna la Sealed Envelope a Sputtervalve, nelle Barrens.",
  progress = "Salve! Come posso aiutarti?",
  reward = "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano valide quanto basta. Cosa non darei per togliermi la Venture Company dai piedi.$B$BPerò qualche bella macchina la tirano fuori... non posso negare che alcune delle migliorie che hanno messo a punto ci sono tornate utili.",
  en_title = "Further Instructions",
  en_obj = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.",
}
T[1095] = {
  title = "Altre Istruzioni",
  desc = "La faccenda di questo gnomo assunto dalla Venture Company ha fatto un po' di rumore a Undermine. I principi del commercio non approvano che Razdunk si accompagni a questo Gerenzo.$B$BRiddlevox mi ha chiesto di occuparmi del problema, e sono sicuro che glielo abbiano ordinato uno o più principi del commercio. Naturalmente, il Direttore non me l'ha detto. Diciamo che ho un presentimento.$B$BComunque sia, Gerenzo va tolto di mezzo, e occuparsi di lui sarebbe una prova su misura per Fizziks.",
  obj = "Porta i nuovi ordini a Ziz Fizziks, nelle Stonetalon Mountains.",
  reward = "Eliminare Gerenzo? Ecco una prospettiva a cui non ho niente da obiettare.$B$BGli gnomi sono già abbastanza insopportabili di loro, ma quello che ho saputo di Gerenzo peggiora solo le cose. A quanto pare era uno dei capi ingegneri a Gnomeregan, dove lavorava al loro progetto segreto — non siamo mai riusciti a infiltrarci a Dun Morogh abbastanza a fondo da scoprire i dettagli precisi. È stato un fallimento. I nostri rapporti dicono che, qualunque cosa fosse, gli è letteralmente esplosa in faccia.",
  en_title = "Further Instructions",
  en_obj = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1096] = {
  title = "Gerenzo Wrenchwhistle",
  desc = "Ho incontrato Gerenzo una volta, ma lascia che te lo dica: non è bello da vedere. La sua carne sembra marcire, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcune membra con altre meccaniche.$B$BA nord-est di qui, ben al di sopra del Lago di Cragpool, lassù vicino alla ruota idraulica, Gerenzo sorveglia tutto il cantiere. Non c'è verso che io riesca a farmi strada combattendo fin là in cima, per non parlare di affrontare Gerenzo... Ma tu hai l'aria di potercela fare.$B$BSe lo uccidi per me, ti ricompenserò a dovere!",
  obj = "Porta Gerenzo's Mechanical Arm a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico andrà bene.",
  reward = "Guarda quel coso... ci voleva uno gnomo per inventarsi una cosa del genere. Non riesco a capire perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe benissimo tenerseli tutti e due e aggiungerne un terzo!$B$BGnomi, te lo dico io...$B$BAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova e che Sputtervalve mi assegni a una delle officine della Tinkers' Union a Gadgetzan o magari perfino a Undermine.",
  en_title = "Gerenzo Wrenchwhistle",
  en_obj = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1098] = {
  title = "Inseguitori della Morte a Shadowfang",
  desc = "In vista di un assalto a Shadowfang, due inseguitori della morte sono stati mandati alla fortezza per raccogliere informazioni. Sono passati molti giorni e non sono tornati, ma dobbiamo avere il loro rapporto se vogliamo sperare in un attacco riuscito!$B$BEcco dunque il tuo compito, $N. Va' a Shadowfang Keep, a sud, e trova gli Inseguitori della Morte Adamant e Vincent. Trovali, e se hanno bisogno di aiuto daglielo.$B$BQuesta missione è tanto pericolosa quanto decisiva, $N. Non fallire.",
  obj = "Trova Deathstalker Adamant e Deathstalker Vincent.",
  reward = "Il corpo di Vincent giace spezzato e immobile.$B$BL'Inseguitore della Morte Adamant manderà il suo rapporto a Hadrec... ma qualunque altro dettaglio Vincent avesse scoperto resterà con lui.$B$BStretto nella sua mano, però, c'è un piccolo monile...",
  en_title = "Deathstalkers in Shadowfang",
  en_obj = "Find the Deathstalker Adamant and Deathstalker Vincent.",
}
T[1100] = {
  title = "Il Diario di Lonebrow",
  desc = "Apri lentamente il diario consunto di Henrig Lonebrow....",
  obj = "Leggi Henrig Lonebrow's Journal.",
  progress = "Dalla tua aria preoccupata capisco che qualcosa non va....",
  reward = "Dici di aver trovato questo diario addosso a un nano morto? Dammi solo un momento per scorrere le pagine...",
  en_title = "Lonebrow's Journal",
  en_obj = "Read Henrig Lonebrow's Journal.",
}
T[1101] = {
  title = "La Megera del Kraul",
  desc = "Povero Heralath! E questo nano... Lonebrow. Che anima coraggiosa era.$B$BNon dobbiamo lasciare che il loro valore vada sprecato. Questa megera... Charlga Razorflank... va fermata.$B$BDi sicuro infiltrarsi nel Kraul sarà pericoloso. Non c'è tempo per avvisare Darnassus. $N, raduna un gruppo per uccidere la megera.$B$BPortami il Medaglione di Razorflank come prova della sua fine.",
  obj = "Porta Razorflank's Medallion a Falfindel Waywarder, a Thalanaar.",
  progress = "Finché Charlga Razorflank raduna le sue forze nel Razorfen Kraul, queste terre sono in grave pericolo.",
  reward = "La megera ha trovato il riposo eterno. È una notizia fantastica, $N.$B$BIn questi tempi di pericolo, è confortante vedere una persona coraggiosa come te.$B$BOra che i tirapiedi di Razorflank sono stati sistemati, i nostri studi nella zona possono continuare. Forse adesso potremo capire meglio che cosa, esattamente, abbia corrotto il luogo di riposo di Agamaggan.$B$BTemo però che anche la risposta a questa domanda stia nel tradimento...",
  en_title = "The Crone of the Kraul",
  en_obj = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",
}
T[1102] = {
  title = "Un Destino di Vendetta",
  desc = "Cairne è un nobile capo: ha unito il nostro popolo qui a Thunder Bluff.$B$BMa io, a differenza di altri, non riesco a perdonare tanto facilmente chi ci ha cacciati dalle nostre terre ancestrali. Il mio popolo ha abitato le Barrens meridionali per decenni. Quella terra per noi era sacra. Ma siamo stati cacciati da numerosi nemici.$B$BUn destino di vendetta attende la megera, Charlga Razorflank, che raduna un esercito immondo all'interno del Razorfen Kraul.$B$BPortami il cuore di Razorflank e potrò morire in pace, $N.",
  obj = "Porta Razorflank's Heart ad Auld Stonespire, a Thunder Bluff.",
  progress = "Quando saprò che le immonde bestie del Razorfen Kraul sono state cacciate dalla loro immonda tana, potrò riposare in pace, sapendo che la vendetta è compiuta.$B$BHai cacciato i quilboar dal Kraul? Mi porti buone notizie sotto forma del cuore di Razorflank?",
  reward = "Vedo che l'odiosa tribù del Razorfen Kraul ora conosce il dolore del mio popolo. Ben gli sta, a quelle bestie immonde.$B$BCacciare qualcuno da una terra sacra è un peccato che merita la vendetta più severa.$B$BGrazie, $N, per avermi aiutato nella mia sventura.",
  en_title = "A Vengeful Fate",
  en_obj = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",
}
T[1104] = {
  title = "Veleno delle Saline",
  desc = "Ho tanti progetti per la nostra auto a razzo! Tantissimi! E devo provarli tutti!!$B$BSto lavorando a un nuovo tipo di carburante. Uno che brucia a temperature davvero davvero davvero alte!! Non ho ancora azzeccato la miscela, ma credo di sapere cosa mi serve...$B$BGli scorpid che vagano per le Shimmering Flats hanno un veleno pieno zeppo di sale. È unico nel suo genere! Ed è proprio quel che mi serve!$B$BPortami il veleno e fidati — la nostra auto volerà!!",
  obj = "Porta 6 Salty Scorpid Venom a Fizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Ehi ehi ehi! L'hai preso quel veleno??",
  reward = "Benissimo! Questo veleno funzionerà alla grande! Grazie, $N!$B$BOra devo solo farlo bollire, applicare lo skipper-otomero, aggiungere un nega-catalizzatore e... Accidenti! Dove sono i miei appunti!?",
  en_title = "Salt Flat Venom",
  en_obj = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.",
}
T[1105] = {
  title = "Gusci Induriti",
  desc = "Mio fratello sta lavorando a un nuovo carburante per la sua auto a razzo. È geniale, davvero. Così geniale che... credo che quel nuovo carburante che sta progettando sia abbastanza forte da mangiarsi il telaio dell'auto!$B$BVoglio rinforzare i serbatoi prima che succeda.$B$BLe tartarughe là fuori nelle saline hanno gusci durissimi. Voglio usarli per fare serbatoi nuovi per la nostra auto a razzo. Serbatoi che reggano il nuovo carburante di mio fratello.$B$BMi sembri abbastanza responsabile. Me li prendi quei gusci?",
  obj = "Porta 9 Hardened Tortoise Shell a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Mio fratello sta facendo progressi con il suo nuovo carburante, e la cosa mi preoccupa. Devo mettermi al lavoro su un serbatoio di guscio di tartaruga il prima possibile!$B$B$N, ce li hai quei gusci?",
  reward = "Li hai presi! Grazie, $N!$B$BCaspita, questi gusci sono più duri di quanto pensassi! Eh, a lavorarli finirò per piegare una cassetta intera di attrezzi!",
  en_title = "Hardened Shells",
  en_obj = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1106] = {
  title = "Martek l'Esiliato",
  desc = "Sto sviluppando un motore nuovo che farà andare l'auto velocissima! Abbastanza veloce da volare, lo so! Mi servono solo pistoni che reggano sforzi molto molto pesanti. Tutte le mie prove sono fallite perché non riesco a fare pistoni abbastanza duri!$B$BMa c'è qualcuno che forse sa come si fa.$B$BSi chiama Martek l'Esiliato. È un grande fabbro e di metalli ne sa più di chiunque altro. Portagli questa lettera, so che può aiutarci!$B$BMa è lontano lontano — ad Azeroth, nei Badlands, in un accampamento, con un goblin!$B$BTrovalo!",
  obj = "Porta Fizzle Brassbolts' Letter a Martek the Exiled, nei Badlands.",
  progress = "Be', mi hai trovato. Buon per te.$B$BSei qui per quell'ascia che ho fatto per Gath'Ilzogg? O sei qui a riscattare l'onore della Duchessa Pamay?$B$BA dire il vero non m'importa quale delle due. Se sei qui per combattere, allora facciamola finita...",
  reward = "Ti manda Fizzle? Be', allora la cosa cambia! Certo che ti aiuto. Fizzle e suo fratello sono tra le poche persone che non mi vogliono morto!$B$BQuindi Fizzle vuole fare dei pistoni, eh? Pistoni abbastanza robusti da reggere qualunque sforzo abbia in mente, e se conosco Fizzle questa sua nuova auto è un vulcano su ruote!",
  en_title = "Martek the Exiled",
  en_obj = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.",
}
T[1107] = {
  title = "Pinne di Coda Incrostate",
  desc = "La nostra auto a razzo è la cosa più veloce delle saline! Così veloce che... temo che l'attrito la farà a pezzi!$B$BPer evitarlo devo creare un composto con cui rivestire le parti in movimento. Deve essere duro ma non fragile, e deve resistere alla corrosione del sale, altrimenti il tempo passato nelle Shimmering Flats se lo mangerà.$B$BHai mai sentito parlare della Scogliera Infame, $N? È al largo della costa di Stranglethorn Vale. Là vivono i murloc Saltscale, e le loro pinne caudali sono un ingrediente fondamentale del mio composto.",
  obj = "Porta 10 Encrusted Tail Fin a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Ce le hai le pinne caudali? Se non riesco a proteggere la nostra auto dalla sua stessa velocità, in queste corse non durerà molto.",
  reward = "Grazie, $N! Dopo averle macinate e fuse con qualche altro ingrediente, il composto sarà pronto. E dopodiché l'auto sarà al sicuro dalla propria velocità.$B$BAl sicuro, finché non va a sbattere contro qualcosa...",
  en_title = "Encrusted Tail Fins",
  en_obj = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1108] = {
  title = "Indurium",
  desc = "Non me ne sto qui solo per stare lontano dalla gente. Nei Badlands c'è metallo in abbondanza, $N, se hai il fegato di andartelo a prendere.$B$BIl metallo si chiama indurium e, guarda caso, si dice che resista molto bene al calore e alle sollecitazioni. Potrebbe andar bene per l'auto di Fizzle.$B$BMa assicuriamocene. Procurami dei campioni di indurium e ne verificherò le proprietà.$B$BIl vero minerale di indurium si trova nelle profondità di Uldaman, ma i trogg Stonevault dei Badlands a volte ne hanno addosso delle scaglie. Portami quelle scaglie.",
  obj = "Porta 10 Indurium Flake a Martek the Exiled, nei Badlands.",
  progress = "Hai trovato delle scaglie di indurium, $N? Ho la forgia accesa e pronta per provarle.",
  reward = "Ah sì, queste andranno bene. Ora mettiamole sul fuoco e vediamo come se la cavano...",
  en_title = "Indurium",
  en_obj = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.",
}
T[1109] = {
  title = "Uno, Due... Guano!",
  desc = "Come vedi, $N, alla Royal Apothecary Society stiamo conducendo degli esperimenti molto... interessanti.$B$BIn quanto Maestro, qui ho il compito di sovrintendere ai nostri tentativi alchemici più ambiziosi. Tanto lavoro e così poco tempo!$B$BPer $Gun:una; $C, hai l'aria di chi ha viaggiato molto. Forse puoi aiutarmi.$B$BHo bisogno di una sostanza rara. È un materiale immondo; viene da una rara specie di pipistrelli che si trova solo in quel buco fangoso noto come Razorfen Kraul. Portami il guano dei Pipistrelli del Kraul, così potremo cominciare il nostro lavoro...",
  obj = "Porta 1 mucchio di Kraul Guano a Master Apothecary Faranell, nell'Undercity.",
  progress = "Ah, vedo che sei $Gtornato:tornata;. Sei $Griuscito:riuscita; a procurarti del Guano del Kraul?",
  reward = "Splendido! È proprio l'inizio che ci serviva, $N.",
  en_title = "Going, Going, Guano!",
  en_obj = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",
}
T[1110] = {
  title = "Pezzi di Auto a Razzo",
  desc = "Eh eh, con tutte le corse che fanno qui, non c'è da stupirsi che ogni tanto capiti qualche incidente. Se ti guardi intorno nelle Shimmering Flats vedrai i segni degli schianti passati — pezzi di auto a razzo sparsi dappertutto!$B$BE per gnomi e goblin quei pezzi sono soldi. Sono sempre a caccia di altri aggeggi da montare sulle loro auto.$B$BQuindi va' là fuori e procurami dei pezzi. Portamene un mucchio e ti pagherò bene.",
  obj = "Porta 30 Rocket Car Parts a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "$N, sei $Gstato:stata; là fuori nelle Flats? Hai riportato quel carico di pezzi che volevo?",
  reward = "Accidenti, guarda che roba! In quel mucchio di rottami c'è della bella merce. Sono sicuro che riuscirò a rivenderla per una bella sommetta.$B$BE... è un orecchio quello che vedo schiacciato tra quelle due lamiere?? Ahia! Eh, non vorrei proprio essere quel pilota!$B$BGrazie, $N. Ecco la tua paga. Ed ecco un consiglio, gratis...$B$BSe cerchi abbastanza bene, nella disgrazia altrui trovi sempre un profitto.",
  en_title = "Rocket Car Parts",
  en_obj = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1111] = {
  title = "Wharfmaster Dizzywig",
  desc = "Il mio mestiere è procurare alla gente quel che le serve, e gli gnomi laggiù hanno un ordine di pezzi da far arrivare. I loro pezzi sono stati spediti a Ratchet una settimana fa, ma io non sono riuscito a fare il viaggio.$B$BAllora, hai voglia di macinare un po' di strada? Va' a Ratchet e consegna questo ordine a Wharfmaster Dizzywig — probabilmente sarà ai moli.$B$BFammi questo favore e avrò altri lavori per te.$B$BLavori, $Gamico mio:amica mia;, con un bel potenziale di profitto...",
  obj = "Porta Kravel's Parts Order a Wharfmaster Dizzywig, a Ratchet.",
  progress = "Parla più forte! Dimmi, consegni o ritiri?",
  reward = "Oh sì. I pezzi per Kravel. Meno male che sei qui. Questa roba è rimasta qui fuori per giorni e temevo che arrugginisse!",
  en_title = "Wharfmaster Dizzywig",
  en_obj = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.",
}
T[1112] = {
  title = "Pezzi per Kravel",
  desc = "Ecco il pacco di Kravel, $N. E quando glielo consegni, digli... che se vuole altri ordini speciali, dovrà saldare il suo conto!",
  obj = "Porta Kravel's Parts a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "Ce l'hai fatta ad arrivare a Ratchet e a prendere quei pezzi?",
  reward = "Ottimo, li hai presi! Ora dobbiamo portarli agli gnomi. Ma prima...$B$BTogliamo un piccolo pezzo...",
  en_title = "Parts for Kravel",
  en_obj = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1113] = {
  title = "Cuori di Zelo",
  desc = "Perché mi serve un tipo raro di guano, ti chiederai. Be', con questo esperimento voglio vedere che effetto possono avere l'una sull'altra due sostanze chimiche diametralmente opposte, soprattutto se unite entrambe a un agente sempre tossico, per ottenere i risultati più... raccapriccianti.$B$BTra le vette nord-orientali delle Tirisfal Glades si trova lo Scarlet Monastery. Là si radunano i folli discepoli della Crociata Scarlatta. Uccidili e portami i loro cuori zelanti.$B$BIl nostro intruglio sarà malvagissimo!",
  obj = "Master Apothecary Faranell, nell'Undercity, vuole 20 Heart of Zeal.",
  progress = "Sei $Gtornato:tornata; dallo Scarlet Monastery? Mi serviranno molti cuori per questo delizioso esperimento!$B$BSenza dubbio anche Varimathras e la Signora Oscura saranno lieti di sbarazzarsi della Feccia Scarlatta...",
  reward = "Caspita, quanto sangue mi hai portato, $N! I tuoi sforzi sono stati eccellenti!",
  en_title = "Hearts of Zeal",
  en_obj = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.",
}
T[1114] = {
  title = "Consegna agli Gnomi",
  desc = "Ora che ho quel che mi serve, da' questi pezzi a Fizzle Brassbolts. Li aspetta da tanto tempo — sono sicuro che non sentirà la mancanza del pezzettino che ho tolto dal suo ordine...$B$BE io non starei a dirglielo. Era piccolo e senza valore.$B$BFidati.",
  obj = "Porta le Delicate Car Parts a Fizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Hai qualcosa per me? Che bello! Vediamo!",
  reward = "Eccoli! I miei cricchetti idraulici e i bulloni a ripetizione! Andranno benissimo. Grazie!",
  en_title = "Delivery to the Gnomes",
  en_obj = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.",
}
T[1115] = {
  title = "Il Pettegolo",
  desc = "Ora che abbiamo fatto un servizio agli gnomi, è ora di fare un favore ai goblin!$B$BHo sentito che il pilota da corsa goblin Nazz Steamboil non si è sempre chiamato così. Mi chiedo perché abbia cambiato nome. Mi chiedo se sia un segreto e... mi chiedo quanto ci tenga a quel segreto.$B$BSe qualcuno sa la verità, è Krazek di Booty Bay, sulla punta meridionale di Stranglethorn. Parla con Krazek e chiedigli del nostro pilota goblin.$B$BSe riesci a farti dare informazioni utili, magari ci ricaviamo un profitto.",
  obj = "Parla con Krazek, a Booty Bay.",
  reward = "Vuoi sapere di Nazz Steamboil? È un pilota da corsa là alle Shimmering Flats, no?$B$BSì, forse riesco a scoprire qualcosa su di lui... ma non sarà facile. Né veloce.$B$BNé a buon mercato.",
  en_title = "The Rumormonger",
  en_obj = "Talk to Krazek in Booty Bay.",
}
T[1116] = {
  title = "Polvere Onirica nella Palude",
  desc = "Procurarti informazioni su Nazz è un bel favore, $N. Sì, proprio un bel favore. Ma sei $Gvenuto:venuta; fin qui dalle Shimmering Flats per averle... te la senti di viaggiare ancora un po'?$B$BMentre contatto le mie fonti, perché non mi raccogli qualcosa, eh?$B$BHmm... cosa potrebbe essere? Direi un po' di polvere onirica dei cuccioli di drago dello Swamp of Sorrows. Sì, mi piacerebbe proprio un po' di polvere onirica per la mia tabacchiera!$B$BProcuramela, $N, e ti darò le informazioni che cerchi.",
  obj = "Porta 10 Speck of Dream Dust a Krazek, a Booty Bay. Lo Speck of Dream Dust si raccoglie dai cuccioli di drago dello Swamp of Sorrows.",
  progress = "Già di ritorno? Ce l'hai la mia polvere onirica?",
  reward = "Ma guarda un po'. Hai trovato la polvere onirica!$B$BE ti è piaciuta la palude, $N? Non è facile rimediare un pasto caldo laggiù, vero?",
  en_title = "Dream Dust in the Swamp",
  en_obj = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.",
}
T[1117] = {
  title = "Voci per Kravel",
  desc = "Ho dovuto spendere qualche favore, regalare una rara bottiglia di vino elfico e fare anche un bel po' di deduzioni da solo! Ma le informazioni che cerchi le ho trovate.$B$BTieni, ho scritto una lettera con qualche particolare molto interessante sul nostro amico Nazz Steamboil. Fanne quel che vuoi — per me è troppo pericoloso usarla.$B$BSolo, non dire a nessuno da chi l'hai avuta!",
  obj = "Porta i Goblin Rumors a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "Hai trovato qualcosa su Nazz Steamboil? Qualcosa che magari vorrebbe tenere segreto??",
  reward = "Bene bene! Questa è interessante... molto interessante. Eh, forse la prossima volta che lo vedo dovrei fare un inchino al pilota goblin.$B$BVale parecchio, $N. Sono sicuro che Nazz pagherà una piccola fortuna per tenere il suo segreto... segreto.",
  en_title = "Rumors for Kravel",
  en_obj = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.",
}
T[1118] = {
  title = "Ritorno a Booty Bay",
  desc = "$N, sei $Gun:una; $C di cui posso fidarmi, sia per portare a termine il lavoro sia per tenere la bocca chiusa mentre lo fai.$B$BSto architettando un nuovo piano. È rischioso, ma se funziona potremmo fare un bel gruzzolo tutti e due! E credo che tu sia proprio la persona giusta per portarlo a compimento.$B$BPer cominciare, devi tornare a Booty Bay. Chiedo scusa, $Gbuon:buona; $N. So che il mio ultimo incarico ti ha già portato là. Ma questa volta parla con Crank Fizzlebub.$B$BDagli questa lettera. E se ha bisogno di aiuto, fa' del tuo meglio per aiutarlo. Ne varrà la pena.",
  obj = "Porta Kravel's Scheme a Crank Fizzlebub, a Booty Bay.",
  progress = "Salve, salve. E cosa porta $Gun nobile:una nobile; $R come te quaggiù a Booty Bay?",
  reward = "Capisco. Kravel ha in mente un grosso piano. Ha una mente diabolica — ed è questo che mi piace di lui.$B$BQuindi ti servirà qualcosa per annebbiare il cervello, eh? Qualcosa di potente...$B$BMi chiedo se si potrebbe usare la miscela che Zanzil dà ai suoi zombi...",
  en_title = "Back to Booty Bay",
  en_obj = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.",
}
T[1119] = {
  title = "Mistura di Zanzil e una Birra Scura del Folle",
  desc = "Ho capito come usare la mistura di Zanzil con la birra scura per ottenere una bevanda potente. Una Birra Scura del Folle. Credo che sarà proprio quello che serve a Kravel, ma provala e fammi sapere come funziona.$B$BE, $N, non tenere questa roba troppo a lungo senza usarla. La mistura di Zanzil ha uno strano effetto sul lievito della birra: lo fa lavorare a pieno ritmo. Quindi non resterà fresca per sempre.",
  obj = "Riporta la Fool's Stout a Kravel, nelle Shimmering Flats.",
  progress = "Salve, $N. Fizzlebub è riuscito ad aiutarci?",
  reward = "Magnifico! Fizzlebub ce l'ha fatta! Me ne ricorderò la prossima volta che lo vedrò.$B$BE grazie, $N. Stai facendo un ottimo lavoro, e tutti e due potremmo guadagnarci un sacco di soldi...",
  en_title = "Zanzil's Mixture and a Fool's Stout",
  en_obj = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.",
}
T[1120] = {
  title = "Fai Ubriacare gli Gnomi",
  desc = "Dobbiamo provare la Birra Scura del Folle su una delle squadre ai box. Se vuoi provarla sugli gnomi, allora tieni — prendi la birra e dalla al caposquadra degli gnomi.$B$BE non aspettare troppo. Prima o poi questa birra andrà a male.",
  obj = "Porta la Fool's Stout allo Gnome Pit Boss.",
  progress = "Ciao! Hai qualcosa per me?",
  reward = "Birra scura? Che pensiero gentile! Grazie!$B$BCon la corsa in arrivo non dovremmo bere, ma... forse ai miei ragazzi un goccio non farebbe male. E poi, non può essere così forte, no?",
  en_title = "Get the Gnomes Drunk",
  en_obj = "Bring the Fool's Stout to the Gnome Pit Boss.",
}
T[1121] = {
  title = "Fai Ubriacare i Goblin",
  desc = "Dobbiamo provare la Birra Scura del Folle su una delle squadre ai box. Se vuoi provarla sui goblin, allora tieni — prendi la birra e dalla al caposquadra dei goblin.$B$BE non aspettare troppo. Prima o poi questa birra andrà a male.",
  obj = "Porta la Fool's Stout al Goblin Pit Boss.",
  progress = "Che hai da guardare?",
  reward = "Cos'abbiamo qui? Alcol, eh?$B$BBe', non mi dispiace se ne beviamo solo un goccio...",
  en_title = "Get the Goblins Drunk",
  en_obj = "Bring the Fool's Stout to the Goblin Pit Boss.",
}
T[1122] = {
  title = "Torna a Riferire a Fizzlebub",
  desc = "Quella Birra Scura del Folle ha funzionato alla grande! Ho scommesso sulla prossima corsa e... speriamo che la squadra che hai fatto ubriacare abbia ridotto a pezzi la loro auto!$B$BTi resta solo un altro compito — riporta questo biglietto a Crank Fizzlebub, a Booty Bay. Vorrà sapere che la prova è riuscita.$B$BE speriamo di poter avere altra Birra Scura del Folle per le prossime corse!",
  obj = "Porta il Fool's Stout Report a Crank Fizzlebub, a Booty Bay.",
  progress = "Salve, $N. Com'è andata con quella birra? È roba forte, vero?",
  reward = "Qui dice che la birra scura del folle è stata un successo. È una bella notizia!$B$BSe mai ne vorrai ancora, fammelo sapere e ti farò raccogliere altra Mistura di Zanzil.",
  en_title = "Report Back to Fizzlebub",
  en_obj = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.",
}
T[1123] = {
  title = "Rabine Saturna",
  desc = "Per questo compito, il maggiordomo del Custode Remulos a Moonglade — Rabine Saturna — cerca aiuto per esplorare le vaste terre desolate molto a ovest di Tanaris e di Un'Goro. Si trova a Nighthaven, il villaggio principale di Moonglade.$B$BVoglio farti capire quanto sia importante la tua presenza. Crescono le tensioni tra gli elfi della notte di Darnassus e il Cenarion Circle di Moonglade. Guarda oltre i confini tra le razze e attingi alla saggezza dei tuoi antenati nei rapporti con il Circle laggiù, $N. Buona fortuna.",
  obj = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra il Felwood e Winterspring, e ci si arriva da un sentiero che parte dalla Timbermaw Hold.",
  reward = "Sono Rabine Saturna, e a nome del Custode Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.$B$BApprezzo il tuo interesse e la tua voglia di aiutare il Cenarion Circle. I tauren hanno mostrato un'incredibile inclinazione verso i precetti di Cenarius, e grazie a loro l'Orda è accolta al sicuro in questa radura. La salvaguardia di Azeroth è un obiettivo che condividiamo.$B$BQui sei tra amici, $N.",
  en_title = "Rabine Saturna",
  en_obj = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
}
T[1124] = {
  title = "Terra Desolata",
  desc = "A ovest di Un'Goro Crater, passando per il crinale nordoccidentale, c'è un'aspra terra desolata — Silithus. Pochi sanno che lì fu combattuta un'antica guerra fra gli elfi della notte e una potenza maligna e aliena. Il male fu sigillato, ma ora sospettiamo che ci siano forze all'opera per risvegliare questo... orrore indicibile.$B$BTrova Layo Starstrike, uno dei nostri agenti a Silithus; cercalo all'Asilo dei Valorosi, l'ultima dimora dei caduti delle lande desolate. Dagli questa lettera, e lui si fiderà di te.",
  obj = "Parla con Layo Starstrike vicino al cimitero di Valor's Rest, a Silithus, e mostragli Rabine's Letter.",
  progress = "Questa è una terra troppo pericolosa per prenderla così alla leggera, $C. Cosa ti porta nelle lande desolate di Silithus?",
  reward = "Ti manda Rabine, dunque? Beh, considerati $Gil benvenuto:la benvenuta; qui... per quanto questa terra desolata e abbandonata possa dare il benvenuto a qualcuno.$B$BNon ero ancora nato al tempo delle grandi tribolazioni che avvennero qui, ma ci sono parti di questo deserto che sembrano proprio immagini inquietanti di quel passato dimenticato. Con il tuo aiuto, il Cenarion Circle potrebbe riuscire a mettere fine una volta per tutte a una minaccia che sarebbe dovuta morire generazioni fa.",
}
T[1125] = {
  title = "Gli Spiriti di Southwind",
  desc = "A sud-ovest di qui si trova un luogo tragico — le rovine di Southwind Village. È da lì che deve cominciare il nostro lavoro, $N.$B$BDa quanto abbiamo appreso, un tempo questo villaggio era una base operativa degli elfi della notte per Silithus. Da molto tempo ormai è invaso dagli alveari dei silithid che infestano queste lande desolate. Posso solo immaginare l'orrore della prima devastazione del villaggio...$B$BGli spiriti tormentati dei druidi e delle sentinelle caduti vagano senza meta fra le rovine. Esplora quel luogo e libera le anime di quegli sventurati, dove serve.",
  obj = "Libera gli spiriti di 8 Tortured Druids e 8 Tortured Sentinels a Southwind Village, poi torna da Layo Starstrike al cimitero di Valor's Rest, a Silithus.",
  progress = "Alleanza o Orda, non importa — nessun essere merita di restare intrappolato in questo mondo come spirito tormentato. Liberare quelle anime rimetterà le cose a posto, $N.",
  reward = "Avevo pensato che il grande alveare turbinante vicino alle rovine del villaggio potesse aver avuto una parte nella sua fine. A quanto pare il tuo lavoro ha dimostrato che è così; la vicinanza dell'alveare è una minaccia per qualsiasi lavoro faremo qui in futuro.$B$BTi ringrazio della bontà con cui hai liberato le anime dei caduti; non è mai un compito facile, lo so. Quando sei $Gpronto:pronta;, però, vorrei chiederti aiuto ancora una volta...",
}
T[1126] = {
  title = "L'Alveare nella Torre",
  desc = "Dell'alveare di Southwind Village bisogna occuparsi, e credo di sapere come arrivare ai silithid. Per mia esperienza, gli alveari dei silithid sono molto sensibili a ciò che li circonda; questo spiega i loro attacchi quando sentono i lamenti di morte degli spiriti.$B$BI silithid sono più forti nella torre — quella con lo sciame di vespe che le gira intorno. Scala la torre e scuoti l'alveare fino a metterlo in agitazione. Torna a riferirmi quello che scopri, ma fai attenzione! Se trovi qualcosa che potrebbe essere utile, portamelo.",
  obj = "Scala la torre di Southwind Village e trova un modo per mettere in agitazione l'alveare dei silithid. Porta a Layo Starstrike, al cimitero di Valor's Rest a Silithus, qualsiasi cosa insolita tu scopra nel farlo.",
  progress = "Allora, ha funzionato? Sei ancora $Gtutto intero:tutta intera;, ed è una buona notizia. Hai trovato qualcosa?",
  reward = "Ma che... che cos'è?$B$BHa la forma di una... scatola, forse? È incrostato da far paura. Aspetta, qui c'è un pezzo scoperto... quello sotto tutta questa robaccia è un libro?$B$BCredo che tu ti sia $Gimbattuto:imbattuta; in una gran bella scoperta, $N... be', almeno lo spero. Forse è un diario o un registro di tempi antichi, conservato in questo guscio.$B$BCredo di sapere come scoprire che cos'è.",
}
T[1130] = {
  title = "Un Messaggio da Melor",
  desc = "$N, Melor Stonehoof ha sentito parlare delle tue imprese, e ti ha posto davanti un cammino.$B$BSe vuoi intraprenderlo, va' a Thunder Bluff e parla con Melor. Lo troverai sull'Altura del Cacciatore.",
  obj = "Parla con Melor Stonehoof a Thunder Bluff.",
  reward = "Dunque, $N, sei $Gvenuto:venuta;. E ora, sei $Gpronto:pronta; a viaggiare per terre lontane?$B$BSe è così, giovane $C, allora ascolta...",
  en_title = "Melor Sends Word",
  en_obj = "Speak with Melor Stonehoof in Thunder Bluff.",
}
T[1131] = {
  title = "Steelsnap",
  desc = "A volte cacciamo per il cibo. A volte cacciamo per l'onore. E a volte cacciamo per meritare gli insegnamenti della Madre Terra.$B$BMa la caccia che ora ti affido non è nessuna di queste cose. Si tratta di uccidere una creatura esclusa dalla benedizione della Madre Terra.$B$BLa iena Steelsnap si aggira per le Thousand Needles, a sud delle Barrens. È un tiranno: attira a sé altre iene e sparge paura e sangue tra le bestie più pacifiche.$B$BTrova Steelsnap, $N. Trovalo, e sconfiggilo.",
  obj = "Porta Steelsnap's Rib a Melor Stonehoof, a Thunder Bluff.",
  progress = "Hai sconfitto l'immondo Steelsnap, $N?",
  reward = "Sconfiggendo la creatura Steelsnap, hai purificato le Thousand Needles da una corruzione orribile.$B$BE questa, $N, è la tua lezione di oggi.",
  en_title = "Steelsnap",
  en_obj = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.",
}
T[1134] = {
  title = "I Pridewing di Stonetalon",
  desc = "Non siamo in guerra aperta con l'Orda, ma la nostra è una pace fragile. Spesso scopriamo i loro agenti che tramano contro di noi, ma lo fanno di nascosto.$B$BUna di queste mosse ci è stata rivelata da fonti segrete a Theramore: dicono che gli orchi raccolgano il veleno dai pridewing vicino al Lago Mirkfallon, nelle Stonetalon Mountains a sud. Poi gli assassini orchi usano quel veleno nelle loro incursioni segrete e mortali contro l'Alleanza!$B$BSe è vero, dobbiamo fermarli, $N. Dobbiamo togliere loro la fonte del veleno.",
  obj = "Porta 12 Pridewing Venom Sac a Shindrell Swiftfire ad Astranaar.",
  progress = "Hai le sacche di veleno dei pridewing, $N? Non possiamo permettere che gli orchi usino contro di noi i veleni di quelle bestie!",
  reward = "Grazie, $N. Mi rattrista ordinare il massacro di creature che forse non aiutano di loro volontà i nostri nemici, eppure è mio dovere farlo.$B$BIl tuo cuore forse piangerà per i pridewing che hai ucciso, $Gamico mio:amica mia;, ma che poi si riempia di gioia sapendo che i tuoi alleati sono al sicuro dal veleno dei pridewing.",
  en_title = "Pridewings of Stonetalon",
  en_obj = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.",
}
T[1135] = {
  title = "Il Veleno di Highperch",
  desc = "Come forse sai, le wyverns vengono spesso addomesticate dagli orchi per farne cavalcature. Ma quello che si sa meno è che il veleno di una wyvern, in certi ambienti, vale più della bestia stessa. Quindi, se non hai paura di andare un po' a caccia di wyverns, allora... ho un lavoro per te.$B$BC'è un posto chiamato Highperch nella terra di Thousand Needles, a ovest di qui. Le wyverns di Highperch hanno un veleno potente. Potente, e prezioso.",
  obj = "Porta 10 Highperch Venom Sac a Fiora Longears, a Theramore.",
  progress = "Hai trovato Highperch, $N? Hai avuto fortuna con le wyverns laggiù?",
  reward = "Ah, quasi tutte sono così piene di veleno che stanno per scoppiare, $N. Di solito sacche così si raccolgono solo dalle wyverns giovani o dalle femmine fertili. Dev'essere stata una bella strage lassù a Highperch!",
  en_title = "Highperch Venom",
  en_obj = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.",
}
T[1136] = {
  title = "Frostmaw",
  desc = "$N, è giunto il momento che tu viaggi verso terre lontane. Sei $Gpronto:pronta;.$B$BOra dai la caccia a Frostmaw, uno yeti nelle Alterac Mountains. È sfuggente, e il suo manto bianco si confonde con le nevi della sua montagna. Si mostra di rado.$B$BMa io ti mostrerò come attirare una creatura come lui. Ecco, prendi questa pergamena. Vi ho scritto sopra come si può adescare Frostmaw.$B$BOra va', $N. Il tuo viaggio è lungo e molte prove ti aspettano. Solo quando tornerai con la criniera di Frostmaw il tuo compito sarà concluso.",
  obj = "Porta Frostmaw's Mane a Melor Stonehoof, a Thunder Bluff.",
  progress = "Sei $Gstato:stata; alle Alterac Mountains, $N? Hai affrontato lo sfuggente Frostmaw?",
  reward = "Per trovare e sconfiggere Frostmaw servivano sia la forza sia l'astuzia, $N. Tu hai entrambe.$B$BIl tuo cammino ti ha portato nelle valli delle Thousand Needles e sulle alte montagne di Alterac. Un giorno ti condurrà per tutte le terre della Madre Terra, perché tale è la via del cacciatore.",
  en_title = "Frostmaw",
  en_obj = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",
}
T[1137] = {
  title = "Notizie per Fizzle",
  desc = "L'indurium ha una resistenza al calore incredibile! Sono sicuro che andrà bene per i pistoni di Fizzle. Ma gli servirà vero minerale di indurium, non solo le scaglie.$B$BPer avere il minerale bisogna estrarlo nel profondo di Uldaman, ai confini settentrionali dei Badlands. È quella la vera fonte dell'indurium.$B$BSaluta Fizzle Brassbolts da parte mia e digli quel che ti ho detto.$B$BBuon viaggio, $N. E non mi stupirò se ci rivedremo — quando Fizzle saprà dell'indurium, probabilmente ti manderà a Uldaman a prenderlo!",
  obj = "Parla con Fizzle Brassbolts, nelle Shimmering Flats.",
  reward = "$N, sei $Gtornato:tornata;! Hai trovato Martek? Gli hai parlato? Cos'ha detto? Può aiutarci??$B$BDimmi, dimmi, dimmi!!",
  en_title = "News for Fizzle",
  en_obj = "Speak with Fizzle Brassbolts in the Shimmering Flats.",
}
T[1139] = {
  title = "Le Tavolette della Volontà Perdute",
  desc = "Abbiamo rallentato il clan Shadowforge tagliandolo fuori dalla Blackrock Spire, ma la missione di Hammertoe non è ancora compiuta. La sua morte non deve essere vana. Sognava di trovare la Tavoletta della Volontà: un frammento di pietra inciso con la magia dai titani in persona per aiutare a infondere la vita nelle loro creazioni — per dare loro una volontà propria, o almeno così dicono le leggende.$B$BDobbiamo ancora recuperare la Tavoletta prima che la trovi il clan Shadowforge.$B$BTorna a Uldaman, trova la tavoletta e torna qui immediatamente.",
  obj = "Trova la Tablet of Will e riportala ad Advisor Belgrum, a Ironforge.",
  progress = "La missione di Hammertoe deve essere portata a compimento, $N. Glielo devo.$B$BIl tuo ritorno a Uldaman è indispensabile non solo per questo scopo, ma anche per la sicurezza di tutto il popolo dei nani. Con la tavoletta nelle mani dei Dark Iron, chissà quanto diventerebbe potente il loro esercito di golem.",
  reward = "<Il Consigliere Belgrum scuote la testa incredulo mentre gli porgi il frammento di pietra.>$B$B$N, è straordinario. Lo farò portare ai maghi del re il prima possibile. Vorranno studiarlo per scoprire se le leggende sono vere. Ma ne parleremo un'altra volta: hai aiutato il nostro popolo più di quanto mi sarei mai aspettato — grazie.",
  en_title = "The Lost Tablets of Will",
  en_obj = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.",
}
T[1140] = {
  title = "La Torre di Althalaxx",
  desc = "La scrittura degli orchi è poco meglio degli scarabocchi di un bambino. Molti del mio ordine hanno storto il naso quando ho scelto di impararne la lingua, ma mi è servito a capire meglio i miei nemici.$B$BDagli scarabocchi di Ilkrud sembra che Athrikus possieda ancora due gemme dell'anima, e che siano custodite a Jorxian e a Satyrnaar, zone in mano ai satiri nel nord-est di Ashenvale.$B$BSta' $Gattento:attenta; là fuori, $N: i templi intrisi di sangue dei satiri possono turbare anche $Gun:una; $C $Gnavigato:navigata; come te.",
  obj = "Libera le anime degli Alti Nobili intrappolate a Night Run e a Satyrnaar, poi torna da Delgren the Purifier, a Maestra's Post.",
  progress = "Una volta ho sentito sussurrare che la storia dei satiri è in qualche modo legata a quella degli elfi della notte, ma i miei stimati ospiti si sono mostrati restii a parlarne.",
  reward = "Forse ai satiri è stato permesso di restare nella foresta troppo a lungo. Ne parlerò con Elissa la prossima volta che andrò ad Auberdine.$B$BComunque sia, con le gemme dell'anima distrutte il potere di Athrikus sarà molto ridotto. Dobbiamo cogliere l'occasione per eliminare lui e il suo culto.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.",
}
T[1142] = {
  title = "La Vita si Spegne",
  desc = "Non mi resta molto da vivere... così... così... debole.$B$B...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvertire Falfindel...$B$BMa prima che io... m-m-muoia...$B$B...mia moglie, Treshala... il ciondolo che la lega a me... rubato... da uno degli i-i-immondi aggressori...$B$BTrovalo, p-p-per favore... e riportalo a Treshala, a Darnassus...$B$B...insieme alla n-n-notizia della mia solitaria... morte.",
  obj = "Trova Treshala's Pendant e riportalo a Treshala Fallowbrook, a Darnassus.",
  progress = "Cosa ti porta a casa mia, $R?",
  reward = "No!$B$BNon è giusto. Oh, mondo crudele e intollerabile!$B$BOra devo portare questo fardello di dolore e non lasciare che l'opera di Heralath muoia con lui.$B$BHai avuto coraggio a venire da un luogo così pericoloso, $N. Ma ora, ti prego, lasciami.$B$BIn solitudine piangerò.",
  en_title = "Mortality Wanes",
  en_obj = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",
}
T[1143] = {
  title = "La Torre di Althalaxx",
  desc = "Capisco. Be', se quello che dici è vero, allora è il momento di colpire. Credo che Athrikus stia in cima alla torre. Però sta' $Gattento:attenta;, perché è circondato da molti stregoni potenti, ben più letali di quelli che hai affrontato finora.",
  obj = "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike, vicino alla Torre di Althalaxx.",
  progress = "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma è evidente che aveva molta fiducia in te, per mandarti $Gda solo:da sola;.",
  reward = "Con la morte di Athrikus spero che le forze demoniache di questa zona vengano respinte. Non ho dubbi che si riorganizzeranno e torneranno, ma allora saremo ancora più pronti ad affrontare la loro minaccia.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1144] = {
  title = "Willix l'Importatore",
  desc = "Finalmente sono arrivati i soccorsi!$B$BNon hai idea di quanto tempo mi abbiano tenuto prigioniero qui. Non ricordo più l'ultima volta che ho visto il mondo là fuori.$B$BVedi, io sono un imprenditore. Sempre a caccia di un soldo, come si dice. Ho sentito dire che Mebok Mizzyrix pagava bene il Tubero Redleaf di questo porcile. Pensavo che sarebbe stato un lavoretto facile, un entra ed esci. Come vedi, mi sbagliavo un pochino!$B$BComunque, se sei così gentile da aiutarmi a uscire di qui, ti ripagherò come si deve.",
  obj = "Scorta Willix the Importer fuori dal Razorfen Kraul.",
  reward = "Grazie ancora, $Gamico:amica;! Te l'avevo detto che ti avrei ripagato come si deve.",
  en_title = "Willix the Importer",
  en_obj = "Escort Willix the Importer out of Razorfen Kraul.",
}
T[1145] = {
  title = "Lo Sciame Cresce",
  desc = "Molti viaggiatori passati dal Crossroads mi hanno aiutato a raccogliere uova nel Campo dei Giganti, e tanti di loro raccontano quanto sono letali quelle creature. Ne ho sentite abbastanza da considerare quelli insetti una minaccia molto più grossa di quanto pensavano all'inizio i miei padroni.$B$BMi serve un corriere che va a Orgrimmar a incontrare Belgrom Rockmaul. Non è mica una faccenda semplice, e ci deve andare uno che l'incarico lo prende sul serio.$B$BBelgrom di solito lo trovi fuori dalla casa della gilda dei guerrieri.",
  obj = "Consegna Korran's Sealed Note a Belgrom Rockmaul, a Orgrimmar.",
  progress = "Ti invidio, $C. Hai l'aria di chi è stato fuori dalle mura di Orgrimmar per un po'.$B$BIo stesso viaggerei in nome del Capoguerra, se Thrall non avesse bisogno delle mie capacità qui in città. Ma ci guida bene, e mi fido del suo giudizio — resto qui finché ha bisogno di me.",
  reward = "Ah, un biglietto da Korran. È un servitore fedele ormai da tempo. Mi chiedevo come andassero i suoi incarichi al Crossroads.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.",
}
T[1146] = {
  title = "Lo Sciame Cresce",
  desc = "Quindi Korran è arrivato a una conclusione simile su questi insetti — sembrano una minaccia più grande di quanto pensassimo.$B$BQualche giorno fa, da Thousand Needles, è tornato da me un cacciatore quasi morto. Era con un gruppo d'assalto mandato a cacciare una squadra di scavo nanica dalle Shimmering Flats. Durante l'attacco altri di questi insetti sono sbucati da una grotta nel sito di scavo e hanno quasi ucciso il gruppo.$B$BLi guidava Moktar Krin, e si sono rifugiati ai confini delle Shimmering Flats. Portagli questo biglietto.",
  obj = "Consegna Belgrom's Sealed Note a Moktar Krin, a Thousand Needles.",
  progress = "È la guerra a portare me e il mio gruppo qui, nelle Shimmering Flats, $C. E tu, cosa ti porta da queste parti?",
  reward = "Non badare all'eco tonante che rimbomba sulle pareti delle montagne. I goblin e gli gnomi sono là nelle Flats a correre l'uno contro l'altro su certe atrocità create da quella che chiamano scienza. Qui a Thousand Needles ci sono minacce più grosse, e una di queste ha ucciso più di metà dei miei guerrieri.$B$BMa restiamo qui finché non avremo notizie da Belgrom, a Orgrimmar. Fino ad allora teniamo la posizione e restiamo vigili.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.",
}
T[1147] = {
  title = "Lo Sciame Cresce",
  desc = "Hmm. Pare che Belgrom consideri quei mostri una minaccia. Vuole che vengano ricacciati nelle profondità da cui sono strisciati fuori.$B$BImmagino che uccidere i nani mandati dalla Lega degli Esploratori non sia bastato — adesso devo mandare in un'altra battaglia un manipolo di guerrieri mezzo morto. Non possiamo farcela da soli, non nelle condizioni in cui siamo. Il sito di scavo è a sud di qui. Non dovrebbero esserci altri nani di cui occuparsi. Te la senti di impugnare una lama o un bastone e di fare la tua parte per aiutarci?",
  obj = "Uccidi 5 Silithid Searcher, 5 Silithid Hive Drone e 5 Silithid Invader, poi torna da Moktar Krin, a Thousand Needles.",
  progress = "Con tutti i viaggiatori che vanno alle Flats per quelle corse, sono sicuro che riusciremo a convincere abbastanza cercatori d'avventura ad aiutarci a ricacciare indietro quegli insetti. Io e la mia banda non potremo muoverci finché non sarà fatto.",
  reward = "Ah! Quell'icore di cui sei $Gcoperto:coperta; ti rende perfino più $Gcarino:carina;, $N! Anche se allo stesso tempo ti fa puzzare da morire. Non stare troppo vicino ai kodo: o scateni una fuga in massa o li mandi in calore.$B$BCredo che i miei compagni saranno d'accordo: già solo il tuo odore è la prova che hai fatto la tua parte per aiutarci contro quelle creature insettoidi. Grazie, $N.",
  en_title = "The Swarm Grows",
  en_obj = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.",
}
T[1148] = {
  title = "Parti dello Sciame",
  desc = "Esamini con attenzione il carapace. Rigirandolo tra le mani ti accorgi che le placche chitinose si intrecciano in modo da renderlo incredibilmente resistente. Non somiglia a niente che tu abbia mai visto. Esamini meglio il resto del cadavere e capisci che queste creature sono molto potenti e molto evolute.$B$BGuardando di nuovo il carapace, pensi che a Korran piacerebbe studiare altre creature come questa. Potrebbe aiutarlo a capire cosa sono e da dove vengono.",
  obj = "Porta 1 Silithid Heart, 5 Silithid Talon e 3 Intact Silithid Carapace a Korran, al Crossroads.",
  progress = "Ah, tanto tempo che non vieni a trovarmi, $N. Cosa posso fare per te oggi? Tu c'hai l'aria di $Guno:una; che ha visto in faccia la battaglia da poco. Bene... bene per l'Orda e bene per te. Più battaglie hai visto, più sarai utile; e anche più forte.",
  reward = "Ahh, hai visto Moktar da poco? Lui mi guarda sempre le spalle. Mi dispiace sentire che passa il tempo a sorvegliare il suo piccolo manipolo di guerrieri invece di andare in battaglia, ma sono sicuro che lui se la gode un mondo ad ammazzare i membri della Lega degli Esploratori.$B$BTu sei $Gstato furbo:stata furba; a portarmi 'sti campioni, $N. Insieme alle uova che noi troviamo nel Campo dei Giganti, dovrebbero darmi un buon inizio per capire cosa sono 'sti insetti e cosa loro vogliono.",
  en_title = "Parts of the Swarm",
  en_obj = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.",
}
T[1149] = {
  title = "Prova di Fede",
  desc = "Allora, mi hai cercato, o forse è il destino a portarti da me? Non importa. Ora sei qui, e il tuo viaggio avrà un nuovo inizio.$B$BUn essere è fatto di molte sfaccettature: lo spirito, il corpo, la mente. Alcune si possono misurare con le tradizioni di un popolo. Di altre possiamo solo sperare che esistano dentro di noi. Se sei d'accordo, metterò alla prova alcune delle sfaccettature che hai dentro.$B$BSe passerai le prove, diventerai più forte. Se fallirai, ti renderai conto della vastità del Nether.$B$BLa prima è una Prova di Fede.",
  obj = "Se hai fede, salta dalle assi che si affacciano su Thousand Needles.",
  progress = "La fede. È molto più importante di quanto alcuni credano.$B$BA volte non conta in cosa credi. Conta soltanto che tu creda in qualcosa.",
  reward = "È solo davanti a un'avversità imprevista che cominciamo a vedere quanto è forte il nostro spirito. Hai fatto il salto della fede pur non avendo alcuna garanzia di sopravvivere. La tua mente è aperta e il tuo spirito è pronto per quel che verrà.$B$BSe te la senti, la prossima prova è pronta.",
  en_title = "Test of Faith",
  en_obj = "If you have faith, leap from the planks overlooking Thousand Needles.",
}
T[1150] = {
  title = "Prova di Resistenza",
  desc = "Mi fa piacere vedere che il tuo coraggio resta saldo dopo quel che hai già fatto. Dato che la tua fede è intatta, è arrivato il momento di mettere alla prova il tuo corpo.$B$BPer prima cosa una prova di resistenza. Va' con degli amici all'Antro di Roguefeather, a ovest del Presidio di Freewind. Arriva fino in fondo alla loro tana e distruggi le loro provviste. A quel punto dovresti averne scatenato la furia, e se riuscirai a sopravvivere abbastanza a lungo verrà a prenderti Grenka Bloodscreech in persona — uccidila e portami il suo artiglio per completare la prova.",
  obj = "Porta Grenka's Claw a Dorn Plainstalker, a Thousand Needles.",
  progress = "Devi essere $Gpronto:pronta; nello spirito, nel corpo e nella mente per le sfide che ti aspettano.$B$BTroppo spesso ci buttiamo avanti prima di essere pronti. Considero un mio dovere verso i giovani, a qualunque tribù appartengano, prepararli ai pericoli che potranno incontrare una volta lasciata la sicurezza di casa.",
  reward = "Grenka era potente, perfino per $Gun:una; $R come te. Dovresti essere $Gfiero:fiera; di quel che hai compiuto oggi.$B$BNella prova di fede hai mostrato forza di spirito, e ora hai mostrato resistenza in battaglia affrontando le arpie Roguefeather, ma è arrivato il momento di una nuova prova.",
  en_title = "Test of Endurance",
  en_obj = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.",
}
T[1151] = {
  title = "Prova di Forza",
  desc = "Al tempo degli Dei Antichi gli elementali abitavano gran parte di questo mondo. Veneravano gli Dei Antichi, e gli Dei, con il loro potere, tenevano gli elementali legati a questo mondo. Quando gli Dei Antichi furono banditi, gli elementali svanirono dal nostro mondo e ora tornano solo al comando di maghi potenti.$B$BCi sono però delle eccezioni. Alcuni elementali erano abbastanza potenti da restare qui da soli. Uno di questi è Rok'Alim.$B$BPer mettere alla prova la tua forza, trova Rok'Alim a Thousand Needles e uccidilo.",
  obj = "Porta Fragments of Rok'Alim a Dorn Plainstalker, a Thousand Needles.",
  progress = "Le tribù dei centauri di Thousand Needles chiamano Rok'Alim anche il Martellatore, per il tuono dei suoi pugni quando si abbattono sulle creature abbastanza coraggiose, o stupide, da mettersi sulla sua strada.",
  reward = "La Prova di Forza è compiuta. Hai mostrato forza e coraggio, e ora sei $Gpronto:pronta; per l'ultima prova prima che questi riti siano completati.",
  en_title = "Test of Strength",
  en_obj = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.",
}
T[1152] = {
  title = "Prova di Sapienza",
  desc = "Il tuo tempo con me sta per finire. So molte cose, ma non sta a me farti affrontare la Prova di Sapienza. Ci sono lezioni da imparare e luoghi da visitare su cui altri rivendicano il proprio dominio.$B$BSe sei $Gpronto:pronta;, cerca Braug Dimspirit — è uno sciamano di grande saggezza. Ti metterà ancora alla prova, quindi ascolta bene le sue parole, $N.$B$BQuando sei $Gpronto:pronta;, trova il tunnel che collega le Stonetalon Mountains con Ashenvale: Braug abita lì vicino. E sta' $Gattento:attenta;, $N, gli elfi della notte potrebbero voler ostacolare la tua prova.",
  obj = "Trova Braug Dimspirit vicino all'ingresso del Sentiero di Talondeep, nelle Stonetalon Mountains.",
  reward = "I giorni e le notti si fanno più freddi in tutto il mondo mentre i goblin violentano la terra e gli elfi della notte puntano il dito contro le razze più giovani. I Reietti e gli orchi non sono i soli responsabili delle sofferenze che affliggono Kalimdor e Lordaeron. Molte delle razze intelligenti hanno contribuito al dolore del mondo. Dorn lo sa, e ti ha mandato da me perché hai mostrato le qualità necessarie per capirlo anche tu.$B$BOra sei davanti a Braug.",
  en_title = "Test of Lore",
  en_obj = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1153] = {
  title = "Un Nuovo Campione di Minerale",
  desc = "$C, in passato mi hai dato un valido aiuto. Il capoguerra finora è soddisfatto di quello che ho ottenuto, e mi chiede di continuare con rinnovata determinazione. Il mio onore mi impone di darti il giusto riconoscimento davanti al capoguerra per tutto quello che hai fatto, ma prima vorrei chiederti ancora aiuto.$B$BDi recente sono arrivati dei viaggiatori da sud, da un posto chiamato Thousand Needles. Là hanno ucciso un coboldo che aveva un campione di minerale insolito, ma non hanno voluto venderlo. Voglio un campione di quel minerale da esaminare.",
  obj = "Trova un Unrefined Ore Sample su un Gravelsnout Digger o Gravelsnout Surveyor e portalo a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.",
  progress = "Ho rivisto quei viaggiatori — quelli che non volevano vendermi un campione del minerale. Gli ho sputato addosso, perché non hanno aiutato il capoguerra.$B$BChe muoiano in battaglia come codardi e non come guerrieri, come dovrebbe essere diritto di chiunque si allei con l'Orda.",
  reward = "Un buon campione, $N. Davvero un buon campione.$B$BQuei viaggiatori non possono più vantarsi con me del minerale che hanno trovato, ora che tu ci sei $Griuscito:riuscita;.$B$BMi metterò al lavoro subito. Se si rivelerà abbastanza resistente, manderò al capoguerra un'arma forgiata con questo materiale, per mostrargli il nostro successo.$B$BNon dimenticherò il tuo aiuto, $C.",
  en_title = "A New Ore Sample",
  en_obj = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[1154] = {
  title = "Prova di Sapienza",
  desc = "Hai superato le prove di Dorn e ora cerchi di superare la prossima. Molto bene. Ma finora le tue sfide sono state roba da bambini. È facile mettere alla prova il tuo corpo — la tua mente è tutta un'altra faccenda.$B$BTe lo spiego in parole semplici: trova il libro che ti dirò, studialo e rispondi alla mia domanda sul suo contenuto.$B$BQuale libro, ti starai chiedendo? L'Eredità degli Aspetti. Si trova in fondo a Dor'danil, nell'Ashenvale meridionale, protetto dai druidi morti e dai loro carnefici.",
  obj = "Trova la Legacy of the Aspects e portala a Braug Dimspirit, vicino all'ingresso del Sentiero di Talondeep, nelle Stonetalon Mountains.",
  progress = "Portami il libro dopo che l'avrai studiato. Non ti farò la domanda finché non me lo avrai consegnato.",
  reward = "Questo è il libro che ti avevo detto. Allora c'è speranza che tu risponda bene alla mia domanda... a meno che tu non ti sia $Gdimenticato:dimenticata; di studiarne il contenuto.$B$BQuando sei $Gpronto:pronta;, parlami di nuovo e ti farò una domanda.",
  en_title = "Test of Lore",
  en_obj = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1159] = {
  title = "Prova di Sapienza",
  desc = "Ben fatto, $N. Hai superato la prima parte della Prova di Sapienza, ma c'è ancora una domanda a cui rispondere. E non tocca a me farla.$B$BCerca Parqual Fintallas, a Lordaeron City. Era un grande storico degli umani, prima che la Piaga lo cogliesse. Ora continua a cercare l'illuminazione, ma di tutt'altra natura.$B$BTi chiederà qualcos'altro prima di farti la domanda, ma finora te la sei cavata da maestro — sono sicuro che supererai anche il suo ostacolo.",
  obj = "Trova Parqual Fintallas, nell'Undercity.",
  reward = "Ti manda Braug? Impossibile.$B$B<Parqual ti squadra da capo a piedi.>$B$BHai affrontato Dor'Danil, hai fatto il salto della fede, hai combattuto e sopraffatto un elementale potente? Bah! Probabilmente sei una farsa; $Gun avventuriero qualsiasi:un'avventuriera qualsiasi; che ha sentito due chiacchiere in taverna. E adesso credi di avere le carte in regola per superare la mia prova. E sia... $C.",
  en_title = "Test of Lore",
  en_obj = "Find Parqual Fintallas in Undercity.",
}
T[1160] = {
  title = "Prova di Sapienza",
  desc = "Ti dirò che cosa devi cercare, e ti farò perfino la mia domanda, ma non perché tu voglia dimostrare il tuo valore. La conoscenza è molto più importante della forza. Anche se altri sembrano superarti in abilità, la tua conoscenza del mondo varrà di più.$B$BVa' al Monastery, nel nord delle Tirisfal Glades. Nella sua biblioteca si trova un libro intitolato Origini della Minaccia dei Non Morti. I paladini di quel luogo, ora corrotti, lo usavano per addestrarsi a combattere quelli come me.$B$BPortamelo.",
  obj = "Trova Beginnings of the Undead Threat e riportalo a Parqual Fintallas, nell'Undercity.",
  progress = "Spero che tu abbia fatto soffrire un po' la Crociata Scarlatta prima di rubarle il libro.$B$BLe mie opinioni su quella gente non sono infondate. Un tempo la Crociata avrà anche seguito la Luce, ma ora cerca di distruggere qualunque creatura non si sia schierata con la sua religione. Crede che tutti i non morti, Reietti o no, vadano purificati, e che chi viaggia nelle sue terre sia pazzo o soggiogato dalla potente magia dei non morti. Idioti. Idioti e stolti, tutti quanti.",
  reward = "Questo è il libro che ti ho mandato a cercare.$B$B<Parqual passa lentamente la mano sulla copertina del libro, fissandolo.>$B$BE ora vuoi una domanda per dimostrare che la tua mente è potente quanto il tuo corpo e il tuo spirito. Se hai studiato il libro abbastanza a lungo, ti farò la tua domanda e avrai chiuso con queste prove!",
  en_title = "Test of Lore",
  en_obj = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.",
}
T[1164] = {
  title = "Rubare ai Ladri",
  desc = "Quella sgualdrina! Quella scrofa! Kenata è ancora viva; la sua famiglia è sana e prospera mentre io soffro. Reietti, davvero!$B$BLa mia famiglia non c'è più, portata via dalla piaga. Anche la nostra tenuta è andata perduta, saccheggiata e bruciata durante la guerra. E dopo tutto questo, lei e i suoi figli pidocchiosi hanno avuto la sfacciataggine di rubare gli unici beni preziosi che mi erano rimasti.$B$BNon m'importa più delle cose che hanno rubato. Ora voglio le loro teste!$B$BUccidili per me! Va' alla Fattoria dei Dabyrie, in Arathi, a nord-est di Refuge Point.",
  obj = "Porta Kenata's Head, Fardel's Head e Marcel's Head dei Dabyrie a Genavie Callow, nell'Undercity.",
  progress = "Uccidili tutti e portami le loro teste!",
  reward = "Sei davanti a me come l'immagine stessa della vendetta, e mi inchino a te in segno di gratitudine.$B$BCon la morte di quella vacca, e sapendo che il loro seme non si spargerà più sulla faccia di Azeroth, posso dedicare le mie energie a qualcosa di più redditizio. Spero che tu abbia saccheggiato la loro fattoria dopo averli fatti fuori.",
  en_title = "To Steal From Thieves",
  en_obj = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",
}
T[1166] = {
  title = "La Preoccupazione del Signore Supremo Mok'Morokk",
  desc = "Inchinati davanti al Signore Supremo Mok'Morokk!$B$BRexxar fare me potente capo di Stonemaul Clan!$B$BIo buon capo. Io tenere clan al sicuro.$B$BGrossi draghi venire e dare fuoco a vecchia casa. Io ogre furbo. Trovare nuova casa per clan qui.$B$BLasciare vecchia casa così in fretta, io dimenticare roba. $GPiccolo:Piccola; $R, tu andare prendere mie cose. Andare a sud e trovare mio grog buonissimo, mio tabacco da fiuto e mia cassaforte. A me piacere tu dopo che tu fare questo. Tu guardare in Tana della Fiamma e Rovine di Stonemaul... loro essere lì, io sicuro!",
  obj = "Overlord Mok'Morokk, a Brackenwall Village, vuole che tu recuperi il suo grog, il suo tabacco da fiuto e la sua cassaforte nel Dustwallow Swamp.",
  progress = "Io avere sete di grog. A me mancare anche tabacco da fiuto. Dove essere cassaforte? Tu andare prendere per Signore Supremo Mok'Morokk.$B$BAndare cercare a sud in vecchia casa. Io troppo occupato a guidare ogre per andare prendere.",
  reward = "Tu essere $Gun bravo:una brava; $R. A me mancare tanto mie cose. A me piacere tu adesso.",
  en_title = "Overlord Mok'Morokk's Concern",
  en_obj = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.",
}
T[1167] = {
  title = "La Torre di Althalaxx",
  desc = "Prima di affrontare Athrikus, faresti forse bene a consultarti con Balthule. Non ho dubbi che abbia vegliato con attenzione sulla Torre, e potrebbe avere notizie sugli ultimi sviluppi.",
  obj = "Parla con Balthule Shadowstrike, vicino alla Torre di Althalaxx.",
  reward = "Ah, che piacere rivederti, $N! Qui intorno stanno succedendo cose stranissime, sono contento che tu sia $Garrivato:arrivata;!$B$BÈ stato stranissimo, $N. Sembrava tutto normale — be', normale per quanto lo siano le cose da queste parti — e poi all'improvviso dalla stanza in cima alla torre è partito un lampo accecante. Poi sono arrivate le urla. Le grida squarciavano l'aria, e ogni tanto un fulmine colpiva il terreno. Che sta succedendo?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1168] = {
  title = "L'Esercito del Drago Nero",
  desc = "Mok'Morokk è stato fatto Signore Supremo da Rexxar. Lui tenere più a potere che a ogre.$B$BDraghi neri uccidere molti ogre. Uccidere moglie di Tharg. Mok'Morokk dire a noi di scappare. Fare noi venire qui.$B$BOgre dovere combattere. Ogre non bravi a scappare. A Mok'Morokk importare solo di Mok'Morokk.$B$BIo chiamare casa Rovine di Stonemaul. A me piacere stare a sud. Questo posto non casa.$B$BAiutare ogre combattere esercito di drago nero. Io volere vendetta. Io volere tornare a casa.",
  obj = "Tharg, a Brackenwall Village, vuole che tu uccida 15 Firemane Scout, 10 Firemane Ash Tail e 5 Firemane Scalebane.",
  progress = "Mok'Morokk dire a tutti ogre di restare e tenere al sicuro questo posto. Io pensare ogre dovere uccidere esercito di drago nero e riprendere vecchia casa.$B$BTu aiutare ogre riprendere casa. Aiutare ogre avere vendetta.",
  reward = "Tu uccidere molti di esercito di drago nero. Tu $Gun:una; $R $Gcoraggioso:coraggiosa;.$B$BTu fare Tharg contento.",
  en_title = "Army of the Black Dragon",
  en_obj = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.",
}
T[1169] = {
  title = "Identificare la Covata",
  desc = "Mentre quel vile sciocco di Mok'Morokk si crogiola nel potere, e Tharg lotta con i demoni del dolore e della vendetta e si contende la guida del clan, sembra che io sia l'unico a preoccuparsi di scoprire l'origine dell'aggressione alla nostra vecchia casa.$B$BPerché quello sguardo perplesso, $N? Ti aspettavi che parlassi come un rozzo attaccabrighe solo perché sono un ogre?$B$BMa ora torniamo a noi: portami i cuori e le lingue dei cuccioli e dei piccoli appena nati. Risalirò alla radice di questo male...",
  obj = "Draz'Zilb, a Brackenwall Village, vuole che tu gli porti 15 Searing Tongue e 15 Searing Heart.",
  progress = "Con i cuori e le lingue della progenie bruciata dell'esercito del drago nero, potrò decifrare quale bestia immonda abbia portato la sua prole nella nostra casa. Forse, conoscendo meglio i nostri aggressori, potremo cercare di distruggerli una volta per tutte e strappare Stonemaul Village alla rovina.$B$BNaturalmente, convincere Mok'Morokk a spostare la sua pigra mole di grasso fuori da questo buco fangoso sarà già di per sé un'impresa epica...",
  reward = "È stata di certo un'impresa pericolosa raccogliere tutti questi cuori e queste lingue. Mi addentrerò nelle profondità dell'arcano per risalire all'origine della minaccia nera che si è abbattuta sulla nostra vecchia casa.",
  en_title = "Identifying the Brood",
  en_obj = "Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts.",
}
T[1170] = {
  title = "La Covata di Onyxia",
  desc = "Stonemaul Village è stato invaso dalla covata di Onyxia. Ma perché la figlia del signore dei draghi neri, Deathwing, dovrebbe calare sulle nostre terre?$B$BÈ molto preoccupante. Di certo Onyxia è stata spinta fin qui da uno scopo che va oltre l'assedio di una piccola banda di ogre.$B$BAvverti subito Mok'Morokk! Bisogna agire.",
  obj = "Parla con Overlord Mok'Morokk, a Brackenwall Village.",
  reward = "Perché tu dire a me di draghi? A me non piacere draghi. A me piacere qui. Qui niente draghi.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Overlord Mok'Morokk in Brackenwall Village.",
}
T[1171] = {
  title = "La Covata di Onyxia",
  desc = "Tu lasciare me in pace adesso. Andare dire a Draz'Zilb che noi restare qui. Qui niente drago nero.",
  obj = "Parla con Draz'Zilb, a Brackenwall Village.",
  reward = "Quel pigro codardo!$B$BMok'Morokk mostrava forza quando Rexxar era il nostro capo. Ma poco dopo la partenza di Rexxar, Mok'Morokk è caduto preda delle tentazioni del potere. Invece di guidare, pretendeva. Non serve la sua gente: si aspetta piuttosto che siamo noi a servire lui.$B$BBisogna fare qualcosa.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Draz'Zilb in Brackenwall Village.",
}
T[1172] = {
  title = "La Covata di Onyxia",
  desc = "La covata di Onyxia è stata sparsa per tutto il Dragonmurk. È indispensabile che non si permetta ad altri cuccioli di uscire dall'uovo.$B$BSbrigati a raggiungere il Wyrmbog, nel sud del Dustwallow Marsh. Di certo è lì che ha fatto la sua tana. Trova le uova del drago malvagio e distruggile.$B$BNon riconquisteremo mai Stonemaul Village se i dintorni restano una zona di nidificazione.$B$BQuanto a Mok'Morokk... ho altri piani per quell'idiota.",
  obj = "Draz'Zilb, a Brackenwall Village, vuole che tu distrugga 5 Egg of Onyxia.",
  progress = "Devi correre al Dragonmurk, $N. Con le uova di Onyxia sparse per tutto il Wyrmbog, ci troveremo davanti a un numero schiacciante di nemici, se non si fa qualcosa in fretta.$B$BDistruggi le sue uova! Non lasciare che la piaga del drago nero si diffonda nella nostra terra!",
  reward = "Splendido! Passerà del tempo prima che Onyxia possa produrre altre uova.$B$BA nome della mia gente, ti ringrazio, $N.$B$BFinora ti ho chiesto molto. Forse puoi rendere un ultimo servizio allo Stonemaul Clan.$B$BMok'Morokk non è adatto a guidarci. Tharg sarebbe un capo eccellente, ma è frenato dalle ferite e dall'età. Caccia Mok'Morokk da questo posto con la forza. Solo allora potremo nominare un nuovo capo che ci riporti alla nostra vera casa, a sud.",
  en_title = "The Brood of Onyxia",
  en_obj = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.",
}
T[1173] = {
  title = "Sfida il Signore Supremo Mok'Morokk",
  desc = "Tu osare sfidare Signore Supremo Mok'Morokk?$B$BAh ah!$B$BIo schiacciare $Gpiccolo:piccola; $R!$B$BTu dire a me quando $Gpronto:pronta; per bella batosta.",
  obj = "Sconfiggi Mok'Morokk e riferisci la notizia a Draz'Zilb, a Brackenwall Village.",
  progress = "Credevo che avresti tentato di cacciare Mok'Morokk dal villaggio. E invece sei $Gvenuto:venuta; da me a fare due chiacchiere?",
  reward = "Quel vile ammasso di grasso di Mok'Morokk è fuggito come un bambino spaventato. Hai reso un grande servizio, $N.$B$BOra la mia gente potrà nominare un nuovo capo, uno che ci aiuti a riconquistare una volta per tutte la nostra vecchia casa.",
  en_title = "Challenge Overlord Mok'Morokk",
  en_obj = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.",
}
T[1175] = {
  title = "Un Ostacolo sulla Strada",
  desc = "Dopo il grande schianto tra il Red Thunder dei goblin e un basilisco, Kronkrider mi ha assunto per occuparmi della pista. Non so cosa mangino tutti gli animali qui nelle saline per diventare così grossi, ma dobbiamo stare attenti a diradarli, così non finiscono in pista durante una corsa.$B$BFacciamo così. Se vuoi guadagnarti qualcosa, va' là fuori e togli di mezzo i basilischi della zona.",
  obj = "Uccidi 10 Saltstone Basilisk, 10 Saltstone Crystalhide e 6 Saltstone Gazer per Trackmaster Zherin, nelle Shimmering Flats.",
  progress = "Già è brutto dover ripulire i rottami delle vetture, figurarsi doverli staccare da pezzi di animale bruciacchiati.",
  reward = "Spero che tu non abbia ucciso nessuno dei basilischi proprio sulla pista! Le carcasse ci mettono un sacco a decomporsi al sole, e preferirei non dover tirare fuori la pala per ripulire.",
  en_title = "A Bump in the Road",
  en_obj = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.",
}
T[1176] = {
  title = "Alleggerire il Carico",
  desc = "Quando si corre, ogni minima cosa conta! Che sia una piccola regolazione della potenza, un leggero allentamento delle molle o l'alleggerimento del telaio, devi tenere conto di tutto.$B$BPer molte delle piccole modifiche strutturali alle nostre vetture usiamo ossa di avvoltoio: hanno l'equilibrio perfetto tra robustezza e peso. E per di più è facile procurarcene altre, perché le saline sono piene di avvoltoi.$B$BPortamene un po' e te le pagherò bene.",
  obj = "Procura 10 Hollow Vulture Bone a Pozzik, nelle Shimmering Flats.",
  progress = "Ce le hai quelle ossa per me? Stavo giusto per mettermi ad alleggerire il gruppo dello sterzo, ma non voglio aprirla senza avere tutti i pezzi che mi servono.",
  reward = "Ottimo! Posso mettere subito la squadra al lavoro. Grazie, $N!",
  en_title = "Load Lightening",
  en_obj = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.",
}
T[1177] = {
  title = "Fame!",
  desc = "Mud grosso ogre.$B$BIo avere fame.$B$BTu andare picchiare pesciolini. Portare cibo a Mud.$B$BTu dare da mangiare a Mud o Mud mangiare te.",
  obj = "Mudcrush Durtfeet, nel Dustwallow settentrionale, vuole 12 Mirefin Head.",
  progress = "Dare cibo a me o io mangiare te.",
  reward = "A me piacere testa di pesciolino!$B$BIo non mangiare te adesso.",
  en_title = "Hungry!",
  en_obj = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.",
}
T[1178] = {
  title = "Gli Sponsor Goblin",
  desc = "La nostra squadra da corsa è l'orgoglio dei goblin di tutto il mondo. Ti sorprenderebbe sapere quanta gente contribuisce in un modo o nell'altro alla squadra.$B$BConosci Gazlowe? Ci trova pezzi in giro per il mondo. Una volta è perfino venuto qui a lavorare su una delle nostre vetture!$B$BQualche settimana fa ha detto che ci avrebbe mandato un nuovo prototipo di regolatore del carburante, ma non è ancora arrivato. Di solito è puntualissimo... Ti dispiacerebbe andare a Ratchet a chiedergli com'è la faccenda? Non vorrei insistere, ma gli gnomi ci stanno raggiungendo!",
  obj = "Parla con Gazlowe, a Ratchet.",
  reward = "Ti manda Pozzik, eh? Sai, Pozzik era uno degli inventori più rispettati di Undermine prima di ritirarsi per mettersi a lavorare sulle vetture da corsa.$B$BLa prima cosa che ha fatto quando è entrato nella squadra è stata sviluppare le vetture a due motori. Può darsi che gli affari ne risentano, senza di lui alla Tinkers' Union, ma chi se ne importa, no? Non c'è niente di meglio delle corse!",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak to Gazlowe in Ratchet.",
}
T[1179] = {
  title = "I Fratelli Brassbolts",
  desc = "Hai mai sentito parlare delle Shimmering Flats? È una distesa di saline laggiù a Kalimdor, appena a sud del canyon di Thousand Needles. È un posto perfetto per le corse perché, be', è tutto piatto!$B$BCi sono due fratelli gnomi laggiù, amici miei, che stanno provando la loro nuova auto a razzo, e da quel che ho sentito è veloce! Eh, così veloce che i loro piloti continuano a schiantarsi. E a prendersi delle belle botte in testa.$B$BCosì mi hanno chiesto qualche elmo da Macchina d'Assedio, ma io qui ho i miei doveri. Non posso fare il viaggio!$B$BTu puoi?",
  obj = "Porta la Crate of Crash Helmets a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Occhio a dove metti i piedi! Occhio occhio occhio!! Qui c'è roba delicata, e se vogliamo vincere deve funzionare tutto alla perfezione!",
  reward = "Ah! Ti manda Longbeard con un carico di elmi! Evviva!$B$BAdesso forse riusciamo a convincere un pilota a guidare la nostra auto...",
  en_title = "The Brassbolts Brothers",
  en_obj = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1180] = {
  title = "Gli Sponsor Goblin",
  desc = "Torniamo al motivo per cui sei qui. Lo so che avevo promesso a Pozzik di consegnargli un nuovo regolatore del carburante, ma non l'ho ancora ricevuto. Revilgaz, laggiù a Booty Bay, aveva detto che me l'avrebbe fatto spedire, ma può darsi che in qualche modo sia finito nel dimenticatoio.$B$BSe è così, non possiamo farci molto. Almeno possiamo scoprire se è mai partito da Booty Bay.$B$BSenti il Capoporto Lozgil, laggiù: dovrebbe poter controllare i registri del carico.",
  obj = "Parla con Wharfmaster Lozgil, a Booty Bay.",
  reward = "Spedizioni per Ratchet? Fammi controllare i registri...$B$BNo, l'ultima spedizione per Ratchet che mi risulta era un carico di stivali di Drizzlik. Non c'è stato molto altro, a parte materiali da costruzione e attrezzi. Di sicuro nessun pezzo da corsa.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Wharfmaster Lozgil in Booty Bay.",
}
T[1181] = {
  title = "Gli Sponsor Goblin",
  desc = "Temo di non poterti aiutare più di così, $N. Se vuoi approfondire, ti consiglio di andare dritto dal Barone in persona. Se c'è qualcuno che conosce gli affari di Revilgaz, è Revilgaz.$B$BLo trovi alla taverna dall'altra parte del porto, all'ultimo piano.",
  obj = "Parla con Baron Revilgaz, a Booty Bay.",
  reward = "Oh, certo che so di cosa parli. Però no, non posso aiutarti. Alcuni dei miei uomini dovevano andare a recuperare i progetti del regolatore del carburante, ma sono tornati a mani vuote.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[1182] = {
  title = "Gli Sponsor Goblin",
  desc = "Vedi, i segatronchi della Venture Company là al Lago Nazferiti (nella Stranglethorn settentrionale) sono stati dotati di un regolatore del carburante di nuovo modello. Pensavo che Pozzik potesse sfruttarlo, se solo avesse qualche dettaglio. Purtroppo Cozzle, il caposquadra laggiù, sembra un po' più furbo di quanto credessi.$B$BTu però potresti avere più fortuna nel trovare i progetti. So che li tiene in casa sua, ma quasi di sicuro sono sotto chiave.",
  obj = "Porta i Fuel Regulator Blueprints a Baron Revilgaz, a Booty Bay.",
  progress = "Per quanto mi costi ammetterlo, quella squadra di gnomi laggiù è piuttosto brava. I nostri ragazzi hanno bisogno di ogni vantaggio possibile.",
  reward = "Allora, mi faccio una copia di questi progetti per i miei appunti e poi puoi portarli dritti a Pozzik. Non vorrei che pensasse che uno dei suoi sponsor lo sta abbandonando.",
  en_title = "Goblin Sponsorship",
  en_obj = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.",
}
T[1183] = {
  title = "Gli Sponsor Goblin",
  desc = "Dovresti essere a posto. Saluta Pozzik da parte mia e digli che se gli serve qualcosa non esiti a chiedere. Aspetto la notizia che presto batterà il record della pista!",
  obj = "Consegna i Fuel Regulator Blueprints a Pozzik, nelle Shimmering Flats.",
  progress = "$N! Sei $Griuscito:riuscita; a rintracciare il regolatore del carburante?",
  reward = "Speravo che fosse già assemblato, ma così ho l'occasione unica di migliorare il progetto da zero. Grazie, $N. Riuscirò a buttare giù qualche schema migliorato, a costruire l'aggeggio e a farlo installare molto presto.",
  en_title = "Goblin Sponsorship",
  en_obj = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.",
}
T[1184] = {
  title = "Parti dello Sciame",
  desc = "Torna da Belgrom, a Orgrimmar, e digli che Moktar lui esegue bene gli ordini suoi, là fuori a Thousand Needles. Digli pure che i studi miei vanno avanti, e che io spero di sapere più cose presto. Questo gli dovrebbe fare tanto piacere.",
  obj = "Torna da Belgrom Rockmaul, a Orgrimmar.",
  reward = "Apprezzo i tuoi sforzi, $C. Il capoguerra sarà contento di sentire con quanta tenacia hai svolto i tuoi doveri.$B$BOh, certo che gli farò il tuo nome. Mi parla spesso e tiene molto in conto le mie opinioni.$B$BOra va', ho molto da fare. E se parlerai presto con Korran e lui avrà notizie di queste creature, torna da me — credo che siano una minaccia da prendere sul serio.",
  en_title = "Parts of the Swarm",
  en_obj = "Return to Belgrom Rockmaul in Orgrimmar.",
}
T[1185] = {
  title = "Sotto la Chitina C'era...",
  reward = "Ehi, sei di nuovo tu! Cioè, voglio dire tu — nel senso del tu che è $N! Sì — quel tu!$B$BEhi, fammi ricominciare da capo!$B$BQuell'oggetto che hai trovato a Silithus — era davvero un libro. Era un diario scritto in un dialetto antichissimo di quella che oggi chiamiamo lingua darnassiana. Ci vorrà un po', ma lo esaminerò da cima a fondo. Ho pensato che dovessi sapere che quello che hai trovato è preziosissimo per il Circle.$B$BLa madre della tana è tutta emozionata e via dicendo!",
}
T[1186] = {
  title = "Il Diciottesimo Pilota",
  desc = "Io sarò impegnato a integrare questo nuovo regolatore del carburante nei progetti delle nostre vetture, ma se ti va di dare ancora una mano alla squadra, parla con Razzeric. È il nostro pilota — be', il nostro diciottesimo pilota, per l'esattezza — e gli piace aggiungere qualche modifica sua alle vetture.$B$BÈ un po' fuori di testa, però, quindi cerca di non sembrare troppo $Gsorpreso:sorpresa;.",
  obj = "Parla con Razzeric, nelle Shimmering Flats.",
  reward = "Sei tu $Gil:la; $R che sta dando una mano a Pozzik, vero? Una volta ero come te: correvo su e giù per i box, aiutando in qualunque lavoro i meccanici mi lasciassero fare.$B$BE adesso guardami! Il pilota fuoriclasse della squadra da corsa dei goblin!",
  en_title = "The Eighteenth Pilot",
  en_obj = "Speak with Razzeric on the Shimmering Flats.",
}
T[1187] = {
  title = "Le Modifiche di Razzeric",
  desc = "Pozzik è un grande meccanico, lo so, ma non ha il coraggio di caricarci sopra tutta la potenza e tenersi forte. Io invece sì.$B$BQuando Pozzik ha finito con una vettura, mi prendo un po' di tempo per aggiungerci le mie modifiche — sai, allentare i comandi, togliere pezzi di telaio e dargli più birra!$B$BHo ordinato un potenziatore al seaforium da Shreev, al Gizmorium di Gadgetzan, ma a quanto pare lo zeppelin su cui viaggiava si è schiantato nel Dustwallow Marsh! Devo averlo, $N!",
  obj = "Recupera il Seaforium Booster per Razzeric, nelle Shimmering Flats.",
  progress = "Come faccio a farmi vedere in pista senza una spintarella in più per partire? È uno scandalo, te lo dico io.",
  reward = "Ma guarda che bellezza! Quindici libbre di pura potenza al seaforium! Appena lo fisso sul fianco della mia vettura, girerò in pista così veloce che batterò gli gnomi due volte!",
  en_title = "Razzeric's Tweaking",
  en_obj = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.",
}
T[1188] = {
  title = "Prima la Sicurezza",
  desc = "Ma un momento, cos'è questo? Shreev ha lasciato inserita la sicura. Così la potenza che posso tirare fuori dal potenziatore sarà sempre limitata. Gli avevo detto che la volevo tolta! Così non va.$B$BDevi portarlo al Gadgetzan Gizmorium, nel Tanaris Desert, e far togliere la sicura a Shreev.",
  obj = "Porta il Seaforium Booster a Shreev, a Gadgetzan.",
  progress = "Come saprai di certo, il Gizmorium può soddisfare ogni tua esigenza di meccanica! Come posso aiutarti?",
  reward = "Solo Razzeric poteva guardare questo aggeggio e dire che ci avevo messo su chissà quale sicura. Questo potenziatore è quasi tutto esplosivo al seaforium. L'ho già modificato perché all'uso rilasci più carica, ma Razzeric non è mai contento finché non spinge tutto oltre il massimo!",
  en_title = "Safety First",
  en_obj = "Bring the Seaforium Booster to Shreev in Gadgetzan.",
}
T[1189] = {
  title = "Prima la Sicurezza",
  desc = "Ecco, ho fatto quel che voleva Razzeric. Digli solo di stare attento quando lo fa partire. Se sbaglia anche di poco, non andrà avanti, diventerà solo una chiazza di bruciato sulla pista.$B$BE sarebbe pure un peccato, se succedesse. Chi lo sa se il nostro diciannovesimo pilota varrebbe qualcosa?",
  obj = "Riporta il Modified Seaforium Booster a Razzeric, nelle Shimmering Flats.",
  progress = "Ci credi che Pozzik ha messo un secchio di sabbia sulla vettura? Come faccio a raggiungere la velocità massima con un secchio di sabbia sotto il sedile?",
  reward = "Ecco, così va meglio! Vorrei proprio vedere la faccia degli gnomi quando mi vedranno accendere questo gioiellino.$B$BPeccato che sarò troppo occupato a stabilire il nuovo record della pista!",
  en_title = "Safety First",
  en_obj = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.",
}
T[1190] = {
  title = "Stare al Passo",
  desc = "I fratelli Brassbolts hanno scoperto un nuovo materiale da costruzione, è l'unica spiegazione sensata. Le loro auto vanno più veloci di prima, ma i loro progetti, e tutti gli altri dati che abbiamo raccolto dalle loro corse, sono identici.$B$BDi sicuro sappiamo che Rizzle Brassbolts non ha fatto quasi altro che lavorare ai piani di questa nuova scoperta.$B$BZamek può creare un diversivo per te, così potrai rubargli quei piani.",
  obj = "Fa' creare un diversivo a Zamek, poi ruba i piani di Rizzle per Pozzik, nelle Shimmering Flats.",
  reward = "Un rotolo di appunti e di disegni scarabocchiati in tutta fretta, sulla raffinazione di una materia prima.",
  en_title = "Keeping Pace",
  en_obj = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.",
}
T[1191] = {
  title = "Il Diversivo di Zamek",
  reward = "Andiamo!",
  en_title = "Zamek's Distraction",
}
T[1192] = {
  title = "Minerale di Indurium",
  progress = "Vorrei usare l'indurium per diverse parti delle nostre vetture, ma per costruirle mi servono grandi quantità di indurium grezzo.$B$BIl minerale di indurium lo trovi nello scavo di Uldaman, nei Badlands, oltre il mare, a Khaz Modan.$B$BGli gnomi se ne stanno procurando una scorta tutta loro, quindi è importante che anche noi abbiamo la nostra, per stare al passo.",
  reward = "Eccellente! Metto subito la squadra al lavoro sui pezzi che ci serviranno per la prossima corsa.",
  en_title = "Indurium Ore",
}
T[1193] = {
  title = "Una Trappola Rotta",
  progress = "Davanti a te c'è una grossa trappola rotta. A quanto pare gli ogre hanno provato a ripararla, ma invano. Accanto alla trappola c'è un biglietto scritto in fretta che, stranamente, spiega con precisione cosa serve per ripararla: un meccanismo di torio e dell'olio del freddo. Se la trappola fosse riparata, un ogre che le passasse vicino potrebbe restarci intrappolato, e lo si potrebbe evitare.$B$BChiaramente, parrebbe una fortuna che pochissimi ogre sappiano leggere.$B$BChiaramente.",
  reward = "Il meccanismo di torio scivola al suo posto senza sforzo, formando un condotto in cui versare l'olio del freddo. Una volta versate le ultime gocce d'olio, la trappola scatta in posizione.$B$BGuai all'ogre incauto che dovesse trovarsi a passare di qui!",
}
T[1194] = {
  title = "Gli Schemi di Rizzle",
  desc = "Gli schemi di Rizzle descrivono il procedimento di raffinazione del minerale di indurium. Dai suoi scarabocchi si capisce che il minerale di indurium viene estratto dal sito di scavo nanico di Uldaman, nei Badlands.$B$BGran parte degli altri appunti riguarda le proprietà di resistenza al calore.$B$BCome fermacarte sui piani c'è un pezzo di quello che sembra minerale di indurium grezzo.",
  obj = "Porta il Sample of Indurium Ore a Pozzik, nelle Shimmering Flats.",
  reward = "Indurium? Interessante... Se resiste al calore quanto dici, spiegherebbe l'aumento di prestazioni che gli gnomi hanno mostrato ultimamente.$B$BAnche questo campione che mi hai portato sarà preziosissimo. Potrò fare qualche prova, ma perché ci sia davvero utile me ne servirà di più.",
  en_title = "Rizzle's Schematics",
  en_obj = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.",
}
T[1195] = {
  title = "La Fiamma Sacra",
  desc = "I centauri Galak, nelle Thousand Needles, custodiscono un manufatto che risale al tempo della creazione dei centauri.$B$BVorremmo recuperarlo, ma ci serve una fiala d'acqua presa da uno dei pozzi lunari degli elfi della notte.$B$BPer raccogliere l'acqua dovrai prima procurarti una delle fiale portate dalle driadi vicino al Rifugio di Raynewood, nel cuore dell'Ashenvale Forest. C'è un pozzo lunare vicino alla riva occidentale del Fiume Falfarren, a sud della strada principale, dove puoi riempire la fiala.",
  obj = "Riporta un Filled Etched Phial a Zangen Stonehoof, a Thunder Bluff.",
  progress = "Una volta che avremo la fiala piena, potremo mandarla al mio collega Rau, nelle Thousand Needles. È stato lui a chiedere la fiala d'acqua, quindi saprà meglio di noi come possiamo usarla.",
  reward = "Molto bene. Questa dovrebbe soddisfare in pieno la richiesta di Rau. Potresti consegnargliela? Forse ti farà piacere passare un po' di tempo nelle Needles.",
  en_title = "The Sacred Flame",
  en_obj = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.",
}
T[1196] = {
  title = "La Fiamma Sacra",
  desc = "Porta la fiala piena a Rau Cliffrunner, al Presidio di Freewind, nelle Thousand Needles sud-orientali. Puoi arrivare alle Thousand Needles prendendo il Grande Ascensore, al margine meridionale delle Barrens.$B$BNon mi stupirei se potessi aiutarci ancora.",
  obj = "Consegna il Filled Etched Phial a Rau Cliffrunner, al Presidio di Freewind.",
  progress = "Non sarai $Gstato mandato:stata mandata; da Zangen, eh?",
  reward = "Hm, sì, questa fiala d'acqua servirà perfettamente ai nostri scopi. Per via della discendenza comune delle driadi e dei centauri, l'acqua dei pozzi lunari ci permetterà di forzare la protezione della fiamma eterna che circonda la reliquia dei centauri.",
  en_title = "The Sacred Flame",
  en_obj = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.",
}
T[1197] = {
  title = "La Fiamma Sacra",
  desc = "Usando l'acqua che hai portato, potrai spegnere per un po' la fiamma che protegge la reliquia dei centauri. Non durerà per sempre, però, quindi dovrai fare in fretta.$B$BTroverai la Rupe di Splithoof, la roccaforte dei centauri, a nord di qui. La fiamma è custodita nel Covo di Splithoof, una parte della rupe molto ben sorvegliata.$B$BSta' $Gattento:attenta;, però: i centauri Galak qui sono in gran numero, e saranno piuttosto restii a cedere qualcosa a cui tengono tanto.",
  obj = "Recupera il Cloven Hoof per Rau Cliffrunner, al Presidio di Freewind.",
  progress = "Non vedo l'ora di mettere le mani sullo Zoccolo Fesso. L'hai già preso?",
  reward = "Sento una strana energia emanare dallo Zoccolo... Non ho dubbi che dal suo studio scopriremo informazioni nuove e sorprendenti sui centauri.$B$BTi ringrazio, $N. Ora devo cominciare a decifrare i misteri che mi hai portato.",
  en_title = "The Sacred Flame",
  en_obj = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",
}
T[1198] = {
  title = "Alla Ricerca di Thaelrid",
  desc = "In questi giorni girano molte voci sull'unione tra il Martello del Crepuscolo e i naga nelle Blackfathom Deeps, sulle coste di Ashenvale.$B$BIl mio ruolo qui, nell'Argent Dawn, è raccogliere quante più informazioni posso, così da sapere quando e dove serve aiuto.$B$BSono passate settimane da quando ho mandato un esploratore a controllare le attività alle Blackfathom Deeps. Argent Guard Thaelrid non ha ancora riferito.$B$BGli altri miei esploratori sono impegnati in faccende urgenti.$B$BTrova Thaelrid e aiutalo per me, $N.",
  obj = "Trova Argent Guard Thaelrid nelle Blackfathom Deeps.",
  reward = "Dawnwatcher Shaedlass ha fatto bene a mandarti. In questo luogo corrotto è davvero in corso un piano malvagio.",
  en_title = "In Search of Thaelrid",
  en_obj = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.",
}
T[1199] = {
  title = "Cala il Crepuscolo",
  desc = "Rafforzati dai riti ancestrali dei caotici Dei Antichi, i membri del Martello del Crepuscolo si adoperano per riportare i loro oscuri padroni e diffondere morte e terrore per il mondo.$B$BCrediamo che il Martello del Crepuscolo si sia alleato con i naga e si stia radunando nelle Blackfathom Deeps, sulla costa di Ashenvale.$B$BQualunque piano malvagio si stia preparando nelle profondità dell'antico tempio va sventato.$B$BMuovi guerra al Martello e riporta la prova delle tue imprese. I tuoi sforzi saranno ricompensati con generosità.",
  obj = "Porta 10 Twilight Pendant ad Argent Guard Manados, a Darnassus.",
  progress = "Le Blackfathom Deeps un tempo erano un antico tempio degli elfi della notte. Un tempo ospitavano un pozzo lunare potentissimo. Chissà quale male vi si prepara ora per mano del Martello del Crepuscolo.$B$BHai fatto progressi nel liberare il luogo dalla loro presenza?",
  reward = "Sei senza dubbio di sangue coraggioso e nobile, $N. L'Argent Dawn ti loda per i tuoi sforzi contro il male.",
  en_title = "Twilight Falls",
  en_obj = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",
}
T[1200] = {
  title = "La Malvagità di Blackfathom",
  desc = "Le forze mi hanno abbandonato. Serve il tuo aiuto!$B$BTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò in rovina quando la corruzione di un Dio Antico filtrò da sotto la terra e contaminò il sacro Pozzo Lunare.$B$BAku'Mai, servitore del Dio Antico, si levò dalle acque.$B$BI cultisti del Martello del Crepuscolo si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai in cambio di potere.$B$BUccidi Kelris e porta la sua testa a Selgorm, a Darnassus, $N, ti prego.",
  obj = "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.",
  progress = "Il tempo è una merce preziosa, $C.$B$BIl mio ruolo qui a Darnassus è fare in modo che l'Argent Dawn prosperi e che le forze del male che avanzano su Kalimdor siano fermate.$B$BDi' in fretta cosa vuoi, oppure va' per la tua strada.",
  reward = "Kelris ci è sfuggito per parecchio tempo.$B$BSembra che ogni volta che il male si è fatto sentire da queste parti, Kelris ci abbia messo lo zampino. Per un po' lo abbiamo creduto morto o scomparso.$B$BMa ora torna tutto. Ponendo fine al suo dominio hai risparmiato la vita a molti innocenti.$B$BPer la Luce! Sacrificare qualcuno a un servitore di un Dio Antico per il proprio tornaconto è a dir poco riprovevole!$B$BHai compiuto una grande impresa, $N. Ti rendo omaggio a nome dell'Argent Dawn.",
  en_title = "Blackfathom Villainy",
  en_obj = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",
}
T[1201] = {
  title = "Spie di Theramore",
  desc = "L'Orda e l'Alleanza mantengono una tregua precaria. Ai confini le due parti si affrontano in scaramucce e azioni segrete, ed è nostro dovere fare in modo che l'Orda abbia la meglio!$B$BOra ne abbiamo l'occasione.$B$BInfiltrati dell'Alleanza hanno preso posizione a est di Brackenwall Village. Spiano il villaggio e riferiscono i nostri movimenti a Theramore, cosa che non possiamo permettere.$B$BDai la caccia agli infiltrati e uccidili. Manda ai loro superiori un messaggio chiaro: non tollereremo la presenza delle loro spie!",
  obj = "Uccidi 9 Theramore Infiltrator, poi torna da Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai trovato gli infiltrati, $N?",
  reward = "Buon lavoro. I loro infiltrati sono abili, ma non abbastanza da sfuggire all'occhio vigile dell'Orda!",
  en_title = "Theramore Spies",
  en_obj = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.",
}
T[1202] = {
  title = "I Moli di Theramore",
  desc = "$N, due delle nostre spie sono state mandate a rubare dei documenti da una nave ai moli di Theramore. Hanno preso le carte, ma sono state scoperte e hanno dovuto gettare i documenti in mare.$B$BPiù tardi una delle due è riuscita a fuggire, ma non a recuperare il bottino. Mi ha riferito il suo fallimento, e ora affido il compito a te.$B$BI documenti sono in un baule, da qualche parte nell'acqua sotto i moli di Theramore. Trova quei documenti, $N, e portameli.",
  obj = "Porta i Captain's Documents a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai trovato i documenti, $N? Contengono informazioni vitali per la stabilità dell'Alleanza e, quindi, vitali per la sicurezza dell'Orda.",
  reward = "Mi congratulo con te, $N. Non era una missione facile. Ma i documenti che hai preso hanno un grande valore per i nostri superiori.",
  en_title = "The Theramore Docks",
  en_obj = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.",
}
T[1203] = {
  title = "A Jarl Serve una Lama",
  desc = "Devo tagliare delle cose. Non posso dirti cosa taglierò, ma... mi serve una lama. Una lama particolare...$B$BAlcuni la chiamano spadone d'acciaio lunare. Io la chiamo lama da falciare.$B$BMi aiuti? Magari la trovi in città, magari parli con un fabbro e lui te la fa apposta.$B$BMa non dormirci sopra. Quello che devo tagliare non si conserva per sempre...",
  obj = "Porta un Moonsteel Broadsword a Jarl, nel Dustwallow Marsh.",
  progress = "Hai la mia lama??",
  reward = "È una bella lama. Falcia bene. È proprio una bella lama da falciare. Grazie. Grazie, grazie, grazie!!! Adesso voglio provarla...$B$BDopo. La provo dopo. Ma come stavo dicendo... grazie.",
  en_title = "Jarl Needs a Blade",
  en_obj = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.",
}
T[1204] = {
  title = "Zuppa di Mudrock e Crostacei",
  desc = "Sto lavorando a un piatto che chiamo \"Zuppa di Mudrock e crostacei\". Mi mancano ancora gli ingredienti principali, e... be', non credo che durerei a lungo arrancando per il Dustwallow Marsh!$B$BAllora, $N, puoi andare a caccia per me? Prima di tutto mi servono le lingue delle tartarughe Mudrock. Trovi le Mudrock lungo la costa, soprattutto intorno alla baia.$B$BMa non voglio lingue qualsiasi! Ho sentito che alcune Mudrock hanno la lingua biforcuta...$B$BDicono che le lingue biforcute abbiano un sapore particolare, e io voglio quel sapore nel mio piatto...",
  obj = "Porta 8 Forked Mudrock Tongue a Morgan Stern, a Theramore.",
  progress = "Hai preso le lingue biforcute?",
  reward = "Queste andranno benissimo! Grazie, $N!$B$BOra proverò diverse tecniche di cottura su queste lingue, per trovare il modo migliore di esaltarne il sapore.$B$BAlla fine avrò un piatto degno di essere servito al Blue Recluse di Stormwind!",
  en_title = "Mudrock Soup and Bugs",
  en_obj = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.",
}
T[1205] = {
  title = "Deadmire",
  desc = "Deadmire è un antico crocolisk del Dustwallow Marsh. Ed è giunta la sua ora di morire.$B$BLe vecchie ossa scricchiolano mentre trascina il suo corpo enorme attraverso la palude, e benché si muova ancora con la forza e la velocità della giovinezza, il suo corpo che invecchia tormenta il grande spirito che racchiude, uno spirito la cui fiamma non vacilla.$B$BEppure ora vive in un dolore costante, che fa impazzire. Devi porre fine alla vita di questa nobile creatura, $N. Devi condurre Deadmire alla pace.",
  obj = "Porta Deadmire's Tooth a Melor, a Thunder Bluff.",
  progress = "Hai il dente di Deadmire, $N? Hai posto fine alle sofferenze della creatura?",
  reward = "Molto bene, $N.$B$BSono sicuro che la caccia non sia stata facile, ma è bello sapere che il dolore della bestia è finalmente finito.",
  en_title = "Deadmire",
  en_obj = "Bring Deadmire's Tooth to Melor in Thunder Bluff.",
}
T[1206] = {
  title = "A Jarl Servono Occhi",
  desc = "Il succo d'occhi è un buon succo da bere. Peccato che quasi tutte le bestiole abbiano solo due occhi.$B$BMa i ragni hanno tanti occhi. Tanti, tantissimi. E il succo d'occhi di Darkmist è saporito. Vellutato e salato! Occhi di ragno non scoppiati... ne sento già il sapore.$B$BI ragni di Darkmist sono a ovest di qui, nella Caverna di Darkmist. Secondo te i ragni prendono il nome dalla caverna... o è il contrario?",
  obj = "Porta 40 Unpopped Darkmist Eye a \"Swamp Eye\" Jarl, alla Dimora di Swamplight.",
  progress = "Dove sono quegli occhi?",
  reward = "Hai preso gli occhi! Hai preso gli occhi! Gustosi, gustosi occhi di ragno!$B$BCerti occhi... quando li fissi, ti fissano anche loro. Quelli mangiali per ultimi. Ti tengono compagnia... qui fuori nella palude.$B$BCiao, occhietti di ragno. Ciao! Sapete di pollo. Pollo appiccicoso e salato!$B$BMmmh.",
  en_title = "Jarl Needs Eyes",
  en_obj = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.",
}
T[1218] = {
  title = "Spezie Esotiche",
  desc = "Mi piace cucinare. La buona cucina di palude. Cosce di rana verde fritte e cose simili.$B$BE per cucinare mi servono spezie. Spezie lenitive. Poi preparo uno stufato, lo faccio stufare per bene, me lo sorbisco e ne do un po' anche a te.$B$BTi piace lo stufato?",
  obj = "Porta 3 Soothing Spices a \"Swamp Eye\" Jarl, nel Dustwallow Marsh.",
  progress = "Spezie. A tutti farebbe comodo un po' di spezie nella vita. Sei d'accordo?",
  reward = "Ah, queste sì che sono spezie! Ecco del buono stufato di palude.",
  en_title = "Soothing Spices",
  en_obj = "Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh.",
}
T[1219] = {
  title = "Il Rapporto dell'Orco",
  desc = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.$B$BLa pergamena è scritta in orchesco... e sembra importante.",
  obj = "Porta lo Spy's Report a un Theramore Lieutenant.",
  progress = "Hai un rapporto da fare?",
  reward = "Hm... non leggo molto bene l'orchesco, ma questo sembra un rapporto... scritto da una spia orchesca!",
  en_title = "The Orc Report",
  en_obj = "Bring the Spy's Report to a Theramore Lieutenant.",
}
T[1220] = {
  title = "Capitano Vimes",
  desc = "Il Capitano Vimes dovrebbe vedere il rapporto dell'orco che hai trovato, $N. Conosce la lingua degli orchi meglio di molti altri. E dovrebbe sapere che ci sono spie dell'Orda vicino a Theramore!$B$BIl capitano è nella caserma, sul lato nord-orientale dell'Isola di Theramore.",
  obj = "Porta lo Spy's Report a Captain Garran Vimes.",
  progress = "Hai qualcosa per me?",
  reward = "Un rapporto di una spia orchesca! Come l'hai trovato? Non importa — vediamo cosa dice...",
  en_title = "Captain Vimes",
  en_obj = "Bring the Spy's Report to Captain Garran Vimes.",
}
T[1221] = {
  title = "Tuberi Blueleaf",
  desc = "I tuberi Blueleaf sono una prelibatezza in tutto il mondo! Ma sono rari, molto rari. L'unico posto dove trovarli è qui nelle Barrens, nelle profondità della terra, nel Razorfen Kraul.$B$BE anche lì è impossibile trovarli, a meno di sapere esattamente dove cercare! Per questo ho addestrato questi roditori snufflenose a trovarli per me. Hanno un gran fiuto e sentono l'odore di un tubero a cinquanta passi di distanza.$B$BNon sarà facile, ma se mi porti qualche tubero ti pagherò profumatamente.",
  obj = "Prendi una Crate with Holes.$BPrendi uno Snufflenose Command Stick.$BPrendi e leggi lo Snufflenose Owner's Manual.$B$BNel Razorfen Kraul, usa la Crate with Holes per evocare uno Snufflenose Gopher e usa lo Snufflenose Command Stick sul roditore per fargli cercare i Blueleaf Tuber.$B$BPorta 6 Blueleaf Tuber, lo Snufflenose Command Stick e la Crate with Holes a Mebok Mizzyrix, a Ratchet.",
  progress = "Hai i tuberi, $N?",
  reward = "Perfetto, li hai presi! Posso venderli ai miei contatti a peso d'oro!$B$BGrazie della consegna, $N! Sei $Gun ottimo socio:un'ottima socia;.",
  en_title = "Blueleaf Tubers",
  en_obj = "Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner's Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",
}
T[1222] = {
  title = "La Fuga di Puzzone",
  desc = "Meno male, finalmente qualcosa che non vuole mangiarmi!$B$BMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.$B$BIl cuoco Morgan Stern sta studiando una nuova ricetta, e mi ha mandato qui a raccogliere foglie di trifoglio d'acqua. Immagino che le trovi gustose.$B$BComunque, mentre cercavo una pianta di trifoglio d'acqua... mi sono fatto circondare! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco il trifoglio?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Morgan Stern, a Theramore.",
  progress = "Hai visto il signor Ignatz? L'ho mandato nella palude un po' di tempo fa e non è tornato!",
  reward = "Il signor Ignatz è appena passato di qui con le foglie di trifoglio d'acqua, e mi ha detto che l'hai aiutato a uscire da un bel guaio.$B$BGrazie, $N. Chiederò a mio zio di offrirti un banchetto la prossima volta che passerai dal Blue Recluse, a Stormwind.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",
}
T[1238] = {
  title = "Il Rapporto Perduto",
  desc = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.$B$BLa pergamena è un rapporto scritto da un orco che ha passato settimane a spiare la città di Theramore.$B$BBasta scorrere la pergamena per capire che va portata al capo delle spie degli orchi, a Brackenwall Village.",
  obj = "Porta lo Spy's Report a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai qualcosa per me?",
  reward = "Buon lavoro, $N. Il nostro agente, Marg Nighteye, era di stanza fuori Theramore. Aveva il compito di spiare la città.$B$BQuesto è il suo rapporto più recente, e potrebbe essere l'ultimo — da quello che racconti, temo che Marg abbia trovato la morte nella palude...",
  en_title = "The Lost Report",
  en_obj = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.",
}
T[1239] = {
  title = "La Testa Mozzata",
  desc = "Scavando con vigore porti alla luce la testa di un orco maschio, mozzata malamente all'altezza del collo. Le labbra sono irrigidite in un ringhio, e gli occhi scuri fissano con aria di sfida.",
  obj = "Porta la Defiant Orc Head a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai qualcos'altro da riferire, $N?",
  reward = "Questa è la testa di Marg Nighteye! Come temevo, è morto.$B$BGuarda la ferita sul collo! Può essere stata un'arma a fare quel taglio frastagliato, o è stata qualche bestia a uccidere il nostro agente?$B$BÈ un mistero che dobbiamo risolvere, $N. Dobbiamo scoprire se la morte di Marg è opera dell'Alleanza!",
  en_title = "The Severed Head",
  en_obj = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.",
}
T[1240] = {
  title = "Lo Stregone Troll",
  desc = "Dobbiamo conoscere le circostanze della morte di Marg! E l'unico modo per saperle, $N, è la magia stregonesca dei troll.$B$BPorta la testa di Marg a Kin'weelay, nella Stranglethorn Vale, al Grom'gol Base Camp.$B$BKin'weelay è lo stregone più potente dei troll Darkspear. Se qualcuno può parlare con lo spirito di Marg Nighteye, è lui.",
  obj = "Porta la Defiant Orc Head a Kin'weelay, al Grom'gol Base Camp, nella Stranglethorn Vale.",
  progress = "C'è uno spirito furioso intorno a te, $Gfratello:sorella;. Cosa ti porta da Kin'weelay?",
  reward = "Ah, ora vedo. Lo spirito di questo orco è legato al nostro mondo, e ribolle di rabbia per un compito non ancora portato a termine.$B$BBene, facciamo due chiacchiere con questo orco arrabbiato...",
  en_title = "The Troll Witchdoctor",
  en_obj = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.",
}
T[1241] = {
  title = "Il Diplomatico Scomparso",
  desc = "Di recente un diplomatico è stato mandato a Theramore per incontrare Jaina Proudmoore. Quel diplomatico non è mai arrivato.$B$BCredo che i Defias siano coinvolti in questo complotto, ma non so in che modo. Per ora la scomparsa del diplomatico è passata inosservata, ma non potrà restare così a lungo.$B$BGli agenti del re stanno già setacciando la città in cerca di indizi, ma ho dei contatti miei che vorrei coinvolgere.$B$BNella Valle degli Eroi c'è un mio vecchio amico di nome Jorgen. Trovalo, dagli questo biglietto e segui le sue istruzioni.",
  obj = "Trova Jorgen, a Stormwind City.",
  progress = "Hmph, sarà meglio che tu abbia un buon motivo per venire a disturbare uno che se ne sta a pescare. Non sopporto gli ambulanti, figurarsi gli accattoni.",
  reward = "Hmm... <Jorgen alza lo sguardo su di te, con gli occhi socchiusi.>$B$BVa bene. Ti do una mano, non perché mi va, ma perché sono obbligato.$B$BE mettiamo in chiaro una cosa: ne sai già molto più di quanto dovresti. Che resti il nostro piccolo segreto, e non andare a spifferare in giro per le taverne quel che scopri. Capito?",
  en_title = "The Missing Diplomat",
  en_obj = "Find Jorgen in Stormwind City.",
}
T[1242] = {
  title = "Il Diplomatico Scomparso",
  desc = "Porta 'sto biglietto a Elling Trias. Non dirgli nient'altro. Sii solo $Geducato:educata; e aspetta che ti risponda. E non preoccuparti, lo farà.$B$BTe lo ripeto solo un'altra volta, $N: prendi sul serio 'sta faccenda, e tieni il becco chiuso.$B$BTrias lo trovi nella sua bottega di formaggi, Formaggio di Trias, nel Quartiere Commerciale. Buona fortuna.",
  obj = "Consegna la Sealed Note to Elling di Jorgen a Elling Trias, a Stormwind City.",
  progress = "Salve, $N. Posso fare qualcosa per te? Magari vuoi assaggiare un po' del nostro cheddar speciale di Trias? O un pezzo di erborinato di Darnassus?",
  reward = "Scusa, una lettera per me? Ma guarda... non capita spesso di ricevere una consegna che non sia una cassa o un barile, quando non fai altro che lavorare. Vediamo di che si tratta.$B$B<Elling alza gli occhi verso di te mentre apre la lettera.>$B$BSembri un po' $Gteso:tesa;, tutto bene, $N?",
  en_title = "The Missing Diplomat",
  en_obj = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.",
}
T[1243] = {
  title = "Il Diplomatico Scomparso",
  desc = "Jorgen, vecchio figlio di.... Ah, quindi la mettiamo così, eh?$B$BVa bene, me ne farò una ragione. Spero che finisca nel Twisting Nether il prima possibile!$B$BEcco come andrà, $N. Io comincio a muovere i miei contatti qui, ma il grosso del lavoro sul campo lo fai tu, così risparmio qualche moneta.$B$BVa' a Darkshire, a Duskwood, e trova Watcher Backus — di solito pattuglia la strada a nord, appena fuori dal paese. Digli soltanto che stai indagando per me su eventuali attività dei Defias e ti darà tutte le informazioni che può.",
  obj = "Consegna la Sealed Note to Watcher Backus, a Duskwood.",
  progress = "Non è troppo sicuro andare in giro per i boschi, $N. Sta' $Gattento:attenta;, e se vedi qualcosa di sospetto o pericoloso avvisa subito i Watcher. Non provare ad affrontare niente da $Gsolo:sola;. Non siamo responsabili se ti capita qualcosa di terribile.$B$BMa lo sappiamo tutti e due che mi ignorerai e combatterai comunque qualunque cosa sbuchi dal buio, vero? Ahah, già, voi avventurieri... tutti uguali.",
  reward = "Oh, ti manda Trias, eh? Questo cambia un po' le cose.$B$BCombatti pure qualunque mostruosità ti venga addosso dal buio. Sono sicuro che te la caverai facilmente, se sei il tipo che bazzica con uno come lui.$B$BAllora, cosa vuole il mio amico da me in una giornata tetra come questa?",
  en_title = "The Missing Diplomat",
  en_obj = "Give the Sealed Note to Watcher Backus in Duskwood.",
}
T[1244] = {
  title = "Il Diplomatico Scomparso",
  desc = "Attività dei Defias? Be', un po' di attività c'è sempre; anche se se ne stanno per conto loro li consideriamo una minaccia.$B$BMa ora che ci penso, c'è stato un avvistamento recente che pareva strano. Sarà stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno alla Cascina degli Addle. Dal rapporto, avevo pensato che fosse successo qualcosa di grosso.$B$BPerché non provi a controllare prima là e mi riporti quel che trovi?$B$BLa fattoria è a sud della strada che viene da Westfall, appena entri a Duskwood.",
  obj = "Trova il Defias Docket e portalo a Watcher Backus, a Duskwood.",
  progress = "Sta' $Gattento:attenta; là fuori, $N. So che è stato Trias a mandarti qui, ma questo non vuol dire che nei boschi non ci sia in agguato qualcosa capace di darti dei guai... soprattutto se stai indagando sui Defias.",
  reward = "Sei $Gtornato sano e salvo:tornata sana e salva;. Non si può chiedere molto di più, no?$B$BOra, vediamo cos'abbiamo qui. Sembra piuttosto ufficiale, per quel che ho visto dei documenti dei Defias. Ma potrebbe essere un falso, giusto per farti perdere le tracce di quel che stai cercando.",
  en_title = "The Missing Diplomat",
  en_obj = "Find the Defias Docket and return it to Watcher Backus in Duskwood.",
}
T[1245] = {
  title = "Il Diplomatico Scomparso",
  desc = "Accidenti, questo sembra troppo complesso per essere messo lì solo per sviarti. Non dovrei nemmeno metterci gli occhi sopra. Portalo a Trias — lui saprà venirne a capo. E NON lasciare che nessuno ti metta i bastoni tra le ruote. Questa cosa è più grossa di me. Forse è più grossa anche di lui, ma vedremo.$B$BE fammi un favore, $N: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.",
  obj = "Porta il Defias Docket a Elling Trias, a Stormwind.",
  progress = "Vedo che sei di ritorno, e tutto $Gintero:intera;. Sappiamo tutti e due che non sei qui per il formaggio, quindi tagliamo corto con i convenevoli. Backus è stato d'aiuto, o non sei ancora $Gpartito:partita; per Duskwood?",
  reward = "Già... è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.$B$BPare che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Hmm... e questo cos'è? \"Fist\"? È un nome che mi dice qualcosa.",
  en_title = "The Missing Diplomat",
  en_obj = "Bring the Defias Docket to Elling Trias in Stormwind.",
}
T[1246] = {
  title = "Il Diplomatico Scomparso",
  desc = "Già, ora che ci penso... Dashel... Dashel qualcosa... Come si chiamava? FIST! Dashel Stonefist. In certi giri lo chiamano Fist — probabilmente perché gli piace fare a botte.$B$BDi solito lo trovi nella Città Vecchia — proprio nel bel mezzo. Va' a parlargli. Se serve, usa una spada o qualcosa di pesante e contundente per convincerlo a sbottonarsi un po'. E non esitare. Se è dentro questa storia fino al collo come dicono queste carte, non ti darà nessuna informazione di sua spontanea volontà.",
  obj = "Parla con Dashel Stonefist, a Stormwind.",
  reward = "Cosa?!$B$BTe ne vieni nel mio vicolo a far domande sugli affari miei? Affari che con te non c'entrano un bel niente, si vede.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Dashel Stonefist in Stormwind.",
}
T[1247] = {
  title = "Il Diplomatico Scomparso",
  desc = "Allora sì... ehm... qualcosa su quell'incontro alla Cascina degli Addle forse la so. È successo qualche settimana fa, mi pare. Io non c'entravo davvero niente. La mia parte era finita quando è fallito il piano A... maledetti avventurieri.$B$BIl tizio che avevamo infiltrato per il piano B veniva da Menethil; uno che chiamano Slim. È tutto quel che so del loro piano di riserva.",
  obj = "Parla con Elling Trias, a Stormwind.",
  reward = "Bello vedere che sei ancora $Gvivo:viva;, $N. Quindi con Dashel è andata bene, eh?$B$BHo letto meglio questo loro piano e, anche se non dice il nome del diplomatico che volevano, parla di questo piano B che hanno messo in atto dopo aver fallito il primo tentativo di catturarlo.$B$BDi questo Slim che ha nominato Dashel qui non c'è scritto nessun altro nome, ma se dici che è a Menethil, è già un inizio.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[1248] = {
  title = "Il Diplomatico Scomparso",
  desc = "Un mio contatto si è ritirato nelle Wetlands, nella città portuale di Menethil. Dovrebbe essere disposto ad aiutarti anche solo sulla tua parola, se gli dici che lavori per me. Si chiama Mikhail. Prima di lasciare Stormwind, qualche anno fa, aveva accennato che voleva fare il barista.$B$BParlagli, trova questo Slim e scopri se c'è altro da sapere su questo diplomatico rapito. Dobbiamo scoprire dove l'hanno portato, o almeno chi è. Il documento non dice niente sui loro piani dopo la cattura.",
  obj = "Parla con Mikhail, nelle Wetlands.",
  reward = "$GBenvenuto:Benvenuta;, $Gbenvenuto:benvenuta;, $Gbenvenuto:benvenuta;, $N. Che piacere averti qui con noi. Magari una birra, oggi? O del montone?$B$BDi' pure cosa desideri e farò in modo che tu sia $Gservito:servita; a dovere. Mi chiamo Mikhail, e sarò lieto di servirti.$B$BHmm? Cosa? Trias? Abbassa la voce, $Gamico mio:amica mia;. Non è una cosa che debba sentire tutta la taverna.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1249] = {
  title = "Il Diplomatico Scomparso",
  desc = "Dici che ti manda Elling? E allora l'ospitalità che ti ho offerto adesso vale dieci volte tanto. Qualunque cosa ti serva, basta chiedere. Farò del mio meglio per aiutarti.$B$BHmm, Slim, dici? Non sono sicuro che il nome mi dica qualcosa, ma terrò gli occhi aperti.$B$BNon guardare adesso, $N, ma il signore laggiù vicino all'uscita sta guardando da questa parte. Ascolta la nostra conversazione un po' troppo attentamente, se capisci cosa intendo. Se fossi in te, farei il possibile per bloccarlo prima che scappi verso la porta.",
  obj = "Blocca Tapoke Jahn prima che scappi, poi torna da Mikhail, a Menethil.",
  progress = "Ti è sgusciato via? Aveva un'aria losca, dal modo in cui ci guardava.",
  reward = "L'hai preso, eh? $GBravo:Brava;. Mi sorprende che fosse Slim.$B$BSarò sincero: non avrei mai pensato che mi sarebbe mancato il brivido di certi traffici clandestini più loschi. Le vecchie abitudini sono dure a morire, immagino. Non dirlo a Elling — se sapesse che mi manca l'azione, probabilmente cercherebbe di farmi tornare a Stormwind.$B$BSono contento di esserti stato almeno un po' utile mentre eri a Menethil. Se ti serve altro, basta chiedere.",
  en_title = "The Missing Diplomat",
  en_obj = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.",
}
T[1250] = {
  title = "Il Diplomatico Scomparso",
  desc = "I Defias non mi pagavano abbastanza da morire per la loro causa. Hanno preso il re. Sì, il re di Stormwind, non un diplomatico qualunque. Stava andando a Theramore per incontrare Jaina Proudmore — a quanto pare era una cosa grossa, e un gran segreto. Ma non ci sono dentro solo i Defias. Lavorano con qualcuno. Credo sapessero che la cosa era più grande di loro.$B$BLa mia parte era solo far salire il loro uomo sulla nave del re mentre era in porto. Il tizio si chiamava Hendel. È tutto quel che so. Lo giuro!",
  obj = "Parla con Mikhail, nelle Wetlands.",
  reward = "IL RE?! Cioè... il re? Il re vero? Stai scherzando? Non avevi detto che cercavi i rapitori del re. Non avevo nemmeno sentito dire che fosse scomparso — questo spiegherebbe in parte perché abbiano incoronato suo figlio.$B$BAvviserò subito Elling. Vorrà sapere che sei sulle loro tracce.$B$BNon avrei mai immaginato che Jahn avrebbe venduto Stormwind per due monete schifose. Anche un ladro deve avere il suo onore su certe cose.$B$BOra il punto è trovare questo Hendel. E credo di poterti aiutare.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1251] = {
  title = "Lo Scudo Nero",
  desc = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Krog, a Brackenwall Village.",
  progress = "Cos'hai lì, $N? Prove trovate tra i resti della Shady Rest Inn?",
  reward = "Ammetto che gli umani hanno gusti strani in fatto di arredamento, ma userebbero davvero un semplice scudo di ferro per decorare il camino? Forse questo scudo l'hanno messo lì quelli che hanno bruciato la locanda.$B$BUn avvertimento? Una minaccia?",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.",
}
T[1252] = {
  title = "Tenente Paval Reethe",
  desc = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Quando togli i detriti e la cenere incrostati sull'oggetto, compare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.$B$BSotto l'ancora è impresso in rilievo il nome \"Tenente Paval Reethe\".",
  obj = "Porta Reethe's Badge a Captain Garran Vimes, a Theramore.",
  progress = "Hai trovato qualcosa di interessante alla Shady Rest Inn?",
  reward = "Non è mai una buona notizia quando mi portano il distintivo di una guardia.$B$BA volte è un uomo o una donna caduti in battaglia, e tocca a me portare la notizia alla famiglia in lutto. Altre volte non scopriamo mai cosa gli sia successo. E altre volte è anche peggio.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.",
}
T[1253] = {
  title = "Lo Scudo Nero",
  desc = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Captain Garran Vimes, a Theramore.",
  progress = "Hai trovato prove sul luogo della Shady Rest Inn?",
  reward = "Hm, non sono un esperto di come si costruiscono armi e armature. Di come si usano sì, ma non di come si fabbricano.$B$BQuesto scudo sembra comunissimo, a parte i danni dell'incendio che ha avvolto la locanda.",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.",
}
T[1258] = {
  title = "... e crostacei",
  desc = "Un altro ingrediente della mia nuova ricetta è la zampa con il guscio di un granchio gigante. E i granchi che hanno nel Dustwallow — li chiamano Muckshell — proprio non vanno bene! Temo che gli unici granchi adatti vivano lontano, nella Swamp of Sorrows.$B$BIl guscio della zampa è un elemento chiave nella presentazione del piatto, quindi mi servono zampe intatte, senza graffi. Un granchio adulto può averne solo una o due così, e a me ne servono molte per mettere a punto il piatto.$B$BAllora, $N... sei $Gdisposto:disposta; a viaggiare?",
  obj = "Porta 12 Pristine Crawler Leg a Morgan Stern, a Theramore.",
  progress = "Le mie ricerche sulle lingue di Mudrock procedono bene. La tua caccia ai granchi va bene, spero?",
  reward = "Sono esemplari magnifici, $N! I gusci sono in perfette condizioni, e la carne è rosa e tenera. Nelle tue vene scorre sangue da chef, ne sono sicuro!",
  en_title = "... and Bugs",
  en_obj = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.",
}
T[1259] = {
  title = "Tenente Paval Reethe",
  desc = "Il nome del Tenente Paval Reethe non mi dice niente. La cosa migliore è chiedere all'Aiutante Tesoran. Tiene i registri di tutta la guardia di Theramore, dal personale all'equipaggiamento.$B$BCon una rapida occhiata ai suoi libri dovrebbe riuscire a dirti chi è questo Reethe.",
  obj = "Scopri di più su Reethe da Adjutant Tesoran, a Theramore.",
  reward = "Salve, $N. Vuoi informazioni su un membro in particolare della guardia di Theramore? Reethe, hai detto?$B$BDammi solo un momento per trovare il libro giusto.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Find out more about Reethe from Adjutant Tesoran in Theramore.",
}
T[1260] = {
  title = "Morgan Stern",
  desc = "Sto preparando un nuovo menù per il ristorante. Sarà pieno di piatti rustici a tema \"bayou\". Credo che la mia clientela del Blue Recluse li adorerà!$B$BHo mandato mio nipote Morgan a Theramore, una città ai margini del Dustwallow Marsh. È lì a raccogliere ricette dalla gente del posto, e devo sapere che cosa ha trovato finora.$B$BIl viaggio fino a Theramore è lungo. Troppo lungo per me. Ma scommetto che $Gun giovane:una giovane; $C come te coglierebbe al volo l'occasione di viaggiare, vero?",
  obj = "Parla con Morgan Stern, a Theramore.",
  reward = "Oh, ti ha mandato mio zio, eh?$B$BBe', sto facendo ricerche sulle ricette e ho qualche pista, ma mi serve aiuto.$B$BL'aiuto di qualcuno che non abbia paura di bagnarsi i piedi.",
  en_title = "Morgan Stern",
  en_obj = "Speak with Morgan Stern in Theramore.",
}
T[1261] = {
  title = "Marg Parla",
  desc = "Maledetto muckshell! Non puoi uccidere Marg! Ah, ma io sono morto. Quindi deve avermi ucciso...$B$BMa la mia missione! La mia missione! Tu, $N, devi portarla a termine.$B$BMentre ero vicino a Theramore, ho avvistato un gruppo di soldati dell'Alleanza accampati sulla spiaggia. E un soldato portava un ciondolo... un ciondolo carico di più gemme di quante un soldato possa mai permettersi!$B$BQuella notte mi sono intrufolato nel loro accampamento e ho rubato il ciondolo, ma sulla via del ritorno alla base un uomo-granchio muckshell mi ha ucciso!$B$B$N, devi trovare quel muckshell e recuperare il ciondolo!",
  obj = "Porta il Jeweled Pendant a Nazeer, a Brackenwall Village.",
  progress = "$N, hai scoperto la sorte di Marg?",
  reward = "Questo ciondolo lo portava un soldato di Stormwind??$B$BGrazie, $N. Hai svelato il segreto della morte di Marg. Ma questo ciondolo è un nuovo mistero da risolvere, un mistero che potrebbe avere conseguenze terribili per l'Alleanza, e per l'Orda.",
  en_title = "Marg Speaks",
  en_obj = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.",
}
T[1262] = {
  title = "Riferisci a Zor",
  desc = "È strano che il ciondolo rubato da Marg fosse nelle mani di semplici soldati. Forse il suo proprietario era travestito, o forse l'hanno rubato i soldati stessi!$B$BQualunque sia la verità, questo è il ciondolo di un nobile, e dobbiamo scoprire il suo vero proprietario se vogliamo svelarne il mistero.$B$BPorta il ciondolo a Zor Lonetree, a Orgrimmar. Conosce bene la politica dell'Alleanza, e saprà se questo ciondolo ha una storia tra i nobili di Stormwind.",
  obj = "Porta il Jeweled Pendant a Zor Lonetree, a Orgrimmar.",
  progress = "Vieni da Brackenwall Village, nel Dustwallow? Come sta Nazeer, e come procede il suo lavoro nella palude?",
  reward = "Questo ciondolo è stato lavorato con grande abilità e precisione, $N. Nessun orco desidererebbe un gioiello simile...$B$BMa molti umani sì.$B$BFarò studiare questo ciondolo. Speriamo che col tempo i suoi misteri ci vengano svelati.",
  en_title = "Report to Zor",
  en_obj = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.",
}
T[1264] = {
  title = "Il Diplomatico Scomparso",
  desc = "All'inizio di ogni mese i Soldati di Kul Tiras vengono pagati e di solito lasciano Theramore per andare da qualche altra parte. Molti vengono qui a correre dietro alle donne, a far baldoria e a divertirsi. Uno di quei gruppi ormai lo considero di casa qui alla taverna, e credo che questo Hendel sia dei loro.$B$BIl Comandante Samaul, a Theramore, potrebbe aiutarti a trovarlo se Hendel è ancora di stanza là. È del tutto fedele a Proudmoore, ma se fai il nome di Elling dovrebbe darti una mano... con discrezione.",
  obj = "Trova Commander Samaul, nel Dustwallow Marsh.",
  reward = "Un piacere conoscerti, $N. Sono il Comandante Samaul. Comando io le forze della Signorina Proudmoore qui a Theramore.$B$BAnche se sono molto occupato, se hai domande non esitare a chiedere. Forse dovrò essere breve, ma se ti serve il mio aiuto non c'è ragione di essere scortese.$B$BSe pensi di uscire dalla città, ti consiglio di stare $Gattento:attenta;. Oltre a ogre, orchi e murloc, la parte meridionale della palude è piena di draghi neri.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Commander Samaul in Dustwallow Marsh.",
}
T[1265] = {
  title = "Il Diplomatico Scomparso",
  desc = "Hendel? Sì, conosco quell'uomo. Ma perché ti servirebbe uno dei miei soldati?$B$BTi manda Elling a cercarlo? Hmm, la cosa non mi piace. Elling non ti avrebbe mandato prima da me se la tua faccenda non fosse preoccupante. Capisco se non puoi dirmi di cosa si tratta, ma sappi una cosa: ho il dovere di proteggere queste terre. Se hai intenzione di creare disordini, allora ti consiglio di dirmi tutto quello che puoi.$B$BCredo che Hendel fosse di stanza alla prima torre fuori Theramore. Sta' $Gattento:attenta;.",
  obj = "Cerca a Sentry Point qualche traccia di Private Hendel.",
  progress = "Sì, $N?",
  reward = "L'uomo che cerchi, quello noto come Hendel, non è qui. Altre fonti hanno portato a Lady Proudmoore informazioni che credo tu già conosca. Mi ha chiesto di trovarti e di darti aiuto nella tua impresa. Se me lo permetti, ti dirò dove trovare il Soldato Hendel, così potremo consegnarlo alla giustizia.",
  en_title = "The Missing Diplomat",
  en_obj = "Search Sentry Point for any sign of Private Hendel.",
}
T[1266] = {
  title = "Il Diplomatico Scomparso",
  desc = "Il Soldato Hendel è a ovest di qui. Al momento è di guardia e protegge alcuni degli infiltrati di Theramore mentre riposano. Tengono d'occhio la base dell'Orda, Brackenwall, e cercano qualunque altra cosa possa minacciare i nostri confini.$B$BNon dovresti avere problemi a trovarlo; basta cercare le tende lungo la strada.$B$BHo un'altra faccenda da sbrigare, ma ti raggiungerò presto. Se hai problemi, mi trovi sempre nella torre di Lady Proudmoore.",
  obj = "Trova Private Hendel, nel Dustwallow Marsh.",
  reward = "Salve, $Gcittadino:cittadina;. È pericoloso andarsene in giro da queste parti. Se tieni alla pelle, al posto tuo non mi tratterrei troppo.$B$BSe fai domande brevi, vedrò di aiutarti. Tieni solo gli occhi aperti, caso mai spunti qualcuno di quei luridi ogre. Si dice che ci sia una base dell'Orda da qualche parte nelle paludi. Gli infiltrati fanno quel che possono per trovarla, ma il lavoro va a rilento e abbiamo fatto pochi progressi.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Private Hendel in Dustwallow Marsh.",
}
T[1267] = {
  title = "Il Diplomatico Scomparso",
  obj = "Parla con Jaina Proudmore, nel Dustwallow Swamp.",
  reward = "Lascia che sia io la prima a ringraziarti per tutto quel che hai fatto, $N. Sei $Gstato:stata; una benedizione incredibile per la mia gente e per quella di Stormwind. Mi dispiace non aver potuto fare la tua conoscenza in circostanze migliori.$B$BDevi anche capire che non posso ringraziarti apertamente per i tuoi sforzi, ma ti assicuro ancora una volta che sono apprezzati.$B$BQuando in futuro passerai da Theramore, vieni da me e cercherò di tenerti $Gaggiornato:aggiornata; sulla situazione.$B$BGrazie ancora, $N.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Jaina Proudmore in Dustwallow Swamp.",
}
T[1268] = {
  title = "Impronte di Zoccoli Sospette",
  desc = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Almeno alcune impronte sono ben visibili, e altre file di orme sono quasi impercettibili nel fango molle della palude.",
  obj = "Riferisci a Krog, a Brackenwall Village, delle impronte sospette alla Shady Rest Inn.",
  reward = "Impronte di zoccoli... Potrebbero essere stati i verrospini, suppongo. O forse perfino i centauri. La loro presenza nelle Barrens non è trascurabile, e non mi sembrerebbe esagerato pensarli capaci di un gesto simile.$B$BTe l'ho detto? Non hanno soltanto bruciato la locanda... La donna e il cucciolo del proprietario sono stati uccisi. Brutta faccenda.$B$BComunque, manderò Kagoro a scoprire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.",
}
T[1269] = {
  title = "Tenente Paval Reethe",
  desc = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Quando togli i detriti e la cenere incrostati sull'oggetto, appare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.$B$BSotto l'ancora è impresso in rilievo il nome \"Tenente Paval Reethe\".",
  obj = "Porta Reethe's Badge a Krog, a Brackenwall Village.",
  progress = "Hai trovato qualche pista su cosa è successo alla Shady Rest Inn?",
  reward = "Conosco questo umano, Paval Reethe. Patetico, perfino per quelli della sua razza. Ha abbandonato i suoi commilitoni e ora si nasconde nei boschi.$B$BHo mandato Ogron a cercarlo. Alcuni dei nostri sospettano che ci rubi le provviste. Mi pare di aver visto Ogron dirigersi a sud-est.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Krog in Brackenwall Village.",
}
T[1270] = {
  title = "La Fuga di Puzzone",
  desc = "Meno male, finalmente qualcosa che non vuole mangiarmi!!$B$BMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.$B$BUn goblin di Ratchet che si chiama Mebok Mizzyrix ha bisogno di foglie di trifoglio d'acqua per una pozione, o roba simile... Sinceramente non m'importa il perché — pagava bene e io questa palude la conosco, quindi eccomi qui.$B$BPeccato che mi sia fatto circondare prima di trovare il trifoglio! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco la pianta di Mebok?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Mebok Mizzyrix, a Ratchet.",
  reward = "Puzzone è passato di qui con le erbe che gli avevo chiesto, e mi ha detto che l'hai tirato fuori dai guai. Ottimo lavoro! Chi è amico di Puzzone è amico mio!$B$BMi ha chiesto di darti questo se mai ti avessi visto, poco prima di tornarsene a sud, verso la palude.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",
}
T[1271] = {
  title = "Banchetto al Blue Recluse",
  reward = "Mio nipote mi ha detto che l'hai aiutato nelle sue ricerche nel Dustwallow e che hai tirato fuori dai guai il suo socio. Beh, noi Stern restiamo uniti e non ci dimentichiamo dei nostri amici!$B$BQuindi lavati le mani, $N, perché stiamo per dare una festa in tuo onore!",
  en_title = "Feast at the Blue Recluse",
}
T[1273] = {
  title = "Interrogare Reethe",
  desc = "Ci è voluto tanto, ma ho trovato Reethe. Lui si nasconde bene, per un umano.$B$BOgron ha paura che lui è diventato matto dopo tanto tempo in palude. Tu vieni con me che andiamo a prendere risposte da lui.",
  obj = "Vai con Ogron a parlare con Reethe, poi torna da Krog, a Brackenwall Village.",
  progress = "Hai trovato Reethe?",
  reward = "Hmph. È un bene che Reethe non si aggiri più per la palude, ma peccato che gli umani siano fatti così fragili: non è riuscito a riprendersi da una piccola ferita di freccia.$B$BSembra che questa pista del mistero non abbia portato da nessuna parte, e dobbiamo cercare altrove.",
  en_title = "Questioning Reethe",
  en_obj = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.",
}
T[1274] = {
  title = "Il Diplomatico Scomparso",
  desc = "Scusami, $Gsignore:signora;. Il Vescovo DeLavey mi ha chiesto di rivolgermi agli avventurieri che potrebbero aiutarlo in una faccenda delicata.$B$BSe puoi andare al Mastio di Stormwind senza dare nell'occhio e parlargli appena ti è possibile, sono sicuro che apprezzerà il tuo aiuto. Te lo ripeto, ti prego, sii $Gdiscreto:discreta;. È una faccenda di una certa importanza.",
  obj = "Trova Bishop DeLavey nel Mastio di Stormwind.",
  reward = "Salve, $N. Sono il Vescovo DeLavey.$B$BSe mi chiedi dei miei affari qui nel mastio, di sicuro il giovane Thomas è riuscito a reclutarti per aiutare il nostro regno. È sempre stato bravo a eseguire le mie richieste.$B$BTemo di non avere tempo per dilungarmi, quindi lascia che sia schietto... e ti prego, fa' in modo che la cosa non si sappia in giro.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Bishop DeLavey in Stormwind Keep.",
}
T[1275] = {
  title = "Studiare la Corruzione",
  desc = "Gli sciocchi elfi del sangue trafficano con la magia demoniaca. Non hanno visto cosa è successo ai naga e ai satiri di Kalimdor?$B$BTemo che gli elfi del sangue vadano incontro a una deformazione simile. Azeroth non può permettersi di dare alla luce un'altra razza immonda di mostri.$B$BDesidero studiare i tronchi encefalici dei satiri e dei naga, per dedurre verso quale destino siano diretti gli elfi. Nelle Blackfathom Deeps, sulla costa di Ashenvale, troverai sia satiri sia naga.$B$BÈ un lungo viaggio, $N.",
  obj = "Gershala Nightwhisper, ad Auberdine, vuole 8 Corrupted Brain Stem.",
  progress = "Una volta che avrò abbastanza campioni da studiare, potrà cominciare il mio vero lavoro. Con i tronchi encefalici corrotti dei satiri e dei naga delle Blackfathom Deeps posso provare a stabilire una correlazione tra le mutazioni.$B$BForse, con quella conoscenza, potremo impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.",
  reward = "Hai viaggiato a lungo e senza dubbio hai affrontato grandi pericoli.$B$BLe tue azioni sono state altruiste. È per il bene di tutta Azeroth che mi aiuti nella mia ricerca. Ti ringrazio, $N, per tutto quello che hai fatto.$B$BOra, se vuoi scusarmi, ho molto lavoro da fare...",
  en_title = "Researching the Corruption",
  en_obj = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",
}
T[1276] = {
  title = "Lo Scudo Nero",
  desc = "Ah, ora ricordo! Mosarn è un fabbro molto stimato di Thunder Bluff. Sapevo di aver già sentito il suo nome da qualche parte.$B$BPer ringraziarmi, il Circolo della Terra mi ha donato un'armatura forgiata da Mosarn. Ottimo lavoro.$B$BForse può dirti di più sullo scudo che ha forgiato.$B$BNon è una gran pista, ma visto che da Reethe non abbiamo ricavato niente di utile, è tutto quello che abbiamo.",
  obj = "Mostra il Blackened Iron Shield a Mosarn, a Thunder Bluff.",
  progress = "Salve, $C. Posso aiutarti in qualcosa?",
  reward = "Sì, hai proprio ragione. Questo scudo l'ho fatto io.$B$BTemo però di non poterti dire molto altro, $N. Forgio così tanti scudi e armature diversi che non riesco a ricordarmeli tutti.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.",
}
T[1282] = {
  title = "Lo Chiamano Smiling Jim",
  desc = "Non posso farci niente se mi dispiace per il vecchio Jim, laggiù. Non è sempre stato così. Per un po' ha gestito una locanda là fuori nella palude, un posto meraviglioso.$B$BSenti, non ho proprio voglia di parlarne. Parlane con il Capitano Vimes, se proprio devi.",
  obj = "Parla con Captain Garran Vimes, a Theramore.",
  reward = "Il suo vero nome è James Hyal. Ha aperto una locanda al limitare delle Barrens. Voleva creare un bel posto dove i viaggiatori potessero fermarsi...$B$BForse puntava troppo in alto, ma per un po' la locanda è andata bene. Poi abbiamo perso il controllo delle strade nella palude, e se ne sono impadroniti gli ogre.$B$BJames era troppo testardo per rinunciare al suo sogno in cambio della sicurezza dentro le nostre mura, e la Shady Rest Inn è stata rasa al suolo dalle fiamme. Stiamo indagando, ma finora con poca fortuna. Se vuoi dare una mano, guarda cosa riesci a trovare tra le macerie.",
  en_title = "They Call Him Smiling Jim",
  en_obj = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.",
}
T[1284] = {
  title = "Impronte di Zoccoli Sospette",
  desc = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Almeno alcune impronte sono ben visibili, e altre file di orme sono quasi impercettibili nel fango molle della palude.",
  obj = "Riferisci a Captain Garran Vimes, a Theramore, delle impronte sospette alla Shady Rest Inn.",
  reward = "Impronte di zoccoli, eh? È vero che nelle terre vicino al Dustwallow Marsh i centauri sono straordinariamente attivi. Durante brevi spedizioni nelle Barrens abbiamo trovato i loro accampamenti e i loro possedimenti sparsi per tutta la zona.$B$BManderò Falgran Hastil, uno dei nostri esploratori, a vedere se riesce a scoprire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.",
}
T[1285] = {
  title = "Gli Uomini di Daelin",
  desc = "Reddon... Redpath... Ah, eccolo! Tenente Paval Reethe.$B$BEntrato nella guardia di Theramore insieme alla maggior parte delle reclute che hanno attraversato il mare con Lady Proudmoore. Arruolato nella fanteria di marina di Kul Tiras a sedici anni. Servizio encomiabile, promozioni...$B$BRisulta disperso.",
  obj = "Riporta a Captain Garran Vimes, a Theramore, le informazioni su Reethe.",
  reward = "Disperso? È il modo gentile di Tesoran per dire traditore.$B$BSenza dubbio è uno di quegli stolti così ciecamente fedeli all'Ammiraglio Daelin da diventare un traditore. Non è un'ironia squisita? I disertori accusano noi di tradire l'Alleanza.",
  en_title = "Daelin's Men",
  en_obj = "Return the information about Reethe to Captain Garran Vimes in Theramore.",
}
T[1286] = {
  title = "I Disertori",
  desc = "Restare nella palude è stata una lotta, ma con la forza della nostra determinazione siamo riusciti a mantenere diverse torri di guardia difensive in tutta la zona.$B$BLe ultime informazioni e i rapporti degli esploratori che ho ricevuto indicano che un gruppo di disertori ha occupato la nostra torre abbandonata al Presidio Perduto, a sud-est della locanda.$B$BIl capo dei disertori è un uomo di nome Jacken. Vedi se riesci a cavargli qualche informazione.$B$BTi avverto, $N. Potrebbe essere un osso duro.",
  obj = "Ottieni informazioni su Reethe da Balos Jacken e dai disertori, nel Dustwallow Marsh.",
  reward = "Ti ha mandato Vimes? Non poteva fare il lavoro sporco da solo, eh...",
  en_title = "The Deserters",
  en_obj = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.",
}
T[1287] = {
  title = "I Disertori",
  desc = "Reethe? Quel codardo?$B$BL'abbiamo cacciato dal campo perché si ostinava a razziare le provviste degli ogre su a Brackenwall Village. Non siamo abbastanza numerosi da poter tener testa a quei bruti senza cervello.$B$BHa passato il segno una volta di troppo, così l'abbiamo lasciato a cavarsela da solo.$B$BSenti, io ti ho aiutato... Allora perché non aiuti noi e ti dimentichi di averci incontrati?",
  obj = "Parla con Captain Garran Vimes, a Theramore, di Reethe.",
  reward = "Manderò il Tenente Caldwell a occuparsi dei disertori al Presidio Perduto. Inoltre gli darò ordine di trovare Reethe. La palude non è così vasta e impervia da impedirgli di trovarlo.",
  en_title = "The Deserters",
  en_obj = "Speak with Captain Garran Vimes in Theramore about Reethe.",
}
T[1288] = {
  title = "Il Rapporto di Vimes",
  desc = "Hai fatto un buon lavoro, $N, il migliore che abbia mai visto da parte di $Gun dilettante:una dilettante;.$B$BLady Proudmoore mi ha chiesto di tenerla informata su questa situazione delicata, e ormai è da un po' che non le parlo.$B$BAvevo intenzione di consegnarle il mio rapporto più tardi, ma mi sembra più giusto che sia tu a parlargliene. Probabilmente puoi rispondere alle sue domande meglio di me.",
  obj = "Porta Vimes's Report a Lady Jaina Proudmoore, a Theramore.",
}
T[1289] = {
  title = "Il Rapporto di Vimes",
  desc = "Bene, a giudicare dal rapporto del Capitano Vimes, hai dato un enorme aiuto alla sua indagine, e per questo ti ringrazio.$B$BMi sento più tranquilla sapendo che la faccenda è in mani così capaci. Se non ti dispiace, ti chiederei di tornare dal Capitano Vimes e di aiutarlo a venire a capo di questo mistero.",
  obj = "Torna da Captain Garran Vimes, a Theramore.",
}
T[1301] = {
  title = "James Hyal",
  desc = "Prima di lavorare qui al Blue Recluse, ho imparato il mestiere da uno dei migliori cuochi e locandieri che abbia mai conosciuto. Si chiamava James Hyal. Tutto quel che ho e tutto quel che ho raggiunto nella vita lo devo a lui.$B$BMi chiedo come se la passi. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma da un po' non ho sue notizie.$B$BSe mai dovessi andare da quelle parti, magari potresti salutarlo da parte mia?",
  obj = "Parla con Vincent Hyal, a Menethil Harbor.",
  reward = "James? Oh, se n'è andato parecchio tempo fa.$B$BGli è tornato il fervore patriottico, immagino. Non è difficile capire perché. Con tutta la follia che c'è in Lordaeron, molti si sono uniti a Jaina Proudmoore quando ha attraversato il mare.",
  en_title = "James Hyal",
  en_obj = "Speak with Vincent Hyal in Menethil Harbor.",
}
T[1302] = {
  title = "James Hyal",
  desc = "Mio fratello James è partito con Lady Proudmoore oltre il mare. L'ultima volta che ne ho avuto notizia, laggiù i combattimenti si erano calmati e James stava aprendo una locanda da qualche parte sul continente. Ovunque sia, sono sicuro che gli affari gli vanno bene. Un gran cuoco, accidenti se lo era.$B$BNon ho sue notizie da un pezzo ormai — troppo preso dalla locanda, scommetto — ma il cancelliere di Theramore potrebbe indicarti dove trovarlo.",
  obj = "Parla con Clerk Lendry, a Theramore.",
  reward = "James Hyal, James Hyal... Perché quel nome mi suona così familiare?$B$BMa certo! L'incidente della Shady Rest Inn. Se sai qualcosa di quello che è successo laggiù, ti consiglio vivamente di parlarne con il Capitano Vimes. È lui che segue le indagini.",
  en_title = "James Hyal",
  en_obj = "Speak with Clerk Lendry at Foothold Citadel in Theramore.",
}
T[1318] = {
  title = "Una Faccenda dei Gordok in Sospeso",
  desc = "Ora tu re, così magari tu riprende prezioso artefatto dei Gordok da elfo inquietante che si fa chiamare Principe! Re prima di te ha fallito, come tutti altri re da quando Tortheldrin — elfo inquietante — l'ha rubato a re Gordok di vecchi tempi!$B$BArtefatto si chiama Guanto della Forza Gordok. Storie di vecchi tempi dice che solo unico vero re di Gordok può riprenderlo. Storia di vecchi tempi dice anche che elfo inquietante è ancora qui in giro — tu lo trovi e lui diventa guanto potente che tu porti per sempre! Yar, io ti faccio vedere!",
  obj = "Trova il Gauntlet of Gordok Might e riportalo a Captain Kromcrush a Dire Maul.$B$BSecondo Kromcrush, la \"storia di vecchi tempi\" dice che Tortheldrin — un elfo \"inquietante\" che si faceva chiamare principe — lo rubò a uno dei re dei Gordok.",
}
T[1319] = {
  title = "Lo Scudo Nero",
  desc = "Mi dispiace non poterti essere di grande aiuto, $N, ma posso indirizzarti da qualcuno che può esserlo. Caz Twosprocket, uno dei nostri migliori fabbri, lavora alla forgia, nella bottega del fabbro.$B$BPortagli lo scudo e senti cosa sa dirti.",
  obj = "Mostra il Blackened Iron Shield a Caz Twosprocket, a Theramore.",
  progress = "Qualcosa da farmi vedere?",
  reward = "Hm... interessante questo pezzo di ferro che hai qui. Di sicuro non l'ha fatto nessuno dei fabbri che conosco da questa parte del mare, e di certo non è opera mia.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.",
}
T[1320] = {
  title = "Lo Scudo Nero",
  desc = "Ah, per poco non mi sfuggiva... La cinghia di cuoio sul retro dev'essere bruciata, ma sembra fatta per una persona grossa. Anzi, direi proprio un tauren.$B$BÈ più o meno tutto quello che posso dirti. Di' al Capitano Vimes che mi dispiace di non aver potuto aiutare di più.",
  obj = "Parla con Captain Garran Vimes, a Theramore.",
  reward = "Non sono molte informazioni su cui lavorare, ma dovremo tenerne conto. Speriamo che altri pezzi di questo mistero vadano al loro posto e ci diano un quadro più utile di quello che è successo.",
  en_title = "The Black Shield",
  en_obj = "Speak with Captain Garran Vimes in Theramore.",
}
T[1321] = {
  title = "Lo Scudo Nero",
  desc = "Hmm... non vedo niente di strano in questo scudo. Dovremmo farlo vedere a Do'gol, il fabbro, e sentire se può dirci qualcosa di più, ma non ci spererei troppo...",
  obj = "Mostra il Blackened Iron Shield a Do'gol, a Brackenwall Village.",
  progress = "Qualcosa per me, $C?",
  reward = "Questo è un scudo buono. Molto forte, pesante, buono. Ma a Do'gol non gli serve. Io gli scudi li faccio, non li compro, $N.$B$BDovresti saperlo.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.",
}
T[1322] = {
  title = "Lo Scudo Nero",
  desc = "Hmmm, c'è una scritta proprio qui sul bordo dello scudo, ma non si legge bene per tutta 'sta roba bruciata.$B$BMi serve dell'acido per farla venire fuori chiara. Il veleno dei ragni Darkfang della palude va bene. Portami un po' delle loro sacche e te lo ripulisco io.",
  obj = "Procura 6 Acidic Venom Sac per Do'gol, a Brackenwall Village.",
  progress = "Le hai prese quelle sacche dai ragni?",
  reward = "Non mi piacciono i ragni così grossi che non ci posso sedere sopra e spiaccicarli.$B$BGrazie di averle prese, $N. Adesso le squarcio e le verso sullo scudo...",
  en_title = "The Black Shield",
  en_obj = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.",
}
T[1323] = {
  title = "Lo Scudo Nero",
  desc = "Oh, credo di aver versato troppo acido sullo scudo. Fammi solo strofinare un po'...$B$BHm, si legge a fatica, ma sembra il nome Mosarn. Mai sentito nominare. Forse Krog lo sa. Krog conosce tanta gente.",
  obj = "Parla con Krog, a Brackenwall Village.",
  reward = "Mosarn? Mi dice qualcosa... ma non riesco a ricordare cosa. Forse mi verrà in mente più tardi.$B$BProbabilmente non è importante. Uno scudo può venire da qualsiasi parte e non significare niente...",
  en_title = "The Black Shield",
  en_obj = "Talk with Krog in Brackenwall Village.",
}
T[1324] = {
  title = "Il Diplomatico Scomparso",
  desc = "Cosa?! Vieni qui ad accusarmi di essermi alleato con i Defias, e pensi che me ne starò qui fermo mentre mi insulti?! Qualcosa mi dice che te la sei cercata da un pezzo.",
  obj = "Sconfiggi Private Hendel, nel Dustwallow Marsh.",
  progress = "Rieccoti, $N. Spero non ti dispiaccia l'aiuto, ma non potevamo permetterci che Hendel scappasse o, peggio, che ci restasse secco.",
  reward = "Ti assicuro che siamo tutti parecchio scossi da quel che sta succedendo, ma lascia che lo riportiamo a Theramore per interrogarlo, e vedremo di trovare il Re.$B$BSono sicuro che la mia signora Proudmore vorrà ringraziarti per l'aiuto. Parlale quando hai un momento.",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Private Hendel in Dustwallow Marsh.",
}
T[1360] = {
  title = "Tesori Recuperati",
  desc = "Avevo un bel lavoro come scavatore al sito di scavo di Uldaman, nelle Badlands... finché non sono arrivati quei maledetti trogg. Me la sono cavata con la pelle a malapena intera, e nient'altro. Nel caos ho lasciato il mio bene più prezioso. Nel mio forziere è al sicuro dai trogg, certo, ma si trova proprio in mezzo a loro.$B$BTi sarei debitore, sia in onore sia in monete, se potessi andarlo a prendere per me! In fondo alla Sala Comune Nord c'è un forziere con il mio nome sopra. È quello che devi aprire.",
  obj = "Prendi il bene più prezioso di Krom Stoutarm dal suo forziere nella North Common Hall di Uldaman, e portalo a Krom, a Ironforge.",
  progress = "Allora, sei $Griuscito:riuscita; a prendere a sberle quei trogg abbastanza a lungo da aprire il mio forziere e arraffare il mio tesoro?",
  reward = "Ah, mi sento di nuovo completo: grazie di cuore.$B$BAlcuni nani apprezzano la lucentezza del metallo, e altri lo scintillio delle gemme... ma uno Stoutarm senza il suo prezioso boccale in mano non si può nemmeno chiamare uno Stoutarm!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.",
}
T[1361] = {
  title = "Regthar Deathgate",
  desc = "Un guerriero dell'Orda, Regthar Deathgate, sta reclutando agenti per una missione nella terra di Desolace. Parla con lui se vuoi offrirti come $Gvolontario:volontaria;. È di stanza nelle Barrens, in una serie di bunker a ovest del Crossroads.$B$BE affila le armi. Desolace è un luogo dilaniato dalla guerra.",
  obj = "Parla con Regthar Deathgate.",
  reward = "Sì, sto reclutando. Questa missione porta a Desolace, contro i centauri che ci vivono. Sarò breve, così potrai cominciare subito.",
  en_title = "Regthar Deathgate",
  en_obj = "Speak with Regthar Deathgate.",
}
T[1362] = {
  title = "I Kolkar di Desolace",
  desc = "I centauri Kolkar vivono a Desolace, e le loro forze si sono estese fino alle Barrens. È un fatto noto, e qui abbiamo agenti dell'Orda che se ne occupano.$B$BMa finché i centauri saranno forti a Desolace, saranno sempre una minaccia. È ora di liberarci di quella minaccia.$B$BParla con Felgur Twocuts al Ghost Walker Post, a Desolace. È stato mandato a raccogliere informazioni sui centauri. Saprà come affrontare al meglio i Kolkar di Desolace.",
  obj = "Parla con Felgur Twocuts al Ghost Walker Post, a Desolace.",
  reward = "Sei qui per ordine di Regthar? Allora sei qui per occuparti dei centauri. Bene.$B$BSpero che tu sia $Griposato:riposata;. Non so come finirà la nostra campagna contro i centauri, ma so che la lotta sarà lunga.$B$BSiediti e ascolta.",
  en_title = "The Kolkar of Desolace",
  en_obj = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.",
}
T[1363] = {
  title = "L'Incarico di Mazen",
  desc = "In quanto custode delle opere di questa biblioteca dell'Academy of Arcane Arts and Sciences, è mia responsabilità assicurarmi che tutti i tomi e le pergamene magiche siano sempre al loro posto. Chissà quali follie succederebbero se alcuni di questi testi incantati finissero nelle mani sbagliate?$B$BA proposito... il mio assistente, Dellis, la settimana scorsa ha fatto un errore terribile. In biblioteca se la cava bene, ma quando esce dalle porte di Stormwind è un incapace. Sii $Gun eroe:un'eroina; e aiuta il vecchio Dellis, ti va?",
  obj = "Parla con Acolyte Dellis, a Stormwind.",
  reward = "Non è stata colpa mia. Davvero, non è stata colpa mia.",
  en_title = "Mazen's Behest",
  en_obj = "Speak with Acolyte Dellis in Stormwind.",
}
T[1364] = {
  title = "L'Incarico di Mazen",
  desc = "Le istruzioni del Maestro Mazen erano chiarissime: consegnare un saggio importantissimo all'Osservatore Mahar Ba, a Nethergarde Keep.$B$BMa io non ero mai stato nelle Blasted Lands! Il viaggio è stato spaventoso!$B$BQuando sono arrivato nella Swamp of Sorrows, ho sbagliato strada e mi sono ritrovato circondato da orribili creature della palude simili a piante. Barcollavano verso di me come per attaccarmi, e così sono scappato. Ma nella fretta mi è caduto il saggio. Una di quelle bestie l'ha preso, ne sono sicuro.$B$BPotresti provare a recuperarlo e consegnarlo a Mahar Ba?",
  obj = "Recupera Khadgar's Essays on Dimensional Convergence e consegnali a Watcher Mahar Ba, a Nethergarde Keep.",
  progress = "Che cosa ti porta a Nethergarde Keep, $R?",
  reward = "Ah, splendido!$B$BPer un po' ho temuto che la mia richiesta del Saggio di Khadgar sulle Convergenze Dimensionali fosse stata trascurata dal Maestro Mazen dell'Academy of Arcane Arts and Sciences.$B$BDev'essere sommerso di richieste, visti i tanti strani avvenimenti in corso.$B$BOra, se vuoi scusarmi, devo cominciare subito le mie ricerche. Poter finalmente intravedere il pensiero di un grande come Khadgar mi riempie di entusiasmo.",
  en_title = "Mazen's Behest",
  en_obj = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.",
}
T[1365] = {
  title = "Khan Dez'hepah",
  desc = "I Kolkar non sono gli unici centauri di Desolace. Molti clan vagano per queste pianure aride e si combattono fra loro fino alla morte. Ed è un bene che combattano tra loro, perché sono forti e brutali. Se i centauri si unissero contro di noi, sarebbero un nemico feroce.$B$BDobbiamo occuparci di loro prima che si uniscano.$B$BIl tuo primo compito è gettare nel caos il clan Kolkar. Per farlo, uccidi il suo capo, Khan Dez'hepah.$B$BIl Villaggio dei Kolkar è a nord-est di qui. Va', e che la fortuna ti accompagni.",
  obj = "Porta Khan Dez'hepah's Head a Felgur Twocuts, a Desolace.",
  progress = "$N, hai sconfitto Khan Dez'hepah?",
  reward = "Ben fatto. Questa rapida azione contro i Kolkar è un'efficace dimostrazione di forza, e la forza è ciò che i centauri capiscono meglio.$B$BLa morte del capo dei Kolkar non solo getterà nel caos quel clan, ma farà riflettere anche gli altri.",
  en_title = "Khan Dez'hepah",
  en_obj = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.",
}
T[1366] = {
  title = "Taglia sui Centauri",
  desc = "Ora che hai spaventato i clan dei centauri, è il momento di dissanguarli. Quando viaggi per Desolace, dai la caccia ai centauri. Non m'importa a quale clan. Raccogli orecchie e basta. Un mucchio di orecchie.$B$BRiducendo il loro numero indebolirai la loro determinazione e toglierai loro ogni voglia di espandersi.$B$BBuona caccia, $N.",
  obj = "Porta 15 Centaur Ear a Felgur Twocuts, a Desolace.",
  progress = "Come va la tua collezione di orecchie, $N? È grande?",
  reward = "Ormai i centauri devono conoscere il tuo nome. Sono sicuro che lo conoscono, lo rispettano e lo temono. E così come conoscono te, conoscono lo stendardo sotto cui cavalchi.$B$BLo stendardo dell'Orda.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",
}
T[1367] = {
  title = "Alleanza con i Magram",
  desc = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e grazie a loro impareremo a sconfiggere tutti i clan.$B$BSe scegli di allearti con i Magram, uccidi i loro nemici, i Gelkis. Così ti guadagnerai il rispetto dei Magram. Quando ne avrai abbastanza, incontra il portavoce dei Magram, Warug, ai margini del Villaggio dei Magram, nel sud-est di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.",
  progress = "Vattene! I Magram non parlano con i deboli. Noi li uccidiamo!$B$BSe vuoi parlare con me, dimostrami che sei forte. Torna dopo aver ucciso molti Gelkis.",
  reward = "I Gelkis piangono quando sentono il tuo nome, $N. Ti temono e ti odiano. Ti odiano come odiano i Magram!$B$BForse sei forte come i Magram. Vedremo...",
  en_title = "Magram Alliance",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1368] = {
  title = "Alleanza con i Gelkis",
  desc = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e grazie a loro impareremo a sconfiggere tutti i clan.$B$BSe scegli di allearti con i Gelkis, uccidi i loro rivali più odiati, i Magram. Dopo aver ottenuto il rispetto dei Gelkis, incontra la sciamana dei Gelkis, Uthek the Wise, ai margini del Gelkis Village, nel sud-ovest di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.",
  progress = "I tuoi due piedi calpestano la terra dei Gelkis. Qui non sei $Gbenvenuto:benvenuta;!$B$BDimostra che cerchi l'amicizia dei Gelkis. Uccidi i centauri Magram. Torna quando il terreno sarà bagnato di sangue Magram.",
  reward = "La terra mi parla. E dice che hai ucciso molti Magram. Questo è bene.$B$BSe sei $Gun amico:un'amica; dei Gelkis, allora ascolta. Ho altri compiti per te.",
  en_title = "Gelkis Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1369] = {
  title = "Lacrime Corrotte",
  desc = "I Gelkis pensano che Theradras, la madre di noi centauri, ci protegga. Sono stupidi. Nessuno protegge i centauri. I Magram non hanno bisogno di protezione! Siamo i più forti!$B$BMostra ai Gelkis che sono stupidi. Va' nella grotta del loro villaggio. In quella grotta accumulano cristalli, le lacrime di Theradras. Distruggi le lacrime e portami i pezzi rotti!",
  obj = "Mantieni la tua reputazione con i Magram e porta 3 Broken Tears a Warug, al Villaggio dei Magram.",
  progress = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!",
  reward = "Hai preso le lacrime! Ora i Gelkis sapranno che Theradras non li aiuterà. Non piangerà quando li schiacceremo! I Magram regneranno!$B$BSei $Gfurbo:furba; ad aiutarci, $N. Siamo i più forti.",
  en_title = "Broken Tears",
  en_obj = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.",
}
T[1370] = {
  title = "Rubare le Provviste",
  desc = "Quando non siamo in guerra, cacciamo per procurarci carne. La carne ci dà forza, e le pance piene combattono con più forza di quelle vuote.$B$BLo stesso vale per i Magram. Mettono da parte carne in più per poter combattere più a lungo tra una caccia e l'altra. Se fai razzia nel loro villaggio a est e prendi le loro scorte di carne, la loro forza verrà meno.",
  obj = "Porta 6 sacchetti di Crudely Dried Meat a Uthek the Wise, al Gelkis Village.",
  progress = "Torna dopo aver dimostrato ancora il tuo valore ai Gelkis!",
  reward = "Bene. Sento brontolare le rumorose pance dei Magram fin dal loro villaggio, lontano!$B$BDarò questa carne ai Gelkis. E combatteremo per molti giorni senza riposo.$B$BQuello che hai fatto è un bene per i Gelkis, $N.",
  en_title = "Stealing Supplies",
  en_obj = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.",
}
T[1371] = {
  title = "Un Aggeggio per Warug",
  desc = "Tanto tempo fa, un piccolo gnomo venne a Desolace. Aveva cavalli e un carro, e il carro conteneva cose strane. Cose buffe. Cose che bruciavano di colori diversi. Cose che si muovevano e non erano vive. Uccisi il piccolo gnomo, ma prima... mi fece ridere.$B$BMi tenni la cosa che mi piaceva di più del suo carro. Era un umano di legno, e mi salutava con la mano finché non lo colpii e lo ruppi.$B$BNe voglio uno nuovo. Portamene uno nuovo!",
  obj = "Mantieni la tua reputazione con i Magram e porta un Advanced Target Dummy a Warug, al Villaggio dei Magram, a Desolace.",
  progress = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!",
  reward = "Sì, è proprio quello che avevo! Lo farò muovere di nuovo. Mi fa ridere!",
  en_title = "Gizmo for Warug",
  en_obj = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.",
}
T[1372] = {
  title = "Nient'altro che la Verità",
  desc = "La nostra forza di spedizione è stata mandata per volere di Varimathras a perlustrare la parte bassa di Azeroth.$B$BMentre ero in ricognizione ho notato un Infiltrato umano che spiava il Torrione del Mendicante. Prima che riuscissi a catturarlo, alcuni dei nostri... fratelli... orchi l'hanno preso e portato a Stonard, la loro roccaforte nella Swamp of Sorrows.$B$BVoglio... aiutare... i nostri alleati orchi. Non hanno visto il nostro accampamento qui, ma voglio comunque dare una mano.$B$BLavora con Faustin, qui, per preparare un... siero della verità per il nostro amico a Stonard.",
  obj = "Parla con Apothecary Faustin a Beggar's Haunt.",
  reward = "Zraedus mi stava giusto parlando di quel ficcanaso di un Infiltrato, prima che arrivassi.$B$BUn bel problema, davvero. L'ultima cosa che ci serve è un impiccione che curiosa in giro per il Torrione del Mendicante.$B$BSono sicuro che gli orchi di Stonard sarebbero impazienti di sentire cosa ha da dire il nostro amico. Visto che sono nostri alleati, ehm, dobbiamo aiutarli a ottenere dall'umano tutte le informazioni che possono.$B$BLavora con me, $N, e porteremo un siero della verità a Stonard.$B$BPer l'Orda!$B$B...l'ho detto giusto?",
  en_title = "Nothing But The Truth",
  en_obj = "Speak with Apothecary Faustin at Beggar's Haunt.",
}
T[1373] = {
  title = "Ongeku",
  desc = "Hai ancora molto da dimostrare, e il tuo prossimo compito ti porterà lontano, quindi per ora i Gelkis combatteranno i Magram senza di te.$B$BLa terra sussurra molti segreti a chi ascolta. Uno dei segreti che sento parla di un cristallo rosso. Si chiama draenethyst, ed è nuovo per la nostra terra. Viene da un luogo dove le montagne volano e dove regnano i demoni.$B$BPortami una scheggia di draenethyst, e renderà forte la mia magia! La scheggia si trova in un luogo chiamato Swamp of Sorrows, nelle mani del perduto Ongeku.",
  obj = "Mantieni la tua reputazione con i Gelkis e porta una Draenethyst Shard a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.",
  reward = "Sì, questa è la scheggia di cui sussurrava la terra. Sento una magia potente al suo interno! Userò questa magia contro i nemici dei Gelkis.$B$BHai svolto un altro compito per noi, $N. Forse presto ti chiameremo $Gamico:amica;.",
  en_title = "Ongeku",
  en_obj = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1374] = {
  title = "Khan Jehn",
  desc = "La terra mi parla, e dice che i Magram si stanno indebolendo. Ora è il momento di uccidere il loro Khan!$B$BPortami la testa del Khan dei Magram, Jehn!",
  obj = "Porta la Khan Jehn's Head a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.",
  reward = "Khan Jehn era forte, ma stupido. Pensava che la sua forza fosse grande. Non vedeva che la magia della terra è più forte. Ora i centauri Magram cadranno senza il loro capo, e un giorno i Gelkis regneranno!",
  en_title = "Khan Jehn",
  en_obj = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1375] = {
  title = "Khan Shaka",
  desc = "Tu aiuti i Magram, e mi piaci. Ora uccidi il Khan dei Gelkis! È Khan Shaka, e voglio la sua testa! Voglio fissare la sua testa e ridere di lui!",
  obj = "Mantieni la tua reputazione con i Magram e porta la Khan Shaka's Head a Warug, al Villaggio dei Magram, a Desolace.",
  progress = "Fai qualche lavoro per i Magram, e io ti aiuterò.",
  reward = "Khan Shaka è morto! Metterò la sua testa su una picca e la terrò con me, così Shaka potrà vedere la forza dei Magram!",
  en_title = "Khan Shaka",
  en_obj = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.",
}
T[1380] = {
  title = "Khan Hratha",
  desc = "$N, ci hai aiutato contro i Magram. Ora aiutaci a battere i Maraudine! Uccidi il capo del loro clan, Khan Hratha!$B$BPer affrontarlo, suona il Corno da Guerra dei Maraudine. Si trova in cima a un'alta rupe nella Valle delle Lance.$B$BMa per suonare il corno ti serve un bocchino per il corno da guerra. Sono rari, e li portano solo i centauri Maraudine di fiducia.$B$BDopo che avrai suonato il corno, arriveranno i centauri. Uccidili finché non compare Hratha.$B$BKhan Hratha custodisce il pezzo di... una chiave. Portamelo...",
  obj = "Mantieni la tua reputazione con i Gelkis e porta il Maraudine Key Fragment a Uthek the Wise, al Gelkis Village.",
  progress = "Khan Hratha è morto? Hai il frammento di chiave?",
  reward = "È morto! Khan Hratha è morto! E ora i Maraudine cadranno! Quando i Gelkis regneranno su questa terra, $N, ci ricorderemo di te. E gli spiriti della terra canteranno il tuo nome per sempre.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.",
}
T[1381] = {
  title = "Khan Hratha",
  desc = "Il Khan dei Gelkis è morto, e ora cadranno i Maraudine! Uccidi il Khan dei Maraudine, Hratha!$B$BPer affrontarlo, suona il corno sull'alta rupe nella Valle delle Lance. Ma per suonare il corno ti serve un bocchino. Per avere un bocchino, uccidi i centauri Maraudine. Continua a ucciderli finché non trovi un bocchino. Poi suona il corno.$B$BFai questo e i centauri Maraudine verranno alla torre. Uccidili finché non compare Khan Hratha. Hratha ha il pezzo di una chiave. Dammi questo pezzo...",
  obj = "Mantieni la tua reputazione con i Magram e porta il Maraudine Key Fragment a Warug, al Villaggio dei Magram, a Desolace.",
  progress = "Fai quello che ti chiedo. Dimostrami che sei $Gun alleato:un'alleata; dei Magram!",
  reward = "Khan Hratha è morto! Ora i Magram sono i più forti tra i centauri! Schiacceremo gli altri e regneremo su Desolace!$B$BCi ricorderemo di te, $N, e sarai $Grisparmiato:risparmiata; dai nostri zoccoli quando tutti gli altri saranno calpestati.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.",
}
T[1382] = {
  title = "Una Strana Alleanza",
  desc = "Siamo fortunati che i clan dei centauri combattano tra loro, perché se si unissero in un'unica forza sarebbero inarrestabili. Sì, siamo fortunati, e dovremmo sfruttare il nostro vantaggio.$B$BUno dei clan dei centauri, il clan Gelkis, è impegnato in una guerra brutale contro il clan Magram. Se attacchiamo i Magram, forse potremo stringere un'alleanza con i Gelkis.$B$BParla con Uthek the Wise, ai margini degli accampamenti Gelkis nel sud-ovest di Desolace. Tramite lei potremmo stringere un'alleanza con i Gelkis.",
  obj = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.",
  progress = "Sparisci! I Gelkis non ti vogliono qui. Vattene subito!!$B$BTorna dopo aver ucciso molti Magram, e allora parlerò con te.",
  reward = "Tra i Gelkis si sussurra il tuo nome. Hai molto sangue dei Magram sulle mani. Questo è bene.$B$BForse è bene anche che parliamo. Parliamo di cosa puoi fare tu per i Gelkis, e di cosa possiamo fare noi per te.",
  en_title = "Strange Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1383] = {
  title = "Nient'altro che la Verità",
  desc = "Ho in mente proprio il siero giusto. Tratterà la verità esattamente come la verità va trattata.$B$BPer questo intruglio mi serviranno parecchi cuori di Pantera dell'Ombra della Swamp. Mi serve anche il fungo incantato del Signore del Brago che vive laggiù. Sono sicuro che qualcuno in gamba come te, $N, saprà convincerlo a cedertene un po'.$B$BOra, la parte difficile sarà trovare un tumore di Deepstrider nella lontana Desolace. Molto di rado i giganti di laggiù si ammalano e si forma un tumore.$B$BOra, va'!",
  obj = "Apothecary Faustin, a Beggar's Haunt, ha bisogno di 5 Shadow Panther Heart, del Mire Lord Fungus e di un Deepstrider Tumor.",
  progress = "Quell'Infiltrato a Stonard di sicuro... si aprirà... dopo aver bevuto il mio siero speciale. Ahah!$B$BGli ingredienti che servono non sono affatto facili da procurare. Le Pantere dell'Ombra sono comuni nella Swamp, ma raccogliere abbastanza cuori per il nostro scopo può essere un'impresa. E il Signore del Brago sa essere una bestia molto capricciosa.$B$BQuanto al tumore di Deepstrider, è terribilmente difficile da trovare. Ma la reazione chimica che posso ricavarne non ha eguali.",
  reward = "Splendido, $N! E proprio in tempo. Da quel che mi dice Zraedus, l'Infiltrato si è ripreso dalle ferite ed è pronto per essere interrogato dagli orchi.$B$BDammi solo un momento per preparare il vel — voglio dire, per preparare il siero della verità.",
  en_title = "Nothing But The Truth",
  en_obj = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor.",
}
T[1384] = {
  title = "Incursione Contro i Kolkar",
  desc = "I centauri Kolkar pensano che la loro magia sia forte. Non sanno cos'è la magia! Non la riconoscerebbero nemmeno se li mordesse!$B$BSarai tu a mostrargli che la loro magia è debole. Va' dai Kolkar a nord-est e uccidili. Prendi i loro amuleti. Portami gli amuleti e io li getterò nel fuoco e riderò!",
  obj = "Mantieni la tua reputazione con i Gelkis e porta 10 Crude Charm a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Hai gli amuleti? Hai mostrato ai Kolkar che sono deboli?",
  reward = "Fai una cosa buona per i Gelkis. I Kolkar sono deboli e moriranno. La loro magia è patetica e non li salverà. Tu gliel'hai mostrato, e la loro paura li renderà ancora più fiacchi!$B$BE nelle nostre terre, chi è fiacco muore presto.",
  en_title = "Raid on the Kolkar",
  en_obj = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1385] = {
  title = "Politica Brutale",
  desc = "Desolace è una terra in guerra. I centauri si fanno guerra tra loro, e crediamo che il vincitore finirà per dilagare e minacciare le nostre roccaforti. Questo non possiamo permetterlo.$B$BDobbiamo imparare a battere i centauri, e per farlo... dobbiamo allearci con uno dei clan. I centauri Magram sono in guerra con i Gelkis. Se combatti i Gelkis, i Magram potrebbero prendere in considerazione un'alleanza.$B$BGuadagnati il favore dei Magram, poi parla con Warug, nel villaggio dei Magram, nel sud-est di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.",
  progress = "Ora te ne vai, o i Magram ti schiacceranno! Per essere $Gnostro amico:nostra amica;, devi uccidere i Gelkis.",
  reward = "Molti Gelkis cadono per mano tua. Mi piace. Forse puoi fare altre cose che mi piacciono. Forse tu e i Magram potete essere amici.",
  en_title = "Brutal Politics",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1386] = {
  title = "Assalto ai Kolkar",
  desc = "I Kolkar pensano di essere forti, ma noi ridiamo di loro! Ridiamo e li uccidiamo! Uccidili anche tu. Dimostrami che sai uccidere i Kolkar come facciamo noi. Va' a nord e sterminali tutti!",
  obj = "Mantieni la tua reputazione con i Magram. Uccidi 12 Kolkar Centaur, 12 Kolkar Scout e 6 Kolkar Mauler, poi torna da Warug, al Villaggio dei Magram, a Desolace.",
  progress = "Hai paura dei Kolkar? Perché non li uccidi? Forse hai dimenticato come si uccide. Sbrigati e uccidi i Kolkar prima che siano morti!",
  reward = "Ora i Kolkar hanno paura di te! Spero che tu abbia riso mentre li uccidevi. È meglio ridere quando uccidi, così il nemico vede che è debole.",
  en_title = "Assault on the Kolkar",
  en_obj = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.",
}
T[1387] = {
  title = "Taglia sui Centauri",
  desc = "La razza dei centauri è formata da molti clan. Ognuno ha il suo capo e i suoi scopi, ma tutti i clan hanno una cosa in comune. La crudeltà.$B$BSe un giorno vogliamo trovare la pace, i centauri vanno eliminati. E perciò affido a te proprio questo compito.$B$BMentre giri per Desolace, dai la caccia ai centauri e prendi le loro orecchie. Portami tante, tante orecchie.$B$BFallo al servizio dell'Alleanza, $N, e saremo un passo più vicini alla fine della guerra.",
  obj = "Porta 15 Centaur Ear a Corporal Melkins, a Nijel's Point, a Desolace.",
  progress = "Hai un rapporto per me, $N?",
  reward = "Ah, le orecchie. Ben fatto.$B$BIl tuo servizio all'Alleanza è fuori discussione, $N. Il sangue che hai versato a Desolace salverà, senza dubbio, innumerevoli vite.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.",
}
T[1388] = {
  title = "Nient'altro che la Verità",
  desc = "Tutto procede secondo i piani, $N. Voglio che tu dia questo siero della verità all'Inseguitore della Morte Zraedus, e lui ti mostrerà come somministrarlo... come si deve.$B$BAhah!",
  obj = "Dai Faustin's Truth Serum a Deathstalker Zraedus, a Beggar's Haunt.",
  progress = "Spero che tu ti sia $Gdimostrato:dimostrata; utile al nostro caro amico, lo Speziale Faustin.",
  reward = "Sapevo che il vecchio Faustin avrebbe tirato fuori qualcosa di buono! Sei $Gstato:stata; di grandissimo aiuto, non c'è dubbio.$B$BOra mettiamoci al lavoro, che ne dici?",
  en_title = "Nothing But The Truth",
  en_obj = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.",
}
T[1389] = {
  title = "Cristalli di Draenethyst",
  desc = "I perduti che vivono nel Santuario dei Perduti hanno il nostro aspetto, ma sono mostri... impazziti per le fatiche del nostro viaggio verso Azeroth. Un tempo erano nostri fratelli, ora vivono nel Santuario dei Perduti a est, e catturano o uccidono chiunque si avvicini.$B$BE ci hanno rubato qualcosa di sacro — i cristalli di draenethyst.$B$BNon abbiamo le forze per entrare nel Santuario dei Perduti e riprenderci il draenethyst che ci hanno rubato, tra le loro capanne e i loro fuochi, ma senza quei cristalli... anche noi potremmo smarrire la via.",
  obj = "Porta 6 Draenethyst Crystal a Magtoor, all'Harborage, nella Swamp of Sorrows.",
  progress = "Hai i cristalli?",
  reward = "Grazie, $N. Noi, siamo in debito con te.",
  en_title = "Draenethyst Crystals",
  en_obj = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.",
}
T[1390] = {
  title = "Ops, li Abbiamo Uccisi di Nuovo.",
  desc = "Testo mancante.",
  obj = "Testo mancante.",
  reward = "Grazie per il lavoro fatto!",
}
T[1391] = {
  title = "Nient'altro che la Verità",
  desc = "Dobbiamo agire con una certa discrezione. Dopotutto, non è che puoi entrare lì con disinvoltura e convincere quell'idiota a bere l'intruglio di Faustin, giusto?$B$BMa se c'è una cosa a cui quegli umani non sanno dire di no, è l'alcol. Prenderò il siero di Faustin e lo mescolerò a questa birra. Ti garantisco che quel poveraccio non esiterà un attimo a tracannarsi un boccale.$B$BSbrigati a raggiungere Stonard, nella Swamp of Sorrows, $N. E mi raccomando, acqua in bocca sulla nostra piccola missione...",
  obj = "Porta Zraedus's Brew a Infiltrator Marksen, a Stonard.",
  progress = "Ti prego, abbi pietà di me! Ho informazioni che vanno oltre gli schieramenti. Non sono un simpatizzante dell'Orda, ma c'è in atto un tradimento politico che deve essere svelato!",
  reward = "Da bere per me? Che gentile. Sono giorni che non mi lasciano bere. Fammi mandare giù questa, e poi ti dirò quello che ho scoperto...",
  en_title = "Nothing But The Truth",
  en_obj = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.",
}
T[1392] = {
  title = "Noboru il Randello",
  desc = "Da mesi Noboru tormenta i Draenei dell'Harborage, e il suo randello è il simbolo della brutalità che hanno subito per mano dei perduti.",
  obj = "Porta Noboru's Cudgel al capo dell'Harborage, nella Swamp of Sorrows.",
  progress = "Salve. E $Gbenvenuto:benvenuta; all'Harborage.",
  reward = "Hai conquistato l'arma del temuto Noboru? Allora è morto?$B$BÈ un giorno di gioia per l'Harborage. Noboru e la sua banda erano il nostro terrore: vagavano per le paludi e uccidevano tutti i Draenei che incrociavano la sua strada. Era una minaccia diretta alla nostra sopravvivenza, e non avevamo la forza di affrontarlo.$B$BSiamo fortunati ad avere in te $Gun amico:un'amica;, $N.",
  en_title = "Noboru the Cudgel",
  en_obj = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.",
}
T[1393] = {
  title = "La Fuga di Galen",
  desc = "Aiuto, ti prego! Queste creature stanno per mangiarmi!$B$BAiutami a uscire di qui, e ti darò un grande tesoro! È nel mio accampamento nella palude, a nord di Stonard, ma è chiuso in un forziere che si apre con un trucco che conosco solo io.$B$BSe mi aiuti a scappare, te lo insegnerò.",
  obj = "Scorta Galen fino a un luogo sicuro, poi trova il suo accampamento nella Swamp of Sorrows e apri il suo forziere.",
  progress = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.",
  reward = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.$B$BMa Galen ti ha parlato di un fermo nascosto sul fondo del forziere...$B$B...Dopo una breve ricerca, trovi il fermo. Lo fai scattare, e il forziere si apre...",
  en_title = "Galen's Escape",
  en_obj = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.",
}
T[1394] = {
  title = "Il Passaggio Finale",
  desc = "Hai fatto un buon lavoro, $N. Hai superato la mia prova e quelle prima della mia. Torna da Dorn, a Thousand Needles. Sentirà il cambiamento dentro di te e vedrà che la tua mente, il tuo corpo e il tuo spirito sono abbastanza forti da meritare una ricompensa per quel che hai fatto.$B$BResta fedele all'equilibrio che hai mostrato in tutte queste prove, $N. Se lo farai, in futuro Dorn ti metterà di nuovo alla prova.",
  obj = "Parla con Dorn Plainstalker, a Thousand Needles.",
  reward = "Ah, $N. È passato molto tempo dall'ultima volta che hai messo piede in casa mia. Sembrano passate molte lune da quando hai fatto il primo salto che ti ha messo sul tuo cammino.$B$BE ora torni da me più forte di prima... più $Gilluminato:illuminata;. Questo mi fa piacere. Ed è giusto che tu sia $Gricompensato:ricompensata; per aver portato a termine le mie prove.",
  en_title = "Final Passage",
  en_obj = "Speak to Dorn Plainstalker in Thousand Needles.",
}
T[1395] = {
  title = "Rifornimenti per Nethergarde",
  desc = "Questa cassa di pietre del potere deve arrivare a Nethergarde Keep, nelle Blasted Lands. Non conserveranno il loro potere a lungo, quindi non possiamo spedirle con la prossima carovana.$B$BDevi portarle tu, e devi portarle in fretta.$B$BPortale al Quartiermastro Lungertz, a Nethergarde Keep. Per raggiungere la fortezza devi andare a est attraverso il Deadwind Pass, poi a est attraverso la Swamp of Sorrows, poi a sud attraverso le Blasted Lands.$B$BSta' $Gattento:attenta;, $N. Attraverserai terre pericolose, ma non devi fallire.",
  obj = "Porta la Crate of Power Stones a Quartermaster Lungertz, prima che le pietre del potere si esauriscano.",
  progress = "Salve! Non badare a tutto questo trambusto, qui a Nethergarde Keep è ordinaria amministrazione.$B$BHai qualcosa per me?",
  reward = "Ah, le pietre del potere! I maghi saranno contenti di vederle!$B$BMille grazie, $N. So che il viaggio da Darkshire non è stato facile.",
  en_title = "Supplies for Nethergarde",
  en_obj = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.",
}
T[1396] = {
  title = "La Fauna Selvatica Avanza",
  desc = "La mia carovana era diretta alla costa orientale, ma non abbiamo raggiunto la meta. I Perduti ci hanno attaccati, uccidendo le guardie e distruggendo le provviste.$B$BSono l'unico sopravvissuto al loro assalto. Ho giurato di proteggere le provviste rimaste, ma le creature selvatiche si aggirano qui vicino. Ti prego, aiutami a difendere il mio accampamento dalle bestie!",
  obj = "Uccidi 8 Young Sawtooth Crocolisk, 10 Sorrow Spinner e 10 Swamp Jaguar, poi torna da Watcher Biggs, nella Swamp of Sorrows.",
  progress = "Le creature della palude si fanno sotto, $N. Ti prego, devi difendere l'accampamento!",
  reward = "I versi degli animali ora sono deboli, più lontani. Grazie, $N. Speriamo che non tornino!",
  en_title = "Encroaching Wildlife",
  en_obj = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.",
}
T[1398] = {
  title = "Legni Spiaggiati",
  desc = "Ti devo moltissimo, $N. In te batte un cuore pieno d'onore. E ora ho un altro compito per cui chiedo umilmente il tuo aiuto.$B$BSe voglio sperare di arrivare a Nethergarde, devo riparare questo carro. E per farlo... mi servirà del legno. Legno robusto e asciutto — non il legno spugnoso e contorto degli alberi della palude.$B$B$N, va' a est verso la costa e cerca legni spiaggiati seccati dal sole. Portameli.",
  obj = "Porta 8 pezzi di Sundried Driftwood a Watcher Biggs, nella Swamp of Sorrows.",
  progress = "Hai trovato dei legni spiaggiati, $N?",
  reward = "Questo legno è leggero, ma resistente. Grazie, $N. Andrà benissimo.",
  en_title = "Driftwood",
  en_obj = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.",
}
T[1418] = {
  title = "Neeka Bloodscar",
  desc = "I Badlands sono una terra dura e si trovano vicino a Loch Modan, in mano all'Alleanza, perciò le comunicazioni tra Stonard e l'avamposto di Kargath nei Badlands vengono spesso interrotte.$B$BDimostra il tuo valore, $N. Va' nei Badlands e parla con Neeka Bloodscar, a capo degli esploratori dell'avamposto di Kargath. Parla con lei, e poi rimanda a me il suo rapporto.",
  obj = "Parla con Neeka Bloodscar.",
  reward = "Helgrum vuole un rapporto, eh? Ho mandato un corriere a Stonard nemmeno tre giorni fa. Ha fallito la sua missione? Se Stonard non ha il mio rapporto, allora sembra proprio che abbia fallito.$B$BSperiamo che il prossimo corriere che mando abbia più abilità, o più fortuna.",
  en_title = "Neeka Bloodscar",
  en_obj = "Speak with Neeka Bloodscar.",
}
T[1419] = {
  title = "I Coyote Ladri",
  desc = "Hai passato molti giorni nei Badlands, $C? Hai sentito il caldo di questa terra? Hai affrontato le bestie che vagano per le sue pianure polverose? È ora di farlo.$B$BI coyote delle rupi sono una razza tosta. Tosti, e abbastanza sfrontati da intrufolarsi a Kargath e rubare le nostre provviste di cibo. Aiutaci a liberare l'avamposto da questi ladri!$B$BDai la caccia ai coyote delle rupi, $N. Cacciali e portami le loro mascelle. Portamene abbastanza, e forse ti crederò quando dirai di conoscere i Badlands.",
  obj = "Porta 30 Coyote Jawbone a Neeka Bloodscar, a Kargath.",
  progress = "Hai le mascelle?",
  reward = "Una bella collezione di mascelle, $N. Ora quei coyote non faranno più a pezzi le nostre provviste in cerca di avanzi.$B$BBen fatto. I coyote dei Badlands non sono prede facili. La tua impresa mi dimostra che forse qui riuscirai a sopravvivere.",
  en_title = "Coyote Thieves",
  en_obj = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.",
}
T[1420] = {
  title = "A Rapporto da Helgrum",
  desc = "Ho scritto un nuovo rapporto per Helgrum, a Stonard. Portaglielo.$B$BE se ti consideri una staffetta, allora non perderti per strada. E non cadere per mano di un nemico.",
  obj = "Porta Neeka's Report a Helgrum the Swift, a Stonard.",
  progress = "Sei $Gtornato:tornata;. Hai un rapporto?",
  reward = "Grazie, $N. Dal rapporto di Neeka vedo che anche l'Alleanza ha i suoi problemi. E potremmo scoprire di avere qualche nemico in comune.",
  en_title = "Report to Helgrum",
  en_obj = "Bring Neeka's Report to Helgrum the Swift in Stonard.",
}
T[1421] = {
  title = "La Carovana Perduta",
  desc = "Sono rimasto stordito durante l'attacco dei Perduti, ma prima che mi si oscurasse la vista ho scorto uno dei nostri carri trascinato al Santuario dei Perduti, il loro villaggio a nord.$B$BIn quel carro c'era una cassa della carovana con reagenti preziosi, reagenti vitali per gli studi dei maghi di Nethergarde Keep. Trova la cassa e prendi quei reagenti, $N. Prendili e portali a me.",
  obj = "Trova la Caravan Chest nel Fallow Sanctuary, prendi i Wizards' Reagents e portali a Watcher Biggs.",
  progress = "Hai i reagenti dei maghi, $N?",
  reward = "Ah, li hai trovati! Con questi, i maghi di Nethergarde potranno continuare il loro lavoro. Non so che cosa facciano di preciso, ma quel che fanno ha a che fare con il Portale Oscuro nelle Blasted Lands, ed è vitale per la sicurezza dell'Alleanza.",
  en_title = "The Lost Caravan",
  en_obj = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.",
}
T[1422] = {
  title = "Minaccia dal Mare",
  desc = "Mentre comincio a lavorare alla tua arma, perché non parli con Katar? Ha detto che gli serve aiuto con le pattuglie lungo la spiaggia, e preferirei vederti con la mente lucida e le armi pronte, invece che a ubriacarti con qualcuno degli altri pidocchi con cui divido questo accampamento.",
  obj = "Parla con Katar, nella Swamp of Sorrows.",
  reward = "Fa' silenzio un momento, $C. Anche sopra il ruggito sordo del mare si sentono ancora quei disgustosi gorgoglii degli uomini pesce.",
  en_title = "Threat From the Sea",
  en_obj = "Speak to Katar in the Swamp of Sorrows.",
}
T[1423] = {
  title = "I Rifornimenti Perduti",
  desc = "Questo barile è piccolo ma robusto. Le giunture sono sigillate con una cera gialla dall'odore pungente. Sul fondo del barile sono stampate le parole:$B$BFURIERE LUNGERTZ$B$BNETHERGARDE KEEP",
  obj = "Porta le Lost Supplies a Quartermaster Lungertz.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, grazie, $N! Tra Darkshire e qui si perdono così tante provviste. Fa piacere vedere che qualcosa si recupera.",
  en_title = "The Lost Supplies",
  en_obj = "Bring the Lost Supplies to Quartermaster Lungertz.",
}
T[1424] = {
  title = "Il Bacino delle Lacrime",
  desc = "Il Capoguerra ci ha mandati a indagare su strani avvenimenti al Temple of Atal'Hakkar.$B$BI troll Atal'ai sono una tribù di incantatori oscuri, noti per praticare magie proibite. Puoi immaginare il nostro stupore quando, arrivati qui, abbiamo scoperto che il tempio era sprofondato.$B$BOra i draghi verdi sorvegliano il luogo, e sostengono di essere i protettori di Azeroth.$B$BDobbiamo scoprire cos'è successo. Esplora i dintorni del Bacino delle Lacrime e raccogli dei manufatti degli Atal'ai. Partendo da quelli potrò cominciare a mettere insieme i pezzi di questo enigma.",
  obj = "Fel'zerul, a Stonard, vuole che tu raccolga 10 Atal'ai Artifact.",
  progress = "Nessuno sa quali pratiche oscure si svolgessero dentro il Temple of Atal'Hakkar. Ma sappiamo che sono state usate forze magiche grandi e potenti.$B$BDobbiamo imparare il più possibile su questa magia. Forse gli incantesimi degli Atal'ai si riveleranno utili all'Orda.$B$BQuando avrai raccolto abbastanza manufatti degli Atal'ai intorno al Bacino delle Lacrime, potrò cominciare a capire cosa speravano di ottenere i troll e cosa è andato così terribilmente storto.",
  reward = "La diligenza con cui hai raccolto i manufatti degli Atal'ai merita un elogio, $C.",
  en_title = "Pool of Tears",
  en_obj = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.",
}
T[1425] = {
  title = "Consegna il Carico",
  desc = "Mentre riparo questo carro, $N, ho un ultimo compito per te.$B$BHo imballato le provviste più importanti tra quelle scampate agli attacchi degli ogre. Portale alla Nethergarde Keep. La fortezza è annidata tra le colline settentrionali delle Blasted Lands, e sorveglia il Portale Oscuro.$B$BPer raggiungere Nethergarde, segui la strada verso est. Quando si dirama, va' a sud nelle Blasted Lands, poi alla biforcazione successiva gira a sinistra. Segui la strada, $N, e fa' attenzione.",
  obj = "Porta lo Shipment to Nethergarde a Quartermaster Lungertz, nella Nethergarde Keep.",
  progress = "Mi cerchi per qualcosa?",
  reward = "Cosa? Un pacco dalla carovana di Biggs? Credevamo che la carovana, e lui, fossero andati perduti.$B$BGrazie, $N. Con un po' di fortuna, queste provviste conterranno il reagente di cui abbiamo tanto bisogno, i Cristalli di Azoran. Le nostre scorte si stanno esaurendo...",
  en_title = "Deliver the Shipment",
  en_obj = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.",
}
T[1426] = {
  title = "Minaccia dal Mare",
  desc = "Non amo il mare, né le creature che ho visto uscire dai suoi abissi. È un'amante potente ma cieca; spietata e brutale. Mi darebbe un gran piacere uccidere gli uomini pesce a centinaia, se fosse in mio potere. Ma provo un certo piacere a guardarli morire per mano di chiunque compia la volontà dell'Orda.$B$BIl che ci porta a te, $C. Quanti riesci a ucciderne? Vuoi metterti alla prova contro i più potenti della loro specie?",
  obj = "Uccidi 10 Marsh Murloc, 10 Marsh Inkspewer e 10 Marsh Flesheater, poi torna da Katar, nella Swamp of Sorrows.",
  progress = "Sono paziente. Paziente ed eterno come una vecchia pietra kank di Draenor. Gli uomini pesce non supereranno i nostri confini — non finché resterò in piedi. Se avessimo un esercito a disposizione, ripulirei questo mondo e tutti gli altri dalla loro presenza. Sento il mio odio ribollire solo a parlarne.",
  reward = "Il mare sembra vasto e implacabile, ma tu l'hai macchiato con il sangue della sua stessa progenie. Gli uomini pesce conoscono il dolore. La loro stupidità li costringerà a rinforzare le file dopo la devastazione che hai causato, ed è un bene.$B$BChe le loro grida gorgoglianti coprano il ruggito del mare fino a notte fonda. Sorriderò ogni volta che ne sentirò uno messo a tacere.$B$BTorna da me se vuoi uccidere altri uomini pesce. Ti ricompenserò di nuovo volentieri.",
  en_title = "Threat From the Sea",
  en_obj = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.",
}
T[1427] = {
  title = "Minaccia dal Mare",
  desc = "Prima di riposarti, parla di nuovo con Tok'Kar. Mentre eri via credo abbia finito qualche arma. Per il tuo aiuto qui, vorrebbe offrirtene una. Faresti bene a metterne alla prova la forza contro gli uomini pesce quando sarai $Gpronto:pronta;... ma solo per farmi ancora più piacere.",
  obj = "Parla con Tok'Kar, nella Swamp of Sorrows.",
  reward = "Ah, $N, sei $Gtornato:tornata;. Bene. Ho finito di forgiare altre armi per la nostra lotta contro i murloc. Per averci portato la carne fresca di dentesega, e per aver strappato un piccolo sorriso a Katar, te ne offro una.",
  en_title = "Threat From the Sea",
  en_obj = "Speak with Tok'Kar in the Swamp of Sorrows.",
}
T[1428] = {
  title = "La Minaccia Continua",
  desc = "Mi fa piacere vedere che il tuo odio per gli uomini pesce cresce insieme al mio.$B$BTrovane altri della loro specie lungo la spiaggia, e quando avrai combattuto abbastanza torna da me. Allora parleremo di una ricompensa per la tua diligenza.",
  obj = "Uccidi 10 Marsh Inkspewer, 10 Marsh Flesheater e 10 Marsh Oracle, poi torna da Katar, nella Swamp of Sorrows.",
  progress = "Non sarò soddisfatto finché il mare e tutti i suoi figli non saranno ridotti al silenzio... soprattutto quei disgustosi uomini pesce.",
  reward = "Ben fatto, $C. Voglio ancora del loro sangue. Che periscano tutti gli uomini pesce.",
  en_title = "Continued Threat",
  en_obj = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.",
}
T[1429] = {
  title = "L'Atal'ai Exile",
  desc = "Mentre affrontavi i pericoli del Bacino delle Lacrime, uno dei miei esploratori è tornato con una pergamena scritta col sangue su carne essiccata. Sembra una sentenza contro un sacerdote della tribù Atal'ai.$B$BTra gli Atal'ai, questo sacerdote è stato condannato a un destino peggiore della morte.$B$BÈ stato esiliato a vivere lontano, a nord, nelle Hinterlands, con i troll Witherbark.$B$BImpacchetterò questi manufatti. Tu devi cercare l'esule e scoprire a cosa servono davvero. Torna da me quando il tuo viaggio sarà concluso.",
  obj = "Porta il Bundle of Atal'ai Artifacts all'Atal'ai Exile, nelle Hinterlands.",
  progress = "Hai coraggio a venire qui. Coraggio o follia...",
  reward = "Mi porti i manufatti di evocazione degli Atal'ai?$B$BVedo che Jammal'an il Profeta sta guidando i discepoli della Camera del Sangue verso il destino che hanno scelto. Che Hakkar sia tornato al Tempio? Si è compiuto il loro destino?",
  en_title = "The Atal'ai Exile",
  en_obj = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.",
}
T[1430] = {
  title = "Carne Fresca",
  desc = "Tra i miei clienti c'è molta richiesta del sapore succulento della carne di crostaceo, soprattutto quella dei crostacei mostruosi.$B$BSe hai intenzione di andare sulla costa, potrei facilmente fare in modo che ti convenga riportarmi un po' delle loro zampe, da spedire a Orgrimmar.$B$BLa costa è a est di qui, e non dovresti avere problemi a trovare le creature che zampettano lungo le spiagge e sotto il mare.",
  obj = "Porta 10 Monstrous Crawler Leg a Dar, nella Swamp of Sorrows.",
  progress = "Ho una botte di vino che aspetta il tuo successo, $N. È giusto che io assaggi la merce prima di spedirla ai miei clienti.",
  reward = "Ah, queste dovrebbero essere perfette. Non vedo l'ora di assaggiarle, dopo averle cotte a puntino sul fuoco vivo. Dovresti portartene un po' nei tuoi viaggi. È davvero una delizia.",
  en_title = "Fresh Meat",
  en_obj = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.",
}
T[1431] = {
  title = "Rapporti con l'Alleanza",
  desc = "Fermati, $C, e lascia che ti dica una cosa importante per il nostro popolo, ma tutt'altro che ovvia.$B$BSiamo una razza orgogliosa, e la guerra con gli umani ha messo alla prova perfino la grande pazienza di Thrall. Vedi, il nostro Capoguerra è saggio e prudente, e continua a mettere al primo posto la sua gente. In fondo è un diplomatico, e nel tempo passato con gli umani ha imparato molto delle loro usanze.$B$BSe la storia che ho cominciato ti incuriosisce, cerca Keldran vicino all'uscita occidentale della città. La sua casupola è là.",
  obj = "Parla con Keldran, a Orgrimmar.",
  reward = "Putanni, nobile $C. Io sono Keldran, studioso di magia... e di altre arti mistiche.$B$BLa faccenda di cui Craven ti ha mandato a parlarmi richiede un po' più di finezza di quanta te ne sia servita finora, ma questo non vuol dire che tu non possa comunque aiutare la nostra causa.$B$BTi prego, mettiti $Gcomodo:comoda;, e ti dirò perché il Capoguerra ha bisogno del mio aiuto... e del tuo.$B$BTutto comincia dalle apparenze, $N. Da come l'Orda vede se stessa. Da come ci vedono i nostri alleati. E soprattutto da come ci vedono i nostri nemici.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1432] = {
  title = "Rapporti con l'Alleanza",
  desc = "Mentre l'Alleanza avanza sempre più a fondo in Kalimdor, si potrebbero trarre conclusioni sbagliate sull'Orda e su presunti patti con la Legione Infuocata. Il Capoguerra non può permetterlo. E con la sua benedizione sto prendendo io in mano il compito di farli eliminare.$B$BHo agenti nella zona di Desolace, al Presidio delle Ombre, a nord del grande Cimitero dei Kodo. Va' a sud della Valle Bruciata, nelle Stonetalon Mountains, e lo troverai. Quando arrivi, cerca Takata Steelblade.",
  obj = "Parla con Takata Steelblade, a Desolace.",
  reward = "Salve, $C. Porti notizie da Orgrimmar: bene.$B$BL'infestazione di demoni soffoca questa zona ancora più della puzza di sterco di centauro. Gli uomini-cavallo rivendicano questa terra come propria, ma è chiaro che ci sono forze fuori dal loro controllo che li schiacceranno, se non le si tiene a bada.$B$BNon mi fa piacere che aiutiamo indirettamente i centauri, ma è per il bene dell'Orda, quindi faccio il mio dovere per il Capoguerra, anche se vuol dire aiutare gli stregoni dentro l'Orda.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1433] = {
  title = "Rapporti con l'Alleanza",
  desc = "I Burning Blade hanno molti piani, ma sappi che sono malvagi fino al midollo, con lo spirito corrotto, e distruggerli è l'unico modo per mandare all'aria i loro obiettivi.$B$BKeldran ha mandato Maurin con me perché conosce bene i Blade e le loro pratiche da stregoni.$B$BÈ lui a guidare le nostre trame contro i Blade, mentre io mi occupo delle altre minacce demoniache qui a Desolace.$B$BParlagli e ti guiderà nei suoi piani.",
  obj = "Parla con Maurin Bonesplitter, a Desolace.",
  reward = "Ah, sì. L'aiuto di chi è fedele al Capoguerra è sempre gradito.$B$BMi chiamo Maurin. Sono qui su richiesta di Keldran e del cucciolo di Capoguerra, Thrall. È mio desiderio aiutare quel giovane capo contro i mali che minacciano il suo governo.$B$BVieni, avvicinati, $C. Ti spiegherò il mio piano per eliminare quel bubbone purulento che sono i Burning Blade.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Maurin Bonesplitter in Desolace.",
}
T[1434] = {
  title = "Corrotti dai Satiri",
  desc = "Un'infestazione di demoni non si verifica senza altre influenze — qualcos'altro permette al male di prendere piede.$B$BPuò cominciare con uno spirito indebolito, con un inutile desiderio di potere; forse è sete di vendetta, o il richiamo di una giustizia definitiva. Quando siamo assaliti dal dolore, il male approfitta di noi — un male come i satiri.$B$BTra loro e i Burning Blade si sono stretti legami, e Thrall li vuole morti. Cercali a nord-est di qui e torna da me quando li avrai ricacciati indietro.",
  obj = "Uccidi 7 Hatefury Rogue, 7 Hatefury Felsworn, 7 Hatefury Betrayer e 7 Hatefury Hellcaller, poi torna da Takata Steelblade, a Desolace.",
  progress = "Un compagno tauren mi ha avvertito che i satiri non sono come sembrano. Crede che ci sia qualcosa di più in loro, che il loro male sia una distorsione della loro vera natura. Ma io queste cose non le ho viste.$B$BIo vedo solo il massacro spietato dei deboli e la corruzione di chi cerca un potere oscuro.$B$BContinuerò nel mio dovere di annientarli finché il Capoguerra non mi ordinerà altro. Fino ad allora, non ho pietà di loro.",
  reward = "Hai fatto un buon lavoro, $C. Hai mostrato onore e dedizione.$B$BQuando la nostra campagna a Desolace sarà finita, il Capoguerra saprà che ci hai aiutato in quel che abbiamo fatto qui e che hai contribuito a realizzare la sua volontà.$B$BTi ringrazio.",
  en_title = "Befouled by Satyr",
  en_obj = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.",
}
T[1435] = {
  title = "Spiriti in Fiamme",
  desc = "La morte è quanto di più desiderabile per quelle creature spregevoli che voltano le spalle al loro signore per ragioni tanto egoistiche. Ma la morte non basta, quando si ha a che fare con chi si è consegnato all'oscurità.$B$BPrendi questa gemma. Quando uno dei Burning Blade è vicino alla morte, attivane la magia. L'incantesimo strapperà lo spirito corrotto dalla sua vittima e lascerà una gemma infusa.$B$BPortami queste gemme infuse, così potrò disfarmene come si deve.$B$BOra va', e possa tu sfuggire alla morte.",
  obj = "Riporta la Burning Gem e 15 Infused Burning Gem a Maurin Bonesplitter, a Desolace.",
  progress = "Ho cercato di rendere la magia il più semplice possibile. Tirare fuori lo spirito della tua vittima dal suo corpo ferito dovrebbe essere un gioco da ragazzi. Non contare sul potere della gemma per uccidere del tutto il nemico. Devi attivarla solo quando è vicino alla morte, altrimenti non servirà a nulla.",
  reward = "Ah, sei $Gtornato:tornata;, e con successo. Bene. Dammi le gemme e le metterò in un posto sicuro....$B$BI miei compiti per te sono finiti, $C. Parla con Takata quando ti sarai $Griposato:riposata;. Potrebbe avere altri incarichi per te, o magari avrà bisogno che tu torni a Orgrimmar a informare Keldran dei nostri progressi qui a Desolace.",
  en_title = "The Burning of Spirits",
  en_obj = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.",
}
T[1436] = {
  title = "Rapporti con l'Alleanza",
  desc = "La lotta va bene, $N. Forse il Capoguerra ci lascerà tornare alle nostre case prima del cambio di stagione, se continuiamo a fare passi avanti così grandi nella battaglia contro i demoni e i loro servi.$B$BTorna da Keldran e fagli sapere cosa abbiamo fatto. Sono sicuro che ti ricompenserà per quel che hai fatto qui. La sua causa gli sta a cuore, e sarà fiero di sapere che il Capoguerra tiene conto delle sue preoccupazioni.",
  obj = "Parla con Keldran, a Orgrimmar.",
  reward = "Sei $Gtornato:tornata; da Desolace con un successo più che pieno, $N. Grazie.$B$BGrazie per il tuo impegno, per il tuo tempo e per aver capito la mia richiesta. Thrall comprende e desidera la pace tra l'Orda e l'Alleanza, e prendendo provvedimenti perché la nostra immagine sia accettabile, non provocheremo altre minacce di violenza inutile.$B$BTi sono debitore.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1437] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Sono Vahlarriel, $N. Mi trovo qui per scoprire dove siano finiti due nobili scomparsi di una famiglia di mercanti di Darnassus — la casata Malem. Il padre della casata teme il peggio, e io devo fare tutto il possibile per ritrovare i suoi figli scomparsi. Non ho ancora cominciato a cercare Tyranis o Dalinda, ma spero di non dover restare qui a lungo.$B$BLe ultime notizie dicono che sono passati per le Stonetalon Mountains qualche settimana fa.$B$BSe trovi il loro carro, ti prego, vieni a cercarmi immediatamente.",
  obj = "Trova e perquisisci il carro di Tyranis e Dalinda Malem, a Desolace.",
  reward = "Frugando tra i resti del carro, ti appare evidente che è stato attaccato sia con incantesimi sia con armi. Lo scontro sembra essere stato rapido e a senso unico: non c'è traccia di sangue, né resti di corpi.$B$BChiunque abbia attaccato il carro è stato efficiente e rapido.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.",
}
T[1438] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Trova sia Dalinda sia Tyranis, se puoi, e torna da me con quello che hai scoperto. Comincia le ricerche da questa fortezza. Contatterò subito i miei superiori a Darnassus e li informerò della situazione.$B$B$N, c'è un'altra cosa che voglio farti capire bene. I miei superiori si sono mostrati preoccupati per Tyranis e per i motivi che l'hanno spinto a venire qui. Per loro è più importante che Dalinda venga ritrovata e riportata a casa sana e salva. Tyranis va... valutato prima di essere riportato a casa.",
  obj = "Trova Dalinda Malem, a Desolace.",
  reward = "Grazie a Elune, finalmente qualcuno è venuto ad aiutarmi. Ti prego, $C, ho bisogno del tuo aiuto. Mio fratello Tyranis e io siamo stati catturati e portati qui dalla Burning Blade. Credo che vogliano sacrificarmi ai loro padroni demoniaci!$B$BSapevo che venire a Desolace era un errore, ma di recente Tyranis ha cominciato a bramare la conoscenza di tutto ciò che è arcano — perfino contro la volontà del nostro popolo. Ha deciso di fare questo viaggio anche dopo aver sentito i racconti sull'infestazione di demoni di questa terra.$B$BTemo il peggio per lui.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find Dalinda Malem in Desolace.",
}
T[1439] = {
  title = "Alla Ricerca di Tyranis",
  desc = "Siamo stati portati qui dopo che gli orchi hanno massacrato tutte le nostre guardie e i nostri servitori. Oh, le cose terribili che gli hanno fatto! Pensavo che di sicuro ci avrebbero uccisi lì, all'istante, ma è diventato chiaro che avevano altri piani.$B$BTyranis ha cercato di parlare con loro. Credo che volesse impressionarli con la sua conoscenza dell'arcano... non so bene perché.$B$BTi prego, non posso andarmene da qui finché non so cosa è successo a mio fratello. Trovalo, poi torna a prendermi quando la sua sorte sarà nota.",
  obj = "Trova Tyranis Malem, a Desolace.",
  progress = "Temo che Tyranis cercherà di imparare i segreti della Burning Blade e di unirsi a loro, se glielo permetteranno — ha sempre adorato il potere che la magia dà a chi se ne lascia sedurre.$B$BNon so se potrei sopportare di tornare a casa dalla mia famiglia con la notizia che Tyranis sta flirtando con simili pericoli. Tra la mia gente è già un crimine abbastanza grave dedicarsi a queste cose, ma diventare ciò da cui cerchiamo di proteggerci, beh, è riprovevole.",
  reward = "È terribile! Ma suppongo che fosse necessario. Se non fosse stato per mano tua, di sicuro sarebbe stato per mano della mia gente. Credo di doverti ringraziare — perdonami se il mio grazie non sembra sincero. Non intendo offenderti.$B$BOra che conosco la sorte di mio fratello, sembra che sia giunto il momento della mia fuga. Se sei ancora $Gdisposto:disposta;, accetterò il tuo aiuto per fuggire da questo posto orribile.$B$BQuando sei $Gpronto:pronta;, possiamo metterci in salvo.",
  en_title = "Search for Tyranis",
  en_obj = "Find Tyranis Malem in Desolace.",
}
T[1440] = {
  title = "Ritorno da Vahlarriel",
  desc = "Allora, è giunto il momento? Apprezzo i tuoi sforzi, e se poi non ci sarà occasione, lascia che ti ringrazi adesso per tutto quello che hai fatto per me e per la mia famiglia. Se sei $Gpronto:pronta;, qui non c'è più niente per me — possiamo partire quando ritieni che sia il momento giusto.",
  obj = "Scorta Dalinda Malem fuori dalla Thunder Axe Fortress, poi torna da Vahlarriel Demonslayer, a Desolace.",
  reward = "Grazie, $N. Dalinda è tornata sana e salva qui a Nijel's Point, e in condizioni molto migliori di quanto potessi sperare. Il fatto che sia arrivata qui con le sue forze è un buon segno. Tu stai bene, spero?$B$BMi addolora sapere che Tyranis non è tornato con Dalinda, ma la vergogna per le scelte di Tyranis dovrà sopportarla lei. È qualcosa che dovrà affrontare quando tornerà a Darnassus.",
  en_title = "Return to Vahlarriel",
  en_obj = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",
}
T[1444] = {
  title = "Ritorno da Fel'Zerul",
  desc = "Jammal'an il Profeta mi ha condannato all'esilio dal Temple of Atal'Hakkar. Un tempo ritenevo che il sommo sacerdote fosse una guida degna.$B$BLa sua fede incrollabile nella propria profezia porterà alla distruzione degli Atal'ai. Se non l'ha già fatto.$B$BQuando ho espresso i miei dubbi, sono stato bollato come infedele e cacciato dal tempio.$B$BI manufatti che mi hai portato sono innocui. Ma se Jammal'an ha trovato l'incantamento del feticcio adatto al rituale di evocazione, il mondo corre un grave pericolo....",
  obj = "Torna da Fel'zerul a Stonard.",
  reward = "È passato parecchio tempo dall'ultima volta che abbiamo parlato, $C. Spero che il tuo viaggio sia andato bene.$B$BChe cosa hai scoperto dall'Atal'ai in esilio nelle Hinterlands?",
}
T[1445] = {
  title = "Il Temple of Atal'Hakkar",
  desc = "Quindi ha parlato della profezia di Jammal'an?$B$BLa guida spirituale degli Atal'ai crede che, quando Hakkar sarà tornato ad Azeroth dal Nether, il dio concederà l'immortalità alla tribù degli Atal'ai.$B$BUno stupido imbroglio per affrettare la fine del mondo, se vuoi il mio parere.$B$BMa dici che l'esule ha parlato di feticci incantati? Questo mi preoccupa molto. Se sono davvero la chiave del rituale degli Atal'ai che ha causato questo disastro, dobbiamo capire quali poteri racchiudono.$B$BAddentrati nel Temple e impadronisciti dei feticci!",
  obj = "Raccogli 20 Fetishes of Hakkar e portali a Fel'Zerul a Stonard.",
  progress = "Se i feticci degli Atal'ai hanno il potere di evocare Hakkar e di far avverare la profezia di Jammal'an, bisogna impadronirsene. L'Orda deve comprendere simili poteri!",
  reward = "$GValoroso:Valorosa; $C, hai dimostrato di essere $Gun grande campione:una grande campionessa; dell'Orda.$B$BOra bisogna occuparsi subito di questa raccolta di feticci di Hakkar!",
}
T[1446] = {
  title = "Jammal'an il Profeta",
  desc = "Ai miei compagni Witherbark non piace vedere estranei intorno a casa loro.$B$BIo? Io una casa non ce l'ho più. Sono stato esiliato dal mio popolo, la grande tribù Atal'ai della Swamp of Sorrows.$B$BLa nostra guida spirituale, Jammal'an, ha avuto quella che lui ha chiamato una profezia. Crede che l'evocazione del dio Hakkar porterà agli Atal'ai l'immortalità.$B$BMa io ho invitato alla prudenza. E se la profezia non fosse altro che una manipolazione?$B$BVoglio vendetta per il mio esilio. Portami la testa di Jammal'an. Forse allora il mio popolo sarà libero.",
  obj = "L'Atal'ai Exile, nelle Hinterlands, vuole la Head of Jammal'an.",
  progress = "Una volta tolto di mezzo Jammal'an, avrò qualche possibilità di tornare dal mio popolo.$B$BCon Jammal'an come guida spirituale, gli Atal'ai vanno incontro a una distruzione certa.",
  reward = "La fiducia sconsiderata di Jammal'an in false visioni ha condotto il mio popolo alla rovina eterna.$B$BTi ringrazio, $C, per aver vendicato il mio esilio. Piango il mio popolo. Non ho una casa a cui tornare.",
}
T[1447] = {
  title = "Il Diplomatico Scomparso",
  desc = "Già, non sei certo $Gil:la; $C più $Gsveglio che sia mai entrato:sveglia che sia mai entrata; a Stormwind, ma stai per diventare $Guno dei più stupidi:una delle più stupide; a non uscirne mai più.$B$BHai conosciuto i miei amici?",
  obj = "Sconfiggi Dashel Stonefist, a Stormwind.",
  progress = "Non volevo offenderti con quella battuta sul fatto che sei $Gun:una; $C $Gstupido:stupida;. Siamo amici, no? Nessun rancore?",
  reward = "Allora, sei $Gvenuto:venuta; da me per un motivo. Di cosa hai bisogno?",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Dashel Stonefist in Stormwind.",
}
T[1448] = {
  title = "Alla Ricerca del Tempio",
  desc = "C'è stato un tempo in cui ero giovane e pieno di vigore come te, $C.$B$BMa ora sono vecchio e non posso più esplorare il mondo come facevo una volta. Ah, le cose che ho visto!$B$BMa c'era un mistero che mi è sempre sfuggito. Per la mia ultima impresa, la Lega degli Esploratori mi ha mandato in cerca del Temple of Atal'Hakkar. Si diceva che si trovasse nella Swamp of Sorrows.$B$BFragile com'ero, l'ho cercato percorrendo i cieli in grifone, ma non l'ho mai trovato.$B$BDaresti una mano a un vecchio nano? Magari tu avrai più fortuna a piedi.",
  obj = "Brohann Caskbelly, a Stormwind, vuole che tu cerchi il Temple of Atal'Hakkar.",
  progress = "Ho girato il mondo, dalle giungle di Azeroth alle cime innevate di Khaz Modan.$B$BMai prima d'ora avevo chiesto aiuto nelle mie avventure. Ma le mie vecchie ossa sono stanche.$B$BNiente mi darebbe più soddisfazione che sapere di aver portato a termine la mia ultima impresa per la Lega degli Esploratori$B$BSe fossi così gentile da aiutarmi a cercare il Temple of Atal'Hakkar, $C, te ne sarei molto grato.$B$BPerlustra la Swamp of Sorrows e torna a riferirmi quello che hai trovato!",
  reward = "Il Temple of Atal'Hakkar è sprofondato sotto il Bacino delle Lacrime? E circondato dal dragonflight verde?$B$BUna scoperta incredibile, $C. Ma è chiaro che qualcosa è andato terribilmente storto.",
  en_title = "In Search of The Temple",
  en_obj = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.",
}
T[1449] = {
  title = "Verso le Hinterlands",
  desc = "Come ti ho detto prima, ho cercato di esplorare il tempio da solo, dall'alto. Be', non ero proprio solo.$B$BSono andato alla famosa voliera dei grifoni di Aerie Peak, nelle Hinterlands. Lì ho chiesto l'aiuto di uno dei loro piloti migliori. Il pilota è caduto dalla sua cavalcatura, giù nella palude...$B$BAlla mia età il nome di quel poveretto mi sfugge. Il capo della voliera se lo ricorderà di sicuro.$B$BVa' laggiù e cerca Falstad Wildhammer.$B$BDobbiamo scoprire che fine ha fatto quel pilota.",
  obj = "Parla con High Thane Falstad Wildhammer ad Aerie Peak, nelle Hinterlands.",
  reward = "Che vuoi, $Gragazzo:ragazza;? Non vedi che ho dei problemi da sistemare qui? Chi ha tempo di stare lì a chiacchierare con $Gun:una; $R $Gchiacchierone:chiacchierona;?$B$BI troll sbucano da tutte le parti! Sbrigati.",
  en_title = "To The Hinterlands",
  en_obj = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.",
}
T[1450] = {
  title = "Il Maestro dei Grifoni Talonaxe",
  desc = "Quindi fai $Gil galoppino:la galoppina; di lusso per qualche vecchio bacucco della Lega degli Esploratori, eh?$B$BBe', ascoltami bene, $C. Non so con chi andasse in volo il tuo vecchio amico giù ad Azeroth. Ti sembro forse il Maestro dei Grifoni Talonaxe? Ti sembro lui?$B$BSe ti interessano tanto i turni di volo, perché non lo chiedi al maestro dei grifoni? Se ti becco a bighellonare qui ancora a lungo, ti metto a fare un lavoro vero.$B$BE ora muoviti.",
  obj = "Parla con Gryphon Master Talonaxe nella voliera di Aerie Peak.",
  reward = "Ah, sì. Certo che mi ricordo di aver mandato uno dei miei cavalieri di grifoni a dare una mano a Brohann Caskbelly.$B$BHo sempre avuto un debole per la Lega degli Esploratori. Mio padre, a dire il vero, ha dato una mano alla prima squadra di scavo, quella che ha scoperto Uldaman.$B$BCon Brohann ho mandato quello che allora consideravo il mio miglior cavaliere di grifoni. Un tipo che si chiamava Rhapsody Shindigger.$B$BE che fantino di grifoni era! Be', finché...",
}
T[1451] = {
  title = "Rhapsody Shindigger",
  desc = "Rhapsody ci aveva preso proprio gusto, con l'alcol. Intendiamoci — a noi nani quassù alla voliera una buona birra piace, quando è il momento giusto.$B$BMa il vecchio Shindigger si è attaccato ai liquori come un grifone si getta nel cielo. Ed è stato un maledetto peccato. Nessuno volava come Rhapsody.$B$BIl primo segnale che qualcosa non andava è stato quando è tornato barcollando da quella missione con il tuo amico Brohann. Da lì tutto è andato a rotoli in fretta. Ho dovuto mandarlo via.$B$BDa quel che ho sentito, ha messo su un accampamento per farsi la birra, a est di qui...",
  obj = "Cerca Rhapsody Shindigger nelle Hinterlands.",
  reward = "Hic!$B$BTi sto guardando dritto dritto, ma continui ad andare su e giù. Mi fai girare la testa. Ohoh!$B$BHic!$B$BUoh! L'hai sentito? La terra balla, $Gamico mio:amica mia;. Mi ci vuole un goccio.$B$BHic!",
}
T[1452] = {
  title = "Il Kocktail Kalimdor di Rhapsody",
  desc = "Hic!$B$BQuindi ti ha mandato quel pazzo di Brohann? Accidenti, che avventura abbiamo vissuto...Hic!$B$BSe vuoi che ti racconti cos'è successo giù nella palude, mi ci vuole qualcosa di forte da bere. Non è stato un bello spettacolo, capisci. Hic!$B$BFacciamo così... portami quello che mi serve per preparare al volo un Kocktail Kalimdor e ti racconto tutto.$B$BMi servono un po' di stomaci di Roc da Tanaris... e vediamo... un po' di fegati di Groddoc e di Ironfur da Feralas...$B$BUn bel Kocktail Kalimdor forte... quello sì che mi scioglie la lingua!",
  obj = "Rhapsody Shindigger nelle Hinterlands vuole che tu gli porti 3 Roc Gizzards, 3 Groddoc Livers e 3 Ironfur Livers.",
  progress = "Hai mai bevuto una Birra Rhapsody? Una delle mie birre migliori, modestamente. Hic!$B$BMa se devo rivivere gli orrori di quel volo fatale sopra... hic... la palude, be', mi ci vuole qualcosa di un tantino più forte. Hic!$B$BNon è che per caso mi hai trovato quegli stomaci e quei fegati che mi servono per dare una marcia in più al mio Kocktail Kalimdor?$B$BHic!",
  reward = "Vedo che non hai avuto nessun problema a procurarmi quello che mi serve! Dev'essere stata una bella trasferta, laggiù nella lontana Kalimdor.$B$BMi ci vuole solo un attimo per estrarre da questi stomaci e fegati quello che mi serve. Hic!$B$BPoi potrò distillarmi un intruglio bello feroce e finalmente dirti quello che vuoi sapere.$B$BHic!$B$BMi vengono i brividi solo a pensare a quella vecchia palude.$B$BHic!$B$BFammi preparare da bere in un lampo.",
}
T[1453] = {
  title = "Affari dei Reclaimers a Desolace",
  desc = "C'è del lavoro da fare a Desolace, $N. È un posto atroce, infestato dai centauri e da altre bestiacce. Ma se cerchi una buona settimana di lavoro onesto, va' là, incontra Kreldig Ungor e digli che ti mando io.$B$BLo trovi rintanato al Presidio di Nijel — è un piccolo accampamento accogliente nascosto tra le montagne del nord di Desolace. Se entri dalle Stonetalon Mountains, basta andare verso est. È facile non vederlo, quindi tieni gli occhi aperti.",
  obj = "Parla con Kreldig Ungor, a Desolace.",
  reward = "Che piacere vedere che ai Reclaimers non manca il lavoro, né gente disposta a dare una mano.$B$BIo sono Kreldig, $N. Hai fatto una mossa furba ad aiutare i Reclaimers. Di questi tempi tutti hanno bisogno di qualcosa: chi ha perso un cimelio di famiglia, chi un oggetto magico, chi una persona cara. Non si sa mai. Ma finché ci sono i Reclaimers, non c'è motivo per cui, al giusto prezzo, chiunque non possa ritrovare quel che ha perso.",
  en_title = "Reclaimers' Business in Desolace",
  en_obj = "Speak to Kreldig Ungor in Desolace.",
}
T[1454] = {
  title = "Il Naufragio di Karnitol",
  desc = "Il mio primo incarico è per il mago Karnitol — una specie di nobile di Stormwind. Pare che la sua nave sia stata attaccata dai giganti marini al largo della costa, nel nord-ovest di Desolace. Lui e i suoi servitori hanno cercato di portare a riva uno dei suoi forzieri più preziosi, ma quando i giganti marini hanno attaccato in massa, ha scelto di abbandonarlo e di teletrasportarsi al sicuro con i suoi servitori.$B$BVuole che troviamo il forziere e il suo contenuto e che glieli riportiamo a Stormwind.",
  obj = "Trova Karnitol's Chest, a Desolace.",
  reward = "Noti che il forziere non sembra danneggiato dall'acqua.$B$BLa seconda cosa che noti è che il coperchio è stato forzato, e qualunque trappola magica fosse stata messa a proteggerlo è scattata da tempo — lo si capisce chiaramente dai segni di bruciatura lungo i bordi.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Chest in Desolace.",
}
T[1455] = {
  title = "Il Naufragio di Karnitol",
  desc = "Ti fermi qualche istante a capire che cosa abbia scardinato il forziere, e noti lungo i lati e sul coperchio dei graffi lunghi e profondi, segno che del forziere si è occupato qualcosa che non era né un uomo né un gigante. I segni non sembrano fatti da un pugnale o da una spada.$B$BFrugando nel forziere, scopri che è completamente vuoto.$B$BNon avendo altro da fare, chiudi il forziere e ti prepari ad andartene. Kreldig sarà deluso.",
  obj = "Torna da Kreldig Ungor, a Desolace.",
  reward = "$GBentornato:Bentornata; a Nijel's Point, $N. Allora, dimmi cosa hai trovato.$B$BCosa!? Niente? Con un forziere vuoto, temo, non ci becchiamo un soldo.$B$BParlami meglio di quei segni che hai visto... di quei tagli.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Return to Kreldig Ungor in Desolace.",
}
T[1456] = {
  title = "Il Naufragio di Karnitol",
  desc = "Interessante.$B$BBeh, forse non abbiamo ancora perso ogni speranza.$B$BLungo quella stessa costa, ma più a nord, vicino alla Ranazjar Isle, ci sono delle rovine degli elfi della notte in fondo all'oceano. Ci vive una tribù di naga, gli Slitherblade. Credo che sia la nostra carta migliore.$B$BSe un gruppo di esploratori si è spinto così a sud, doveva essere piuttosto potente. Se vuoi trovare gli effetti personali di Karnitol, io comincerei dai naga più potenti: i cacciatori delle maree o le streghe del mare.",
  obj = "Trova Karnitol's Satchel e riportala a Kreldig Ungor, a Desolace.",
  progress = "Senza offesa per chiunque sia questo Nijel, ma questo accampamento non è il posto più comodo in cui abbia mai passato una notte, se capisci cosa intendo, $N.",
  reward = "Fantastico, $N! Hai trovato gli effetti personali di Karnitol!$B$BQuei maledetti naga, sempre a creare guai. Credo che preferirei passare la vita in guerra con l'Orda piuttosto che dover affrontare quelli della loro specie. Hai reso un grande servizio ai Reclaimers.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.",
}
T[1457] = {
  title = "Il Naufragio di Karnitol",
  desc = "Riporta le cose di Karnitol a Roetten, a Ironforge, e lui ti pagherà per il lavoro ben fatto.$B$BAhah, se non fai attenzione, sarà così contento di te che ti chiederà di unirti a noi a tempo pieno.$B$BAncora una volta, ottimo lavoro, $N.$B$BFa' attenzione sulla via del ritorno, e non metterci troppo — Karnitol non è il più paziente degli uomini, ma è comunque molto generoso.",
  obj = "Porta Karnitol's Satchel a Roetten Stonehammer, a Ironforge.",
  progress = "Gli affari vanno a gonfie vele, $N, e non ho molto tempo per le domande. Se hai affari con i Reclaimers, sentiamo. Altrimenti dovrò chiederti di parlare con uno dei miei sottoposti — se la cavano abbastanza bene a sbrigare le faccende qua intorno.",
  reward = "Ah, la faccenda di Karnitol a Desolace. Eccellente!$B$BQuindi il forziere è stato distrutto, ma gli oggetti ci sono tutti, eh? Beh, lascerò che sia lui a giudicare. Una cosa buona di questo mio giro d'affari è che, se non sono soddisfatti, posso mandarli a quel paese! Contano su di noi per ritrovare la loro roba... non per assicurarci che sia tutta bella e in buono stato quando la riavranno.$B$BBuon lavoro, $N. Vediamo di darti la tua paga.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.",
}
T[1458] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Uno dei miei compiti qui fuori è procurare dei reagenti per Leftwitch, un mago gnomo di Kharanos. Roetten pensa che siano soldi facili, visto che siamo già qui. Non gli importa granché che siamo già a corto di personale.$B$BLe prime cose sulla sua lista dovrebbero essere abbastanza facili da trovare, e ci sarebbe un bel gruzzolo per chi mi dà una mano.$B$BMi servono corna e artigli dei satiri Hatefury, a est di qui. Portameli e cominceremo con il resto della lista.",
  obj = "Porta 10 Hatefury Claw e 10 Hatefury Horn a Kreldig Ungor, a Desolace.",
  progress = "Creature spregevoli, i satiri. Si racconta che siano in qualche modo legati agli elfi della notte, ma non so se ci credo davvero.$B$BCredo che quella storia venga da quell'elfo che li ha trascinati nella guerra qualche anno fa. Da allora il mondo non è più stato lo stesso. Molto più pericoloso, e molto più spaventoso.",
  reward = "Bene, bene, $N. Non so se siano di buona qualità, ma se Leftwitch voleva un tipo particolare, avrebbe dovuto specificarlo prima di mandare i Reclaimers quaggiù.$B$BChe ne dici di passare alla prossima voce della sua lista?",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.",
}
T[1459] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "La prossima voce della lista di Leftwitch è... vediamo... hmm. Ah, eccola.$B$BAbbastanza semplice, ma le sue istruzioni sono piuttosto precise. Gli serve veleno di scorpashi e pelle di kodo. Le clausole in piccolo dicono che tutti e due devono venire da creature specifiche: il veleno deve venire da uno scorpashi qualsiasi, e la pelle da un kodo vecchio, non da quelli morenti o antichi.$B$BI maghi, te lo dico io, certe cose che vogliono... sono proprio strane.",
  obj = "Porta 7 fiale di Scorpashi Venom e 3 Aged Kodo Hide a Kreldig Ungor, a Desolace.",
  progress = "Mi dispiace di non averti saputo dire dove trovare i kodo o gli scorpashi. Non conosco molto bene la zona, e non ho avuto tempo di esplorarla.",
  reward = "Il tuo aiuto qui è una manna, $N. Stai dimezzando come minimo il tempo che devo passare qui a Desolace. Con il tuo aiuto, in un attimo sarò di nuovo a Ironforge a scaldarmi i piedi.$B$BQuando avremo sistemato questa lista e sarò di nuovo a casa, vieni a trovarmi: una birra te la offro di sicuro.$B$BMa fino ad allora, raccogliamo il resto di questi reagenti.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.",
}
T[1462] = {
  title = "Sapta di Terra",
  obj = "Parla con Seer Ravenfeather per avere un'altra Earth Sapta.",
  reward = "Prendila, e ricorda: è sacra.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Seer Ravenfeather for another Earth Sapta.",
}
T[1463] = {
  title = "Sapta di Terra",
  obj = "Parla con Canaga Earthcaller per avere un'altra Earth Sapta.",
  reward = "Te ne do una in buona fede. Hai già dimostrato il tuo valore una volta, ma io mi sa che in futuro devi stare più $Gattento:attenta;.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Canaga Earthcaller for another Earth Sapta.",
}
T[1464] = {
  title = "Sapta di Fuoco",
  obj = "Parla con Telf Joolam per avere un'altra Fire Sapta.",
  reward = "Che il fuoco arda nel tuo cuore, $N.$B$BGli elementi ti aspettano.",
  en_title = "Fire Sapta",
  en_obj = "Speak to Telf Joolam for another Fire Sapta.",
}
T[1465] = {
  title = "La Ricerca di Vahlarriel",
  desc = "Continuando a perquisire il carro trovi non solo un ciondolo, ma anche delle impronte che si allontanano verso sud. In lontananza vedi il fumo che sale da un grande forte. È il fumo di un fuoco tenuto acceso, non di edifici in fiamme, e l'istinto ti dice che i Malem, se ancora vivi, sono stati portati in quella direzione.$B$BPensi che Vahlarriel, a Nijel's Point, non debba solo vedere il ciondolo che hai trovato, ma anche sapere dei segni di vita a sud.",
  obj = "Riporta il Malem Pendant a Vahlarriel Demonslayer, a Desolace.",
  reward = "Esasperante! Tutto questo disastro!$B$BEntrambi erano stati avvertiti di quanto sarebbe stato pericoloso venire qui. Ora sono spariti tutti e due... o peggio.$B$BHai detto di aver visto delle tracce dirette verso un forte qui vicino? Potrebbe essere la nostra carta migliore.$B$BDa quello che dice la gente del posto, quella fortezza è infestata da membri della Burning Blade — orchi che si sono votati alla causa dei demoni. Forse non rappresentano ciò in cui crede la maggior parte dell'Orda, ma sono malvagi e ti uccideranno a vista se ti sorprendono a spiare.",
  en_title = "Vahlarriel's Search",
  en_obj = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.",
}
T[1466] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Questa è l'ultima voce della lista, e non ti mentirò: non è un bel lavoro. Mi aspetto anche che ti porti via un po' più di tempo delle altre.$B$BAllora, basta avvertimenti, cominciamo. Leftwitch dice che gli servono: dieci cervelli di mangiatori di mana, cacciatori di maghi o cacciatori della faglia. Dieci ali fatue da un'ancella, una sorella o una maga fatua. E... dieci fiale di sangue di custode della rovina da un capitano o da un signore dei custodi della rovina.$B$BAbbastanza semplice, eh? Accidenti... se vuoi rinunciare a questa, ti capirei.",
  obj = "Porta 10 Felhound Brain, 10 Nether Wing e 10 fiale di Doomwarder Blood a Kreldig Ungor, a Desolace.",
  progress = "Non sapevo nemmeno che a Desolace ci fossero queste cose demoniache. L'ultima volta che ho letto qualcosa in proposito, i centauri erano praticamente i padroni di queste terre, dopo che anni fa gli elfi della notte avevano fatto i bagagli e se n'erano andati.$B$BMi chiedo perché si siano stabiliti qui, e come.",
  reward = "Sul serio? Non l'avrei mai detto. Sei incredibile, $N. Affrontare dei demoni per gli esperimenti di un mago, e per giunta tornare $Gtutto intero:tutta intera;. Ottimo lavoro!$B$BParlerò di te a Roetten di persona quando tornerò a Ironforge.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.",
}
T[1467] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Per ricevere la paga, dovrai tornare a Ironforge e parlare con Roetten in persona. Sarà comunque felice di togliersi di mezzo il pacco di Leftwitch. Dagli solo questo e dovrebbe bastare per avere il tuo bottino.$B$BE non preoccuparti, metterò comunque una buona parola per te quando tornerò. Non dovrei restare a Desolace ancora per molto.",
  obj = "Riporta Leftwitch's Package a Roetten Stonehammer, a Ironforge.",
  progress = "Salute, $N. Gli affari vanno a gonfie vele, il clangore delle incudini risuona per tutta Ironforge, i mantici attizzano i fuochi e mia moglie mi sta preparando una torta per il dessert dopo la cena di stasera. Si può chiedere di meglio alla vita?",
  reward = "Ah, il pacco per Leftwitch da Desolace. Eccellente. Apprezzo il lavoro, e la tua puntualità, $C. Sono contento di averti avuto con noi almeno per questo piccolo lavoro.$B$BHo il tuo pagamento proprio qui. Che si sappia: la Reclaimers Inc. paga sempre bene per una dura settimana di lavoro.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.",
}
T[1468] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.$B$BForza, $N, usa il fischietto e conosci il tuo protetto! Sono sicura che il bambino non vedrà l'ora di conoscerti.",
  obj = "Usa lo Human Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Ehm... ciao. Mi chiamo Randis, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. Sono contento di conoscerti.$B$BSpero che ci divertiremo un sacco insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco, sì, $Gsignore:signora;.",
  en_title = "Children's Week",
  en_obj = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[1469] = {
  title = "Il Racconto di Rhapsody",
  desc = "Prima del volo mi sono scolato un barile intero di birra scura. Hic!$B$BE che volo è stato. Sfrecciavo di qua e di là con Brohann che mi veniva dietro. Però il tempio non l'ho mica visto. Hic!$B$BBe', il tempio non l'ho mica visto finché non mi sono ubriacato un po' troppo e sono cascato dalla cavalcatura. Sono finito dritto in acqua e sono stato risucchiato giù. Mi sono ritrovato circondato da un branco di troll inquietanti. Me la sono filata a nuoto in un lampo, eccome! Mi sono pure portato via questo ricordino troll. Tieni, portalo a Brohann e digli che il suo tempio è proprio là sotto. Hic!",
  obj = "Porta l'Atal'ai Tablet Fragment a Brohann Caskbelly a Stormwind.",
  progress = "Finalmente sei $Gtornato:tornata;, $N. È passato parecchio tempo dall'ultima volta che abbiamo parlato. Pensavo che ti fossi $Gdimenticato:dimenticata; della mia missione.$B$BHai trovato quel furbastro del cavaliere di grifoni? Aveva qualcosa da riferire?",
  reward = "Rhapsody Shindigger! Ma certo... come ho potuto dimenticare un nome così?$B$BQuindi sapeva fin dall'inizio che il tempio era sprofondato? Be', questo ti avrebbe di certo risparmiato un bel po' di strada.$B$BMa questo manufatto degli Atal'ai! Perbacco, è una bella scoperta!",
}
T[1470] = {
  title = "Squarciare il Velo",
  desc = "Salve, $Gfigliolo:figliola;. Vedo che sei ancora $Gacerbo:acerba; nell'arte $Gdel:della; $C, e il potere ti sfugge ancora. Percepisco la tua voglia di imparare.$B$BE imparerai.$B$BNon c'è forza nell'ignoranza. La conoscenza è il nostro potere più grande. Applicandola possiamo controllare le magie del caos e gli esseri del vuoto, piegandoli alla nostra volontà.$B$BTi mostrerò come vincolare un servitore alla tua volontà, ma prima devi portarmi tre teschi degli scheletri rattlecage vicino alla fucina abbandonata.",
  obj = "Porta a Venya Marthand 3 Rattlecage Skull.",
  progress = "Ora il tuo potere è scarso, anche se sospetto che tu ne intuisca già le possibilità.$B$BPerfino i morti potrebbero sentirsi vivi, con quel potere che ci scorre dentro.",
  reward = "Anche se non sei ancora $Gstato messo:stata messa; alla prova e sei agli inizi del tuo apprendistato, hai dimostrato di possedere abilità sufficienti a padroneggiare l'evocazione e il vincolo di un imp. Non lasciarti ingannare dalle dimensioni di un imp. Anche se gli manca la forza fisica, possiede poteri e un'astuzia che ti saranno molto utili.$B$BAscoltami con attenzione, $N, perché non ripeterò questa lezione, e lascerò a te il compito di padroneggiarla.",
  en_title = "Piercing the Veil",
  en_obj = "Bring Venya Marthand 3 Rattlecage Skulls.",
}
T[1471] = {
  title = "Il Vincolo",
  desc = "Avrai certamente visto il cerchio di evocazione qui sotto? Solo lì potrai richiamare un voidwalker non vincolato.$B$BCon queste rune potrai richiamarlo, e poi dovrai dominarlo con la forza delle armi e della magia.$B$BUna volta sottomesso, sarà al tuo servizio. Allora vieni da me, e ti spiegherò l'incantesimo di evocazione, così che possa servirti per qualunque scopo tu voglia.",
  obj = "Usando le Runes of Summoning, evoca e sottometti un Voidwalker, poi riporta le Runes of Summoning a Carendin Halgar, in Magic Quarter, a Undercity.",
  progress = "Mi aspetto di avere notizie del tuo successo, $N. Se dovessi fallire, però, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.",
  reward = "Hai fatto un buon lavoro, $N. Ora ti trasmetterò l'incantesimo per evocare il voidwalker.$B$BIl potere che ha scatenato contro di te ora è ai tuoi ordini. Usalo con saggezza.",
  en_title = "The Binding",
  en_obj = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1472] = {
  title = "Divoratrice di Anime",
  desc = "Una succube è una divoratrice di anime, una distruttrice di cuori, una tentatrice di uomini. Una creatura di profonda malvagità, con la mente fissa su un solo scopo.$B$BNon può essere portata nel nostro mondo senza uno stimolo.$B$BPer questo usiamo la sua stessa forza contro di lei. Con i cuori di uomini buoni, uomini puri, uomini amorevoli, la succube non potrà resistere e passerà nel nostro mondo. Allora potrai dominarla e renderla tua.$B$BParla con il mio assistente, Godrick Farsan, nel Tempio. Ti aiuterà a trovare l'esca.",
  obj = "Parla con Godrick Farsan, nel Temple of the Damned.",
  reward = "Ti manda Carendin? Allora sei $N.$B$BNon sottovalutarmi solo perché ho perso la vista. Ora vedo le cose che si celano dietro, con una chiarezza che non avevo mai conosciuto. Quella che un tempo credevo una maledizione, ora è una benedizione.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Godrick Farsan in the Temple of the Damned.",
}
T[1473] = {
  title = "Creatura del Vuoto",
  desc = "Sembra che tutti siano d'accordo sul fatto che tu sia $Gpronto:pronta; a imparare a evocare un voidwalker.$B$BÈ un essere creato dal caos che si trova oltre: se ne evochi uno ma non riesci a controllarlo, verrai $Gfatto:fatta; a pezzi.$B$BIl primo voidwalker fu evocato da Egalin, e il procedimento è spiegato nel suo grimorio.$B$BPurtroppo ce l'ha rubato un agente della Crociata Scarlatta, che lo tiene nascosto nella sua base, in una torre a ovest. Portamelo, e ti trasmetterò la conoscenza.",
  obj = "Recupera Egalin's Grimoire e portalo a Carendin Halgar, nel Temple of the Damned.",
  progress = "Egalin fu il maestro che mi istruì. Gli bastava un'occhiata per comandare il voidwalker che aveva evocato.$B$BQuando venne il mio turno di provarci, peccai di presunzione. Non scherzare con i poteri che maneggi, $N: possono consumare anche i più vigili.",
  reward = "Ah, eccellente. Con ogni probabilità, Perrine ignorava il vero potere del libro ammuffito che ci aveva rubato.$B$BNon ci sfuggirà più di mano. Osserva, $N, la struttura dell'incantesimo, il modo in cui il tuo potere deve essere incanalato.",
  en_title = "Creature of the Void",
  en_obj = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.",
}
T[1474] = {
  title = "Il Vincolo",
  desc = "Usando questi cuori, lancia un incantesimo nel cerchio di evocazione per aprire un varco da cui la succube possa passare. Ora i tuoi poteri sono maggiori, e ti serviranno tutti per sconfiggere la succube.$B$BGuardati dal suo fascino, $N: molte menti forti sono state piegate alla sua volontà. Una volta sconfitta, la succube tornerà nel vuoto, e io ti insegnerò l'incantesimo per richiamarla ai tuoi ordini.",
  obj = "Usando i Pure Hearts, evoca e sottometti una Succubus, poi riporta i Pure Hearts a Carendin Halgar, nel Magic Quarter dell'Undercity.",
  progress = "Tra i poteri che vengono da oltre il vuoto, la succube è uno dei più pericolosi, perché i deboli sono i più facili da rigirare a suo piacimento.$B$BRicordalo, ora e in futuro.",
  reward = "Ancora una volta hai fatto un buon lavoro, $N. Era da parecchio tempo che non vedevo $Gun giovane stregone:una giovane strega; con un potenziale come il tuo. Ti assicuro che continuerò a seguire i tuoi progressi, e a prepararti e aiutarti nelle tue prove future.$B$BPer ora, lascia che ti mostri l'incantesimo di evocazione per la succube che hai appena dominato.",
  en_title = "The Binding",
  en_obj = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1475] = {
  title = "Nel Temple of Atal'Hakkar",
  desc = "Secondo la leggenda, il Temple of Atal'Hakkar è un santuario consacrato all'antico dio Hakkar il Soulflayer. A occuparsene è una feroce tribù di troll chiamata Atal'ai, e si dice che il tempio sia impenetrabile.$B$BOra che è sprofondato sotto il Bacino delle Lacrime, recuperare manufatti dal tempio è ancora più difficile. Ma è proprio questo che devi fare per me, $N.$B$BAiutami raccogliendo le Tavolette degli Atal'ai intatte. Portamele e tornerò alla Lega degli Esploratori da eroe. La gloria la divideremo insieme.",
  obj = "Raccogli 10 Atal'ai Tablets per Brohann Caskbelly a Stormwind.",
  progress = "Ora che sulla mia carriera cala lentamente il crepuscolo, mi rivolgo a te, $N, perché mi aiuti nella mia ultima missione per la Lega degli Esploratori. Se le mie vecchie ossa trovassero la forza di affrontare la Swamp of Sorrows e il tempio sommerso, combatterei proprio al tuo fianco.$B$BL'orgoglio mi rende difficile chiederti aiuto per raccogliere le Tavolette degli Atal'ai. Ma la vecchiaia non mi lascia scelta.$B$BTi prego, aiutami, $N. Voglio ritirarmi dalla Lega degli Esploratori dopo aver portato a termine il suo ultimo incarico.",
  reward = "Le Tavolette degli Atal'ai! Grazie, $N!$B$BQuando le avrò consegnate alla Lega degli Esploratori, i nostri nomi passeranno alla storia insieme. Hai aiutato un vecchio nano a compiere l'ultimo dovere della sua vita. Te ne sarò grato in eterno.",
}
T[1476] = {
  title = "I Cuori dei Puri",
  desc = "Uomini d'onore e di bontà? Esiste davvero un uomo così?$B$BCi sono volute molte ricerche, ma mettendo insieme frammenti di storie sentite qua e là, sono riuscito a trovare due uomini che dovrebbero andare bene.$B$BIl primo è Dalin Forgewright, che si è dedicato alla cura dei profughi di Lordaeron, respinti dalla loro stessa gente al Muro di Greymane.$B$BL'altro è Comar Villard, un uomo che resta fedele al suo amore perduto e vaga per le Wetlands in cerca di una traccia di sua moglie.$B$BConsegna i loro cuori a Carendin. Ma prima, lascia che ti mostri le tue prede.",
  obj = "Porta i cuori di Dalin Forgewright e di Comar Villard a Carendin Halgar, nel Temple of the Damned.",
  progress = "Sono piacevolmente sorpreso dalla rapidità dei tuoi progressi finora, $N. Portami i cuori e mi stupirai ancora una volta.",
  reward = "Il cuore di un uomo buono sembra uguale a qualsiasi altro, visto così, non trovi?$B$BForse abbiamo una visione un po'... diversa... della cosa. Questi andranno bene, comunque. Non ho dubbi che una succube sarebbe attratta dalla loro purezza.",
  en_title = "Hearts of the Pure",
  en_obj = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.",
}
T[1477] = {
  title = "Rifornimenti Vitali",
  desc = "I nostri maghi stanno conducendo delle ricerche a Nethergarde Keep, nelle Blasted Lands: ricerche vitali per capire i Portali Oscuri. Hanno bisogno di rifornimenti quasi continui, ma la nostra linea di rifornimento verso Nethergarde è fragile.$B$BDevi aiutarci a fare in modo che i rifornimenti arrivino a Nethergarde. Presentati al Capo della Guardia Sorigal, a Darkshire, e fa' quello che ti chiede. Questo compito ti porterà in terre ostili, $N. Preparati.",
  obj = "Parla con Watchmaster Sorigal.",
  reward = "Ti ha mandato Andromath? Molto bene. Ho un compito importante per te...",
  en_title = "Vital Supplies",
  en_obj = "Speak with Watchmaster Sorigal.",
}
T[1478] = {
  title = "La Convocazione di Halgar",
  desc = "Ah, $N! Ho appena saputo da Carendin Halgar che vorrebbe vederti per continuare il tuo addestramento.$B$BDovresti essere $Gfiero:fiera; di te $Gstesso:stessa;, $N. Non capita tutti i giorni che il Maestro Halgar ritenga opportuno istruire di persona $Gun giovane stregone:una giovane strega;.$B$BLo troverai nel Quartiere della Magia dell'Undercity, vicino al Tempio dei Dannati.",
  obj = "Parla con Carendin Halgar, nell'Undercity.",
  reward = "Bene, vedo che Ageron è riuscito a trovarti, $N. Non perdiamo tempo in chiacchiere e convenevoli e concentriamoci sul tuo addestramento. Hai ancora molto da imparare.",
  en_title = "Halgar's Summons",
  en_obj = "Speak with Carendin Halgar in the Undercity.",
}
T[1479] = {
  title = "Il Ramo degli Eterni",
  desc = "Ho sentito raccontare che gli elfi della notte tengono la loro banca dentro un albero, uno che sembra un orso! Troppo forte! Gli elfi della notte sono simpatici, con quella loro passione per la natura e tutto il resto, ma gli orsi sono proprio fantastici!$B$BMi porteresti a vedere l'albero-orso a Darnassus, per piacere? C'è una nave che ci porta lì vicino, e non dovrebbe volerci molto. Per piacere, per piacere, per piacere!",
  obj = "Porta l'orfano alla banca di Darnassus. La banca è scavata in un albero noto come Bough of the Eternals.",
  progress = "Siamo arrivati?",
  reward = "Wow, era ancora più bello di come me l'ero immaginato: il Ramo degli Eterni! Non pensavo fosse così grande, e invece lo era! Hai visto anche l'uccello in cima?! Chissà come hanno fatto a dare quella forma ai rami!$B$BGrazie di avermi portato a Darnassus, $N. Sei $Gfantastico:fantastica;!",
  en_title = "The Bough of the Eternals",
  en_obj = "Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals.",
}
T[1480] = {
  title = "Il Corruttore",
  desc = "La pelle strappata ha un odore di marcio ed è sorprendentemente flessibile per qualcosa che sembra secco e fragile.$B$BMentre la srotoli, vedi chiaramente su un lato dei segni rossi di una qualche lingua. In fondo alla pelle c'è un simbolo molto chiaro che immagini sia una specie di firma.$B$BForse Maurin potrebbe dirti qualcosa di più?",
  obj = "Porta la Flayed Demon Skin a Maurin Bonesplitter, a Desolace.",
  progress = "Quelli della Burning Blade cominciano a capire quanto siano davvero deboli. Le loro magie sono patetiche, la loro forza misera.$B$BIl loro unico potere viene da coloro che servono, e non da una qualche comprensione del vero potere e della vera conoscenza.",
  reward = "Hmm, queste rune sono davvero una lingua, $N, una lingua antica. Somigliano vagamente alla lingua Eredun, ma le differenze sono enormi. Se non mi sbaglio, si tratta di una specie di contratto... Ecco, sì, questo simbolo è la firma del demone: Lord Azrethoc.",
  en_title = "The Corrupter",
  en_obj = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.",
}
T[1481] = {
  title = "Il Corruttore",
  desc = "Credo di poter trovare questo signore dei demoni, con i reagenti giusti.$B$BSe è davvero potente come sospetto, mi serviranno oggetti presi da creature letali. Ma tu agisci in nome del Capoguerra, quindi di sicuro accetterai il mio compito.$B$BPer prima cosa dovrò spezzare le protezioni che ha contro la divinazione. Per questo mi servirà lo scalpo di un satiro — ma non di un satiro qualsiasi. Lo scalpo deve venire da un inseguitore dell'ombra Hatefury.$B$BCercali tra le antiche rovine nel nord-est di Desolace.",
  obj = "Porta uno Shadowstalker Scalp a Maurin Bonesplitter, a Desolace.",
  progress = "Non portarmi uno scalpo sbagliato, $C. Usare i reagenti sbagliati potrebbe costarci la vita. Il signore dei demoni potrebbe avere su di sé incantesimi pronti a scattare per uccidere chi tenta di spiarlo con la divinazione.$B$BIl destino mi ha già inflitto abbastanza dolore.",
  reward = "Gli inseguitori dell'ombra non sono riusciti a ucciderti, $C. Notevole... davvero notevole.$B$BQuesto scalpo andrà benissimo per il mio incantesimo. Mentre eri via, sono riuscito a procurarmi alcuni degli altri reagenti che servono per l'incantesimo.$B$BCi sono quasi. Mi serve solo un catalizzatore per l'incantesimo — qualcosa che proietti un'immagine del signore dei demoni e del luogo in cui si trova.",
  en_title = "The Corrupter",
  en_obj = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.",
}
T[1482] = {
  title = "Il Corruttore",
  desc = "Un cristallo dell'oracolo andrebbe benissimo. I naga li fabbricano perché li usino i loro oracoli.$B$BA nord-ovest di qui, lungo la costa, c'è una vasta barriera corallina che i naga hanno preso come dimora quando si trovano così vicini alla riva. Là troverai i loro oracoli. Gli Slitherblade sono letali e non accoglieranno di buon grado le tue intrusioni, quindi fa' attenzione e sbrigati.$B$BQuando tornerai, vedremo di trovare questo signore dei demoni, Azrethoc.",
  obj = "Porta un Oracle Crystal a Maurin Bonesplitter, a Desolace.",
  progress = "Sono pronto per il cristallo dell'oracolo, $C. Trovare e distruggere questo Lord Azrethoc ci farebbe salire tutti e due di molto nella stima del Capoguerra. Faremmo bene a lavorare insieme, e a farlo in fretta, così da perseguire i nostri scopi e ingraziarci il Capoguerra.",
  reward = "Un prezioso cristallo dell'oracolo... perfetto... bellissimo. Davvero.$B$BCominceremo subito. Trovare questo signore dei demoni dev'essere la nostra prima preoccupazione, e ucciderlo richiede tutta la nostra attenzione.$B$BFai un passo indietro, $C, e vediamo che cos'è questo demone e dove si può trovare.",
  en_title = "The Corrupter",
  en_obj = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.",
}
T[1483] = {
  title = "Ziz Fizziks",
  desc = "La Venture Company ci ha rubato molte delle migliori teste goblin, ma ogni tanto ci capita l'occasione di rubargliene qualcuna a nostra volta.$B$BTempo fa la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle — uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ne è rimasto così sconvolto che mi ha supplicato di trovargli un nuovo impiego nella Tinkers' Union. Gli ho affidato qualche incarico, ma potrebbe aver bisogno d'aiuto.$B$BMagari potresti andare a dargli un'occhiata per me? È di stanza sul margine occidentale della Landa di Windshear.",
  obj = "Parla con Ziz Fizziks, a Windshear Crag.",
  reward = "Pensavo che i pezzi grossi della Venture Company fossero degli aguzzini, poi ho conosciuto Sputtervalve, il più crudele di tutti!$B$BAh! Anche se è sempre meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.",
  en_title = "Ziz Fizziks",
  en_obj = "Speak with Ziz Fizziks in Windshear Crag.",
}
T[1484] = {
  title = "Il Corruttore",
  desc = "Questa creatura è molto più pericolosa di quanto avessi previsto. Di sicuro Takata dubita delle mie capacità di affrontare una creatura simile, e sarebbe un'offesa al suo onore non informarlo di quello che è appena successo.$B$BParla con lo spadaccino, digli che sei $Gdisposto:disposta; a uccidere il demone se lui te lo permette, ma non insistere troppo. È meglio se pensa che l'idea sia sua.",
  obj = "Parla con Takata Steelblade, a Desolace.",
  reward = "Ho visto quello che è appena successo con Maurin e il signore dei demoni. Quella creatura, anche solo come apparizione, sembra avere più potere del mio compagno stregone. Mi chiedo: sarà all'altezza di sconfiggere il mostro? Servirei meglio il Capoguerra se andassi io stesso, ma con le responsabilità che ho qui, disonorerei il mio clan se voltassi le spalle ai miei doveri per combattere questo male in nome del mio onore.",
  en_title = "The Corrupter",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1485] = {
  title = "I Famigli Vili",
  desc = "Gli stregoni che ci hanno preceduto si sono guadagnati la sfiducia dell'Orda, e anche se siamo tollerati, non siamo amati.$B$BQuesto però non ha avvicinato gli stregoni tra loro, perché molti scelgono di vivere appartati, dilettandosi con la magia da soli. Non cercherò di condurti su una strada o sull'altra, ma solo di aiutarti a crescere.$B$BPrima di insegnarti l'arte dell'evocazione, portami sei teste dei famigli vili dalla caverna a nord-est.",
  obj = "Porta 6 Vile Familiar Head a Ruzan.",
  progress = "È importante che tu sappia controllare gli esseri che evochi con la tua magia. Sono così pochi quelli interessati a imparare le vie $Gdel:della; $C che non rischierei la tua vita insegnandoti qualcosa prima che tu sia $Gpronto:pronta;.",
  reward = "Durante il tuo addestramento da $C, imparerai a richiamare esseri di molti tipi. Alcuni potrebbero non sembrarlo, ma sono tutti strumenti utili.$B$BNon lasciarti ingannare dalle piccole dimensioni dell'imp. Come avrai certamente notato, resta un avversario temibile.",
  en_title = "Vile Familiars",
  en_obj = "Bring 6 Vile Familiar Heads to Ruzan.",
}
T[1486] = {
  title = "Pelli Degeneri",
  desc = "Mentre Naralex sprofondava sempre più nel suo incubo, dal sottosuolo delle Barrens è emersa nelle Wailing Caverns una strana stirpe di bestie.$B$BQueste creature degeneri hanno proprietà strane, ultraterrene. Sono malvagie per natura, ma secondo me dalla loro esistenza qui in Kalimdor può venire qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nell'arte della conciatura.$B$BSe te la senti, avventurati nelle grotte qui sotto e recupera qualche pelle degenere.",
  obj = "Nalpak, nelle Wailing Caverns, vuole 20 Deviate Hide.",
  progress = "Mi interessa molto esaminare le pelli delle creature degeneri che hanno infestato queste grotte. Hai avuto fortuna a raccoglierne qualcuna, $C?",
  reward = "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, $N.$B$BGrazie per la tua dedizione.",
  en_title = "Deviate Hides",
  en_obj = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.",
}
T[1487] = {
  title = "Sterminio dei Degeneri",
  desc = "Naralex aveva un fine nobile.$B$BIl nostro grande capo aspirava a entrare nell'Emerald Dream e a far rinascere in queste terre aspre la foresta rigogliosa di un tempo. Ma qualcosa è andato terribilmente storto.$B$BIl sogno di Naralex si è trasformato in un incubo e creature corrotte hanno cominciato a popolare le caverne.$B$BMentre alcuni Disciples of Naralex cercano di svegliare il nostro maestro, io mi preoccupo di liberare queste grotte dalle bestie malvagie.$B$BAffronta le caverne, $N, e stermina la progenie degenere.",
  obj = "Ebru, nelle Wailing Caverns, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.",
  progress = "$N, noi Disciples of Naralex abbiamo bisogno del tuo aiuto. Siamo sempre di meno, ora che il nostro maestro è intrappolato nel suo incubo contorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.$B$BTi supplico, entra nelle grotte e fa' guerra alle creature degeneri!",
  reward = "Da Disciple of Naralex, lodo il tuo coraggio, $N.$B$BIl tuo aiuto nel ripulire le caverne è il primo passo del nostro lungo e difficile cammino per vedere le Barrens risanate.$B$BGrazie, e che tu possa prosperare.",
  en_title = "Deviate Eradication",
  en_obj = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",
}
T[1488] = {
  title = "Il Corruttore",
  desc = "Anche se non so nulla di questo Lord Azrethoc, sono d'accordo con Maurin: va fermato, soprattutto se sta cercando di ottenere influenza sulla Burning Blade per i suoi scopi.$B$BHai già dimostrato di voler aiutare il Capoguerra, e ti affiderei volentieri il compito di radunare un gruppo e uccidere il signore dei demoni e il suo servo stregone.$B$BQuando sei $Gpronto:pronta;, va' dritto a sud, e torna da me quando la minaccia sarà eliminata.",
  obj = "Uccidi Lord Azrethoc e Jugkar Grim'rod e torna da Takata Steelblade, a Desolace.",
  progress = "Gloria all'Orda, e morte ai nostri nemici, $N!$B$BI demoni di Desolace sono una minaccia più grande che mai. La mia speranza di tornare dal Capoguerra si affievolisce man mano che compaiono sempre più di quelle creature immonde.$B$BA volte vorrei che avessimo a che fare solo con i centauri.",
  reward = "Una grande vittoria per tutti noi, $N. Gioiamo del tuo successo. Ora confido che il nostro futuro qui non sia così cupo come pensavo un tempo.$B$BI demoni saranno uccisi, gli sforzi della Burning Blade saranno vani, e un giorno potremo di nuovo chiamare casa un luogo sicuro.",
  en_title = "The Corrupter",
  en_obj = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",
}
T[1489] = {
  title = "Hamuul Runetotem",
  desc = "I gusci che mi hai portato sono intaccati da una corruzione che non avevo mai visto prima. Sono certo che la causa sia l'acqua delle Oasi, e sento la confusione che portano in questa terra. È come se la terra sognasse e non riuscisse a svegliarsi.$B$BLe Wailing Caverns devono essere l'origine della corruzione. Ma prima di andarci, parla con Hamuul Runetotem, il druido anziano. Gli ho fatto sapere quello che succede nelle Barrens. È saggio, e può consigliarti.$B$BLo troverai a Thunder Bluff, sull'Elder Rise.",
  obj = "Parla con Hamuul Runetotem",
  reward = "Ti porgo il mio saluto, $N. Sei $Gil benvenuto:la benvenuta; qui, e ti consiglio di raccogliere tutte le tue forze. Perché il compito che ora ti affidiamo... è terribile.",
  en_title = "Hamuul Runetotem",
  en_obj = "Speak with Hamuul Runetotem.",
}
T[1490] = {
  title = "Nara Wildmane",
  desc = "Sono entrato nella terra dei sogni, e ho sognato una setta di druidi che dimora nelle Wailing Caverns. Ho visto che un tempo i loro fini erano nobili, ma hanno smarrito la via. Ora sono servi della corruzione che si insinua nelle Barrens.$B$BSono vecchio e le forze mi vengono meno. Non ho potuto restare a lungo in quel luogo di sogno e so poco altro dei druidi corrotti. Ma Nara è giovane e il suo spirito è fiero. Lei è rimasta nel sogno quando io sono fuggito.$B$BParla con Nara. È nella tenda laggiù.",
  obj = "Parla con Nara Wildmane.",
  reward = "Sì, è vero. So dei druidi delle Wailing Caverns. Ho visto le loro facce contorte e squamose. Conosco i loro crimini, e conosco i loro piani.$B$BDevi fermarli, $N.",
  en_title = "Nara Wildmane",
  en_obj = "Speak with Nara Wildmane.",
}
T[1491] = {
  title = "Bevande dell'Intelligenza",
  desc = "Ok, i corni di raptor non hanno funzionato granché. Ma va bene — nessuno è diventato ricco al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande dell'intelligenza!$B$BC'è una sostanza che si chiama Essenza Lamentosa, e secondo me è la causa delle piante e degli animali strani delle Barrens. Procuramene un po' e la proverò nella mia bevanda!$B$BHo sentito che l'essenza si accumula nelle creature ectoplasmiche delle Wailing Caverns, a ovest. Caccia quelle creature e raccogli l'essenza.",
  obj = "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix, a Ratchet.",
  progress = "Dov'è la mia essenza lamentosa?",
  reward = "Ottimo, ce l'hai! Non vedo l'ora di provarla. Questa mi farà fare una fortuna, me lo sento!$B$BGrazie, $N. Prendi questo, e quando sarò ricco te ne manderò dell'altro, promesso!",
  en_title = "Smart Drinks",
  en_obj = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",
}
T[1498] = {
  title = "La Via della Difesa",
  desc = "Per noi guerrieri, uno dei compiti più importanti è... la protezione. Siamo lo scudo dell'Orda, e teniamo al sicuro i nostri fratelli più deboli. Se vuoi unirti alle nostre file, devi dimostrarmi quanto vali.$B$BVa' alla Fossa del Tuono, in Durotar, dove vivono i sauri del fulmine e i sauri del tuono. Caccia quelle bestie! Dimostrami che sei più resistente di loro! Affronta i loro attacchi e portami un mucchio delle loro scaglie strinate come prova.$B$BFallo, e allora ti insegnerò.",
  obj = "Porta 5 Singed Scale a Uzzek, al Far Watch Post, nelle Barrens.",
  progress = "Hai le scaglie, $N? Se non riesci a resistere agli attacchi dei sauri del tuono, i miei insegnamenti non ti serviranno a niente.",
  reward = "Ah. Vedo che hai sconfitto i sauri del tuono, e questo dimostra che sei resistente. Ora ti mostrerò come una pelle dura e movimenti accorti possano unirsi a formare un impenetrabile muro di difesa.$B$BImpara bene la lezione, $N. E tieniti $Gpronto:pronta; per i prossimi insegnamenti.",
  en_title = "Path of Defense",
  en_obj = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.",
}
T[1499] = {
  title = "I Famigli Vili",
  desc = "Zureetha manda i novizi come te ad aiutare a sfoltire le creature nella caverna vicino a dove hai combattuto i famigli vili.$B$BCredo che ti farebbe bene fare esperienza aiutandola. Dille che hai contribuito a risolvere il problema degli imp: probabilmente avrà una ricompensa per te.",
  obj = "Parla con Zureetha Fargaze.",
  reward = "Hai fatto un buon lavoro, $N.$B$BAnche se i famigli vili erano solo animaletti al servizio dei poteri più oscuri della Burning Blade, il tuo successo contro di loro fa presagire imprese più grandi.",
  en_title = "Vile Familiars",
  en_obj = "Speak with Zureetha Fargaze.",
}
T[1501] = {
  title = "Creatura del Vuoto",
  desc = "Sono rimasti così pochi stregoni... Rischiamo molto, ma i rischi sono giustificati. Devi raggiungere in fretta la piena maturità nelle tue capacità, se vuoi essere utile all'Orda e al Capoguerra.$B$BÈ ora che tu impari un nuovo incantesimo di evocazione.$B$BPrima devi recuperare la Tavoletta di Verga, rubata dagli stregoni della Burning Blade e ora custodita nel loro covo alla Roccia del Teschio, a est della città. Con la tavoletta, ti mostrerò le rune necessarie per evocare un voidwalker.",
  obj = "Recupera la Tablet of Verga per Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Hai la Tavoletta di Verga, $N? Se no, non voglio parlarti finché non ce l'avrai.",
  reward = "Bene. Spero che tu abbia inflitto qualche altra perdita alla Burning Blade quando sei $Gandato:andata; a recuperarla.$B$BSono stati una grande seccatura per il Capoguerra, e una grande piaga per tutti gli stregoni.",
  en_title = "Creature of the Void",
  en_obj = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.",
}
T[1502] = {
  title = "Thun'grim Firegaze",
  desc = "È fondamentale che l'arma di un guerriero sia di qualità. E se c'è un orco capace di forgiare armi di qualità, quell'orco è Thun'grim Firegaze. È un eremita che vive in cima alle colline a est del Crossroads.$B$BSe cerchi un'arma, $Gguerriero:guerriera;, allora dovresti cercare Thun'grim. Per trovarlo, raggiungi prima il Crossroads, a ovest, poi dirigiti a est tra le colline. Il suo accampamento è in alto, sulla cima di una collina.",
  obj = "Parla con Thun'grim Firegaze, nelle Barrens.",
  reward = "I miei occhi si sono seccati da tempo a forza di fissare la fiamma della forgia, ma certe cose riesco ancora a vederle. Vedo che vuoi qualcosa.$B$BE se hai trovato la strada fin qui, posso immaginare cosa desideri.",
  en_title = "Thun'grim Firegaze",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1503] = {
  title = "Acciaio Forgiato",
  desc = "Ti darò un'arma, $N, ma prima devi aiutarmi. I Razormane a nord-ovest sono entrati nel mio accampamento qualche notte fa. Non volevano affrontarmi in combattimento, ma sanno che ci vedo poco — alcuni mi hanno distratto con i loro grugniti mentre altri mi derubavano! Codardi!$B$BHanno preso un forziere di ferro, e dentro c'erano delle barre d'acciaio forgiato. Se riesci a recuperarle, ti darò l'arma che cerchi.$B$BCerca la cassa di ferro negli accampamenti dei quilboar e torna con le barre d'acciaio forgiato.",
  obj = "Porta le Forged Steel Bars a Thun'grim Firegaze, nelle Barrens.",
  progress = "Hai le mie barre d'acciaio?",
  reward = "Le hai trovate! E ci sono tutte, il che non mi sorprende. Non credevo che i Razormane sapessero cosa farsene di un acciaio pregiato come questo.$B$BGrazie, $N. Ecco la tua ricompensa. Che ti sia utile.",
  en_title = "Forged Steel",
  en_obj = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.",
}
T[1504] = {
  title = "Il Vincolo",
  desc = "Ora osserva la Tavoletta di Verga, perché contiene i glifi che ti serviranno per l'evocazione. Portali al cerchio nella tenda di Neeru Fireblade, dall'altra parte della caverna. Lì potrai richiamare il voidwalker.$B$BDevi sconfiggerlo con qualunque mezzo fisico e magico tu abbia a disposizione. Fatto questo, torna da me con i glifi dell'evocazione e ti mostrerò come vincolare la creatura alla tua volontà.",
  obj = "Usando i Glyphs of Summoning, evoca e sottometti un Summoned Voidwalker, poi riporta i Glyphs of Summoning a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Il voidwalker è una creatura potente. Ricordo quando ero io al tuo posto, $N. Negli anni il mio voidwalker ha imparato a combattermi di meno, anche se sospetto che sia solo perché spera che io abbassi la guardia.$B$BRicordalo, $N.",
  reward = "Hai fatto un buon lavoro, $N. Ti mostrerò come evocare un voidwalker simile a quello che hai appena sconfitto.$B$BDevi sapere che abbiamo grandi aspettative su di te, e finora ne sei $Gstato:stata; all'altezza.$B$BMa non montarti la testa, perché i compiti che ti aspettano faranno sembrare questo facile come svegliarsi al mattino.",
  en_title = "The Binding",
  en_obj = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.",
}
T[1505] = {
  title = "Il Veterano Uzzek",
  desc = "L'Orda onora i suoi guerrieri perché la loro forza è indiscussa. Ma i guerrieri davvero grandi sono anche grandi allievi.$B$BCerca Uzzek. È un veterano di molte battaglie e ora insegna ai giovani guerrieri le vie del combattimento. Lo troverai a sud del Far Watch Post, la guarnigione orchesca al confine tra le Barrens e Durotar, a est.",
  obj = "Parla con Uzzek al Far Watch Post.",
  reward = "Salve, giovane. Sei qui per un po' di addestramento, eh?",
  en_title = "Veteran Uzzek",
  en_obj = "Speak with Uzzek at Far Watch Post.",
}
T[1506] = {
  title = "La Convocazione di Gan'rul",
  desc = "Ehi, tu. $N, giusto?$B$BSpero che tu non abbia troppi impegni, perché Gan'rul vuole vederti subito. Lo troverai con gli stregoni anziani nella Fenditura dell'Ombra.$B$BA giudicare dai miei trascorsi con Gan'rul, questa convocazione o è un'ottima cosa o è una pessima cosa.",
  obj = "Parla con Gan'rul Bloodeye, a Orgrimmar.",
  reward = "Bene. Temevo che Ophek non riuscisse a raggiungerti.$B$BÈ ora che io porti avanti il tuo addestramento da $Gstregone:strega;. Qualunque faccenda tu abbia in corso dovrà aspettare.$B$BNon ci saranno problemi, spero?",
  en_title = "Gan'rul's Summons",
  en_obj = "Speak with Gan'rul Bloodeye in Orgrimmar.",
}
T[1507] = {
  title = "Divoratrice di Anime",
  desc = "È giunto il momento che tu impari di più sulle magie di evocazione. Imparerai a evocare una succube, una creatura dai poteri mentali incredibili. Può ridurre al suo servizio chi ha una mente debole — ma non temere! Sono certo che sarai all'altezza della sfida.$B$BUna succube si può evocare solo attirandola con un oggetto che rappresenti una grande devozione e un grande amore. Lascio a te il compito di trovarlo.$B$BUn suggerimento? Parla con Cazul... Sembra che ci sia ben poco che l'antico stregone non sappia.",
  obj = "Parla con Cazul, nella Cleft of Shadow.",
  reward = "Mm... $N. Sei ancora agli inizi del tuo cammino, ma percepisco in te un potenziale di grandezza.$B$BSei $Gnato:nata; con dei doni, $N. Fa' in modo che non vadano sprecati.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Cazul in the Cleft of Shadow.",
}
T[1508] = {
  title = "Il Cieco Cazul",
  desc = "Mm... Ma certo, non è per questo che sei $Gvenuto:venuta; a parlarmi.$B$BSe Gan'rul ti ha mandato da me, vuol dire che devi evocare una succube e ti serve un oggetto per attirarla.$B$BMm... Se ti fidi a farti guidare da un cieco, $N, allora ascolta. Sulle alture di Orgrimmar, a ovest della torre dei wind riders, vive Zankaja. Aspetta il ritorno del suo compagno.$B$BVa' da lei.",
  obj = "Parla con Zankaja, a Orgrimmar.",
  reward = "Porti notizie di Dogran? Sarebbe dovuto tornare giorni fa, e non ho saputo niente...",
  en_title = "Blind Cazul",
  en_obj = "Speak with Zankaja in Orgrimmar.",
}
T[1509] = {
  title = "Notizie di Dogran",
  desc = "Il mio compagno, Dogran, è stato mandato da poco in servizio al Crossroads. Era una promozione, e ne andava molto fiero.$B$BIo ero triste, naturalmente, ma non gliel'ho fatto capire. E anche preoccupata. Le Barrens sono un posto più pericoloso di Orgrimmar, e temevo il peggio.$B$BOra è passata una settimana da quando sarebbe dovuto tornare, e non ho ricevuto sue notizie...$B$BForse potresti andare al Crossroads a vedere se hanno notizie? Lavorava con Gazrog, che dovrebbe essere ancora di stanza lì.",
  obj = "Parla con Gazrog, al Crossroads.",
  reward = "Zankaja? È la compagna di Dogran, giusto?$B$BSì, ho avuto sue notizie, ma non sono il genere di notizie da far arrivare a lei...$B$BNo, non è morto. Ma è ferito ed è prigioniero dei quilboar.",
  en_title = "News of Dogran",
  en_obj = "Speak with Gazrog at the Crossroads.",
}
T[1510] = {
  title = "Notizie di Dogran",
  desc = "Era di stanza a Camp Taurajo, dove stiamo cercando di sbarazzarci dei quilboar. Ha guidato alcuni grunt in uno dei loro accampamenti, dove è stato ferito gravemente. Gli altri sono riusciti a tornare e hanno cercato di salvarlo. Era messo male, le ferite si erano infettate, quindi avevano paura di spostarlo senza prima medicarlo.$B$BHanno mandato un messaggio qui, chiedendo una pozione curativa ai troll di Malaka'jin, ai piedi delle Stonetalon Mountains. Abbiamo mandato qualcuno a prenderla, ma non è ancora tornato.",
  obj = "Parla con Ken'zigla, a Malaka'jin.",
  reward = "$GUn altro orco:Un'altra orchessa;, eh? Spero che tu non sia qui per l'altro. Non ce l'ha fatta. Quei goblin l'hanno sistemato per bene.$B$BHa detto che gli serviva una pozione curativa, ma non ha detto molto altro.",
  en_title = "News of Dogran",
  en_obj = "Speak with Ken'zigla at the Malaka'jin.",
}
T[1511] = {
  title = "Bevanda di Ken'zigla",
  desc = "Immaginavo che qualcun altro sarebbe potuto venire a prendere la pozione, così l'ho preparata comunque.$B$BEcco qua, $N. Mi raccomando, dagliene solo metà! Gli darà abbastanza forza per muoversi senza dissanguarsi. Aspetta una notte, poi dagli l'altra metà.$B$BComunque, dovrai portarla a Logmar, a Camp Taurajo. Da quello che mi ha detto il primo, lui dovrebbe avere un'idea di dove sia questo Dogran.",
  obj = "Porta Ken'zigla's Draught a Grunt Logmar, a Camp Taurajo.",
  progress = "Sì, che c'è?",
  reward = "Beh, era ora! Dogran sta morendo là fuori, in attesa di questa pozione.$B$BDobbiamo fargliela avere subito, ma la maggior parte dei grunt di stanza qui è fuori in missione per procurarsi viveri.",
  en_title = "Ken'zigla's Draught",
  en_obj = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.",
}
T[1512] = {
  title = "Il Dono dell'Amore",
  desc = "Zankaja è giovane e bella. Legata a un invalido... Non le permetterò di subire questa ingiustizia.$B$BLasciami, $N. E grazie. Potrò porre fine alla mia vita in una battaglia gloriosa, invece che come un guscio vuoto.$B$BE ti prego, non dire niente di tutto questo alla mia compagna... Non voglio che si senta in colpa.",
  obj = "Porta il Dirt-caked Pendant a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Sei $Gtornato:tornata;. Sei $Gpronto:pronta; ad affrontare una succube?",
  reward = "Se mi dici che basterà, allora mi fido di te, $N. Lascia però che lo pulisca... Immacolato e splendente, potrebbe essere ancora più allettante per una succube.",
  en_title = "Love's Gift",
  en_obj = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1513] = {
  title = "Il Vincolo",
  desc = "Porta questo al cerchio di evocazione nella tenda di Neeru, $N. Richiama un'immonda succube, poi mostrale la tua maestria. Credo nella forza della tua magia. Come sempre, però, sta' in guardia, perché l'orgoglio e la presunzione sono stati la rovina di molti stregoni promettenti.$B$BQuando l'avrai sconfitta, riportami il ciondolo, così che io possa dare la notizia a Zankaja.",
  obj = "Usando Dogran's Pendant, evoca e sottometti una Succubus, poi riporta Dogran's Pendant a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Quando guardo una succube, il mio cuore prende il volo... Ma allo stesso tempo, sento quasi la mia anima che si ritira, come la marea.$B$BSta' in guardia, $Gamico mio:amica mia;.",
  reward = "Ce l'hai fatta! Non mi aspettavo niente di meno $Gdal mio allievo migliore:dalla mia allieva migliore;.$B$BHai dimostrato il tuo valore, e ti mostrerò volentieri il metodo per evocare la succube che hai sottomesso. Ora va', hai molto da imparare, e la prossima volta che ti vedrò mi aspetto che tu abbia raggiunto la vera padronanza della tua succube.$B$BLascia il dolore di Dogran e Zankaja a quelli tra noi che hanno più anni sulle spalle, ma ricordalo, e tienilo come protezione contro le lusinghe del potere oscuro che hai imparato a evocare oggi.",
  en_title = "The Binding",
  en_obj = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1514] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[1515] = {
  title = "La Prigionia di Dogran",
  desc = "Sei $Garrivato:arrivata; fin qui, quindi se vuoi andare fino in fondo, non ti fermerò. Però non posso darti altri uomini: sarai $Gda solo:da sola;.$B$BDogran è tenuto prigioniero in un accampamento dei quilboar a nord di qui. Cerca un gruppo di due capanne. Sarà ben sorvegliato — sempre che non l'abbiano già ucciso, o che non sia morto per le ferite.$B$BBuona fortuna.",
  obj = "Porta Ken'zigla's Draught a Dogran, nelle Barrens.",
  progress = "Urrrghhhh...",
  reward = "Che intruglio disgustoso...$B$BOra sento la forza dentro di me, abbastanza per allontanarmi zoppicando... Ma la gamba non la riavrò più per il resto della mia vita. E nemmeno il braccio.",
  en_title = "Dogran's Captivity",
  en_obj = "Bring Ken'zigla's Draught to Dogran in the Barrens.",
}
T[1516] = {
  title = "Il Richiamo della Terra",
  desc = "È giunto il momento, giovane $C. Sei $Gdiventato:diventata; forte e il tuo spirito resiste come la terra. Seguire la via dello sciamano è segno che hai saggezza, prima ancora di aver dimostrato il tuo valore.$B$BL'elemento della terra guiderà il tuo destino, e diventerà parte di te se sei $Gpronto:pronta;. Ma devi presentarti davanti alla terra stessa. Se sei $Gpronto:pronta;, vedrai cose che solo gli sciamani conoscono.$B$BCerca i Felstalker a nord e prendi due dei loro zoccoli. Poi torna da me, e parleremo ancora del tuo futuro.",
  obj = "Porta 2 Felstalker Hoof a Canaga Earthcaller, nella Valley of Trials.",
  progress = "La pazienza è la più grande virtù della terra. La terra è testimone del ciclo di tutte le cose: le montagne che diventano deserti; i fiumi che diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi, e non tollera l'impazienza.$B$BLa terra ti chiama ora perché si avvicina un tempo di conflitto. Quando tornerai da me $Gvittorioso:vittoriosa;, sarai molto più $Gvicino:vicina; a raggiungere la tua pienezza.$B$BGli altri invidieranno la tua saggezza e ti odieranno per la loro ignoranza.",
  reward = "Eccellente. Il tuo successo dimostra che sei $Gpreparato:preparata;.$B$BDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le si mostra il dovuto rispetto. Come gli altri elementi, anche la terra può essere volubile. La terra è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che la terra condivide con te.$B$BOra preparerò una sapta per te, e accettandola capirai qual è la tua strada.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.",
}
T[1517] = {
  title = "Il Richiamo della Terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia di sciamani ne conosce la ricetta.$B$BLa sapta si beve sempre in un luogo sacro, e mai altrove — ricordalo.$B$BCerca la Roccia dello Spirito, a sud-ovest di qui — si trova alla fine del Sentiero Nascosto. Bevi lì la tua sapta, e... be', vedrai.",
  obj = "Trova la Spirit Rock e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$BCon il corpo e lo spirito uniti, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.$B$BPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Spirit Rock and drink the Earth Sapta.",
}
T[1518] = {
  title = "Il Richiamo della Terra",
  desc = "Prendi questo quarzo grezzo e portalo a Canaga Earthcaller come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere a molte altre.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Canaga Earthcaller, nella Valley of Trials.",
  progress = "Voglio essere il primo a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che guideranno per sempre il tuo destino.$B$BSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso.$B$BAltrimenti, vattene finché non avrai trovato la tua strada.",
  reward = "Eccellente!$B$BIl totem che creerò per te è più di un simbolo del tuo rango come $C — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra.$B$BGli istruttori sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi.$B$BMa per ora prendi questo totem della terra, e una pergamena che ti insegnerà la tua prima abilità.",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.",
}
T[1519] = {
  title = "Il Richiamo della Terra",
  desc = "È giunto il momento, giovane $C. Il tuo corpo matura e si fa forte, e il tuo spirito resiste come la terra. Lo vedo dentro di te — hai già saggezza.$B$BLa terra guida il nostro popolo, e ci parla, come a suo tempo parlerà a te. Ma devi essere $Gmesso:messa; alla prova. Se sei $Gpronto:pronta;, vedrai cose che solo la nostra gente conosce.$B$BCerca gli sciamani Bristleback nel loro burrone a est, e prendi loro un unguento che usano nei loro rituali. Torna da me solo quando ne avrai abbastanza per la tua pozione.",
  obj = "Porta 2 dosi di Ritual Salve a Seer Ravenfeather, a Camp Narache.",
  progress = "La terra è paziente, e ti aspetterà finché non sarai $Gpronto:pronta;, perché sa che col tempo tutte le cose si consumano e rinascono. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi.$B$BDevi imparare la pazienza e la resistenza sopra ogni cosa. La terra ora ti chiama perché sente che sei $Gpronto:pronta;. Se ci riuscirai, considera questa la tua rinascita. Dopo, non potrai mai più tornare all'ignoranza.",
  reward = "Bene, $N. Il tuo ritorno significa che sei davvero $Gpronto:pronta; per il passo successivo.$B$BDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il dovuto rispetto. Lei è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che condivide con te.$B$BOra preparerò la tua sapta, e accettandola vedrai aprirsi davanti a te una nuova strada.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.",
}
T[1520] = {
  title = "Il Richiamo della Terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha la mente aperta di vedere gli elementi come nessuno li ha mai visti. Il tuo spirito sarà legato per sempre all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia della nostra gente conosce i segreti della sua preparazione.$B$BLa sapta si beve sempre in un luogo sacro, e mai altrove.$B$BCerca il santuario sciamanico a est di qui e bevi la sapta.",
  obj = "Trova la Roccia dei Kodo e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$BCon il corpo e lo spirito uniti, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.$B$BPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Kodo Rock and drink the Earth Sapta.",
}
T[1521] = {
  title = "Il Richiamo della Terra",
  desc = "Prendi questo quarzo grezzo e portalo alla Veggente Ravenfeather come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere alle montagne.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Seer Ravenfeather, a Camp Narache.",
  progress = "Salve, $N. Non torneresti da me se non avessi portato a termine il tuo compito. Lascia che sia la prima a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che governeranno per sempre i tuoi viaggi.$B$BSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso. Altrimenti, mi fai pena. Quando ci si dedica completamente agli elementi, c'è molto di cui andare fieri.",
  reward = "Splendido.$B$BIl totem che creerò per te è più di un simbolo — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra. Gli istruttori che troverai in tutta Kalimdor sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi, e te lo diranno quando andrai da loro.$B$BMa per ora prendi questo totem della terra...",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.",
}
T[1522] = {
  title = "Il Richiamo del Fuoco",
  desc = "Il fuoco sia con te, mon. Io vedo che tu già forte nelle vie della terra, e io penso che tu $Gpronto:pronta; per parlare con Kranal.$B$BKranal sta a nord del Crossroads, nelle Barrens. Lui forte nelle vie degli elementi e può insegnarti le vie del fuoco... se tu pensi di essere $Gpronto:pronta;.$B$BLui facile da trovare, basta che non vai troppo lontano — tu vai troppo lontano e ti ritrovi nelle terre degli elfi.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Searn, vero?$B$BBe', di Searn ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1523] = {
  title = "Il Richiamo del Fuoco",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Narm, vero?$B$BBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1524] = {
  title = "Il Richiamo del Fuoco",
  desc = "Sei abbastanza potente per impugnare il totem del fuoco, ma questo non significa che tu sia $Gpronto:pronta;.$B$BLungo il Fiume Southfury, a Durotar, prima del Great Sea, c'è un sentiero nascosto che porta a una delle vette più alte di queste terre. Trova la strada per la cima e troverai uno dei nostri santuari sacri, custodito da Telf Joolam — il Santuario della Fiamma Sopita.$B$BPortagli questa torcia — è il segno che stai tentando di domare il fuoco. Riportamela dopo averla accesa al braciere del santuario, e farò in modo che tu riceva il totem del fuoco.",
  obj = "Porta la Torch of the Dormant Flame a Telf Joolam, a Durotar.",
  progress = "Salve, $N. Sei $Garrivato:arrivata; al Santuario della Fiamma Sopita. Solo chi è abbastanza esperto nelle arti sciamaniche arriverà mai a conoscere i segreti di questo luogo e il potere che custodisce. Mi dispiace che tu abbia fatto tutta questa strada per essere $Grespinto:respinta; proprio adesso — dopotutto la salita fin quassù è tutt'altro che sicura — ma sono il custode del santuario, e non posso permettere a chiunque di aggirarsi da queste parti.",
  reward = "Ah, errore mio, $N. Ti chiedo scusa. Non mi ero accorto che avessi con te la Torcia. Sono lieto di fare la tua conoscenza.$B$BMolti avventurieri arrivano fin qui in cerca di tesori perduti o attratti dalla promessa di creature mistiche da uccidere, salvo poi essere respinti da un santuario che sembra vuoto. Ma noi conosciamo la verità, non è vero, $N?$B$BQuesto santuario custodisce un segreto più grande, nascosto ai membri comuni dell'Orda. Per noi è sacro.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.",
}
T[1525] = {
  title = "Il Richiamo del Fuoco",
  desc = "Ma non sei $Gvenuto:venuta; qui per una lezione di storia, vero? Sei $Gvenuto:venuta; per la Fiamma Eterna e per il totem del fuoco.$B$BIl primo passo è creare una sapta e legarti alla fiamma.$B$BPosso creare la sapta del fuoco per te, se mi porti due oggetti. Il primo è il catrame di fuoco, un oggetto comune che di solito portano con sé gli incantatori Razormane nelle Barrens orientali.$B$BIl secondo sarà più pericoloso da procurare: una borsa dei reagenti presa a uno dei cultisti della Burning Blade. Li trovi in una grotta sopra i burroni a nord-est di Razor Hill.",
  obj = "Porta 1 Fire Tar e 1 Reagent Pouch a Telf Joolam, a Durotar.",
  progress = "Ho abbastanza ingredienti per una sapta del fuoco, se riesci a trovare la borsa dei reagenti e un po' di catrame di fuoco. I fanatici della Burning Blade tengono in quelle borse i componenti adatti per la maggior parte dei loro incantesimi, e di solito hanno abbastanza di quello che mi serve, così non dovremo cercare nient'altro molto più lontano.$B$BLe sapta si preparano sempre con ingredienti strettamente legati ai rispettivi elementi. Grazie al legame degli stregoni con il fuoco, il nostro lavoro è più facile.",
  reward = "Andranno benissimo, $N.$B$BIl fuoco è più che caos e distruzione — faresti bene a ricordarlo. Riguarda anche la vita, e la creazione. Tutte le cose sono legate tra loro in questo modo. Le forze si oppongono l'una all'altra, ma allo stesso tempo l'una non può esistere senza l'altra. Si spengono a vicenda, ma si danno anche un senso a vicenda. Ricordalo sempre.$B$BUsare diversi tipi di magia insieme dimostrerà non solo una vera abilità, ma anche una grande saggezza.",
  en_title = "Call of Fire",
  en_obj = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.",
}
T[1526] = {
  title = "Il Richiamo del Fuoco",
  desc = "La sapta del fuoco è pronta. È giunto il momento di affrontare la fiamma. Usa la sapta al santuario e sali in cima alla montagna per affrontare la manifestazione che si trova lassù. Non attaccherà finché non sarai $Gpronto:pronta;, ma si renderà conto che riesci a vederla.$B$BAbbattila in fretta, $N, perché più tempo impiegherai a ucciderla, più diventerà potente. Una volta sconfitta, metti le sue braci ardenti nel braciere e accendi la torcia.",
  obj = "Sconfiggi la Minor Manifestation of Fire e metti la Glowing Ember nel braciere in cima allo Shrine of Eternal Flame.",
  progress = "Il braciere è alto circa un terzo di te, e sembra normale, a parte le iscrizioni lungo i suoi lisci montanti di metallo. Il metallo non mostra segni di usura dovuti alle intemperie, e la coppa posta in cima è fresca al tatto.",
  reward = "Una fiamma bianca, rovente, si accende nella coppa quando ci metti dentro la brace. Senti gli effetti magici della sapta scorrerti nel corpo, e il fuoco danza a ritmo davanti a te.$B$BInfili la punta della torcia nel bacile, e prende subito fuoco.",
  en_title = "Call of Fire",
  en_obj = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.",
}
T[1527] = {
  title = "Il Richiamo del Fuoco",
  desc = "Con la torcia ben stretta in mano, ti allontani dal braciere e il tuo sguardo spazia su Durotar. Senti un fremito agitarti lo spirito, mentre il vento si alza e costringe la fiamma a una danza violenta.$B$BTi incammini lungo il sentiero che riporta alle Barrens, in cerca di Kranal Fiss.",
  obj = "Porta la Torch of the Eternal Flame a Kranal Fiss, nelle Barrens.",
  progress = "Sì, $N? Cos'hai lì?",
  reward = "Il tuo spirito arde più luminoso di qualunque torcia io abbia mai visto, $N, e per questo dovresti andarne $Gfiero:fiera;.$B$BSe continuerai su questa strada, gli elementi saranno ai tuoi ordini, e i nostri fratelli si rivolgeranno a te per avere guida e saggezza. Lascia che sia il primo a congratularmi con te e a consegnarti il tuo nuovo totem.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.",
}
T[1528] = {
  title = "Il Richiamo dell'Acqua",
  desc = "C'è l'acqua nel tuo futuro, mon. Vedo che tu già sei forte nelle vie del fuoco, e a me mi sa che sei $Gpronto:pronta; per parlare con Islen.$B$BIslen sta lungo la costa delle Barrens. Se vai giù a sud lungo il Fiume Southfury, non la puoi non vedere — cerca il grosso squalo! Lei è forte nelle vie degli elementi e ti può insegnare le vie dell'acqua... se pensi che sei $Gpronto:pronta;.$B$BÈ facile da trovare, basta che non vai troppo a sud — sta giusto dopo Ratchet.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1529] = {
  title = "Il Richiamo dell'Acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Fiume Southfury e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1530] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.$B$BIl suo potere scorre, erode e purifica ogni genere di cosa. Scoprirai che la sua capacità di guarire e di ristorare non ha eguali, ma solo quando è pura.$B$BQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia vitale questa risorsa.$B$BSe vuoi la sapta d'acqua, trova Brine nel profondo delle Barrens del sud. La sua casa è continuamente tormentata dai verrospini della zona.",
  obj = "Trova Brine, nelle Barrens del sud.",
  reward = "Sì?$B$BMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere quaggiù, nella parte più remota delle Barrens, con la minaccia dei verrospini tutt'intorno e nessuna protezione? Be', tutti abbiamo le nostre ragioni per giustificare quello che facciamo. La vera domanda è: cosa porta $Gun semplice:una semplice; $R fin nel cuore delle Barrens a parlare con una donna a cui chiaramente non importa niente della propria incolumità?$B$BScommetto che la risposta la conosciamo $Gtutti e due:tutte e due;.",
  en_title = "Call of Water",
  en_obj = "Find Brine in Southern Barrens.",
}
T[1531] = {
  title = "Il Richiamo dell'Aria",
  desc = "Adesso sì che stai facendo progressi, mon. Sei $Gpronto:pronta; per dimostrare che sei $Gdegno:degna; del totem dell'aria, ma prima devi trovare Prate Cloudseer a Thousand Needles. Lei te lo dice volentieri come prendere il tuo totem dell'aria, se la tratti con abbastanza rispetto.$B$BVai giù a sud per le Barrens, e quando arrivi a Thousand Needles, vai a est. La trovi nascosta in una buca col suo fidanzato — ah ah, non dirle che io parlo male di lei — non la prende mica tanto bene.",
  obj = "Trova Prate Cloudseer, a Thousand Needles.",
  reward = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1532] = {
  title = "Il Richiamo dell'Aria",
  desc = "I venti di Kalimdor ti corrono incontro, e sarai $Gannoverato:annoverata; tra $Gi nostri fratelli:le nostre sorelle; più potenti. È un orgoglio per me vedere che sei $Garrivato:arrivata; fin qui e che hai un futuro così promettente.$B$BL'elemento dell'aria è difficile da controllare, ma ho fiducia che le tue abilità supereranno qualunque ostacolo ti venga posto davanti.$B$BVa' all'estremo sud delle Barrens ed entra a Thousand Needles. È lì, molto a est, che troverai Prate Cloudseer. Ti insegnerà di più.",
  obj = "Trova Prate Cloudseer, a Thousand Needles.",
  reward = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1534] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Prendi quest'otre e addentrati nella foresta rigogliosa che gli elfi della notte chiamano Ashenvale. Si trova all'estremo nord delle Barrens.$B$BQuando sarai nella foresta, dirigiti a ovest. Lungo le montagne che separano Stonetalon e Ashenvale, e oltre il Lago Mystral, troverai un luogo sacro: le Rovine di Polvere di Stelle. Al centro del lago troverai una piccola fontana.$B$BPortami un campione dell'acqua della fontana. Sarà l'ultimo componente che ti servirà prima che ti rimandi da Islen.",
  obj = "Riempi l'Empty Blue Waterskin alle Ruins of Stardust, in Ashenvale, e torna da Brine, nelle Barrens.",
  progress = "Hai già l'acqua, $N? Le leggende dicono che le rovine erano protette da grandi creature della natura a cui non piacciono i visitatori, ma potrebbero essere miti per spaventare i nemici degli elfi della notte.$B$BIn ogni caso, fai attenzione.",
  reward = "Magnifico, $N. Con tutti e tre i campioni raccolti, posso creare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nelle prossime tappe del tuo rito di passaggio.$B$BSono lieta di contarti tra la nostra gente, $N. Fai onore a ogni $C, e non vedo l'ora di sentir parlare delle tue imprese in futuro.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.",
}
T[1535] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Per arrivare a capire, e per ottenere da me la sapta, devi cercare solo le forme più pure d'acqua. Mentre raccogli i campioni per me, osserva bene ciò che ti circonda. Fai attenzione alle creature che dipendono dall'acqua, che la proteggono. Guarda come influisce sulle foreste e sui deserti. Osserva come proprio la sostanza che sostiene la vita spinga le creature a uccidere.$B$BCominceremo con un compito semplice: sotto la mia capanna c'è uno stagno di questo liquido prezioso. Riempi quest'otre e torna da me.",
  obj = "Riempi l'Empty Brown Waterskin alla pozza sotto la capanna di Brine e riportalo a lei, nelle Barrens.",
  progress = "Sono quasi pronta a mandarti a svolgere gli altri compiti. Hai già riempito l'otre?$B$BSo quanto i verrospini sanno essere gelosi della loro acqua. Anche una fonte d'acqua così piccola per loro è un immenso tesoro. Fanno grandi banchetti ogni volta che sulle Barrens cade anche la più leggera pioggia. L'acqua è sacra per la loro specie perché è così scarsa. Capisci?",
  reward = "Immaginavo che ci sarebbe scappato del sangue se avessi provato a prendere l'acqua dalla pozza. È un peccato che i verrospini non si rendano conto che tutti gli esseri viventi sono legati tra loro; che la loro avidità non fa che perpetuare il dolore e la sofferenza del loro popolo. Quante cose potrebbero ottenere, se mettessero da parte le loro divisioni e i loro clan si unissero.$B$BAncora una volta, è un peccato, ma con ogni probabilità è una fortuna per le altre razze delle Barrens.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.",
}
T[1536] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Molto tempo fa seguii alcuni compagni nelle Hillsbrad Foothills. Ci difendemmo da certi umani tenaci che vivono lì, e ci ritrovammo in una cittadina che i Reietti avevano conquistato: Tarren Mill.$B$BFu lì che trovai una cosa davvero curiosa: al centro del paese c'era un piccolo pozzo di acqua sorgiva fresca. Non sono sicura che gli abitanti appestati della cittadina ne capiscano davvero il valore — è una piccola traccia di sacro in un mare profano.$B$BPortami un campione di quell'acqua in quest'otre.",
  obj = "Riempi l'Empty Red Waterskin al pozzo di Tarren Mill e torna da Brine, nelle Barrens.",
  progress = "Il pozzo rimasto puro in mezzo alla cittadina mi ricorda le storie che mi raccontavano quand'ero più giovane, $N. Anche nei momenti di grande dolore e tristezza si può trovare uno spiraglio di speranza, un piccolo simbolo attorno a cui stringersi. Gli orchi vedono Thrall in questo modo. È sopravvissuto contro ogni previsione e, con la sua forza e il suo esempio, è diventato la guida del nostro popolo.$B$BNon so se ci sia un orco che abbia sofferto quanto lui, ma allo stesso tempo non so nemmeno se ci sia un orco forte quanto lui.",
  reward = "Bene così, $N. Ti dedichi al compito che hai davanti e sai cercare ciò che serve.$B$BMi serve solo un altro campione per creare il reagente necessario per la tua sapta. Anche Islen ne sarà contenta.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.",
}
T[1558] = {
  title = "La Diga di Pietrasalda",
  desc = "Ironforge è dove vivono tutti i nani e gli gnomi. Lì vicino c'è un posto chiamato Loch Modan, e i nani ci hanno costruito una diga ENORME. Dicono che sia una delle cose più grandi che siano mai state costruite. Wow!$B$BMi porteresti a Loch Modan a vedere la diga, per piacere? Mi sembra che sia la Diga di Pietra... ehm... Pietrachiave? Pietrasalda? È grande, questo è sicuro. Vorrei affacciarmi sulla grande cascata. Prometto che non mi sporgerò troppo!",
  obj = "Porta l'orfano alla Stonewrought Dam, a Loch Modan. Dovresti portarlo al centro della diga, così potrà guardare la cascata gigante.",
  progress = "Siamo arrivati?",
  reward = "WOW, la diga era MOLTO più grande di quanto pensassi! Riuscivo a malapena a sentirmi parlare per il rumore di tutta quell'acqua che scorreva! Ehi, pensi che l'acqua possa mai finire? Accidenti, cosa succederebbe se quella diga si rompesse! WOW, sarebbe spaventoso!$B$BGrazie di avermi portato a vedere la diga. È stato molto gentile da parte tua. Te l'avevo detto che non mi sarei sporto troppo!",
  en_title = "The Stonewrought Dam",
  en_obj = "Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall.",
}
T[1559] = {
  title = "La Ricetta delle Bombe Accecanti",
  reward = "Quindi sei $Gun ingegnere:un'ingegnera;, eh? Be', in cambio del tuo aiuto per procurarmi quelle perle, ecco la ricetta delle bombe accecanti.$B$BBuona fortuna, e cerca di non accecarti!",
  en_title = "Flash Bomb Recipe",
}
T[1560] = {
  title = "La Missione di Tooga",
  desc = "Mi sono proprio perso!$B$BMia moglie, Torta, mi ha mandato a prendere la cena e devo aver sbagliato strada da qualche parte.$B$BSaresti così gentile da riportarmi da Torta? Mi aspetta appena a sud del Porto di Steamwheedle.",
  obj = "Mostra a Tooga la strada per tornare da sua moglie, Torta.",
  progress = "Dov'è Tooga?",
  reward = "Quindi non è riuscito a ritrovare la strada da solo? C'era da aspettarselo.$B$BBe', immagino che ti meriti qualcosa per il disturbo....",
}
T[1578] = {
  title = "Rifornire il Fronte",
  desc = "I montanari del Loch Modan stanno combattendo contro i trogg, e hanno il loro bel da fare! Hanno bisogno di rifornimenti continui di armature e armi nuove, se vogliamo riuscire una buona volta a tenere a bada quei trogg.$B$BPer questo il mio collega Thorvald è laggiù, a cercare di tenere i montanari ben equipaggiati. Quindi, se tu fabbricassi qualche ascia di rame e qualche cintura a maglie di rame e le portassi a Thorvald, te ne sarebbe grato. Potrebbe perfino condividere con te le sue conoscenze.$B$BThorvald si trova nella torre di guardia a sud del Loch Modan.",
  obj = "Porta 6 Copper Axe e 6 Copper Chain Belt a Thorvald, nella torre di guardia a sud del Loch Modan",
  progress = "Non ho tempo per chiacchierare. Hai qualche affare da sbrigare con me?",
  reward = "Ah, scusami! Non avevo capito che eri qui per aiutare a rifornire le nostre truppe. Quello che hai fabbricato sarà di grande aiuto!$B$BEcco gli schemi di un'armatura. Spero che ti siano utili.",
  en_title = "Supplying the Front",
  en_obj = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.",
}
T[1579] = {
  title = "Spinotti Isolati",
  desc = "Sono venuto ad Auberdine per la tranquillità. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il rumore di Ironforge!$B$BCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Ho fatto cadere in mare la mia scatola di spinotti isolati! Mi servono i miei spinotti isolati!$B$BNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano forse ti andrà bene...",
  obj = "Porta 8 Gaffer Jack a Wizbang Cranktoggle, ad Auberdine.",
  progress = "Hai trovato i miei spinotti isolati, $N? Senza i miei spinotti isolati non posso regolare i miei pioli stintle!",
  reward = "Non ci posso credere, li hai trovati! Devi essere $Gil:la; $R più $Gfortunato:fortunata; di Kalimdor!",
  en_title = "Gaffer Jacks",
  en_obj = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.",
}
T[1580] = {
  title = "Electropellers",
  desc = "Sappiamo che sei $Gfortunato:fortunata;, ma... quanto sei $Gfortunato:fortunata;, di preciso, $N?$B$BUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago per provare il mio nuovo richiamo per anatre esplosivo e semovente, e credo di essere stato un po' brillo... perché sono svenuto e mi sono risvegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia borsa di electropellers era sparita! Devo averli fatti cadere in acqua!$B$BMi servono quegli electropellers! Magari riesci a ripescarli da qualche lago o torrente di Darkshore...",
  obj = "Porta 12 Electropeller a Wizbang Cranktoggle, ad Auberdine.",
  progress = "Hai trovato degli electropellers? Mi serviranno se voglio continuare le mie ricerche sui richiami per anatre...",
  reward = "Non ci posso credere! Li hai trovati! Sei $Gil miglior pescatore:la miglior pescatrice; che abbia mai visto!$B$BGrazie, $N. E tieni, prendi questi. Anche se sei così $Gbravo:brava; che probabilmente non ti servono, ti aiuteranno a pescare.",
  en_title = "Electropellers",
  en_obj = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.",
}
T[1581] = {
  title = "Elisir per i Bladeleaf",
  desc = "Il nostro negozio di erbe e di alchimia va a gonfie vele, ma mio marito passa così tanto tempo a mescolare pozioni che non abbiamo mai tempo l'uno per l'altra.$B$BPuoi aiutarci?$B$BSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho alcune erbe rare che potrebbero esserti utili.",
  obj = "Porta 6 Elixir of Lion's Strength e 2 Elixir of Minor Defense a Syral Bladeleaf, a Dolanaar.",
  progress = "Salve, $N. Hai gli elisir da scambiare?",
  reward = "Sono miscelati bene. Metti grande cura nel tuo mestiere, $N, e per un alchimista questo conta molto.$B$BEcco le tue erbe, appena raccolte. Che tu possa farne buon uso.",
  en_title = "Elixirs for the Bladeleafs",
  en_obj = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.",
}
T[1582] = {
  title = "Giaco del Bagliore Lunare",
  desc = "Noi di Darnassus, e soprattutto noi artigiani, abbiamo molto da fare. I giovani avventurieri sono impazienti di mettersi alla prova nelle terre selvagge, e hanno sempre bisogno di rifornimenti.$B$BSe mi aiuti a evadere i miei ordini di articoli di cuoio, forse potrò insegnarti una tecnica di conciatura avanzata.",
  obj = "Porta 1 Embossed Leather Gloves, 5 Embossed Leather Boots e 5 Embossed Leather Cloak a Lotherias, a Darnassus.",
  progress = "Salve, $N.",
  reward = "Sì, sono pezzi di buona fattura. Hai una mano abile e occhio per i dettagli. Come $Gconciatore:conciatrice; hai un futuro promettente.$B$BEcco, $N. Lascia che ti mostri lo schema per fare il Giaco del Bagliore Lunare.",
  en_title = "Moonglow Vest",
  en_obj = "Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.",
}
T[1598] = {
  title = "Il Tomo Rubato",
  desc = "Ehi, tu! $N, giusto?$B$BSpero che tu sia $Gsicuro:sicura; di voler diventare $Gun stregone:una strega;, perché se non riesci a cavartela, rischi di essere $Gtrascinato:trascinata; a fondo.$B$BDevo insegnarti, ma prima devo assicurarmi che tu sia abbastanza forte.$B$BC'era un novizio che studiava all'Abbazia ed è scappato per unirsi alla Defias Brotherhood. Perché mi importa? Beh, ha rubato alcuni libri importanti.$B$BUno di questi è proprio un libro che volevo per me, Poteri del Vuoto. Rubamelo: lo tengono nascosto nella loro tenda nei Vigneti.",
  obj = "Recupera Powers of the Void per Drusilla La Salle.",
  progress = "Sarebbe stato troppo vistoso rubare il libro di persona. Che fortuna che uno dei loro galoppini abbia fatto il lavoro sporco al posto mio.",
  reward = "Eccellente... Non ero mai riuscita ad accedere a questo testo: era custodito in un'ala protetta della biblioteca, e se mi fossi aggirata da quelle parti sarei sembrata sospetta.$B$BBeh, hai fatto un buon lavoro a procurartelo, e sono convinta che probabilmente sai gestire un imp tutto tuo, quindi non vedo perché non dovrei mostrarti come evocarne uno.",
  en_title = "The Stolen Tome",
  en_obj = "Retrieve the Powers of the Void for Drusilla La Salle.",
}
T[1618] = {
  title = "Equipaggiare Redridge",
  desc = "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel da fare!$B$BRedridge subisce attacchi periodici dagli orchi blackrock, e le loro scorte di equipaggiamento sono sempre scarse. Se li aiutassi, di sicuro il loro fabbro, Verner Osgood, ti insegnerebbe un trucco o due.",
  obj = "Tormus Deepforge vuole che tu porti 4 Runed Copper Belt e 4 Heavy Copper Maul a Verner Osgood, a Redridge.",
  progress = "Spero che tu sia qui con buone notizie da Ironforge. Perché io non so più dove sbattere la testa!",
  reward = "Grazie, $N. Questo mi aiuterà tantissimo. Con gli orchi Blackrock che attaccano dal Mastio di Stonewatch e gli gnoll di Redridge in agguato sulle colline a nord, non faccio che riparare armature e forgiare armi nuove per le nostre truppe.$B$BI rifornimenti che hai portato mi daranno un momento di pace. Avrò abbastanza tempo per insegnarti qualcosa...",
  en_title = "Gearing Redridge",
  en_obj = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.",
}
T[1638] = {
  title = "L'Addestramento di un Guerriero",
  desc = "Hai dimostrato di essere $Gun guerriero capace:una guerriera capace;, $N. Ma sei ancora giovane e hai molto da imparare.$B$BParla con Harry Burlguard — di solito sta nella Pig and Whistle, nella Città Vecchia di Stormwind. Harry è un vecchio veterano e un buon insegnante. Può mostrarti qualche mossa che ti terrà in vita più a lungo.",
  obj = "Parla con Harry Burlguard.",
  reward = "Ohò! Bevi qualcosa con me, $N. Fuori sembri $Gtosto:tosta;, ma vediamo se il tuo stomaco regge qualche boccale della roba più forte della Pig and Whistle!!$B$BOppure... sei qui per una lezione?",
  en_title = "A Warrior's Training",
  en_obj = "Speak with Harry Burlguard.",
}
T[1639] = {
  title = "Bartleby l'Ubriacone",
  desc = "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.$B$BVedi quell'ubriaco laggiù, in fondo al bancone? Bartleby? Voglio che tu gli prenda il boccale.$B$BAh, e se conosci Bartleby, sai che non te lo darà tanto facilmente.",
  obj = "Parla con Bartleby.",
  reward = "Salve, $Gsignorino:signorina;! Che ci fa una cosina delicata come te alla Pig and Whistle? Sta' $Gattento:attenta;, o potresti romperti un'unghia...",
  en_title = "Bartleby the Drunk",
  en_obj = "Speak with Bartleby.",
}
T[1640] = {
  title = "Batti Bartleby",
  desc = "Che cosa vuoi?? Sei $Gpazzo:pazza;!$B$BL'unico modo per avere questo boccale è passare sul mio cadavere...",
  obj = "Batti Bartleby, poi parla con lui.",
  progress = "L'unico modo per avere questo boccale è passare sul mio cadavere...",
  reward = "Sei molto più $Gtosto:tosta; di quanto sembri!",
  en_title = "Beat Bartleby",
  en_obj = "Beat Bartleby, then talk to him.",
}
T[1641] = {
  title = "Il Tomo della Divinità",
  reward = "Qui a Stormwind, il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.$B$BÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Libro della Divinità. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.",
  en_title = "The Tome of Divinity",
}
T[1642] = {
  title = "Il Tomo della Divinità",
  desc = "In ogni cosa, un paladino deve riflettere la Luce che accresce la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.$B$BAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che ciò che ti distinguerà davvero dagli abitanti di Azeroth è l'aiuto che dai agli altri. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.$B$BSappilo bene, e non dimenticarlo mai.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Eccoti di nuovo, $N. Come procedono i tuoi studi sul Tomo della Divinità?$B$BAllora dovresti essere $Gpronto:pronta; a farti mettere alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.$B$BDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1643] = {
  title = "Il Tomo della Divinità",
  desc = "Il tuo compito, allora, $N, è trovare qualcuno qui a Stormwind che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.$B$BFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce.",
  obj = "Cerca Stephanie Turner nel Trade District di Stormwind.",
  reward = "Oh, ciao, tesoro. Come vanno le tue avventure? Oh, sono così contenta di sentire che ti va tutto bene.$B$BOh, io? Grazie per avermelo chiesto — sto bene, tutto sommato.$B$BL'aumento degli artigiani ha un po' ridotto la quantità di cuoio e di stoffa che la gente è disposta a cedere di questi tempi, quindi è stato più difficile fare vestiti per i bambini dell'orfanotrofio, ma ce la caveremo. Con \"noi\" intendo me e mio marito. È su a Ironforge, a chiedere aiuto alla gente del posto.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the Trade District of Stormwind for Stephanie Turner.",
}
T[1644] = {
  title = "Il Tomo della Divinità",
  desc = "Poveri cari, quasi nessuno di loro ha più una famiglia, per colpa degli attacchi del Flagello nell'ultimo decennio.$B$BMio marito John raccoglie i materiali perché io cucia camicie e pantaloni per i bambini, ma non ho avuto nemmeno il tempo di farlo. Ho pensato solo a non fargli mancare il cibo nel piatto e un tetto sopra la testa.$B$BCome dici? Saresti $Gdisposto:disposta; ad aiutarmi? Oh, sia ringraziata la Luce, e grazie a te, $N.$B$BSe potessi portarmi un po' di linen cloth per cucire i vestiti ai bambini, mi aiuteresti tantissimo.",
  obj = "Porta 10 Linen Cloth a Stephanie Turner, a Stormwind.",
  progress = "Spero che il mio John abbia più fortuna a Ironforge. Gli pesano tanto quei viaggi, perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore così buono.$B$BAlcuni anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se nell'aria ci fosse il segnale di un grande cambiamento. Ma chi lo sa?",
  reward = "Grazie, $N, grazie mille!$B$BI bambini saranno contentissimi, e mi hai fatto risparmiare un sacco di tempo. Ora potrò pensare agli altri bisogni dei bambini, e spero che il mio John possa tornare a casa prima del previsto.$B$BGrazie ancora, $N. Sapevo di poter contare sulla carità degli altri. Che la Luce sia con te.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.",
}
T[1645] = {
  title = "Il Tomo della Divinità",
  reward = "Piacere di conoscerti, $N. Il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.$B$BÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Libro della Divinità. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.",
  en_title = "The Tome of Divinity",
}
T[1646] = {
  title = "Il Tomo della Divinità",
  desc = "In ogni cosa, un paladino deve riflettere la Luce che accresce la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.$B$BAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che ciò che ti distinguerà davvero dagli abitanti di Azeroth è l'aiuto che dai agli altri. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.$B$BSappilo bene, e non dimenticarlo mai.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "$GBentornato:Bentornata;, $N. Hai passato del tempo a leggere il libro, spero?$B$BAllora dovresti essere $Gpronto:pronta; a farti mettere alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.$B$BDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1647] = {
  title = "Il Tomo della Divinità",
  desc = "Il tuo compito, allora, $N, è trovare qualcuno qui a Ironforge che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.$B$BFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce. Resterò qui nel tempio ad aspettare il tuo ritorno. Anche altri paladini avranno bisogno della mia guida.",
  obj = "Cerca John Turner nell'anello esterno di Ironforge.",
  reward = "L'ORFANOTROFIO DI STOR... oh, scusa, non volevo urlarti contro, $Gsignore:signorina;,$B$BMi chiamo John Turner. Come stai?$B$BBene, bene, sono contento di sapere che ti va tutto bene. Ho già avuto una lunga giornata di lavoro, e mi manca terribilmente mia moglie, ma è il prezzo da pagare quando ci sono bocche da sfamare e schiene da vestire.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the outer ring of Ironforge for John Turner.",
}
T[1648] = {
  title = "Il Tomo della Divinità",
  desc = "Mia moglie e io gestiamo un orfanotrofio a Stormwind, soprattutto per i bambini che hanno perso i genitori negli attacchi del Flagello dell'ultimo decennio. Vengo a Ironforge più o meno una volta al mese per vedere di raccogliere altre provviste dai cittadini di qui, e per parlare con i vari gruppi e capire se possono fare qualcosa per aiutare.$B$BQuesto viaggio è stato di una lentezza esasperante, e non molto fruttuoso.$B$BSe solo riuscissi a procurare un po' di linen in più a mia moglie per fare dei vestiti, potrei finalmente spedire un carico a casa.",
  obj = "Porta 10 Linen Cloth a John Turner, a Ironforge.",
  progress = "Con tutti gli artigiani che arrivano qui e in tutta Azeroth, ci sono meno materiali per fare i vestiti ai bambini del nostro orfanotrofio. Aiutarmi a raccogliere il linen perché mia moglie possa fargli dei vestiti nuovi è molto nobile da parte tua, $N. Grazie.$B$BSpero di poter tornare presto a casa da mia moglie.",
  reward = "È davvero magnifico da parte tua, $N. Grazie ancora.$B$BSei $Gun uomo nobile:una donna nobile; a fare questo per me. Non c'è da stupirsi che tu abbia scelto di seguire la Luce. Vorrei che ci fosse un modo per ripagarti di tutto quello che hai fatto... come dici? È il minimo che potessi fare? Visto? È proprio quello che dicevo, $N: nobile fino in fondo.$B$BStammi bene, e che la Luce ti protegga nei tuoi viaggi.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to John Turner in Ironforge.",
}
T[1649] = {
  title = "Il Tomo del Valore",
  desc = "Il valore, e tutte le virtù che lo accompagnano, sono come minerali rari: devi custodirli gelosamente quando li trovi, per il loro valore, ma devi anche prenderti il tempo di estrarli... di raffinarli. Quando si fondono nel modo giusto, formano una lega resistente, che a volte nemmeno i colpi più potenti riescono a spezzare.$B$BQuesta forza, la tua fede, il tuo coraggio, devono essere messi alla prova. Devi imparare a non perdere mai la fede, e a capire che con il potere della Luce puoi superare prove che la maggior parte degli altri non riesce a superare.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Ah, desideri chiedermi una prova di valore. Splendido.$B$BCi sono molti compiti in città e nelle terre circostanti che presentano grandi sfide, e servirebbe $Gun uomo:una donna; con le tue capacità.$B$BQuesta prova non va presa alla leggera, $N. Questa, come molte cose lungo il nostro cammino, potrebbe costarci la vita. La Chiesa desidera sempre rafforzare i suoi ranghi, ma comprende i sacrifici necessari per assicurarsi che i paladini al suo servizio ne siano degni.$B$BSei $Gpronto:pronta;?",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1650] = {
  title = "Il Tomo del Valore",
  desc = "Bene! Non hai esitato, ed è il segno sicuro che sei $Gpronto:pronta; e impaziente di metterti alla prova. Così sia.$B$BProprio in fondo a Rivalunga, a Westfall, c'è una casetta che si affaccia sull'oceano. Lì vive una coppia, gli Stilwell. Jordan è un fabbro straordinario, ed è andato per un po' a Ironforge a incontrare i nani. Ma così Daphne, sua moglie, è rimasta sola e senza protezione.$B$BStando ai rapporti, i Defias hanno quasi preso il controllo della zona: Daphne potrebbe aver bisogno di qualcuno che la protegga da quei furfanti. Va' laggiù.",
  obj = "Trova Daphne Stilwell a Westfall.",
  reward = "Salve, $N. Con tutta quell'armatura e quell'arma, immagino che tu sia qui o per cercare di prenderti la mia terra, o perché la Chiesa ha finalmente mandato qualcuno ad aiutarmi a difendermi finché il mio Jordan è via.$B$BBe', lascia che mi presenti: sono Daphne Stilwell. Piacere.$B$BComunque, non sei in ritardo... Dall'alba ho fatto fuori solo una mezza dozzina di quei farabutti. Ci hanno messo un po' a sbucare dalla curva lassù, ma probabilmente ti hanno visto arrivare, quindi saranno qui da un momento all'altro.",
  en_title = "The Tome of Valor",
  en_obj = "Find Daphne Stilwell in Westfall.",
}
T[1651] = {
  title = "Il Tomo del Valore",
  desc = "Allora, torneranno presto, ci scommetto, quindi preparati.$B$BIn casa ho un fucile. Vado a prenderlo e sarò pronta a darti una mano, ma per lo più te la dovrai cavare da $Gsolo:sola;.$B$BNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi che hanno mandato prima.$B$BChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.$B$BResisteremo vicino alla casa!",
  obj = "Difendi Daphne Stilwell dall'attacco dei Defias.$B$BSe vuoi riuscire, nessuno dei vostri due spiriti deve abbandonare il proprio corpo mortale.$B$BDopo la vittoria, parla di nuovo con Daphne Stilwell.",
  progress = "Resisteremo qui, alla casa!",
  reward = "Ce l'abbiamo fatta, $N! Grazie per l'aiuto. Là fuori sei $Gstato:stata; davvero $Gstraordinario:straordinaria;. Non avrei mai pensato che un paladino potesse tenere testa a così tanti nemici tutti insieme.$B$BHai dimostrato un vero coraggio, contro forze di gran lunga superiori.",
  en_title = "The Tome of Valor",
  en_obj = "Defend Daphne Stilwell from the Defias attack.$B$BNeither of your spirits must be released from their mortal coils if you wish to succeed.$B$BAfter you are successful, speak to Daphne Stilwell again.",
}
T[1652] = {
  title = "Il Tomo del Valore",
  desc = "Ti prego, torna da Duthorian e fagli sapere che per ora sono al sicuro. Per questo devo ringraziare te e la Chiesa.$B$BManderà un messaggio a Ironforge per far sapere al mio Jordan che non ha niente da temere.$B$BOh, quanto mi manca mio marito. Non vedo l'ora che torni.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Dunque ci rincontriamo, $N, e vedo che sei di ottimo umore.$B$BLa casa degli Stilwell sarà al sicuro per un altro giorno, e dal tuo racconto capisco che il pericolo non è mancato. Ben fatto.$B$BDaphne e Jordan hanno aiutato molto la Chiesa, e mandarti a proteggere la loro proprietà — e la loro stessa vita — era il minimo che potessimo fare per loro.$B$BPer il tuo valore, sarai $Gricompensato:ricompensata;.",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1653] = {
  title = "La Prova della Rettitudine",
  desc = "A dire il vero, non ho dubbi che Jordan in persona vorrebbe ringraziarti, e visto che mi serve un messaggero che gli faccia sapere che sua moglie è salva, penso che saresti la scelta perfetta.$B$BJordan doveva diventare un paladino della Luce, prima che la dedizione al mestiere di suo padre lo portasse su un'altra strada — conosce a fondo il nostro modo di vivere, ed è considerato tra i nostri più fedeli.$B$BDovrebbe essere ancora a Ironforge — di giorno gli piace lavorare fuori dai cancelli, per via dell'aria fresca di montagna o qualcosa del genere.",
  obj = "Parla con Jordan Stilwell, a Ironforge",
  reward = "Buongiorno, $N. La Luce è con te, spero?$B$BCome dici? Ti ha mandato Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai se fossi partito. Ti prego, dimmi che è... oh, grazie al cielo. Sono così contento che sia salva. I Defias erano una minaccia molto prima di questi attacchi, ma ora i consiglieri del Re non possono più negarlo.$B$BCos'altro ha detto Duthorian?$B$BHanno mandato te a proteggere mia moglie? Allora ti ringrazio di nuovo, $N. Non saprei immaginare una prova di valore migliore di questa.",
  en_title = "The Test of Righteousness",
  en_obj = "Speak to Jordan Stilwell in Ironforge",
}
T[1654] = {
  title = "La Prova della Rettitudine",
  desc = "Vorrei darti una ricompensa, sempre che tu voglia accettarla? Non fraintendermi, la mia generosità dipende da quanto potrai essermi d'aiuto, ma vedo un grande vantaggio per tutti e due in un'alleanza del genere.$B$BForgerò per te un'arma degna di ciò che hai compiuto, un simbolo dell'essere paladino e della Luce, ma dovrai raccogliere tu gli oggetti che mi servono per forgiarla. Ho già cominciato a prendere appunti sugli oggetti, serve solo qualcuno abbastanza coraggioso e abile da recuperarli. Che ne dici, $C?",
  obj = "Usando Jordan's Weapon Notes, trova del Whitestone Oak Lumber, Jordan's Refined Ore Shipment, Jordan's Smithing Hammer e una Purified Kor Gem, e riportali a Jordan Stilwell, a Ironforge.",
  progress = "Gli oggetti che cerchi saranno difficili da procurare, ma ti assicuro che l'arma che forgerò per te varrà la fatica.$B$BSarà il mio lavoro migliore fino a oggi, e solo un piccolo compenso per il servizio che mi hai reso.",
  reward = "È magnifico! Hai recuperato tutti gli oggetti.$B$BNon dovrei avere problemi a forgiarti un'arma grandiosa con questi. A dire il vero, i progetti per farla li ho da un po' di tempo. Non avevo mai avuto l'occasione di raccogliere il materiale. Grazie, $N.$B$BÈ bello riavere il martello di mio padre... e una gemma Kor. Non avrei mai pensato di vederne una con i miei occhi.",
  en_title = "The Test of Righteousness",
  en_obj = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.",
}
T[1657] = {
  title = "Appestare Southshore",
  desc = "Festeggia la Veglia delle Ombre con stile... seminando guai tra i nostri nemici di Southshore!$B$BPrendi una di queste bombe puzzolenti preparate apposta. È piena di un tanfo nauseabondo che nessun umano — e del resto nessuna bestia dalla volontà debole — riesce a sopportare. Dovrai lanciarla proprio nel cuore di Southshore perché faccia effetto, quindi preparati a combattere contro l'Alleanza!$B$BQuando avrai portato a termine questo compito... questo tributo alla nostra liberazione, torna da me!",
  obj = "Lancia tre Forsaken Stink Bomb nel cuore di Southshore, a Hillsbrad, e torna da Darkcaller Yanka al Wickerman Festival, nella Tirisfal Glade.",
  progress = "Hai consegnato il nostro \"regalo\" alla gente di Southshore?$B$B<Darkcaller Yanka ride malvagiamente.>",
  reward = "Ah, ben fatto! Spero che l'Alleanza soffochi con il regalo schifoso che le abbiamo fatto, proprio come noi siamo stati costretti a soffocare sotto il giogo della schiavitù al Flagello!$B$BHai onorato il vero spirito della Veglia delle Ombre, $N, e per questo ti rendo omaggio. Come premio in più, lascia che divida con te alcuni di questi dolcetti della Veglia delle Ombre. Credo che li troverai uno svago piuttosto piacevole!",
  en_title = "Stinking Up Southshore",
  en_obj = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
T[1658] = {
  title = "Imbucarsi al Wickerman Festival",
  desc = "Mi servono persone coraggiose che vadano nella Tirisfal Glade a dare un'occhiata al Wickerman Festival. Non ti mentirò — andare lassù sarà pericoloso. Le guardie della festa saranno spietate come non mai. Però dobbiamo sapere quanto è grande la festa quest'anno, e quanti guai ci daranno i Reietti durante la Veglia delle Ombre.$B$BSe te la senti, va' a Tirisfal e perlustra la festa. Torna da me con le informazioni, e farò in modo che tu venga $Gricompensato:ricompensata; bene.",
  obj = "Trova il Wickerman Festival dei Reietti nella Tirisfal Glade. Quando l'avrai trovato, torna da Sergeant Hartman a Southshore.",
  progress = "Sei $Gandato:andata; nella Tirisfal Glade a dare un'occhiata? Di solito tengono la festa vicino all'Undercity...",
  reward = "Ben fatto, $N. Il Wickerman Festival continuerà a darci problemi finché agli abominevoli Reietti sarà permesso di infestare i resti di Lordaeron. NON è un tributo degno di quel regno un tempo fiero, te lo dico io...$B$BEcco qualche moneta per le riparazioni che potrebbero servirti, e nello spirito della festa ci ho messo anche qualche dolcetto che potrebbe piacerti. Buona Veglia delle Ombre — cerchiamo di passarla il più possibile al sicuro, qui a Southshore.",
  en_title = "Crashing the Wickerman Festival (PvP)",
  en_obj = "Locate the Forsaken's Wickerman Festival in Tirisfal Glade.  Return to Sergeant Hartman in Southshore once you've done so.",
}
T[1661] = {
  title = "Il Tomo della Nobiltà",
  desc = "Ti saluto ancora una volta, $N. Sono più fiero che mai di chiamarti $Gfratello:sorella; — la tua dedizione fa onore a tutti noi.$B$BÈ giunto il momento che io ti faccia un grande dono. Sappi però una cosa, per ora te lo do senza chiedere nulla, ma più avanti, quando ci sarà tempo, questa sarà una sfida ben più grande per tutti i paladini che sceglieranno di affrontare la mia missione.$B$BParlami di nuovo e ti concederò una grande grazia.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Congratulazioni, e che la Luce ti protegga.",
}
T[1665] = {
  title = "Boccale di Bartleby",
  desc = "Va bene, ecco il mio boccale. Aspetta! Prima lasciami finire quello che c'è dentro... ecco fatto.",
  obj = "Porta Bartleby's Mug a Burlguard",
  progress = "Ho visto il tuo scontro con Bartleby. Bel lavoro! Hai preso il suo boccale?",
  reward = "Eccolo! Di certo non voleva separarsene, ma sei $Gstato:stata; convincente. Ben fatto.$B$BE ora la tua lezione...",
  en_title = "Bartleby's Mug",
  en_obj = "Bring Bartleby's Mug to Burlguard",
}
T[1666] = {
  title = "Maresciallo Haggard",
  desc = "Hai imparato qualche mossa, ma ti farebbe comodo un'arma decente. Scommetto che, se parlassi con il Maresciallo Haggard, potrebbe aiutarti.$B$BIl Maresciallo Haggard vive in una casa padronale nell'Elwynn Forest, al Campo dei Taglialegna di Eastvale. Ora è in pensione, ma durante la sua carriera ha messo insieme un sacco di equipaggiamento.$B$BDigli che ti mando io e, con un po' di fortuna, avrà un'arma in più da offrirti.",
  obj = "Parla con Marshal Haggard.",
  reward = "Chi è?$B$BBurlguard, sei tu?$B$BDevi avvicinarti un po'. I miei occhi non sono più quelli di una volta.$B$BA vederti arrivare così, ti avevo preso per uno gnoll!",
  en_title = "Marshal Haggard",
  en_obj = "Speak with Marshal Haggard.",
}
T[1667] = {
  title = "Jack Dentemorto",
  desc = "Ti manda Burlguard, eh? Sì, qui ho delle armi in più, ma prima ho un compito per te...$B$BTempo fa un furfante dei Defias, Jack Dentemorto, mi ha ingannato. Era buio, lui indossava una tabarda di Stormwind e io l'ho preso per il Maresciallo Dughan. Ha detto che gli serviva il mio vecchio distintivo da Maresciallo di Stormwind e io gliel'ho dato... poi è scoppiato a ridere ed è scappato prima che riuscissi ad acciuffarlo!$B$BRecupera il mio distintivo! Probabilmente Jack Dentemorto l'ha nascosto nel suo accampamento, a sud.",
  obj = "Recupera Marshal Haggard's Badge dall'accampamento di Dead-Tooth Jack e torna da Marshal Haggard.",
  progress = "Hai il mio distintivo? Non voglio neanche pensare ai guai che Jack Dentemorto potrebbe combinare con quello.",
  reward = "Magnifico, l'hai trovato! Temevo che fosse perduto per sempre, e che i Defias lo usassero per spacciarsi per un funzionario di Stormwind. Beh, ora non succederà, grazie a te.$B$BEcco alcune armi che usavo quando ero Maresciallo. Le ho tenute in ottimo stato — scegli quella che preferisci!",
  en_title = "Dead-tooth Jack",
  en_obj = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.",
}
T[1678] = {
  title = "Vejrek",
  desc = "Se vuoi salire di grado tra i guerrieri, faresti meglio a essere $Gtosto:tosta;. Posso insegnarti mosse nuove, ma prima dimostrami che sai cavartela contro nemici veri.$B$BVejrek è il troll più duro che troverai da queste parti, ed è lui che devi battere. Ha una capanna sulle colline appena a sud del Covo dei Frostmane.$B$BPortami la testa di Vejrek e saprò che hai fegato.",
  obj = "Porta Vejrek's Head a Muren Stormpike, a Ironforge.",
  progress = "Sei $Gstato:stata; alla capanna di Vejrek, $N? È puzza di $R quella che sento addosso a te?",
  reward = "Era proprio brutto, Vejrek, eh? Bel lavoro, $N! Hai la stoffa giusta, ora cominciamo la lezione...$B$BForse non lo sai, ma per $Gun:una; $C una buona difesa è molto importante. Permette di restare in piedi contro nemici che abbatterebbero chiunque altro, ed è proprio quello di cui i tuoi alleati hanno bisogno.",
  en_title = "Vejrek",
  en_obj = "Bring Vejrek's Head to Muren Stormpike in Ironforge.",
}
T[1679] = {
  title = "Muren Stormpike",
  desc = "Salve, $Gguerriero:guerriera;! Sei molto promettente, ma devi ancora imparare qualche trucco, e Muren Stormpike è proprio il nano giusto per insegnarteli.$B$BTroverai Muren nella Sala d'Armi, nel Quartiere Militare di Ironforge. Parla con lui quando sei $Gpronto:pronta; a imparare cosa significa essere $Gun guerriero:una guerriera;.",
  obj = "Parla con Muren Stormpike.",
  reward = "Ah, $N. Ho sentito i guerrieri del Dun Morogh fare il tuo nome. Spero che tu non abbia passato tutto il tempo nei birrifici!",
  en_title = "Muren Stormpike",
  en_obj = "Speak with Muren Stormpike.",
}
T[1680] = {
  title = "Tormus Deepforge",
  desc = "Ora che hai imparato qualche mossa, è il momento di procurarti un'arma decente. Parla con Tormus Deepforge. Può farti un'arma che, ne sono sicuro, ti piacerà.$B$BTroverai Tormus qui a Ironforge, alla Grande Forgia.",
  obj = "Parla con Tormus Deepforge.",
  reward = "Ti manda Muren, eh? Sì, posso farti una bella arma... ma prima ho un favore da chiederti.$B$BNon preoccuparti. È parecchio pericoloso e potrebbe costarti la vita: è proprio il genere di lavoro che $Gun:una; $C desidera.",
  en_title = "Tormus Deepforge",
  en_obj = "Speak with Tormus Deepforge.",
}
T[1681] = {
  title = "Presidio di Ironband",
  desc = "Il mio maestro, Sturgy Ironband, aveva un presidio a sud del Lago di Lettofreddo, nel Dun Morogh orientale. Lì insegnava la forgiatura, ed era il migliore.$B$BMa un giorno uno dei suoi allievi gli portò un carico di uno strano minerale. Mastro Ironband lo chiamò minerale ombrale e non vedeva l'ora di lavorarlo, ma poco dopo il suo arrivo... una banda di nani Dark Iron attaccò il presidio. Uccisero tutti!$B$BEntra nel presidio di Ironband, $N, e vendica la morte del mio maestro. E portami il carico di minerale ombrale che l'ha causata.",
  obj = "Porta un carico di Umbral Ore a Tormus Deepforge, a Ironforge.",
  progress = "Sei $Gentrato:entrata; nel Presidio di Ironband? Hai trovato il minerale ombrale?",
  reward = "L'hai trovato! Ben fatto!$B$BSpero che tu abbia ucciso una schiera di nani Dark Iron mentre cercavi. Temo che il presidio di Ironband non sarà l'ultimo posto in cui li vedremo.$B$BMa grazie per il minerale, $N. Non vedo l'ora di lavorarlo e di scoprirne le proprietà.",
  en_title = "Ironband's Compound",
  en_obj = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.",
}
T[1682] = {
  title = "Armi di Ferro Grigio",
  reward = "Ecco delle armi, appena uscite dall'incudine e fatte con il nuovo minerale ombrale che mi hai portato!$B$BPer favore, $N, scegli quella che preferisci!",
  en_title = "Grey Iron Weapons",
}
T[1683] = {
  title = "Vorlus Zoccolo Vile",
  desc = "Prima che io possa insegnarti, devi dimostrarmi la tua determinazione.$B$BIl satiro Vorlus Zoccolo Vile ha trovato uno dei nostri pozzi lunari più remoti, a sud-est dell'Eremo di Ban'ethil. Ora ci sguazza dentro, profanando le sue acque pure con la sua sozzura.$B$BTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e comincerò il tuo addestramento avanzato da $Gguerriero:guerriera;.$B$BIl sentiero per il pozzo lunare è ben nascosto, $N, ma resta $Gconcentrato:concentrata; e vigile e lo troverai.",
  obj = "Porta l'Horn of Vorlus a Elanaria, a Darnassus.",
  progress = "Hai il corno, $N? Il nostro pozzo lunare è libero da quel demonio di Vorlus?",
  reward = "Ben fatto, $N. È bello sapere che Vorlus è stato sconfitto e che il nostro pozzo lunare è purificato, ed è bello vedere giovani guerrieri desiderosi di tenere la nostra amata Teldrassil libera dalla corruzione.$B$BOra cominciamo il tuo addestramento...",
  en_title = "Vorlus Vilehoof",
  en_obj = "Bring the Horn of Vorlus to Elanaria in Darnassus.",
}
T[1684] = {
  title = "Elanaria",
  desc = "Salve, $Gguerriero:guerriera;. La tua abilità cresce, ma nella tua professione c'è più di quanto tu possa credere. Per progredire ancora, presto dovrai trovare un insegnante.$B$BLa guerriera Elanaria vive a Darnassus, alla Terrazza dei Guerrieri. Sarà lei a istruirti.",
  obj = "Parla con Elanaria.",
  reward = "Ti porgo i miei saluti, $N. Il tuo nome risuona forte a Darnassus, perché mostri del talento. Ma presto vedremo se possiedi la forza di volontà per seguire la via $Gdel:della; $C.",
  en_title = "Elanaria",
  en_obj = "Speak with Elanaria.",
}
T[1685] = {
  title = "La Convocazione di Gakin",
  desc = "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me lo aspetto, mi vieni incontro.$B$BHo perso abbastanza tempo a cercarti, quindi non ti trattengo oltre. Il Maestro Gakin ti ha convocato per un ulteriore addestramento. Mi sa che dovresti andare a cercarlo il prima possibile.$B$BLo troverai nel seminterrato della taverna dell'Agnello Sgozzato. A proposito, faresti bene a non parlare in giro di quel posto. Meglio che non se ne sparga la voce.",
  obj = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  reward = "Era ora che arrivassi. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.$B$BNon importa.$B$BSei $Grimasto:rimasta; troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente resta a lungo con la testa attaccata al collo.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1686] = {
  title = "L'Ombra di Elura",
  desc = "Hai imparato molto, $N. Ora ti forgeremo un'arma. Un'arma da guerriero.$B$BPer farlo, devi andare a Darkshore.$B$BMolto tempo fa una nave si schiantò sugli scogli vicino al faro di Auberdine, spargendo molte casse di minerale di elunite sul fondo dell'oceano.$B$BPrima devi sconfiggere la guardiana dell'elunite, l'Ombra di Elura. Un tempo era il capitano della nave; maledisse se stessa, condannandosi a vagare negli abissi e a proteggere il suo carico in eterno. Sconfiggila, prendi il suo medaglione e raccogli le casse di Elunite perduta.",
  obj = "Porta 8 carichi di Elunite Ore e l'Elura's Medallion a Elanaria, a Darnassus.",
  progress = "Hai sconfitto l'Ombra di Elura, $N? E hai il minerale di elunite perduto?",
  reward = "Hai agito con coraggio, $N.$B$BHai dato all'Ombra di Elura la pace che meritava, e useremo l'elunite raccolta per forgiarti un'arma pregiata.",
  en_title = "The Shade of Elura",
  en_obj = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.",
}
T[1687] = {
  title = "Il Faro Spettrale",
  desc = "A volte, a notte fonda, le matrone dell'orfanotrofio ci raccontano storie di paura. Sono FANTASTICHE! Ce n'è una su un fantasma che infesta un faro a Westfall. Dicono che fosse un capitano pirata a cui altri pirati avevano preso la nave. Wow!$B$BMi porteresti a vedere il faro a Westfall, per piacere? Voglio vedere se il fantasma di quel capitano c'è davvero! Prometto di starti vicino; non scapperò né niente!",
  obj = "Porta l'orfano a vedere il faro al largo della costa di Westfall.",
  progress = "Siamo arrivati?",
  reward = "WOW, era un fantasma vero! È stato fantastico: non vedo l'ora di raccontarlo a tutti all'orfanotrofio. Il capitano Grayson... sembrava proprio un pirata! Da grande voglio essere un pirata fantasma anch'io!$B$BGrazie di avermi portato a Westfall, $N. So che là fuori, nelle terre selvagge di Westfall, ci sono cose che fanno paura, e spero di non averti dato troppo fastidio. Sei $Gfantastico:fantastica;!",
  en_title = "Spooky Lighthouse",
  en_obj = "Take the orphan to see the lighthouse off the coast of Westfall.$B",
}
T[1688] = {
  title = "Surena Caledon",
  desc = "Avevo un'allieva di nome Surena Caledon. Stava dove stai tu ora, desiderosa di imparare la magia degli stregoni, e con un talento non da poco. Per di più era giovane e piacevole allo sguardo. Se solo me ne fossi accorto allora, quella sgualdrina traditrice!$B$BQuella ladra svergognata è scappata con uno dei Defias, Erlan Drudgemoor. La sua perdita conta poco, ma le avevo regalato un girocollo di sanguinite che devo riavere.$B$BOra la sua vita non significa niente per me. La troverai al Campo di Zucche di Brackwell. Recupera ciò che è mio.",
  obj = "Recupera Surena's Choker per Gakin the Darkbinder, a Stormwind.",
  progress = "Anche i più anziani e saggi possono perdere la testa davanti alle lusinghe della giovinezza e della bellezza, $N. Un consiglio che faresti bene a ricordare per tutta la vita.",
  reward = "Surena aveva talento, ma non abbastanza da padroneggiare da sola la magia degli stregoni. È un peccato vedere un talento sprecato, ma a volte è necessario.$B$BSpero che l'investimento che ho fatto su di te dia risultati diversi.",
  en_title = "Surena Caledon",
  en_obj = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.",
}
T[1689] = {
  title = "Il Vincolo",
  desc = "Recuperando il mio girocollo e battendo Surena, hai dimostrato di essere capace almeno quanto lei.$B$BDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, sì, ma essere uno stregone è molto più di questo.$B$BTi mostrerò come comandare un voidwalker, ma prima devi richiamarne uno in un cerchio di evocazione e sottometterlo con tutte le armi — fisiche e magiche — che hai a disposizione. Usa la magia di questo girocollo nel cerchio di evocazione qui sotto.",
  obj = "Usando il Bloodstone Choker, evoca e sottometti un Voidwalker, poi riporta il Bloodstone Choker a Gakin the Darkbinder, a Stormwind.",
  progress = "Non posso mostrarti come controllare un voidwalker finché non ne avrai sopraffatto uno.",
  reward = "Hai fatto meglio di quanto mi aspettassi, $N, ma non bene quanto speravo. Ora puoi imparare a comandare il voidwalker che hai soggiogato, un alleato che ti sarà prezioso nelle prove che di certo ti aspettano.$B$BPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, $N.",
  en_title = "The Binding",
  en_obj = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.",
}
T[1690] = {
  title = "Giustizia Contro i Wastewander",
  desc = "Ehi, tu! È ora che tu dia una bella mano alla Gadgetzan Water Company.$B$BI nomadi Wastewander, là nel deserto di Tanaris, si sono presi quasi tutti i pozzi d'acqua! Se non possiamo usarli, le nostre scorte d'acqua si esauriranno in un attimo. Se vuoi entrare nelle nostre grazie, ci aiuterai a fare giustizia di quei nomadi!$B$BVai a est di qui e abbatti dieci fra Banditi e Ladri Wastewander, poi torna a rapporto da me di corsa. La giustizia non aspetta nessun uomo... goblin... bah, datti da fare e basta!",
  obj = "Abbatti 10 fra Wastewander Bandits e Wastewander Thieves a est di Gadgetzan, poi torna a rapporto da Chief Engineer Bilgewhizzle.",
  progress = "Già di ritorno? Spero che tu sia $Griuscito:riuscita; a portare un po' di giustizia alla goblin a quei Banditi e Ladri Wastewander, come ti avevo chiesto!",
  reward = "Questa sì che la chiamo efficienza! Hai sfoltito abbastanza le file dei nomadi, e ora possiamo cominciare a pensare a come riprenderci quei pozzi.$B$BLa Gadgetzan Water Company ti ringrazia dell'aiuto, ma con quegli schifosi nomadi siamo ben lontani dall'aver finito. Ascolta bene — ecco cosa ci serve adesso...",
}
T[1691] = {
  title = "Altra Giustizia Contro i Wastewander",
  desc = "Adesso ci serve che tu affronti i ranghi più forti dei nomadi Wastewander. Finora hai fatto un buon lavoro, ma se dobbiamo riprenderci quei pozzi, ha senso farlo contro meno nomadi possibile!$B$BStavolta devi abbattere i loro furfanti, assassini e maghi dell'ombra. Li troverai a est e a sud-est di qui.$B$BNon ti mentirò — sono gentaccia. Fallo per noi, però, e saremo sulla buona strada per riprenderci ciò che è nostro di diritto!",
  obj = "Abbatti 10 Wastewander Shadow Mages, 8 Wastewander Rogues e 6 Wastewander Assassins per Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Allora, sei $Griuscito:riuscita; a far fuori quei nomadi come ti avevo chiesto? La Gadgetzan Water Company sta preparando dei piani che contano sul tuo successo! Non deluderci, eh...",
  reward = "Lavoro di prim'ordine, $N... di prim'ordine! Hai ridotto la popolazione dei nomadi al punto che possiamo davvero portare la battaglia in casa loro!$B$BSe non l'hai già fatto, parla con l'Addetto ai Rubinetti Luglunket, qui; dà una ricompensa per ogni otre d'acqua dei Wastewander che ti è capitato di trovare mentre assicuravi quei nomadi alla giustizia!",
}
T[1692] = {
  title = "Fabbro Mathiel",
  desc = "Ho messo in una cassa l'elunite che hai raccolto. Portala al fabbro Mathiel, e lui ti forgerà un'arma di elunite.$B$BMathiel è a sud, dall'altra parte di questo edificio.",
  obj = "Porta la Case of Elunite a Smith Mathiel.",
  progress = "Salve, giovane $C. Come posso servirti con la mia arte?",
  reward = "Ah, minerale di elunite. È un metallo splendido da lavorare, perché è benedetto dalla dea Elune in persona. Sarebbe un onore forgiarci delle armi.$B$BAttendi, per favore, mentre lavoro...",
  en_title = "Smith Mathiel",
  en_obj = "Bring the Case of Elunite to Smith Mathiel. ",
}
T[1693] = {
  title = "Armi di Elunite",
  reward = "$N, ho forgiato queste armi con l'elunite che mi hai portato. Per favore, prendi quella che ti si addice di più.$B$BE devo ringraziarti. Lavorare l'elunite è sia un onore sia un piacere.",
  en_title = "Weapons of Elunite",
}
T[1698] = {
  title = "Yorus Barleybrew",
  desc = "Yorus Barleybrew ha lanciato una sfida a tutti i guerrieri valenti dell'Alleanza. Aspetta alla Locanda di Lakeshire, a Redridge, e promette una grande ricompensa a chiunque riesca a superare la sua prova.",
  obj = "Parla con Yorus Barleybrew.",
  reward = "Ah! Quindi hai sentito parlare della mia sfida, eh?$B$BBeh, siediti e ascolta. Fatti un bicchiere, e gustatelo... perché potrebbe essere l'ultimo.",
  en_title = "Yorus Barleybrew",
  en_obj = "Speak with Yorus Barleybrew.",
}
T[1699] = {
  title = "La Prova di Rethban",
  desc = "La mia sfida la chiamo la Prova di Rethban. Per superarla, devi solo entrare nelle Caverne di Rethban, arrivare al primo bivio e tornare qui. Facile! Se non fosse per qualche piccolo intoppo...$B$BDevi tornare entro un'ora.$B$BSulla strada c'è un sacco di Gnoll di Redridge.$B$BPrima di partire, devi mandare giù un sorso della bevanda tipica della mia famiglia: la Barleybrew Scalder!$B$BAllora, che ne dici? Le Caverne di Rethban sono sulle colline a nord di Lakeshire. Sei $Gpronto:pronta; ad affrontare la Prova di Rethban?",
  obj = "Entra nelle Caverne di Rethban, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo stabilito.$B$BNon devi morire né rilasciare lo spirito.",
  progress = "Il tempo stringe, $N. Se fossi in te, mi darei una mossa...",
  reward = "Ce l'hai fatta! Ben fatto! Tre urrà per $N!",
  en_title = "The Rethban Gauntlet",
  en_obj = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit.",
}
T[1700] = {
  title = "Grimand Elmore",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere a Grimand Elmore. È qui nel Distretto dei Nani, nella bottega di armi.$B$BE abbassati quando glieli dai. È orgogliosissimo della sua abilità, e non gli piacerà l'idea di imparare qualcosa da me...",
  obj = "Porta Furen's Notes a Grimand Elmore.",
  progress = "Salve, piacere di conoscerti. Come posso esserti utile?",
  reward = "L'ha scritto Furen? Come si permette! Ma se gli ho insegnato tutto quello che sa! Pensare che possa insegnarmi qualcosa è un oltraggio! Un oltraggio!$B$BMm... però c'è una cosa nei suoi appunti che vorrei provare...",
  en_title = "Grimand Elmore",
  en_obj = "Bring Furen's Notes to Grimand Elmore.",
}
T[1701] = {
  title = "Maglia Temprata nel Fuoco",
  desc = "Ti ho dato un bello scudo, ma non dobbiamo fermarci qui. Conosco i segreti per fare un'armatura di maglia durissima. Non è facile e servono materiali molto rari, ma se sei $Gdisposto:disposta; a darti da fare, te ne farò un pezzo.$B$BChe ne dici, $N? Se sei all'altezza della sfida, ti darò un elenco di cosa procurarti e dove trovarlo.",
  obj = "Raccogli i materiali che servono a Furen Longbeard e portaglieli, a Stormwind.",
  progress = "Come va la caccia al tesoro, $N? Hai i materiali?",
  reward = "Hai preso tutto? Incredibile! Temevo proprio che quelle chimere ti avrebbero divorato!$B$BBeh, mettiamoci al lavoro su quell'armatura...",
  en_title = "Fire Hardened Mail",
  en_obj = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.",
}
T[1702] = {
  title = "Il Fabbro di Scudi",
  desc = "Hai davvero dimostrato di che pasta sei $Gfatto:fatta; quando hai affrontato la Prova di Rethban, $N. E io mantengo la parola. Ti darò la ricompensa che ti ho promesso...$B$BSolo che si trova a Stormwind.$B$BParla con il mio amico Furen Longbeard, nel Distretto dei Nani di Stormwind. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.$B$BEcco, porta a Furen questo barile di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.",
  obj = "Porta il Cask of Scalder a Furen Longbeard.",
  progress = "Salve! Che sete, di questi tempi, non trovi?",
  reward = "Ah, la Barleybrew Scalder. Roba ottima! Quindi sei $Gstato:stata; da Yorus, eh?$B$BUno scudo te lo procuro, eccome! Non ne troverai uno migliore, e non è una bugia!",
  en_title = "The Shieldsmith",
  en_obj = "Bring the Cask of Scalder to Furen Longbeard.",
}
T[1703] = {
  title = "Mathiel",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere al fabbro Mathiel. Vive a Darnassus, che è piuttosto lontano, ma sono sicuro che sarà molto grato di imparare quello che ho imparato io.",
  obj = "Porta Furen's Notes a Mathiel.",
  progress = "Ti porgo i miei saluti, $C.",
  reward = "Sono interessanti, davvero molto interessanti. Il mio collega nano Furen ha fatto una grande scoperta!$B$BGrazie, $N. Sarà un onore applicare le sue nuove tecniche alle mie creazioni.",
  en_title = "Mathiel",
  en_obj = "Bring Furen's Notes to Mathiel.",
}
T[1704] = {
  title = "Klockmort Spannerspan",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e mi serve qualcuno che li porti a Klockmort Spannerspan. È un fabbro gnomo di Ironforge, e quando scoprirà quello che ho imparato... scommetto che si strapperà la barba per l'emozione.",
  obj = "Porta Furen's Notes a Klockmort Spannerspan.",
  progress = "Buongiorno, o buon mattino o buonasera. Da quaggiù non riesco a capirlo. Allora, hai qualche lavoro per me?",
  reward = "Oh, cielo! Questi appunti sono fantastici! E per giunta... sono incredibili, sono stupefacenti e mi fanno tremare le ginocchia!$B$BFuren ha fatto una scoperta! Una vera scoperta! Non vedo l'ora di provare la sua nuova tecnica!",
  en_title = "Klockmort Spannerspan",
  en_obj = "Bring Furen's Notes to Klockmort Spannerspan.",
}
T[1705] = {
  title = "Sangue Bruciante",
  desc = "Mi secca ammetterlo, ma Furen potrebbe aver davvero scoperto qualcosa. Per esserne sicuro, però, devo provare le sue tecniche su un'armatura nuova. Se mi aiuti con i materiali, $N, l'armatura potrai tenerla tu.$B$BPer fare questa armatura mi servono dei campioni di sangue bruciante e una roccia ardente.$B$BL'unico posto che conosco dove trovarli è Duskwood. I worgen Nightbane che hanno la loro base nella miniera Rovina di Roland hanno il sangue bruciante, e il loro capo, Gutspill, avrà la roccia.$B$BChe la fortuna ti renda $Grapido:rapida;, $N.",
  obj = "Porta 20 fiale di Burning Blood e 1 Burning Rock a Grimand Elmore, a Stormwind.",
  progress = "$N, hai il sangue bruciante e la roccia? Mi servono per completare l'armatura.",
  reward = "Bel lavoro! Ora, se vuoi scusarmi, anch'io ho del lavoro da fare...",
  en_title = "Burning Blood",
  en_obj = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.",
}
T[1706] = {
  title = "L'Armatura di Grimand",
  reward = "Stento a crederci! La tecnica di Furen ha funzionato, e questa armatura dovrebbe reggere a sollecitazioni enormi.$B$BEccola, $N. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per metterla alla prova di persona.",
  en_title = "Grimand's Armor",
}
T[1707] = {
  title = "Taglia sugli Otri d'Acqua",
  desc = "Salute, $N — mi chiamo Luglunket, e abbiamo un lavoro importante per te, se te la senti! Urrà!$B$BDa addetto ai rubinetti di lunga esperienza, niente mi farebbe più piacere che ritirare gli otri d'acqua dei Wastewander che ti capita di trovare nel deserto. Tanto quella è acqua nostra — i nomadi l'hanno solo rubata, tutto qui! La Gadgetzan Water Company ti offrirà un pacco dono ufficiale ogni cinque otri consegnati. Ma soprattutto, stai aiutando Gadgetzan ad aiutarsi da sola!",
  obj = "Porta 5 Wastewander Water Pouches a Spigot Operator Luglunket a Gadgetzan.",
  progress = "Hai i cinque otri d'acqua dei Wastewander che ci servono? Se li hai, il Pacco Dono della Gadgetzan Water Company, Modello 103-XB, sarà tuo!",
  reward = "Eccellente — più otri d'acqua riusciamo a recuperare, più saremo tutti lontani dal disastro! Continua a portarmeli, e non mancherò di ricompensarti per ogni cinque otri d'acqua che mi porti.",
}
T[1708] = {
  title = "Corallo di Ferro",
  desc = "Voglio provare le nuove tecniche di Furen Longbeard su un'armatura tutta mia. E visto che tu hai aiutato Furen e lui ha aiutato me, l'armatura, una volta fatta, sarà tua!$B$BPer finire il pezzo mi serve un corallo speciale, il corallo rovente. Cresce in un solo posto — lungo la costa a sud di Menethil Harbor, nelle Wetlands.$B$BPortami abbastanza corallo rovente e mi metterò subito al lavoro sull'armatura. E sbrigati, $N. Sono così impaziente di cominciare che mi si attorcigliano le dita dei piedi!",
  obj = "Porta 20 carichi di Searing Coral a Klockmort Spannerspan, a Ironforge.",
  progress = "Salve, salve, $N! Hai il corallo rovente? Non vedo l'ora di mettermi al lavoro!",
  reward = "Proprio quello che ci voleva! Ben fatto! Ora lascia che lo fonda e lo martelli, così posso combinare la tecnica di Furen con la mia, e poi vediamo che succede!$B$BOh cielo, oh cielo! Me lo sento che l'armatura sarà molto molto molto resistente!",
  en_title = "Iron Coral",
  en_obj = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.",
}
T[1709] = {
  title = "La Creazione di Klockmort",
  reward = "Ecco la tua armatura, $N. Il procedimento di Furen ha funzionato benissimo! Alla perfezione! Davvero a meraviglia!$B$BPotresti passarci sopra con una macchina d'assedio e riprenderebbe subito la sua forma!",
  en_title = "Klockmort's Creation",
}
T[1710] = {
  title = "Conchiglie Sbiancate dal Sole",
  desc = "Il mio collega Furen Longbeard ha fatto una scoperta che non vedo l'ora di mettere alla prova. Vorrei provarla su una nuova armatura che sto studiando, perché credo che le tecniche di Furen daranno risultati migliori.$B$BMi aiuterai? Se raccogli ciò che mi serve per fare l'armatura, ne farò un pezzo in più per te.$B$BMi servono i gusci d'uovo bruciati dal sole delle Viverne di Highperch che vivono a Highperch, nelle Thousand Needles. Cerca i gusci sotto i loro nidi, e torna da me quando ne avrai abbastanza.",
  obj = "Porta 20 Sunscorched Shell a Mathiel, a Darnassus.",
  progress = "Hai i gusci, $N? Sono molto robusti, e se ne può ricavare una lacca con cui rivestirò gli anelli della mia nuova armatura di maglia.",
  reward = "Ah, grazie. Andranno benissimo!$B$BComincerò subito a forgiare l'armatura...",
  en_title = "Sunscorched Shells",
  en_obj = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.",
}
T[1711] = {
  title = "L'Armatura di Mathiel",
  reward = "Ho finito il tuo pezzo d'armatura, e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono fuse alla perfezione con le mie, e sono sicuro che questa armatura si dimostrerà molto resistente.$B$BGrazie, $N. Che ti sia utile nelle battaglie future.",
  en_title = "Mathiel's Armor",
}
T[1712] = {
  title = "Cyclonian",
  desc = "Ho passato secoli a osservare questo luogo. Osservo per poter vedere, un giorno, la caduta del grande Cyclonian. Ma non ho ancora trovato un campione capace di sconfiggere il signore del vento.$B$BForse sei tu quel campione.$B$BDimostramelo. Raccogli gli oggetti che mi servono per evocare Cyclonian, e saprò che sei $Gun grande guerriero:una grande guerriera;. Forse allora potrai sconfiggerlo e prendere il suo cuore turbinante.$B$BSe ci riuscirai, infonderò il potere del cuore in un'arma, e quell'arma la darò a te.$B$BEcco una pergamena con gli oggetti che mi servono.",
  obj = "Porta gli oggetti elencati in Bath'rah's Parchment a Bath'rah the Windwatcher, ad Alterac.",
  progress = "Hai gli oggetti, $N? Raccoglierli è la prova che mi serve per sapere che hai la forza di affrontare Cyclonian.",
  reward = "Hai raccolto gli oggetti per il mio incantesimo, e mi hai mostrato la tua forza e la tua astuzia. Ma la prossima fase della nostra impresa è ancora più pericolosa.$B$BSperiamo che la tua forza non vacilli.",
  en_title = "Cyclonian",
  en_obj = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.",
}
T[1713] = {
  title = "L'Evocazione",
  desc = "Sono pronto a compiere il rituale per evocare Cyclonian. Quando sarà evocato, dovrai sconfiggerlo e prendere il suo cuore turbinante. Lo userò per infondere in un'arma il potere di Cyclonian.$B$B$N, sei $Gpronto:pronta; ad affrontare il signore del vento?",
  obj = "Porta il Whirlwind Heart a Bath'rah Windwatcher.",
  progress = "$N, devo avere il cuore turbinante!",
  reward = "Ce l'hai fatta! Hai sconfitto Cyclonian e hai preso il Cuore Turbinante!",
  en_title = "The Summoning",
  en_obj = "Bring the Whirlwind Heart to Bath'rah Windwatcher.",
}
T[1714] = {
  title = "L'Essenza dell'Esiliato",
  progress = "Il calderone ribolle. I suoi vapori ti chiamano...",
  reward = "Gli amuleti affondano lentamente nelle profondità del calderone...$B$BUna grossa bolla sale in superficie e scoppia...$B$B...e appare un grumo di roccia fusa che ribolle.",
  en_title = "Essence of the Exile",
}
T[1715] = {
  title = "L'Agnello Sgozzato",
  desc = "Hmph. Un tempo tutti gli stregoni del Khaz Modan venivano addestrati sotto la guida dei maestri di Gnomeregan, ma ora che siamo stati tutti costretti a trasferirci in questa tana di topi a Ironforge, e che Magni ha deciso di tenerci d'occhio, dobbiamo mandare i nostri novizi ad addestrarsi a Stormwind.$B$BPer fortuna Gakin non è uno sprovveduto, quindi imparerai comunque quello che ti serve, ma mi fa ribollire il sangue!$B$BComunque, troverai Gakin nel seminterrato dell'Agnello Sgozzato, a Stormwind.",
  obj = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  reward = "Ti manda Blackwrench, eh? Quei dannati stregoni di Ironforge devono sistemare le loro faccende. A Stormwind c'è poco spazio e ci sono pochi insegnanti. Con tutto questo via vai, prima o poi attireremo l'attenzione.",
  en_title = "The Slaughtered Lamb",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1716] = {
  title = "Divoratrice di Anime",
  desc = "Una succube è una divoratrice di anime, una distruttrice di cuori e una dominatrice di menti. Non conosce altro che il male.$B$BSarà questa la creatura che imparerai a evocare e controllare, ma non può essere portata nel nostro mondo senza uno stimolo.$B$BCon un simbolo d'amore come esca, risponderà di certo al tuo richiamo. Allora potrai sconfiggerla e farne il tuo strumento.$B$BSarà difficile trovare qualcosa del genere, però. Dovresti parlare con Takar the Seer. Lo troverai nelle Barrens di Kalimdor, vicino a Camp Taurajo.",
  obj = "Parla con Takar the Seer, nelle Barrens.",
  reward = "La traversata è stata difficile, $N? Hai fatto molta strada per parlare con me. Ma non temere: so perché Gakin ti ha mandato, e ha fatto bene, perché posso aiutarti nella tua ricerca.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Takar the Seer in the Barrens.",
}
T[1717] = {
  title = "La Convocazione di Gakin",
  desc = "$N! Non mi aspettavo di vederti da queste parti, ma mi avevano chiesto di tenere gli occhi aperti nel caso passassi.$B$BÈ più che ora che tu riceva altro addestramento, quindi la prossima volta che sei a Stormwind dovresti passare da Gakin. Ti starà aspettando.",
  obj = "Presentati da Gakin the Darkbinder, a Mage Quarter di Stormwind.",
  reward = "Sono contento che qualcuno sia riuscito a rintracciarti, $N. Cominciavo a temere il peggio. Sarebbe un peccato perderti, dopo tutto il tempo che abbiamo investito su di te.$B$BMa ne parleremo più tardi. Adesso conta solo il tuo addestramento.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1718] = {
  title = "L'Isolano",
  desc = "La tua fama di $Gguerriero:guerriera; cresce, $N. Ora è il momento di misurarti con i tuoi pari e di vedere a che punto sei.$B$BAl largo della costa delle Barrens, a sud di Ratchet, c'è un'isola. Si chiama Isola della Contesa, ed è un luogo dove i guerrieri si incontrano.$B$BSi incontrano, e combattono.$B$BParla con il capo dei guerrieri dell'Isola della Contesa, Klannoc Macleod. Se ti riterrà $Gdegno:degna;, Klannoc ti guiderà più avanti sulla via del guerriero.$B$BPer raggiungere l'Isola della Contesa, cerca le secche del banco di sabbia lungo la Costa dei Mercanti.",
  obj = "Parla con Klannoc Macleod.",
  reward = "Salve, $Gguerriero:guerriera;. Mi fa piacere vedere che sei $Garrivato:arrivata; all'Isola della Contesa. Spero che sia di tuo gradimento...",
  en_title = "The Islander",
  en_obj = "Speak with Klannoc Macleod.",
}
T[1719] = {
  title = "La Zuffa",
  desc = "Se vuoi imparare da me, prima devi superare la Zuffa. È una sfida che noi dell'Isola della Contesa offriamo ai guerrieri emergenti che si credono dei duri, e se riesci a superarla saprò che lo sei davvero.$B$BPer cominciare, entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei $Gpronto:pronta;, e ti manderà contro degli sfidanti.$B$BBatti tutti gli sfidanti e lui chiamerà Grande Will. Uccidi Grande Will, e torna da me entro il tempo concesso.",
  obj = "Uccidi Big Will, poi parla con Klannoc Macleod, a Fray Island.",
  progress = "Hai completato la tua sfida?",
  reward = "Ben fatto, $N. Hai superato la Zuffa!$B$BSei $Gun guerriero degno:una guerriera degna;, ed è un onore per me insegnarti...",
  en_title = "The Affray",
  en_obj = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.",
}
T[1738] = {
  title = "Cuor di Legno",
  desc = "In attesa del tuo arrivo, ho usato la mia vista per osservare il mondo e guardare attraverso le nebbie del tempo. Ho trovato ciò che cerchi.$B$BDurante la Guerra degli Antichi, due amanti caddero insieme in battaglia. Là dove esalarono l'ultimo respiro crebbe un albero noto come il cuor di legno, simbolo del loro amore eterno.$B$BDovrebbe bastare a tentare una succube. Lo troverai tra le rovine di Ordil'Aran, nella parte nord-occidentale della foresta di Ashenvale.",
  obj = "Recupera l'Heartswood ad Ashenvale e portalo a Gakin the Darkbinder, a Mage Quarter di Stormwind.",
  progress = "La tua ricerca ha avuto successo, $N?",
  reward = "Sì, vedo che andrà benissimo. Lascia che ci lavori un momento...$B$BFa comodo avere intorno un tipo pieno di risorse come Takar, vero? Se solo riuscissi a convincerlo a tornare alla civiltà.",
  en_title = "Heartswood",
  en_obj = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1739] = {
  title = "Il Vincolo",
  desc = "Con il nucleo di cuor di legno potrai lanciare un incantesimo nel cerchio di evocazione, nella cripta qui sotto, per aprire un portale da cui la succube possa passare.$B$BFa' attenzione, $N: le succubi hanno sopraffatto anche le menti più forti.$B$BUna volta che l'avrai battuta e rimandata nel vuoto, torna da me e ti mostrerò come richiamarla e controllarla.",
  obj = "Usando l'Heartswood Core, evoca e sottometti una Succubus, poi riporta l'Heartswood Core a Gakin the Darkbinder, a Slaughtered Lamb.",
  progress = "A volte mi chiedo se Surena non fosse una succube travestita, mandata a distorcere e confondere la mia mente... Ah! Credo di sopravvalutarla.",
  reward = "Ben fatto, ben fatto, $N. Vedo che abbiamo fatto bene a decidere di addestrarti. La tua prova non delude di certo.$B$BNon ho remore a mostrarti come controllare la succube che hai appena vincolato. Osserva con attenzione.",
  en_title = "The Binding",
  en_obj = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.",
}
T[1740] = {
  title = "Il Globo di Soran'ruk",
  desc = "Quando i demoni della Legione cadono in disgrazia, i loro spiriti vengono imprigionati in globi e distribuiti ai loro maghi e stregoni.$B$BSu Azeroth, molti li portavano con sé i loro servitori. Anche in frammenti, possiedono ancora i poteri dei demoni intrappolati al loro interno.$B$BIl globo di Soran'ruk fu spezzato in due parti: una fu ridotta in pezzi ancora più piccoli, usati dagli accoliti del Martello del Crepuscolo nelle Blackfathom Deeps. L'altra, più grande, era in possesso di un mago di Shadowfang Keep. Trovale e potrò ricomporlo.",
  obj = "Trova 3 Soran'ruk Fragment e 1 Large Soran'ruk Fragment e riportali a Doan Karhan, nelle Barrens.",
  progress = "Mi ci sono voluti molti anni per raccogliere i pezzi del globo di Zargain, ma mi è stato molto utile, come sono sicuro che il globo di Soran'ruk lo sarà per te.",
  reward = "Sì... Il globo non era molto frammentato, e qui ci sono quasi tutti i pezzi. Ricomporli è una cosa semplice, e Soran'ruk tornerà intero.$B$BHo dedicato la mia vita allo studio dei globi della Legione Infuocata e alla loro ricostruzione. Mi hai fatto un favore raccogliendo questi pezzi da studiare, e te li restituirò — completamente ricostruiti — nella forma che preferisci.",
  en_title = "The Orb of Soran'ruk",
  en_obj = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",
}
T[1758] = {
  title = "Tomo della Cabala",
  desc = "Per richiamare un vilsegugio da sfidare non basterà un semplice cerchio di evocazione.$B$BI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tomo della Cabala, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un vilsegugio senza aiuto.$B$BForse Krom Stoutarm può aiutarti. Oggi è uno stregone girovago, e passa le giornate ad accumulare testi antichi e ad aggirarsi furtivo nella biblioteca di Ironforge.",
  obj = "Parla con Krom Stoutarm, a Ironforge.",
  reward = "Il Tomo della Cabala? Mm... mi dice qualcosa. Però qui non l'ho mai visto — e credimi, mi ricordo ogni libro che leggo.$B$BMm...$B$BAh, sì! L'ho visto citato nei cataloghi della biblioteca.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Krom Stoutarm in Ironforge.",
}
T[1778] = {
  title = "Il Tomo della Divinità",
  desc = "Vedrò di organizzarmi per tornare presto a casa. Spero che Stephanie stia bene, a Stormwind. Non vedo l'ora di rivederla. Alla prossima, $C.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Allora, sei $Ggià tornato:già tornata;, eh? E di grazia, cosa hai combinato mentre eri via?$B$BSei $Griuscito:riuscita; ad aiutare una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Notevole, $N, queste sono di certo le azioni di chi segue la Luce.$B$BUn simile sacrificio sarà sempre ricompensato, col tempo.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1779] = {
  title = "Il Tomo della Divinità",
  desc = "Voglio che tu prenda questo, $N. Si chiama Simbolo della Vita.$B$BHai dato prova di carità e di pazienza, e ora voglio che tu dimostri quanto sei $Gdiventato:diventata; abile sia nel combattimento sia nel potere.$B$BMio marito Muiredon è tornato di recente da uno scontro con alcuni nani Dark Iron, e ne è uscito vivo per un pelo — è laggiù a farsi curare le ferite da uno dei nostri sacerdoti.$B$BPrendi il Simbolo e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che la Luce risplenda su di te.",
  obj = "Prendi il Symbol of Life e parla con Muiredon Battleforge, a Ironforge.",
  reward = "*tossisce*$B$BBuongiorno a te, $C. Non far caso alle mie ferite, il buon sacerdote qui prima o poi lo rimette in sesto, il vecchio Muiredon. Del potere di quel Simbolo della Vita che hai lì non ho mica ancora bisogno.$B$BAllora, t'ha mandato mia moglie a parlare con me, eh? Va be'. Il tempo per parlarti lo trovo — ti racconto per filo e per segno cos'è successo a Muiredon e al suo migliore amico Narm, un paladino proprio come te.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.",
}
T[1780] = {
  title = "Il Tomo della Divinità",
  desc = "Porterò queste cose ai bambini oggi stesso. Ti prego, sta' $Gattento:attenta;, $Gbuon:buona; $C. Non capita spesso che $Guomini:donne; della tua levatura si facciano vedere in città, ma hai dimostrato che i paladini qui a Stormwind non volteranno mai le spalle a chi ha bisogno.$B$BAddio.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Sei $Gtornato:tornata; così in fretta, $N. E cosa hai fatto mentre eri $Glontano:lontana; dalla Cattedrale?$B$BHai aiutato una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Be', sono colpito, $N, queste sono di certo le azioni di chi segue la Luce e mette gli altri prima di sé.$B$BUn simile sacrificio sarà sempre ricompensato, col tempo.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1781] = {
  title = "Il Tomo della Divinità",
  desc = "Prendi questo, $N. Si chiama Simbolo della Vita.$B$BHai dato prova di carità e di pazienza, e ora è giunto il momento di vedere se sei abbastanza potente da concentrare uno dei più grandi doni della Luce.$B$BIl mio amico Gazin è tornato di recente da uno scontro con alcuni Defias a Elwynn, vicino alla Veglia degli Eroi — ne è uscito vivo per un pelo. È vicino all'altare a farsi curare le ferite dai nostri sacerdoti.$B$BPrendi il Simbolo e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che tu possa crogiolarti nella gloria della Luce.",
  obj = "Porta il Symbol of Life a Gazin Tenorm, a Stormwind.",
  reward = "*tossisce*$B$BPiacere di conoscerti, $C. Non badare alle mie ferite, il buon sacerdote qui stavolta si prenderà cura del vecchio Gazin. Non avrò bisogno del potere di quel Simbolo della Vita che hai lì... non ancora, almeno.$B$BAllora, ti ha mandato Duthorian a parlare con me, eh? D'accordo. Ti racconterò esattamente cosa è capitato a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse puoi ancora aiutarci tutti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life to Gazin Tenorm in Stormwind.",
}
T[1782] = {
  title = "L'Armatura di Furen",
  reward = "Ecco la tua armatura, $N. Reggerà agli assalti più violenti, o non mi chiamo Furen Longbeard!$B$BE devo ringraziarti. Ho imparato molto lavorando con i materiali$Bche mi hai portato. Credo che un giorno farò un'altra scoperta!$B$BManderò quello che ho imparato ad altri$Bfabbri dell'Alleanza.$B$BDirò loro che mi sei $Gstato:stata; di grande aiuto, e magari vorranno ricambiare il favore.",
  en_title = "Furen's Armor",
}
T[1783] = {
  title = "Il Tomo della Divinità",
  desc = "Stavamo spiando un po' di quei nani Dark Iron che si son trincerati a sud del Lago di Lettofreddo. Lo sapevamo, che quelli lì stavano tramando qualcosa, così io e Narm abbiamo pensato di andare a guardare più da vicino — e l'abbiamo visto, il loro capo, che gli dava ordini ad alcuni dei suoi uomini.$B$BIo e Narm n'abbiamo approfittato per farne fuori qualcuno, ma quelli erano più tosti di quel che pensavamo, e poi ce ne son saltati addosso degli altri. Narm m'ha detto di scappare a chiamare rinforzi, e allora eccomi qua.$B$BNarm ha bisogno d'aiuto, e io non mi do pace finché non lo riceve.$B$BMi dai una mano, $N?",
  obj = "Prendi il Symbol of Life e riporta in vita Narm Faulk, a Dun Morogh.",
  reward = "Non so come ringraziarti, $Gfratello:sorella;.$B$BSe porti il Simbolo della Vita, posso solo pensare che ti abbiano mandato qui Tiza e Muiredon ad aiutarmi.$B$BÈ vero, sono caduto per mano dei Dark Iron mentre cercavo di prendere uno dei loro documenti: ho resistito abbastanza a lungo da permettere a Muiredon di fuggire, ma la Luce mi aveva quasi del tutto accolto quando sei $Garrivato:arrivata; tu. Il fatto che tu sia $Gstato:stata; abbastanza potente da usare il Simbolo ti promette grandi cose, ma ci sarà tempo per parlarne più avanti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.",
}
T[1784] = {
  title = "Il Tomo della Divinità",
  desc = "Prima di cadere in battaglia, Muiredon e io avevamo quasi sconfitto una delle spie Dark Iron vicino a quella casetta. Avevamo visto il loro capitano passare degli ordini alle spie, e abbiamo cercato di ucciderlo e di prendere gli ordini.$B$BAlcuni membri del consiglio di Ironforge non credono ancora che a Dun Morogh ci siano nani Dark Iron. Se prendiamo uno di quei documenti, non solo avremo la prova dei loro movimenti, ma forse anche un'idea di cosa stanno tramando.$B$BPrendi uno di quei documenti e portalo a Muiredon, $N.",
  obj = "Recupera un Dark Iron Script dai nani Dark Iron vicino a Helm's Bed, e torna da Muiredon Battleforge, a Ironforge.",
  progress = "Sei $Gtornato:tornata;! Che piacere vederti, $N. Le ferite son guarite e son quasi pronto a tornare al lago di Lettofreddo, appena riesco a convincere mia moglie che me la caverò.",
  reward = "Ah ah! Ce l'hai fatta! Hai salvato Narm, e hai pure trovato la prova che mia moglie deve portare al consiglio. Se ho mai visto una benedizione della Luce, sei proprio tu... a parte mia moglie, s'intende.$B$BGrazie ancora, $N.",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.",
}
T[1785] = {
  title = "Il Tomo della Divinità",
  desc = "La vedo, mia moglie, laggiù, già tutta raggiante d'orgoglio. Ti conviene portare le chiappe laggiù, e di corsa. Mi sa che ha un paio di cose da dirti.$B$BLa Luce sia con te, possente $C. Ti cercherò sul campo di battaglia contro il Flagello e quei Dark Iron lì, quando sarà ora.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Oggi hai fatto un grande favore a tutta Ironforge, $N. Sono fiera di annoverarti tra noi, e se ti senti $Gpronto:pronta;, vorrei benedirti con questa pergamena. Il Simbolo della Vita avrebbe funzionato solo nelle mani di un paladino pronto per una delle più grandi benedizioni della Luce — il potere di riportare in vita i morti.$B$BTi insegnerò l'abilità di resuscitare i tuoi compagni. Usala con saggezza, $N, e grazie, a nome mio, di mio marito e di Ironforge.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1786] = {
  title = "Il Tomo della Divinità",
  desc = "Henze e io eravamo arrivati alla Veglia degli Eroi, un'isola in mezzo al Lago del Memoriale, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati oltre i nostri confini, e volevamo una prova da portare ai consiglieri del re.$B$BAbbiamo avvistato un paio di quei farabutti che esaminavano dei documenti, e li abbiamo attaccati. Purtroppo siamo stati presto sopraffatti da altri maghi.$B$BHenze li ha trattenuti per me mentre scappavo... quello sciocco, a fare il coraggioso.$B$BÈ ancora là fuori, Henze. Puoi aiutarci, $N?",
  obj = "Prendi il Symbol of Life e riporta in vita Henze Faulk, a Elwynn.",
  reward = "Grazie, $Gfratello:sorella;.$B$BVisto che impugni il Simbolo della Vita, posso supporre che ti abbiano mandato Duthorian o Gazin?$B$BSono caduto per mano degli incantatori Defias mentre Gazin e io cercavamo di sottrarre loro i piani: ho resistito abbastanza a lungo da permettere a Gazin di fuggire, ma alla fine la loro magia mi ha sopraffatto.$B$BMa tu sei $Griuscito:riuscita; a riportarmi indietro: la capacità di usare il Simbolo non è concessa a chiunque, $N. È di buon auspicio per te che tu sia $Griuscito:riuscita; a dargli forza con la tua fede.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.",
}
T[1787] = {
  title = "Il Tomo della Divinità",
  desc = "Avremo tempo di parlare ancora del Simbolo più avanti. Ora l'importante è prendere quelle carte che i Defias stavano esaminando. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn, e magari capire qualcosa dei loro piani.$B$BPer ora non sono in condizioni di combattere, $N. Pensi di essere abbastanza forte da prendere quelle carte ai Defias qui sull'isola?$B$BSe riesci a prenderle, portale a Gazin e digli che sto bene.",
  obj = "Recupera un Defias Script dai Defias Rogue Wizard a Elwynn, e torna da Gazin Tenorm, a Stormwind.",
  progress = "Henze è salvo, $N? Ci sei $Griuscito:riuscita;?$B$BTra la tua abilità con le armi e il potere della Luce, immagino che la Veglia degli Eroi sia al sicuro da qualunque minaccia dei Defias, ma questo devono dirlo il Re e i suoi consiglieri.",
  reward = "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è con te, non c'è dubbio, $N!",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.",
}
T[1788] = {
  title = "Il Tomo della Divinità",
  desc = "Porterò il documento ai consiglieri del Re dopo che Duthorian gli avrà dato un'occhiata, ma nel frattempo dovresti andare subito a parlare con Duthorian. Vorrà di sicuro darti una pacca sulla spalla!$B$BGrazie ancora, $N. Spero di rivederti. Sei di sicuro $Gun alleato:un'alleata; che sono fiero di avere per $Gamico:amica;.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Oggi hai fatto un buon lavoro, $N. Dovresti andare un po' $Gfiero:fiera; di quello che hai realizzato.$B$BE ancora di più dovresti essere $Gfiero:fiera; delle tue capacità. Non tutti possono usare il potere del Simbolo della Vita. Invocare la Luce per riportare indietro i morti significa che sei $Gpronto:pronta; per uno dei più grandi onori del paladino: il potere della resurrezione.$B$BAvrai il potere di riportare indietro i compagni caduti, proprio come hai fatto con Henze.$B$BStammi bene, $N. La Luce risplende su di te, e dovresti accoglierla senza riserve.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1789] = {
  title = "Il Simbolo della Vita",
  reward = "Affrettati, $N, perché se fallisci sarà in pericolo più di una vita.$B$BSe per qualche motivo non riesci ad aiutare Muiredon e Narm, torna da me e ti darò un altro Simbolo della Vita per il viaggio.$B$BNon scambiare il mio aiuto per semplice carità, perché devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.",
  en_title = "The Symbol of Life",
}
T[1790] = {
  title = "Il Simbolo della Vita",
  reward = "Affrettati, $N, perché se fallisci sarà in pericolo più di una vita.$B$BSe per qualche motivo non riesci ad aiutare Gazin e Henze, torna da me e ti darò un altro Simbolo della Vita per il viaggio.$B$BNon scambiare il mio aiuto per semplice carità, perché devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.",
  en_title = "The Symbol of Life",
}
T[1791] = {
  title = "Il Guardavento",
  desc = "Ora che hai imparato la Berserker Stance, ti servirà una bella arma con cui usarla.$B$BParla con Bath'rah the Windwatcher, un eremita troll che vive tra le Alterac Mountains e le Western Plaguelands. È un abile armaiolo e un potente sciamano.$B$BPer trovare Bath'rah, raggiungi il fiume che scorre lungo il fianco orientale di Tarren Mill. Seguilo verso nord — Bath'rah è accampato vicino a delle rovine sulla riva est del fiume.",
  obj = "Parla con Bath'rah the Windwatcher.",
  reward = "Hai fatto molta strada, $Ggiovane guerriero:giovane guerriera;. Vedo fuoco nei tuoi occhi. Cerchi un'arma di grande potere, vero?$B$BPosso aiutarti nella tua ricerca. E tu puoi aiutare me nella mia.",
  en_title = "The Windwatcher",
  en_obj = "Speak with Bath'rah the Windwatcher.",
}
T[1792] = {
  title = "L'Arma del Turbine",
  reward = "Ho il cuore turbinante, e sono pronto a infonderlo nell'arma che sceglierai.$B$BScegli la tua arma, $N, e sappi che il suo potere è il potere di Cyclonian.",
  en_title = "Whirlwind Weapon",
}
T[1793] = {
  title = "Il Tomo del Valore",
  reward = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?$B$BIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cattedrale della Luce.",
  en_title = "The Tome of Valor",
}
T[1794] = {
  title = "Il Tomo del Valore",
  reward = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?$B$BIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cattedrale della Luce.",
  en_title = "The Tome of Valor",
}
T[1795] = {
  title = "Il Vincolo",
  desc = "Se sei abbastanza $Gpreparato:preparata;, possiamo cominciare. Lascia che ti spieghi il procedimento.$B$BComincerò creando il cerchio di evocazione di base. Quando sarà finito, i miei accoliti useranno le verghe di incanalamento per creare il cerchio maggiore.$B$BFatto questo, leggi l'incantesimo dal Tomo della Cabala, e il vilsegugio verrà richiamato. Fa' attenzione, $N. Un vilsegugio è un avversario potente, e mi piacerebbe vederti con la testa ancora sulle spalle.",
  obj = "Usando il Tome of the Cabal, evoca e sottometti un Felhunter, poi riporta il Tome of the Cabal a Strahad Farsan, a Ratchet.",
  progress = "Ogni stregone dovrebbe avere un vilsegugio ai suoi ordini. Anche se è difficile da domare, i poteri che dà al suo padrone valgono ben più del prezzo.",
  reward = "Devo dire che sono colpito, $N. Quando ho affrontato il mio vilsegugio, me la sono cavata per un pelo. Sento che hai il potenziale per diventare $Guno degli stregoni più potenti:una delle streghe più potenti; di quest'epoca.",
  en_title = "The Binding",
  en_obj = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.",
}
T[1796] = {
  title = "Componenti per la Tonaca Dorata Incantata",
  desc = "Il primo oggetto che ti aiuterò a creare è una tonaca. Tu mi procurerai quello che serve, e lo metteremo insieme. Dopo, sempre che tu ci riesca, avrai il primo di molti oggetti che ti renderanno più potente e ti aiuteranno nelle tue lotte.$B$BPer cominciare, devi avere delle Vesti Arcane già confezionate. Può fartele un sarto, o magari puoi comprarle da qualcun altro — mi colpirebbe molto se riuscissi a farle tu — ma in ogni caso portami le vesti, e da lì proseguiremo.",
  obj = "Porta le Robes of Arcana a Menara Voidrender, nelle Barrens.",
  progress = "Come va la ricerca delle vesti, $N? Le hai create tu? Trovo che questi tocchi personali rendano tanto più dolce infondere la magia. Ti danno una soddisfazione più grande. Ma capisco se scegli la via più rapida e te le fai fare — anche una simile... ambizione ha i suoi meriti.",
  reward = "Andranno benissimo, $N.$B$BOgni oggetto magico deve nascere da un oggetto di alta qualità. Più impegno e abilità si mettono in un oggetto, più potenti sono le magie che può contenere. I componenti rari e più costosi trattengono meglio la magia. Non ti pentirai di aver fatto di queste vesti la tonaca che creeremo per te più avanti.",
}
T[1798] = {
  title = "In Cerca di Strahad",
  desc = "È ora che tu impari a evocare il vilsegugio, $N. Qui non ho i reagenti e gli oggetti necessari per insegnartelo, quindi dovrai cercare un altro membro della nostra cerchia ristretta, Strahad Farsan.$B$BAbita nel porto goblin di Ratchet. Gli manderò un messaggio per avvisarlo del tuo arrivo.",
  obj = "Parla con Strahad Farsan, nelle Barrens.",
  reward = "$N? Ah, certo. Il nostro ultimo prodigio. Temo che la realtà non sia all'altezza della leggenda.$B$BNon importa: sei qui per imparare, non per sentirmi scherzare da solo.",
  en_title = "Seeking Strahad",
  en_obj = "Speak with Strahad Farsan in the Barrens.",
}
T[1799] = {
  title = "Frammenti del Globo di Orahil",
  desc = "Bene, allora cominciamo.$B$BLa prima cosa che devi fare è parlare con i miei accoliti, all'interno. Scegli quale delle loro vie seguire — ti spiegheranno loro il resto.$B$BSecondo, devi andare a Desolace e procurarti un Globo Infernale da uno degli stregoni della Congrega di Mannoroc. È quel globo che purificherai con l'aiuto di una maga di nome Tabetha, nel profondo sud di Dustwallow Marsh. Ti aiuterà per via dei nostri trascorsi.$B$BTe lo ripeto, non tornare finché non avrai fatto entrambe le cose che ti ho chiesto.",
  obj = "Parla con gli accoliti di Menara all'interno della torre sopra Ratchet e scegli quale delle loro vie seguire.$B$BPoi porta un Infernal Orb a Tabetha, a Dustwallow Marsh.",
  progress = "E dato che chiaramente non sei $Gun mago:una maga;, mi chiedo se posso davvero fidarmi di te. Ti sento addosso l'odore del potere arcano, ma a quanto pare sei $Gsfuggito:sfuggita; al tanfo di corruzione che accompagna tanto volentieri quelli come te.$B$BSì, $Gun:una; $C... $Gun:una; $C è $Gvenuto:venuta; a chiedere il mio aiuto.$B$BAllora, cosa posso fare per te, $N?",
  reward = "Oh, quindi ti manda Menara. Mi sta bene... suppongo che per il momento tu possa restare come $Gmio:mia; ospite. Ma devi avere qualche faccenda urgente — forse sei qui in cerca di un potere perduto? Forse mi sbaglio. Forse la corruzione non è poi così lontana da te, dopotutto.",
}
T[1800] = {
  title = "Sala del Trono di Lordaeron",
  desc = "Le matrone dell'orfanotrofio dove vivo, la sera, ci raccontano grandi storie di battaglie e di leggende, se siamo stati buoni e abbiamo fatto le faccende. Una storia parlava di come cadde Lordaeron, e di come il malvagio Arthas tolse la vita a suo padre per diventare sovrano.$B$BNon aveva onore, $N! Quando sarò grande e diventerò un possente guerriero dell'Orda, la mia lama sarà guidata dall'onore, mai dal male!$B$BMi porteresti a vedere la sala del trono, per piacere? È proprio prima del punto in cui si scende nell'Undercity.",
  obj = "Porta il tuo protetto alla vecchia Sala del Trono di Lordaeron, che si trova poco prima della discesa nell'Undercity.",
  progress = "Siamo arrivati?",
  reward = "Quella sala del trono faceva paura, $N! Anche se era vuota, sembrava che lì fosse successo un grande male. Mi sono sentito arrabbiato... ma anche triste. Capisco perché le matrone ci raccontano storie così: io non tradirò mai il mio popolo in quel modo!$B$BGrazie di avermi portato nella sala del trono, $N. Ho imparato tante cose.",
  en_title = "Lordaeron Throne Room",
  en_obj = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.$B",
}
T[1801] = {
  title = "Tomo della Cabala",
  desc = "Per richiamare un vilsegugio da sfidare non basterà un semplice cerchio di evocazione.$B$BI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tomo della Cabala, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un vilsegugio senza aiuto.$B$BForse Jorah Annison può aiutarti. Oggi lavora come cartografo nell'Undercity, ma di testi antichi ne sa più di chiunque io conosca.",
  obj = "Parla con Jorah Annison, nell'Undercity.",
  reward = "Fare mappe! Immagini, stime della realtà. Non so che farmene.$B$BNei libri, nel racconto, nella descrizione! È lì che sta la verità. Darei tutte le mappe di questo negozio per un solo libro sull'ascesa della negromanzia, o per un racconto del trionfo della Signora Oscura.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Jorah Annison in the Undercity.",
}
T[1802] = {
  title = "Tomo della Cabala",
  desc = "È andato perduto, ma si sa più o meno dove potrebbe trovarsi.$B$BNe fu fatta una sola copia, che a un certo punto venne vandalizzata: una buona parte fu strappata dalla rilegatura. Si dice che in qualche modo sia finita nelle mani dei centauri delle Thousand Needles.$B$BIl resto andò perduto al largo della costa a ovest di Southshore, mentre veniva trasportato in nave a Menethil Harbor. Non arrivò mai.$B$BIn cambio di queste informazioni ti chiedo solo una cosa: se lo trovi, portamelo, così posso vederlo.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Krom Stoutarm, a Ironforge.",
  progress = "Le voci si sono rivelate vere, $N?",
  reward = "Fantastico! Ora potrò unirmi ai pochi che ne hanno sbirciato il contenuto.$B$BNon vedo l'ora di studiare meglio questo testo. È un gran giorno, $N! Lasciami solo dargli un'occhiata prima che tu te ne vada. Sono sicuro che Strahad sarà disposto a mandarmene una copia.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.",
}
T[1803] = {
  title = "Tomo della Cabala",
  desc = "Ah! Vedo che sei $Gun stregone:una strega; con gusti simili ai miei. Procurarsi il Tomo della Cabala è davvero un'aspirazione degna. Sapevi che un tempo era custodito tra le mura di Lordaeron? Però fu vandalizzato, e gli strapparono quasi metà delle pagine. Chi commetterebbe mai un atto così infame?$B$BQuella metà è perduta, anche se si dice che sia finita nelle mani dei centauri delle Thousand Needles.$B$BIl resto del testo doveva essere trasferito a Ironforge, ma andò perduto durante il viaggio, sulla costa a ovest di Southshore.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Jorah Annison, nell'Undercity.",
  progress = "Può darsi che tu stia inseguendo delle favole, $N, ma un fondo di verità si trova anche nelle voci più assurde.",
  reward = "Bene bene bene! Cosa abbiamo qui?$B$BÈ notevole, $N. Non l'avrei creduto possibile, eppure eccolo qui, nelle mie mani: il Tomo della Cabala completo.$B$BLascia che ne sfogli le pagine solo un momento, prima che tu riparta.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.",
}
T[1804] = {
  title = "Tomo della Cabala",
  desc = "Be', ecco, è difficile separarsene. Ma l'hai trovato tu, e hai cose più importanti da farci, naturalmente. Solo, ti prego, ricordati di dire a Strahad che ne volevo una copia.$B$BMentre eri via, ti ha mandato un messaggio. Voleva che ti dicessi che, perché i suoi accoliti possano aiutarti con l'evocazione, dovrai procurarti tre verghe di incanalamento.$B$BLui forse non sa dove trovarle, ma io sì! Gli ultimi a usarle sono stati gli orchi del clan Dragonmaw, nelle Wetlands. Io controllerei i loro incantatori!",
  obj = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.",
  progress = "È da un po' che non ti vedo da queste parti. Hai trovato il tomo e le verghe?",
  reward = "Ben fatto! Il Tomo della Cabala e tre perfette — un po' graffiate, direi — verghe di incanalamento.$B$BSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un vilsegugio per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1805] = {
  title = "Tomo della Cabala",
  desc = "È uno dei testi più interessanti che abbia letto negli ultimi anni. Qui la scelta è scarsa — soprattutto libri di geografia — e li ho già letti tutti. Spero che Strahad mi mandi una copia di questo tomo quando potrà.$B$BA proposito di lui, mentre eri via mi ha mandato un messaggio. Per il tuo compito devi procurarti tre verghe di incanalamento.$B$BPer avermi lasciato guardare questo testo, ti svelerò un segreto: le verghe le trovi sugli orchi del Clan Dragonmaw, nelle Wetlands.",
  obj = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.",
  progress = "Sì, $N? In cosa posso esserti utile?",
  reward = "Ben fatto! Il Tomo della Cabala e tre perfette — un po' graffiate, direi — verghe di incanalamento.$B$BSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un vilsegugio per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1806] = {
  title = "La Prova della Rettitudine",
  desc = "Perché non andiamo alla forgia e cominciamo? È da un po' che mi preparo al tuo arrivo, quindi non ci vorrà molto.$B$BQuando avremo finito, sarai molto più $Gpronto:pronta; di prima a difendere la Luce, questo te lo giuro.$B$BTi confesso una cosa, $N: vedere i frutti delle tue imprese mi rende un po' invidioso. Ma sapere che posso dare alle tue avventure un contributo tutto mio, e non da poco, mi dà una certa gioia.",
  obj = "Aspetta che Jordan Stilwell finisca di forgiare un'arma per te.",
  reward = "Eccola, $N. Un'arma degna di $Gun campione:una campionessa; della Luce come te. Le ho dato il nome di un grande paladino nanico, un mio amico. Si chiamava Verigan... Bosch Verigan.$B$BTi prego, accettala da parte mia e di mia moglie. Abbiamo un grande debito con te, e il mondo sarà un posto più sicuro con qualcuno abile come te in giro per queste terre.",
  en_title = "The Test of Righteousness",
  en_obj = "Wait for Jordan Stilwell to finish forging a weapon for you.",
}
T[1818] = {
  title = "Parla con Dillinger",
  desc = "Mi hanno detto che il Guardiamorte Dillinger ha un lavoro per qualcuno come te. Se vuoi dimostrare il tuo valore alle forze della Signora Oscura, presentati subito da Dillinger.$B$BLa postazione del Guardiamorte Dillinger è all'estremità ovest di Brill, vicino al cimitero.",
  obj = "Parla con Deathguard Dillinger, a Brill.",
  reward = "Sei qui per una missione? Bene. Ne ho una importante, che metterà alla prova la tua abilità in combattimento... e la tua determinazione nel difendere i Reietti.",
  en_title = "Speak with Dillinger",
  en_obj = "Speak with Deathguard Dillinger in Brill.",
}
T[1819] = {
  title = "Ulag la Mannaia",
  desc = "Quando il Flagello dilagò nelle Tirisfal Glades, ne catturammo uno per studiarlo. Aveva una mente libera, e si faceva chiamare Ulag la Mannaia. Ma, anche se la sua volontà era libera, era ancora soggiogato dal Re dei Lich.$B$BSperavamo di trovare un modo per spezzare il controllo del re su Ulag, ma abbiamo fallito. Ora, finalmente, è il momento di liberarlo.$B$BLiberalo, e uccidilo.$B$BAttiva il meccanismo della pietra a forma di teschio vicino al mausoleo, a nord. Toglierà il sigillo magico che lo tiene prigioniero.$B$BPoi... tieniti $Gpronto:pronta;, $N.",
  obj = "Uccidi Ulag the Cleaver, poi parla con Deathguard Dillinger.",
  progress = "Non hai ancora portato a termine il tuo compito, $N. Per un guerriero non è saggio mostrare paura...",
  reward = "Ben fatto, $N. Ulag non era un agente qualsiasi del Flagello. Hai dimostrato ai Guardiamorte, e quindi alla Signora Oscura, di essere $Gun guerriero:una guerriera; di abilità e determinazione, e di meritare un ulteriore addestramento.",
  en_title = "Ulag the Cleaver",
  en_obj = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.",
}
T[1820] = {
  title = "Parla con Coleman",
  desc = "Hai dimostrato il tuo valore alla Signora Oscura; ora forse puoi dimostrarlo a uno dei suoi sudditi.$B$BColeman Farthing aspetta un guerriero disposto a essere lo strumento della sua vendetta contro i nemici dei Reietti.$B$BLo troverai alla Gallows' End Tavern, nella parte est di Brill.",
  obj = "Parla con Coleman Farthing.",
  reward = "Sì, è vero. Ho bisogno delle tue abilità in combattimento. I miei mezzi sono pochi, ma il mio compito aiuta sia me sia la causa dei Reietti. Fallo, e la tua ricompensa sarà doppia.",
  en_title = "Speak with Coleman",
  en_obj = "Speak with Coleman Farthing.",
}
T[1821] = {
  title = "I Cimeli degli Agamand",
  desc = "Lavoravo per la famiglia Agamand quando ero in vita, e sono stati loro la causa della mia morte! È giusto che ora gli Agamand siano servitori senza mente del Re dei Lich.$B$BOra voglio prendermi quel che resta del loro onore. Entra nella loro cripta di famiglia e deruba gli Agamand dei cimeli di famiglia: una spada, un'ascia, un pugnale e una mazza. Portameli!$B$BLa cripta della famiglia Agamand si trova all'estremità nord dei mulini degli Agamand, protetta dal flagello in agguato e dagli Agamand morti.",
  obj = "Porta a Coleman Farthing l'Agamand Family Axe, l'Agamand Family Sword, l'Agamand Family Mace e l'Agamand Family Dagger.",
  progress = "Hai i cimeli, $N?",
  reward = "Ah! Li hai recuperati! Ora le maledette terre degli Agamand sono spogliate anche dell'ultima parvenza di onore e di memoria. La famiglia è davvero finita!",
  en_title = "Agamand Heirlooms",
  en_obj = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.",
}
T[1822] = {
  title = "L'Arma di Famiglia",
  reward = "Terrò tre delle armi che mi hai riportato, come ricordo del mio dolore e della mia perdita. Ma ti prego, $N, scegli il cimelio che preferisci e tienilo per te.$B$BChe ti serva meglio di quanto abbia servito i suoi maledetti vecchi proprietari.",
  en_title = "Heirloom Weapon",
}
T[1823] = {
  title = "Parla con Ruga",
  desc = "Sei $Gun guerriero:una guerriera; di talento e di fama crescente. Forse sei $Gpronto:pronta; per la prova di Ruga Ragetotem? Se è così, trova Ruga a Camp Taurajo, nelle Barrens.$B$BAspetta i guerrieri che rispondono alla sua chiamata.",
  obj = "Parla con Ruga Ragetotem.",
  reward = "Sei qui per la mia prova, $N?",
  en_title = "Speak with Ruga",
  en_obj = "Speak with Ruga Ragetotem.",
}
T[1824] = {
  title = "La Prova al Campo dei Giganti",
  desc = "Per superare questa prova, devi andare a sud, nel Campo dei Giganti. Lì troverai una moltitudine di creature striscianti simili a insetti. Sono arrivate da poco nelle Barrens, e non mi piace ciò che annunciano.$B$BPortami le loro antenne ancora frementi, e non perdere tempo, $N, perché le antenne raccolte non fremono a lungo. Portami le antenne entro il tempo stabilito e avrai superato la prova.",
  obj = "Porta 5 Twitching Antenna a Ruga Ragetotem, a Camp Taurajo",
  progress = "Hai le antenne? Se sì, dammele in fretta, perché le antenne frementi non fremono per sempre...",
  reward = "Ottimo lavoro, $N! Superando la prova al Campo dei Giganti, fai un altro passo lungo la via $Gdel:della; $C.",
  en_title = "Trial at the Field of Giants",
  en_obj = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo",
}
T[1825] = {
  title = "Parla con Thun'grim",
  desc = "Thun'grim Firegaze, un famoso fabbro orco, ha sentito parlare delle tue continue imprese valorose al servizio dell'Orda. Vorrebbe forgiarti un'armatura, e ti chiede di andare subito a parlare con lui.$B$BL'accampamento di Thun'grim è a est del Crossroads, nelle Barrens.",
  obj = "Parla con Thun'grim Firegaze, nelle Barrens.",
  reward = "Sì, sei $Gvenuto:venuta;. Bene, perché abbiamo molto di cui discutere, io e te.",
  en_title = "Speak with Thun'grim",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1838] = {
  title = "L'Armatura Brutale",
  desc = "Ho sentito racconti sulla tua forza e sul tuo valore, e voglio farti un'armatura, una compagna che ti aiuti mentre crescono i racconti delle tue grandi imprese.$B$BMa forgiare questa armatura sarà un'impresa a sé, $N. Mi servirà il tuo aiuto, e quello di altri fabbri dell'Orda.$B$BEcco, prendi questa pergamena. Ho passato molte notti a scriverci ciò che mi serve per l'armatura, faticando con questi occhi quasi ciechi. Portami gli oggetti di questa pergamena e ti creerò il primo pezzo dell'armatura.",
  obj = "Porta a Thun'grim Firegaze 15 Smoky Iron Ingot, 10 Powdered Azurite, 10 Iron Bar e una Vial of Phlogiston.",
  progress = "Hai gli oggetti della mia pergamena, $N?",
  reward = "Hai portato tutto quello che ho chiesto. Ora farò la mia parte...",
  en_title = "Brutal Armor",
  en_obj = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.",
}
T[1839] = {
  title = "Ula'elek e i Guanti Lunghi Brutali",
  desc = "Il fabbro troll Ula'elek ti forgerà i guanti brutali. Vive in Durotar, a Sen'jin Village, con i suoi fratelli Darkspear, e aspetta il tuo arrivo.",
  obj = "Parla con Ula'elek, in Durotar.",
  reward = "Salve, $N. Il vecchio Thun'grim mi ha avvisato del tuo arrivo, ma anche se non avesse detto niente, la tua presenza qui non mi avrebbe sorpreso.$B$BGli spiriti seguono i tuoi progressi, giovane $C, e mi dicono che molti nemici sono caduti davanti a te.",
  en_title = "Ula'elek and the Brutal Gauntlets",
  en_obj = "Speak with Ula'elek in Durotar.",
}
T[1840] = {
  title = "Orm Stonehoof e l'Elmo Brutale",
  desc = "Orm Stonehoof è molto rispettato per la sua abilità. Sarà lui a farti l'elmo brutale.$B$BCercalo a Thunder Bluff, vicino alla pozza accanto al grande totem centrale della città.",
  obj = "Parla con Orm Stonehoof, a Thunder Bluff.",
  reward = "Salve, $C. Sono Orm, e Thun'grim mi dice che vuoi farti fare un elmo?",
  en_title = "Orm Stonehoof and the Brutal Helm",
  en_obj = "Speak with Orm Stonehoof in Thunder Bluff.",
}
T[1841] = {
  title = "Velora Nitely e i Gambali Foderati Brutali",
  desc = "Si dice che, prima di morire, Velora Nitely fosse una delle migliori armaiole di Lordaeron. A quanto pare la morte non ha intaccato il suo talento. Parla con Velora — sarà lei a farti i gambali brutali.$B$BVelora esercita il suo mestiere nell'Undercity di Lordaeron, nel quartiere del commercio.",
  obj = "Parla con Velora Nitely, nell'Undercity.",
  reward = "Sei qui per un'armatura per le gambe? Magnifico!$B$BEhm... sono io che faccio l'armatura per te, o sei tu che la fai per me?$B$BEra una battuta. Faceva ridere? Non saprei dirlo... Ho perso il senso dell'umorismo insieme al senso dell'olfatto. Più o meno quando ho smesso di respirare.",
  en_title = "Velora Nitely and the Brutal Legguards",
  en_obj = "Speak with Velora Nitely in the Undercity.",
}
T[1842] = {
  title = "Zoccoli di Satiro",
  desc = "Posso farti un paio di guanti brutali, e racchiuderanno una grande magia. Ma prima devi raccogliere questa magia e portarmela.$B$BI satiri vivono nella parte nord-orientale di Ashenvale per via del potere della foresta. Si nutrono della sua purezza, succhiandola e corrompendola. Puoi capire quali satiri hanno assorbito più magia di Ashenvale dai loro zoccoli gonfi e non divisi.$B$BQuesti zoccoli racchiudono un grande potere. Mi serviranno per forgiare i tuoi guanti.",
  obj = "Porta 7 Uncloven Satyr Hoof a Ula'elek, a Sen'jin Village, in Durotar",
  progress = "Hai gli zoccoli, $N? La magia che contengono è forte.",
  reward = "Ah, li hai! Ora, proprio come i Satiri hanno succhiato la forza di Ashenvale, io succhierò il potere racchiuso in questi zoccoli e lo imbriglierò nel mio lavoro...",
  en_title = "Satyr Hooves",
  en_obj = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar.",
}
T[1843] = {
  title = "Guanti Lunghi Brutali",
  reward = "Grazie, $N. Questi guanti sono il mio lavoro migliore. Prendili. Indossandoli, porti onore a me e ai miei antenati.",
  en_title = "Brutal Gauntlets",
}
T[1844] = {
  title = "Il Corno della Chimera",
  desc = "Ti farò l'elmo, ma devi dimostrarmi di esserne $Gdegno:degna;.$B$BNelle regioni nord-occidentali delle Stonetalon Mountains si trova la Valle Carbonizzata. Un tempo era verdeggiante, ma ora è profanata e coperta di cenere, e le creature che vi sono rimaste sono impazzite per il dolore e la disperazione.$B$BÈ lì che ti mando, $N.$B$BDevi andare nella Valle Carbonizzata e trovare una chimera matriarca. Uccidila, liberala dalla sua sofferenza. Portami il suo corno galvanizzato come prova, e ti farò l'elmo.",
  obj = "Porta un Galvanized Horn a Orm Stonehoof, a Thunder Bluff.",
  progress = "Hai il corno? La matriarca è libera dal dolore?",
  reward = "Hai portato a termine il tuo compito, $N, e mi hai mostrato il tuo valore e la tua determinazione. L'elmo sarà tuo...",
  en_title = "Chimaeric Horn",
  en_obj = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.",
}
T[1845] = {
  title = "Elmo Brutale",
  reward = "Ti consegno questo elmo.$B$BGrandi imprese ti hanno portato da me, $N, e, se la Madre Terra vorrà... imprese ancora più grandi ti attendono.",
  en_title = "Brutal Helm",
}
T[1846] = {
  title = "Gli Stinchi dei Dragonmaw",
  desc = "Per fare i gambali brutali mi serve un paio di stinchi robusti. Gli orchi Dragonmaw delle Wetlands hanno stinchi belli spessi. Mi servono i loro.$B$BMa devono essere robusti. Assicurati di metterli alla prova mentre li raccogli. Se riesci a spezzarli a mani nude, non saranno abbastanza robusti per lavorarci.",
  obj = "Porta 8 Sturdy Dragonmaw Shinbone a Velora Nitely, nell'Undercity.",
  progress = "Aspetto quegli stinchi, $N. Saranno un'ottima struttura per i tuoi gambali.",
  reward = "Ben fatto! Sembrano tutti robusti. Credo che andranno benissimo. Come l'hanno presa quegli orchi, quando gli hai portato via gli stinchi, $N? Si sono lamentati molto?$B$BEra un'altra battuta. Non ridi.$B$BNon sono molto divertente di questi tempi, vero...",
  en_title = "Dragonmaw Shinbones",
  en_obj = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.",
}
T[1847] = {
  title = "Le Gambiere Brutali",
  reward = "Ecco le tue gambiere, $N. Fammi sapere come ti stanno o se c'è da fare qualche ritocco. Faccio di tutto per accontentare! O almeno, lo facevo una volta.$B$BOrmai il mio mestiere non m'importa granché. Ma è sempre meglio che essere una serva senza cervello del Flagello!$B$BCredo.",
  en_title = "Brutal Legguards",
}
T[1848] = {
  title = "L'Usbergo Brutale",
  reward = "Sono sicuro che hai sopportato molte fatiche e versato molto sangue per portare a termine il mio incarico, $N. Ecco il frutto del tuo lavoro.$B$BChe tu possa indossarlo con onore, e un giorno tornare qui a raccontarmi come ti ha servito.",
  en_title = "Brutal Hauberk",
}
T[1858] = {
  title = "La Shattered Hand",
  desc = "Lascio a te il compito di aprire la borsa di Tazan e di tornare da me con il suo contenuto. Il meccanismo della serratura è complesso, quindi probabilmente la cosa più facile sarebbe procurarti la chiave.$B$BVisto che non l'hai trovata sul corpo di Tazan, posso solo supporre che l'abbia lasciata in custodia a qualcun altro... Ah, sì, giusto. Aveva un assistente di nome Gamon. È un ubriacone: con ogni probabilità lo troverai alla taverna. Forse potresti alleggerirlo della chiave senza dare nell'occhio.",
  obj = "Ruba Tazan's Key, poi usala per aprire Tazan's Satchel e consegnane il contenuto a Therzok, nella Cleft of Shadow, a Orgrimmar.",
  progress = "Non è irritante avere l'oggetto del desiderio a portata di mano e non avere modo di arrivarci?",
  reward = "Mmm, questo sì che è interessante. Con questo hai più che dimostrato il tuo valore, $N. Sono davvero colpito. Considerati il membro più recente della Shattered Hand. E prendi questo: penso che in futuro ti sarà di grande aiuto.",
  en_title = "The Shattered Hand",
  en_obj = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1859] = {
  title = "Therzok",
  desc = "Abbassa la voce, $N. Sì, so come ti chiami. Mi hanno detto di tenere gli occhi aperti per $Gun orco:un'orchessa; che corrisponde alla tua descrizione.$B$BDa quello che abbiamo sentito su di te, sai cavartela in combattimento, e ogni tanto non disdegni un po' di sotterfugi.$B$BHo ragione?$B$BComunque, dovresti andare a trovare Therzok a Orgrimmar. Ha un'offerta da farti.",
  obj = "Parla con Therzok nella Cleft of Shadow, a Orgrimmar.",
  reward = "Molto bene, sono contento che Kaplak ti abbia rintracciato.$B$BAbbiamo alcune cose di cui parlare, non ultimo il tuo futuro nella Hand.",
  en_title = "Therzok",
  en_obj = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1860] = {
  title = "Parla con Jennea",
  desc = "Noi maghi abbiamo un compito da portare a termine. Un compito vitale per la sicurezza di Stormwind e dell'Elwynn Forest.$B$BI dettagli li ha Jennea Cannon. Studia nel santuario del mago, nel quartiere dei maghi di Stormwind. Dovresti raggiungerla al più presto.",
  obj = "Parla con Jennea Cannon, a Stormwind.",
  reward = "Ti hanno mandato ad aiutarmi nel mio compito, $N? Bene. Fa piacere vedere giovani maghi così desiderosi di aiutare la nostra causa...$B$BQuale causa, chiedi? A tempo debito, giovane. Lo saprai... a tempo debito.",
  en_title = "Speak with Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1861] = {
  title = "Lago Riflesso",
  desc = "Questo mondo è stato vittima di immense lotte mistiche, che hanno strappato le correnti magiche a canali un tempo stabili. Facciamo fatica a capire quali effetti abbiano causato questi cambiamenti, e alcuni di noi temono il peggio!$B$BMa te ne parlerò meglio più avanti. Per ora ci serve che tu raccolga informazioni.$B$BEcco, prendi questa fiaschetta. Va' ai piedi della cascata del Lago Riflesso, a sud-ovest delle porte di Stormwind, e preleva un campione dell'acqua. Riportamelo, così potrò analizzarlo per vedere se contiene tracce di corruzione magica.",
  obj = "Porta un campione di Mirror Lake a Jennea Cannon, a Stormwind.",
  progress = "Hai il campione, $N? Il flusso della magia a Stormwind e a Elwynn è stato alterato, e devo sapere se sta filtrando nell'acqua.",
  reward = "Grazie, $N. Analizzerò quest'acqua per scoprire se ha proprietà magiche. Speriamo che non ne abbia, altrimenti potremmo scoprire che chi beve dal Lago Riflesso troppo a lungo ne subisce gli effetti negativi.$B$BEcco, $N. Prendi questo globo o questo bastone come segno di riconoscimento per il tuo servizio. Che possa esserti utile.",
  en_title = "Mirror Lake",
  en_obj = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.",
}
T[1878] = {
  title = "Taglia sugli Otri d'Acqua",
  progress = "Di nuovo qui, $N? Se hai altri cinque otri d'acqua dei Wastewander, ho un pacco dono con sopra il tuo nome!",
  reward = "Eccellente — più otri d'acqua riusciamo a recuperare, più saremo tutti lontani dal disastro! Continua a portarmeli, e non mancherò di ricompensarti per ogni cinque otri d'acqua che mi porti.",
}
T[1879] = {
  title = "Parla con Bink",
  desc = "$N! Bink, la mia collega gnoma di Ironforge, manda a dire che ha un compito da sbrigare e che non lo affiderà a nessuno se non a un mago! Sei tu $Gquel mago:quella maga;, $N?$B$BSe è così, va' a parlare con Bink. Passa le sue giornate nell'Hall of Mysteries, nel Quartiere Mystic di Ironforge.",
  obj = "Parla con Bink, a Ironforge.",
  reward = "Oh, vedo che hai del potenziale, eccome se ce l'hai! Ma per essere un buon mago non basta il potenziale. E se non sei $Gun buon mago:una buona maga;, allora sei $Gun pessimo mago:una pessima maga;. E i pessimi maghi fanno parte del problema, eccome se ne fanno parte!$B$BOps, sto correndo troppo. Cominciamo dall'inizio!",
  en_title = "Speak with Bink",
  en_obj = "Speak with Bink in Ironforge.",
}
T[1880] = {
  title = "Mage-tastic Gizmonitor",
  desc = "Noi maghi non ci limitiamo ad agitare le dita e a fare delle belle scintille! Noi controlliamo la magia, il tessuto fondamentale del nostro mondo! E per farlo servono grande attenzione e determinazione. E conoscenza... tantissima conoscenza!$B$BUno dei miei congegni, il mage-tastic gizmonitor, raccoglie e conserva quella conoscenza in quantità enormi! Ma è andato perduto! Quando siamo fuggiti da Gnomeregan, la nostra casa, l'ho lasciato in una cassa, dentro una delle nostre capanne fuori città, e adesso il posto brulica di gnomi lebbrosi!$B$BTi prego, $N, recupera il mio gizmonitor!",
  obj = "Porta a Bink il suo Mage-tastic Gizmonitor.",
  progress = "Hai trovato il gizmonitor? Devo riaverlo prima che la sua riserva di energia si esaurisca!",
  reward = "Oh, che splendida giornata! Quando ho costruito il gizmonitor non mi rendevo conto di quanto ne sarei diventata dipendente. Adesso posso ricominciare i miei studi!$B$BGrazie, $N! Ed ecco — questi sono stati i miei primi strumenti da maga. Sono un po' graffiati, ma sono ben collaudati. Scegli quello che preferisci — sono sicura che l'uno o l'altro ti tornerà utile.",
  en_title = "Mage-tastic Gizmonitor",
  en_obj = "Bring Bink her Mage-tastic Gizmonitor.",
}
T[1881] = {
  title = "Parla con Anastasia",
  desc = "$N, Anastasia Hartwell ha un compito per qualcuno con il tuo talento. Va' a parlarle nel Magic Quarter dell'Undercity e preparati al tuo primo incarico per i maghi dei Reietti.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "Salve, $N. Hai agito con saggezza rispondendo alla mia chiamata, e ne mostrerai ancora di più se darai ascolto a quello che sto per dirti...",
  en_title = "Speak with Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1882] = {
  title = "La Cascina dei Balnir",
  desc = "Le Plaguelands a est sono un'aberrazione. Ideate dal Re dei Lich, diffondono la loro magia nel suolo, corrompendo e uccidendo tutto ciò che vive. Per quanto le forze distruttive della piaga abbiano un certo fascino, noi maghi dei Reietti riteniamo che sia ingovernabile e che vada tenuta a freno.$B$BMa prima dobbiamo misurare fin dove si è spinta in Tirisfal. Va' alla Cascina dei Balnir, nella parte orientale di Tirisfal. Nel giardino ci sono dei fiori — bocche di leone. Raccoglile e torna qui.",
  obj = "Porta Balnir Snapdragons ad Anastasia Hartwell, nel Mage Quarter dell'Undercity.",
  progress = "Hai le bocche di leone? Quella varietà di fiore è molto sensibile alle energie magiche, e studiando quelle cresciute così vicino alle Plaguelands possiamo capire se la piaga è entrata nelle Tirisfal Glades.",
  reward = "Ah, questo è un bell'esemplare. Lo farò studiare ai nostri speziali, per stabilire fin dove arriva la corruzione delle Plaguelands.$B$BBen fatto, $N. Per i tuoi servigi ti offro una scelta: un globo o un bastone. Qualunque cosa sceglierai, ti sarà molto utile.",
  en_title = "The Balnir Farmstead",
  en_obj = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.",
}
T[1883] = {
  title = "Parla con Un'Thuwa",
  desc = "Un'thuwa, il mago della tribù di Sen'jin Village, avverte una perturbazione nelle correnti magiche di Durotar e chiede aiuto. Parla con Un'thuwa e fa' il possibile per aiutarlo.$B$BFallo, e col tempo ti saranno svelati altri segreti.",
  obj = "Parla con Un'Thuwa.",
  reward = "Salute, $N. Sia lode a te, perché la mia richiesta d'aiuto ha avuto risposta. Speriamo che tu sia all'altezza del compito...",
  en_title = "Speak with Un'thuwa",
  en_obj = "Speak with Un'thuwa.",
}
T[1884] = {
  title = "Cumuli Ju-Ju",
  desc = "Lo stregone Zalazane delle Isole dell'Eco ha sconvolto il normale flusso della magia in Durotar. Ci riesce con dei feticci contaminati, i cumuli ju-ju, che ha piazzato fra le sue capanne sulla principale delle Isole dell'Eco.$B$BQuesti cumuli corrompono la nostra fauna e danno potere agli stregoni e alle creature infernali in agguato negli angoli oscuri di queste terre.$B$BDevi distruggere i cumuli ju-ju, $N, prima che il flusso della magia cambi per sempre.",
  obj = "Distruggi 4 Ju-Ju Heap, poi torna da Un'Thuwa, a Sen'jin Village.",
  progress = "Devi sbrigarti, $N. Distruggi i cumuli ju-ju!",
  reward = "Sento che i cumuli ju-ju di Zalazane sono stati distrutti, e con il tempo e un po' di fortuna il flusso della magia in Durotar tornerà alla normalità.$B$BUna grande impresa hai compiuto per la tua gente, $N. E hai dimostrato il tuo valore a noi maghi dell'Orda.",
  en_title = "Ju-Ju Heaps",
  en_obj = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.",
}
T[1885] = {
  title = "Mennet Carkad",
  desc = "$N? Non proprio ciò che mi aspettavo, visto che Carkad in persona si è interessato a te. Ma l'apparenza inganna, giusto?$B$BIn ogni caso, dovresti andare da lui il prima possibile. Non vuoi sapere che fine hanno fatto gli ultimi che hanno scelto di ignorare la sua convocazione.",
  obj = "Parla con Mennet Carkad nel Rogues' Quarter dell'Undercity.",
  reward = "Mm. Senza dubbio sei $Gvenuto:venuta; qui appena hai sentito parlare della mia convocazione, vero? Naturalmente. Non mi aspetterei niente di meno da chi aspira a diventare Inseguitore della Morte.",
  en_title = "Mennet Carkad",
  en_obj = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1886] = {
  title = "Gli Inseguitori della Morte",
  desc = "Se vuoi unirti agli Inseguitori della Morte, la guardia scelta di Lord Varimathras, dovrai dimostrare il tuo valore.$B$BNon ti mentirò, $N: questo compito potrebbe costarti la vita.$B$BHo alcune faccende di cui occuparmi. Mi servono gli effetti personali di Astor Hadren, un messaggero che fa la spola tra Silverpine e l'Undercity. Come procurarteli, lo lascio decidere a te.$B$BMeglio per te sapere il meno possibile sulla natura di questo affare. Se ci riesci, ti dirò di più.",
  obj = "Procurati Astor's Letter of Introduction e riportala a Mennet Carkad, nel Rogues' Quarter.",
  progress = "Hai buone notizie da riferire?",
  reward = "Ben fatto, $N. Hai superato la prima parte di questa prova. Speriamo che Andron non abbia avuto sentore delle tue attività: così potremo convincerlo che sei proprio $Gil messaggero:la messaggera; che aspetta.",
  en_title = "The Deathstalkers",
  en_obj = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.",
}
T[1898] = {
  title = "Gli Inseguitori della Morte",
  desc = "La lettera di presentazione dovrebbe bastare a convincere Andron che sei $Gil messaggero:la messaggera; che aspettava. Ho già incontrato Andron: non ha abbastanza cervello per essere così sospettoso.$B$BLord Varimathras sospetta che Andron stia aiutando qualche altro gruppo. Vuole sapere di quale organizzazione si tratta, e gliene serve la prova.$B$BVoglio che tu parli con Andron e che ottenga questa informazione. Lo troverai nella sua bottega, vicino all'Apothecarium.",
  obj = "Parla con Andron Gant, nell'Undercity.",
  progress = "Salve. Posso fare qualcosa per te?",
  reward = "Ah, sì, ti stavo aspettando. Non ho dubbi che i nostri comuni conoscenti siano soddisfatti delle informazioni che ho fornito finora, vero?$B$BImmagino sia inutile chiederlo a te: dubito che vogliano gravarti di certe conoscenze. Perché riporre tanta fiducia in chi porta i messaggi, eh?",
  en_title = "The Deathstalkers",
  en_obj = "Speak with Andron Gant in the Undercity.",
}
T[1899] = {
  title = "Gli Inseguitori della Morte",
  desc = "Il registro con le informazioni che cercano i tuoi datori di lavoro è sullo scaffale dietro di me. Consegnalo con i miei saluti, e di' loro che preferirei che mandassero te, se ritengono che valga la pena continuare il nostro accordo.",
  obj = "Porta Andron's Ledger a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Ce l'hai fatta, $N?",
  reward = "Beh, sono certamente più informazioni di quante mi aspettassi di ottenere da Andron. Dammi un momento per esaminarle, prima di affidarti il prossimo compito.",
  en_title = "The Deathstalkers",
  en_obj = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.",
}
T[1918] = {
  title = "L'Elemento Corrotto",
  desc = "L'elementale ucciso ha lasciato un globo d'acqua che brilla intensamente. Il contenuto del globo è, a dir poco, disgustoso. È lecito supporre che ciò che ha corrotto l'acqua del Lago Mystral si trovi con ogni probabilità anche nell'acqua del globo.$B$BNon è proprio chiaro chi possa interessarsi a un ritrovamento simile; forse chi ti aveva mandato al lago, Mastok Wrilehiss all'Avamposto di Splintertree, ha qualche idea.",
  obj = "Porta il Befouled Water Globe a Mastok Wrilehiss all'Avamposto di Splintertree, in Ashenvale.",
  progress = "Sì, cosa ti serve?",
  reward = "Trovi una brutta palla d'acqua e decidi di portarla a me? Chi sono io, il Circolo della Terra o roba del genere?$B$BA dire il vero, mi viene un'idea... forse per questa cosa ti serve davvero il Circolo della Terra. Voglio dire, se serve a sistemare per sempre la situazione al lago, ci sto.$B$BSai chi sono quelli del Circolo della Terra, $N?",
  en_title = "The Befouled Element",
  en_obj = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[1919] = {
  title = "Presentati a Jennea",
  desc = "La tua conoscenza dell'arte cresce, giovane $N. Adesso sei $Gpronto:pronta; a cominciare le tue vere lezioni? Sei $Gpronto:pronta; a prendere il tuo posto nella guerra segreta che combattiamo?$B$BSe è così, parla con Jennea Cannon, nel santuario dei maghi, nel quartiere dei maghi di Stormwind. Ha per te un compito che ti aprirà la prima finestra sul mondo invisibile.",
  obj = "Parla con Jennea Cannon, a Stormwind.",
  reward = "$N, ho una missione per te, qui nel quartiere dei maghi. Ascoltami bene, perché non c'è tempo da perdere.",
  en_title = "Report to Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1920] = {
  title = "Indaga sul Blue Recluse",
  desc = "È stata segnalata una perturbazione alla taverna Blue Recluse, nel Quartiere dei Maghi. Strane creature invisibili ora si aggirano per la taverna, e temo che lì si sia aperta una fenditura di mana.$B$BVoglio che tu indaghi nella taverna e catturi quelle creature. Usa il canto della manifestazione dentro la taverna per renderle visibili, sottomettile e poi usa uno scrigno di contenimento per catturarle. Quando ne avrai abbastanza, torna da me con gli scrigni pieni, quelli vuoti e il canto.",
  obj = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Jennea Cannon. Porta 3 Filled Containment Coffer a Jennea, al Wizard's Sanctum.",
  progress = "Hai catturato le creature, $N? Vanno studiate per capire il motivo del loro arrivo.",
  reward = "Ottimo lavoro! Studierò queste creature e, con impegno e un po' di fortuna, scoprirò come sono sgusciate nel nostro mondo.$B$BIl tuo valore per la società dei maghi cresce, $N.",
  en_title = "Investigate the Blue Recluse",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.",
}
T[1921] = {
  title = "Raccogliere i Materiali",
  desc = "Hai servito bene i tuoi compagni maghi, e ora è tempo che tu indossi la tua veste da $Gmago:maga;. Wynne Larson può confezionartela, ma devi portarle i materiali necessari.$B$BLa veste sarà di linen, che è facile da trovare, ma dovrai anche procurarti delle gemme di fenditura cariche, e l'unico posto noto in cui trovarle è la Miniera Vena d'Argento di Loch Modan: la lega dei minatori nani le ha lasciate lì, in alcune casse.$B$BRaccogli il linen e le gemme e portali a Wynne Larson, ai Larson Clothiers nel Quartiere dei Maghi.",
  obj = "Porta 10 Linen Cloth e le 6 Charged Rift Gem a Wynne Larson, a Stormwind.",
  progress = "Ciao, $N. Jennea mi aveva detto che saresti $Gvenuto:venuta;. Hai qualcosa per me?",
  reward = "Sì, questi sono ottimi pezzi di linen. Ci posso fare una bella veste. E quando ci avrò intessuto le gemme di fenditura, avremo un abito degno di un mago!",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind.",
}
T[1938] = {
  title = "Trattato di Ur sull'Ombra",
  desc = "Molto tempo fa, tre maghi studiavano in questa torre, finché uno di loro cadde preda delle arti oscure. Fu esortato ad abbandonare quella magia malvagia, ma non riuscì a resisterle. E così fu esiliato.$B$BIl nuovo dominio del mago caduto è la torre di Ilgalar, a Redridge, e con sé ha portato un libro potente — il Trattato di Ur sull'Ombra.$B$BNoi maghi di Stormwind vogliamo che quel libro ci venga restituito. Entra nella torre di Ilgalar, trova il tomo nella sua biblioteca e portamelo.",
  obj = "Porta Ur's Treatise on Shadow Magic a High Sorcerer Andromath, a Stormwind.",
  progress = "Hai il libro, $N? I suoi segreti non sono fatti per chi non ha la preparazione necessaria, e scandagliarne le profondità può portare alla rovina e alla distruzione.",
  reward = "Temevo che Morganth avesse nascosto il libro altrove, o che avesse trovato il modo di aprirlo e di leggerne il contenuto.$B$BPer fortuna non l'ha fatto, e i sigilli che abbiamo posto sul Trattato di Ur sull'Ombra reggono ancora.",
  en_title = "Ur's Treatise on Shadow Magic",
  en_obj = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.",
}
T[1939] = {
  title = "Sommo Stregone Andromath",
  desc = "Il Sommo Stregone Andromath desidera parlarti, $N. Si trova in cima al santuario dei maghi, nel quartiere dei maghi di Stormwind.$B$BFaresti bene a parlargli, perché Andromath è uno dei maghi più potenti fra quelli che non sono rinchiusi a Dalaran. Un suo consiglio è davvero un consiglio di alto livello.",
  obj = "Parla con High Sorcerer Andromath.",
  reward = "Salve, $N. Sono lieto di vederti, e spero che tu abbia il tempo di ascoltare le parole di un vecchio...",
  en_title = "High Sorcerer Andromath",
  en_obj = "Speak with High Sorcerer Andromath.",
}
T[1940] = {
  title = "Seta di Ragno Intatta",
  desc = "Il tuo impegno non è mai venuto meno, $N. Penso che forse sia giunto il momento che tu abbia un abito più raffinato, più adatto al tuo rango di $Gmago esperto:maga esperta;. Se raccoglierai i materiali necessari, provvederemo a farti confezionare la veste.$B$BDevi andare a Duskwood e cacciare le recluse carogna. Estrai la loro seta, ma andrà bene solo la seta più fine e immacolata. Quando ne avrai abbastanza, portala a Wynne Larson, qui nel quartiere dei maghi, ai Larson Clothiers. Sarà lei a confezionarti la veste.",
  obj = "Porta 8 Pristine Spider Silk a Wynne Larson, a Stormwind.",
  progress = "Ah, sì. I maghi del Santuario dei Maghi mi avevano detto che saresti $Gvenuto:venuta; a parlarmi. Hai la seta che serve?",
  reward = "Begli esemplari, questi. Mi metto subito al lavoro!",
  en_title = "Pristine Spider Silk",
  en_obj = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.",
}
T[1941] = {
  title = "Veste Manaweave",
  reward = "Ecco la tua veste. È una delle migliori che abbia mai fatto! Indossala con orgoglio, e quando te lo chiederanno... di' che l'hai presa ai Larson Clothiers!",
  en_title = "Manaweave Robe",
}
T[1942] = {
  title = "Abito del Nodo Astrale",
  reward = "Il tuo abito è pronto! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatto un filo più corto per tenermi un avanzo di seta, vero?$B$BSto solo scherzando. Ti starà benissimo, e sarà perfetto sia per l'avventura sia per le cene di gala. Goditelo!",
  en_title = "Astral Knot Garment",
}
T[1943] = {
  title = "Parla con Deino",
  desc = "La maga troll Deino ha bisogno del tuo aiuto, $N. Vive a Orgrimmar, nella Darkbriar Lodge.",
  obj = "Parla con Deino.",
  reward = "Bene, sei $Gvenuto:venuta;. Il mio compito non è facile, ma è vitale per la società dei maghi. Se mi aiuterai, sono sicura che ne varrà la pena.",
  en_title = "Speak with Deino",
  en_obj = "Speak with Deino.",
}
T[1944] = {
  title = "Le Acque di Xavian",
  desc = "La leggendaria città di Xavian è annidata nel cuore della parte orientale di Ashenvale, e i racconti sul suo antico sapere sono ben noti fra i dotti. Si dice che le acque di Xavian abbiano immensi poteri magici.$B$BVorrei un campione di quelle acque, preso alla fonte.$B$BPrendi questa fiasca e va' a Xavian. Raccogli l'acqua ai piedi della sua cascata più alta e torna da me. E fa' attenzione mentre ti muovi in quell'antica città — ora le rovine sono in mano ai satiri, che non gradiscono che i maghi ficchino il naso nei loro affari.",
  obj = "Porta lo Xavian Water Sample a Deino, a Orgrimmar.",
  progress = "Sono lieta che tu sia $Gtornato sano e salvo:tornata sana e salva;, $N. Hai il campione d'acqua? Non vedo l'ora di studiarne le proprietà.",
  reward = "Ah, molto bene. I satiri di Xavian non ti hanno dato troppi problemi, spero?$B$BGrazie, $N. Studierò subito questo campione d'acqua di Xavian.",
  en_title = "Waters of Xavian",
  en_obj = "Bring the Xavian Water Sample to Deino in Orgrimmar.",
}
T[1945] = {
  title = "Sorelle Ridenti",
  desc = "Per i tuoi servigi ho fatto in modo che ti venga confezionata una veste nuova, purché tu riesca a raccogliere i materiali necessari...$B$BPer questa veste devi tornare in Ashenvale a prendere le ciocche di capelli delle sorelle ridenti — driadi che si radunano vicino al Rifugio di Raynewood.$B$BQuando avrai i loro capelli, portali a Kil'hala, un sarto troll al Crossroads, nelle Barrens. Ti starà aspettando, e sarà lui a confezionarti la veste.",
  obj = "Porta 12 Laughing Sister's Hair a Kil'hala, al Crossroads.",
  progress = "Salve, $N. Deino mi ha detto che saresti $Gvenuto:venuta; e che mi avresti portato i capelli delle sorelle ridenti. Ce li hai?",
  reward = "Ah, con questi capelli si tesserà una bella veste, $N. Peccato che le sorelle ridenti siano dovute morire per separarsene, anche se dubito che li avrebbero mai dati di loro spontanea volontà.$B$BUn peccato, ma da poco.",
  en_title = "Laughing Sisters",
  en_obj = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.",
}
T[1946] = {
  title = "Indumento di Pizzo del Nether",
  reward = "Ecco il tuo pizzo del Nether, $N. È comodo e resistente, e racchiude la magia dei capelli delle sorelle ridenti.$B$BGoditelo e, se ti soddisfa, per favore fallo sapere a Deino. È una maga con cui ci tengo a restare in buoni rapporti...",
  en_title = "Nether-lace Garment",
}
T[1947] = {
  title = "Viaggio nella Palude",
  desc = "Ora è il momento di guadagnarti la tua bacchetta da $Gmago:maga;. Per cominciare questa impresa, parla con Tabetha, l'eremita umana, nel Dustwallow Marsh. Troverai la sua capanna nel cuore della palude, a ovest di Theramore.$B$BParla con lei, perché il suo sapere è vasto. Troverai la casupola di Tabetha a ovest di Theramore, appena a nord delle Rovine degli Stonemaul.",
  obj = "Parla con Tabetha.",
  reward = "Silenzio! Sono in un momento delicato e non devo essere disturbata!$B$BUn momento...",
  en_title = "Journey to the Marsh",
  en_obj = "Speak with Tabetha.",
}
T[1948] = {
  title = "Oggetti di Potere",
  desc = "Costruire la bacchetta di un mago non è facile. Servono sostanze rare, e bisogna creare un recipiente capace di contenere grandi quantità di energia magica. Devi raccogliere queste cose e portarmele.$B$BSu questa pergamena ho scritto ciò che ti serve e come procurartelo. Portami esattamente quello che c'è nell'elenco, e segui alla lettera le mie istruzioni scritte, perché se non lo farai, quando creeremo la tua bacchetta le cose potrebbero andare... male.",
  obj = "Porta 1 Jade e il Bolt Charged Bramble a Tabetha, nel Dustwallow Marsh.",
  progress = "Ciao, $N. Hai gli oggetti che mi servono?",
  reward = "Aha! Hai preso la giada e hai preparato il rovo! Ben fatto!$B$BÈ fumo quello che ti vedo uscire dalle orecchie? Forse ti sei $Gavvicinato:avvicinata; troppo quando il fulmine ha colpito i bastoncini del totem, ma non preoccuparti. Essere colpiti da un fulmine porta fortuna!",
  en_title = "Items of Power",
  en_obj = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.",
}
T[1949] = {
  title = "Segreti Nascosti",
  desc = "Per fare la tua bacchetta devo leggere alcuni passi fondamentali di un certo libro. Si intitola Rituali del Potere, e l'ha scritto Magus Tirth.$B$BNon ho una copia del suo libro, e nessuna delle grandi biblioteche del mondo lo possiede. Quindi devi parlare con Tirth e fartelo dare da lui.$B$BBuona fortuna. Un tempo Tirth era un grande mago e studioso, ma ora passa il tempo alle corse degli gnomi e dei goblin nelle Shimmering Flats, a bere e a scommettere.",
  obj = "Parla con Magus Tirth, nelle Shimmering Flats.",
  reward = "Cosa? Parla più forte! Queste vecchie orecchie non sono più buone come una volta.$B$BBeh, spero che tu sia qui con un boccale di birra appena spillata o con qualche soffiata sulla prossima corsa! Altrimenti faresti meglio a tirare dritto... perché ho una bacchetta di metamorfosi con sopra scritto il tuo nome!",
  en_title = "Hidden Secrets",
  en_obj = "Speak with Magus Tirth in the Shimmering Flats.",
}
T[1950] = {
  title = "A Caccia di Notizie",
  desc = "Posso aiutarti con il libro, ma prima devi aiutare me!$B$BIl tomo che cerchi è nel mio forziere chiuso con la magia. Per aprirlo bisogna pronunciare una frase speciale, e io non me la ricordo! Di solito è il mio assistente ad aiutarmi a ricordare queste cose, ma non si trova da nessuna parte.$B$BSe vuoi il mio libro, allora trova il mio apprendista! Chiedi in giro vicino alla pista delle corse — con un po' di fortuna, qualcuno l'avrà visto. Trascinalo qui, o almeno fatti dire da lui la mia frase magica, così possiamo aprire il forziere!",
  obj = "Trova la frase che apre il forziere di Tirth, poi torna da Tirth.",
  progress = "Cosa aspetti? Mi serve la mia frase magica!",
  reward = "Ah, ora mi ricordo...$B$BMi ero dimenticato di quella piccola maledizione che ho lanciato su Johnson. Non ricordo perché l'ho fatto, ma di sicuro se l'era meritata, quel piccolo ingrato!",
  en_title = "Get the Scoop",
  en_obj = "Find the phrase to Tirth's strongbox, then return to Tirth.",
}
T[1951] = {
  title = "Rituali del Potere",
  desc = "Mm... ora che ci penso, il libro non ce l'ho! Vedi, avevo dei debiti di gioco, e per saldarli ho venduto l'ultima copia di Rituali del Potere a un membro del clero...$B$BUn membro della Scarlet Brotherhood. Deve averlo portato nella loro biblioteca, allo Scarlet Monastery nelle Tirisfal Glades!$B$BSe vuoi quel libro, dovrai andare al monastero a cercarlo. E scusa per tutto il disturbo. Di questi tempi non sono più me stesso...",
  obj = "Porta il libro Rituals of Power a Tabetha, nel Dustwallow Marsh.",
  progress = "Salve, $N. Hai trovato il libro Rituali del Potere?",
  reward = "È questo! È proprio quello che mi serve per preparare il rituale che creerà la tua bacchetta! Spero che trovarlo non ti abbia dato troppo disturbo...",
  en_title = "Rituals of Power",
  en_obj = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.",
}
T[1952] = {
  title = "Bacchetta da Mago",
  desc = "Ora vado a fare le bacchette.",
  obj = "Parla con Tabetha dopo il suo rituale.",
  reward = "Ecco le bacchette che ho fatto. Scegli quella che preferisci!",
  en_title = "Mage's Wand",
  en_obj = "Speak with Tabetha after her ritual.",
}
T[1953] = {
  title = "Ritorno alla Palude",
  desc = "È ora, $N, che tu parli con Tabetha... l'eremita di Dustwallow Marsh. Ti insegnerà a creare un potente strumento da mago.$B$BLa baracca di Tabetha si trova nel cuore di Dustwallow Marsh, a ovest di Theramore.",
  obj = "Parla con Tabetha.",
  reward = "Ah, sì. Sei qui per un globo o un bastone, $N? Molto bene. Ti aiuterò a costruirlo.$B$BMa ti avverto — il procedimento è pericoloso e potrebbe voler dire la tua morte.$B$BO la mia morte. Di sicuro la morte di qualcuno...$B$BMa speriamo che sia la morte di qualcun altro, eh?",
}
T[1954] = {
  title = "Il Globo Infernale",
  desc = "Il primo passo è procurarsi un globo dotato di potere. Gli stregoni del Burning Blade hanno dei bei globi, di ottima qualità... peccato che ci abbiano vincolato dentro dei demoni! Ma a questo possiamo rimediare, sì che possiamo.$B$BVa' a Desolace e strappa un globo infernale a un evocatore del Burning Blade. Gli evocatori li trovi alla Congrega di Mannoroc.$B$BQuando avrai il globo, torna da me.",
  obj = "Porta un Infernal Orb a Tabetha, a Dustwallow Marsh.",
  progress = "Hai un globo infernale, $N?",
  reward = "Oh, questo sì che è bello! No, non intendo \"bello\" come è bello un succo fresco in una giornata calda.$B$BAnzi, ora che ci penso è proprio NON bello. Non il succo. Il globo!$B$BConcentrati, $N! Ci servi $Gconcentrato:concentrata;, se mai vogliamo portare a termine il nostro compito!",
}
T[1955] = {
  title = "L'Esorcismo",
  desc = "Ora che abbiamo il globo di un evocatore, dobbiamo esorcizzare il demone che c'è dentro. Quello posso farlo io. È la parte facile.$B$BSei tu che hai il lavoro difficile. Sei tu che devi uccidere il demone una volta uscito.$B$BE dovrai fare in fretta. Se ci metti troppo, salterà di nuovo dentro il globo e ci toccherà ricominciare da capo!$B$BQuindi preparati. Tieni pronti i tuoi incantesimi più potenti e le pozioni a portata di mano, e va' a chiamare un amico, se ne hai uno. Perché non sarà un bello spettacolo.",
  obj = "Uccidi il Demon of the Orb, poi parla con Tabetha.",
  progress = "Dovrai uccidere quel demone per togliere la sua corruzione dal globo, $N.",
  reward = "Ben fatto, $N! Hai dato a quel demone una lezione che non dimenticherà tanto presto.$B$BCi penserà due volte prima di tornare a ficcare il suo brutto muso in questo mondo, in cerca $Gdello stupido:della stupida; mortale che l'ha battuto. Probabilmente con degli amici, stavolta. Amici grossi e squamosi che non chiederebbero di meglio che farti a pezzettini di $R.$B$BNon ti ho spaventato, vero...$N?",
}
T[1956] = {
  title = "Potere a Uldaman",
  desc = "Ora che il demone è stato rimosso, dobbiamo procurarci una sorgente di energia. Purtroppo le sorgenti di energia migliori di solito sono le più antiche e le più difficili da ottenere. Bello come al destino ogni tanto piaccia metterti i bastoni fra le ruote, vero?$B$BPerciò dovrai andare a Uldaman e sconfiggere la sentinella di ossidiana che c'è lì. È grossa, è tosta, e la sua sorgente di energia non scherza!$B$BTi auguro tutta la fortuna del mondo, $N. E se poi la fortuna non l'avrai, be'... è stato bello conoscerti.",
  obj = "Recupera un'Obsidian Power Source e portala a Tabetha, a Dustwallow Marsh.",
  progress = "Sei $Gstato:stata; a Uldaman, $N? Hai sconfitto la sentinella di ossidiana?",
  reward = "Ce l'hai fatta? Ben fatto!$B$BStavo chiacchierando con alcuni miei colleghi e, quando è saltato fuori il tuo nome, hanno detto, \"Lo sai che $N lavora proprio bene sotto pressione!\"$B$BMa quando ho raccontato che ti avevo mandato a Uldaman contro la sentinella di ossidiana, mi hanno detto che ero pazza! Hanno detto, \"Tabetha, sei pazza! È impossibile che $N tenga testa a quella sentinella!\"$B$BE io ho detto, \"Vedremo\", e allora loro hanno detto \"Già, vedremo...\"$B$BBe', gliel'abbiamo fatta vedere, eh!",
}
T[1957] = {
  title = "Eruzioni di Mana",
  desc = "Abbiamo quasi finito, ma quest'ultimo passo è il più pericoloso, $N.$B$BHo il globo vuoto dell'evocatore e sono pronta a infondergli potere. Lo faremo imbrigliando l'energia di una fenditura di mana. Lancerò un incantesimo che aprirà per poco una fenditura, da cui si riverseranno fuori delle creature, le eruzioni di mana. Tu devi sconfiggere le eruzioni di mana, così il loro potere si libererà e io lo raccoglierò.$B$BUccidi abbastanza eruzioni di mana prima che la fenditura si chiuda e metterò nel tuo globo tutta l'energia raccolta.",
  obj = "Uccidi 12 Mana Surges entro il tempo concesso.",
  progress = "Non hai ucciso il numero richiesto di eruzioni di mana, $N.",
  reward = "Ce l'hai fatta! Non ho dubitato di te nemmeno per un secondo! Ok, forse giusto per un secondo, o due... ma in sostanza non ho avuto grandi dubbi.$B$BGiuro.",
}
T[1958] = {
  title = "Potere Celestiale",
  reward = "Dovresti essere $Gfiero:fiera; di te, $N. Molti maghi sono caduti contro le creature che hai affrontato.$B$BIl Globo Celestiale è pronto. Oppure, se preferisci, posso montarlo in cima a un bastone. Decidi tu. Io preferirei il globo, ma chi sono io per giudicare?",
}
T[1959] = {
  title = "Presentati ad Anastasia",
  desc = "I maghi dell'Undercity hanno notato una perturbazione magica all'interno della città, e hanno mandato a chiamare i maghi dell'Orda perché indaghino.$B$BAnastasia Hartwell può dirti di più. Va' a parlarle nel Quartiere della Magia dell'Undercity.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "È vero. Nella nostra città è stata rilevata una perturbazione magica. Non siamo ancora certi della sua origine, né se sia maligna o benigna. Prima dobbiamo raccogliere altre informazioni...$B$BE questo, $N, ci porta al tuo compito.",
  en_title = "Report to Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1960] = {
  title = "Indaga sulla Bottega dell'Alchimista",
  desc = "La bottega d'alchimia di Algernon, nell'Apothecarium, è il centro di una strana perturbazione. Creature invisibili, fatte solo di magia, si aggirano per la bottega — ci dev'essere un motivo, e dobbiamo scoprirlo!$B$BIndaga sulla perturbazione e cattura quelle creature. Prendi una cassa di scrigni e una pergamena, qui dietro di me. Usa la pergamena nella bottega per rendere visibili le creature, sottomettile con i tuoi incantesimi, poi getta a terra uno scrigno per catturarle. Torna con gli scrigni pieni, quelli vuoti e il canto.",
  obj = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Anastasia Hartwell. Porta 3 Filled Containment Coffer, la Chest of Containment Coffers e la Cantation of Manifestation ad Anastasia, nell'Undercity.",
  progress = "Hai indagato sulla perturbazione, $N? Hai catturato le creature?",
  reward = "Molto bene, $N. Le creature chiuse in questi scrigni di contenimento saranno studiate dalle nostre menti migliori, e il motivo della loro presenza nell'Undercity verrà chiarito.$B$BSe la loro comparsa è causata da una fenditura nel flusso naturale della magia, dobbiamo stabilire se la fenditura è stata casuale. Se non lo è stata, e si tratta invece di un attacco da parte di qualche forza magica, allora dobbiamo prepararci a perturbazioni future, e più gravi.",
  en_title = "Investigate the Alchemist Shop",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.",
}
T[1961] = {
  title = "Raccogliere i Materiali",
  desc = "È tempo che tu indossi la tua prima veste da $Gmago:maga;, $N. È un segno del tuo rango e una prova del tuo valore.$B$BPer ottenerla, devi prendere le gemme di mana ai maghi di Dalaran che stanno a Silverpine. Le loro convinzioni sono simili alle nostre, quindi ucciderli è un po' sgradevole; ma se non hanno la forza di resisterci, non meritano di vivere.$B$BPorta le gemme e una scorta di linen a Josef Gregorian, nella sartoria del Quartiere della Magia.",
  obj = "Porta 10 Linen Cloth e 6 Dalaran Mana Gem a Josef Gregorian.",
  progress = "Anastasia mi ha detto che saresti $Gvenuto:venuta; da me, e sono pronto a confezionare la tua veste. Hai le gemme e il linen?",
  reward = "È un materiale molto buono, e anche se non ho il talento per giudicare la qualità di queste gemme di mana, sapremo presto se hanno il potere necessario per creare delle vesti spellfire...",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian.",
}
T[1962] = {
  title = "Vesti Spellfire",
  reward = "Ecco la tua veste, $N. Indossala degnamente.",
  en_title = "Spellfire Robes",
}
T[1963] = {
  title = "La Shattered Hand",
  desc = "Il Capoguerra usa metodi troppo sottili. È restio a scatenare la potenza dell'Orda. Un tempo eravamo più forti, tutti potenti conquistatori. Dobbiamo riconquistare quell'orgoglio, e la Shattered Hand lo farà.$B$BCostruiamo la nostra forza nell'ombra e colpiamo chi resta scoperto, abbattendo i nostri nemici in segreto. C'è un compito che devi portare a termine per me, per dimostrare il tuo valore.$B$BIl troll Tazan commercia con i pirati vicino a Ratchet. Ha delle informazioni che devo avere. Uccidilo e portami la sua borsa.",
  obj = "Uccidi Tazan e porta Tazan's Satchel a Therzok, nella Cleft of Shadow, a Orgrimmar.",
  progress = "Solo uno sciocco crede che una carica con l'ascia in pugno sia più pericolosa di un coltello nel buio.",
  reward = "Mm, anche se mi fa piacere sapere che Tazan non è più tra noi, una borsa chiusa a chiave non ci serve a niente. Ci servono le informazioni che contiene.$B$BQuesta dovrebbe essere una seconda prova degna per chi desidera unirsi alla Shattered Hand.",
  en_title = "The Shattered Hand",
  en_obj = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1978] = {
  title = "Gli Inseguitori della Morte",
  desc = "Il Syndicate? Non l'avrei mai sospettato. Sembra che i nobili di Alterac siano caduti molto in basso negli anni dopo il loro tradimento.$B$BLord Varimathras sarà lieto di saperlo, e visto che sei $Gstato:stata; così determinante per questa scoperta, sarebbe giusto che fossi tu a consegnarglielo.$B$BAh, e come potevo dimenticarlo?$B$B$GBenvenuto:Benvenuta; tra gli Inseguitori della Morte.",
  obj = "Consegna Andron's Ledger a Varimathras nella Hall of the Dark Lady, nell'Undercity.",
  progress = "Sì?",
  reward = "Mmm, questo è interessante. Gli Inseguitori della Morte hanno svolto il loro compito in modo egregio, scovando tutto questo.$B$BA quanto mi risulta, anche tu meriti un encomio per il tuo operato. Spero che per te diventi un'abitudine, $N: ai miei Inseguitori della Morte fa sempre comodo $Gun uomo:una donna; in gamba.",
  en_title = "The Deathstalkers",
  en_obj = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.",
}
T[1998] = {
  title = "Fenwick Thatros",
  desc = "Lord Varimathras mi ha appena mandato un messaggio su una minaccia per i Reietti che va eliminata immediatamente. Si chiama Fenwick Thatros, e Lord Varimathras crede che sia uno dei capi dei non morti che hanno messo radici nella Silverpine Forest.$B$BIl tuo nome mi è venuto subito in mente, $N. Ho abbastanza fiducia nelle tue capacità da essere certo che porterai a termine questa missione alla perfezione.$B$BGli ultimi rapporti degli Inseguitori della Morte a Silverpine indicano che Thatros si trova vicino al molo in rovina sul Lordamere.",
  obj = "Uccidi Fenwick Thatros e porta la sua testa a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Ho riposto in te la massima fiducia per questo servizio a Lord Varimathras.",
  reward = "Hai fatto un buon lavoro, $N. Mi viene in mente che hai reso molti servigi agli Inseguitori della Morte, dimostrando il tuo valore, e che forse è ora di approfondire il tuo addestramento nelle arti dell'ombra.",
  en_title = "Fenwick Thatros",
  en_obj = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1999] = {
  title = "Gli Attrezzi del Mestiere",
  desc = "I maghi del Kirin Tor ad Ambermill hanno messo al sicuro documenti importanti sulla situazione attuale di Dalaran. Lo sappiamo dalla confessione di uno dei nostri prigionieri. Lord Varimathras ha affidato agli Inseguitori della Morte il compito di recuperarli.$B$BQuesto compito spetta a te, $N. Però ti serviranno un po' di attrezzatura e la capacità di scassinare le serrature. Parla con Estelle Gendry, la nostra fornitrice, e chiedile un set di attrezzi prima di partire.",
  obj = "Trova il Dalaran Status Report e riportalo a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Hai trovato i documenti, $N?",
  reward = "Molto bene, $N! Hai imparato bene la raffinata arte dello scasso, e più in fretta di quanto potessi mai aspettarmi.$B$BVedo che ho fatto bene a fidarmi di te. Credimi, $Gragazzo:ragazza;, prevedo che farai molta strada in questo mestiere.",
  en_title = "Tools of the Trade",
  en_obj = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[2040] = {
  title = "Assalto Sotterraneo",
  desc = "Gnomeregan è caduta sotto il controllo di quegli infami trogg! La situazione è grave, ma forse puoi aiutarci, $N.$B$BNelle profondità delle Deadmines c'è un segatronchi goblin ancora funzionante. Trova quel segatronchi e riporta indietro l'alimentatore intatto. Con l'alimentatore del segatronchi possiamo dare ai nostri escavatori girotrivellomatici la potenza che serve per sfondare le barriere di roccia sotterranee di Gnomeregan, aprendo la strada a un assalto gnomesco!",
  obj = "Recupera lo Gnoam Sprecklesprocket dalle Deadmines e riportalo a Shoni the Shilent, a Stormwind.",
  progress = "Hai trovato lo Gnoam Sprecklesprocket, $N?",
  reward = "Ben fatto, $N. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!",
  en_title = "Underground Assault",
  en_obj = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",
}
T[2178] = {
  title = "Vita Facile con gli Zampalunga",
  desc = "Senti questo profumo delizioso? È la mia ricetta segreta, $N — stufato di zampalunga appena fatto. Delizioso!$B$BTi piacerebbe imparare la ricetta?$B$BPrima di insegnartela, dovrai dimostrare di saper tenere testa a quelle bestie.$B$BOra, non mi aspetto che tu vada ad addomesticarne una e torni qui in groppa, ma se riesci a ucciderne qualcuna e a riportarmi un po' della loro carne succulenta, forse riuscirai a convincermi a svelarti i segreti dello stufato di zampalunga.",
  obj = "Riporta 5 Strider Meat ad Alanndarian Nightsong, ad Auberdine.",
  progress = "La pentola è vuota e ho fame! Perché ci metti così tanto?",
  reward = "Fantastico! Assaggialo e dimmi cosa ne pensi, $N!",
  en_title = "Easy Strider Living",
  en_obj = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",
}
T[2198] = {
  title = "La Collana Infranta",
  desc = "Hai trovato una collana annerita, anche se la patina nasconde una lavorazione elaborata e magica. La collana è rotta: al castone sembrano mancare tre gemme. Sul retro della collana c'è l'impronta sbiadita del sigillo cittadino di Ironforge. Sotto il sigillo ci sono tre minuscole lettere incise: \"TdK\".$B$BSe c'è qualcosa da ricavare da questa collana, dovrai scoprirne le origini. Forse il sigillo e le iniziali sono un punto di partenza...",
  obj = "Cerca chi ha creato la Shattered Necklace, per scoprire quanto potrebbe valere.",
  progress = "Hai sbagliato gnomo, $Gamico:amica;! Io non c'ero! Non puoi dimostrare niente!$B$BAspetta un attimo... chi sei? Ma che... dove l'hai trovata questa collana?",
  reward = "Sì... sono io il gioielliere che ha fatto questa collana. E non sono nemmeno uno che dà informazioni gratis. Le informazioni non sono mai gratis, $Gamico:amica;. Se devo aiutarti, prima devi aiutare ME.",
  en_title = "The Shattered Necklace",
  en_obj = "Search for the original creator of the shattered necklace to learn of its potential value.",
}
T[2199] = {
  title = "Informazioni a Pagamento",
  desc = "Sono un gioielliere di grande fama, qui a Ironforge! Be', di fama passata, almeno... Sono caduto in disgrazia per colpa degli imbrogli di un concorrente! In questo mestiere una cattiva reputazione vuol dire la rovina. Il risultato è che mi ritrovo senza un soldo, con un buon nome che al momento è infangato.$B$BVoglio che tu mi procuri cinque barre d'argento per completare un ordine che ho ricevuto, il primo da quella che sembra un'eternità.$B$BPortami quelle cinque barre d'argento e risponderò alle tue domande sulla collana.",
  obj = "Porta cinque Silver Bar a Talvash del Kissel, a Ironforge.",
  progress = "Hai le cinque barre d'argento che ti ho chiesto? Ti racconterò la triste storia delle mie sventure legate alla collana che hai adesso... ma solo dopo aver avuto quelle barre! Ti prego, dai una mano a uno gnomo, eh?",
  reward = "Per me sei a posto; non m'importa cosa dicono tutti gli altri... Scherzo, scherzo! Davvero, grazie, $Gamico mio:amica mia;.$B$BAllora, la collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che la aiutano a legare a sé il potere magico. L'ho fatta tempo fa per un paladino. Si era dato da solo la missione di ripulire dalla \"corruzione malvagia\" un sito di scavo nelle Badlands chiamato Uldaman.$B$BBe'... quel paladino è morto a Uldaman, e quello è stato solo l'inizio delle mie disgrazie.",
  en_title = "Lore for a Price",
  en_obj = "Bring five silver bars to Talvash del Kissel in Ironforge.",
}
T[2200] = {
  title = "Ritorno a Uldaman",
  desc = "Un mio concorrente ha messo in giro la voce che la mia collana avesse maledetto il paladino. Inutile dire che nessuno vuole comprare oggetti maledetti da un gioielliere.$B$B$N, ti propongo un accordo: trova le gemme e io rimetterò insieme la collana, a patto che tu vada in giro a dire che io NON faccio oggetti maledetti!$B$BProva a cercare indizi a Uldaman; magari vedi se il corpo del paladino è laggiù, visto che, per quanto ne sappiamo, è stato lui l'ultimo ad averla! Quando trovi le gemme, usa questa: ti permetterà di contattarmi qui a Ironforge.",
  obj = "Cerca a Uldaman indizi su dove si trova ora la collana di Talvash. Il paladino ucciso di cui ha parlato è l'ultimo che l'ha avuta.",
  reward = "Resti di un paladino: leggendo il diario scopri che, dopo molti sforzi, il paladino aveva individuato dove si trovano tutte e tre le gemme mancanti:$B$BI nani Shadowforge hanno nascosto il rubino nella loro zona barricata, mentre combattevano contro i Trogg per il controllo di Uldaman.$B$BI trogg hanno nascosto il topazio in un'urna vicino ad alcuni abitanti insoliti di Uldaman: dei nani dell'Alleanza!$B$BInfine, l'anziano dei trogg in persona ha preso lo zaffiro per sé.",
  en_title = "Back to Uldaman",
  en_obj = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who had it last.",
}
T[2201] = {
  title = "Trova le Gemme",
  desc = "Il diario del paladino ha fornito forse gli unici indizi che Uldaman potrà dare su dove si trovano le gemme della collana. Se quello che ha scritto il paladino è ancora esatto, bisognerà occuparsi dei nani Shadowforge e dei trogg che si contendono il controllo del sito di scavo.$B$BCon queste informazioni in mano, la ricerca delle gemme comincia sul serio. Quando avrai recuperato tutte le gemme, dovrai avvisare Talvash, a Ironforge, con la Fiala della Chiaroveggenza, come da sue istruzioni.",
  obj = "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta recuperati, contatta Talvash del Kissel a distanza usando la Phial of Scrying che ti ha dato.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona barricata degli Shadowforge.$B* Il topazio è stato nascosto in un'urna in una delle zone dei Trogg, vicino ad alcuni nani dell'Alleanza.$B$B* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.",
  progress = "Dalle acque della coppa della chiaroveggenza prende forma l'immagine di Talvash.$B$B\"Wow, sei ancora $Gvivo:viva;! Sei $Griuscito:riuscita; a trovare le gemme? Sei davvero tu $Gil salvatore:la salvatrice; della mia reputazione, come speravo? Ti prego, dimmi che non hai sprecato una carica della fiala solo per chiacchierare: quelle cose NON costano poco, e sono già in gravi difficoltà economiche.",
  reward = "Sì, sono proprio le tre gemme. Ben fatto! Purtroppo il tuo lavoro non è ancora del tutto finito.$B$BNo, non sto cercando di fregarti, $C $Gsciocco:sciocca;. Si tratta di fare gioielli magici: gioielli della qualità di Talvash del Kissel! Serve una fonte di energia potente per dargli un po' di grinta. Be', quella collana di grinta da dare non ne ha più.",
  en_title = "Find the Gems",
  en_obj = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2202] = {
  title = "Reagenti da Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, i cappelli di fungo magenta. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.$B$BTrova i grappoli di cappelli magenta e portamene una dozzina. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.$B$BFallo per me, e ti preparerò al volo una dose di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Cap a Jarkal Mossmeld, a Kargath.",
  progress = "Ti sei $Gprocurato:procurata; i cappelli di fungo magenta che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!",
  reward = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! Studiare questi cappelli sarà interessante, puoi scommetterci.$B$BE ora, come promesso, goditi un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...$B$BSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",
}
T[2203] = {
  title = "Reagenti dalle Badlands II",
  desc = "Mi sei $Gstato:stata; di grande aiuto, $C. Vorrei ricompensarti con la ricetta stessa dell'intruglio che ti ho dato prima... ma devo chiederti un compito piuttosto pericoloso. Ascolta la mia richiesta.$B$BIn questa cassetta ci sono tre recipienti taumaturgici vuoti; sono intrisi di un'aura di sintonia che assorbirà il sangue di un drago guardiano infuocato. Usarne uno sulla bestia la farà infuriare parecchio, quindi sei $Gavvisato:avvisata;. Quando li avrai riempiti tutti e tre, portameli.$B$BFallo, e la ricetta sarà tua.",
  obj = "Usa gli Empty Thaumaturgy Vessel sugli Scorched Guardian delle Badlands. Quando li avrai riempiti, portali a Jarkal Mossmeld, a Kargath.",
  progress = "Hai usato i recipienti per procurarmi il sangue di drago guardiano infuocato che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ristoratore aspetta solo il tuo successo. Rischio e ricompensa, $Gamico mio:amica mia;... rischio e ricompensa...",
  reward = "Da alchimista ad alchimista, ti rendo omaggio. Ecco, prendi questa ricetta e imparala a memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni.",
  en_title = "Badlands Reagent Run II",
  en_obj = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.",
}
T[2204] = {
  title = "Restaurare la Collana",
  desc = "Dovrai trovare un po' di \"grinta\" per la collana, e Uldaman è probabilmente il posto migliore dove cercarla, in effetti. Immagino che là dentro ci siano un sacco di costrutti in giro, eh? Be', fai fuori il costrutto più grosso e più cattivo di quel posto e prendi la sua fonte di energia! Sono quasi sicuro di poterla fondere con la collana.$B$BSenza quella fonte di energia sarà impossibile riparare la collana. Torna da me qui a Ironforge quando l'avrai, e ti sistemeremo tutto!",
  obj = "Procurati una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman, e consegnala a Talvash del Kissel, a Ironforge.",
  progress = "Non ti sei nemmeno $Gfermato:fermata; a darti una ripulita dopo aver lasciato Uldaman, eh? Sei $Gvenuto:venuta; dritto qui, alla faccia degli odori di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.$B$BHai la fonte di energia per la collana?",
  reward = "Accidenti: sono proprio contento di vedere te e questa fonte di energia $Gtutti interi:tutte intere;. Mi ci vorrà un momento per fondere magicamente la fonte di energia con la collana, ora che le gemme sono tornate al loro posto. Una volta finito, però, la collana sarà tua!$B$BSei $Gemozionato:emozionata;, vero? $GTutto:Tutta; un fremito per l'attesa? Ora, dove ho messo quel focus per incantesimi...",
  en_title = "Restoring the Necklace",
  en_obj = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",
}
T[2205] = {
  title = "Cerca lo SI: 7",
  desc = "Il distintivo? Oh, non è niente, $Gpivello:pivella; — niente alla tua portata, in ogni caso. A giudicare dal tuo aspetto, direi che Mathias probabilmente ti scambierà per $Gil ragazzo:la ragazza; che consegna il formaggio invece che per $Gun vero ladro:una vera ladra;. Comunque sia, mi è stato affidato un lavoro e ho promesso di portarlo a termine.$B$BA proposito di consegne, porta questo pacco a Mathias: forse ti darà un incarico o due.$B$BDatti da fare.",
  obj = "Consegna il pacco di Keryn Sylvius a Master Mathias Shaw, agli Stormwind Barracks.",
  progress = "Posso aiutarti, $C?",
  reward = "Mi hai trovato — e a guardarti, direi che la corsa e la ricerca che ne è seguita potrebbero averti messo a dura prova, sia nella mente sia nel corpo.$B$BVuoi che Renzik ti mostri la strada per una locanda, o sei $Gpronto:pronta; per un po' di lavoro?",
  en_title = "Seek out SI: 7",
  en_obj = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",
}
T[2206] = {
  title = "Arraffa e Scappa",
  desc = "I nostri agenti sul campo riferiscono un'intensa attività dei Defias a sud di Goldshire. Dai rapporti risulta che i Defias hanno preso il controllo del Molo di Jerod e ora lo usano per contrabbandare grandi quantità di merce illegale da Redridge a Westfall.$B$BHo bisogno che tu ti infiltri nella casa del molo e mi porti quel calendario delle spedizioni, $N. Probabilmente lo troverai sepolto in fondo alle tasche del Capo del Molo.$B$B...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.",
  obj = "Trova il Defias Dockmaster e recupera lo Shipping Schedule per Master Mathias Shaw.",
  progress = "La tua vita mortale si consuma a ogni istante che sprechi a gironzolare per la caserma, $C.",
  reward = "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che forse ha la stoffa per diventare $Gun vero ladro:una vera ladra;. Prendi questa lama, $N. Verrà il giorno in cui sarai $Gchiamato:chiamata; di nuovo a servire lo SI:7. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.$B$BNon ci vedrai arrivare, ma lo sentirai, quando arriveremo...",
  en_title = "Snatch and Grab",
  en_obj = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.$B",
}
T[2218] = {
  title = "La Via della Salvezza",
  desc = "Un'altra anima perduta in cerca di una guida, eh? Immagino che tu voglia trovare uno scopo — il tuo scopo. L'ho visto mille volte: $Gun altro eroe:un'altra eroina; in cerca di lavoro.$B$BBeh, oggi è il tuo giorno fortunato, $Gamico:amica;. Hogral ha la cura per il tuo male.$B$BEcco cosa devi fare: prendi questa strada fino a Ironforge e raggiungi la Caverna Sperduta. Una volta lì, trova la gilda dei ladri e parla con Hulfdan Blackbeard. Sarà lui a metterti sulla via della salvezza.",
  obj = "Parla con Hulfdan Blackbeard, a Ironforge.",
  reward = "Allora ti credi $Gun furfante:una furfante; coi fiocchi? $GDestinato:Destinata; a essere $Guno:una; dei pochi eletti di Blackbeard — $Gun ufficiale:un'ufficiale; dell'Hidden Circle?$B$BSolo un mascalzone buono a nulla può avere un'idea così alta di sé.$B$BÈ proprio quello che ci serve a noi! $GBenvenuto:Benvenuta; a bordo, $N!",
  en_title = "Road to Salvation",
  en_obj = "Speak with Hulfdan Blackbeard in Ironforge.",
}
T[2238] = {
  title = "Semplici Sotterfugi",
  desc = "Vedi, il Re sta raschiando la cava fino all'osso per estrarre minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.$B$BL'Hidden Circle ha dei valori, $N. Diamo valore a ciò che ha valore. Capisci?$B$BOra, a noi ci pare che il Re dovrebbe spartire un po' di quel bottino, ma non vogliamo che il vecchio 'Barbapuzza' sappia che sta spartendo — se capisci cosa intendo.$B$BCi serve che vai a parlare con Onin MacHammar, dalle parti di Gnomeregan, e che torni con un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fa' attenzione.",
  obj = "Trova Onin MacHammar, vicino a Gnomeregan.",
  reward = "Shhhh! Abbassa la voce, testa vuota. Ci sentiranno.",
  en_title = "Simple Subterfugin'",
  en_obj = "Find Onin MacHammar by Gnomeregan.",
}
T[2239] = {
  title = "Il Rapporto di Onin",
  desc = "La Cava? Già, vedo passare qui davanti quei mostruosi carri a vapore corazzati quasi ogni giorno.$B$BI miei contatti a est mi dicono che il carro parte da Ironforge, carica merce alla Cava di Gol'Bolar, si ferma a Kharanos per fare rifornimento e poi, per qualche maledetto motivo, fa il giro lungo passando da Gnomeregan, prima di arrivare a Ironforge a consegnare il carico.$B$BÈ tutto nel rapporto, $R. Riportalo a Hulfdan, così può pianificare la prossima mossa.",
  obj = "Riporta Onin's Report a Hulfdan, a Ironforge.",
  progress = "Ti è piaciuta la puzza di gnomo lebbroso? Te lo chiedo solo perché hai un sorriso da matto stampato in faccia.$B$BChe notizie mi porti da Onin?",
  reward = "Il giro lungo? Per la mia barba!$B$BHai fatto un buon lavoro, $N. Prendi questo pugnale e sparisci. Il Circle ti chiamerà di nuovo quando il passo tre sarà pronto per partire.$B$BCos'è il passo tre? Viene subito dopo il passo due: io che ti pianto lo stivale nel sedere.$B$BTi interessa?",
  en_title = "Onin's Report",
  en_obj = "Take Onin's Report back to Hulfdan in Ironforge.",
}
T[2240] = {
  title = "La Camera Nascosta",
  desc = "E ora veniamo al compito da svolgere.$B$BC'è una camera segreta, la Camera di Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta chiusa! Per fortuna io so come aprirla.$B$BHo descritto tutto nel mio diario, qui sul tavolo. Io e i miei compagni per ora siamo bloccati qui... quindi tocca a te, $N, trovare la camera di Khaz'mul per noi!$B$BLeggi il mio diario, esplora la camera, poi fai rapporto al Prospettore Stormpike, alla Lega degli Esploratori, a Ironforge.",
  obj = "Leggi Baelog's Journal, esplora la camera nascosta, poi fai rapporto a Prospector Stormpike.",
  progress = "Hai qualcosa da riferire?",
  reward = "Hai visto la Camera di Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.$B$BGrazie, $N. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riprendere Uldaman. E se mai tornerà sotto il controllo di Ironforge, i segreti della Camera di Khaz'mul saranno nostri!",
  en_title = "The Hidden Chamber",
  en_obj = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",
}
T[2241] = {
  title = "La Mela Cade",
  desc = "Dicono che sono 'innamorato perso', qualunque cosa voglia dire.$B$BCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, la mia casa è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, senza dormire e senza bere, mentre mi struggo per l'amore che avremmo potuto avere. È così sbagliato?$B$BE ora lei non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma lei non parla nemmeno con chi non sia un ladro.$B$BPotresti consegnarle questo fiore? Non dimenticare di dirle che è da parte di Jannok.",
  obj = "Porta Jannok's Rose a Syurna, a Darnassus.",
  progress = "Oh, ma che meraviglia. Hai portato dei fiori per il tuo funerale.",
  reward = "Se avessi conservato ogni fiore che quello zuccone di Jannok mi ha mandato, avrei avuto di che aprire un negozio. Comunque sia, sembra che $Gl'ultimo messaggero:l'ultima messaggera; di Jannok possa rivelarsi utile.$B$BTi interessa un po' di lavoro, $C?",
  en_title = "The Apple Falls",
  en_obj = "Take Jannok's Rose to Syurna in Darnassus.",
}
T[2242] = {
  title = "Il Destino Chiama",
  desc = "Crediamo che esista un essere che potrebbe aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo, convincere la creatura a collaborare si è rivelato un disastro.$B$BSi nasconde su un ramo ai margini della Radura dell'Oracolo. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, hanno fatto una brutta fine. Forse la risposta è la furtività, $N.$B$BScopri cosa porta Sethir l'Antico nelle sue borse e fammi rapporto.",
  obj = "Trova Sethir the Ancient e porta a Syurna tutti gli indizi che riesci a scoprire.",
  progress = "Hai qualcosa da riferire su Sethir l'Antico, $N?",
  reward = "Sono notizie cupe, $N. Sembrerebbe che il morbo che ha colpito le foreste e i fiumi di Darkshore abbia cominciato a portare la corruzione nella nostra casa.$B$BCi hai servito bene, ma qui non c'è più nulla che tu possa fare. Prendi questa lama come ricompensa per i tuoi servigi a Teldrassil.",
  en_title = "Destiny Calls",
  en_obj = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.$B",
}
T[2258] = {
  title = "Reagenti dalle Badlands",
  desc = "$N, mi servirebbe il tuo aiuto, se te la senti. Sono un alchimista di una certa fama, e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.$B$BPer rifornire le mie scorte mi servono queste cose: cinque ventrigli di condor, dieci zanne di coyote delle rupi e cinque schegge di elementale della roccia. Ovviamente puoi prenderli direttamente da quelle bestiacce; se combattere non fa per te, trovati degli amici che sappiano farlo.$B$BProcurami queste cose e ci guadagnerai qualche moneta. Allora, che vuoi fare?",
  obj = "Porta 5 Buzzard Gizzard, 10 Crag Coyote Fang e 5 Rock Elemental Shard a Jarkal Mossmeld, a Kargath, nelle Badlands.",
  progress = "Hai già preso le cose che mi servono? Non sarai $Gpagato:pagata; se non mi porti quei reagenti.",
  reward = "Ah, ben fatto! Questi mi basteranno almeno per un po'. Ecco la tua paga, come promesso.$B$BSe ti interessa, ci sono altri reagenti che mi farebbero comodo. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi ancora farò in modo che ne valga la pena.$B$BMagari qualcosa di più di qualche moneta luccicante, eh?",
  en_title = "Badlands Reagent Run",
  en_obj = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.",
}
T[2259] = {
  title = "Erion Shadewhisper",
  desc = "Non preoccuparti, $N, non ti sto mandando da Syurna. Erion richiede la tua presenza all'Enclave Cenarion. Sbrigati!",
  obj = "Mettiti in contatto con Erion Shadewhisper, a Darnassus.",
  reward = "È ora di allargare i tuoi orizzonti, $R — il mondo ti aspetta.",
  en_title = "Erion Shadewhisper",
  en_obj = "Contact Erion Shadewhisper in Darnassus.$B",
}
T[2260] = {
  title = "Per Volere di Erion",
  desc = "La notizia delle tue imprese si è diffusa in lungo e in largo, $N. Al punto che la Stormwind Intelligence ha chiesto di te per nome.$B$BIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi presso lo SI:7 non va presa alla leggera.$B$BUn mondo nuovo ti aspetta, $N. Raggiungi la Città Vecchia, a Stormwind, e parla con Renzik \"Il Coltello\" al quartier generale dello SI:7.",
  obj = "Raggiungi Stormwind City e chiedi di parlare con Renzik \"The Shiv\".",
  reward = "Hai risposto alla chiamata dello SI:7, $N, e hai viaggiato da coste lontane per unirti a noi; tuttavia, hai ancora molto da imparare.",
  en_title = "Erion's Behest",
  en_obj = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"$B",
}
T[2278] = {
  title = "I Dischi di Platino",
  desc = "Al centro di questa camera del tesoro ci sono quattro enormi dischi di platino, ognuno ornato di numerosi sigilli di origine sconosciuta. Toccarli ti fa formicolare la mano. Subito dopo che hai toccato i dischi, compare l'immagine di un grande guardiano di pietra.$B$B\"Saluti. Sono un custode della conoscenza. La sintesi dei Terrigeni compiuta dai Creatori è stata registrata e conservata qui, per questo mondo, nei Dischi di Norgannon.\"$B$BHai portato alla luce un patrimonio di sapere sul mondo mai scoperto prima!",
  obj = "Parla con il guardiano di pietra e scopri quale antico sapere custodisce. Quando avrai appreso il sapere che ha da offrire, attiva i Discs of Norgannon.",
  progress = "La voce del guardiano di pietra sembra risuonare nel profondo del tuo essere:$B$B\"Prima devi soddisfare il requisito di assimilazione dei dati dei Dischi di Norgannon; una volta soddisfatto questo requisito, ti sarà permesso ottenere una versione portatile dei dati archiviati. Assicurati prima di aver esplorato a fondo le informazioni di questo archivio.\"",
  reward = "Seguendo le istruzioni del guardiano di pietra, accedi di nuovo ai Dischi di Norgannon, ora che hai appreso la storia dei Terrigeni, dei trogg e dei nani. Dall'interno dei dischi si sente un ronzio debole e breve. Poi il guardiano di pietra parla:$B$B\"I dischi sono stati sintetizzati. Accedi ancora una volta ai Dischi di Norgannon per ricevere la tua copia personale.\"",
  en_title = "The Platinum Discs",
  en_obj = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.",
}
T[2279] = {
  title = "I Dischi di Platino",
  desc = "Toccare di nuovo i Dischi di Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano stridore.$B$BIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!$B$BSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. La Lega degli Esploratori di Ironforge è proprio un gruppo così, conosciuto in tutta l'Alleanza; forse potrà farne buon uso.",
  obj = "Porta la versione in miniatura dei Discs of Norgannon alla Lega degli Esploratori, a Ironforge.",
  progress = "Sì, posso aiutarti in qualcosa? Ti assicuro che in questo momento sono molto occupato. Se però è una questione di grande importanza per la Lega degli Esploratori, allora sono tutt'orecchi!",
  reward = "Cos'hai lì... oh, cielo. Dove l'hai trovato?$B$BNo, davvero?$B$BHai parlato con chi, di cosa?$B$BNO, DAVVERO?!$B$B$GMio caro:Mia cara; $C, potresti aver appena fatto la scoperta archeologica dell'anno! Per gli Dèi, ma chi voglio prendere in giro, la scoperta del secolo! Se questi dischi sono quello che penso, potrebbero essere proprio la chiave che cercavamo! Potrebbero dimostrare una volta per tutte la legittimità della creazione incantata dei Nani!",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.",
}
T[2280] = {
  title = "I Dischi di Platino",
  desc = "Toccare di nuovo i Dischi di Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano stridore.$B$BIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!$B$BSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. I saggi di Thunder Bluff sono proprio storici di questo tipo, conosciuti in tutta l'Orda; forse potranno farne buon uso.",
  obj = "Porta la versione in miniatura dei Discs of Norgannon a uno dei saggi di Thunder Bluff.",
  progress = "Sì, giovane, ti vedo entrare nella mia tenda con passo deciso... con determinazione nei tuoi propositi. Cerchi il mio consiglio su una questione di grande importanza per l'Orda? O forse desideri che ti venga svelato un mistero dell'universo?",
  reward = "Cosa sono questi, allora?$B$BNotevole, giovane! In questi dischi percepisco segreti che la terra ha custodito gelosamente per molti anni. Hai fatto molto bene a portarli qui da me.",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.",
}
T[2281] = {
  title = "Appuntamento a Redridge",
  desc = "Mandarti sul campo adesso sarebbe un suicidio. A Renzik non serve un altro ladro morto sulla coscienza. Ma non preoccuparti, $N — Renzik ti metterà al passo.$B$BRaggiungi le Redridge Mountains e parla con un collaboratore dello SI:7 di nome Lucius. Lo troverai a bighellonare vicino ai moli di Lakeshire, insieme agli altri buoni a nulla dall'aria losca.",
  obj = "Mettiti in viaggio verso Lakeshire, nelle Redridge Mountains, e parla con Lucius.",
  reward = "Ah, quindi hai le dita un po' grassocce, eh? Non preoccuparti, $N: ho trasformato in ladri provetti dei borsaioli ben più inetti di te.",
  en_title = "Redridge Rendezvous",
  en_obj = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.$B",
}
T[2282] = {
  title = "Segheria di Alther",
  desc = "Qui addestriamo ladri da anni! Dopotutto, non tutti i furfanti nascono con la grazia e la finezza del vecchio Lucius.$B$BQui sopra, poco fuori dalla strada, troverai la Segheria di Alther. Lassù ho un forziere con dentro una cosa importante. Va' a prendermela! Riportami quel gettone e riceverai il tuo Attestato di Ladro!",
  obj = "Apri Lucius's Lockbox, recupera il Token of Thievery e riportalo a Lucius, a Lakeshire.",
  progress = "Mi sono dimenticato di dirti degli orchi?$B$BHo sentito che ficcanasano lassù, vicino alla segheria.",
  reward = "L'hai scassinato, eh? Bel lavoro, $N.$B$BSe muori adesso, possiamo stare tranquilli: sarà per colpa della tua stupidità e non dell'inesperienza.",
  en_title = "Alther's Mill",
  en_obj = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.",
}
T[2283] = {
  title = "Recupero della Collana",
  desc = "Abbiamo un lavoro per te, sempre che tu abbia il fegato di farlo!$B$BNel profondo delle Badlands c'è il sito di scavo di Uldaman. Ci è arrivata la storia di un paladino idiota che ci è morto di recente. Il motivo per cui ce ne importa è che aveva addosso una collana di grande valore. A quanto pare ha tre grosse gemme: un rubino, uno zaffiro e un topazio.$B$BEcco il punto: la vogliamo, e per averla paghiamo IL MASSIMO in argento. Potrebbe essere danneggiata, ma poco importa: qualunque graffio abbia, lo sistemiamo noi.",
  obj = "Cerca una collana di valore nel sito di scavo di Uldaman e riportala a Dran Droffers, a Orgrimmar. La collana potrebbe essere danneggiata.",
  progress = "Allora, ce l'hai la collana? Da noi non vedrai un soldo, se non hai quella collana!",
  reward = "Mmm, roba da recupero! Sento l'odore della collana da qui. Ora diamo un'occhiata a questa bellezza...$B$BEhi, cosa credi di fare? Questa collana non ha le gemme! Pensavi che non ce ne saremmo accorti? Perfino Malton vedrebbe che le gemme non ci sono.$B$BBe', forse non le hai rubate tu... ma senza quelle gemme questa collana non vale niente! Il tuo lavoro qui non è ancora finito, tutt'altro!",
  en_title = "Necklace Recovery",
  en_obj = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.",
}
T[2284] = {
  title = "Recupero della Collana, Secondo Tentativo",
  desc = "Com'è vero che Malton è uno stupido, quelle gemme sono ancora da qualche parte a Uldaman. Dovrai tornare laggiù a cercarle.$B$BCome ho detto prima, se le informazioni che abbiamo sono giuste, con la collana vanno un rubino, uno zaffiro e un topazio. Trovali e rimettili nella collana.$B$BQuanto a dove siano le gemme, chi lo sa? Magari avrai fortuna e troverai il cadavere del Paladino. Se non l'hanno già spogliato di tutto, magari le ha ancora addosso.",
  obj = "Trova un indizio su dove si trovano le gemme, nelle profondità di Uldaman.",
  reward = "Sembra che tu abbia trovato i resti del paladino di cui ti aveva parlato Dran. Frugando tra i resti scopri quello che sembra il suo diario. Il libro è in pessime condizioni: il sangue secco ha macchiato quasi tutto il testo. Quello che riesci a leggere, però, è incomprensibile: per quanto ne sai, è scritto nella lingua degli umani.$B$BSe vuoi ricavarne qualcosa, dovrai far tradurre il libro.",
  en_title = "Necklace Recovery, Take 2",
  en_obj = "Find a clue as to the gems' whereabouts in the depths of Uldaman.",
}
T[2298] = {
  title = "Una Retata Reale",
  desc = "Allora, eravamo lì lì per cominciare a pianificare la fase III, quando un paio di teste di legno di Magni piombano qua dentro parlando di un qualche colpo e arrestano alcuni dell'Hidden Circle.$B$BBeh, nessuno mette i ferri al vecchio Blackbeard! La discussione s'è fatta pesante e accesa, e chissà come il tuo nome è stato spifferato!$B$BIl consiglio mio? Prendi il primo Grifone che parte da Ironforge e vai a Stormwind. Arriva fino alla Città Vecchia e, una volta lì, parla con un mio vecchio amico di nome Renzik \"Il Coltello\".",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".",
  reward = "Fa sempre piacere avere $Guno:una; dei ladri di Hulfdan tra le nostre file!",
  en_title = "Kingly Shakedown",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
}
T[2299] = {
  title = "Da Hulfdan!",
  desc = "Dove ti eri $Gcacciato:cacciata;, $N? Hulfdan ti sta cercando dappertutto. Pensavamo che il re ti avesse messo ai ferri.$B$BVa' a Ironforge il prima possibile e parla con Hulfdan!",
  obj = "Raggiungi Ironforge e parla con Hulfdan Blackbeard.",
  reward = "Abbassa la voce, $N, che le guardie ti posson sentire.",
  en_title = "To Hulfdan!",
  en_obj = "Travel to Ironforge and speak with Hulfdan Blackbeard.",
}
T[2300] = {
  title = "SI:7",
  desc = "Renzik ti stava cercando, $Gpivello:pivella;.$B$BIo, al posto tuo, non farei aspettare il vice di Mathias.",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".",
  reward = "Sei $Gpronto:pronta; a metterti al lavoro o ti serve un pisolino prima di cominciare?",
  en_title = "SI:7",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"$B",
}
T[2318] = {
  title = "Tradurre il Diario",
  desc = "Sei in una specie di vicolo cieco: sai che dovrai far tradurre il libro in una lingua che capisci. Nel mondo ci sono di sicuro parecchie persone in grado di farlo; il posto più vicino dove potrebbe esserci qualcuno capace, però, è l'avamposto di Kargath, nelle Badlands. Forse è un buon punto di partenza.",
  obj = "Trova qualcuno che sappia tradurre il diario del paladino. Il posto più vicino dove potrebbe esserci qualcuno è Kargath, nelle Badlands.",
  reward = "Potente $C, so cosa fai qui nelle Badlands. So che cerchi il mio dono delle lingue. Sei sulle tracce dei pezzi di quella collana che hai trovato a Uldaman.$B$BTi sorprende? Non dovrebbe: sapere queste cose è il mio lavoro. Parliamo piuttosto di cosa farai in cambio di un diario tradotto. Fidati: sono l'unico che troverai in grado di tradurlo.$B$BMeglio ancora, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, che ti permetterà comunque di portare a termine il tuo accordo con loro. Ora ti interessa, vero?",
  en_title = "Translating the Journal",
  en_obj = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.",
}
T[2338] = {
  title = "Tradurre il Diario",
  desc = "Quelli della Droffers and Son Salvage non sono abbastanza furbi da ridare magia alla collana, ma io sì. Voglio solo studiare la collana per imparare a farne anch'io. Per farlo, mi serve la tua collana. Prestamela, e in cambio del tempo che avrò per studiarla ti tradurrò il diario. Mentre tu cerchi le gemme, dovrei avere abbastanza tempo per imparare quello che mi serve.$B$BÈ un accordo semplice, e nessun altro lo verrà a sapere. Allora, che vuoi fare?",
  obj = "Presta la collana a Jarkal. In cambio, lui ti tradurrà il diario.",
  progress = "Ci hai pensato, vero? Sei $Gun:una; $C $Gfurbo:furba; se accetti questo accordo: tu e io otterremo quello che vogliamo tutti e due, e quelli della Droffers and Son Salvage crederanno di ottenere quello che vogliono loro.",
  reward = "Un buon affare lo riconosci quando lo vedi: sapevo di poter contare su di te.$B$BCi vorrà solo un momento, il tempo di lanciare un incantesimo per tradurre in fretta la lingua degli umani in una forma che tu possa capire. Sono un troll di parola: chiedi di Jarkal Mossmeld a chiunque nell'Orda. Ora cominciamo...",
  en_title = "Translating the Journal",
  en_obj = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.",
}
T[2339] = {
  title = "Trova le Gemme e la Fonte di Energia",
  desc = "Ecco il diario, tradotto perché tu possa leggerlo da te. Il succo è che i nani hanno nascosto il rubino, i trogg hanno nascosto il topazio, e un trogg di nome Grimlok ha lo zaffiro.$B$BSenti: ti servirà una fonte di energia per far funzionare di nuovo la collana. Dran Droffers non lo sa. Per trovarne una, ecco cosa farei io: scendi più in profondità che puoi a Uldaman e uccidi il costrutto più forte che c'è. Senza dubbio, qualunque cosa sia, ce l'avrà.$B$BQuando avrai raccolto tutto, torna qui!",
  obj = "Recupera a Uldaman tutte e tre le gemme e una fonte di energia per la collana, poi portale a Jarkal Mossmeld, a Kargath. Jarkal crede che una fonte di energia si possa trovare sul costrutto più forte di Uldaman.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona barricata degli Shadowforge.$B* Il topazio è stato nascosto in un'urna in una delle zone dei Trogg, vicino ad alcuni nani dell'Alleanza.$B* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.",
  progress = "Ti aspetta un altro viaggio nelle profondità di Uldaman, se non hai le gemme e una fonte di energia in grado di incanalare di nuovo il potere magico nella collana.$B$BLe gemme te le riprenderai per consegnarle a quegli scagnozzi di Orgrimmar; io terrò la fonte di energia, visto che è proprio quella che farà funzionare la collana...",
  reward = "Ben fatto davvero, $C. Ora i frutti del nostro dirottamento ci ripagheranno lautamente. Con la collana in sé ho finito, e sono sicuro di poter ripetere il procedimento di costruzione ogni volta.$B$BMa prima userò un incantesimo preparato apposta per analizzare in fretta quelle gemme, prima che tu le riporti a Orgrimmar insieme alla collana. Ci vorrà solo un attimo.",
  en_title = "Find the Gems and Power Source",
  en_obj = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2340] = {
  title = "Consegna le Gemme",
  desc = "Va bene qualunque castone e qualunque gemma, purché siano dello stesso materiale. Questa fonte di energia, invece, è quella che riporterà la magia nella collana... spero.$B$BTi fornirò volentieri le gemme che servono per la tua versione della collana, a patto che la fonte di energia funzioni davvero.$B$BVa' a Orgrimmar e mantieni la tua parte del patto con la Droffers and Son Salvage. Solo, tieni la bocca chiusa sul nostro accordo, e quando torni potrei avere una splendida sorpresa per te.",
  obj = "Consegna il Necklace and Gem Salvage a Dran Droffers, a Orgrimmar.",
  progress = "Ma guarda chi si vede! Te la sei presa comoda, vedo. Speriamo che non sia una perdita di tempo! Non verrai $Gpagato:pagata; se non hai tutto quello che ti ho chiesto. E fidati — controlleremo tutto due e tre volte!",
  reward = "Sì, c'è tutto. Senti, ti spiace se ci teniamo anche la borsa? No? Grazie, molto gentile! Ah ah!$B$BQuesta collana sarà il nostro colpo migliore di sempre! Ma non prendertela troppo; sono sicuro che comunque la collana non ti sarebbe andata. Ah ah, di nuovo!$B$BI patti sono patti, quindi ecco il tuo compenso per il recupero. Per ora i nostri affari sono chiusi; ripassa più tardi per vedere se abbiamo altro lavoro. Fino ad allora, sparisci!",
  en_title = "Deliver the Gems",
  en_obj = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",
}
T[2341] = {
  title = "Recupero della Collana, Terzo Tentativo",
  desc = "Mentre Dran e Malton Droffers cominciano a litigare sul loro nuovo bottino, metà dell'accordo è conclusa. Ora ci vuole un viaggio nelle Badlands per chiudere la faccenda, perché Jarkal Mossmeld, a Kargath, potrebbe avere una ricompensa speciale ad aspettarti.",
  obj = "Va' da Jarkal Mossmeld, a Kargath, per vedere se ci è riuscito.",
  reward = "La fonte di energia che mi hai dato ha superato ogni mia aspettativa. Sono riuscito a fare una collana per te e una per me, e me ne avanza abbastanza per farne almeno altre tre. Frutteranno un bel compenso, e la Droffers and Son Salvage non ne saprà niente.$B$BEcco a te, $Gamico mio:amica mia;. Ti ringrazio per lo splendido lavoro... e ti do qualcosa di davvero speciale per il disturbo.",
  en_title = "Necklace Recovery, Take 3",
  en_obj = "Visit Jarkal Mossmeld in Kargath to see if he was successful.",
}
T[2342] = {
  title = "Tesori Recuperati",
  desc = "Spazzare i recinti dei pipistrelli con questa scopa non si addice a un Garrett! Con questo lavoro maledetto ho messo da parte qualche moneta, e sono disposto a spenderla per te pur di migliorare la mia posizione.$B$BL'arma preferita della famiglia Garrett è chiusa nel nostro forziere nella Sala Comune Sud di Uldaman, da quando noi Garrett lavoravamo lì come scavatori. Senza di essa resterò bloccato qui per sempre, letteralmente, a spazzare dietro a questi pipistrelli infernali.$B$BRecupera il tesoro della mia famiglia e portamelo! Aiutami a riprendermi ciò che mi spetta per nascita!",
  obj = "Prendi il tesoro di famiglia di Patrick Garrett dal forziere di famiglia nella South Common Hall di Uldaman, e portalo a Patrick, nell'Undercity.",
  progress = "Non si finisce mai di spazzare... questi pipistrelli non si stancano mai di prendersi gioco di me e della mia scopa. Dimmi che hai recuperato il tesoro della mia famiglia! Ti ho offerto il mio argento: non basta?!",
  reward = "Finalmente, una scopa degna di un Garrett. Vali fino all'ultima moneta d'argento che ho speso per te, parola mia!$B$BMi sentite, pipistrelli schifosi? Ora impugno l'arma preferita della famiglia Garrett! Tremate, pipistrelli, tremate!!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
}
T[2358] = {
  title = "Corna di Nez'ra",
  desc = "Molti anni fa, le Corna di Nez'ra furono rubate dal maniero di Ravenholdt. Le ho cercate per continenti e oceani, per poi scoprire che queste bestie insignificanti le avevano da sempre.$B$BUccidi ogni orco Blackrock che incontri finché non avrai recuperato le Corna di Nez'ra. Se recuperi le corna, mi troverai a Lakeshire.$B$BFallo per me, e il tuo nome sarà noto a Ravenholdt, $N.",
  obj = "Riporta gli Horns of Nez'ra ad Arantir's Shadow, a Lakeshire.",
  progress = "Hai le corna del principe demone?",
  reward = "Negare il manufatto a Ravenholdt significherebbe negare la propria stessa esistenza. Ben fatto, $Gladro:ladra;. Un giorno potresti camminare tra gli assassini di Ravenholdt.$B$BDa giovane ladro, durante le mie avventure a Darkshore, ho scoperto un tè che ridà energia in combattimento. Mi è stato utile per tutti questi anni, e ora ti passo un assaggio di tè di cardo. Bevilo quando sei $Gstanco:stanca;, $N, e torna a combattere con vigore!",
  en_title = "Horns of Nez'ra",
  en_obj = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.",
}
T[2359] = {
  title = "Klaven's Tower",
  desc = "Tengo d'occhio questa torre da settimane, $N. Di recente è arrivato un grosso carico da Duskwood, e insieme sono arrivate quelle guardie.$B$BChe cosa sono? Ne so quanto te. Una cosa però posso dirtela — non sono umani.$B$BComunque, nel carico c'era un forziere — ed è quello che, immagino, stanno sorvegliando quegli abomini. Lo zombie con gli spuntoni ha una chiave che ci servirà.$B$BPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta quello che trovi a Mathias.",
  obj = "Ruba la Defias Tower Key, introduciti nella Torre dei Defias e scopri il contenuto della Duskwood Chest. Porta tutte le informazioni che trovi a Mathias Shaw, a Stormwind. Leggi Kearnen's Journal per saperne di più sulla torre.",
  progress = "Notizie dall'Agente Kearnen?",
  reward = "Questo spiegherebbe i droni dei Defias che tu e Kearnen avete visto fuori dalla torre, $N. E spiegherebbe anche il coinvolgimento della Venture Company con i Defias e gli strani carichi provenienti da Duskwood.$B$BSecondo questo libro, i troll di Zanzil a Stranglethorn hanno scoperto un modo per risvegliare i morti con le pozioni... o, per essere più precisi, con il veleno.$B$BSenza una solida conoscenza dei veleni non servirai a niente allo SI:7, $N — soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.",
  en_title = "Klaven's Tower",
  en_obj = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.$B",
}
T[2360] = {
  title = "Mathias e i Defias",
  desc = "Appena in tempo, $N. La ricognizione dello SI:7 segnala un'attività dei Defias insolitamente intensa a Westfall.$B$BSembra che i Defias abbiano occupato una torre di guardia abbandonata dell'Alleanza a sud-est di Guardiacolle, e che la usino come base operativa per contrabbandare merci dalla via di rifornimento di Redridge.$B$BRaggiungi Westfall e mettiti in contatto con l'Agente Kearnen per il resoconto. La troverai nascosta vicino alla torre.$B$B...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.",
  obj = "Raggiungi Westfall e trova Agent Kearnen per il resoconto.",
  reward = "Mathias ha finalmente mandato $Gun altro agente:un'altra agente; a darmi man forte, eh? Beh, spero che sia $Gpronto:pronta; a sentire qualche brutta notizia.",
  en_title = "Mathias and the Defias",
  en_obj = "Travel to Westfall and find Agent Kearnen for your debriefing.",
}
T[2361] = {
  title = "Restaurare la Collana",
  reward = "Ti do volentieri questa collana, potente $C. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire ad alta voce e più volte chi te l'ha fatta!$B$BE poi, se potessi aggiungere che non è affatto maledetta, sarebbe fantastico.",
  en_title = "Restoring the Necklace",
}
T[2378] = {
  title = "Trova la Shattered Hand",
  desc = "Hai servito bene gli Inseguitori della Morte, $N, ma forse è ora che tu ti spinga più lontano. Anche se hai mostrato attitudine per la furtività e l'inganno, hai ancora bisogno di molto addestramento.$B$BGli Inseguitori della Morte hanno degli alleati nella Shattered Hand. Cerca quelli che potrebbero aiutarci — trova Shenthul a Orgrimmar.",
  obj = "Raggiungi Orgrimmar e parla con Shenthul nella Cleft of Shadow.",
  reward = "Dunque è questo ciò che i nostri potenti alleati hanno mandato a Shenthul? Che delusione...",
  en_title = "Find the Shattered Hand",
  en_obj = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.",
}
T[2379] = {
  title = "Zando'zan",
  desc = "La tua determinazione da sola non basta a superare gli ostacoli che ci aspettano.$B$BParla con Zando'zan per cominciare il tuo addestramento come agente della Shattered Hand.$B$BSolo quando avrai padroneggiato le arti della furtività e del furto potrai fare il passo successivo verso il tuo destino.",
  obj = "Parla con Zando'zan nella Cleft of Shadow.",
  reward = "Forse Zando'zan si è sbagliato. Zando'zan chiede scusa.",
  en_title = "Zando'zan",
  en_obj = "Speak with Zando'zan at the Cleft of Shadow.",
}
T[2380] = {
  title = "A Orgrimmar!",
  desc = "Non sei $Gun maestro:una maestra; della furtività e dell'inganno, ma tutto questo può cambiare, e cambierà. Evidentemente hai fatto colpo su chi comanda con le tue misere abilità, visto che il grande Shenthul ha chiesto di te per nome.$B$BPrendi la strada a nord di qui fino a Orgrimmar e parla con Shenthul nella Fenditura dell'Ombra.",
  obj = "Parla con Shenthul nella Cleft of Shadow, a Orgrimmar.",
  reward = "È importante che la Shattered Hand resti vigile di fronte ai cambiamenti che Thrall vuole portare nell'Orda. Il nostro numero da solo non basterà a rovesciare il suo dominio — bisogna padroneggiare la furtività e l'inganno.",
  en_title = "To Orgrimmar!",
  en_obj = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.",
}
T[2381] = {
  title = "Depredare i Predoni",
  desc = "Non voglio spaventarti, $N, ma gli ultimi cinque ladri che ho mandato a rubare il tesoro dei mari del sud mi sono tornati indietro a pezzi.$B$BPiù a sud lungo la costa troverai la Tide Razor, la nave dei filibustieri dei mari del sud. Nella stiva c'è il bottino — il tesoro dei mari del sud. Sul secondo ponte della nave c'è il covo dei pirati, il posto dove addestrano tutti i loro ladri.$B$BSali su quella nave, ruba il tesoro e portamelo. Se hai bisogno di esercitarti a rubare, usa il covo dei pirati, ma fa' attenzione!",
  obj = "Riporta il Southsea Treasure a Wrenix the Wretched, a Ratchet. Non dimenticare di prendere un E.C.A.C. e i Thieves' Tools da Wrenix's Gizmotronic Apparatus. Ti serviranno entrambi per completare la missione.$B$BSe dovessi essere $Gattaccato:attaccata; da pappagalli insolitamente ostili, usa il tuo E.C.A.C.!",
  progress = "Beh, almeno hai ancora tutti i pezzi al loro posto. Hai trovato il tesoro?",
  reward = "Incredibile! Improbabile! Semplicemente strabiliante! Hai talento, $N. O quello, o sei $Gl'uomo più fortunato:la donna più fortunata; del mondo!$B$BEcco la tua parte del bottino. Di sicuro tu ne farai un uso migliore del mio.",
  en_title = "Plundering the Plunderers",
  en_obj = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.$B$BShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!$B$B",
}
T[2382] = {
  title = "Wrenix di Ratchet",
  desc = "Zando'zan l'ha visto! Sì, il giorno arriva! La morte di Thrall... il pugnale nella sua schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.$B$B$N! Zando'zan ha un compito per $N! $N deve andare a Ratchet, a est del Crossroads, e parlare con Wrenix the Wretched. Va'!",
  obj = "Raggiungi Ratchet e parla con Wrenix the Wretched.",
  reward = "$GUn altro:Un'altra;? Gli ultimi cinque che quel troll matto mi ha mandato sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?",
  en_title = "Wrenix of Ratchet",
  en_obj = "Travel to Ratchet and speak with Wrenix the Wretched.",
}
T[2383] = {
  title = "Cartapecora Semplice",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, a ripararsi all'ombra.",
  obj = "Leggi la Simple Parchment e parla con Frang, nella Valley of Trials.",
  progress = "Cos'hai lì? Una pergamena? Non sarai $Guno studioso:una studiosa;, spero...",
  reward = "Ah, è la mia pergamena. Avevo sentito che saresti $Garrivato:arrivata; nella Valle, $N. Sono contento di vedere che ce l'hai fatta — speriamo che tu sopravviva alle prove che ti aspettano. Come dicevo, man mano che cresci in potenza vieni da me — farò il possibile per addestrarti nelle vie $Gdel:della; $C.$B$BBuona fortuna, $N, e torna da me quando ti senti $Gpronto:pronta;.",
  en_title = "Simple Parchment",
  en_obj = "Read the Simple Parchment and speak to Frang in the Valley of Trials.",
}
T[2398] = {
  title = "I Nani Perduti",
  desc = "Il sito di scavo di Uldaman non è sempre stato invaso. Noi nani di Ironforge controllavamo la zona, ma... questo succedeva prima che arrivassero i trogg. Sono arrivati così in fretta e così numerosi che nemmeno la forza dei nani è riuscita a fermarli!$B$BAnzi, il loro attacco è stato così improvviso che temo che alcuni dei nostri siano rimasti intrappolati dietro le linee nemiche.$B$BIl mio amico Baelog ha guidato un piccolo gruppo di nani nel cuore del sito poco prima che si facessero vivi i trogg. Se lui e la sua compagnia sono vivi, voglio che tu li trovi.",
  obj = "Trova Baelog a Uldaman.",
  reward = "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!$B$BAveva scommesso che la barba gli sarebbe arrivata alle ginocchia prima di vedere $Gun altro:un'altra; $R in vita. Be', eccoti qui, e come vedi alla barba di Olaf manca ancora qualche pollice.$B$BGrazie, $N. Dividerò la vincita con te.",
  en_title = "The Lost Dwarves",
  en_obj = "Find Baelog in Uldaman.",
}
T[2418] = {
  title = "Pietre Energetiche",
  desc = "Tempo fa ho avuto una disavventura con i Nani Shadowforge. Mi hanno portato alla Fortezza di Angor per studiare due tipi di strane pietre di Uldaman. Ho scoperto che, se trattate nel modo giusto, erano fonti di energia durature e stabili. È incredibile quello che si trova in quel vecchio sito di scavo!$B$BComunque, dopo che gli ho svelato il segreto delle pietre, mi hanno cacciato dalla Fortezza di Angor e si sono messi a scavare a Uldaman per trovarne altre.$B$BQuelle pietre le voglio io! Portami tutti e due i tipi e ti pagherò un sacco!",
  obj = "Porta 8 Dentrium Power Stone e 8 An'Alleum Power Stone a Rigglefuzz, nei Badlands.",
  progress = "Hai le pietre energetiche, $N? Ho un roditore robotico che ha bisogno di una fonte di energia...",
  reward = "Fantastico, ne hai trovate! Grazie mille, $N. Sei $Gil:la; $R più affidabile che abbia mai incontrato!$B$BNon vedo l'ora di provarle su certi congegni che sto mettendo a punto. Scommetto che, nelle giuste condizioni, i congegni alimentati con queste pietre andranno avanti, e avanti, e avanti...",
  en_title = "Power Stones",
  en_obj = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",
}
T[2439] = {
  title = "I Dischi di Platino",
  desc = "Questo oggetto è una scoperta incredibile. Gli antichi Titani, o i Creatori, come li chiamano questi dischi, sono il legame con la nostra creazione incantata, se le conoscenze custodite qui dentro sono corrette! Dovremo dedicare a queste ricerche tutto il tempo possibile.$B$BQuanto a te, $Geroico:eroica; $C, porta questo buono a Dinita Stonemantle, al caveau. Ti dà diritto a quella che secondo me è una ricompensa adeguata a una scoperta così straordinaria!$B$BQuando sei $Gpronto:pronta; torna direttamente da me; c'è ancora molto da fare per la Lega degli Esploratori!",
  obj = "Porta il tuo Reward Voucher a Dinita Stonemantle, nel Vault of Ironforge.",
  progress = "$GBenvenuto:Benvenuta; nel Caveau di Ironforge, $N. Cosa posso fare per te oggi?",
  reward = "Ah, sì, un buono della Lega degli Esploratori... e anche di gran valore, se posso dirlo.$B$BLa Lega degli Esploratori mi autorizza a offrirti una scelta sul tuo compenso, direttamente dal suo caveau. Riceverai questo oggetto, e come ricompensa potrai scegliere tra cinque pozioni di cura superiori e cinque pozioni di mana maggiori.",
}
T[2440] = {
  title = "I Dischi di Platino",
  desc = "Concentrerò le mie energie su questi dischi; a tempo debito mi riveleranno il loro vero funzionamento.$B$BQuanto a te, $N, ora ti ricompenserò per la diligenza con cui me li hai segnalati. Porta questo buono a Bena Winterhoof, l'istruttrice di alchimia di Thunder Bluff. Ti darà un oggetto speciale che credo troverai interessante, e ti offrirà una scelta di pozioni dalla mia scorta personale.$B$BTorna presto da me, perché sento che c'è ancora molto da fare riguardo a questa scoperta.",
  obj = "Porta il Reward Voucher a Bena Winterhoof, a Thunder Bluff.",
  progress = "Salve, $C! Sei qui per imparare l'alchimia, o per qualcos'altro?",
  reward = "Be', $N, devi aver fatto molto piacere a Sage Truthseeker, se ti ha dato questo oggetto. Ti spetta anche un dono dalla sua scorta di pozioni; come ricompensa puoi scegliere tra 5 pozioni di cura superiori e 5 pozioni di mana maggiori.",
  en_title = "The Platinum Discs",
  en_obj = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.",
}
T[2458] = {
  title = "Sotto Copertura",
  desc = "La Venture Company... Forse ne hai sentito parlare?$B$BPer un anno ci siamo impegnati a infiltrare un agente nel cuore delle loro file. Con molto lavoro e un'attenta pianificazione, ci siamo riusciti.$B$BDi recente ci è giunta voce che la Venture Co. sta preparando qualcosa in grande. Va' a nord della Palude Melmosa, alla torre della Venture Co., e mettiti in contatto con il nostro agente sotto copertura, il Sorvegliante Fizzule.$B$BQuando trovi la torre, usa questa pistola lanciarazzi, poi avvicinati a Fizzule e fagli il saluto della Shattered Hand.",
  obj = "Raggiungi la Torre della Venture Co., a nord di Sludge Fen, e mettiti in contatto con l'agente segreto della Shattered Hand, Taskmaster Fizzule.$B$BQuando la torre è in vista, usa la Flare Gun per segnalare il tuo arrivo a Taskmaster Fizzule. Spara DUE razzi, poi avvicinati a Taskmaster Fizzule ed esegui lo Shattered /Salute.$B$BQueste azioni vanno eseguite nell'ordine giusto, perché Fizzule attacca ed elimina chiunque non riconosca.",
  reward = "Fa piacere vedere $Gun altro agente:un'altra agente; della Shattered Hand da queste parti; però il razzo forse era un po' troppo!$B$BLa prossima volta che devi parlarmi, soffia due volte in questo fischietto e saprò che sei $Gun alleato:un'alleata;.",
  en_title = "Deep Cover",
  en_obj = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",
}
T[2460] = {
  title = "Lo Shattered Salute",
  desc = "Come $Gladro:ladra; della Shattered Hand, è indispensabile che tu impari lo Shattered Salute. È l'unico modo per riconoscere con certezza un altro membro della Hand.$B$BGuarda, impara, ripeti.",
  obj = "Esegui lo Shattered Salute davanti a Shenthul.",
  progress = "Esercitati!",
  reward = "Ben fatto, $N. Ora sei $Gpronto:pronta; per andare avanti.",
  en_title = "The Shattered Salute",
  en_obj = "Perform the Shattered Salute on Shenthul.",
}
T[2478] = {
  title = "Missione: Possibile ma Non Probabile",
  desc = "Dovrai rubare la chiave della torre al Caposquadra Silixiz, $N. Una volta che l'avrai in tuo possesso, tienila — potrebbe servirmi più tardi.$B$BRicorda, il veleno ha indebolito tutti quelli che stanno in questa torre. Usa le tue abilità per portare caos e distruzione tra i suoi abitanti. Uccidili tutti — nessuna pietà!$B$BQuando dentro non resterà che un mucchio di corpi insanguinati, scassina lo scrigno di Gallywix e ruba la scorta della miscela di Zanzil che contiene. Porta sia la testa di Gallywix sia la miscela a Shenthul, a Orgrimmar.",
  obj = "Ruba Silixiz's Tower Key a Foreman Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.$B$BAssassina Grand Foreman Gallywix e prendi la sua testa, poi scassina Gallywix's Lockbox e ruba la Cache of Zanzil's Altered Mixture. Porta la Cache e Gallywix's Head a Shenthul, a Orgrimmar, per ulteriori istruzioni.",
  progress = "Cosa hai da riferire, $N?",
  reward = "Povero Fizzule, era un buon agente — uno dei nostri migliori. Ahimè, è il prezzo che paghiamo, $N. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.$B$BHai svolto bene il tuo dovere, $C. Sarebbe un peccato se non vivessi abbastanza da servirci ancora.",
  en_title = "Mission: Possible But Not Probable",
  en_obj = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.$B$BAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.$B",
}
T[2479] = {
  title = "L'Aiuto di Hinott",
  desc = "Porta un campione della miscela a Serge Hinott, a Tarren Mill.$B$BSe qualcuno può curarti, quello è Serge. Se vivrai abbastanza, Serge ti mostrerà come si creano e si usano i veleni.",
  obj = "Raggiungi Tarren Mill, nelle Hillsbrad Foothills, e consegna il Sample of Zanzil's Mixture a Serge Hinott.$B$BPer arrivare a Tarren Mill, prendi lo zeppelin per l'Undercity e segui la strada verso sud attraverso Silverpine, in direzione di Hillsbrad. Segui i cartelli!",
  progress = "Cos'è questo???",
  reward = "Hai un pallore delizioso, $C. E cos'è quell'odore nauseabondo che emani? Devo saperlo!",
  en_title = "Hinott's Assistance",
  en_obj = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!$B$B",
}
T[2480] = {
  title = "L'Aiuto di Hinott",
  desc = "Non ho mai visto risultati così meravigliosi da un veleno! Zanzil, dici? Mai sentito nominare; però devo fargli i miei complimenti per aver creato questo intruglio.$B$BDunque, dovrei curarti da questo e poi insegnarti a usare il veleno?$B$BDammi qualche istante per esaminare la tossina, $N.",
  obj = "Aspetta che Serge Hinott finisca di preparare la cura.",
  reward = "La cura è pronta! Bevi questa antitossina e la follia strisciante si fermerà; per l'odore, però, non potrò fare niente.",
  en_title = "Hinott's Assistance",
  en_obj = "Wait for Serge Hinott to complete the cure.",
}
T[2521] = {
  title = "Servire Kum'isha",
  desc = "$R, il tuo minuscolo cervello riesce a comprendere quanto sia rara una sfera perfetta di draenethyst? I Draenei hanno passato vite intere alla ricerca di uno solo di questi cristalli, per poi andare incontro a destini orribili, senza aver raggiunto lo scopo.$B$BDunque sei al cospetto di Kum'isha, sai cosa ha chiesto Kum'isha e vuoi comunque aiutare? Molto bene, $R... Se in qualsiasi momento dei tuoi viaggi per queste terre dovessi trovare una sfera perfetta di draenethyst, portala a me e ti ricompenserò con ricchezze che vanno oltre i tuoi sogni più sfrenati.",
  obj = "Se nei tuoi viaggi per le Blasted Lands ti capitasse di trovare una Flawless Draenethyst Sphere, riporta l'oggetto a Kum'isha the Collector.$B$BBada, questa gemma è uno dei cristalli più rari di tutta Azeroth. Qualsiasi creatura di queste terre potrebbe avere con sé una Flawless Draenethyst Sphere.$B$BRiceverai una ricompensa per ogni Flawless Draenethyst Sphere raccolta.",
  progress = "Ho dedicato la mia vita alla ricerca di sfere perfette di draenethyst. Una vita intera, $R!",
  reward = "I miei occhi mi ingannano? Impossibile! Dove l'hai... Come...$B$BForse ora si potrà aprire un varco che ci riporti nella nostra terra natale.",
}
T[2522] = {
  title = "I Tentativi di Kum'isha",
  desc = "Anche se l'evocazione del portale è fallita, continuo a sperare che il prossimo tentativo riesca.$B$BLa speranza dei Draenei è fervida quanto la tua avidità di monili, $R. Torna in queste terre maledette e recupera un'altra sfera perfetta di draenethyst.$B$BNaturalmente, la scelta di accettare questo compito spetta solo a te *ghigno*.",
  obj = "Trova una Flawless Draenethyst Sphere e portala a Kum'isha the Collector.",
  progress = "Hai trovato un'altra sfera perfetta di draenethyst?",
  reward = "Semplicemente incredibile. Dubitavo che potessi trovare un'altra sfera, eppure eccola qui, che pulsa fra le mie mani.$B$BBen fatto, $N!$B$BSe dovessi trovarne altre — e lo ritengo impossibile — portamele e ti ricompenserò di nuovo.",
}
T[2523] = {
  title = "Songflower Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di songflower. La pianta emana un odore pungente e malsano. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion sul songflower. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[2581] = {
  title = "Guance di Snickerfang",
  desc = "È risaputo che le iene hanno una forza tremenda nelle mascelle, ma tanta da spezzare tre pollici di acciaio di thorium? Impossibile, improbabile, eppure ne ho visto la dimostrazione con i miei occhi.$B$BAvventurati nelle Blasted Lands e portami tre guance di snickerfang. Mentre cerchi le snickerfang, tieni d'occhio cinghiali e scorpok: per completare il saggio iniziale servono anche due polmoni di cinghiale devastato e una chela di scorpok.",
  obj = "Porta tre Snickerfang Jowls, due Blasted Boar Lungs e uno Scorpok Pincer a Bloodmage Drazial.",
  progress = "Hai un odore nauseante, $N. Sei $Gandato:andata; a zonzo per i campi di zolfo? E i miei componenti dove sono?!",
  reward = "Come ti senti, $N? Irradi l'aura della snickerfang — la tua forza non ha pari tra i mortali!$B$BPurtroppo, con i componenti che mi hai portato, ho potuto preparare abbastanza saggio per una sola compressa. Se te ne servirà un'altra, mi serviranno altri componenti.",
}
T[2582] = {
  title = "Furia delle Ere",
  desc = "Ah, $N, $Gbentornato:bentornata;. A quanto pare hai gradito l'effetto dell'infusione robusta e operativa, derivata dalla snickerfang. Sappi che, se l'effetto immediato è un'esplosione titanica di forza, gli effetti a lungo termine sul tuo spirito e sulla tua intelligenza potrebbero essere pericolosi.$B$BDetto questo, te ne serve ancora? Se sì, portami altre tre guance di snickerfang, due polmoni di cinghiale devastato e una chela di scorpok.",
  obj = "Porta tre Snickerfang Jowls, due Blasted Boar Lungs e uno Scorpok Pincer a Bloodmage Drazial.",
  progress = "Hai gli organi delle bestie?",
  reward = "Ecco a te! Ricorda, usala con parsimonia. Se te ne serve un'altra, torna da me quando avrai finito quella che hai adesso.",
}
T[2583] = {
  title = "La Vitalità di un Cinghiale",
  desc = "In queste terre devastate vivono due specie di cinghiale: il cinghiale dalla criniera di cenere e l'helboar.$B$BA quanto pare la resistenza di queste bestie le rende quasi immuni alle ferite, visto che per gli altri animali sono troppo difficili da uccidere e, di conseguenza, non valgono la fatica.$B$BServono altre analisi, $N. Se mi porterai tre polmoni di cinghiale devastato, due chele di scorpok e un cervello di basilisco, creerò un elisir divino dal residuo del saggio. Sarai la mia prima cavia!",
  obj = "Porta tre Blasted Boar Lungs, due Scorpok Pincers e un Basilisk Brain a Bloodmage Drazial.",
  progress = "Dove sono gli organi, $N!?",
  reward = "Lo spirito del cinghiale illumina il tuo essere, $N! Mi chiedo, ti credi invulnerabile quanto queste bestie?",
}
T[2584] = {
  title = "Spirito del Cinghiale",
  desc = "Quando ti ho somministrato l'elisir la prima volta, $N, ho capito che una o due dosi non avrebbero saziato il tuo appetito. Anche adesso ti vedo la fame negli occhi. Il preparato dà una dipendenza a cui, a quanto pare, non resistono nemmeno i più forti di volontà.$B$BE sia! Se ti serve altro cocktail di succo di polmoni, torna nella landa desolata e trovami tre polmoni di cinghiale devastato, due chele di scorpok e un cervello di basilisco.",
  obj = "Porta tre Blasted Boar Lungs, due Scorpok Pincers e un Basilisk Brain a Bloodmage Drazial.",
  progress = "Dove sono gli organi, $N!?",
  reward = "Devo avvertirti, $N, non provare a mescolare le formule che ho creato. Le proprietà chimiche dell'ultima formula che hai ingerito prevarranno sempre sugli incantamenti precedenti; di conseguenza, l'altra formulazione risulterà nulla.",
}
T[2585] = {
  title = "L'Assalitore Risoluto",
  desc = "Li hai mai osservati in battaglia, $N? Gli scorpok, intendo. Hai mai visto la grazia e l'agilità con cui si muovono? La risolutezza dei loro colpi?$B$BSe solo potessimo isolare in qualche modo quell'agilità e incapsularla, saremmo ricchi oltre ogni nostro... voglio dire... sarebbe una manna per la comunità scientifica.$B$BAiutami, $N, e ti concederò un campione del saggio.$B$BPer creare un campione stabile mi serviranno tre chele di scorpok, due ventrigli d'avvoltoio e un polmone di cinghiale devastato.",
  obj = "Porta tre Scorpok Pincers, due Vulture Gizzards e un Blasted Boar Lung a Bloodmage Drazial.",
  progress = "Dove sono gli organi, $N!?",
  reward = "Affascinante. Di tutti i saggi, questo è stato il più difficile da analizzare.$B$BPrendi un pizzico di questo sale residuo e mettilo sotto la lingua. Dovresti provare una leggera euforia, seguita da uno stato di agilità e rapidità senza precedenti.",
}
T[2586] = {
  title = "Sale dello Scorpok",
  desc = "Sei $Gvivo:viva;! Questa sì che è una buona notizia. Immagino che tu sia $Gtornato:tornata; per altro saggio di scorpok?$B$BMolto bene, $N, torna nella landa desolata e non farti rivedere finché non avrai raccolto tre chele di scorpok, due ventrigli d'avvoltoio e un polmone di cinghiale devastato.",
  obj = "Porta tre Scorpok Pincers, due Vulture Gizzards e un Blasted Boar Lung a Bloodmage Drazial.",
  progress = "Dove sono gli organi, $N!?",
  reward = "Ottimo lavoro, $N. Ecco un campione del saggio per te, mentre gli altri nove li userò per le mie ricerche.$B$BOgni volta che ti servirà altro saggio di scorpok macinato, torna da me e troveremo un accordo.",
}
T[2601] = {
  title = "Il Morso del Basilisco",
  desc = "Queste lande desolate pullulano di basilischi redstone, $N. Questi basilischi si sono adattati e hanno prosperato più di ogni altro animale selvatico della regione.$B$BLi ho osservati da lontano mentre cacciano e si dedicano alle loro attività quotidiane — queste bestie mostrano un modo di ragionare più complesso persino di quello di certi umanoidi.$B$BDevo studiare i loro cervelli!$B$BRecuperami dieci dei loro cervelli, $N. Il composto però non può essere completo senza due ventrigli d'avvoltoio che facciano da base alla soluzione.",
  obj = "Porta dieci Basilisk Brains e due Vulture Gizzards a Bloodmage Lynnore.",
  progress = "Sei $Gtornato:tornata; con gli organi richiesti?",
  reward = "È meraviglioso, $N! Quello che ti offro è un assaggio dei meccanismi interni del basilisco redstone.$B$BSe il composto sarà di tuo gradimento, se ne può sempre preparare dell'altro... a un certo prezzo.",
}
T[2602] = {
  title = "Mente Infallibile",
  desc = "La tua profonda concentrazione è già scemata? Bisogna fare altre ricerche!$B$BOh sì, il prezzo resta lo stesso, $N. Avventurati nelle terre devastate e torna da me con dieci cervelli dei redstone e due ventrigli d'avvoltoio.",
  obj = "Porta dieci Basilisk Brains e due Vulture Gizzards a Bloodmage Lynnore.",
  progress = "Sei $Gtornato:tornata; con gli organi richiesti?",
  reward = "Sì, sì, dammi un momento e avrai dell'altro composto pronto da consumare, $N.$B$BPrendilo... e $N, non provare a consumare questi preparati sperimentali in rapida successione. I risultati potrebbero essere disastrosi.",
}
T[2603] = {
  title = "Vigore dell'Avvoltoio",
  desc = "In queste terre devastate la morte ha davvero le ali, $R. Ho visto i sicari neri e i bonepicker banchettare sul cadavere di più di un esploratore caduto — a volte si nutrono delle carcasse più immonde e infestate dalle malattie. C'è da stupirsi, dunque, di come il loro organismo riesca a vincere la pestilenza che domina queste terre.$B$BAiutami nei miei studi, $N! Ventrigli mi servono! Per la base del preparato serviranno anche due guance di snickerfang.$B$BI tuoi sforzi saranno doppiamente ricompensati.",
  obj = "Porta dieci Vulture Gizzards e due Snickerfang Jowls a Bloodmage Lynnore.",
  progress = "Non farmi perdere tempo, $N. Non abbiamo niente di cui parlare, a meno che tu non abbia recuperato gli oggetti che ho richiesto.",
  reward = "Eccellente! Mi metto subito al lavoro. Chissà che non si trovi una cura per molti dei mali del mondo!$B$BAh sì, la tua ricompensa — naturalmente, se ti servirà altra gomma, torna da me e un altro compito ti verrà affidato.",
}
T[2604] = {
  title = "Dominio Spirituale",
  desc = "Vedo che il fuoco interiore si è affievolito. Diresti che l'euforia spirituale è durata un'ora?$B$BSe è altra gomma di ventriglio che desideri, sono altri ventrigli che mi servono. Torna nelle lande desolate, $N. Non ripresentarti finché non avrai recuperato dieci ventrigli e due guance.",
  obj = "Porta dieci Vulture Gizzards e due Snickerfang Jowls a Bloodmage Lynnore.",
  progress = "Non farmi perdere tempo, $N. Non abbiamo niente di cui parlare, a meno che tu non abbia recuperato gli oggetti che ho richiesto.",
  reward = "Forse un giorno riuscirò a isolare gli enzimi attivi di questo saggio e a ottenere un prodotto molto più efficace. Purtroppo dovrai accontentarti di quello che riesco a produrre per ora. Torna da me se ti servirà altra gomma di ventriglio.",
}
T[2605] = {
  title = "Il Goblin Assetato",
  desc = "Ho un'idea, sai. Ho sentito parlare di certe strane creature, i raccoglitori di rugiada, che vivono a sud-ovest... e che riescono a immagazzinare l'acqua in ghiandole speciali.$B$BPenso che, se riuscissi ad avere una di queste ghiandole, potrei creare una bevanda capace di placare la mia terribile sete! Pensi di potermi aiutare, $N?$B$BCerca il giardino di cactus, $N; è lì che troverai i raccoglitori di rugiada.",
  obj = "Raccogli una Laden Dew Gland e portala a Marin Noggenfogger a Gadgetzan.",
  progress = "Ti prego, dimmi che hai trovato i raccoglitori di rugiada?",
  reward = "Oh, magnifico! Dammela — fammela bere!",
}
T[2606] = {
  title = "Di Buon Gusto",
  desc = "Bleah! Questa roba ha un sapore tremendo! Tanti saluti a quell'idea...$B$BAspetta, come dici? Oh, lo so, lo so, secondo te non dovrei lasciar perdere questa roba. E va bene, allora.$B$BUhhhh, ho un'idea! Geniale! Porta questa rugiada alla mia amica Sprinkle — è una cuoca eccellente. Dille cosa stiamo combinando qui e che vogliamo farla andare giù un po' meglio.$B$BVoglio dire, se deve avere un sapore così cattivo, almeno dovrebbe dare un po' di botta... E io proprio non la sento...",
  obj = "Marin Noggenfogger vuole che tu parli con Sprinkle a Gadgetzan.",
  progress = "E così il vecchio Marin ne combina un'altra delle sue, eh? Di cosa è fatto questo intruglio?",
  reward = "Marin è un bravo tipo, non fraintendermi — solo un po'... eccentrico, direi.$B$BE ovviamente ha bisogno del mio aiuto, ancora una volta.",
}
T[2607] = {
  title = "Il Tocco di Zanzil",
  desc = "Sembra che tu abbia riportato più informazioni di quante me ne aspettassi perfino io. Questa sì che è una strana piega degli eventi, $N.$B$BUna cura? Mmh... Scendi in cantina e parla con il Dottor Mixilpixil — forse può aiutarti.",
  obj = "Parla con Doc Mixilpixil nella cantina dei Barracks.",
  reward = "Era ora! Metti il formaggio sul tavolo e fila via. Osborne ti pagherà all'uscita.",
  en_title = "The Touch of Zanzil",
  en_obj = "Speak with Doc Mixilpixil in the cellar of the Barracks.",
}
T[2608] = {
  title = "Il Tocco di Zanzil",
  desc = "Oh cielo, sembri la morte in persona. Correggo — io la morte l'ho vista, e tu sei $Gmesso:messa; peggio. Tu, $Gsignore:signorina;, saresti quello che la morte ha tossito fuori alla sua ultima visita medica.$B$BAh! Hai sentito, Noarm? Scrivitela!$B$B*Coff* Ehm, sì, per poterti aiutare dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay down quando sei $Gpronto:pronta; per il trattamento, $N.",
  obj = "Usa /Lay down per farti visitare da Doc Mixilpixil. Come può trovare la cura se non trova la causa?",
  progress = "Quando sei $Gpronto:pronta; per la visita, sdraiati a terra con /lay down e comincerò la flebotomia.",
  reward = "Dammi un momento per consultarmi con i miei colleghi, $N. Dottor Montgomery, Signor Noarm, a consulto!",
  en_title = "The Touch of Zanzil",
  en_obj = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?$B",
}
T[2609] = {
  title = "Il Tocco di Zanzil",
  desc = "Siamo tutti d'accordo, $N. Hai la 'ite'.$B$BPer fortuna, ho una cura per la 'ite'.$B$BEcco cosa mi serve: un mazzo di fiori di campo semplici, una fiala piombata, un tubo di bronzo e, ultimo ma non per importanza, un rocchetto di filo di seta verde chartreuse chiaro. Ol' Emma me ne ha lasciato uno a 'The Finest Thread'. Trovi la bottega lungo i canali.$B$BOra sbrigati, $N, e cerca di non toccare nessuno finché non sarai $Gguarito:guarita;. Ah, e il Dottor Montgomery dice che hai bisogno di una doccia — parole sue, non mie.",
  obj = "Porta a Doc Mixilpixil un mazzo di Simple Wildflowers, un Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread. La 'ite' non guarisce da sola, $Ggiovanotto:signorina;.",
  progress = "Se vuoi guarire dalla 'ite', dovrai impegnarti più di così, $N. Dove sono i reagenti per la cura?",
  reward = "Che cosa sto facendo? Che cosa ti sembra che stia facendo? Sto preparando una cura per la tua 'ite'! E adesso non prendertela con me, $N!$B$BAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e tornerai $Gcome nuovo:come nuova;.",
  en_title = "The Touch of Zanzil",
  en_obj = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ",
}
T[2621] = {
  title = "Il Disonorato",
  desc = "Rimpianto. È tutto quello che mi resta. Una sola decisione sbagliata, e tante conseguenze orribili. Se solo avessi aspettato quegli ordini. Forse avrebbero descritto gli orrori che ci aspettavano in quelle terre maledette! Forse dovevano assegnarci a un altro incarico? In fin dei conti, è stata colpa mia. È stata tutta colpa mia.$B$BE così eccomi qui, in attesa di ordini. Devo sapere. Devo avere quegli ordini.$B$BIl Comandante dei Dispacci Ruag si trova a Stonard. Trovalo e scopri che fine hanno fatto gli ordini.",
  obj = "Parla con Dispatch Commander Ruag a Stonard.",
  reward = "Thrall's Grasp... Quella storia ce l'ho ancora viva nella mente.$B$B<Il Comandante Ruag scuote la testa.>$B$BUna cosa terribile, quella che è successa a quel reggimento. L'Orda ha perso alcuni dei suoi soldati migliori quando quel battaglione è stato distrutto.",
}
T[2622] = {
  title = "Gli Ordini Scomparsi",
  desc = "Gli ordini? Cosa te ne faresti mai degli ordini?$B$BCosa vorresti insinuare, $N? Certo che ho trasmesso quegli ordini! I soldati a cui li avevo affidati sono finiti in un'imboscata dei murloc, che li hanno massacrati di botte. Ne è sopravvissuto uno solo, se così si può dire. Riesce a malapena a parlare, non può camminare, e bisogna nutrirlo con un tubo. Se vuoi sapere che fine hanno fatto quegli ordini, parla con Bengor. Sono sicuro che è qui da qualche parte... e, $N, sta' $Gattento:attenta; a dove ficchi il naso — potrebbero staccartelo a morsi.",
  obj = "Parla con Bengor.",
  reward = "Oratore delle pa... palu... paludi...",
  en_title = "The Missing Orders",
  en_obj = "Speak to Bengor.",
}
T[2623] = {
  title = "L'Oratore delle Paludi",
  desc = "Ordini dati dal comandante dei dispacci. Noi presi... presi ordini. Verso Blasted Lands, agguato.$B$BMurloc... Tanti murloc... Uno chiamato Oratore delle Paludi. Preso ordini da mie mani mentre lancia entrava nel cranio. Est... grotta...$B$B<Bengor sviene.>",
  obj = "Recupera i Warchief's Orders e riportali al Fallen Hero of the Horde.",
  progress = "In attesa di ordini.",
  reward = "È peggio di quanto immaginassi. A diciannove dei miei uomini si sarebbe potuta risparmiare l'agonia che hanno patito. Se solo non avessi agito in modo così irrazionale.$B$BDevi aiutarli, $N! Io non posso fare niente.",
  en_title = "The Swamp Talker",
  en_obj = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.",
}
T[2641] = {
  title = "L'Ingrediente Segreto di Sprinkle",
  desc = "Quand'ero piccola, a cucinare era sempre mia sorella. Un orrore! Certi suoi intrugli riuscivo a malapena a mandarli giù — finché non ho scoperto quello che mi piace chiamare il mio ingrediente \"segreto\"! Aggiungilo a qualsiasi cosa, e... WOW! Diventa buonissima!$B$BCos'è, mi chiedi? È un fungo che si chiama Tragan Viola. Se vuoi che ti aiuti a trasformare questa brodaglia dal sapore orrendo in qualcosa di commestibile, vai nelle Hinterlands e cerca un laghetto.$B$BOh, e ricorda, il Tragan Viola si trova solo sott'acqua.",
  obj = "Sprinkle a Gadgetzan vuole che tu raccolga un Violet Tragan e glielo riporti.",
  progress = "Sotto le acque di quel lago — è l'unico posto in cui si trova il Tragan Viola. Spero che tu sia $Gbravo:brava; a trattenere il respiro!",
  reward = "È proprio quello, $N!$B$BHa un aspetto così buono che quasi quasi... Ahah, ci sei $Gcascato:cascata;!",
}
T[2661] = {
  title = "Consegna per Marin",
  desc = "Ecco la Polvere Viola, $N. Portala a Marin e digli che mi deve un favore!",
  obj = "Sprinkle vuole che porti la Violet Powder a Marin Noggenfogger, a Gadgetzan.",
  progress = "Oh, $N, finalmente sei $Gtornato:tornata;. Cos'hai portato?",
  reward = "Polvere Viola, eh? Proviamola — di certo non può peggiorare le cose, questo è sicuro!",
}
T[2662] = {
  title = "Elisir di Noggenfogger",
  desc = "E ora mescoliamo questa polvere con la rugiada.$B$BTorna a parlarmi fra un minuto... quando avrò perfezionato il favoloso Elisir di Noggenfogger!",
  obj = "Marin Noggenfogger vuole che torni a parlargli dopo che avrà creato il suo elisir.",
  reward = "Bevi questo! È assolutamente meraviglioso!!!$B$BLo sapevo che ne ero capace... Oh, grazie ancora dell'aiuto, $N, ma per favore, mettiti un po' di lato, ti dispiace? Mi stai intralciando gli affari! Farò i milioni con il favoloso Elisir di Noggenfogger, i milioni!$B$BCome dici? Sprinkle dice che le devo un favore? Oh, quella Sprinkle, che burlona!",
}
T[2681] = {
  title = "Le Pietre che ci Legano",
  desc = "Tu $Gsolo:sola; non basti per sconfiggere le forze di Razelikh e dei suoi subordinati.$B$BRaduna un gruppo di avventurieri all'altezza e libera i miei uomini dalla loro tortura eterna! Diciotto pietre devi frantumare.$B$BCombatti con tutte le tue forze e muori con onore, $N.",
  obj = "Libera nove Servants of Razelikh, tre Servants of Sevine, tre Servants of Allistarj e tre Servants of Grol. Torna dal Fallen Hero of the Horde quando avrai portato a termine il compito. Devi restare vicino alle pietre, altrimenti il processo fallirà.",
  progress = "Non è un compito facile, $N. Non arrenderti!",
  reward = "Ce l'hai fatta, $N! Quelle povere anime torturate possono finalmente riposare.$B$BIl nostro lavoro non è ancora finito, $N. Abbiamo molto di cui parlare e ancora di più da compiere.",
}
T[2701] = {
  title = "Eroi di un Tempo",
  desc = "Ti prego, prendi da qui un cimelio di un tempo. A noi quell'oggetto non serve più.$B$BChe ti sia utile nella tua lotta contro la legione.",
  obj = "Apri il forziere e ritira la tua ricompensa.",
  reward = "Per un attimo lo scintillio e il luccichio ti accecano.",
}
T[2702] = {
  title = "Eroi di un Tempo",
  desc = "Mi hai onorato con la tua nobiltà e il tuo eroismo, $N.$B$BHai onorato anche loro...",
  obj = "Parla con Corporal Thund Splithoof.",
  reward = "È vero, hai onorato tutti noi. I nostri ringraziamenti da soli non bastano.",
}
T[2721] = {
  title = "Kirith",
  desc = "Mentre un capitolo della tua avventura si chiude, un altro comincia, $N.$B$BUno dei miei uomini manca ancora all'appello, disperso da qualche parte nelle Blasted Lands. Parlo del Tenente Kirith, naturalmente.$B$BCome ti avevo già detto, Allistarj ci ha imprigionati e torturati entrambi, ma al povero Kirith la forza di volontà è venuta meno. Dalla mia gabbia sentivo gli esperimenti; le urla di tormento risuonavano nelle gallerie della caverna. Da allora di Kirith non ho più visto né saputo nulla.",
  obj = "Scopri che fine ha fatto Lieutenant Kirith.",
  reward = "Trebor? Ti ha mandato Trebor?",
}
T[2741] = {
  title = "Il Super Egg-O-Matic",
  progress = "Il Super Egg-O-Matic è l'ultima delle invenzioni di Curgle Cranklehop. È un macchinario davvero notevole.$B$BMentre ti avvicini al pannello di controllo, il Super Egg-O-Matic si mette a scoppiettare all'impazzata.",
  reward = "Metti l'uovo di ippogrifo nella macchina. Segue una serie di bip, insieme a strani rumori meccanici.$B$BA quanto pare l'Eggometer ha pesato, misurato e impacchettato il tuo uovo. Questo sì che è un servizio rapido!",
}
T[2742] = {
  title = "Rin'ji è in Trappola!",
  desc = "Ehi, $R!$B$BRin'ji perso ascia ed è stato catturato! Per favore, aiuta Rin'ji a scappare. Me sa che $Gun:una; $R come te non ama quelli come Rin'ji, ma Rin'ji supplica! Deve uscire da qui!$B$BHa qualcosa per $Gil:la; $R gentile se $Glui:lei; aiuta Rin'ji a uscire da qui...$B$BRin'ji nasconde qualcosa di segreto alle Scogliere Altosguardo.",
  obj = "Scorta Rin'ji fuori dal Padiglione Quel'Danil, poi trova il suo segreto nascosto alle Overlook Cliffs, a est.",
  progress = "Rin'ji ha paura!",
  reward = "Questa tavoletta troll dev'essere il \"segreto\" di cui parlava Rin'ji.$B$BÈ coperta di strani segni e non riesci a decifrare cosa dice.",
}
T[2743] = {
  title = "Il Favore delle Tenebre",
  desc = "Non usiamo mezzi termini, $R; il mio tempo qui è limitato.$B$BDevi distruggere la triade del potere che protegge il signore dei demoni, Razelikh. Non sarà semplice come liberare un'anima dannata.$B$B<Kirith sogghigna.>$B$BVedi, ognuno dei sottoposti di Razelikh porta al collo un terzo di un amuleto creato da Razelikh stesso. Lo stesso amuleto che ti servirà per evocare l'arcidemone.$B$BTorna da Trebor e digli cosa serve per evocare Razelikh. Lui saprà darti altre istruzioni.",
  obj = "Torna dal Fallen Hero of the Horde con quello che hai scoperto.",
  reward = "Il signore dei demoni dà prova di un'astuzia calcolata quasi quanto la sua brutalità, $N.",
}
T[2744] = {
  title = "Il Cacciatore di Demoni",
  desc = "La triade è protetta da Razelikh.$B$BIn cambio della loro servitù, Razelikh ha concesso a ciascuno di loro un potere quasi illimitato all'interno delle Blasted Lands. Ogni pezzo dell'amuleto è in sintonia con la forza vitale di chi lo possiede e gli dona l'immortalità. Finché restano nelle Blasted Lands non possono essere uccisi, e la loro vita si prolunga fino alla fine dei giorni.$B$BC'è qualcuno che forse può esserti di ulteriore aiuto, $N. Va' ad Azshara e trova il cacciatore di demoni, Loramus Thalipedes. Cerca sulle isole.",
  obj = "Parla con Loramus Thalipedes ad Azshara.",
  progress = "Che ci fai qui?",
  reward = "Ti aiuterò. Anche se non credo che tu capisca fino in fondo cosa stai affrontando.",
}
T[2745] = {
  title = "Infiltrarsi nel Castello",
  desc = "Hmm, una storia interessante, e non da prendere alla leggera. Sì, posso aiutarti, ma dovrai dispensare una forma di giustizia che non è... legale, se vuoi andare fino in fondo.$B$BBisogna occuparsi di Lescovar e Marzon, e in fretta. Pensi di essere capace di una cosa del genere?$B$BDecidi tu. Se è così, allora corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. È da un paio di settimane che tiene d'occhio Lescovar. Dovrebbe riuscire ad aiutarti a chiudere questa faccenda.",
  obj = "Parla con Tyrion, nel Castello di Stormwind.",
  reward = "Ma che...?! Non arrivarmi alle spalle così! E abbassa la voce! In nome dell'Ombra, che ti salta in mente di arrivarmi alle spalle di soppiatto? Non vedi che ho da fare, $Gbrutto sciocco:brutta sciocca;?$B$BCome sarebbe, cosa sto facendo? Sto aspettando che si apra il prossimo Portale Oscuro, tu che diamine credi che stia facendo? Di' quel che hai da dire e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da mantenere.",
  en_title = "Infiltrating the Castle",
  en_obj = "Speak to Tyrion in Stormwind Castle.",
}
T[2746] = {
  title = "Oggetti di una Certa Importanza",
  desc = "Trias vuole anticipare un po' i tempi, eh? Va bene, si può fare, ma io non sono pronto. E sappi una cosa: la parte difficile la faccio io, ma sei tu $Gquello:quella; che si sporcherà le mani, chiaro? Bene.$B$BAllora, prima di poter mettere in atto il mio piano ho bisogno che tu mi procuri un po' di cose. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.$B$BPortami un po' di silk e un paio di mele. Per il silk fai tu, ma la piccola fattoria di Clara appena fuori città ha mele della misura perfetta.",
  obj = "Porta 3 Silk Cloth e 2 Clara's Fresh Apple a Tyrion, a Stormwind.",
  progress = "Sono un paio di settimane che tengo d'occhio Lescovar. Trias non si è mai fidato di lui, ma non sospettavamo che avesse a che fare con la Defias Brotherhood. Seguivamo piste che lo legavano al Martello del Crepuscolo. In ogni caso è diventato un pericolo più grande di quanto questa città possa affrontare, ed è qui che entriamo in gioco noi.$B$BProcurami quelle cose e potremo mettere in atto il mio piano.",
  reward = "Queste vanno benissimo, $N. Ottimo lavoro.$B$BIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... grazie alla Luce, mi sono appena fatto fare una borsa di seta da un amico sarto. Mi stava finendo lo spazio, con tutta la roba che mi porto dietro.$B$BPrima che Spybot entri, mettiamo a punto i dettagli, così sai cosa devi fare.",
  en_title = "Items of Some Consequence",
  en_obj = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.",
}
T[2747] = {
  title = "Un Uovo Straordinario",
  progress = "Ho visto pochissime uova recuperate a Feralas in condizioni straordinarie. Sono uova del tipo più raro...",
  reward = "Ma guarda, ne hai uno — incredibile!$B$BSpero che ricorderai sempre il bene che hai fatto oggi.",
}
T[2748] = {
  title = "Un Uovo Buono",
  progress = "Un uovo buono è un uovo che, in condizioni ideali, si schiuderà libero dagli effetti malefici degli incantesimi degli ogre Gordunni.",
  reward = "Molto bene, $N. Manderò quest'uovo a Darnassus, dove spero che si schiuda presto!$B$BTi prego, accetta questo in segno della mia gratitudine.",
}
T[2749] = {
  title = "Un Uovo Comune",
  progress = "Le uova di ippogrifo comuni si schiudono più o meno una volta su due. Facciamo del nostro meglio per accudirle e, con un po' di fortuna, si schiuderanno.",
  reward = "Allora, hai trovato un uovo comune, $N? Dammelo, per favore... E possiamo solo sperare in bene.$B$BNon ho molto, ma ti prego di accettare questa ricompensa. Se mai dovessi ritrovarti a Feralas, sappi che io sono sempre qui a prendere le uova che troverai laggiù.",
}
T[2750] = {
  title = "Un Uovo Guasto",
  progress = "Queste sono le uova che non si possono salvare — non si schiuderanno mai.",
  reward = "Temo di avere brutte notizie per te, $N. Per quest'uovo è ormai troppo tardi. Posso prenderlo io, così sarà smaltito come si deve.$B$BNon scoraggiarti, ti prego; non possiamo salvarle tutte. Se ti ritrovi di nuovo a Feralas, riprova, mi raccomando. Porta un altro uovo per il Super Egg-O-Matic!",
}
T[2751] = {
  title = "Bastioni Barbarici",
  desc = "Venti generazioni di Omosh hanno impugnato questo martello, $N. Centomila tonnellate di metallo abbiamo plasmato. Tragicamente, tutto finisce con Orokk, fallimento degli Omosh: senza parenti e incapace di generare figli.$B$BNon posso lasciare che le ricette segrete degli Omosh muoiano con me! Qualcuno deve portare avanti l'eredità, Omosh o no!$B$BDimostra a Orokk di essere capace, $N. Porta a Orokk quanto segue: due bracciali di bronzo decorato, due spadoni di bronzo e due artigli affilati. Portali a Orokk e andremo avanti.",
  obj = "Porta due Patterned Bronze Bracers, due Bronze Greatswords e due Sharp Claws a Orokk Omosh, a Orgrimmar.",
  progress = "Bronzo, $N! Altro bronzo!!",
  reward = "La stirpe si spegnerà, ma forse la leggenda degli Omosh continuerà!$B$BHai dimostrato di essere $Gun fabbro:una fabbra;, $N. Per il fabbro la ricompensa è la soddisfazione di vedere le proprie armi e armature ricoperte del sangue dei nemici!$B$BChe i pettorali che creerai per le generazioni a venire siano intrisi del sangue dei tuoi nemici!",
}
T[2752] = {
  title = "Sugli Spallacci di Ferro",
  desc = "Orokk vede l'entusiasmo nei tuoi occhi, $N. Come una spugna assorbi la saggezza degli Omosh.$B$BTre lezioni insegnerò!$B$BTorna all'incudine, assorbi il calore della forgia, crea per Orokk quattro asce da battaglia di bronzo e quattro martelli da guerra di bronzo. Solo allora imparerai a conoscere lo spallaccio di ferro.",
  obj = "Porta quattro Bronze Battle Axes e quattro Bronze Warhammers a Orokk Omosh, a Orgrimmar.",
  progress = "Mostrami la tua dedizione, $R.",
  reward = "Rendi fiero Orokk, $N. Leggi, impara a conoscere gli spallacci di ferro!",
}
T[2753] = {
  title = "Calpestati Sotto i Piedi",
  desc = "Solo altre due lezioni insegnerà Orokk, $N. I muscoli ti fanno male, lo so, ma vai avanti per gli Omosh!$B$BPorta a Orokk quattro elmi di ferro verde, quattro bracciali di ferro verde e due gambiere di ferro verde — in cambio tu impari e i tuoi nemici soffrono!",
  obj = "Porta quattro Green Iron Helms, quattro Green Iron Bracers e due Green Iron Leggings a Orokk Omosh, a Orgrimmar.",
  progress = "I loro crani si spaccheranno sotto il peso dei tuoi stivali!",
  reward = "Ricordi a Orokk suo nonno, il Capo Gorokk degli Omosh! Leggi, impara a conoscere lo stivale di ferro.",
}
T[2754] = {
  title = "Corna della Frenesia",
  desc = "L'ultima lezione Orokk ti insegna, $N. Alla sacra incudine e alla forgia tu torni! Porta a Orokk due magli di ferro solido, due stivali di bronzo argentato e due guanti di bronzo argentato.$B$BGuarda la paura nei loro occhi mentre ti avvicini!",
  obj = "Porta due Solid Iron Mauls, due Silvered Bronze Boots e due Silvered Bronze Gauntlets a Orokk Omosh, a Orgrimmar.",
  progress = "Fai vedere al ferro chi comanda, $N!",
  reward = "Stupefacente! Hai imparato la via degli Omosh, $N!",
}
T[2755] = {
  title = "Gioie degli Omosh",
  desc = "Orokk non piange, $N. Fuliggine è in occhio.$B$B<Orokk si asciuga una lacrima.>$B$BC'è un ultimo segreto della famiglia Omosh che Orokk ti insegnerà. Orokk morirà felice, grazie a $N.$B$BImpara danza della gioia degli Omosh e poi impari pugno di ferro!",
  obj = "Guarda e impara la Danza della Gioia degli Omosh.",
  reward = "<Orokk ansima.>$B$BÈ passato moltissimo tempo dall'ultima volta che Orokk ha fatto la danza della gioia degli Omosh. Ora impara, $N!",
}
T[2756] = {
  title = "Le Vecchie Usanze",
  desc = "Al tempo delle leggende, Aturk schiacciava i crani dei suoi nemici e ne macinava le ossa in una polvere fine, da usare nel filamento. Quei giorni sono passati da un pezzo, $R. Il Capoguerra chiede la pace fra i clan. I vecchi nemici ormai li si osserva soltanto, con occhi diffidenti!$B$BIncredibile, lo so, ma tale è la volontà di Thrall.$B$BBasta lamenti! Sei qui per imparare, e imparerai! Portami quattro pettorali d'acciaio e quattro elmi d'acciaio e avrai un assaggio di guerra!",
  obj = "Porta quattro Steel Breastplates e quattro Steel Plate Helms ad Aturk the Anvil, a Orgrimmar.",
  progress = "Aturk, come il tempo, non aspetta nessuno! Sbrigati, $Gsciocco:sciocca;!",
  reward = "A quanto pare sei solo un altro docile lemming del Capoguerra, $N. Che delusione.$B$BQuanto desidero una morte gloriosa sul campo di battaglia. E invece sono bloccato qui, per ordine di Thrall, a insegnare ai poppanti come si fabbrica! Guarda e impara, $Gbambino:bambina;!",
}
T[2757] = {
  title = "Booty Bay o Niente!",
  desc = "Senti, $Gragazzo:ragazza;, standotene qui in giro non imparerai niente.$B$BConosco uno che conosce uno. Sta sempre dalle parti della fucina di Booty Bay. Se gli mostri questo distintivo, ti dirà tutto sul mithril.$B$BAllora, che ne dici? Lascia 'sta roba da bambini ai poppanti col pannolino, $N — è ora di andare avanti.$B$BSe ti interessa, si chiama McGavan. Mostragli questo monile e riconoscerà il tuo impegno.",
  obj = "Parla con McGavan a Booty Bay.",
  progress = "Siete una razza rara, voialtri, $Gamico:amica;. Fammi vedere quel distintivo.",
  reward = "Per i peli sulla schiena di Blackhoof — finalmente, $Guno degno:una degna; del Mithril Order!",
}
T[2758] = {
  title = "Le Origini della Forgiatura",
  desc = "Quando avevo più o meno la tua età, un nano di nome Galvan mi prese sotto la sua ala e mi addestrò nell'arte del forgiatore di armature. Prima di partire per Booty Bay, mi fece promettere di addestrare tutti quelli che avessero il desiderio e la determinazione di progredire nel mestiere della forgiatura — ed eccomi qui — tanti anni dopo.$B$BQuindi, ora tocca a te imparare qualcosina. Fammi sei bracciali di scaglie d'oro e imparerai da dove viene la forgiatura, $N.",
  obj = "Porta sei Golden Scale Bracers a Hank the Hammer, a Stormwind.",
  progress = "Che sia tu $Gil prossimo pupillo:la prossima pupilla; di Galvan?",
  reward = "Molto bene, $N! Ascolta e impara.$B$BLa forgiatura non viene mai da qui! <Hank indica il suo martello.>$B$BLa forgiatura non viene mai da qui! <Hank indica l'incudine.>$B$BLa forgiatura viene solo da qui! <Hank si indica il cuore.>$B$BE ora conosci l'origine della forgiatura.",
}
T[2759] = {
  title = "Alla Ricerca di Galvan",
  desc = "Anche se Galvan ha lasciato Booty Bay molti anni fa, alcuni membri dell'ordine sono rimasti in città, nella speranza di trovare un giorno qualcun altro degno dell'insegnamento di Galvan.$B$BPrendi questo distintivo e presentalo a McGavan, a Booty Bay.$B$BSe arrivi davvero fin lì, saprà che sei $Gdegno:degna;. Io ho fiducia, $N!",
  obj = "Parla con McGavan a Booty Bay.",
  progress = "Siete una razza rara, voialtri, $Gamico:amica;. Fammi vedere quel distintivo.",
  reward = "Per i peli sulla schiena di Blackhoof — finalmente, $Guno degno:una degna; del Mithril Order!",
}
T[2760] = {
  title = "Il Mithril Order",
  desc = "La maggior parte delle nostre reclute a Booty Bay non ci arriva mai, $N. Il luccichio del distintivo basta a scatenare la brama di bottino anche nel più saldo dei fabbri. Sciocchi che sono, perché il distintivo è una goccia nel mare in confronto alla ricchezza di oggetti che vedrai!$B$BTrova Galvan the Ancient e mostragli questa spilla. Abita molto più a nord, fra Zul'Gurub e il tumulo degli ogre Mosh'Ogg.",
  obj = "Parla con Galvan the Ancient nella Stranglethorn Vale.",
  progress = "Salute! Vieni più vicino; mostra a Galvan cos'hai.",
  reward = "Ah, molti anni sono passati dall'ultima volta che qualcuno è stato degno dell'iniziazione del Mithril Order. Cominceremo ora!",
}
T[2761] = {
  title = "Metti a Fondere, Togli dal Fuoco",
  desc = "Molti fabbri credono che estrarre e forgiare siano due mestieri separati, indipendenti l'uno dall'altro; ma può esistere la forgiatura senza l'estrazione? Aha — è impossibile! Il fabbro esperto dev'essere anche un minatore esperto.$B$BDimostra a Galvan di esserne capace, $N. Portami quaranta barre di ferro e quaranta barre di mithril. In cambio, Galvan ti insegnerà l'arte dei pantaloni di mithril decorati!",
  obj = "Porta quaranta Mithril Bars e quaranta Iron Bars a Galvan the Ancient, a Stranglethorn.",
  progress = "Dopo tanto scavare, i muscoli ti si gonfiano e hai tutto il corpo indolenzito!",
  reward = "La tua etica del lavoro è impeccabile, $N! Cominci a capire la mineralogia secondo Galvan! Prendi questo e impara tutto quello che può insegnarti.",
}
T[2762] = {
  title = "Il Grande Ingannatore d'Argento",
  desc = "Si dice che il verargento sia più forte e più resistente del mithril. Galvan non contesta questo giudizio sui minerali, ma a dispetto del nome, il verargento di vero non ha niente! Il mithril è un minerale di gran lunga più nobile! AH! Comunque sia, per questa lezione dovrai trovare il grande ingannatore d'argento, $N.$B$BPortami quaranta barre di mithril e cinque barre di verargento. In cambio ti verrà insegnato il segreto dei guanti di mithril decorati e, cosa più importante, imparerai che il verargento è un bugiardo!",
  obj = "Porta quaranta Mithril Bars e cinque Truesilver Bars a Galvan the Ancient, a Stranglethorn.",
  progress = "Dopo tanto scavare, i muscoli ti si gonfiano e hai tutto il corpo indolenzito!",
  reward = "È una padrona crudele, non trovi, $N? Parlo del verargento, naturalmente. Già, Galvan ha passato più di dieci anni fra le montagne di Alterac per imparare questa lezione. Prendi questo e impara tutto quello che può insegnarti!",
}
T[2763] = {
  title = "L'Arte dell'Infusione",
  desc = "La raccolta delle gemme preziose è della massima importanza per il nostro mestiere, $N. Poche gemme sono più preziose del citrino. Le proprietà magiche che infondiamo nei nostri manufatti vengono amplificate enormemente dalla presenza del citrino.$B$BPer questa lezione rinforzeremo quaranta barre di mithril con quattro citrini. Il risultato sarà una migliore comprensione della gemmologia magica e la conoscenza necessaria per creare gli spallacci di mithril decorati.",
  obj = "Porta quaranta Mithril Bars e quattro Citrines a Galvan the Ancient, a Stranglethorn.",
  progress = "Dopo tanto scavare, i muscoli ti si gonfiano e hai tutto il corpo indolenzito!",
  reward = "Si fa fatica a staccare gli occhi dal suo splendore, $N. Già, il citrino è una gemma magnifica.$B$BFai attenzione e impara cosa può insegnarci una scoperta del genere!",
}
T[2764] = {
  title = "Il Miglior Allievo di Galvan",
  desc = "Se sei $Gpronto:pronta; a concludere il tuo addestramento con Galvan, dovresti metterti in viaggio per Gadgetzan.$B$BLì troverai il mio allievo migliore: Trenton Lighthammer. Ha molto da insegnarti sull'arte del mithril decorato. Altrimenti, resta qui e impara!$B$BAh, Gadgetzan è a Tanaris, naturalmente!",
  obj = "Parla con Trenton Lighthammer a Gadgetzan.",
  reward = "Ti manda Galvan l'Antico??$B$B<Trenton si inchina.>$B$BÈ un grande onore conoscere $Gun altro allievo:un'altra allieva; del maestro!",
}
T[2765] = {
  title = "Fabbro Esperto!",
  desc = "Quando sei $Gvenuto:venuta; da me la prima volta, sapevo che saresti $Gdiventato:diventata; $Guno dei miei allievi migliori:una delle mie allieve migliori;! Senza esitare, hai ceduto a McGavan un monile di un certo potere. L'hai fatto solo per potermi incontrare. Una fede così cieca e una tale dedizione al mestiere meritano una ricompensa.$B$BHai raggiunto il grado di esperto nella forgiatura, $N. Raccogline i frutti!",
  obj = "Ritira la tua ricompensa da Galvan the Ancient!",
  reward = "È giusto che tu riceva un monile ben più potente di quello che hai sacrificato per arrivare qui. Goditelo in salute, $N.",
}
T[2766] = {
  title = "Trova OOX-22/FE!",
  desc = "Hai scoperto una specie di strano congegno di metallo a forma di uovo. Armeggi con una delle sue manopole e l'uovo prende vita: si apre e si trasforma in una specie di aggeggio robotico gnomesco! Dall'interno dell'uovo robotico gracchia una voce.$B$B\"Mi chiamo Oglethorpe Obnoticus, e il mio robot a ritorno automatico si è schiantato! Ti ricompenserò se lo recuperi; ti prego, porta questo segnalatore al robot!\"$B$B\"Ho calcolato per te le coordinate del robot: è in una grotta vicino a Valsfregiata!\"",
  obj = "Porta l'OOX-22/FE Distress Beacon al robot a ritorno automatico di Oglethorpe, in una grotta vicino a Feral Scar Vale.",
  progress = "Sembra che tu abbia scoperto il relitto di... un pollo robotico? La voce dall'interno dell'uovo gracchia di nuovo:$B$B\"Sì, ottimo lavoro! Questo è proprio il mio robot a ritorno automatico, anche se i miei sensori indicano che ha bisogno di una spinta per ripartire prima di poter tornare in volo a Booty Bay per le riparazioni. Coraggio, metti il segnalatore dentro il rover — al resto penserà il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot a ritorno automatico.$B$BDall'interno del robot si sentono ronzii e fruscii mentre cerca di rimettersi in piedi. Quando il robot prende vita, si sente di nuovo la voce di Oglethorpe, ma ora dall'interno del robot:$B$B\"OOX-22/FE almeno funziona, ma ha bisogno di riparazioni importanti! È troppo pesante perché tu possa portarlo... ma credo di avere un'idea. Te la senti di sorvegliarlo ancora un po'?\"",
  en_title = "Find OOX-22/FE!",
  en_obj = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.",
}
T[2767] = {
  title = "Salva OOX-22/FE!",
  desc = "La voce dello gnomo gracchia di nuovo dal robot:$B$B\"Devo portare OOX-22/FE in un posto aperto e sicuro, così potrà cominciare una lunga procedura di decollo. Ha un occultamento incorporato, ma io, da qui, ho bisogno di tempo per rimetterlo in funzione. Scorta il robot da dove si trova ora fino, diciamo, al molo lungo la Costa Dimenticata! Dovrebbe essere il posto perfetto, e un tragitto abbastanza lungo, per riattivare tutto!\"$B$B\"Scortalo al molo sano e salvo, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus — passo e chiudo!\"",
  obj = "Scorta OOX-22/FE fino al molo lungo la Forgotten Coast, poi fai rapporto a Oglethorpe Obnoticus, a Booty Bay.",
  progress = "Sì, sono Oglethorpe Obnoticus, maestro inventore al tuo servizio! Allora, c'è qualcosa in cui posso aiutarti?",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-22/FE! Non so nemmeno da dove cominciare per ringraziarti del tuo aiuto! La mia serie di robot a ritorno automatico ha bisogno di altro sviluppo, ma recuperandolo mi hai risparmiato innumerevoli ore di ricostruzione, e anche parecchie monete d'oro in costi di fabbricazione!$B$BTi prego, scegli uno di questi oggetti che ho. Grazie ancora per il tuo generoso aiuto, $N: io e i miei robot siamo in debito con te!",
  en_title = "Rescue OOX-22/FE!",
  en_obj = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.",
}
T[2768] = {
  title = "La Verga Divino-matic",
  desc = "Sergeant Bly mi ha derubato! Aveva detto che me la prendeva solo in prestito, ma mi ha rubato la mia preziosa verga divino-matic!! Senza quella verga come faccio a sapere dove scavare nuovi pozzi d'acqua??$B$BTrova Bly e riportami la mia verga! Ho sentito che ha portato la sua banda di avventurieri di dubbia fama a caccia di tesori a Zul'Farrak, a ovest. Scommetto che lo troverai lì.$B$BSperiamo che i troll l'abbiano già sistemato, perché se dovrai batterti con lui per la verga, ti aspetta uno scontro serio.",
  obj = "Porta la Divino-matic Rod a Chief Engineer Bilgewhizzle, a Gadgetzan.",
  progress = "Hai trovato Sergeant Bly? Hai preso la mia verga divino-matic?",
  reward = "L'hai trovata! Ben fatto, $N! Hai dovuto combattere con Bly per averla? Spero che tu abbia steso lui e la sua banda come si deve!",
  en_title = "Divino-matic Rod",
  en_obj = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",
}
T[2769] = {
  title = "I Fratelli Brassbolts",
  desc = "Hai conosciuto i fratelli Brassbolts? Sono laggiù nelle Shimmering Flats, in Kalimdor, a gareggiare con la loro auto a razzo contro i goblin. Di solito vincono, e non c'è da stupirsi — l'auto dei goblin esplode così spesso che non taglia quasi mai il traguardo!$B$BMa anche così, i fratelli Brassbolts cercano sempre nuovi modi per far andare più veloce la loro auto, e Wizzle mi ha detto che gli serve un componente molto raro per il suo prossimo esperimento.$B$BProbabilmente ha bisogno di aiuto per procurarsi quel pezzo. Parla con lui e scoprilo.",
  obj = "Parla con Wizzle Brassbolts, nelle Shimmering Flats.",
  reward = "Ah, vuoi aiutarmi? Fantastico!$B$BC'è un pezzo che voglio per un esperimento a cui sto lavorando, e mi serve $Gun:una; $C $Gcoraggioso:coraggiosa; come te che mi aiuti a procurarmelo!",
  en_title = "The Brassbolts Brothers",
  en_obj = "Speak with Wizzle Brassbolts in the Shimmering Flats.",
}
T[2770] = {
  title = "Gahz'rilla",
  desc = "Nel profondo di Zul'Farrak, la città dei troll delle sabbie a Tanaris, c'è una vasca sacra. Da quella vasca i troll evocano una bestia enorme! Gahz'rilla! È così feroce che perfino le sue scaglie crepitano di energia. È quell'energia che voglio imbrigliare per la mia macchina!$B$BPortami la scaglia elettrificata di Gahz'rilla!$B$BMa l'evocazione di Gahz'rilla è un segreto ben custodito dai troll. Per affrontarlo, prima dovrai strappare loro il segreto.",
  obj = "Porta Gahz'rilla's Electrified Scale a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Hai la scaglia? Non vedo l'ora di provare vari modi per imbrigliarne l'energia!",
  reward = "Caspita, hai preso la scaglia! Grazie, $N. Non vedo l'ora di mettermi al lavoro su questa cosa!$B$BAllora hai visto Gahz'rilla? Era grosso come dicono??",
  en_title = "Gahz'rilla",
  en_obj = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",
}
T[2771] = {
  title = "La Testa sulle Spalle",
  desc = "A quanto pare il maestro aveva previsto tutto fin dall'inizio. A me non è stato insegnato a creare gli oggetti che hai imparato a creare tu, e a te non sono stati insegnati quelli che ho imparato a creare io.$B$BIl maestro è saggio, $N. Ci istruiremo a vicenda!$B$BMostrami come si fanno un camaglio di mithril e degli spallacci di mithril decorati, e io ti mostrerò come si crea un elmo di mithril decorato.",
  obj = "Porta due Mithril Coifs e un Ornate Mithril Shoulder a Trenton Lighthammer.",
  progress = "Hai finito di creare gli oggetti, $N?",
  reward = "Eccellente! Uno scambio equo, lasciamelo dire. Guarda e impara, $N!",
}
T[2772] = {
  title = "Il Mondo ai Tuoi Piedi",
  desc = "Al Campionato di Forgiatura di Tutta la Valle dell'anno scorso, tutto il pubblico ha visto un cane vigliacco della Fonderia della Venture Co. falciarmi la gamba. Quello che nessuno sapeva, però, era il motivo per cui sono riuscito a continuare e alla fine a vincere il torneo: proprio così, gli stivali di mithril decorati!$B$BPer il torneo di quest'anno, però, dovrò imparare a creare i pantaloni di mithril decorati, perché fra gli iscritti c'è un segatronchi della Venture Co.! Insegnami la via dei pantaloni e impara la via dello stivale!",
  obj = "Porta due Heavy Mithril Boots e un Ornate Mithril Pants a Trenton Lighthammer.",
  progress = "Hai finito di creare gli oggetti, $N?",
  reward = "Il mondo sarà ai tuoi piedi, $N! Che provino pure tutti a colpirti alle gambe, perché ormai nessuno può più falciarti!",
}
T[2773] = {
  title = "Il Ragazzo del Mithril",
  desc = "Da queste parti mi conoscono come il Ragazzo del Mithril. Rifornisco di mithril decorato avventurieri di tutto il mondo.$B$B<Trenton sussurra.>$B$BQuello che non sanno è che non conosco la tecnica per fabbricare i guanti di mithril decorati. Shhhh! Sarà il nostro piccolo segreto.$B$BInsegnami la tecnica per creare i guanti di mithril decorati, $N, e in cambio ti mostrerò il frutto del coronamento del mio addestramento con Galvan: il pettorale di mithril decorato.",
  obj = "Porta due Heavy Mithril Breastplates e un Ornate Mithril Gloves a Trenton Lighthammer.",
  progress = "Hai finito di creare gli oggetti, $N?",
  reward = "Grazie per tutto quello che mi hai insegnato, $N. Il signore e padrone del completo di mithril decorato sarà presto in tuo possesso.$B$BAmmira!",
}
T[2781] = {
  title = "RICERCATO: Califfo Scorpidsting",
  desc = "RICERCATO: Califfo Scorpidsting!$B$BLa Gadgetzan Water Company di Gadgetzan, Tanaris, pagherà una ricca taglia per la testa del Califfo Scorpidsting, capo dei fuorilegge Wastewander. Fra i suoi crimini:$B$B1. Assassinio di dipendenti della Gadgetzan Water Co.!$B2. Furto di risorse della Gadgetzan Water Co.!$B3. Occupazione di proprietà della Gadgetzan Water Co.!$B$BPorta la prova della morte del Califfo Scorpidsting all'Ingegnere Capo Bilgewhizzle per una ricompensa immediata!",
  obj = "Porta la testa di Caliph Scorpidsting a Chief Engineer Bilgewhizzle a Gadgetzan.",
  progress = "Sì, $C, sono un funzionario della Gadgetzan Water Company. In cosa posso esserti utile?",
  reward = "Finalmente — giustizia è fatta! Hai inferto un duro colpo a quei vili nomadi! Morto Scorpidsting, potrebbe essere proprio questa la spinta che serve per cacciare una buona volta quegli abusivi dai pozzi d'acqua di Gadgetzan!$B$BIn virtù dell'autorità della Gadgetzan Water Company, ti consegno con piacere questa taglia. Hai reso un grande servizio a tutti noi.",
}
T[2782] = {
  title = "Il Segreto di Rin'ji",
  desc = "La tavoletta è coperta di segni dei troll Witherbark. Il segreto di Rin'ji è davvero un mistero...$B$BPotresti avere fra le mani qualcosa di molto prezioso. D'altra parte, è possibile anche il contrario. Un troll Witherbark nei guai farebbe probabilmente di tutto pur di cavarsela...",
  obj = "Oran Snakewrithe, nota studiosa di tutto ciò che riguarda i troll Witherbark, potrebbe riuscire a decifrare la tavoletta. Si sa che vive nel Magic Quarter di Undercity.",
  progress = "Bene, bene, e questo cos'è?",
  reward = "Questa tavoletta... Davvero insolita... Dove l'hai trovata, $N?",
}
T[2783] = {
  title = "Beghe Meschine",
  desc = "Combattiamo il nemico sbagliato, $N.$B$BLa vera potenza di queste terre continua a crescere in forza e in numero, mentre noi ci accapigliamo con gli orchi per della terra bruciata.$B$BVogliamo continuare a combattere in queste terre una guerra contro l'Orda, per poi farci sbaragliare un giorno dagli eserciti della Legione Infuocata? È inutile.$B$BMetti da parte le tue divergenze, $N, parla con l'eroe caduto dell'Orda. Lui conosce la verità che si cela dietro le Blasted Lands.",
  obj = "Parla con il Fallen Hero of the Horde al confine tra le Blasted Lands e la palude.",
  reward = "L'Alleanza vuole aiutare?$B$BPensavo che non avrei mai più rivisto questo giorno. Un giorno in cui l'Alleanza combatte fianco a fianco con l'Orda contro un nemico comune.$B$BCosì sia... ci uniremo.",
}
T[2784] = {
  title = "Caduta in Disgrazia",
  desc = "Ascolta la mia storia, $R.",
  obj = "Ascolta il Fallen Hero of the Horde che racconta la sua storia.",
  progress = "Ascolta quello che ho da dire.",
  reward = "Da spirito sono impotente, $N. Aiutami. Permettimi di riconquistare il mio onore.",
}
T[2801] = {
  title = "Una Storia di Dolore",
  desc = "Prima di poter proseguire, devi ascoltare la mia storia.",
  obj = "Ascolta il Fallen Hero of the Horde mentre racconta la sua storia.",
  progress = "Ascolta quello che ho da dire, $N.",
  reward = "Il momento di agire è adesso, $N.",
}
T[2821] = {
  title = "Il Marchio di Qualità",
  desc = "La mia filosofia sulla conciatura è che il lavoro dev'essere della migliore qualità possibile — senza compromessi. Chi dice che la qualità non conta sta cercando di venderti una villa sul mare a Dun Morogh!$B$BNella mia ultima ricerca di materiali di prima qualità mi sono imbattuto nelle spesse pelli di yeti. Gli Yeti vivono a Feralas, e se ne trovano molti a Valsfregiata. Ne voglio un po', e per una pila di dieci ti farò scegliere uno dei miei articoli in pelle. Se ti sembra giusto, affare fatto.",
  obj = "Porta 10 Thick Yeti Hide a Pratt McGrubben, alla Feathermoon Stronghold.",
  progress = "Una pila di dieci spesse pelli di yeti ti farà guadagnare uno dei miei lavori, a tua scelta. Visto che ci tengo alla qualità, posso garantirti che avrai un buon oggetto!$B$BSe non riesci a trovare gli yeti, io so dove potrebbero essercene alcuni. Prova a cercare nell'entroterra, subito dietro la Costa dell'Oblio, intorno a Valsfregiata.",
  reward = "Ti sei $Gfermato:fermata; a esaminare la grana di queste pelli? Trattate a dovere, potrebbero benissimo essere più resistenti del ferro. Non sono in molti a conoscere queste pelli, e questo, insieme alle tante soluzioni di concia che conosco, potrebbe permettermi di realizzare oggetti con un vero marchio di qualità... grazie a te, naturalmente!$B$BE ora, per favore, scegli fra quello che posso offrirti per quello che hai fatto!",
}
T[2822] = {
  title = "Il Marchio di Qualità",
  desc = "Sono orgoglioso del mio lavoro di conciatura, e credo che si veda; la qualità non va mai sacrificata. Chi dice che la qualità non conta vorrebbe farti credere anche che la terra non custodisce segreti!$B$BNella mia ultima ricerca di materiali di prima qualità ho scoperto le spesse pelli di yeti. Gli yeti vivono a Feralas, spesso a ovest di qui, a Valsfregiata. Per una pila di dieci ti farò scegliere uno dei miei articoli in pelle. Se ti va bene, siamo d'accordo!",
  obj = "Porta 10 Thick Yeti Hide a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Sei $Griuscito:riuscita; a procurarti una pila di dieci spesse pelli di yeti? I miei articoli in pelle non sono secondi a nessuno, e se hai le pelli te ne farò avere uno.$B$BSe non riesci a trovare gli yeti, io so dove potrebbero essercene alcuni. Prova a cercare a ovest di qui, nell'entroterra subito dietro la Costa dell'Oblio, intorno a Valsfregiata.",
  reward = "Ah, ottimo! Queste pelli, con un trattamento speciale, diventano resistenti come il ferro, te lo dico io! Ci vorranno molti tentativi per trovare la miscela giusta per la concia, ma sono sicuro che porteranno il mio marchio di qualità a un livello superiore.$B$BQuanto a te, $N... il tuo aiuto si è rivelato preziosissimo. Scegli, per favore, fra questi oggetti che ho realizzato.",
}
T[2841] = {
  title = "La Guerra delle Macchine",
  desc = "La tecnologia gnomica — due anni fa era buona soprattutto per le barzellette. I tempi sono cambiati, eccome. Adesso hanno costruito una macchina nuova migliore di tutti i nostri modelli di segatronchi messi insieme. Mi servono i progetti, $N!$B$BPurtroppo i piani sono chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E come se non bastasse, la combinazione della cassaforte la conosce solo Mekgineer Thermaplugg.$B$BFa' quel che devi per avere quella combinazione, $N. Poi apri quella cassaforte e riportami quei progetti!",
  obj = "Recupera i Rig Blueprints e Thermaplugg's Safe Combination da Gnomeregan e portali a Nogg, a Orgrimmar.",
  progress = "Non vedo nessun progetto. Te li sei nascosti addosso da qualche parte o te ne stai qui $Gimpalato:impalata; solo per irritarmi?",
  reward = "Sapevo che ce l'avresti fatta, $N! Sovik invece aveva i suoi dubbi.$B$B<Nogg si schiarisce la gola.>$B$BOra che i progetti sono nostri, è solo questione di tempo prima che capiamo tutte le trovate gnomiche finite nella costruzione della macchina e le trasformiamo in trovate goblin per i nostri nuovi modelli di segatronchi.",
  en_title = "Rig Wars",
  en_obj = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.$B",
}
T[2842] = {
  title = "Ingegnere Capo Scooty",
  desc = "Appena abbiamo avuto notizie da Kernobee sulla nuova macchina gnomica, io e Scooty ci siamo messi a lavorare al Transpolyporter 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.$B$BFinalmente è pronto a imbarcare passeggeri, $N. Se vuoi provarlo, va' a Booty Bay e parla con Scooty al posatoio dei wind riders. Per arrivare a Booty Bay, prendi la nave da Ratchet.$B$BCerto, potresti sempre provare a farti tutta la strada fino a Gnomeregan attraverso le montagne di Dun Morogh infestate dai nani!",
  obj = "Parla con Scooty, a Booty Bay.",
  reward = "È una bellezza, vero? L'apice della tecnologia goblin dei trasporti — è esplosa sì e no una dozzina di volte.$B$BNon preoccuparti, $N, l'ho rimessa a posto per bene. Non ti scoppierà addosso — e se succede, sarà rapido e indolore.",
  en_title = "Chief Engineer Scooty",
  en_obj = "Speak with Scooty in Booty Bay.",
}
T[2843] = {
  title = "Gnomeregan, arriiiivo!",
  desc = "Finché hai il segnalatore con te, ti basta salire sulla piattaforma e verrai $Gteletrasportato:teletrasportata; a Gnomeregan.$B$BPotresti avvertire qualche effetto collaterale insolito, ma nessuno dovrebbe essere permanente... non più.$B$BQuasi dimenticavo la parte più importante — tornare indietro. Quando sei $Gpronto:pronta; a rientrare, sali sulla piattaforma del transpolyporter a Gnomeregan!$B$BOra calibriamo il segnalatore sulla tua taglia e sul tuo peso.",
  obj = "Aspetta che Scooty calibri il Goblin Transponder.",
  progress = "È pronto!",
  reward = "Fatto! Quando sei $Gpronto:pronta;, sali sulla piattaforma.",
  en_title = "Gnomer-gooooone!",
  en_obj = "Wait for Scooty to calibrate the Goblin Transponder.",
}
T[2844] = {
  title = "Il Guardiano Gigante",
  desc = "Io non valgo niente, $N. Dovevo stargli dietro, alla mia amichetta Shay, e non so come m'è scappata. Cos'è successo mica lo so bene, ma l'ultima volta che l'ho vista noi camminavamo per 'ste rovine qui a nord.$B$BAndava tutto bene, poi mi giro e... non c'era più.$B$BAdesso proprio non riesco a capire cosa devo fare. Ce l'hai un'idea, $N? Son preoccupato da morire.$B$BEhi, e se vai tu a cercarla, la Shay? Le gambe tue vanno molto più svelte delle mie.",
  obj = "Trova la ragazzina elfa della notte che si è persa.",
  reward = "Oh, sono così contenta che tu mi abbia trovata! Devo ammetterlo, mi sono un po' persa... Ma non è un posto bellissimo?",
}
T[2845] = {
  title = "Shay la Girovaga",
  desc = "Pensi di potermi aiutare a ritrovare la strada per tornare dal mio amico Rockbiter? Doveva badare a me... Ma è vero che ogni tanto tendo ad allontanarmi. Ci sono così tante cose da vedere, e mi distraggo così facilmente.$B$BC'è una cosa, però, che riesce sempre ad attirare la mia attenzione.$B$BIn questa cassa troverai una campanella a cui tengo moltissimo. Adoro il suo suono. Ti do la mia parola: se mi allontano, non devi fare altro che suonarla e tornerò di corsa.",
  obj = "Prendi Shay's Bell dalla cassa.$B$BScorta Shay Leafrunner all'accampamento di Rockbiter.",
  progress = "Cominciavo a preoccuparmi per te! Grazie tante che me l'hai riportata a casa, la Shay, $N.",
  reward = "Cosa? Dici che 'sta campanella funziona quando la Shay scappa? Ma guarda un po'!$B$BSiccome che hai fatto tanto per me, ecco qua, $N.",
}
T[2846] = {
  title = "La Tiara del Profondo",
  desc = "Molto tempo fa possedevo un gioiello bellissimo, la Tiara del Profondo. E non era solo graziosa — racchiudeva un grande potere per chi sapeva usarlo.$B$BQuando la voce sulla tiara arrivò all'Idromante Velratha, lei volle averla a tutti i costi. Mandò dei suoi agenti a casa mia, e me la rubarono mentre ero via. Ladri!$B$BRivoglio la mia tiara! Va' a Zul'Farrak, la città troll di Tanaris, trova Velratha e strappale la tiara. Riportamela e ti guadagnerai il mio favore.",
  obj = "Porta la Tiara of the Deep a Tabetha, nel Dustwallow Marsh.",
  progress = "Hai la tiara, $N? Velratha ha imparato quanto costa mettersi contro di me?",
  reward = "Magnifico! L'hai trovata! E cosa altrettanto importante — Velratha non ce l'ha più! Grazie, $N. Ti sarò per sempre debitrice!$B$BE se prima ti sono sembrata un po'... cattiva, non farci caso. Scoprirai che sono una persona molto più gentile con chi non mi ha derubata.",
  en_title = "Tiara of the Deep",
  en_obj = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",
}
T[2847] = {
  title = "Armatura di Cuoio Selvatico",
  desc = "$N, come $Gconciatore:conciatrice; stai diventando davvero abile! Conosco alcuni schemi che potrebbero interessarti... l'armatura di Cuoio Selvatico! Il Cuoio Selvatico sfrutta le proprietà potenti e caotiche delle viti selvagge, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per chi ha la tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.$B$BTi insegnerò a farla, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di cuoio spesso. Dopo, parleremo dei dettagli.",
  obj = "Porta 10 Thick Leather a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Come ti ho detto, lavorerai per me mentre impari a conoscere l'armatura di Cuoio Selvatico. Dato che le viti selvagge sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me arrivare a questa conoscenza.$B$BPer avviare il lavoro, il costo iniziale è di dieci pezzi di cuoio spesso.$B$BQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.",
  reward = "Bene, $N, sono contento di averti con me. Come $Gconciatore:conciatrice; hai fatto una scelta intelligente: chi indossa armature di cuoio farà a gara per venire da te, quando avrai imparato a fare uno qualsiasi dei pezzi dell'armatura di Cuoio Selvatico.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2848] = {
  title = "Spallacci di Cuoio Selvatico",
  desc = "Gli spallacci di Cuoio Selvatico danno un sostegno eccellente alla corporatura di chi li indossa e offrono una protezione di prim'ordine alla parte alta delle braccia e alle spalle stesse. Come per tutta l'armatura di Cuoio Selvatico, cucendoci dentro la vite selvaggia il pezzo acquista un vantaggio potente ma casuale.$B$BPer questo schema mi serviranno sei potenziamenti d'armatura spessi e una vite selvaggia. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.",
  obj = "Porta 6 Thick Armor Kit e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai i sei potenziamenti d'armatura spessi e la vite selvaggia che ti ho chiesto?$B$BNon pensare che fare potenziamenti d'armatura sia un lavoro monotono: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi potenziamenti ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiede l'armatura di Cuoio Selvatico.$B$BVedi — c'è un vero motivo dietro a quello che fai per me...",
  reward = "Questi potenziamenti d'armatura sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi lavora per me, è la qualità.$B$BHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2849] = {
  title = "Veste di Cuoio Selvatico",
  desc = "Le vesti di Cuoio Selvatico sono il pezzo base di ogni set di armatura di Cuoio Selvatico. La struttura della veste si fonde con la vite selvaggia per dare vita a un capo che offre la massima protezione al torso, lasciando che la potente magia si diffonda in tutto l'indumento.$B$BPer questo schema mi serviranno due pettorali di Scaglie di Tartaruga, due paia di guanti di Scaglie di Tartaruga e una vite selvaggia. È un ordine impegnativo, ma non dovresti avere grandi difficoltà a evaderlo per me.",
  obj = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai i due pettorali e i guanti di Scaglie di Tartaruga che ti ho ordinato? E non dimenticare la vite selvaggia!$B$BGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma dei pettorali di Scaglie di Tartaruga ti prepara ai dettagli che servono per fare una veste di Cuoio Selvatico.$B$BE i guanti... be', quelli servono solo a me. Ricorda che lavori per me!",
  reward = "Sono pezzi davvero belli, $N. Solo per la maestria e la cura con cui sono stati fatti, varrebbero diverse monete d'argento in più rispetto a un pezzo qualunque.$B$BHai evaso il mio ordine, e per questo ti spetta la ricompensa. Ora la conoscenza per fare le vesti di Cuoio Selvatico è tua!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2850] = {
  title = "Elmetto di Cuoio Selvatico",
  desc = "Un elmetto di Cuoio Selvatico offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura di Cuoio Selvatico, la vite selvaggia incorporata nell'elmo dà alla sua struttura un potenziamento forte ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!$B$BPer questo schema mi serviranno due tuniche della Fuga Notturna, due fasce della Fuga Notturna e una vite selvaggia. Completa questo ordine e lo schema sarà tuo!",
  obj = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di vite selvaggia, prima di svelarti come si fanno gli elmetti di Cuoio Selvatico.$B$BTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.",
  reward = "L'equipaggiamento della Fuga Notturna che mi hai portato soddisfa l'ordine alla perfezione, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.$B$BQuesto schema te lo sei davvero $Gguadagnato:guadagnata;. Te lo do volentieri, e spero che tu ne tragga il giusto profitto.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2851] = {
  title = "Stivali di Cuoio Selvatico",
  desc = "Ormai hai imparato parecchio, $N, ma c'è ancora altro da imparare. Adesso tocca agli stivali di Cuoio Selvatico, la pietra angolare di ogni set.$B$BQuesti stivali sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.$B$BPer questo schema devi evadere un ordine di due paia di pantaloni Nightscape e due paia di stivali Nightscape. Mi serviranno anche due viti selvagge... non una sola. Quando hai tutto, fammelo sapere.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "L'ordine dei pantaloni, degli stivali e delle viti selvagge va evaso prima che tu abbia lo schema, $N. Hai finito?$B$BFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.",
  reward = "Ancora una volta hai evaso un ordine complesso con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche la mia gratitudine.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2852] = {
  title = "Gambiere di Cuoio Selvatico",
  desc = "Ora che hai le basi, sei $Gpronto:pronta; a padroneggiare lavori più complessi, $N. Le gambiere di Cuoio Selvatico sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della vite selvaggia, gli avventurieri che le possiedono ti ringrazieranno ogni volta che ti vedranno.$B$BPer questo schema devi evadere un ordine di due elmi di Scaglie di Tartaruga, due bracciali di Scaglie di Tartaruga e due viti selvagge.",
  obj = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai pronti i bracciali e gli elmi di Scaglie di Tartaruga? Non dimenticare le due viti selvagge che mi servono!$B$BOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura di Cuoio Selvatico. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!",
  reward = "Di nuovo hai evaso un ordine senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?$B$BEcco lo schema delle gambiere, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2853] = {
  title = "$GMaestro:Maestra; del Cuoio Selvatico",
  desc = "Be', $N, sei la diligenza fatta persona. Rimane un solo schema dell'armatura di Cuoio Selvatico; gli altri li padroneggi già. Non ti farò sgobbare inutilmente per averlo. Te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più... ma non posso dartelo io. È il mio maestro, colui che mi ha iniziato al mestiere, che deve ricompensarti.$B$BPorta questa lettera a Telonis; insegna conciatura a Darnassus. Mostragli la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.",
  obj = "Consegna Pratt's Letter a Telonis, il maestro conciatore di Darnassus.",
  progress = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?",
  reward = "Ah, sì, ti manda Pratt. Anche se è un umano, a volte mi ricorda noi elfi della notte. La sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Cuoio Selvatico. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei mantelli di Cuoio Selvatico.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.",
}
T[2854] = {
  title = "Armatura di Cuoio Selvatico",
  desc = "$N, la tua abilità di $Gconciatore:conciatrice; ti precede. Custodisco un sapere di conciatura che faresti bene ad acquisire... l'armatura di Cuoio Selvatico! Il Cuoio Selvatico sfrutta le proprietà potenti e caotiche delle viti selvagge, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per $Gun artigiano:un'artigiana; della tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.$B$BTi insegnerò, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di cuoio spesso. Dopo, parleremo dei dettagli.",
  obj = "Porta 10 Thick Leather a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Mettiamo le cose in chiaro: sarai $Gil mio apprendista:la mia apprendista; mentre impari l'arte dell'armatura di Cuoio Selvatico. Dato che le viti selvagge sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me acquisire questa conoscenza.$B$BPer avviare il lavoro, il costo iniziale è di dieci pezzi di cuoio spesso.$B$BQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.",
  reward = "Bene, $N, sono lieto di averti come $Gmio apprendista:mia apprendista;. Come $Gconciatore:conciatrice; hai fatto una scelta saggia: chi usa armature di cuoio farà a gara per venire da te, quando avrai imparato a padroneggiare l'arte del Cuoio Selvatico.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.",
}
T[2855] = {
  title = "Spallacci di Cuoio Selvatico",
  desc = "Gli spallacci di Cuoio Selvatico sostengono benissimo il fisico di chi li indossa e offrono una protezione superiore alla parte alta delle braccia oltre che alle spalle. Come per tutta l'armatura di Cuoio Selvatico, cucendoci dentro la vite selvaggia il pezzo si impregna di un potenziamento casuale ma molto potente.$B$BPer questo schema mi serviranno sei kit spessi per armature e una vite selvaggia. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.",
  obj = "Porta 6 Thick Armor Kit e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai i sei kit spessi per armature e la vite selvaggia che ti ho chiesto?$B$BConsidera la fabbricazione dei kit per armature una lezione di lavoro costante e affidabile: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi kit ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiedono le armature di Cuoio Selvatico.$B$BOgni lezione ha uno scopo, $N. È importante accoglierle tutte con lo spirito giusto.",
  reward = "Questi kit per armature sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi è sotto la mia guida, è la qualità.$B$BHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2856] = {
  title = "Veste di Cuoio Selvatico",
  desc = "Le vesti di Cuoio Selvatico sono il pezzo base di ogni set di armatura di Cuoio Selvatico. La struttura della veste e la vite selvaggia intrecciata al suo interno danno vita a un capo che offre la massima protezione al torso, lasciando che una potente magia si diffonda in tutto l'indumento.$B$BPer questo schema mi serviranno due pettorali di Scaglie di Tartaruga, due paia di guanti di Scaglie di Tartaruga e una vite selvaggia. Non è una lezione facile, ma di sicuro hai l'abilità per portarla a termine.",
  obj = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai i due pettorali e i guanti di Scaglie di Tartaruga? E non dimenticare la vite selvaggia!$B$BGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma dei pettorali di Scaglie di Tartaruga ti prepara ai dettagli che servono per fare una veste di Cuoio Selvatico.$B$BMan mano che andrai avanti con le lezioni, le abilità che ti insegno diventeranno arte.",
  reward = "Sono pezzi davvero belli, $N. La maestria e la cura con cui li hai fatti mostrano che hai scelto di dedicarti completamente a questi compiti.$B$BHai soddisfatto le mie richieste, e per questo ti spetta la ricompensa. Ora la conoscenza per fare le vesti di Cuoio Selvatico è tua!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2857] = {
  title = "Elmetto di Cuoio Selvatico",
  desc = "Un elmetto di Cuoio Selvatico offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura di Cuoio Selvatico, la vite selvaggia incorporata nell'elmetto infonde nella sua struttura una magia potente ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!$B$BPer questo schema mi serviranno due tuniche Nightscape, 2 fasce Nightscape e una vite selvaggia. Completa questa lezione e lo schema sarà tuo!",
  obj = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di vite selvaggia, prima di svelarti come si fanno gli elmetti di Cuoio Selvatico.$B$BTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.",
  reward = "L'equipaggiamento Nightscape che mi hai portato soddisfa alla perfezione le richieste che ti avevo fatto, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.$B$BTi sei $Gguadagnato:guadagnata; l'onore di fabbricare gli elmetti di Cuoio Selvatico. Ti do questo schema volentieri, e spero che tu ne tragga il giusto profitto.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2858] = {
  title = "Stivali di Cuoio Selvatico",
  desc = "La tua conoscenza dell'armatura di Cuoio Selvatico cresce, $N, ma c'è ancora altro da imparare.$B$BGli stivali di Cuoio Selvatico sono la pietra angolare di ogni set. Stivali come questi sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.$B$BPer questo schema devi fabbricare due paia di pantaloni Nightscape e due paia di stivali Nightscape. Mi serviranno anche due viti selvagge... non una sola. Quando avrai questi oggetti, andremo avanti.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "I pantaloni, gli stivali e le viti selvagge devono arrivarmi prima che tu impari lo schema, $N. Hai fatto come ti ho chiesto?$B$BFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.",
  reward = "Ancora una volta hai prodotto oggetti con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche le mie congratulazioni.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2859] = {
  title = "Gambiere di Cuoio Selvatico",
  desc = "Sei $Gpronto:pronta; a padroneggiare lezioni più complesse, $N. Le gambiere di Cuoio Selvatico sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della vite selvaggia, gli avventurieri che le possiedono ti ringrazieranno ogni volta che ti vedranno.$B$BPerché tu possa avere questo schema, mi servono due elmi di Scaglie di Tartaruga, due bracciali di Scaglie di Tartaruga e due viti selvagge.",
  obj = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai pronti i bracciali e gli elmi di Scaglie di Tartaruga? Non dimenticare le due viti selvagge che ti ho chiesto.$B$BOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura di Cuoio Selvatico. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!",
  reward = "Di nuovo hai portato a termine il mio compito senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?$B$BEcco lo schema delle gambiere, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2860] = {
  title = "$GMaestro:Maestra; del Cuoio Selvatico",
  desc = "$N, hai imparato tutto quello che sono in grado di insegnarti. Resta però un ultimo schema dell'armatura di Cuoio Selvatico. Non ti farò sgobbare inutilmente per averlo; te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più. Questo schema, però, non posso condividerlo con te liberamente.$B$BÈ la mia maestra, colei che mi ha iniziato al mestiere, che deve ricompensarti. Porta questo biglietto a Una; insegna conciatura a Thunder Bluff. Mostrale la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.",
  obj = "Consegna Jangdor's Letter a Una, la maestra conciatrice di Thunder Bluff.",
  progress = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?",
  reward = "Ah, sì, ti manda Jangdor. Sono lieta di vedere che uno dei miei allievi migliori ora ha $Gun allievo tutto suo:un'allieva tutta sua;.$B$BLa sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Cuoio Selvatico. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei mantelli di Cuoio Selvatico.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.",
}
T[2861] = {
  title = "Il Compito di Tabetha",
  desc = "Si dice che Tabetha, una collega maga che vive nel profondo del Dustwallow Marsh, abbia un conto in sospeso con un certo troll delle sabbie di Zul'Farrak. Se parli con Tabetha, potrà dirti di più.$B$BE porta con te qualche amico, $N. Se Tabetha ti manda a Zul'Farrak, non vorrai andarci da $Gsolo:sola;.$B$BTroverai la casetta di Tabetha a ovest di Theramore, appena a nord delle Rovine di Stonemaul.",
  obj = "Parla con Tabetha, nel Dustwallow Marsh.",
  reward = "Proprio così. Ho davvero un conto in sospeso con una troll. Anzi, più d'uno. Voglio tutte le sue ossa!$B$BVuoi aiutarmi?",
  en_title = "Tabetha's Task",
  en_obj = "Speak with Tabetha in Dustwallow Marsh.",
}
T[2862] = {
  title = "Guerra ai Woodpaw",
  desc = "Gli gnoll... sono più di un fastidio. Sono una minaccia costante per l'esistenza stessa di questo campo! Poco importa se siano originari di Feralas o no: se non rafforziamo la nostra determinazione contro di loro, ci ritroveremo cacciati dall'intera regione.$B$BUltimamente gli attacchi degli gnoll contro il campo si sono fatti più accaniti. Ci serve il tuo aiuto per sfoltirne il numero; portami dieci delle loro criniere, e ti ricompenserò generosamente per il tuo impegno.$B$BVa'!",
  obj = "Porta 10 Woodpaw Gnoll Mane a Hadoken Swiftstrider, a Camp Mojache.",
  progress = "Li respingiamo, eppure continuano ad attaccare! Dev'essere qualcuno o qualcosa a farli impazzire... oh, sei $Gtornato:tornata;, eh, $N? Hai le criniere che mi servono per la taglia?",
  reward = "Questa è la prova di un buon inizio, $N. Le tue capacità di $Gsoldato:soldatessa; meritano un elogio.$B$BNon sei $Gl'unico:l'unica; a cui chiedo questo compito. Molti prima di te li hanno combattuti, e in passato i nostri sforzi li hanno tenuti a bada. Di recente, però, i loro tentativi di spingersi a nord, nella nostra zona d'influenza, sono aumentati moltissimo. E anche i loro attacchi sono diventati più feroci... quasi come se fossero disperati.$B$BMa ho un piano, $N, che potrebbe sistemare le cose con loro una volta per tutte...",
  en_title = "War on the Woodpaw",
  en_obj = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.",
}
T[2863] = {
  title = "Attacco agli Alfa",
  desc = "Il piano è abbattere in rapida successione vari capi degli gnoll, gli Alfa, come si fanno chiamare. Se riusciamo a scatenare contro di loro una devastazione così rapida e precisa, porteremo il caos nelle loro file. Forse faremo anche entrare nelle loro teste dure e piene di pulci il messaggio che possiamo distruggerli, e che lo faremo!$B$BVoglio che tu sia $Gil messaggero:la messaggera; della mia volontà: elimina cinque dei loro Alfa entro un'ora perché funzioni, $N, altrimenti resteremo in questa situazione di stallo!",
  obj = "Uccidi 5 Woodpaw Alpha e torna da Hadoken Swiftstrider entro un'ora.",
  progress = "Il tempo stringe, $N! Se non sei qui per riferirmi che hai fatto fuori gli Alfa, stai perdendo tempo!",
  reward = "Hai fatto quello che ti ho chiesto, e per questo ti rendo onore. Prendi questa piccola ricompensa per i tuoi sforzi, $N.$B$BOra che sono meno numerosi e i loro capi sono stati uccisi, gli gnoll ci penseranno due volte prima di assaltare il campo. Ma questo non chiude la questione...$B$BDeve esserci un motivo se gli gnoll sono stati aizzati fino a questo stato di frenesia. Prima che abbiano la possibilità di riorganizzarsi, voglio scoprire cosa lo provoca.",
  en_title = "Alpha Strike",
  en_obj = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.",
}
T[2864] = {
  title = "Tran'rek",
  desc = "Mio cugino Tran'rek è nei guai. Settimane fa mi aveva promesso un carico di gusci di scarabeo e non l'ha ancora consegnato. È mio cugino, quindi non vorrei dover mandare qualcuno a Gadgetzan a rompergli qualcosa.$B$BPuoi parlare con Tran'rek per me? E dirgli che deve preparare quella consegna prima che io faccia qualcosa di avventato?$B$BGadgetzan si trova nel nord di Tanaris, in Kalimdor.",
  obj = "Parla con Tran'rek, a Gadgetzan.",
  reward = "Salve!$B$BOh, hai parlato con mio cugino Krazek? Come sta? Spero che Booty Bay lo tratti bene...$B$BGusci di scarabeo, dici? Be'... lascia che ti racconti una storia...",
  en_title = "Tran'rek",
  en_obj = "Speak with Tran'rek in Gadgetzan.",
}
T[2865] = {
  title = "Gusci di Scarabeo",
  desc = "Gli scarabei di Tanaris hanno gusci durissimi! Abbastanza duri da usarli come materiale da costruzione per un sacco di cose. Tantissime cose!$B$BAnzi, quei gusci sono così utili... che gli scarabei sono stati cacciati quasi fino all'estinzione!$B$BIo so dove ci sono altri scarabei, e se mi prometti di portarmi i loro gusci, ti dirò dove sono. Promesso?$B$BBene, gli scarabei hanno una colonia a Zul'Farrak. A quanto pare i troll non li cacciano per i gusci.$B$BMa tu sì! Va' a Zul'Farrak e portami dei gusci non incrinati!",
  obj = "Porta 5 Uncracked Scarab Shell a Tran'rek, a Gadgetzan.",
  progress = "Hai i gusci? Mio cugino a Booty Bay aspetta un carico, e si sta spazientendo!",
  reward = "Oh, fantastico! Li hai presi!$B$BGrazie, $N. Mi hai proprio salvato la vita!",
  en_title = "Scarab Shells",
  en_obj = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.",
}
T[2866] = {
  title = "Le Rovine di Solarsal",
  desc = "A sud di qui ci sono le Rovine di Solarsal: una zona che risale a molto prima dei tempi moderni. All'inizio abbiamo esplorato le rovine e non abbiamo trovato niente di notevole; per questo le abbiamo lasciate in pace.$B$BDi recente, però, i naga Hatecrest hanno occupato queste rovine in numero allarmante. All'inizio l'abbiamo considerato il preludio di un attacco. Anche se quella minaccia resta possibile, crediamo che stia succedendo qualcos'altro.$B$BVa' là, esplora le rovine e cerca qualunque cosa ti sembri fuori dal comune. Buona fortuna, $N.",
  obj = "Esplora le Rovine di Solarsal e indaga sulla presenza dei naga.",
  reward = "Esaminando il gazebo scopri alcune cose interessanti e insolite, rispetto alle rovine circostanti.$B$BPrima di tutto, il gazebo è chiaramente una costruzione più recente degli altri elementi delle rovine. Poi, sui suoi lati è incisa una piccola serie di glifi; i glifi seguono uno schema che si ripete, ma per il resto la loro origine e il loro significato sono sconosciuti. Infine, la pietra del gazebo è calda al tatto.$B$BQuesto rientra di sicuro tra le cose \"fuori dal comune\" nella ricerca tra le rovine!",
  en_title = "The Ruins of Solarsal ",
  en_obj = "Explore the Ruins of Solarsal and investigate the presence of the naga there.",
}
T[2867] = {
  title = "Ritorno alla Feathermoon Stronghold",
  desc = "Con la scoperta dello strano gazebo nel cuore delle Rovine di Solarsal, è giunto il momento di tornare alla Feathermoon Stronghold e riferire al Generale Shandris Feathermoon quello che hai scoperto.",
  obj = "Torna da Shandris Feathermoon, alla Feathermoon Stronghold, e riferisci le tue scoperte.",
  reward = "$GBentornato:Bentornata;, $N. Il tuo rapporto su questo gazebo è molto... inquietante. Sembra che, anche se i naga non stessero progettando un attacco, la loro presenza continua non promette niente di buono per la nostra avanzata in Feralas. Comunque, ecco un compenso per la tua indagine.$B$BSembra che la Feathermoon Stronghold abbia un disperato bisogno di altro aiuto contro i naga Hatecrest. Vorrei affidarti questo compito, se lo desideri. C'è molto da fare.",
  en_title = "Return to Feathermoon Stronghold",
  en_obj = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.",
}
T[2869] = {
  title = "Contro gli Hatecrest",
  desc = "A questo punto la cosa migliore da fare è dare per scontato che, qualunque cosa stiano tramando, i naga prima o poi cercheranno di prendersi l'isola. Dobbiamo fare passi decisi per contrastare questa minaccia prima che sia troppo tardi.$B$BPortami dieci Scaglie Hatecrest in buone condizioni; dovrebbe esserti chiaro come procurartele. Farai le tue prime armi contro i naga, e noi avremo una presenza naga più debole sull'Isola di Sardor: due prospettive che vanno entrambe a nostro vantaggio.",
  obj = "Porta 10 Hatecrest Naga Scale a Latronicus Moonspear, alla Feathermoon Stronghold.",
  progress = "$N, se sei qui per il compito che ti è stato affidato, ottimo: cerco dieci scaglie Hatecrest. Se sei qui per fare due chiacchiere, al momento non ho tempo per simili sciocchezze.$B$BSappi questo: noi elfi della notte non siamo guerrafondai. La nostra razza è votata alla conservazione della pace e dell'armonia. Questo però non vuol dire che non prenderemo l'iniziativa per difendere i nostri interessi. È il mio dovere verso il Generale Feathermoon e verso la roccaforte.",
  reward = "Sì, sì, queste scaglie sono più che soddisfacenti. Anzi, credo che le manderò giù a Pratt perché ci dia un'occhiata. Magari riuscirà a ricavarne qualcosa di utile.$B$BQuanto a te, voglio mandarti in un'altra missione. Ma prima, ecco la tua ricompensa per le scaglie. Il tuo servizio costante al Generale e a tutta la Feathermoon Stronghold è una benedizione nelle avversità.",
  en_title = "Against the Hatecrest",
  en_obj = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2870] = {
  title = "Contro Lord Shalzaru",
  desc = "$N, nuovi rapporti degli esploratori ci hanno dato un'idea chiara della catena di comando dei naga. Tra i loro ranghi ci sono anche dei reali, e sono loro a dare tutti gli ordini.$B$BIn particolare, abbiamo individuato uno dei reali più crudeli: Lord Shalzaru. Gli esploratori riferiscono che lui stesso ha portato alla luce una strana reliquia durante un recente scavo dei naga, in una grotta a sud delle rovine principali, oltre l'acqua, sull'Isola del Terrore.$B$BMetti fine a tutto questo mettendo fine a lui, e portami la sua reliquia perché possiamo studiarla.",
  obj = "Elimina Lord Shalzaru, poi porta la Mysterious Relic che ha portato alla luce a Latronicus Moonspear, alla Feathermoon Stronghold.",
  progress = "Abbattere Lord Shalzaru ritarderebbe di sicuro i loro piani di settimane, se non di mesi. Oltretutto, la reliquia che ha portato alla luce ci interessa senza dubbio.$B$BHai portato a termine la missione che ti è stata affidata, $N?",
  reward = "Ottimo lavoro, $N! La morte di Lord Shalzaru getterà i naga nello scompiglio per un po' di tempo, se non per sempre. La minaccia che rappresentano è ora sotto il nostro controllo più di quanto lo sia mai stata, e lo dobbiamo a te.$B$BEcco altro denaro della taglia dalle casse della roccaforte: te lo sei $Gguadagnato:guadagnata; fino all'ultima moneta. Tu e i tuoi siete sempre i benvenuti alla Feathermoon Stronghold, $Gamico mio:amica mia;.$B$BUn'ultima cosa prima che tu vada, $N... se potessi...",
  en_title = "Against Lord Shalzaru",
  en_obj = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2871] = {
  title = "Consegnare la Reliquia",
  desc = "Se fossi così gentile da consegnare la reliquia a mia moglie Vestia, te ne sarei grato. Non è solo un'ottima sacerdotessa per la nostra comunità, ma è anche una delle studiose più esperte che si possano trovare. Io non capirei nulla di questo congegno nemmeno se ci fosse una scommessa in ballo. Mia moglie invece, se c'è qualcuno che può capire cos'è questa cosa, è lei... e dobbiamo saperlo!$B$BÈ appena dietro l'angolo, di sicuro a studiare. Grazie, $N.",
  obj = "Consegna la Mysterious Relic a Vestia Moonspear, alla Feathermoon Stronghold.",
  progress = "Sì, posso esserti utile?$B$BAspetta, sei tu $Gil:la; $C che ha aiutato il generale Feathermoon e Latro con la minaccia dei naga, vero? Sono Vestia, la moglie di Latro — ehm, anzi, di Latronicus. È un piacere conoscerti!$B$BScusa, sei qui per lavoro, naturalmente. Hai qualcosa per me — da parte sua, per caso?",
  reward = "Interessante... dici che viene dalle Rovine di Solarsal? Be', Latro ha ragione: devo esaminarla. A prima vista non sembra originaria delle rovine. D'altra parte, non è di fattura naga... non una cosa così aliena.$B$BCi vorrà un po' di tempo per studiare questo oggetto. Quando avrò finito le mie ricerche, forse sfrutterò il tuo talento, se sarai da queste parti.$B$BTieni, prendi uno di questi oggetti in più che abbiamo; spero che ti sia utile!",
  en_title = "Delivering the Relic",
  en_obj = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.",
}
T[2872] = {
  title = "Il Debito di Stoley",
  desc = "Il mio vecchio amico Stoley mi deve una bottiglia di rum molto speciale. Fa il barista a Steamwheedle Port, a Tanaris, su Kalimdor, e mi ha garantito che il rum di lì è più forte di qualsiasi cosa si trovi a Booty Bay. Ne è così convinto che, dice, se provo quel rum e non gli do ragione, raddoppierà i soldi che mi deve!$B$BBe', secondo me non è più sicuro come l'ultima volta che ci siamo parlati, e adesso ha paura di darmi quel rum. Ma io davanti a una scommessa non mi tiro indietro, quindi perché non gli parli tu per me...",
  obj = "Parla con Stoley a Steamwheedle Port.",
  reward = "Ah, e così hai parlato con MacKinley, eh?$B$BNon è come pensa lui! Non ho paura di dargli un po' di Rum di Sentina di Steamwheedle...$B$BÈ che non ho rum da dargli!",
}
T[2873] = {
  title = "La Spedizione di Stoley",
  desc = "Devo del rum a \"Lupo di Mare\" MacKinley di Booty Bay, per saldare una scommessa, ma sono rimasto senza! Il Capitano Cuergo mi ha rubato l'ultima spedizione, e la tiene stivata in quella città pirata cinta da mura, a sud.$B$BSe riesci a trovare la mia spedizione di rum e a riportarmela, potrò dimostrare a MacKinley che i liquori di Kalimdor stracciano quelli di Booty Bay!",
  obj = "Porta Stoley's Shipment a Stoley a Steamwheedle Port.",
  progress = "Hai trovato la mia spedizione di rum, $N?",
  reward = "Ottimo, grazie per la spedizione! Ora io e MacKinley possiamo finalmente chiudere la nostra scommessa.",
}
T[2874] = {
  title = "Consegna per MacKinley",
  desc = "Grazie ancora dell'aiuto, $N. Ecco una bottiglia di rum di sentina di Steamwheedle. Portala a MacKinley, così potrà finalmente mettere da parte le sue idee strampalate sui liquori di Booty Bay.",
  obj = "Porta Stoley's Bottle a \"Sea Wolf\" MacKinley a Booty Bay.",
  progress = "Stoley ha sganciato il mio liquore?",
  reward = "Mh, proviamo...$B$BNon ci posso credere! Questa roba è... terribile! Fantastico!$B$BBe', mi sa che Stoley può tenersi i soldi che mi deve. Sul rum di sentina di Steamwheedle è stato di parola. Quella roba è densa come la ghiaia e brucia come la lava!",
}
T[2875] = {
  title = "RICERCATO: Andre Firebeard",
  desc = "Il vile pirata Andre Firebeard è ricercato per crimini contro Steamwheedle e Gadgetzan.$B$BPer decreto del consiglio di governo, chiunque legga il presente avviso è autorizzato a usare la forza letale durante la cattura di Andre e dei suoi complici.$B$BPer ulteriore decreto, qualora Andre risultasse deceduto, o altrimenti indisposto, al momento dell'udienza, la sua testa potrà farne le veci, e la consegna di detta testa al Capo della Sicurezza Bilgewhizzle costituisce un contratto vincolante, ed esigibile.",
  obj = "Porta Firebeard's Head a Security Chief Bilgewhizzle a Steamwheedle Port.",
  progress = "Hai l'aria un po' frastornata. Hai letto i nostri documenti legali?",
  reward = "Ah, la testa di Andre. Allora mi sa che al processo ci arriverà, dopotutto!$B$BMolto obbligato, $N. Ora, se firmi qui, posso versarti il compenso per i servizi resi.$B$BNon preoccuparti delle clausole scritte in piccolo. Sono innocue, e... tanto non credo esista una lente d'ingrandimento abbastanza piccola per leggerle.",
}
T[2876] = {
  title = "Orari delle Navi",
  desc = "Questa pergamena contiene gli orari delle spedizioni fra Steamwheedle Port e Booty Bay. Ci sono sia le spedizioni passate sia quelle future, con i nomi delle navi, grosse 'X' accanto ai viaggi di alcune navi e annotazioni come \"GRAN BOTTINO\" e \"SCONTRO DURO\" accanto ad altri.$B$BA Steamwheedle Port qualcuno vorrà vedere questo documento.",
  obj = "Porta gli Ship Schedules a un'autorità di Steamwheedle Port.",
  progress = "Sembri senza fiato. Hai qualcosa da dirmi?",
  reward = "Oh, accidenti, sembra un elenco di partenze e arrivi delle navi, con date e orari precisi e tutto quanto! Se ci mettesse le mani il capitano di una nave pirata, andrebbe a nozze!$B$BDici che l'hai preso a un pirata? Be', è una notizia preoccupante...$B$BGrazie, $N. Sono contento che tu gliel'abbia tolto, e sono contento che in questo momento quel pirata stia mordendo la polvere!",
}
T[2877] = {
  title = "Pulizia al Tumulo Strisciante",
  desc = "Noi Wildhammer ricordiamo il passato, più dei nostri fratelli di Ironforge. Se vuoi farti degli amici qui, allora ti sporchi le mani per noi!$B$BL'Orda ha abbandonato le sue posizioni negli Hinterlands intorno al Tumulo Strisciante; ora è invaso da poltiglie e melme schifose. Abbiamo dei piani per quella zona, ma prima ci serve una squadra di pulizia che ci apra un varco.$B$BEd è qui che entri in gioco tu, $Gbello mio:bella mia;! Scendi laggiù e fai fuori dieci poltiglie verdi e dieci melme di giada, poi torna a fare rapporto da me. In marcia!",
  obj = "Uccidi 10 Green Sludges e 10 Jade Oozes, poi torna a fare rapporto da Fraggar Thundermantle ad Aerie Peak.",
  progress = "Non provare a mercanteggiare sulla missione, $R! Se gli dei avessero voluto quelle melme morte, ci avrebbero già pensato loro con un miracolo, non credi?!",
  reward = "Ma guardati, che dai una mano ai Wildhammer! Sei $Gun:una; $C d'azione, e l'azione è quello che rispettiamo da queste parti.$B$BLa tua piccola missione di pulizia è molto più importante di quanto potresti pensare. Con qualcuno che sfoltisce melme e poltiglie, estenderemo la nostra sfera d'influenza in un attimo. Ecco — prenditi un pensierino, oltre ai nuovi amici che hai trovato qui ad Aerie Peak!",
}
T[2878] = {
  title = "Songflower Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di songflower. La pianta emana un odore pungente e malsano. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion sul songflower. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[2879] = {
  title = "Il Bastone di Equinex",
  desc = "Questo bastone potrebbe essere il Bastone di Equinex! Il Bastone di Equinex è in realtà una chiave, che serve ad aprire il Monolito di Equinex nelle Rovine di Ravenwind, sulla terraferma a ovest dell'Albero dei Sogni.$B$BTrova le quattro fiamme che ardono ancora fra quelle rovine: Samha, Imbel, Byltan e Lahassa. Raccogli la loro essenza e poi, stando accanto al Monolito di Equinex, usa le essenze per caricare di energia il bastone. Se è davvero il Bastone di Equinex, potrai aprire il Monolito e prenderne un artefatto sacro.",
  obj = "Carica di energia Troyas' Stave e trova l'Equinex Monolith.",
  progress = "Il Monolito di Equinex si erge silenzioso fra le rovine. Cosa potrebbe custodire?",
  reward = "Tenere in mano il bastone carico di energia è quasi impossibile. Il suo potere ti rimbomba in tutto il corpo.$B$BAllunghi la mano verso la superficie fredda del Monolito di Equinex...$B$BSi apre una piccola porta, e puoi infilarci la mano per prendere l'artefatto che c'è dentro.$B$BFasci di luce riempiono la zona intorno al Monolito di Equinex.",
}
T[2880] = {
  title = "Taglia sulle Collane Troll",
  desc = "Mettitelo bene in testa, $R — NON facciamo parte dell'Alleanza! I Wildhammer sono indipendenti e dimostrano quanto valgono con le imprese e con i fatti, non con le ciance di chi si riempie la bocca di bla bla per puntellare il proprio atteggiamento da fannullone!$B$BSe cerchi amici qui, allora prima dimostraci quanto vali! I troll schifosi che soffocano i pendii delle Hinterlands a volte portano collane tribali. Portamene cinque e lo segneremo come un passo nella giusta direzione.",
  obj = "Porta 5 Troll Tribal Necklaces a Fraggar Thundermantle ad Aerie Peak.",
  progress = "Voglio cinque di quelle collane tribali che i troll si portano addosso. Se te lo devo spiegare ancora meglio, ucciderne uno ti dà buone probabilità di trovarne una!$B$BDimostra il tuo valore ai Wildhammer!",
  reward = "Ecco, così si parla! Vedi — queste collane dimostrano che sei $Gdisposto:disposta; a sporcarti le mani. Noi Wildhammer lo apprezziamo in chi frequentiamo.$B$BContinua così, e prima o poi entrerai nelle nostre grazie.",
}
T[2881] = {
  title = "Taglia sulle Collane Troll",
  progress = "L'hai già fatto, ma continueremo ad accettare tutte le collane tribali troll che trovi e che vuoi consegnare. Consegnandole a me, continuerai a migliorare la tua posizione presso i Wildhammer; se sei $Gdisposto:disposta; a combattere per noi, noi saremo disposti a combattere per te!$B$BPerché valgano, mi servono cinque collane tribali troll, $N.",
  reward = "Ecco, così si parla! Vedi — queste collane dimostrano che sei $Gdisposto:disposta; a sporcarti le mani. Noi Wildhammer lo apprezziamo in chi frequentiamo.$B$BContinua così, e prima o poi entrerai nelle nostre grazie.",
}
T[2902] = {
  title = "Indagine sui Woodpaw",
  desc = "Gli gnoll non sono esattamente dei geni, ma di sicuro avranno una qualche strategia scritta sulle loro attività recenti. Se trovassimo quei piani, avremmo un'idea più chiara di cosa li agita tanto.$B$BVoglio che tu torni dai Woodpaw e trovi qualunque cosa somigli ai loro piani di battaglia. Devono avere qualcosa: i loro attacchi sono stati troppo coordinati per essere fatti senza un piano. Trovali, e torna da me quando li avrai.",
  obj = "Trova i piani di battaglia degli gnoll, da qualche parte nei loro accampamenti a sud di Camp Mojache.",
  reward = "Esaminando la mappa scopri che si tratta dei piani di battaglia che vuole Hadoken Swiftstrider. Sulla mappa sono disegnate numerose frecce che forse rappresentano movimenti di truppe, anche se quasi tutte sembrano dirette verso sud, e non verso nord, dove si trova Camp Mojache.$B$BUn'altra parte della mappa mostra il disegno di quello che credi sia un grosso insetto di qualche tipo, con sotto varie tacche. A giudicare dagli gnoll, forse rappresentano le loro perdite contro questi insetti sconosciuti...",
  en_title = "Woodpaw Investigation",
  en_obj = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.",
}
T[2903] = {
  title = "I Piani di Battaglia",
  desc = "Ora che hai scoperto i piani di battaglia degli gnoll, non resta che riportarli a Hadoken Swiftstrider, a Camp Mojache. Forse lui, o qualcun altro lì, riuscirà a capire meglio cosa stanno tramando gli gnoll.",
  obj = "Porta i Woodpaw Battle Plans a Hadoken Swiftstrider, a Camp Mojache.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a trovare qualche prova concreta dei piani degli gnoll?",
  reward = "Ah, è proprio quello che ci serviva. Anche se non sono molto abile a decifrare la maggior parte degli scarabocchi di questa mappa, ai miei tempi ho visto abbastanza piani di battaglia da capire cosa sta succedendo con gli gnoll. Sembra che al momento stiano combattendo una guerra su due fronti. Uno è contro di noi... ma pare che le loro energie principali siano rivolte contro un nemico a sud.$B$BQui c'è sotto più di quanto sembri. Forse è il momento di capire chi sia davvero quest'altro nemico che stanno affrontando.",
  en_title = "The Battle Plans",
  en_obj = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.",
}
T[2904] = {
  title = "Un Bel Guaio",
  desc = "<Kernobee geme.> Cos... Cos'è successo?$B$BL'ultima cosa che ricordo è che un gruppo di nani dark iron mi ha catturato, mi ha pestato quasi a morte e poi mi ha buttato qui dentro con questi trogg immondi.$B$BPortami fuori di qui, $N!$B$BEcco il piano: portami all'uscita; se ne usciamo vivi, tu vai a Booty Bay e fai sapere a Scooty che sono andato a Ratchet ad avvertire Tinkerwiz che i dark iron hanno messo mano alla costruzione di quel super macchinario.$B$BMuoviamoci!",
  obj = "Scorta Kernobee fino all'uscita della Clockwerk Run, poi riferisci a Scooty, a Booty Bay.",
  progress = "Eh? Kernobee è vivo??",
  reward = "Immagino che tu meriti una ricompensa per averci riportato Kernobee tutto intero, $N. Se torni a Gnomeregan, questi potrebbero darti il vantaggio che ti serve per sconfiggere quel buono a nulla di un traditore, Mekgineer Thermaplugg.",
  en_title = "A Fine Mess",
  en_obj = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",
}
T[2922] = {
  title = "Salva il Cervello di Techbot!",
  desc = "Quando la nostra amata città di Gnomeregan è caduta, una scintilla impazzita deve aver scosso la mia povera creatura, Techbot. Un tempo aiutava me e i miei soci con i suoi innumerevoli aggeggi e il suo sterminato archivio di informazioni, ma il suo cervello positronico si è polarizzato. Adesso è negatronico... e i comportamenti di Techbot sono invertiti. Si aggira per Gnomeregan in preda alla frenesia!$B$BMa forse si può ancora salvare. Forse, se riesci a recuperare il nucleo di memoria di Techbot e a portarmelo, posso scoprire la causa della polarizzazione e riparare il mio povero Techbot.",
  obj = "Porta Techbot's Memory Core a Tinkmaster Overspark, a Ironforge.",
  progress = "L'hai trovato Techbot? Hai recuperato il suo nucleo di memoria??",
  reward = "Oh, è meraviglioso! Grazie, $N! Mi metto subito al lavoro!!$B$BPovero, povero Techbot... Non prendertela. Ti rimettiamo a posto noi.$B$BOra, dove ho messo lo spinotto della mia chiave idro-snodata...",
  en_title = "Save Techbot's Brain!",
  en_obj = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.",
}
T[2923] = {
  title = "Tinkmaster Overspark",
  desc = "Tinkmaster Overspark è molto turbato per la sorte della sua creatura meccanica, Techbot. Io ricordo Techbot come uno strumento gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.$B$BMolto triste. Ma con un po' di fortuna forse lo si può riparare!$B$BParla con Tinkmaster Overspark, a Tinker Town, a Ironforge. Sarà contento del tuo aiuto.",
  obj = "Parla con Tinkmaster Overspark, a Ironforge.",
  reward = "Sì, è vero. Techbot è impazzito! Ti prego, puoi aiutarmi?",
  en_title = "Tinkmaster Overspark",
  en_obj = "Speak with Tinkmaster Overspark in Ironforge.",
}
T[2924] = {
  title = "Essenziali Artificiali",
  desc = "Un componente meccanico quasi universale — l'essenziale artificiale — era molto utile ai meccanici e ai fabbri di Gnomeregan. Ma durante l'esodo frenetico dalla nostra città nessuno si è ricordato di portarne via nemmeno uno! E a me ne serve una grande scorta per un lavoro che comincerò presto.$B$BTi prego, entra a Gnomeregan e portamene un po'. Li troverai nelle zone più profonde della nostra città, dentro contenitori chiamati estrapolatori artificiali.$B$BGrazie, $N, e fa' in fretta, ti prego!",
  obj = "Porta 12 Essential Artificial a Klockmort Spannerspan, a Ironforge.",
  progress = "Ce li hai gli essenziali artificiali?",
  reward = "Li hai presi! Ora posso cominciare i miei nuovi esperimenti!$B$BNon so come ringraziarti, $N! Il tuo coraggio ha fatto fare alla ricerca gnomica un balzo in avanti!",
  en_title = "Essential Artificials",
  en_obj = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.",
}
T[2925] = {
  title = "Gli Essenziali di Klockmort",
  desc = "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da Ironforge. Mi dice che gli serve aiuto per una missione pericolosa, ma essenziale, dentro Gnomeregan: un tempo era la grande città degli gnomi, ora è contaminata e piena di gnomi impazziti e dei loro congegni.$B$BIo devo restare qui, ma desidero con tutto il cuore aiutare il mio amico. Se puoi andare al mio posto, ti sarò molto obbligato.$B$BKlockmort si trova a Tinkertown, a Ironforge.",
  obj = "Parla con Klockmort Spannerspan, a Ironforge.",
  reward = "Sì! Sì che mi serve aiuto per una missione dentro Gnomeregan. E tu sei proprio $Gil:la; $C che ci vuole!",
  en_title = "Klockmort's Essentials",
  en_obj = "Speak with Klockmort Spannerspan in Ironforge.",
}
T[2926] = {
  title = "Gnogaine",
  desc = "Dall'incidente, Gnoarn non pensa e non parla d'altro: ripulire Gnomeregan dall'infestazione dei trogg e trovare una cura per il male che la affligge, $N.$B$BPer fortuna io e Razzle siamo vicini a una specie di cura — o quello, o la ricetta di un rum davvero potente. Non lo sapremo finché non proviamo! Naturalmente, per provare la nostra teoria ci serviranno alcune cose, cioè la ricaduta radioattiva dei trogg irradiati di Gnomeregan. Riempi questa fiala con il bagliore verde e riportamela!",
  obj = "Usa l'Empty Leaden Collection Phial sugli Irradiated Invader o sugli Irradiated Pillager per raccogliere la ricaduta radioattiva. Quando è piena, riportala a Ozzie Togglevolt, a Kharanos.",
  progress = "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!",
  reward = "Ottimo lavoro! È arrivato il momento di provare la nuova formula. Se funziona, non solo quello gnomo lebbroso catturato dovrebbe guarire, ma io dovrei ritrovarmi con una bella chioma folta! Indietro!",
  en_title = "Gnogaine",
  en_obj = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.",
}
T[2927] = {
  title = "Il Giorno Dopo",
  desc = "Non penserai mica che sia sempre stato calvo, vero? No di certo, $Gsignore:signora;! È stata la fuga di radiazioni a Gnomeregan a causare questa tragica perdita di capelli. Prima di quel giorno avevo l'unico gnomefro di tutta Azeroth.$B$B<Gnoarn agita il pugno in aria.>$B$BMaledetti quei dannati sporchi trogg — maledetti tutti!!$B$BForse non è troppo tardi, $N. Forse possiamo ancora salvarla — la città, intendo! Parla con Ozzie Togglevolt, a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.",
  obj = "Parla con Ozzie Togglevolt, a Kharanos.",
  reward = "Pensavo che perdere quella chioma straordinaria sarebbe stata la sua fine, e invece è sopravvissuto!$B$BEro proprio accanto a lui quando l'ha colpito la scarica di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! E l'orrore è diventato ancora più grande quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, dico! Gnoarn si è toccato la testa pelata incredulo, e il suo sguardo urlava vendetta, $N! Poi ha rivolto la sua rabbia contro i trogg!$B$B<Ozzie rabbrividisce.>",
  en_title = "The Day After",
  en_obj = "Speak with Ozzie Togglevolt in Kharanos.",
}
T[2928] = {
  title = "Gyrodrillmatic Excavationators",
  desc = "È terribile, $N. Non avremo abbastanza pezzi per portare la nostra flotta di gyrodrillmatic excavationators fino a Dun Morogh.$B$BQuel che ci serve sono pezzi di ricambio, $N. E quale posto migliore di Gnomeregan per procurarsi i ricambi dei nostri veicoli? Mi dicono che là dentro bot e mech girano come mandrie al pascolo.$B$BQuel che devi fare è andare a Gnomeregan e fare a pezzi quei robot. Riportami le loro interiora meccaniche. Due dozzine dovrebbero bastare.",
  obj = "Porta ventiquattro Robo-mechanical Guts a Shoni the Shilent, a Stormwind.",
  progress = "Se fosse una gara, a quest'ora avresti perso.",
  reward = "Questi andranno benissimo, $N. Un gyrodrillmatic excavationator riparato; ne restano 398.",
  en_title = "Gyrodrillmatic Excavationators",
  en_obj = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",
}
T[2929] = {
  title = "Il Grande Tradimento",
  desc = "Mi fidavo di Thermaplugg, $R. Non avrei mai immaginato che avrebbe tradito me e l'intero popolo gnomico. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati da casa nostra e quel pazzo comanda. Il re del nulla....$B$BRiprenderemo Gnomeregan, $N. Non ci fermeremo finché la città non tornerà sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.",
  obj = "Va' a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna da High Tinker Mekkatorque a lavoro finito.",
  progress = "Hai portato a termine il compito? Ha implorato clemenza? Pietà??",
  reward = "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stata il tuo piede, $R. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a realizzarsi.",
  en_title = "The Grand Betrayal",
  en_obj = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",
}
T[2930] = {
  title = "Recupero Dati",
  desc = "Quando siamo fuggiti da Gnomeregan ci siamo lasciati dietro tantissimi dati! Dati di importanza vitale!$B$BMi servono i dati su una scheda perforata prismatica, da un terminale ad alta sicurezza Matrice Punchograph 3005-D, nelle profondità di Gnomeregan. Devi accedere a quel terminale, ma per farlo ti serve prima l'autorizzazione... e per averla devi accedere ai terminali a sicurezza più bassa — i modelli -A, -B e -C. E per fare QUELLO ti servono le schede perforate di sicurezza, a cominciare da quella bianca... e le schede perforate le abbiamo lasciate tutte in città.$B$BÈ una catastrofe! Puoi aiutarci?",
  obj = "Porta una Prismatic Punch Card a Master Mechanic Castpipe, a Ironforge.",
  progress = "Ce l'hai la scheda perforata prismatica??",
  reward = "Ce l'hai fatta! Hai trovato la scheda perforata prismatica e recuperato i dati perduti! Dati di importanza vitale, critica, incommensurabile, senza i quali non potremmo vivere un istante di più!$B$BIl servizio che hai reso agli gnomi sarà ricordato a lungo, $N.",
  en_title = "Data Rescue",
  en_obj = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",
}
T[2931] = {
  title = "L'Incarico di Castpipe",
  desc = "Il Maestro Meccanico Castpipe, a Ironforge, ha bisogno di avventurieri! Sta organizzando squadre per rientrare a Gnomeregan in una missione di recupero dati della massima segretezza e importanza.$B$BCastpipe non sarà un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma resta uno gnomo in gamba: quindi, se lui pensa che sia importante, secondo i miei calcoli c'è una probabilità dell'ottantaquattro per cento che lo sia davvero!$B$BSono buone probabilità!",
  obj = "Parla con Master Mechanic Castpipe, a Ironforge.",
  reward = "Sto organizzando missioni di estrazione dati dentro Gnomeregan. Se sei qui per questo, ascolta bene!",
  en_title = "Castpipe's Task",
  en_obj = "Speak with Master Mechanic Castpipe in Ironforge.",
}
T[2932] = {
  title = "Messaggio Cupo",
  desc = "Un tempo i troll Witherbark erano alleati dell'Orda, ma hanno tradito Thrall... e questo va punito!$B$BEcco, prendi la mia picca e va' nelle Hinterlands, lontano a nord. Le troverai a nord-est di Tarren Mill, un villaggio in mano ai nostri alleati, i Reietti.$B$BUna volta nelle Hinterlands, dai la caccia ai troll Witherbark. Raccogli i loro teschi e pianta la mia picca nel terreno in uno dei loro villaggi più piccoli, Hiri'watha o Zun'watha.$B$BFagli vedere che le loro azioni infami hanno delle conseguenze!",
  obj = "Raccogli Witherbark Skulls e mettili su Nimboya's Pike. Pianta Nimboya's Laden Pike in uno dei Witherbark Villages delle Hinterlands, poi torna da Nimboya a Stranglethorn.",
  progress = "Non hai portato a termine il mio compito, $N.",
  reward = "Mi è giunta voce della tua impresa. Un'impresa cupa, ma onorevole. Speriamo che i Witherbarks diano ascolto al tuo messaggio.",
}
T[2933] = {
  title = "Bottiglie di Veleno",
  desc = "Queste bottiglie contengono un veleno verde e ripugnante.$B$BVisto il numero di bottiglie in questo villaggio, i Witherbark devono ritenerlo molto importante. Forse a uno speziale della vicina Tarren Mill farebbe piacere un campione.",
  obj = "Porta una Venom Bottle a uno speziale di Tarren Mill.",
  progress = "Salve, gentile $C. La giornata è stata lunga e nemmeno un esperimento è riuscito...spero che tu mi porti buone notizie.",
  reward = "Ah, e questo cos'è? Sembra veleno... di qualche creatura aracnide, direi. E dove l'hai preso?",
}
T[2934] = {
  title = "Sacca di Veleno Intonsa",
  desc = "Mi serve un campione fresco del veleno che mi hai portato. I ragni da cui è stato raccolto devono vivere negli Hinterlands — dagli la caccia finché non trovi una sacca di veleno intatta, e portamela. Troverai molti ragni vicino alla città troll di Shadra'Alor.$B$BNon indugiare, $N, perché la sacca di veleno dev'essere fresca quando me la consegni.",
  obj = "Porta un'Undamaged Venom Sac ad Apothecary Lydon a Tarren Mill.",
  progress = "Hai la sacca di veleno intatta, $N? Non vedo l'ora di fare esperimenti con il suo veleno fresco, e ho ordinato una collezione di animaletti terribilmente carini su cui provarlo!",
  reward = "Oh, splendido! Il veleno è freschissimo e, ne sono certo, molto letale. Grazie!",
}
T[2935] = {
  title = "Consulta il Maestro Gadrin",
  desc = "Il veleno dei guardiani della covata non era potente come quello che mi avevi portato la prima volta. Dev'essere di un altro ragno.$B$BVoglio un campione fresco di quel veleno. Per scoprire da dove viene, devi consultare un troll che conosce bene i Witherbark — il Maestro Gadrin, a Sen'jin Village. Va' in Durotar e parla con Gadrin. Con un po' di fortuna, saprà dove prendono il veleno i Witherbark.",
  obj = "Parla con Master Gadrin a Sen'jin Village.",
  reward = "Ah, quindi vuoi il veleno fresco del ragno dei witherbark, eh? Be', siediti... quello che ho da dirti non ti piacerà.",
}
T[2936] = {
  title = "La Dea Ragno",
  desc = "I Witherbark adorano una dea ragno, e da lei raccolgono il loro veleno più potente. Quindi, se vuoi il veleno, devi evocare la loro dea!$B$BPer farlo devi conoscere il suo vero nome, e quel nome è su una tavoletta sepolta a Tanaris, nella città troll di Zul'Farrak, in una tomba sorvegliata da Theka il Martire.$B$BSconfiggi Theka, trova la sua tavoletta e leggila per scoprire il nome della dea ragno. Quando lo conoscerai, torna da me.",
  obj = "Leggi la Tablet of Theka per scoprire il nome della dea ragno dei Witherbark, poi torna da Master Gadrin.",
  progress = "Conosci il nome della dea ragno?",
  reward = "Ah, Elortha no Shadra... pronuncia questo nome solo a bassa voce, perché nei regni dello spirito ha un gran peso.$B$BLo metterò per iscritto e creerò per te un incantesimo di evocazione...",
  en_title = "The Spider God",
  en_obj = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.",
}
T[2937] = {
  title = "Evocare Shadra",
  desc = "Prendi la sua pergamena e leggila all'altare di Shadra'Alor, nel profondo del regno dei Witherbark, negli Hinterlands. Così evocherai Shadra, la dea ragno.",
  obj = "Sconfiggi Shadra all'altare di Shadra'Alor, poi porta il suo veleno ad Apothecary Lydon a Tarren Mill.",
  progress = "Hai preso il veleno?",
  reward = "Splendido, ce l'hai!",
}
T[2938] = {
  title = "Veleno per Undercity",
  desc = "Il veleno che hai preso alla dea ragno dei Witherbark è davvero una bella scoperta! Con una sola goccia di quella roba sono riuscito a uccidere quasi due dozzine di conigli. Certo, alcuni erano molto giovani, e tanto piccoli da stare nel palmo di una mano, quindi di sicuro resistevano poco alle tossine, ma non si può negare che questo veleno sia potente!$B$BVorrei che un campione arrivasse al mio superiore, lo Speziale Faranell, nell'Apothecarium di Undercity. Sono certo che vorrà provarlo di persona.",
  obj = "Porta Faranell's Parcel a Master Apothecary Faranell a Undercity.",
  progress = "Mi hanno annunciato il tuo arrivo, $N. Hai un pacco per me?",
  reward = "Ah, molto bene. Lydon mi ha detto che il veleno di questo pacco è il più potente con cui sia mai venuto a contatto, e ora è impegnato a studiarne nuovi impieghi.$B$BCon un po' di fortuna, ne troveremo molti.$B$BGrazie, $N. Nessuno può negare il servizio che hai reso alla Royal Apothecary Society.",
}
T[2939] = {
  title = "In Cerca di Conoscenza",
  desc = "Le rovine di Feralas possono essere molto pericolose, ma hanno molto da raccontare su quello che è successo qui.$B$BQualche giorno fa, frugando fra le macerie a sud, ho scoperto quello che sembra un normale bastone. Eppure non riesco a togliermi di dosso la sensazione che ci sia qualcosa di più. Angelas e io abbiamo passato ore sui nostri libri, ma non troviamo niente al riguardo.$B$BHo una collega a Darnassus che potrebbe dirci di cosa si tratta, $N. Perché non vai a parlarle e vedi se può aiutarci?",
  obj = "Parla con Daryn Lightwind, a Rut'theran Village.",
  reward = "Oh, quindi ti manda Troyas Moonbreeze?$B$B<borbotta>...sempre a infastidirmi con le sue idee strampalate di aver trovato qualcosa di importante...$B$BSenti, $N, sarò franca. Troyas crede sempre di aver trovato qualcosa di importante in quelle rovine. La verità è che tutto quello che aveva davvero valore è stato probabilmente accaparrato molto tempo fa dagli ogre o dalle arpie che ora vivono lì.$B$BPuoi dare un'occhiata, se vuoi, ma non so se troverai qui dei libri che possano esserti utili.",
}
T[2940] = {
  title = "Feralas: Una Storia",
  desc = "Sembra che nessuno apra questo libro da moltissimo tempo. Le copertine sono consumate e le pagine ingiallite, ma esaminandolo ti accorgi che potrebbe essere proprio quello che Troyas sta cercando.$B$BLo prendi, ma ti rendi conto che forse dovresti chiedere prima di portarlo via.",
  obj = "Chiedi a Daryn Lightwind se puoi prendere in prestito il suo libro.",
  reward = "Allora, vorresti prendere in prestito Feralas: Una Storia?$B$BFammi pensare...$B$BTi presterò questo libro, $N, ma solo se prima farai qualcosa per me.",
}
T[2941] = {
  title = "Chi Chiede in Prestito",
  desc = "Nella mia vita ho studiato molte materie, e la mia ultima passione sono le tartarughe azzannatrici che popolano la spiaggia delle Hinterlands. Ce n'è una in particolare che vorrei vedere: una tartaruga azzannatrice gigante di nome Gammerita. Ci andrei di persona, ma le mie ricerche mi trattengono qui. Credo che una sua immagine sarebbe il ripiego migliore.$B$BPorta questa lettera a Curgle Cranklehop, a Tanaris. Ha creato per me un'invenzione che può catturare un'immagine. L'ha chiamata \"istantanea\", credo...",
  obj = "Porta la lettera a Curgle Cranklehop, a Tanaris.",
  progress = "Una lettera — per me?",
  reward = "Sei $Gun altro degli apprendisti:un'altra delle apprendiste; di Daryn? È una storica molto preparata, $N. Dovresti essere $Ggrato:grata; di studiare sotto la sua guida.$B$BE ora vado a prendere il Fotomatic FX. Ti piacerà da morire!",
}
T[2942] = {
  title = "La Pietra del Domani",
  desc = "Nel momento in cui togli l'artefatto dal Monolito, senti l'energia del Bastone di Equinex cominciare a svanire.",
  obj = "Riporta la Sparkling Stone e lo Stave of Equinex a Troyas Moonbreeze, alla Feathermoon Stronghold.",
  progress = "Sono contento che tu sia $Gtornato:tornata;, $N. Non vedo l'ora di sapere cosa hai scoperto.",
  reward = "Da quando sei $Gpartito:partita; ho continuato a leggere, $N. La pietra che hai trovato si chiama Pietra del Domani. Anche se non sono ancora del tutto sicuro di quale sia il suo scopo, puoi star $Gcerto:certa; che è qualcosa di grande importanza, se era nascosta così dentro il Monolito di Equinex.$B$BContinuerò i miei studi, e spero di poter contare su di te in futuro, $N. Grazie di tutto il tuo aiuto.",
}
T[2943] = {
  title = "Ritorno da Troyas",
  desc = "Eccolo, $N. Ti prego, abbi cura del mio libro.$B$BE ora sbrigati. Sono sicura che Troyas non vede l'ora che tu torni.",
  obj = "Consegna il libro a Troyas Moonbreeze, alla Feathermoon Stronghold.",
  progress = "Ciao, $N. Sei $Gstato:stata; a Darnassus?",
  reward = "Hai portato un libro. Ottimo!",
}
T[2944] = {
  title = "Il Fotomatic FX",
  desc = "Sarai $Gil primo:la prima; a vedere la mia nuova invenzione, $N. Devi solo inquadrare quello che vuoi fotografare e premere il pulsante.$B$BCom'era quella creatura delle Hinterlands di cui mi hai parlato? Gammerita? Be', buona fortuna a trovarla. Sono sicura che Daryn sarà molto contenta dell'istantanea che le porterai.$B$BComunque, ecco il Fotomatic. Divertiti!",
  obj = "Usa il Super Snapper FX per scattare un'istantanea di Gammerita, poi torna da Daryn Lightwind, a Rut'theran Village.",
  progress = "Dunque sei finalmente $Gtornato:tornata;, $N. E hai portato l'aggeggio che Curgle ha costruito per me — perfetto.",
  reward = "Però! L'invenzione di Curgle è stata all'altezza delle aspettative.$B$BNon montarti la testa, ma sappi che sono soddisfatta del tuo lavoro, $N.$B$BE ora, dove ho lasciato quel libro...",
}
T[2945] = {
  title = "Anello Sudicio",
  desc = "Dal cadavere di uno dei nani Dark Iron hai tirato fuori quello che sembra un anello. È difficile però dire che tipo di anello sia: terra e residui induriti lo ricoprono del tutto e rendono impossibile indossarlo. Ti pare di intravedere il lieve luccichio di un metallo prezioso e forse perfino il bagliore di una gemma sotto i residui.$B$BSe vuoi servirti di questo anello, dovrai trovare qualcosa per togliergli i residui induriti.",
  obj = "Trova un modo per togliere la sporcizia dal Grime-Encrusted Ring.",
  progress = "L'aggeggio gnomico davanti a te ha una targa che dice \"Lo Sparklematic 5200\". Dalle istruzioni sotto la targa si capisce che, in sostanza, la macchina serve a strofinare via lo sporco dagli oggetti. Ha una fessura per le monete: una volta messo dentro l'oggetto, ci vogliono tre monete d'argento per avviare il processo.$B$BPare proprio che l'anello incrostato di sporcizia che hai trovato prima sia la cosa giusta da provare in questa macchina!",
  reward = "Metti l'anello dentro lo Sparklematic 5200 e infili una moneta d'argento nella fessura.$B$BDalla macchina escono stridori strazianti mentre comincia a sobbalzare violentemente. Si può solo immaginare cosa stia succedendo all'anello là dentro...$B$BLa macchina si ferma di colpo e annuncia la fine con un semplice \"Ding!\". Lo scomparto si apre e rivela una scatoletta incartata con cura, con un fiocco rosso. Pare che lo Sparklematic 5200 faccia anche i pacchetti regalo!",
  en_title = "Grime-Encrusted Ring",
  en_obj = "Figure out a way to remove the grime from the Grime-Encrusted Ring.",
}
T[2946] = {
  title = "Vedere Cosa Succede",
  desc = "Vogliamo che porti i dischi in miniatura che hai trovato alle porte sigillate di Uldum. Non... non sappiamo bene cosa succederà quando lo farai.$B$BSembra rischioso, certo, lo ammettiamo. Però potrebbe anche non succedere niente. Potresti dover usare i dischi su qualcosa. Forse le porte si sbloccano quando hai i dischi con te. Sii $Gdisposto:disposta; a provare qualsiasi cosa, e $Gpronto:pronta; a qualsiasi evenienza.$B$BQuando avrai scoperto cosa succede, torna a Ironforge. A cose fatte avremo un bel po' da analizzare!",
  obj = "Porta i Miniature Platinum Discs alle porte di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.",
  progress = "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui ha un significato...",
  reward = "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman vibrano e brillano nel tuo zaino. Un formicolio familiare ti attraversa le mani, mentre l'immagine di un altro Guardiano di Pietra prende vita davanti alle porte di Uldum.$B$B\"Saluti. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Piastre di Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza di accesso. Grazie.\"",
}
T[2947] = {
  title = "Il Ritorno dell'Anello",
  desc = "Aprendo la scatola uscita dallo Sparklematic 5200 trovi quel che sospettavi — un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.$B$BAll'interno dell'anello c'è un'impronta piccola ma comunque riconoscibile del sigillo di Ironforge. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o restituirlo a questa persona. Che dilemma...",
  obj = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni al suo interno.",
  progress = "Ehi, calma, socio — sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei $Gil mio padrone:la mia padrona; di casa.$B$BMa certo che no — che sciocco! Sei $Gvenuto:venuta; da me perché cerchi il miglior gioielliere di tutta Ironforge, uno che NON fa oggetti MALEDETTI! Sì!$B$BEhm... di cosa hai bisogno?",
  reward = "Un anello, dici? Vediamo... sì, perbacco, quell'anello l'ho fatto io.$B$BPrima che Gnomeregan saltasse avevo una botteguccia là. Forse è uno di quelli che mi sono lasciato dietro quando sono scappato a gambe levate: è un modello semplice, e ne ho fatti parecchi così. Magari era di qualcuno che non ce l'ha fatta a uscire.$B$BCe l'avevano dei nani Dark Iron? Be', questo aggiunge uno strato di cospirazione ai nove che già girano. Forse le autorità vorrebbero saperlo; con uno come me è fiato sprecato.$B$BOra, torniamo all'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2948] = {
  title = "Miglioria Gnomesca",
  desc = "Senti, $N, quell'anello è tuo, certo... ma te ne posso fare uno migliore! Quel disegno, come ti ho detto, è davvero semplice. Ora sono molto più bravo, e per la modica cifra di trenta monete d'argento te lo rifaccio più bello! Be', un pochino più di trenta, a dire il vero...$B$BAl momento sono messo male; le mie scorte di materiali sono tutte esaurite. Se mi porti una barra d'argento e un'agata muschiata, aggiungo all'anello un reticolo d'argento e agata che gli darà un po' più di brio!$B$BFidati!",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Talvash del Kissel, a Ironforge.",
  progress = "Ce li hai i materiali che mi servono? Non te li chiederei, se non stessi passando un brutto periodo...",
  reward = "Ah, proprio quel che mi serviva! Un giorno, quando sarò uscito da questo buco in cui mi trovo ingiustamente, farò per te, anzi, per TUTTI, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie di non aver fatto storie per i reagenti. Di solito per un anello di questa qualità chiedo dieci volte tanto...$B$BA proposito di anelli, ecco quello nuovo!",
  en_title = "Gnome Improvement",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.",
}
T[2949] = {
  title = "Il Ritorno dell'Anello",
  desc = "Aprendo la scatola uscita dallo Sparklematic 5200 trovi un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.$B$BAll'interno dell'anello c'è un'impronta piccola ma comunque riconoscibile del sigillo di Orgrimmar. Accanto ci sono delle lettere incise, ma anche dopo la pulizia se ne distinguono solo le prime tre: \"NOG...\"$B$BPotrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o trovare \"NOG\" — che dilemma...",
  obj = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni al suo interno.",
  progress = "Verrebbe da pensare che un modo per battere quegli sporchi gnomettini riusciremmo a trovarlo da soli. Anzi, scommetterei che in origine quella macchina l'hanno rubata a noi! Bah, quegli unti, lerci... ehm, sì? Ti serve qualcosa?",
  reward = "Un anello da Gnomeregan? Vediamo... non è mio, ma è interessante.$B$BLa faccenda di Gnomeregan — non poteva capitare a una banda di teste di legno più simpatica. Per anni sono stati una barzelletta, e adesso, quasi da un giorno all'altro, costruiscono macchine migliori delle nostre?$B$BCe l'avevano dei nani Dark Iron, l'anello? Questo è ancora più interessante! Sai, magari gli gnomi hanno rubato i loro folli progetti di golem e li hanno modificati. E quei Dark Iron vorrebbero di sicuro vendicarsi come si deve. Vale proprio la pena di indagare.$B$BA proposito, quell'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2950] = {
  title = "L'Anello Rifatto da Nogg",
  desc = "No, no, no — non sto dicendo che all'improvviso l'anello è mio. Di solito non lo faccio, ma le tue informazioni sui Dark Iron sono state molto utili. Te lo miglioro io l'anello, meglio di come avrebbe mai potuto fare chi ha fatto questa cosetta semplice. Probabilmente qualche gnomo...$B$BSe mi porti una barra d'argento, un'agata muschiata e trenta monete d'argento per il disturbo, aggiungo all'anello un reticolo d'argento e agata che rafforzerà la magia che ha dentro. Ti interessa?",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Nogg, a Orgrimmar.",
  progress = "Ce li hai i materiali che mi servono? Senza tutto quel che ti ho chiesto non posso migliorare questo lavoro.",
  reward = "Ecco il tuo anello, meglio di prima. Grazie ancora per le informazioni su quei nani Dark Iron. Sembra una buona pista per capire come mai quegli gnomi si siano ritrovati di colpo con un'ispirazione da goblin.",
  en_title = "Nogg's Ring Redo",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",
}
T[2951] = {
  title = "Lo Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"Lo Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Object nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina rimbombano forti e violenti rumori di rimescolio. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[2952] = {
  title = "Lo Sparklematic 5200!",
  reward = "Rapido com'era partito, lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta chiusa da un fiocchetto. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è solo un modo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[2953] = {
  title = "Ancora un Giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Lo scomparto della macchina si apre a spirale e rivela una scatola incartata con cura.",
  en_title = "More Sparklematic Action",
}
T[2954] = {
  title = "Lo Stone Watcher",
  desc = "\"Saluti — sono un guardiano dell'ingresso. Se non hai già integrato le Piastre di Uldum nella tua serie di dischi, non consentirò l'ingresso nel complesso di Uldum.\"$B$BLa comparsa dello Stone Watcher of Norgannon dev'essere la reazione che si sperava di ottenere mandandoti nel deserto di Tanaris con i dischi di platino. Come da istruzioni, prima di proseguire dovrai scoprire cosa c'è dietro lo Stone Watcher.",
  obj = "Scopri qual è la funzione dello Stone Watcher of Norgannon, poi interagisci con l'Uldum Pedestal nel deserto di Tanaris.",
  progress = "Prima di proseguire bisogna scoprire la funzione del guardiano di pietra...",
  reward = "La voce del guardiano di pietra risuona di potenza e autorità:$B$B\"I tuoi dischi ti saranno restituiti quando accederai al piedistallo. Quando avrai ottenuto le Piastre di Uldum e le avrai incorporate nella serie di dischi che già possiedi, potrai entrare nel complesso.\"",
}
T[2962] = {
  title = "L'unica cura è altro bagliore verde",
  desc = "Il tuo campione non solo era insufficiente per quantità: era anche impuro.$B$BQuel che ci serve è altro bagliore verde. È chiaro che i trogg non sono irradiati abbastanza per i nostri scopi. Dovrai entrare a Gnomeregan e riportare della ricaduta radioattiva, presa direttamente alla fonte. Parlo delle creature irradiate: melme, predatori in agguato e orrori. Attenzione: contenere questo tipo di ricaduta è difficile. Potresti dover fare diversi tentativi con la fiala prima di recuperare un campione adatto.",
  obj = "Va' a Gnomeregan e riporta un High Potency Radioactive Fallout. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.$B$BA lavoro finito Ozzie vorrà anche la tua Heavy Leaden Collection Phial.",
  progress = "Hrm, non brilli. È un buon segno.",
  reward = "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti al loro posto. Ora vediamo cosa sa fare questa roba!",
  en_title = "The Only Cure is More Green Glow",
  en_obj = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.$B$BOzzie will also require your Heavy Leaden Collection Phial when the task is complete.$B",
}
T[2963] = {
  title = "Presagi di Uldum",
  desc = "Salve di nuovo, $N! La tua scoperta a Uldaman ha messo in fermento la Lega degli Esploratori. La Lega sta lavorando per svelare i segreti dei dischi di platino in miniatura che hai trovato. Il tuo arrivo fortuito qui nella Sala mi permette di dirti che molto probabilmente siamo sulla pista giusta!$B$BLo Storico Karnik ha scoperto degli indizi importanti sulle vere origini della Valle dei Guardiani, nel deserto di Tanaris. Vorrebbe parlarti il prima possibile!",
  obj = "Parla con Historian Karnik a Hall of Explorers, a Ironforge.",
  reward = "Sono contento che il tuo interesse per l'esplorazione non si sia spento, $N! Con il tuo talento naturale e la tua grinta potremmo svelare segreti che non avremmo mai creduto possibili!$B$BI Dischi di Norgannon, a Uldaman, erano un archivio di informazioni sterminate; a te è stato concesso di accedere solo agli strati superiori, per così dire, delle informazioni lì custodite. Si diceva che i Creatori avessero altri archivi sparsi per tutta Azeroth. E questo ci porta a Uldum...",
}
T[2964] = {
  title = "Un Compito Futuro",
  desc = "Be', $N... a quanto pare siamo in un vicolo cieco, per il momento. Sappiamo cosa ci serve — le Piastre di Uldum — ma non abbiamo idea di dove possano essere. Dovremo fare parecchie ricerche per mettere insieme un piano d'attacco solido. Ho un paio di idee su dove cominciare a cercare; ho buone speranze che presto ti chiederemo di partire per recuperarle.$B$BIl Sommo Esploratore deve esserne informato, $N; di sicuro vorrà anche ringraziarti di persona per aver aiutato ancora una volta la Lega.",
  obj = "Parla con High Explorer Magellas a Ironforge.",
  reward = "Allora siamo tutti d'accordo — il miglior piano d'attacco è mettere la cosa in sospeso finché non riusciremo a restringere le zone in cui queste piastre potrebbero essere nascoste. Ci hai portati fin qui, $N, e spero che sarai tu a tornare sul campo per aprire Uldum per tutti noi!$B$BNel frattempo permettimi di darti questo onorario; dovrebbe coprire le spese che hai sostenuto per aiutarci, più un piccolo extra. Ricordati di ripassare presto da noi... Uldum chiama!",
}
T[2965] = {
  title = "Presagi di Uldum",
  desc = "Ah, $N, è una fortuna che tu sia $Gvenuto:venuta; di nuovo da me. Le tue scoperte agli scavi di Uldaman hanno di certo dato a noi saggi molto di cui discutere. Ne stavo parlando proprio con una dei druidi, Nara Wildmane, quando mi è venuto in mente che le sue passate esperienze di avventuriera potrebbero avere grande importanza per il prossimo passo da compiere.$B$BVorrei che tu parlassi con lei dei suoi viaggi nella Valle dei Guardiani, nel deserto di Tanaris. Ti aspetta sull'Altura degli Anziani.",
  obj = "Parla con Nara Wildmane, sull'Elder Rise di Thunder Bluff.",
  reward = "Nel cuore del deserto di Tanaris c'è un luogo chiamato Valle dei Guardiani. I dischi che hai recuperato... i loro glifi tradotti parlano di un luogo chiamato Uldum. Quasi tutti pensano che sia un mito.$B$BIo so che non è così; Uldum esiste. Ci sono stata. Be'... fuori, almeno.$B$BIl punto è questo, $N: pensiamo che ci sia un legame tra i dischi e Uldum, e vogliamo che tu ci vada.",
  en_title = "Portents of Uldum",
  en_obj = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.",
}
T[2966] = {
  title = "Vedere Cosa Succede",
  desc = "Il Saggio Truthseeker e io vorremmo che portassi i dischi in miniatura che hai trovato alle porte sigillate di Uldum. Non... non siamo sicuri di cosa succederà quando lo farai.$B$BSembra rischioso, certo, lo riconosciamo. Ma potrebbe anche non succedere niente. Forse dovrai usare i dischi su qualcosa. Forse le porte si aprono quando hai i dischi con te. Sii $Gdisposto:disposta; a provare qualsiasi cosa, e $Gpronto:pronta; a qualsiasi evenienza.$B$BScopri quello che puoi, poi torna da me. Avremo molto di cui parlare.",
  obj = "Porta i Miniature Platinum Discs alle porte di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.",
  progress = "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui ha un significato...",
  reward = "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman vibrano e brillano nel tuo zaino. Un formicolio familiare ti attraversa le mani, mentre l'immagine di un altro Guardiano di Pietra prende vita davanti alle porte di Uldum.$B$B\"Saluti. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Piastre di Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza di accesso. Grazie.\"",
  en_title = "Seeing What Happens",
  en_obj = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.",
}
T[2967] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Accedi di nuovo al piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.$B$BOra che hai appreso ciò che sa il guardiano di pietra e i dischi sono tornati in tuo possesso, è giunto il momento di tornare a Thunder Bluff e informare Nara Wildmane della tua scoperta.",
  obj = "Parla con Nara Wildmane, a Thunder Bluff.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a usare i dischi a tuo vantaggio, o è stato tutto inutile?",
  reward = "Ti mancavano dei dischi? È interessante: sembra che i Dischi di Norgannon siano solo una parte della serie completa — come le chiavi di un mazzo, per così dire.$B$BSe riusciamo a trovare le Piastre di Uldum, potremmo davvero accedere al complesso di Uldum. Non so se esserne entusiasta o terrorizzata.$B$BPotremmo dover rischiare tutto per fare in modo che i segreti custoditi dalla terra, che ci distruggerebbero tutti, restino ciò che sono — segreti.",
  en_title = "Return to Thunder Bluff",
  en_obj = "Speak with Nara Wildmane in Thunder Bluff.",
}
T[2968] = {
  title = "Un Compito Futuro",
  desc = "Be', $N... sembra che siamo arrivati a un punto morto, purtroppo. Sappiamo cosa ci serve — le Piastre di Uldum — ma non abbiamo idea di dove possano essere. Faremo delle ricerche, e poi elaboreremo un solido piano d'attacco. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di unirti di nuovo ai nostri sforzi per scoprire la verità.$B$BIl Saggio Truthseeker deve esserne informato, $N; di certo vorrà anche ringraziarti di persona per aver risposto ancora una volta alla chiamata.",
  obj = "Parla con Sage Truthseeker, a Thunder Bluff.",
  reward = "Siamo tutti d'accordo, allora — la cosa migliore è aspettare finché non riusciremo a restringere le zone in cui potrebbero essere nascoste queste piastre. Ci hai portati fin qui, $N, e spero che sarai tu a tornare sul campo per affrontare i segreti di Uldum.$B$BNel frattempo permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più un piccolo extra. Torna presto a trovarci... Uldum chiama tutti noi, giovane.",
  en_title = "A Future Task",
  en_obj = "Speak with Sage Truthseeker in Thunder Bluff.",
}
T[2969] = {
  title = "Libertà per Tutte le Creature",
  desc = "Quei luridi del clan Grimtotem stanno catturando i draghi fatati, $N. Jer'kai e io non abbiamo idea di cosa vogliano farne, ma di certo non hanno buone intenzioni.$B$BNon siamo abbastanza forti per aprirci la strada nell'accampamento e liberare i draghi prigionieri, ma forse con il tuo aiuto...$B$BSe te la senti e hai qualche amico forte, libera le creature dalla gabbia con questa chiave e fa' in modo che ne escano vive. Sarò al tuo fianco per tutto il tempo. Jer'kai resterà qui.",
  obj = "Con la Bamboo Cage Key, libera gli Sprite Darter dal recinto nell'accampamento Grimtotem. Devono sopravvivere almeno 6 Sprite Darter e Kindal Moonweaver.$B$BHai 6 minuti prima che Kindal decida che è ora di ritirarsi e la missione fallisca.",
  progress = "Non possiamo permettere che il clan Grimtotem distrugga queste splendide creature. Devono essere liberate!",
  reward = "Sia lodata Elune, $N! Sei una grande benedizione per noi e per i draghi fatati che hai salvato. Jer'kai e io non saremmo mai riuscite ad aiutare i draghi da sole — il tuo intervento negli affari dei Grimtotem non sarà dimenticato.$B$BOra parla con Jer'kai... io devo prepararmi per la nostra rappresaglia. Il fatto che i draghi fatati siano liberi non vuol dire che lo resteranno. Jer'kai e io adesso passeremo all'attacco.",
}
T[2970] = {
  title = "Giustizia da Dispensare",
  desc = "Come ti ha già detto, ora Kindal e io passeremo all'attacco contro i Grimtotem. Insieme dovremmo riuscire ancora a far fuori qualche tauren senza correre troppi rischi, ma ci piacerebbe un po' d'aiuto, se te la senti e ne hai la possibilità.$B$BHai visto l'accampamento qui sotto, ma ce ne sono altri a est. Con la tattica che preferisci, infliggi ai tauren tutti i danni che puoi. Ci ritroveremo qui dopo che avranno assaggiato le frecce di Kindal e le tue armi.",
  obj = "Uccidi 12 Grimtotem Naturalist, 10 Grimtotem Raider e 6 Grimtotem Shaman, poi torna da Jer'kai Moonweaver, a Feralas.",
  progress = "A Kindal serve tempo per prepararsi, ma abbiamo già ucciso decine di nemici. Il clan Grimtotem sa benissimo che siamo nella zona, e i suoi membri ci danno la caccia come vipere.$B$BFaranno tutto il possibile per staccarci la testa dal collo. Sta' $Gattento:attenta;... ora che ti sei $Gintromesso:intromessa;, verranno a cercare anche te.",
  reward = "Kindal aveva ragione su di te, $N — ci sai proprio fare. Hai molta più esperienza di noi due, e per questo ti ringraziamo.$B$BIl clan Grimtotem è molto più ostile della maggior parte dei tauren... Mi chiedo se la loro stessa gente disapprovi le loro azioni. Non me ne stupirei. Come probabilmente sai, molte razze di Azeroth sono legate a parenti meno benevoli.$B$BMa di questo parleremo un'altra volta.",
}
T[2972] = {
  title = "Giustizia da Dispensare",
  desc = "Qui fuori, nelle terre selvagge, Kindal e io abbiamo pochi mezzi per ricompensare il tuo aiuto, ma non vogliamo che tu ti senta poco $Gapprezzato:apprezzata;. Prendi il mio anello con sigillo. Se mai ti troverai fra i rami di Teldrassil, va' al Tempio della Luna, nel cuore di Darnassus. Lì troverai la mia Somma Sacerdotessa Tyrande Whisperwind. L'anello le farà sapere che stiamo bene e renderà credibile il tuo racconto.$B$BTi ringraziamo tutte e due, $N.",
  obj = "Porta Jer'kai's Signet Ring a High Priestess Tyrande Whisperwind, a Darnassus.",
  progress = "Salve, $Gfiglio:figlia;. Ci rallegra avere qui nel tempio avventurieri più potenti. Se hai tempo, racconteresti una storia o due agli avventurieri più giovani? So che a molti di loro la tua saggezza farebbe bene.$B$BScusami, che scortese da parte mia. Sei $Gvenuto:venuta; al Tempio in cerca del nostro aiuto, e sono io a chiederti un favore. Perdonami, ti prego. Dimmi cosa possono fare per te i servitori della Luce.",
  reward = "È una storia straordinaria, $N. Ci rallegra che tu abbia aiutato non solo la stirpe dei draghi, ma anche una delle nostre sacerdotesse. Jer'kai ha fatto bene a mandarti da me. Farò in modo che le venga restituito il suo anello — presto alcuni miei esploratori partiranno in direzione di Feralas. Sarà una cosa in più da verificare durante la loro missione.$B$BGrazie ancora e, ti prego, finché sei qui fa' come se fossi a casa tua.",
}
T[2973] = {
  title = "La Lucentezza di un Nuovo Mantello",
  desc = "$GBen trovato:Ben trovata;, $C. Sono venuto in Feralas con i miei compagni, in missione per conto dei nostri superiori di Orgrimmar.$B$BLa mia compagna di vita, Korrin, adora i vestiti nuovi, quindi voglio farle un nuovo mantello adornato con le ali diafane dei draghi fatati. Potresti aiutarmi? I folletti sfreccianti con le splendide ali che voglio si trovano a ovest di Camp Mojache.",
  obj = "Porta 10 Iridescent Sprite Darter Wing a Krueg Skullsplitter, a Camp Mojache.",
  progress = "I folletti sfreccianti possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi tendono a rintanarsi anche loro nelle foreste.$B$BQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne certo!",
  reward = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.$B$BSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per essere clemente, ma è chiaro che te la sei $Gcavato:cavata; bene.$B$BGrazie ancora, $C.",
  en_title = "A New Cloak's Sheen",
  en_obj = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.",
}
T[2974] = {
  title = "Una Scoperta Cupa",
  desc = "Cosa?! Hai incontrato dei tauren da queste parti? Stai scherzando! Che aspetto avevano?!$B$BIl clan Grimtotem! Ne hai trovati alcuni? Belgrom, uno dei nostri superiori, ha un interesse per quelli come loro... ha perfino messo una taglia su di loro.$B$BDevi tornarci, $C. Torna e portami le loro corna... a mucchi, se puoi. I Grimtotem non vanno presi alla leggera né sottovalutati. Torna e uccidili; che i fiumi di Feralas scorrano rossi del loro sangue oscuro.",
  obj = "Porta 20 Grimtotem Horn a Krueg Skullsplitter, a Camp Mojache.",
  progress = "Prendi sul serio le mie parole, $C: il clan Grimtotem è malvagio. Se hai scoperto dove si trovano, tocca a te tornare e sferrare il primo colpo contro il loro clan... prima che possano venire nelle nostre terre e radere al suolo i nostri villaggi, o saccheggiare le nostre terre.",
  reward = "Sono buone corna, $C. Ben fatto. Le prendo io, e mi assicurerò di dirlo a Belgrom appena torneremo a Orgrimmar. Mi hai aiutato due volte, ormai, e per questo hai il mio riconoscimento. Forse in futuro potrò aiutarti io! Buona fortuna.",
  en_title = "A Grim Discovery",
  en_obj = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.",
}
T[2975] = {
  title = "Gli Ogre di Feralas",
  desc = "Gli effetti della tribù degli Ogre Gordunni non possono passare inosservati da queste parti. Guardati intorno, $N: la loro sola presenza sfregia questa terra. Dobbiamo respingerli prima che si espandano ancora di più in Feralas.$B$BSegui il fiume verso nord e troverai il loro avamposto. Riduci il loro numero, $N. Dobbiamo mostrare loro che qui la loro specie non è gradita.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Ogre, 10 Gordunni Ogre Mage e 5 Gordunni Brute.",
  progress = "Muoviti in fretta, $N. O il compito che ti ho chiesto è troppo difficile?",
  reward = "Eccellente, $N. Col tempo, la terra guarirà. Non dobbiamo arrenderci.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.",
}
T[2976] = {
  title = "Una Scoperta Cupa",
  desc = "Cosa?!$B$BAh, allora ho parlato di una taglia, vero? Be', così imparo ad aprire bocca, no?$B$BIl lavoro l'hai fatto tu, quindi immagino sia giusto che tu ne raccolga la ricompensa più grande. Prendi le corna: le farò mettere in una cassa per te. Trova Belgrom Rockmaul nella Valle dell'Onore: vorrà sapere cosa hai visto, e ti ricompenserà per il tuo duro lavoro.$B$BStammi bene, $C, e grazie ancora per tutto quello che hai fatto.",
  obj = "Porta la Crate of Grimtotem Horns a Belgrom Rockmaul, a Orgrimmar.",
  progress = "Fa' presto, $C, oggi ho molto da fare.",
  reward = "I Grimtotem!? Interessante. Dici di averli incontrati mentre cacciavi in Feralas? Davvero?$B$BI miei pari vorranno sentire le tue notizie, $C. Raccontami di più, e intanto ti conto le monete.$B$BE prima che tu vada, sappi che ti ringrazio per le informazioni che mi hai dato oggi.",
  en_title = "A Grim Discovery",
  en_obj = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.",
}
T[2977] = {
  title = "Ritorno a Ironforge",
  desc = "Accedi di nuovo al piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.$B$BOra che hai appreso le conoscenze del guardiano di pietra e i dischi sono tornati in tuo possesso, è arrivato il momento di tornare a Ironforge e informare la Lega degli Esploratori della tua scoperta.",
  obj = "Parla con Historian Karnik a Ironforge.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a usare i dischi a tuo vantaggio, o si è rivelato un viaggio a vuoto?",
  reward = "Ti mancavano dei dischi? Cosa curiosa, pare che i dischi di Norgannon siano solo una parte della serie completa — come le chiavi di un mazzo, se vogliamo.$B$BSe riusciamo a trovare le Piastre di Uldum, potremmo addirittura entrare nel complesso di Uldum vero e proprio! Immagina di esplorare davvero il luogo in cui lavoravano i Creatori senza doverti portare dietro una pala enorme!$B$BNon che ci sia qualcosa di male nelle pale... o nello scavare...",
}
T[2978] = {
  title = "La Pergamena di Gordunni",
  desc = "Raccogliendo la pergamena sudicia, noti che sembra raffigurare una specie di incontro o di cerimonia. A Rok Orhan interesserebbe questa pergamena, e cosa potrebbe significare per i Gordunni.",
  obj = "Porta la Gordunni Scroll a Rok Orhan, a Camp Mojache.",
  progress = "Cos'è questo?",
  reward = "Questa pergamena... L'hai trovata nell'Avamposto dei Gordunni?",
  en_title = "The Gordunni Scroll",
  en_obj = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.",
}
T[2979] = {
  title = "Cerimonia Oscura",
  desc = "Sembrano i piani di una specie di cerimonia oscura, $N. Da quel che riesco a capire, questo rituale lo celebrano i signori dei maghi Gordunni.$B$BTrova uno di questi signori dei maghi e prendigli un globo.$B$BIl globo di un mago racchiude un grande potere, e ci aiuterà a scoprire di più su questa cerimonia e sulla magia che usano i Gordunni.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu trovi un Gordunni Orb.",
  progress = "Dobbiamo scoprire di più sul perché i Gordunni sono qui, $N.",
  reward = "Questo globo ci darà altre informazioni sui Gordunni... che poi useremo per preparare la loro disfatta, $N.",
}
T[2980] = {
  title = "Gli Ogre di Feralas",
  desc = "Ora che hai dimostrato di essere $Gun vero combattente:una vera combattente;, confido che tu abbia il coraggio di continuare con il compito da svolgere.$B$BVa' nella High Wilderness, a sud-ovest di qui. Lì ci sono alcune strutture abbandonate e distrutte, su terre che un tempo appartenevano agli elfi della notte. Cerca queste rovine, e quando vedrai gli alberi avvizziti e il terreno profanato, troverai i Gordunni. Respingili.$B$BQuesti ogre sono molto più forti di quelli che hai affrontato prima, $N. Sta' $Gattento:attenta;.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Shaman, 10 Gordunni Warlock e 5 Gordunni Mauler.",
  progress = "Hai trovato le rovine, $N?",
  reward = "Hai dimostrato di essere $Gun alleato leale e affidabile:un'alleata leale e affidabile;, $N.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.",
}
T[2981] = {
  title = "Una Minaccia a Feralas",
  desc = "Feralas è il posto ideale perché $Gun:una; $C $Gesperto:esperta; dimostri di che pasta è $Gfatto:fatta;. Lì la forza militare dominante è una tribù di ogre, i Gordunni, e il loro numero è in crescita. Vanno fermati prima che minaccino la nostra presenza a Feralas.$B$BSo di una guerriera di nome Rok Orhan che sta a Camp Mojache, a Feralas; va' da lei. Quando arriverai ti dirà di più sulla situazione.",
  obj = "Belgrom Rockmaul vuole che tu parli con Rok Orhan a Camp Mojache.",
  reward = "E così ti ha mandato Belgrom. Arrivi giusto in tempo, $R.$B$BLascia che ti spieghi la situazione, poi deciderai se sei all'altezza della sfida... Ma se ti ha mandato Belgrom, sono certa che il tuo coraggio è fuori discussione.",
}
T[2982] = {
  title = "La High Wilderness",
  desc = "Anche se è pericoloso, io e Troyas stiamo esplorando le rovine che coprono le foreste di Feralas.$B$BUltimamente, però, Troyas va da solo nella High Wilderness, e sono davvero in pensiero per lui. Gli Ogre Gordunni hanno preso possesso di quella zona, e non vedono di buon occhio chiunque entri nel loro territorio.$B$BSperavo che fossi $Gdisposto:disposta; a raggiungere le rovine a sud-est e a eliminare un po' di ogre. Rendi quel posto un po' più sicuro per il mio Troyas, e te ne sarò estremamente grata.",
  obj = "Angelas Moonbreeze vuole che tu uccida 8 Gordunni Warlock, 8 Gordunni Shaman e 8 Gordunni Brute.",
  progress = "Fa' attenzione con i Gordunni, $N. La loro magia sembra devastare la terra stessa su cui si trovano.",
  reward = "Ti sono molto grata per aver fatto questo per me.$B$BOra, ti prego, non dire una parola a Troyas di tutto questo...",
  en_title = "The High Wilderness",
  en_obj = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.",
}
T[2983] = {
  title = "Il Richiamo del Fuoco",
  desc = "È passato un po' di tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora sei $Gstato:stata; paziente nei tuoi studi, ma è ora che tu conosca poteri più grandi... è ora che tu conosca il vero potere. L'elemento del fuoco è tuo, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi a quelle maledette terre degli elfi della notte, sei $Gandato:andata; fin troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Swart, vero?$B$BBe', di Swart ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2984] = {
  title = "Il Richiamo del Fuoco",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Narm, vero?$B$BBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2985] = {
  title = "Il Richiamo dell'Acqua",
  desc = "Mi sembri $Gpronto:pronta; per la tua prossima prova, $N. Sei $Gstato:stata; paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Fiume Southfury e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2986] = {
  title = "Il Richiamo dell'Acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Fiume Southfury e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2987] = {
  title = "Cobalto dei Gordunni",
  desc = "Sono appena arrivato qui in Feralas, e ho sentito che gli Ogre Gordunni che abitano queste terre selvagge hanno dei minerali interessanti. Chissà cosa combinano, ma di sicuro sono molto gelosi di quella roba! Non la lasciano in giro, no: la seppelliscono, per impedire a gente come me di metterci le mani sopra.$B$BSe ti va, ti darò la mia pala. Va' all'Avamposto dei Gordunni, a nord di qui, e dissotterrami un po' di cobalto dei Gordunni. Cerca il bagliore blu, poi comincia a scavare!",
  obj = "Orwin Gizzmick, a Camp Mojache, vuole 12 campioni di Gordunni Cobalt.",
  progress = "Vai lassù e comincia a scavare!$B$BHo mille cose da fare — il tempo è denaro!",
  reward = "Perfetto! Li porterò con me nei miei viaggi, $N. Sono sicuro di poter trovare qualcuno che pagherà fior di quattrini per questo cobalto.$B$BTieni, prendi questo per il disturbo.",
  en_title = "Gordunni Cobalt",
  en_obj = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.",
}
T[2988] = {
  title = "Le Gabbie dei Witherbark",
  desc = "Il figlio del nostro grifone più possente è sparito! L'erede di Swiftwing, Sharpbeak, si è perso qualche giorno fa mentre cacciava con i genitori, e crediamo che siano stati i troll a prenderlo.$B$BDevi aiutarci! Ispeziona le gabbie nei due villaggi dei troll Witherbark per vedere se Sharpbeak è lì.",
  obj = "Controlla le gabbie nei due villaggi Witherbark, poi torna da Gryphon Master Talonaxe.",
  progress = "Hai ispezionato le gabbie, $N? Dobbiamo trovare Sharpbeak!",
  reward = "Sharpbeak non era nei villaggi? Hm... brutte notizie. Quel grifone è destinato a guidare la prossima generazione di grifoni. Se lo perdiamo, la forza e lo spirito della nostra flotta ne soffriranno moltissimo.",
}
T[2989] = {
  title = "L'Altare di Zul",
  desc = "Sharpbeak non era con i troll Witherbark. Forse l'hanno preso i troll Vilebranch. Va' all'Altare di Zul, sul confine occidentale del territorio dei Vilebranch, e cerca il piccolo grifone.",
  obj = "Controlla la cima dell'Altare di Zul, poi torna da Gryphon Master Talonaxe.",
  progress = "Sbrigati, $N! Se Sharpbeak ce l'hanno i troll Vilebranch, chissà cosa gli stanno facendo!",
  reward = "Sharpbeak non c'era? È una brutta notizia, ma anche una buona notizia...$B$BÈ un bene che non fosse all'Altare di Zul, perché i troll Vilebranch sono noti per i loro sacrifici.$B$BTi ringrazio per tutto il tuo aiuto, ma temo di avere davanti un compito ancora più grande.",
}
T[2990] = {
  title = "Thadius Grimshade",
  desc = "Porta questa piuma a Thadius Grimshade, l'indovino. Anni fa ha lasciato Aerie Peak per inseguire conoscenze più oscure, ma nel suo cuore è ancora un Wildhammer!$B$BE forse le sue doti possono aiutarci a trovare Sharpbeak.$B$BQuesta piuma viene dal nido dove dorme il piccolo grifone. Se la dai a Thadius, con un po' di fortuna potrà usare le sue magie divinatorie per trovare Sharpbeak.$B$BBuona fortuna, $N. Troverai Thadius nelle Blasted Lands, nella torre dei maghi di Nethergarde Keep.",
  obj = "Porta Sharpbeak's Feather a Thadius Grimshade nelle Blasted Lands.",
  progress = "$N, vieni a portarmi un dono?",
  reward = "Ah, sì. Questa piuma appartiene a un grifone splendido. Uno destinato a grandi cose... se riuscirà a diventare adulto senza un graffio.$B$BVuoi trovarlo? Allora ascolta bene, prode $C...",
}
T[2991] = {
  title = "Il Medaglione di Nekrum",
  desc = "Scoprirò dov'è il tuo grifone, ma prima devi fare qualcosa per me. A Zul'Farrak c'è un troll, Nekrum Gutchewer, che possiede un medaglione che vorrei tanto studiare. Portami quel Medaglione e userò i miei poteri per trovare Sharpbeak.$B$BZul'Farrak è oltre l'oceano, a ovest, nel deserto di Tanaris.",
  obj = "Porta Nekrum's Medallion a Thadius Grimshade, nelle Blasted Lands.",
  progress = "Hai il Medaglione di Nekrum, $N? Dentro ci sono poteri nascosti che sono ansioso di scoprire.",
  reward = "Ah, il medaglione di Nekrum. Si dice che abbia dato al troll una vita innaturalmente lunga, ma a caro prezzo. Spero di scoprire un modo per sfruttare il potere del medaglione evitando i suoi... sgradevoli effetti collaterali.$B$BMi hai reso un servizio, $N. Ora manterrò la mia parte del patto.",
  en_title = "Nekrum's Medallion",
  en_obj = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.",
}
T[2992] = {
  title = "La Divinazione",
  desc = "Fammi spazio mentre eseguo un rituale di divinazione. Troverò il legame fra la piuma che mi hai portato e il suo proprietario, e seguirò quel legame fino a Sharpbeak in persona.$B$BCioè... lo farò se tutto va secondo i piani. Se no, allora... faresti meglio a chiudere gli occhi.",
  obj = "Aspetta che Grimshade esegua il rituale di divinazione.",
  reward = "Il rituale è riuscito. Ho visto Sharpbeak e posso dirti come trovarlo.",
}
T[2993] = {
  title = "Ritorno negli Hinterlands",
  desc = "Sharpbeak è rinchiuso in una gabbia, in alto su una rupe in cima a Jintha'Alor, negli Hinterlands. La chiave di quella gabbia ce l'ha la somma sacerdotessa dei troll Vilebranch, la Sacerdotessa Infame Hexx.$B$BEcco. Io ho fatto la mia parte. Ti auguro fortuna nella tua impresa, $N.",
  obj = "Parla con Gryphon Master Talonaxe.",
  reward = "Hai parlato con Grimshade? Cosa ti ha detto?$B$B...Cosa? Sharpbeak ce l'hanno i troll Vilebranch? È intollerabile! Dobbiamo radunare delle forze per riprendercelo!",
}
T[2994] = {
  title = "Salvare Sharpbeak",
  desc = "Dobbiamo salvare Sharpbeak!$B$BFatti strada fino alla cima di Jintha'Alor, nel cuore del territorio dei Vilebranch, strappa la chiave della gabbia di Sharpbeak alla vile Sacerdotessa Hexx, e poi trova e salva Sharpbeak!",
  obj = "Fatti strada fino alla cima di Jintha'Alor, uccidi Vile Priestess Hexx per avere la chiave di Sharpbeak's Cage e salva Sharpbeak.",
  progress = "Salva Sharpbeak!",
  reward = "Swiftwind e Keenclaw sono tornati poco fa con il loro piccolo, e gli fanno mille premure come due genitori alle prime armi. Vederli di nuovo insieme basta a far venire gli occhi lucidi perfino a questo vecchio nano...$B$BNon potremo mai ripagarti abbastanza per quello che hai fatto, $N. I grifoni di Aerie Peak, e i loro cavalieri, canteranno il tuo nome per molto, molto tempo.",
}
T[2995] = {
  title = "Linee di Comunicazione",
  desc = "Il Padiglione Quel'Danil è un centro di comunicazione per gli alti elfi delle Hinterlands. I loro ambasciatori stanno lavorando per stabilire rapporti con altre razze, con cui condividono ciò che sanno dei troll Witherbark che abitano la zona meridionale delle Hinterlands. Tutti i documenti che riguardano queste comunicazioni sono conservati al padiglione.$B$BNon ci serve che gli Highvale stringano alleanze con altri, $N.$B$BDistruggi i documenti degli Highvale. Dobbiamo bruciare le loro linee di comunicazione... letteralmente.",
  obj = "Oran Snakewrithe, a Undercity, vuole che tu vada nelle Hinterlands e bruci gli Highvale Records, l'Highvale Report e le Highvale Notes.",
  progress = "Tenere isolati gli elfi Highvale è la chiave. Hai trovato il padiglione?",
  reward = "Perfetto, $N. Mentre gli Highvale si danno da fare per recuperare le informazioni perdute, noi potremo chiudere ancora di più quelle linee...",
}
T[2996] = {
  title = "In Cerca di Strahad",
  desc = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole. È potente, anche se può sembrare piccolo. Può insegnarti evocazioni più potenti — credo che tu sia $Gpronto:pronta;. Va' da lui ora. Si trova a Ratchet... sopra la città portuale, vicino alla sua torre.",
  obj = "Parla con Strahad Farsan, a Ratchet.",
  reward = "Una giornata movimentata a Ratchet, vero? Quanto mi piace osservare il duro lavoro di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.$B$BÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a frutto.",
  en_title = "Seeking Strahad",
  en_obj = "Speak to Strahad Farsan in Ratchet.",
}
T[2997] = {
  title = "Tomo della Divinità",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire fino a Ironforge per parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.$B$BLa trovi al piano di sopra, nella Sala dei Misteri. Se non ci sei mai $Gstato:stata;, è nel Quartiere Mystic. Buona fortuna, $N.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[2998] = {
  title = "Tomo della Divinità",
  desc = "Salve, $Gfratello:sorella;. Duthorian Rall, uno dei nostri paladini più influenti, ha parlato di te di recente. L'ho sentito dire che era ora di metterti un po' alla prova... insieme a parecchi complimenti su quanto bene te la sei cavata finora.$B$BSe fossi in te, andrei a Stormwind a parlargli quando hai tempo. Di sicuro è nella Cattedrale della Luce — è lì che passa la maggior parte del tempo.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "È bello qui a Stormwind, non trovi?$B$BNon potevi capitare in un momento migliore, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[2999] = {
  title = "Tomo della Divinità",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire al piano di sopra e parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.",
  obj = "Parla con Tiza Battleforge, a Ironforge",
  reward = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge",
}
T[3000] = {
  title = "Tomo della Divinità",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Azeroth, ma quando hai tempo dovresti tornare a Ironforge e parlare con una paladina tra le più rispettate della tua terra: Tiza Battleforge. È da lei che vanno i giovani paladini nani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da tutti noi.$B$BLa trovi al piano di sopra, nella Sala dei Misteri, che si trova nel Quartiere Mystic.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Ti saluto, e ti do il benvenuto, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[3001] = {
  title = "In Cerca di Strahad",
  desc = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole, né che sia tuo nemico... almeno per ora. È potente e va rispettato. Può insegnarti evocazioni superiori, evocazioni per cui credo tu sia $Gpronto:pronta;. Va' da lui ora.$B$BLo trovi a Ratchet... sopra la città portuale, vicino alla torre.",
  obj = "Trova Strahad Farsan, a Ratchet.",
  reward = "Una giornata movimentata a Ratchet, vero? Quanto mi piace osservare il duro lavoro di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.$B$BÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a frutto.",
  en_title = "Seeking Strahad",
  en_obj = "Find Strahad Farsan in Ratchet.",
}
T[3002] = {
  title = "Il Globo Gordunni",
  desc = "Anche se conosco bene il mio nemico, sono una guerriera, $N. Non saprei nemmeno da dove cominciare per dirti di cosa è capace questo globo.$B$BConosco un mago a Orgrimmar che saprà dirci di più sul globo. Portaglielo.",
  obj = "Porta il Gordunni Orb a Uthel'nay, nella Darkbriar Lodge di Orgrimmar.",
  progress = "Cosa mi hai portato, $R?",
  reward = "Affascinante, $N...$B$BQuesto globo è molto potente, ma anche molto pericoloso.",
}
T[3022] = {
  title = "Maneggiare con Cura",
  desc = "$N, si vede che muori dalla voglia di dedicarti alla mia meritevole causa. Sì, certo che puoi fare qualcosa per me!$B$BPorta questa cassa di uova a Erelas Ambersky. È un druido che si prende cura di queste uova, le aiuta a schiudersi e poi addestra i giovani ippogrifi. Lo troverai a Teldrassil, in un piccolo villaggio a sud che si chiama Rut'theran.",
  obj = "Porta la Carefully-packed Crate a Erelas Ambersky a Rut'theran Village.",
  progress = "Un'altra spedizione da parte di Curgle, immagino?",
  reward = "Grazie dell'aiuto, $N. Se non fosse per noi, la popolazione degli ippogrifi non potrebbe proprio prosperare. Ah, ma sono certo che tu lo capisca fin troppo bene, visto che sei $Gstato:stata; a Feralas di persona e hai visto la devastazione portata lì dai Gordunni.$B$BBene, come vedi qui ho molto da fare, perciò è meglio che tu vada.$B$BGrazie ancora, $N.",
}
T[3042] = {
  title = "Sudore di Troll",
  desc = "I troll Sandfury di Zul'Farrak ricavano un agente di tempra dalle arenarie, e io posso usarlo per temprare le cose che fabbrico, eccome se posso! È molto apprezzato dagli intenditori, quindi se mi porti una buona scorta di tempra, ti ricompenserò bene.$B$BZul'Farrak è a nord-ovest di Gadgetzan. Buona fortuna.",
  obj = "Porta 20 Troll Temper a Trenton Lighthammer, a Gadgetzan.",
  progress = "Mi hai portato la tempra, $N?",
  reward = "Ah, questa sì che è un'ottima tempra! E quanta! Ci lavorerò per giorni prima di finirla tutta!$B$BGrazie, $N. Ti prego, prendi questo come pagamento.",
  en_title = "Troll Temper",
  en_obj = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.",
}
T[3062] = {
  title = "Cuore Oscuro",
  desc = "Edana Hatetalon è la regina delle arpie Northspring che vivono nelle rovine a ovest. È la malvagità fatta persona; ho sentito dire che ha un cuore di cristallo. È priva di qualsiasi emozione, a parte l'odio che prova per tutti gli altri. Devi affrontare Edana e riportarmi il suo cuore oscuro.$B$BHo sentito parlare di un corno che le arpie portano con sé — se lo suoni accanto alle pietre Hatetalon, nella parte settentrionale delle rovine, evocherai la regina.$B$BImmagina la sua sorpresa quando a chiamarla non sarà la sua gente, ma la sua morte.",
  obj = "Talo Thornhoof, a Camp Mojache, vuole Edana's Dark Heart.",
  progress = "L'odio che Edana diffonde su queste terre va fermato.",
  reward = "Ora so che Edana è davvero morta. Questo cuore; lo terrò in ricordo di quello che hai fatto qui per me, $N. Grazie.",
}
T[3063] = {
  title = "Vendetta Contro le Northspring",
  desc = "Ai miei tempi ero un cacciatore esperto. Non c'era creatura, da queste parti, che temessi. Finché...$B$BEro nella foresta ad affilare la lama dopo una dura battaglia, quando mi tesero un agguato. Delle arpie mi circondarono e riuscii a malapena a trascinarmi in salvo.$B$BAncora oggi sento l'eco delle loro grida...$B$BDa allora non sono più stato lo stesso. Ma l'odio mi ribolle dentro — devo pareggiare i conti, dopo tutti questi anni.$B$BLe arpie Northspring si trovano a ovest di qui. $N, vendicami.",
  obj = "Talo Thornhoof vuole che tu uccida 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers e 4 Northspring Slayers.",
  progress = "Le ali delle arpie Northspring sono nere come la notte; non toglier loro gli occhi di dosso, o svaniranno nell'oscurità.",
  reward = "Grazie, $N. Hai dato pace all'animo di un vecchio tauren.",
}
T[3065] = {
  title = "Tavoletta Semplice",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, al riparo all'ombra.",
  obj = "Leggi la Simple Tablet e parla con Frang, nella Valley of Trials.",
  progress = "$GUn altro:Un'altra; $R a rinforzare le file. Per me va bene.$B$BProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualsiasi altra cosa.$B$B$GBenvenuto:Benvenuta; nella Valle delle Sfide.",
  reward = "Vedrai che questo posto è adatto a te, mentre continui ad addestrarti nelle vie $Gdel:della; $C. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti $Gpronto:pronta;, torna da me per l'addestramento. Ne so quanto qualsiasi $C qui nella Valle e posso trasmetterti quello che so... per un compenso.",
  en_title = "Simple Tablet",
  en_obj = "Read the Simple Tablet and speak to Frang in the Valley of Trials.",
}
T[3082] = {
  title = "Tavoletta Intagliata",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Parla con Jen'shan, nella Valley of Trials.",
  progress = "Jen'shan vede davanti a lei $Gun potente cacciatore:una potente cacciatrice;, e gli spiriti approvano.$B$BLa via del cacciatore è uno dei modi di vivere più vecchi che c'abbiamo. Quelli dell'Orda son venuti da noi quando faticavano solo a sopravvivere su Azeroth, e ci chiedono di insegnargli, di fargli vedere i segreti di tante cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non è la loro via... a quel tempo.",
  reward = "Adesso noi gli insegniamo quelle cose, e loro ce ne insegnano altre. Diventiamo una razza sola... quasi. Noi alleati da tanto tempo, ormai. Allora tu ricordati di aiutarli. E Jen'shan si ricorda di aiutare te.$B$BJen'shan t'insegna le vie del cacciatore — te le insegna bene. Non te lo scordare mai, i cacciatori son rispettati tanto dalla tribù. Tu c'hai una gran parte nel futuro... non te lo scordare mai.$B$BQuando senti il bisogno, vieni da Jen'shan. Lei t'insegna tutto quello che può, quando sente che sei $Gpronto:pronta;.",
  en_title = "Etched Tablet",
  en_obj = "Speak to Jen'shan in the Valley of Trials.",
}
T[3083] = {
  title = "Tavoletta Codificata",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Tablet e parla con Rwag, nella Valley of Trials.",
  progress = "$GBenvenuto:Benvenuta; nella Valle delle Sfide, $N. Non saresti qui se non avessi ricevuto la mia tavoletta, quindi vengo al punto.$B$BSono Rwag, e mi occupo di addestrare i ladri, i furfanti e i tagliaborse qui nella Valle. Sono io quello a cui si rivolgerà la Hand se non sarai $Gpronto:pronta; per ciò che ti aspetta. Ma non preoccuparti: la Hand non controllerà tutto quello che fai, anche se, qualora avessero bisogno dei tuoi talenti, sarebbe saggio collaborare con loro.",
  reward = "Fino ad allora, sarai sotto la mia tutela. Ti insegnerò i trucchi del mestiere, come si suol dire. Quando ti senti $Gpronto:pronta;, vieni da me e vedrò di addestrarti ancora. Nel frattempo, esercita le tue abilità e tienile affilate come un rasoio. Non si sa mai quando potrà servirti anche l'abilità più insignificante.",
  en_title = "Encrypted Tablet",
  en_obj = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.",
}
T[3084] = {
  title = "Tavoletta con Rune",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Parla con Shikrik, a Valley of Trials.",
  progress = "Ah, $Gbenvenuto:benvenuta;, $N. Sono lieta che tu sia $Garrivato:arrivata;. Con tutti questi allievi da istruire le mie giornate sono diventate lunghe e anche molto impegnate, ma l'arrivo di qualcuno come te mi dà un grande senso di soddisfazione — ricordo i giorni in cui ero io l'allieva di uno sciamano del tuo popolo.",
  reward = "Come probabilmente sai, gli elementi ci danno il nostro potere. Fuoco, terra, acqua e aria — sono i nostri strumenti.$B$BLa nostra forza viene dagli spiriti dei nostri antenati. Siamo le guide del nostro popolo. Come Thrall lo è per l'Orda, così saremo noi per i villaggi e le cittadine che visitiamo. Si rivolgeranno a noi per avere saggezza e protezione. Per essere più $Gpreparato:preparata;, devi allenarti spesso. Quando senti di aver acquisito più potere, vieni da me e ti insegnerò quello che posso.",
  en_title = "Rune-Inscribed Tablet",
  en_obj = "Speak to Shikrik in the Valley of Trials.",
}
T[3085] = {
  title = "Tavoletta Benedetta",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Ken'jai, l'istruttore di sacerdoti. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Hallowed Tablet e parla con Ken'jai, fuori dal Den, nella Valley of Trials.",
  progress = "Allora ce l'hai fatta... bene bene! Gli spiriti m'hanno detto che venivi presto da Ken'jai. Lascia che sia io uno dei primi a darti il benvenuto nella Valle delle Sfide. 'Sto posto non esser casa tua per tanto, ma finché lo è, perché non ne tiri fuori il meglio.",
  reward = "Mentre ti metti alla prova, vedrai che comandi gli spiriti sempre meglio — li chiamerai per cose sempre più grosse... ed è lì che entra in gioco il vecchio Ken'jai. Tu vieni a parlare col vecchio Ken'jai quando ti senti $Gpronto:pronta;. Se gli spiriti sono d'accordo, allora vediamo di insegnarti abilità più potenti... ma solo se gli spiriti sono d'accordo.$B$BOra va', parla col resto della gente della Valle. Torna a parlarmi più tardi.",
  en_title = "Hallowed Tablet",
  en_obj = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.",
}
T[3086] = {
  title = "Tavoletta con Glifi",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Mai'ah, l'istruttrice di maghi. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi la Glyphic Tablet e parla con Mai'ah, vicino all'ingresso del Den, a Valley of Trials.",
  progress = "Già cerchi di fare contenta Mai'ah, $N. Questo va bene. Tu dai rispetto a Mai'ah, e magari Mai'ah ti ridà rispetto. Ma basta con 'ste cose: tu sei qui per imparare la magia, mica per sentire Mai'ah che chiacchiera.$B$BC'è solo una cosa della magia che Mai'ah non ti può insegnare, $N, ed è come si ferma la corruzione.",
  reward = "Tu sei tra gli esseri più potenti del pianeta, $N... su questo niente da dire. E lo sanno tutti... e lo sanno pure bene!$B$BMa devi stare in guardia! Perché non è l'orco, o l'elfo, o il nano che ti deve fare paura... sono le cose che non puoi vedere. La magia è potente. Ti fa fare cose che magari non vuoi fare. Ti fa credere che sei più potente di quello che sei davvero. Sii paziente. Usa la testa.$B$BQuando pensi che sei $Gpronto:pronta; per l'addestramento, torna da Mai'ah. Lei ti insegna quello che sei $Gpronto:pronta; a imparare, nessun problema.",
  en_title = "Glyphic Tablet",
  en_obj = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.",
}
T[3087] = {
  title = "Cartapecora Intagliata",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Etched Parchment e parla con Jen'shan, nella Valley of Trials.",
  progress = "Ah, allora sei $Garrivato:arrivata;, finalmente. Bene. Jen'shan ti aspettava.$B$BTanti pensano che è una via facile, ma Jen'shan ti dice che non è vero. Per diventare maestri con le bestie di Durotar e più in là ci vuole la stessa abilità che per le arti arcane o per parlare coi nostri antenati.$B$BTirare con l'arco o col fucile forse per te non è pericoloso come lanciare un incantesimo, ma per il tuo nemico è pericoloso uguale, sicuro.",
  reward = "Quando finiamo di parlare, tu dovresti andare dal resto della gente della Valle. Loro ti chiedono di fare cose per loro... cose che mettono alla prova la tua abilità e t'insegnano un po' dei pericoli di questa terra.$B$BPiù cresci in esperienza e saggezza, più ti serve che Jen'shan ti fa vedere tecniche e abilità migliori. Torna spesso da Jen'shan. Io ti faccio sapere cosa posso insegnarti.",
  en_title = "Etched Parchment",
  en_obj = "Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.",
}
T[3088] = {
  title = "Cartapecora Codificata",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Parchment e parla con Rwag, nella Valley of Trials.",
  progress = "Shhh, non così forte. Di Nartok, laggiù, non mi fido. Chi deve nascondersi in una caverna più in fondo di me non è uno con cui scherzare.$B$BImmagino che tu non abbia avuto problemi a trovare la strada?",
  reward = "Ora che sai dove mi sono rintanato, devo dirti una cosa: la Shattered Hand mi ha chiesto di tenerti d'occhio. Vogliono che sia io ad addestrarti e a tenerti al corrente di tutto ciò di cui potrebbero aver bisogno. Anche se per ora non ti interessa aiutarli — e saresti $Gpazzo:pazza; a non volerlo — farò quello che posso per addestrarti... in cambio di un piccolo compenso. Torna da me ogni volta che pensi di essere $Gpronto:pronta;, e vedremo cosa sei $Gpronto:pronta; a imparare.",
  en_title = "Encrypted Parchment",
  en_obj = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.",
}
T[3089] = {
  title = "Cartapecora con Rune",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi la Rune-Inscribed Parchment e parla con Shikrik, a Valley of Trials.",
  progress = "Allora sei $Garrivato:arrivata;. Cominciavo a chiedermi quando ti saresti $Gfatto vivo:fatta viva;. Ho mandato la pergamena un po' di tempo fa — non ero sicura che fosse arrivata.$B$BMa basta chiacchiere... sei qui perché sei $Gstato scelto:stata scelta;, $Gscelto:scelta; per guidare la vita spirituale del nostro popolo.",
  reward = "Sarai il tramite attraverso cui parlano i nostri antenati. Avrai il potere degli elementi ai tuoi ordini. Fare a pezzi i tuoi nemici sarà un gioco da ragazzi; curare i tuoi alleati sarà facile come respirare. Tieni a mente queste cose quando affronterai nuove sfide, e torna da me tutte le volte che vuoi. Resterò qui per insegnarti nuovi incantesimi e per metterti sulla strada giusta, quando sarai $Gpronto:pronta;.",
  en_title = "Rune-Inscribed Parchment",
  en_obj = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.",
}
T[3090] = {
  title = "La Cartapecora Corrotta",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BDi solito, se posso, evito di avere a che fare con gli stregoni, ma credo che dovresti leggerla quando hai tempo. Se non sbaglio, viene da Nartok, il tuo nuovo istruttore. Vuole parlarti quando sarai $Gpronto:pronta;.",
  obj = "Leggi la Tainted Parchment e parla con Nartok, dentro il Den, a Valley of Trials.",
  progress = "Finalmente sei $Garrivato:arrivata;... e con discrezione, per giunta. Bene.$B$BIl nostro mondo è pieno di sciocchi, $N. Perfino il potente Thrall ha difetti più grandi di quanto molti riescano a vedere. Volta le spalle al potere che servirebbe per rendere questa terra completamente nostra! Non siamo più lo stesso popolo che fu manipolato e usato dalle creature del Nether. Siamo padroni di noi stessi. Siamo fieri... e siamo forti.",
  reward = "E ora anche tu sei $Gentrato:entrata; nelle nostre file. Non fraintendermi, $N. Avere accesso a un potere che molti ti invidieranno non significa che sarai $Gaccettato:accettata; facilmente. Thrall permette alla nostra gente di stare a Orgrimmar perché siamo pur sempre della sua stessa stirpe — non può voltarci le spalle, altrimenti diventeremmo patetici come gli umani che lo resero schiavo. Quello che voglio dire è: sta' $Gattento:attenta;. Puoi essere potente, ma se sei $Gsciocco:sciocca;, sei già $Gmorto:morta;.$B$BSe hai bisogno di imparare nuovi incantesimi, torna da me.",
  en_title = "Tainted Parchment",
  en_obj = "Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.",
}
T[3091] = {
  title = "Nota Semplice",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Harutt, l'istruttore di guerrieri. Se il biglietto è di Harutt, al posto tuo non aspetterei a leggerlo.",
  obj = "Leggi la Simple Note e parla con Harutt Thunderhorn, a Camp Narache.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;, $C. Nel mio biglietto non ho mentito, $N. Anche noi siamo una stirpe speciale, come i druidi o gli sciamani della nostra tribù. Tu sei altrettanto importante. Siamo noi quelli chiamati a difendere i nostri confini, a cacciare i centauri e ad andare in guerra.",
  reward = "Ognuno di noi ha un ruolo nella nostra tribù. E ognuno di noi deve anche passare per gli stessi riti. Non lasciare mai che il tuo orgoglio ti dica il contrario.$B$BIo resto qui per addestrare i nuovi guerrieri che cercano la gloria della battaglia e seguono le vie dei nostri antenati più lontani. Quando ti senti $Gpronto:pronta;, torna da me e farò il possibile per addestrarti ancora. Va' con la benedizione della tribù, $N.",
  en_title = "Simple Note",
  en_obj = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.",
}
T[3092] = {
  title = "Nota Intagliata",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Lanka, l'istruttore di cacciatori. Se questo biglietto viene da Lanka, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi l'Etched Note e parla con Lanka Farshot, a Red Cloud Mesa.",
  progress = "$GBenvenuto:Benvenuta; a Camp Narache, $N. Sento parlare bene di te. La tua stirpe è forte, e molti degli anziani ti ritengono già abile. Ma questo lo metteremo alla prova.$B$BLe pianure di Mulgore saranno la tua casa per un po' di tempo — dovresti fare del tuo meglio per conoscerle molto bene. Un giorno viaggerai verso terre sconosciute per padroneggiare abilità superiori. Devi essere $Gpronto:pronta;.",
  reward = "Ed è mio compito assicurarmi che tu sia $Gpreparato:preparata;, insegnandoti le basi della nostra professione — come addomesticare il tuo animale, come sparare con il fucile, e molte altre abilità che ti serviranno.$B$BI cacciatori sono una parte importante della nostra tradizione e della nostra storia, $N. Faresti bene a ricordare quanto sei importante per la tribù. Sarai $Grispettato:rispettata; e $Gvenerato:venerata; se servirai bene il nostro popolo.",
  en_title = "Etched Note",
  en_obj = "Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa.",
}
T[3093] = {
  title = "Nota con Rune",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Meela, l'istruttrice di sciamani. Se questo biglietto viene da Meela, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi la Rune-Inscribed Note e parla con Meela Dawnstrider, a Camp Narache.",
  progress = "Veloce come l'acqua che cade dal cielo, eccoti davanti a me. La tua rapidità mi fa piacere. Vuol dire che hai capito quanto sono importanti sia il nostro incontro sia il fatto che tu sia qui. Non sono una guida, ma comprendo gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.",
  reward = "Ci incontreremo molte volte nei giorni a venire. Ogni volta, spero, te ne andrai da me un po' più potente... un po' più $Gpreparato:preparata;. Come la Fiamma Eterna, il tuo spirito arderà intenso e luminoso.$B$BOra va', $N. Va' e mettiti alla prova. Sarò qui per te quando ne avrai bisogno.",
  en_title = "Rune-Inscribed Note",
  en_obj = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.",
}
T[3094] = {
  title = "Nota Verdastra",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Gart, l'istruttore di druidi. Se questa nota viene da Gart, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi la Verdant Note e parla con Gart Mistrunner, a Camp Narache.",
  progress = "Sei $Garrivato:arrivata;. Bene. Gli spiriti dei nostri antenati sono diventati inquieti in tutta Mulgore e oltre, ma non riesco a capire perché. Sarà per sempre tuo dovere imparare ad ascoltare gli spiriti della natura, e a essere la loro incarnazione. Tienilo a mente.",
  reward = "Anche se ci unisce un legame comune, non aspettarti una grande accoglienza dagli elfi della notte. Il loro orgoglio offusca ancora il loro sguardo, ma non è affar nostro. Gli insegnamenti della Madre Terra sono tutto ciò di cui devi preoccuparti, e ti insegnerò quello che so man mano che crescerai in saggezza.$B$BTorna spesso da me, $N. Scoprirai che la Madre Terra concede abilità incredibili a chi le è più devoto.",
  en_title = "Verdant Note",
  en_obj = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.",
}
T[3095] = {
  title = "Pergamena Semplice",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Dannal, l'istruttore di guerrieri. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi il Simple Scroll e parla con Dannal Stern, a Deathknell.",
  progress = "Ah, dunque sei $Garrivato:arrivata;. Bene. Ho sentito dire che alcuni altri sono riusciti a sfuggire alla \"morte\" e stavano venendo in città. Forse questa tenacia ripagherà anche in futuro.$B$BPuoi ringraziare Sylvanas per la tua libertà... libertà della mente e del corpo. Anche se sei ancora $Gtormentato:tormentata; dalla piaga e dai suoi effetti, ora sei $Glibero:libera; di andare e venire come meglio credi.",
  reward = "Sarò qui ad addestrarti man mano che acquisti esperienza... vieni da me tutte le volte che vuoi. Chiedo un compenso minimo, ma vedrai che tutto quello che posso insegnarti ne vale la pena.$B$BOra va' e metti alla prova la tua abilità. Molte altre cose ti saranno rivelate man mano che acquisti esperienza, e di alcune non posso parlarti qui. Sappi solo che in futuro Sylvanas avrà bisogno di guerrieri della tua tempra. Sarai la spina dorsale della nostra salvezza. Non dimenticarlo.",
  en_title = "Simple Scroll",
  en_obj = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.",
}
T[3096] = {
  title = "Pergamena Codificata",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di David Trias, l'istruttore di ladri. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi l'Encrypted Scroll e parla con David Trias, a Deathknell.",
  progress = "Quindi ce l'hai fatta? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalker finiranno per trovarti quando riterranno che sia il momento giusto, perciò non commettere passi falsi e non fare niente di cui potresti pentirti. Hanno bisogno di agenti di talento... non di borseggiatori e di sciocchi.",
  reward = "Passo la maggior parte del tempo qui alla locanda, a tenere d'occhio le facce nuove e a seguire da vicino le giovani promesse. Fila dritto e farò quello che posso per insegnarti un paio di cose. Torna da me quando vuoi, e vedremo se sei $Gpronto:pronta; per un'abilità nuova o due.",
  en_title = "Encrypted Scroll",
  en_obj = "Read the Encrypted Scroll and speak to David Trias in Deathknell.",
}
T[3097] = {
  title = "Pergamena Benedetta",
  desc = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Duesten, l'istruttore di sacerdoti. Io mi prenderei il tempo di leggerla prima di ripartire.",
  obj = "Leggi l'Hallowed Scroll e parla con Dark Cleric Duesten nella chiesa di Deathknell.",
  progress = "Ah, dunque tra incendi, peste, rivolte e cose ben peggiori, un altro dei \"fedeli\" bussa alla mia porta. Be', lascia che ti dia il benvenuto, $C. E concedimi un momento per spiegarti un paio di cose prima che tu decida che è ora di cercare ciò che ti spinge avanti: la Luce Sacra non ti riguarda più, gli spiriti dei tuoi antenati sono favole e le creature del Nether non ti vogliono.$B$BFin qui mi segui?",
  reward = "C'è una sola cosa che devi sapere: siamo sopravvissuti solo grazie alla volontà. È la fede in noi stessi che ci separa dagli altri, e con i nostri poteri porteremo un grande cambiamento in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno $GSignore:Signora;. E gli ignoranti si rivolgeranno a te per avere una guida. È mio dovere assicurarmi che tu abbia gli strumenti necessari, così che quando verrà il momento sarai $Gpronto:pronta;. Man mano che acquisti esperienza, vieni a cercarmi. Ti insegnerò poteri più grandi, se sarai $Gpronto:pronta;.",
  en_title = "Hallowed Scroll",
  en_obj = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.",
}
T[3098] = {
  title = "Pergamena con Glifi",
  desc = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Isabella, che addestra ogni $C come te. Al posto tuo la leggerei prima di ripartire.",
  obj = "Leggi la Glyphic Scroll e parla con Isabella nella chiesa di Deathknell.",
  progress = "Sapevo che saresti $Gvenuto:venuta; da me, $N. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo anime affini. $GEntrambi:Entrambe; abbiamo provato il dolore. $GEntrambi:Entrambe; abbiamo sofferto. E ora vogliamo il potere di riprenderci ciò che sappiamo essere nostro: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.",
  reward = "Dovrai tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi ci si oppone. Le regole della magia valgono ancora per te, $N. Scoprirai che la corruzione ti segue come un branco di lupi affamati nella notte. Scoprirai che la sua carezza somiglia a una dipendenza, a un vecchio amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti controlleranno solo se glielo permetterai.$B$BOra va', e torna da me quando sarai $Gdiventato:diventata; più potente.",
  en_title = "Glyphic Scroll",
  en_obj = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.",
}
T[3099] = {
  title = "La Pergamena Corrotta",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Maximillion, l'istruttore di stregoni. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi il Tainted Scroll e parla con Maximillion, a Deathknell.",
  progress = "$GBenvenuto:Benvenuta;, $Gfratello:sorella;. Sapevo che saresti $Gvenuto:venuta;. Era solo questione di tempo.$B$BQuello che ho detto ti ha interessato, vero? Ho toccato la corda giusta... qualcosa dentro di te sapeva che quello che affermavo era la verità. Bene.$B$BMa sappi questo: non sono un traditore di Sylvanas. Semmai, lei apprezzerebbe le mie parole, visto che sono state proprio le sue convinzioni a mettere i Reietti nella posizione in cui si trovano ora.",
  reward = "Ho detto che uno schiavo resta uno schiavo, qualunque sia il padrone. Ricordi? Sappiamo entrambi che è quel tipo di controllo — quel tipo di potere — a guidarci ora. Vogliamo creature che ci servano. Sappiamo di essere più potenti e di meritare più rispetto di quanto ci concedano gli altri... e così ora cerchiamo di prendercelo.$B$BSarò tuo alleato in questa lotta — la lotta per la nostra libertà. La libertà di scegliere da noi le nostre alleanze. Quando ti sentirai $Gpronto:pronta;, torna da me e ti insegnerò tutto quello che so.",
  en_title = "Tainted Scroll",
  en_obj = "Read the Tainted Scroll and speak to Maximillion in Deathknell.",
}
T[3100] = {
  title = "Lettera Semplice",
  desc = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Llane, il nostro istruttore di guerrieri. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi la Simple Letter e parla con Llane Beshere, alla Northshire Abbey.",
  progress = "Ah, hai ricevuto la mia lettera, $N... bene.$B$BUltimamente a Elwynn sono arrivati molti guerrieri — un bene per Stormwind, ma un male per i coboldi e i Defias della zona.",
  reward = "Sistemati per bene, impara com'è fatta la zona e torna da me ogni volta che hai bisogno di addestramento. Sarò qui giorno e notte.$B$BI Cavalieri della Mano d'Argento hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno dei problemi per cui farebbe loro comodo un aiuto — un aiuto che $Gun:una; $C può dare. Buona fortuna.",
  en_title = "Simple Letter",
  en_obj = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.",
}
T[3101] = {
  title = "Lettera Consacrata",
  desc = "Mi hanno chiesto di fartela avere non appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con l'insegna di Fratello Sammuel, il nostro istruttore di paladini. Al posto tuo la leggerei senza esitare, prima di dedicarmi a qualsiasi altra faccenda qui nell'Abbazia.",
  obj = "Leggi la Consecrated Letter e parla con Brother Sammuel, nell'Abbazia di Northshire.",
  progress = "Finalmente! Ci incontriamo faccia a faccia, da fratello a $Gfratello:sorella;. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un breve periodo, mentre impari come funzionano le cose, ma sappi che Stormwind non è lontana, e prima o poi il tuo cammino ti porterà là. Ma fino ad allora, abbi pazienza... $GCavaliere:Cavaliera; della Mano d'Argento.",
  reward = "Nel frattempo, dovresti sapere un paio di altre cose. Sei un simbolo per molti, qui in questa terra — comportati di conseguenza. La Luce Sacra risplende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.$B$BInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando senti di aver fatto un po' di esperienza qui a Northshire, torna da me e ti insegnerò quello che ritengo tu sia $Gpronto:pronta; a imparare. Buona fortuna... $C!",
  en_title = "Consecrated Letter",
  en_obj = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.",
}
T[3102] = {
  title = "Lettera Codificata",
  desc = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Jorik, uno dei nostri istruttori. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi l'Encrypted Letter e parla con Jorik Kerridan, nella stalla dietro l'Abbazia di Northshire.",
  progress = "Sei $Garrivato:arrivata; fin qui senza un graffio, e non sembra che ti abbiano visto in molti. Tanto mi basta. Qui dietro non mi piace attirare troppo l'attenzione... tutto bello tranquillo. Sono sicuro che capisci.$B$BHai già avuto qualche guaio? Mi fa piacere sentire di no. Le cose cambieranno presto.",
  reward = "Troverai parecchi gruppi che farebbero di tutto per avere le nostre abilità, $N. Gli avventurieri, lo SI:7... accidenti, perfino la Defias Brotherhood non disdegnerebbe una spia o due dentro Stormwind. Ma ricordati questo: rispondi solo a te $Gstesso:stessa;. Non lasciare che nessuno ti costringa a fare qualcosa che non vuoi fare! E poi, le carte in mano le abbiamo tutte noi... almeno finché la partita non è finita. Capisci cosa intendo?$B$BComunque, volevo solo presentarmi e farti sapere che sono qui se hai bisogno di addestramento. Passa quando vuoi.",
  en_title = "Encrypted Letter",
  en_obj = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.",
}
T[3103] = {
  title = "Lettera Benedetta",
  desc = "Mi hanno chiesto di consegnarti questa appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con l'insegna della Sacerdotessa Anetta, la nostra istruttrice di sacerdoti. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbazia.",
  obj = "Leggi l'Hallowed Letter e parla con Priestess Anetta, nell'Abbazia di Northshire.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;. Sapevo che avresti trovato la strada fino a me. La Luce Sacra risplende su di te e sul cammino che hai scelto. Questi sono tempi duri — la Legione Infuocata è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e sta a te aiutare quante più persone puoi.",
  reward = "Man mano che acquisti esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.",
  en_title = "Hallowed Letter",
  en_obj = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.",
}
T[3104] = {
  title = "Lettera con Glifi",
  desc = "Mi hanno chiesto di consegnarti questa non appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con l'insegna di Khelden, il nostro istruttore di maghi. Al tuo posto la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi la Glyphic Letter e parla con Khelden Bremen, dentro l'Abbazia di Northshire.",
  progress = "Salve, $N. Sono Khelden. Posso fare qualcosa per te?",
  reward = "Ah ah, sapevo che il mio biglietto non ti avrebbe distolto dal tuo cammino. Quindi sei $Gpronto:pronta;, vero? $GPronto:Pronta; ad accettare il tuo destino? $GPronto:Pronta; a sfidare gli dei e qualsiasi altra forza ti si pari davanti nella ricerca della conoscenza e del potere?$B$BNon ti mentirò, $N: sarai $Gtemuto:temuta; quanto $Grispettato:rispettata;. Ma sappi anche questo: sarò qui per te quando avrai bisogno di addestramento. Basterà che tu venga a cercarmi man mano che diventerai più potente.",
  en_title = "Glyphic Letter",
  en_obj = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.",
}
T[3105] = {
  title = "La Lettera Corrotta",
  desc = "Mi hanno chiesto di consegnarti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei coboldi, $N. Sembra una lettera sigillata con lo stemma di Drusilla, una delle nostre istruttrici. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.",
  obj = "Leggi la Tainted Letter e parla con Drusilla La Salle, accanto all'Abbazia di Northshire.",
  progress = "Ah, dunque sei $Garrivato:arrivata;, e appena in tempo, $N. Poco fa alcune guardie erano qui e mi lanciavano occhiate curiose... patetici profani.",
  reward = "Man mano che il tuo potere crescerà, sarai $Gtentato:tentata; — devi sempre ricordarti di controllarti. Non ti mentirò — la corruzione può colpire chiunque pratichi le arti arcane, soprattutto chi ha a che fare con le creature del Twisting Nether. Sii paziente, e sii prudente... ma non lasciare che questo soffochi la tua ambizione.$B$BQuando sarai più potente, torna da me e ti insegnerò di più sulle nostre vie.",
  en_title = "Tainted Letter",
  en_obj = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.",
}
T[3106] = {
  title = "Runa Semplice",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi la Simple Rune e parla con Thran Khorman, nella Coldridge Valley.",
  progress = "Accidenti che freddo oggi, eh? Sembra che la neve non se ne vada mai, $N.$B$BProbabilmente l'hai già notato, ma adesso nella nostra città vivono degli gnomi. È perché sono riusciti a farsi saltare in aria la loro casa. Non andarlo a raccontare in giro, ma non posso proprio dargli torto — credo che anch'io sarei ricorso agli esplosivi, se Ironforge fosse stata infestata dai Dark Iron o gente simile.",
  reward = "Altre cose che probabilmente vedrai, così sei al corrente: nani che in battaglia usano la magia invece del fucile. Alcuni di noi che si mettono a venerare la Luce Sacra come certi umani e, ultimi ma non meno importanti, i trogg. Su di loro ne saprai di più in seguito, ma quello che devi sapere adesso è che sono qui per aiutarti.$B$BSono qui per insegnarti a essere $Gun vero:una vera; $C. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.",
  en_title = "Simple Rune",
  en_obj = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.",
}
T[3107] = {
  title = "Runa Consacrata",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Mi sa che viene da Bromos, l'istruttore di paladini. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi la Consecrated Rune e parla con Bromos Grummner, nella Valle di Coldridge.",
  progress = "Allora, ce l'hai fatta! E appena in tempo. C'è molto da fare nella Valle di Coldridge e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!$B$BOra sei $Gun Cavaliere:una Cavaliera; della Mano d'Argento, sii $Gpronto:pronta; a comportarti come tale.",
  reward = "Gli umani ci hanno insegnato molto sulla Luce Sacra e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo un grande rispetto per quanto sia intriso di tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra il dolore e la salvezza.$B$BNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere $Gpronto:pronta;, torna da me e vedremo di darti un po' di addestramento. Non possiamo mandarti in giro per il mondo $Gimpreparato:impreparata;, no?",
  en_title = "Consecrated Rune",
  en_obj = "Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley.",
}
T[3108] = {
  title = "Runa Intagliata",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thorgas, l'istruttore di cacciatori. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Etched Rune e parla con Thorgas Grimson, nella Valle di Coldridge.",
  progress = "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai nemmeno dovuto seguire le mie tracce per trovare il posto. Ah ah!$B$BLa nostra professione ha radici profonde nella tradizione, $N. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Perfino sopravvivere contando solo sul proprio ingegno richiede molto coraggio e molta astuzia. Credi di farcela?",
  reward = "Una cosa che dovresti ricordare sempre è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; il luccichio della tua arma; il peso delle tue munizioni; il morso di un vento gelido; tutte queste cose devi conoscerle a fondo.$B$BFarò quello che posso per aiutarti, ma la maggior parte del lavoro spetta a te. Ogni volta che pensi di essere $Gpronto:pronta;, torna a parlare con me. Ti addestrerò quando potrò.",
  en_title = "Etched Rune",
  en_obj = "Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley.",
}
T[3109] = {
  title = "Runa Codificata",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Encrypted Rune e parla con Solm Hargrin, nella Valle di Coldridge.",
  progress = "Ce l'hai fatta! Magnifico!$B$BUltimamente c'è un gran via vai, quindi sono contento di contare un altro membro del clan di Ironforge tra le nostre file. Per i miei gusti, troppi di noi guardano all'arcano e al divino. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?",
  reward = "Comunque, quando comincerai a curiosare in giro per Coldridge, prima o poi avrai bisogno di addestramento. Torna da me ogni volta che senti di averne bisogno e ti insegnerò quello che so — un trucco qui, una manovra là. Sai, le cose che ti tengono in vita e ti fanno guadagnare qualche moneta in più.$B$BE tieni d'occhio anche i nostri amici gnomi... sono loro ad aver avuto la peggio, visto che Gnomeregan è stata... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.",
  en_title = "Encrypted Rune",
  en_obj = "Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley.",
}
T[3110] = {
  title = "Runa Benedetta",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Branstock, l'istruttore di sacerdoti. Dacci un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Hallowed Rune e parla con Branstock Khalder, ad Anvilmar.",
  progress = "Ah! Ce l'hai fatta, $N! Magnifico!$B$BStavo per dirti che ormai perdevo la fede nel tuo arrivo... capito, perdere la fede? È una battuta, $Gragazzo:ragazza;... uff, lascia stare. Tanto non sei $Gvenuto:venuta; qui per le mie battutacce.",
  reward = "Sono io quello che può addestrarti mentre cominci a orientarti nella Valle di Coldridge. Quando ti senti $Gpronto:pronta;, torna da me e vedremo se insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.$B$BHai la Luce dalla tua parte, insieme a tutta Ironforge, $N... ma non sentirti sotto pressione per diventare qualcuno di speciale.",
  en_title = "Hallowed Rune",
  en_obj = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.",
}
T[3111] = {
  title = "Runa con Glifi",
  desc = "Tanto tempo fa gli alti elfi insegnarono i segreti della magia a noi e ai nostri alleati umani. Ci facevano grandi prediche sulle regole e su come la magia possa farti impazzire! Ma non crederci. Noi non siamo come gli elfi; non abbiamo le loro stesse debolezze. Basta che tu resti sulla retta via, e scoprirai che la magia è potente come strumento quanto come arma.$B$BQuando sei $Gpronto:pronta;, vieni a cercarmi dentro Anvilmar. Ti aspetto!",
  obj = "Parla con Marryk Nurribit, dentro Anvilmar.",
}
T[3112] = {
  title = "Promemoria Semplice",
  desc = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi il Simple Memorandum e parla con Thran Khorman, nella Coldridge Valley.",
  progress = "Ah, beh, un altro memorandum da $Gun:una; $R in missione... che tenerezza.$B$BNo, no, non ti sto prendendo in giro, $Gpiccoletto:piccoletta;. Bisogna rispettare la tua tenacia, questo è certo. Sarei seccato anch'io se Ironforge fosse stata presa dai nani Dark Iron, quindi non pensare che non capisca la tua situazione...",
  reward = "Beh, visto che questa è la tua direttiva principale, o come la chiamate di questi tempi, ho dato la mia parola che avrei fatto tutto il possibile perché tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.$B$BOgni volta che ti senti $Gpronto:pronta;, torna dal buon vecchio Thran e sarò felice di condividere con te quello che so. L'addestramento ha un costo, ma non sarà troppo caro. Buona fortuna.",
  en_title = "Simple Memorandum",
  en_obj = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.",
}
T[3113] = {
  title = "Promemoria Codificato",
  desc = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Encrypted Memorandum e parla con Solm Hargrin, nella Valle di Coldridge.",
  progress = "Sono contento di vedere che hai ricevuto il mio biglietto e che sei $Gvenuto:venuta;. Scusa se ho finto che fosse un memorandum dei tuoi superiori... non volevo offenderti. Sapevo solo che noi due, insieme agli altri come noi, dobbiamo restare uniti.$B$BNon sono in molti a pensare che sia una gran cosa avere la tua gente e la mia rintanate nella stessa città, ma io credo che possiamo andare d'accordo benissimo. Tu che ne pensi?",
  reward = "Qui me ne sto per conto mio, così nessuno ci dà la colpa delle cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o altro, torna pure quando vuoi.$B$BIo e te ci capiamo. Sappiamo che, quando si arriva al dunque, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Anche se Gnomeregan è stata... invasa, e qualunque altra cosa ci capiti addosso, possiamo contare gli uni sugli altri per guardarci le spalle. Giusto?",
  en_title = "Encrypted Memorandum",
  en_obj = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.",
}
T[3114] = {
  title = "Promemoria con Glifi",
  desc = "Mentre mi davi una mano, mi hanno dato questo promemoria da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Marryk, l'istruttore di maghi. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi il Glyphic Memorandum e parla con Marryk Nurribit, dentro Anvilmar, sopra la Valle di Coldridge.",
  progress = "Sì, cosa c'è, $R? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.",
  reward = "Ah, già! Le Arti Arcane... ma certo.$B$BEcco quello che devi sapere, $N: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per qualunque incantesimo tu voglia. E per carità, stai alla larga da Gnomeregan. A parte questo, buona giornata! Sono qui se hai bisogno di me o vuoi addestrarti... o per qualsiasi altra cosa.",
  en_title = "Glyphic Memorandum",
  en_obj = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.",
}
T[3116] = {
  title = "Sigillo Semplice",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di guerrieri, Alyissia. Sembra che Alyissia voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.",
  obj = "Leggi il Simple Sigil e parla con Alyissia, a Shadowglen.",
  progress = "Ce l'hai fatta. Ne sono davvero felice.$B$BNegli ultimi anni sono successe molte cose, $N: la creazione di Teldrassil, la corruzione di molte creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute, come Feralas... tante cose, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui; la più importante è proteggere la nostra gente da altro male.",
  reward = "Presto vedrai gente di altre razze tra i rami della nostra casa — non lasciare che questo faccia nascere in te dei pregiudizi. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno disinteressati, ma meritano un po' di fiducia.$B$BMa ora niente di tutto questo conta. Ora dobbiamo concentrarci su di te e su come puoi aiutare la nostra gente. Sono qui proprio per questo. Ti addestrerò nelle vie $Gdel:della; $C man mano che diventi più forte. Torna da me quando vuoi, e farò quello che posso per aiutarti.",
  en_title = "Simple Sigil",
  en_obj = "Read the Simple Sigil and speak to Alyissia in Shadowglen.",
}
T[3117] = {
  title = "Sigillo Intagliato",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di cacciatori, Ayanna. Sembra che Ayanna voglia parlarti quando hai un momento. Leggilo, e poi portaglielo.",
  obj = "Leggi l'Etched Sigil e parla con Ayanna Everstride, in cima ad Aldrassil, a Shadowglen.",
  progress = "Sei $Garrivato:arrivata;, e appena in tempo, $N. $GBenvenuto:Benvenuta; a Shadowglen.$B$BConfido che il mio sigillo ti abbia trovato in buona salute e di buon umore?$B$BCome ho detto prima, sono qui per addestrarti come $Gcacciatore:cacciatrice;; ad addomesticare le bestie perché ti aiutino in battaglia; a usare l'arco con precisione infallibile; a rispettare le terre che chiamiamo casa, e anche quelle al di là.",
  reward = "Mentre scopri quello che Shadowglen ha da insegnarti, vieni a trovarmi — potrò aiutarti a capire meglio il tuo ruolo di $Gcacciatore:cacciatrice; e ciò di cui sei capace.$B$BSono tempi pericolosi, $N, non dare per scontata l'abilità dei tuoi animali — in questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Che Elune ti accompagni, e torna ancora da me.",
  en_title = "Etched Sigil",
  en_obj = "Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen.",
}
T[3118] = {
  title = "Sigillo Codificato",
  desc = "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore di ladri, Frahun. Sembra che Frahun voglia parlarti quando hai un momento. Leggilo e poi portalo a lui.",
  obj = "Leggi l'Encrypted Sigil e parla con Frahun Shadewhisper, a Shadowglen.",
  progress = "Salve, $N. Sono contento che tu mi abbia trovato. Pensavo che magari ti fossi $Gperso:persa; lungo la strada.$B$BA Shadowglen non è successo niente di davvero nuovo da quando ti ho mandato il mio sigillo, ma lascio a te il compito di raccogliere informazioni. Parla con le altre persone intorno ad Aldrassil, se vuoi.",
  reward = "Fino ad allora, sappi che quelli come noi servono più che mai in questi tempi incerti. La pace con le altre razze può venire meno da un momento all'altro, e si parla molto di membri dell'Orda che cercano di seminare ancora più sfiducia. Ricordalo.$B$BMan mano che acquisti potere e ti senti più $Gpreparato:preparata;, torna da me qui e vedrò di farti avere un po' di addestramento. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.",
  en_title = "Encrypted Sigil",
  en_obj = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.",
}
T[3119] = {
  title = "Sigillo Benedetto",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di sacerdoti, Shanda. Sembra che Shanda voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.",
  obj = "Leggi l'Hallowed Sigil e parla con Shanda, ad Aldrassil.",
  progress = "Mi fa piacere vedere che sei $Garrivato:arrivata; così in fretta, $N. $GBenvenuto:Benvenuta;.$B$BCome probabilmente avrai sentito, tutta Teldrassil è in fermento per l'andirivieni dei viaggiatori. Perfino ai membri dell'Alleanza è stato concesso di salire sui rami di Teldrassil, per incontrare altri Kaldorei che si preparano alle avventure che li attendono.",
  reward = "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora va' a parlare con gli altri a Shadowglen — possono dirti di più su quello che è accaduto. Aiutali in ogni modo possibile, e ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò quello che posso.",
  en_title = "Hallowed Sigil",
  en_obj = "Read the Hallowed Sigil and speak to Shanda in Aldrassil.",
}
T[3120] = {
  title = "Sigillo Verdastro",
  desc = "Questo sigillo me l'ha dato un messaggero del nostro istruttore di druidi, Mardant. Pare che Mardant voglia parlarti quando hai un momento. Leggilo e poi portaglielo.",
  obj = "Leggi il Verdant Sigil e parla con Mardant Strongoak, nell'albero Aldrassil, a Shadowglen.",
  progress = "Ah, giovane $C. Vedo che sei impaziente di continuare i tuoi studi. Bene.$B$BMi chiedo: hai già passato molto tempo nell'Emerald Dream? Forse non sei ancora $Gpronto:pronta; per questo... Col tempo lo sarai, ne sono certo.$B$BMa fino ad allora, dovremmo parlare d'altro.",
  reward = "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti dell'Emerald Dream.$B$BMan mano che imparerai e acquisterai potere, conoscerai meglio la nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò quello che posso sulle vie della nostra gente.",
  en_title = "Verdant Sigil",
  en_obj = "Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen.",
}
T[3121] = {
  title = "Una Strana Richiesta",
  desc = "Neeru Fireblade, a Orgrimmar, ha quello che mi serve per cominciare il lavoro qui! Ha preparato un intruglio che mi occorre per il mio... be', vedrai.$B$BE adesso va' — a Orgrimmar. Tieni, porta questa con te. È una testa rimpicciolita che ho promesso a Neeru in cambio delle erbe. È la testa di un povero nano in cui mi sono imbattuto nella foresta. Sono sicuro che a Neeru piacerà.$B$BTroverai Neeru nella Fenditura dell'Ombra.",
  obj = "Porta la Shrunken Head a Neeru Fireblade, a Orgrimmar.",
  progress = "Sì?",
  reward = "Aspettavo che Uzer'i me la consegnasse...$B$BLascia che ti dia il miscuglio di erbe che ho preparato per i suoi... be', esperimenti...",
}
T[3122] = {
  title = "Ritorno dallo Stregone Uzer'i",
  desc = "Ecco le erbe, $N. Portale allo stregone Uzer'i.$B$BDigli, per favore, che sono soddisfatto della testa rimpicciolita.",
  obj = "Consegna Neeru's Herb Pouch a Witch Doctor Uzer'i, in Feralas.",
  progress = "Hai parlato con Neeru?",
  reward = "È proprio quello che mi serve per preparare il recipiente del muisek, $N. Presto vedremo se i miei ultimi incantesimi sono potenti come speravo.$B$BUn momento, per favore. Devo compiere il rituale e applicare le erbe.",
}
T[3123] = {
  title = "La Prova del Recipiente",
  desc = "Sarà una prova; sia del rituale che ho compiuto, sia delle tue capacità. Prendi questo recipiente, $N. Con esso avrai il potere di rimpicciolire una creatura e catturarla al suo interno.$B$BVa' nelle Hinterlands e cerca le creature chiamate Wildkin, che un tempo erano gli animali prediletti di Elune, la dea degli elfi della notte. I tuoi bersagli sono gli owlbeast feroci, primitivi o selvaggi, $N. Uccidine 10 e usa il recipiente del muisek per rimpicciolirli e catturarli prima che i loro spiriti possano fuggire.",
  obj = "Va' nelle Hinterlands e trova i Wildkin. Uccidine 10 e usa il Wildkin Muisek Vessel per rimpicciolire e catturare i Wildkin caduti.$B$BPorta 10 Wildkin Muisek e il Wildkin Muisek Vessel a Witch Doctor Uzer'i, a Feralas.",
  progress = "Sei $Griuscito:riuscita; a catturare i wildkin?$B$BSe ci riesci, saremo pronti a rimpicciolire e catturare il muisek delle creature di Feralas.",
  reward = "Quando una creatura muore di morte violenta, il suo muisek può fuggire e cercare vendetta. Rimpicciolire le creature, come hai fatto tu, $N, impedisce al muisek di fuggire. Ora possiamo usarlo come vogliamo!",
}
T[3124] = {
  title = "Muisek di Ippogrifo",
  desc = "Visto che hai dimostrato di essere $Gdegno:degna; di fiducia e capace di usare il recipiente del muisek, ora voglio che tu catturi un'altra creatura.$B$BDa molti anni gli ippogrifi sono compagni fedeli degli elfi della notte; il loro spirito è leale e saldo.$B$BIl tuo compito è uccidere 10 ippogrifi piumaribelle e, in fretta, rimpicciolirli e catturarli con il recipiente, così che il loro muisek sia conservato. Troverai gli ippogrifi nella High Wilderness, a sud di qui.",
  obj = "Uccidi 10 Frayfeather Hippogryph di qualunque tipo, poi usa l'Hippogryph Muisek Vessel per rimpicciolirli e catturarli.",
  progress = "Sei $Griuscito:riuscita; a catturare gli ippogrifi?",
  reward = "Se, dopo aver ucciso un animale, lasciassimo fuggire il muisek, potrebbe prendere la forma di una creatura ancora più grande. Non saremmo mai al sicuro dalla sua vendetta.$B$BTi ho dato un lavoro pericoloso, $N. E ancora una volta l'hai portato a termine bene.",
}
T[3125] = {
  title = "Muisek del Drago Fatato",
  desc = "$N, ora devo chiederti di catturare una creatura che all'aspetto può sembrare assai fragile, ma è il suo spirito potente quello che cerchiamo davvero. I draghi fatati di cui parlo sono stati alleati degli elfi della notte. Dobbiamo catturarne uno, così che anche l'orda possa trarre beneficio da questa forza di spirito.$B$BEcco il muisek, $N. Uccidi 8 folletti sfreccianti o draghi folletto e cattura il loro muisek. Li troverai a ovest di qui.",
  obj = "Uccidi 8 Sprite Darter o Sprite Dragon. Usa il Faerie Dragon Muisek Vessel per rimpicciolire e catturare i Draghi Fatati caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare il muisek dei draghi fatati?",
  reward = "Grazie, $N. Ora i poteri spirituali del drago fatato saranno a nostra disposizione.$B$BSpero che tu sia $Gdisposto:disposta; a svolgere un altro compito per me.",
}
T[3126] = {
  title = "Muisek del Treant",
  desc = "I camminatori erranti della foresta, che vagano qua e là tra gli alberi, sono il nostro prossimo bersaglio, $N. Gli elfi della notte hanno arruolato i treant come alleati per combattere l'orda. Saranno anche lenti nei movimenti, ma il loro ruolo di protettori è innegabile.$B$BPresto potremo usare questo potere a nostro vantaggio.$B$BTrova 3 camminatori erranti della foresta; uccidili e usa il recipiente del muisek per rimpicciolirli e catturarli.",
  obj = "Uccidi 3 Wandering Forest Walkers. Usa il Treant Muisek Vessel per rimpicciolire e catturare i Treant caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare i camminatori erranti della foresta?",
  reward = "Grazie, $N. La nostra collezione di muisek è quasi completa.",
}
T[3127] = {
  title = "Muisek del Gigante delle Montagne",
  desc = "L'ultimo compito che ti chiederò è di andare a nord-ovest e trovare il nemico finale.$B$BI giganti delle montagne lasciarono le montagne per aiutare gli elfi della notte quando la legione infuocata comparve nel mondo. Li riconoscerai dalla loro mole enorme e da come il terreno comincia a tremare mentre attraversi le loro terre rocciose.$B$BNon vedo l'ora di imbrigliare un potere di quella grandezza. Uccidi 7 giganti delle montagne, poi usa il recipiente del muisek per catturare il loro potente muisek.",
  obj = "Uccidi 7 Land Walkers o Cliff Giants. Usa il Mountain Giant Muisek Vessel per rimpicciolire e catturare i Giganti delle Montagne caduti.",
  progress = "Sei $Griuscito:riuscita; a catturare i giganti delle montagne?",
  reward = "Immagina un po' le possibilità che ci offre ciò che ora possediamo, $N. Insieme ai materiali che hai raccolto, potrò intrappolare per sempre il muisek di queste creature in qualunque cosa io voglia.",
}
T[3128] = {
  title = "Materiali Naturali",
  desc = "Mi serviranno alcuni materiali per portare a termine la mia impresa... Puoi occupartene insieme agli altri compiti che ti darò.$B$BMi servirà un ceppo scheggiato preso da un treant di Feralas. Minerali incrostati, quelli li trovi sui giganti delle montagne e sui draghi fatati a ovest. Poi trovami un po' di tendini resistenti dagli owlbeast delle Hinterlands o dagli ippogrifi di Feralas. Infine, mi servirà una gran quantità di frammenti metallici da una qualunque delle creature che ho nominato.",
  obj = "Porta 2 Splintered Logs, 6 Encrusted Minerals, 20 pezzi di Resilient Sinew e 40 Metallic Fragments a Witch Doctor Uzer'i a Camp Mojache.",
  progress = "Sei $Griuscito:riuscita; a raccogliere i materiali che mi servono?",
  reward = "Ottimo! Questi materiali, uniti al muisek, dovrebbero darci proprio i risultati che volevamo.",
}
T[3129] = {
  title = "Armi dello Spirito",
  desc = "Infondere il muisek nelle armi è un procedimento difficile. Ora che ho tutti i materiali necessari e il muisek delle creature che hai catturato, posso cominciare. Aspetta, per favore; torno tra un attimo.",
  obj = "Witch Doctor Uzer'i vuole che tu aspetti un momento mentre prepara le armi.",
  reward = "Come promesso, a te la scelta, $N. Il muisek delle creature è stato sigillato per sempre nel potere di queste armi.$B$BOra puoi impugnare la loro energia come se fosse tua. Usala bene.",
}
T[3130] = {
  title = "Contro gli Hatecrest",
  desc = "A questo punto ti indirizzerò al mio secondo, Latronicus. Finora ha tenuto d'occhio da vicino le forze dei naga. Io valuterò qui la situazione generale riguardo ai naga; anche se vorrei impegnare tutte le nostre forze contro di loro, lasciare la roccaforte esposta a un attacco diretto dell'Orda, o peggio, non mi sembra la scelta migliore.$B$BComunque, Latronicus ti aspetta. Buon lavoro finora, $N. Continua così.$B$BPuoi andare.",
  obj = "Fai rapporto a Latronicus Moonspear, alla Feathermoon Stronghold.",
  reward = "Eccellente, $N: in chi lavora con me apprezzo un atteggiamento da \"si può fare\".$B$BIl Generale Feathermoon mi ha incaricato di affrontare i naga in modo diretto. I miei piani sono due: primo, indeboliremo le loro forze, sia nel numero sia nel comando; secondo, scopriremo cosa stanno facendo tra le rovine. Con il tuo aiuto contrasteremo la presenza dei naga senza sacrificare la sicurezza generale della roccaforte.",
  en_title = "Against the Hatecrest",
  en_obj = "Report to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[3141] = {
  title = "Loramus",
  desc = "Dunque desideri combattere i demoni? Faresti bene ad ascoltare la mia storia.",
  obj = "Ascolta Loramus Thalipedes raccontare la sua storia.",
  progress = "Non interrompermi, $R.",
  reward = "E sia...",
}
T[3161] = {
  title = "Gahz'ridian",
  desc = "$N, sono uno scienziato, ma in fondo al cuore anche un cacciatore di tesori!$B$BTanto tempo fa, quando i troll occupavano questa terra, crearono grandi quantità di ornamenti modellati su Gahz'rilla, un'idra che veneravano come una divinità. Questi ornamenti sono intagliati in un elemento che io chiamo \"Gahz'ridian\", dal nome del dio idra.$B$BUn po' ne ho trovati anch'io, ma mi piacerebbe averne altri da studiare — magari riesci a trovarne tu?$B$BHo perfino inventato un rilevatore che rende la ricerca del Gahz'ridian un gioco da ragazzi! Basta indossarlo, e la ricerca comincia!",
  obj = "Marvon Rivetseeker a Tanaris vuole che tu raccolga 30 Gahz'ridian Ornaments.",
  progress = "Hai qualche difficoltà?$B$BIl Gahz'ridian si trova praticamente dappertutto a Tanaris, $N, quindi continua a cercare!",
  reward = "Perfetto; questi ornamenti sono perfetti per i miei studi. Grazie mille dell'aiuto, $N.$B$BOh, posso riavere il mio elmo?",
}
T[3181] = {
  title = "Il Corno della Bestia",
  desc = "Il corno gigantesco è pieno di graffi e crepe. Nella superficie ruvida è conficcato uno strano oggetto di metallo.$B$BGuardando meglio, ti accorgi che il metallo è in realtà la testa spezzata di un'ascia. Sul metallo sono incise queste parole:$B$BProprietà della Montanara Pebblebitty.$B$BQuando provi a staccare la testa d'ascia spezzata, va in mille pezzi.$B$BOps!",
  obj = "Porta Margol's Gigantic Horn a Mountaineer Pebblebitty.",
  progress = "No, non aprirò il cancello.",
  reward = "Cos'hai lì? Un falso, ovviamente!$B$BIo Margol l'ho vista in faccia e so per certo che il suo corno è almeno otto volte più grande di quello che hai in mano, $N. Quello l'avrai preso a uno stormsnout nelle Barrens. No, $Gsignore:signora;, Pebblebitty non la freghi!",
}
T[3201] = {
  title = "Finalmente!",
  desc = "Non riesco a credere che Pebblebitty abbia dubitato dell'autenticità del corno. Detto tra noi, secondo me è solo gelosa. So che ci teneva tanto a uccidere quella bestia con le sue mani, con la storia dell''incidente' e tutto il resto.$B$BQuindi ti serve una certificazione di eroismo? Dopo il contributo che hai appena dato al museo, non sarà un problema.$B$B<Il Curatore Thorius comincia a compilare un grosso documento.>$B$BEcco fatto! Puoi riportarla a Pebblebitty.",
  obj = "Riporta la Proof of Deed a Mountaineer Pebblebitty.",
  progress = "Non ci credo.",
  reward = "Non so come abbia fatto $Guno:una; debole come te a battere Margol, ma i patti sono patti. Ecco la chiave.$B$BSe da qui in poi ti succede qualcosa, sarà solo colpa tua.",
}
T[3321] = {
  title = "Hai Perso Questo?",
  desc = "Hai fatto molto per l'Ordine, $N. Una persona qualunque si sarebbe arresa davanti alla dedizione che ci vuole per arrivare fin qui. Né io né Galvan abbiamo il minimo dubbio: sei $Guno:una; di noi.$B$BEd è per questo che penso che ti meriti una piccola ricompensa. Non è niente di che, solo un monile. Forse ne conosci già le proprietà: se non sbaglio, è proprio quello che ti ha portato da noi.",
  obj = "Aspetta che Trenton finisca il suo lavoro.",
  progress = "Oggi portiamo a compimento la celebrazione del tuo impegno verso l'Ordine.",
  reward = "Alzati e ricevi il tuo riconoscimento, $N, fabbro del Mithril Order.",
}
T[3341] = {
  title = "Porta la Fine",
  desc = "Nelle Barrens si trova un orrendo groviglio di rampicanti chiamato Razorfen Downs. Se le nostre prime osservazioni di quel luogo avevano rivelato una minaccia modesta, le nostre scoperte recenti sono molto più gravi...$B$BI quilboar di Razorfen Downs si sono alleati con il Flagello. Ora li governa un Lich di nome Amnennar l'Araldo del Freddo, che usa il potere della sua immensa coscienza per controllare ogni loro mossa.$B$BAmnennar ha un legame telepatico diretto con Ner'zhul; dobbiamo spezzare questo legame, $N. Bisogna porre fine all'Araldo del Freddo.",
  obj = "Andrew Brownell vuole che tu uccida Amnennar the Coldbringer e riporti il suo teschio.",
  progress = "Questa faccenda è della massima importanza, $N. Dobbiamo fermare ogni tentativo del Flagello di rinforzare le sue file.",
  reward = "La lealtà di un Lich è incrollabile, $N. Fagli capire che una lealtà simile li porterà solo alla distruzione.",
  en_title = "Bring the End",
  en_obj = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",
}
T[3362] = {
  title = "Valle dei Thistleshrub",
  desc = "Hai mai visto la Valle dei Thistleshrub? È un posto parecchio pericoloso, $N.$B$BQuelle strane bestie che ci sono lì, non mi fido di loro nemmeno per un istante! Thistleshrubs nodosi e thistleshrub rootshapers, mi pare che si chiamassero così...$B$BComunque, io nella valle voglio entrarci, ma con tutti quei thistleshrubs in giro non ci torno neanche per sogno. Ed è qui che entri in gioco tu — se ne togli di mezzo un po', potrei anche pensare di tornarci. Che ne dici, $N? Mi dai una mano?",
  obj = "Tran'rek, a Gadgetzan, vuole che tu uccida 8 Gnarled Thistleshrubs e 8 Thistleshrub Rootshapers.",
  progress = "Vorrei dare un'occhiata più da vicino a quel cactus nella valle... Quindi vedi di lasciarne un po' intero, eh?",
  reward = "Sono così grossi? Mi sa che dovrò ripensare il mio piano...$B$BMa tu la tua parte l'hai fatta, quindi ecco quello che ti avevo promesso.",
}
T[3363] = {
  title = "Songflower Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di songflower. La pianta emana un odore pungente e malsano. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion sul songflower. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[3366] = {
  title = "La Scheggia Brillante",
  desc = "La scheggia è di un verde brillante e, anche se è solida, appena sotto la superficie turbina qualcosa che sembra fumo. Non puoi fare a meno di fissare le profondità del cristallo; allo stesso tempo, sai che ha qualcosa di molto inquietante.$B$BForse dovresti cercare a Ratchet qualcuno che sappia dirti di più su questa strana scheggia.",
  obj = "Va' a Ratchet per scoprire il significato del Nightmare Shard.",
}
T[3367] = {
  title = "Pietre di Suntara",
  desc = "<Dorius geme.>$B$BSono ferito gravemente, $R. Mi sento... stordito... Gira tutto... Perdo sangue... dentro.$B$BDevo tornare a Ironforge. Aiutami, $N.",
  obj = "Aiuta Dorius Stonetender a tornare a Ironforge.",
  progress = "Non ce la farò...",
  reward = "Questa lettera è caduta a Dorius quando gli hanno sparato.",
}
T[3368] = {
  title = "Pietre di Suntara",
  desc = "Fratello,$B$BSe stai leggendo questa lettera, io non ci sono più. Non so come ti sia arrivata, ma ringrazia e ricompensa chi ne ha il merito.$B$BQuanto alle pietre: esistono, e sono in mano ai Dark Iron. Il loro capo, Lathoric il Nero, usa il potere delle pietre per ridurre in schiavitù la mia squadra di scavo. Li hanno portati al calderone. Hanno la mente stravolta e lavorano giorno e notte per completare qualcosa chiamato Obsidion.$B$BAiutali, fratello. È l'ultimo desiderio di un morto.$B$B— Dorius",
  obj = "Porta la Singed Letter a Curator Thorius a Ironforge. Si trova nella Hall of Explorers.",
  progress = "<Thorius singhiozza.>",
  reward = "<Thorius si asciuga il viso.>$B$BIn nome della Luce, il suo desiderio sarà esaudito. Lo giuro.",
}
T[3369] = {
  title = "Negli Incubi",
  desc = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi.$B$BDevi trovare Hamuul Runetotem, sull'Elder Rise. Va' a Thunder Bluff. Non posso dire altro.",
  obj = "Porta il Nightmare Shard a Hamuul Runetotem, sull'Elder Rise.",
  progress = "Posso esserti utile in qualcosa?",
  reward = "Ti manda Falla? Bene, vediamo questa scheggia di cui, a quanto dici, era così restia a parlare...$B$B<Hamuul scruta dentro la scheggia>$B$BOh... io non... Be'.$B$B$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui non dovresti occuparti.$B$BDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...$B$BForse in futuro le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",
}
T[3370] = {
  title = "Negli Incubi",
  desc = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi...$B$BDevi trovare Mathrengyl Bearwalker, presso il Cenarion Circle. Va' a Darnassus. Non posso dire altro.",
  obj = "Porta il Nightmare Shard a Mathrengyl Bearwalker, a Darnassus.",
  progress = "Posso esserti utile in qualcosa?",
  reward = "Ti manda Falla? Bene, vediamo questa scheggia di cui, a quanto dici, era così restia a parlare...$B$B<Mathrengyl scruta dentro la scheggia>$B$BOh... io non... Be'.$B$B$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui devono occuparsi soltanto i druidi del Cenarion Circle.$B$BDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...$B$BForse in futuro le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.",
}
T[3371] = {
  title = "Giustizia Nanica",
  desc = "Dove una volta avevo il cuore c'è un buco vuoto, desolato, $N. Dalla perdita di Dorius non mi riprenderò tanto presto. Devo portare a compimento la sua ultima volontà — i responsabili di questo omicidio a sangue freddo devono essere assicurati alla giustizia.$B$BTorna nella Searing Gorge ed esaudisci la sua ultima richiesta: Libera i suoi uomini.",
  obj = "Torna nella Searing Gorge e trova la squadra di archeologi di Dorius.",
  reward = "Lascia perdere me, aiuta gli altri.",
}
T[3372] = {
  title = "Liberali",
  desc = "Liberali, $R. Anche dopo che i loro corpi hanno ceduto, il potere della Suntara li costringe a portare a termine i loro compiti.$B$BL'altare di Suntara è la chiave. Vai a nord-ovest; sulle colline sopra la caverna... il Martello del Crepuscolo sorveglia una reliquia. Recuperala e mettila sull'altare di Suntara.$B$B<L'archeologo morente crolla a terra.>",
  obj = "Trova il Mysterious Artifact custodito dagli Idolatri del Martello del Crepuscolo nel quadrante nord-ovest della Searing Gorge.",
  progress = "L'altare è vuoto.",
  reward = "Posi il manufatto misterioso sull'altare di Suntara.",
}
T[3373] = {
  title = "L'Essenza di Eranikus",
  desc = "Appena tocchi la gemma, una voce profonda ti risuona nella mente.$B$B\"Mortale, ascolta questa supplica. Io sono Eranikus del Green Dragonflight, custode di questo tempio maledetto. Il mio compito, impedire che i troll riportino mai più tra noi quell'abominio del loro dio, per ora è finito in un fallimento. Mentre infondo in questa gemma parte della mia essenza, sento la mia presa sul Sogno torcersi nel caos. Ti prego — metti questa gemma nella fonte dell'essenza nella mia tana, e lascia che lì la nostra magia purifichi la mia psiche dalla corruzione, così che io possa riposare.\"",
  obj = "Metti l'Essence of Eranikus nell'Essence Font che si trova in questa tana, nel Sunken Temple.",
  progress = "Mentre ti avvicini alla fonte dell'essenza di cui ti ha parlato Eranikus, la sua voce ti sfiora di nuovo la mente.$B$B\"Sì, mortale, questa fonte dell'essenza redimerà quel che resta di incorrotto nella mia psiche, infuso in questa gemma. Metti la gemma dentro la fonte, e lascia che la magia del Green Dragonflight lavi via dal mio essere la contaminazione e la corruzione. Solo allora troverò la vera liberazione, e solo allora il Dragonflight potrà riaffermare la propria tutela sugli Atal'ai.\"",
  reward = "Metti la gemma dentro la fonte dell'essenza.$B$B\"Grazie, mortale, hai — no... questo, questo non può essere! No! La corruzione di questo dio maledetto contamina perfino la santità di una fonte dell'essenza del Green Dragonflight! No, ti prego, sento la mia essenza strapparsi da me! IL DOLORE! Sento la morsa di un incubo eterno che mi afferra...\"$B$B\"Mortale, ti imploro! Trova qualcuno del Green Dragonflight che fermi tutto questo... aiutami... sono incatenato nell'oscurità... per sempre nel tormento... ti prego, non torturare...\"",
}
T[3374] = {
  title = "L'Essenza di Eranikus",
  desc = "Attivi la Pietra del Giuramento, e Itharius ti parla direttamente nella mente attraverso la pietra.$B$B\"Accettando l'incarico racchiuso in questa Pietra del Giuramento, accetti di aiutare la mia causa e quella dello Stormo di Ysera nel redimere l'anima corrotta di Eranikus. Il primo sacrificio, uno dei tanti che senza dubbio tu e io faremo, sarà consegnarmi la gemma che tiene incatenato ciò che resta della parte libera della mente di Eranikus.\"$B$B\"Fallo, $N, e lavoreremo insieme per redimere un'anima degna di redenzione.\"",
  obj = "Porta l'Oathstone of Ysera's Dragonflight e la Chained Essence of Eranikus a Itharius, nella Swamp of Sorrows. Lì sceglierai se aiutare lo Stormo di Ysera oppure no.",
  progress = "Eccoci, $N, a un altro bivio. È giunto il momento di fare un'altra scelta. Cosa scegli, mortale?",
  reward = "Hai fatto la tua scelta, e così tutto ha inizio. Finora le tue scelte sono state quelle che considererei giuste; d'ora in poi, le tue azioni e le tue imprese decideranno se continuerà a essere così.",
  en_title = "The Essence of Eranikus",
  en_obj = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.",
}
T[3377] = {
  title = "Preghiera a Elune",
  desc = "Mi aiuterai, mortale? Ascolta la mia storia.",
  obj = "Ascolta Zamael Lunthistle che racconta la sua storia.",
  progress = "Lasciami finire la mia storia.",
  reward = "Ho accettato il mio destino qui, in questa gabbia, ma la preghiera va trovata.",
}
T[3378] = {
  title = "Preghiera a Elune",
  desc = "Mi aiuterai, mortale? Troverai la preghiera a Elune?$B$BCome ho detto, la preghiera era incisa su una tavoletta d'oro. Deve averla addosso una di queste canaglie adoratrici di idoli.$B$BSe recuperi la mia preghiera, portala ad Astarii Starseeker a Darnassus. Poco importa che la mia fede si sia riaccesa dopo le innumerevoli azioni malvagie che ho compiuto contro questo mondo e i suoi abitanti, ma la mia preghiera deve essere ascoltata. L'assoluzione è l'ultima cosa che mi aspetto.",
  obj = "Trova la Prayer to Elune e portala ad Astarii Starseeker a Darnassus.",
  progress = "Cosa ti porta al Tempio della Luna, $N?",
  reward = "Elune ti sorride questa sera, $N. Le hai restituito un'anima perduta. Ti prego di accettare questo in segno della nostra gratitudine.",
}
T[3379] = {
  title = "Tessitore d'Ombra",
  desc = "I ragni della Searing Gorge sono una fonte inestimabile di seta d'ombra. Come sai, la seta d'ombra è molto ricercata dagli artigiani del nostro mestiere.$B$BDi recente un gruppo di bracconieri ha invaso queste terre e fa strage di ragni con noncuranza, senza darsi il minimo pensiero degli effetti a lungo termine di quello che fa. Il primo compito che ti chiedo, quindi, è semplice: trovali... ed eliminali.$B$BComincia a cercare a nord.$B$BSe ti serve aiuto, parla con Raze.",
  obj = "Uccidi il gruppo di Shadowsilk Poachers che si aggira per la Searing Gorge. Nilith ha motivo di credere che siano cinque quelli da sterminare. A compito finito, torna da Nilith nella Searing Gorge.",
  progress = "Che informazioni mi porti?",
  reward = "Ottimo lavoro, $N.$B$BSono sicura che questo è un capo in tessuto d'ombra che non hai ancora visto.",
}
T[3380] = {
  title = "Il Sunken Temple",
  desc = "Ci sono spiriti inquieti in questo mondo, $N. Ci sono spiriti corrotti dal loro isolamento, legati a un male antico...$B$BHo sentito parlare di un luogo che giace nelle profondità della terra — relegato laggiù da poteri più grandi di quanti ne abbia mai visti.$B$BSe desideri saperne di più su questo luogo; il Sunken Temple, cerca un goblin di nome Marvon Rivetseeker. Ha studiato molti luoghi antichi del mondo, e l'ultima cosa che si sa di lui è che ha lasciato la sua casa a Ratchet per studiare le rovine dei troll a Tanaris.",
  obj = "Trova Marvon Rivetseeker a Tanaris.",
  reward = "Sì, il Sunken Temple, posso dire di averlo visto con i miei occhi. Forse ti piacerebbe saperne di più?$B$BMi sembri un tipo avventuroso — so cose che potrebbero incuriosirti...",
}
T[3381] = {
  title = "Un Incontro con il Padrone",
  desc = "Ah, $Gun:una; giovane $R $Gvenuto:venuta; a parlare con Sanath. Che splendida giornata! Sono così onorato che tu mi degni della tua presenza. Grazie!$B$BPer favore... non essere così arrogante da prendere il mio sarcasmo per un complimento. Mettiamo in chiaro una cosa: non mi piaci. Ma questa chiacchierata non riguarda noi due — riguarda il mio padrone.$B$BPortami un paio di piume di ippogrifo per le mie frecce e ti darò il permesso di vederlo. Mi ha chiesto di mandargli gli avventurieri che si dimostrano abbastanza degni.",
  obj = "Porta 2 Undamaged Hippogryph Feathers a Sanath Lim-yo ad Azshara, se vuoi parlare con il suo padrone.",
  progress = "Resto qui per ordine del mio padrone. Ho il permesso di chiedere il prezzo che voglio per il trasporto fino alla sua torre. Per ora chiedo solo due piume a ogni viaggiatore, così posso continuare a fabbricare le mie frecce inconfondibili.$B$BSe non stai $Gattento:attenta;, alzo il prezzo. Che ne dici di mezza dozzina di monete d'oro?$B$BGià, lo immaginavo. Tu bada a come ti comporti e il prezzo resta dov'è.",
  reward = "Due piume, proprio come avevo chiesto. E per niente male.$B$B$GPronto:Pronta;, allora? Basta una parola e sei in viaggio.$B$BAh, e ancora una volta, bada a come ti comporti... il mio padrone non sopporta gli imbecilli, ma è molto generoso con chi sa compiacerlo.",
}
T[3382] = {
  title = "Un Equipaggio Sotto Attacco",
  desc = "Eravamo appena al largo della costa, in cerca di un approdo sicuro dove gettare l'ancora. Il sole era tramontato da non più di un'ora quando hanno attaccato... quei maledetti naga!$B$BNon so bene cosa cercassero, ma è chiaro che non l'hanno trovato — sono già tornati una volta. Un paio dei miei esploratori sono di guardia all'ingresso della valle, per avvertirci in tempo quando arriverà il prossimo attacco.$B$BMi dispiace che tu sia $Garrivato:arrivata; proprio adesso, $N, ma non dipende da me.$B$BSei $Gpronto:pronta; per la battaglia della tua vita?",
  obj = "Difendi Captain Vanessa Beltis, il suo equipaggio e i passeggeri della Horizon Scout dall'attacco dei naga. Captain Vanessa Beltis deve sopravvivere.",
  progress = "Sarà una battaglia dura...",
  reward = "Ce l'hai fatta! Grazie! È stata di sicuro una delle battaglie più brutali a cui abbia mai preso parte. Non so come ringraziarti.$B$BVorrei solo che più membri del mio equipaggio fossero sopravvissuti a questa prova.$B$BTi chiederei di parlare con i passeggeri sopravvissuti della Horizon Scout. Alcuni di loro avevano degli affari da sbrigare in zona, e potrebbero avere una richiesta o due per te, se te la senti. Ancora grazie per tutto l'aiuto.",
}
T[3385] = {
  title = "L'Undermarket",
  desc = "Si fanno chiamare Undermarket: commercianti spietati che al giusto prezzo vendono, trasportano, scambiano e fanno praticamente qualsiasi cosa.$B$BE c'è di peggio, $N. Hanno messo su una base operativa qui nella Searing Gorge. A dirigere le operazioni è il Maestro del Commercio Kovic, che ha stretti legami con i nani Dark Iron della regione.$B$BDobbiamo colpire duro e mandare un messaggio ai loro capi. Uccidi il Maestro del Commercio Kovic e il suo tirapiedi Clunk. A lavoro finito, riportami la sua sacca da commerciante.$B$BAl Calderone!",
  obj = "Uccidi Trade Master Kovic e il suo tirapiedi Clunk. Recupera la Trader's Satchel dal suo cadavere e riportala a Nilith.",
  progress = "Il Maestro del Commercio è ancora vivo?",
  reward = "Hai inferto un colpo decisivo all'Undermarket. I suoi capi ci penseranno due volte prima di mandare altri scagnozzi nella gola.$B$BAh, e nella sacca del commerciante non ho trovato niente di utile. Puoi tenerti tutto quello che ci trovi dentro.",
}
T[3402] = {
  title = "L'Undermarket",
  desc = "Voglio che sia tu a portare di persona a Vizzklick, a Gadgetzan, la notizia della sconfitta di Kovic. Sarà così felice di sapere che Kovic è morto che di sicuro ti darà una gran bella ricompensa.",
  obj = "Parla con Vizzklick a Gadgetzan.",
  reward = "Kovic ucciso??! Questo è un giorno glorioso, $N! Per anni quella canaglia ha portato avanti loschi traffici sottobanco, stracciando i prezzi ai danni dei commercianti onesti e laboriosi di tutto il mondo.$B$BPer quest'impresa meriti una bella ricompensa! E una bella ricompensa avrai!",
}
T[3421] = {
  title = "Viaggio di Ritorno",
  reward = "Ora ti riporto all'accampamento di Sanath.$B$BNon badare alle sue cattive maniere — è sgarbato con tutti tranne che con il padrone. Forse un giorno imparerà la lezione.",
}
T[3441] = {
  title = "Castigo Divino",
  desc = "Ascolta la mia storia, $Gavventuriero:avventuriera;.",
  obj = "Ascolta Kalaran Windblade che racconta la sua storia.",
  progress = "Lasciami finire, mo... $R.",
  reward = "Hai sentito abbastanza? Sei $Gpronto:pronta; ad agire?",
}
T[3442] = {
  title = "La Fiamma Perfetta",
  desc = "Hai preso la decisione giusta, $N.$B$BDobbiamo colpire dove faremo più danni: le quattro torri di guardia.$B$BCon le quattro torri in fiamme, potremo lanciare un'offensiva prima che abbiano il tempo di reagire.$B$BPer dare fuoco alle torri ti servirà lo strumento adatto. E per fabbricarlo servono dei materiali.$B$BPortami quattro cuori di fiamma e quattro oli di golem e creerò la torcia della fiamma perfetta.$B$BI golem e gli elementali di queste terre dovrebbero essere il tuo primo bersaglio.",
  obj = "Raccogli 4 Hearts of Flame e 4 globi di Golem Oil e riporta tutto a Kalaran Windblade.",
  progress = "Hai raccolto i materiali?",
  reward = "Ben fatto, $N. Siamo quasi pronti.",
}
T[3443] = {
  title = "Forgiare l'Asta",
  desc = "Per reggere la fiamma perfetta ci serviranno un'asta e un involucro. Per prima cosa devi trovare un'asta adatta.$B$BI sorveglianti e gli schiavisti Dark Iron del calderone usano armi di torio incantato, una lega estremamente resistente. Se mi porti otto pugnali placcati di torio, posso scomporre la lega e riforgiarla in un'asta.",
  obj = "Porta 8 Thorium Plated Daggers a Kalaran Windblade.",
  progress = "Otto, $N. Me ne servono otto!",
  reward = "Sei $Gun lavoratore:una lavoratrice; eccezionale, $N. Hai mai pensato di cambiare mestiere? Magari detective? $GRaccoglitore:Raccoglitrice; di cianfrusaglie? Oh, ci sono, uno di quegli sciocchi gnomi che strisciano sulle spiagge di Azeroth con i loro aggeggi cercametalli, a caccia di tesori perduti. Sì, sarebbe il posto ideale per te.",
}
T[3444] = {
  title = "Il Cerchio Pietroso",
  desc = "Una volta sono entrato nelle sale sinistre del Sunken Temple. Il male di quel luogo penetra in chiunque vi entri; sono riuscito a stento a trovare l'uscita, arrancando nella melma che ormai ricopre i pavimenti. Ricordo soltanto di aver attraversato barcollando una grande sala circolare, piena di statue di serpenti...$B$BDi recente ho scoperto una pietra rotonda su cui sembrava impresso lo stesso simbolo del serpente. L'ho fatta imballare e spedire alla mia officina di Ratchet. Recuperala, e forse potrò dirti di più.",
  obj = "Recupera lo Stone Circle dall'officina di Marvon Rivetseeker a Ratchet.",
  progress = "Ratchet non è lontana da qui, $N. Il viaggio non dovrebbe richiedere molto tempo.",
  reward = "Sì... È questa la pietra.$B$BOra mi sta tornando in mente tutto, $N...",
}
T[3445] = {
  title = "Il Sunken Temple",
  desc = "Ho sentito parlare di un luogo che giace nelle profondità della terra — confinato laggiù da poteri più grandi di qualunque altro io abbia mai visto.$B$BSe vuoi saperne di più su questo luogo; il Sunken Temple, cerca un goblin di nome Marvon Rivetseeker. Come Troyas e me, ha studiato molti luoghi antichi del mondo. Le ultime notizie dicono che ha lasciato la sua casa a Ratchet per studiare le rovine troll di Tanaris.$B$BBuona fortuna con la ricerca; è da un po' che nessuno ha sue notizie.",
  obj = "Trova Marvon Rivetseeker a Tanaris.",
  reward = "Sì, il Sunken Temple, posso dire di averlo visto con i miei occhi. Forse ti piacerebbe saperne di più?$B$BMi sembri un tipo avventuroso — so cose che potrebbero incuriosirti...",
}
T[3446] = {
  title = "Nelle Profondità",
  desc = "Dentro il tempio ho trovato una sala circolare con sei balconate, ognuna con una statua di serpente sul bordo. Incuriosito, ne ho spinta una per vedere cosa sarebbe successo, ed era una trappola! Per poco l'esplosione non mi ha fatto precipitare verso morte certa. Steso lì sul cornicione, ho guardato giù e ho notato che in fondo alla sala c'era un'altra statua; una specie di altare... Hakkar, mi pare che si chiamasse.$B$BCredo che il segreto sia quell'altare — devi portare questo gettone all'altare nel Sunken Temple.",
  obj = "Trova l'Altar of Hakkar nel Sunken Temple, nella Swamp of Sorrows.",
  progress = "Esaminando la statua, noti su un lato un incavo, grande giusto quanto il gettone che ti ha dato Marvon...",
  reward = "Spingi il cerchio di pietra nell'apertura, e lo senti bloccarsi al suo posto.$B$BOra che la pietra è in posizione, puoi proseguire... ma cosa dovresti fare adesso?$B$BForse dovresti esaminare meglio questo altare...",
}
T[3447] = {
  title = "Il Segreto del Cerchio",
  desc = "I miei ricordi sono confusi, ma ti dirò quello che posso. Il cerchio di statue nel Sunken Temple è pericoloso, ma credo che custodisca il segreto per arrivare a un tesoro ancora più grande.$B$BDall'altare principale sono riuscito ad attivare una serie di luci. Credo che, se riesci a scoprire cosa significano queste luci, potresti svelare i segreti che si nascondono in quella sala, quali che siano.$B$BPerò ti avverto, $N. Nel tempio si annida un grande male. È probabile che qualunque cosa di valore sia sorvegliata con accanimento...",
  obj = "Entra nel Sunken Temple e scopri il segreto nascosto nel cerchio di statue.",
  reward = "L'occhio dell'idolo brilla vivido anche nella penombra del tempio. È trasparente, e lascia intravedere qualcosa che luccica dietro. Lo fai scorrere di lato, infili la mano e afferri ciò che si trova dentro la statua.$B$BIl tesoro degli Atal'ai ora è tuo.",
}
T[3448] = {
  title = "Passare il Fardello",
  desc = "Di recente mi hanno affidato il compito di indagare su Azshara — una regione un tempo bellissima, che gli elfi chiamavano casa. Parlo di quando praticavano ancora la magia. Oggi è un posto più pericoloso che bello, ma questo non ci impedisce di frugare in ogni angolo in cerca di risposte sul nostro passato.$B$BUn mio compagno di nome Tymor si è offerto di aiutarmi a studiare la zona, visto che queste cose lo interessano in modo particolare.$B$BHa un posticino a destra della Sala dei Misteri, qui in città.",
  obj = "Parla con Tymor a Ironforge.",
  reward = "Ah, ti manda Karnik, eh? Mi aspettavo di avere presto sue notizie. Ho scoperto cose davvero meravigliose su Azshara.. So che gli elfi della notte hanno una vita incredibilmente lunga, ma a volte tutti dimenticano alcuni degli eventi più... spiacevoli della propria vita. Non è una critica, solo un'osservazione.$B$BMolto tempo fa esistevano città create dagli elfi, piene di conoscenze sulla magia e su altre arti perdute. Dato che studio queste cose, ho cominciato le mie ricerche. Quello che ho trovato è stato davvero entusiasmante.",
}
T[3449] = {
  title = "Rune Arcane",
  desc = "Un tempo alcuni elfi veneravano la magia quanto Elune stessa. Alcuni dei loro maghi più potenti crearono rune e tavolette che riportavano le regole dell'arcano e riflessioni sulle loro scoperte. Le lasciavano nei luoghi pubblici, perché tutti potessero meditarci sopra.$B$BMi piacerebbe molto avere i ricalchi di queste rune dalle Rovine di Eldarath. Ho un corredo con cui potrai fare i ricalchi, ma trovarle toccherà a te. Fa' attenzione, però, perché la Lega degli Esploratori non è la sola a interessarsi a Eldarath.",
  obj = "Con il Drawing Kit, fai i ricalchi della Rune of Beth'Amara, della Rune of Jin'yael, della Rune of Markri e della Rune of Sael'hai, prima di raggiungere la piccola isola al largo della penisola meridionale di Azshara e segnalare a Pilot Xiggs Fuselighter di venire a prenderli.",
  progress = "Bene, bene, bene, mi fa piacere vedere che ce l'hai fatta ad arrivare fin qui, $N. Hai preso i ricalchi per Tymor?$B$BPer quanto questo posto sia pericoloso, lungo la costa non c'è stato granché movimento. Sarà perché i naga nuotano sott'acqua, ma non è un problema mio... io pattuglio i cieli.",
  reward = "Che bello vederti $Gsano e salvo:sana e salva;, $N. Spero che non sia stata troppo dura per te.$B$BLi porto subito a Tymor. Sarà felicissimo di dare un'occhiata a questa roba.$B$BIl lanciarazzi buttalo pure... tanto probabilmente non ti servirà più a niente, e io ne ho già uno nuovo.",
}
T[3450] = {
  title = "Un Ritiro Facile",
  desc = "Voglio che i ricalchi vengano consegnati alla mia torre, ma non c'è bisogno che tu faccia tutta quella strada. Li farò semplicemente portare via da Azshara per via aerea.$B$BXiggs Fuselighter mi deve un favore o due e presto sarà da quelle parti — ha preso l'incarico di pattugliare la costa. Parla con lui prima di partire. Può darti un lanciarazzi con cui fargli un segnale. Quando avrai i ricalchi, ti basterà andare dove ti dirà lui e consegnarglieli, così potrà portarli alla mia torre senza rischi. Dovrebbe essere nell'hangar del Quartiere Militare.",
  obj = "Parla con Xiggs Fuselighter a Ironforge.",
  reward = "Cosa posso fare per te, $N? Ho un po' da fare al momento, sto preparando il mio velivolo per un lungo viaggio. Sono passato solo a trovare qualcuno dei piloti dei carri armati — mi servono delle criniere dei wendigo per foderare la cabina, e di solito loro ne hanno in più.$B$BSe fai in fretta posso concederti un minuto... uno dei ragazzi è appena partito per lo Scalo di Steelgrill, a vedere se i piloti laggiù hanno qualche criniera in più per me.",
}
T[3451] = {
  title = "Segnale per il Ritiro",
  desc = "Ah, quindi ti manda Tymor, eh? Sì, gli devo un favore o due. Come dici? Ma guarda quel diavoletto. Sì, per questo posso dargli una mano. Quindi ti servono un lanciarazzi e un posto... niente di difficile.$B$BAl largo della penisola meridionale di Azshara c'è una piccola isola su cui abbiamo fatto una piazzola d'atterraggio. Prendi questo lanciarazzi e usalo lì. Vedrò il tuo segnale e passerò a ritirare questo... quello che vuole lui, qualunque cosa sia.",
  obj = "Parla con Xiggs Fuselighter a Ironforge e fatti dare da lui uno Standard Issue Flare Gun.",
  reward = "Ecco il mio lanciarazzi d'ordinanza, e dopo aver sparato abbi pazienza — questi affari hanno solo un paio di cariche, e potrei metterci un minuto a raggiungerti, a seconda di quanto sono al largo. Dopo aver sparato il razzo, guarda verso il mare.",
}
T[3452] = {
  title = "L'Involucro della Fiamma",
  desc = "Ci serve un ultimo pezzo per comporre la torcia.$B$BSulle montagne a nordovest troverai un grande accampamento del Martello del Crepuscolo. Si dice che portino con sé simboli e idoli che rendono omaggio al loro dio. Questi simboli e idoli potrebbero avere un incantamento sufficiente a formare un involucro magico. Portami un solo simbolo di Ragnaros e proverò a estrarne la magia per creare l'involucro.",
  obj = "Trova un Symbol of Ragnaros e portalo a Kalaran Windblade.",
  progress = "Senza una fonte adatta di energia arcana, la torcia del castigo non può essere completata.",
  reward = "Il simbolo irradia una magia immonda; è perfetto per il nostro scopo.",
}
T[3453] = {
  title = "La Torcia del Castigo",
  desc = "Dammi un momento per unire i pezzi e applicare gli incantamenti necessari.",
  obj = "Aspetta che Kalaran Windblade completi la Torch of Retribution.",
  progress = "Non interrompere la canalizzazione.",
  reward = "C'è un ultimo compito che devi portare a termine.",
}
T[3454] = {
  title = "La Torcia del Castigo",
  desc = "Ora la torcia va legata $Gal suo proprietario:alla sua proprietaria;. Raccogli la torcia, $N.",
  obj = "Prendi la Torch of Retribution.",
  reward = "Afferri la torcia con entrambe le mani; ondate di odio e di rabbia pulsano in tutto il tuo essere.",
}
T[3461] = {
  title = "Torna da Tymor",
  desc = "Tymor non mi ha dato niente con cui pagarti, quindi ti consiglio di parlarne con lui quando torni a Ironforge. Sono sicuro che sarà ancora a casa sua, nel Quartiere Mystic. Va' a bussare e fatti pagare per bene. Questo posto non è mica una passeggiata... poco ma sicuro.$B$BComunque grazie ancora per avergli dato una mano, e buona fortuna.$B$BAh, e il corredo da disegno non mi serve. Perché non lo riporti a Tymor quando vai da lui?",
  obj = "Riporta a Tymor il suo Drawing Kit, a Ironforge.",
  progress = "Sei $Gtornato:tornata;! Ottimo. Hai anche il mio corredo da disegno?",
  reward = "Magnifico! Mi fa davvero piacere saperlo.$B$BNon vedo l'ora di andare alla mia torre a studiare quei ricalchi. Ti invidio tantissimo... andare in un posto come Azshara. È il sogno di chiunque studi l'arcano, immagino.$B$BBe', non abbiamo mai parlato di ricompense di alcun tipo, dato che lavoravi solo per la Lega degli Esploratori, ma qualcosa te lo meriti.",
}
T[3462] = {
  title = "Scudiero Maltrake",
  desc = "Parla con il mio emissario, lo Scudiero Maltrake. Sarà lui a darti altre istruzioni sull'uso della Torcia del Castigo.",
  obj = "Parla con Squire Maltrake.",
  reward = "Sei $Gpronto:pronta; a sferrare il tuo attacco?",
}
T[3463] = {
  title = "Incendiale!",
  desc = "Ascolta bene, $N. Le quattro torri non potranno mai essere distrutte, ma con la torcia del castigo puoi incendiarle per un tempo lunghissimo: un fuoco che nessun elemento e nessuna forza può domare.$B$BFinché sono in fiamme, nessuna guardia e nessuna unità di sentinelle può occupare i posti di vedetta, e così la loro prima linea di difesa è annullata.$B$BDevi entrare in ogni torre e usare la Torcia del Castigo all'interno delle fortificazioni. Guardati dalle unità scelte di sentinelle dei Dark Irons, $N.",
  obj = "Dai fuoco alle Torri di Guardia Nord, Sud, Est e Ovest usando la Torch of Retribution all'interno di ciascun edificio.",
  progress = "Ti sei $Gperso:persa;, $N?",
  reward = "È glorioso! Non è glorioso, mio signore?",
}
T[3481] = {
  title = "Monili...",
  desc = "Il forziere sembra chiuso a chiave.",
  obj = "Apri il forziere.",
  reward = "Il forziere si apre appena lo tocchi. Quanto formaggio potrà mai esserci qui dentro? C'è un solo modo per scoprirlo.",
}
T[3483] = {
  title = "Segnale per il Ritiro",
  reward = "Ah, un altro lanciarazzi, eh? Questo posso farlo.$B$BE non dimenticare, punta meridionale di Azshara. È un'isoletta piccola piccola trasformata in piazzola d'atterraggio. Se sei nel posto giusto, non puoi sbagliare.",
}
T[3501] = {
  title = "Tutto Conta In Grandi Quantità",
  desc = "Anche se forse non troverai mai una sfera perfetta di draenethyst, esplorando queste terre ti imbatterai di sicuro in vari frammenti imperfetti di draenethyst.$B$BÈ difficile che Kum'isha possa usare i frammenti difettosi per tornare a casa, ma quei pezzi possono servire ai draenei per altri scopi utili.$B$BPortami ogni frammento difettoso di draenethyst che troverai e ti ricompenserò.",
  obj = "Porta a Kum'isha the Collector gli Imperfect Draenethyst Fragments e riceverai una ricompensa per ognuno che consegni.",
  progress = "Hai avuto fortuna nelle tue esplorazioni?",
  reward = "Mi disgusti davvero, $R. $GUn uomo adulto:Una donna adulta; che sbava per un mucchio di ciarpame? Penoso! Prendi la tua ricompensa e sparisci dalla mia vista.",
}
T[3502] = {
  title = "Quel che per un Draenei È Ciarpame...",
  desc = "Beh, dopo quello sfoggio di avidità vorace, ho la nausea.$B$BComunque sia, non mi soffermerò troppo sulla tua dipendenza dai beni materiali.$B$BPer ogni frammento di draenethyst imperfetto che mi consegni, ti ricompenserò con altro ciarpame. Il mio mucchio di ciarpame si riduce mentre il tuo cresce. Su Draenor la chiamiamo una situazione 'vantaggiosa per tutti'.",
  obj = "Porta a Kum'isha the Collector degli Imperfect Draenethyst Fragments. Qualsiasi tipo di mostro delle Blasted Lands potrebbe avere con sé un frammento.",
  progress = "Allora? Il draenethyst? Ricordi?$B$B<Kum'isha stringe il pugno e ti bussa sulla testa.>$B$BC'è nessuno in casa?",
  reward = "Mi disgusti davvero, $R. $GUn uomo adulto:Una donna adulta; che sbava per un mucchio di ciarpame? Penoso! Prendi la tua ricompensa e sparisci dalla mia vista.$B$BTi suona familiare? Dovrebbe, perché lo dico mille volte al giorno.$B$BOh, quanto detesto questo mondo.",
}
T[3503] = {
  title = "Incontro con il Padrone",
  reward = "C'è stato un tempo in cui potevo chiedere quello che volevo a chi cercava il mio padrone. Ma ora ti basta chiedere e ti mando da lui.$B$BLa cosa mi irrita, ma non discuto i suoi ordini. Posso solo divertirmi a prendere in giro i vestiti ridicoli che porti o quell'espressione patetica che hai in faccia. Anche questo mi annoia...$B$BPerfino questo sproloquio mi annoia! Vuoi vedere il mio padrone o no?",
}
T[3504] = {
  title = "Tradito",
  desc = "Donna traditrice e ladra! Così la chiamo — e non sarà mai nient'altro!$B$BForse ho commesso un grave errore, $N. Mi sono fidato di un elfo del sangue. Peggio ancora, mi sono fidato di una donna!$B$BSosteneva che ad Azshara ci fossero grandi ricchezze... oggetti potenti. Bastava che mandassi con lei dei guerrieri a proteggerla e sarei stato ricompensato. Be', guarda un po' chi è lo stupido — li ha ammazzati tutti.$B$BVoglio vendetta, $N, ma non posso permettermi di mandare nessun altro. Trova Ag'tor a Valormok, a nord dell'Accampamento di Haldarr. Ti dirà di più lui.",
  obj = "Consegna la Sealed Letter to Ag'tor ad Ag'tor Bloodfist, ad Azshara.",
  progress = "Ah, Belgrom si è fatto furbo e alla fine ha mandato ad aiutarci qualcuno che non è dei suoi, eh?$B$BUn tempo questo campo contava una dozzina di guerrieri, $N, ma ora sono tutti morti. Quella maga, Rimtori, li ha uccisi tutti. Si è rigirata Belgrom come ha voluto... lo ha perfino sedotto. Non sono affari miei, ma detto fra noi, è una gran tentatrice. Probabilmente è per questo che sono ancora qui ad aiutare Belgrom — probabilmente avrei fatto lo stesso anch'io.",
  reward = "Abbiamo scagliato contro di lei e i suoi operai tutto quello che avevamo, ma in battaglia sono forti. Nessuno si è preso la briga di tornare. Immagino che qualcuno sia morto, ma di sicuro altri sono semplicemente scappati... codardi.$B$BMa ora che sono arrivati i rinforzi, forse possiamo ancora fare qualcosa. Forse possiamo ancora punirla per aver mentito a Belgrom e averlo tradito.$B$BChe ne dici, ci stai?",
}
T[3505] = {
  title = "Tradito",
  desc = "Lo immaginavo.$B$BCominciamo la nostra crociata contro i suoi operai lungo le scogliere meridionali della penisola settentrionale di Azshara. Uccidili con furia sanguinaria — fagli capire che hanno tradito gli alleati sbagliati.$B$BDi lei non preoccuparti, per ora — passa quasi tutto il tempo a perlustrare Azshara con le sue guardie del corpo. Dopo che avrai ucciso i suoi operai, sarebbe prudente trovare il suo accampamento personale. Sarebbe saggio andare a vedere dove possiamo attaccarla. Forse lì c'è qualcosa che possiamo usare per provocarla.",
  obj = "Uccidi 10 Blood Elf Reclaimers e 10 Blood Elf Surveyors prima di cercare l'accampamento di Magus Rimtori. Quando l'avrai trovato, cerca qualcosa che potrebbe essere importante per lei e che si possa usare per trascinarla in uno scontro.",
  progress = "Il titolo del libro è impresso in foglia d'oro sulla copertina di pelle nera — Tomo dell'Evocazione Kaldorei. Sfogliandolo, vedi che il libro è molto antico ma in condizioni eccellenti.$B$BSupponi che il testo sia in qualche lingua antica... forse Kaldorei?$B$BL'istinto ti dice che dovresti tornare qui quando avrai finito di far scontare agli elfi del sangue il loro tradimento.",
  reward = "Cominci a scorrere alcune pagine finché arrivi a una pagina segnata da una sottile striscia nera di stoffa di seta.$B$BMentre cerchi di decifrare la scrittura, vedi un diagramma in fondo a una delle pagine. Dai una rapida occhiata alla scena che hai davanti e ti rendi conto che i cristalli, il cerchio e perfino alcuni degli altri componenti a terra sono disposti secondo uno schema simile a quello del diagramma.",
}
T[3506] = {
  title = "Tradito",
  desc = "Dopo qualche altro istante di riflessione ti vengono in mente alcune idee, e una ti fa sorridere: forse distruggere i cristalli farebbe arrabbiare l'elfa del sangue responsabile del massacro di tanti orchi e del tradimento di Belgrom?$B$BContinui a decifrare altre parti della scrittura e delle figure e capisci che uno dei cristalli è legato a chi ha creato il cerchio — gli altri sono legati a qualcosa di molto più sinistro.$B$BChiudi il libro e cominci a decidere quale cristallo distruggere.",
  obj = "Distruggi il cristallo di focalizzazione arcana legato a Magus Rimtori, poi uccidila. Dopodiché porta la Head of Magus Rimtori ad Ag'tor Bloodfist, ad Azshara.",
  progress = "Come procede il massacro dei traditori elfi del sangue, $N? Hai fatto progressi?$B$BSpero che sia tu $Gquello:quella; abbastanza forte da mettere in ginocchio quella cagna! Per tutto ciò che ha fatto non merita altro che una morte dolorosa!",
  reward = "RAR!! Incredibile!$B$BCe l'hai fatta! Belgrom sarà contento! Finalmente gli spiriti di decine dei nostri guerrieri possono trovare pace. Grazie, $N.",
}
T[3507] = {
  title = "Tradito",
  desc = "Torna da Belgrom, a Orgrimmar. Quella testa vorrà vederla con i propri occhi! Noi torneremo là a breve.$B$BAh, questa è davvero una bella giornata. Grazie per il tuo aiuto, $N.",
  obj = "Parla con Belgrom Rockmaul, a Orgrimmar.",
  progress = "Mi ricordo di te, $C. Ti avevo chiesto di andare ad Azshara a distruggere quella sgualdrina che mi ha tradito! Sembrano passate molte lune. Non dirmi che sono morti anche Ag'tor e gli altri!",
  reward = "AHAH! Guardati adesso, donna patetica! Sputo sui tuoi resti!$B$BGrazie, $N. Grazie dal profondo del cuore! Questo è davvero un gran giorno!$B$BTi darei un regno, se fosse in mio potere! Ma forse ti accontenterai di questo.$B$B<Belgrom abbassa lo sguardo sulla testa della maga che lo aveva tradito.>$B$BAhah! Stupida elfa del sangue, guardati adesso... in un sacco di iuta e senza il corpo! Non avresti mai dovuto tradire Belgrom!",
}
T[3508] = {
  title = "Spezzare la Protezione",
  desc = "Sei $Gtemerario:temeraria;, $N. È una qualità ammirevole della tua specie — gettarsi alla cieca in battaglia quando le speranze di farcela sono poche o nulle. Ti aiuterò, non fosse altro che per veder cadere almeno uno dei servitori di Razelikh.$B$BPer spezzare la protezione posta sui subordinati di Razelikh ci vorrà tempo, e bisognerà procurarsi dei manufatti rari.$B$BResta $Gfermo:ferma;, devo prima compiere il rituale dell'illuminazione. Le informazioni che raccoglierò mi aiuteranno a forgiare armi di grande potere.",
  obj = "Aspetta che Loramus Thalipedes completi l'incantesimo dell'illuminazione.",
  reward = "Bisogna trovare il nome della bestia.",
}
T[3509] = {
  title = "Il Nome della Bestia",
  desc = "C'è un solo modo per nuocere al signore dei demoni e ai suoi servitori. Bisogna forgiare un'arma di potere che porti il suo vero nome.$B$BQuando un'arma simile viene forgiata, il demone e tutti quelli ai suoi ordini diventano vulnerabili.$B$BAd Azshara dimora una divinità minore: Lord Arkkoroc. Devi andare a cercarlo, ma sta' in guardia: se ti scoprono, i suoi servitori non si fermeranno davanti a niente pur di distruggerti.$B$BDi sicuro, per un'informazione simile dovrai pagare un prezzo.",
  obj = "Parla con Lord Arkkoroc ad Azshara. Per trovare il Tempio di Arkkoran, comincia a cercare in riva all'acqua.",
  reward = "Un signore dei demoni?$B$B<Lord Arkkoroc ride.>$B$BForse l'unico può aiutarti con questa informazione; ma prima sei tu che devi aiutare l'unico.",
}
T[3510] = {
  title = "Il Nome della Bestia",
  desc = "Uccide i miei figli, mortale. Lei, che si proclama sovrana di questi oceani. Una falsa divinità, niente di più. Schiacciala e riportami tutte le sue teste.$B$BIn cambio ti sarà dato il nome che cerchi, e un'altra cosa di pari importanza.$B$BSi aggira intorno alla covata... Hetaera, la chiamano.$B$B<Lord Arkkoroc indica verso sud-ovest.>$B$BVa'!",
  obj = "Uccidi Hetaera e riporta Hetaera's Bloodied Head, Hetaera's Beaten Head e Hetaera's Bruised Head a Lord Arkkoroc.",
  progress = "<Lord Arkkoroc si china per esaminarti.>$B$BDove sono?",
  reward = "Finalmente qualcuno degno della saggezza di Arkkoroc!",
}
T[3511] = {
  title = "Il Nome della Bestia",
  desc = "Come promesso, ti rivelerò il nome del signore dei demoni, Razelikh il Profanatore. Prima, però, devo preparare una cosa della massima importanza per il tuo viaggio.$B$BL'arma che vuoi creare richiede un liquido di tempra. Dammi un momento per cavare il sangue da queste teste.$B$B<Lord Arkkoroc stringe le teste fra i pugni giganteschi, dissanguandole.>$B$BRiporta il liquido di tempra a Loramus, insieme al nome della bestia: Rakh'likh.",
  obj = "Riporta il liquido di tempra a Loramus Thalipedes.",
  progress = "Sei $Gtornato:tornata;! Sbalorditivo, $R. Hai scoperto il vero nome?",
  reward = "Il liquido di tempra darà il vetriolo necessario per forgiare le armi. Alla loro creazione manca ormai un solo passo.",
}
T[3512] = {
  title = "Con le Parole di Eranikus",
  desc = "$N, il nostro primo passo sarà trovare un modo per parlare con Eranikus attraverso la gemma. Ora si trova in uno stato precario tra il sonno e la morte, avvolto in una trama di incubi. Anche se l'essenza che mi hai dato è gravemente corrotta, c'è la possibilità di raggiungerlo.$B$BViaggia lontano, fino alle terre gelide di Winterspring orientale, e cerca uno dei nostri alleati mortali, Umbranse the Spiritspeaker. È un medium umano che parla per i morti. Anche se Eranikus non è davvero morto, potrebbe comunque esserci d'aiuto.",
  obj = "Va' nella parte orientale di Winterspring e parla con Umbranse the Spiritspeaker.",
  reward = "Itharius ha fatto bene a mandarti da me. Anche se non è morto come tu intendi la morte, presto Eranikus ci darà consiglio con le sue stesse parole. Per ora, però, non posso aiutarti direttamente... almeno non ancora.$B$BMetterò al tuo servizio la mia abilità nel parlare con i morti, ma prima mi serve l'aiuto di qualcuno che, a differenza di me, non sia limitato dalle fragilità della vecchiaia. Il mio strumento di divinazione più potente mi è stato portato via contro la mia volontà, e se non lo riavrò non potremo aiutare Eranikus.",
  en_title = "In Eranikus' Own Words",
  en_obj = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",
}
T[3513] = {
  title = "La Pergamena Runica",
  desc = "La pergamena, dall'aria ufficiale, è avvolta stretta in un nastro argenteo. Sei $Gsicuro:sicura; che a qualcuno interesserebbe vederla, ma a chi?$B$BC'è un avamposto vicino al confine di Ashenvale, a nord, e se quello che c'è scritto su questa pergamena riguarda gli elfi della notte, è quello il posto dove portarla.",
  obj = "Porta il Runed Scroll alla torre di guardia settentrionale delle Barrens.",
  progress = "Che hai lì?",
  reward = "Bene, bene... Dove l'hai trovata?",
  en_title = "The Runed Scroll",
  en_obj = "Take the Runed Scroll to the northern guard tower in the Barrens.",
}
T[3514] = {
  title = "Presenza dell'Orda",
  desc = "Questa pergamena viene da quella driade intrigante di Rynthariel, Custode delle Chiavi del Covo dell'Artiglio sul Picco di Stonetalon.$B$BNon avrà più contatti con il messaggero da cui l'hai presa, eh eh, ma qui dobbiamo tenere la posizione. L'Orda non tollererà le sue staffette da queste parti.$B$B$N, va' al Covo dell'Artiglio. Uccidi Rynthariel, e poi pianta un simbolo che tutti possano vedere. Prendi questa bandiera dell'Orda, $N. Piantala nel Covo dell'Artiglio, così non saranno più tanto avventati da mandare un altro messaggero nel nostro territorio.",
  obj = "Uccidi il capo di Talon Den, Rynthariel the Keymaster.",
  progress = "Non possiamo permettere all'Alleanza di stare sulla nostra terra, $N. Fallo sapere.",
  reward = "Sei $Guno tosto:una tosta;! Liberare il Covo da Rynthariel è un passo importante, $N. Ci metteranno un po' a riorganizzarsi, e così nelle Barrens ci saranno meno corrieri dell'Alleanza. Ci penseranno due volte prima di mandarne un altro da queste parti.$B$BGrazie.",
  en_title = "Horde Presence",
  en_obj = "Kill the leader of the Talon Den, Rynthariel the Keymaster.",
}
T[3517] = {
  title = "Rubare il Sapere",
  desc = "Lo ammetto, $N, ho tratto il massimo dalla mia situazione ad Azshara. La punizione di Belgrom ha avuto i suoi vantaggi.$B$BPrima di partire ho fatto qualche ricerca, e ti stupiresti di quanti oggetti di valore ci sono in giro.$B$BTi dirò di più sui miei affari, e ti darò perfino una fetta dei guadagni, se mi aiuti a raccoglierne qualcuno.$B$BMi servono delle tavolette sparse per le Rovine di Eldarath, a est. Tutte e quattro portano il nome di maghi degli Alti Nobili. Prendimele e ne riparliamo.",
  obj = "Trova la Tablet of Beth'Amara, la Tablet of Jin'yael, la Tablet of Markri e la Tablet of Sael'hai, poi torna da Jediga ad Azshara.",
  progress = "Le tavolette che ti faccio raccogliere dovrebbero fruttare qualche bel soldo, con le persone giuste. Ti dirò a chi vanno consegnate dopo che le avrai trovate. Ma non sono una stupida... avrai la tua parte quando avrò la prova che sono state consegnate.$B$BQuindi datti da fare — non abbiamo tutto il giorno. Potrei dover cercare qualcun altro che mi aiuti.",
  reward = "Perfetto, $N, e sono anche in buono stato. Dovrebbero farci avere un buon prezzo da tutti gli interessati.$B$BNon restiamo qui a ciondolare più del necessario. C'è da fare soldi.",
}
T[3518] = {
  title = "Consegna a Magatha",
  desc = "La prima tavoletta va a una tauren... una certa Magatha. È tra gli anziani di Thunder Bluff ed è fra i sostenitori dell'alleanza tra i tauren e i Reietti. Lei, più di chiunque altro tra gli anziani, pensa che i tauren e le loro usanze possano aiutare i Reietti a trovare la strada per tornare umani.$B$BPortale la Tavoletta di Beth'Amara. La tavoletta potrebbe essere l'anello che le manca per trovare il modo di aiutare i Reietti... o almeno così sostiene.",
  obj = "Porta la Tablet of Beth'Amara a Magatha a Thunder Bluff.",
  progress = "Sì, $N. Cosa posso fare per te? Ho molte faccende di cui occuparmi, perciò fai in fretta, per favore.",
  reward = "Ah, finalmente, la Tavoletta di Beth'Amara. Mi chiedevo se la mia collaborazione con Jediga fosse fallita o se la povera orchessa avesse trovato la morte ad Azshara. Sono lieta che ci sia riuscita.$B$BBeth'Amara era tra gli alchimisti più influenti degli Alti Nobili. Si diceva che quel mago, da solo, fosse arrivato a padroneggiare la trasmutazione dei metalli, tra le altre cose.",
}
T[3520] = {
  title = "Spiriti degli Stridenti",
  desc = "Cerco gli spiriti degli stridenti della vallata di Feralas. Sono i cugini di un dio antico, antichissimo, e i loro spiriti sono legati a lui.$B$BPrendi questa bacchetta di rovo e vai a Feralas. Trova e sconfiggi gli stridenti della vallata nel sud e nel centro di Feralas, poi agita il mio rovo sui loro cadaveri. Questo convincerà il loro spirito a rivelarsi. Tocca lo spirito e raccogline l'essenza.$B$BTorna da me con il mio rovo e con l'essenza raccolta, e ti dirò di più sul dio antico di cui ti ho parlato.",
  obj = "Cattura gli spiriti di 3 stridenti a Feralas, poi torna da Yeh'kinya a Steamwheedle Port.",
  progress = "Hai raccolto l'essenza degli spiriti degli stridenti, $N?",
  reward = "Hai fatto un buon lavoro, $N. Forse ora è il momento di rivelare qualcosa in più...$B$BFra i troll c'è un'antica profezia, secondo cui il dio morto Hakkar, il Soulflayer, un giorno tornerà su questa terra. Alcuni dicono che la venuta di Hakkar porterà gioia e gloria ai troll, mentre altri credono che la sua resurrezione segni la fine di ogni cosa.$B$BIo non credo a questo mito, ma so che l'essenza di Hakkar racchiude un grande potere, e questo potere va tenuto lontano da chi ne abuserebbe...",
}
T[3523] = {
  title = "Il Flagello dei Downs",
  desc = "Straordinario! Mi chiamo Belnistrasz, e ti ringrazio per avermi salvato. Mi ero già dato per morto... o peggio, per finito in pasto a questi parassiti infestati dal Flagello. Sì — ho detto proprio Flagello; hanno stretto una specie di patto con i Quilboar di qui, e questo incubo ne è il risultato.$B$BAscolta... invece di fuggire e basta, voglio fare qualcosa di concreto, per il bene di tutti noi. Te la sentiresti di aiutarmi in questo? Probabilmente è pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.",
  obj = "Se accetti di aiutare Belnistrasz, parla di nuovo con lui e restituiscigli la Belnistrasz's Oathstone che ti ha dato.",
  progress = "La politica non fa per me; non mi importa se stai con l'Orda o con l'Alleanza. Mi interessa di più schiacciare le minacce dirette e terribili per tutte le razze... e qui dentro ne abbiamo una bella grossa.$B$BSe vuoi essere $Gun vero eroe:una vera eroina; per tutti, allora dammi la pietra del giuramento che ti ho dato, come segno del tuo impegno. Io... non sono di queste parti; per quelli come me, una pietra del giuramento è importante come vincolo di un accordo.",
  reward = "Fantastico, mi sembravi proprio il tipo eroico! Ci aspetta un lavoro difficile, $N, non ti mentirò. Se restiamo concentrati sul compito che abbiamo davanti, dovremmo riuscire a spuntarla.$B$BOra lascia che ti metta al corrente di quello che sta succedendo...",
  en_title = "Scourge of the Downs",
  en_obj = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",
}
T[3525] = {
  title = "Spegnere l'Idolo",
  desc = "Vicino all'ingresso c'è un idolo che fa da forno macabro per i Quilboar; quelle bestie... divorano letteralmente le persone che rapiscono nelle Barrens. Posso spegnere l'idolo e impedire che lo usino di nuovo, ma per farlo mi serve il tuo aiuto. Il mio piano: scortami fino all'idolo. Una volta arrivati, comincerò il rituale. Riuscirò a stento a comunicare con te, figurarsi a difendermi. Proteggimi mentre spengo l'idolo. Se mi abbattono, per noi è finita.$B$BSei con me?!",
  obj = "Scorta Belnistrasz fino all'idolo dei Quilboar, a Razorfen Downs.$B$BProteggi Belnistrasz mentre esegue il rituale per spegnere l'idolo.",
  reward = "L'improvvisa partenza di Belnistrasz ha lasciato dietro di sé un braciere ardente. Mentre fissi la fiamma, l'immagine di un grande drago rosso dalle ampie ali ti riempie la mente. La voce di Belnistrasz, più roca, ti parla direttamente.$B$B\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi, il massacro che queste bestie compivano appartiene al passato. La mia fiducia nei mortali come te si è rinnovata ancora una volta. Prendi questo come ricompensa degna di $Gun eroe:un'eroina;.\"",
  en_title = "Extinguishing the Idol",
  en_obj = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol.",
}
T[3526] = {
  title = "Ingegneria Goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Ovviamente, l'ingegneria goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con l'uso giudizioso di esplosivi ad alto potenziale e di attrezzature fantastiche!$B$B$N, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3527] = {
  title = "La Profezia di Mosh'aru",
  desc = "L'antica profezia di Mosh'aru parla di un modo per imprigionare l'essenza del dio Hakkar. Fu scritta su due tavolette e portata nella città troll di Zul'Farrak, a ovest di Gadgetzan.$B$BPortami le tavolette di Mosh'aru!$B$BLa prima tavoletta è in mano a Theka il Martire, un troll morto da tempo. Si dice che i suoi persecutori siano stati tramutati per maledizione in scarabei, e che ora zampettino intorno al suo santuario.$B$BLa seconda tavoletta è custodita dall'idromante Velratha, vicino alla vasca sacra di Gahz'rilla.$B$BQuando avrai le tavolette, portamele.",
  obj = "Porta la First Mosh'aru Tablet e la Second Mosh'aru Tablet a Yeh'kinya, a Tanaris.",
  progress = "Hai le tavolette della profezia di Mosh'aru, $N?$B$BQuando avrò le tavolette, le studierò e imparerò come imprigionare l'essenza di Hakkar!",
  reward = "Ah, molto bene. Posso fondere insieme queste antiche tavolette, e poi studiarne i segreti nascosti.$B$BIl mio debito con te cresce, $N. E crescerà ancora.",
  en_title = "The Prophecy of Mosh'aru",
  en_obj = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.",
}
T[3528] = {
  title = "Il Dio Hakkar",
  desc = "Ora è il momento di catturare l'essenza dell'avatar di Hakkar.$B$BPorta l'Uovo di Hakkar nel Santuario del Dio Caduto, nel Sunken Temple, ad Azeroth. Invoca il potere dell'uovo per ridestare il dio morto.$B$BTi manderà contro i suoi servitori. Sconfiggi i suoi bevitori di sangue e prendi il loro sangue Hakkari, poi usa quel sangue per spegnere le fiamme eterne che trattengono lo spirito di Hakkar. Quando tutte le fiamme si saranno spente, l'avatar di Hakkar entrerà nel nostro mondo.$B$BSconfiggilo, e riponi la sua essenza nell'uovo di Hakkar.",
  obj = "Porta il Filled Egg of Hakkar a Yeh'kinya a Tanaris.",
  progress = "Hai sconfitto l'avatar di Hakkar, $N? La sua essenza ha già infuso potere nell'uovo che ti ho dato?",
  reward = "L'essenza di Hakkar è stata raccolta! Già ora l'Uovo freme di vita! Possibile che i miti su Hakkar siano veri?$B$BNon dev'essere vero, perché allora temo ciò che Hakkar potrebbe fare se tornasse a nascere. Terrò quest'uovo al sicuro e farò in modo che non cada in mani malvagie.$B$BLe tue fatiche al mio fianco sono finite, $N. Hai toccato una leggenda, e un giorno le tue azioni potrebbero cambiare il volto del nostro mondo.",
}
T[3541] = {
  title = "Consegna a Jes'rimon",
  desc = "Ho un ricettatore a Orgrimmar. Sta nel Corso. È difficile da scovare se non sai dove cercare, ma se guardi in uno degli edifici più alti della zona lo troverai senza problemi.$B$BFammi un favore, però, non andare a gridare a tutto Kalimdor che sta lì e di cosa si occupa — sarebbe un male per tutti e due.$B$BPer la Tavoletta di Jin'yael ci darà un prezzo più che onesto. Non so bene perché, ma avresti dovuto vedere quanto era entusiasta quando ha saputo dove si trovava.",
  obj = "Porta la Tablet of Jin'yael a Jes'rimon a Orgrimmar.",
  progress = "Sì, che ti serve, mon? Oggi c'ho un sacco di cose da sbrigare, e tu nella mia agenda non ci stai. Scocciami, e vedrai che la cosa cambia.",
  reward = "Ahhh, Jediga manda il suo pacco fin da Azshara. Bene. Lo stavo aspettando.$B$BJediga, quella sì che è una gran donna... e pure letale. Che vuoi di più?$B$BMa guarda... la tavoletta è in perfette condizioni. Sei $Gun bravo messaggero:una brava messaggera;, $N.",
}
T[3542] = {
  title = "Consegna ad Andron Gant",
  desc = "Andron Gant è il mio prossimo contatto. Di solito se ne sta rintanato a Undercity... proprio accanto all'Apothecarium.$B$BHa avuto la lingua un po' più sciolta quando si è parlato di cosa voleva farci con la Tavoletta. A quanto pare alcuni maghi di Undercity vogliono studiare certi incantesimi arcani usati dagli alti nobili. Pensano che questa tavoletta li aiuterà. Markri era abile nell'evocare creature; specialmente elementali.$B$BPrendi la Tavoletta di Markri e torna da me per la tua parte della ricompensa.",
  obj = "Porta la Tablet of Markri ad Andron Gant a Undercity.",
  progress = "Be'... <hic>... ma che sorpresa, eh? $GUn avventurierororo:Un'avventurierarara;... <hic>!$B$BChe poss' fare per te... <hic>?",
  reward = "Tieni, prenditi qualche moneta... comprati... <hic>... un'armatura nuova o che so io....$B$BQuesta frutterà una bella moneta d'oro o due, con le... <hic> persone giuste.",
}
T[3561] = {
  title = "Consegna all'Arcimago Xylem",
  desc = "Quest'ultima tavoletta va a una persona molto pericolosa, $N. Dammi retta quando ti dico che di questa persona mi fido molto meno di chiunque altro ti abbia chiesto di incontrare.$B$BL'Arcimago Xylem ha una torre sulle colline che dominano Azshara. È umano, ma non si comporta come nessun umano che io abbia incontrato... o ucciso. Emana potere, e non oso chiedergli cosa intende fare con la tavoletta.$B$BÈ venuto lui da me, ma mi ha detto che la sua guardia del corpo, Sanath, mi avrebbe aiutata a raggiungere la torre quando fossi stata pronta a incontrarlo. Cerca Sanath a nord.",
  obj = "Porta la Tablet of Sael'hai ad Archmage Xylem ad Azshara.",
  progress = "In cosa posso aiutarti, $N?",
  reward = "Ah, la Tavoletta di Sael'hai... da quanto tempo desideravo studiarla.$B$BGrazie, $N. Puoi dire a Jediga che ha fatto un buon lavoro. Varrà senz'altro il compenso che ha chiesto.",
}
T[3562] = {
  title = "Il Pagamento di Magatha per Jediga",
  desc = "Porta questo biglietto a Jediga. Dille che il pagamento sarà qui ad aspettarla quando tornerà. E dille che sono soddisfatta del suo lavoro.$B$BVa' in fretta, $N. Di' alla tua padrona che l'aspetterò qui.",
  obj = "Consegna Magatha's Note a Jediga ad Azshara.",
  progress = "Allora, cos'ha detto Magatha? Quella vecchia megera... scommetto che non è stata proprio gentile.",
  reward = "Ah, bene. È stata molto più ragionevole di quanto mi aspettassi... almeno con te. Quasi mi aspettavo che ti facesse punire per l'insolenza di aver mandato qualcuno al posto mio. Deve volerla davvero, quella tavoletta. Interessante.$B$BUna cosa su cui riflettere un'altra volta.",
}
T[3563] = {
  title = "Il Pagamento di Jes'rimon per Jediga",
  desc = "Porta 'sta lettera a Jediga. Falle sapere che il nostro affare ha reso bene e che sono contento del suo lavoro.$B$BTu dille che torna a Orgrimmar alla svelta, e Jes'rimon ci pensa lui a trattarla come si deve.$B$BDille così, e magari in futuro mi servi ancora, $N.",
  obj = "Consegna Jes'rimon's Note a Jediga ad Azshara.",
  progress = "Hai già parlato con Jes'rimon?$B$BÈ un cinghiale tra i troll, ma le sue informazioni di solito sono esatte e i suoi lavori pagano bene.$B$BSe riesci a sopportare i suoi modi, dai suoi affari puoi ricavare dei bei soldi.",
  reward = "A giudicare dal suo biglietto, vedo che è rimasto più che soddisfatto.... un po' troppo soddisfatto.$B$BMagari un giorno troverò il tempo di fargli capire per bene quanto apprezzo anche le sue avances. Be', almeno c'è un motivo per passare volentieri altro tempo ad Azshara.$B$BEcco la tua parte del nostro pagamento.",
}
T[3564] = {
  title = "Il Pagamento di Andron per Jediga",
  desc = "Tieni... porta... <hic> questo a Jediga. Buona fortuna a te!",
  obj = "Consegna Andron's Note a Jediga ad Azshara.",
  progress = "Hai già incontrato Andron? Lascia di rado Undercity, quindi non credo sia troppo difficile trovarlo.",
  reward = "Perfetto... aspetta un attimo.$B$BAh ah! Cosa gli hai detto quando gli hai consegnato la tavoletta, $N? Ci ha pagato decisamente troppo! Non che mi lamenti. Gli hai detto che l'accordo era cambiato? O era ubriaco un'altra volta?$B$BNon importa... tieni, prenditi anche una parte in più.",
}
T[3565] = {
  title = "Il Pagamento di Xylem per Jediga",
  desc = "Che c'è? Ah sì, il tuo pagamento. Certo.$B$BPrendi questo e vattene. Sono sicuro che Jediga aspetta il tuo ritorno con tanta, ma tanta pazienza.",
  obj = "Consegna Xylem's Note a Jediga ad Azshara.",
  progress = "Allora, cosa aveva da dire Xylem? Non ti ha fatto niente, vero? Ti ha lanciato un incantesimo? Ti ha raggirato per farti lavorare per lui?",
  reward = "Nessun problema? Proprio nessuno? Be', non è cosa da poco... Mi aspettavo che mostrasse una qualche riluttanza, o almeno che tradisse il nostro accordo. Hmm, forse dopotutto ci si può fidare di lui.$B$BBe', inutile rimuginarci troppo. Ecco la tua parte. Grazie per l'aiuto.",
}
T[3566] = {
  title = "Sorgi, Obsidion!",
  desc = "Era... Era... Era tutta una trappola.$B$BPerdonami...$B$BUccidi quel bastardo... Uccidilo per noi... per Thorius.",
  obj = "Uccidi Lathoric the Black e Obsidion, e torna da Curator Thorius a Ironforge con la Head of Lathoric the Black e l'Heart of Obsidion.",
  progress = "Non ti credo! Mostrami le prove!",
  reward = "<Il volto di Thorius sbianca.>$B$BNon... non può essere. Proprio mio fratello? Ha organizzato tutto lui?$B$B<Il volto di Thorius si contorce per la rabbia.>$B$BMi ha tradito, ha tradito Ironforge! A quanto pare l'influenza degli Dei Antichi è ancora forte in queste terre. Temo che se mio fratello — un tempo uomo nobile e d'onore — è stato piegato così facilmente al volere di Ragnaros, nessuno è al sicuro.",
}
T[3567] = {
  title = "Fino in Cima",
  reward = "Ti piacerebbe vedere il panorama dalla cima di uno dei colossi gemelli? Posso mandarti lassù io, $R.$B$BPensa però a come farai a scendere. È un viaggio di sola andata.",
  en_title = "To the Top",
}
T[3568] = {
  title = "Corruzione che S'insinua",
  desc = "Vedi quella tauren dietro di me — quella che sembra sul punto di sentirsi male da un momento all'altro? È stata ad Azshara di recente. Dice di essere stata ferita da alcuni naga mentre attraversava le Rovine di Eldarath.$B$BDopo averne respinti alcuni, si è fermata a riposare sulla spiaggia e ha bevuto da una delle pozze di marea. Ora ha la nausea... tra le altre cose.$B$BVorrei scoprire che cosa ha bevuto. Prendi questa scatola, dentro ci sono delle fiale vuote che ho etichettato. Riempi ognuna in una pozza diversa e torna qui.",
  obj = "Riempi tutte e 4 le Empty Vials nelle pozze di marea lungo la costa delle Rovine di Eldarath, ad Azshara, prima di tornare da Chemist Cuely.",
  progress = "Lo sai dove si va a parare, vero, $N? Non può sopravvivere in nessun modo... guardala. La cosa migliore che possa fare ora è aiutarci a trovare una cura per la piaga. L'acqua che ha bevuto potrebbe contenere un indizio che ci aiuti a capire come. Morirà comunque — tanto vale che, prima di morire, faccia qualcosa di nobile per il nostro popolo. Non sei d'accordo?",
  reward = "Magnifico. Sei $Gtornato:tornata; prima che morisse. Bene, bene.$B$BAllora mettiamoci al lavoro, d'accordo?$B$BÈ un po' che studio i suoi sintomi, ed è un gran brutto quadro. Mi stupisce che si regga ancora in piedi. Ha vomitato tre o quattro volte dappertutto... un odore davvero gradevole.$B$BDammi solo un momento per mettere insieme qualcosa da provare sulla nostra... amica.",
}
T[3569] = {
  title = "Corruzione che S'insinua",
  desc = "Dai questo a Thersa. Forse la guarirà... forse no. Non lo sapremo davvero finché non l'avrà bevuto.",
  obj = "Dai Cuely's Elixir a Thersa Windsong a Undercity.",
  progress = "Sono venuta a Undercity perché ho sentito che i suoi alchimisti studiano da tempo, e con impegno, come trovare una cura per il loro stesso male. Mi è stato detto che forse potevano aiutare anche me.$B$BAnche se in questo posto mi sento tutt'altro che benvenuta, non avevo scelta — il male che mi ha colta mi sta dilaniando dentro, e mi serviva subito il loro aiuto.",
  reward = "Il Chimico Cuely è stato molto disponibile... in modo inquietante. Ma se dice che questo mi aiuterà, allora non ho altra scelta. Non ho il tempo di cercare un'altra soluzione. Ho già parlato con sacerdoti e sciamani, e nessuno ha potuto aiutarmi.$B$BSperiamo che la Madre Terra vegli sul mio spirito.",
}
T[3570] = {
  title = "Corruzione che S'insinua",
  reward = "Non avrei mai immaginato che l'elisir facesse effetto così in fretta. Grazie, $N. Mi metto subito al lavoro sul resto di questi campioni. Sono sicuro che molto presto Lady Sylvanas e i Reietti potranno servirsene.",
}
T[3601] = {
  title = "Kim'jael, Come No!",
  desc = "Kim'jael, come no!! Lo sai cosa vuol dire Kim'jael per gli elfi del Sangue, $N? Piccolo ratto... o qualcosa del genere. Quei gran prepotenti!$B$BMi hanno assunto per aiutarli a esplorare la zona in cerca di non so quali tesori perduti. Ovviamente ho accettato al volo appena hanno detto \"tesoro\" e la cifra che erano disposti a pagare, ma ovviamente mi si sono rivoltati contro e hanno cercato di uccidere... ME!$B$BCome vedi, di un elfo del Sangue non ci si può fidare.$B$BIl problema è che hanno ancora la mia attrezzatura e non riesco a riprendermela. Mi dai una mano?",
  obj = "Cerca nel Thalassian Base Camp Kim'Jael's Compass, Kim'Jael's Scope, Kim'Jael's Stuffed Chicken e Kim'Jael's Wizzlegoober, poi riportaglieli ad Azshara.",
  progress = "Quei puzzoni di elfi del Sangue. Te lo dico io, se fossi forte come te, scenderei laggiù a dargli una bella lezione di persona! Ma mi toccherà accontentarmi di pagare te perché li sistemi al posto mio.",
  reward = "Ah ah! Gliel'hai fatta vedere, eh?!$B$BFantastico! Così quegli elfi del Sangue imparano a tradire i soci... soprattutto uno leale come un mercante goblin! Bah, gli elfi del Sangue...!$B$BBe', il minimo che posso fare per te è pagarti per il tuo tempo... proprio come avevo detto.$B$BEcco qua... dovrebbero tornarti utili.",
}
T[3602] = {
  title = "Azsharite",
  desc = "Gli antichi giganti delle scogliere della regione meridionale di Azshara si nutrono della roccia e degli edifici di questa terra. L'escremento che ne risulta è un cristallo molto malleabile ed estremamente resistente, noto come Azsharite.$B$BLe formazioni sono sparse per tutto l'arco meridionale, ma se ne recuperano ben poche, per via dell'indole estremamente violenta dei giganti.$B$BDevi spingerti a sud e recuperare abbastanza Azsharite per creare il corpo dell'arma. I miei vilsegugi ti aiuteranno a recuperare il cristallo.",
  obj = "Recupera venti Crystallized Azsharite nel sud di Azshara. Puoi usare il Felhound per farti aiutare a 'fiutare' dove si trovano i giacimenti nascosti ad arte.$B$BA compito finito, torna da Loramus Thalipedes.",
  progress = "Il male non dorme, $Gsciocco:sciocca;. Avrai tempo di riposare quando finalmente sarai $Gmorto:morta;. Ora portami quei cristalli.",
  reward = "I tuoi compiti ad Azshara sono conclusi, mortale. Ora devo forgiare i componenti necessari per il prossimo passo della tua avventura.",
}
T[3621] = {
  title = "La Creazione di Felbane",
  desc = "Le armi sono pronte per essere forgiate. Devi portare l'azsharite temprata a qualcuno capace di imbrigliare l'energia vile.$B$BA Stranglethorn Vale c'è un fabbro così. Galvan l'Antico, capo del Mithril Order, forgerà le armi secondo le tue indicazioni. Troverai il suo accampamento fra Zul'Gurub e il tumulo degli ogre Mosh'Ogg.$B$BChe la tua determinazione e la tua fede ti sostengano in questa prova. Se dovessi fallire, sappi che il tuo Dio ti sorride dall'alto, mortale.",
  obj = "Porta lo Shipment to Galvan a Galvan the Ancient, a Stranglethorn Vale.",
  progress = "Loramus, eh? Sono passati molti anni dall'ultima volta che ho sentito quel nome.",
  reward = "Santo cielo, posso solo immaginare cosa hai passato per procurarti questi materiali. Sono pochi quelli che si avventurano ad Azshara e ne tornano vivi, figuriamoci quelli che affrontano semidei e giganti!",
}
T[3625] = {
  title = "Armi Demoniache Incantate di Azsharite",
  desc = "$N, la creazione di ogni arma richiederà un po' di tempo.$B$BInoltre, potrai usare il potere del Felcurse solo una volta ogni tre minuti. I suoi effetti indebolenti su Razelikh il Profanatore e sui suoi servitori potrebbero avere una durata variabile. Per questo devi liberare il Felcurse solo al momento giusto!$B$BOra dammi un momento per forgiare la tua arma, $N.",
  obj = "Aspetta che Galvan finisca di forgiare le armi.",
  progress = "Interrompere la forgiatura potrebbe dare un'arma imperfetta. Abbi pazienza, $N.",
  reward = "<Galvan si asciuga il sudore dalla fronte.>$B$BNon è mai esistito un ammazzademoni migliore, $N.",
  en_title = "Enchanted Azsharite Fel Weaponry",
  en_obj = "Wait for Galvan to finish forging the weaponry.",
}
T[3626] = {
  title = "Ritorno nelle Blasted Lands",
  desc = "L'ora della redenzione è vicina, $N. Devi tornare nelle Blasted Lands con le tue nuove armi e parlare con l'Eroe Caduto dell'Orda per ricevere il tuo ultimo obiettivo.",
  obj = "Torna dal Fallen Hero of the Horde.",
  reward = "Sembri $Gtemprato:temprata; dalle battaglie, $N. Sei $Gpronto:pronta; ad affrontare Razelikh e i suoi servitori?",
  en_title = "Return to the Blasted Lands",
  en_obj = "Return to the Fallen Hero of the Horde.",
}
T[3627] = {
  title = "Ricomporre l'Amuleto in Frantumi",
  desc = "Per arrivare al Profanatore devi prima distruggere la triade del potere e recuperare i pezzi dell'amuleto. Quando li avrai recuperati tutti e tre, torna da me e ti darò altre istruzioni.$B$BVa', $N! Nelle Blasted Lands! Sevine, Allistarj e Grol devono cadere!",
  obj = "Uccidi Grol the Destroyer, Lady Sevine e Archmage Allistarj. Prendi dai loro cadaveri l'Amulet of Grol, l'Amulet of Sevine e l'Amulet of Allistarj.$B$BRicordati di USARE il tuo Enchanted Azsharite Fel Weaponry per indebolire la triade. Altrimenti non possono essere uccisi — ma usalo con saggezza...",
  progress = "I tre formeranno l'uno, l'uno illuminerà la via.",
  reward = "L'amuleto di Razelikh il Profanatore è di nuovo completo, ma lui avverte lo scompiglio nella sua catena di comando. Sa che stai venendo a prenderlo...",
}
T[3628] = {
  title = "Tu Sei Rakh'likh, Demone",
  desc = "Il covo di Razelikh è in cima alla montagna più alta delle Blasted Lands. L'unico modo per arrivarci è usare le rune di teletrasporto vicino alla montagna. Finché hai con te l'amuleto, puoi trasportarti liberamente fino al covo. Una volta lì, devi evocare la bestia. L'amuleto è la tua chiave, $N. Usalo sull'Altare del Profanatore.$B$BSe riuscirai a sconfiggere il Profanatore, riporta il suo corno. Diventerà un simbolo di speranza per tutti quelli che lo vedranno — la prova che in questo mondo dilaniato dalla guerra gli eroi esistono davvero.",
  obj = "Distruggi Razelikh the Defiler e riporta il Severed Horn of the Defiler al Fallen Hero of the Horde. Dovrai riportare anche il Ward of the Defiler, così che il Fallen Hero of the Horde possa distruggerlo e impedire che cada mai nelle mani sbagliate.",
  progress = "Non c'è più niente da temere.",
  reward = "Oggi è un giorno che sarà ricordato per l'eternità. Il sovrano demoniaco delle Blasted Lands è finalmente caduto!",
}
T[3629] = {
  title = "Ingegneria Goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.$B$B$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3630] = {
  title = "Ingegneria Gnomica",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!$B$B$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.",
  reward = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, $Gamico:amica;. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando si vede $Gun altro ingegnere:un'altra ingegnera; rispondere alla chiamata della vera ingegneria!",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
}
T[3631] = {
  title = "Summon Felsteed",
  desc = "Hmph. Io dico che non sei $Gpronto:pronta;, ma non sta a me decidere. Strahad la pensa diversamente, e la decisione spetta a lui... stavolta.$B$BVuole parlarti, e subito. Lo trovi ancora sopra Ratchet, nelle Barrens, in quella sua torretta, con i suoi accoliti.$B$BNon attardarti troppo.",
  obj = "Parla con Strahad Farsan, nelle Barrens.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile.$B$BI miei accoliti si chiedevano se ti saresti mai $Gpresentato:presentata;. Ho detto loro che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[3632] = {
  title = "Ingegneria Gnomica",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!$B$B$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, qui a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!",
  obj = "Se vuoi saperne di più sull'Ingegneria Gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.",
