T[3661] = {
  title = "Prediletti di Elune?",
  desc = "I Wildkin sono creature piuttosto imprevedibili, $N. Capaci di un'incredibile dolcezza, mostrano una ferocia estrema se viene minacciato qualcosa che ritengono importante.$B$BSi dice che queste bestie siano state create da Elune, e mi interessa scoprire se è davvero così.$B$BDi recente ho sentito parlare di una popolazione di wildkin che vive nelle Hinterlands — Owlbeast Feroci, Primitivi e Selvaggi. Si trovano tra gli animali selvatici del posto. Mi raccoglieresti qualche penna di wildkin?",
  obj = "Raccogli 15 Wildkin Feathers nelle Hinterlands per Erelas Ambersky a Rut'theran Village.",
  progress = "Cerca di evitarli, se puoi, $N. I Wildkin potrebbero scambiare il tuo interesse per l'intenzione di far loro del male...",
  reward = "Grazie per avermele portate, $N.$B$BCos'hai scoperto sui Wildkin?$B$BForse queste penne ci diranno di più. Mostri feroci, o semplicemente animali da compagnia finiti sulla cattiva strada? Un giorno vorrei sapere la verità...$B$BContinuerò le mie ricerche — per favore, torna a parlarmi fra qualche tempo.",
}
T[3681] = {
  title = "Tomo della Divinità",
  desc = "Scusa se interrompo i tuoi viaggi, $R, ma ho pensato che dovessi sapere che di recente è arrivato un messaggio da Stormwind che chiede ai paladini di presentarsi là per l'addestramento.$B$BSe non sbaglio, direi che sei $Gvicino:vicina; a un momento speciale, ed è ora che cominci a studiare i Tomi.$B$BCerca Duthorian Rall a Stormwind. Di solito addestra i paladini nella Cattedrale della Luce.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "$GBenvenuto:Benvenuta; nella Cattedrale della Luce, $C.",
  en_title = "Tome of Divinity",
  en_obj = "Speak with Duthorian Rall in Stormwind.",
}
T[3701] = {
  title = "Le Rovine Fumanti di Thaurissan",
  desc = "Avventurati tra le rovine fumanti di Thaurissan, nelle Burning Steppes, e raccogli più informazioni che puoi.$B$BSi dice che le rovine siano disseminate di reliquie misteriose. Forse dovresti cominciare le ricerche da lì, $N. Fa' attenzione ai guardiani di Thaurissan: Assassini che sorvegliano le rovine e proteggono qualunque segreto vi sia ancora sepolto.",
  obj = "Avventurati tra le Rovine di Thaurissan, nelle Burning Steppes, e recupera le informazioni dalle Thaurissan Relics. Torna da Royal Historian Archesonus quando avrai recuperato le informazioni.",
  progress = "Porti nuove informazioni?",
  reward = "Oh, cielo! Queste informazioni spiegano parecchie cose su Thaurissan.$B$BC'è ancora molto da imparare!",
}
T[3702] = {
  title = "Le Rovine Fumanti di Thaurissan",
  desc = "Ti andrebbe di ascoltare una breve storia dei nani Dark Iron?",
  obj = "Ascolta Royal Historian Archesonus raccontare la storia di Thaurissan.",
  progress = "Lascia che finisca di raccontarti la storia di Thaurissan.",
  reward = "Vogliamo procedere?",
}
T[3721] = {
  title = "Un OOX Tutto per Te",
  reward = "Hai recuperato tre dei miei robot OOX a rientro automatico! Hai fatto ben più del necessario, quindi per tutto il tuo aiuto ti darò una cosa speciale. È una versione in miniatura dello stesso robot che hai imparato a conoscere e ad amare, l'OOX!$B$BDi norma non lascerei a nessuno un congegno potenzialmente letale come questo, ma mi hai dato davvero una mano. E poi — su questo esemplare i meccanismi di combattimento e la logica di rientro sono stati disattivati.$B$BPer il resto, è un OOX, perbacco!",
}
T[3761] = {
  title = "Terra di Un'Goro",
  desc = "Si dice che la terra dell'Un'Goro Crater sia ricca di potenti qualità magiche. Il Cenarion Circle vuole studiarla in grandi quantità; addentrati nelle terre selvagge di Un'Goro e procuratene abbastanza per proseguire le nostre ricerche.$B$BQua e là la terra fertile affiora in mucchi, e alcune bestie potrebbero averne addosso dei campioni utilizzabili. Portali tutti fuori, da Ghede; basta cercare i mucchi di terra e il tauren che abbaia ordini. Ha buone intenzioni, ma non farlo arrabbiare!",
  obj = "Porta 20 Un'Goro Soil a Ghede, sull'Elder Rise di Thunder Bluff.",
  progress = "Riposo, $Gsoldato:soldatessa;. Se sei qui per scaricare terra di Un'Goro — magnifico! Altrimenti, sparisci.",
  reward = "Ma certo, $Gsoldato:soldatessa; $N, non fare il minimo sforzo per aiutarmi a scaricare questa terra sui mucchi! Se i Grandi Spiriti avessero voluto che fosse fatto, ce l'avrebbero portata lassù per miracolo, non ti pare?!$B$BL'Arcidruido Runetotem vuole parlarti di nuovo, ma per il suo prossimo incarico scopri che ti sarebbe utile una conoscenza dell'Erbalismo di livello Journeyman. Se però non ce l'hai, troverà comunque un modo di impiegarti.",
  en_title = "Un'Goro Soil",
  en_obj = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.",
}
T[3762] = {
  title = "Aiutare l'Arcidruido Runetotem",
  desc = "Scusami, $C, ma vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Thunder Bluff è molto interessato a trovare avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.$B$BTi prego — se ti interessa, parla direttamente con lui sull'Altura degli Anziani, dentro Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem, a Thunder Bluff.",
  reward = "Salve, $C; sono lieto che tu voglia aiutare la nostra ricerca. C'è molto da fare, e ti renderei un cattivo servizio se ti dicessi che questo lavoro non è pericoloso. Spero che questo non ti spaventi... ma, a giudicare dal tuo aspetto, direi che col pericolo hai già avuto a che fare.",
  en_title = "Assisting Arch Druid Runetotem",
  en_obj = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.",
}
T[3763] = {
  title = "Aiutare l'Arcidruido Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'Arcidruido Fandral Staghelm.$B$BTi prego — se ti interessa, parla direttamente con lui nell'Enclave Cenarion, a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... visto che ti hanno detto che sono io a guidare questa ricerca, sei $Gvenuto:venuta; più in fretta che potevi, è evidente.$B$BOra che sei qui, mi raccomando, fa' attenzione la prima volta che ti spiego i dettagli: non ho nessuna voglia di ripetermi.",
}
T[3764] = {
  title = "Terreno di Un'Goro",
  desc = "A quanto si dice, il terreno dell'Un'Goro Crater è ricco di potenti proprietà magiche. Voglio distinguere i fatti dalle falsità; addentrati nella natura selvaggia di Un'Goro e procurati abbastanza campioni di terreno di buona qualità per proseguire i nostri studi.$B$BMagari pensi che i lavori di raccolta non siano alla tua altezza; un atteggiamento del genere non ti fa guadagnare la mia simpatia né quella del Cenarion Circle. Porta i campioni a Jenal, che di sicuro sta perdendo tempo qui fuori, dietro quest'albero; ti basta cercare i mucchi di terra. Della logistica si occuperà lui — non io.",
  obj = "Porta 20 campioni di Un'Goro Soil a Jenal, al Cenarion Enclave di Darnassus.",
  progress = "Ah, sì, la terra. L'Arcidruido vuole venti carichi per avventuriero, e venti carichi avrà. E chi trama contro di noi si perda pure per strada!",
  reward = "Scarica qui il tuo prezioso carico, nobile $C. Dev'essere stato un bel peso... non diverso da quello che porto io, da visionario quale sono. Ecco un onorario per il tuo lavoro, come disposto dall'Arcidruido in persona.$B$BL'Arcidruido Staghelm vuole parlarti di nuovo, $N, ma per il suo prossimo incarico ti sarà d'aiuto conoscere l'Erbalismo a livello di praticante. Se però non lo conosci, potrai comunque aiutare il Circle!",
}
T[3765] = {
  title = "La Corruzione d'Oltremare",
  desc = "Stormwind — che centro pieno di vita e di movimento.$B$BVengo da lontano in cerca di aiuto. Si sente dire spesso che per le strade di questa città girano avventurieri coraggiosi.$B$BMio fratello, Gershala, ha bisogno di aiuto a Darkshore. Vive ad Auberdine, una cittadina sul mare.$B$BÈ un viaggio lungo ed epico. Per questo chiedo l'aiuto di $Gun:una; $C $Gesperto:esperta; come te.",
  obj = "Raggiungi Gershala Nightwhisper, ad Auberdine.",
  reward = "Ah, quindi ti manda mio fratello, Argos? Immagino che tu sia $Gstanco:stanca; per il viaggio. Ma abbiamo molto di cui parlare.",
  en_title = "The Corruption Abroad",
  en_obj = "Travel to Gershala Nightwhisper in Auberdine.",
}
T[3781] = {
  title = "Ricerche sull'Erbavoglio",
  desc = "Con quello che chiamiamo Zaino Sempreverde abbiamo coltivato i semi di Tharlendris nel terreno dell'Un'Goro Crater. Da questi semi nasce un assortimento casuale di erbe potenti. Una di queste è l'erbavoglio, un'erba misteriosa di cui sappiamo poco; intendo svelare questo mistero.$B$BPorta questo a Mathrengyl, al piano di sotto, e lui ti darà dei semi per cominciare. Se li finisci, dovrai comprarne altri da lui.",
  obj = "Porta il Seed Voucher dell'Arcidruido a Mathrengyl Bearwalker, al Cenarion Enclave di Darnassus.",
  progress = "Pace e serenità a te, $Gamico:amica;. Sei qui per un incarico dell'Arcidruido in persona, vero?",
  reward = "Sì, questo buono vale venti pacchetti di semi. Se li finisci, ne abbiamo altri da darti. Purtroppo, però, produrre semi di Tharlendris in grandi quantità costa parecchio. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire coprendo una parte della spesa.$B$BChi torna con l'erbavoglio scopre che la ricompensa offerta dall'Arcidruido ripaga ampiamente la spesa.",
}
T[3782] = {
  title = "Ricerche sull'Erbavoglio",
  desc = "Con quello che chiamiamo Zaino Sempreverde, abbiamo coltivato semi di Tharlendris nella terra dell'Un'Goro Crater. Da questi semi sono sbocciate, in modo imprevedibile, erbe potenti di ogni genere. Una di queste è l'erbavoglio, un'erba misteriosa di cui sappiamo poco; spero davvero di svelare questo mistero per il Circle.$B$BPorta questo buono a mia figlia Bashana, e lei ti darà dei semi, così potrai aiutarci. Se li finisci, dovrai comprarne altri da lei.",
  obj = "Porta il Seed Voucher a Bashana Runetotem, a Thunder Bluff.",
  progress = "Pace a te, $Gamico:amica;. Sei qui per conto dell'Arcidruido in persona, vero?",
  reward = "Sì, questo buono vale venti pacchetti di semi. Se finisci i semi, ne ho altri che posso venderti.$B$BPurtroppo, $N, produrre semi di Tharlendris in quantità significative è piuttosto costoso. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire coprendo parte della spesa. Chi torna con l'erbavoglio scopre che la ricompensa offerta dall'Arcidruido ripaga ampiamente la spesa.",
  en_title = "Morrowgrain Research",
  en_obj = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.",
}
T[3783] = {
  title = "Siamo Arrivati, Yeti?",
  desc = "I miei amici tirano sempre fuori idee fantastiche. Non mi sono mai sentita alla loro altezza... fino a oggi! Ho appena finito i progetti di una cosa grandiosa! Se prometti di non dirlo a nessuno, ti svelo il segreto...$B$BCostruirò uno yeti meccanico! Non solo ai miei amici verrà di sicuro un colpo quando lo vedranno, ma passato lo spavento so che resteranno a bocca aperta!$B$BPer cominciare mi serve della pelliccia spessa di yeti, quella degli yeti ice thistle. Mi aiuti? Li trovi a sud-est.",
  obj = "Raccogli 10 Thick Yeti Furs per Umi Rumplesnicker a Everlook.",
  progress = "Qui ho un sacco di cose a cui mettere mano. Portami quelle pellicce appena puoi, per favore!",
  reward = "Queste pellicce sono perfette, $N. Siamo partiti alla grande!",
}
T[3784] = {
  title = "Aiutare l'Arcidruido Runetotem",
  desc = "Scusami, $C, ma vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Thunder Bluff è molto interessato a trovare avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.$B$BTi prego — se ti interessa, parla direttamente con lui sull'Altura degli Anziani, dentro Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem, a Thunder Bluff.",
  reward = "Salve, $C; sono lieto che tu voglia aiutare la nostra ricerca. C'è molto da fare, e ti renderei un cattivo servizio se ti dicessi che questo lavoro non è pericoloso. Spero che questo non ti spaventi... ma, a giudicare dal tuo aspetto, direi che col pericolo hai già avuto a che fare.",
}
T[3785] = {
  title = "Ricerche sull'Erbavoglio",
  desc = "Ecco il tuo Zaino Sempreverde: ti servirà per usare i semi di Tharlendris. Devi anche avere con te dei campioni di terreno di Un'Goro, da usare come fertilizzante per i semi. Quando hai tutto, ti basta usare lo zaino; al resto penserà lui.$B$BQuando hai abbastanza erbavoglio, portalo qui da me, nell'enclave. Ti prego, non disturbare l'Arcidruido; è un uomo molto impegnato, e non ha bisogno di essere interrotto ogni volta che qualcuno torna con un'altra partita di erbavoglio!",
  obj = "Usa un Evergreen Pouch con un Packet of Tharlendris Seeds e due campioni di Un'Goro Soil per provare a coltivare dei campioni di Morrowgrain.$B$BPorta 10 Morrowgrain a Mathrengyl Bearwalker, a Darnassus.",
  progress = "Sì, $N, hai coltivato dell'erbavoglio per le importanti ricerche dell'Arcidruido? Il lavoro che sta facendo per il Cenarion Circle è molto importante, e il tuo aiuto non passerà inosservato!",
  reward = "Ottimo lavoro, $N, lo consegnerò di sicuro all'Arcidruido in persona quando ne avrà bisogno. Nel frattempo, ti prego di accettare questo in segno della riconoscenza del Cenarion Circle.$B$BDi erbavoglio abbiamo bisogno di continuo; se vuoi continuare ad aiutarci, torna da me quando ne avrai coltivato dell'altro per noi.",
}
T[3786] = {
  title = "Ricerche sull'Erbavoglio",
  desc = "Ecco il tuo Zaino Sempreverde, che ti servirà per usare i semi di Tharlendris. Devi avere a portata di mano anche dei campioni di terra di Un'Goro, da usare come fertilizzante per i semi. Usa lo zaino quando hai tutto; al resto penserà lui.$B$BQuando avrai abbastanza erbavoglio, portalo a me, qui sull'Altura degli Anziani. Per favore, non disturbare l'Arcidruido; sarà molto impegnato con la ricerca, oltre che con le mille preoccupazioni che ha!",
  obj = "Usa una Evergreen Pouch con un Packet of Tharlendris Seeds e due Un'Goro Soil per provare a coltivare campioni di Morrowgrain.$B$BPorta 10 Morrowgrain a Bashana Runetotem, a Thunder Bluff.",
  progress = "Sì, $N, hai coltivato un po' di erbavoglio per l'importante ricerca dell'Arcidruido? Le misteriose proprietà dell'Un'Goro Crater diventano più chiare ogni giorno che passa, grazie all'aiuto che ci stai dando.",
  reward = "Ben fatto, $N, mi assicurerò di consegnarlo all'Arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno di gratitudine del Cenarion Circle.$B$BPer ora il nostro bisogno di erbavoglio è costante; se vuoi continuare ad aiutarci, torna quando ne avrai coltivato altro.",
  en_title = "Morrowgrain Research",
  en_obj = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.",
}
T[3787] = {
  title = "La Richiesta di Jonespyre",
  desc = "Scusami, $Gamico:amica;...$B$BUn mio collega vorrebbe parlarti delle ricerche che stai facendo insieme al Cenarion Circle. È un druido di nome Quintis Jonespyre, e vive a Feathermoon Stronghold, nel Feralas. Vorrebbe confrontarsi con te sulla morrowgrain... e ci terrebbe molto che la nostra conversazione non arrivasse alle orecchie dell'Arcidruido.$B$BSe ti interessa, parla con lui; di sicuro, una volta che l'avrai fatto, tutto ti sarà svelato.",
  obj = "Parla con Quintis Jonespyre a Feathermoon Stronghold.",
  reward = "Ti ringrazio di essere $Gvenuto:venuta;, $Gstanco viandante:stanca viandante;! Permettimi di presentarmi — sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (il Generale Shandris Feathermoon e il Protectorate — forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.$B$BPrima di andare oltre, vorrei chiederti che la nostra conversazione resti fra noi. Se per te va bene, possiamo proseguire.",
  en_title = "Jonespyre's Request",
  en_obj = "Speak with Quintis Jonespyre in Feathermoon Stronghold.",
}
T[3788] = {
  title = "La Richiesta di Jonespyre",
  desc = "Scusami, $Gamico:amica;...$B$BUn mio collega vorrebbe parlarti delle ricerche che stai conducendo insieme al Cenarion Circle. È un druido di nome Quintis Jonespyre e risiede qui a Feathermoon Stronghold. Vorrebbe discutere con te dell'erbavoglio... e ci terrebbe molto che la nostra conversazione non arrivasse alle orecchie dell'Arcidruido.$B$BSe ti interessa, parla con lui; di sicuro, quando lo farai, ti sarà rivelato tutto.",
  obj = "Parla con Quintis Jonespyre a Feathermoon Stronghold.",
  reward = "Ti ringrazio di essere $Gvenuto:venuta;, $Gstanco viandante:stanca viandante;! Permettimi di presentarmi — sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (il Generale Shandris Feathermoon e il Protectorate — forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.$B$BPrima di andare oltre, vorrei chiederti che la nostra conversazione resti fra noi. Se per te va bene, possiamo proseguire.",
}
T[3789] = {
  title = "Aiutare l'Arcidruido Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'Arcidruido Fandral Staghelm.$B$BTi prego — se ti interessa, parla direttamente con lui nell'Enclave Cenarion, a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... visto che ti hanno detto che sono io a guidare questa ricerca, sei $Gvenuto:venuta; più in fretta che potevi, è evidente.$B$BOra che sei qui, mi raccomando, fa' attenzione la prima volta che ti spiego i dettagli: non ho nessuna voglia di ripetermi.",
  en_title = "Assisting Arch Druid Staghelm",
  en_obj = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
}
T[3790] = {
  title = "Aiutare l'Arcidruido Staghelm",
  desc = "Scusami, $C, vorrei rubarti solo un momento, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'Arcidruido Fandral Staghelm.$B$BTi prego — se ti interessa, parla direttamente con lui nell'Enclave Cenarion, a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... visto che ti hanno detto che sono io a guidare questa ricerca, sei $Gvenuto:venuta; più in fretta che potevi, è evidente.$B$BOra che sei qui, mi raccomando, fa' attenzione la prima volta che ti spiego i dettagli: non ho nessuna voglia di ripetermi.",
}
T[3791] = {
  title = "Il Mistero dell'Erbavoglio",
  desc = "Lascia che sia franco con te, $N. Mi interessa — anzi, mi preoccupa il motivo per cui l'Arcidruido di Darnassus sta usando il nome del Cenarion Circle, oltre alle risorse del Circle, per procurarsi enormi quantità di erbavoglio. Sono un ricercatore — le maledizioni sono la mia specialità. Ho sentito dire che l'erbavoglio, nelle giuste condizioni, sprigiona proprietà simili a quelle di altre erbe usate nelle maledizioni primitive.$B$BVoglio saperne di più, e chiedo il tuo aiuto. Portami dieci erbavoglio, e saprò sdebitarmi.",
  obj = "Porta 10 Morrowgrain a Quintis Jonespyre a Feathermoon Stronghold.",
  progress = "Cerco dieci erbavoglio — dovrebbero bastare almeno per avviare le mie ricerche. Di sicuro ne consumerò parecchi imboccando strade sbagliate, ma la ricerca è fatta così.",
  reward = "Ugh, questi erbavoglio mi fanno sentire... strano. In nome di Elune, cosa sta combinando Staghelm con questa roba?$B$BComunque, grazie ancora dell'aiuto. Ecco una cosetta... sai, per l'impegno. Le mie ricerche sull'erbavoglio andranno per le lunghe, e di sicuro me ne servirà ancora. Già che ci sono, immagino che potrei prendermi il tempo di vedere se l'erbavoglio ha qualche uso alchemico interessante. Eppure, mi sento a disagio anche solo a starci vicino.",
}
T[3792] = {
  title = "Erbavoglio per Feathermoon Stronghold",
  progress = "Ciao di nuovo, $N. Le mie ricerche procedono abbastanza bene, ma se hai altri cinque Erbavoglio sarò felice di liberartene. Be'... felice si fa per dire, in questo caso; più ci sto vicino, più mi sento a disagio. Comunque, le mie ricerche mi impongono di stringere i denti e andare fino in fondo.",
  reward = "Grazie, $N; per il momento li metto da parte, dove non danno fastidio. Non dispongo delle risorse di Staghelm, ma posso darti una cosetta per il disturbo. Comunque, chissà cosa succederà se Staghelm continua a ricevere Erbavoglio su Erbavoglio. Qui c'è sotto qualcosa di losco, te lo dico io.$B$BRicorda che sono sempre in cerca di altri Erbavoglio. Li prendo cinque alla volta.",
}
T[3801] = {
  title = "L'Eredità dei Dark Iron",
  desc = "Salute, $N. Io sono Franclorn Forgewright. Sì, proprio il Franclorn Forgewright a cui si deve il metodo architettonico della pietra lavorata. Di sicuro, nelle tue avventure per questo nostro mondo devastato dalla guerra, hai attraversato una delle mie creazioni o ci hai messo piede.$B$BTi starai chiedendo perché sono qui e che cosa voglio da te — domande legittime, tutte e due.$B$BMi serve il tuo aiuto, naturalmente. In cambio del tuo aiuto ti concederò la chiave delle profondità della mia città maledetta.",
  obj = "Parla con Franclorn Forgewright se ti interessa ottenere la chiave maestra della città.",
  reward = "Che a portarti qui sia stata l'avidità o un gesto di devozione disinteressata, quello che stai per intraprendere è per il bene di tutti noi.",
}
T[3802] = {
  title = "L'Eredità dei Dark Iron",
  desc = "Troverai Fineous Darkvire oltre l'Anello della Legge, nella Sala dell'Artigianato. Uccidi quel cane rognoso e recupera Ironfel.$B$BPorta Ironfel al Santuario di Thaurissan e metti il martello al posto che gli spetta: nelle mani della statua eretta in mio onore.$B$BFatto questo, si aprirà lo scomparto in cui ho riposto la chiave maestra. E soprattutto, Ironfel resterà per sempre nelle mie mani. Provino pure a togliere il martello; tanto la statua quanto il martello andranno in frantumi, perduti per sempre.",
  obj = "Uccidi Fineous Darkvire e recupera il grande martello, Ironfel. Porta Ironfel al Santuario di Thaurissan e mettilo sulla statua di Franclorn Forgewright.",
  progress = "La statua incombe minacciosa su di te.",
  reward = "Il martello si incastra saldamente al suo posto, tra le mani dell'imponente monumento dei Dark Iron. Alla base della statua si apre un minuscolo scomparto. Dentro trovi...",
}
T[3803] = {
  title = "Erbavoglio a Darnassus",
  progress = "L'Arcidruido cerca sempre altro erbavoglio per le ricerche che il Cenarion Circle porta avanti. Lo prendiamo a gruppi di dieci, e in cambio ti diamo una cassa di oggetti che dovrebbero tornarti utili. Quando ne hai dieci, fammelo sapere e ti ricompenserò come si deve.",
  reward = "Eccellente — questo erbavoglio farà senz'altro piacere all'Arcidruido. Devo ammettere, però... che solo a stare vicino a quest'erba mi sento un po' a disagio. Posso solo immaginare quanto sia difficile per l'Arcidruido sopportarne quantità così grandi!$B$BQuesto è per te, $N. Il Cenarion Circle ti ringrazia per il tuo sostegno costante.",
}
T[3804] = {
  title = "Erbavoglio per Thunder Bluff",
  progress = "L'Arcidruido cerca sempre altro erbavoglio per il progetto di ricerca del Cenarion Circle sull'Un'Goro Crater. Lo accettiamo a gruppi di dieci, e in cambio ti diamo una scorta di beni che dovrebbero tornarti utili. Quando ne avrai dieci, fammelo sapere e ti ricompenserò di conseguenza.",
  reward = "Eccellente — questo erbavoglio sarà senza dubbio utile quando verrà il momento. Sappiamo che gli elfi della notte stanno conducendo ricerche simili su queste erbe, anche se non è chiaro a che scopo le useranno, se scopriranno qualcosa. L'Arcidruido pensa che il bisogno di erbavoglio resterà finché non avremo svelato i misteri di quest'erba.$B$BQuesto è per te, $N. Il Cenarion Circle ti ringrazia per il tuo costante sostegno.",
  en_title = "Morrowgrain to Thunder Bluff",
}
T[3821] = {
  title = "Masso dei Dreadmaul",
  desc = "Più di tre settimane fa, Sha'ni è stata mandata a indagare su alcune segnalazioni di strane attività rituali tra gli ogre Firegut delle Burning Steppes.$B$BGoretooth mi dice che non ha avuto notizie da nessuno di quel plotone e che è meglio che volti pagina e mi concentri sul mio compito. Ti rendi conto? È mia moglie!$B$BNon posso lasciare il mio posto, $N, ma devo sapere che fine ha fatto Sha'ni. Va' nelle Burning Steppes e cercala.",
  obj = "Avventurati nelle Burning Steppes e scopri che fine ha fatto Sha'ni Proudtusk.",
  reward = "Il mio povero Thal'trak.$B$BAvevamo in programma di andare a vivere con mia madre e mio padre nelle Hinterlands, finito il servizio. Ora quei progetti sono rovinati!",
  en_title = "Dreadmaul Rock",
  en_obj = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.",
}
T[3822] = {
  title = "Krom'Grul",
  desc = "Hanno catturato tutto il mio plotone, $N. Sono stati uccisi tutti — tranne me.$B$BIl loro capo, Krom'Grul, voleva tenermi per una specie di rituale.$B$BSono stata incatenata a questo altare e seviziata da quella bestia. Dopo un'ora di tortura il mio corpo ha smesso di funzionare. Allora la bestia mi ha strappato dal viso l'anello nuziale che portavo al naso e se l'è infilato al dito. Non avevo mai visto una ferocia simile!$B$BTrova Krom'Grul e uccidilo! Riporta il mio anello a Thal'trak.$B$BE, $N, digli che ci rivedremo... in un'altra vita.",
  obj = "Recupera Sha'ni's Nose-Ring da Krom'Grul e riportalo a Thal'trak Proudtusk, a Kargath. Cerca nelle varie grotte e miniere del Masso dei Dreadmaul.",
  progress = "Hai trovato Sha'ni? Sta bene?",
  reward = "<Thal'trak crolla a terra.>$B$BVolevamo trasferirci nelle Hinterlands. Te l'ha detto? Questa doveva essere la sua ultima missione.$B$B<Thal'trak singhiozza.>$B$BNon lo voglio, $N. Tienilo, buttalo via, non m'importa! Quell'anello ormai non significa più niente per me. Non senza di lei...",
}
T[3823] = {
  title = "Spegni i Firegut",
  desc = "Dobbiamo colpire i nostri nemici prima che siano loro a colpire noi!$B$BSarò breve, soldato.$B$BGli ogre Firegut delle Burning Steppes sono alleati degli orchi Blackrock. Lavorano fianco a fianco con quegli orchi spregevoli, sorvegliando il Masso dei Dreadmaul, ricco di minerali, e tenendo sempre aperte le vie di rifornimento.$B$BLascia il segno, $N. Metti in ginocchio le loro forze e torna da me a lavoro finito.$B$B<Oralius afferra l'aria e fa il gesto di strozzare qualcuno.>$B$BIO TI AMMAZZO, WINKY!",
  obj = "Uccidi 15 Firegut Ogre Mages, 7 Firegut Ogres e 7 Firegut Brutes, e torna da Oralius quando hai finito.",
  progress = "Sulla tua uniforme c'è decisamente troppo poco sangue, soldato!",
  reward = "Eccellente, soldato! Questo colpo farà barcollare orchi e ogre per minuti, forse addirittura per ore!",
}
T[3824] = {
  title = "Gor'tesh il Signore dei Bruti",
  desc = "Barcollano, te lo dico io! Il nostro prossimo colpo dev'essere decisivo.$B$BIl signore dei bruti, Gor'tesh, va ucciso. E soprattutto la sua testa va riportata a me, così potrò preparare la terza fase del nostro attacco agli ogre Firegut.$B$BBada, soldato, Gor'tesh non comanda dal Masso dei Dreadmaul ma da una costruzione degli orchi Blackrock a ovest del Masso dei Dreadmaul.$B$BI tuoi ordini, quindi, sono semplici. Trova Gor'tesh e mozzagli quel testone grasso. Torna da me a lavoro finito.$B$BSTA' ZITTO, WINKY!",
  obj = "Trova Gor'tesh, da qualche parte a ovest del Masso dei Dreadmaul. Uccidi Gor'tesh e poi riporta Gor'tesh's Lopped Off Head a Oralius, nelle Burning Steppes.",
  progress = "Oh, giorno glorioso! Sei $Gtornato:tornata; con la testa?",
  reward = "Ma guardala, soldato. Disgustosa! Quando gli ogre Firegut rimasti vedranno questo faccione grasso infilzato su una picca in cima alla loro montagna, scoppierà l'isteria di massa!$B$B<Oralius sghignazza come un pazzo.>",
}
T[3825] = {
  title = "Testa di Ogre su un Bastone = Festa",
  desc = "Ti resta solo un'ultima cosa da fare, soldato.$B$BMi sono preso la libertà di infilzare la testa di Gor'tesh su una picca. Ora non devi far altro che portare questa testa in cima al Masso dei Dreadmaul e piantarla nel terreno. Fatto questo, guarda quei codardi di ogre darsela a gambe! Quando ti sarai $Gdivertito:divertita;, torna da me e ti ricompenserò per tutto il tuo duro lavoro.$B$B<Oralius sembra perdere il contatto con la realtà.>",
  obj = "Prendi Gor'tesh's Lopped Off Head e mettila in cima al Masso dei Dreadmaul. Cerca un Soft Dirt Mound in cui piantare la picca.",
  progress = "Allora? Hai dipinto qualche quadro dell'evento?",
  reward = "Ottimo lavoro, soldato! Semplicemente strepitoso! Oh, per questo mi daranno la medaglia al valore, ehm, cioè, per questo avrai una lauta ricompensa!",
}
T[3841] = {
  title = "Un Orfano in Cerca di Casa",
  desc = "Oh, ciao, $N. Sono così contenta di rivederti. Com'è andato il viaggio a Darnassus?$B$BBe', sarai felice di sapere che mentre eri via abbiamo fatto parecchi progressi. Abbiamo perfino salvato un nido pieno di uova. Purtroppo la madre è morta prima che arrivassimo da lei.$B$BSenti, ne vorresti uno come animale da compagnia? Sembra che stiano per schiudersi, quindi avranno bisogno di $Gun buon padre:una buona madre;. Che ne dici?$B$BSe ti interessa davvero, porta una delle uova a Quentin, alla pista delle corse di Shimmering Flats. Lui ti dirà di più.",
  obj = "Parla con Quentin, a Thousand Needles.",
  progress = "Ma salve, $C.$B$BNon lasciarti ingannare dal posto in cui mi trovi: non sono qui per le corse... per quanto possano essere divertenti.$B$BIn realtà sono qui a Thousand Needles a indagare più che posso per capire quanto si possa recuperare di questa terra. È diventata una sorta di crociata personale: rivitalizzare la zona e rifornirla di terreno nuovo e fertile. Forse scoprirò che qui vicino c'è una fonte d'acqua.$B$BNon dirmi che non hai notato quanto è strano il passaggio fra Feralas e Thousand Needles. Quando è successo, era all'opera una strana magia.",
  reward = "Ah, un uovo di folletto sfrecciante, e vicino alla schiusa, se non sbaglio. È notevole che tu ne abbia trovato uno, e per di più in condizioni così buone. Di questi tempi a Feralas si vedono di rado. Ho sentito che nella zona c'erano diversi bracconieri che cercavano di catturarli e ucciderli per molte ragioni. Un vero peccato... sono creature così belle quando diventano adulte.$B$BCome hai fatto a trovare una cosa del genere?",
}
T[3842] = {
  title = "Una Breve Incubazione",
  desc = "I Moonweaver, eh? Molto interessante. Vorrei che i folletti sfreccianti potessero capire davvero cosa significa avere quelle due a occuparsi di loro. Sono tutte e due molto capaci.$B$BQuindi ti hanno regalato l'uovo. Be', allora dovresti occupartene tu, per tutto il tempo che vorrai. Sembra quasi pronto a schiudersi, ma dovremmo assicurarci che sia in salute e che non abbia subito danni.$B$BMi servono solo due elisir di tempra per un piccolo incantesimo che protegga l'uovo. Il resto degli ingredienti ce l'ho già qui con me.",
  obj = "Porta 2 Elixir of Fortitude a Quentin, a Thousand Needles.",
  progress = "Più resto qui, più mi viene la tentazione di partecipare a queste corse, $N. Roba da non credere...$B$BHai già trovato gli elisir? Appena potrò dire se l'uovo sarà in salute o no, te lo restituirò, così lo terrai tu finché non sarà pronto a schiudersi.$B$BFammi sapere.",
  reward = "Magnifico. Questi andranno benissimo. Dammi un momento per mescolare gli ingredienti e vedremo come se la caverà quest'uovo.",
}
T[3843] = {
  title = "Il Nuovo Arrivato in Famiglia",
  desc = "Un esemplare magnifico, $N. Se questa creatura sopravvive alla gestazione, sarà davvero un animale sano!$B$BC'è un'ultima cosa che ti suggerirei di fare, se hai intenzione di andare fino in fondo — va' ad Aerie Peak, nelle Hinterlands. Parla con un nano che si chiama Agnar Beastamer, un maestro nel trattare gli animali, che dovrebbe saperti guidare nelle ultime fasi dell'incubazione.$B$BMa sbrigati, $N, perché questo uovo è fragile e senza le cure giuste non durerà a lungo.",
  obj = "Porta il tuo Fragile Sprite Darter Egg nelle Hinterlands e parla con Agnar Beastamer, ma sbrigati, perché hai solo 1 ora per trovarlo prima che il piccolo dentro l'uovo muoia.",
  progress = "Salute, $N. Che posso fare per te?",
  reward = "Bene, bene, bene... Erano secoli che non ne vedevo uno. Un drago fatato, se non sbaglio... e sembra della varietà dei folletti sfreccianti. Ottimo, davvero ottimo.$B$BBe', se questo piccoletto deve nascere e crescere sano e forte, dovremmo procurargli un po' di cibo. Meno male che me l'hai portato in tempo.",
}
T[3844] = {
  title = "È un Segreto per Tutti",
  desc = "Una zattera distrutta giace lungo la riva. Dato che questo è solo un piccolo stagno, non è chiaro come sia finita qui, anche se a guardare gli alberi si direbbe che il livello dell'acqua non sia sempre lo stesso.$B$BForse esplorando un po' la zona potresti scoprire altri indizi...",
  obj = "Cerca nello stagno un indizio su chi possa essere il proprietario di questa zattera sfasciata.",
  reward = "Sul fondo dello stagno giace uno zaino zuppo d'acqua.",
}
T[3845] = {
  title = "È un Segreto per Tutti",
  desc = "Afferri lo zaino e lo trascini fino a riva. Forse, esaminando gli oggetti che contiene, potresti scoprire qualcosa di più sul suo proprietario.$B$BAl Rifugio dei Marshal c'è qualche viaggiatore sperduto. Forse là potresti scoprire qualcosa di più.",
  obj = "Esamina gli oggetti nello zaino e portali al loro proprietario.",
  progress = "Ciao. Ti ho già visto... Non è vero?",
  reward = "Oh... Sì, queste cose hanno un'aria familiare... be', più o meno...",
}
T[3881] = {
  title = "La Salvezza della Spedizione",
  desc = "Non so come tu abbia fatto ad arrivare fin qui, ma vederti è un sollievo! Sono Williden Marshal e guido una compagnia di spedizioni non schierata. La nostra ultima impresa, la più grande, è andata incontro a disastri che sembrano non finire mai, e il più grave è che abbiamo sottovalutato la ferocia di Un'Goro Crater!$B$BFuggendo dai nostri campi base nella parte sudoccidentale e in quella nordorientale del cratere, ci siamo lasciati indietro provviste indispensabili. Hai l'aria di chi è abbastanza in gamba — puoi aiutarci a recuperarle?",
  obj = "Porta una Crate of Foodstuffs e il Research Equipment a Williden Marshal a Un'Goro Crater.",
  progress = "Se vogliamo avere una qualche possibilità di uscire vivi da qui, ci serve la nostra grossa cassa di viveri. E poi, riavere almeno una parte dell'attrezzatura di ricerca sarebbe una benedizione in un mare di sventure.",
  reward = "Ci hai riportato sia i viveri SIA l'attrezzatura di ricerca! Non hai salvato soltanto la spedizione, hai salvato anche le nostre vite. Io e il resto della mia squadra non sapremo mai come ringraziarti; forse adesso ce la faremo a resistere qui per un po', grazie a te.$B$BNon abbiamo molto, ma di certo non ti lascerò a bocca asciutta dopo l'aiuto inestimabile che ci hai dato. Grazie, $N — hai un amico nella Marshal Expeditions!",
}
T[3882] = {
  title = "Tira i Dadi",
  desc = "Uno penserebbe che, se faccio il capo scavatore per la Marshal Expeditions, scavare mi piaccia. Ci saranno pure cose peggiori da fare a questo mondo... ma non me ne viene in mente nessuna.$B$BDovevamo scavare nella Landa del Terrore — nome FANTASTICO, fra l'altro — in cerca di stegodonti e diemetradonti morti. Be', là ce ne sono anche un sacco di vivi! Wil e Hol sono ancora tutti presi dallo studio di questa trappola mortale, quindi quelle ossa di dinosauro ci servono. Detto fra noi, però, andrà bene lo stesso se ne porti qualcuna presa da quelli vivi.",
  obj = "Porta 8 Dinosaur Bones a Spark Nilminer nell'Un'Goro Crater.",
  progress = "Pensa di me quello che vuoi, ma a loro non importerà se le ossa che avranno da studiare vengono da antichi stegodonti e diemetradonti o da quelli che per poco non ci hanno divorati tutti quanti mentre cercavamo di montare i campi. Io sarò contento anche solo se usciamo vivi da qui...",
  reward = "Eccellente, queste dovrebbero andare bene. E ora, se permetti...$B$BGRAZIE PER AVER DISSOTTERRATO PER NOI TUTTE QUESTE OSSA SENZA FARE ALCUN MALE ALLE BESTIE DEL POSTO.$B$BChe tu l'abbia fatto davvero oppure no, non lo voglio sapere. Lasciamo le cose così, d'accordo? Tieni — magari questo ti farà tenere la bocca chiusa su tutta la faccenda. Qualsiasi cosa pur di uscire vivi da qui, dico io!",
}
T[3883] = {
  title = "Ecologia Aliena",
  desc = "Aver subito una battuta d'arresto non vuol dire che la ricerca debba fermarsi! Prima di finire qui stavamo studiando gli insetti Gorishi, nella parte meridionale del cratere. La loro presenza è estranea all'ecologia di Un'Goro, e vogliamo scoprire perché.$B$BNella rete dei loro alveari devono esserci degli incubatoi di larve. Puoi riconoscere questi posti dalle covate di larve appese. Usa questa fiala per prelevare un campione della parete dell'alveare vicino a uno qualsiasi degli incubatoi. Riportamelo, così potrò studiarlo, ma fai attenzione!",
  obj = "Usa la Scraping Vial per raccogliere un Hive Wall Sample in uno degli incubatoi degli alveari Gorishi nell'Un'Goro Crater. Cerca le camere con le covate di larve appese.$B$BPorta l'Hive Wall Sample a Hol'anyee Marshal nell'Un'Goro Crater.",
  progress = "Hai il campione dell'alveare Gorishi da farmi studiare, $N?",
  reward = "Sì, questo andrà benissimo. Mi sei $Gstato:stata; di grande aiuto... Vorrei poterti dare di più, ma essere praticamente bloccata in mezzo a una terra selvaggia limita parecchio quello che posso e non posso dare. Sta' pur $Gcerto:certa;, però — senza il tuo aiuto la ricerca fatta qui non sarebbe stata possibile!",
}
T[3884] = {
  title = "Il Diario di Williden",
  desc = "Hai trovato un diario malridotto. Alcune parti sono ancora leggibili, e un certo Williden Marshal dichiara suo tutto ciò che contiene. Se il diario dice il vero, Williden potrebbe trovarsi da qualche parte nella zona settentrionale del Crater; stando al diario, lui e i suoi compagni hanno cercato rifugio più in alto per sfuggire alle bestie feroci del Crater, dopo che i loro campi base erano stati invasi.",
  obj = "Riporta il diario a Williden Marshal, da qualche parte nell'Un'Goro Crater.",
  progress = "Ehilà! Io e i miei compagni siamo felici di vedere qui qualche essere vivente che non sia una bestia feroce cresciuta a dismisura! Cosa ti porta nell'Un'Goro Crater?",
  reward = "Ma guarda un po' — il mio diario! Lo credevo perduto, come quasi tutto quello che abbiamo portato a Un'Goro. Ti ringrazio di cuore per avermelo riportato!",
}
T[3906] = {
  title = "Disarmonia della Fiamma",
  desc = "Gli anziani hanno percepito un turbamento fra gli elementi. I nani Dark Iron hanno evocato nel nostro mondo uno spirito immondo, che minaccia di affliggere le nostre terre con una siccità eterna. Bisogna indagare su questa disarmonia della fiamma.$B$BRaggiungi Blackrock Mountain e, attraverso la Voragine della Fiamma, entra nella cava. È lì che troverai questo signore del fuoco: il Maestro Supremo Pyron.$B$BPoni fine allo sconvolgimento e torna da me.",
  obj = "Raggiungi la cava a Blackrock Mountain e uccidi Overmaster Pyron. Torna da Thunderheart quando avrai portato a termine questo incarico.",
  progress = "Gli elementi sono ancora in subbuglio, $N.",
  reward = "Non può essere... non deve essere. La distruzione di Pyron ha soltanto sollevato un velo. Nelle profondità di Blackrock c'è una fonte di corruzione molto più insidiosa.",
}
T[3907] = {
  title = "Disarmonia del Fuoco",
  desc = "Sento il sapore dell'impurità nell'aria che ti circonda, $N. C'è un altro, nascosto nelle profondità di Blackrock, ed è lui a dominare questa impurità.$B$BIl vento e la terra gridano il suo nome: Lord Incendius... ma qualcuno... qualcosa... comanda questo essere. Lui è soltanto un emissario.$B$BTrovalo e scopri dove si nasconde il suo padrone. Torna da me quando avrai raccolto queste informazioni.",
  obj = "Entra nelle Blackrock Depths e scova Lord Incendius. Uccidilo e riporta a Thunderheart qualsiasi fonte di informazioni tu riesca a trovare.",
  progress = "Le fiamme invaderanno presto queste terre. Sbrigati, $N!",
  reward = "<Thunderheart stringe fra le mani la Tavoletta di Kurniya.>$B$BRagnaros... qui...$B$BGli anziani avevano ragione a temere la corruzione che emana dalla Blackrock Mountain. Un generale degli Dei Antichi! NEL NOSTRO MONDO! Dobbiamo riconsiderare la nostra posizione qui a Kargath. Dobbiamo decidere se restare e combattere o fuggire per paura di una nuova grande separazione.$B$BGuardati dall'esplorare ancora la Blackrock Mountain, $N. In quelle profondità infuocate dimora un male molto più grande di qualsiasi cosa esista in questo mondo.",
}
T[3908] = {
  title = "È un Segreto per Tutti",
  desc = "Vedi, non ho idea di come sono finito qui. Nessuno lo sa davvero — è un segreto per tutti! È che non riesco proprio a ricordare niente...$B$BQuesti oggetti che mi hai portato, però... Qualcosa mi sta tornando in mente.$B$BLa mia spada. Dovrei rinforzarla in qualche modo, ma non so proprio perché. Scusa se non so dirti di più, ma non me lo ricordo e basta!$B$BVabbè, comunque so dove puoi portarla — da Donova Snowden, a Winterspring. La troverai vicino alle sorgenti calde. Può temprare la spada presso le pozze che ci sono là.",
  obj = "Porta Linken's Training Sword a Donova Snowden, a Winterspring.",
  progress = "Ma guarda... Così Linken si è finalmente deciso a mandarmi la sua spada.",
  reward = "Ma certo che posso temprare questa spada. Mentre lavoro, puoi spiegarmi perché Linken ci ha messo tanto a farmela avere. Di solito non è uno che dimentica le cose...",
}
T[3909] = {
  title = "L'Elisir Videre",
  desc = "Ma cosa sento? Linken... ha DIMENTICATO?$B$BAh, capisco... Ha perso la memoria...$B$BBene, ecco la sua spada. Però non è completa. Conosco chi può finirla, ma... parlare con lui potrebbe rivelarsi difficile.$B$BAscolta, conosco qualcuno che potrà aiutarti. Ora sarebbe troppo lungo da spiegare, ma devi procurarti in qualche modo un Elisir Videre. Che io sappia, l'unico che può aiutarti in questo è Gregan Brewspewer. È difficile da rintracciare, ma l'ultima volta che ne ho avuto notizia era accampato nelle terre selvagge di Feralas.",
  obj = "Cerca Gregan Brewspewer nel nord di Feralas. Fatti spiegare da lui come procurarti il Videre Elixir, poi torna da Donova Snowden a Winterspring.",
  progress = "Già di ritorno?",
  reward = "Mi servirà una fiala per assicurarmi che questo sia davvero l'elisir... Sì... È proprio questo.",
}
T[3911] = {
  title = "L'Ultimo Elemento",
  desc = "C'è lavoro per chi si avventura nelle profondità, $N.$B$BI Dark Iron sono diventati maestri nel creare golem di potenza straordinaria.$B$BDai primi rapporti delle nostre spie risulta che i nani usano una fonte di energia unica nel suo genere per dare alle loro creazioni una capacità di uccidere senza pari.$B$BPensa solo a cosa potremmo fare con i nostri abomini, se mettessimo le mani su questa essenza degli elementi! Metti sottosopra quella città, se necessario, ma non tornare finché non avrai trovato l'essenza! Il compenso ripagherà il rischio.",
  obj = "Vai nelle Blackrock Depths e recupera 10 Essence of the Elements. Il tuo primo istinto è frugare i golem e i costruttori di golem. Ricordi che Shadowmage Vivian Lagrave ha borbottato anche qualcosa sugli elementali.",
}
T[3912] = {
  title = "Incontro alla Tomba",
  desc = "Questo elisir ti permetterà di parlare con qualcuno che di norma non riusciresti nemmeno a vedere...$B$BPorta l'elisir Videre, insieme alla spada di Linken, al cimitero appena fuori Gadgetzan, a Tanaris. Una volta là, bevi la pozione. Il risultato potrebbe sorprenderti parecchio, ma non allarmarti.$B$BNella tua \"altra\" forma, vai dritto a nord fino alle montagne. Troverai colui con cui devi parlare in uno dei crepacci fra le rocce. Si chiama Gaeriyan.$B$BRicorda, ti parlerà solo in quella forma...",
  obj = "Vai al cimitero fuori Gadgetzan e usa il Videre Elixir. Segui il resto delle istruzioni di Donova per trovare Gaeriyan.",
  reward = "È passato molto tempo dall'ultima volta che qualcuno è venuto a parlare con me...",
}
T[3913] = {
  title = "Una Situazione Grave",
  desc = "Se torni al cimitero, $N, vi troverai una lapide... Non una lapide qualsiasi; questa spicca fra le altre. Dentro si celano dei segreti.$B$BSpingi la pietra, e scoprirai questi segreti...",
  obj = "Torna in vita, poi cerca la lapide che Gaeriyan ti ha detto di trovare.",
  progress = "Dev'essere questa la lapide di cui parlava Gaeriyan...",
  reward = "Spingi con forza la pietra, che scivola via rivelando un piccolo incavo sotto di sé.$B$BAppoggi la Spada di Linken nell'incavo e ti accorgi che ci sta alla perfezione...",
}
T[3914] = {
  title = "La Spada di Linken",
  desc = "Dopo un forte lampo di luce, riesci a riprendere la spada. Si è trasformata!",
  obj = "Consegna Linken's Superior Sword a Linken nell'Un'Goro Crater.",
  progress = "Oh! Io mi ricordo di te! Tu sei... No, non dirmelo!",
  reward = "La mia spada... È finita!$B$BOra, se solo riuscissi a ricordare perché mi serviva...$B$BTieni, lascia almeno che ti paghi per il tuo lavoro.",
}
T[3941] = {
  title = "L'Aiuto di una Gnoma",
  desc = "Sto pensando... Sto pensando... So di essere venuto qui per qualcosa di importante...$B$BMi è venuta un'idea, $N. Nella grotta laggiù c'è una gnoma di nome J.D. che è stata molto gentile con me quando sono arrivato qui. Può darsi che, confuso com'ero, le abbia accennato qualcosa.$B$BPerché non vai a chiederle se sa qualcosa? Ah, ma fai attenzione — armeggia sempre con quegli assurdi cristalli luminosi che ho visto nel cratere. Non so bene cosa stia combinando là dentro!",
  obj = "Trova J.D. Collie nella grotta del Rifugio dei Marshal.",
  reward = "Resta dove sei solo un momento... Sto provando una nuova combinazione di cristalli...",
}
T[3942] = {
  title = "La Memoria di Linken",
  desc = "Oh... Linken? Sì, è un tipo curioso. Quando è arrivato qui borbottava cose strane di ogni genere. Avrà preso una bella botta in testa, immagino.$B$BUna cosa che ha detto però mi è rimasta in mente — che stava costruendo una specie di totem; diceva di dover parlare con qualcuno di nome Eridan Bluewind... in un posto chiamato Felwood, mi pare?$B$BDubito che adesso possa dirti granché, però. Se vuoi saperne di più, magari potresti cercare Eridan di persona?",
  obj = "Trova Eridan Bluewind nella parte meridionale di Felwood.",
  reward = "Salve, $C. Posso esserti d'aiuto in qualcosa?",
}
T[3961] = {
  title = "L'Avventura di Linken",
  desc = "E pensare che per tutto questo tempo Linken era qui proprio per liberarci di Blazerunner... Sembra un tipo così normale, ma in effetti ho notato che i miei esperimenti e i miei aggeggi non gli interessano affatto, al contrario di quasi tutti gli gnomi. In fondo al cuore dev'essere un vero guerriero.$B$BPortagli il totem. Vedi se lo aiuta a ricordare perché è venuto qui.",
  obj = "Porta il Silver Totem of Aquementas a Linken al Rifugio dei Marshal.",
  progress = "Ciao di nuovo, $N!",
  reward = "J.D. ti ha aiutato in qualche modo?",
}
T[3962] = {
  title = "È Pericoloso Andare da Soli",
  desc = "$N, finalmente ora ricordo... Ero venuto qui davvero per combattere Blazerunner. Ero in viaggio, e questa doveva essere l'ultima tappa.$B$BMa l'eroe non sono più io... Sei tu. Tutto quello che hai fatto — ora devi essere tu a finire quest'opera, non io.$B$BBlazerunner custodisce un artefatto chiamato Fiamma Dorata. Dà un potere più vasto di qualunque altra cosa io abbia mai conosciuto, ed è pericoloso nelle mani di chi ha un cuore malvagio.$B$BTi conviene portare altri con te — è pericoloso andare da $Gsolo:sola;. Prendilo come un mio consiglio.",
  obj = "Raggiungi Fire Plume Ridge, a sud del Rifugio di Marshal.$B$BTrova Blazerunner e usa il Silver Totem of Aquementas per rimuovere la sua aura protettiva. Una volta sconfitto, recupera la Golden Flame nella caverna.",
  progress = "Blazerunner è quasi invincibile dietro l'aura che ha creato usando la Fiamma Dorata. Solo tu hai il potere di rimuoverla con il Totem di Aquementas d'Argento.",
  reward = "Grazie, $N.$B$BOra la Fiamma Dorata tornerà nella mia terra natale, dove potrà essere protetta, per non essere mai più usata per il male.$B$BSenza di te, non avrei ancora idea di chi sono! Visto che hai fatto così tanto per me, vorrei che avessi qualcosa di speciale...$B$BPrendine uno, quello che vuoi!",
}
T[3981] = {
  title = "Comandante Gor'shak",
  desc = "Povero Gargal... non l'ha nemmeno vista arrivare. BAM! La freccia gli si è piantata in cima alla testa, in pieno centro. Un genio non lo era neanche prima, ma adesso...$B$B<Galamav fa una smorfia.>$B$BQuando abbiamo estratto la freccia, abbiamo notato un biglietto arrotolato legato all'asta. Sul biglietto c'era un rozzo disegno di un orco dietro le sbarre, accompagnato dalla firma del Comandante Gor'shak.$B$BSe è ancora vivo nelle Depths, dovrai trovarlo.$B$BUna trappola, dici? Ma non mi dire, testa di zoccolo! È per questo che ci vai tu!",
  obj = "Trova Commander Gor'shak nelle Blackrock Depths.$B$BRicordi che nel rozzo disegno dell'orco c'erano delle sbarre tracciate sopra il ritratto. Forse dovresti cercare una prigione di qualche tipo.",
  reward = "Non abbiamo molto tempo. Ascolta bene, $R. Quello che sto per dirti è riservato, ed è solo per le tue orecchie.",
}
T[3982] = {
  title = "Che Sta Succedendo?",
  desc = "Sono stato mandato qui per volere di Thrall. Credi davvero che questi buffoni potessero catturarmi? Mi sono lasciato catturare io, per raccogliere informazioni.$B$B<Gor'shak sussurra.>$B$BLa Principessa di Ironforge è stata rapita dall'Imperatore Thaurissan. La Principessa Bronzebeard è proprio in questa città! Scommetto che al vecchio Magni si è quasi fermato il cuore, quando ha saputo la notizia.$B$B<Gor'shak ride.>$B$BShhh! Lo senti? Arrivano le guardie! DIFENDITI!",
  obj = "Difendi Commander Gor'shak.",
  progress = "Difenditi, $Gsciocco:sciocca;!",
  reward = "C'è mancato poco. Ormai sanno che sei qui... ne arriveranno di sicuro altri.",
}
T[4001] = {
  title = "Che Sta Succedendo?",
  desc = "Finora i miei contatti con il nano Kharan, nella cella dall'altra parte del corridoio, sono stati limitati. Sono riuscito comunque a convincerlo che io, anzi -noi- non vogliamo fargli alcun male.$B$BVai a parlare con lui e raccogli più informazioni possibile sulla Principessa e sui suoi rapitori. Porta quelle informazioni al Capoguerra.$B$BThrall non vuole che alla Principessa sia fatto del male, anzi, ha in serbo un grande piano che prevede il suo ritorno a Ironforge sana e salva. Kharan sa già tutto questo... Vai!",
  obj = "Parla con Kharan Mighthammer e raccogli informazioni sul rapimento di Princess Moira Bronzebeard. Porta quelle informazioni a Thrall a Orgrimmar.$B$BRicordi che Commander Gor'shak ha detto che Kharan Mighthammer è rinchiuso in una cella lì vicino.",
  progress = "Cosa ti porta su questo suolo sacro?",
  reward = "Per l'Orda questa è l'occasione di cambiare per sempre il clima politico del nostro mondo devastato dalla guerra. Ascolta bene, $N.$B$BIn questa missione non possiamo permetterci di fallire.",
}
T[4002] = {
  title = "Gli Eastern Kingdoms",
  desc = "Le informazioni che porti sono eccellenti, $N.$B$BCome Capoguerra, è mio dovere fare ciò che è meglio per l'Orda. Fare in modo che le generazioni che verranno dopo di noi non siano costrette a un'esistenza senza speranza.$B$BL'occasione di plasmare le nostre alleanze future ci è capitata fra le mani, a tutti noi. Una mossa in aiuto dei nani potrebbe rafforzare di molto i nostri rapporti negli Eastern Kingdoms. Ecco, dunque, perché non devi fallire!$B$BSei $Gpronto:pronta;?",
  obj = "Parla con Thrall se sei $Gpronto:pronta; ad affrontare la missione che ha in mente.",
  reward = "Da qui in poi non si torna indietro, $N.",
}
T[4003] = {
  title = "Il Salvataggio Reale",
  desc = "Questo attacco contro i nani Dark Iron, se avrà successo, propagherà un'onda d'urto in tutto il loro regno.$B$BLa Principessa Bronzebeard è sotto il controllo dell'Imperatore Thaurissan. Per liberarla devi uccidere l'Imperatore. Bada, il tuo compito è doppiamente pericoloso, perché Bronzebeard, finché sarà sotto il controllo dell'Imperatore, ti attaccherà senza esitare.$B$BNON FARLE DEL MALE!",
  obj = "Uccidi Emperor Dagran Thaurissan e libera Princess Moira Bronzebeard dal suo malvagio incantesimo.",
  progress = "<La Principessa Moira si rannicchia per la paura.>",
  reward = "Che cosa hai fatto!",
}
T[4004] = {
  title = "La Principessa È Salva?",
  desc = "Hai ucciso mio marito, $R! Mio figlio verrà al mondo senza un padre.$B$B<La Principessa Moira punta il dito dritto contro di te.>$B$BTe lo assicuro, questo bambino sarà il prossimo sovrano del regno di Ironforge. Per questo atto ingiusto tu e i tuoi simili sarete braccati fino alla fine dei giorni.$B$B<Pensi che la Principessa Moira possa essere sotto l'effetto residuo dell'incantesimo di Thaurissan.>$B$BLasciami in pace, $R. Sono certa che il tuo capoguerra sarà impaziente di sapere cosa ha prodotto la sua ingerenza.",
  obj = "Torna da Thrall!",
  reward = "<Thrall è sbigottito dalle informazioni che gli hai riferito.>$B$BUna nuova minaccia si profila all'orizzonte. Quando gli anni di Magni volgeranno al termine, si aprirà la strada perché questo Dark Iron non ancora nato diventi sovrano di Ironforge.$B$BHai portato a termine ciò che ti avevo chiesto e per questo sarai $Gricompensato:ricompensata;.$B$BOra lasciami, $N! Devo consultarmi con Sylvanas e Cairne.",
}
T[4005] = {
  title = "Aquementas",
  desc = "Porta con te a Tanaris questa sacca di provviste. Raggiungi la Cala del Sartiame e cerca un cerchio di pietre.$B$BIl segreto è la penisola più a oriente...$B$BSoltanto da quel cerchio, leggi dal libro di Aquor; evoca l'unica creatura capace di trasformare gli oggetti che hai raccolto in un totem per combattere Blazerunner.$B$BAd Aquementas non farà piacere essere svegliato, ma ricorda, devi restare nel cerchio perché lui trasformi gli oggetti.",
  obj = "Porta il Book of Aquor, i Silvery Claws e l'Irontree Heart a Tanaris.$B$BUsa il Book of Aquor per evocare Aquementas.$B$BQuando avrai il totem completo, portalo a J.D. Collie al Rifugio dei Marshal.",
  progress = "Allora sei $Gtornato:tornata;, eh? Mmm... Fammi dare un'occhiata, $N.",
  reward = "Blazerunner, dici...$B$BSì, so che nel centro carbonizzato del cratere risiede un elementale molto forte. Noi ce ne teniamo tutti alla larga e basta; nessuno è riuscito a penetrare la potente aura che lo circonda. Molti, cercando di affrontarlo, sono stati spinti giù dai sentieri rocciosi fino al suolo sottostante.",
}
T[4022] = {
  title = "Un Assaggio di Fiamma",
  desc = "Lo stormo è al corrente del tuo operato nella Searing Gorge.$B$BMostramela, $R. La muta, imbecille.",
  obj = "Mostra a Cyrus Therepentous la Black Dragonflight Molt che hai ricevuto da Kalaran Windblade.",
  progress = "<Gli occhi di Cyrus diventano due sfere fiammeggianti.>",
  reward = "<Cyrus esamina la muta.>$B$BHai dimostrato di non essere del tutto inutile, mortale.",
}
T[4023] = {
  title = "Un Assaggio di Fiamma",
  desc = "Cerchi il Flight? Mostrami una prova del tuo valore, mortale.",
  obj = "Mostra a Cyrus Therepentous una prova del tuo valore.$B$BHai la sensazione che Cyrus sappia già che non ne sei $Gdegno:degna;.",
  progress = "<Gli occhi di Cyrus diventano due sfere fiammeggianti.>",
  reward = "<Cyrus esamina la muta.>$B$BHai dimostrato di non essere del tutto inutile, mortale.",
}
T[4024] = {
  title = "Un Assaggio di Fiamma",
  desc = "Voglio assaporare le fiamme brucianti della montagna di fuoco. Lasciare che i fuochi liquidi di Blackrock si riversino su tutto il mio essere. Quell'essenza, quel calore bruciante, è ciò che bramo.$B$BBael'Gar dimora nelle Depths di Blackrock: un essere di pura fiamma, nato dai fuochi di Ragnaros. Uccidi Bael'Gar e dai suoi resti fumanti portami un frammento del suo fuoco interiore.$B$BUsa la muta sui suoi resti per estrarre senza pericolo la fiamma interiore.$B$BRiesci nell'impresa e sarai $Gricompensato:ricompensata;.",
  obj = "Vai nelle Blackrock Depths e uccidi Bael'Gar.$B$BSai soltanto che il gigante si trova dentro le Blackrock Depths. Ricordati di usare l'Altered Black Dragonflight Molt sui resti di Bael'Gar per catturare l'Encased Fiery Essence.$B$BRiporta l'Encased Fiery Essence a Cyrus Therepentous.",
  progress = "Il gigante è stato abbattuto?",
  reward = "<Cyrus ti strappa di mano l'essenza ardente.>$B$BSÌ!$B$BPrendi il tuo premio e vattene. Sparisci subito dalla mia vista!",
}
T[4041] = {
  title = "L'Elisir Videre",
  progress = "Portami un Evoroot e certo, posso prepararti quell'Elisir Videre.$B$BSo un sacco di cose su erbe e alchimia... Anzi, lascia che ti racconti di quella volta che ho trasmutato in oro il formaggio che stavo per mangiare a pranzo... ehi... Dove vai?",
  reward = "Allora, gliel'hai fatta sotto il naso al vecchio Miblon, eh?",
}
T[4061] = {
  title = "L'Ascesa delle Macchine",
  desc = "Le macchine si sono manifestate durante le nostre prime incursioni nella Searing Gorge. Indagando più a fondo abbiamo scoperto che venivano importate dalle Burning Steppes, forse da Blackrock Depths. È per questo che abbiamo bisogno di te, $N.$B$BIl tuo primo compito è recarti nelle Burning Steppes e recuperare delle schegge elementali dagli automi di roccia e dalle creazioni di roccia minori della regione. Quando ne avrai raccolte a sufficienza, torna da me e ne stabilirò l'origine.",
  obj = "Recati nelle Burning Steppes e recupera 10 Fractured Elemental Shards per Hierophant Theodora Mulvadania.$B$BRicordi che Theodora ha indicato i golem e gli elementali di quella regione come fonte di queste schegge.",
  progress = "Non prendere questo compito alla leggera, $N!",
  reward = "<Theodora dispone i frammenti davanti a sé.>$B$B<Theodora esamina con attenzione i frammenti con un monocolo enorme.>$B$BInteressante. Incise nella struttura portante di ciascuno di questi frammenti ci sono... delle iniziali.",
}
T[4062] = {
  title = "L'Ascesa delle Macchine",
  desc = "G.L.A.$B$BSono queste le \"iniziali\" impresse sulle schegge elementali. Sotto le iniziali c'è una specie di segno di grado. Le macchine che hai distrutto nelle Burning Steppes erano di \"Grado IV\". Presumo che sia un grado basso.$B$BPorta questo campione di scheggia a Lotwil Veriatus, nell'accampamento a est. È uno studioso di una certa fama nel campo delle scienze elementali. Potrebbe aiutarci nella nostra ricerca.",
  obj = "Porta l'Elemental Shard Sample a Lotwil Veriatus.$B$BRicordi che Theodora ha detto che Lotwil si trovava in un accampamento a est.",
  progress = "Cos'hai lì, $R?",
  reward = "<Lotwil sbianca in volto.>$B$BIo... io conosco questi segni.",
  en_title = "The Rise of the Machines",
  en_obj = "Take the Elemental Shard Sample to Lotwil Veriatus.$B$BYou recall Theodora saying that Lotwil was stationed in a camp to the east.$B",
}
T[4063] = {
  title = "L'Ascesa delle Macchine",
  desc = "Non può essere Argelmach! Argelmach è stato ucciso dieci anni fa. Come faccio a esserne sicuro? Sono stato io a ucciderlo.$B$BEra un nano spregevole, deciso a ogni costo a stravolgere il lavoro di tutta la mia vita per i suoi scopi diabolici. A quanto pare i malvagi trovano sempre il modo di sfuggire alla giustizia.$B$BSe questa è opera di Argelmach, allora va distrutto. Mi serviranno dei campioni delle sue ultime creazioni. Con i campioni giusti potrei riuscire a fermare questa rivolta. Le creazioni fanno la guardia ad Argelmach nelle Blackrock Depths.",
  obj = "Trova e uccidi Golem Lord Argelmach. Riporta la sua testa a Lotwil Veriatus. Dovrai anche raccogliere 10 Intact Elemental Cores dai Ragereaver Golems e dai Warbringer Constructs che proteggono Argelmach. Lo sai perché sei $Gun sensitivo:una sensitiva;.",
  progress = "Era lui? Era vivo davvero?",
  reward = "E questo cos'è?!? Questa testa non è di carne. È una qualche creazione di ferro scuro: un'ombra di Argelmach — UN'ALTRA macchina! Hai distrutto Argelmach, ma sospetto che durerà poco, perché presto un altro sorgerà a prendere il 'suo' posto.",
}
T[4081] = {
  title = "UCCIDERE A VISTA: Nani Dark Iron",
  desc = "Per ordine del Signore della Guerra Goretooth, comandante della Kargath Expeditionary Force:$B$BTutte le forze del Generale Angerforge presenti nelle Blackrock Depths, nessuna esclusa, devono essere annientate.$B$BGli uomini di Angerforge sono assassini spietati, responsabili del massacro della 109ª divisione della Kargath Expeditionary Force. Si avvertono gli eroi di usare la massima prudenza nell'affrontare questi bruti.$B$BChiunque distrugga la prima linea delle forze del Generale Angerforge nelle Blackrock Depths riceverà un tributo.",
  obj = "Avventurati nelle Blackrock Depths e distruggi i vili aggressori!$B$BWarlord Goretooth vuole che tu uccida 15 Anvilrage Guardsmen, 10 Anvilrage Wardens e 5 Anvilrage Footmen. Torna da lui quando avrai portato a termine il compito.",
  progress = "Che c'è, $R? Non vedi che ho un plotone da comandare?",
  reward = "Questo primo colpo dovrebbe far saltare la mosca al naso ad Angerforge. E ora circolare, soldato. Ho lavoro da finire, battaglie da pianificare, nemici da schiacciare!$B$BControlla i manifesti dei ricercati per altro lavoro.",
}
T[4082] = {
  title = "UCCIDERE A VISTA: Alti Ufficiali Dark Iron",
  desc = "Per ordine del Signore della Guerra Goretooth, comandante della Kargath Expeditionary Force:$B$BIl capo della divisione di ricognizione della K.E.F., il Gran Maestro Lexlort, è tornato con notizie su dove si trovano gli alti ufficiali Dark Iron. Oltre il cancello sbarrato, vicino al cuore della città, addestrano le loro forze per sterminare i nostri uomini. Vai nelle Blackrock Depths e distruggili!$B$BChi porterà a termine questa missione riceverà un tributo.",
  obj = "Avventurati nelle Blackrock Depths e distruggi i vili aggressori!$B$BWarlord Goretooth vuole che tu uccida 10 Anvilrage Medics, 10 Anvilrage Soldiers e 10 Anvilrage Officers. Torna da lui quando avrai portato a termine il compito.",
  progress = "Ancora tu? Devo riconoscertelo, $N, sei tenace.",
  reward = "Angerforge è senza dubbio... arrabbiato. Torna da me quando avrai ricevuto un terzo tributo, e daremo il via all'Operazione: Morte ad Angerforge. Non posso entrare nei dettagli di cosa comporta, ma ti assicuro che di mezzo c'è qualcuno che muore.",
}
T[4083] = {
  title = "Il Calice Spettrale",
  progress = "Il calice spettrale fluttua nell'aria, alzandosi e abbassandosi lentamente... come al ritmo di un cuore morente.",
  reward = "Le gemme non fanno alcun rumore cadendo nelle profondità del calice...",
}
T[4084] = {
  title = "Cuore d'Argento",
  desc = "Non conosco colui di cui parli, $N.$B$BMa non temere; se il tuo amico era in viaggio per trovarmi, so bene che cosa desiderava.$B$BNel cuore di Un'Goro Crater dimora il male nella sua forma più pura. Questo male prende la forma di un elementale chiamato Blazerunner... protetto da un'aura che nessuno può dissolvere...$B$BNessuno... tranne chi ha abbastanza potere per farlo. Posso istruirti su questo potere, $N.$B$BPrima, fa' come ti chiedo. Raccogli 11 Artigli Argentei e 1 Cuore di Irontree dalle creature di Felwood, poi torna.",
  obj = "Raccogli 11 Silvery Claws e 1 Irontree Heart per Eridan Bluewind a Felwood.",
  progress = "Posso dirti di più sul potere necessario per sconfiggere Blazerunner, ma prima devi procurarti le cose che mi servono.",
  reward = "Molto bene, $N. Vedo che ci tieni davvero ad aiutare il tuo amico.",
}
T[4101] = {
  title = "Purificare Felwood",
  desc = "Le piante danno vita a Felwood, eppure anche loro patiscono la corruzione. Conosco dei modi per purificarle, ma non posso affidare questo sapere a persone che non conosco o di cui non mi fido. Dimostrami che aiuterai davvero la causa del Cenarion Circle!$B$BA nord ci sono le Caverne di Irontree. Per gli elementali Warpwood che vi si trovano non c'è più speranza di purificazione. Ti chiedo di portarmi la loro linfa — ambra sanguigna, la chiamano — così potrò studiarla nella speranza di salvare altre forme di vita di questa terra.",
  obj = "Porta 15 Blood Amber ad Arathandris Silversky a Felwood.",
  progress = "Lo so che Felwood soffre, $N — soffro anch'io con lei! Devo restare salda nella mia convinzione; se il sapere che possiedo finisse nelle mani sbagliate, sarebbe un disastro per tutta Felwood.$B$BPortami l'ambra sanguigna estratta dagli elementali Warpwood uccisi, e avrò abbastanza fiducia in te da farmi aiutare a mettere in atto un modo per combattere la corruzione.",
  reward = "Quest'ambra sanguigna servirà a trovare un modo per sconfiggere la corruzione che c'è a Felwood. Mi hai dimostrato di essere $Gdisposto:disposta; a tutto per il Cenarion Circle. Ora mi fido di te, $Gamico:amica;.$B$BPuò sembrare strano che tu mi abbia dato prova di te uccidendo gli elementali, ma il fine di salvare innumerevoli esseri senzienti deve giustificare i mezzi che usiamo. Ora tu e io possiamo dedicarci a preservare la vita con gli unguenti che so preparare.$B$B$N, è giunto il momento di purificare Felwood.",
}
T[4102] = {
  title = "Purificare Felwood",
  desc = "Le piante danno vita a Felwood, eppure anche loro patiscono la corruzione. Conosco dei modi per purificarle, ma non posso affidare questo sapere a persone che non conosco o di cui non mi fido. Dimostrami che aiuterai davvero la causa del Cenarion Circle!$B$BA nord ci sono le Caverne di Irontree. Per gli elementali Warpwood che vi si trovano non c'è più speranza di purificazione. Ti chiedo di portarmi la loro linfa — ambra sanguigna, la chiamano — così potrò studiarla nella speranza di salvare altre forme di vita di questa terra.",
  obj = "Porta 15 Blood Amber a Maybess Riverbreeze a Felwood.",
  progress = "Lo so che Felwood soffre, $N — soffro anch'io con lei! Devo restare salda nella mia convinzione; se il sapere che possiedo finisse nelle mani sbagliate, sarebbe un disastro per tutta Felwood.$B$BPortami l'ambra sanguigna estratta dagli elementali Warpwood uccisi, e avrò abbastanza fiducia in te da farmi aiutare a mettere in atto un modo per combattere la corruzione.",
  reward = "Quest'ambra sanguigna servirà a trovare un modo per sconfiggere la corruzione che c'è a Felwood. Mi hai dimostrato di essere $Gdisposto:disposta; a tutto per il Cenarion Circle. Ora mi fido di te, $Gamico:amica;.$B$BPuò sembrare strano che tu mi abbia dato prova di te uccidendo gli elementali, ma il fine di salvare innumerevoli esseri senzienti deve giustificare i mezzi che usiamo. Ora tu e io possiamo dedicarci a preservare la vita con gli unguenti che so preparare.$B$B$N, è giunto il momento di purificare Felwood.",
}
T[4103] = {
  title = "Unguento con la caccia",
  progress = "Chi possiede un rilevatore Cenarion può vedere un frammento d'anima corrotto sulle bestie contaminate che vengono abbattute per il bene superiore. Io macino i frammenti fino a farne un reagente utilizzabile, che serve a preparare l'unguento per piante Cenarion. Con quell'unguento faremo tornare sane le piante corrotte.$B$BIn cambio di questi frammenti ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora, ecco i tuoi unguenti per piante Cenarion. Setaccia Felwood in cerca di piante corrotte, $N! Ovunque siano, usa l'unguento che ti ho dato per purificarle.",
}
T[4104] = {
  title = "Unguento con l'estrazione mineraria",
  progress = "Se hai con te un rilevatore Cenarion mentre estrai minerali a Felwood, potrai vedere il vetriolo corrotto che contamina una vena di metallo grezzo. Io so come purificare quel vetriolo e trasformarlo in un reagente che serve a preparare l'unguento per piante Cenarion. Poi userai quell'unguento sulle piante da salvare che troverai in natura.$B$BSe hai raccolto del vetriolo corrotto, ti darò un po' di unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora, ecco un po' di unguento per piante Cenarion. Se trovi altro vetriolo quando estrai minerali a Felwood, ricordati di tenerlo da parte per me! Più ne trovi, più unguento potrò preparare.",
}
T[4105] = {
  title = "Unguento con la raccolta",
  progress = "Un rilevatore Cenarion permette a un erborista esperto di individuare l'insidiosa vilerba — un prodotto malefico della corruzione di Felwood. Il mio lavoro qui mi ha insegnato a purificare la vilerba fino a farne un reagente per la purificazione... usato in quello che ormai chiamiamo unguento per piante Cenarion.$B$BQuando raccogli erbe a Felwood, dovresti imbatterti nella vilerba, purché tu abbia il rilevatore. In cambio di quella che mi porti ti darò dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — ogni singolo pezzetto, una volta purificato, ci aiuterà a riprenderci Felwood. Tieni, prendi qualche dose di unguento per piante Cenarion e va' nella foresta. La riconquista della terra dalla corruzione non aspetta $Gun:una; $R!",
}
T[4106] = {
  title = "Unguento con la scuoiatura",
  progress = "Un rilevatore Cenarion permette a uno scuoiatore ben addestrato di individuare i lembi di pelle corrotta nel bottino raccolto a Felwood. Io trasformo questi lembi in apparenza inutili in una pasta densa che fa da accelerante per l'unguento per piante Cenarion. Quando scuoi le bestie che uccidi qui a Felwood, assicurati di avere con te un rilevatore!$B$BQuando raccogli dei lembi corrotti, portameli e ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "È proprio quello che mi serve. Tieni — prendi questi unguenti per piante e usali per strappare Felwood alla corruzione. Dobbiamo perseverare, $N!",
}
T[4107] = {
  title = "Unguento con il disincantamento",
  progress = "Il potere di un oggetto magico disincantato si avverte nell'essenza che crea. Ho escogitato un modo per trasformare l'essenza grezza usata dagli incantatori in un reagente adatto a creare l'unguento per piante Cenarion. Per questo non ti serve un rilevatore Cenarion; va bene qualunque oggetto disincantato a dovere che dia essenze inferiori del nether.$B$BMi basta una sola essenza inferiore del nether; in cambio ti darò degli unguenti per piante Cenarion. L'essenza è potentissima — ne basta davvero poca per fare tanto!",
  reward = "Ecco alcuni unguenti per piante Cenarion — per questo mi basta una sola essenza inferiore del nether, $N. L'essenza è di gran lunga la cosa più potente di cui possa servirmi per trasformare le spade in vomeri, per così dire. Se ti serve altro unguento, mi trovi qui!",
}
T[4108] = {
  title = "Unguento con la caccia",
  progress = "Chi possiede un rilevatore Cenarion può vedere un frammento d'anima corrotto sulle bestie contaminate che vengono abbattute per il bene superiore. Io macino i frammenti fino a farne un reagente utilizzabile, che serve a preparare l'unguento per piante Cenarion. Con quell'unguento faremo tornare sane le piante corrotte.$B$BIn cambio di questi frammenti ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora, ecco i tuoi unguenti per piante Cenarion. Setaccia Felwood in cerca di piante corrotte, $N! Ovunque siano, usa l'unguento che ti ho dato per purificarle.",
}
T[4109] = {
  title = "Unguento con l'estrazione mineraria",
  progress = "Se hai con te un rilevatore Cenarion mentre estrai minerali a Felwood, potrai vedere il vetriolo corrotto che contamina una vena di metallo grezzo. Io so come purificare quel vetriolo e trasformarlo in un reagente che serve a preparare l'unguento per piante Cenarion. Poi userai quell'unguento sulle piante da salvare che troverai in natura.$B$BSe hai raccolto del vetriolo corrotto, ti darò un po' di unguento per piante Cenarion che ho già preparato.",
  reward = "Molto bene, allora, ecco un po' di unguento per piante Cenarion. Se trovi altro vetriolo quando estrai minerali a Felwood, ricordati di tenerlo da parte per me! Più ne trovi, più unguento potrò preparare.",
}
T[4110] = {
  title = "Unguento con la raccolta",
  progress = "Un rilevatore Cenarion permette a un erborista esperto di individuare l'insidiosa vilerba — un prodotto malefico della corruzione di Felwood. Il mio lavoro qui mi ha insegnato a purificare la vilerba fino a farne un reagente per la purificazione... usato in quello che ormai chiamiamo unguento per piante Cenarion.$B$BQuando raccogli erbe a Felwood, dovresti imbatterti nella vilerba, purché tu abbia il rilevatore. In cambio di quella che mi porti ti darò dell'unguento per piante Cenarion già pronto.",
  reward = "Ottimo lavoro, $N — ogni singolo pezzetto, una volta purificato, ci aiuterà a riprenderci Felwood. Tieni, prendi qualche dose di unguento per piante Cenarion e va' nella foresta. La riconquista della terra dalla corruzione non aspetta $Gun:una; $R!",
}
T[4111] = {
  title = "Unguento con la scuoiatura",
  progress = "Con un rilevatore Cenarion, uno scuoiatore esperto riesce a scorgere lembi di pelle corrotta nel bottino raccolto a Felwood. Io trasformo questi lembi, in apparenza inutili, in una pasta densa che fa da catalizzatore per l'unguento per piante Cenarion. Quando scuoi le tue prede qui a Felwood, assicurati di avere con te un rilevatore!$B$BQuando avrai raccolto dei lembi corrotti, portameli e ti darò alcuni unguenti per piante Cenarion che ho già preparato.",
  reward = "È proprio quello che mi serve. Ecco — prendi questi unguenti per piante e usali per strappare Felwood alla corruzione. Dobbiamo perseverare, $N!",
}
T[4112] = {
  title = "Unguento con il disincantamento",
  progress = "Il potere di un oggetto magico disincantato si avverte nell'essenza che produce. Ho trovato il modo di trasformare l'essenza grezza usata dagli incantatori in un reagente adatto a creare l'unguento per piante Cenarion. Per questo non ti serve un rilevatore Cenarion; va bene qualsiasi oggetto che, disincantato a dovere, dia essenze inferiori del nether.$B$BMi basta una sola essenza inferiore del nether; in cambio ti darò degli unguenti per piante Cenarion. L'essenza è potentissima — con poca si fa davvero tanto!",
  reward = "Ecco alcuni unguenti per piante Cenarion — per questi mi basta una sola essenza inferiore del nether, $N. L'essenza è di gran lunga l'oggetto più potente di cui possa servirmi per trasformare le spade in vomeri, per così dire. Se ti serve altro unguento, mi trovi qui!",
}
T[4113] = {
  title = "Songflower Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di songflower. La pianta emana un odore pungente e malsano. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion sul songflower. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
