T[4117] = {
  title = "Radice Sferzante Corrotta",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di radice sferzante. Le radici visibili sembrano dure e coriacee, e dalla pianta pende una pellicola viscida. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi 3 Unguenti per Piante Cenarion sulla Radice Sferzante. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
