T[4119] = {
  title = "Drago Notturno Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di drago notturno. I frutti che pendono dalla pianta sembrano marci e velenosi. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi 4 Unguenti per Piante Cenarion sul Drago Notturno. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4120] = {
  title = "La Forza della Corruzione",
  desc = "Da cacciatore, cerco di imitare i punti di forza che vedo nei miei avversari. Si può volgere una battaglia a proprio favore semplicemente conoscendo bene il nemico, $N.$B$BIn un luogo chiamato Felwood, a nord di Ashenvale, le creature sono state contaminate da una sostanza chiamata fel. Orsi e lupi ne sono impazziti, ma credo che siano anche diventati ancora più forti.$B$BVa', $N. Raggiungi Felwood e affronta queste bestie. Scopri con i tuoi occhi se sono davvero forti come credo.",
  obj = "Talo Thornhoof di Camp Mojache, a Feralas, vuole che tu uccida 12 Angerclaw Grizzlies e 12 Felpaw Ravagers a Felwood.",
  progress = "Tutto ciò che il fel ha toccato emana uno strano bagliore verde... Sento che è malvagio, ma al tempo stesso molto potente.",
  reward = "Da quello che mi racconti, sembra che le creature mostrino una ferocia cieca...$B$BResta all'erta, $N. Ti conviene saperne di più sulla corruzione. Conosci sempre il tuo nemico.",
}
T[4121] = {
  title = "Situazione Precaria",
  desc = "Credi davvero di arrivare al punto d'incontro con me prigioniero? Ti aspettavi sul serio di irrompere in una roccaforte dei Blackrock pesantemente difesa e catturare una loro risorsa preziosa senza mettere in allarme niente e nessuno?$B$BSarai $Gdistrutto:distrutta;!",
  obj = "Scorta il tuo prigioniero, Grark Lorkrub, attraverso le Burning Steppes e la Blackrock Mountain fino alla Searing Gorge.$B$BRicordi che Lexlort aveva detto che i suoi uomini avrebbero aspettato dall'altra parte per prendere in custodia Grark.$B$BDovrai anche consegnare a Lexlort le tue Thorium Shackles.",
  progress = "Questo lurido traditore lo prendo io, $N.",
  reward = "Il tuo eroismo non resterà senza riconoscimento, $N. Ti sei $Gguadagnato:guadagnata; questo tributo. Ora il Signore della Guerra ti parlerà dell'ultima missione.",
}
T[4122] = {
  title = "Grark Lorkrub",
  desc = "L'ho seguito per tutta la Searing Gorge, attraverso la montagna e fin dentro le Burning Steppes. Quel traditore è stato colto in flagrante mentre passava agli orchi Blackrock informazioni vitali sulle nostre operazioni quotidiane. Parlo di Grark Lorkrub.$B$BAdesso se ne sta nelle Burning Steppes, al sicuro sotto la loro protezione — o così crede lui.$B$BPrendi queste manette, $N. Trova Grark, mettigliele e conducilo attraverso la Blackrock Mountain. Fallo e avrai un tributo.",
  obj = "Vai nelle Burning Steppes e trova Grark Lorkrub. Ricordi che Lexlort aveva detto che è stato visto l'ultima volta in un'enorme fortezza dei Blackrock.$B$BQuando trovi Grark Lorkrub, usa le Thorium Shackles per ammanettarlo e poi riportalo attraverso la Blackrock Mountain fino alla Searing Gorge. Gli uomini di Lexlort aspetteranno dall'altra parte per prendere in custodia Grark.",
  reward = "Non vedi quanto potere otteniamo unendoci alla legione di Blackrock?",
}
T[4123] = {
  title = "Il Cuore della Montagna",
  desc = "Sono anni che cerco una certa gemma. Si chiama Cuore della Montagna ed è grossa come il tuo pugno! I nani Dark Iron la tengono chiusa nella loro camera blindata e, per quanto ci provi, non me la lasciano comprare.$B$BQuindi devo ricorrere alla forza.$B$BApriti la strada combattendo fino alla Camera Blindata Inferiore delle Blackrock Depths, forza la cassaforte segreta e prendi il Cuore. Per riuscirci devi sconfiggere il Sorvegliante Doomgrip, che non comparirà finché non avrai aperto tutti gli scrigni delle reliquie della camera!$B$BBuona fortuna.",
  obj = "Porta The Heart of the Mountain a Maxwort Uberglint nelle Burning Steppes.",
  progress = "Hai il Cuore della Montagna? Per me ha un valore senza limiti.",
  reward = "Hai il cuore! Incredibile! È ancora più bello di come l'immaginavo!$B$BTi prego, $N, prendi questo come pagamento!",
}
T[4124] = {
  title = "Il Corriere Scomparso",
  desc = "Un mio collega, Ginro Hearthkindle, cerca aiuto per ritrovare un corriere e i pacchi che portava. È passata una settimana circa da quando il corriere è scomparso; le nostre ricerche non hanno dato frutti, e siamo a un punto morto. Purtroppo ho dovuto dichiarare il corriere disperso in azione.$B$BSe hai tempo e risorse da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui nella Stronghold, forse nei suoi alloggi.",
  obj = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.",
  reward = "Ti manda Latro, immagino. Anche se a questo punto credo sia una causa persa, accetterò qualunque aiuto tu possa offrire. Devo ammetterlo... sarò contento quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno a mani vuote, con nient'altro che denti di gnoll e delusione.",
  en_title = "The Missing Courier",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4125] = {
  title = "Il Corriere Scomparso",
  desc = "È passata circa una settimana da quando Raschal, il corriere, è partito per Thalanaar. Conosce bene Feralas; è con noi da quando il Generale Feathermoon ha guidato qui il corpo di spedizione. So che il suo piano era prendere una barca a remi, scendere lungo la costa e poi provare ad attraversare il sud di Feralas per evitare il campo dell'Orda.$B$BIo non sono riuscito a trovare la sua barca, ma forse tu ci riuscirai. Forse è nascosta, o forse è affondata. In ogni caso, potrebbe contenere un indizio su dove si trova lui. Se scopri qualcosa, fammelo sapere.",
  obj = "Trova la barca del corriere da qualche parte lungo la costa di Feralas.",
  reward = "Hai trovato quella che sembra una barca a remi naufragata. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano la fiancata di babordo; la barca è quasi ridotta alla sua semplice ossatura di legno. Qualunque cosa l'abbia distrutta, molto probabilmente ha cercato di spezzarla in due. Sulla fiancata di tribordo è dipinto un piccolo stemma della Feathermoon Stronghold.$B$BNel fango, alla base della barca, qualcosa di metallico ti cattura lo sguardo con un luccichio...",
  en_title = "The Missing Courier",
  en_obj = "Locate the courier's boat somewhere along the coast of Feralas.",
}
T[4126] = {
  title = "Hurley Blackbreath",
  desc = "I nani Dark Iron, guidati da quel mascalzone di Hurley Blackbreath, hanno rubato una delle migliori ricette dei Thunderbrew, la Thunderbrew Lager. Mascalzoni! Non se la meritano, una birra così buona!$B$B$N, ho un compito difficile per te. Vai nelle Blackrock Depths, nelle Burning Steppes, distruggi tutti i barili di Thunderbrew Lager che trovi e riporta indietro la nostra ricetta della Thunderbrew Lager!$B$BTi prego, recupera quella ricetta, anche a costo di mettere sottosopra le Blackrock Depths!",
  obj = "Porta la Lost Thunderbrew Recipe a Ragnar Thunderbrew a Kharanos.",
  progress = "Hai la ricetta, $N? Non sopporto l'idea di quei nani Dark Iron che si bevono la birra della mia famiglia!",
  reward = "L'hai trovata! Ottimo lavoro! E spero che tu le abbia suonate per bene a quei Dark Iron, e a Hurley Blackbreath!$B$BI Thunderbrew sono al tuo servizio, $N. Sei $Gun eroe:un'eroina; fra gli eroi!",
}
T[4127] = {
  title = "Il Relitto della Barca",
  desc = "Mentre passi la mano nel fango, le tue dita sfiorano il manico di un coltello. Sembra ben tenuto, e si può presumere che chi era sulla barca l'abbia perso. Forse il grosso pezzo che manca alla barca ha qualcosa a che fare con la perdita.$B$BPrendi il coltello, ricordando che Ginro Hearthkindle, alla Feathermoon Stronghold, ti ha chiesto di tornare da lui con ogni indizio trovato. Hai però la sensazione di non essere del tutto $Gsolo:sola; nell'acqua...",
  obj = "Torna alla Feathermoon Stronghold e mostra a Ginro Hearthkindle il Discarded Knife che hai trovato.",
  progress = "Ah, $Gbentornato:bentornata;, $N. Spero che tu sia $Griuscito:riuscita; a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.",
  reward = "Interessante... credo che questo sia il coltello di Raschal. Dici di averlo trovato sul fondo dell'acqua, insieme alla sua barca? Be', il ritrovamento del coltello da solo potrebbe non bastare a collegarlo alla scomparsa di Raschal; abbiamo però un'opzione poco convenzionale per cercare di saperne di più.$B$BHai mai sentito parlare di psicometria?",
  en_title = "Boat Wreckage",
  en_obj = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.",
}
T[4128] = {
  title = "Ragnar Thunderbrew",
  desc = "Ehilà, $N. Ho sentito che Ragnar Thunderbrew fuma dalla rabbia perché qualcuno gli ha rubato la birra. Cerca avventurieri in gamba, ed è disposto a pagare bene.$B$BSe ti interessa, parla con Ragnar. È alla Distilleria Thunderbrew a Kharanos, a Dun Morogh.",
  obj = "Parla con Ragnar Thunderbrew.",
  reward = "Certo che sono furioso! Mi hanno derubato! Derubato di una delle ricette di famiglia! Come osano! Come se non avessi già abbastanza motivi per odiare i nani Dark Iron! Ma adesso, oh... adesso sono guai per loro!",
}
T[4129] = {
  title = "Ciò che il Coltello Rivela",
  desc = "Il druido della Roccaforte, Quintis Jonespyre, ha delle capacità... insolite. Una di queste è la psicometria — la capacità di rivelare la storia di un oggetto toccandolo. Non chiedermi come faccia; per me è una magia che non capisco e che scelgo di non capire. So però due cose: primo, l'ho vista funzionare, e secondo, quel perdigiorno è in debito con me.$B$BPorta il coltello a Quint, su nella sua casetta sull'albero qui vicino, e digli da parte mia che il suo debito di Kalimdor Hold 'Em sarà saldato se fa la sua magia su quel coltello.",
  obj = "Porta il Discarded Knife a Quintis Jonespyre, alla Feathermoon Stronghold.",
  progress = "Ti manda Ginro, eh?$B$BLe mie letture psicometriche sono piuttosto sfiancanti per la mente... ma lo sono anche le mie perdite a Kalimdor Hold 'Em. Qui alla Roccaforte mi chiamano \"Re delle Batoste\". Sfortunato al gioco... fortunato nel padroneggiare i segreti della natura, direi.$B$BComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Se mi dai il coltello, possiamo cominciare.",
  reward = "Grazie, $N.$B$BAnche se la psicometria non è affatto un'arte esatta, in passato l'ho usata per far luce su situazioni che altri avevano dato per perse. Credo che usarla sul coltello che hai trovato ci farà intravedere cosa è successo a Raschal.$B$BCi vorrà solo un momento, ma non è quello che chiamerei un compito leggero per chi lancia incantesimi. Abbi pazienza.",
  en_title = "The Knife Revealed",
  en_obj = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.",
}
T[4130] = {
  title = "Lettura Psicometrica",
  desc = "Sono ancora un po' stordito, scusa. Comunque, ho avuto delle visioni utili.$B$BRaschal prende due grossi zaini di cuoio dalla sua barca e si addentra nell'entroterra; poi però torna alla barca. Vedo scalpi di gnoll... si è imbattuto in alcuni gnoll — Woodpaw, credo si chiamino. È molto preoccupato — quasi terrorizzato — per qualcosa. Tanto che non si accorge degli elementali dell'acqua che si formano alle sue spalle. Le immagini... si fermano lì.$B$BDevo riposare, scusa, $N. Riferisci a Gin quello che ho visto. Deve saperlo.",
  obj = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.",
  reward = "Grazie per avermi riferito le visioni di Quint, $N. Cercherò di ricordarmi di essere un po' più indulgente con lui la prossima volta che giochiamo a carte.$B$BRaschal sa cavarsela in un combattimento, e gli gnoll non sono certo qualcosa che potrebbe preoccuparlo — anzi, terrorizzarlo. Comunque, forse tu e i tuoi potrete agire in base a queste nuove informazioni e trovare la svolta di cui abbiamo disperatamente bisogno.",
  en_title = "Psychometric Reading",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4131] = {
  title = "Gli Gnoll Woodpaw",
  desc = "Alla fine i nostri \"amici\" Woodpaw potrebbero aver preso Raschal, ma qualcosa mi dice che non è andata così. Comunque, sono il punto di partenza migliore per cercare.$B$BVorrei avere le idee più chiare su cosa fare, ma per ora ho solo \"Cerca negli accampamenti dei Woodpaw — vai.\" So che gli gnoll tengono gli oggetti che razziano e se li contendono; forse si sono imbattuti negli zaini di cui ha parlato Quint. Nelle ricerche passate non avevo rischiato uno scontro frontale, ma con la visione di Quint dico di farli a pezzi.",
  obj = "Cerca negli accampamenti degli gnoll Woodpaw, nel sud di Feralas, tracce degli averi del corriere o del corriere stesso.",
  reward = "Appesi a un albero lì vicino ci sono due grossi zaini di cuoio. Ognuno porta sul davanti un piccolo stemma della Feathermoon Stronghold...",
  en_title = "The Woodpaw Gnolls",
  en_obj = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.",
}
T[4132] = {
  title = "Operazione: Morte ad Angerforge",
  desc = "Hai fatto un lavoro esemplare, $N. È arrivato il momento di affidarti l'ultima missione.$B$BIl Generale Angerforge, il Dark Iron responsabile di aver coordinato gli attacchi alla 109ª divisione della K.E.F. e il massacro delle nostre truppe, deve essere assicurato alla giustizia.$B$BSarà senza dubbio la tua missione più dura, ma se avrai successo sarai $Gricompensato:ricompensata; lautamente.",
  obj = "Vai nelle Blackrock Depths e uccidi General Angerforge! Torna da Warlord Goretooth quando avrai portato a termine l'incarico.",
  progress = "Il Macellaio di Blackrock è stato eliminato?",
  reward = "Finalmente! Quel criminale è stato assicurato alla giustizia! Sei una persona straordinaria, $N. Porta questo medaglione come simbolo della tua incrollabile dedizione all'Orda e alla K.E.F.",
}
T[4133] = {
  title = "Vivian Lagrave",
  desc = "La Maestra delle Ombre Vivian Lagrave ha bisogno dei tuoi servigi. Si trova nelle Badlands, nell'avamposto orchesco di Kargath, dove segue le voci su una certa birra prodotta dai nani Dark Iron delle Blackrock Depths.$B$BParla con Vivian. Ti aspetta.",
  obj = "Parla con Shadowmage Vivian Lagrave a Kargath.",
  reward = "Grazie di essere $Gvenuto:venuta;, $N. Questo posto non è privo di un suo fascino austero, ma gli mancano le comodità dell'Apothecarium.$B$BBasta con i convenevoli. Veniamo agli affari, sì?",
}
T[4134] = {
  title = "Ricetta Perduta della Thunderbrew",
  desc = "Si dice che il Dark Iron Hurley Blackbreath abbia rubato la ricetta di una birra. Pare che questa birra, la Thunderbrew Lager, infonda grande forza e coraggio in chi la beve. Vogliamo studiarla. Forse troveremo altri impieghi per le sue virtù... impieghi più consoni agli scopi dei Reietti.$B$BAddentrati nelle Blackrock Depths, trova Hurley, prendigli la ricetta della Thunderbrew lager e portala a me.$B$BE per trovarlo, forse dovrai attirarlo minacciando la sua preziosa birra.",
  obj = "Porta la Lost Thunderbrew Recipe a Shadowmage Vivian Lagrave a Kargath.",
  progress = "Hai la ricetta della Thunderbrew Lager, $N?",
  reward = "Molto bene. Manderò questa ricetta all'Apothecarium perché la studino, e col tempo ne scopriremo i segreti. Un giorno le virtù di questa bevanda potrebbero essere usate proprio contro i nani dell'Alleanza!$B$BLo trovo terribilmente divertente. Forse la morte ha qualche effetto sul senso dell'umorismo... non credi?",
}
T[4135] = {
  title = "La Fossa Fremente",
  desc = "Negli zaini ci sono due cose: la prima è un pacco di merci diretto a Thalanaar, la seconda un biglietto scritto in fretta per un destinatario sconosciuto.$B$BIl biglietto racconta la scoperta di insidiose creature simili a insetti a sud degli accampamenti degli gnoll, in un posto chiamato Fossa Fremente. L'autore sentiva il bisogno di indagare di persona, come se fosse una grave minaccia per tutta Feralas. Il biglietto è firmato \"Raschal di Feathermoon\".$B$BA quanto pare hai trovato il posto dove Raschal alla fine si è diretto.",
  obj = "Ora che hai scoperto dove Raschal è stato visto l'ultima volta, continua a cercare lui o i suoi resti a Writhing Deep. Secondo il biglietto, si trova a sud degli accampamenti degli gnoll Woodpaw.",
  reward = "Hai scoperto un grosso baccello di natura aliena. Ha un aspetto mucoso, e da punti a caso spuntano protuberanze indurite. Il baccello è alto e largo abbastanza da contenere comodamente un umanoide... e dalla debole sagoma umanoide che si intravede attraverso la sua membrana, deduci che è proprio quello che racchiude.",
}
T[4136] = {
  title = "Ribbly Screwspigot",
  desc = "Mio fratello Ribbly è sempre stato un salasso per la famiglia, a furia di prendersi i nostri soldi e buttarli in una trovata dopo l'altra.$B$BEcco, l'ultima trovata dev'essere stata la peggiore, perché il Barone Revilgaz di Booty Bay ha appena messo una taglia sulla testa del povero Ribbly. Non ti dico quanto ne sono felici gli Screwspigot! Il nostro piccolo Ribbly finalmente vale qualcosa!$B$BMa adesso se ne sta nascosto in fondo alle Blackrock Depths. Ti prego, trovalo e portalo da me!$B$BOppure, se non vuole venire, pazienza... portami solo la sua testa.",
  obj = "Porta Ribbly's Head a Yuka Screwspigot nelle Burning Steppes.",
  progress = "Hai Ribbly? O almeno una parte di lui?",
  reward = "Aha! L'hai trovato! E... a quanto pare il mio fratellino non ha voluto venire con le buone. Peccato. Mi sarebbe piaciuto vedere la sua faccia mentre gli dicevo che avevamo in mente di consegnarlo a Revilgaz.$B$BGrazie, $N. Hai reso molto felice la mia famiglia. E Ribbly non ha mai avuto un'aria serena come adesso.",
}
T[4141] = {
  title = "Muigin e Larion",
  desc = "Lo vedi Larion, laggiù? È colpa SUA se siamo qui!$B$BGliel'avevo detto che stavamo sbagliando strada, ma mi ha dato retta, lui? E ci crederesti che è lui quello che non mi rivolge la parola? Beh, finché non cambia idea, divertiamoci un po' alle sue spalle.$B$BHai notato le strane creature simili a piante che ci sono qui intorno? Portano solo guai, a dire il vero, ma credo che, se le addestrassi a dovere, riuscirei a farle obbedire agli ordini.$B$BPer prima cosa, però, mi servono dei campioni da studiare. Pensi di poterne raccogliere qualcuno?",
  obj = "Raccogli 15 Bloodpetals e torna da Muigin.",
  progress = "Larion avrà quel che si merita, questo è poco ma sicuro!",
  reward = "Spero che non ti abbiano dato troppi problemi, $N. Io cerco di starne alla larga — sono selvagge!$B$BHo provato a scavalcarne una con un salto... Mi ha aggredito! Le piante non dovrebbero proprio comportarsi così!",
}
T[4142] = {
  title = "Una Visita a Gregan",
  desc = "Non so bene cosa pensare, $N. Le piante... sembrano avere un minimo di intelligenza.$B$BIo però non sono un esperto. Ma conosco qualcuno che lo è!$B$BVai nel nord di Feralas e cerca un mio amico che si chiama Gregan Brewspewer. È un esperto di queste cose.$B$BSono sicuro che Gregan può darci una mano. Lo troverai in mezzo alla natura selvaggia; non è il tipo da vivere in una grande città.",
  obj = "Porta un Bloodpetal a Gregan Brewspewer a Feralas.",
  progress = "Vivo qui, in mezzo alla foresta... C'è pace.$B$BBeh, o almeno così pensavo. Ricevo più visite qui di quante ne abbia mai ricevute quando stavo a Ironforge!",
  reward = "Bloodpetal, eh? Hmmm... Beh, sarà meglio che mi spieghi il piano, e poi ti dirò se posso aiutarti o no.",
}
T[4143] = {
  title = "Nuvola del Male",
  desc = "A dirti la verità, $N, nei miei viaggi non ho mai visto piante del genere. Forse dovrei fare un salto in questo cratere...$B$BA ogni modo, credo di sapere cosa fa al caso di Muigin — la nuvola degli Atal'ai. È una robaccia orrenda, difficile da raccogliere, ma è proprio quello che gli serve per controllare quei mostriciattoli.$B$BDovrai andare al tempio di Atal'Hakkar, nella Swamp of Sorrows. La Nuvola degli Atal'ai si può raccogliere dai guardinghi del profondo, dai vermi del buio o dalle melme che si trovano lì. Buona fortuna, $N!",
  obj = "Raccogli 5 campioni di Atal'ai Haze, poi torna da Muigin nell'Un'Goro Crater.",
  progress = "Larion non mi rivolge ancora la parola! Certo che sa portare rancore, lui.",
  reward = "Lo ammetto, $N, non me la sento tanto di toccare quella roba! Ma se Gregan dice che funzionerà, allora sono disposto a provarci!",
}
T[4144] = {
  title = "Germogli di Bloodpetal",
  progress = "Ecco il piano, $N: vai a raccogliere dei germogli di bloodpetal — sai, le piante che non sono ancora spuntate del tutto, e portali qui. Poi vedrò cosa riesce a fare la nuvola degli Atal'ai.$B$BPenserai che io sia vendicativo... In effetti, avresti ragione!$B$BLa verità è che la via per uscire da qui la conosco, ma finché Larion non ammetterà che ho ragione io, resto esattamente dove sono!$B$BQuindi forza, trova quei germogli di bloodpetal e divertiamoci un po'!",
  reward = "O la va o la spacca, $N! Questo sì che attirerà l'attenzione di Larion!",
}
T[4145] = {
  title = "Larion e Muigin",
  desc = "Lo vedi Muigin, laggiù? È colpa SUA se ci siamo persi!$B$BEro io quello che conosceva la strada, ma lui si è impuntato dicendo di conoscere una scorciatoia, e siamo finiti qui!$B$BCome se non bastasse, adesso continua a mandare quelle sue pazze piante infestanti a darmi fastidio. Sono così arrabbiato che non ho intenzione di parlargli tanto presto, ma con queste infestanti non ce la faccio più.$B$BPer prima cosa, vediamo di ridurgli le scorte. Vai a caccia di qualche Bloodpetal, poi torna da me.",
  obj = "Caccia 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers e 5 Bloodpetal Trappers per Larion al Rifugio dei Marshal.",
  progress = "Prima Muigin deve chiedermi scusa, poi tornerò a parlargli!",
  reward = "Grazie dell'aiuto, $N, ma temo di avere brutte notizie...",
}
T[4146] = {
  title = "Carburante per il Folgoratore",
  desc = "Sei $Gfortunato:fortunata;, $N! Mentre Marvon era via ho lavorato a qualche esperimento mio, e uno è un folgoratore per insetti a corto raggio. Con appena qualche ritocco, dovrebbe essere perfetto per sbarazzarti di quelle infestanti Bloodpetal.$B$BPosso darti uno dei miei prototipi di folgoratore, ma il carburante dovrai comunque procurartelo tu. La nuvola degli Atal'ai che serve al folgoratore la trovi nel tempio di Atal'Hakkar. Dovrai prenderla dai guardinghi del profondo, dai vermi del buio o dalle melme.",
  obj = "Consegna l'Unloaded Zapper e 5 campioni di Atal'ai Haze a Larion al Rifugio dei Marshal.",
  progress = "È sfiancante, $N. Quelle cose non mi lasciano proprio in pace!",
  reward = "Quindi Marvon non c'era? Beh, fammi vedere lo stesso cos'hai portato.",
}
T[4147] = {
  title = "L'Officina di Marvon",
  desc = "Sono riuscito a spiare quello che combina Muigin, e quelle dannate cose le sta addirittura coltivando, laggiù!$B$BSecondo me l'unica soluzione è... no, non è andare a parlargli... Ma cosa vai a pensare? La soluzione è contrattaccare!$B$BCi servirà l'aiuto del mio amico Marvon, che ha un'officina a Ratchet. Sono sicuro che saprà creare qualche congegno che ci aiuti.",
  obj = "Raggiungi l'officina di Marvon Rivetseeker a Ratchet.",
  reward = "Marvon è via da un bel pezzo ormai, $N. È andato a Tanaris a studiare alcune delle antiche rovine dei troll.$B$BAllora, cos'è che hai detto che ti serviva?",
}
T[4148] = {
  title = "Folgoratore per Bloodpetal",
  progress = "Per funzionare, il folgoratore ha bisogno di un campione della creatura da colpire. Vai nel cratere e raccogli un germoglio di Bloodpetal. Poi potrò tararlo perché funzioni sugli amichetti di Muigin...$B$BSe non fosse così testardo, potremmo già essere sulla via di casa... Ma nel frattempo non mi resta che dimostrargli che il suo scherzetto non mi dà il minimo fastidio!",
  reward = "A quanto pare funzionerà alla perfezione, $N. E ricorda, se vedi in giro qualcuna di quelle infestanti, non esitare a usare il folgoratore!",
}
T[4161] = {
  title = "La Ricetta dei Kaldorei",
  desc = "Tanto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino come $C, $N, quindi ascolta bene quello che ho da dirti.$B$BI kaldorei sono sempre stati molto fieri del loro rapporto armonioso con la natura. Questo significa che prendiamo dalla natura solo ciò che è necessario, e che restituiamo in egual misura. Questo equilibrio ci ha dato molto, $N.$B$BVa' a raccogliere sette piccole zampe di ragno — non di più, e torna da me.",
  obj = "Raccogli 7 Small Spider Leg per Zarrin, a Dolanaar.",
  progress = "Ricorda l'equilibrio, $N. Desidero che tu sviluppi comprensione e una forte empatia per le foreste viventi.",
  reward = "Ricorda sempre quello che ti ho mostrato oggi, $N. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche in tempi difficili.",
  en_title = "Recipe of the Kaldorei",
  en_obj = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.",
}
T[4181] = {
  title = "Ingegneria Goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.$B$B$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'Ingegneria Goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'Ingegneria Goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[4182] = {
  title = "La Minaccia dei Dragonkin",
  desc = "La vita nelle Burning Steppes è un conflitto continuo.$B$BGuarda questo posto! Sappiamo ben poco di quello che è successo a questi edifici, ma sappiamo che un tempo, prima della grande esplosione, tutto questo faceva parte della catena montuosa di Redridge.$B$BBasta lamentarsi! Abbiamo un problema, $N. Avrai notato i dragonkin sotto questo crinale. Ci serve aiuto per respingerli. Uccidine più che puoi e torna da me. Se ci riesci, forse potremo parlare d'altro.",
  obj = "Uccidi 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin e 1 Black Drake. Torna da Helendis Riverhorn a compito concluso.",
  progress = "Come va la caccia ai draghi?",
  reward = "Una strage magnifica, $N. Ora che sappiamo che con i dragonkin te la sai cavare, possiamo parlare di questioni più urgenti.",
}
T[4183] = {
  title = "I Veri Padroni",
  desc = "Avevamo sempre creduto che gli orchi Blackrock fossero il frutto dell'ambiente selvaggio in cui sono cresciuti. Quello che abbiamo trovato qui, nella loro terra d'origine, racconta un'altra storia.$B$BCerto, sono la sete di sangue e la brama di conflitto a dar loro forza, ma è il dragonflight nero a controllare gli orchi di Blackrock. Sospettiamo che sia il dragonflight nero ad alimentare in loro rabbia e ostilità.$B$BPorta questa lettera al Magistrato Solomon. Lui saprà cosa fare.$B$B<Helendis ti consegna una lettera sigillata.>",
  obj = "Recati a Lakeshire e consegna Helendis Riverhorn's Letter a Magistrate Solomon.",
  progress = "Salute, $N. Ci siamo già incontrati? Hai un'aria vagamente familiare.",
  reward = "<Il Magistrato Solomon apre la lettera sigillata di Helendis e comincia a leggere.>",
}
T[4184] = {
  title = "I Veri Padroni",
  desc = "Sono brutte notizie, $N. Scoprire che i nostri nemici giurati sono soltanto pedine di una minaccia ben più grande è sconfortante. Lakeshire non ha alcuna possibilità di sopravvivere a un attacco degli orchi Blackrock e del dragonflight nero insieme. Se Lakeshire dovesse cadere sotto questa minaccia, poi toccherebbe a Darkshire, e dopo? Goldshire? Stormwind stessa?$B$BDevi portare subito queste informazioni al Gran Signore Bolvar Fordragon, a Stormwind! Se questo non merita l'aiuto di Stormwind, niente lo meriterà e tutto è perduto.",
  obj = "Recati a Stormwind e consegna Solomon's Plea to Bolvar a Highlord Bolvar Fordragon.$B$BBolvar risiede nel Mastio di Stormwind.",
  progress = "Cosa ti porta al Mastio di Stormwind?",
  reward = "Draghi? Impossibile!",
}
T[4185] = {
  title = "I Veri Padroni",
  desc = "Solomon dipinge un quadro fosco. Eppure non possiamo permetterci di mandare in aiuto di Lakeshire, sulla base di congetture, le nostre truppe già troppo disperse. Mi servono le prove di queste affermazioni prima di poter agire.$B$BParla con Lady Prestor, $N. È una donna colta e sa molto di draghi e dragonkin. Forse potrà fare un po' di luce su questa situazione.",
  obj = "Parla con Highlord Bolvar Fordragon dopo aver parlato con Lady Katrana Prestor.",
  progress = "<Bolvar ti osserva attentamente.>",
  reward = "<Bolvar si prende il mento fra le dita, come immerso nei suoi pensieri.>$B$BPur rispettando la posizione di Lady Prestor, credo che a questo dilemma ci sia una soluzione capace di fugare tutte le nostre preoccupazioni.",
}
T[4186] = {
  title = "I Veri Padroni",
  desc = "Ti conferisco i poteri di $Gdelegato provvisorio:delegata provvisoria; di Stormwind, $N.$B$BTorna dal Magistrato Solomon, a Lakeshire, e consegnagli questo decreto.",
  obj = "Porta Bolvar's Decree a Magistrate Solomon, a Lakeshire.",
  progress = "Notizie da Bolvar?",
  reward = "Poteva andare peggio, immagino...$B$B<Il Magistrato Solomon ti squadra da capo a piedi.>$B$BA quanto pare il destino di Lakeshire poggia tutto sulle tue spalle.$B$B<Noti che il Magistrato Solomon sbatte rapidamente le palpebre. Sembra che stia piangendo.>",
}
T[4201] = {
  title = "La Pozione d'Amore",
  desc = "Oh, le pene d'amore! Il mio caro Soldato Rocknot è immune al mio fascino. Sono stata respinta! C'è da impazzire!$B$BDevi aiutarmi! Noi succubi sappiamo molte cose dell'amore, e io so preparare una pozione capace di abbattere le mura di ferro attorno al cuore di Rocknot. Per farla mi servono queste cose: l'erba gromsblood, vene d'argento di gigante prese ai giganti delle scogliere di Azshara e acqua delle Sorgenti Golakka, nel cratere di Un'Goro. L'acqua puoi metterla in questa fiala.$B$BTi prego, $N, aiuta una povera anima nella sua ricerca della felicità!",
  obj = "Porta 4 Gromsblood, 10 Giant Silver Veins e Nagmara's Filled Vial a Mistress Nagmara nelle Blackrock Depths.",
  progress = "Hai gli ingredienti? Il vuoto che ho nel cuore rischia di divorarmi!",
  reward = "Oh, ce l'hai fatta! Ora posso preparare la mia pozione e usarla su Rocknot. Finalmente cadrà vittima del mio fascino!$B$BGrazie, $N. Sei $Gun campione:una campionessa; dell'amore!",
}
T[4221] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4222] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4223] = {
  title = "I Veri Padroni",
  desc = "<Il Magistrato Solomon sospira.>$B$BDevi tornare nelle Burning Steppes, $N. In quanto $Gdelegato:delegata; di Stormwind, dovrai fare rapporto al Maresciallo Maxwell. Buona fortuna.",
  obj = "Parla con Marshal Maxwell, nelle Burning Steppes.",
  reward = "<Il Maresciallo Maxwell ride.>",
}
T[4224] = {
  title = "I Veri Padroni",
  desc = "Cosa? Credevi di essere $Gil primo:la prima;? Quanti soldati dobbiamo perdere prima che Stormwind si muova?$B$BAvevamo accumulato un'enorme quantità di informazioni sulla minaccia dei Blackrock prima di perdere il nostro comandante, il Maresciallo Windsor. Con il Maresciallo Windsor se ne sono andate tutte le nostre preziose informazioni.$B$BÈ di quella documentazione che abbiamo bisogno. Parla con John lo Straccione, $N. Era con Windsor quando sono stati attaccati da una squadra di razziatori Blackrock. L'ultima volta è stato visto in una grotta a nord.",
  obj = "Parla con Ragged John per scoprire che fine ha fatto Marshal Windsor e, quando hai finito, torna da Marshal Maxwell.$B$BRicordi che Marshal Maxwell ti ha detto di cercarlo in una grotta a nord.",
  progress = "Hai già parlato con John?",
  reward = "Avrei potuto avvertirti, ma che gusto ci sarebbe stato?",
}
T[4241] = {
  title = "Maresciallo Windsor",
  desc = "E così quel codardo buono a nulla dice che Windsor è vivo, eh?$B$BEquipaggiati, vice, entri tu a cercarlo. Se Windsor è vivo, devi riportarlo indietro. Se è morto, voglio una prova.$B$B<Maxwell ride.>$B$BScommetto che ti stai stancando di sentirtelo dire, vero?",
  obj = "Vai a Blackrock Mountain, a nord-ovest, ed entra nelle Blackrock Depths. Scopri che fine ha fatto Marshal Windsor.$B$BRicordi che Ragged John raccontava che Marshal Windsor era stato trascinato via in una prigione.",
  reward = "Dov'è! Lo ammazzo!",
}
T[4242] = {
  title = "Speranza Abbandonata",
  desc = "Bolvar è uno sciocco. Stavo raccogliendo la sua preziosa 'prova' per potergliela cacciare in gola.$B$BÈ un buffone cieco. La prova gli sta a due piedi di distanza e lui non la vede.$B$BQuanto ai miei dati, sono persi. Spariti. Irrecuperabili.$B$BSe mai dovessi ritrovare Ironfoe e uscire da questo labirinto, la mia prima tappa sarà Stormwind, per piantare il mio martello in mezzo agli occhi di quel rettile.$B$BLasciami, $N.",
  obj = "Porta la brutta notizia a Marshal Maxwell.",
  reward = "È impazzito, a quanto pare.$B$B<Maxwell china il capo in segno di lutto.>$B$BÈ triste che un guerriero un tempo fiero e nobile si sia ridotto a uno svitato che farnetica. IMMAGINO che siamo arrivati a un vicolo cieco...$B$BDevo ricompensarti per quanto hai fatto finora, $N.",
}
T[4243] = {
  title = "Sulle Tracce di A-Me 01",
  desc = "Purtroppo è successo qualcosa a una delle mie invenzioni migliori. Hai presente gli scoiattoli meccanici, sì? Ecco, per avvicinarmi alle scimmie di Un'Goro Crater ho creato una scimmia meccanica che si confondesse tra loro — la chiamo A-Me 01.$B$BAl posto degli occhi ha delle gemme divinatorie, così potevo vedere tutto quello che vedeva lei. È arrivata fino alla Roccia del Fungo — la tana delle scimmie — appena a est di qui, ed è lì che ho perso il contatto. L'ultima cosa che ho visto è stato uno dei loro maschi alfa che le correva incontro per salutarla!$B$BPuoi aiutarmi a ritrovarla?",
  obj = "Trova A-Me 01 a Un'Goro Crater.",
  reward = "Esaminando A-Me 01, noti due enormi ammaccature che rovinano quella che per Karna è evidentemente un'opera d'ingegneria ben riuscita. Un'ammaccatura orna la spalla di A-Me 01, l'altra è sulla testa.$B$BGuardando meglio, non sembra che nei suoi componenti passi energia.",
}
T[4244] = {
  title = "Sulle Tracce di A-Me 01",
  desc = "Guardando ancora un po', scopri un pannello scorrevole. Sopra alcuni cavi si legge chiaramente la scritta \"Sostituire il Rivestimento di Mithril, Poi Spegnere e Riaccendere.\"$B$BMentre rimetti a posto il pannello, ti chiedi se basterà così poco per riparare A-Me 01 e riportarla da Karna Remtravel, vicino al Rifugio dei Marshal.$B$BLo si saprà solo provando.",
  obj = "Trova un Mithril Casing e torna da A-Me 01 a Un'Goro Crater.",
  progress = "Il pannello dietro cui va il rivestimento di mithril è ancora ben chiuso. Il resto di A-Me 01 rimane inerte.",
  reward = "Togli ancora una volta il pannello dalla schiena di A-Me 01 e rimuovi con cura il vecchio rivestimento di mithril, che sembra bruciato. Quello nuovo scivola al suo posto senza difficoltà. Ammesso che il problema fosse il rivestimento di mithril, non resta che spostare l'interruttore su \"Spento\" e poi di nuovo su \"Acceso\".",
}
T[4245] = {
  title = "Sulle Tracce di A-Me 01",
  desc = "Controlli di essere $Gpronto:pronta; a ricondurre A-Me 01 da Karna Remtravel e sposti l'interruttore su \"Spento\". Ti guardi intorno ancora una volta per assicurarti che non stia arrivando nessun gorilla e ti prepari a vedere cosa succede riportando l'interruttore su \"Acceso\".$B$BÈ la tua ultima occasione... sei $Gsicuro:sicura; che sia questo ciò che vuoi fare?",
  obj = "Scorta A-Me 01 fino a Karna Remtravel, a Un'Goro Crater.",
  progress = "Sei $Griuscito:riuscita; ad aiutare A-Me? Quel rivestimento di mithril distrutto di cui mi parlavi era una buona ipotesi su cosa non andava. Sono sicura che, sostituendolo, si riattiverà e potrà tornare a casa.",
  reward = "Oh, ce l'hai fatta! Magnifico! Grazie, $N.$B$BOh, mia povera A-Me. Guarda quante ammaccature. Con appena un po' di lavoro la rimetteremo in perfetta efficienza.$B$BGrazie ancora, $N. Te ne sono davvero grata.",
}
T[4261] = {
  title = "Spirito Antico",
  desc = "Felwood un tempo era una terra pacifica e serena... Finché non se ne impadronì la legione. Gli infernali, la distruzione, il caos...$B$BIl teschio di Gul'dan fece sì che qui nessuno fosse risparmiato. Tutti cedettero alla corruzione.$B$BPerfino adesso, da spirito, mi ritrovo ancora $Gintrappolato:intrappolata;, a portare su di me la sofferenza di questa terra. Aiutami a trovare la via di casa. Ti prego, $N, dimmi che condurrai uno spirito antico lontano da qui, dove potrò finalmente riposare.$B$BQuando sarò $Glibero:libera;, cerca Kayneth Stillwind, un druido che vive a Cantaselva, a est.",
  obj = "Scorta Arei in salvo, poi parla con Kayneth Stillwind a Forest Song, nella parte orientale di Ashenvale.",
  progress = "Cos'hai visto in questa terra corrotta?",
  reward = "Sì, $N. Felwood ha patito molte sofferenze. Grazie per quello che hai fatto.$B$BUn giorno, forse, riusciremo a strappare Felwood alla corruzione; ogni buona azione aiuta.",
}
T[4262] = {
  title = "Maestro Supremo Pyron",
  desc = "Gli ultimi cinque dei miei maghi che sono andati a ficcanasare a Blackrock Mountain sono tornati belli croccanti e con un afro gnomesco arancione che non va più via — o peggio.$B$B<Jalinda raccoglie un po' di cenere da terra e la lascia andare nell'aria.>$B$BUn tipaccio in particolare, il Maestro Supremo Pyron, a quanto pare sta causando un bel po' di guai. Quell'elementale va eliminato, così la squadra della nostra spedizione potrà farsi strada fin dentro Blackrock Depths!$B$BLui sta di guardia all'ingresso, alla Cava di Blackrock.",
  obj = "Uccidi Overmaster Pyron e torna da Jalinda Sprig.$B$BRicordi che Jalinda diceva che Pyron fa la guardia alla cava. Forse dovresti cercare lì?",
  progress = "<Jalinda sembra fissarti la testa.>",
  reward = "Incendius? Oh, cielo...",
}
T[4263] = {
  title = "Incendius!",
  desc = "Sei $Gsicuro:sicura; che Pyron abbia detto 'Incendius' quando è morto?$B$B<Jalinda deglutisce a fatica.>$B$BA quanto si dice, Lord Incendius è un servitore di Ragnaros! Oh cielo, oh cielo... e adesso che facciamo?$B$BPensi di farcela con un'altra missione? Non ho nessun altro da mandare, $N!$B$BNon riusciremo mai a far entrare una squadra se Incendius continua a far risorgere Pyron dalle ceneri.$B$BDovrai trovare e distruggere Lord Incendius!",
  obj = "Trova Lord Incendius nelle Blackrock Depths e distruggilo!",
  progress = "Quel mostro è morto??",
  reward = "Oh cielo! Sei $Gsicuro:sicura; che Incendius abbia detto 'Ragnaros?'$B$B<Jalinda ti porge qualcosa e ti dà qualche colpetto sul polso, mentre sprofonda nei suoi pensieri.>",
}
T[4264] = {
  title = "Un Biglietto Accartocciato",
  desc = "Il biglietto è coperto di macchie. Il testo si legge a malapena, ma riesci a decifrare quanto segue:$B$B...dolce ironia...$B$B...la caduta dell'Alleanza in frantumi...$B$B...se non fosse stato per lo zelo del Generale Angerforge, forse non avremmo mai scoperto lo schema della cifratura...$B$B...Argelmach ha quasi finito di decifrare gli appunti di Windsor.$B$BIl nostro signore sorgerà dalle profondità e schiaccerà chiunque rimanga...$B$B— Imperatore Dagran Thaurissan.",
  obj = "Forse ti sei appena $Gimbattuto:imbattuta; in qualcosa che Marshal Windsor vorrebbe vedere. Dopotutto, potrebbe esserci ancora speranza.",
  progress = "<Il Maresciallo Windsor osserva il biglietto che hai in mano.>$B$BCos'hai lì, $N?",
  reward = "<Il Maresciallo Windsor prende il biglietto e comincia a leggere.>",
}
T[4265] = {
  title = "Liberato dall'Alveare",
  desc = "Quando lo tocchi, il baccello si apre un poco e rivela un elfo della notte, sorprendentemente ancora vivo. Sembra in buona salute, anche se profondamente stordito. Mentre lo aiuti a scendere dal baccello, si riprende.$B$B\"Sia lodata Elune — mi hai salvato, $Gamico:amica;! Io... io sono Raschal. Mi sono svegliato paralizzato dentro questo baccello, dopo che questi insetti mi hanno sopraffatto. Ti ha mandato la Roccaforte?\"$B$BA quanto pare hai trovato il corriere scomparso!",
  obj = "Libera Raschal dall'alveare degli Zukk'ash.$B$BTorna da Ginro Hearthkindle, alla Feathermoon Stronghold, e fagli sapere che Raschal è vivo e sta bene.",
  progress = "Hai qualcosa da riferire, $N?",
  reward = "$GBentornato:Bentornata; a casa, $N. Raschal si è presentato poco fa e mi ha raccontato cos'è successo.$B$BIo... no, l'intera Roccaforte non saprebbe nemmeno da dove cominciare per ringraziarti della tua grande impresa; senza il tuo aiuto tempestivo Raschal sarebbe morto, e ci hai aiutato senza chiedere nemmeno l'ombra di un compenso da mercenario. Hai la stoffa di $Gun vero eroe:una vera eroina;. Sappi che in Ginro Hearthkindle avrai sempre un amico.",
}
T[4266] = {
  title = "Un'Accoglienza Trionfale",
  desc = "$N, il Generale Shandris Feathermoon vorrebbe parlarti di persona. Di certo vuole ringraziarti per il tuo servizio alla Roccaforte, ma so anche che vuole parlarti delle creature simili a insetti che tu e Raschal avete affrontato nel sud di Feralas. I rapporti su quegli insetti Zukk'ash sono... a dir poco spaventosi.$B$BIl Generale Feathermoon ti aspetta nell'edificio principale.",
  obj = "Parla con Shandris Feathermoon, alla Feathermoon Stronghold.",
  reward = "$N, ti ringrazio di cuore per l'aiuto che ci hai dato. Il coraggio che hai mostrato di fronte a forze soverchianti meriterebbe una ricompensa mille volte più grande. Tuttavia, spero che accetterai questa a nome di tutta la Roccaforte.$B$BE ora, se posso... vorrei chiederti aiuto ancora una volta. Vista la scoperta dell'alveare degli Zukk'ash qui a Feralas, credo che tu sia la persona più adatta per questa missione.",
}
T[4267] = {
  title = "L'Ascesa dei Silithid",
  desc = "Ti affido una copia del rapporto che Raschal ha scritto sull'infestazione del sud-est di Feralas. Mentre il rapporto principale viene archiviato a Darnassus, voglio che tu consegni questa copia a una collaboratrice del Protectorate. Si chiama Gracina Spiritmight; è una sacerdotessa che vive nel Tempio della Luna, a Darnassus. Conosce bene questo genere di creature, e se ricevesse questo rapporto ne trarremmo beneficio tutti.$B$BPuoi andare — buona fortuna, $N; che Elune vegli su tutti noi.",
  obj = "Porta Raschal's Report a Gracina Spiritmight, a Darnassus.",
  progress = "$GBenvenuto:Benvenuta; in questo tempio benedetto, $Gamico:amica;. Mi era stato predetto che saresti $Garrivato:arrivata; qui dalla Feathermoon Stronghold. Hai il rapporto che Shandris Feathermoon ti ha chiesto di portare?",
  reward = "Noi elfi della notte conosciamo il terrore descritto in questo rapporto. Shandris ha fatto bene a mandare da me questo rapporto, e te.$B$BQueste creature divoreranno Feralas in fretta; non sono niente di meno che una delle minacce più grandi che tutti noi dovremo mai affrontare. Gli insetti che tu e il corriere avete incontrato si chiamano silithid. Sono semplici strumenti di una delle minacce più grandi che l'Orda e l'Alleanza dovranno mai affrontare.$B$BPrego che abbiamo la determinazione di sconfiggerli prima che ci distruggano.",
}
T[4281] = {
  title = "Consegna a Thalanaar",
  desc = "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Woodpaw doveva essere consegnato alla piccola stazione di sosta di Thalanaar, nel sud-est di Feralas. Qualunque sia stata la sorte del corriere scomparso, il compito di consegnare il pacco resta da portare a termine.$B$BEsaminando il pacco con attenzione, scopri un nome scritto a mano sull'esterno dell'imballaggio: \"Falfindel Waywarder\". Forse è il destinatario finale del pacco.",
  obj = "Porta l'Undelivered Parcel a Falfindel Waywarder, a Thalanaar.",
  progress = "$GBenvenuto:Benvenuta; a Thalanaar, $C. Ti serve aiuto di qualche tipo?",
  reward = "Sia lodata Elune, la consegna dalla Feathermoon Stronghold è finalmente arrivata!$B$BLa tua presenza qui mi fa pensare che forse a Raschal, il nostro solito corriere, sia capitata una brutta sorte. Spero che tutto si sistemi. So che di recente i Woodpaw si sono molto agitati per qualcosa che viene da sud. Forse è caduto lì, nelle terre selvagge; io starei attento, $Gamico:amica;.$B$BComunque, grazie ancora. Ecco il pagamento per la consegna di questo pacco.",
  en_title = "Thalanaar Delivery",
  en_obj = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.",
}
T[4282] = {
  title = "Un Briciolo di Speranza",
  desc = "<Il Maresciallo Windsor agita il biglietto, tutto elettrizzato.>$B$BTi rendi conto di cosa significa, $N?$B$BForse non tutto è perduto! Da quel che riesco a capire, le informazioni sono in mano a due nani Dark Iron: il Generale Angerforge e il signore dei golem, Argelmach. Ho la sensazione che non ce le consegneranno certo se gliele chiediamo per favore.$B$BSpero che tu sia $Gpronto:pronta; a combattere.$B$BMettiti in marcia e trova questi due furfanti! Distruggili e riportami le informazioni che ho perduto.",
  obj = "Riporta Marshal Windsor's Lost Information.$B$BMarshal Windsor ritiene che le informazioni siano in mano a Golem Lord Argelmach e a General Angerforge.",
  progress = "Presto questo grande inganno avrà fine.",
  reward = "<Il Maresciallo Windsor ti strappa di mano le due tavolette.>$B$BDobbiamo andarcene da qui!",
}
T[4283] = {
  title = "CINQUANTA! EH GIÀ!",
  desc = "Ti svelo un piccolo segreto, soldato. Vieni un po' più vicino.$B$BQUI L'UNICO SANO DI MENTE SONO IO!$B$BGuarda questa gente! Ci crederesti che sono tutti pazzi!? Beh, lo sono! SVITATI! MATTI!$B$B<Oralius abbassa la voce.>$B$BChe resti fra me, te e il mio compare, il Capitano Winky.$B$B<Oralius afferra l'aria e stringe.>$B$BComunqueeeee... Sto raccogliendo distintivi da affiancare alla mia collezione di orecchie di ogre. Il gusto del giorno è l'orco. Cinquanta. VIA!$B$B<Oralius soffia in un corno.>$B$BSPEDISCI!",
  obj = "Oralius vuole 50 Blackrock Medallions. È molto probabile che questi medaglioni si trovino addosso agli orchi delle Burning Steppes.",
  progress = "<Oralius sta parlando dentro un orecchio mozzato di ogre, piuttosto grande.>$B$BBurning Steppes chiama base, rispondete, base.",
  reward = "Ce l'hai fatta! La tua ricompensa è: ACCAREZZAMI LA PANCIA! FORZA! ACCAREZZALA!",
}
T[4284] = {
  title = "Cristalli di Potere",
  desc = "Li avrai notati di sicuro, $N. Sono dappertutto!$B$BDi cosa sto parlando? Ma dei cristalli, naturalmente!$B$BI cristalli... Il cratere ne è pieno. La maggior parte della gente li ignora, ma io ho la strana sensazione che racchiudano del potere. È da un po' che ci faccio esperimenti qui, ma non riesco a scoprire niente. Beh, non ancora, almeno.$B$BSenti, quelli che ho qui stanno per finire — non è che riusciresti a raccogliermene degli altri?",
  obj = "Raccogli 7 Power Crystals di ogni colore: rosso, blu, giallo e verde. Portali a J.D. Collie al Rifugio dei Marshal.",
  progress = "Me lo sento che sono sulla pista giusta, $N!",
  reward = "Ora continuerò i miei esperimenti! Grazie, $N.",
}
T[4285] = {
  title = "Il Pilone Settentrionale",
  desc = "A cosa potrebbero servire? Non riesco a togliermi questo pensiero dalla testa!$B$BMi fa impazzire — l'idea che le voci che ho sentito sui piloni di cristallo siano tutte vere. Dammi pure dell'ingenua, ma di solito credo a qualsiasi cosa mi dica la gente.$B$BComunque, ho sentito dire che uno dei piloni di cristallo è piuttosto vicino. Da qualche parte a nord... Ti prego, trovalo, $N. Io lo so che esistono.",
  obj = "Scopri dove si trova il Northern Crystal Pylon a Un'Goro Crater.",
  progress = "Hai visitato il pilone, $N?",
  reward = "Lo so che quelle storie sono vere, $N.",
}
T[4286] = {
  title = "La Roba Buona",
  desc = "Il Capitano Winky mi dice che la roba buona ce l'hanno tutta i Dark Iron nelle Depths. Dico bene, Winky?$B$B<Oralius fa la sua migliore imitazione di un pirata.>$B$BARRR MARINAIO! VERO È!$B$BCapito cosa intendo? Devi andare là dentro e riportarmi qualche campione della roba buona.$B$BVai là dentro e muovi le chiappe!",
  obj = "Vai nelle Blackrock Depths e recupera 20 Dark Iron Fanny Packs. Torna da Oralius quando avrai portato a termine l'incarico. Presumi che questi aggeggi chiamati 'marsupi' li portino i nani Dark Iron dentro le Blackrock Depths.",
  progress = "Adesso non voglio seccature, $N. Io e Winky c'abbiamo una riunione.",
  reward = "<Oralius si mette a frugare nella montagna di marsupi.>$B$BOH, CHE MERAVIGLIA!$B$B<Oralius infila il suo grosso naso nel mucchio e dà un'annusata.>$B$BDELIZIOSO! Guarda quanta bella roba!$B$BPrendine uno anche tu, $N. Ce n'è per tutti.",
}
T[4287] = {
  title = "Il Pilone Orientale",
  desc = "Da quando sono qui ho sentito strane voci su piloni misteriosi che si troverebbero nelle zone selvagge del cratere, $N. Da quel che ho capito sono piuttosto grandi, con l'interno rivestito di cristalli.$B$BAnche se non ne ho mai visto uno, non posso fare a meno di pensare che le voci siano vere — e che i piloni c'entrino qualcosa con tutti i cristalli che abbiamo trovato$B$BAllora, perché non mi aiuti a togliermi questa curiosità? A quanto si dice, ce n'è uno nella zona orientale del cratere. Pensi di riuscire a trovarlo?",
  obj = "Scopri dove si trova l'Eastern Crystal Pylon a Un'Goro Crater.",
  progress = "Hai visitato il pilone, $N?",
  reward = "Un'Goro è un posto davvero strano, $N. Quando entri nel cratere è come trovarsi in un mondo completamente diverso...",
}
T[4288] = {
  title = "Il Pilone Occidentale",
  desc = "Finora i miei esperimenti non hanno dato alcun risultato positivo, $N. Non posso che sperare che tu trovi una soluzione cercando uno dei piloni che, a quanto ho sentito, esistono.$B$BForse, se lì combinassimo certi colori... ma sto correndo troppo. Prima troviamoli!$B$B$N, cerca nella zona occidentale del cratere; si dice che un pilone sia da qualche parte laggiù.",
  obj = "Scopri dove si trova il Western Crystal Pylon.",
  progress = "Hai visitato il pilone, $N?",
  reward = "Lungo i fianchi del cratere ci sono molte zone nascoste. Se non ti viene in mente nessun altro posto dove cercare, prova a esplorare i sentieri tortuosi, $N.",
}
T[4289] = {
  title = "Le Scimmie di Un'Goro",
  desc = "Questo cratere ospita molte creature strane — sembrano versioni più nobili di quelle che si trovano nella mia terra natale e oltre. Non so spiegarlo, ma questo luogo parla a gran voce della Madre Terra. Le rendo omaggio ogni volta che seguo le tracce di una delle sue splendide creature attraverso la conca.$B$BSe anche tu desideri provare l'illuminazione che accompagna una così grande impresa, dirigiti a nord. Lì troverai grandi scimmie che mettono alla prova la forza di qualsiasi mortale. Portami le loro pelli... dimostra la tua forza.",
  obj = "Porta 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts e 2 Un'Goro Thunderer Pelts a Torwa Pathfinder all'ingresso di Un'Goro Crater.",
  progress = "Le creature di qui hanno già avuto la meglio su di te, $N?$B$BNon lasciarti scoraggiare così facilmente. Seguire le tracce delle scimmie di Un'Goro e sconfiggerle non è un'impresa semplice, nemmeno per un grande cacciatore.",
  reward = "Dunque ti sei $Gdimostrato:dimostrata; forte, abbastanza forte da avere la meglio sulle grandi scimmie di Un'Goro — è un bene. La sfida era piccola in confronto a Lar'korwi, ma non ti toglierò una vittoria così grande.$B$BDa queste pelli la mia tribù ricaverà splendidi indumenti. Mi hai aiutato e ti sei $Gdimostrato degno:dimostrata degna;.$B$BPrima che tu parta per un'altra impresa, rendiamo lode alla Madre Terra e ringraziamo gli spiriti delle scimmie che hai ucciso — devono sapere che la loro morte non sarà vana.",
}
T[4290] = {
  title = "Il Pasto di Lar'korwi",
  desc = "Una volta, tanto tempo fa, un mio fratello prese un po' di carne da una delle prede uccise da Lar'korwi. In quel momento non lo sapeva, ma Lar'korwi lo aveva visto dalla foresta. Lar'korwi seguì mio fratello per giorni, distruggendo tutto ciò che toccava. Alla fine mio fratello, spaventato, decise di fuggire dal Cratere e di lasciarsi Lar'korwi alle spalle.$B$BLar'korwi lo uccise non lontano da questo punto.$B$BSe vuoi provocare Lar'korwi, trova una sua preda appena uccisa e prendine un po' di carne.$B$BDopo, torna da me.",
  obj = "Trova la carcassa della preda più recente di Lar'korwi e ruba un Piece of Threshadon Carcass, poi torna da Torwa Pathfinder a Un'Goro Crater.",
  progress = "Non prendere le mie parole alla leggera, $N. Se vuoi davvero affrontare questa creatura, devi essere $Gcauto:cauta;... e $Gastuto:astuta;. Serviranno molta forza e molto acume per stanare Lar'korwi e sconfiggerlo.",
  reward = "Questo andrà benissimo, $N. A quanto pare Lar'korwi mangia bene di questi tempi. Mi chiedo, però, dove abbia trovato un threshadon in questa zona. Strano.$B$BIn ogni caso, lo terrò io finché non sarai $Gpronto:pronta; ad affrontare la bestia. Non temere per la mia incolumità — sono certo che hai fatto infuriare Lar'korwi abbastanza perché non mi uccida prima di aver assaggiato la tua carne.",
}
T[4291] = {
  title = "L'Odore di Lar'korwi",
  desc = "In verità mi sorprende che non sia ancora venuto a cercarti, $N. Ma va bene così, perché ho un ultimo piano che porterà il mostro da noi.$B$BEssere il maschio dominante dà a Lar'korwi il diritto di accoppiarsi con qualsiasi femmina scelga — e ne sceglie molte. Troverai molte uova di ravasaur a ovest di qui. Avvicinati e dovresti provocare l'attacco delle sue compagne. Le femmine producono un odore tremendo da una ghiandola che hanno nella testa, e da quello i maschi capiscono che sono pronte ad accoppiarsi. Portami due di quelle ghiandole.",
  obj = "Porta 2 Ravasaur Pheromone Glands a Torwa Pathfinder, vicino all'ingresso di Un'Goro Crater.",
  progress = "Fai attenzione, $N. Avvicinarti a un qualsiasi nido di uova provocherà di sicuro le madri... anche se hai già preso una ghiandola a una di loro. Quando combattono per proteggere i piccoli, le madri possono essere letali quanto Lar'korwi stesso. Ma se ci riuscirai, avremo un modo sicuro per stanare Lar'korwi dal suo nascondiglio.",
  reward = "Ah, ottimi esemplari, $N. I due pezzi che hai trovato dovrebbero essere perfetti per attirare Lar'korwi allo scoperto. Non vedo l'ora di vedere come finirà il tuo scontro con il mostro. È una creatura imponente, con artigli affilati come le lame più pregiate. Lo guarderai negli occhi e conoscerai la morte.",
}
T[4292] = {
  title = "L'Esca per Lar'korwi",
  desc = "Questa sarà la parte più difficile, perché il piano è piuttosto complesso. A nord di qui troverai un piccolo sentiero che sale fra le montagne. È lì che ho visto Lar'korwi l'ultima volta. Capirai di essere nel posto giusto da tutte le ossa delle creature enormi che un tempo vagavano lì intorno. Prendi la carne che hai recuperato e mettila lì. Poi strofina sulla carne questa mistura che ho preparato. Se le due esche mescolate insieme non faranno venire Lar'korwi da te, allora non conosco nient'altro che possa riuscirci.",
  obj = "Usa il contenuto di Torwa's Pouch per richiamare Lar'korwi e sconfiggilo. Poi porta Lar'korwi's Head a Torwa Pathfinder, vicino all'ingresso dell'Un'Goro Crater.",
  progress = "Non lasciarti sopraffare dalla paura, $N. La paura è la grande traditrice... devi restare forte!$B$BPrendi la carne, mettila nella piccola valle e poi usaci sopra la ghiandola. Solo allora la morte verrà a cercarti.",
  reward = "Sia lodata la Madre Terra! Ce l'hai fatta! Onore al merito, $N. Hai dimostrato di essere $Gun grande cacciatore:una grande cacciatrice; a pieno titolo. Il tuo spirito è forte. Il tuo coraggio non ha pari. E la tua forza si è temprata. Mi inchino davanti alla tua abilità.$B$BSolo i più grandi fra i miei antenati sarebbero riusciti in un'impresa così incredibile. Congratulazioni.",
}
T[4293] = {
  title = "Un Campione di Melma...",
  desc = "Felwood è una foresta molto a nord delle Barrens, ancora più lontana di Ashenvale. Lì le melme si trovano tutt'intorno a pozze d'acqua benedette dal tocco del Fel. Il Flagello ha devastato la zona con attacchi di Infernali e altre magie demoniache — pare che le melme siano risalite dalla terra durante questi attacchi.$B$BRaccogli dei campioni delle melme di Felwood, e useremo l'apparecchiatura per le analisi qui accanto a me per creare un gruppo di controllo con cui confrontare, nei nostri test, gli altri campioni che raccoglierai.",
  obj = "Raccogli dei Felwood Slime Samples da una qualsiasi delle melme di Felwood. Poi, con il Testing Equipment accanto a Chemist Fuely, a Undercity, scopri quali dei tuoi campioni sono i più corrotti. Porta a Chemist Fuely 5 dei Corrupted Felwood Samples che trovi.",
  progress = "Mi serviranno almeno cinque campioni corrotti per il nostro gruppo di controllo, $N. Continua a raccogliere campioni di melma di Felwood finché non potrai darmi quello che ci servirà. Lo decreta Lady Sylvanas...",
  reward = "Ah, eccellente. Questi campioni andranno benissimo. Ti ringrazio dell'aiuto.$B$BQuando avremo raccolto tutti i campioni di melma, potremo capirne di più. Comincio a sospettare che l'intuizione di Lady Sylvanas non fosse solo giusta, ma più acuta di quanto lei stessa potesse prevedere. Questi campioni sono molto interessanti. Solo a vedere come hanno reagito con i miei composti... hmm, sì, dovremo senz'altro indagare più a fondo.",
}
T[4294] = {
  title = "... e una Partita di Poltiglia",
  desc = "Hai mai sentito parlare dell'Un'Goro Crater, $N? Si trova vicino al deserto di Tanaris, ed è un posto magnifico: lussureggiante, pieno di vita, ricco di creature e di piante.$B$BÈ là che devi andare. Mi è giunta voce che quel posto sembra del tutto incontaminato da mani estranee. Gli esploratori ne stanno scoprendo i segreti solo adesso.$B$BVorrei analizzare le melme o le poltiglie di quel posto. Se è vero — che sono incorrotte — allora vorrei vedere come si sono evolute creature simili.",
  obj = "Raccogli degli Un'Goro Slime Samples da una qualsiasi delle melme dell'Un'Goro Crater. Poi, con il Testing Equipment accanto a Chemist Fuely a Undercity, scopri quali dei tuoi campioni sono i più puri. Porta a Chemist Fuely 5 dei Pure Un'Goro Samples che trovi.",
  progress = "Sì, $N? Come procede la tua ricerca?",
  reward = "Davvero straordinario, $N. Questo Un'Goro Crater nasconde molti più segreti di quanto mi aspettassi. Mi chiedo cos'altro scopriremo proseguendo con le analisi.$B$BSemplicemente straordinario... guarda la purezza di questi campioni. Mmm, mi chiedo cosa possa significare. Sembrano di natura elementale, ma... c'è qualcosa di più. Mi ricordano gli... gli Dei Antichi. Ne abbiamo trovato tracce in tutta Azeroth, e ora mi chiedo se queste creature non siano in qualche modo imparentate con loro.$B$BDovremo fare altre analisi.",
}
T[4295] = {
  title = "La Birra di Rocknot",
  progress = "Oh, birra! Ucciderei per un po' di birra Dark Iron!! Presto, sto tornando sobrio! Lo so perché la sobrietà mi annebbia la vista... e mi fa sembrare che tu sia $Gil:la; $R che ho ucciso la settimana scorsa!",
  reward = "Cos'è questo? Ah! Ha l'odore della Birra Dark Iron! Il bere mi ha annebbiato la vista, ma capisco che tu, $Gsignore:signora;, sei $Gun vero amico:una vera amica;!",
  en_title = "Rocknot's Ale",
}
T[4296] = {
  title = "Tavoletta dei Sette",
  desc = "Sono venuto nelle Burning Steppes seguendo le leggende dei Sette. Erano nani di grande sapienza e potere, e se hai sapienza e potere, la ricchezza arriva di sicuro.$B$BÈ questo che voglio. La ricchezza!$B$BSe scopriamo qualcosa di più sui Sette, magari diventiamo ricchi insieme. Si dice che fra le rovine di Thaurissan sia custodita la Tavoletta dei Sette, che racchiude il sapere degli antichi nani. Trova la tavoletta, copiane il testo e portamelo. Scopriamone insieme i segreti!",
  obj = "Porta la Tablet Transcript a Maxwort Uberglint, nelle Burning Steppes.",
  progress = "Hai gli scritti dei Sette, $N? Hai scoperto i segreti della loro tavoletta?",
  reward = "Ah, hai trovato la tavoletta! E la tua trascrizione è magnifica! Sei $Gsicuro:sicura; di essere $Gun:una; $C e non $Guno:una; scriba?$B$BEcco a te, $N. Questo è il compenso che ti avevo promesso.",
}
T[4297] = {
  title = "La Pappa per il Piccolo",
  desc = "I folletti sfreccianti sono onnivori — vuol dire che mangiano sia carne sia vegetali. Se il tuo uovo deve schiudersi, sarà meglio farci trovare pronti. Per questi piccoletti vanno bene le costate di carne, crude e succose, che tu ci creda o no. Non sono mai riuscito a scoprire perché, ma ha qualcosa a che fare con i piani di Elune per gli elfi... forse dovevano essere dei protettori o qualcosa del genere, non lo so.$B$BPer adesso all'uovo ci penso io. Perché non mi porti qualche bella costata di inseguitore Peloargento da fargli mangiare quando sarà nato?",
  obj = "Porta 5 Silvermane Stalker Flank ad Agnar Beastamer, nelle Hinterlands.",
  progress = "Hai già trovato la carne, $N? Il tuo uovo è quasi pronto a schiudersi. Se non gli dai un primo pasto come si deve, potrebbe non arrivare alla fine della prima settimana, e mi dispiacerebbe un sacco.$B$BNon ti posso mentire, $N: già solo per aver avuto quest'uovo ti invidio parecchio. Non farmi pentire di averti dato una mano così.",
  reward = "Questi andranno benissimo, e se non sbaglio il tuo uovo è quasi pronto a schiudersi. Che effetto fa? Sai, stare per diventare $Gpapà:mamma;? Ah ah, non pensavi di doverti prendere una responsabilità del genere, eh?",
}
T[4298] = {
  title = "Diventare Genitore",
  desc = "Accidenti, era molto più pronto di quanto pensassi...",
  obj = "Parla con Agnar Beastamer, nelle Hinterlands.",
  reward = "Tieni, prendi l'uovo... meglio che lo tenga tu, così si affeziona a te e ti vede come $Gil suo papà:la sua mamma;.$B$BCongratulazioni, $N. Ora sei un genitore... più o meno.",
}
T[4300] = {
  title = "Armi con la Lama d'Osso",
  desc = "Mmh, forse c'è qualcosa che puoi fare per la Hand, ora che ci penso. Sì, a Jes'rimon il tuo aiuto gli serve di sicuro.$B$BNell'Un'Goro Crater ci stanno dei raptor con gli artigli micidiali. Certi di quei raptor ogni tanto ci hanno gli artigli bianchi invece che neri come la morte. La Hand ci ha dei... clienti... che gli piacciono le armi fatte con questi artigli. Portami tanti di quegli artigli bianchi, e io ti pago bei soldi. Fallo abbastanza in fretta, e magari ti aiuto pure in altri modi.",
  obj = "Porta 8 White Ravasaur Claws a Jes'rimon, a Orgrimmar.",
  progress = "I clienti miei non ci hanno tanta pazienza, $N. Ne hai già presi di artigli?",
  reward = "Ah, questi vanno bene. Grazie, $N. E sei qui molto prima che servivano... questo è bene.$B$BMagari ti facciamo fare un'arma con gli artigli. Che ne dici?",
}
T[4301] = {
  title = "Il Possente U'cha",
  desc = "Mentre tu esploravi Un'Goro, io ho visto altre cose che farebbero la gioia di $Gun possente cacciatore:una possente cacciatrice; come te. Una di queste era un enorme scimmione fra gli altri gorilla a nord. In quella caverna ci sei già $Gstato:stata;, ma questa volta, se accetti il mio incarico, mi chiedo se sopravvivrai all'incontro.$B$BIo lo chiamo U'cha, ed è uno dei più grandi figli della Madre Terra, di questo puoi star $Gcerto:certa;. Sconfiggi U'cha e portami la sua pelle. Fallo, e difenderò il tuo diritto di definirti $Gun grande cacciatore:una grande cacciatrice;.",
  obj = "Porta U'cha's Pelt a Torwa Pathfinder all'ingresso di Un'Goro Crater.",
  progress = "U'cha... la bestia era magnifica. Enorme e rossa, con denti grandi come pugnali. Le braccia grosse come tronchi d'albero, e veloci come qualunque puma su cui io abbia mai posato gli occhi. Dovresti ritenerti $Gfortunato:fortunata; ad aver trovato una tale prova di coraggio — il mio popolo può passare generazioni intere senza vedere una creatura simile.",
  reward = "Ben fatto, $N. Sono soddisfatto. Oggi qui hai compiuto una grande impresa.$B$BU'cha era una delle scimmie più grandiose che avessi mai visto. Il fatto che tu abbia superato la sua forza fa onore alla tua forza... e al tuo coraggio.$B$BÈ giusto che io ti dia questo in segno di rispetto. L'hai meritato.",
}
T[4321] = {
  title = "Venirne a Capo",
  desc = "Le informazioni che mi hai dato sui piloni sono molto interessanti...$B$BDammi un momento per fare qualche calcolo, $N. Torna a parlarmi tra un attimo e dovrei essere in grado di darti la risposta che cercavamo.",
  obj = "Parla con J.D. Collie tra un momento.",
  reward = "Bene, $N. È affascinante... Posso solo sperare che i miei diagrammi siano corretti! Ho raccolto tutto in questo manuale, che puoi tenere.$B$BAdesso credo di poter rispondere a qualsiasi tua domanda sui cristalli, $N.",
}
T[4322] = {
  title = "Evasione!",
  desc = "Dobbiamo andarcene da qui, $N. Aiutami a recuperare il mio equipaggiamento dal deposito e a liberare i miei amici. Se riusciamo a uscire da qui, devi andare al Presidio di Morgan e parlare con il Maresciallo Maxwell. Ti darà lui altre istruzioni.",
  obj = "Aiuta Marshal Windsor a recuperare il suo equipaggiamento e a liberare i suoi amici. Se ci riesci, torna da Marshal Maxwell.",
  progress = "Hai l'aria esausta, $N. Forse dovresti sederti accanto al fuoco e rilassarti.",
  reward = "Incredibile, $N. Semplicemente incredibile. Windsor è passato di qui come una furia nemmeno cinque minuti fa. Fa affermazioni clamorose, ma sostiene che le sue prove le confermino. Ora è in viaggio per Stormwind, per affrontare Bolvar e ... Lady Prestor.",
}
T[4324] = {
  title = "Yuka Screwspigot",
  desc = "Il mio fratellino Ribbly non è mai valso niente in vita sua, ma credo che adesso, finalmente, un valore ce l'abbia! Però... potremmo aver bisogno del tuo aiuto per mettere a frutto questo suo nuovo valore.$B$BMia sorella Yuka lo cerca da settimane, e ha seguito le sue tracce fino alle Burning Steppes. Mi ha fatto sapere che le serve gente a pagamento.$B$BAllora, che ne dici? Vuoi darci una mano? Se sì, parla con mia sorella. La troverai rintanata al Cimiero Ardente, una grotta a nord-ovest del Masso dei Dreadmaul.",
  obj = "Parla con Yuka Screwspigot nelle Burning Steppes.",
  reward = "Sì, sto cercando mio fratello. Dobbiamo trovarlo e riportarlo indietro, povero caro.$B$BMa se non riusciamo a portarlo tutto intero... allora basterà la testa.",
}
T[4341] = {
  title = "Kharan Mighthammer",
  desc = "Sei $Gstato:stata; alle rovine fumanti di Thaurissan? Ti è capitato di incontrare un miserabile zoticone di nome Kharan Mighthammer? Il nano che in teoria doveva badare alla mia bambina!$B$B<Il Re singhiozza.>$B$BE adesso è sparita, $N!$B$BHo mandato i miei uomini a rivoltare le Steppes da cima a fondo. L'unico indizio che hanno su dove si trovi mia figlia è che potrebbe essere dentro le Depths. Per quel che ne so, potrebbe essere morta!$B$BA quanto pare Kharan è tenuto prigioniero lì... trovalo! Voglio delle risposte!",
  obj = "Vai nelle Blackrock Depths e trova Kharan Mighthammer.$B$BIl Re ha detto che Kharan è tenuto prigioniero lì — forse dovresti cercare una prigione.",
  reward = "Ti prego, lasciami spiegare.",
}
T[4342] = {
  title = "Il Racconto di Kharan",
  desc = "Ti prego, ascoltami fino in fondo prima di giudicarmi!",
  obj = "Ascolta Kharan Mighthammer mentre racconta la sua storia.",
  progress = "Lasciami finire di raccontare la mia storia.",
  reward = "Come vedi, non avrei potuto fare niente.",
}
T[4343] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4361] = {
  title = "Il Latore di Cattive Notizie",
  desc = "Devi portare queste informazioni a Re Magni, $N. Lui saprà cosa fare!",
  obj = "Torna a Ironforge e porta le cattive notizie a King Magni Bronzebeard.",
  reward = "<Re Magni batte il pugno con rabbia.>",
}
T[4362] = {
  title = "Il Destino del Regno",
  desc = "A quanto pare il mio vecchio avversario, Dagran Thaurissan, tiene in pugno me e il regno di Ironforge.$B$BPotresti essere la mia ultima speranza, $N. Devi salvare la mia cara figlia, Moira!$B$BC'è un solo modo per essere certi di spezzare l'incantesimo che Thaurissan ha lanciato su Moira: ucciderlo.$B$BE $N, non farle del male! Ricorda, è Thaurissan a controllarla! Quello che potrà fare o dire è frutto del malvagio incantesimo di Thaurissan!",
  obj = "Torna nelle Blackrock Depths e salva Princess Moira Bronzebeard dalle grinfie malvagie di Emperor Dagran Thaurissan.",
  reward = "<La Principessa Bronzebeard piange la perdita dell'Imperatore Dagran Thaurissan.>$B$BPerché???",
}
T[4363] = {
  title = "La Sorpresa della Principessa",
  desc = "Thaurissan era un grande nano, un nano d'onore. Hai rovinato la mia vita e quella del bambino che porto in grembo!$B$B<Pensi che la Principessa Bronzebeard possa essere ancora sotto l'effetto residuo dell'incantesimo dell'Imperatore.>$B$BTorna a Ironforge e di' a mio padre che l'erede del Regno di Ironforge sarà un nano Dark Iron.$B$BChe lui approvi o no, così sarà.",
  obj = "Torna a Ironforge e parla con King Magni Bronzebeard.",
  reward = "<Re Magni Bronzebeard è visibilmente turbato.>$B$BA quanto pare, perfino da morto, Thaurissan ha vinto.$B$BPuoi andare, $N. Prima di lasciarci, scegli pure la tua ricompensa dal tesoro reale.$B$B<Re Bronzebeard si accascia sul trono a rimuginare su questa bizzarra piega degli eventi.>",
}
T[4381] = {
  title = "Ristoro Cristallino",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici verdi con quelli gialli.$B$BSecondo il manuale di J.D., questa combinazione si può usare per curare te o i tuoi alleati.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4382] = {
  title = "Forza Cristallina",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici verdi con quelli blu.$B$BSecondo il manuale di J.D., questa combinazione si può usare per aumentare il tuo spirito.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4383] = {
  title = "Protezione Cristallina",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici verdi con quelli rossi.$B$BSecondo il manuale di J.D., questa combinazione si può usare per rafforzare la tua protezione dai danni fisici.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4384] = {
  title = "Cedimento Cristallino",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici rossi con quelli blu.$B$BSecondo il manuale di J.D., questa combinazione si può usare per indebolire le difese di un nemico.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4385] = {
  title = "Carica Cristallina",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici rossi con quelli gialli.$B$BSecondo il manuale di J.D., questa combinazione si può usare per creare una grande esplosione capace di infliggere danni ai tuoi nemici.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4386] = {
  title = "Guglia Cristallina",
  progress = "Il tavolo del Pilone ti permette di combinare i cristalli energetici blu con quelli gialli.$B$BSecondo il manuale di J.D., questa combinazione si può usare per creare uno scudo che infligge danni ai nemici.",
  reward = "Disponi i cristalli sul tavolo e ne allinei con cura i colori. Quando spingi l'ultimo al suo posto, un lampo di luce li fonde insieme.$B$BLa combinazione ottenuta ora è tua.",
}
T[4401] = {
  title = "Songflower Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di songflower. La pianta emana un odore pungente e malsano. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi un po' di unguento per piante Cenarion sul songflower. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4403] = {
  title = "Windblossom Corrotto",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di windblossom. Le bacche che pendono dalla pianta sembrano marce e velenose. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi due unguenti per piante Cenarion sul windblossom. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
T[4421] = {
  title = "La Corruzione dei Jadefire",
  desc = "Non sono molti a cercare avventure qui... La corruzione di Felwood è estesa e indiscriminata.$B$BCome membro dell'Emerald Circle cerco di guarire questa terra, ma c'è chi vuole che marcisca.$B$BParlo dei satiri Jadefire che dimorano a nord-ovest di qui, alle Rovine di Constellas. Guidati da un satiro particolarmente crudele di nome Xavathras, continuano a diffondere il morbo fra tutte le creature che incontrano.$B$BDobbiamo difendere questa terra che un tempo era nostra. Sconfiggi Xavathras e distruggi i suoi servitori.",
  obj = "Uccidi 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues e Xavathras. Torna da Eridan Bluewind a Felwood quando avrai portato a termine il compito.",
  progress = "Qui la corruzione spinge le creature alla follia...",
  reward = "Liberare Felwood da Xavathras è solo il primo passo di un lungo percorso. Ci vorrà molto lavoro per riparare i danni che sono stati fatti qui.$B$BSento che qui è all'opera qualcosa di molto più grande dei soli satiri, ma la verità la conosceremo solo col tempo...",
}
T[4441] = {
  title = "Antichi Vincolati dal Fel",
  desc = "Il flauto che hai trovato è stato intagliato nel legno di un antico protettore, uno dei treant alleati che hanno protetto fedelmente gli elfi della notte.$B$BI satiri sono riusciti a corrompere tutto ciò con cui entrano in contatto, compresi gli antichi che avevano fatto di Felwood la loro casa. Con l'uso del fel, lo spirito dell'antico è stato vincolato e torturato, e mai liberato del tutto. Il felbind che hai trovato c'entra di sicuro.$B$BDobbiamo provare a purificare il flauto, $N. Portami dell'acqua benedetta dal Tempio della Luna di Darnassus.",
  obj = "Va' a Darnassus e usa Eridan's Vial per raccogliere una Vial of Blessed Water a Temple of the Moon. Torna da Eridan Bluewind con la fiala piena.",
  progress = "Si spera che l'acqua liberi lo spirito dell'antico e gli permetta di trovare pace.",
  reward = "Grazie, $N. Ora dobbiamo pregare di riuscire a rimediare al danno che è stato fatto...",
}
T[4442] = {
  title = "Purificato!",
  desc = "Con l'acqua di Elune tenterò di purificare il flauto. Dobbiamo porre fine a questa sofferenza...$B$BChe Elune guidi le mie mani e il mio cuore.$B$BParlami di nuovo fra un momento.",
  obj = "Parla di nuovo con Eridan Bluewind fra un momento.",
  reward = "Con l'acqua benedetta sono riuscita a spezzare il legame fra il flauto e lo spirito dell'antico. Credo però che, se usassi questo flauto in un luogo sacro, potresti riuscire a evocare gli spiriti degli antichi.$B$BPotresti provare alle rovine nella parte meridionale del Bosco di Irontree. Un tempo quella zona era abitata da molti treant corrotti, ed è possibile che siano ancora lì, anche solo in forma di spirito.",
}
T[4443] = {
  title = "Radice Sferzante Corrotta",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di radice sferzante. Le radici visibili sembrano dure e coriacee, e dalla pianta pende una pellicola viscida. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi 3 Unguenti per Piante Cenarion sulla Radice Sferzante. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
