T[4449] = {
  title = "In Trappola!",
  desc = "Ehi! Ehi, tu! Vieni qua!$B$BMi devi dare una mano. Scappavo da quei nani Dark Iron e mi sono $Gnascosto:nascosta; qui dentro per non farmi vedere. Maledetti geologi bastardi, con le loro magie! Devono avermi visto mentre mi nascondevo, perché un attimo dopo hanno chiuso la porta a chiave e mi hanno bloccato qui dentro.$B$BDai una lezione a quei geologi! Ah... e mi porteresti qualche pezzo di silk cloth per... per... niente.",
  obj = "Uccidi 8 Dark Iron Geologists e porta 15 pezzi di Silk Cloth alla persona chiusa nella latrina della Searing Gorge.",
  progress = "Non ho mica tutto il giorno! Portami quei pezzi di silk cloth! Cioè, i geologi. Fai fuori quei geologi! Meritano di assaggiare la mia, be'... la tua ira.",
  reward = "Oh, che meraviglia! Ed è pure bello al tatto!$B$BCosa? Ah, sì... i geologi. Li hai sistemati per bene, eh? Non so come ringraziarti, $N. Così avrò un po' di tempo per finire qua dentro... Grazie ancora, $N.",
}
T[4450] = {
  title = "Registro da Tanaris",
  desc = "Ah, sai che c'è? Mi hai fatto venire in mente una cosa.$B$BTi va di finire un lavoretto che ho preso quand'ero a Tanaris? È facile...$B$BKrinkle Goodsteel, a Gadgetzan, cercava della roba che si trova qui nella Searing Gorge e in qualche altro posto. Magari potresti dare un'occhiata alla lista e poi portargli tutto?$B$BSe ti interessa, ti passo il suo registro sotto la porta. Prendilo e, quando hai raccolto tutto, riportaglielo insieme alla roba che vuole.",
  obj = "Prendi la copia del Goodsteel Ledger, trova gli oggetti che elenca e poi cerca Krinkle Goodsteel a Tanaris.",
  progress = "Sì, sì? Cosa posso fare per te, $R? Ho un sacco da fare e tanti clienti che richiedono i miei servizi. Magari tu puoi accelerare le cose. Non vorrei sembrare scortese, ma non ho proprio tempo, se voglio rimettermi in pari con tutto il lavoro.",
  reward = "Oh, hai pensato bene di fare un po' del lavoro che avevo chiesto. Eccellente. E io che credevo volessi chiedermi di fabbricarti qualcosa.$B$BÈ tutto perfetto... e non manca niente. Grazie, $C.$B$BMagari non guasterebbe darti una piccola ricompensa... mmh, cosa potrebbe tornarti utile.",
}
T[4451] = {
  title = "La Chiave della Libertà",
  desc = "La piccola chiave d'ottone sembra piuttosto semplice. L'unica cosa che la distingue sono alcune parole graffiate sulla testa:$B$B\"Latrina dei Dark Iron — Non Duplicare.\"$B$BNon hai idea di cosa significhi né a cosa porterà.",
  obj = "Esplora la Searing Gorge e scopri a cosa serve la Grimesilt Outhouse Key che hai trovato.",
  progress = "*coff*$B$BChi è? Non vedi che sono $Goccupato:occupata;?",
  reward = "Ma guarda un po'! Ma come diavolo!? Hai trovato la chiave! Lo sapevo che quei maledetti Dark Iron la tenevano nascosta, dopo avermi chiuso qui dentro! Grazie mille, $N. Sei $Gil:la; migliore! Ora gira la chiave e fai uscire di qui il vecchio Locheed!",
}
T[4461] = {
  title = "Radice Sferzante Corrotta",
  progress = "Hai trovato una versione malata e corrotta di quella che sembra una pianta di radice sferzante. Le radici che si vedono hanno un aspetto duro e coriaceo, e dalla pianta pende una patina viscida. Ha un disperato bisogno di qualche cura per tornare com'era.",
  reward = "Applichi 3 Unguenti per Piante Cenarion sulla Radice Sferzante. Subito comincia a liberarsi della sua forma corrotta e sboccia in una pianta vigorosa e sana.",
}
