T[4463] = {
  title = "Libram della Meditazione",
  progress = "Consegnami i componenti, mortale.$B$BPer questa creazione esigo anche un pagamento di trenta monete d'oro.",
  reward = "Prendi il tuo monile, $Gsciocco:sciocca;. Lasciami ai miei studi!",
}
