T[4481] = {
  title = "Libram della Costituzione",
  progress = "Ogni cosa a questo mondo ha un prezzo. Quello dell'oggetto che cerchi è di trenta monete d'oro.$B$BNaturalmente tratterrò la maggior parte dei componenti che hai raccolto. Ma non temere, avrai il tuo monile.",
  reward = "È un'offesa alla sua memoria... $Gun:una; mortale, come te, che porta a termine l'opera della sua vita.$B$BPrendi il tuo amalgama e vattene!",
}
T[4482] = {
  title = "Libram della Tenacia",
  progress = "Trenta monete d'oro, $R. Trenta monete d'oro e i componenti richiesti.",
  reward = "Per completare il libram che ora hai tra le mani, $R, a Kariel è servito un tempo pari a parecchie delle tue vite. E tutto per cosa? Perché il suo discepolo potesse starsene nelle Burning Steppes a snaturare le sue ricerche per saziare una brama arcana senza fine... Sia maledetta questa turpe dipendenza.$B$BLa tua mancanza di compassione e la tua avidità insaziabile mi disgustano. Vattene!",
}
T[4483] = {
  title = "Libram della Resilienza",
  progress = "Se è la resilienza che desideri, trenta monete d'oro io richiedo.",
  reward = "Altri libram sono andati perduti in questo mondo. Perduti in luoghi dove non oseresti entrare. Luoghi che pregheresti non esistessero.$B$BIo mi abbevererò alle energie di questi componenti. A te andranno gli scarti residui...",
}
T[4484] = {
  title = "Libram della Voracità",
  progress = "Non farmi perdere tempo, $R. Dammi quello che mi serve. Trenta monete d'oro e i componenti.",
  reward = "Mi pulsa la testa... Le energie delle vaste distese che compongono il nostro universo... ARGGH!$B$BPrendi quello che desideri e vattene!",
}
T[4485] = {
  title = "Il Tomo della Nobiltà",
  desc = "Salve, $N. Vedo che la tua dedizione resta salda, come la tua fede.$B$BCredo sia ora che tu parli con Duthorian Rall, a Stormwind. Hai altre lezioni da imparare, e sento che sei $Gpronto:pronta;.$B$BCercalo nella Cattedrale della Luce e, $N, prendi sul serio queste lezioni. Hai raggiunto la tua posizione con l'umiltà e il duro lavoro, non deluderci diventando arrogante.$B$BAbbi cura di te.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Ah, sei $Gtornato:tornata; alla Cattedrale, $N. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai $Gdegno:degna;.$B$BIn giro ci sono molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.",
}
T[4486] = {
  title = "Il Tomo della Nobiltà",
  desc = "Bene, bene, bene, guarda $Gil potente paladino:la potente paladina; in tutta la sua regalità.$B$BScusa, $N, non volevo offenderti... è che ogni tanto divento un po' invidioso, quando vedo certe imprese che hai compiuto. Tiza mi dice che è il mio punto debole, e le ho giurato che ci avrei lavorato. È che a volte è dura, sai?$B$BMa volevo parlarti perché Duthorian Rall, a Stormwind, ha mandato a dire di raggiungerlo alla Cattedrale della Luce quando sei $Gpronto:pronta;. Sembrava importante. Sembrava che stesse succedendo qualcosa.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Ah, sei $Gtornato:tornata; alla Cattedrale, $N. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai $Gdegno:degna;.$B$BIn giro ci sono molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.",
}
T[4487] = {
  title = "Summon Felsteed",
  desc = "Ah, bene, sei qui. Ti ho mandato dietro $Guna succube:un infernale; per attirare la tua attenzione, ma a quanto pare sei $Griuscito:riuscita; ad arrivare prima che ti trovasse. Poco importa.$B$BUltimamente si parla del tuo potere che cresce — buon per te, forse un male per altri. Ma sono dettagli irrilevanti. Il punto è che secondo me hai dimostrato quanto vali e quindi meriti... hehe... una specie di benedizione.$B$BSopra Ratchet, nelle Barrens, troverai un uomo di nome Strahad. Mi pare che vi siate già incontrati.",
  obj = "Parla con Strahad Farsan, a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile.$B$BI miei accoliti si chiedevano se ti saresti mai $Gpresentato:presentata;. Ho detto loro che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4488] = {
  title = "Summon Felsteed",
  desc = "Ah, $N, hai pensato bene di onorarci della tua presenza. Che meraviglia!$B$BSpero che tu non ti aspetti anche di essere $Gservito e riverito:servita e riverita;. Il tuo potere crescerà anche in fretta, ma quanto a vera conoscenza e comprensione sei ancora un cucciolo. Se non stai $Gattento:attenta;, la corruzione travolgerà te e la tua debole volontà.$B$BMa è meglio che venga al punto: Strahad vuole parlarti. Sta ancora nella sua torre che domina Ratchet, nelle Barrens. Ti consiglio di non metterci troppo.",
  obj = "Parla con Strahad Farsan, a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile.$B$BI miei accoliti si chiedevano se ti saresti mai $Gpresentato:presentata;. Ho detto loro che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4489] = {
  title = "Summon Felsteed",
  desc = "Tu, $R! Vieni qui!$B$BSei tu $Gquello:quella; che chiamano $N, vero?$B$BLo immaginavo. Sarò breve: il tuo potere cresce, e la cosa è stata riconosciuta. E ora è arrivato il momento che tu riceva la ricompensa per i tuoi sforzi.$B$BVa' nelle Barrens. Lì, sopra Ratchet, troverai Strahad Farsan — forse te lo ricordi? Vorrebbe scambiare due parole con te. Io non ci metterei troppo.",
  obj = "Parla con Strahad Farsan, a Ratchet.",
  reward = "Così hai deciso di onorarmi di nuovo della tua presenza. Che gentile.$B$BI miei accoliti si chiedevano se ti saresti mai $Gpresentato:presentata;. Ho detto loro che non c'era alcun dubbio. Quando c'è di mezzo il potere, ne sei $Gattratto:attratta; come una falena dalla fiamma.",
}
T[4490] = {
  title = "Summon Felsteed",
  desc = "Voglio ricompensare la tua pazienza e il tuo impegno. Sappi però che in futuro la capacità di evocare un Felsteed sarà molto più difficile da ottenere. Dovrai guadagnartela... e non sarà facile.$B$BPer ora vai, con il potere di evocare una creatura simile, e usalo come meglio credi.",
  obj = "Parla con Strahad Farsan a Ratchet per imparare a evocare un Felsteed.",
  reward = "Buona fortuna, $N. Conto di rivederti in futuro.",
}
T[4491] = {
  title = "Un Piccolo Aiuto dai Miei Amici",
  desc = "Uff... Fa così caldo...$B$BStavo esplorando questa zona, quando all'improvviso il caldo è diventato insopportabile. Devo aver preso un colpo di calore.$B$BTi prego, aiutami a tornare dalla mia amica Spraggle al Rifugio dei Marshal. Credo di stare abbastanza bene da seguirti fin là.$B$BMi sento un po' stordito, quindi se dovessi svenire di nuovo, spruzzami addosso un po' d'acqua dalla borraccia di Spraggle. Dovrebbe funzionare, spero...",
  obj = "Accompagna Ringo da Spraggle Frock al Rifugio dei Marshal.$B$BSe Ringo sviene, usa Spraggle's Canteen per farlo rinvenire.",
  progress = "Sono stata così in pensiero per Ringo...",
  reward = "Ringo non è proprio in gran forma, $N, ma sono contenta di riaverlo qui tutto intero!$B$BGrazie per averlo trovato.",
}
T[4492] = {
  title = "Disperso!",
  desc = "Devi aiutarmi, $N! Il mio amico Ringo è partito un po' di tempo fa per esplorare il vulcano a sud di qui, ed è via da fin troppo tempo. Sono davvero preoccupata per lui.$B$BPensi di poterlo trovare? Porta pure con te la mia borraccia — se trovi Ringo, sono sicura che gli servirà!",
  obj = "Trova Ringo a Fire Plume Ridge.",
  progress = "Co... Cosa?",
  reward = "Oh... Sono così contento che qualcuno mi abbia trovato...",
}
T[4493] = {
  title = "La Marcia dei Silithid",
  desc = "Sembrerebbe che l'intento dei silithid, anzi — la loro ragion d'essere, sia divorare sul loro cammino tutto ciò che non fa parte del loro ecosistema. Hanno un unico scopo, ed è per questo che sono una grave minaccia per ogni forma di vita su Azeroth.$B$BFinora abbiamo visto soltanto le prime fasi. Sospetto che la loro forza venga da una zona più interna di Kalimdor: l'Un'Goro Crater. Va' a Gadgetzan, nel deserto di Tanaris, e parla con l'Alchimista Pestlezugg. Esponigli la mia teoria; ci aiuterà di sicuro a combattere i silithid.",
  obj = "Parla con Alchemist Pestlezugg a Gadgetzan.",
  reward = "Sì, avevo capito che ti ha mandato Gracina. La tua esperienza nel combattere queste bestiole non ha prezzo; che io sappia, nessuno ha mai avuto a che fare con esseri del genere prima d'ora. Quanto all'idea di Gracina che l'Un'Goro Crater sia il loro cuore... forse è così. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. E forse è anche un passo avanti per capire cosa c'è dietro ai silithid.",
}
T[4494] = {
  title = "La Marcia dei Silithid",
  desc = "Sembrerebbe che l'intento dei silithid, anzi — la loro ragion d'essere, sia divorare sul loro cammino tutto ciò che non fa parte del loro ecosistema. Hanno un unico scopo, ed è per questo che sono una grave minaccia per ogni forma di vita su Azeroth.$B$BFinora abbiamo visto soltanto le prime fasi. Sospetto che la loro forza venga da una zona più interna di Kalimdor: l'Un'Goro Crater. Va' a Gadgetzan, nel deserto di Tanaris, e parla con l'Alchimista Pestlezugg. Esponigli la mia teoria; ci aiuterà di sicuro a combattere i silithid.",
  obj = "Parla con Alchemist Pestlezugg a Gadgetzan.",
  reward = "Sì, l'avevo capito che ti ha mandato da me Zilzibin. La tua esperienza nel combattere queste bestiacce non ha prezzo; che io sappia, nessuno ha mai avuto a che fare con creature del genere prima d'ora. Quanto all'idea di Zil che l'Un'Goro Crater sia il loro cuore... forse lo è. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Forse è anche un passo in più verso la comprensione di cosa siano davvero i silithid.",
}
T[4496] = {
  title = "Un Pasticcio nella Giungla",
  desc = "Dalle mie ricerche ho scoperto che i silithid sono come le api; distruggi la regina dell'alveare, e tutti gli altri dovrebbero finire nel caos. Preparerò un'esca che useremo per far uscire la regina; una volta evocata, toccherà a te abbatterla.$B$BPrima però ci servono dei reagenti; non vogliamo che tu vada a fare pasticci nella giungla $Gimpreparato:impreparata;. Vai a ovest, trova l'alveare dei silithid nell'Un'Goro Crater e procurati una ghiandola odorosa da uno di quegli insetti. Mi serviranno anche dei campioni del terreno autoctono di Un'Goro.",
  obj = "Porta una Gorishi Scent Gland e 5 campioni di Un'Goro Soil ad Alchemist Pestlezugg, a Gadgetzan.",
  progress = "Trovare una ghiandola odorosa adatta potrebbe richiedere un po' di tempo — la ghiandola non dev'essere danneggiata, ma il modo in cui la si ottiene di certo non aiuta. Quanto al terreno, immagino che sia abbastanza facile da trovare.$B$BComunque, hai gli oggetti che mi servono per preparare l'esca?",
  reward = "La ghiandola odorosa, ah sì. La membrana sembra intatta — ottimo. Il terreno, sì, dovrebbe andare alla perfezione. Con le mie aggiunte speciali, dovrei riuscire a macinare tutto e ricavarne l'esca perfetta.$B$BDammi un momento per preparare l'esca, $N. Appena sarà pronta, potremo passare alla fase successiva, che, si spera, fermerà i silithid prima che invadano Gadgetzan... e il resto di Kalimdor.",
}
T[4501] = {
  title = "Attenti agli Pterrordax",
  desc = "Cercasi: abile combattente per affrontare la minaccia degli Pterrordax che popolano Un'Goro Crater. Il loro numero è in crescita, e stanno diventando un pericolo per chi viaggia nella zona.$B$BRiduci la popolazione uccidendo 10 pterrordax e 15 pterrordax furiosi.$B$BA incarico concluso, parla con Spraggle Frock per ricevere una ricompensa.",
  obj = "Uccidi 10 Pterrordax e 15 Frenzied Pterrordax, poi parla con Spraggle Frock al Rifugio di Marshal.",
  progress = "A dire il vero, quelle strane creature non mi preoccupavano poi tanto... Fino al giorno in cui l'ho visto scritto sul fianco di una grossa pietra.$B$BATTENTI AGLI PTERRORDAX$B$BChi può averlo scritto? Non lo so, ma è troppo inquietante per ignorarlo e basta!",
  reward = "Sono assolutamente terrorizzata dagli pterrordax di qui! Grazie per averne ridotto il numero, $N. Ora forse mi sentirò abbastanza al sicuro da avventurarmi fuori dal Rifugio di Marshal.",
}
T[4502] = {
  title = "Attività Vulcanica",
  desc = "Come apprendista di Marvon Rivetseeker ho imparato tantissimo. Ma ormai manca da così tanto tempo che penso di mettermi a lavorare a qualche esperimento tutto mio.$B$BUltimamente ho letto di Un'Goro Crater, e della strana attività vulcanica in corso al centro del cratere. Penso che si potrebbe imparare molto, se solo riuscissi ad avere un po' della cenere degli elementali di là.$B$BTi dispiacerebbe raccoglierne un po' per me, se vai da quelle parti?",
  obj = "Raccogli 9 campioni di Un'Goro Ash dagli elementali del fuoco intorno al vulcano di Un'Goro Crater e portali a Liv Rizzlefix a Ratchet.",
  progress = "È vero che il vulcano di Un'Goro è attivo? Sono sicura che con un po' di cenere del vulcano potrei imparare molto, $N.",
  reward = "Questi campioni saranno perfetti per i miei studi! Grazie, $N! Te lo prometto, sarai $Gil primo:la prima; a cui racconterò le mie scoperte.",
}
T[4503] = {
  title = "Il Velivolo di Shizzle",
  desc = "Sto costruendo una macchina volante!$B$BSono rimasto bloccato qui, e a orientarmi sono un vero disastro. Tornerei a Gadgetzan con un grifone o un wind rider, ma quelle bestie mi fanno una paura da morire.$B$BAllora, mi aiuti? Mi restano da costruire solo le ali, e pensavo che le scaglie palmate dello pterrordax e del diemetradon sarebbero perfette. Io contro uno di quelli non mi ci metto proprio, ma tu mi sembri piuttosto $Gtosto:tosta;. Perché non ci provi tu?",
  obj = "Raccogli 8 Webbed Diemetradon Scales e 8 Webbed Pterrordax Scales per Shizzle, al Rifugio dei Marshal.",
  progress = "Ogni grande veicolo ha bisogno di un nome... Pensavo di chiamarlo... Pwned!",
  reward = "Sì, queste scaglie sono perfette. Con queste scaglie dovrei proprio riuscire a far decollare il velivolo!$B$BGrazie!",
}
T[4504] = {
  title = "Appiccicosissima",
  desc = "Sono sempre in cerca di un modo rapido per guadagnarmi una moneta d'oro, $N. Se mi aiuti con la mia ultima idea, ti farò avere una piccola parte del guadagno. Che te ne pare?$B$BLo immaginavo!$B$BVai alle pozze di pece nella parte nord dell'Un'Goro Crater e raccoglimi un po' di pece. Non una pece qualunque, bada, dovrai prenderla dalle bestie che vivono intorno alle pozze. La pece normale semplicemente non è abbastanza appiccicosa.$B$BQuelle creature simili a piante hanno la clorofilla nella pelle e, mescolata alla pece, la rende appiccicosissima!",
  obj = "Raccogli 12 campioni di Super Sticky Tar per Tran'rek, a Gadgetzan.",
  progress = "Tran'rek ha colpito ancora — questa colla appiccicosissima farà furore!",
  reward = "Sì, questa pece è proprio quello che ci vuole...$B$BEhi, aspetta un attimo, le mie mani... Non riesco più a staccarle...$B$BForse non è stata poi una grande idea. Oh, ma aspetta! Solvente per pece appiccicosissima! È lì che stanno i soldi veri!",
}
T[4505] = {
  title = "Pozzo della Corruzione",
  desc = "Qualcuno dirà che sono di una crudeltà eccezionale... Ma in realtà è solo un forte desiderio di vedere l'Orda avvantaggiarsi sull'Alleanza, in qualunque modo.$B$BIl mio ultimo interesse è un pozzo lunare alle Rovine di Constellas, a sud di qui, di cui si occupano i satiri Jadefire. Il pozzo lunare, un tempo simbolo di rinnovamento per quegli insopportabili elfi della notte, ora è corrotto e serve a far nascere altri satiri.$B$BHo un'idea, $N, e vorrei un campione di quell'acqua... per questa mia piccola amica felina.",
  obj = "Raccogli un campione d'acqua corrotta dal pozzo lunare dei Jadefire Satyrs e portalo a Winna Hazzard a Bloodvenom Post.",
  progress = "È della massima importanza. Su, mettiti in cammino.",
  reward = "Molto bene. Dobbiamo trovare il modo di usare questa corruzione contro i nostri nemici...",
}
T[4506] = {
  title = "Fiere Corrotte",
  desc = "Quest'acqua corrotta può tornare a nostro vantaggio, $N. Ne è bastata poca perché la mia gattina raddoppiasse di taglia, e sembra più forte... in qualche modo. Questi gatti potrebbero rivelarsi utili...$B$BEcco, $N. Prendi questo trasportino e libera la gattina che c'è dentro accanto al pozzo lunare delle Rovine di Constellas. Eh, eh... Sono sicura che i risultati ti piaceranno!$B$BRiportami la gatta, e sono certa di poterti ripagare del tempo speso.",
  obj = "Porta Winna's Kitten al pozzo lunare corrotto, liberala e poi riportala a Winna Hazzard.$B$BQuando sei di nuovo da Winna Hazzard, clicca sulla gatta per restituirgliela.",
  progress = "Non venirmi a dire che non puoi tornare laggiù! Muoviti!",
  reward = "Eccellente!$B$BI Reietti ricorreranno a qualsiasi mezzo pur di schiacciare l'Alleanza! Usare l'acqua corrotta si rivelerà di sicuro utile per le nostre prossime mosse...",
}
T[4507] = {
  title = "Il Pedone Cattura la Regina",
  desc = "Ecco l'esca. Dentro la rete dell'alveare dovrebbe esserci un cristallo di qualche tipo. Pensiamo che i silithid lo usino come una sorta di dispositivo di sintonizzazione per tutto l'alveare. Quanto a dove possa trovarsi questo cristallo, direi di provare negli incubatoi all'interno dell'alveare.$B$BUsare l'esca sul cristallo dovrebbe stanare la regina, ma ti avverto — probabilmente sarà protetta da diverse guardie. Elimina la regina e asportale il cervello. Per quanto possa sembrare schifoso, abbiamo un disperato bisogno di studiarlo. Buona fortuna, $N!",
  obj = "Sconfiggi la Gorishi Hive Queen una volta evocata.$B$BPorta il Gorishi Queen Brain ad Alchemist Pestlezugg, a Gadgetzan.",
  progress = "Procurarci il cervello della regina per le nostre ricerche è assolutamente indispensabile. Da quello che abbiamo scoperto, crediamo che questi silithid siano molto probabilmente controllati da un'intelligenza maligna. Rabbrividisco al pensiero di cosa possa controllare qualcosa di insidioso come i silithid, $N.",
  reward = "Fantastico, $N! Oggi abbiamo ottenuto una gran bella vittoria. Ci vorrà un po' di tempo per capire fino in fondo cosa abbiamo tra le mani; ne faremo buon uso però, su questo non preoccuparti.$B$BQuanto ai silithid, dubito sinceramente che la loro presenza si limitasse a questo. È una conclusione fin troppo pulita, mi dispiace dirlo.",
}
T[4508] = {
  title = "La Quiete Prima della Tempesta",
  desc = "Le mie ultime scoperte e quello che abbiamo appreso qui oggi devono arrivare nelle mani di qualcuno che forse può davvero farci qualcosa. Per quanto qui a Gadgetzan siamo pieni di risorse, da soli non possiamo farcela.$B$BTorna da Gracina Spiritmight, a Darnassus, con il mio ultimo rapporto; è ancora al Tempio della Luna, non è vero? Ha amici che sono pezzi grossi dell'Alleanza; se riusciamo a coinvolgerli in questa faccenda, $N, forse ne usciremo vivi.",
  obj = "Porta Pestlezugg's Un'Goro Report a Gracina Spiritmight, a Darnassus.",
  progress = "Sono degli stolti, $N! Non pensano nemmeno a guardarsi intorno in cerca di una minaccia più grande; il loro odio irrazionale per l'Orda sarà la fine di tutti noi. Non so quante altre prove potrei dare loro della minaccia dei silithid, a meno di calarli in uno degli alveari perché vedano con i propri occhi!$B$BPerdonami, porti notizie che richiedono la mia attenzione?",
  reward = "Lo apprezzo sinceramente, ma non so quanto potrà servirci. L'Alleanza ignora ogni minaccia che non venga dall'Orda, e perfino i nostri capi qui a Darnassus non riescono a mettersi d'accordo su cosa sia esattamente questa minaccia. Stolti come Fandral Staghelm teorizzano che i silithid non abbiano nulla a che vedere con la minaccia venuta dall'antico passato di cui parlo io. La sua ignoranza è superata soltanto dalla sua arroganza.$B$BTu la minaccia l'hai vista con i tuoi occhi, $N. Dobbiamo continuare a impegnarci per sconfiggere i silithid!",
}
T[4509] = {
  title = "La Quiete Prima della Tempesta",
  desc = "Le mie ultime scoperte e quello che abbiamo appreso qui oggi devono arrivare nelle mani di qualcuno che forse può davvero farci qualcosa. Per quanto qui a Gadgetzan siamo pieni di risorse, da soli non possiamo farcela.$B$BTorna da Zilzibin Drumlore, a Orgrimmar, con il mio ultimo rapporto; è ancora al suo posto nella parte alta del Corso, non è vero? Ha amici molto in alto nell'Orda; se riusciamo a coinvolgerli in questa faccenda, $N, forse ne usciremo vivi.",
  obj = "Porta Pestlezugg's Un'Goro Report a Zilzibin Drumlore, a Orgrimmar.",
  progress = "Sono degli stolti, $N! Non pensano nemmeno a guardarsi intorno in cerca di una minaccia più grande; il loro odio irrazionale per l'Alleanza sarà la nostra rovina. Non so quante altre prove potrei dare loro della minaccia dei silithid, a meno di calarli in uno degli alveari perché vedano con i propri occhi!$B$BPerdonami, porti notizie che richiedono la mia attenzione?",
  reward = "Lo apprezzo sinceramente, ma non so quanto potrà servirci. L'Orda ignora ogni minaccia che non venga dall'Alleanza. Thrall in persona forse agirebbe, se gli venissero presentati i fatti, ma è assediato da ogni parte da consigli contrastanti. Questi stolti ci farebbero rincorrere la nostra coda immaginaria, se pensassero che così si possa cogliere l'Alleanza alla sprovvista!$B$BTu la minaccia l'hai vista con i tuoi occhi, $N. Dobbiamo continuare a impegnarci per sconfiggere i silithid!",
}
T[4510] = {
  title = "La Quiete Prima della Tempesta",
  desc = "$N, il tuo aiuto è stato inestimabile. Verrà di sicuro il momento in cui ti chiederò ancora una mano contro i silithid. Dobbiamo assimilare quello che abbiamo imparato a Un'Goro; temo che ormai le mie supposizioni sull'origine dei silithid a Un'Goro siano sbagliate... che in realtà da qualche parte ci sia una presenza ben più forte.$B$BPorta questo biglietto a Idriana, alla banca. Ti darà qualcosa dal mio deposito, da considerare un segno della mia gratitudine. Grazie per il tuo aiuto, $Gcoraggioso:coraggiosa; $C.",
  obj = "Porta il Bank Voucher a Idriana, nella banca di Darnassus.",
  progress = "Elune'adore, $C. Cosa posso fare per te oggi?",
  reward = "Questo buono della banca mi autorizza a prelevare un oggetto dal conto che Gracina Spiritmight ha presso di noi e a consegnartelo. Direi che le congratulazioni sono d'obbligo!",
}
T[4511] = {
  title = "La Quiete Prima della Tempesta",
  desc = "$N, non saremmo mai arrivati fin qui senza di te. Verrà presto il momento, non c'è dubbio, in cui ti chiederò ancora aiuto contro i silithid. Dobbiamo assimilare quello che abbiamo imparato a Un'Goro; temo che la mia ipotesi, che i silithid venissero da Un'Goro, ora sia sbagliata... che in realtà ci sia da qualche parte una presenza ben più forte.$B$BPorta questo biglietto a Karus, alla banca. Ti darà una cosa presa dal mio deposito, da considerare un segno della mia gratitudine. Grazie per il tuo aiuto, possente $C.",
  obj = "Porta il Bank Voucher a Karus, nella banca di Orgrimmar.",
  progress = "Zug zug! In cosa posso aiutarti oggi, $C?",
  reward = "Questo buono della banca mi autorizza a ritirare un oggetto dal conto che Zilzibin Drumlore ha presso di noi e a consegnartelo. Direi che le congratulazioni sono d'obbligo!",
}
T[4512] = {
  title = "Con un Po' di Poltiglia si Va Lontano",
  desc = "Ma la cosa che ho studiato di più è la melma. Lo so che sembra strano, ma le melme sono dappertutto!$B$BA Menethil, non molto tempo fa, ho aiutato una signora a ritrovare la borsa — se l'erano mangiata le melme. Ho visto membri della Royal Apothecary Society di Undercity raccogliere campioni di quella roba. Voglio sapere perché! Da dove viene?$B$BHo sentito che ce ne sono altre a Felwood. Mi servono campioni delle melme di lì, per portare avanti la mia ricerca. Io ti do i contenitori, tu li usi per raccogliere un campione dalle creature morte.",
  obj = "Porta 6 Filled Cursed Ooze Jars e 6 Filled Tainted Ooze Jars a Laris Geardawdle, a Ironforge.",
  progress = "Alcuni degli esperimenti che ho fatto sono affascinanti. Credo che con ancora un po' di lavoro riuscirò a capire la natura di queste creature e che parte hanno avuto nello sviluppo della vita su Azeroth... sempre che c'entrino davvero qualcosa.$B$BUna delle mie teorie più importanti, e che non piace molto, è l'idea che melme e poltiglie siano legate alla creazione di questo pianeta... quasi come se ne fossero una secrezione.$B$BMa non posso né dimostrarla né smentirla finché non avrò altri campioni.",
  reward = "Risultati strepitosi, $N! Ti sei $Gavvicinato:avvicinata; abbastanza da prendere un campione di quelle cose corrotte, e a vederti non sembri nemmeno $Gprovato:provata;! Grazie. Oh, questi campioni saranno perfetti. Non vedo l'ora di cominciare a farci gli esperimenti.$B$BSe ho ragione, potrei essere uno dei più grandi scienziati della Lega degli Esploratori!$B$BQuesto dimostrerà a tutti i nani che non è stato un errore far entrare noi gnomi a Ironforge dopo l'incidente di Gnomeregan.",
}
T[4513] = {
  title = "Con un Po' di Poltiglia si Va Lontano",
  desc = "Mi serviranno altri campioni, $N. Ma — e non so come dirlo — devono essere campioni puri. Lo so, lo so. \"Che vuol dire 'puri', Laris?\" Non ne sono sicuro. So però che questi sono corrotti... proprio come Felwood. Ed è questo a rendere così importante ciò che ho capito. Le melme sembrano adattarsi... assumere le caratteristiche della zona in cui si trovano. Dovrò trovare campioni che non siano stati contaminati. Ma dove? Dove?!$B$BBah! $N, prendi questi contenitori, nel caso ne trovassi qualcuno per conto tuo.",
  obj = "Porta 10 Filled Pure Sample Jars a Laris Geardawdle, a Ironforge.$B$BSe fai fatica a trovarli, prova magari a farti dare altri indizi da Laris.",
  progress = "Quante cose da considerare. Ma cosa significa? E come influisce sulla vita degli abitanti di Azeroth?",
  reward = "L'hai trovato? $N, sei un vero tesoro. La tua dedizione e il tuo aiuto sono stati magnifici, e non potrò mai ringraziarti abbastanza.$B$BTi prego, prendi questo per il disturbo. Ho del lavoro da fare, ma sono sicuro che, se tornerai più avanti, avrò ancora bisogno dei tuoi servigi.$B$BGrazie. Grazie di cuore.",
}
T[4521] = {
  title = "Guardiani Selvaggi",
  desc = "Winterspring è appena oltre Timbermaw, a nord-est di Felwood. Ci sei mai $Gstato:stata;?$B$BHo sentito dire che la zona pullula di creature chiamate wildkin. Si sa che queste bestie custodiscono segreti; segreti degli Elfi della notte.$B$BDobbiamo scoprire cosa potrebbe nascondersi a Winterspring.$B$BHo sentito dire che gli owlbeast malconci si trovano subito a sud della strada, e che ce ne sono altri, chiamati owlbeast furenti, al centro di Winterspring. Spazzali via e guadagnati l'accesso a quella terra.",
  obj = "Trull Failbane, a Felwood, vuole che tu uccida 15 Raging Owlbeasts e 15 Ragged Owlbeasts.",
  progress = "Torna a fare rapporto quando avrai portato a termine il compito che ti ho dato.",
  reward = "Ottime notizie, $N. Tolte di mezzo queste bestie, possiamo cominciare a spingerci più all'interno di Winterspring. Sei $Gpronto:pronta; ad andare avanti?",
}
T[4542] = {
  title = "Messaggio per il Presidio di Freewind",
  desc = "$GCoraggioso viaggiatore:Coraggiosa viaggiatrice;, i centauri hanno intensificato gli attacchi in questa zona. Il Presidio di Freewind deve sapere subito che le scorrerie sono ricominciate! Cerca Cliffwatcher Longhorn al Presidio di Freewind, a sud-est, e consegnagli questo messaggio urgente.$B$BSta' in guardia, evita il Grimtotem Clan qui vicino... ultimamente si comportano in modo strano con noi.",
  obj = "Porta l'Urgent Message a Cliffwatcher Longhorn, al Presidio di Freewind.",
  progress = "Cosa vuoi, $C? Un messaggio urgente — per me?",
  reward = "Altre cattive notizie! Questi centauri sono andati troppo oltre! Hanno assalito una delle mie carovane di rifornimenti e massacrato l'intero gruppo. È un oltraggio, e non resterà impunito!",
  en_title = "Message to Freewind Post",
  en_obj = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
}
T[4561] = {
  title = "Analisi delle Impurità — Un'Goro Crater",
  progress = "Prendi un campione di melma dell'Un'Goro Crater e ne versi un po' nelle varie provette e nei becher sul tavolo. Mentre tutto comincia a bollire e a schizzare, la melma cambia colore. Quando il processo rallenta e i liquidi si calmano, vedi una piccola capsula di petri con dentro i tuoi campioni purificati di melma di Un'Goro, insieme a qualche altro residuo.",
  reward = "Prendi la capsula di petri con dentro il campione di melma. L'unico modo per capire se il campione è abbastanza puro è aprirla ed esaminare tu $Gstesso:stessa; il contenuto. Con un po' di fortuna troverai un campione che risponde ai criteri del Chimico Fuely.",
}
T[4581] = {
  title = "Kayneth Stillwind",
  desc = "Il druido Kayneth Stillwind mi ha mandato un messaggio. Vorrebbe un rapporto su quel che accade lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia diffondendo in Ashenvale... e potrebbe avere ragione.$B$BEcco, portagli il mio rapporto. Lo troverai nel santuario di Forest Song, nei Boschi di Nightsong, a est.",
  obj = "Porta Shindrell's Note a Kayneth Stillwind, a Forest Song.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, il rapporto di Shindrell! Molte grazie, $N. Shindrell è un'ottima sentinella, coraggiosa e vigile. Devo leggerlo per cercarvi indizi di una malvagità che temo si stia diffondendo in Ashenvale.",
  en_title = "Kayneth Stillwind",
  en_obj = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.",
}
T[4601] = {
  title = "Lo Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"Lo Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Object nello Sparklematic 5200 e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno servano una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina pulsano forti e violenti rumori di rimescolamento. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4602] = {
  title = "Lo Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"Lo Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Object nello Sparklematic 5200 e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno servano una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina pulsano forti e violenti rumori di rimescolamento. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4603] = {
  title = "Ancora un Giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Lo scomparto della macchina si apre a spirale e rivela una scatola incartata con cura.",
  en_title = "More Sparklematic Action",
}
T[4604] = {
  title = "Ancora un Giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Lo scomparto della macchina si apre a spirale e rivela una scatola incartata con cura.",
  en_title = "More Sparklematic Action",
}
T[4605] = {
  title = "Lo Sparklematic 5200!",
  reward = "Rapido com'era partito, lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta chiusa da un fiocchetto. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è solo un modo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[4606] = {
  title = "Lo Sparklematic 5200!",
  reward = "Rapido com'era partito, lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta chiusa da un fiocchetto. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è solo un modo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[4621] = {
  title = "Alt Là, Ammiraglio!",
  desc = "Ascolta bene, lupo di mare... è il potere di Booty Bay che non ci lascia a noi Bloodsail navigare dove ci pare e prenderci quello che ci va per diritto di saccheggio. Se pianti un coltello nel Comandante della Flotta Seahorn, con le navi di Booty Bay non ci avremo mai più guai. Se pianti un coltello nel Barone Revilgaz, non dovremo mai più fare i conti con la loro legge.$B$BSe vuoi diventare $Gammiraglio onorario:ammiraglia onoraria; tra noi — sì, $GAMMIRAGLIO:AMMIRAGLIA;, pianterai un coltello in tutti e due, come t'ho detto. Ora va', $Gragazzo:ragazza;, e torna da me quando avrai fatto il lavoro.",
  obj = "Uccidi Fleet Master Seahorn e Baron Revilgaz di Booty Bay, poi torna da Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.",
  progress = "Sei già di ritorno, maledetto marinaio! Hai fatto quello che t'ho ordinato? Deludici e camminerai sull'asse.$B$BArrrrr...",
  reward = "Alt là... $GAmmiraglio:Ammiraglia; $N! Sei il pirata dei pirati, $Gragazzo:ragazza;!$B$BMi scalda il cuore darti questo cappello. Non ne troverai mai un altro così da nessuna parte, e chiunque ti guarda vedrà che sei $Gun Ammiraglio:un'Ammiraglia; della Bloodsail Navy!",
  en_title = "Avast Ye, Admiral!",
  en_obj = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.",
}
T[4642] = {
  title = "Fusione di Influenze",
  desc = "Ecco della poltiglia chiusa in un contenitore, creata dai campioni di Felwood che hai recuperato. Porta il contenitore nell'Un'Goro Crater e trova una poltiglia pura... la varietà primordiale andrà benissimo. Quando sarai abbastanza $Gvicino:vicina;, libera la poltiglia che c'è nel contenitore, e vediamo cosa pensano l'una dell'altra.$B$BFinito l'esperimento, portami un campione di quello che resta. Ti aspetterò qui nell'Apothecarium.",
  obj = "Porta un Merged Ooze Sample a Chemist Fuely a Undercity.",
  progress = "Come procede l'esperimento, $N? Io continuerò a studiare i campioni che hai recuperato per me — comincio a capire perché Lady Sylvanas si interessa tanto a queste creature. Se fanno davvero parte degli Dei Antichi, chissà come potremo sfruttare la cosa a nostro vantaggio.",
  reward = "Oh, eccellente, $N. È davvero eccellente.$B$BChe storia. Chi avrebbe mai detto che le due avrebbero interagito tra loro in questo modo... Dovrò dedicare più tempo a studiare i fattori ambientali che provocano cambiamenti in queste creature.$B$BPer ora continuerò le mie ricerche. Forse ci riparleremo presto. Fino ad allora, ti auguro ogni bene.",
}
T[4661] = {
  title = "Analisi della Corruzione — Felwood",
  progress = "Prendi un campione di melma di Felwood e ne versi un po' nelle varie provette e nei becher sul tavolo. Mentre tutto comincia a bollire e a schizzare, la melma cambia colore. Quando il processo rallenta e i liquidi si calmano, vedi una piccola capsula di petri con dentro i tuoi campioni alterati di melma di Felwood, insieme a qualche altro residuo.",
  reward = "Prendi la capsula di petri con dentro il campione di melma. L'unico modo per capire se il campione è abbastanza puro è aprirla ed esaminare tu $Gstesso:stessa; il contenuto. Con un po' di fortuna troverai un campione che risponde ai criteri del Chimico Fuely.",
}
T[4701] = {
  title = "Abbattila",
  desc = "Avrai senz'altro visto i worg agli ordini degli orchi Blackrock.$B$BÈ curioso — per quanti ne distruggiamo, il loro numero non cala mai. I miei esploratori hanno riferito che i worg vengono allevati, addestrati e infine esportati da Blackrock Spire: la capitale degli orchi Blackrock. Devi andare a Blackrock Spire e scoprire l'origine di questa minaccia. Scoprirla... e distruggerla.$B$BBuona fortuna, $N. Che Cenarius ti protegga...",
  obj = "Vai a Blackrock Spire e distruggi l'origine della minaccia dei worg. Mentre ti allontanavi da Helendis, lui ha gridato un nome: Halycon. È il nome che fanno gli orchi quando parlano dei worg.",
  progress = "Hai scoperto l'origine della minaccia dei worg e te ne sei $Goccupato:occupata;?",
  reward = "Non restare a pensare alla sua sofferenza, $N. La bestia era corrotta — un prodotto della magia oscura. Hai reso un grande servizio all'Alleanza e sarai $Gricompensato:ricompensata;.",
}
T[4721] = {
  title = "Guardiani Selvaggi",
  desc = "Delle staffette sono tornate da Winterspring e riferiscono che nella zona meridionale c'è una serie di piccole grotte. Pare che nella zona intorno a queste grotte ci siano dei wildkin. Se c'è qualcosa di prezioso che custodiscono, credo che sia quello il posto dove lo troveremo.$B$BVedrai che questi sono più impegnativi di quelli di prima, $N. Sembra che le creature siano impazzite a forza di stare esposte proprio alla cosa che si sforzano di proteggere.",
  obj = "Trull Failbane, a Felwood, vuole che tu dia la caccia a 10 Berserk Owlbeasts a Winterspring.",
  progress = "I tuoi ordini li conosci, $N.",
  reward = "Il duro lavoro è una cosa che rispetto molto, $N. Ora possiamo andare avanti con i nostri piani per Winterspring.",
}
T[4724] = {
  title = "La Signora del Branco",
  desc = "C'è chi dice che i worg controllati dagli orchi Blackrock siano la creazione di una forza soprannaturale. Altri dicono che non sono veri worg, ma una razza di cani demoniaci, concessa agli orchi da un signore delle fosse caduto.$B$BLa verità è molto meno contorta, ma fa altrettanta paura. I worg di Blackrock vengono da Halycon e dal suo compagno. Halycon è la gigantesca matriarca della tana dei worg. Il suo compagno? Nessuno è mai sopravvissuto per raccontare di lui.$B$BColpisci i worg al cuore. Distruggi Halycon... e $N, guardati le spalle.",
  obj = "Uccidi Halycon, signora del branco dei Bloodaxe worg.",
  progress = "Uccisa la signora del branco, possiamo cominciare a sfoltire i worg di sentinella alla Spire e, col tempo, farci strada nella città.",
  reward = "Cuccioli rabbiosi? Gizrul il Capobranco? E sei ancora $Gvivo:viva; per raccontarlo?! Incredibile! Un tributo ben meritato!",
}
T[4726] = {
  title = "Essenza della Progenie",
  desc = "Studio da settimane i dragonkin delle Burning Steppes, e credo di aver finalmente fatto un passo avanti decisivo! Ho creato un congegno — lo chiamo Draco Incarcinatrix 900. Può catturare l'essenza dei cuccioli di drago della progenie!$B$BO almeno, credo che possa.$B$BEcco, prendi il congegno e dai una scarica a un cucciolo della progenie nelle Burning Steppes. Sconfiggi il cucciolo mentre è sotto l'effetto del congegno, e la sua essenza dovrebbe liberarsi.$B$BSe succede, splendido! Portami dei campioni, così li posso studiare!",
  obj = "Porta 8 Broodling Essence e il Draco-Incarcinatrix 900 a Tinkee Steamboil, a Flame Crest, nelle Burning Steppes.",
  progress = "Hai l'essenza della progenie, $N? Non vedo l'ora di studiarla.$B$BE poi... il mio finanziatore non è il tipo di persona che conviene deludere.",
  reward = "Ha funzionato! Hai preso l'essenza! $GBravo:Brava;, $N! $GBravo:Brava;!$B$BQuest'essenza sarà preziosissima per le mie ricerche. Spero di imparare un giorno a catturare i cuccioli di drago vivi, o magari le loro uova. Se trovassi il modo di farlo, farei invidia agli studiosi di draghi di tutto il mondo!$B$BSarebbe contento anche il mio datore di lavoro e, come ho detto, è uno che conviene tenere contento...",
}
T[4729] = {
  title = "Gli Animali Esotici di Kibler",
  desc = "Ti starai chiedendo cosa ci faccio qua fuori. Guarda le gabbie! Non si vede?$B$BIo sono prima di tutto uno che ama gli animali, ma di mestiere faccio il venditore. Scovo animali esotici per i ricchi e famosi e addomestico le bestie perché si comportino da veri animali da compagnia.$B$BAdesso ti starai chiedendo: \"Cosa posso fare per te, Kibler.\" La risposta è semplice: prendi 'sta gabbia per bestie e trovami dei cuccioli di worg. In cambio, ti addomestico un worg!",
  obj = "Vai a Blackrock Spire e trova dei Bloodaxe Worg Pups. Usa la gabbia per trasportare quelle bestiole feroci. Riporta un Caged Worg Pup a Kibler.",
  progress = "<Kibler è impegnato a discutere con Opus.>",
  reward = "Li hai presi al momento giusto, $N. Un po' più tardi e non si potevano più addestrare! Dammi un minuto e ti preparo il piccoletto, così te lo porti a casa.",
}
T[4734] = {
  title = "Congelamento delle Uova",
  desc = "$N, ho lavorato sodo a un nuovo congegno, l'uovometro! È progettato per sparare una scarica di energia fredda sull'uovo di un drago nero... e congelarlo del tutto! Puoi provarlo per me?$B$BHo sentito che in alto, a Blackrock Spire, i draghi hanno un nido dove fanno schiudere le uova. È lì che dovrai andare a provare l'uovometro, e poi fammi sapere come ha funzionato!$B$BE non preoccuparti. Le uova di drago congelate dovrebbero essere innocue. È di quelle non congelate che ti devi preoccupare!",
  obj = "Usa l'Eggscilloscope Prototype su un uovo nella Rookery.",
  progress = "$N, hai provato l'uovometro?",
  reward = "Ha funzionato? Splendido! Lo sapevo!$B$BMentre eri via ho lavorato a una nuova versione dell'uovometro. Questa ha una portata molto maggiore.$B$BTieni, prendine uno, nel caso tornassi a Blackrock Spire.",
}
T[4735] = {
  title = "Raccolta delle Uova",
  desc = "$N, sono finalmente pronta per dei veri campioni di uova di drago! Tieni, prendi questo modulo collettronico. È progettato per estrarre un uovo di drago e prepararlo per il trasporto. Torna al Nido e usa il modulo per raccogliere le uova.$B$BE non dimenticarti di congelarle prima, o potrebbero schiudersi prima che tu riesca a raccoglierle!$B$BQuando avrai abbastanza uova, portamele!",
  obj = "Porta 8 Collected Dragon Eggs e il Collectronic Module a Tinkee Steamboil a Flame Crest, nelle Burning Steppes.",
  progress = "Hai le uova, $N? Il mio committente ha saputo che le stavi raccogliendo per me, e non vede l'ora di metterci le mani sopra!",
  reward = "Wow, le hai prese! Il modulo collettronico ha funzionato! Sono un genio!$B$BGrazie, $N. Il mio committente sarà molto contento di avere queste uova...",
}
T[4736] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Ah, ciao, $N. Stai facendo progressi nell'addestramento. Tanto che, secondo me, meriti una ricompensa per il tuo impegno — e per non esserti ancora $Glasciato:lasciata; corrompere dall'arcano.$B$BSe ti interessa, cerca Menara Voidrender a Ratchet. Al momento sta nella torre di Strahad Farsan, che domina la città.$B$BNon è molto cordiale, $N, quindi non aspettarti elogi. Ma se ti impegni, farà in modo che non ti manchi niente.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, ti manda Briarthorn. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Ne sono lieta.$B$BÈ tipico di quelli come noi, $N, fare fronte comune, senza badare alla razza. È importante soprattutto perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.$B$BSento che hai imparato moltissime cose e, se lo vuoi, ti aiuterei a creare strumenti che completino le tue capacità.",
}
T[4737] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Hmph, cerchi ancora di diventare più potente. Io dico che è solo questione di tempo prima che la corruzione e la dipendenza si impadroniscano di te e tu diventi $Gschiavo:schiava; di ciò che cerchi di dominare.$B$BPfah! $GUno sciocco:Una sciocca;, ecco cosa sei! Il tempo mi darà ragione — nient'altro... solo il tempo.$B$BMa a quanto pare non tutti sono d'accordo con Zevrost. Pare che Menara voglia crearti degli strumenti per diventare più potente e imbrigliare la tua forza. Se ti interessa, va' a Ratchet, nelle Barrens. La trovi lì, affacciata sulla città.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, ti manda Zevrost. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Ne sono lieta.$B$BÈ tipico di quelli come noi, $N, fare fronte comune, senza badare alla razza. È importante soprattutto perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.$B$BSento che hai imparato moltissime cose e, se lo vuoi, ti aiuterei a creare strumenti che completino le tue capacità.",
}
T[4738] = {
  title = "In Cerca di Menara Voidrender",
  desc = "Mettiamo in chiaro una cosa, $N: secondo me non sei $Gpronto:pronta; per responsabilità del genere. Non credo che chi è alle prime armi dovrebbe mai partecipare alla creazione di un oggetto di potere; tanto meno se ha dato così poca prova di sé.$B$BMa non sta a me decidere. A deciderlo è chi comanda, o almeno chi di loro vuole davvero concederti simili doni.$B$BSe ti interessa saperne di più, ti consiglio di cercare Menara Voidrender a Ratchet. Di solito sta nella torre sopra la città portuale.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, ti manda Demisette. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Ne sono lieta.$B$BÈ tipico di quelli come noi, $N, fare fronte comune, senza badare alla razza. È importante soprattutto perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.$B$BSento che hai imparato moltissime cose e, se lo vuoi, ti aiuterei a creare strumenti che completino le tue capacità.",
}
T[4739] = {
  title = "In Cerca di Menara Voidrender",
  desc = "$C! Sì, dico a te!$B$BNon hai tutto l'armamentario, ma si vede bene che sei $Gpronto:pronta; — l'aria intorno a te trasuda più sicurezza. Sì, ora lo vedo.$B$BMenara Voidrender ti insegnerebbe un paio di cose, se ti senti $Gpronto:pronta;. Passa il tempo a istruire nell'arcano gli allievi più giovani. Fa perfino dei doni a chi supera le sue prove.$B$BSe ti interessa, va' a Ratchet, nelle Barrens. Lei è sopra la città, nella torre di Strahad.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, ti manda Kaal. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Ne sono lieta.$B$BÈ tipico di quelli come noi, $N, fare fronte comune, senza badare alla razza. È importante soprattutto perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.$B$BSento che hai imparato moltissime cose e, se lo vuoi, ti aiuterei a creare strumenti che completino le tue capacità.",
}
T[4741] = {
  title = "Guardiani Selvaggi",
  desc = "Nelle zone settentrionali di Winterspring i Wildkin si fanno ancora più feroci. Dobbiamo continuare a prendere provvedimenti anche lì.$B$BDai la caccia agli owlbeast toccati dalla luna a Winterspring, ed esplora la zona in cui vivono.$B$BÈ un territorio pericoloso, ma so che saprai essere all'altezza. Torna da me quando avrai ucciso 13 di quei wildkin.",
  obj = "Trull Failbane, a Felwood, vuole che tu dia la caccia a 13 Moontouched Owlbeasts.",
  progress = "Non dirmi che hai troppa paura! Muoviti!",
  reward = "Sento che questo lavoro ti piace. E credo che qui siamo sulla pista di qualcosa.",
}
T[4742] = {
  title = "Sigillo dell'Ascesa",
  desc = "Come vedi, il sigillo disadorno ha tre incavi vuoti. Ognuno di quegli incavi va riempito con una gemma che rappresenta il comando dei capi. Infine il Supremo Wyrmthalak, padrone della cittadella inferiore, deve forgiare il sigillo nelle fiamme del Black Dragonflight.$B$BSappi questo, mortale: è raro che uno dei tre generali della cittadella inferiore porti con sé una gemma in un dato momento. Devi essere vigile nella tua ricerca. Resta $Gdeterminato:determinata;!",
  obj = "Trova le tre gemme del comando: la Gemstone of Smolderthorn, la Gemstone of Spirestone e la Gemstone of Bloodaxe. Riportale a Vaelan, insieme all'Unadorned Seal of Ascension.$B$BI Generali, come ti ha detto Vaelan, sono: War Master Voone degli Smolderthorn; Highlord Omokk degli Spirestone; e Overlord Wyrmthalak dei Bloodaxe.",
  progress = "Coraggio e pazienza prima di tutto, $N!",
  reward = "<L'immagine di Vaelan si offusca per un momento.>$B$B<I pezzi che avevi raccolto sono scomparsi.>$B$BIl Sigillo dell'Ascesa Non Forgiato ora è pronto. È il momento dell'ultimo passo.",
}
T[4743] = {
  title = "Sigillo dell'Ascesa",
  desc = "Pochi dei dragonkin neri, a parte quelli della cittadella superiore, sono capaci di forgiare il sigillo con il loro soffio di fuoco. Wyrmthalak è uno di questi, ma la sua volontà non si può spezzare.$B$BDevi andare al Wyrmbog, a Dustwallow Marsh. È lì che troverai un antico draco conosciuto come Emberstrife. Devi spezzare la sua volontà, $N. Spezzala e usa questo globo sul suo corpo indebolito. Avrai pochissimi secondi per controllare la sua mente e alimentare le fiamme che forgeranno il sigillo.",
  obj = "Vai al Wyrmbog, a Dustwallow Marsh. Trova l'antico draco, Emberstrife, e colpiscilo senza pietà finché la sua volontà non sarà spezzata.$B$BÈ in quel momento che devi posare l'Unforged Seal of Ascension davanti alla grande bestia. Poi devi essere $Grapido:rapida; a usare l'Orb of Draconic Energy sul suo corpo indebolito e prendere il dominio delle sue facoltà mentali. Controlla la bestia e scaglia le Fiamme del Black Dragonflight sull'Unforged Seal of Ascension!",
  progress = "Non perdere tempo, $N. Nefarian lavora febbrilmente per scatenare il suo male sul nostro mondo.",
  reward = "Resta $Gfermo:ferma; mentre lancio l'ultima invocazione di protezione.$B$B<Gli occhi di Vaelan diventano due globi di fiamma.>$B$BIl Sigillo dell'Ascesa è completo...$B$BSappi questo, ho infuso nell'artefatto delle potenti protezioni. Nella tua ora più buia, quando tutto sembrerà perduto, la potenza dello stormo rosso sarà a tua disposizione.",
}
T[4764] = {
  title = "Fibbia di Doomrigger",
  desc = "C'è una sala, in alto a Blackrock Spire, che un tempo era chiamata Sala della Fortuna. Era lì che i nani Dark Iron custodivano le loro reliquie, i trofei e gli oggetti d'arte.$B$BÈ passato molto tempo. Si dice che la sala sia crollata e che ora venga usata per... faccende meno raccomandabili. Ma credo che lì si possano ancora trovare delle antiche reliquie naniche.$B$BUna di queste è la fibbia di Doomrigger, con una superficie così incrostata di gemme rare che, si diceva, faceva piangere ogni nano che vi posasse lo sguardo.$B$BQuella fibbia, $N, è il tuo obiettivo.",
  obj = "Porta Doomrigger's Clasp a Mayara Brightwing nelle Burning Steppes.",
  progress = "Hai la fibbia, $N? Il mio committente la pagherà davvero profumatamente.",
  reward = "L'hai trovata! Allora le voci erano vere!$B$BGrazie, $N. Il mio committente, il Conte Remington Ridgewell, sarà ben lieto di vedere questo nuovo pezzo aggiungersi alla collezione.",
}
T[4765] = {
  title = "Consegna per Ridgewell",
  desc = "Ho imballato la Fibbia di Doomrigger in una cassa, adatta alla spedizione a Stormwind. $N, mi sei $Gstato:stata; di enorme aiuto — posso chiederti un ultimo favore?$B$BConsegna la cassa al Conte Remington Ridgewell. Lo troverai nel Mastio di Stormwind. Sono sicura che sarà molto contento di vedere cos'hai per lui.",
  obj = "Porta Ridgewell's Crate a Count Remington Ridgewell a Stormwind.",
  progress = "Mi è stato detto che sarebbe venuto un messaggero. Uno con un dono da Blackrock Spire.$B$BSei tu $Gquello:quella;?",
  reward = "Ah, allora sei proprio $Gquello:quella;! Ti ringrazio, $N. E... nel caso non lo sapessi già... la gratitudine di un nobile della casata dei Ridgewell vale quasi il riscatto di un re.",
}
T[4766] = {
  title = "Mayara Brightwing",
  desc = "Una mia agente, Mayara Brightwing, è stata mandata nelle Burning Steppes a esplorare la città in rovina di Thaurissan. Quella città distrutta dei nani Dark Iron potrebbe nascondere oggetti di grande valore... oggetti che starebbero benissimo nel museo della nostra famiglia.$B$BMayara dice di aver trovato qualcosa e che le servirà aiuto per recuperarlo, ma non si trova a Thaurissan. Bisognerà invece fare un'incursione a Blackrock Spire.$B$BNon conosco i dettagli, ma se ti interessa parla con Mayara nelle Burning Steppes.",
  obj = "Parla con Mayara Brightwing nelle Burning Steppes.",
  reward = "Vieni da Stormwind? Magnifico — so di un oggetto d'arte che Remington farebbe carte false per avere nel suo museo, ma tirarlo fuori non sarà facile.$B$BEd è qui che entri in gioco tu.",
}
T[4767] = {
  title = "Wind Rider",
  desc = "Mi hanno incaricato di reclutare nuove wyverns per i maestri wind riders. Il loro numero cresce e anch'io spero di diventare un wind rider, un giorno. Però non riusciamo ad addestrare abbastanza wyverns per stare dietro alla richiesta. Forse puoi aiutarmi tu, $N.$B$BHo bisogno che tu vada a Highperch a raccogliere qualche uovo di wyvern. Da qui prosegui a nord-ovest lungo le pareti del canyon fino a una rampa che ti porterà a Highperch. Sta' $Gattento:attenta;: le wyverns sono molto protettive con le loro uova e non saranno gentili con gli intrusi.",
  obj = "Porta 10 Highperch Wyvern Egg a Elu, al Presidio di Freewind.",
  progress = "$N, hai recuperato le uova di wyvern che cerco? Non vedo l'ora di cominciare l'addestramento da wind rider!",
  reward = "Perfetto! Con queste uova spero di fare il prossimo passo per diventare un wind rider. Ecco un segno della mia riconoscenza; che la buona caccia ti sorrida sempre, $C.",
  en_title = "Wind Rider",
  en_obj = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
}
T[4768] = {
  title = "La Tavoletta di Darkstone",
  desc = "La Tavoletta di Darkstone contiene gli scritti del nano Urheld Darkstone, morto da molto tempo. Alchimista di grande talento, era ritenuto pazzo dai suoi contemporanei e, perciò, non condivise le sue ricerche.$B$BMa le incise su delle tavolette, e credo che una di queste si trovi a Blackrock Spire, in una sala un tempo chiamata Sala della Fortuna. Non so come si chiami ora, perché pochi entrano a Blackrock e ne tornano.$B$BMa se sei $Gdisposto:disposta; ad affrontarne i pericoli e a tornare da me con la tavoletta, la tua ricompensa sarà grande.",
  obj = "Porta la Darkstone Tablet a Shadowmage Vivian Lagrave a Kargath.",
  progress = "Hai trovato la Tavoletta, $N? Bramo di addentrarmi nei suoi segreti.",
  reward = "Eccellente. Le formule incise su questa tavoletta richiederanno giorni di ricerche, ma sono certa che queste ricerche daranno dolci frutti.$B$BGrazie, $N. Per noi sei $Gstato prezioso:stata preziosa;.",
}
T[4769] = {
  title = "Vivian Lagrave e la Tavoletta di Darkstone",
  desc = "Vivian Lagrave mi ha mandato notizie da Kargath, nelle Badlands. Grazie ai suoi studi, è convinta che dentro Blackrock Spire ci sia un testo antico che gioverebbe alle nostre ricerche. Per averne la conferma, le servirà qualcuno che porti il testo fuori dalla guglia. Compito non facile.$B$BSe ti interessa, parla con Vivian a Kargath.",
  obj = "Parla con Shadowmage Vivian Lagrave.",
  reward = "È vero. Credo che dentro Blackrock Spire sia custodita una tavoletta, una tavoletta che contiene antiche ricette alchemiche. Sono lieta che tu sia qui, perché mi serve aiuto per recuperarla.$B$BMettiti $Gcomodo:comoda;, e ti spiegherò meglio.",
}
T[4770] = {
  title = "Verso Casa",
  desc = "Aiutami, ti prego, $C! Sono nascosto qui a Highperch da un po' di tempo e sono giorni che non vedo una faccia amica. Sono venuto a studiare le wyverns e credo di essermi avvicinato un po' troppo. Dopo essere stato cacciato via da uno dei nidi mi sono perso.$B$BDevo tornare all'Accampamento di Whitereach! Motega non sa che sono sparito e andrà su tutte le furie quando saprà che mi sono avventurato a Highperch da solo.$B$BL'Accampamento di Whitereach è appena a est di qui... portamici, ti prego!",
  obj = "Scorta Pao'ka Swiftmountain fuori da Highperch, poi parla con Motega Firemane, all'Accampamento di Whitereach.",
  reward = "Cosa?! Se avessi saputo che Pao'ka Swiftmountain sarebbe andato a ficcare il naso a Highperch, l'avrei incatenato a un totem! Suo padre non era per niente convinto di lasciarlo venire con me a Thousand Needles. Siamo venuti qui a studiare le varie creature che abitano queste belle terre.$B$BTi ringrazio per l'aiuto che hai dato a Pao'ka. Spero che questo basti a ripagarti di qualunque guaio ti sia costata l'impresa.",
  en_title = "Homeward Bound",
  en_obj = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
}
T[4771] = {
  title = "Azzardo dell'Alba",
  desc = "Ho messo l'Azzardo dell'Alba nel contenitore che ci hai portato, quello in cui c'erano le uova di drago. Il tuo compito è portarlo nelle profondità della Scholomance.$B$BIl mago non morto Vectus guida una squadra di studiosi del flagello... metti l'Azzardo dell'Alba nella loro sala, chiamata \"sala d'osservazione\". Reagirà con i non morti che si trovano lì e, con un po' di fortuna, li distruggerà!$B$BDopodiché, sconfiggere Vectus non dovrebbe essere un problema. Giusto?",
  obj = "Metti Dawn's Gambit nella Viewing Room della Scholomance. Sconfiggi Vectus, poi torna da Betina Bigglezink.",
  progress = "Ricorda, $N — dobbiamo essere tolleranti ma inflessibili nelle nostre convinzioni!",
  reward = "Ce l'hai fatta! Vectus è sconfitto! E l'Azzardo dell'Alba... ha funzionato?$B$BMh... forse il mio congegno non è stato il successo che speravo, ma sono contenta che tu te la sia cavata comunque. Ottimo lavoro, $N!$B$BL'Argent Dawn, e la brava gente di Azeroth, ti sono debitori.",
}
T[4781] = {
  title = "Componenti per la Tonaca Dorata Incantata",
  desc = "Il tuo prossimo compito è semplice quanto il primo, ma dovrai cercare aiuto.$B$BMi serve del filo d'oro per il ricamo della tonaca, ma il filo d'oro non è facile da trovare, e pochissimi sanno come farlo. Per fortuna, uno che è fedele alla nostra causa ne conosce i segreti ed è disposto ad aiutare chi sale nei nostri ranghi.$B$BPorta una barra d'oro a Xizk Goodstitch, a Booty Bay. È un maestro sarto e sarà felice di filartelo. Le barre d'oro le fondono i minatori esperti. Chiedi aiuto a un minatore.",
  obj = "Porta una Gold Bar a Xizk Goodstitch, a Stranglethorn Vale.",
  progress = "Barre d'oro, sì... sì. Portamene una e vedremo cosa si può fare per ricavarne un po' di filo per te. Fino ad allora, ti consiglierei di concentrarti sul diventare più potente. Le prove più dure devi ancora affrontarle. E fidati... rimpiangerai di non esserti $Gpreparato:preparata; meglio, per quanto potente tu creda di essere.",
  reward = "Perfetto, $N. Sono contento che tu abbia trovato così in fretta un minatore che ti aiutasse. O hai fatto tutto da te? In ogni caso, ottimo lavoro. Questa sarà perfetta per il filo.$B$BCi vorrà un po' per prepararlo, quindi dovrai tornare — in realtà la mando a una principessa che teniamo rinchiusa in una torre e il cui unico compito è filare filo d'oro... no, sul serio. Dico davvero... e va bene, non è vero.",
}
T[4782] = {
  title = "Componenti per la Tonaca Dorata Incantata",
  desc = "Torna da Menara e dille che ci vorrà un po', ma che non la deluderò... e nemmeno te. Dille di farti finire di raccogliere il resto dei componenti — per allora dovrei aver finito il filo. A quel punto potrai tornare a prenderlo.$B$BBuona fortuna, $N. Ah, e già che ci sei salutami Strahad. Quel vecchio strambo... piazzare una torre proprio lì accanto a Ratchet... roba da matti.",
  obj = "Torna da Menara Voidrender, nelle Barrens.",
  reward = "Bene, sei $Gtornato:tornata;, $N. E dov'è il filo?$B$BAh, capisco. È accettabile. Il goblin e suo fratello non ci hanno ancora delusi — suppongo sia comprensibile che non l'avesse pronto lì per lì. E sia... nel frattempo abbiamo altro di cui occuparci.$B$BSei $Gpronto:pronta; per il prossimo passo?",
}
T[4783] = {
  title = "Componenti per la Tonaca Dorata Incantata",
  desc = "I prossimi componenti si trovano a Desolace, molto a ovest delle Barrens e perfino delle Stonetalon Mountains.$B$BLì, dopo la Grande Separazione, regna ancora il caos. Laggiù saranno messe alla prova sia la tua forza sia la tua astuzia — affronterai creature dell'odio e anche della Legione Infuocata.$B$BDei satiri Hatefury, a nordest, portami il sangue. Dagli infernali minori della Congrega di Mannoroc, portami una pietra infernale minore.$B$BUseremo entrambi per confezionare la tua tonaca.",
  obj = "Porta 10 Vials of Hatefury Blood e 1 Lesser Infernal Stone a Menara Voidrender, nelle Barrens.",
  progress = "Desolace non è una terra clemente: naga, giganti, satiri, la Legione Infuocata... tutti loro, e i clan di centauri in guerra, la rendono pericolosa per chi non fa attenzione.$B$BCome ti ho già detto, non metterà alla prova solo la tua forza e la tua astuzia, ma anche la tua pazienza. Sta' in guardia in quelle terre, $N.",
  reward = "Eccellente, $N. Questi andranno benissimo. Li preparo subito, mentre tu passi agli ultimi due componenti. Sei $Gpronto:pronta;?",
}
T[4784] = {
  title = "Componenti per la Tonaca Dorata Incantata",
  desc = "Ormai mi servono solo tre cose, $N, poi potremo finire la tua tonaca.$B$BPrimo, il filo d'oro pregiato che Xizk sta preparando per te. Torna da lui a Booty Bay e fattelo dare.$B$BSecondo, portami due carboni ardenti presi agli elementali del fuoco degli Arathi Highlands. Se ricordo bene, stanno a ovest, vicino al Muro di Thoradin.$B$BInfine, un frammento d'anima creato da te.$B$BQuando avrai tutti i componenti, torna qui alla torre e completerò la tonaca per te.",
  obj = "Porta del Fine Gold Thread, 2 Smoldering Coals e un Soul Shard a Menara Voidrender, nelle Barrens.",
  progress = "Presto, $N. Te lo prometto. La tonaca sarà più che adeguata alle tue esigenze e ti darà di certo un vantaggio sui tuoi avversari.",
  reward = "Eccellente, $N! I componenti sono raccolti e siamo $Gpronti:pronte;.$B$BConfido che ne sarai $Gsoddisfatto:soddisfatta;.",
}
T[4785] = {
  title = "Filo Dorato Pregiato",
  reward = "Ecco a te, $N. E per favore, porta a Menara i nostri saluti.$B$BCi aspettiamo grandi cose da te. Forse, quando la Legione cadrà in ginocchio, il tuo nome sarà pronunciato a gran voce, in lode del tuo potere. Non vedo l'ora!",
}
T[4786] = {
  title = "La Tonaca Completata",
  desc = "Ora metterò insieme la tonaca per te. Ci vorranno solo pochi istanti. Non allontanarti.",
  obj = "Aspetta che Menara Voidrender completi la tua tonaca, poi parlale di nuovo.",
  progress = "Un momento, $N...",
  reward = "Ecco fatto, $N. Tieni. Indossala con orgoglio.$B$BHai lavorato sodo e vedo grandi cose nel tuo futuro. Ricorda, per resistere alla corruzione che accompagna la nostra via servono grande volontà e forza d'animo. Finché la tua volontà resterà tua, avrai grande successo.",
}
T[4787] = {
  title = "L'Uovo Antico",
  desc = "La Profezia di Mosh'aru parla di un uovo antico. È una reliquia dei tempi in cui i troll dominavano vasti imperi, e ha il potere di contenere l'essenza di Hakkar. Forse è l'unico modo per tenere il nostro mondo al sicuro dalla sua malvagità.$B$BPortami l'uovo antico, $N. Si dice che sia nascosto nelle profondità di Jintha'Alor, negli Hinterlands, in una caverna dietro l'anfiteatro in cima alla città.",
  obj = "Porta l'Ancient Egg a Yeh'kinya a Tanaris.",
  progress = "Hai l'uovo antico? Sento grandi forze che si risvegliano, e temo che ci resti poco tempo.",
  reward = "Ah, hai l'uovo! Mi inchino davanti a te, $N. La tua forza e il tuo coraggio saranno ricordati a lungo.",
}
T[4788] = {
  title = "Le Ultime Tavolette",
  desc = "Mentre io esamino la terza e la quarta tavoletta di Mosh'aru, tu devi trovare la quinta e la sesta! Non sarà facile, perché le tengono i troll Smolderthorn dentro Blackrock Spire. La guglia è una cupa montagna di fuoco fra le Burning Steppes e la Searing Gorge.$B$BBuona fortuna, $N. Blackrock Spire non è posto per gente perbene...",
  obj = "Porta la Fifth Mosh'aru Tablet e la Sixth Mosh'aru Tablet a Prospector Ironboot a Tanaris.",
  progress = "Sei $Gstato:stata; alla guglia, $N? Hai la quinta e la sesta tavoletta?",
  reward = "Incredibile! Le hai trovate! Sei $Gun vero eroe:una vera eroina;, $N!$B$BEd è un bene, perché ho letto le tavolette che mi avevi portato prima e, da quello che ho capito... ci servirà un eroe per fermare quello che sta per arrivare...",
}
T[4801] = {
  title = "E'ko Frostsaber",
  progress = "A Winterspring combatterai dei grandi felini chiamati frostsaber. Queste bestie hanno una velocità e un'astuzia incredibili. Se vuoi ottenere la velocità del frostsaber, portami l'E'ko che gli trovi addosso.$B$BRicorda, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari può ricavare il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4802] = {
  title = "E'ko Winterfall",
  progress = "A Winterspring combatterai contro delle creature traviate che chiamano mezzorsi Winterfall. Per volere del loro capo, hanno acquisito una forza incredibile. Se vuoi ottenere la potenza dei Winterfall, portami l'E'ko che gli trovi addosso.$B$BRicorda, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari può ricavare il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4803] = {
  title = "E'ko Shardtooth",
  progress = "A Winterspring troverai dei grossi orsi con la pelle spessissima. Questi orsi Shardtooth ricavano molta protezione da quello che riescono a sopportare. Se vuoi ottenere la resistenza al fuoco, portami l'E'ko che trovi addosso agli Shardtooth.$B$BRicorda, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari può ricavare il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4804] = {
  title = "E'ko di Chillwind",
  progress = "A Winterspring combatterai contro delle grosse creature volanti che chiamano Chillwind. Queste bestie hanno il potere di usare le magie del gelo. Se vuoi diventare resistente al gelo, portami l'E'ko che trovi sui Chillwind.$B$BRicordati, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari ne può tirare fuori il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4805] = {
  title = "E'ko Ice Thistle",
  progress = "A Winterspring combatterai contro delle grosse creature che chiamano yeti cardighiaccio. Queste bestie si muovono piano, ma con la protezione che gli dà la pelliccia folta riescono a evitare tanti colpi. Se vuoi avere l'abilità di schivare gli attacchi, portami l'E'ko che trovi su di loro.$B$BRicordati, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari ne può tirare fuori il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4806] = {
  title = "E'ko di Frostmaul",
  progress = "A Winterspring hai combattuto contro quei grossi giganti del ghiaccio che chiamano frostmaul. Di potenza e di forza bruta ne hanno quanta ne vogliono. Se vuoi avere la forza dei frostmaul, portami l'E'ko che trovi su di loro.$B$BRicordati, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari ne può tirare fuori il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4807] = {
  title = "E'ko di Wildkin",
  progress = "A Winterspring combatterai contro delle creature possenti che sembrano avere un'abilità magica innata. Questi wildkin sanno usare magie potenti. Se vuoi aumentare il tuo intelletto, portami l'E'ko che trovi su uno qualsiasi degli owlbeast che incontri là.$B$BRicordati, devi avere la Cassa di Mau'ari nell'inventario se vuoi andare a caccia di E'ko.",
  reward = "Mau'ari ne può tirare fuori il juju per $N... Usa la Cassa di Mau'ari per lanciarlo su di te o sui tuoi alleati.",
}
T[4808] = {
  title = "Felnok Steelspring",
  desc = "Ho un altro favore da chiederti.$B$BDal mio primo studio dell'essenza che hai raccolto risulta che forse è possibile congelare le uova dei cuccioli di drago e conservarle! Voglio mettere alla prova questa teoria, ma prima mi servono dei componenti di ingegneria fatti apposta. Il mio collega, Felnok Steelspring, li sa costruire.$B$BEcco, porta questa lettera a Felnok. Dentro c'è scritto cosa mi serve. Troverai Felnok a Winterspring, nella cittadina di Everlook.",
  obj = "Consegna Tinkee's Letter a Felnok Steelspring.",
  progress = "Che freddo quassù! Spero che tu mi abbia portato una coperta!",
  reward = "Questa non è una coperta! Ma cos'abbiamo qui? Una lettera di Tinkee? Chissà cos'ha da dirmi...$B$BAh, sta facendo ricerche nelle Burning Steppes. Ha senso — lì di dragonkin ce n'è in abbondanza. Oh, ma guarda! Qui dice che le servono dei pezzi per un congegno che vuole costruire. Mi sa che è qui che entro in gioco io, eh?",
}
T[4809] = {
  title = "Corna di Chillwind",
  desc = "Ho quasi tutto quello che serve a Tinkee, ma mi manca un componente importante, cioè le corna di chillwind. Le corna della chimera chillwind di Winterspring sono una fonte concentrata di freddo, ma vanno bene solo quelle perfette, intatte! Me ne servirà una scorta per completare l'ordine di Tinkee.$B$BPortami le corna di chillwind intatte e preparerò un pacco per Tinkee.",
  obj = "Porta 8 Uncracked Chillwind Horns a Felnok Steelspring.",
  progress = "Hai le corna di chillwind, $N?",
  reward = "Sono dei begli esemplari. Sono carichi di freddo! Fammi mettere dei guanti, poi li imballo insieme alle altre cose che servono a Tinkee...",
}
T[4810] = {
  title = "Ritorno da Tinkee",
  desc = "Ok, è tutto preparato, imballato e pronto per il trasporto! Buona fortuna per il viaggio, e mi raccomando, di' a Tinkee che è in debito con me!",
  obj = "Porta Felnok's Package a Tinkee Steamboil nelle Burning Steppes.",
  progress = "$N! Hai parlato con Felnok? Hai portato i componenti che mi servono?",
  reward = "Li hai portati! Ottimo! Mi metto subito al lavoro! Grazie mille, $N!$B$BMi sei $Gstato:stata; così d'aiuto che più avanti potrei aver bisogno di te per compiti ancora più importanti...",
}
T[4821] = {
  title = "Uovo Alieno",
  desc = "È circolata la voce di un uovo alieno qui a Thousand Needles. Chi dice di averlo visto non è nemmeno riuscito ad avvicinarsi abbastanza da esaminarlo nei dettagli. I serpenti sorvegliano l'uovo come se fosse uno dei loro.$B$BVoglio che tu trovi questo uovo alieno e me lo porti, così potrò esaminarlo. Si dice che l'uovo si trovi in una tana di serpenti, ma di tane ce ne sono parecchie lungo la base delle pareti rocciose a sud e a nord-est del Presidio di Freewind.",
  obj = "Porta l'Alien Egg a Hagar Lightninghoof, al Presidio di Freewind.",
  progress = "Devo saperne di più su quest'uovo misterioso: chissà cosa ne uscirà.",
  reward = "Sì, finalmente... l'uovo misterioso mi è stato finalmente consegnato. Ora, fammi dare un'occhiata più da vicino... Cosa...! Cos'è questo...?",
  en_title = "Alien Egg",
  en_obj = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.",
}
T[4822] = {
  title = "Tu Gridi, Io Grido...",
  desc = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Gelato alla Fragola di Tigule e Foror! È il mio gelato preferito in tutto il mondo!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Gelato alla Fragola di Tigule e Foror??!?!",
  obj = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!",
  reward = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!$B$BGrazie mille, $N: è la cosa più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[4841] = {
  title = "Pacificare i Centauri",
  desc = "$N, ti supplico di dare la caccia a questi centauri. Sentiranno l'ira della nostra vendetta. Attacca l'accampamento dei centauri a nord del Presidio di Freewind! Che l'ira guidi la tua mano!",
  obj = "Uccidi 12 Galak Scout, 10 Galak Wrangler e 6 Galak Windchaser, poi torna da Cliffwatcher Longhorn, al Presidio di Freewind.",
  progress = "Suvvia, $N, lo so che non ne hai ancora uccisi abbastanza. Dagli la caccia, e ti darò una ricompensa in segno di gratitudine.",
  reward = "In segno di gratitudine, questo è per te, $N.",
  en_title = "Pacify the Centaur",
  en_obj = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.",
}
T[4842] = {
  title = "Strane Origini",
  desc = "A dire la verità, anche se qui a Winterspring non ci sono vulcani, credo che dietro queste sorgenti termali ci siano cause ben più minacciose...$B$BBe', penso che vorrai vederlo con i tuoi occhi. Dovrai attraversare Winterspring per tutta la sua lunghezza e spingerti fino all'estremo sud. Quando l'aria si farà pesante e afosa e il cielo si oscurerà, avrai trovato quella che secondo me è l'origine delle sorgenti termali.$B$BDai un'occhiata. Sono sicura che al tuo ritorno avrai molte domande.",
  obj = "Segui le istruzioni di Donova Snowden, poi torna a fare rapporto.",
  progress = "L'acqua delle sorgenti sembra avere delle proprietà molto strane... Non so ancora bene cosa significhi...",
  reward = "Sì, i demoni laggiù nella Gola di Darkwhisper; credo sia la loro presenza ad alterare così questa terra. Io continuerò a osservare le sorgenti termali qui, per vedere se scopro qualcos'altro.$B$BSe pensi di addentrarti ancora nella Gola di Darkwhisper, io aspetterei di essere un po' più forte.",
}
T[4861] = {
  title = "Wildkin Infuriati",
  desc = "Ehilà, $Gragazzo:ragazza;! Dei wildkin assetati di sangue mi hanno cacciato dal mio accampamento, nel sud di Winterspring! Be', mi sa che mi sono avvicinato troppo a qualcosa che i wildkin stavano sorvegliando.$B$BIo me la sono cavata per un pelo; temo che un mio amico non abbia avuto la stessa fortuna. Ti dispiacerebbe sfidare i wildkin e andare all'accampamento? Ho proprio bisogno delle mie scorte, e vorrei anche riavere l'amuleto che ho dissotterrato ieri allo scavo.",
  obj = "Trova l'accampamento distrutto di Jaron Stoneshaper e le sue scorte nel sud di Winterspring.",
  reward = "Tra il resto delle cose distrutte dell'accampamento spicca una cassa gravemente danneggiata...",
}
T[4862] = {
  title = "Esse-Ci-Acca-I-Effe-O",
  desc = "Che tu ci creda o no, c'è gente in giro disposta a pagare per la più ripugnante delle bestie addomesticate!$B$BAvevo mandato Bijou nella Guglia a cercare di raccogliere un po' di quelle uova di ragno della guglia, ma non ho sue notizie da settimane. Magari mi puoi dare una mano tu?$B$BFacciamo così, $N. Vai a Blackrock Spire e raccoglimi un po' di uova di ragno della guglia. Riportale qui e non solo ti do qualche soldo, ma te ne addomestico pure uno!",
  obj = "Vai a Blackrock Spire e raccogli 15 Spire Spider Eggs per Kibler.$B$BA quanto pare, queste uova si potrebbero trovare vicino ai ragni.",
  progress = "Hai delle uova di ragno nello zaino o sei solo $Gcontento:contenta; di vedermi?",
  reward = "Che carico! Cioè, guarda quante uova! Queste dovrebbero fruttare un bel po' d'oro.$B$BCome promesso, ecco la tua bestiolina. Non farti mordere!",
}
T[4863] = {
  title = "Wildkin Infuriati",
  desc = "Guardandoti intorno, non vedi molto che possa servire a Jaron. Noti però che la cassa che hai trovato è stata sfondata, quasi fosse proprio quella che i wildkin cercavano...$B$BGuardando a est, riesci a malapena a distinguere un carro abbandonato. Forse lì potresti trovare le cose di Jaron. Vale la pena dare un'occhiata.",
  obj = "Trova il carro distrutto di Jaron Stoneshaper.",
  reward = "Avvicinandoti al carro, non ti sembra che qui ci sia molto altro per Jaron. Ma, guardando a terra, noti alcune casse che sembrano intatte, pur essendo semisepolte nella neve.",
}
T[4864] = {
  title = "Wildkin Infuriati",
  desc = "Dopo aver esaminato il contenuto della cassa, decidi che a Jaron potrebbero servire gli attrezzi e gli altri oggetti che ci sono dentro. Dell'amuleto, però, non c'è traccia.$B$BA quanto pare i wildkin vivono nelle terre a nord e a est di qui, quindi decidi che il prossimo passo è affrontare le creature e recuperare l'amuleto.",
  obj = "Raccogli Jaron's Supplies dalla neve, poi trova i wildkin che hanno rubato l'amuleto di cui parlava Jaron.$B$BPorta Jaron's Supplies e il Blue-feathered Amulet a Jaron Stoneshaper al rifugio a Winterspring.",
  progress = "Sì... Dimmi le novità.",
  reward = "Be', me l'aspettavo, $Gragazzo:ragazza;. Immaginavo che quelle bestie impazzite avessero distrutto tutta la mia roba...$B$BMa hai trovato i miei attrezzi e, cosa più importante, l'amuleto! Chissà perché i wildkin difendevano con tanta ferocia questo oggetto... In ogni caso, ci penserò due volte prima di tornare dalle loro parti!",
}
T[4865] = {
  title = "Serpente Selvaggio",
  desc = "Se non l'avessi visto con i miei occhi non ci avrei mai creduto. La vendetta è arrivata a Thousand Needles!$B$B<Hagar si asciuga la fronte.>$B$B$N, devi agire in fretta! Va' subito a cercare Motega Firemane; si trova all'Accampamento di Whitereach, appena a nord-ovest del Presidio di Freewind, lungo la strada. Lui saprà cosa fare!",
  obj = "Riferisci quel che hai scoperto a Motega Firemane.",
  reward = "Vendetta! Allora la leggenda di Arikara è vera. Sì, è un problema da risolvere subito.",
  en_title = "Serpent Wild",
  en_obj = "Report your findings to Motega Firemane.",
}
T[4866] = {
  title = "Latte di Madre",
  desc = "Probabilmente è uno dei veleni più potenti del mondo, $R!$B$BNelle mie scappate dentro la Guglia ho sentito i Blackrock parlare di quanto è letale. Lo chiamano 'Latte di Madre', da Madre Smolderweb, quel grosso ragnaccio nella caverna Skitterweb.$B$BOra, ecco cosa mi serve da te: un campione vivo del Latte, che scorre nelle TUE vene. Portarmi solo la ghiandola non basta! Fatti avvelenare da lei e torna da me!$B$BPoi... ti mungo io!$B$B<Si sfrega le mani, pregustando il momento.>",
  obj = "Nel cuore di Blackrock Spire troverai Mother Smolderweb. Affrontala e fatti avvelenare da lei. È molto probabile che tu debba anche ucciderla. Torna da Ragged John quando sei $Gavvelenato:avvelenata;, così potrà 'mungerti'.",
  progress = "<Ragged John ti dà un pizzicotto.>",
  reward = "Con questo verrà fuori la birra migliore di sempre!$B$BEh, per cosa credevi che l'avrei usato? Per farci del veleno o roba simile??$B$BQuesti ragazzi sono matti...",
}
T[4867] = {
  title = "Urok Doomhowl",
  desc = "Argh! Che fatica parlare!$B$BPrendi questo biglietto! Portami il mio mojo!",
  obj = "Leggi Warosh's Scroll. Porta Warosh's Mojo a Warosh.",
  progress = "Ah! Ce l'hai il mio mojo?",
  reward = "Aha! Sento già i miei poteri che tornano. E la maledizione di Urok non mi tormenta più la mente.$B$BGrazie, $N! L'umiltà non è degna di me, ma il tuo aiuto devo riconoscerlo.$B$BE ti auguro buona fortuna nei tuoi viaggi per Blackrock Spire. Sei $Guno sciocco:una sciocca; a pensare di poter arrivare fino in cima, ma il tuo coraggio è fuori discussione.",
}
T[4881] = {
  title = "Complotto Omicida",
  desc = "Il Tauren Kanati Greycloud ha l'ardire di piantare un campo di caccia a Thousand Needles. Dobbiamo ucciderlo per liberarci di questo campo e di tutti quelli che potrebbero seguirlo. Ci raduneremo al piccolo avamposto a sud-ovest del Grande Ascensore.",
  obj = "Avverti Kanati Greycloud, all'Accampamento di Whitereach, del complotto per ucciderlo.",
  reward = "Vengono a uccidermi? Mostrerò loro come combatte un Tauren!",
  en_title = "Assassination Plot",
  en_obj = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
}
T[4882] = {
  title = "A Guardia dei Segreti",
  desc = "Non sai bene che importanza abbia la collana caduta dal collo del wildkin appena ucciso. Emana una luce intensa, che lentamente si affievolisce e si ravviva.$B$BTrull Failbane potrebbe saperti dire di più, visto che la sua conoscenza dei wildkin sembra vasta. Forse dovresti chiederglielo.",
  obj = "Porta la Blue-feathered Necklace a Trull Failbane all'Avamposto di Bloodvenom.",
  progress = "A rapporto per un altro incarico?",
  reward = "Una scoperta importante?",
}
T[4883] = {
  title = "A Guardia dei Segreti",
  desc = "Anche se so molte cose sugli owlbeast che hai sconfitto a Winterspring, non sono molto ferrato sulle magie che usano. Ma credo di conoscere qualcuno che potrebbe esaminare la collana e, molto probabilmente, dirti cos'è.$B$BNara Wildmane, a Thunder Bluff, è un'esperta in questo campo; va' da lei. Buona fortuna, $N.",
  obj = "Porta la Blue-feathered Necklace a Nara Wildmane.",
  progress = "Come posso aiutarti, $N?",
  reward = "L'energia di questa collana, $N. Credo che abbia un'unica origine.$B$B<Nara chiude gli occhi e resta in silenzio per un momento.>$B$BI wildkin, ora sviati e confusi, un tempo non erano così. Un tempo avevano uno scopo, ed erano guidati a servire. Elune, la dea degli elfi della notte, creò queste creature perché custodissero i suoi luoghi più sacri.$B$BAnche se questo fatto può sembrare di poco valore; ti esorto a guardare più a fondo.$B$BImparerai, col tempo. Grazie per avermela portata, $N.",
}
T[4901] = {
  title = "Guardiani dell'Altare",
  desc = "Proprio in cima al crinale c'è quello che credo sia un altare della dea Elune. Da quel che ho capito, dobbiamo accendere le cinque torce in ogni grotta, e poi potremo accedere direttamente all'altare.$B$BHo trascritto alcuni incantesimi incisi nella pietra nelle antiche rovine di Kel'Theril, e credo che siano il segreto per sbloccare l'altare. Mi servirà il tuo aiuto per accendere ogni torcia, mentre io recito l'incantesimo.$B$BSe ci riusciamo, potrai riferire a Erelas le nostre scoperte!",
  obj = "Proteggi Ranshalla mentre tenta di riattivare l'Altar of Elune. Riferisci le tue scoperte a Erelas Ambersky a Rut'theran Village.",
  reward = "Hai incontrato Ranshalla?",
}
T[4902] = {
  title = "Wildkin di Elune",
  desc = "È affascinante!$B$BMi sono sempre chiesto quale fosse la verità... Be', devi assolutamente far conoscere quello che hai scoperto! Vai subito dall'Arcidruido Fandral Staghelm — lo troverai a Darnassus, nel Cenarion Circle. Spiegagli cos'è successo, proprio come l'hai raccontato a me. Sono sicuro che gli interesserà altrettanto!$B$BSono informazioni importanti, $N!",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Non esitare; dimmi perché sei $Gvenuto:venuta;.$B$BAh, sì? Hmm. Bene.$B$BGrazie per averlo riferito subito a me; è sempre meglio rivolgersi direttamente ai piani alti... Ma... Sì. I druidi del Cenarion Circle sanno dei Wildkin da tempo. Che sono gli animali prediletti di Elune, e che furono scelti per custodire i luoghi più sacri.$B$BQuindi, anche se non è una novità, ti faccio senz'altro i complimenti per l'impegno. Ecco, prendi questo — mi sembra adatto a un gesto simile.",
}
T[4903] = {
  title = "L'Ordine del Signore della Guerra",
  desc = "Per ordine del Signore della Guerra Goretooth, i seguenti abitanti di Blackrock Spire devono essere annientati:$B$BLa minaccia corpulenta, il Gran Signore Omokk.$B$BIl troll crudele e spietato, il Maestro di Guerra Voone.$B$BIl Supremo Wyrmthalak, aguzzino della città minore.$B$BDovrai inoltre riportare ogni documento importante che ti capiterà di trovare.$B$BRiesci, e sarai $Gonorato:onorata;.$B$BFallisci, e sarai $Gdimenticato:dimenticata;.",
  obj = "Uccidi Highlord Omokk, War Master Voone e Overlord Wyrmthalak. Recupera gli Important Blackrock Documents. A missione compiuta, torna da Warlord Goretooth a Kargath.",
  progress = "<Il Signore della Guerra Goretooth fa il saluto militare.>",
  reward = "<Per un breve istante la pelle verde spento del Signore della Guerra Goretooth si fa di un bianco smorto.>",
}
T[4904] = {
  title = "Finalmente Libera",
  desc = "Arnak crede che ci sposeremo... ma dopo che ho rifiutato la sua proposta è tornato quella stessa notte e mi ha rapita. Mio fratello ha cercato di fermarlo, ma Arnak era troppo forte. Lui... lui ha ucciso mio fratello e poi mi ha portata qui. Povero fratello mio...$B$B$N, potresti scortarmi fuori dal Pinnacolo di Darkcloud? Ti prego... devo tornare da Thalia! Sarà preoccupatissima per me.",
  obj = "Scorta Lakota Windsong fuori dal Pinnacolo di Darkcloud, poi parla con Thalia Amberhide, al Presidio di Freewind.",
  progress = "Thalia Amberhide:",
  reward = "Grazie, $N. Lo sentivo nelle ossa che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato del tuo coraggio e di come l'hai aiutata a fuggire. Questi oggetti erano di suo fratello. So che vorrebbe che li avessi tu.",
  en_title = "Free at Last",
  en_obj = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
}
T[4906] = {
  title = "Altra Corruzione",
  desc = "Un secondo accampamento di satiri minaccia la terra di Felwood, verso nord, guidato dal crudele Xavaric. Quegli ignobili traditori e ingannatori si nutrono della corruzione delle creature originarie di Felwood.$B$BXavathras e i suoi servitori erano solo una parte di un piano più grande — coltivare un pozzo lunare corrotto, per poi consegnare il bottino a Xavaric.$B$BOra che Xavathras è stato tolto di mezzo, porta a termine il compito, $N. Va' a nord e sconfiggi Xavaric.",
  obj = "Eridan Bluewind, a Felwood, vuole che tu uccida 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters e Xavaric. Torna da Eridan Bluewind a compito finito.",
  progress = "Ti prego, metti fine alle sofferenze delle creature di Felwood.",
  reward = "Grazie per tutto quello che hai fatto, $N. Che Elune ti protegga e ti guidi sul cammino che ti aspetta.",
}
T[4907] = {
  title = "Tinkee Steamboil",
  desc = "Ciao, $N. Ti ricordi di Tinkee Steamboil? Beh, lei di te si ricorda! Mi ha mandato un messaggio per dirmi di tenere gli occhi aperti nel caso ti vedessi, perché... ha di nuovo bisogno del tuo aiuto. Credo che c'entrino i suoi studi sui draghi.$B$BDovresti andare a parlarle nelle Burning Steppes, al Cimiero Ardente.",
  obj = "Parla con Tinkee Steamboil.",
  reward = "Felnok aveva ragione! Ho davvero bisogno di nuovo del tuo aiuto, e stavolta... sarà pericoloso sul serio.$B$BSei $Gpronto:pronta;??",
}
T[4941] = {
  title = "La Saggezza di Eitrigg",
  desc = "Rend è vivo?$B$BImpossibile!$B$BSi credeva che Rend fosse stato ucciso decenni fa.$B$BCerca la saggezza di Eitrigg, $N. Nessuno conosce i Blackrock e il loro modo di agire meglio di lui e, se ciò che è scritto qui è vero, Eitrigg dev'essere informato. A nessuno va negato il diritto alla vendetta.$B$BLo troverai a Orgrimmar.$B$BDopo aver parlato con Eitrigg, consultati con il Capoguerra per sapere cosa intende fare riguardo a questo problema.",
  obj = "Parla con Eitrigg a Orgrimmar. Dopo averne discusso con Eitrigg, chiedi consiglio a Thrall.$B$BRicordi di aver visto Eitrigg nella sala di Thrall.",
  progress = "Non vedi che non devo essere interrotto?",
  reward = "<Thrall appare sgomento per le notizie che porti.>",
}
T[4961] = {
  title = "La Purificazione del Globo di Orahil",
  desc = "Ah, un globo da evocatore — ecco da dove deve venire la corruzione. Se vuoi usarlo, dobbiamo esorcizzare il demone che c'è dentro. Quello lo posso fare senza fatica.$B$BLa parte difficile tocca a te. Devi uccidere il demone appena lo libero.$B$BE dovrai fare in fretta. Se ci metti troppo tornerà nel globo e dovremo ricominciare da capo!$B$BQuindi preparati, $N. Tieni pronti i tuoi incantesimi più potenti e le pozioni a portata di mano, e vai a chiamare un amico, se ne hai uno. Perché non sarà un bello spettacolo.",
  obj = "Uccidi il Demon of the Orb, poi parla con Tabetha.",
  progress = "Dovrai uccidere quel demone per eliminare per sempre la sua presenza dal globo, $N.",
  reward = "Ottimo lavoro, $N! Hai dato a quel demone una lezione che non dimenticherà tanto presto. Hai dimostrato grande potere e grande abilità. Ora direi che è tempo di tornare da Menara con il tuo globo purificato, così potrai farne buon uso.$B$BBuona fortuna, $C. Forse le nostre strade si incroceranno ancora.",
}
T[4962] = {
  title = "Frammento di un Vilsegugio",
  desc = "Dunque hai scelto di catturare l'anima di un vilsegugio, bene.$B$BPrendi questo rubino — ti permetterà di catturare l'anima della creatura. Funziona più o meno come gli incantesimi che conosci già: quando la creatura è in fin di vita, usa la gemma e al resto dovrebbe pensare lei.$B$BTi consiglio di andare a Desolace e di provarci con uno qualsiasi dei vilsegugi che trovi lì. Quelli dovrebbero andare benissimo.$B$BQuando ce l'avrai fatta, porta a Menara sia lo spirito catturato sia il tuo rubino.",
  obj = "Prendi il Felhas Ruby e usalo su uno dei Felhounds che si trovano a Desolace. Quando ce l'avrai fatta, riporta il Felhas Ruby e l'Imprisoned Felhound Spirit a Menara Voidrender nelle Barrens.",
  progress = "Sì, $N? Hai scelto? Infernale o vilsegugio?$B$BOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Capita che uno stregone scelga di potenziarsi ancora di più, invece di rimediare là dove è carente. A volte sopraffare il nemico è una tattica valida quanto diventare un incantatore più equilibrato.",
  reward = "Ah, lo spirito di un vilsegugio. Ottimo lavoro, $N.$B$BQuando avrò sia lo spirito sia il globo purificato li fonderò per te, ma non prima.",
}
T[4963] = {
  title = "Frammento di un Infernale",
  desc = "Dunque hai scelto di catturare l'anima di un infernale, bene.$B$BPrendi questo smeraldo — ti permetterà di catturare l'anima della creatura. Funziona più o meno come gli incantesimi che conosci già: quando la creatura è in fin di vita, usa la gemma e al resto dovrebbe pensare lei.$B$BTi consiglio di andare a Desolace e di provarci con uno qualsiasi degli infernali che trovi lì. Quelli dovrebbero andare benissimo.$B$BQuando ce l'avrai fatta, porta a Menara sia lo spirito catturato sia il tuo smeraldo.",
  obj = "Prendi l'Infus Emerald e usalo su uno degli Infernals che si trovano a Desolace. Quando ce l'avrai fatta, riporta l'Infus Emerald e l'Imprisoned Infernal Spirit a Menara Voidrender nelle Barrens.",
  progress = "Sì, $N? Hai scelto? Infernale o vilsegugio?$B$BOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Capita che uno stregone scelga di potenziarsi ancora di più, invece di rimediare là dove è carente. A volte sopraffare il nemico è una tattica valida quanto diventare un incantatore più equilibrato.",
  reward = "Ah, lo spirito di un infernale. Ottimo lavoro, $N.$B$BQuando avrò sia lo spirito sia il globo purificato li fonderò per te, ma non prima.",
}
T[4964] = {
  title = "Il Globo di Dar'Orahil Completato",
  desc = "Mi metto subito a creare il tuo globo e a infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante adattarmi all'arma scelta da uno stregone... Non vedo motivo di smettere.",
  obj = "Aspetta che Menara Voidrender completi l'Orb of Dar'Orahil, poi parlale di nuovo.",
  reward = "È fatto, $N. Dimmi soltanto cosa preferisci: un bastone, che richiederebbe tutte e due le mani, o un globo, così da poter usare come arma un pugnale o una spada.$B$BAffrontare un vilsegugio è stata una vera prodezza da parte tua. Sono certa che il tuo oggetto ti sarà molto utile in futuro. Continua a impegnarti nelle arti, $N. Aspetto notizie delle tue imprese.",
}
T[4965] = {
  title = "La Conoscenza del Globo di Orahil",
  desc = "Bene, bene, bene... è un piacere vedere che il tuo potere cresce, $N. Scommetto che ormai sei quasi $Gpronto:pronta; per parlare con Menara Voidrender, nelle Barrens. Se non le hai mai parlato, lascia che te lo dica: non credo di aver mai conosciuto un altro esperto nella creazione di oggetti — globi, per la precisione — capaci di imprigionare con tanta facilità perfino un demone perché serva la nostra volontà.$B$BSe ti interessa, è nella torre di Strahad, sopra Ratchet, nelle Barrens.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, allora cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero $Gpronto:pronta;.$B$BÈ una gradita novità vedere $Guno:una; di noi che cerca più potere in forme diverse dalla sola conoscenza.$B$BAllora, ti senti $Gpronto:pronta;, $N?",
}
T[4966] = {
  title = "Proteggi Kanati Greycloud",
  desc = "Però i centauri potrebbero essere più di quanti pensassi: ti chiedo, $N, di combattere al mio fianco contro questi vili assassini.",
  obj = "Proteggi Kanati Greycloud dall'attacco dei centauri.",
  reward = "Grazie del tuo aiuto, $N. Senza di te non sarei riuscito a tenerli a bada.",
  en_title = "Protect Kanati Greycloud",
  en_obj = "Protect Kanati Greycloud from the centaur attack.",
}
T[4967] = {
  title = "La Conoscenza del Globo di Orahil",
  desc = "Sei ancora $Guno sciocco:una sciocca;, e cerchi ancora gli orpelli dei mortali. Sì, ti parlo con arroganza. Ti vedo davanti a me e rido. Sei $Gpatetico:patetica;!$B$BMa non conta quello che penso io. Conta solo quello che pensa chi è disposto ad avere a che fare con te! E in questo caso, contro il mio parere, quelli che hanno un po' di potere ritengono che tu meriti di più.$B$BSe è a questo che aspiri, allora dovresti parlare con Menara Voidrender, nella torre sopra Ratchet. Mi pare che tu l'abbia già incontrata qualche tempo fa.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, allora cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero $Gpronto:pronta;.$B$BÈ una gradita novità vedere $Guno:una; di noi che cerca più potere in forme diverse dalla sola conoscenza.$B$BAllora, ti senti $Gpronto:pronta;, $N?",
}
T[4968] = {
  title = "La Conoscenza del Globo di Orahil",
  desc = "Hmm, sei $Garrivato:arrivata; fin qui... davvero sorprendente. Avrei detto che a quest'ora la corruzione che viene dall'incanalare l'arcano ti sarebbe già penetrata fin nell'anima e ti avrebbe fatto impazzire. Che ne dici se proviamo a spingerti più in là, allora?$B$BSe vuoi mettere alla prova la tua abilità, cerca Menara Voidrender sopra Ratchet, nella torre di Strahad. Ti guiderà lei.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, allora cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero $Gpronto:pronta;.$B$BÈ una gradita novità vedere $Guno:una; di noi che cerca più potere in forme diverse dalla sola conoscenza.$B$BAllora, ti senti $Gpronto:pronta;, $N?",
}
T[4969] = {
  title = "La Conoscenza del Globo di Orahil",
  desc = "Haha! Te la stai cavando benissimo, giovane $C.$B$BCol tempo, infernali e signori del terrore si inchineranno davanti a te!$B$BMa finché non verrà quel momento, dovrai ancora affidarti ad armi forgiate dalle mani delle razze mortali.$B$BSembri $Gpronto:pronta; per un'altra creazione del genere e, se lo vuoi, Menara Voidrender vorrebbe parlarti! È vicino alla torre di Strahad, che domina la città portuale di Ratchet. Vacci quando sei $Gpronto:pronta;.",
  obj = "Parla con Menara Voidrender, nelle Barrens.",
  reward = "Ah, allora cerchi davvero qualcosa di più... sostanzioso. Posso aiutarti, se sei davvero $Gpronto:pronta;.$B$BÈ una gradita novità vedere $Guno:una; di noi che cerca più potere in forme diverse dalla sola conoscenza.$B$BAllora, ti senti $Gpronto:pronta;, $N?",
}
T[4970] = {
  title = "Provviste per le Frostsaber",
  desc = "Se desideri dimostrare il tuo valore, puoi cominciare da un compito molto semplice, ma molto importante.$B$BProcurati la carne delle chimere e degli orsi shardtooth della zona. Portamela, così che io possa nutrire le frostsaber in addestramento.",
  obj = "Raccogli 5 Shardtooth Meats e 5 Chillwind Meats per Rivern Frostwind a Winterspring.",
  progress = "Disciplina e determinazione sono i tuoi obiettivi. Potrei chiederti di svolgere molte volte un compito semplice; ogni volta dovrai dare il meglio di te.",
  reward = "Ti ringrazio dell'aiuto, $N. Con il passare del tempo la mia stima per te cresce.",
}
T[4971] = {
  title = "Una Questione di Tempo",
  desc = "Una forza sinistra — molto probabilmente il Flagello — ha manomesso la linea temporale ad Andorhal! Posso provare a mantenere intatto lo scorrere del tempo qui e a riparare ciò che è stato danneggiato, ma mi servirà il tuo aiuto per farlo senza interruzioni.$B$BI parassiti temporali — carogne che si nutrono dei fili del flusso alterato del tempo — ora infestano i silos di Andorhal. Una pulsazione blu di distorsione è l'unico segno visibile della loro presenza. Rallentano le mie divinazioni; ti prego, $N, aiutami usando questo distorsore temporale per stanare i parassiti.",
  obj = "Usa il Temporal Displacer vicino a uno dei silos di Andorhal e fai uscire allo scoperto i Temporal Parasites.$B$BUccidi 15 Temporal Parasites, poi riporta il Temporal Displacer a Chromie nella Locanda di Andorhal, nelle Western Plaguelands.",
  progress = "I parassiti temporali sono un male comune, presente ovunque il flusso del tempo sia stato manomesso. Sento che ce ne sono molti, e questo è preoccupante.$B$BStanare tutti quelli che riesci a trovare mi aiuterà a tenere meglio sotto controllo la situazione temporale di qui, che si sta deteriorando. Quando sarà fatto, lo percepirò.",
  reward = "Ora il tempo sembra più facile da riparare, grazie, $N. Anche se forse non comprendi fino in fondo le conseguenze di una linea temporale spezzata, apprezzo che tu comprenda l'urgenza di contrastare quello che sospetto sempre di più essere un misfatto opera del Flagello.$B$BNon vedo alcun male nel ricompensarti per il tuo aiuto, mortale. Le tue imprese più grandi devono ancora venire, e il dono di un gingillo non altererà di certo il tuo destino futuro. Del tuo aiuto costante, però, io e il dragonflight potremmo avere bisogno...",
}
T[4972] = {
  title = "Il Conto del Tempo",
  desc = "Ho bisogno che tu ti spinga nel mondo al di là di questa stanza, $N. Lascia che ti spieghi.$B$BLo vedi quanto è diversa questa stanza dal resto di Andorhal. Il mio dragonflight opera in molti modi diversi e in molte linee temporali diverse. Per riparare i danni di Andorhal, ora agisco da un'altra linea temporale, così da non contaminarla troppo. Per andare avanti, però, mi servono dei monili del tempo, rimasti intrappolati nel momento in cui ha colpito la piaga. Cercali negli scrigni, dentro gli edifici in rovina che formano questa città un tempo fiera.",
  obj = "Trova 5 Andorhal Watches, che stanno negli scrigni fra le macerie della città. Poi portali a Chromie nella Locanda di Andorhal, nelle Western Plaguelands.",
  progress = "I monili del tempo che cerco sono congegni semplici. Sono perlopiù orologi, e le loro lancette sono intrappolate per sempre nell'istante in cui la piaga ha cominciato a devastare Andorhal.$B$BIl tempo non ha mai fine, e il suo conto riporterà immancabilmente a casa gli orologi che mi porti... sempre che qui le perturbazioni continuino.",
  reward = "Sono proprio quello che mi serve, $N. Grazie.$B$BLascia che ti ricompensi come meriti, con questo. Forse non capisci a cosa potrebbe servirti un congegno simile. Forse non sai nemmeno bene che cosa sia davvero. Purtroppo non posso dirti quando ti sarà più utile; sappi solo che un giorno, in futuro, potresti scoprire che questo oggetto, una volta consumato, è di un'utilità e di un'efficacia straordinarie. Tenerlo o no fino ad allora... questo, $Gamico mio:amica mia;, sta a te.",
}
T[4974] = {
  title = "Per l'Orda!",
  desc = "Rend osa avanzare pretese tanto grandiose perché gode della protezione dello stormo nero.$B$BTu, $N, troverai il modo di attraversare le Sale dell'Ascesa. Poi troverai il 'Capoguerra' Rend Blackhand e lo annienterai — PER L'ORDA!$B$B<Thrall sbatte un pugno sul trono.>$B$BLa prossima volta che tornerai nelle mie stanze terrai alta la sua testa in segno di trionfo, e poi la consegnerai al tuo Capoguerra. Fallo, e sarai $Gonorato come eroe:onorata come eroina; dell'Orda.",
  obj = "Vai a Blackrock Spire e uccidi Warchief Rend Blackhand. Prendi la sua testa e torna a Orgrimmar.",
  progress = "<Thrall grugnisce.>",
  reward = "Hai inferto un colpo devastante alle forze di Blackrock, $N. Ucciso il loro Capoguerra, la legione Blackrock viene gettata ancora una volta nelle fauci del caos.$B$BIn onore delle tue gesta eroiche, il popolo di Kalimdor sarà ricompensato!",
}
T[4975] = {
  title = "Il Globo di Noh'Orahil Completato",
  desc = "Mi metto subito a creare il tuo globo e a infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante adattarmi all'arma scelta da uno stregone... Non vedo motivo di smettere.",
  obj = "Aspetta che Menara Voidrender completi l'Orb of Noh'Orahil, poi parlale di nuovo.",
  reward = "È fatto, $N. Dimmi soltanto cosa preferisci: un bastone, che richiederebbe tutte e due le mani, o un globo, così da poter usare come arma un pugnale o una spada.$B$BAffrontare l'infernale è stata una vera prodezza da parte tua, e questa ricompensa fa proprio al caso tuo. Ti auguro altri successi nelle arti, $N.",
}
T[4976] = {
  title = "Riportare il Globo Purificato",
  desc = "Riporta il globo purificato a Menara, a Ratchet, $N. Salutala da parte mia e abbi cura di te. Spero davvero che tu riesca a resistere alla tentazione e alla corruzione che di certo incontrerai sul tuo cammino.$B$BBuona fortuna.",
  obj = "Riporta la Cleansed Infernal Orb a Menara Voidrender nelle Barrens.",
  progress = "Come procede la ricerca di Tabetha e del globo, $N?$B$BTabetha si è rivelata più che utile nelle questioni arcane. Sono sicura che ti aiuterà senza problemi, se riesci a trovarla.",
  reward = "Ottimo lavoro, $N. Questo andrà benissimo.$B$BNon ti resta che decidere quale demone vuoi che imprigioni nel globo purificato. Fallo, e avrai un nuovo, magnifico oggetto da impugnare.",
}
T[4981] = {
  title = "Agente Bijou",
  desc = "Mai fidarsi di un goblin. Tutto si riduce a questo, $N.$B$BSi chiama Bijou — uno dei nostri agenti più sfuggenti. Ho scoperto che lavorava per un certo Kibler, un losco venditore di animali esotici delle Burning Steppes, e che in sostanza faceva il doppio gioco con noi. Peggio ancora, usava i fondi dell'Orda per finanziare le sue operazioni.$B$BVoglio che sia riportata qui viva.$B$BL'ultima volta è stata vista entrare a Blackrock Spire. Trovala e riportala indietro.$B$BE $N, non farti incantare dalle sue belle parole.",
  obj = "Vai a Blackrock Spire e scopri cos'è successo a Bijou.",
  reward = "Non ti mentirò, $R. Mi servivano i soldi! Kibler paga molto, molto bene — molto meglio di quanto la K.E.F. potrebbe mai fare.$B$BMa non dubitare della mia lealtà! Perché credi che io sia quaggiù? Per procurare a quel goblin matto delle uova di qualche animale esotico o un'altra scemenza del genere? No, solo qualcuno di veramente suonato verrebbe a Blackrock Spire a raccogliere animaletti. Già, non credo che di gente così ce ne sia molta a questo mondo.$B$B<Bijou ride.>$B$BL'ultima cosa che ci serve è che gente del genere si riproduca.",
}
T[4982] = {
  title = "Beni di Bijou",
  desc = "Di notte, quando questo posto è poco sorvegliato, giro di nascosto per la città, prendendo appunti e segnando tutto quello che vedo e che potrebbe avere un valore strategico per la K.E.F.$B$BIeri notte, però, le cose sono andate malissimo. Sono inciampata in un filo teso e ho fatto scattare un allarme. Ho nascosto la mia attrezzatura da ricognizione e sono corsa al riparo! Purtroppo non posso tornare a prenderla. Hanno raddoppiato e triplicato le pattuglie! Tutte quelle informazioni sono perse.$B$BRecupera le mie cose e tornerò alla K.E.F. senza fare storie.",
  obj = "Trova Bijou's Belongings e riportaglieli. Ricordi che ha detto di averli nascosti al piano più basso della città.",
  progress = "Hai avuto fortuna?",
  reward = "Ce l'hai fatta! Quando Lexlort avrà questi piani, si scorderà di tutte le brutte cose che voleva farmi.$B$B$N, sei $Gil mio eroe:la mia eroina;!",
}
T[4983] = {
  title = "Rapporto di Ricognizione di Bijou",
  desc = "Riporta questo rapporto a Lexlort. Riscatterà il mio buon nome e darà di sicuro alla K.E.F. un vantaggio strategico contro questi orchi.$B$BVenire con te? Ho fin troppo lavoro da fare. Muoviti, questi rapporti gli servono il prima possibile!",
  obj = "Riporta Bijou's Reconnaissance Report a Grandmaster Lexlort a Kargath.",
  progress = "Dov'è la goblin???",
  reward = "Glielo devo riconoscere; è riuscita a sgusciare fuori da un altro brutto pasticcio! Questi rapporti si riveleranno preziosissimi per affrontare gli orchi Blackrock.$B$BNaturalmente, sarai $Gricompensato:ricompensata; per il tuo duro lavoro.",
}
T[4984] = {
  title = "Anche la Fauna Soffre",
  desc = "Da solo potevo fare ben poco per ostacolare il Flagello, eppure sono venuto in queste terre per provare a guarire le ferite inferte alla natura. Gli animali soffrono per la piaga che continua a soffocare queste terre, e non trovano né pietà né pace. Ti chiedo di continuare quello che io qui non sono riuscito a finire.$B$BPer gli animali che soffrono non c'è altra salvezza che una liberazione dolce e pietosa. Cerca i lupi malati qui intorno e abbattili. Ti prego, $N, poni fine alle loro sofferenze — di certo così allevierai anche le mie.",
  obj = "Abbatti 8 Diseased Wolves, poi torna da Mulgris Deepriver a Writhing Haunt, nelle Western Plaguelands.",
  progress = "I lupi infettati dalla piaga vanno abbattuti, $N. La malattia che portano non si può curare. Ci ho provato... ci ho provato finché non ho ceduto anch'io alla piaga.",
  reward = "Io... io sento che le anime dei lupi che hai abbattuto ora hanno pace. Loro — e io — ti ringraziamo per questa liberazione pietosa.$B$BI lupi non sono i soli a soffrire in questo posto maledetto, $N. Ti prego, ho ancora bisogno di te.",
}
T[4985] = {
  title = "Anche la Fauna Soffre",
  desc = "A est di qui, vicino a dove cominciano le Eastern Plaguelands, un tempo vagavano per le campagne grizzly fieri e maestosi. La piaga scatenata dal Flagello ha spezzato anche queste bestie. Vagano per le campagne, straziate dai muscoli che si irrigidiscono e dalla pelliccia e dalla carne che marciscono.$B$BTi chiedo di porre fine anche al loro tormento. L'unica cura per la loro sofferenza è una morte rapida, e dev'essere la tua mano a darla.",
  obj = "Abbatti 8 Diseased Grizzlies, poi torna da Mulgris Deepriver a Writhing Haunt, nelle Western Plaguelands.",
  progress = "Sento i tuoi passi, $N. La vista mi ha abbandonato, ma riesco ancora a percepire ciò che ho intorno. Hai posto fine al tormento dei grizzly divorati dalla malattia?",
  reward = "\"So che i grizzly sono stati abbattuti e che il loro tormento è finito. Ho... ho un'ultima cosa per te. L'ho scritta su... su questo ramo, quando ho sentito che il mio tempo in questo mondo era giunto alla fine.$B$BSì... sono arrivato a quella fine. Grazie ancora, $Gamico:amica;... le creature di questa terra maledetta possono riposare... e ora anch'io.\"$B$BDetto questo, il druido esala un sospiro pesante, seguito da quello che sembra un rantolo di morte. Il suo corpo giace immobile sul pavimento della casetta.",
}
T[4986] = {
  title = "Ramo di Quercia con Glifi",
  desc = "La mano senza vita del druido tauren stringe un ramo di quercia dall'aspetto sorprendentemente sano. A guardarlo bene, nella corteccia sono incisi glifi di natura druidica.$B$BQuando afferri il ramo, ti accorgi che è caldo al tatto, più di quanto dovrebbe. Ti si affaccia alla mente l'immagine dell'albero di Teldrassil — di Darnassus, per la precisione — e hai sulla punta della lingua le parole \"Cenarion Circle\". A quanto pare, il suggerimento su dove portare il ramo è stato messo dentro il ramo stesso.",
  obj = "A giudicare dalla magia racchiusa nel Glyphed Oaken Branch, il druido tauren voleva che il passo successivo fosse la consegna al Cenarion Circle di Darnassus. Cerca uno dei druidi di lì e chiedigli aiuto.",
  progress = "A nome del Cenarion Circle, ti do il benvenuto in questa enclave, $C. Che cosa ti porta da noi?",
  reward = "Questo... questo è davvero strano. Questo druido — un druido tauren, nientemeno — ti ha affidato una gran quantità di informazioni preziose sulla portata della piaga del Flagello. Mi sorprende che un tauren dia informazioni simili a $Gun:una; $R, e di sua spontanea volontà, per giunta, se quello che dici è vero. Ne faremo buon uso, te lo prometto. Forse i tauren non si sono allontanati da Cenarius quanto crede Fandral...$B$BEhm, comunque, ti prego — accetta questo in segno di gratitudine da parte del Cenarion Circle.",
}
T[4987] = {
  title = "Ramo di Quercia con Glifi",
  desc = "La mano senza vita del druido tauren stringe un ramo di quercia dall'aspetto sorprendentemente sano. A guardarlo bene, nella corteccia sono incisi glifi di natura druidica.$B$BQuando afferri il ramo, ti accorgi che è caldo al tatto, più di quanto dovrebbe. Ti si affaccia alla mente l'immagine di Thunder Bluff, a Mulgore — dell'Altura degli Anziani, per la precisione — e hai sulla punta della lingua le parole \"Cenarion Circle\". A quanto pare, il suggerimento su dove portare il ramo è stato messo dentro il ramo stesso.",
  obj = "A giudicare dalla magia racchiusa nel Glyphed Oaken Branch, il druido tauren voleva che il passo successivo fosse la consegna al Cenarion Circle di Thunder Bluff. Cerca uno dei druidi di lì e chiedigli aiuto.",
  progress = "A nome del Cenarion Circle, ti do il benvenuto in questa enclave, $C. Che cosa ti porta da noi?",
  reward = "Viene da Mulgris, dici? Avevamo saputo che voleva prendersi cura delle creature che soffrono nelle Plaguelands, ma questo è del tutto inaspettato... e molto triste. Mulgris è... era un buon amico. Piangerò la sua scomparsa con grande dolore.$B$BI suoi sforzi non sono stati vani, grazie alla tua diligenza. In questo ramo è custodito molto sapere sulla piaga che il Flagello diffonde sulla terra. Lo studieremo con diligenza. Quanto a te, ti prego di accettare questo. È il minimo che possiamo fare per i tuoi nobili sforzi.",
}
T[5001] = {
  title = "Beni di Bijou",
  desc = "Di solito non tratto con $Gun:una; $R, ma a quanto pare sono finita tra il troll e l'incudine. Vedi, la mia missione qui è della massima importanza per l'Orda. Le informazioni che ho scoperto, però, riguardano anche il bene dell'Alleanza. Ora, credimi, non ho nessuna simpatia per l'Alleanza, ma la minaccia dei Blackrock è più grande di una semplice banda di orchi.$B$BTu mi aiuti a ritrovare le mie cose, e io ti aiuto con qualche informazione che potrebbe tornare utile alla tua gente.$B$BAffare fatto?",
  obj = "Trova Bijou's Belongings e riportaglieli. Buona fortuna!",
  progress = "Hai avuto fortuna?",
  reward = "Ma guarda un po'! Dov'erano??",
}
T[5002] = {
  title = "Messaggio per Maxwell",
  desc = "Sono una goblin di parola, $R. Ora ascolta bene:$B$BQuesti orchi vengono usati soprattutto come bestie da soma e carne da cannone per il dragonflight nero!$B$BIl loro vero capo è nientemeno che Nefarian, progenie di Deathwing. Ho anche scoperto dove si trovano i sottoposti di Nefarian in questa parte della cittadella.$B$BPorta questa mappa al Maresciallo Maxwell nelle Burning Steppes. Ci sono segnate le posizioni di questi mostri, così è facile individuarli.",
  obj = "Vai nelle Burning Steppes e consegna Bijou's Information a Marshal Maxwell.",
  progress = "Ah, $N. È passato molto tempo.",
  reward = "Coincide con gran parte di quello che già sapevamo. In ogni caso, sono informazioni interessanti e piuttosto spiacevoli.$B$BI segni su questa mappa si riveleranno preziosi per ridurre la minaccia dei Blackrock.",
}
T[5021] = {
  title = "Meglio Tardi che Mai",
  desc = "\"Il pacco va consegnato... consegnato prima che io resti intrappolata qui!\"$B$BLe grida di una donna in preda al panico sembrano quasi un sussurro che aleggia per la casa. Rannicchiata nell'angolo al piano di sopra c'è l'apparizione di una donna. Non sembra del tutto consapevole di ciò che la circonda, e si accorge appena di te.$B$B\"Sei qui per consegnare il mio pacco? Ti prego, prima che le cose peggiorino ancora! Stavo per andarmene di qui a cavallo. Dovrebbe essere ancora vicino al mio cavallo... o ormai ho fatto tardi?\"",
  obj = "Dai vaneggiamenti della donna spettrale si capisce che aveva bisogno di far consegnare un pacco. Diceva che si trovava dov'era il suo cavallo. Quanto a dove sia il cavallo o a dove andasse consegnato il pacco — il fantasma resta incomprensibile.",
  reward = "Nel fienile, un pacco che altrimenti forse non avresti notato ora spicca in mezzo al degrado e alla rovina. Forse è quello per cui il fantasma di Janice Felstone strepitava tanto...",
}
T[5022] = {
  title = "Meglio Tardi che Mai",
  desc = "Raccogli il pacco e lo ripulisci dal velo di polvere e sudiciume che vi si era posato sopra. L'indirizzo, scritto con mano frettolosa, è quello di una certa Emma Felstone di Stormwind; la data di consegna risale a ben più di quattro anni fa.$B$BNon si sa nemmeno se Emma Felstone sia ancora viva, ma è risaputo che il Municipio di Stormwind tiene i registri della popolazione della città. Se ne occupano i Fattori Reali del Censimento di Stormwind.",
  obj = "Chiedi ai Royal Factors di Stormwind dove si trova una certa Emma Felstone. Di solito c'è un funzionario del censimento a City Hall.",
  progress = "$GBenvenuto:Benvenuta; all'ufficio del censimento di Stormwind. Se ti servono informazioni sulla nostra popolazione, posso aiutarti io.",
  reward = "Un pacco per una certa Emma Felstone, dici? Ultimo indirizzo conosciuto Stormwind, quattro anni fa? Bene, vediamo un po'...$B$BStando a quello che ci risulta, circa quattro anni fa in città c'era un'Emma Felstone. Anzi, dovrei dire forse — il censimento che sto consultando è di cinque anni fa, e non mi risulta che abbia lasciato la città. Questo però non vuol dire che sia ancora qui.$B$BAspetta un secondo... questo pacco non sarà mica per Ol' Emma, vero?",
}
T[5023] = {
  title = "Meglio Tardi che Mai",
  desc = "Raccogli il pacco e lo ripulisci dal velo di polvere e sudiciume che vi si era posato sopra. L'indirizzo, scritto con mano frettolosa, è quello di un certo Jeremiah Felstone di Lordaeron; la data di consegna risale a ben più di quattro anni fa.$B$BNon si sa nemmeno se Jeremiah Felstone sia ancora vivo, ma è risaputo che Undercity, un tempo nota come Lordaeron, tiene i registri della popolazione della città. Se ne occupano i Sovrintendenti Reali del Censimento di Undercity.",
  obj = "Chiedi ai Royal Overseers di Undercity dove si trova un certo Jeremiah Felstone. Di solito c'è un funzionario del censimento vicino alla registrazione delle gilde e delle insegne.",
  progress = "Sei qui per chiedere l'assistenza del censimento di Undercity, o solo per chiedermi se qualcuno che conoscevi è morto? Me lo chiedono spesso.",
  reward = "Un pacco per un certo Jeremiah Felstone, con ultimo indirizzo conosciuto Lordaeron... Dovrei poterti aiutare.$B$BJeremiah Felstone era in città prima della piaga. Anzi, dovrei dire l'ex Jeremiah Felstone — alcuni Reietti hanno cambiato cognome per lasciarsi alle spalle ciò che erano un tempo. Questo caso non fa eccezione; l'ex Jeremiah Felstone oggi si fa chiamare Jeremiah Payson.$B$BAspetta un attimo... ma non è il venditore di scarafaggi?",
}
T[5047] = {
  title = "Finkle Einhorn, al Tuo Servizio!",
  desc = "Troverai Malyfous Darkhammer a Everlook, $C. Digli che 'Finkle sta benone' e che la tuta funziona a meraviglia.$B$BPoi dagli questo:$B$B<Finkle ti porge un pezzo di carne luminescente.>$B$BL'ho strappato dalle viscere della bestia durante la mia 'vacanza'.$B$BScommetto che Malyfous saprà dirti con una certa precisione cosa può fare con i pezzi di un mostro del genere!$B$BAh, immagino che tu non sappia dov'è Everlook, vero? Destinazione Winterspring, $Gamico:signora;!",
  obj = "Parla con Malyfous Darkhammer a Everlook.",
  progress = "Sì?",
  reward = "Vivo? La tuta ha funzionato? E qui cos'abbiamo?",
}
T[5048] = {
  title = "La Buona Emma",
  desc = "È un po' scorbutica, e forse le manca qualche rotella... ma dai registri risulta che Ol' Emma corrisponde davvero al profilo di Emma Felstone.$B$BForse hai visto Ol' Emma girare per la città: parla da sola, e il più delle volte farfuglia cose senza senso. Comunque non fa male a niente e a nessuno, quindi la gente la lascia in pace.$B$BTutto considerato, direi che Ol' Emma è proprio Emma Felstone. Potresti provare a chiederle se il suo cognome è davvero Felstone.",
  obj = "Trova Ol' Emma a Stormwind e scopri se è davvero Emma Felstone. Se lo è, forse le farebbe piacere il pacco che Janice Felstone ha preparato per lei.",
  progress = "Ti direi di levarti dal mio prato, ma come vedi non ce l'ho.",
  reward = "Mi chiamo proprio Emma Felstone: sei la prima persona da anni a chiamarmi così. Chi... chi sei?$B$BDici che conoscevi... mia sorella?! È ancora viva? Ma chi voglio prendere in giro, certo che no. Quando è scoppiata la piaga a Lordaeron, mi ero rassegnata al peggio. Tanti della mia famiglia sono morti... o peggio. Ed eccomi qui, la pazza Ol' Emma, tutta sola. Che cosa sei, $Gun tombarolo:una tombarola; o qualcosa del genere? Cerchi il tuo prossimo bersaglio?$B$BCosa... hai un pacco per me da parte di mia sorella?",
  en_title = "Good Natured Emma",
  en_obj = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.",
}
T[5049] = {
  title = "Il Blues di Jeremiah",
  desc = "Dagli indizi che riesco a mettere insieme, la persona che cerchi — nonché il destinatario del pacco — è Jeremiah Payson, il venditore di scarafaggi di Undercity.$B$BSono sempre stato dell'idea che ci voglia un dono speciale per vendere... scarafaggi. Senza dubbio il tuo è ormai un viaggio davvero epico, possente $C. Ti lascio alle tue imprese che plasmano il mondo. Permettimi, però, di prendere parte al tuo magnum opus e di rivelarti che si trova vicino alla banca, dove striscia, come gli si addice, sotto una delle passerelle.",
  obj = "Trova Jeremiah Payson a Undercity e scopri se è davvero Jeremiah Felstone. Se lo è, forse gli farà piacere avere il pacco che Janice Felstone ha preparato per lui.",
  progress = "Ogni volta che qualcuno calpesta uno scarafaggio, io piango. Ti prego, non farmi piangere.",
  reward = "Non uso quel nome da anni... ma sì, a un certo punto della mia vita — prima di questa gloriosa non-vita — quello era il mio cognome.$B$BSostieni di aver conosciuto mia sorella... o meglio, di aver parlato da poco con mia sorella.$B$BChe è morta.$B$BDa quattro anni.$B$BSai, se non avessi le ossa già così fragili, sarei tentato di prenderti a calci nel posteriore fino a spezzarmi il piede. Sei proprio un avvoltoio, eh?$B$BCosa... hai un pacco per me da parte di mia sorella?",
}
T[5050] = {
  title = "Talismano Portafortuna",
  desc = "A quanto pare mi sbagliavo sul tuo conto, $N, e per questo ti devo delle scuse. Mia sorella mi ha mandato diversi effetti personali, compreso, ironia della sorte, l'atto di proprietà della fattoria dei Felstone. Per adesso credo che non andrò a reclamarla.$B$BSe lo spirito di mia sorella è ancora legato alla fattoria e non trova pace, ti prego... potresti riportarle questo? È la metà di un talismano portafortuna che aveva lei, mentre l'altra metà ce l'aveva suo marito.$B$BForse sapere che queste cose le ho io darà finalmente pace alla sua anima.",
  obj = "Riporta a Janice Felstone, nelle Western Plaguelands, il suo Good Luck Half-Charm.",
  progress = "John, tesoro... sei tu? All'improvviso ho tanto freddo...",
  reward = "Restituisci il mezzo talismano all'apparizione. Lei lo guarda, poi guarda te, in attesa.$B$B\"Amore, dove hai messo la tua metà del talismano? Non possiamo stare insieme se non abbiamo tutte e due le metà. Amore... riesci a vedermi?\"",
}
T[5051] = {
  title = "Due Metà Diventano una",
  desc = "I vaneggiamenti del povero fantasma continuano:$B$B\"Ho tanto freddo, John. Portami il tuo talismano e staremo insieme! Presto, John, prima che arrivi la piaga a trasformarci in bestie orrende! Non riesco a vederti, John... ma so che sei vicino. Ti sento vicino a me.\"$B$BForse, se si trovasse la seconda metà del talismano e lo si ricomponesse, sarebbe proprio questo ciò che lo spirito di Janice Felstone sta cercando.",
  obj = "Trova l'altra metà del Good Luck Charm da qualche parte nella Fattoria dei Felstone, nelle Western Plaguelands, e ricomponilo.$B$BDai il Good Luck Charm a Janice Felstone nella Fattoria dei Felstone, nelle Western Plaguelands.",
  progress = "John, non farti prendere dai ghoul... non lasciare che i ghoul prendano me... brutti ghoul... il nostro talismano ci terrà al sicuro.",
  reward = "Porgi il talismano portafortuna ricomposto al fantasma di Janice Felstone. Appena lo stringe, noti in lei un cambiamento quasi immediato. La sua forma eterea tremola, e lei ti guarda con occhi limpidi ma tristi.$B$B\"Mi hai liberata... questo talismano non mi servirà più. Ti prego, prendilo, e forse darà anche a te il conforto che ha dato a me.\"",
}
T[5052] = {
  title = "I Frammenti di Sangue di Agamaggan",
  desc = "Insieme alle spine, il sangue ha toccato <grugnito> altre parti della terra: pietre rosso sangue mescolate agli altri minerali. I Bristleback dissotterrano questi frammenti e li portano come totem <grugnito> per avere forza in battaglia e come totem per le loro magie. <grugnito>$B$BIo conosco i segreti di quella magia.$B$BPorta a Mangletooth uno di questi frammenti di sangue per dimostrare che hai capito. Portane molti a Mangletooth, e ti benedirà con la magia quilboar — la magia di Agamaggan! <grugnito>",
  obj = "Porta un Blood Shard a Mangletooth, a Camp Taurajo, nelle Barrens.$B$BRaccogli altri Blood Shard se vuoi che ti benedica con il potere di Agamaggan.",
  progress = "Le nostre tribù si radunano nelle zone spinose di tutte le Barrens <grugnito> perché sono luoghi sacri, ma nessuno è sacro quanto il Razorfen. Il corpo di Agamaggan forma per intero il Razorfen, <grugnito> ma le Downs sono protette in modo particolare, perché l'ingresso è fatto delle sue grandi fauci! <grugnito> Inghiottirà interi quelli che non gli sono fedeli, e sputerà fuori i loro corpi dopo averli masticati! <grugnito>$B$BAgamaggan ci ha lasciato il suo corpo per proteggerci, e ci dona un po' del suo spirito perché possiamo proteggere lui. <grugnito>",
  reward = "Ah, hai capito davvero. <grugnito> Le mie parole non sono cadute nel vuoto, $R. Mangletooth sarà anche in gabbia, ma nessuna gabbia può fermare il potere di Agamaggan! <grugnito>$B$BIl contatto del frammento, la sensazione che dà... è passato tanto tempo, $R.$B$BSai cosa si prova? Sentirsi strappare via il proprio potere?$B$BMa questa è una storia per un'altra volta. Ti ho promesso informazioni. Ti ho promesso il potere di Agamaggan. La mia gente ha voltato le spalle a Mangletooth. Ora ti scateno contro di loro. <grugnito>",
  en_title = "Blood Shards of Agamaggan",
  en_obj = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.$B$BCollect more Blood Shards if you want him to bless you with Agamaggan's power.",
}
T[5054] = {
  title = "Ursius degli Shardtooth",
  desc = "Tra le montagne innevate di Winterspring, a nord-ovest, un abile cacciatore bracca la sua preda... Parlo di Ursius degli orsi shardtooth, una bestia agile e astuta.$B$BOra mando te contro di lui. Si aggira tra le colline digradanti a nord-ovest di Everlook. Trovalo e dagli la caccia, prima che scopra le tue intenzioni.$B$BTutti quelli che hanno affrontato Ursius si sono ritrovati ben presto a essere la preda, e lui il cacciatore. Resta in guardia.",
  obj = "Storm Shadowhoof di Everlook, a Winterspring, vuole che tu uccida Ursius.",
  progress = "Ora va', $C. Trova Ursius.",
  reward = "Non era un compito facile, eppure l'hai svolto in modo eccellente. Ma non credere troppo in fretta di avermi impressionato, $N.",
}
T[5055] = {
  title = "Brumeran dei Chillwind",
  desc = "Rapida e astuta, Brumeran plana silenziosa sul paesaggio innevato del sud di Winterspring. Ma non lasciare che il suo aspetto aggraziato ti convinca che sia innocua. Tutti quelli che le si mettono contro la pagano cara, e spesso con la propria vita.$B$BCerca Brumeran dei chillwind tra le chimere. Sconfiggila, poi torna di nuovo da me.",
  obj = "Storm Shadowhoof di Everlook, a Winterspring, vuole che tu uccida Brumeran.",
  progress = "Brumeran ti chiama, $N.",
  reward = "Sì. Sei $Gtornato:tornata;. Ora credo che tu sia $Gun vero cacciatore:una vera cacciatrice; per natura. Hai affrontato la più feroce delle creature e sei $Gtornato:tornata;, superando le mie aspettative.$B$BOra sei $Gpronto:pronta; per la mia ultima richiesta.",
}
T[5056] = {
  title = "Shy-Rotam",
  desc = "Nel nord di Winterspring, i grandi felini si radunano intorno a un grande punto di riferimento chiamato Roccia delle Frostsaber. La loro guida è nota con il nome di Shy-Rotam. Sconfiggere la matriarca delle frostsaber ti varrebbe grande rispetto agli occhi di ogni $Galtro:altra; $R.$B$BTorna in quelle aspre terre selvagge e, una volta lì, procurati la carne sacra delle frostsaber. Trova la pietra di Shy-Rotam e deponi lì la carne. Mettere davanti a lei la carne dei suoi simili evocherà Shy-Rotam, in collera.$B$BPreparati alla sua furia, e sconfiggila.",
  obj = "Storm Shadowhoof a Everlook, a Winterspring, vuole che tu sconfigga Shy-Rotam.",
  progress = "Shy-Rotam è audace e non perdona; difenderà i suoi simili con fervido slancio.",
  reward = "Hai dimostrato sia la tua forza sia la tua determinazione. Ti attendono molte altre sfide, ma io ti ho già mostrato tutto ciò che potevo.",
}
T[5057] = {
  title = "Imprese Passate",
  desc = "Prima che tu mi parlassi, $N, avevo sentito delle tue imprese... che avevi un desiderio incrollabile di dimostrare il tuo valore, che avevi doti eccezionali come $C, e ora so che è tutto vero.$B$BChi eccelle come te merita un riconoscimento. Porta questo contrassegno a un mio amico di Thunder Bluff, Melor Stonehoof. Sono certo che si ricorderà di te, e di ciò che hai compiuto tanto tempo fa. Parlagli delle tue vittorie recenti, e non dimenticare mai ciò che hai compiuto oggi.",
  obj = "Porta Storm Shadowhoof's Marker a Melor Stonehoof a Thunder Bluff.",
  reward = "Impariamo dalle esperienze della vita, $N. Sono sicuro che le tue ti hanno solo reso più forte e più $Gsaggio:saggia;. Sei $Gcresciuto:cresciuta; molto da quando ci siamo parlati la prima volta.$B$BPrendi questo in ricordo dei compiti difficili che hai portato a termine come $C $R, e sappi che avrai sempre il mio rispetto e la mia ammirazione.",
}
T[5058] = {
  title = "Il Diario della Signora Dalson",
  reward = "Un diario dalle pagine ingiallite è aperto sull'ultima annotazione:$B$B\"Non so cosa succederà adesso che Harold si è trasformato. Ho dato fondo a tutte le mie forze per trascinarlo nell'unico posto che ho trovato dove chiuderlo per bene e tenerlo dentro. La chiave l'ho nascosta addosso a me, e prego che funzioni...$B$BSpero di riuscire ad andarmene da qui, ma per farlo mi servono soldi. La nostra roba è tutta nell'armadio, credo... e adesso che ci penso, la chiave non la tiene addosso Harold?$B$BCi dormo sopra, adesso sono stanca morta.\"",
}
T[5059] = {
  title = "Sotto Chiave",
  progress = "La porta della latrina ha cominciato a scheggiarsi lungo i bordi del telaio, come se qualcuno avesse tentato senza sosta, più e più volte, di forzarla. Al momento è chiusa a chiave per bene dall'esterno della latrina.$B$BQuando scuoti la porta, senti un gemito gutturale provenire dall'interno! Qualunque cosa ci sia lì dentro, di certo non sembra amichevole.",
  reward = "Con la chiave trovata sullo scheletro di quella che fu la Signora Dalson, apri la porta della latrina. Ne salta fuori un ghoul assetato di sangue, rimasto intrappolato lì dentro per chissà quanto tempo.$B$BDall'urlo agghiacciante che il ghoul lancia alla tua vista è chiaro che per quello che fu il Contadino Dalson non c'è più salvezza.",
}
T[5060] = {
  title = "Sotto Chiave",
  progress = "Davanti a te c'è un armadio robustissimo, chiuso saldamente da una serratura incorporata. Il davanti dell'armadio è pieno di graffi e segni profondi. Si può supporre che siano il risultato di numerosi e violenti tentativi falliti di svelare i segreti che l'armadio, al momento, nasconde alla vista.$B$BSe vuoi aprire questo armadio, dovrai trovare la chiave.",
  reward = "La chiave presa dalle spoglie di ghoul del Contadino Dalson entra alla perfezione nella serratura. Le ante dell'armadio si spalancano e rivelano diversi oggetti ancora intatti e dall'aria piuttosto preziosa.",
}
T[5061] = {
  title = "Aquatic Form",
  desc = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Mathrengyl Bearwalker, a Darnassus. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.$B$BArrivederci, giovane $Gdruido:druida;. Parleremo ancora.",
  obj = "Torna a Darnassus e mostra il Pendant of the Sea Lion a Mathrengyl Bearwalker.",
  progress = "La notizia del tuo ritorno a Darnassus ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua forma acquatica.$B$BHai il Pendente del Leone Marino?",
  reward = "Davvero notevole, $N. Sei $Gpronto:pronta; a imparare la tua forma acquatica, ed è un piacere per me insegnartela.$B$BInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.",
}
T[5062] = {
  title = "Il Fuoco Sacro",
  desc = "Arikara è una creatura letale di cui bisogna occuparsi in fretta. Per darle la caccia dovrai accendere il fuoco sacro della vita — sarà questo a evocare Arikara.$B$BVa' subito a raccogliere la rara agave Incendia. Quando ne avrai raccolta abbastanza, chiedi consiglio a Magatha Grimtotem, sull'Altura degli Anziani a Thunder Bluff. È una sciamana potente e può incantare l'agave per ricavarne una polvere che accenda il fuoco.$B$BVa' a nord-est fino alla Pozza Ribollente e raccogli l'Agave Incendia.",
  obj = "Raccogli 10 fasci di Incendia Agave, poi consulta Magatha Grimtotem a Elder Rise, a Thunder Bluff.",
  progress = "Dunque Motega Firemane mi fa sapere di Arikara... be', questa sì che è una cosa grave.$B$B<Magatha si guarda intorno.>$B$BArikara è una creatura letale, nata solo per vendicarsi di chi ha commesso atti atroci.$B$B<Magatha sorride.>",
  reward = "Bene, hai raccolto la quantità necessaria di agave Incendia. Quest'erba rara, che si trova solo a Thousand Needles, aiuterà ad accendere il fuoco sacro della vita, ormai sopito.$B$B<Magatha comincia a incantare l'agave Incendia.>",
  en_title = "Sacred Fire",
  en_obj = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
}
T[5064] = {
  title = "Spiare i Grimtotem",
  desc = "$N, in passato ci hai servito bene, e per questo ora ti affido una missione importante. Il Grimtotem Clan sta tramando qualcosa in segreto. Nelle ultime settimane tre agenti di origine ignota sono stati visti far visita ai Grimtotem. Abbiamo scoperto che questi messaggi, ben custoditi, si trovano in casse separate nel Pinnacolo di Darkcloud.$B$B$N, se riuscirai in questa missione pericolosa, ti ricompenserò come meriti.",
  obj = "Trova e recupera le tre Secret Note nel Pinnacolo di Darkcloud",
  progress = "Hai scoperto cosa stanno tramando i Grimtotem?",
  reward = "Grande Totem dello Spirito! Sono notizie davvero gravi. Devo cominciare a prepararmi a qualunque cosa accada.$B$B$N, come promesso, ecco la ricompensa per il coraggio con cui ci hai servito.",
  en_title = "Grimtotem Spying",
  en_obj = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.",
}
T[5065] = {
  title = "Le Tavolette Perdute di Mosh'aru",
  desc = "Il troll con cui hai parlato non ha detto la verità. Le due tavolette che gli hai procurato parlavano di come contenere l'essenza di Hakkar, ma la leggenda non finisce lì. Ho studiato a lungo e ho scoperto che le Tavolette di Mosh'aru sono sei, non due! Sei!$B$BE temo che i segreti custoditi dalle altre non ci piaceranno...$B$BTrova la terza e la quarta tavoletta di Mosh'aru. Sono nelle Eastern Plaguelands, in mano ai troll mossflayer. Trovale e portamele.",
  obj = "Porta la Third Mosh'aru Tablet e la Fourth Mosh'aru Tablet a Prospector Ironboot, a Tanaris.",
  progress = "Hai le tavolette? Temo che i loro testi riveleranno una grave minaccia per il nostro mondo.",
  reward = "Le hai trovate! Ottimo!$B$BGrazie, $N. Studierò a fondo questi testi e ne decifrerò il significato.$B$BTu, però, hai un altro compito...",
}
T[5066] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!$B$BIl Regno di Stormwind ha lanciato una chiamata alle armi! Tutti coloro che sono in grado di combattere sono invitati a prendere le armi contro l'oscura minaccia del Flagello nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!$B$BEroi del reame — cercate il Comandante Ashlam Valorfist, che ha allestito il suo accampamento a Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo accampamento si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che con te il richiamo del dovere e del servizio al bene comune non è caduto nel vuoto!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è tanto da fare per gli eroi volenterosi e capaci.",
  en_title = "A Call to Arms: The Plaguelands!",
  en_obj = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
}
T[5081] = {
  title = "La Missione di Maxwell",
  desc = "Queste informazioni colmano le lacune dei nostri rapporti su Blackrock Spire, per il resto impeccabili.$B$BL'attacco dev'essere risolutivo, $N.$B$BPer primo va annientato il loro maestro di guerra, il troll Voone. Senza i suoi piani di battaglia, gli orchi Blackrock piomberanno nel caos.$B$BPoi dovrai togliere di mezzo il Gran Signore degli ogre, Omokk. Senza la sua guida, i vili ogre di Blackrock sono impotenti.$B$BInfine, il signore supremo della cittadella: Wyrmthalak. Morto Wyrmthalak, la loro unità di comando centrale resta senza un tramite.",
  obj = "Vai a Blackrock Spire e annienta War Master Voone, Highlord Omokk e Overlord Wyrmthalak. A lavoro finito, torna da Marshal Maxwell.",
  progress = "Situazione?",
  reward = "Ottimo lavoro, $N. Se non altro ci hai fatto guadagnare altro tempo — tempo prezioso, preziosissimo.",
}
T[5082] = {
  title = "La Minaccia dei Winterfall",
  desc = "Sono venuta a Winterspring per studiare le Sorgenti Termali di Frostfire. Ho notato che l'acqua sembra avere ...strane proprietà. Non sono ancora riuscita a scoprirne l'origine e, a dire la verità, ultimamente ho avuto qualche difficoltà per via dei mezzorsi Winterfall.$B$BSembrano attratti dalle sorgenti, proprio come me. Sono diventati gelosissimi di quell'acqua, e non mi lasciano avvicinare alle due sorgenti più grandi a nord di qui.$B$BVorrei continuare i miei studi, perciò non mi daresti una mano?",
  obj = "Donova Snowden, a Winterspring, vuole che tu uccida 8 Winterfall Pathfinders, 8 Winterfall Den Watchers e 8 Winterfall Totemics.",
  progress = "Ti sono grata per l'aiuto!",
  reward = "Grazie mille, $N! Ora posso rimettermi al lavoro qui.$B$BHai trovato qualcosa di interessante all'accampamento dei Winterfall?",
}
T[5083] = {
  title = "L'Acqua di Fuoco dei Winterfall",
  desc = "Questa fiala che hai preso ai mezzorsi Winterfall è vuota, ma all'interno noti qualche goccia di uno strano liquido verde; sembra quasi brillare.$B$BSarà qualcosa di importante?$B$BProbabilmente Donova Snowden saprebbe dirti di più, visto che è accampata da tempo vicino alle sorgenti termali di Winterspring.",
  obj = "Porta l'Empty Firewater Flask a Donova Snowden a Winterspring.",
  progress = "Cos'è che hai trovato?",
  reward = "Questa l'hai presa ai Winterfall?",
}
T[5084] = {
  title = "Cedere alla Corruzione",
  desc = "Questo liquido verdastro... mi ricorda un po' la melma che ho visto attraversando Felwood. E ho visto dei Messaggeri Winterfall entrare a Timbermaw... Forse queste cose c'entrano con la fiala che hai trovato, $N.$B$BAppena oltre Timbermaw Hold, a Felwood, c'è un folto gruppo di mezzorsi. Si chiamano tribù Deadwood, e sono stati corrotti e fatti impazzire dalla vilenergia. Perché non dai un'occhiata da quelle parti, per vedere se trovi qualche prova di rapporti tra i Winterfall e i Deadwood?",
  obj = "Cerca un indizio nell'accampamento dei mezzorsi Deadwood, nella parte settentrionale di Felwood.",
  reward = "Dentro il calderone ribolle una sostanza putrida, dall'odore ripugnante...",
}
T[5085] = {
  title = "Poltiglia Misteriosa",
  desc = "La sostanza verdastra nel calderone sembra simile a quella che hai trovato nella fiala. Questa strana roba appiccicosa potrebbe essere corrotta quanto i mezzorsi che l'hanno creata...$B$BSe i mezzorsi Winterfall la stanno usando, vuol dire che presto saranno corrotti quanto la tribù Deadwood?$B$BLa cosa migliore è tornare da Donova a riferirle quello che hai scoperto, portandole anche un campione del liquido del calderone.",
  obj = "Torna da Donova Snowden a riferire quello che hai scoperto.",
  progress = "Spero che tu abbia trovato qualcosa, $N. I Winterfall stanno diventando sempre più aggressivi!",
  reward = "Sei $Gpieno:piena; di risorse, $N. Pensi che i mezzorsi Winterfall siano stati all'accampamento dei Deadwood?",
}
T[5086] = {
  title = "Orrori Tossici",
  desc = "Ho studiato il campione che hai riportato e, anche se non posso dirlo con certezza, credo che contenga tracce di elementi tossici. L'unico modo per esserne sicuri, però, è raccoglierne un po' per fare un confronto.$B$BCredo che i mezzorsi Deadwood ricavino questi elementi da altre creature corrotte di Felwood; in particolare dagli elementali che vivono nei Boschi di Irontree, chiamati orrori tossici.$B$BRaccogli qualche campione da farmi confrontare, ma fai attenzione — laggiù è molto pericoloso!",
  obj = "Raccogli 3 Toxic Horror Droplets per Donova Snowden a Winterspring.",
  progress = "Credo che stiamo cominciando a scoprire cosa sta succedendo qui, $N.",
  reward = "Devo confrontarlo con la sostanza che hai trovato nel calderone, e a quel punto sono sicura che ne sapremo di più.",
}
T[5087] = {
  title = "Messaggeri Winterfall",
  desc = "Molto interessante, $N...$B$BQuando questa sostanza tossica viene mescolata con l'acqua delle sorgenti termali, perde la sua tossicità e conserva solo la capacità di agire per un po' su chi la ingerisce. Dev'essere per questo che i Winterfall proteggono le sorgenti termali con tanto fervore — ne hanno bisogno per purificare la loro acqua di fuoco.$B$BDobbiamo mettere fine a tutto questo — troncare i contatti tra i Winterfall e i Deadwood. Un gruppo di messaggeri percorre a piedi la strada tra il loro villaggio e Felwood. Trovali, sconfiggili e ruba il loro carico.",
  obj = "Trova i Winterfall Runners e impedisci loro di consegnare il carico a Winterfall Village.",
  progress = "Vedremo cosa succede quando i Winterfall resteranno senza la loro acqua di fuoco!",
  reward = "<Donova esamina il contenuto della cassa.>$B$BMi chiedo se consumare questa sostanza renda i mezzorsi più aggressivi. Di certo sembrano molto più grossi...",
}
T[5088] = {
  title = "Arikara",
  desc = "Porta questa polvere di Incendia raffinata e purificata a Thousand Needles e gettala sul fuoco sacro della vita. Si trova nel Pinnacolo di Darkcloud, su una guglia isolata dove seppelliscono i loro morti.$B$BL'incantesimo che ho intessuto nella polvere di Incendia evocherà Arikara davanti a te, $N.$B$BTemo che stia dando la caccia a Cairne Bloodhoof; troppe tradizioni Tauren sono cambiate, e temo che questo abbia fatto infuriare Arikara. Muoviti in fretta, prima che tutto sia perduto, $C!",
  obj = "Uccidi Arikara. Porta i suoi resti e l'Incendia Powder a Motega Firemane, all'Accampamento di Whitereach, come prova di quel che hai fatto.",
  progress = "Hai ucciso Arikara, quel serpente feroce, $N?",
  reward = "Non ha senso. Perché Arikara dovrebbe dare la caccia a Cairne Bloodhoof? Magatha non può sbagliarsi, è la nostra sciamana più potente.$B$B<Motega scuote la testa.>$B$BIn ogni caso la tua grande impresa per l'Orda non passerà inosservata — ti prego, scegli una di queste cose come ricompensa per il tuo aiuto.",
  en_title = "Arikara",
  en_obj = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",
}
T[5089] = {
  title = "Comando del Generale Drakkisath",
  desc = "Sul cadavere del serpente sconfitto scopri quello che sembra un biglietto di una certa importanza: una lettera del suo superiore, il Generale Drakkisath, in materia di protocollo.$B$BL'istinto ti dice che dovresti portarla al Maresciallo Maxwell.",
  obj = "Porta General Drakkisath's Command a Marshal Maxwell, nelle Burning Steppes.",
  progress = "Cos'hai lì, $N?",
  reward = "La faccenda si complica...",
}
T[5090] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!$B$BIl Regno di Stormwind ha lanciato una chiamata alle armi! Tutti coloro che sono in grado di combattere sono invitati a prendere le armi contro l'oscura minaccia del Flagello nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!$B$BEroi del reame — cercate il Comandante Ashlam Valorfist, che ha allestito il suo accampamento a Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo accampamento si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. Questa è una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia del Flagello che incombe a nord e a nord-est. Sono lieto di sapere che con te lo squillante richiamo del dovere e del servizio al bene superiore non è rimasto inascoltato!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto da fare per gli eroi volenterosi e capaci.",
}
T[5091] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!$B$BIl Regno di Stormwind ha lanciato una chiamata alle armi! Tutti coloro che sono in grado di combattere sono invitati a prendere le armi contro l'oscura minaccia del Flagello nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!$B$BEroi del reame — cercate il Comandante Ashlam Valorfist, che ha allestito il suo accampamento a Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo accampamento si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. Questa è una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia del Flagello che incombe a nord e a nord-est. Sono lieto di sapere che con te lo squillante richiamo del dovere e del servizio al bene superiore non è rimasto inascoltato!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto da fare per gli eroi volenterosi e capaci.",
}
T[5092] = {
  title = "Sgombrare la Strada",
  desc = "Le strade che entrano ad Andorhal da ovest e da nord sono ben fortificate, perciò intendo colpire la città dalla strada orientale, meno difesa. Come prima linea di difesa il Flagello conta sul cuscinetto di non morti che infesta la Collina del Cordoglio. Se vogliamo avanzare su Andorhal, dovremo passare dalla Collina del Cordoglio.$B$BIl tuo primo incarico sarà sgombrare la strada attraverso la Collina del Cordoglio. Sfoltisci gli scheletri e i ghoul che infestano la zona; a lavoro finito, torna a fare rapporto!",
  obj = "Uccidi 10 Skeletal Flayers e 10 Slavering Ghouls a Sorrow Hill.$B$BTorna da Commander Ashlam Valorfist a Chillwind Camp, nelle Western Plaguelands.",
  progress = "Voglio che ti prepari al peggio, $N — tira fuori tutto quello che hai. Il compito che ci aspetta non sarà facile. Mentre qui raduniamo le forze per arrivare a colpire il Flagello, tu farai parte dell'avanguardia che gli porta la battaglia in casa! La missione che ti è stata assegnata alla Collina del Cordoglio aprirà il nostro cammino verso la vittoria!",
  reward = "Missione compiuta, $N! Ben fatto, ben fatto.$B$BPermettimi di ricompensare il lavoro che hai svolto finora con un po' di denaro dalle casse di Stormwind. Ti consiglio di spenderlo in equipaggiamento che ti sia utile nella prossima missione... una missione che ti porterà fin dentro le rovine di Andorhal.$B$BTieniti $Gpronto:pronta;! Resta vigile!",
}
T[5093] = {
  title = "Chiamata alle Armi: Le Plaguelands!",
  desc = "Eroi del regno, ascoltatemi — l'Orda vi chiama ad agire in fretta!$B$BÈ stata lanciata una chiamata alle armi perché tutti gli individui abili impugnino le armi contro il Flagello! Corrono voci di nuove minacce che sorgono dalle rovine degli Eastern Kingdoms. Incombono a est di Undercity, nelle propaggini settentrionali delle terre oggi note come Plaguelands!$B$BEroi del regno — cercate il Gran Esecutore Derrington, che ha stabilito il suo campo base al Baluardo, a est di Tirisfal Glades!",
  obj = "Cerca High Executor Derrington. Il suo campo base si trova al Bulwark, a est di Tirisfal Glades e di Undercity.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. Questa è una delle frontiere più pericolose di Azeroth, con la minaccia del Flagello che incombe a est, e poi ancora più a est di lì. Mi fa piacere sapere che con te il richiamo del dovere e del servizio all'Orda non è caduto nel vuoto!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è molto da fare per eroi volenterosi e capaci.",
}
