T[5929] = {
  title = "Great Bear Spirit",
  desc = "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato un maestro e una guida verso la prima vera comprensione della natura dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.$B$BVa' ora dal Great Bear Spirit e impara ciò che ha da insegnare. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.",
  obj = "Cerca il Great Bear Spirit nella parte nord-occidentale di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Una volta finito, torna da Dendrite Starblaze a Nighthaven, in Moonglade.",
  progress = "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può continuare senza la sua benedizione.",
  reward = "Mentre ti avvicini, Dendrite fa un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e sul suo viso compare un sorriso appena accennato.$B$B\"Sento in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e con intenzione consapevole, anche se questa intenzione non è ancora concentrata. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso in ciò che farai.\"",
  en_title = "Great Bear Spirit",
  en_obj = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
}
T[5930] = {
  title = "Great Bear Spirit",
  desc = "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato un maestro e una guida verso la prima vera comprensione della natura dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.$B$BVa' ora dal Great Bear Spirit e impara ciò che ha da insegnare. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.",
  obj = "Cerca il Great Bear Spirit nella parte nord-occidentale di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Una volta finito, torna da Dendrite Starblaze a Nighthaven, in Moonglade.",
  progress = "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può continuare senza la sua benedizione.",
  reward = "Mentre ti avvicini, Dendrite fa un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e sul suo viso compare un sorriso appena accennato.$B$B\"Sento in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e con intenzione consapevole, anche se questa intenzione non è ancora concentrata. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso in ciò che farai.\"",
  en_title = "Great Bear Spirit",
  en_obj = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
}
T[5931] = {
  title = "Ritorno a Darnassus",
  desc = "È giunto il momento di separarci, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Mathrengyl Bearwalker cammina davvero in equilibrio con la natura, anche se vive pericolosamente vicino al luogo in cui l'equilibrio ha vacillato. Ascolta le sue istruzioni, e presto completerai le prime lezioni sul tuo ruolo di $Gprotettore:protettrice; dell'equilibrio.$B$BOra va', giovane. Ci rivedremo.",
  obj = "Torna a Darnassus e parla con Mathrengyl Bearwalker nell'Enclave Cenarion.",
  reward = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è stato come lo è per tutti i druidi quando cominciano a percorrere la via dell'Unghia... un po' sconcertante, ma molto intenso. So che per me è stato così.$B$BIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Col tempo abbiamo imparato ad affidarci alla sua saggezza e al suo potere per dare forza alla nostra missione. Ora è giunto il momento della tua prima prova al servizio di questa missione. Ascolta bene...",
  en_title = "Back to Darnassus",
  en_obj = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.",
}
T[5932] = {
  title = "Ritorno a Thunder Bluff",
  desc = "È giunto il momento di separarci, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Anche se si pensa che i tauren siano giovani nelle vie di Cenarius, Turak Runetotem cammina con grande equilibrio al cospetto della natura. Ascolta le sue istruzioni, e presto completerai le prime lezioni sul tuo ruolo di $Gprotettore:protettrice; dell'equilibrio.$B$BOra va', giovane. Ci rivedremo.",
  obj = "Torna a Thunder Bluff e parla con Turak Runetotem sull'Elder Rise.",
  reward = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è stato come lo è per tutti i druidi quando cominciano a percorrere la via dell'Unghia... un po' sconcertante, ma molto intenso. So che per me è stato così.$B$BIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Noi tauren ascoltiamo con attenzione spiriti come questo, e tutti prosperiamo grazie alla sua missione. Ora è giunto il momento della tua prima prova al servizio di questa missione. Ascolta bene...",
  en_title = "Back to Thunder Bluff",
  en_obj = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.",
}
T[5941] = {
  title = "Ritorna da Chromie",
  desc = "Hai raccolto molte reliquie della battaglia di Darrowshire. Ogni volta che ne riportavi altre, il mio cuore si struggeva per il mio villaggio... si struggeva dalla voglia di proteggerlo dal suo destino.$B$BSo che non può essere, ma Chromie, quella strana gnoma di Andorhal, mi dice che è possibile. Dice che tu puoi salvare Darrowshire!$B$BMi ha chiesto di radunare le reliquie e di fartele portare da lei. Ha detto che ti aspetta nella locanda in rovina di Andorhal.",
  obj = "Porta il Bundle of Relics a Chromie, ad Andorhal.",
  progress = "Sono stata in contatto con il tuo amico Carlin. Soffre molto per la sorte toccata al suo villaggio, ma parla molto bene di te e sa che puoi sistemare le cose.$B$BOh, ma sto divagando... $N, hai le reliquie che ho chiesto?",
  reward = "Ah sì, eccole. Insieme tessono un incantesimo potente, che farà levare gli spiriti di Darrowshire.$B$BCon quell'incantesimo, e con un po' di fortuna, possiamo salvare Joseph Redpath!",
}
T[5942] = {
  title = "Tesori Nascosti",
  desc = "Papà mi ha detto di darti questa chiave. Ha detto che apre un baule qui fuori, dietro casa.$B$BVoleva anche che ti ringraziassi. Gli hai fatto un favore? Gli hai detto che hai trovato la mia bambola?$B$BBe', ecco la chiave. E grazie, $N. Grazie! Sei $Gun signore:una signora; molto gentile!",
  obj = "Porta Joseph's Key a Joseph's Chest.",
  progress = "Questo baule è vecchio e coperto di sudiciume.",
  reward = "La chiave entra nella serratura, e il baule si apre...",
}
T[5943] = {
  title = "Gizelton Caravan",
  desc = "Sembri $Gun:una; $R capace. Forse ti interessa guadagnare qualche soldo? Cork e io abbiamo messo in piedi questa carovana per fare un mucchio di quattrini; non immaginavamo quanto potesse essere pericoloso fare affari!$B$BPiù avanti c'è la Congrega di Mannoroc... di solito i demoni ci ignorano, ma questa volta qualcosa ha spaventato i kodo. Ti pagherò per proteggere la carovana oltre la Congrega di Mannoroc. Quando l'avremo superata sani e salvi, potrai ricevere la ricompensa dal nostro socio d'affari Smeed, all'Accampamento di Scrabblescrew.",
  obj = "Scorta la Gizelton Caravan attraverso la Congrega di Mannoroc. Parla con Smeed all'Accampamento di Scrabblescrew per la ricompensa.",
  progress = "Sai, se quella carovana dovesse mai sparire sarei rovinato! Non sei $Gil portatore:la portatrice; di cattive notizie sulla carovana, vero?$B$B<Smeed si asciuga la fronte.>$B$BSia ringraziata la dea dell'avidità!",
  reward = "Non sono sicuro che pagare così tanti soldi per proteggere la Gizelton Caravan sia un affare vantaggioso. Cork e Rigger guadagnano solo una moneta d'oro a settimana, ma finché continuano a pagarmi i kodo, di come mandano avanti i loro affari non me ne importa niente.",
  en_title = "Gizelton Caravan",
  en_obj = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.",
}
T[5944] = {
  title = "Nei Sogni",
  desc = "Per tanto tempo sono stato un burattino del Gran Crociato. Che ragione c'era di combattere contro ciò che la Crociata Scarlatta era diventata? Sono passati decenni, eppure i ricordi di mio padre; quei ricordi preziosi, sono loro che mi hanno tenuto in vita.$B$BFaccio dei sogni, $Gstraniero:straniera;. In questi sogni mio padre è con me. È al mio fianco, fiero, mentre vengo accolto nell'Ordine. Combattiamo fianco a fianco contro legioni del Flagello. Portiamo onore all'Alleanza, a Lordaeron.$B$BNon voglio più sognare.$B$BPortami da lui.",
  obj = "Scorta Taelan Fordring fuori da Hearthglen.",
  progress = "<Tirion si ricompone.>",
  reward = "La morte di mio figlio per mano di questi mostri non resterà senza conseguenze. Ti sia di conforto sapere che l'Ordine è rinato.$B$BOra prendo il mio posto come Gran Signore del nuovo Ordine della Mano d'Argento.$B$BQuesti averi del mio passato — sono tutto ciò che ho da offrirti per tutto quello che hai fatto. Ti prego, prendili come segno della mia gratitudine; tutti mi hanno servito bene negli anni.$B$BChe ci si possa rivedere, in tempi migliori, per ricordare giorni ormai lontani... battaglie duramente combattute... sogni riscattati.",
}
T[5961] = {
  title = "Il Campione della Regina Banshee",
  desc = "Mi fa grande piacere vedere chi è temprato dalla battaglia unirsi alla nostra causa. Diventiamo più numerosi e più forti ogni giorno che passa. Forse sei $Gpronto:pronta; a metterti alla prova, $C?$B$BTra i miei primi campioni ci fu Nathanos, oggi noto come il Blightcaller. Pochi, tra le nostre file, hanno più dedizione o più vigore di lui.$B$BCercalo nelle Eastern Plaguelands. Risiede alla Tenuta dei Marris; di tanto in tanto vaga per le lande devastate, uccidendo tutta la feccia del Flagello e dell'Alleanza che incrocia il suo cammino.",
  obj = "Parla con Nathanos Blightcaller nelle Eastern Plaguelands. Si dice che si sia stabilito alla Tenuta dei Marris.",
  reward = "Di certo la Signora Oscura non ti ritiene $Gdegno:degna; di incontrare il suo campione. Sei qui per dare da mangiare ai miei segugi, vero? Non può esserci altro motivo per questa interruzione.",
}
T[5981] = {
  title = "Giganti Scatenati",
  desc = "Circa 4000 anni fa, Tyrande Whisperwind salvò la vita alla regina delle frostsaber, assalita da giganti scatenati. Da allora le frostsaber sono alleate degli elfi della notte.$B$BQuegli stessi giganti che un tempo erano un pericolo per le frostsaber esistono ancora, non troppo lontano da qui. Si chiamano frostmaul, e si sono impadroniti della grande valle a sud.$B$BDimostra la tua lealtà alle frostsaber; uccidi questi giganti in nome della regina delle frostsaber, Shy-Rotam!",
  obj = "Rivern Frostwind vuole che tu uccida 4 Frostmaul Giants e 4 Frostmaul Preservers.",
  progress = "Devi continuare a dimostrare il tuo valore, $N.",
  reward = "Eccellente, $N. Ho preso debita nota della tua determinazione.",
}
T[6001] = {
  title = "Corpo e Cuore",
  desc = "Subito a est di Auberdine ci sono molte grotte di lunagufi. In quella più vicina ad Auberdine c'è una Pietra dei Lunagufi. Lunaclaw, il difensore della pietra, ti affronterà solo quando sulla pietra verrà sparsa la Polvere di Luna Cenarion. Lunaclaw possiede una forza che tu devi usare come membro dell'Unghia.$B$BTi sei $Gguadagnato:guadagnata; il diritto di usare questa Polvere di Luna Cenarion, $N... ora dimostrami di esserti $Gguadagnato:guadagnata; il diritto di possedere la forza del corpo e la forza del cuore che ti servono come $Gdruido:druida;!",
  obj = "Usa la Cenarion Moondust sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.$B$BQuando hai finito, parla con Mathrengyl Bearwalker, a Darnassus.",
  progress = "Quando avrai affrontato la sfida che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.",
  reward = "Hai finalmente fatto il tuo grande passo verso un mondo molto più grande, $N. Sento dentro di te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che Lunaclaw possedeva.$B$BNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa significa essere $Gun Druido dell'Unghia:una Druida dell'Unghia;!",
  en_title = "Body and Heart",
  en_obj = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Mathrengyl Bearwalker in Darnassus when you are done.",
}
T[6002] = {
  title = "Corpo e Cuore",
  desc = "Nelle terre a ovest di Taurajo, nelle Barrens — appena prima che diventino Mulgore — si trova una Pietra del Lunagufo. I lunagufi sono bestie speciali, non originarie di queste parti. Lunaclaw, il difensore della pietra, ti affronterà quando sulla pietra verrà sparsa la Cenarion Lunardust. Lunaclaw possiede una forza che tu devi usare come membro dell'Unghia.$B$BTi sei $Gguadagnato:guadagnata; il diritto di usare questa Cenarion Lunardust, $N... ora dimostrami di esserti $Gguadagnato:guadagnata; il diritto di possedere la forza del corpo e la forza del cuore che ti servono come $Gdruido:druida;!",
  obj = "Usa la Cenarion Lunardust sulla Moonkin Stone tra Mulgore e le Barrens per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.$B$BQuando hai finito, parla con Turak Runetotem, a Thunder Bluff.",
  progress = "Quando avrai affrontato la sfida che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.",
  reward = "Hai finalmente fatto il tuo grande passo verso un mondo molto più grande, $N. Sento dentro di te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che Lunaclaw possedeva.$B$BNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa significa essere $Gun Druido dell'Unghia:una Druida dell'Unghia;!",
  en_title = "Body and Heart",
  en_obj = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Turak Runetotem in Thunder Bluff when you are done.",
}
T[6004] = {
  title = "Questioni in Sospeso",
  desc = "Mi hanno mandata come esploratrice a fare qualche danno e a valutare la forza delle difese di Hearthglen. Nell'Alleanza c'è chi pensa che quella cittadina abbia un'importanza non solo storica. Non spetta a me chiedermi quale sia, ma in ogni caso non sono in condizione di continuare finché non mi sarò riposata.$B$BSe te la senti, pagherei profumatamente per un po' d'aiuto. Comincia a sud di qui, dal loro accampamento vicino al piccolo baluardo che hanno tirato su. Se dimostri di essere abbastanza forte, forse potresti aiutarmi con il mio obiettivo principale.",
  obj = "Uccidi 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi e 2 Scarlet Knights, poi torna da Kirsta Deepshadow nelle Western Plaguelands.",
  progress = "Come va, $N? Sono più forti di quanto pensavi? Spero di no. Se devo andare fino in fondo, qui ci vorrà un sacco di forza in più rispetto a quello che ti ho già chiesto di fare.",
  reward = "Ben fatto, $N. Mi stupisce che tu li abbia sistemati così in fretta. Grazie.$B$BNon ho ancora incontrato nessuno che approvi la Crociata Scarlatta e i suoi metodi. Credo nella Luce quanto chiunque altro a Stormwind, ma loro hanno dimostrato di voler soltanto uccidere chiunque non sia fedele al loro movimento... anche gli innocenti.",
}
T[6021] = {
  title = "Zaeldarr l'Errante",
  desc = "Ci credi che, con tutti i guai che abbiamo nelle plaguelands... dobbiamo preoccuparci pure dei ladri? E mica ladri normali, ladri troll.$B$BE mica ladri troll normali. Ladri troll morti!$B$BLi guida un troll morto grande e grosso che si chiama Zaeldarr l'Errante, e vengono qui di notte a rubare i cadaveri dalla fossa qui sotto, poi se li portano nel loro malvagio covo di troll morti — la Cripta, a ovest.$B$BVai lì e fai fuori Zaeldarr, $N. Sono stufo marcio delle sue malefatte!",
  obj = "Porta Zaeldarr's Head a Caretaker Alen a Light's Hope Chapel.",
  progress = "Hai trovato il covo, $N? Hai sistemato Zaeldarr?",
  reward = "Grande, l'hai preso! E spero che tu abbia dato una lezione anche alla sua banda!",
}
T[6022] = {
  title = "Uccidere con uno Scopo",
  desc = "Finché resti nella mia fattoria, uccidi con uno scopo.$B$BIl tuo primo compito è dar da mangiare ai miei segugi.$B$BPrendi questo mortaio con il pestello e va' a Corin's Crossing. Lì troverai un ricco assortimento di creature del Flagello da massacrare. Dalle loro carcasse fresche mi serve del putridume vivo. Prendi quel putridume vivo e pestalo nel mortaio, poi lascialo riposare finché non coagula. Riporta qui il putridume coagulato.$B$BE vedi di capire, imbecille, che il putridume vivo dei non morti non resta 'vivo' molto a lungo. Devi uccidere in fretta!",
  obj = "Vai a Corin's Crossing, a est, e massacra le creature del Flagello che infestano la città. Raccogli 7 pezzi di Living Rot in meno di 10 minuti. Usa il Mortar and Pestle per ridurre il Living Rot in Coagulated Rot.",
  progress = "Stai piangendo? Se per te è troppo 'noioso', '$Geroe:eroina;', ti consiglio di tornare dalla Signora Oscura e di informarla degli orribili maltrattamenti che hai subito nella mia fattoria.$B$BE ora sparisci dalla mia vista!",
  reward = "Che delusione. Speravo, invece, di dare te in pasto ai miei segugi.$B$B<Nathanos sospira.>$B$BBe', almeno avranno qualcosa da mangiare.",
}
T[6023] = {
  title = "Questioni in Sospeso",
  desc = "La mia vera missione era indebolire le forze esterne della Crociata Scarlatta e poi infiltrarmi a Hearthglen per valutare quanti sono. Non sono ancora in condizione di farcela da sola, quindi forse potrei chiederti di aiutarmi di nuovo, $N? Dalle informazioni che ho raccolto prima di essere scoperta, la Crociata ha due membri importanti che sono la spina dorsale delle sue forze fuori dalla cittadina: la Predatrice Radley e il Cavaliere Durgen. Uccidili, e avremo fatto un passo avanti. Dovrebbero essere lungo il Passo di Hearthglen, fuori dalla cittadina vera e propria.",
  obj = "Uccidi Huntsman Radley e Cavalier Durgen, poi torna da Kirsta Deepshadow nelle Western Plaguelands.",
  progress = "Li hai già trovati, $N? Una volta sistemati quei due, potrò entrare a Hearthglen per guardare più da vicino come sono organizzati. Non posso farcela senza il tuo aiuto. Ti prego, trova Radley e Durgen per me.",
  reward = "Grazie, $N. Mi hai aiutata più di quanto potessi sperare. L'aria di qui sembra proprio prosciugarmi la volontà. Mi sento stanca, e mi accorgo che, restando qui, non miglioro affatto.$B$BNon so proprio come farò a infiltrarmi dentro Hearthglen e a riferire quanto è forte la presenza della Crociata Scarlatta.$B$BMa questa è un'altra faccenda, prima che tu vada, ecco, prendi questo... come compenso per il tuo aiuto. Grazie ancora.",
}
T[6024] = {
  title = "La Supplica di Hameya",
  desc = "Uccidimi. Prima che sia troppo tardi.$B$BSono Hameya. Durante il viaggio verso Zul'Mashar, io e i miei fratelli abbiamo mangiato della carne avariata... e siamo cambiati. Siamo infetti.$B$BOra sento le parole del lich, che mi spingono a raggiungere Zul'Mashar e a infettare altri della mia gente. Non riesco a resistere, e così ho scritto questa pergamena prima che la volontà mi abbandonasse.$B$BHo sepolto un forziere nella terra accanto a un carro dietro questa cripta, ma solo la mia chiave può aprirlo. La chiave ce l'ho io. Se vuoi il mio tesoro, allora trovami.$B$BUccidimi. Prima che sia troppo tardi.",
  obj = "Uccidi Infiltrator Hameya. Usa la sua chiave sul Mound of Dirt dietro l'Undercroft.",
  progress = "Il forziere sepolto qui è ben chiuso a chiave.",
  reward = "Il forziere di Hameya è aperto!!",
}
T[6025] = {
  title = "Questioni in Sospeso",
  desc = "Cosa? Davvero? Vuoi saperne di più? Ma hai già fatto così tanto per me, $N. Non potrei mai chiederti di entrare proprio a Hearthglen al posto mio.$B$BNe sei $Gsicuro:sicura;, $N? Hearthglen è molto più pericolosa del Passo — non posso darti nessuna protezione, e nemmeno informazioni su quello che potresti trovarti davanti.$B$BBeh, se vuoi davvero aiutarmi, entra in città e trova un punto in alto da cui si veda bene tutto l'abitato. Da lì puoi valutare quanti sono e venire a riferirmelo. Ma fai attenzione....",
  obj = "Entra a Hearthglen e trova un punto elevato da cui vedere la città e valutare le forze della Crociata Scarlatta, poi torna da Kirsta Deepshadow nelle Western Plaguelands.",
  progress = "È un compito pericoloso, $N. Invidio il tuo coraggio.",
  reward = "Ce l'hai fatta, $N! Grazie!$B$BTornerò a Elling... volevo dire a Stormwind, appena posso. Ecco, prendi questa moneta, è il minimo che possa fare per te. Fai onore alla tua gente, $N. Grazie e buona fortuna.",
}
T[6026] = {
  title = "È Chiedere Tanto",
  desc = "Questi qua dell'Argent Dawn hanno ingaggiato il vecchio Smokey per un lavoretto di demolizione. La mamma di Smokey mica ha tirato su uno scemo. Quando sul tavolo sbattono monete d'oro, i servizi di Smokey sono a disposizione. È il mio motto!$B$BOra, sarei disposto a dividere il compenso con te, se ti va di scarpinare un po'. Il patto è questo: io vado a Plaguewood a segnare gli edifici che dobbiamo distruggere. Tu procuri i componenti per le bombe. Ci ritroviamo qui quando hai tutto. Affare fatto?",
  obj = "Smokey LaRue vuole che gli procuri 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs e 8 Unstable Triggers.$B$BPer questi oggetti dovrai trovare un fabbro e un ingegnere.",
  progress = "Fidati del vecchio Smokey, $R. La ricompensa varrà la fatica. Questi dell'Argent Dawn non scherzano, quando c'è da pagare.",
  reward = "Posso pagarti metà subito e metà a lavoro finito.",
}
T[6027] = {
  title = "Libro degli Antichi",
  desc = "$N, ti affido la Gemma del Serpente. Metti questa gemma sulla mano della Statua del Serpente, sulla Ranazjar Isle, una piccola isola a nord-ovest di qui. Posandola evocherai colui che protegge il Libro degli Antichi. Questo libro contiene i segreti dei naga, segreti custoditi per secoli. Portami questo libro, e impareremo molto sui nostri nemici squamosi!",
  obj = "Prendi il Book of the Ancients e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.",
  progress = "Ah, $N! È bello rivederti. Hai il Libro degli Antichi?",
  reward = "Il Libro degli Antichi, perduto da tanto tempo! Mi assicurerò che questo libro venga consegnato all'alto consiglio. Oggi hai fatto un ottimo lavoro, e per questo meriti di essere $Gringraziato:ringraziata;... come si ringrazia un eroe!",
  en_title = "Book of the Ancients",
  en_obj = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.$B",
}
T[6028] = {
  title = "Il Rapporto di Everlook",
  desc = "Cerco una persona affidabile che mi aiuti in una faccenda piccola, ma non per questo meno importante. Sono qui per rappresentare gli interessi dell'Argent Dawn presso il governo locale di Everlook. Devo far avere un rapporto sugli sviluppi all'Argent Officer Pureheart, all'Accampamento di Chillwind; è piuttosto lontano da qui, lungo il margine meridionale delle Western Plaguelands.$B$BSe posso permettermi — sarebbe l'occasione perfetta per presentarti alla mia superiore e magari farti affidare qualche incarico da lei!",
  obj = "Consegna l'Everlook Report ad Argent Officer Pureheart a Chillwind Camp, nelle Western Plaguelands.",
  progress = "Salute, $C. A nome dell'Argent Dawn, ti offro protezione e riparo finché resterai qui all'Accampamento di Chillwind. Potrei anche avere del lavoro per te...",
  reward = "È davvero pieno di risorse, Gregor. Tratta da tempo con lo Steamwheedle Cartel ed è diventato un esperto dell'\"arte\" della trattativa goblin. È vero che i goblin sono fedeli prima di tutto a chi ha la borsa più gonfia, ma conoscono e rispettano anche il valore della diplomazia. Se non altro, procura loro clienti abituali...$B$BA ogni modo, l'Argent Dawn riconosce il tuo impegno. Ecco, accetta questo, con i nostri ringraziamenti.",
}
T[6029] = {
  title = "Il Rapporto di Everlook",
  desc = "Cerco una persona affidabile che mi aiuti in una faccenda piccola, ma non per questo meno importante. Sono qui per rappresentare gli interessi dell'Argent Dawn presso il governo locale di Everlook. Devo far avere un rapporto sugli sviluppi all'Argent Officer Garush, al Baluardo; è piuttosto lontano da qui, lungo il margine occidentale delle Western Plaguelands, a est delle Tirisfal Glades.$B$BSe posso permettermi — sarebbe l'occasione perfetta per presentarti al mio superiore e magari farti affidare qualche incarico da lui!",
  obj = "Consegna l'Everlook Report ad Argent Officer Garush al Bulwark, nelle Western Plaguelands.",
  progress = "Salute, $C. A nome dell'Argent Dawn, ti offro protezione e riparo finché resterai qui al Baluardo. Potrei anche offrirti l'occasione di combattere per una causa per cui vale la pena battersi!",
  reward = "È pieno di risorse per essere un umano, Gregor. Tratta da tempo con lo Steamwheedle Cartel ed è diventato un esperto dell'\"arte\" della trattativa goblin. È vero che i goblin sono fedeli prima di tutto a chi ha la borsa più gonfia, ma conoscono e rispettano anche il valore della diplomazia. Se non altro, procura loro clienti abituali...$B$BA ogni modo, l'Argent Dawn riconosce il tuo impegno. Ecco, accetta questo, con i nostri ringraziamenti.",
}
T[6030] = {
  title = "Duca Nicholas Zverenhoff",
  desc = "Un medium solitario che vive da queste parti, un certo Umbranse, ha fornito all'Argent Dawn un vero capolavoro letterario... che è con ogni probabilità la più grande raccolta di farneticazioni che io abbia mai visto mettere per iscritto.$B$BUno dei capi più rispettati della Dawn, il Duca Nicholas Zverenhoff, è un linguista brillante. Potresti portarglielo da parte mia — dietro ricompensa, s'intende? La Cappella della Luce — è lì che si trova adesso, all'estremità orientale delle Eastern Plaguelands.",
  obj = "Consegna il libro \"Studies in Spirit Speaking\" a Duke Nicholas Zverenhoff a Light's Hope Chapel, nelle Eastern Plaguelands.",
  progress = "Che la Luce ti guidi in questi tempi travagliati, $C. Cosa ti porta qui, in questo faro di speranza in mezzo all'oscurità e alla disperazione?",
  reward = "Questo... questo che mi hai portato è un libro molto speciale. Mi piacerebbe dirti che \"speciale\" in questo caso significa \"unico e molto probabilmente illuminante\", ma è ancora tutto da vedere.$B$B\"Ooooooo?\" Chi mai, sano di mente, si inventa una cosa simile?$B$BBe', ho già sentito nominare questo Umbranse di cui parlava Gregor, quindi la cosa non è priva di valore. Farò del mio meglio per decifrarlo. Quanto a te... ecco, prendi questo — omaggio dell'Argent Dawn. Già che sei qui, forse ci sono altre cose in cui puoi darci una mano.",
}
T[6031] = {
  title = "Runecloth",
  desc = "A Timbermaw stiamo bene così. Gli estranei non ci piacciono. Per noi è un bene, ma per il commercio è un male.$B$BNon molto tempo fa è venuta a Timbermaw una rara amica elfa della notte, e portava un mantello di runecloth. Il runecloth è raro fra noi, ma il mantello era così bello che la mia gente vuole che io faccia altri vestiti di runecloth.$B$BMi porterai del runecloth? Se me ne porti abbastanza, ti darò qualcosa in cambio.",
  obj = "Porta 30 Runecloth a Meilosh, a Timbermaw Hold.",
  progress = "Hai il runecloth? La mia gente non vede l'ora di avere altre cose di runecloth!",
  reward = "Ah, hai portato il tessuto. Che bel materiale!$B$BGrazie, $N. Sei $Gun vero amico:una vera amica;. Ti prego, accetta questo in cambio.",
}
T[6032] = {
  title = "Tessuto Sacro",
  desc = "Anche se alla gente di Timbermaw piace tanto toccare il runecloth, per noi non è sacro. Ma il mooncloth è sacro.$B$BPortami una piccola scorta di questo tessuto sacro, e ti insegnerò una tecnica segreta di lavorazione.",
  obj = "Porta 2 Mooncloth a Meilosh, a Timbermaw Hold.",
  progress = "Hai portato il mooncloth, $N?",
  reward = "Ah, molto bene. Questo mooncloth servirà per le vesti sacre al nostro popolo. Grazie, $N. Ora ti addestrerò.",
}
T[6041] = {
  title = "Quando Smokey Canta, Divento Violento",
  desc = "Mentre tu raccoglievi i materiali, ho mandato alcuni dei miei a segnare gli edifici del Flagello che dobbiamo demolire.$B$BIl piano è questo: ti do dieci candelotti della mia miscela speciale. Tu li porti a Plaguewood e li piazzi dentro le strutture del Flagello che ho fatto segnare per la detonazione.$B$B<Smokey schiocca le dita.>$B$BBing! Facile così.",
  obj = "Vai a Plaguewood, a nord-ovest di Light's Hope. Distruggi 8 Scourge Structures usando Smokey's Special Compound sul Mark of Detonation piazzato dentro ogni edificio. Smokey ha fatto segnare le Ziggurat e i Mattatoi.$B$BPiazzata la bomba, esci dall'edificio e ammira la tua opera.$B$BA proposito, Smokey's Special Compound è piuttosto... instabile.",
  progress = "Mi è avanzata roba per fare qualche altro candelotto di miscela speciale. Se te ne servono ancora, basta dirlo al vecchio Smokey.",
  reward = "Sei molto più $Gscuro:scura; di come ti ricordavo. Hai proprio quell'aria lì; l'aria che dice: 'Sono $Gstato carbonizzato:stata carbonizzata; da una bomba ad alto potenziale.'$B$B<Smokey ride.>$B$BComunque! Ecco la tua parte del bottino. Ci ho aggiunto qualcosina in più per lenire le scottature.",
}
T[6042] = {
  title = "I Piccoli Fastidi della Non Vita",
  desc = "Non si possono fare due passi fuori da questa fattoria senza imbattersi in uno di quegli odiosi pipistrelli. Voglio poter portare fuori i segugi a massacrare il Flagello senza essere importunato da qualche maledetto, lurido pipistrello. Ovviamente ho di meglio da fare che ammazzare pipistrelli senza pensare, un giorno dopo l'altro. Tu invece no.$B$BCosa? Il tuo addestramento? Questo è il tuo addestramento! Ora sparisci dalla mia vista e non tornare finché non avrai ucciso un bel po' di quei demoni alati. Non deludermi.",
  obj = "Uccidi 20 Noxious Plaguebats e 10 Monstrous Plaguebats. Quando hai finito, torna da Nathanos Blightcaller.",
  progress = "Poteva andare peggio. Avrei potuto mandarti a raccogliere guano di pipistrello.$B$B<Nathanos ti fissa pensieroso.>$B$BHrm... Ehi! Aspetta un momento. Dove stai andando?",
  reward = "È incredibile quello che si riesce a fare con un po' di rabbia e di furia.",
}
T[6061] = {
  title = "Addomesticare la Bestia",
  desc = "Per un tauren è importante seguire le tradizioni dei nostri antenati combattendo creature possenti. Sconfiggendo queste creature, possiamo accogliere in noi i loro spiriti, e questo ci permette di avvicinarci alla Madre Terra.$B$BAllo stesso modo, addomesticare una bestia perché combatta al nostro fianco ci aiuta a diventare una cosa sola con la natura che ci circonda. Col tempo imparerai ad addomesticare una bestia a tua scelta. Ma tutto richiede pratica, e hai molto da imparare. Per cominciare, prendi questo bastone per addomesticare; devi domare uno zampalunga delle pianure adulto.",
  obj = "Usa la Taming Rod per addomesticare un Adult Plainstrider. Esercita le tue abilità, poi riporta la Taming Rod a Yaw Sharpmane, a Bloodhoof Village.",
  progress = "Esercita le tue abilità, $N. Addomestica lo zampalunga delle pianure adulto.",
  reward = "La Madre Terra mi ha mandato dei segni; hai fatto bene.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
}
T[6062] = {
  title = "Addomesticare la Bestia",
  desc = "Saper imporre la propria autorità sulla natura è un'abilità ammirevole. In quanto $Gcacciatore:cacciatrice;, devi sforzarti di imparare a usare la forza e il potere propri di qualunque creatura tu scelga.$B$BOttenere il controllo di un animale non è un'impresa facile; è un compito che devi affrontare con molta determinazione.$B$BCome primo incarico, prendi questo bastone per addomesticare e usalo per domare un cinghiale chiazzato feroce. Li trovi piuttosto vicino a Razor Hill. Esercita le tue abilità in battaglia con il cinghiale al tuo fianco, poi torna da me.",
  obj = "Usa la Taming Rod per addomesticare un Dire Mottled Boar. Esercita le tue abilità, poi riporta la Taming Rod a Thotar, a Razor Hill.",
  progress = "Buona fortuna, $Ggiovane cacciatore:giovane cacciatrice;.",
  reward = "Hai fatto bene, $N. Credo che tu sia $Gpronto:pronta; per il tuo prossimo compito.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.",
}
T[6063] = {
  title = "Addomesticare la Bestia",
  desc = "In quanto $Gcacciatore:cacciatrice;, è importante che tu ricordi la responsabilità che hai tra le mani. La natura non è un potere che si possa piegare ai nostri desideri; è un potere che va rispettato e riconosciuto come qualcosa di più forte della tua stessa esistenza.$B$B$N, devi dimostrare di averlo compreso prima di acquisire la capacità di addomesticare un animale che ti faccia da compagno.$B$BIl tuo primo compito è prendere questo bastone per addomesticare. Con esso potrai domare un ragno guardingo telalegno. Domalo, ed esercita le tue abilità di $Gcacciatore:cacciatrice;.",
  obj = "Usa la Taming Rod per addomesticare un Webwood Lurker. Esercita le tue abilità, poi riporta la Taming Rod a Dazalar, a Dolanaar.",
  progress = "Imparerai, $N, e un giorno sarai $Gun grande cacciatore:una grande cacciatrice;.",
  reward = "Eccellente, $N! Impari davvero in fretta.",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
}
T[6064] = {
  title = "Addomesticare la Bestia",
  desc = "Ciao, $Gragazzo:ragazza;! Allora, vorresti sapere come ottenere un animale tutto tuo?$B$BBe', cominciamo. Non c'è niente di più importante dell'equipaggiamento quando si tratta di cacciare, ma del mio nuovo Fulminatore a Schegge possiamo parlare un'altra volta. Per ora concentriamoci su qualcosa che di sicuro ti interessa parecchio: un animale!$B$BIl modo migliore per imparare è provare diverse creature come compagne e vedere cosa ti piace. Quindi trova un grande cinghiale delle rupi, poi usa il bastone per addomesticare e domalo.",
  obj = "Usa la Taming Rod per addomesticare un Large Crag Boar. Esercita le tue abilità, poi riporta la Taming Rod a Grif Wildheart, a Kharanos.",
  progress = "Non preoccuparti, $Gragazzo:ragazza;! Potrai provarne qualcuno prima di doverti decidere per uno solo.",
  reward = "Lo so, lo so; ti stai chiedendo cosa viene dopo, vero?!",
  en_title = "Taming the Beast",
  en_obj = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
}
T[6065] = {
  title = "La Via del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza abile da gestire una bestia e addestrarla come compagna.$B$BDevi andare da Yaw Sharpmane, a Bloodhoof Village. Può metterti sulla via per guadagnarti un animale tutto tuo.",
  obj = "Parla con Yaw Sharpmane, a Bloodhoof Village.",
  reward = "Sì, credo proprio che tu sia $Gpronto:pronta;...",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Yaw Sharpmane in Bloodhoof Village.",
}
T[6066] = {
  title = "La Via del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza abile da gestire una bestia e addestrarla come compagna.$B$BDevi andare da Yaw Sharpmane, a Bloodhoof Village. Può metterti sulla via per guadagnarti un animale tutto tuo.",
