T[6068] = {
  title = "La Via del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza abile da saper gestire una bestia e addestrarla come tua compagna.$B$BDevi andare da Thotar, a Razor Hill. Può metterti sulla via per guadagnarti un animale tutto tuo.",
  obj = "Parla con Thotar, a Razor Hill.",
  reward = "Sì, è ora che tu cominci il tuo addestramento.",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Thotar at Razor Hill.",
}
T[6069] = {
  title = "La Via del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza abile da saper gestire una bestia e addestrarla come tua compagna.$B$BDevi andare da Thotar, a Razor Hill. Può metterti sulla via per guadagnarti un animale tutto tuo.",
  obj = "Parla con Thotar, a Razor Hill.",
  reward = "Sì, credo che tu sia $Gpronto:pronta; per l'addestramento...",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Thotar at Razor Hill.",
}
T[6070] = {
  title = "La Via del Cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza abile da saper gestire una bestia e addestrarla come tua compagna.$B$BDevi andare da Thotar, a Razor Hill. Può metterti sulla via per guadagnarti un animale tutto tuo.",
