T[7025] = {
  title = "Dolcetti per Greatfather Winter",
  desc = "Ehi, puoi fare un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?$B$BNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è all'opera da tutto il giorno, e un dolcetto farebbe comodo anche a lui. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Pensi di poter fare un piacere al Greatfather e procurarmene un po'?",
  obj = "Porta 5 Gingerbread Cookie e un Ice Cold Milk a Greatfather Winter, a Ironforge.",
  progress = "Tutto questo parlare di dolcetti ha fatto venire voglia anche a me. Mmmm... biscotti di pan di zenzero e latte...",
  reward = "Sei proprio un bell'aiuto per il vecchio Greatfather Winter, $N. Buona Vigilia di Grande Inverno.$B$BEcco una cosetta... sai, per il disturbo.",
  en_title = "Treats for Greatfather Winter",
  en_obj = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",
}
T[7026] = {
  title = "Finimenti per Montoni",
  progress = "La Stormpike Brigade non può andare alla carica cavalcando a pelo! Alle nostre cavalcature servono i finimenti, dopotutto non siamo dei selvaggi.$B$BPotremmo benissimo uccidere i montoni che girano vicino alla nostra base per avere il cuoio che serve a fabbricare un finimento, ma sarebbe da idioti. Quei montoni ci servono come cavalcature.$B$BDevi colpire la base del nemico, uccidere i lupi del gelo che usano come cavalcature e prendere le loro pelli. Portami quelle pelli, così si potranno fare i finimenti per la cavalleria. Va'!",
  reward = "Ben fatto, soldato. Ti avviserò quando avrò messo da parte abbastanza pelli.$B$BContinua così!",
}
T[7027] = {
  title = "Stalle Vuote",
  desc = "Guarda un po' le stalle, $N! Vuote! La Stormpike Brigade non ha montoni da cavalcare — la cavalleria non esiste più.$B$BDevi aiutarci, soldato. Prendi questo collare d'addestramento e addentrati nelle terre selvagge di questa valle. Trova i montoni d'Alterac che girano per tutta la zona e usa il collare per prenderne uno. Quando avrai catturato un montone, portamelo e io lo metterò nella nostra stalla.$B$BQuando avremo abbastanza montoni, il comandante dei cavalieri di montoni sarà avvisato. Con il tuo aiuto, la cavalleria rinascerà!",
  obj = "Trova un Alterac Ram nell'Alterac Valley. Usa lo Stormpike Training Collar quando sei vicino all'Alterac Ram per 'domare' la bestia. Una volta domato, l'Alterac Ram ti seguirà fino alla Stormpike Stable Master. Parla con la Stormpike Stable Master perché la cattura ti venga riconosciuta.",
  progress = "Senza il tuo aiuto, i Cavalieri di Montoni Stormpike non avrebbero cavalcature con cui andare in battaglia. Ci rendi un grande servizio!",
  reward = "Le stalle saranno piene in men che non si dica. Continua così!",
}
T[7028] = {
  title = "Mali Perversi",
  desc = "Le caverne di cristallo di Terramok si trovano a ovest, nel profondo di Maraudon... È un luogo antico, ricco di storia. E io voglio mettere le mani su un po' di quella storia, $C. Dietro le porte giganti giacciono nascoste reliquie degli dei antichi.$B$BSe sei $Gdisposto:disposta; ad affrontare i mali perversi che si trovano a Maraudon, credo di poter fare in modo che ne valga la pena. Raccogli le sculture di cristallo teradrico che trovi e riportamele.$B$BUna volta avute le sculture, potrò... studiarle. Questi poteri sono rimasti a riposo troppo a lungo...",
  obj = "Raccogli 25 Theradric Crystal Carvings per Willow a Desolace.",
  progress = "Niente domande!$B$BSai già cosa ti ho chiesto.",
  reward = "Ah ah ah! Lo sapevo che saresti $Gtornato:tornata;.$B$B<Willow borbotta.>$B$B...Così facile da convincere.$B$B...$GDisposto:Disposta; a tutto per il giusto prezzo. Eh eh eh...",
}
T[7029] = {
  title = "La Corruzione di Vyletongue",
  desc = "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, bloccando la crescita di molte delle piante che ci sono dentro.$B$BPrendi questa fiala, $N. Riempila alla pozza di cristallo arancione che si trova nelle caverne: il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in una sostanza curativa.$B$BTrova i rampicanti Vylestem nelle caverne arancioni e usa su di loro il liquido purificato. La pianta sarà liberata dalla corruzione, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...",
  obj = "Riempi la Coated Cerulean Vial alla pozza di cristallo arancione a Maraudon.$B$BUsa la Filled Cerulean Vial sui Vylestem Vines per far uscire il Noxxious Scion corrotto.$B$BGuarisci 8 piante uccidendo questi Noxxious Scion, poi torna da Vark Battlescar a Shadowprey Village.",
  progress = "Se riesci a guarire la pianta, ricomincerà a crescere. Dobbiamo fare quello che possiamo, $N...",
  reward = "Grazie per avermela riportata, $N. Con il liquido rimasto che mi hai portato posso continuare i miei studi.$B$BC'è ancora molto da fare, ma hai contribuito a guarire parte della corruzione che Vyletongue ha diffuso a Maraudon. Ti prego, accetta questo in segno della mia gratitudine.",
}
T[7041] = {
  title = "La Corruzione di Vyletongue",
  desc = "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, bloccando la crescita di molte delle piante che ci sono dentro.$B$BPrendi questa fiala, $N. Riempila alla pozza arancione corrotta che si trova nelle caverne: il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in una sostanza curativa.$B$BTrova i rampicanti Vylestem nelle caverne arancioni e usa su di loro il liquido purificato. La pianta sarà liberata dalla corruzione, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...",
  obj = "Riempi la Coated Cerulean Vial alla pozza di cristallo arancione a Maraudon.$B$BUsa la Filled Cerulean Vial sui Vylestem Vines per far uscire il Noxxious Scion corrotto.$B$BGuarisci 8 piante uccidendo questi Noxxious Scion, poi torna da Talendria a Nijel's Point.",
  progress = "Se riesci a guarire la pianta, ricomincerà a crescere. Dobbiamo fare quello che possiamo, $N...",
  reward = "Grazie per avermela riportata, $N. Con il liquido rimasto che mi hai portato posso continuare i miei studi.$B$BC'è ancora molto da fare, ma hai contribuito a guarire parte della corruzione che Vyletongue ha diffuso a Maraudon. Ti prego, accetta questo in segno della mia gratitudine.",
}
T[7042] = {
  title = "Le Leccornie Rubate della Vigilia di Grande Inverno",
  desc = "Senti... non per rovinare la magia della festa, ma alla Smokywood Pastures farebbe comodo un po' d'aiuto — quello che di solito date voi avventurieri.$B$BManca un carico importante di leccornie che doveva rifornirci per la festa, e adesso manca anche l'agente della Smokywood Pastures che avevamo mandato a cercarlo! Ti prego — il carico è stato segnalato l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarlo.$B$BVedi se sono tutti e due là, sani e salvi!",
  obj = "Trova l'investigatore della Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.",
  reward = "M-m-mi senti! Sia r-r-ringraziato il b-b-bilancio!$B$BNon sono davvero un p-p-pupazzo di neve — mi ch-ch-chiamo Sacks e l-l-lavoro per la f-f-filiale di Ironforge della Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai v-v-visto p-p-prima!$B$BChe f-f-freddo...",
  en_title = "Stolen Winter Veil Treats",
  en_obj = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
}
T[7043] = {
  title = "Che Cattivone...",
  desc = "Una c-c-creatura chiamata \"L'Abominevole Greench\" è quella che ha r-r-rubato il nostro carico di l-l-leccornie, $N. Ma sta' $Gattento:attenta;! È l-l-lui che mi ha r-r-ridotto a questo ammasso di n-n-neve!$B$BTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare in lungo e in largo dalle parti degli y-y-yeti; di s-s-sicuro è qui da q-q-qualche parte! T-t-trova le leccornie, $N, riportale alla Smokywood Pastures a Ironforge e d-d-di' che bisogna s-s-scongelarmi!",
  obj = "Trova e riporta gli Stolen Treats a Wulmort Jinglepocket, a Ironforge. L'ultima volta si pensava che li avesse l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle Alterac Mountains.",
  progress = "$N — la nostra Vigilia di Grande Inverno sarà rovinata senza quelle leccornie per rifornirci! Lo stesso Graccu non potrà dividere i suoi deliziosi pasticci di carne con tutti i bambini e le bambine buoni, quest'anno...",
  reward = "Le hai trovate! Hai salvato la Vigilia di Grande Inverno della Smokywood Pastures!$B$BPovero Sacks... manderemo di sicuro una squadra laggiù per trovare un modo di scongelarlo. Speriamo che torni in tempo per il giorno della Vigilia; però dovrà recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe possibile senza di te!",
  en_title = "You're a Mean One...",
  en_obj = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.$B",
}
T[7044] = {
  title = "Leggende di Maraudon",
  desc = "Un satiro oscuro di nome Lord Vyletongue ha diffuso il suo male in queste grotte tortuose, avvelenando la mente di tutti coloro che vi si trovano. Risiede ancora oltre i cristalli viola.$B$BVyletongue ha anche creato un simbolo vivente della sua corruzione, di nome Noxxion, che dimora oltre i cristalli arancioni. Insieme hanno rubato le due parti dello scettro di mio fratello. Celebras, mio fratello... vaga alla cieca là dentro, maledetto dalla corruzione.$B$BDevi aiutarlo! Trova i pezzi e parla con mio fratello... in qualche modo.",
  obj = "Recupera le due parti dello Scepter of Celebras: la Celebrian Rod e il Celebrian Diamond.$B$BTrova un modo per parlare con Celebras.",
  progress = "Mi sono risvegliato da un incubo che sembrava non dovesse mai finire...",
  reward = "Ora che hai recuperato le due parti del mio scettro, spero che un giorno Maraudon possa liberarsi della corruzione Vyle.",
}
T[7045] = {
  title = "Un Grazie dalla Smokywood Pastures!",
  desc = "Noi della Smokywood Pastures ti siamo grati per aver recuperato le leccornie rubate, $N. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Greatfather Winter in persona!$B$BPer favore, parla con Greatfather Winter: ti darà il tuo regalo della Vigilia di Grande Inverno da parte di noi della Smokywood Pastures. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Smokywood Pastures... grazie a te, naturalmente!",
  obj = "Parla con Greatfather Winter, a Ironforge.",
  reward = "Oh oh ohilà, $Gavventuriero:avventuriera;!$B$BI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono lieto di dartelo. Eccolo qui — che la tua Vigilia di Grande Inverno sia meravigliosa, questa e tutte quelle che verranno.",
  en_title = "A Smokywood Pastures Thank You!",
  en_obj = "Speak with Greatfather Winter in Ironforge.",
}
T[7046] = {
  title = "Lo Scettro di Celebras",
  desc = "Un tempo il mio scettro era per me una fonte di speranza. Il suo potere mi dava la libertà di spostarmi rapidamente in queste caverne. Speravo di portare la pace allo spirito di mio zio... È un compito che ora affido a te.$B$BPerché le due parti tornino a essere una sola, avrò bisogno del tuo aiuto per compiere il rituale. Ti prego, seguimi e ascolta le mie istruzioni mentre incanalo l'energia necessaria per riunire la verga al diamante.$B$BInsieme ricreeremo lo Scettro di Celebras!",
  obj = "Aiuta Celebras the Redeemed mentre crea lo Scepter of Celebras.$B$BParla con lui quando il rituale è completo.",
  progress = "Se vuoi ricominciare il rituale, ti prego, abbandona il nostro primo tentativo e poi parlami di nuovo.",
  reward = "Prendi questo, ti prego, e sappi che il potere che ora ti è concesso deve essere usato per il bene. Continua il tuo viaggio attraverso le caverne e, si spera, troverai i resti di mio zio. Ti attendono molti pericoli, $N.$B$BParla di nuovo con me se ne avrai bisogno.",
}
T[7061] = {
  title = "La Vigilia di Grande Inverno",
  desc = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso di leggende da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando avrai finito, porta il libro a Cairne Bloodhoof, a Thunder Bluff. So per certo che gli farà piacere sapere che altri si sono interessati alla tradizione del nostro popolo.",
  obj = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a Cairne Bloodhoof, a Thunder Bluff.",
  progress = "Ti do il benvenuto a Mulgore e nella nostra umile comunità di Thunder Bluff, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?",
  reward = "Con gli anni, le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, passando in secondo piano nel pensiero comune. Sì, so che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che il nostro popolo ci rifletta, almeno in qualche forma, aiuta a mantenere viva questa tradizione.$B$BIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua saggezza.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.",
}
T[7062] = {
  title = "Il Senso della Festa",
  desc = "Doni, leccornie, regali... bah, dico io!$B$BQuei goblin inquinano il vero significato di questa ricorrenza — la Vigilia di Grande Inverno. È un tempo di rinascita; la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quello sciocco pasticcione vestito di rosso laggiù!$B$BSe vuoi scoprire da te che cos'è davvero la Vigilia, chiedi a Historian Karnik, all'Explorer's League. Sono sicuro che sarà sorpreso che a qualcuno importi della storia più che di ricevere regali.",
  obj = "Parla della Vigilia di Grande Inverno con Historian Karnik, all'Explorer's League, a Ironforge.",
  reward = "La Vigilia di Grande Inverno, dici? Ahimè, un tempo per noi nani aveva un significato più profondo. Oggi sembra che altri abbiano trasformato la leggenda di Greatfather Winter in qualcosa che serve a vendere dolciumi e regali.$B$BNon c'è da stupirsi che Goli sia amareggiato per un cambiamento del genere. Lui e altri nani come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Vigilia.",
  en_title = "The Reason for the Season",
  en_obj = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",
}
T[7063] = {
  title = "La Vigilia di Grande Inverno",
  desc = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando avrai finito, porta il libro a King Magni Bronzebeard. So per certo che gli farà piacere sapere che altri si sono interessati alle leggende più antiche.",
  obj = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a King Magni Bronzebeard, a Ironforge.",
  progress = "Ti do il benvenuto nel Regno di Ironforge, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?",
  reward = "Con gli anni, le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, passando in secondo piano nel pensiero comune. Riconosco che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che i cittadini ci pensino, almeno in qualche forma, aiuta a mantenere viva questa tradizione.$B$BIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua erudizione.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.",
}
T[7064] = {
  title = "La Corruzione della Terra e del Seme",
  desc = "Nelle profondità di Maraudon vive una malvagia creatura del caos — la Principessa Theradras è una forza elementale della terra legata agli Dei Antichi. Secoli fa, lei e Zaetar, primo figlio di Cenarius, iniziarono una relazione. I figli nati dalla loro unione divennero noti alle genti di Kalimdor come centauri. Creature sempre riconoscenti, i centauri uccisero Zaetar, e ora ne custodiscono i resti. La mia missione qui è trovare chi sia abbastanza forte da uccidere Theradras, così da poter recuperare i resti di Zaetar prima di tornare a Stonetalon.",
  obj = "Uccidi Princess Theradras e torna da Selendra vicino a Shadowprey Village, a Desolace.",
  progress = "Preferirei combattere questa battaglia con le nostre forze, ma non ci restano altre possibilità — abbiamo bisogno di chi è più forte di noi, e le razze di Azeroth hanno dimostrato senza ombra di dubbio di saper superare prove simili quando lavorano insieme. Per questo ci rivolgiamo a te per chiedere aiuto.$B$BSpero solo che basti.$B$BZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine questo ha causato la sua stessa morte. Spero solo di non aver causato altre morti chiedendoti di aiutarci.",
  reward = "È una notizia meravigliosa, $N! Grazie!$B$BParlerò con Marandis e gli chiederò consiglio sulla questione dei resti di Zaetar, ma almeno hai superato la prova più difficile.$B$BMi è stato detto che, se la nostra missione fosse riuscita, avrei potuto ricompensare chi ci ha aiutato. Mi hanno dato questi oggetti come dono del nostro popolo — puoi sceglierne uno.",
}
T[7065] = {
  title = "La Corruzione della Terra e del Seme",
  desc = "Nelle profondità di Maraudon vive una creatura di caos e malvagità, $N. La Principessa Theradras è una forza elementale della terra, legata in qualche modo agli Dei Antichi. Secoli fa, fu Zaetar, primo figlio di Cenarius, ad andare in cerca di lei. I figli nati dalla loro... relazione sono le creature conosciute come centauri. Creature sempre riconoscenti, i centauri uccisero Zaetar, e ora è Theradras a custodirne i resti. La mia missione qui è trovare chi sia abbastanza forte da uccidere Theradras, così da poter recuperare i resti di Zaetar prima di tornare a Stonetalon.",
  obj = "Uccidi Princess Theradras e torna da Keeper Marandis a Nijel's Point, a Desolace.",
  progress = "Mi pesa dover rivolgere la mia supplica alle razze mortali, ma non ci restano altre possibilità. Le razze di Azeroth hanno dimostrato senza ombra di dubbio di saper superare prove simili quando lavorano insieme, ed è a loro che chiedo aiuto.$B$BSpero solo che basti.$B$BZaetar, fratello di Remulos, ha portato molte sofferenze in questo mondo, e alla fine questo ha causato la sua stessa morte. C'è una lezione per tutti noi, se siamo abbastanza saggi da coglierla.",
  reward = "È una notizia meravigliosa, $N! Grazie!$B$BAnche se mi preoccupa che tu non sia $Griuscito:riuscita; a riportare i resti di Zaetar, chi sono io per mettere in dubbio la volontà del primogenito di Cenarius. Forse ora la volontà dei centauri si spezzerà e la loro sete di sangue si placherà — possiamo solo sperarlo.$B$BMi hanno affidato questi oggetti per ricompensare chiunque ci avesse aiutato, se la nostra missione fosse riuscita. Puoi sceglierne uno in segno di gratitudine.",
}
T[7066] = {
  title = "Il Seme della Vita",
  desc = "I centauri, creature malnate — i miei figli e le mie figlie — hanno bisogno del loro padre.$B$BGuardati intorno — questo luogo risuona di speranza e di tutto ciò che predica mio padre Cenarius. È nato da me! E io non posso toglierlo a loro... nemmeno per i crimini che hanno commesso contro di me.$B$BMa c'è una cosa che vorrei chiederti, per dare pace all'animo di mio fratello. Prendi questo... è il primo seme caduto dalla vita che i miei resti hanno nutrito. Digli che il mio spirito rimane qui e che io continuo a vivere. Sono sicuro che capirà.",
  obj = "Cerca Remulos a Moonglade e consegnagli il Seed of Life.",
  progress = "Hai addosso l'odore della corruzione, $N... come molti avventurieri di questi tempi. Ma in te c'è qualcosa di diverso. C'è qualcosa di cui sei $Gvenuto:venuta; a parlarmi? Hai intorno a te un'aura che mi sembra familiare, ma non riesco a capire da dove venga.$B$BTi prego, te ne supplico, dimmi perché mi hai chiesto udienza.",
  reward = "Dunque mio fratello ha finalmente trovato la pace? Sono fiero di aver vissuto abbastanza da vedere questo giorno. Con tutta la sua arroganza e la sua rabbia, credevo davvero che l'avessimo perduto, ma questo... questo simbolo del suo sacrificio dimostra che non è perduto — è solo rinato. Prende il suo posto nella natura, come era suo dovere.$B$BGrazie, $N. Portandomi questo, mi hai ridato un po' della speranza che credevo di aver perso. Un giorno questo seme sarà importante per la gente di questa terra devastata dalla guerra... lo sento.",
}
T[7067] = {
  title = "Le Istruzioni del Paria",
  desc = "Anche se sono stato esiliato come eretico, le mie convinzioni restano vere — questo basta a spingermi avanti. Ma perché il mio destino si compia, mi serve l'aiuto di uno straniero... qualcuno che non appartenga a nessuna tribù di centauri.$B$BL'impresa richiede che qualcuno entri nelle sale sacre di Maraudon — una tomba che il mio popolo protegge, e in cui possono entrare soltanto i più devoti.$B$BSe accetti di aiutarmi, basta un cenno del capo. Ti darò una pergamena con le mie istruzioni. Leggila e medita sulle mie parole.",
  obj = "Leggi le Pariah's Instructions. Poi recupera l'Amulet of Union a Maraudon e riportalo al Centaur Pariah, nel sud di Desolace.",
  progress = "Cosa hai deciso, $N? Puoi aiutarmi? Metterai piede sul suolo sacro per aiutarmi a forgiare un'unica, grande tribù di centauri!?",
  reward = "Eccolo, $R! Eccolo! Ora posso cominciare la grande impresa di unire le tribù. Grazie.$B$BPrendi questo per il tuo impegno, ti prego. Spero che, la prossima volta che ci incontreremo, le circostanze siano molto diverse.",
}
T[7068] = {
  title = "Frammenti di Shadowshard",
  desc = "Magie potenti ci stanno nel luogo sacro dei centauri... il luogo sacro di Maraudon. Le tribù di centauri di Desolace proteggono quel posto con la loro vita, ma non ce la fanno a impedirci di prendere quello che ci serve.$B$BTu, tu vai in questo posto di Maraudon e trovi le creature di roccia fatte di shadowshard. Tu porti a me i cristalli viola, e Uthel'nay fa qualcosa per te in cambio del tuo tempo.$B$BQuel posto è pericoloso, quindi magari tu porti qualche amico.",
  obj = "Raccogli 10 Shadowshard Fragments a Maraudon e riportali a Uthel'nay a Orgrimmar.",
  progress = "Tu già trovato i cristalli? Rituali di potere, incantesimi di grande forza — quegli shadowshard forse molto utili in ogni tipo di magia arcana.",
  reward = "Ah, questi perfetti per le mie magie. Ecco, tu prendi uno di questi monili e vai per la tua strada... io ho tanto da studiare, io.",
}
T[7070] = {
  title = "Frammenti di Shadowshard",
  desc = "Da poco ho cominciato a fare esperimenti su vari cristalli e sulle loro proprietà arcane. Lady Proudmoore mi ha concesso di chiedere ai viaggiatori diretti a Desolace di cercare un luogo chiamato Maraudon. Nel tempio in rovina si trovano grandi elementali fatti di pietre violacee, che ho chiamato shadowshard.$B$BSe decidi di andare da quella parte e trovi qualcuno di quei cristalli, te ne sarei molto grato. Potrei persino ricavarne un monile per te, se lo desideri.",
  obj = "Raccogli 10 Shadowshard Fragments a Maraudon e riportali ad Archmage Tervosh a Theramore, sulla costa di Dustwallow Marsh.",
  progress = "Hai già fatto il viaggio? Mi rendo conto che sarebbe piuttosto pericoloso, ma se ci riuscissi, ne varrebbe davvero la pena.",
  reward = "Sono perfetti, $N. A dire il vero anche altri avventurieri sono tornati da lì, e con quello che mi hanno portato sono riuscito a ricavare questi... ti prego, prendine pure uno per il tuo impegno. E grazie ancora per i nuovi campioni da studiare.",
}
T[7081] = {
  title = "Cimiteri dell'Alterac Valley",
  desc = "I cimiteri dell'Alterac Valley sono territori ambiti. Sia l'Orda sia l'Alleanza combattono selvaggiamente per questi luoghi sacri. E tu, $N, sei $Gpronto:pronta; a unirti a quella lotta?$B$BVoglio che tu assalti un cimitero nemico. Trova un cimitero con in mezzo uno stendardo dell'Orda, e strappalo da terra! Fallo, e il tuo compito sarà concluso....$B$BMa se riesci anche a tenere il cimitero per qualche minuto, le nostre truppe arriveranno presto a darti il cambio.",
  obj = "Assalta un cimitero, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "$N, non hai ancora assaltato un cimitero. Torna da me quando avrai portato a termine questo compito!",
  reward = "Ben fatto! I cimiteri sono vitali per il nostro controllo dell'Alterac Valley. Quando ne catturi uno, contribuisci a garantire la sovranità dell'Alleanza qui.$B$BOra va', $N. Torna in battaglia, e se vedi un cimitero sotto il controllo dell'Orda... sai cosa fare!",
}
T[7082] = {
  title = "I Cimiteri di Alterac",
  desc = "Le linee di battaglia dell'Alterac Valley cambiano di continuo. I territori passano da una parte all'altra mentre affrontiamo i nostri avversari in scontri mortali. Ed è nei cimiteri, $N, che le battaglie infuriano più feroci.$B$BVoglio che attacchi un cimitero in mano all'Alleanza! Trova un cimitero con in mezzo uno stendardo dell'Alleanza e strappalo da terra.$B$BFallo e il compito che ti ho dato sarà concluso, ma... se tieni il cimitero per qualche minuto, allora sarà nostro e le truppe verranno a darti il cambio.",
  obj = "Assalta un cimitero, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Attacca un cimitero in mano all'Alleanza!",
  reward = "Ben fatto, $N! Con ogni cimitero che passa sotto il nostro controllo, gli spiriti dei nostri nemici vagheranno sempre più smarriti e senza meta.",
}
T[7101] = {
  title = "Torri e Bunker",
  desc = "Torri e bunker sono posizioni importanti, e dobbiamo conquistarli e tenerli tutti! Per questo voglio che attacchi un bunker controllato dal nemico.$B$BPer farlo, entra in uno che ha uno stendardo dell'Alleanza. Dentro vedrai un altro stendardo. Togli quello stendardo, e al suo posto comparirà uno stendardo bianco dell'Orda. Ben fatto!$B$BA quel punto il compito che ti ho dato sarà concluso, ma se tieni il posto abbastanza a lungo, e se l'Alleanza non se lo riprende, allora verrà distrutto!",
  obj = "Conquista una torre nemica, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Non hai ancora assaltato un bunker, $N! Aspetti che siano altri a prendersi la tua gloria?",
  reward = "Ho saputo che la tua missione è riuscita! Mi fa piacere...$B$BOra le nostre truppe possono lanciarsi alla carica impunemente, e mostrare all'Alleanza che Alterac Valley non è il suo posto!",
}
T[7102] = {
  title = "Torri e Bunker",
  desc = "Torri e bunker sono posizioni difensive fondamentali, quindi dobbiamo tenerne il più possibile! Voglio che attacchi una torre o un bunker ad Alterac Valley.$B$BPer farlo, entra in una torre che ha in cima uno stendardo dell'Orda. Dentro vedrai un altro stendardo nemico. Togli quello stendardo, e al suo posto comparirà uno stendardo bianco dell'Alleanza. Ben fatto!$B$BA quel punto la missione che ti ho dato sarà conclusa, ma tieni la zona abbastanza a lungo e, se l'Orda non se la riprende, allora verrà distrutta!",
  obj = "Distruggi lo stendardo di una torre o di un bunker nemico, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "Non hai ancora assaltato una torre, $N! Cosa aspetti?",
  reward = "Ho ricevuto un rapporto dal campo secondo cui hai aiutato a conquistare uno stendardo nemico. Ben fatto, $N! Con i loro tiratori fuori posizione possiamo spostare in avanti la linea di battaglia!",
}
T[7121] = {
  title = "Il Quartiermastro",
  desc = "$N, il nostro quartiermastro mi ha incaricato di mandargli le nuove reclute. Gli servono rifornimenti dai depositi allestiti nelle miniere di Alterac, e probabilmente manderà te a prenderli.$B$BSegui la strada. Troverai il nostro quartiermastro a ovest.",
  obj = "Parla con lo Stormpike Quartermaster.",
  reward = "È bello vedere truppe fresche qui, $N, ma con un po' di fortuna finirai in mezzo all'azione e non resterai $Gfresco:fresca; a lungo!$B$BParlami di nuovo. Ho degli incarichi di cui devo discutere con te....",
}
T[7122] = {
  title = "Conquista una Miniera",
  desc = "Le miniere di Alterac Valley non custodiscono solo minerali. Sia i Frostwolf sia gli Stormpike hanno nascosto le scorte in eccesso nelle miniere Irondeep e Coldtooth... non è una cattiva idea, se solo riuscissimo a mantenerne il controllo!$B$BConquista una miniera, poi torna da me. Per conquistare una miniera, entra in una che non controlliamo e uccidine il capo. Fatto questo, la miniera sarà nostra, e manderemo truppe a proteggerla!",
  obj = "Conquista una miniera che gli Stormpike non controllano, poi torna da Sergeant Durgen Stormpike nelle Alterac Mountains.",
  progress = "Non hai ancora conquistato la miniera, $N!$B$BQuando controlleremo una miniera, sarà molto più facile ricavarne minerali e rifornimenti.",
  reward = "Ci sei $Griuscito:riuscita;! Ben fatto, $N!$B$BQuando controlliamo una miniera e ci teniamo delle truppe, è molto più facile ricavarne minerali e rifornimenti.",
}
T[7123] = {
  title = "Parla con il nostro quartiermastro",
  desc = "$N, il Quartiermastro dei Frostwolf cerca reclute, per incarichi che portano nelle miniere di Alterac Valley. Parla con lui; ti dirà di più.$B$BSegui la strada a ovest fin dentro il bunker, poi prendi l'uscita ovest e troverai il nostro quartiermastro.",
  obj = "Parla con il Frostwolf Quartermaster.",
  reward = "Salve, $N! È bello vedere $Gun:una; $C come te, $Gdesideroso:desiderosa; di fare la sua parte per l'Orda. Parlami di nuovo, perché ho incarichi vitali per te...",
}
T[7124] = {
  title = "Conquista una Miniera",
  desc = "Come la battaglia infuria per le terre di Alterac Valley, così infuria anche nelle miniere Coldtooth e Irondeep. Tutte e due sono ricche di minerali e tutte e due servono da deposito per i rifornimenti; non c'è da stupirsi che siano così ambite!$B$BAiuta il nostro sforzo bellico, $N! Conquista una delle miniere per l'Orda! Per conquistare una miniera, entra in una che non controlliamo e uccidine il capo. Fatto questo, la miniera sarà nostra e manderemo truppe a proteggerla!",
  obj = "Conquista una miniera, poi torna da Corporal Teeka Bloodsnarl nelle Alterac Mountains.",
  progress = "Non hai ancora conquistato una miniera, $N! Trovane una che non controlliamo e sconfiggi il suo capo!",
  reward = "Hai conquistato una miniera! Con i nostri guerrieri a proteggerla, sarà molto più semplice estrarre minerali dalle sue profondità, o recuperare i rifornimenti che vi sono stati nascosti.$B$BBen fatto, $N. La tua impresa è un grande aiuto per il nostro sforzo in battaglia.",
}
T[7141] = {
  title = "La Battaglia di Alterac",
  desc = "La Lega degli Esploratori è convinta che ad Alterac Valley ci siano dei manufatti, ma gli orchi Frostwolf non ci lasciano esplorare. Non possiamo permettere all'Orda di fermare i nostri studi! Sconfiggi il generale dei Frostwolf, Drek'Thar. Morto lui, gli orchi perderanno il loro vantaggio.$B$BDrek'Thar è nella Rocca dei Frostwolf, nel sud di Alterac Valley. Annientalo, e poi torna da me.",
  obj = "Entra ad Alterac Valley, sconfiggi il generale dell'Orda Drek'thar, e poi torna da Prospector Stonehewer nelle Alterac Mountains.",
  progress = "Vai, $N. Vai ad Alterac Valley e sconfiggi il generale orco!",
  reward = "Ben fatto, $N! Ora che l'Orda ha preso una bella batosta con la morte del suo generale, avremo il respiro che ci serve per esplorare!",
}
T[7142] = {
  title = "La Battaglia per Alterac",
  desc = "I nani Stormpike e i loro alleati hanno invaso Alterac Valley, e dobbiamo ricacciarli fuori! Per vincere la battaglia per Alterac, dobbiamo sconfiggere il loro generale, Vanndar Stormpike!$B$BTroverai Vanndar a Dun Baldar, nel nord di Alterac Valley.$B$BDistruggilo, $N, e poi torna da me.",
  obj = "Entra ad Alterac Valley e sconfiggi il generale dei nani, Vanndar Stormpike. Poi torna da Voggah Deathgrip nelle Alterac Mountains.",
  progress = "Non tollereremo i nani in casa nostra! Piomba sui nostri nemici e sconfiggi il loro capo, il generale Stormpike!",
  reward = "Ben fatto, $N! Gli Stormpike non hanno speranze in questa stupida invasione.$B$BAh! Finora sono riusciti solo a far ammazzare il loro generale!",
}
T[7161] = {
  title = "Terreno di Prova",
  desc = "Salve, $C. È passato molto tempo dall'ultima volta che abbiamo potuto rispondere al richiamo della battaglia. Le vecchie sensazioni tardano ad affiorare ma, una volta risvegliate, il sangue scorre impetuoso. La furia della battaglia ritorna...$B$BTutti i nuovi arrivati nella Valley devono prima compiere il rito della battaglia.$B$BIn fondo alla caverna degli gnoll Wildpaw c'è uno stendardo dei Frostwolf. Avventurati là dentro e recupera lo stendardo. Riportamelo e ti concederò l'insegna di iniziato dei Frostwolf.",
  obj = "Raggiungi la caverna dei Wildpaw, a sud-est della base principale ad Alterac Valley, e trova il Frostwolf Banner. Riporta il Frostwolf Banner a Warmaster Laggrond.",
  progress = "Sveglia! Sveglia, $N! Questo non è un sogno. Sei davvero in trincea, nel mezzo di una battaglia che infuria!",
  reward = "Quel bruciore che senti è la tua anima che si risveglia. Il tuo spirito ha accettato la chiamata alle armi.$B$BOra sei $Guno:una; dei Frostwolf, $N. Congratulazioni.$B$BPorta sempre con te questa insegna. Man mano che salirai fra i ranghi dei Frostwolf, sostituirò l'insegna con altre, più potenti.$B$BForse un giorno sarai $Gesaltato:esaltata; nel Frostwolf Clan. Se mai quel giorno arriverà, ti verrà concesso l'Occhio del Comando.",
}
T[7162] = {
  title = "Terreno di Prova",
  desc = "Sei $Garrivato:arrivata; giusto in tempo, $C. Questi selvaggi dei Frostwolf non vogliono proprio arrendersi! Dobbiamo mostrare loro la potenza degli Stormpike. Devono inchinarsi alla nostra superiorità.$B$BPrima di andare sul campo di battaglia, ti conviene entrare nei ranghi degli Stormpike.$B$BA sud-ovest di Dun Baldar troverai le Caverne Icewing. Piantato in fondo alle caverne c'è uno Stendardo degli Stormpike. Avventurati là dentro e recupera quello stendardo. Riportamelo, e avrai guadagnato un'insegna di iniziato degli Stormpike.",
  obj = "Raggiungi le Caverne Icewing, a sud-ovest di Dun Baldar ad Alterac Valley, e recupera lo Stormpike Banner. Riporta lo Stormpike Banner a Lieutenant Haggerdin nelle Alterac Mountains.",
  progress = "Guardati dalle arpie della regione, $C. Non ci penseranno due volte a squarciarti la gola!",
  reward = "Prendi questa insegna e portala con orgoglio, $N. Man mano che il tuo grado fra gli Stormpike crescerà, crescerà anche l'insegna. Torna da me quando guadagnerai onore presso gli Stormpike, e sostituirò la tua insegna con altre, più potenti.$B$BForse un giorno diventerai una leggenda su questo campo di battaglia. Se mai quel giorno arriverà, ti verrà concesso l'Occhio del Comando.",
}
T[7163] = {
  title = "Alzati e Ricevi il Riconoscimento",
  progress = "<Il Maestro di Guerra Laggrond ti fa il saluto.>$B$BÈ il tuo momento, $N. Hai fatto molto per il Frostwolf Clan e così hai guadagnato un posto non solo come $Gsoldato:soldatessa; dei Frostwolf ma anche come $Gamico:amica;.$B$BBen fatto! Presenta la tua insegna di iniziato.",
  reward = "Questa nuova insegna rispecchia il tuo grado fra i Frostwolf. Tienila sempre con te.$B$BE, $C... Muori con onore!",
}
T[7164] = {
  title = "Honored nel Clan",
  progress = "È bello rivederti, $C. Non mi aspettavo che tornassi. E invece hai dimostrato di essere $Gun soldato coraggioso:una soldatessa coraggiosa; e onorevole dei Frostwolf.$B$BIl tuo momento è arrivato di nuovo, $N. Hai guadagnato un nuovo grado e, con esso, una nuova insegna che indica questa crescita di prestigio.$B$BPresenta la tua insegna.",
  reward = "<Il Maestro di Guerra Laggrond fa il saluto.>$B$BVai, $N! Continua a difendere i Frostwolf. Questa guerra va vinta! Per Drek'Thar! Per il Capoguerra!",
}
T[7165] = {
  title = "Reverenza Meritata",
  progress = "Così tanti caduti. Il sangue inzuppa i campi. Eppure... Tu vivi... Hai resistito. Hai guidato i nostri eserciti a molte vittorie. Per questo, dunque, $Gsoldato:soldatessa;, hai guadagnato un nuovo grado.$B$BPresenta la tua insegna.",
  reward = "<Il Maestro di Guerra Laggrond ruggisce.>$B$BHanno già cominciato a raccontare le tue gesta, $Gsoldato:soldatessa;. Gli Stormpike tremano di paura quando viene pronunciato il tuo nome. Continua così!",
}
T[7166] = {
  title = "Eroi Leggendari",
  progress = "Irradi autorità e potere, $C. $GEsaltato:Esaltata; agli occhi dei Frostwolf — il nemico si fa piccolo quando sente il tuo nome.$B$BAlzati, $GEroe:Eroina; dei Frostwolf. Alzati e ricevi gli onori!$B$BPresenta la tua insegna.",
  reward = "Presto tutti sul campo di battaglia saranno sotto il tuo occhio vigile. Il comando della Valley e delle sue truppe sarà tuo!",
}
T[7167] = {
  title = "L'Occhio del Comando",
  progress = "Drek'Thar canta le tue lodi. Kalimdor è in fermento per i racconti delle tue imprese eroiche. Il Capoguerra è raggiante — la tua strenua difesa del nostro clan gli ha fatto molto piacere.$B$BHai guadagnato l'Occhio del Comando.$B$BPresenta la tua insegna, Comandante $N.",
  reward = "Incanala il potere dell'insegna. Fai sentire al nemico le tue parole. La potenza dell'Orda è indiscutibile!",
}
T[7168] = {
  title = "Alzati e Ricevi il Riconoscimento",
  progress = "I più non vivono abbastanza da elevarsi al di sopra della propria mediocrità. Tu hai dimostrato di essere $Gun soldato:una soldatessa; esemplare, $C. È giunto il momento.$B$BPresenta la tua insegna.",
  reward = "Che i nostri nemici vedano che ad abbatterli è $Gstato un soldato:stata una soldatessa; di rango! Combatti per la gloria degli Stormpike!",
}
T[7169] = {
  title = "Honored nella Guard",
  progress = "Alla base non si parla d'altro che delle tue imprese nel Pian della Discordia! Hai inferto colpi poderosi al nostro nemico — annientandone il morale! Per questo hai guadagnato un grado d'onore fra gli Stormpike.$B$BPresenta la tua insegna.",
  reward = "Il re è stato informato dei tuoi atti d'eroismo al fronte, $C. Continua la tua strenua difesa della Stormpike Guard!",
}
T[7170] = {
  title = "Reverenza Meritata",
  progress = "Devo saperlo, $N. Quando guardi il nemico dritto negli occhi, vedi paura? Adesso si fanno piccoli in tua presenza? Devono rendersi conto di essere sconfitti!$B$BHai guadagnato la reverenza della Guard. Presenta la tua insegna!",
  reward = "Quando ci siamo incontrati la prima volta, non avrei mai immaginato che stesse nascendo $Gun eroe:un'eroina;. Continua così, $Gsoldato:soldatessa;!",
}
T[7171] = {
  title = "Eroi Leggendari",
  progress = "Davanti a me c'è $Gun eroe eccelso:un'eroina eccelsa; dell'Alleanza.$B$B<Il Tenente Haggerdin fa il saluto.>$B$BPochi hanno guadagnato un grado simile fra gli Stormpike. Ho guardato il nemico cadere davanti a te. Ho visto la sua determinazione sgretolarsi in tua presenza. Quando entri nella mischia, diventi il faro di speranza per le nostre forze!$B$BPresenta la tua insegna.",
  reward = "Sarai di certo tu a portare l'Occhio del Comando!",
}
T[7172] = {
  title = "L'Occhio del Comando",
  progress = "Che sentano la tua voce, Comandante $N! Che conoscano la paura. Mostra loro quale potere hanno gli Stormpike nei loro ranghi!$B$BPresenta la tua insegna.",
  reward = "Sei tu che devi guidare le nostre truppe alla vittoria, Comandante! I soldati sono al tuo comando. Eseguiranno i tuoi ordini diretti. Guidali.... Schiaccia i Frostwolf.",
}
T[7181] = {
  title = "La Leggenda di Korrak",
  desc = "Gli invasori Stormpike non sono l'unica minaccia della regione, soldato. La guerra nella Valle si combatte su due fronti. Anche i troll cannibali Winterax lottano per il potere.$B$BLi guida Korrak la Furia del Sangue — una bestia crudele e astuta.$B$BUn attacco a Korrak potrebbe rivelarsi un colpo durissimo per il clan Winterax. Uccidi la bestia e avrai la tua ricompensa!",
  obj = "Secondo la leggenda, il capo dei potenti Winterax trolls compare quando vuole per seminare distruzione fra gli abitanti di Alterac Valley.$B$BSe Korrak the Bloodrager dovesse farsi vedere, annientalo e torna da Warmaster Laggrond.",
}
T[7201] = {
  title = "L'Ultimo Elemento",
  desc = "C'è lavoro per chi si avventura nelle profondità, $N.$B$BI Dark Iron sono diventati maestri nel creare golem di potenza straordinaria.$B$BDai primi rapporti delle nostre spie risulta che i nani usano una fonte di energia unica nel suo genere per dare alle loro creazioni una capacità di uccidere senza pari.$B$BPensa solo a cosa potremmo fare con i nostri abomini, se mettessimo le mani su questa essenza degli elementi! Metti sottosopra quella città, se necessario, ma non tornare finché non avrai trovato l'essenza! Il compenso ripagherà il rischio.",
  obj = "Vai nelle Blackrock Depths e recupera 10 Essence of the Elements. Il tuo primo istinto è frugare i golem e i costruttori di golem. Ricordi che Shadowmage Vivian Lagrave ha borbottato anche qualcosa sugli elementali.",
  progress = "Fammele vedere!",
  reward = "Magnifico! Le farò spedire subito a Undercity con un corriere!$B$BQuanto a te — ecco il compenso, come promesso. Tieni pure il resto, lurida bestia!",
}
T[7202] = {
  title = "Korrak la Furia del Sangue",
  desc = "I troll Winterax, indigeni della regione, sono selvaggi spietati che più di ogni cosa vorrebbero aggiungere le nostre ossa al loro immondo stufato.$B$BDobbiamo mostrare loro la nostra forza!$B$BNelle loro caverne abbiamo recuperato dei tomi che descrivono in dettaglio la gerarchia dei loro capi. Secondo quei reperti il loro capo, Korrak la Furia del Sangue, tende a restare nascosto finché non gli si dà un motivo per farsi vedere.$B$BLa morte di Korrak sarebbe la morte del Clan Winterax! Uccidilo e torna qui.",
  obj = "Secondo la leggenda, il capo dei potenti Winterax trolls compare quando vuole per seminare distruzione fra gli abitanti di Alterac Valley.$B$BSe Korrak the Bloodrager dovesse farsi vedere, annientalo e torna da Lieutenant Haggerdin nelle Alterac Mountains.",
}
T[7221] = {
  title = "Parla con la Prospettrice Stonehewer",
  desc = "Ah, $N, a rapporto, eh? Ottimo, agli Stormpike serve chiunque riusciamo a radunare!$B$BParla con la Prospettrice Stonehewer a Dun Baldar. Sta reclutando per una missione vitale in territorio nemico. Troverai Stonehewer nella parte bassa della guarnigione di Dun Baldar.$B$BE tieni gli occhi aperti mentre attraversi Dun Baldar. C'è molto da fare per $Gun:una; $C che lavora sodo e non ha paura di sporcarsi le mani.",
  obj = "Parla con Prospector Stonehewer nella guarnigione di Dun Baldar.",
}
T[7222] = {
  title = "Parla con Voggah Deathgrip",
  desc = "$GUn:Una; $C? Bene! Siamo lieti di vederti ad Alterac, $N. Quegli intrusi dei nani e i loro alleati invadono la nostra valle, e chiunque nell'Orda è benvenuto al nostro fianco in un giusto massacro!$B$BParla con Voggah Deathgrip. Cerca agenti per una missione importante nella roccaforte dell'Alleanza ad Alterac Valley!$B$BTroverai Voggah nella Rocca dei Frostwolf.",
  obj = "Parla con Voggah Deathgrip nella Rocca dei Frostwolf.",
}
T[7223] = {
  title = "Pezzi di Armature",
  desc = "Ad Alterac Valley si combatte senza sosta, e i rifornimenti che ci arrivano da Ironforge non bastano a equipaggiare le nostre truppe esperte.$B$BSe sul campo di battaglia trovi dei pezzi di armatura, contribuisci allo sforzo bellico e portali a me!",
  obj = "Porta 20 Armor Scraps a Murgot Deepforge a Dun Baldar.",
  progress = "Hai portato dei pezzi di armatura, $N?",
  reward = "Questi sono dei buoni pezzi, $N. Posso usarli per fabbricare equipaggiamento nuovo per le nostre truppe.$B$BSe le mie scorte crescono abbastanza, forse le nostre unità da combattimento più esperte scenderanno in campo!",
}
T[7224] = {
  title = "Bottino Nemico",
  desc = "Quando combatti contro il nemico, raccogli i pezzi delle sue armature e portameli. Con quei pezzi farò armature per le nostre truppe!",
  obj = "Porta 20 Armor Scraps a Smith Regzar nel Villaggio dei Frostwolf.",
  progress = "Come va la caccia, $N. Hai dei pezzi di armatura per me?",
  reward = "Questi andranno benissimo. Li fondo, li rattoppo e non si capirà mai che vengono da quei codardi degli Stormpike!$B$BGrazie, $N. E fammi dare una lucidata a quella tua armatura...",
}
T[7241] = {
  title = "In Difesa dei Frostwolf",
  desc = "I tamburi di guerra risuonano in una terra lontana, $C. Il clan prediletto del tuo Capoguerra è sotto l'attacco della scellerata Stormpike Guard di Ironforge.$B$BA guardarti, capisco che sei davvero $Gtemprato:temprata; dalla battaglia e $Gpronto:pronta; ad abbracciare la causa dei Frostwolf.$B$BSei tu che ora devi fare il passo successivo nella tua evoluzione.$B$BA nord di Tarren Mill, ad Alterac, troverai l'ingresso di Alterac Valley. È lì che troverai il Maestro di Guerra Laggrond. Sbrigati, $C, perché la battaglia incombe!",
  obj = "Raggiungi Alterac Valley, nelle Alterac Mountains. Trova Warmaster Laggrond — che sta fuori dall'ingresso della galleria — e parlagli per cominciare la tua carriera di soldato dei Frostwolf. Troverai Alterac Valley a nord di Tarren Mill, ai piedi delle Alterac Mountains.",
  reward = "Per diventare un soldato dei Frostwolf, bisogna prima essere messi alla prova...",
}
T[7261] = {
  title = "L'Imperativo Sovrano",
  desc = "Stiamo combattendo una battaglia brutale nelle valli di Alterac. I troll cannibali Winterax ci attaccano da un lato e il selvaggio Clan Frostwolf dall'altro. Vanno sterminati entrambi in nome di Re Magni Bronzebeard! Conquistare, ripulire e dissodare quella terra è un imperativo sovrano e territoriale per il regno di Ironforge.$B$BAhimè, i soldati non crescono sugli alberi! Presentati al Tenente Haggerdin fuori da Alterac Valley per cominciare il tuo turno di servizio e d'onore fra gli Stormpike.",
  obj = "Raggiungi Alterac Valley, nelle Hillsbrad Foothills. Fuori dalla galleria d'ingresso, trova Lieutenant Haggerdin e parlagli.$B$BPer la gloria di Bronzebeard!",
  reward = "Mettiamoci al lavoro!",
}
T[7281] = {
  title = "Amore Fraterno",
  desc = "Tragico... Mio fratello mi fronteggia sul campo di battaglia: un comandante degli Stormpike.$B$BDei quattro Comandanti degli Stormpike, è senza dubbio il più pericoloso. Forse, se venisse ucciso, la Regina Banshee potrebbe trasformarlo come ha fatto con me — mostrargli che è nell'errore...$B$BTroverai mio fratello nel cuore del territorio nemico. Uccidilo e torna da me. Confido che tu sia in grado di portare a termine questa missione, soldato.$B$BE, soldato, non andare $Gda solo:da sola;.",
  obj = "Entra nel territorio degli Stormpike e uccidi Commander Karl Philips. A missione compiuta, torna da Commander Louis Philips.",
  progress = "Quanto deve soffrire a restare fra i vivi, mentre il suo amato fratello è asceso alla perfezione.",
  reward = "Le tue gesta eroiche non passeranno inosservate, $N.$B$BNon posso perdere tempo, se deve essere salvato. Bisogna contattare Sylvanas!",
}
T[7282] = {
  title = "Amore Fraterno",
  desc = "Bisogna porre fine alle sue sofferenze, soldato! Non sa quello che fa. È diventato un servo senza volontà della temuta Regina Banshee.$B$BAvanza, oltre il Pian della Discordia, fino al cuore del territorio dei Frostwolf. Trova mio fratello e distruggilo. Il suo tormento deve finire.",
  obj = "Entra nel territorio dei Frostwolf e uccidi Commander Louis Philips. A missione compiuta, torna da Commander Karl Philips.",
  progress = "È con il cuore pesante che do un ordine simile, soldato.",
  reward = "Ti sei $Gricordato:ricordata; di bruciare il cadavere, vero?",
}
T[7301] = {
  title = "I Signori del Cielo Caduti",
  desc = "Li teniamo prigionieri, $R. Parlo dei loro Comandanti di Stormo. È stata una battaglia furiosa nei cieli, ma alla fine sono caduti! Purtroppo i nostri piloti migliori sono stati abbattuti in un contrattacco contro la Rocca dei Frostwolf. Devi scoprire che fine hanno fatto.$B$BCerca alla Torre Granguardia Ovest e alla Rocca dei Frostwolf. Sono gli ultimi posti in cui sono stati visti. Perlustra queste zone a fondo.",
  obj = "Entra nel territorio dei Frostwolf e cerca Wing Commander Slidore, Wing Commander Vipore e Wing Commander Ichman. Se porti a termine la missione, torna da Commander Duffy.",
  progress = "Hai qualcosa che mi interessi sentire?",
  reward = "Incredibile! Li hai liberati, vero? Vero??? Be', se non altro sappiamo dove erano tenuti.",
}
T[7302] = {
  title = "I Signori del Cielo Caduti",
  desc = "Il nostro appoggio aereo è a pezzi, $N. I Comandanti di Stormo sono stati abbattuti sopra il territorio nemico. Devi scoprire che ne è stato di loro, così potremo tentare di salvarli!$B$BGuse è stato visto l'ultima volta in volo sopra il Fortilizio Icewing. Il Cavalcaguerra di Jeztor è stato avvistato vicino alla segheria degli Stormpike. Mulverick... quell'incosciente è stato visto schiantarsi vicino al Fortilizio Nord di Dun'Baldar.$B$BNon ho altre informazioni. Muoviti! Perlustra le zone a fondo.",
  obj = "Scopri che ne è stato di Wing Commander Guse, Wing Commander Jeztor e Wing Commander Mulverick. Se porti a termine la missione, torna da Commander Mulfort.",
  progress = "A che punto è la caccia, soldato?",
  reward = "Ben fatto! Le informazioni che hai recuperato saranno preziosissime per la nostra causa.",
}
T[7321] = {
  title = "Zuppa Cremosa di Tartaruga",
  desc = "Chi dice che i non morti non sanno niente di cucina? Prendi la mia ricetta segreta della Zuppa di Tartaruga, per esempio. Ho conosciuto gente che tornerebbe dalla morte solo per gustarne una ciotola! Eh, eh...$B$BA proposito, ultimamente non ho potuto prepararne. Andavo di persona al Lago Lordamere a cacciare le tartarughe azzannatrici, quelle brutte bestie, ma non riesco a staccarmi dal mio lavoro qui.$B$BSe mi porti un po' di Carne di Tartaruga delle tartarughe azzannatrici e delle spezie lenitive, ti mostrerò come si fa!",
  obj = "Porta 10 pezzi di Turtle Meat e delle Soothing Spices a Christoph Jeffcoat, a Tarren Mill.",
  progress = "Hai avuto fortuna con gli ingredienti? Te lo dico io, quei vermi dell'alleanza sono fin troppi da queste parti ormai... Secondo me si sono già avvicinati fin troppo...",
  reward = "La mia confortante zuppa di tartaruga ti terrà al caldo in una notte fredda... se ti importa di queste cose.",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
}
T[7341] = {
  title = "Uno Scambio Equo",
  progress = "Salve, $R. Sono Kolark, Cacciatore di Taglie di Thunder Bluff. Ho viaggiato per gran parte del mondo e ho visto molte cose.$B$BI miei viaggi attraverso i Mari del Sud mi hanno portato a scoprire queste meravigliose frecce con la punta di torio. Ahimè, di frecce ne ho una scorta infinita ma ho esaurito la scorta di cartucce. Bah, nessun Tauren che si rispetti si farebbe mai vedere con un arco fragile in mano, nemmeno morto. Le frecce sono inutili!$B$BTi propongo uno scambio: cartucce di torio per le mie frecce con la punta di torio, alla pari. Affare fatto?",
  reward = "Ottimo! Sono un Tauren di parola, $R. Le frecce sono tue.",
}
T[7342] = {
  title = "Le Frecce Sono Roba da Femminucce",
  progress = "Ma ti pare possibile una schifezza simile?! L'ultimo carico di munizioni da Kharanos è stato un pasticcio! Adesso come munizioni abbiamo solo queste frecce gracili e buone a nulla! Che diavolo me ne faccio di 500.000 frecce con la punta di torio?$B$BFacciamo così, $Gragazzo:ragazza;. Se mi porti delle cartucce di torio, in cambio ti do le frecce con la punta di torio — alla pari! Affare fatto?",
  reward = "Questo sì che è un affare fatto! Le frecce sono tue.",
}
T[7361] = {
  title = "Favore fra i Darkspear",
  desc = "<Najak ringhia.>$B$BPrima che esistessero gli elfi della notte c'era il troll. È dal troll che sono venuti gli elfi della notte.$B$BI loro attacchi da ribelli contro il mio popolo non saranno tollerati. Staghelm vuole spazzarci via — non lasciare traccia di coloro che hanno generato lui e i suoi simili. Non accadrà!$B$BPer ogni elfo della notte che ucciderai e decapiterai, Najak ti concederà favore fra i Darkspear. La notizia delle tue gesta si diffonderà per Kalimdor e gli Eastern Kingdoms. Ora va' e servi i Darkspear!",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori elfi della notte avversari ad Alterac Valley.$B$BUccidi un elfo della notte e torna da Najak Hexxen alla Rocca dei Frostwolf con una Severed Night Elf Head.",
  progress = "Vogliono sterminarci? Saranno loro a essere sterminati.",
  reward = "$N, non è che una fra migliaia. Un buon lavoro, comunque.",
}
T[7362] = {
  title = "$GAlleato:Alleata; dei Tauren",
  desc = "L'Anziana Megera mi ha mandato in questa zona di guerra a studiare le altre razze. Più precisamente, devo raccogliere campioni di gnomo. A Magatha interessa soprattutto la loro capacità di sopravvivenza. Già, gli gnomi — per quanto pietosamente deboli e minuscoli — mostrano una grande resistenza, in combattimento e fuori.$B$BPer tua fortuna, cerco dei tipacci che eseguano gli ordini di Magatha. Torna da me con dei ciuffi di capelli di gnomo e i tauren ti riconosceranno come $Gun alleato:un'alleata;.",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori gnomi avversari ad Alterac Valley.$B$BUccidi uno gnomo e torna da Ravak Grimtotem alla Rocca dei Frostwolf con un Tuft of Gnome Hair.",
  progress = "Non m'importa da dove vengono i capelli, $R.",
  reward = "Già, questo è senza dubbio di gnomo. Ben fatto, $R, ma c'è altro lavoro da fare.",
}
T[7363] = {
  title = "La Condizione Umana",
  desc = "Gli umani sono così profondamente detestabili.$B$B<Il Comandante Philips fa una smorfia.>$B$BPer quanto sia vero che sono un soldato dei Frostwolf, resto un servitore di Sylvanas.$B$BDurante il mio turno di servizio, faccio qualche lavoro in più per gli Speziali Oscuri di Undercity.$B$BMi è stato affidato il compito di raccogliere schegge d'osso umano, che serviranno a curare la condizione umana.$B$BSono autorizzato a passare quel compito ai miei subordinati.$B$BTrovali. Uccidili. Riportami le schegge delle loro ossa.",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori umani avversari ad Alterac Valley.$B$BUccidi un umano e torna da Commander Louis Philips (che si aggira fra le prime linee e la rocca dei Frostwolf) con una Human Bone Chip.$B$BUna cura per la condizione umana è a portata di mano!",
  progress = "Sì, è vero. Mio fratello è un umano. Una vergogna... Una macchia sul mio stato di servizio quasi immacolato.",
  reward = "Sarebbe più facile se accettassero la loro malattia e cedessero al tuo tocco guaritore. Probabilmente sarebbe anche meno divertente. Continua così! Li cureremo, in un modo o nell'altro.",
}
T[7364] = {
  title = "La Taglia di Gnomeregan",
  desc = "Il Gran Meccanico in persona mi ha mandato su questo campo di battaglia a difendere i miei fratelli e le mie sorelle gnomi. Ci è giunta voce che i tauren prendono di mira gli gnomi e li uccidono. Peggio ancora, strappano ciuffi di gloriosi capelli di gnomo dai cadaveri dei caduti. Queste atrocità vanno fermate. Dobbiamo ripagarli con la stessa moneta!$B$BLi voglio dezoccolati, $C. Portami i loro zoccoli! Dimostra di essere $Gun alleato:un'alleata; degli gnomi.",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori tauren avversari ad Alterac Valley.$B$BUccidi un tauren e torna da Dirk Swindle a Dun'Baldar con un Tauren Hoof.",
  progress = "Falli zoppicare, $N. Devono imparare che il popolo degli gnomi non si lascia mettere i piedi in testa!",
  reward = "*Dirk getta lo zoccolo su un mucchio alle sue spalle.*",
}
T[7365] = {
  title = "Il Requiem di Staghelm",
  desc = "Staghelm ha dato l'ordine. Tutti i troll sul campo di battaglia vanno sterminati. Alle loro assurde pretese di aver generato gli elfi della notte si deve rispondere con la forza e con la dovuta durezza.$B$BUccidili e torna da me con il loro mojo. Ripeto: voglio che rubi il loro mojo.",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori troll avversari ad Alterac Valley.$B$BUccidi un troll e torna da Athramanis a Dun'Baldar con del Darkspear Troll Mojo.",
  progress = "Sento ancora l'odore di quei troll puzzolenti.",
  reward = "Grazie, $N. L'aria è un po' più pura.",
}
T[7366] = {
  title = "La Misericordia dell'Arcivescovo",
  desc = "L'Arcivescovo è tanto buono quanto saggio. Che un uomo guardi con misericordia a una gentaglia così miserabile...$B$B<Il Comandante Philips scuote la testa, incredulo.>$B$BTroppo buono... Davvero troppo buono.$B$BL'Arcivescovo ci chiede di avere pietà dei non morti e di concedere loro una morte rapida e definitiva. Per questo grande gesto di misericordia, chiediamo soltanto i loro cuori neri, divorati dalla malattia.$B$BPortami i cuori dei Reietti, perché siano inceneriti con una cerimonia nella Cattedrale della Luce. Fa' presto, $N!",
  obj = "Ti è stato dato l'incarico di uccidere i giocatori Reietti avversari ad Alterac Valley.$B$BUccidi un Reietto e torna da Commander Karl Philips (che si aggira fra la segheria e la miniera) con un Forsaken Heart.",
  progress = "Benedictus! Non sono che un granello nell'ombra della sua grandezza. Sia lode a lui!",
  reward = "Sia lode a Benedictus! Un'altra anima perduta, che presto sarà salvata dalle fiamme incandescenti della Luce!$B$BVa', o soldato della Luce! Altre devono essere salvate!",
}
T[7367] = {
  title = "Disinnescare la Minaccia",
  desc = "I Frostwolf hanno riempito di trappole esplosive le prime linee e le basi, $C. Devi guardare dove metti i piedi quando invadi il territorio nemico.$B$BSe vuoi assestare loro un colpo serio, devi distruggere la fonte delle loro munizioni antiuomo — parlo del loro esperto di esplosivi. Se lo uccidi, puoi disarmare le mine senza rischi. Finché lui resta fuori gioco, restano fuori gioco anche le mine.$B$BProbabilmente lo troverai in una torre vicino al Presidio Iceblood. Buona fortuna!",
  obj = "Trova il Frostwolf Explosives Expert e uccidilo. A missione compiuta, torna dallo Stormpike Explosives Expert.",
}
T[7368] = {
  title = "Disinnescare la Minaccia",
  desc = "So tutto delle mine. Dopotutto sono io che piazzo tutte le mine in prima linea, qui.$B$BSe vuoi disinnescare i campi minati degli Stormpike, ti basta uccidere il loro esperto di esplosivi. Quel codardo di un nano si nasconde di sicuro nella prima torre del Pian della Discordia. Fallo fuori e quelle mine, una volta disarmate, non torneranno più.$B$BSe per caso lo uccidi, torna qui a dirmelo. Nessuna buona azione dovrebbe restare senza ricompensa.",
  obj = "Trova lo Stormpike Explosives Expert e uccidilo. A missione compiuta, torna dal Frostwolf Explosives Expert.",
}
T[7385] = {
  title = "Un Gallone di Sangue",
  progress = "Puoi anche offrire quantità maggiori del sangue preso ai nostri nemici. Sarò lieta di accettare offerte da un gallone, $N.",
  reward = "Il sangue dei nostri nemici è stato versato. Mescolerò questo sangue a quello già raccolto. Quando l'offerta sarà completa, il Signore del Ghiaccio mostrerà a questi cani Stormpike tutta l'ira del Clan Frostwolf!",
}
T[7386] = {
  title = "Ammasso di Cristalli",
  progress = "Ci sono momenti in cui potresti restare $Gtrincerato:trincerata; in battaglia per giorni o settimane di fila. In quei periodi di attività più lunghi potresti ritrovarti a raccogliere grossi ammassi di cristalli del temporale dei Frostwolf.$B$BIl Circle accetta offerte del genere, $N.",
  reward = "Ben fatto, $N. Userò il potere di questi amuleti per accrescere la magia già raccolta. Quando sarà stato accumulato abbastanza potere, concentrerò le energie raccolte e invocherò il Signore della Foresta perché aiuti la nostra causa.",
}
T[7401] = {
  title = "Ricercati: NANI!",
  desc = "Per ordine della Sergente Yazra Bloodsnarl, tutti i nani sul campo di battaglia vanno uccisi a vista.$B$BSe uccidi un nano in combattimento, strappagli la spina dorsale e lascia lì un mucchio smidollato di fetore e marciume, che serva da monito a chiunque osi opporsi alla potenza dei Frostwolf.$B$BTorna dalla Sergente Yazra Bloodsnarl con la prova delle tue gesta eroiche.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori Nani avversari ad Alterac Valley.$B$BUccidi un Nano e strappagli la spina dorsale. Porta la Dwarf Spine a Sergeant Yazra Bloodsnarl alla Rocca dei Frostwolf.",
  progress = "Io tratto ironia all'ingrosso, $Gsoldato:soldatessa;.",
  reward = "Ora hai licenza di decimare nani a dozzine, $C!$B$B<Yazra resta per un attimo con lo sguardo perso in lontananza.>$B$BLa prima spina dorsale strappata non si scorda mai...",
}
T[7402] = {
  title = "Ricercati: ORCHI!",
  desc = "Per ordine del Caporale Noreg Stormpike, tutti i soldati Stormpike abili al combattimento sono tenuti a uccidere ogni orco nemico che incontrano sul campo di battaglia.$B$BI soldati sono tenuti a estrarre una zanna o un dente dalle fauci del nemico e a presentare detto dente come prova dell'impresa.$B$BIndossare guanti protettivi.",
  obj = "Ti è stato affidato il compito di uccidere i giocatori Orchi avversari ad Alterac Valley.$B$BUccidi un Orco e riporta il suo Orc Tooth a Corporal Noreg Stormpike a Dun Baldar.",
  progress = "Ti serve una pinza per cavare i denti?",
  reward = "Bene, $N. Aspetto i topolini.",
}
T[7429] = {
  title = "Libera Knot!",
  progress = "Si chiama Chiave delle Catene di Gordok — o almeno è così che continuano a chiamarla questi \"quintali di simpatia\". Credo che potrebbe averla uno qualunque degli ogre, ma non so se ce l'abbia qualcuno in particolare. Forse è più probabile che ne abbiano una le guardie...$B$BMa cosa sto dicendo — ce l'hai già, vero?! È quella lì??!",
  reward = "Oh, grazie per avermi liberato! Tu — al primo posto. Tutti gli altri — dal secondo posto in giù.$B$BLo sapevo che la mia vita era destinata a qualcosa di più che fare da antipasto a un ogre qualunque!",
}
T[7441] = {
  title = "Pusillin e l'Anziano Azj'Tordin",
  desc = "Avevo abbassato la guardia per un solo istante, $Gstraniero:straniera;. Nella fretta di sfuggire alla morsa del Principe caduto, sono stato derubato. Un demone quanto mai immondo, il diavoletto Pusillin, mi ha sottratto il libro degli incantesimi e la chiave delle sale un tempo grandiose di Eldre'Thalas.$B$BLa chiave non mi interessa più, perché ho scambiato l'immortalità con la libertà, ma ho un disperato bisogno del mio libro degli incantesimi.$B$BTrova il diavoletto, Pusillin, e recupera il mio libro.$B$BCerca Pusillin nel Quartiere di Warpwood di Dire Maul.",
  obj = "Vai a Dire Maul e trova l'Imp, Pusillin. Convinci Pusillin a darti il Book of Incantations di Azj'Tordin con ogni mezzo necessario.$B$BSe recuperi il Book of Incantations, torna da Azj'Tordin al Padiglione di Lariss, a Feralas.",
  progress = "Non rimpiango nulla, $Gstraniero:straniera;. La Regina è scomparsa da molto tempo. Le opere degli Shen'Dralar sono state deturpate dalla follia del Principe Tortheldrin. Io cerco solo la libertà... La fuga...",
  reward = "L'hai trovato! Sia maledetto quel miserabile diavoletto. Ahimè, i miei beni materiali sono ben poca cosa. Puoi scegliere fra ciò che ho da offrire.",
}
T[7461] = {
  title = "La Follia Interiore",
  desc = "Hai sentito abbastanza? Sei $Gun uomo:una donna; d'azione?$B$BQuesta follia deve finire. L'era degli immortali è passata da molto tempo. Distruggi i guardiani attorno ai piloni per abbassare il campo di forza. Fatto questo, distruggi Immol'thar. Quando il potere del Principe sarà molto ridotto, attaccalo e finiscilo. Dai pace agli spiriti di questa città, $Gavventuriero:avventuriera;.",
  obj = "Devi distruggere i guardiani attorno ai 5 Piloni che alimentano la Prigione di Immol'thar. Quando i Piloni si saranno spenti, il campo di forza attorno a Immol'thar si sarà dissolto.$B$BEntra nella Prigione di Immol'thar ed elimina l'immondo demone che sta nel suo cuore. Infine, affronta Prince Tortheldrin nell'Athenaeum.$B$BSe completi questa missione, torna dalla Shen'dralar Ancient nel cortile.",
  progress = "Sta' in guardia, $Gavventuriero:avventuriera;. Il Principe è... persuasivo.",
  reward = "Ti ringraziamo, $Geroe:eroina;.",
}
T[7462] = {
  title = "Il Tesoro degli Shen'dralar",
  desc = "Nella biblioteca, l'Athenaeum, troverai un antico scrigno nascosto sotto la scalinata. Prendi da lì ciò che desideri.",
  obj = "Torna all'Athenaeum e trova il Treasure of the Shen'dralar. Reclama la tua ricompensa!",
  reward = "Apri lo scrigno e trovi...",
}
T[7463] = {
  title = "Ristoro Arcano",
  desc = "$GUn mago:Una maga; $R! Che meraviglia. Non vedevo uno dei tuoi da... oh, a quanto siamo arrivati ormai? 500 anni!$B$BHo qualcosa che placherà la tua sete, ma prima devi svolgere un compito per me.$B$B<Lydros ridacchia.>$B$BC'è un'anomalia a Eldre'Thalas. Un elementale dell'acqua si è stabilito nell'ala est. La sua presenza va catalogata!$B$BAvventurati nel Quartiere di Warpwood ed estrai una parte dell'essenza elementale di Hydrospawn. Portamela e ti insegnerò un trucchetto utile.",
  obj = "Vai nel Quartiere di Warpwood di Dire Maul e uccidi l'elementale dell'acqua, Hydrospawn. Torna da Lorekeeper Lydros nell'Athenaeum con la Hydrospawn Essence.",
  progress = "Sì? Ci conosciamo?",
  reward = "Magnifico! Chi hai detto che sei? Oh, non importa. Cos'è che dovevo darti? Hmm... be', sei $Gun mago:una maga;, forse questo ti sarà utile.",
}
T[7481] = {
  title = "Leggende Elfiche",
  desc = "Diversi anni fa un maestro elfico solitario di nome Kariel Winthalus fuggì dalla devastazione della sua patria portando con sé diversi antichi artefatti elfici.$B$BLa ricerca di questo maestro scomparso ci ha portati dalle rovine di Quel'Thalas, attraverso le Burning Steppes, oltre le grandi distese del mare, fino a Feralas.$B$BSospettiamo che l'elfo abbia cercato rifugio nelle sale di Eldre'Thalas (quella che oggi è nota come Dire Maul).$B$BDevi trovarlo, $Gavventuriero:avventuriera;. Che sia vivo o morto, il sapere che portava con sé va recuperato!",
  obj = "Cerca Kariel Winthalus a Dire Maul. Torna a riferire a Sage Korolusk a Camp Mojache qualunque informazione tu riesca a trovare.",
  progress = "La mia collega, la studiosa elfa della notte Runethorn, sta reclutando i suoi alleati per questo compito.",
  reward = "Un peccato... una tragedia. Gli oggetti sono andati perduti, dici? Di lui nessuna traccia, eh?",
}
T[7482] = {
  title = "Leggende Elfiche",
  desc = "Diversi anni fa un maestro elfico solitario di nome Kariel Winthalus fuggì dalla devastazione della sua patria portando con sé diversi antichi artefatti elfici.$B$BLa ricerca di questo maestro scomparso ci ha portati dalle rovine di Quel'Thalas, attraverso le Burning Steppes, oltre le grandi distese del mare, fino a Feralas.$B$BSospettiamo che l'elfo abbia cercato rifugio nelle sale di Eldre'Thalas (quella che oggi è nota come Dire Maul).$B$BDevi trovarlo, $Gavventuriero:avventuriera;. Che sia vivo o morto, il sapere che portava con sé va recuperato!",
  obj = "Cerca Kariel Winthalus a Dire Maul. Torna a riferire a Scholar Runethorn a Feathermoon Stronghold qualunque informazione tu riesca a trovare.",
  progress = "Il mio collega, il saggio tauren Korolusk, sta reclutando i suoi alleati per questo compito.",
  reward = "Un peccato... una tragedia. Gli oggetti sono andati perduti, dici? Di lui nessuna traccia, eh?",
}
T[7483] = {
  title = "Compendio sulla Rapidità",
  desc = "Il Maestro Winthalus ha perso il Compendio sulla Rapidità nell'ala est. Il Compendio permette di applicare al tuo equipaggiamento un trucchetto minore di rapidità. Giochetti da salotto, in fondo...$B$BIn ogni caso, se ti interessa, dovrai presentare il Compendio insieme a qualche reagente di base.$B$BHmm... Credo che servano anche del sangue degli eroi, un diamante nero intatto e dei grossi frammenti splendenti. Potrei sbagliarmi!$B$B<Lydros fa spallucce.>",
  obj = "Porta un Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards e 2 Blood of Heroes a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Rapidity.",
  progress = "Che c'è? Ho molto da catalogare!",
  reward = "<Lydros sbadiglia.>$B$BCome promesso, l'Arcanum della Rapidità. Non spenderlo tutto in una volta.$B$B<Lydros ridacchia.>",
}
T[7484] = {
  title = "Compendio sulla Concentrazione",
  desc = "Questo compendio ha quasi destato l'interesse di uno dei famigli del Custode del Sapere più giovane. Poverino, aveva solo poche settimane di vita.$B$BQuelli di voi più portati per la magia potrebbero trovare interessante questo oggetto.$B$BIl Compendio sulla Concentrazione è andato perduto in quest'ala. Posso solo supporre che sia in possesso di uno degli spiriti degli Alti Nobili.$B$BPortami il Compendio insieme a dei grossi frammenti splendenti, della pelle dell'ombra e un diamante nero intatto, ed evocherò l'Arcanum.",
  obj = "Porta un Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards e 2 Skin of Shadow a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Focus.",
  progress = "Ancora tu? Cosa mai potresti volere adesso?",
  reward = "Non farti male mentre applichi l'incantamento, $R.",
}
T[7485] = {
  title = "Compendio sulla Protezione",
  desc = "Ha pianto come un bambino per la perdita di questo compendio. Intendiamoci, anch'io ho pianto per dei testi — non c'è perdita più grande di quella del sapere e della storia — ma piangere per questa accozzaglia quasi inutile di incantesimi? Assurdo! Mi ha fatto pensare che il Principe gli stesse facendo un favore, a strappargli la carne dalle ossa.$B$BPortami il Compendio insieme a un diamante nero intatto, dei grossi frammenti splendenti e una cucitura sfilacciata di abominio, e ricreerò l'Arcanum.$B$BAh, e controlla nell'ala nord.",
  obj = "Porta un Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards e 1 Frayed Abomination Stitching a Lorekeeper Lydros a Dire Maul per ricevere un Arcanum of Protection.",
  progress = "È la mia pazienza a risparmiarti la sofferenza.",
  reward = "Sì, sì... Calmati. Come promesso, ecco il tuo Arcanum.",
}
T[7486] = {
  title = "La Ricompensa di un Eroe",
  desc = "$N, i servigi che hai reso ai Waterlords hanno superato tutto ciò che potevamo aspettarci dagli abitanti di questo mondo.$B$BNoi non comprendiamo le idee della tua gente sulla gratitudine, o sul ricompensare le buone azioni, ma in questo caso... forse una ricompensa è dovuta.$B$BSotto i frangenti, ai piedi del lato sud di quest'isola, troverai un forziere. Dentro troverai la tua... ricompensa.$B$BVa', $N. Ritira la tua ricompensa.",
  obj = "Ritira la tua ricompensa da Hydraxis' Coffer.",
  reward = "La voce di Hydraxis scende dalla superficie dell'acqua...$B$B\"Scegli ciò che più ti si addice, $N. Possa proteggerti dai nemici dei Waterlords.\"",
}
T[7487] = {
  title = "Sintonizzazione con il Core",
  desc = "Le fenditure si agitano, si lacerano e collassano tutt'intorno a noi, $R. A meno di due passi da dove mi trovo c'è uno squarcio che attraversa le profondità di Blackrock Mountain e porta nelle fauci del Firelord.$B$B$GSorpreso:Sorpresa;? Che pena... Le razze mortali non riescono a comprendere ciò che non possono vedere, toccare o percepire.$B$BTe lo assicuro, il portale c'è e l'accesso è possibile.$B$BHo stuzzicato il tuo interesse? Sintonizzarsi è semplice. Avventurati nelle Blackrock Depths e recupera un frammento di nucleo. Riportamelo e sintonizzerò la tua essenza con il portale.",
  obj = "Raggiungi il portale d'ingresso del Molten Core nelle Blackrock Depths e recupera un Core Fragment. Quando avrai recuperato il Core Fragment, torna da Lothos Riftwaker a Blackrock Mountain.",
  progress = "Saltare nell'apertura adesso potrebbe finire in un disastro... per te.",
  reward = "Attraversa l'apertura alla mia destra e ti ritroverai dentro il Molten Core.",
}
T[7488] = {
  title = "La Tela di Lethtendris",
  desc = "La maga Lethtendris, una feroce elfa del sangue la cui brutalità è pari solo alla sua perversa dipendenza dalla magia, è fuggita a Dire Maul. Ha creato un congegno, una tela per intrappolare le energie magiche di quel luogo, e temiamo che, se nessuno la ferma, causerà danni irreparabili al nostro mondo!$B$BFermala, $N. Trovala e recupera la sua tela. Probabilmente è vicino ai satiri, nel Quartiere di Warpwood di Dire Maul. Portami la tela, così che il suo potere possa tornare senza pericolo alla natura selvaggia...",
  obj = "Porta Lethtendris's Web a Latronicus Moonspear a Feathermoon Stronghold, a Feralas.",
  progress = "Hai la tela, $N? La sua energia magica concentrata va dissipata!",
  reward = "Hai recuperato la tela! Ben fatto, $N! Lethtendris, come molti elfi della sua risma, è cieca davanti ai pericoli che l'abuso della magia può causare al nostro mondo. Credono di essere padroni della magia; non si rendono conto di essere schiavi della propria dipendenza. La sua morte mi rattrista, ma era necessaria.$B$BGrazie, $N. Farò liberare senza pericolo le energie racchiuse nella tela su un'area vasta, e poi la distruggerò per impedire altri abusi della magia in futuro.",
}
T[7489] = {
  title = "La Tela di Lethtendris",
  desc = "L'elfa del sangue Lethtendris ha passato il segno. Era così avida di potere magico che ha sfidato i suoi simili e ha creato un congegno di concezione insidiosa, una tela fatta per risucchiare le corrotte energie magiche di Dire Maul. Proprio ora sta raccogliendo quelle energie e intende scatenarle contro i suoi nemici.$B$BLethtendris va fermata. Trovala nel Quartiere di Warpwood di Dire Maul, sconfiggila e portami la sua tela, così che possa essere affidata a elfi del sangue più assennati perché la studino.",
  obj = "Porta Lethtendris's Web a Talo Thornhoof a Camp Mojache, a Feralas.",
  progress = "$N, hai la Tela di Lethtendris?",
  reward = "Hai fatto un buon lavoro, $N. Questa tela racchiude enormi riserve della magia di Dire Maul, e temo i danni che si scatenerebbero se quelle energie fossero imbrigliate da qualcuno di così irresponsabile come Lethtendris. La sua morte mi rattrista, ma so che da viva non si sarebbe mai separata dalla sua tela.$B$BGrazie, $N. Manderò la tela a studiosi di magia più responsabili di Lethtendris. Saranno loro i nuovi custodi del suo potere.",
}
T[7490] = {
  title = "Vittoria per l'Orda",
  desc = "Hai compiuto l'impossibile. La madre della covata del Black Dragonflight giace morta ai tuoi piedi. Prendine la testa e presentala al tuo Capoguerra.",
  obj = "Porta la Head of Onyxia a Thrall, a Orgrimmar.",
  progress = "<L'atteggiamento stoico di Thrall cambia per una frazione di secondo quando vede l'enorme testa di Onyxia. C'è mancato poco che il possente Doomhammer venisse sguainato.>",
  reward = "Questa è una grande vittoria per l'Orda, $N. Hai reso onore tante volte al tuo Capoguerra. È tempo che sia il Capoguerra a rendere onore a te.",
}
T[7491] = {
  title = "Perché Tutti Vedano",
  desc = "Il Signore Supremo Runthak attende il tuo arrivo nella Valley of Strength.$B$B<Thrall ti fa il saluto.>$B$BNon far aspettare il tuo pubblico, $Geroe:eroina;.",
  obj = "Cerca Overlord Runthak nella Valley of Strength.",
  reward = "Scegli la tua ricompensa, e che i festeggiamenti per la tua gloriosa vittoria abbiano inizio.",
}
T[7492] = {
  title = "Camp Mojache",
  desc = "Talo Thornhoof, un anziano Tauren di Feralas, manda una richiesta d'aiuto. Ha dato pochi dettagli, ma ha detto che gli servono agenti per una questione delicata... e grave.$B$BServi l'Orda, $N. Vai a Camp Mojache, a Feralas, e parla con Talo.",
  obj = "Parla con Talo Thornhoof a Camp Mojache, a Feralas.",
  reward = "Ah, è bello vedere $Gun:una; $C rispondere alla mia chiamata. Ho bisogno dei tuoi servigi, $N, e temo che ti porteranno su un sentiero pericoloso...$B$BUn sentiero che porta dentro Dire Maul.",
}
T[7493] = {
  title = "Il Viaggio È Appena Cominciato",
  reward = "$GUn ammazzadraghi e un esperto conciatore:Un'ammazzadraghi e un'esperta conciatrice;? Non smetti di stupire, $Geroe:eroina;. Sono onorato.$B$BTi prego, accetta quello che sto per insegnarti. Questa conoscenza ti sarà preziosissima se vorrai distruggere ciò che resta del Black Dragonflight.$B$BCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Blackrock... Nefarian.",
}
T[7494] = {
  title = "Feathermoon Stronghold",
  desc = "$N! C'è bisogno del tuo aiuto a Feralas!$B$BUna maga fuorilegge, Lethtendris, è fuggita fra le antiche rovine elfiche di Eldre'thalas, oggi chiamate Dire Maul. Si ritiene che abbia un oggetto carico di una pericolosa energia magica, che va recuperato.$B$BLatronicus Moonspear chiede agenti che entrino a Dire Maul e riprendano l'oggetto a Lethtendris.$B$BServi l'Alleanza! Cerca Latronicus a Feathermoon Stronghold, a Feralas.",
  obj = "Parla con Latronicus Moonspear a Feathermoon Stronghold, a Feralas.",
  reward = "Salute, $N. Sono lieto di vederti, ma mi rammarico che il nostro incontro non avvenga in circostanze più piacevoli.$B$BAscolta bene, perché ho per te un compito di vitale importanza...",
}
T[7495] = {
  title = "Vittoria per l'Alleanza",
  desc = "Hai compiuto l'impossibile. La madre della covata del Black Dragonflight giace morta ai tuoi piedi. Prendi la sua testa e presentala al Gran Signore.",
  obj = "Porta la Head of Onyxia a Highlord Bolvar Fordragon, a Stormwind.",
  progress = "Per la barba di Uther!",
  reward = "Per tanti anni sono stato prigioniero del suo sguardo ammaliatore. Finalmente vedo fatta giustizia e restituito l'onore di Stormwind! Oggi celebriamo questa gloriosa vittoria!",
  en_title = "Victory for the Alliance",
  en_obj = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.",
}
T[7496] = {
  title = "Tempi di Festa",
  desc = "Cerca il Maggiore Mattingly nella Valle degli Eroi, $N. Ti starà aspettando...",
  obj = "Cerca Major Mattingly a Valley of Heroes.",
  reward = "A pochi è concessa una cerimonia simile, $N. Ti prego, scegli la tua ricompensa, così possiamo cominciare i festeggiamenti.",
  en_title = "Celebrating Good Times",
  en_obj = "Seek out Major Mattingly in the Valley of Heroes.",
}
T[7497] = {
  title = "Il Viaggio È Appena Cominciato",
  reward = "$GUn ammazzadraghi e un esperto conciatore:Un'ammazzadraghi e un'esperta conciatrice;? Non smetti di stupire, $Geroe:eroina;. Sono onorato.$B$BTi prego, accetta quello che sto per insegnarti. Questa conoscenza ti sarà preziosissima se vorrai distruggere ciò che resta del Black Dragonflight.$B$BCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Blackrock... Nefarian.",
  en_title = "The Journey Has Just Begun",
}
