T[7507] = {
  title = "Compendio di Foror",
  desc = "Hai scoperto qualcosa di grande importanza. Questo libro è diverso da tutti quelli che hai visto.$B$BA quanto pare qualcuno, o qualcosa, è riuscito a spezzare il sigillo dell'Ateneo. Il testo all'interno è confuso e a malapena leggibile.",
  obj = "Riporta Foror's Compendium of Dragon Slaying all'Athenaeum.",
  progress = "Ah, una delle nostre raccolte più importanti. Questa mancava da un'eternità.",
  reward = "Al mercato nero avresti potuto ricavare parecchio oro da questo libro, $N. Soprattutto ora che il sigillo protettivo è stato spezzato e i segreti dell'uccisione dei draghi sono sotto gli occhi di chiunque abbia l'intelletto necessario per assimilare il sapere custodito in queste sacre pagine.$B$BForse ci vuole una ricompensa grandiosa... Beh, una ricompensa che per essere ottenuta richiederà uno sforzo enorme.$B$B<Lydros sogghigna.>",
}
T[7508] = {
  title = "La Forgiatura di Quel'Serrar",
  desc = "Se desideri assumerti questo compito, porgi a Lydros la lama smussata.",
  obj = "Consegna la Dull and Flat Elven Blade a Lorekeeper Lydros.",
  progress = "Eccellente, cominciamo...",
  reward = "Se riuscirai a entrare nella tana della dragonessa, a scaldare la lama sotto il suo alito di fuoco e infine a temprarla nel suo sangue, vincolerò la lama a te perché tu possa usarla.",
}
T[7509] = {
  title = "La Forgiatura di Quel'Serrar",
  desc = "Porta l'antica lama cruda nella tana di Onyxia e affrontala in battaglia.$B$BPer scaldare la lama bisogna ricorrere a qualche astuzia. Durante lo scontro, cercherà di sicuro di incenerirti con il suo soffio infuocato. Devi piantare l'antica lama cruda lì vicino e sperare che il soffio infuocato la scaldi. Se sopravvivi, raccogli l'antica lama, ora arroventata, e finisci il drago.$B$BAffonda l'antica lama arroventata nel suo cadavere fumante per ottenere l'antica lama trattata.",
  obj = "Devi fare in modo che Onyxia soffi il suo fuoco sulla Unfired Ancient Blade. Fatto questo, raccogli quella che ora è la Heated Ancient Blade. Attenzione, una Heated Ancient Blade non resta rovente per sempre — il tempo stringe.$B$BL'ultimo passo prima di tornare da me è uccidere la bestia e conficcare la Heated Ancient Blade nel suo cadavere.$B$BFallo e Quel'Serrar sarà tua.",
  progress = "Forse un giorno qualcun altro impugnerà la lama prismatica.",
  reward = "<Lydros mormora qualcosa di incomprensibile.>$B$BCome promesso, $C, la lama di Quel'Serrar.",
}
T[7521] = {
  title = "Thunderaan il Windseeker",
  desc = "Ti ho detto tutto quello che so, $N. Sei tu a dover trovare l'elementium. Sei tu a dover distruggere la forma corporea del Firelord.$B$BFallo, e avrai la benedizione di Thunderaan.",
  obj = "Per liberare Thunderaan the Windseeker dalla sua prigione, devi presentare a Highlord Demitrian le metà destra e sinistra delle Bindings of the Windseeker, 10 Elementium Bars e l'Essence of the Firelord.",
  progress = "Metti il mondo in ginocchio, se devi!",
  reward = "Nemmeno in sogno ho osato immaginare questo giorno.$B$BContempla, mortale.$B$BCONTEMPLA COLUI CHE È PIÙ ANTICO DELL'ESISTENZA!$B$BCONTEMPLA COLUI CHE HA AFFRONTATO TITANI E DÈI!$B$BSORGI, MIO PADRONE! LIBERATI DAI TUOI VINCOLI!",
}
T[7541] = {
  title = "Al Servizio dell'Orda",
  reward = "Ci vorrà tempo perché i nostri studiosi esaminino il ciondolo che ci hai portato. Ma per il tuo servizio all'Orda vorrei offrirti un piccolo segno di riconoscenza.$B$BGrazie, $N. Le tue azioni fanno onore a te, e a noi.",
  en_title = "Service to the Horde",
}
T[7562] = {
  title = "Mor'zul Bloodbringer",
  desc = "$N, ti sei $Gaddentrato:addentrata; a fondo nelle arti oscure. Il tuo dominio sugli abitanti degli altri mondi è diventato così forte... forse sei $Gpronto:pronta; a legare a te uno dei famigerati dreadsteed.$B$BIl rituale per evocare la bestia dalla sua dimora richiede grande potere e grandi risorse, ma se desideri dominare quella cavalcatura epica, parla con Mor'zul Bloodbringer. È accampato vicino all'Altare delle Tempeste, nelle Burning Steppes.$B$BVai, $N. Questa missione sarà pericolosa, ma $Guno Stregone:una Strega; della tua levatura non si tira indietro davanti al pericolo!",
  obj = "Parla con Mor'zul Bloodbringer nelle Burning Steppes.",
  reward = "Salute, $N, e $Gbenvenuto:benvenuta;. Sei qui per studiare vicino all'Altare delle Tempeste come me, magari per imbrigliarne l'energia per qualche scopo nascosto...$B$BO... sei qui per parlare con me? Sì, credo proprio di sì.$B$BVuoi sottomettere un dreadsteed? Non è cosa facile. Ti costerà non poco sangue, sudore... e naturalmente oro. Ma un dreadsteed di Xoroth è un premio che vale la pena conquistare, quindi, se ti interessa, continua ad ascoltare...",
}
T[7563] = {
  title = "La Furia del Sangue",
  desc = "I dreadsteed vivono su un altro mondo, nelle infuocate Pianure di Xoroth, e per legare a te una di quelle celebri bestie devi invocare glifi potenti. Posso tracciarli per te su una pergamena, ma prima mi servirà un inchiostro speciale.$B$BNella lontana Winterspring vive una razza di owlbeast. Un tempo erano creature pure, ma le emanazioni demoniache della Gola di Darkwhisper le hanno fatte impazzire, e ora vagano per le nevi in preda alla frenesia.$B$BÈ il loro sangue che mi serve per scrivere la tua pergamena. Portamelo.",
  obj = "Porta 30 bottiglie di Raging Beast's Blood a Mor'zul Bloodbringer nelle Burning Steppes.",
  progress = "Hai visto gli owlbeast furenti, $N? La magia di quelle creature è forte, e si concentra nel sangue che scorre nei loro corpi straziati.",
  reward = "Ah, molto bene. Farò distillare questo sangue in un inchiostro e lo userò per la pergamena che ti ho promesso. E magari ne terrò giusto un po' per me, perché ho sentito che il suo sapore dà una certa euforia...",
}
T[7564] = {
  title = "Wildeyes",
  desc = "Il mio servo, Gorzeeki, è un alchimista di una certa abilità. Può preparare l'inchiostro che mi servirà per la tua pergamena. Ho messo insieme il sangue che hai recuperato; portalo a Gorzeeki, così potrà mettersi al lavoro.",
  obj = "Porta la Case of Blood a Gorzeeki Wildeyes nelle Burning Steppes.",
  progress = "Hai qualcosa per me? Non sarà mica un bel ragno grosso e succoso, vero? O magari uno scarafaggio? Spero sia ancora vivo... mi piace tanto masticarli quando sono ancora vivi...",
  reward = "Oh, è sangue. Allora deve venire da padron Mor'zul. Ne è così invaghito, e adora vederlo versato. Io, invece, lo preferisco quando scorre nelle vene di un piccolo roditore. Così resta caldo... finché non ti viene voglia.$B$BQuesto è sangue potente. Mor'zul starà preparando un'altra pergamena per evocare un dreadsteed! Che emozione!$B$BSe è così, e sarai tu a compiere il rituale, allora... ti servirà molto più del sangue, $Gamico mio:amica mia;.",
}
T[7581] = {
  title = "I Leganti della Prigione",
  desc = "Devi procurarti dai demoni minori i leganti per la prigione del Demone Guardiano.$B$BIl sangue dei satiri Wildspawn che occupano Dire Maul dovrebbe andare benissimo. Il sangue coagulato legherà i frammenti di Hederine e alimenterà la prigione di cristallo.",
  obj = "Vai a Dire Maul, a Feralas, e recupera 15 Satyr Blood dai Wildspawn Satyr che abitano Warpwood Quarter. Quando hai finito, torna da Daio the Decrepit a Tainted Scar.",
  progress = "Va bene soltanto il sangue dei satiri Wildspawn.",
  reward = "Ah, un recupero davvero eccellente. Il sangue annullerà le difese magiche del Demone Guardiano.",
}
T[7582] = {
  title = "L'Involucro della Prigione",
  desc = "I demoni Hederine che occupano le pendici del Mount Hyjal secernono potenti veleni vili che, se lasciati maturare, si induriscono in un denso cristallo antimagia. Questi cristalli sono ormai noti come Lacrime di Hederine.$B$BNemmeno l'immenso potere di un Demone Guardiano potrebbe infrangere le pareti di una prigione costruita con questo materiale.$B$BVai alla Gola di Darkwhisper, a Winterspring, e recupera le Lacrime.",
  obj = "Vai alla Gola di Darkwhisper, a Winterspring, e recupera 5 Tears of the Hederine dai demoni Hederine che occupano la gola. Quando avrai portato a termine il compito, torna da Daio a Tainted Scar.",
  progress = "Gli Hederine non cederanno le loro preziose gemme senza combattere, $N.",
  reward = "Mi basta unire il sangue dei Wildspawn a questi cristalli e la prigione sarà pronta all'uso.",
}
T[7583] = {
  title = "Repressione",
  desc = "La prigione è pronta. Ora viene la parte più difficile del compito.$B$BDevi trovare e catturare un Demone Guardiano Comandante nella Cicatrice Contaminata usando questa prigione di cristallo.$B$BTi avverto! Un Demone Guardiano è un avversario astuto e letale, e cercherà di distruggerti appena comincerai il rituale di imprigionamento. Si dimenerà furiosamente nel tentativo di sfuggire alla prigionia.$B$BNon penserà ad altro che a te, $N. Per questo devo raccomandarti di portare dei compagni capaci di tenerti in vita!",
  obj = "Avventurati a Tainted Scar e trova un Doomguard Commander.$B$BUsa la Glowing Crystal Prison sul Doomguard Commander. Preparati a una raffica feroce di attacchi, mentre il demone cerca di sfuggire alla cattura.$B$BSe ci riesci, riporta l'Imprisoned Doomguard a Daio, a Tainted Scar.",
  progress = "Hmm? Allora?",
  reward = "Hai fatto come ti avevo chiesto. Sei $Gpronto:pronta; a ricevere la conoscenza per evocare e controllare la bestia.",
}
T[7601] = {
  title = "Ciò che Niby Comanda",
  desc = "Se vuoi che ti insegni i segreti dell'evocazione di un servo infernale, devi distruggere Kroshius e portarmi il nucleo infernale dai suoi resti ardenti. Non è però facile come sembra. Kroshius si è spento quasi del tutto. Devi riaccendere il suo cadavere e farlo risorgere dalle macerie. Per riuscirci, però, devi raccogliere alcuni componenti da altre entità demoniache.$B$BIl mio imp, Impsy, ti metterà sulla buona strada.",
  obj = "Parla con Impsy a Felwood.",
  reward = "Oh mamma, ci risiamo.",
}
T[7602] = {
  title = "Vil Essenza Perfetta",
  desc = "Se vuoi rianimare Kroshius, ti servirà il Vil fuoco. Il Vil fuoco posso crearlo io, ma ci vorranno alcuni componenti.$B$BDevi portarmi delle Vil essenze perfette da tre diverse regioni del mondo.$B$BI Satiri Legashi di Azshara hanno il primo tipo di essenza; i legionari di Jaedenar, a Jaedenar, il secondo e le vilguardie avvistatrici delle Blasted Lands il terzo.$B$BPortami un'essenza per tipo e creerò il Vil fuoco, con cui potrai rianimare Kroshius.",
  obj = "Impsy, a Felwood, ti ha chiesto di portargli tre Flawless Fel Essences provenienti da tre luoghi diversi.$B$BI Legashi Satyrs di Azshara hanno la Flawless Fel Essence della loro regione. I Jaedenar Legionnaires di Jaedenar hanno la Flawless Fel Essence della loro regione. Le Felguard Sentries delle Blasted Lands hanno la Flawless Fel Essence della loro regione.$B$BRecupera le Flawless Fel Essences e torna da Impsy a Felwood.",
  progress = "Non dirlo a nessuno, ma Niby è uno svitato.",
  reward = "Dammi un minuto e unirò le essenze per farne Vil fuoco.",
}
T[7603] = {
  title = "Il Nucleo Infernale di Kroshius",
  desc = "Kroshius giace ridotto a un mucchio a nord-est, nella Valle dei Crateri Infernali. Prendi questo Vil fuoco e usalo sui suoi resti. Il fuoco dovrebbe rianimare l'infernale caduto.$B$BA quel punto mi aspetto proprio che uccida te e tutti gli amici che avrai portato — e fidati, qualche amico ti conviene portarlo.$B$BSe per qualche miracolo dovessi uccidere Kroshius, prendi il suo nucleo infernale e portalo a Niby.",
  obj = "Cerca i resti di Kroshius a Shatter Scar Vale, a Felwood. Quando li trovi, usa il Fel Fire lì vicino e aspetta il ritorno di Kroshius. Quando l'infernale si sarà risvegliato, uccidilo e prendi dal suo cadavere Kroshius' Infernal Core.$B$BPorta Kroshius' Infernal Core a Niby the Almighty a Felwood.",
  progress = "Ti sei $Gperso:persa;?",
  reward = "Un patto è un patto! Presto, tieni questo e prendi nota. Non ho tempo! La mia più grande evocazione sta per compiersi!",
}
T[7604] = {
  title = "Un Contratto Vincolante",
  desc = "$GIl sottoscritto:La sottoscritta; dichiara con la presente che il lingotto di Sulfuron che sta consegnando alla Thorium Brotherhood (TB Ltd.) è autentico e non una sua riproduzione. $GIl sottoscritto:La sottoscritta; riconosce inoltre che qualsiasi danno $Ggli:le; dovesse derivare dal tentativo di costruire, forgiare, trovare, creare, vendere o mangiare Sulfuras non è responsabilità né colpa della TB Ltd.$B$BFirmando questo contratto accetti tutte le condizioni qui elencate.$B$B_________________$B$BFirma",
  obj = "Consegna il Thorium Brotherhood Contract a Lokhtos Darkbargainer se vuoi ricevere i progetti di Sulfuron.",
  progress = "Affare fatto?",
  reward = "È stato un piacere fare affari con te, $N!$B$BA nome della TB Ltd., ti auguro buona fortuna nella ricerca di Sulfuras!",
}
T[7621] = {
  title = "Un Avvertimento",
  reward = "$GSacerdote:Sacerdotessa;, stai per affrontare una dura serie di eventi che metterà alla prova tutte le tue capacità.$B$BTi consiglio di ascoltare la storia che ho da raccontare.$B$BBada, devi portare a termine questo compito da $Gsolo:sola;. È consigliabile che i tuoi alleati restino a distanza. L'interferenza di estranei comporterà una punizione severissima.$B$BIl destino ha condotto qui te e te soltanto. Combatti con onore. Incanala la Luce.",
}
T[7622] = {
  title = "L'Equilibrio fra Luce e Ombra",
  desc = "Devi fare ciò che io non ho potuto: salvare i popolani che furono falciati mentre fuggivano da Stratholme.$B$BCammineranno verso la luce, tu devi fare in modo che sopravvivano. Se ne cadranno troppi, la nostra esistenza maledetta continuerà — avrai fallito.$B$BOgni abilità, preghiera e incantesimo che hai imparato sarà messo alla prova. Che la Luce ti protegga, $N.",
  obj = "Salva 50 Peasants prima che ne vengano uccisi 15. Se riesci nell'impresa, parla con Eris Havenfire.$B$BPuoi guardare il Death Post per vedere quanti Peasants sono stati uccisi.",
  reward = "La tua tenacia e il tuo coraggio sono sbalorditivi, $Gsacerdote:sacerdotessa;. Ti sei $Gguadagnato:guadagnata; il diritto di portare la Scheggia di Nordrassil. Resta un solo compito: l'Occhio dell'Ombra va recuperato. Setaccia il mondo.",
}
T[7623] = {
  title = "Lord Banehollow",
  desc = "Mor'zul dice che vuoi aprire un portale per Xoroth. Per farlo ti servirà della polvere stellare di Xoroth. Non è facile trovarla su Azeroth!$B$BC'è un essere che potrebbe averne: Lord Banehollow, a Jaedenar, la sede del Concilio dell'Ombra! Parlagli e forse te ne cederà un po'.$B$BMa se vai a Jaedenar dovrai ammantarti di quel male tutto particolare del Concilio dell'Ombra. Per questo servono alcune delle mie pozioni dell'ombra, e quelle ti costeranno...",
  obj = "Compra le Shadowy Potions da Gorzeeki Wildeyes nelle Burning Steppes.$B$BUsa le pozioni per attraversare Jaedenar e parla con Lord Banehollow.",
  reward = "La mia pazienza abbraccia i millenni, $C. Ma non credere che questo ti conceda più di un istante del mio tempo...",
}
T[7624] = {
  title = "Ulathek il Traditore",
  desc = "Vuoi entrare nelle mie grazie? Allora uccidi per me.$B$BIl mio servo, Ulathek, è patetico per come striscia ai miei piedi, e intanto trama con Lord Hel'nurath su Xoroth. Hel'nurath vuole usurpare il mio potere qui, e Ulathek è la sua spia...$B$BDimostra che servi me e non i miei rivali. Affronta Ulathek nei suoi alloggi, nell'Eremo delle Ombre, a ovest. Digli che conosco il suo segreto e guarda la paura impadronirsi di lui. Poi portami il cuore del traditore!",
  obj = "Affronta Ulathek, poi porta The Traitor's Heart a Lord Banehollow a Jaedenar.",
  progress = "Sento già sulle labbra il sapore del cuore di Ulathek. Com'è dolce la carne di un traditore...",
  reward = "Ah, che meraviglia! Dopo una settimana a marcire, questo cuore sarà una ghiottoneria succulenta! Forse manderò a prendere la testa di Ulathek per tenerla davanti a me mentre mangio...$B$BMi hai reso un servigio, $C, e perciò la mia pazienza verso di te è cresciuta. Di poco.",
}
T[7625] = {
  title = "Polvere Stellare di Xoroth",
  desc = "E così vieni da me in cerca di polvere stellare di Xoroth? Vuoi aprire un portale per Xoroth, il dominio di Hel'nurath, il mio rivale? Magari hai in mente di rubargli uno dei suoi preziosi maldestrieri?$B$BMolto bene. Il mio servitore Ur'dan ha una scorta di polvere stellare di Xoroth. Puoi ottenerla da lui... se sei in grado di pagarne il prezzo.",
  obj = "Compra la Xorothian Stardust da Ur'dan. Portala a Gorzeeki Wildeyes nelle Burning Steppes.",
  progress = "Sei $Gstato:stata; a Jaedenar, $N? Hai avuto la polvere stellare da Lord Banehollow?",
  reward = "Eccola! Quasi non ci credo che ce l'hai! Devi aver concluso un grosso affare con quel Signore del Terrore, o aver pagato una bella somma, o tutte e due le cose!$B$BMor'zul avrà il suo inchiostro molto presto, e allora potrà finalmente preparare la pergamena dei glifi, così potrai aprire un portale per Xoroth e tirarne fuori uno dei famosi maldestrieri!",
}
T[7626] = {
  title = "Campana di Dethmoora",
  desc = "Una Campana di Dethmoora, che prende il nome dal defunto stregone Dethmoora Darkeyes, è uno dei tre strumenti necessari per creare un Cerchio di Evocazione Superiore. Quando la campana è accordata a dovere con la Ruota e la Candela, questi oggetti incanalano immense riserve di potere arcano.$B$BIl mio servitore Gorzeeki può costruire una campana del genere, ma per farlo gli servirà una grossa scorta di elisir del potere dell'ombra. Procurati gli elisir da un alchimista e portali a Gorzeeki.",
  obj = "Porta 10 Elixirs of Shadow Power a Gorzeeki Wildeyes nelle Burning Steppes.",
  progress = "Hai quegli elisir, $N? Mor'zul mi ha detto che ti serve una Campana di Dethmoora, e per farne una ci vuole un sacco di potere dell'ombra!",
  reward = "Molto bene! Spero che questi elisir non siano stati troppo difficili da trovare. A volte gli alchimisti sanno essere così avari con le loro creazioni...$B$BFarò la campana e la terrò io finché non sarai $Gpronto:pronta; per il tuo rituale.",
}
T[7627] = {
  title = "Ruota della Marcia Nera",
  desc = "Una Ruota della Marcia Nera contiene e dirige le energie violente necessarie al Cerchio di Evocazione Superiore. Per costruire una ruota, a Gorzeeki serviranno sia dei grossi frammenti splendenti da un incantatore, sia del minerale di dark iron da un maestro minatore.$B$BProcurateli e portali al mio servitore.",
  obj = "Porta 6 Large Brilliant Shards e 25 Dark Iron Ore a Gorzeeki nelle Burning Steppes.",
  progress = "La Ruota della Marcia Nera non è facile da fare, e richiede un sacco di materiali. Li hai già raccolti?",
  reward = "Eccoli! Ho sentito che il minerale di dark iron si trova solo nelle profondità di Blackrock, e sono sicuro che nemmeno questi frammenti sono stati facili da trovare. Resto spesso sbalordito dalla dedizione che avete voi stregoni. Se invece metteste tutta quell'energia nell'arte di acchiappare insetti, oh... che banchetto vi godreste!$B$BScusa, una piccola digressione. Creerò la ruota e te la terrò da parte finché non sarai $Gpronto:pronta; per il tuo rituale.",
}
T[7628] = {
  title = "Candela del Giorno del Giudizio",
  desc = "Una Candela del Giorno del Giudizio accumula il fuoco e lo dirige contro chi vorrebbe disturbare il tuo rituale. Mentre crei il tuo Cerchio di Evocazione Superiore, se la candela è accesa ogni demone ribelle verrà bruciato dalle sue fiamme!$B$BContenere quel fuoco non è facile, e richiede l'essenza racchiusa nelle scaglie di un drago nero. Procurati quelle scaglie da uno scuoiatore e portale a Gorzeeki Wildeyes.",
  obj = "Porta 35 Black Dragonscales a Gorzeeki Wildeyes nelle Burning Steppes.",
  progress = "Hai portato le scaglie di drago, $N? Non voglio mettermi a fare la candela finché non le ho... o rischio di far saltare in aria tutto l'accampamento!",
  reward = "Ah, molto bene. Mi serviranno per contenere i fuochi della candela. Ora che ho le scaglie, farò la candela e la terrò da parte finché non sarai $Gpronto:pronta; a cominciare il tuo rituale per il Cerchio di Evocazione Superiore.",
}
T[7629] = {
  title = "Consegna dell'Imp",
  desc = "Per la pergamena di Mor'zul serve ancora un procedimento; mi occorre della carta impregnata di polvere stellare di Xoroth. E... temo di non poterlo fare qui. Non ho l'attrezzatura!$B$BC'è però un laboratorio di alchimia con tutto il necessario. È a Scholomance, sull'isola di Caer Darrow, nelle Plaguelands.$B$BIo non posso fare il viaggio, ma tieni — prendi questo barattolo. Dentro c'è un imp parecchio sveglio. Liberalo nel laboratorio di alchimia e ci penserà lui a impregnare la pergamena.",
  obj = "Porta l'Imp in a Jar all'Alchemy Lab di Scholomance. Quando la pergamena sarà stata creata, riporta il barattolo a Gorzeeki Wildeyes.",
  progress = "Sei $Gstato:stata; a Scholomance, $N? L'imp ha già impregnato la pergamena con la polvere stellare?",
  reward = "Ah, bene. J'eevee ha creato la pergamena. Com'era Scholomance? Incantevole, non trovi? E gli insetti di lì... dicono che siano deliziosi!$B$BBen fatto, $N, e grazie di avermi riportato il barattolo. Ce l'ho da tanto tempo... e non è in vendita!",
}
T[7630] = {
  title = "Arcanite",
  desc = "Ora che la Campana, la Ruota e la Candela sono fatte, dovrei preparare una magnetite nera. Durante il rituale ti servirà per tenere in funzione gli altri oggetti rituali, se dovessero cedere.$B$BPer fare la magnetite mi occorre dell'arcanite. Ne hai? Se no, allora... dovrai procurarti l'arcanite da un alchimista.$B$BTorna da me quando avrai l'arcanite, e allora farò la magnetite nera.",
  obj = "Porta 3 Arcanite Bars a Gorzeeki nelle Burning Steppes.",
  progress = "Hai l'arcanite, $N? Appena ce l'ho posso farti la magnetite nera.",
  reward = "Ce l'hai! Ottimo lavoro! Ora posso creare la magnetite. Quando finalmente sarai $Gpronto:pronta; per il rituale che crea il Cerchio di Evocazione Superiore, ti servirà una magnetite per evitare che il rituale faccia cilecca!",
}
T[7631] = {
  title = "Maldestriero di Xoroth",
  desc = "Tutti i preparativi sono fatti. Ora devi compiere il rituale per creare un Cerchio di Evocazione Superiore, e poi usare la pergamena impregnata di polvere stellare di Xoroth... per aprire un portale per Xoroth.$B$BHo scritto le istruzioni del rituale su un rotolo. Studialo con attenzione, perché se vuoi riuscirci devi eseguire ogni passo con esattezza.$B$BBuona fortuna, $N. E che le anime dei tuoi nemici trovino presto la strada per la tua sacca dei frammenti.",
  obj = "Leggi Mor'zul's Instructions. Evoca uno Xorothian Dreadsteed, sconfiggilo e poi lega a te il suo spirito.",
  reward = "Lo spirito del Maldestriero di Xoroth è sconfitto. Anche se la rabbia pulsa nei suoi fianchi spettrali, sai che l'anima della bestia è tua...$B$BTi sussurra nella mente una magia oscura e ti infonde la conoscenza per evocare un maldestriero.",
}
T[7632] = {
  title = "La Foglia Antica",
  desc = "L'epidermide della foglia brilla di un verde acceso. La superficie è estremamente rugosa e mostra diverse nervature e grinze.$B$BSe dovessi tirare a indovinare, diresti che questa foglia viene da qualcosa di antico e potente.$B$BForse dovresti trovare il proprietario originario di questa foglia?",
  obj = "Trova il proprietario dell'Ancient Petrified Leaf. Buona fortuna, $N; il mondo è grande.",
  progress = "<Vartrus geme.>",
  reward = "Certo che riconosco le mie foglie. Ma guarda! È in perfette condizioni.$B$BÈ stato gentile da parte tua riportarla, $C.$B$BForse potresti essere utile a noi, e noi a te.",
}
T[7633] = {
  title = "Una Presentazione",
  reward = "La tua diligenza e la tua integrità non sono passate inosservate, $C.$B$BNoi siamo Antichi: Protettori di questa foresta un tempo grandiosa. Le nostre forme fisiche furono distrutte 10.000 anni fa, quando Archimonde e la Legione Infuocata marciarono su Hyjal. I nostri spiriti, però, restano intatti.$B$BCi sono compiti che possiamo offrire. Compiti che, se portati a termine, ti schiuderanno i segreti degli Antichi.$B$BSappi questo, se porterai a termine questi compiti, ti basterà tornare a questa roccia e noi risponderemo alla chiamata.",
}
T[7634] = {
  title = "Antica Lamina Avvolta nel Tendine",
  desc = "Salute a te, $C. Io sono Hastat, Antico della Sapienza. Custodisco conoscenze perdute eoni fa.$B$BCon la legatura giusta, una delle mie foglie può servire da faretra, di quelle che non si vedono da 10.000 anni. Una faretra che, accompagnata da un arco degli Antichi, potrebbe conferire poteri indicibili.$B$BTorna qui con il tendine di un drago blu adulto e questa faretra sarà tua.",
  obj = "Hastat the Ancient ti ha chiesto di portargli un Mature Blue Dragon Sinew. Se trovi questo tendine, portalo a Hastat, a Felwood.",
  progress = "$GBentornato:Bentornata;, giovane $C.",
  reward = "Che le mie foglie proteggano le tue frecce da ogni danno. Che le tue frecce colpiscano nel segno. Che i nemici del nostro mondo siano abbattuti.",
}
T[7635] = {
  title = "Una Corda Come si Deve",
  desc = "Vartrus potrà anche offrirti l'asta per creare un arco degli Antichi, ma solo io posso incantare la corda necessaria a completarlo.$B$BÈ un compito semplice, creatura insignificante. Uccidi un drago nero adulto e staccagli il tendine dalle ossa. Riportami quel tendine e io incanterò il materiale fino a farne una corda d'arco quasi indistruttibile.",
  obj = "Stoma the Ancient ti ha chiesto di portargli un Mature Black Dragon Sinew. Se trovi questo tendine, portalo a Stoma, a Felwood.",
  progress = "Sono certo che non avrai grandi difficoltà a trovare e uccidere un drago nero, $N. Non farmi perdere tempo con chiacchiere inutili.",
  reward = "Era un drago davvero immondo, questo. Il tendine puzza di malvagità.$B$BDammi un momento per ripulire questa carne dal sudiciume e applicare gli incantamenti giusti.",
}
T[7636] = {
  title = "Asta degli Antichi",
  desc = "Gli agenti della Legione Infuocata sono ancora attivi nel nostro mondo, $C. Questi agenti corrompono tutto ciò che toccano. In loro presenza la natura appassisce e piange.$B$BDevi scovare questi corruttori demoniaci e distruggerli, $N. Bada, devi affrontarli da $Gsolo:sola;, altrimenti fuggiranno. Finché sarai $Gsolo:sola;, cercheranno di distruggerti. Devi colpirli, trasformando la loro arroganza in sofferenza.$B$BTi concedo un pezzo della mia corteccia, le iscrizioni ti guideranno ai tuoi bersagli. Recupera le loro teste.",
  obj = "Devi trovare e distruggere questi quattro corruttori demoniaci:$B$BSimone the Seductress.$B$BKlinfran the Crazed.$B$BSolenor the Slayer.$B$BArtorius the Doombringer.$B$BDistruggi queste creature e torna da Vartrus the Ancient, a Felwood, con le loro teste.$B$BConsulta la Petrified Bark nel tuo inventario per trovare indizi su dove si trovano.$B$BDEVI portare a termine questo compito da $Gsolo:sola;.",
  progress = "Non farti ingannare dai loro travestimenti!",
  reward = "Ci hai servito bene, $N! Prendi quest'asta e uniscila alla corda d'arco che Stoma è in grado di creare. Insieme formano un'arma davvero formidabile.",
}
T[7637] = {
  title = "L'Accento sul Sacrificio",
  desc = "Per prepararti a questo compito, devi prima dar prova del dovuto sacrificio e del dovuto giudizio... con l'accento sul sacrificio.$B$BPer il tuo compito devi procurarti l'incensiere per esorcismo del Sommo Sacerdote Rohan. Anche se sarà usato per ragioni buone e giuste, va dato in cambio il dovuto compenso.$B$BVai a Ironforge e parla con il Sommo Sacerdote. Portando con te denaro in abbondanza per compensare la perdita del suo incensiere, darai prova del dovuto sacrificio.$B$BVai ora, $N, il tempo stringe.",
  obj = "Vai a Ironforge e procurati l'Exorcism Censer di High Priest Rohan. Per averlo dovrai fare una donazione di 150 monete d'oro.",
  progress = "Salute, nobile $GPaladino:Paladina;! Ho preparato il mio fidato incensiere con l'incenso più fresco e l'ho benedetto tre volte perché tu possa usarlo. La tua donazione ci aiuterà, qui a Ironforge, non solo a fabbricare un nuovo incensiere, ma anche a rimpolpare le magre scorte di cibo per i nostri bisognosi.",
  reward = "Che tu sia $Gbenedetto:benedetta;, $Gamico:amica; $C! La tua donazione va ben oltre il necessario. Il tuo sacrificio non ci aiuterà soltanto a recuperare quello che abbiamo perso, ma anche ad aiutare chi ha più bisogno qui a Ironforge.$B$BOra fammi controllare di aver preparato a dovere questo incensiere per ciò che ti servirà...",
}
T[7638] = {
  title = "Lord Grayson Shadowbreaker",
  desc = "È giunto il momento, $N, che tu sappia cosa ci vorrà per ottenere una cosa che senza dubbio aspetti da tempo... il tuo destriero.$B$BParla con Lord Grayson Shadowbreaker, qui nel Quartiere della Cattedrale di Stormwind. Sarà lui a guidarti non solo fra gli arcani della cavalcatura più fidata di un Paladino, ma anche nelle prove che ti aspettano per ottenerne una tua.$B$BTi auguro ogni bene in questa prova. Per la Luce, nobile $Gfratello:sorella;!",
  obj = "Parla con Lord Grayson Shadowbreaker, nel Cathedral District di Stormwind.",
  reward = "Sono lieto di vederti, $N. So che aspettavi di sapere come ottenere il tuo destriero, e ora quel momento è arrivato.$B$BSarai senz'altro $Gmesso:messa; alla prova in molti modi diversi, ma soprattutto nella tua volontà di superare i tanti ostacoli che ti verranno posti davanti. Non sono pensati come un esercizio per imparare — la tua statura va oltre le semplici prove di apprendimento. Devi salvare il tuo futuro compagno dalle grinfie del male che hai combattuto per tutta la vita.$B$BFa' attenzione, il tuo momento è arrivato!",
}
T[7639] = {
  title = "Dar Prova del Dovuto Giudizio",
  desc = "Prendi l'incensiere, con la mia benedizione. L'ho usato io stesso in diversi esorcismi, e dovrebbe esserti molto utile negli ardui compiti che ti aspettano.$B$BOra torna da Lord Grayson Shadowbreaker, a Stormwind, $N. La tua missione continua con lui.",
  obj = "Riporta Rohan's Exorcism Censer a Lord Grayson Shadowbreaker, nel Cathedral District di Stormwind.",
  progress = "$GBentornato:Bentornata;, $N. Hai ottenuto l'incensiere per esorcismo?",
  reward = "Sì, questo andrà bene. Durante questo percorso ti sarà chiesto più di una volta di compiere atti di sacrificio; sono lieto di vedere che sei $Gdisposto:disposta; a farlo. Il sacrificio è una parte essenziale di ciò che serve per tener fede ai doveri di un Paladino... ma non c'è bisogno che ti faccia la predica.$B$BOra, $N, dovrai dar prova del dovuto giudizio nelle tue azioni. A questo scopo, l'incensiere sarà il tuo strumento per dispensare tale giudizio sugli spiriti tormentati delle terre che abbiamo perduto.",
}
T[7640] = {
  title = "Esorcizzare Terrordale",
  desc = "Ho aggiunto all'incensiere un pizzico di terra del suolo contaminato di Terrordale, nelle Eastern Plaguelands. Ora userai questo incensiere per trovare, laggiù, le zone che mostrano segni di tumulto e turbamento spirituale. Cerca le aure verdi che impregnano il terreno, là dove il mondo fisico cede sotto il tormento del regno degli spiriti, e usa l'incensiere per scacciare gli spiriti maligni.$B$BQuando avrai giudicato un numero sufficiente di spiriti laggiù, sarai $Gpronto:pronta; a proseguire.",
  obj = "Usa l'Exorcism Censer per scacciare gli spiriti che tormentano Terrordale. Quando avrai ucciso 25 Terrordale Spirits, torna da Lord Grayson Shadowbreaker, nel Cathedral District di Stormwind.",
  progress = "È bello rivederti, $N. Hai finito il tuo lavoro a Terrordale?",
  reward = "Ben fatto, $N. Portare il giudizio della Luce su coloro che dimorano nelle tenebre è un compito che dobbiamo affrontare con vigore e zelo; tu hai fatto proprio questo, con il tuo sacrificio a Ironforge e i tuoi giudizi sugli spiriti di Terrordale.$B$BI tuoi prossimi passi richiederanno ancora sacrificio e giudizio insieme, perché ora dovrai impegnarti a riprenderti lo spirito di un destriero caduto, che oggi serve un Cavaliere della Morte noto come Darkreaver.",
}
T[7641] = {
  title = "Il Lavoro di Grimand Elmore",
  desc = "Senza una bardatura adeguata, il destriero da guerra di un paladino non è altro che una bestia da soma. La bardatura del tuo destriero non solo dev'essere fatta dei migliori materiali che esistano, ma, date le circostanze, deve anche essere in sufficiente sintonia con il regno degli spiriti.$B$BAndiamo con ordine, $N — cominciamo col farti fare la bardatura. Nel Distretto dei Nani di Stormwind c'è uno dei migliori artigiani viventi, Grimand Elmore. Il suo lavoro non costerà poco, ma è la sua qualità che cerchiamo. Parla con lui.",
  obj = "Parla con Grimand Elmore a Dwarven District, a Stormwind.",
  reward = "Salve — Lord Shadowbreaker mi ha avvisato per tempo che saresti $Gpassato:passata; da queste parti a trovarmi. Sono disposto a farti la bardatura che ti serve, ma non sarà né economico né facile; mettiamolo in chiaro prima di ogni altra cosa.$B$BTi dico solo questo, e Grayson potrà confermartelo... una bardatura migliore di quelle che si fanno qui non la troverai da nessuna parte, in tutta Azeroth.",
}
T[7642] = {
  title = "Raccolta di Materiali",
  desc = "Per la bardatura ti serviranno quattro cose — runecloth per la fodera, barre d'arcanite per le piastre, Lacrime di Arthas per la sintonia spirituale e acqua santa di Stratholme per l'infusione spirituale. Anzi, te ne servono cinque... l'oro per il mio compenso. Nel compenso sono compresi tutta la manodopera, una sella fatta a mano e le staffe.$B$BQuando avrai tutto, potrò finire la tua bardatura. Nel frattempo, mentre metti insieme la tua raccolta di materiali, ci sono alcune cose che posso cominciare a prepararti.",
  obj = "Porta 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 fiale di Stratholme Holy Water e 150 monete d'oro a Grimand Elmore a Dwarven District, a Stormwind.",
  progress = "Ah, $C. Senza le cose che ti ho detto non potrò finire la tua bardatura. Hai messo insieme tutto?",
  reward = "Questo... beh, è esattamente quello che mi serviva. Sei proprio $Gun:una; $C $Gpieno:piena; di risorse, eh?$B$BBene, allora finiamo questa tua bardatura!",
}
T[7643] = {
  title = "Antico Spirito Equino",
  desc = "La tua bardatura ha bisogno di una benedizione particolare, quella di uno spirito adatto. A Dire Maul c'è uno spirito così, l'Antico Spirito Equino. Al momento lo tiene prigioniero un treant corrotto, Tendris Warpwood. Emetti il tuo giudizio su quella bestia immonda, $N.$B$BSappi questo — la libertà da sola non basta. Dovrai placare lo spirito prima di ricevere la sua benedizione. Per farlo serve una biada speciale. Prima vai a Southshore e parlane con Merideth Carlson... e preparati a sacrificare ancora.",
  obj = "Procurati la biada speciale che serve a nutrire un cavallo spirituale. A quanto pare è Merideth Carlson, a Southshore, a fornire questo cibo.$B$BVai nel dungeon di Dire Maul, a Feralas, e uccidi Tendris Warpwood. Così libererai l'Ancient Equine Spirit. Dagli da mangiare la biada speciale, in modo da placarlo. Infine dagli l'Arcanite Barding, perché la benedica.",
  progress = "L'Antico Spirito Equino ti guarda in attesa, come se volesse qualcosa da te.",
  reward = "L'Antico Spirito Equino accetta l'offerta della Biada Ricostituente Arricchita e strofina il muso sul contenitore mentre si serve dell'avena e dei cereali speciali. Dopo aver mangiato un po', guarda la bardatura che hai con te e si mette in posizione, come se volesse che tu gliela posassi sul dorso...",
}
T[7644] = {
  title = "Bardatura d'Arcanite Benedetta",
  desc = "Posata sul dorso dell'Antico Spirito Equino, la bardatura emana un bagliore appena percettibile. Per un breve istante l'aria è densa di potere, poi la bardatura scompare dal dorso del cavallo e si ritrova al sicuro nel tuo zaino.$B$BA quanto pare la bardatura è stata benedetta. Come da istruzioni di Lord Shadowbreaker, ora dovresti riportargliela a Stormwind.",
  obj = "Torna con la Blessed Arcanite Barding da Lord Grayson Shadowbreaker a Cathedral District, a Stormwind.",
  progress = "$N, sei $Gtornato:tornata;! Sei $Griuscito:riuscita; a vedertela con Merideth Carlson e Tendris Warpwood? Sinceramente, certe volte non so chi dei due sia la minaccia più grande...",
  reward = "Ne hai fatta di strada, $Gamico mio:amica mia;. Ora la tua bardatura è pronta come si deve per l'ultimo compito che ti aspetta.$B$BMetterai questa bardatura al tuo destriero da guerra una volta compiuta l'opera di redenzione. Prima, però, dovrai vincere una lotta immane. La tua ora si avvicina — urrà!$B$BC'è un ultimo oggetto da fabbricare prima di cominciare, $N. Spero che la tua intraprendenza non ti abbia abbandonato da quando ti sei $Gfatto:fatta; fare la bardatura...",
}
T[7645] = {
  title = "Biada Ricostituente Arricchita",
  desc = "La Mano d'Argento mi ha presa per PAZZA quando ho detto che sapevo fare una biada speciale capace di nutrire i cavalli spirituali. TUTTI mi hanno presa per pazza! Beh, adesso è l'ora della rivincita!$B$BTi farò quello che ti serve, $GPALADINO:PALADINA;... $Gcosiddetto CAMPIONE:cosiddetta CAMPIONESSA;... ma ti costerà. Per questa miscela mi servono dei biscotti speciali — i Biscotti Ricostituenti Arricchiti, che vende solo l'Argent Dawn. E poi pretendo, sì, PRETENDO dell'oro, come risarcimento per le sofferenze che ho patito!$B$BFammi vedere il sacrificio di cui ti vanti tanto, $GPALADINO:PALADINA;.",
  obj = "Recupera 20 Enriched Manna Biscuits — l'ingrediente principale per preparare la Manna-Enriched Horse Feed — per Merideth Carlson a Southshore, nelle Hillsbrad Foothills. Si sa che l'Argent Dawn è l'unico fornitore di questi biscotti.$B$BDevi anche darle 50 monete d'oro per lenire il suo amor proprio ferito.",
  progress = "Sì, te l'ho dimostrato che avevi torto, eh? L'ho dimostrato a tutti quanti! AVEVO RAGIONE IO FIN DALL'INIZIO!!!",
  reward = "SÌ, E ADESSO CHI — aspetta — mi dai anche l'oro? Non sei $Gstato:stata; tu a darmi della pazza (anzi, mi hanno dato della svitata fuori di testa)... eppure sei $Gdisposto:disposta; a sacrificarti anche per torti che non hai commesso?$B$BIo... ti avevo giudicato male, $N. Se ti servirà altra biada, vieni da me. Te la darò gratis. Grazie... nobile $C.$B$BI soldi però me li tengo — non sono così svitata da rinunciare a una fortuna.",
}
T[7646] = {
  title = "Il Veggente della Divinazione",
  desc = "Ora dobbiamo assemblare un Veggente della Divinazione — darà inizio alla prova che ti permetterà di redimere il destriero da guerra caduto. Il tuo veggente, in realtà, è quasi finito. L'incensiere per esorcismi usato a Terrordale ne è il catalizzatore, e io costruirò un alloggiamento adatto al congegno.$B$BGli ultimi componenti che servono, però, sono due diamanti. Devono essere opposti per splendore quanto lo sono per scopo — uno di Azeroth e uno Nero Intatto. Saranno loro il faro con cui il veggente squarcerà le ombre!",
  obj = "Porta un Azerothian Diamond e un Pristine Black Diamond a Lord Grayson Shadowbreaker a Cathedral District, a Stormwind.",
  progress = "Ne hai fatta davvero tanta di strada, $N. Il tuo ultimo sacrificio di beni terreni darà origine a una delle tue imprese più grandi. Lo sento in ogni fibra del mio essere!",
  reward = "Sono begli esemplari, $N — ora gli ultimi pezzi sono al loro posto. Finalmente è giunta la tua ora!$B$BNelle profondità del Grande Ossario di Scholomance ci sono i resti scheletrici di molti esseri. Fra loro c'è un destriero da guerra un tempo nobile. L'anima svuotata di questo destriero ora fa da cavalcatura al Cavaliere della Morte Darkreaver. È lui che affronterai, ed è su questa cavalcatura che emetterai il tuo giudizio. Solo tu, $N, puoi redimere la sua anima e salvarla dal tormento della servitù.",
}
T[7647] = {
  title = "Giudizio e Redenzione",
  desc = "Prendi questa bisaccia — dentro ci sono gli oggetti che ti serviranno per il tuo compito.$B$BUsa il veggente della divinazione nel cuore del seminterrato del Grande Ossario per far apparire gli spiriti maledetti che devono essere giudicati. Usa con saggezza i tuoi giudizi durante questa prova — si riveleranno più potenti di quanto credi. Dopo gli spiriti apparirà il cavaliere della morte; sconfiggilo e riprenditi l'anima perduta del destriero da guerra. Solo allora, $N, potrai redimerlo e mettere la tua bardatura sulla tua nuova cavalcatura!$B$BBuona fortuna!",
  obj = "Usa il Divination Scryer nel cuore del seminterrato di Great Ossuary, a Scholomance. Così farai apparire gli spiriti che devi giudicare. Sconfitti questi spiriti, verrà evocato Death Knight Darkreaver. Sconfiggilo e riprenditi l'anima perduta del destriero da guerra caduto.$B$BDai la Charger's Redeemed Soul e la Blessed Arcanite Barding a Darkreaver's Fallen Charger.",
  progress = "Lo spirito del destriero da guerra caduto ti rivolge uno sguardo addolorato. Occhi tristi, quasi vuoti, ti guardano come se per lui ogni speranza fosse perduta.",
  reward = "Un barlume di vita — assente da tempo nella povera bestia — le brilla negli occhi quando le restituisci la sua anima giudicata. Senti un'ondata di potere sacro avvolgerti mentre le posi la bardatura sul dorso, dopo aver giudicato redento il destriero. Il destriero ti strofina il muso sulla mano mentre la bestia viene liberata dal peso del passato. Ora senti di poter chiamare questa bestia a farti da cavalcatura, in caso di bisogno.$B$BHai conquistato il tuo destriero da guerra epico, $C! Congratulazioni!",
}
T[7648] = {
  title = "Il Lavoro Migliore di Grimand",
  desc = "<Grimand si asciuga il sudore dalla fronte, raggiante d'orgoglio.>$B$BEcco qua, $Gamico mio:amica mia;. Questo è uno dei miei lavori migliori — all'altezza della bardatura che ho fatto di persona per Lord Shadowbreaker quando è andato a prendersi il suo destriero da guerra. Ti ringrazio di esserti $Gaffidato:affidata; a me per avere il meglio.$B$BDi sicuro anche Grayson vorrà vedere il lavoro con i suoi occhi. Portagli la tua bardatura, e ringrazialo da parte mia per avermi onorato della sua clientela.",
  obj = "Porta l'Arcanite Barding a Lord Grayson Shadowbreaker a Cathedral District, a Stormwind, perché la esamini.",
  progress = "Stai procedendo bene, $N. Una volta fatta la tua bardatura, sarai sulla buona strada per il prossimo compito.",
  reward = "È un lavoro davvero notevole. A quanto pare, più Grimand invecchia, più la sua maestria migliora. Non è cosa da poco, visto che i suoi lavori erano già fra i migliori in circolazione quando fece la mia bardatura, a suo tempo.$B$BQuesta bardatura farebbe la sua figura su qualsiasi cavalcatura normale, ma qui non abbiamo a che fare con una bestia così ordinaria. Dovrai farla benedire da una fonte adatta perché sia degna di posare sul destriero da guerra di $Gun:una; $C. Fino ad allora te la tengo io.",
}
T[7649] = {
  title = "Armatura a Piastre di Torio Incantato: Volume I",
  desc = "Il tomo porta il marchio dell'Ateneo.",
  obj = "Riporta il libro ai suoi legittimi proprietari.",
  progress = "Hai recuperato un tomo!",
  reward = "Ben fatto, $Gragazzo mio:ragazza mia;.$B$B<Il Custode del Sapere Lydros strappa una pagina dal libro.>$B$BSono sicuro che questa ricetta ti tornerà utile.",
}
