}
T[7652] = {
  title = "Un'Offerta Speciale",
  reward = "Allora, $Gsignore:signora;, c'ho un affarone per te.$B$BSto cercando di sbolognare un po' di queste ricette dell'armatura a piastre Imperiale e mi serve qualcuno disposto ad accollarsi il peso. In cambio voglio solo qualche barra di torio. Ti va?",
}
T[7653] = {
  title = "Cintura a Piastre Imperiale",
  progress = "Per il progetto della cintura mi servono 20 barre di torio.",
  reward = "È un piacere fare affari con te.$B$B$BE $N, levati quell'aria schifata dalla faccia.",
}
T[7654] = {
  title = "Stivali a Piastre Imperiali",
  progress = "Per il progetto degli stivali mi servono 40 barre di torio. Già, 40. Ti metti a piangere? Vuoi un fazzolettino?$B$B<Derotain ride.>",
  reward = "È un piacere fare affari con te.$B$BE $N, levati quell'aria schifata dalla faccia.",
}
T[7655] = {
  title = "Bracciale a Piastre Imperiale",
  progress = "Per il progetto del bracciale mi servono 20 barre di torio.$B$BTutto bene, $Gfigliolo:figliola;? Stai diventando $Gtutto rosso:tutta rossa;.",
  reward = "È un piacere fare affari con te.$B$BE $N, levati quell'aria schifata dalla faccia.",
}
T[7656] = {
  title = "Pettorale di Piastre Imperiale",
  progress = "Per i progetti del pettorale mi ci vogliono 60 barre di torio.$B$B$BMamma mia, ci risiamo. Adesso corri dai tuoi Dei blu a chiedere perché ti hanno abbandonato?!? Tira fuori la grinta, femminuccia! Nessuno ha mai detto che la vita è giusta.",
  reward = "È un piacere fare affari con te.$B$BE $N, levati dalla faccia quell'aria schifata.",
}
T[7657] = {
  title = "Elmo di Piastre Imperiale",
  progress = "Basta che mi dai 50 barre di torio e i progetti dell'elmo sono tuoi.",
  reward = "È un piacere fare affari con te.$B$BE $N, levati dalla faccia quell'aria schifata.",
}
T[7658] = {
  title = "Gambali di Piastre Imperiali",
  progress = "Basta che mi dai 60 barre di torio e i progetti dei gambali sono tuoi.$B$BLo so, ti sto mandando in bancarotta! Le ho già sentite tutte, quindi la storia strappalacrime puoi risparmiartela, pappamolle.",
  reward = "È un piacere fare affari con te.$B$BE $N, levati dalla faccia quell'aria schifata.",
}
T[7659] = {
  title = "Spallacci di Piastre Imperiali",
  progress = "Per i progetti degli spallacci mi ci vogliono 20 barre di torio.",
  reward = "È un piacere fare affari con te.$B$BE $N, levati dalla faccia quell'aria schifata.",
}
T[7660] = {
  title = "Scambio di Lupi — Lupo Artico",
  reward = "Se mi porti il tuo vecchio lupo veloce, te lo cambio con uno del nuovo branco. Il lupo nuovo sarà veloce quanto quello vecchio, ma avrà un aspetto diverso. Per vedere com'è, puoi guardare i lupi rapidi che abbiamo già qui in giro per il cortile.",
}
