T[7664] = {
  title = "Sostituzione del Raptor d'Avorio",
  reward = "Tu mi porti il tuo vecchio raptor, io ti do uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata qui ai raptor veloci per vedere fra quali potrai scegliere.",
  en_title = "Ivory Raptor Replacement",
}
