T[7666] = {
  title = "Di Nuovo nel Grande Ossario",
  reward = "Stai tornando a Scholomance, $N? Hai già pagato un prezzo così alto per usare il Veggente della Divinazione — forse vorresti portartene dietro un altro. Con quello potresti affrontare ancora una volta i pericoli del Grande Ossario.$B$BPrendilo pure. Te lo sei senz'altro guadagnato.",
}
T[7667] = {
  title = "Aiuto Materiale",
  desc = "$N, c'è una questione urgente in cui spero tu possa aiutarmi... sia materialmente che spiritualmente. Lascia che ti spieghi.$B$BNelle profondità di Scholomance, a Lordaeron, c'è una camera chiamata Grande Ossario. Devo completare un congegno capace di squarciare le ombre di quell'orrida stanza. Per finire ciò che ho cominciato mi servono due diamanti: uno di Azeroth e uno Nero Intatto. Non sono oggetti da poco, lo so — è solo che io non ho i mezzi.$B$BPotresti procurarmene uno per tipo?",
  obj = "Se ti interessa aiutare Sagorne Creststrider a Valley of Wisdom, a Orgrimmar, portagli un Azerothian Diamond e un Pristine Black Diamond.",
  progress = "Mi mette a disagio chiedere un aiuto materiale, ma al mio veggente della divinazione — il congegno che spero di finire — ne serve uno per tipo. Se non puoi aiutarmi, lo capirei senz'altro.",
  reward = "La tua generosità non ha pari, $N. Ti ringrazio della tua gentilezza.$B$BOra potrò finire il mio veggente della divinazione, e dovrei riuscire a costruirne altri senza più bisogno di diamanti... forse ti interesserebbe aiutarmi a usarlo? È per un compito della massima importanza, te lo assicuro... una questione che, lasciata a se stessa, potrebbe voler dire un disastro assoluto per il regno degli spiriti!",
}
T[7668] = {
  title = "La Minaccia di Darkreaver",
  desc = "Il Cavaliere della Morte Darkreaver spadroneggia sul Grande Ossario di Scholomance. Minaccia di piegare il regno degli spiriti al suo volere, e va fermato! È qui che entra in gioco il veggente che hai contribuito a costruire.$B$BUsa il veggente della divinazione nel cuore del seminterrato del Grande Ossario per evocare gli spiriti al servizio di Darkreaver. Sconfiggi gli spiriti e apparirà il cavaliere della morte in persona. $N, portami la sua testa! Solo la sua fine potrà riparare il danno fatto al regno degli spiriti!",
  obj = "Usa il Divination Scryer nel cuore del seminterrato di Great Ossuary, a Scholomance. Così farai apparire gli spiriti che devi combattere. Sconfitti questi spiriti, verrà evocato Death Knight Darkreaver; sconfiggilo.$B$BPorta Darkreaver's Head a Sagorne Creststrider a Valley of Wisdom, a Orgrimmar.",
  progress = "Il tempo stringe, $N — sei $Griuscito:riuscita; a fermare la minaccia del Cavaliere della Morte Darkreaver?",
  reward = "È una vittoria da assaporare, $N! La fine di Darkreaver dovrebbe rinsaldare i fragili legami che tengono ancorato il regno degli spiriti.$B$BSei $Gandato:andata; ben oltre quello che ti era stato chiesto, anche quando non ti aspettavi né ricompense né compensi. Sei davvero $Gun:una; $C di valore, $Gamico mio:amica mia;.$B$BSo che agire per preservare il regno degli spiriti dovrebbe essere già un ringraziamento sufficiente, ma ti prego — accetta questo semplice dono con la mia gratitudine.",
}
T[7669] = {
  title = "Di Nuovo nel Grande Ossario",
  reward = "Stai tornando a Scholomance, $N? Hai già pagato un prezzo così alto per usare il Veggente della Divinazione — forse vorresti portartene dietro un altro. Con quello potresti affrontare ancora una volta i pericoli del Grande Ossario.$B$BPrendilo pure. Te lo sei senz'altro guadagnato.",
}
T[7670] = {
  title = "Lord Grayson Shadowbreaker",
  desc = "È giunto il momento, $N, che tu sappia cosa ci vorrà per ottenere una cosa che senza dubbio aspetti da tempo... il tuo destriero da guerra.$B$BParla con Lord Grayson Shadowbreaker, nel Distretto della Cattedrale di Stormwind. Sarà lui a guidarti non solo attraverso i misteri della cavalcatura più fidata di un Paladino, ma anche nei compiti che ti aspettano per averne una tua.$B$BTi auguro il meglio per questa prova. Per la Luce, nobile $Gfratello:sorella;!",
  obj = "Parla con Lord Grayson Shadowbreaker a Cathedral District, a Stormwind.",
  reward = "Sono lieto di vederti, $N. So che aspettavi notizie su come ottenere il tuo destriero da guerra, e ora quel momento è arrivato.$B$BVerrai senz'altro $Gmesso:messa; alla prova in molti modi diversi, ma soprattutto nella tua volontà di superare i tanti ostacoli che ti verranno gettati davanti. Non sono pensati come un esercizio per imparare — la tua statura va ben oltre le semplici prove da allievo. Devi salvare il tuo futuro compagno dalle grinfie del male che hai combattuto per tutta la vita.$B$BFa' attenzione, la tua ora è giunta!",
}
