T[7675] = {
  title = "Sostituzione del Tecnostruzzo Blu Ghiaccio",
  reward = "Se vai ancora in giro su quel vecchio Tecnostruzzo Blu Ghiaccio, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo tecnostruzzo veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata qui ai tecnostruzzi veloci per vedere fra quali splendidi modelli potrai scegliere.",
}
T[7676] = {
  title = "Sostituzione del Tecnostruzzo Bianco",
  reward = "Se vai ancora in giro su quel vecchio Tecnostruzzo Bianco Mod A, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo tecnostruzzo veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata qui ai tecnostruzzi veloci per vedere fra quali splendidi modelli potrai scegliere.",
}
T[7701] = {
  title = "RICERCATO: Sovrintendente Maltorius",
  desc = "Per ordine di sua eminenza, il Sovrintendente Oilfist, l'agente rinnegato della Thorium Brotherhood, da poco assunto come comandante della squadra dei Dark Iron alla Fossa delle Scorie del Calderone, il Sovrintendente Maltorius, dev'essere ammazzato e la sua testa riportata indietro come prova che il lavoro è fatto.$B$BPer la ricompensa di 'sta taglia va' dal Capitano delle Vedette Lolo Longstriker.",
  obj = "In fondo a Slag Pit di Cauldron, nella Searing Gorge, troverai il nano Dark Iron traditore di nome Overseer Maltorius.$B$BUccidi Overseer Maltorius e prendi la sua testa. Riporta la testa a Lookout Captain Lolo Longstriker nella Searing Gorge per avere la ricompensa.",
  progress = "Non lo vedi che shono occupato? Cosh'è *hic* che vuoi? *hic*",
  reward = "Non penshavo mica di rivederlo, 'shto brutto muso!$B$BA dire il vero shta meglio shenza il reshto attaccato.$B$BEcco la tua ricompensa *hic*, $R.",
}
T[7703] = {
  title = "Una Faccenda Gordok in Sospeso",
  desc = "Ora tu $Gil re:la regina;, così magari tu riprendi prezioso artefatto dei Gordok da elfo viscido che si fa chiamare Principe! Il re prima di te ha fallito, come tutti gli altri re da quando Tortheldrin — l'elfo viscido — l'ha rubato a re Gordok dei tempi vecchi!$B$BArtefatto si chiama Guanto della Forza Gordok. Storie dei tempi vecchi dicono che solo l'unico vero re dei Gordok può riprenderlo. Storia dei tempi vecchi dice anche che elfo viscido è ancora qua in giro — tu lo trovi e diventa guanto potente che porti per sempre! Yar, ti faccio vedere io!",
  obj = "Trova il Gauntlet of Gordok Might e riportalo a Captain Kromcrush a Dire Maul.$B$BSecondo Kromcrush, la \"storia dei tempi vecchi\" dice che Tortheldrin — un elfo \"viscido\" che si faceva chiamare principe — lo rubò a uno dei re Gordok.",
  progress = "Hah, tu non l'hai trovato, vero capo? Forse storia dei tempi vecchi è storia sbagliata... difficile credere che elfo viscido può rubare a re Gordok!",
  reward = "Wow... tu SEI $Gil vero re:la vera regina;! Mai pensavo di vedere questo guanto in vita mia! Pare che non ha più mojo dentro... forse quell'elfo viscido ha provato a rovinare guanto. Beh, io gli dico HAR HAR!$B$BGuarda — questo marchio su guanto è marchio magico dei tempi vecchi vecchi VECCHI, più vecchio dei Gordok, dicono. Beh, come Capitano dei Gordok, tutti impariamo una cosa tante e tante volte — come far prendere vita a marchio e ridare potere a guanto!$B$BLo faccio io per te, $Gre:regina;! Ecco, prendi guanto e regna PER SEMPRE!",
}
T[7704] = {
  title = "Guarda Quant'è Grosso!",
  desc = "Bene, bene, bene... Questa sì che è una sorpresa. La Domestica aveva un gigantesco cuscino decorato e adesso è tuo. Evonice Sootsmoker vorrà di sicuro metterci sopra le sue manine sudice. Portaglielo e vedi se ti offre qualcosa di bello per il disturbo.",
  obj = "Porta Chambermaid Pillaclencher's Pillow a Evonice Sootsmoker nella Searing Gorge.",
}
T[7721] = {
  title = "Energia per il Raggio",
  desc = "Se vado contro il mio stesso buon senso e resto a gestire una bottega di ingegneria lungo la Costa Dimenticata, dovrò vedermela con questi fastidiosi elementali. Maledetti i poteri elementali senza freno, dico io!$B$BPer fortuna mia, e ora anche tua, $Gmio aspirante agente provocatore:mia aspirante agente provocatrice;, gli elementali sono una fonte ideale di energia grezza per perfezionare il mio Ultra Riduttore — dagliene di santa ragione, dico io! Mentre lo fai, però, assicurati di conservarmi i nuclei di elementale dell'acqua!",
  obj = "Raccogli 10 Water Elemental Core dai Sea Elemental e dai Sea Spray lungo la Forgotten Coast di Feralas e portali a Zorbin Fandazzle, vicino al molo.",
  progress = "Potrei annoiarti con i dettagli tecnici sull'utilità dei nuclei elementali, ma preferisco invogliarti a portare a termine questo compito importante offrendoti in cambio monete preziose e premi. Orbene, in verità, hai finito?",
  reward = "Stratosferifico! Con questi nuclei avrò da lavorare per un bel po'. Aggiungici il vantaggio di avere meno elementali lungo la costa, e forse non piangerò più fino ad addormentarmi al pensiero di aver aperto bottega nel posto forse peggiore che si possa immaginare!$B$BGrazie, $N, per quello che hai fatto per me. Anche se di certo mi mette in difficoltà con le finanze, permettimi di mostrarti la mia gratitudine in un modo che puoi capire e apprezzare... bottino!",
}
T[7722] = {
  title = "Ma che Flussante?",
  desc = "Quando quel bastardo di Maltorius ha lasciato il nostro clan, si è portato via una cosa più preziosa di un cristallo arcano purissimo: la nostra ricetta del flussante infuocato! Scommetterei qualsiasi cosa che la ricetta faceva parte dell'accordo per la sua nuova promozione fra i Dark Irons.$B$BVoglio che tu recuperi i nostri progetti segreti, $N. Sono sicuro che stanno da qualche parte vicino a Maltorius, in fondo alla Fossa delle Scorie.",
  obj = "Da qualche parte a Slag Pit di Cauldron troverai i Secret Plans: Fiery Flux rubati da Overseer Maltorius. Trova quei progetti e riportali a Master Smith Burninate nella Searing Gorge.",
  progress = "Hai trovato i progetti?",
  reward = "Spero che tu gli abbia anche fatto saltare i denti a calci, $N. Lo sa Ragnaros se se lo meritava.$B$BAdesso possiamo metterci al lavoro.",
}
T[7723] = {
  title = "Maledette Queste Dita Grasse",
  desc = "Purtroppo non riesco più a menare come una volta, per via di 'sto problema delle dita grasse. Vedi, il clima di qua, insieme alla poca pressione dell'aria, mi fa gonfiare le dita. Sembrano dei Sanguinacci di Thelsamar giganti, sembrano...$B$BTi toccherà sbrigare tu le mie faccende e compagnia bella.$B$BPrima cosa in agenda: riempire di botte i golem da guerra pesanti della Gorge. Datti una mossa.",
  obj = "Hansel Heavyhands vuole che tu uccida 20 Heavy War Golems.$B$BGli Heavy War Golems si aggirano nelle zone intorno al Cauldron, nella Searing Gorge. Quando ne avrai uccisi abbastanza, torna da Hansel Heavyhands nella Searing Gorge.",
  progress = "Li hai pestati?",
  reward = "Sei $Gun bravo ragazzo:una brava ragazza;, sei. Ti ho preso un regalino per il disturbo.",
}
T[7724] = {
  title = "Minaccia Infuocata!",
  desc = "Manco a dirlo, ogni volta che il vecchio Hansel vuole prendersi un momento per rilassarsi e riflettere sulla sua vita, quelli che comandano gli rifilano un altro lavoro.$B$BIo c'ho da pensare, e dai! Capisci che voglio dire? E. Dai.$B$BAllora, 'sti ragni della lava superiori stanno combinando un qualche putiferio. Oilfist dice che sparano fuoco dal... ehm, sì, be', comunque, cose così turbano i bambini.$B$BMi sa che ci tocca ammazzarli. Anzi, tocca a te ammazzarli.",
  obj = "Hansel Heavyhands vuole che tu uccida 20 Greater Lava Spiders nella Searing Gorge. Trovi i Greater Lava Spiders sugli altopiani e nelle pozze di lava della Searing Gorge.$B$BTorna da Hansel Heavyhands nella Searing Gorge quando avrai ucciso abbastanza Greater Lava Spiders.",
  progress = "Aveva ragione? Gli esce dal didietro?",
  reward = "<Hansel starnutisce.>$B$BMi sa che mi sto prendendo un raffreddore. Maledetto clima gelido!",
}
T[7725] = {
  title = "Ancora Giganti Rimpiccioliti",
  desc = "Lo so che mi hai già raccolto del residuo... ma se ti venisse voglia di un bis di questa attività così divertente, un po' di residuo in più mi fa sempre comodo.$B$BStavolta non posso offrirti un compenso neanche lontanamente pari a quello di prima, ma sarò più che felice di spargere la voce dei tuoi servigi fra tutti i miei amici goblin dotati di orecchie.$B$BCredimi, $Gsignore:signora;, quando ti dico che questi goblin hanno orecchie belle grandi.",
  obj = "Usa Zorbin's Ultra-Shrinker per ridurre con il raggio qualunque tipo di gigante di Feralas a una forma più gestibile. Porta 10 Miniaturization Residues, che trovi sulle versioni rimpicciolite di questi giganti, a Zorbin Fandazzle ai moli della Forgotten Coast, a Feralas.",
  progress = "Ah, i frutti della ricerca e dell'utilizzo sotto forma di dolce, dolcissimo residuo. Be', voglio dire, non è che lo assaggi o cose del genere quando lo studio.$B$BNon troppo.",
  reward = "Inconcepibilmente fantasmagorico, $N! Ancora una volta non mi hai deluso, e per questo ti ringrazio.$B$BGrazie!$B$BAnche se questa moneta ti sembrerà un po' meno di quello a cui sei $Gabituato:abituata;, stai pur $Gcerto:certa; che le tue grandi imprese sul campo della goblinità echeggiano nelle sale del potere dello Steamwheedle Cartel. Se ti serve qualcos'altro da fare, non esitare a parlarmi!",
}
T[7726] = {
  title = "Altra Energia per il Raggio",
  desc = "Altro lavoro, dici? La mia eroica missione di raccogliere pezzetti di poltiglia dall'interno degli esseri elementali non ha placato la tua sete d'avventura? Forse un'altra dose della stessa cosa proverà invano a riempire il pozzo senza fondo della tua voglia di imprese...$B$BVa bene, melodramma a parte, mi servono davvero altri nuclei di elementale dell'acqua. Sto cercando disperatamente di aprire bottega qui, quindi le ricompense non saranno altrettanto ricche... ma ti prometto che racconterò a chiunque mi stia a sentire come mi hai aiutato. Fidati — conosco gente nel Cartel!",
  obj = "Raccogli 6 Water Elemental Cores dai Sea Elementals e dai Sea Sprays lungo la Forgotten Coast di Feralas e portali a Zorbin Fandazzle, vicino al molo.",
  progress = "Sei $Griuscito:riuscita; a trovare i nuclei elementali che mi servono?",
  reward = "Eccellente, $N, eccellente! La moneta che ti do non sarà forse la paga più alta che riceverai mai per un lavoro del genere, ma stai pur $Gcerto:certa; che i miei compagni dello Steamwheedle Cartel sapranno dei tuoi sforzi!$B$BSe cerchi qualcos'altro da fare, fammelo sapere. Nuclei elementali e cose simili mi fanno sempre comodo.",
}
T[7727] = {
  title = "Incendiosauri? Chissenefregasauri, Piuttosto",
  desc = "Calli, $Gragazzo:ragazza;. I miei calli c'hanno i calli. Come faccio ad ammazzare qualcosa con i piedi ridotti così? Per questo mi aiuti tu.$B$BScrange e Burninate mi hanno incaricato di ammazzare 'ste bestie per poter mandare qualche squadra di spedizione giù nelle pozze di lava della Fossa delle Scorie a fare un po' di esplorazione. Pare che là sotto ci siano degli incendiosauri, o qualche scemenza del genere, che creano ogni sorta di problemi. Ora fila, e non tornare finché la popolazione degli incendiosauri non è estinta.",
  obj = "Hansel Heavyhands vuole che tu uccida 20 Incendosaurs.$B$BTroverai gli Incendosaurs nelle pozze di lava dentro lo Slag Pit. Lo Slag Pit si trova nel Cauldron della Searing Gorge.$B$BTorna da Hansel Heavyhands nella Searing Gorge quando avrai ucciso abbastanza Incendosaurs.",
  progress = "<Hansel è tutto preso a massaggiarsi i calli.>$B$BNon stare lì a guardare, prendi dell'olio e una luffa e mettiti a strofinare 'sti calli.$B$BNon ce l'hai una luffa? Ma bene! Forse è ora che ti mandi a cercare una luffa?$B$BEhi, dove vai?",
  reward = "Oh, 'sti miei piedi doloranti.$B$BPensavo che, visto che non avevi una luffa...",
}
T[7728] = {
  title = "RUBATI: Tubo per Fucine e Cannocchiale della Vedetta",
  desc = "Sono stati rubati i seguenti oggetti:$B$B*Un Tubo Dark Iron.$B$B*Un Cannocchiale della Vedetta.$B$BÈ offerta una ricompensa a chi troverà e restituirà gli oggetti trafugati.$B$BLa Thorium Brotherhood è certa che a rubarli siano stati i nani Dark Iron, invidiosi e senza scrupoli, che abitano la Searing Gorge.$B$BIl cannocchiale in questione era uno strumento eccellente per le vedette e il tubo era un attrezzo da forgiatura insostituibile.$B$BSe trovi gli oggetti scomparsi, riportali a Scrange.",
  obj = "Trova lo Smithing Tuyere e il Lookout's Spyglass e riportali a Taskmaster Scrange nella Searing Gorge.$B$BDi questi oggetti sai soltanto questo: li hanno sicuramente rubati i nani Dark Iron. Lo Smithing Tuyere è un attrezzo da forgiatura usato dai fabbri e il Lookout's Spyglass è uno strumento di sorveglianza preziosissimo per le vedette.",
  progress = "Se sei qui per la ricompensa, mi devi dare la refurtiva.",
  reward = "Ottimo lavoro! E ora la tua ricompensa.",
}
T[7729] = {
  title = "OFFERTA DI LAVORO: Sfoltire la Concorrenza",
  desc = "Il Coordinatore Scrange cerca qualche uomo e qualche donna in gamba che lo aiutino a 'sfoltire la concorrenza' nella Searing Gorge.$B$BSe il posto ti interessa, avventurati nella Searing Gorge e massacra ogni Coordinatore Dark Iron e ogni Schiavista Dark Iron che vedi.$B$BTorna dal Coordinatore Scrange quando avrai i vestiti abbastanza insanguinati.$B$BQuando lo saranno abbastanza lo capirai da te, quindi non chiedere.",
  obj = "Uccidi 15 Dark Iron Taskmasters e 15 Dark Iron Slavers. Fatto questo, torna da Taskmaster Scrange nella Searing Gorge.",
  progress = "Per esserne sicuri dovremo pesarti con e senza vestiti.",
  reward = "15,9 libbre! Potrebbe essere un nuovo record di peso di sangue e budella sui vestiti! Congratulazioni, $C!",
}
T[7730] = {
  title = "Infestazione Zukk'ash",
  desc = "Da quel poco che siamo riusciti a esplorare, crediamo che il nemico a sud degli gnoll sia una razza simile agli insetti. Sinceramente, che siano senzienti o no non ha importanza. Se sono loro a spingere gli gnoll alla furia contro di noi, allora sono una minaccia grande quanto gli gnoll — se non di più.$B$BAddentrati là dove vivono questi insetti Zukk'ash; il posto si chiama Fossa Fremente. Riduci il loro numero e riferiscimi quello che trovi, portando i loro carapaci come prova del tuo lavoro.",
  obj = "Porta 20 Zukk'ash Carapace a Hadoken Swiftstrider, a Camp Mojache, Feralas.",
  progress = "Come va la caccia, $N? Sei qui per riferirmi il tuo successo?",
  reward = "Ben fatto, $C. Anche se la presenza degli Zukk'ash è così estesa che solo un'invasione su vasta scala potrà fermarla, ci hai fatto guadagnare un po' di tempo per mettere a punto una strategia adeguata.$B$BFarò analizzare questi carapaci; dobbiamo scoprire tutto su di loro prima di affrontare quello che, purtroppo, è diventato un problema molto più grande del previsto.",
}
T[7731] = {
  title = "Sferzaculei",
  desc = "Durante un sopralluogo nell'Abisso Serpeggiante, uno dei nostri esploratori ha riferito di aver visto un insetto gigantesco — molto più grande degli altri insetti avvistati — aggirarsi su quel terreno contorto. Non solo è più grande, ma sembra anche emanare una specie di aura che gli altri insetti non hanno. Gli abbiamo dato un nome — Sferzaculei.$B$BLe viscere di questa bestia sarebbero preziosissime da studiare, mentre cerchiamo il modo migliore di affrontare questa nuova minaccia. Estrai le sue ghiandole secretorie e portamele subito!",
  obj = "Sconfiggi Stinglasher nel Writhing Deep e porta le sue ghiandole a Hadoken Swiftstrider, a Camp Mojache, Feralas.",
  progress = "Sei $Griuscito:riuscita; ad abbattere Sferzaculei?",
  reward = "Impressionante, $C... davvero impressionante! Se Sferzaculei è proprio una delle loro creature più forti, studiare questa bestia col tempo si rivelerà molto utile. Ora è mio compito fare in modo che ci difendiamo abbastanza a lungo da trarne vantaggio.$B$BAccetta questa taglia in monete come segno della gratitudine di tutto l'accampamento, $N. Ben fatto.",
}
T[7732] = {
  title = "Rapporto sugli Zukk'ash",
  desc = "Hai fatto doppiamente bene ad affrontare la minaccia che gli insetti Zukk'ash rappresentano per Camp Mojache. Questa minaccia è tutt'altro che finita, e vorrei chiederti un ultimo compito a nome dell'Orda.$B$BQuesto documento riporta tutte le informazioni che abbiamo raccolto su questi insetti Zukk'ash. Voglio che tu lo consegni a Zilzibin Drumlore, nel Corso di Orgrimmar. È un esperto di creature aliene come queste; spero che possa fare qualcosa con le conoscenze che abbiamo ottenuto.",
  obj = "Consegna il Camp Mojache Zukk'ash Report a Zilzibin Drumlore. Si trova nel Drag di Orgrimmar.",
  progress = "Salve, $Gamico:amica;... sembri qui per una faccenda urgente. Posso esserti utile in qualcosa?",
  reward = "Ah, me lo aspettavo. Queste creature che hai affrontato... sono un'antica minaccia che l'Orda si ostina a ignorare. Hadoken ha fatto bene a portare da me questo rapporto — e te.$B$BGli Zukk'ash non sono altro che le creature chiamate silithid. Qualcuno potrebbe pensare che siano solo una seccatura senza cervello, ma lascia che te lo assicuri — sono una minaccia molto, molto peggiore di qualsiasi cosa l'Alleanza possa mettere in campo.$B$BSe te la senti e sei abbastanza forte, il tuo aiuto mi farebbe comodo per portare alla luce questa minaccia.",
}
T[7733] = {
  title = "Una Qualità Superiore",
  desc = "Ho una pista su una fonte di pelli ancora MIGLIORE, per quanto possa sembrare incredibile! Nel nord di Feralas — nel profondo della Tana degli Artiglio Selvaggio — c'è un altro branco di yeti. Sono molto più duri di quelli con cui te la sei vista prima, quindi se sei $Gpronto:pronta; a una sfida più grande, faresti meglio a stare all'erta!$B$BPer una pila di dieci delle loro pelli ti ricompenserei generosamente: portamele qui e concluderemo il nostro affare.",
  obj = "Porta 10 Rage Scar Yeti Hide a Pratt McGrubben, alla Feathermoon Stronghold, Feralas.",
  progress = "Se queste pelli di yeti di Artiglio Selvaggio hanno anche solo in parte la qualità di quelle dei loro simili di Valsfregiata, potrebbero benissimo essere resistenti come il torio!$B$BTi immagini?",
  reward = "Ottimo, ottimo! Andranno incredibilmente bene — capisco già che, conciate a dovere, saranno molto più dure.$B$BGrazie ancora per il tuo aiuto, $N. Ecco — prendi una delle mie ultime creazioni.",
}
T[7734] = {
  title = "Una Qualità Superiore",
  desc = "Ho una pista su una fonte di pelli ancora MIGLIORE, per quanto possa sembrare incredibile! Nel nord di Feralas — nel profondo della Tana degli Artiglio Selvaggio — c'è un altro branco di yeti. Sono molto più duri di quelli con cui te la sei vista prima, quindi se sei $Gpronto:pronta; a una sfida più grande, faresti meglio a stare all'erta!$B$BPer una pila di dieci delle loro pelli ti ricompenserei generosamente: portamele qui e concluderemo il nostro affare.",
  obj = "Porta 10 Rage Scar Yeti Hide a Jangdor Swiftstrider, a Camp Mojache, Feralas.",
  progress = "Se queste pelli di yeti di Artiglio Selvaggio hanno anche solo in parte la qualità di quelle dei loro simili di Valsfregiata, potrebbero benissimo essere resistenti come il torio!$B$BTi immagini?",
  reward = "Ottimo, ottimo! Andranno incredibilmente bene — capisco già che, conciate a dovere, saranno molto più dure.$B$BGrazie ancora per il tuo aiuto, $N. Ecco — prendi una delle mie ultime creazioni.",
}
T[7735] = {
  title = "Pelle di Yeti Intatta",
  desc = "Hai trovato una pelle di yeti intatta, eccezionalmente spessa e robusta — più ancora di quelle che hai visto sugli yeti della Tana degli Artiglio Selvaggio.$B$BVisto che Pratt McGrubben, alla Feathermoon Stronghold, è in cerca di pelli di yeti, questa in particolare potrebbe interessargli parecchio.",
  obj = "Porta la Pristine Yeti Hide a Pratt McGrubben, alla Feathermoon Stronghold, Feralas.",
  progress = "Cos'è questo, $N — hai qualcosa di speciale per me?",
  reward = "Incredibile! Forse hai trovato la madre di tutte le pelli di yeti!$B$BPuoi scommetterci che te la pagherò. Di solito non pago così tanto per una sola pelle, ma sono quasi sicuro di poterne ricavare qualcosa di speciale. Grazie di aver pensato a me, $N!",
}
T[7736] = {
  title = "Ripristinare le scorte di Flussante Infuocato con il Sanguesacro",
  progress = "Non sprechiamo in chiacchiere altro del mio tempo prezioso, $R. È ora di pensare a rimpinguare le nostre scorte di flussante infuocato, che si stanno assottigliando.$B$BEcco cosa mi serve da te:$B$B*Scaglie di Incendosaur.$B$B*Sanguesacro.$B$B*Carbone.$B$BPrendo tutto quello che riesci a darmi!$B$BE vedi di fare in fretta, se vuoi entrare nelle grazie della Brotherhood.",
  reward = "C'è sempre posto per altro flussante infuocato, $Gnovellino:novellina;. Continua a portarne... a meno che non ti dica io di smettere.",
}
T[7737] = {
  title = "Farsi Accettare",
  progress = "Hai fatto carriera nella gerarchia aziendale della Brotherhood, $R. Abbiamo cominciato a guardarti di buon occhio. Un bel traguardo! $B $BSe ti interessa avere altro lavoro e guadagnarti più rispetto fra noi, apri bene le orecchie.$B $BPossiamo raffinare il flussante infuocato aggiungendo alla miscela un semplice residuo di Dark Iron. Il residuo di Dark Iron si trova a Blackrock Depths.",
  reward = "Continua a far arrivare residuo a fiumi!",
}
T[7738] = {
  title = "Pelle di Yeti Perfetta",
  desc = "Hai trovato quella che potrebbe essere proprio una pelle di yeti perfetta. Noti subito che è eccezionalmente spessa e robusta — più ancora di quelle che hai visto sugli yeti della Tana degli Artiglio Selvaggio.$B$BVisto che Jangdor Swiftstrider, a Camp Mojache, è in cerca di pelli di yeti, questa in particolare potrebbe interessargli parecchio.",
  obj = "Porta la Perfect Yeti Hide a Jangdor Swiftstrider, a Camp Mojache, Feralas.",
  progress = "Cos'è questo, $N — hai qualcosa di speciale per me?",
  reward = "È una scoperta incredibile! Credo che sia il più bell'esemplare di pelle di yeti che abbia mai visto!$B$BSenza dubbio merita una ricompensa adeguata. Di solito non pago così tanto per una sola pelle, ma sono sicuro di poterne ricavare qualcosa di speciale. Grazie di aver pensato a me, $N!",
}
T[7761] = {
  title = "L'Ordine di Blackhand",
  desc = "Imbecille,$B$BHo pochissima fiducia nella tua capacità di impedire agli estranei di entrare nella tana del padrone. Nel caso, assai probabile, della tua morte, questo globo ha un suo meccanismo di sicurezza incorporato, che impedisce agli estranei di teletrasportarsi direttamente dentro Blackwing.$B$BSolo chi ha il Marchio di Drakkisath impresso a fuoco sulla mano può usare questo globo. Per fortuna Drakkisath non è neanche lontanamente incompetente quanto te, Quartiermastro. Il ferro per marchiare lo custodisce lui in persona!$B$B— Capoguerra Rend Blackhand$B$BP.S. Distruggi questa lettera, idiota.",
  obj = "Questo sì che è un orco stupido. A quanto pare devi trovare questo ferro per marchiare e ottenere il Marchio di Drakkisath per poter usare l'Orb of Command.$B$BLa lettera dice che il ferro lo custodisce General Drakkisath. Forse dovresti indagare.",
  reward = "Non batti nemmeno ciglio mentre il ferro rovente ti viene premuto sulla carne. Sei proprio $Gun duro:una dura;!$B$BOra hai il Marchio di Drakkisath. Buon divertimento con l'assalto al castello.",
}
T[7781] = {
  title = "Il Signore di Blackrock",
  desc = "La vecchia sensazione ritorna. Il gradito fremito della vittoria ti risuona in tutto l'essere. Davanti a te giace la testa di Nefarian, monolitica e segnata dalle battaglie. Riportala al tuo Gran Signore, $Gcampione:campionessa;.",
  obj = "Riporta la Head of Nefarian a Highlord Bolvar Fordragon, a Stormwind.",
  progress = "Inconcepibile!",
  reward = "Non c'è bisogno che ti si spieghi il significato di ciò che hai fatto, $N. Questo giorno sarà scritto negli annali della storia. Una vittoria come l'Alleanza non ne conosceva da anni — se mai ne ha conosciute!",
  en_title = "The Lord of Blackrock",
  en_obj = "Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind.",
}
T[7782] = {
  title = "Il Signore di Blackrock",
  desc = "Va' nella Valle degli Eroi e parla con il Feldmaresciallo Afrasiabi.",
  obj = "Raggiungi Valley of Heroes, a Stormwind City, e parla con Field Marshal Afrasiabi.",
  reward = "<Il Feldmaresciallo Afrasiabi si inchina.>$B$BScegli la tua ricompensa, e che i festeggiamenti abbiano inizio!",
  en_title = "The Lord of Blackrock",
  en_obj = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",
}
T[7783] = {
  title = "Il Signore di Blackrock",
  desc = "La vecchia sensazione ritorna. Le gradite fitte della vittoria risuonano in tutto il tuo essere. Davanti a te giace la testa di Nefarian, monolitica e segnata dalle battaglie. Riportala al tuo Capoguerra, $Gcampione:campionessa;.",
  obj = "Riporta la Head of Nefarian a Thrall, a Orgrimmar.",
  progress = "Avrei voluto essere lì a vedere che faccia ha fatto la bestia quando le hai inferto il colpo mortale, $N.",
  reward = "Hai reso onore all'Orda ancora una volta, $N. Il figlio di Deathwing giace morto. Di certo, il malvagio si sta destando.",
}
T[7784] = {
  title = "Il Signore di Blackrock",
  desc = "Cerca il Gran Signore Supremo Saurfang nella Valley of Strength.",
  obj = "Parla con High Overlord Saurfang a Orgrimmar. Ti aspetta nella Valley of Strength.",
  reward = "Scegli la tua ricompensa, così potrò appendere la testa della bestia perché tutti la vedano.",
}
T[7785] = {
  title = "Esamina il Contenitore",
  desc = "Esamina il contenitore della sua rinascita, mortale. È da questo che rinascerà il Windseeker!",
  obj = "Esamina il Vessel of Rebirth e riportalo a Highlord Demitrian.",
  progress = "Lo libererai dalla sua prigione eterna?",
  reward = "Che tu sia $Gprotetto:protetta; nella tua crociata. Che il Padrone benedica i tuoi sforzi.",
}
T[7786] = {
  title = "Thunderaan il Windseeker",
  desc = "Ti ho detto tutto quello che so, $N. Sei tu a dover trovare l'elementium. Sei tu a dover distruggere la forma corporea del Firelord.$B$BFallo, e avrai la benedizione di Thunderaan.",
  obj = "Per liberare Thunderaan the Windseeker dalla sua prigione, devi presentare a Highlord Demitrian, a Silithus, le metà destra e sinistra delle Bindings of the Windseeker, 10 Elementium Bars e l'Essence of the Firelord.",
  progress = "Metti il mondo in ginocchio, se devi!",
  reward = "Nemmeno in sogno ho osato immaginare questo giorno.$B$BContempla, mortale.$B$BCONTEMPLA COLUI CHE È PIÙ ANTICO DELL'ESISTENZA!$B$BCONTEMPLA COLUI CHE HA AFFRONTATO TITANI E DÈI!$B$BSORGI, MIO PADRONE! LIBERATI DAI TUOI VINCOLI!",
}
T[7787] = {
  title = "Sorgi, Thunderfury!",
  desc = "Hai sconfitto il Wind Seeker. Prendi la lama dormiente e costringi quel miserabile bugiardo di Demitrian a risvegliare Thunderfury con i materiali che gli hai fornito per il suo tradimento.",
  obj = "Presenta la Dormant Wind Kissed Blade a Highlord Demitrian.",
  progress = "<Demitrian si rannicchia impaurito al tuo cospetto.>",
  reward = "Ti prego, non farmi del male! Prendila! Prendi la lama! Lascia che Demitrian ricostruisca la sua patetica vita!",
}
T[7788] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Rocca di Silverwing. Respingi le forze d'invasione dell'Orda!$B$BFallo, e ti guadagnerai un Contrassegno d'Onore. Portamelo, $N, e ti ricompenserò.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Boschetto dei Silverwing.",
  progress = "Hai combattuto in Warsong Gulch e difeso la Rocca di Silverwing?",
  reward = "Hai dimostrato il tuo valore nella nostra lotta in Warsong Gulch. Continua ad aiutare la causa e portami altri Contrassegni d'Onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.",
  en_title = "Vanquish the Invaders!",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[7789] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro volere sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BSenti l'orgoglio gonfiarti il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un marchio d'onore. Ce l'hai un marchio simile?",
  reward = "<Il Capitano Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[7791] = {
  title = "Una Donazione di Wool",
  progress = "Al momento accettiamo donazioni di wool cloth. Donando sessanta pezze di wool cloth otterrai il pieno riconoscimento di Stormwind per il tuo gesto generoso. Con le scorte di wool che abbiamo, da te ci bastano sessanta pezze in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.$B$BSe hai con te le sessanta pezze di wool cloth e sei $Gpronto:pronta; a donarle, posso prenderle subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7792] = {
  title = "Una Donazione di Wool",
  progress = "Al momento accettiamo donazioni di wool cloth. Una donazione di sessanta pezze di wool cloth ti farà guadagnare il pieno riconoscimento di Darnassus per la tua generosità. Con le scorte di wool che abbiamo, da te ci bastano sessanta pezze in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.$B$BSe hai con te le sessanta pezze di wool cloth e sei $Gpronto:pronta; a donarle, posso prenderle subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7793] = {
  title = "Una Donazione di Silk",
  progress = "Come per quasi tutti gli altri tessuti, le nostre scorte di silk sono al minimo storico. Visto quello che abbiamo, da te ci bastano sessanta pezze di silk in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.$B$BUn dono generoso come il silk, aggiungerei, farebbe di certo crescere la tua reputazione qui nella comunità! Se hai con te le sessanta pezze di silk cloth e sei $Gpronto:pronta; a donarle, posso prenderle subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7794] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave sta finendo, e il tuo aiuto ci farebbe comodo per rifornire le nostre scorte! Se tutta la comunità fa la sua parte, da te ci servirebbe solo una donazione di 60 pezzi di mageweave cloth per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Stormwind, te lo assicuro!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Mageweave",
}
T[7795] = {
  title = "Una Donazione di Runecloth",
  progress = "$N, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre ci diamo da fare per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo — il runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai fatto in passato!$B$BSe vuoi, portami tutta il runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, e poi vedremo.",
  reward = "Fantastico — lo useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero persi.$B$BCon tutte le donazioni che hai fatto, accetterò volentieri qualsiasi altra donazione di runecloth vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non restino senza riconoscimento!",
  en_title = "A Donation of Runecloth",
}
T[7796] = {
  title = "Altro Runecloth",
  progress = "Quando sei $Gpronto:pronta; a consegnare la pila di runecloth, la accetterò.",
  reward = "$N — senza eroi come te che lavorano per il nostro popolo, soffriremmo di sicuro. Grazie per il tuo impegno costante!",
  en_title = "Additional Runecloth",
}
T[7798] = {
  title = "Una Donazione di Silk",
  progress = "Come per quasi tutti gli altri tessuti, le nostre scorte di silk sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta pezze di silk in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.$B$BUn dono generoso come il silk, lasciamelo dire, farebbe di certo crescere la tua reputazione qui nella comunità! Se hai con te le sessanta pezze di silk cloth e sei $Gpronto:pronta; a donarle, posso prenderle subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7799] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave sta finendo, e il tuo aiuto ci farebbe comodo per ricostituire le scorte! Contando sull'intera comunità, da te ci basterebbe una donazione di 60 pezzi di mageweave cloth per raggiungere il nostro obiettivo. Una tale generosità non passerebbe inosservata a Darnassus, te lo assicuro!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
}
