T[7802] = {
  title = "Una Donazione di Wool",
  progress = "Al momento accettiamo donazioni di wool cloth. Una donazione di sessanta pezzi di wool cloth ti farà guadagnare il pieno riconoscimento di Ironforge per il tuo gesto generoso. Con le scorte di wool che abbiamo, da te ci bastano sessanta pezzi in tutto; il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.$B$BSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7803] = {
  title = "Una Donazione di Silk",
  progress = "Come per quasi tutti gli altri tessuti, le nostre scorte di silk sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta pezzi di silk in tutto; con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.$B$BUn dono generoso come il silk, aggiungerei, accrescerebbe di certo la stima di cui godi qui nella comunità! Se hai con te i sessanta pezzi di silk cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7804] = {
  title = "Una Donazione di Mageweave",
  progress = "Il mageweave scarseggia, e ci farebbe comodo il tuo aiuto per rifornire le nostre scorte! Contando su tutta la comunità, da te ci basterebbe una donazione di 60 pezzi di mageweave cloth per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Ironforge, te lo assicuro!$B$BSe hai con te i sessanta pezzi di mageweave cloth e sei $Gpronto:pronta; a donarli, posso prenderli adesso.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
}
T[7805] = {
  title = "Una Donazione di Runecloth",
  progress = "$N, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre ci diamo da fare per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo — il runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai fatto in passato!$B$BSe vuoi, portami tutta il runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, e poi vedremo.",
  reward = "Fantastico — lo useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero persi.$B$BCon tutte le donazioni che hai fatto, accetterò volentieri qualsiasi altra donazione di runecloth vorrai fare in futuro. Passa pure da me, e mi assicurerò personalmente che le tue buone azioni non restino senza riconoscimento!",
}
T[7806] = {
  title = "Altro Runecloth",
  progress = "Quando sei $Gpronto:pronta; a consegnare la pila di runecloth, la accetterò.",
  reward = "$N — senza eroi come te che lavorano per il nostro popolo, soffriremmo di sicuro. Grazie per il tuo impegno costante!",
