T[7810] = {
  title = "Maestro dell'Arena",
  desc = "Per essere $Gun maestro:una maestra; dell'arena ci vuole di più! Forse il Pirata che organizza l'evento a Gurubashi lo saprà!",
  obj = "Parla con Short John Mithril nell'Arena di Stranglethorn.",
  reward = "Arr, compare! Un Monile solo non basta mica per fare di te $Gun maestro:una maestra; dell'Arena! Adesso è ora di far vedere davvero di che tempra sei.",
  en_title = "Arena Master",
  en_obj = "Speak with Short John Mithril in the Stranglethorn Arena.",
}
