  en_title = "A Donation of Silk",
}
T[7815] = {
  title = "Snapjaw, Mon!",
  desc = "Non farti ingannare da quei loro occhioni, mon! Quegli snapjaw d'acqua salata sono una minaccia. Non riesco a pescare cinque minuti senza ritrovarmi con la lenza spezzata da uno di quegli aspirapesci giganti che mi rubano l'esca.$B$BFai un favore a me e alla gente di Revantusk Village e ammazzali, mon.$B$BAmmazzali tutti quanti!",
  obj = "Katoom the Angler a Revantusk Village, negli Hinterlands, vuole che tu uccida 15 tartarughe Saltwater Snapjaw. Torna da lui quando avrai finito.",
  progress = "Come va la caccia?",
  reward = "Oh, mon! Non finirò mai di ringraziarti! Spero che questa canna da pesca basti come ricompensa per il lavoro.",
}
T[7816] = {
  title = "Gammerita, Mon!",
  desc = "Ehi! Là fuori c'è una tartaruga diversa dalle altre. Lei è la Gammerita, capo degli snapjaws d'acqua salata — un rettile sporco e ladro fino al midollo.$B$BMon, mi ha rubato la mia esca migliore. Me l'ha strappata dalla lenza con un morso! Da allora i pesci non abboccano più come prima.$B$BTrova Gammerita e tirale fuori dalla pancia la mia esca.",
  obj = "Katoom the Angler, a Revantusk Village negli Hinterlands, vuole che tu uccida Gammerita e recuperi Katoom's Best Lure dal suo cadavere.$B$BKatoom ha detto che Gammerita se ne sta sulla costa con le altre tartarughe.",
  progress = "L'hai già presa?",
  reward = "MON! È fantastico! Con la mia esca migliore e meno snapjaw in giro, i pesci arriveranno a mucchi.",
}
