T[7828] = {
  title = "Agguato agli Inseguitori",
  desc = "Molti troll coraggiosi sono caduti nelle terre selvagge e spietate degli Hinterlands, $R. I lupi Silvermane sono una delle minacce più grandi per i nostri cacciatori. Stanno in agguato, nascosti tra i cespugli e le pieghe del terreno, poi colpiscono quando se ne presenta l'occasione.$B$BUna simile ferocia non resterà senza risposta!$B$BDevi pensare come i Silvermane. Tendi un agguato agli inseguitori! Uccidili tutti!",
  obj = "Huntsman Markhor, a Revantusk Village negli Hinterlands, vuole che tu uccida 15 Silvermane Stalkers e 15 Silvermane Howlers. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i lupi si nascondono nelle terre selvagge degli Hinterlands.",
  progress = "Mostra loro la potenza dei Revantusk!",
  reward = "Ottimo lavoro, $R. I Revantusk ti ringraziano per il tuo contributo.",
}
T[7829] = {
  title = "Caccia ai Selvaggi",
  desc = "Tra le creature più irascibili degli Hinterlands ci sono gli owlbeasts selvaggi. Molti bravi guerrieri Revantusk sono caduti sotto gli artigli e il becco feroci di queste bestie.$B$BUccidi ogni owlbeast selvaggio che vedi, $R. Torna da me quando non ne potrai più di spargere sangue. Allora il tuo contributo sarà pesato, misurato e giudicato.",
  obj = "Huntsman Markhor, a Revantusk Village negli Hinterlands, vuole che tu uccida 20 Savage Owlbeasts. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i Savage Owlbeasts popolano le terre selvagge degli Hinterlands.",
  progress = "Libera la mente dai pensieri impuri, $R. Diventa tutt'uno con la natura selvaggia!",
  reward = "Hai dimostrato di essere $Gun degno alleato:una degna alleata; dei Revantusk, $N. Ben fatto.",
}
T[7830] = {
  title = "Vendicare i Caduti",
  desc = "La feccia che si fa chiamare Wildhammer addestra i grifoni a uccidere i troll. Orribile, lo so, ma non temere, presto giustizia sarà fatta.$B$BPer ora voglio che ti concentri sullo sterminio dei grifoni anziani della regione. Sono conosciuti come Signori dei Cieli.$B$BUccidine uno e torna da me con la sua piuma.",
  obj = "Huntsman Markhor, a Revantusk Village negli Hinterlands, vuole che tu uccida un Razorbeak Skylord e recuperi la sua Skylord Plume. Torna da lui quando avrai finito.$B$BMarkhor ha detto che i Razorbeak Skylord sono una razza rara che di solito vive nelle terre selvagge degli Hinterlands.",
  progress = "Il Signore dei Cieli Razorbeak è una razza di grifone molto più rara: è quella che si accoppia e genera una prole assassina.",
  reward = "<Markhor esamina la piuma.>$B$BMi chiedo quanti dei nostri cacciatori abbia divorato questa bestia prima che tu gliela facessi pagare.",
}
