T[7837] = {
  title = "Altro Runecloth",
  progress = "Quando sei $Gpronto:pronta; a consegnare la pila di runecloth, la accetterò.",
  reward = "$N — senza eroi come te che lavorano per la tribù, soffriremmo di sicuro. Grazie per il tuo impegno costante!",
}
T[7838] = {
  title = "Gran Maestro dell'Arena",
  progress = "$GFermo:Ferma; là, $Gmarinaio d'acqua dolce:marinaia d'acqua dolce;! Portami 12 monili del Maestro delle Arene e sarai $GGran Maestro:Gran Maestra; dell'Arena dei Gurubashi! Arrrr!",
  reward = "Tanto sangue hai versato sulla sabbia dell'Arena, e a me mi fa piacere nominarti $GGran Maestro:Gran Maestra; dell'Arena!",
  en_title = "Arena Grandmaster",
}
T[7839] = {
  title = "Teppisti Vilebranch",
  desc = "La feccia Vilebranch ha invaso il nostro villaggio e mi ha rubato gli attrezzi! Ne ho di scorta, ma quelli che mi hanno rubato erano un regalo di uno gnomo di buon cuore che mi ha salvato la vita quando ero un giovane orco.$B$BRivoglio quegli attrezzi, $N — per me valgono più di ogni cosa.$B$BMarkhor ha riferito che gli attrezzi sono stati avvistati vicino ai templi di Agol'watha e Shaol'watha.$B$BQuei templi si trovano nella regione nordorientale degli Hinterlands.$B$BRecupera i miei attrezzi!",
  obj = "Smith Slagtree, a Revantusk Village negli Hinterlands, vuole che tu trovi Slagtree's Lost Tools. Torna da lui quando avrai finito.$B$BTi ricordi che Smith Slagtree ha detto che gli attrezzi potrebbero essere in uno dei templi Vilebranch, nella regione nordorientale degli Hinterlands. Dovresti controllare anche a Skulk Rock.",
  progress = "Fa' attenzione ai troll Vilebranch della zona, $N. Sono feccia spietata e assassina.",
  reward = "I miei attrezzi! Li hai trovati! Oh, che giorno glorioso! Grazie, $N.",
}
T[7840] = {
  title = "Lard Ha Perso il Pranzo",
  desc = "Lard era a posto speciale segreto a fare picnic quando Vilebranch brutto e cattivo colpisce Lard con grosso bastone. Lard scappa a Revantusk ma scorda pranzo di Lard. Lard ha fame. Forse tu torni a posto speciale segreto e prendi pranzo di Lard? Lard ha paura. Va' a nord! Isola là a nord è posto speciale segreto.",
  obj = "Lard a Revantusk Village, negli Hinterlands, vuole che tu trovi Lard's Lunch. Torna da lui quando avrai finito.$B$BLard ha detto di averlo lasciato sull'isola a nord. Fai attenzione ai troll Vilebranch.",
  progress = "<Lard si strofina l'enorme pancia.>$B$BLard ha tanta fame.",
  reward = "<Lard ti prende dalle mani l'enorme cosciotto di carne e se lo caccia in bocca.>$B$BQuesto ci voleva! Grazie, $Gpiccolo:piccola;.$B$BLard fa a te cestino da picnic speciale per aiuto a Lard.",
}
T[7841] = {
  title = "Messaggio ai Wildhammer",
  desc = "I Wildhammer fanno patti coi nostri nemici, stringono nuove alleanze. Stavolta se la fanno con gli alti elfi, mon.$B$B<Otho sputa.>$B$BDobbiamo mandare un messaggio a quei nani Wildhammer — un messaggio scritto col sangue dei nostri nemici. Massacra ogni alto elfo Highvale che incontri, lascia i corpi come avvertimento.$B$BMai mettersi contro i troll!",
  obj = "Otho Moji'ko, a Revantusk Village negli Hinterlands, vuole che tu massacri 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman e 15 Highvale Rangers. Torna da lui quando avrai finito.$B$BGli alti elfi Highvale li trovi al Padiglione Quel'Danil, nella regione nordoccidentale degli Hinterlands.",
  progress = "Sei troppo $Gpulito:pulita;, mon. Devi buttarti nella mischia — sporcarti le mani col nemico.",
  reward = "Pare che anche i Revantusk stringono nuove alleanze, mon! Hai fatto un bel lavoro.",
}
T[7842] = {
  title = "Un Altro Messaggio per i Wildhammer",
  desc = "Dicono che i Wildhammer e i grifoni sono legati come un troll e la sua compagna. Che schifo, ma noi possiamo usare questa cosa a nostro vantaggio, mon. Noi mandiamo a loro un altro messaggio.$B$BUccidi tutti i grifoni che vedi negli Hinterlands, raccogli le loro piume. Con quelle noi facciamo l'ultimo messaggio.",
  obj = "Otho Moji'ko a Revantusk Village, negli Hinterlands, vuole che tu gli porti 10 Long Elegant Feathers presi ai grifoni che vivono negli Hinterlands. Torna da lui quando avrai finito.$B$BSi sa che i grifoni vivono in ogni regione degli Hinterlands.",
  progress = "L'ultimo messaggio li fa scappare di sicuro. Oppure li fa arrabbiare tanto, tanto.",
  reward = "Oh, mon, qui viene il bello. Manca un passo solo, e poi i Wildhammer vedono che con i troll non si scherza!",
}
T[7843] = {
  title = "L'Ultimo Messaggio per i Wildhammer",
  desc = "<Otho ti porge una lunga lancia intrisa di sangue, avvolta in diverse piume di grifone.>$B$BPrendi questa, mon. Tu la porti ad Aerie Peak, proprio in mezzo al paese, vicino al pozzo. La pianti! La ficchi dritta nel terreno! Fai vedere a quei nani che i troll fanno sul serio! Torna quando hai fatto. Speriamo che torni $Gvivo:viva;.",
  obj = "Otho Moji'ko a Revantusk Village, negli Hinterlands, vuole che tu vada ad Aerie Peak, nella regione occidentale degli Hinterlands, e metta il Final Message to the Wildhammer vicino al pozzo al centro del paese. Torna da lui quando avrai finito.$B$BGuardati dai nani Wildhammer infuriati e dai membri turbolenti dell'Alleanza.",
  progress = "Perché ci metti tanto, mon?",
  reward = "Peccato non esserci stato a vedere che facce hanno fatto, mon. Stanno facendo i bagagli? Se ne vanno dal paese?$B$BTu fatto bene, $N. Proprio bene. Otho ti ricompensa con il grande mojo.",
}
T[7844] = {
  title = "Cugini Cannibali",
  desc = "Negli Hinterlands vivono tre diverse tribù di troll, $N. E le somiglianze fra le tribù finiscono più o meno qui: siamo tutti troll e viviamo negli Hinterlands.$B$BI Vilebranch — mai nome fu più azzeccato — sono una banda di depravati; si nutrono di altri troll e di umanoidi.$B$BSe Zul'jin fosse qui, li avrebbe distrutti tutti con un gesto della mano — ma purtroppo Zul'jin non è ancora tornato, e dobbiamo cavarcela da soli.$B$BTocca a te distruggere la feccia di questa regione!",
  obj = "Mystic Yayo'jin a Revantusk Village, negli Hinterlands, vuole che tu uccida 30 Vilebranch Scalpers e 15 Vilebranch Soothsayers. Torna da lei quando avrai finito.$B$BYayo'jin ha detto che questi troll si trovano vicino ai templi di Shaol'watha e Agol'watha, nella regione a nord-nordest degli Hinterlands.",
  progress = "Gli Indovini e gli Scotennatori Vilebranch vivono nella regione a nord-nordest degli Hinterlands.",
  reward = "Ben fatto, $C. Nemmeno Zul'jin in persona avrebbe potuto fare di meglio!",
}
T[7845] = {
  title = "L'Anziano Torntusk Rapito!",
  desc = "Il mio compagno è stato rapito dai selvaggi Vilebranch in un'audace incursione di mezzanotte nel nostro villaggio. Le nostre spie mi hanno detto che è ancora vivo e che lo tengono prigioniero in cima a Jintha'alor. Si dice che la Sacerdotessa Vile Hexx lo stia preparando per sacrificarlo al Dio del sangue senza volto, Hakkar.$B$BDevi salvarlo, $N! Il nostro villaggio non reggerebbe a una perdita così grande.",
  obj = "Primal Torntusk a Revantusk Village, negli Hinterlands, vuole che tu porti in salvo il suo compagno, Elder Torntusk, da Jintha'alor.$B$BTi hanno detto che lo tengono prigioniero in cima a Jintha'alor, la capitale dei Vilebranch, che si trova nella regione meridionale degli Hinterlands.",
  reward = "Devi fare in fretta, $N. Di sicuro le guardie sono già in allerta per la tua presenza.",
}
T[7846] = {
  title = "Recupera la Chiave!",
  desc = "La chiave dei miei ceppi è nelle mani di Hitah'ya la Custode. Si trova nella caverna qui vicino. Fai attenzione, $C, perché è ben sorvegliata.$B$BUccidila e riporta la chiave per togliermi le catene. Solo allora sarò libero di tornare a casa.",
  obj = "Elder Torntusk a Jintha'alor vuole che tu uccida Hitah'ya the Keeper per avere la Shackle Key dei suoi ceppi. Torna da Elder Torntusk quando avrai recuperato la chiave.",
  progress = "Devi sbrigarti!",
  reward = "Finalmente libero! Grazie, $N. Revantusk saprà delle tue imprese!",
}
T[7847] = {
  title = "Ritorno dalla Primeva Torntusk",
  desc = "Torna dalla mia compagna, la Primeva Torntusk, a Revantusk Village. Dille che sto tornando a casa! Di sicuro ti ricompenserà.",
  obj = "Elder Torntusk a Jintha'alor vuole che tu torni da Primal Torntusk a Revantusk Village con la notizia della sua liberazione.",
  reward = "Hai reso un grande servizio ai Revantusk, $N! Ti siamo immensamente grati.",
}
T[7848] = {
  title = "Sintonizzazione con il Core",
  desc = "Le fenditure si agitano, si lacerano e collassano tutt'intorno a noi, $R. A meno di due passi da dove mi trovo c'è uno squarcio che attraversa le profondità di Blackrock Mountain e porta nelle fauci del Firelord.$B$B$GSorpreso:Sorpresa;? Che pena... Le razze mortali non riescono a comprendere ciò che non possono vedere, toccare o percepire.$B$BTe lo assicuro, il portale c'è e l'accesso è possibile.$B$BHo stuzzicato il tuo interesse? Sintonizzarsi è semplice. Avventurati nelle Blackrock Depths e recupera un frammento di nucleo. Riportamelo e sintonizzerò la tua essenza con il portale.",
  obj = "Raggiungi il portale d'ingresso del Molten Core nelle Blackrock Depths e recupera un Core Fragment. Quando avrai recuperato il Core Fragment, torna da Lothos Riftwaker a Blackrock Mountain.",
  progress = "Devi sintonizzare la tua anima con il Molten Core prima che ti sia concesso l'accesso.",
  reward = "Ora sono in grado di trasportarti nel Molten Core. Chiedi e sarà fatto.",
}
T[7849] = {
  title = "Ansia da Separazione",
  desc = "Come molti nel nostro villaggio, anch'io ho perso una persona cara, portata via dalle terre selvagge. Nel mio caso, ahimè, si tratta di mio fratello gemello Malkhor — rapito dai Vilebranch nella stessa incursione in cui hanno preso il compagno di Torntusk.$B$BPurtroppo il destino non gli ha concesso di vivere, e l'hanno giustiziato in modo rapido e brutale; i suoi resti sono stati dati in pasto alle melme e ai lupi dei Vilebranch.$B$BÈ troppo tardi per salvargli la vita, ma non per salvargli l'anima. Recupera i suoi resti, $N.",
  obj = "Huntsman Markhor a Revantusk Village, negli Hinterlands, vuole che tu recuperi i resti di suo fratello gemello. Trova Huntsman Malkhor's Skull e Huntsman Malkhor's Bones e portali a Huntsman Markhor.$B$BMarkhor ha detto che i resti di suo fratello sono stati dati in pasto alle melme e ai lupi dei Vilebranch. Ha detto anche che a Jintha'alor c'è una fossa dei rifiuti piena di melme, oltre a una tana di lupi. Tutti e due i posti sono vicino alla cima del tempio.",
  progress = "Quando avrò i suoi resti, li porterò a Yayo'jin perché li prepari per una degna sepoltura.",
  reward = "Mio amatissimo fratello, quanto mi mancherai...$B$BGrazie per il tuo aiuto, $N. Ai miei occhi sei davvero $Gun eroe:un'eroina;.",
}
T[7850] = {
  title = "Vasi Oscuri",
  desc = "I Vilebranch combattono con una ferocia soprannaturale. È opera degli immondi incantesimi intessuti dalla Vile Sacerdotessa Hexx.$B$BIn tutta Jintha'alor troverai dei vasi oscuri pieni di sangue corrotto. I vasi emanano la magia immonda del Dio del sangue senza volto, che rende più forti i Vilebranch ma li fa anche impazzire.$B$BRuba quei vasi e portameli, così potrò eliminare la corruzione e, alla fine, allentare la presa del Dio del sangue.",
  obj = "Primal Torntusk a Revantusk Village, negli Hinterlands, vuole che tu recuperi 10 Vessels of Tainted Blood da Jintha'alor. Torna da Primal Torntusk quando avrai finito.",
  progress = "Fai attenzione quando combatti i Vilebranch, $N. Hanno la mente offuscata — lottano fino alla morte.",
  reward = "L'energia oscura che spinge i Vilebranch si è dissolta — per ora. Dobbiamo restare sempre vigili nella nostra battaglia contro il male, perché anche se la Vile Sacerdotessa viene distrutta, presto un'altra ne prende il posto.",
}
T[7861] = {
  title = "Ricercati: La Sacerdotessa Vile Hexx e i Suoi Sgherri",
  desc = "Per ordine della Primeva Torntusk, la Sacerdotessa Vile Hexx e i suoi sgherri devono essere assicurati alla giustizia!$B$BSi offre una ricca ricompensa a chiunque uccida la Sacerdotessa Vile Hexx e tutta la sua guardia scelta Aman'zasi.",
  obj = "Ti è stato ordinato di uccidere Vile Priestess Hexx e 20 Vilebranch Aman'zasi Guards. Presentati a Primal Torntusk a Revantusk Village, negli Hinterlands, quando avrai finito.$B$BVile Priestess Hexx e le Vilebranch Aman'zasi Guards si trovano in cima a Jintha'alor, negli Hinterlands.",
  progress = "Porti notizie da Jintha'alor?",
  reward = "Un colpo davvero devastante per i Vilebranch. Sarai $Gricompensato:ricompensata; generosamente, $N.",
}
T[7862] = {
  title = "Posto Vacante: Capitano della Guardia di Revantusk Village",
  desc = "Con la perdita del Capitano della Guardia Malkhor, il posto di Capitano della Guardia di Revantusk è di nuovo vacante. Se ti interessa diventare Capitano della Guardia di Revantusk, porta a termine i compiti seguenti e presenta la tua candidatura alla Primeva Torntusk:$B$BStermina i Berserker Vilebranch.$B$BStermina i Cacciatori dell'Ombra Vilebranch.$B$BStermina i Succhiasangue Vilebranch.$B$BStermina i Mangiatori di Anime Vilebranch.",
  obj = "Il tuo compito è decimare 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers e 20 Vilebranch Soul Eaters.$B$BSe porti a termine il compito, torna da Primal Torntusk a Revantusk Village, negli Hinterlands.",
  progress = "Sei qui per il posto vacante?",
  reward = "Sei davvero $Gun candidato degno:una candidata degna; del nuovo incarico, $N. Accetta questo monile in segno del nostro apprezzamento per il tuo duro lavoro. Esaminerò tutte le candidature l'anno prossimo.",
}
T[7863] = {
  title = "Pacco Base di Rifornimenti delle Sentinelle",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende che si possono usare solo a Warsong Gulch.$B$BContinuando a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
  en_title = "Sentinel Basic Care Package",
}
