}
T[7874] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagna un Contrassegno d'Onore. Torna da me con quel Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un marchio d'onore. Ce l'hai un marchio simile?",
  reward = "<Il Capitano Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[7875] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro volere sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BSenti l'orgoglio gonfiarti il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Ne hai uno?",
  reward = "<Il Capitano Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
}
T[7876] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro volere sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BSenti l'orgoglio gonfiarti il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Ne hai uno?",
  reward = "<Il Capitano Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
}
T[7877] = {
  title = "Il Tesoro degli Shen'dralar",
  desc = "Nella biblioteca, l'Ateneo, troverai un antico forziere nascosto sotto la scalinata. Prendi da lì ciò che desideri.",
  obj = "Torna all'Athenaeum e trova il Treasure of the Shen'dralar. Reclama la tua ricompensa!",
  reward = "Apri il forziere e trovi...",
}
T[7881] = {
  title = "Stivali per il Luna Park",
  progress = "Noi della Darkmoon Faire camminiamo parecchio. Camminiamo da un luogo della fiera all'altro... anzi, non ci vedrai mai stare seduti mentre lavoriamo! Quindi non c'è da stupirsi se consumiamo un sacco di stivali! Ci servono stivali resistenti ed eleganti, e gli stivali di cuoio sbalzato fanno proprio al caso nostro.$B$BTu! Sei $Gun conciatore:una conciatrice;: fammi degli stivali di cuoio sbalzato e ti darò un biglietto della Darkmoon Faire per il lavoro.",
  reward = "Grazie, $N. Sono fatti davvero bene. Una lavorazione di prim'ordine! Ecco un biglietto della Darkmoon Faire... divertiti, $Gmio signore:mia signora;.",
  en_title = "Carnival Boots",
}
T[7882] = {
  title = "Farsetti per il Luna Park",
  progress = "I nostri lavoratori della Faire fanno ben più che spazzare rifiuti e piantare picchetti! Aiutano anche a sorvegliare il luna park quando è in viaggio, e per questo hanno sempre bisogno di buoni farsetti robusti.$B$BSe fai qualche armatura di cuoio resistente e me la porti, farò in modo che arrivi alle persone giuste. E in cambio ti procurerò anche qualche biglietto della Darkmoon Faire.",
  reward = "Ah, hai portato i farsetti. Splendido. Posso chiederti di che animale è la pelle che hai usato? Le cuciture sono fatte molto bene, e la grana del cuoio ha un aspetto rustico. Si vede che sei $Gun artigiano:un'artigiana; di talento!$B$BGrazie, $N, ed ecco i tuoi biglietti.",
  en_title = "Carnival Jerkins",
}
T[7883] = {
  title = "Lo Gnomo Più Grande del Mondo!",
  progress = "Yebb Nebblegear vuole aggiungere altri talenti al suo spettacolo, e sta cercando in lungo e in largo lo gnomo più grande del mondo. Conosci qualche gnomo di dimensioni notevoli?$B$BBe', prima ancora di trovare lo gnomo, vuole avere pronto il suo costume. Credo che un'imbracatura barbarica sarebbe una buona base per il costume: puoi fare delle imbracature e portarmele? Fallo, e avrò un mazzo di biglietti della Darkmoon Faire per te...",
  reward = "Oh cielo, sono proprio grandi!! Non riesco a immaginare uno gnomo che ci stia dentro a pennello, ma niente paura — se lo gnomo che troveremo non sarà abbastanza grande, posso sistemare il suo costume.$B$BMille grazie, $N. Ecco i biglietti che ti avevo promesso.",
  en_title = "The World's Largest Gnome!",
}
T[7884] = {
  title = "Il Ragazzo Crocolisco e il Murloc Barbuto",
  progress = "Yebb sta lavorando ad altre attrazioni per il suo zoo, tra cui dimore umide e paludose per un ragazzo cresciuto dai crocolischi, e forse per un murloc. Ci serviranno dei buoni gambali impermeabili, così non ci inzupperemo durante i montaggi e gli smontaggi. Per questo lavoro credo che i gambali di scaglie di tartaruga andranno benissimo.$B$B$N, sai fare quei gambali? Se li fai, la tua ricompensa sarà un bel mazzo di biglietti della Darkmoon Faire...",
  reward = "Magnifico, li hai fatti! Andranno benissimo... Spero solo di non essere io quello che dovrà pulire la gabbia dei crocolischi, quando sarà il momento. Quelle bestie sanno essere proprio bestiali, non credi?$B$BEcco i tuoi biglietti, $N. Goditeli, e goditi il soggiorno alla Darkmoon Faire!",
  en_title = "Crocolisk Boy and the Bearded Murloc",
}
T[7889] = {
  title = "Pietra da Contrappeso Comune",
  progress = "Ci vuole un sacco di lavoro per essere la donna più forte del mondo! I miei pesi stanno diventando troppo leggeri, e se voglio restare in forma mi serviranno altri pesi!$B$BPensi di potermi portare qualche pietra da contrappeso? Se lo fai, ti darò un biglietto della Darkmoon Faire.",
  reward = "Fantastico! Andranno benissimo! Non sono troppo pesanti, ma nemmeno troppo leggere. Sono perfette per far crescere i muscoli!$B$BGrazie mille, $N. Ecco il tuo biglietto della Darkmoon Faire!",
  en_title = "Coarse Weightstone",
}
T[7890] = {
  title = "Pietra da Molatura Pesante",
  progress = "Per allenarmi, mi piace infilare un bastone tra pesanti pietre da molatura e poi sollevarlo sopra la testa. Non è facile, ma essere la donna più forte del mondo, come sono io, non è una cosa che si guadagna stando seduti!$B$BMi aiuti? Mi servono altre pietre da molatura — portamene qualcuna e in cambio ti darò dei biglietti della Darkmoon Faire.",
  reward = "Hai portato le pietre! E sono pesanti! Sento già i muscoli che crescono. Grazie, $N!$B$BEcco, prendi questi biglietti, e mi raccomando, non mangiare troppi dolci mentre sei alla fiera. $GUn:Una; $C grande e forte come te deve tenersi in forma per combattere!",
  en_title = "Heavy Grinding Stone",
}
T[7891] = {
  title = "Bracciali di Ferro Verdi",
  progress = "Sto preparando un nuovo costume, per quando avrò il mio stand come la donna più forte del mondo! Adesso sto cercando dei bracciali da indossare. Non devono coprire molto, perché la gente vuole vedere i miei muscoli, ma voglio comunque sfoggiare un po' di colore, capisci?$B$BChe ne dici di bracciali di ferro verdi, $N? Puoi farmi dei bracciali di ferro verdi? Se puoi, ho un bel mucchio di biglietti della Darkmoon Faire per te.",
  reward = "Sì! Sono proprio quello che mi serve! Che bel colore, e lasciano comunque le braccia scoperte, così si vede quanto sono forti! Perfetto!$B$BEcco a te, $N. Ecco i tuoi biglietti: divertiti!",
  en_title = "Green Iron Bracers",
}
T[7892] = {
  title = "Grossa Mazza Nera",
  progress = "Per il mio numero da donna più forte del mondo, ho intenzione di farmi dare degli oggetti dal pubblico e di spaccarli con una grossa mazza nera!$B$BPuoi farmi una grossa mazza nera, $N?",
  reward = "Ah, perfetta! Questa mazza ha una testa grossa e pesante. Scommetto che potrei spaccarci praticamente qualsiasi cosa. Spero solo di non romperla insieme a quello che colpisco!$B$BEcco i tuoi biglietti, $N. Goditi il soggiorno alla fiera!",
  en_title = "Big Black Mace",
}
T[7894] = {
  title = "Modulatore di Rame",
  progress = "Yebb sta preparando una nuova attrazione per lo Zoo Bizarre, una che farà impazzire la gente di meraviglia e di gioia! Ma ci vorrà un sacco di lavoro, e un sacco di materiali...$B$BTra questi ci sono i modulatori di rame. Ci servono tanti modulatori per le parti meccaniche dell'attrazione. Portami dei modulatori di rame e te li scambierò con un biglietto della Darkmoon Faire.",
  reward = "Ah! I modulatori! Magnifico!$B$BNon posso dirti esattamente cosa stiamo costruendo, ma saranno preziosissimi per costruirlo. Ti sono debitore, $N, ma ti prego, prendi questo biglietto della Darkmoon Faire come segno della mia riconoscenza.",
  en_title = "Copper Modulator",
}
T[7895] = {
  title = "Ingranaggi Rotanti di Bronzo",
  progress = "Il mio nuovo stand sarà uno spettacolo da vedere, sissignore! Uno spettacolo da vedere e... per pochi fortunati, da toccare!$B$BSento già gli ingranaggi rotanti di bronzo che cantano la loro canzone di estasi meccanica, mentre i clienti si avvicinano al mio stand e mettono alla prova la loro abilità!$B$BAh... ora mi servono gli ingranaggi veri e propri, per avvicinare il mio sogno alla realtà. Ti prego, $N, portami degli ingranaggi rotanti di bronzo... e i biglietti della Darkmoon Faire saranno tuoi!",
  reward = "Hai portato gli ingranaggi! Meraviglioso! Sento già nella mente il loro coro di ronzii e frullii! Oh, quando questo stand sarà pronto sarà la meraviglia del mondo, ricordatelo!$B$BEcco i tuoi biglietti, $N. E goditi il soggiorno alla Faire!",
  en_title = "Whirring Bronze Gizmo",
}
T[7896] = {
  title = "Fuochi d'Artificio Verdi",
  progress = "Quando finalmente avrò messo in piedi questo stand, vorrò farmi pubblicità! E quale modo migliore per farsi pubblicità se non i fuochi d'artificio?$B$BBe', qualcuno potrebbe pensare che l'odore di un calderone in cui bollono le teste dei tuoi nemici attiri di più la folla, ma... qui c'è gente di ogni genere. Quindi dovranno essere fuochi d'artificio!$B$BPortami dei fuochi d'artificio verdi, $N, e ho una bella manciata di biglietti della Darkmoon Faire per te.",
  reward = "Hai portato i fuochi d'artificio. Splendido lavoro, $N! Non vedo l'ora di accenderli e dire al mondo che il mio stand è pronto! Devo ancora aspettare, temo per parecchio tempo, ma... sarò pronto quando sarò pronto, no?$B$BEcco i biglietti, $N. Divertiti!",
  en_title = "Green Fireworks",
}
T[7897] = {
  title = "Kit per Riparazioni Meccaniche",
  progress = "Il motivo principale per cui non posso aprire il mio stand è che... è tutto rotto! Mi servono dei kit per riparazioni meccaniche, per aggiustare tutta questa roba!$B$BPuoi portarmi quei kit, $N? Facciamo uno scambio... kit in cambio di biglietti della Darkmoon Faire. Che ne dici?",
  reward = "Grazie! Adesso posso mettermi ad aggiustare le cose.$B$BCi vorranno un sacco di kit di riparazione e un sacco di nottate per rimettere tutto in funzione. A volte penso che sarebbe meglio tornare alle mie radici e ricominciare la carriera di cacciatore di teste, ma... la Faire mi ha trattato bene.$B$BPrendi questi biglietti, $N, e divertiti!",
  en_title = "Mechanical Repair Kits",
}
T[7899] = {
  title = "Piccole Zampe Pelose",
  progress = "La prima lezione per attirare la folla è: adescarla con aggeggi e ninnoli! Mi aiuti?$B$BMi servono delle piccole zampe pelose da usare come premi. Le trovi sui felini delle Barrens o di Darkshore...$B$BPortami qualche zampa e in cambio ti darò un biglietto della Darkmoon Faire.",
  reward = "Magnifico, le hai trovate! Possiamo usarle per fare giocattoli e gingilli, e quelli attireranno altra gente alla Faire!$B$BEcco il tuo biglietto, $N. Te lo sei guadagnato!",
  en_title = "Small Furry Paws",
}
T[7900] = {
  title = "Pelli d'Orso Strappate",
  progress = "I bambini adorano i giocattoli! E, di qualunque razza siano, ho scoperto che tutti i bambini adorano i giocattoli morbidi e pelosi fatti con pelli d'orso strappate!$B$BPuoi prendere quelle pelli dagli orsi di Ashenvale o di Hillsbrad. Portamene un mucchio e guadagnati un mucchio di biglietti della Darkmoon Faire!",
  reward = "Belle pelli, $N! Le farò cucire a qualcuno per farne un bel po' di peluche. Con un po' d'imbottitura e un po' di colore, credo che faranno invidia ai bambini di tutta Azeroth!$B$BI biglietti? Ah sì, il tuo pagamento! Eccoli!",
  en_title = "Torn Bear Pelts",
}
T[7901] = {
  title = "Code Folte Morbide",
  progress = "È incredibile a cosa la gente dia valore! Prendi, per esempio, un bastoncino di legno con attaccata una coda folta e morbida. Ora, tu e io potremmo pensare che una cosa del genere non valga granché... ma se dai a quella cianfrusaglia un nome accattivante come \"Coda Pelosa Selvaggia\" e la metti in una bella scatola, la gente penserà che abbia valore. La spazzatura diventa un tesoro!$B$BProcurami delle code folte e morbide dai lupi di Desolace e delle Badlands, e ti darò dei biglietti della Darkmoon Faire.",
  reward = "Ben fatto, $N! Queste code saranno ottimi premi per i nostri visitatori, e questo significa visitatori contenti... che ne parlano agli amici e portano altri visitatori!$B$BEcco i tuoi biglietti! Divertiti alla Darkmoon Faire... e non dimenticare di parlare di noi ai tuoi amici!",
  en_title = "Soft Bushy Tails",
}
T[7902] = {
  title = "Piume Vivaci",
  progress = "L'immaginazione di una persona è una cosa incredibile. Può far sembrare la collina più piccola la montagna più grande. Può far sembrare l'ombra più innocua quella di un incubo orribile!$B$BNoi della Darkmoon Faire lasciamo sbocciare l'immaginazione dei nostri visitatori! Ma per stimolarla un po'... a volte dobbiamo ricorrere a qualche trucco.$B$BMi servono delle piume vivaci per una delle mie attrazioni. Le trovi sugli uccelli delle zone più pericolose di Azeroth. Portami le piume, e molti biglietti saranno tuoi!",
  reward = "Ah, le piume! Sono stupende, non trovi! Con bellezze così sarebbe facile accendere l'immaginazione!$B$BFai proprio un'opera di bene, $N. I sorrisi sulle facce dei nostri visitatori quando vedono lo spettacolo sono già un grande compenso, ma ti prego, prendi anche questi biglietti.",
  en_title = "Vibrant Plumes",
}
T[7905] = {
  title = "La Darkmoon Faire",
  desc = "La Darkmoon Faire sta arrivando! Quando passa in città, non perderti tutte le sue meraviglie e le sue emozioni!$B$BSe ti muovi subito, puoi riscattare questo buono per dei biglietti premio gratis! Basta che consegni il buono a Gelvas Grimgate, dentro il luna park.$B$BIn questo momento la Faire è fuori Goldshire, nell'Elwynn Forest. Non perdertela! Vacci oggi stesso!",
  obj = "Consegna il Free Ticket Voucher a Gelvas Grimgate, dentro il luna park della Darkmoon Faire.",
  progress = "Sì, $Gamico:amica;, posso aiutarti? Hai un buono da riscattare?",
  reward = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE, sì, CINQUE biglietti premio!$B$BQuando avrai messo insieme dei biglietti premio, vieni a parlarmi per riscattarli e avere premi di valore. Più biglietti raccogli, più premi puoi vincere. Evviva!",
  en_title = "The Darkmoon Faire",
  en_obj = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
}
T[7908] = {
  title = "Maestro dell'Arena",
  desc = "Per essere $Gun maestro:una maestra; dell'arena ci vuole di più! Forse il Pirata che organizza l'evento a Gurubashi lo saprà!",
  obj = "Parla con Short John Mithril nell'Arena di Stranglethorn.",
}
T[7926] = {
  title = "La Darkmoon Faire",
  desc = "La Darkmoon Faire sta arrivando! Quando passa in città, non perderti tutte le sue meraviglie e le sue emozioni!$B$BSe ti muovi subito, puoi riscattare questo buono per dei biglietti premio gratis! Basta che consegni il buono a Gelvas Grimgate, dentro il luna park.$B$BIn questo momento la Faire è appena fuori Thunder Bluff, a Mulgore. Non perdertela! Vacci oggi stesso!",
  obj = "Consegna il Free Ticket Voucher a Gelvas Grimgate, dentro il luna park della Darkmoon Faire.",
  progress = "Sì, $Gamico:amica;, posso aiutarti? Hai un buono da riscattare?",
  reward = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE, sì, CINQUE biglietti premio!$B$BQuando avrai messo insieme dei biglietti premio, vieni a parlarmi per riscattarli e avere premi di valore. Più biglietti raccogli, più premi puoi vincere. Evviva!",
  en_title = "The Darkmoon Faire",
  en_obj = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.",
}
T[7930] = {
  title = "5 Biglietti — Fiore di Darkmoon",
  progress = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!",
  reward = "Ecco qua, ecco qua! Un premio degno di $Gun re:una regina;! Congratulazioni, $Gamico mio:amica mia;!$B$BSe hai altri biglietti da consegnare, fammelo sapere! Finché la Darkmoon Faire resta qui, riscatterò i tuoi biglietti.",
  en_title = "5 Tickets - Darkmoon Flower",
}
T[7931] = {
  title = "5 Biglietti — Premio di Darkmoon Minore",
  progress = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!",
