T[7936] = {
  title = "50 Biglietti — Montone dell'Anno Scorso",
  progress = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!",
  reward = "Ecco qua, ecco qua! Un premio degno di $Gun re:una regina;! Congratulazioni, $Gamico mio:amica mia;!$B$BSe hai altri biglietti da consegnare, fammelo sapere! Finché la Darkmoon Faire resta qui, riscatterò i tuoi biglietti.",
}
T[7939] = {
  title = "Altre Pietre da Molatura Dense",
  progress = "$N, grazie per tutto l'aiuto che mi hai dato. Non so davvero come ringraziarti!$B$BAnche se non ne ho più un gran bisogno... se mi porti altre pietre da molatura dense, ho ancora dei biglietti della Darkmoon Faire per te.",
  reward = "Grazie mille, $N. Ecco i tuoi biglietti della Darkmoon Faire!",
}
T[7940] = {
  title = "1200 Biglietti — Globo di Darkmoon",
  progress = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!",
  reward = "Ecco qua, ecco qua! Un premio degno di $Gun re:una regina;! Congratulazioni, $Gamico mio:amica mia;!$B$BSe hai altri biglietti da consegnare, fammelo sapere! Finché la Darkmoon Faire resta qui, riscatterò i tuoi biglietti.",
}
T[7941] = {
  title = "Altri Potenziamenti d'Armatura",
  progress = "$N, devo ringraziarti per tutto il tuo aiuto. Ho scorte in abbondanza, grazie ai tuoi notevoli sforzi, ma se vuoi portarmi altri potenziamenti d'armatura, li scambierò volentieri con dei biglietti della Darkmoon Faire.",
  reward = "Ecco a te, $N. Uno scambio equo. Buon divertimento.",
}
T[7942] = {
  title = "Altri Meccanismi di Torio",
  progress = "$N, sei $Gstato:stata; così $Gbuono:buona; con noi, a portarmi merci senza mai stancarti. Hai la mia eterna gratitudine!$B$BAnche se non abbiamo più tanto bisogno di meccanismi di Torio come una volta, puoi ancora portarmeli e li scambierò volentieri con dei biglietti della Darkmoon Faire.",
  reward = "Ecco a te, $N. Eccoti dei biglietti della Darkmoon Faire con cui divertirti. Non spenderli, come si suol dire, tutti in una volta!",
}
T[7943] = {
  title = "Altri Occhi di Pipistrello",
  progress = "$N, l'attrazione che sto progettando sarà l'evento più spaventoso da quando Gnomeregan è stata invasa! Ed è in gran parte merito tuo e di tutti i ninnoli che mi hai portato. Grazie, grazie mille!$B$BNon mi serve molto altro, ma... se mi porti altri occhi di pipistrello malvagio presi ai pipistrelli delle Eastern Plaguelands... potrei avere altri biglietti della Darkmoon Faire per te.",
  reward = "Grazie ancora, $N. Ecco i tuoi biglietti!",
}
T[7944] = {
  title = "La Tua Fortuna ti Attende...",
  desc = "\"La tua fortuna ti attende nelle Wailing Caverns.\"$B$BIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi l'immagine di una grotta a sud-ovest del Crossroads, nelle Barrens. Concentrandoti sull'immagine, segui passaggi tortuosi finché non raggiungi un portale scintillante... uno che conduce nel cuore stesso delle caverne. Quando lo attraversi, uno strano forziere compare dal nulla.",
  obj = "Raggiungi le Wailing Caverns, nelle Barrens, e va' in cerca della tua fortuna.",
  progress = "Questo forziere somiglia a quello della tua visione...",
  reward = "Frugando rapidamente nel forziere trovi una cassetta chiusa a chiave! Pare proprio che tu abbia trovato la tua fortuna!",
  en_title = "Your Fortune Awaits You...",
  en_obj = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.",
}
T[7981] = {
  title = "1200 Biglietti — Amuleto di Darkmoon",
  progress = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!",
  reward = "Ecco qua, ecco qua! Un premio degno di $Gun re:una regina;! Congratulazioni, $Gamico mio:amica mia;!$B$BSe hai altri biglietti da consegnare, fammelo sapere! Finché la Darkmoon Faire resta qui, riscatterò i tuoi biglietti.",
}
T[8041] = {
  title = "Forza del Monte Mugamba",
  reward = "Salute a te, $C. Io sono Jin'rokh lo Spezzatore, troll di Mugamba. Noi della tribù Zandalar riconosciamo le tue imprese. Rendiamo onore alla tua tenacia e alla tua forza di volontà.$B$BPorta al collo questo talismano, $C. Lascia che la forza del Monte Mugamba scorra in tutto il tuo essere. Che ti dia potere mentre abbatti i nostri nemici!",
}
T[8042] = {
  title = "Forza del Monte Mugamba",
  progress = "È bello vederti in buona salute, $N. Le gloriose battaglie che hai affrontato riguardano ogni forma di vita su questo pianeta. Hakkar non deve mai uscire dai confini di Zul'Gurub, perché il mondo crollerebbe di sicuro sotto la sua fame immensa.$B$BDammi il tuo talismano e ne amplificherò la forza. Usa l'Amuleto della Forza di Mugamba per punire i nostri nemici!",
  reward = "Le nostre strade si incroceranno ancora, $C.",
}
T[8043] = {
  title = "Forza del Monte Mugamba",
  progress = "$GMaestro:Maestra; $N, sei $Gtornato:tornata;! Molthor ha fatto sapere al Re delle tue imprese. Il tuo nome è conosciuto perfino nei Mari del Sud. Forse un giorno sarai $Gun:una; $C $Gleggendario:leggendaria; — una storia da tramandare nei secoli.$B$BDammi il tuo talismano, così che possa amplificarne ancora una volta il potere.",
  reward = "Usa la tua nuova forza per distruggere i Gurubashi!",
}
T[8044] = {
  title = "La Rabbia di Mugamba",
  progress = "Re Rastakhan ti manda i suoi saluti, $GMaestro:Maestra; $N. Un simile onore non era mai stato concesso a qualcuno estraneo alla tribù Zandalar.$B$B<Jin'rokh si inchina.>$B$BDammi il tuo talismano, così che possa potenziarlo ancora una volta. Sappi che la Rabbia di Mugamba è ormai intrinsecamente legata alla tua stessa anima.",
  reward = "Zul'jin sarebbe invidioso, $C. Va' e conquista!",
}
T[8045] = {
  title = "Il Marchio dell'Infedele",
  reward = "Sappi questo, infedele: una catastrofe ci ha uniti. Le tue usanze pagane non sono né comprese né apprezzate da Zandalar, ma noi siamo un popolo giusto. Porta questo marchio al collo. Sarà insieme un monito per i nostri nemici e un simbolo della tua amicizia con Zandalar.$B$BContinua a servire il nostro popolo e amplificherò il potere del marchio.",
}
T[8046] = {
  title = "Il Marchio dell'Infedele",
  progress = "Forse sono stato troppo frettoloso nel giudicare, $C. A quanto pare la tua fede cieca in questa Luce ha un qualche valore, dopotutto.$B$BDammi il tuo marchio e ne amplificherò il potere.",
  reward = "Fa' ciò che devi per sconfiggere i nostri nemici, $C. Anche se questo significa incanalare la Luce.$B$B<Jin'rokh rabbrividisce.>",
}
T[8047] = {
  title = "Il Marchio dell'Infedele",
  progress = "Devo confessarlo, non credevo che avessi la determinazione per portare fino in fondo questa causa, $C. Ora Zandalar ti considera $Gun alleato:un'alleata; di valore inestimabile. Ben fatto, davvero.$B$BDammi il tuo marchio e ne amplificherò ancora una volta il potere.",
  reward = "Le nostre fedi sono diverse, ma la nostra causa è giusta. Abbatti i nostri nemici, nobile $C.",
}
T[8048] = {
  title = "Il Marchio dell'Eroe",
  progress = "Il Re ha preso atto della tua esistenza, $C. Sei $Gil primo:la prima; della tua gente a essere $Gaccettato:accettata; da Rastakhan come $Gun vero alleato:una vera alleata; di Zandalar.$B$BI tuoi sforzi saranno ricompensati con generosità. Porgimi il tuo marchio e compirò l'ultima amplificazione.",
  reward = "Vigilanza, onore, lealtà, coraggio... Tu incarni tutte queste qualità, e così sarà anche per il tuo marchio.",
}
T[8049] = {
  title = "L'Occhio di Zuldazar",
  reward = "Accetta questo talismano come segno della nostra riconoscenza, $Gsacerdote:sacerdotessa;.$B$BL'Occhio di Zuldazar diventerà più potente man mano che il tuo legame con i troll di Zandalar si rafforzerà. Torna da me di tanto in tanto e io infonderò potere nel gioiello.",
}
T[8050] = {
  title = "L'Occhio di Zuldazar",
  progress = "$GBenvenuto:Benvenuta;, $Gsacerdote:sacerdotessa;. L'Occhio di Zuldazar pulsa di energia. Sei $Gpronto:pronta; per il passo successivo. Dammi il talismano e procederò all'infusione.",
  reward = "Continua la tua battaglia contro il Soulflayer e i suoi servitori, $N. Non gli si deve mai permettere di uscire dai confini di Zul'Gurub.",
}
T[8051] = {
  title = "L'Occhio di Zuldazar",
  progress = "I venti sussurrano i racconti delle tue battaglie contro i Gurubashi, $Gsacerdote:sacerdotessa;. Perfino i reali cominciano a parlare delle tue imprese. Si dice che Re Rastakhan abbia addirittura fatto il tuo nome.$B$BÈ giunto il momento di infondere potere nell'Occhio. Dammi il talismano e provvederò io.",
  reward = "Sii $Grisoluto:risoluta; nelle tue imprese, $N. Il Soulflayer cercherà di risucchiarti la volontà di vivere.",
}
T[8052] = {
  title = "L'Occhio Onniveggente di Zuldazar",
  progress = "Se solo ne avessimo altri diecimila come te, $N. Gli eserciti di Hakkar verrebbero dispersi al vento in un batter d'occhio.$B$B<Al'tabim sospira.>$B$BAhimè... ma l'Occhio è pronto a esprimere tutto il suo potenziale. Dammelo.",
  reward = "Puniscili tutti, Hakkar riconoscerà i suoi...",
}
T[8053] = {
  title = "Modelli di Potere: I Parabracci del Libero Pensatore",
  desc = "Sei $Gun pagano:una pagana;. I pagani hanno un posto nella tribù. I pagani sono i liberi pensatori di Zandalar. I liberi pensatori non temono l'oppressione. I liberi pensatori muoiono per ciò in cui credono. Sappiamo che tu moriresti per ciò in cui credi. Questo ti vale il nostro riconoscimento. Questo ti vale l'occasione di dimostrare ancora il tuo valore.$B$BDobbiamo avere i Modelli di Potere. Vai a Zul'Gurub. Uccidi i servitori di Hakkar. Torna quando avrai ciò che cerco. Prenditi il primo equipaggiamento da battaglia di un libero pensatore Zandalar.$B$BVai.",
  obj = "Porta a Jin'rokh the Breaker i Primal Hakkari Bindings. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata;? Hai i Modelli di Potere? Mi stai facendo perdere tempo?$B$BSpero di no, $Gpagano:pagana;.",
  reward = "Fai molto per onorarci. Le tue mani grondano del sangue dei servitori di Hakkar. Sei $Gun amico:un'amica; della tribù.$B$BIndossa questi bracciali. Sono i parabracci del libero pensatore. Ecco cosa intendo per vero potere.",
}
T[8054] = {
  title = "Modelli di Potere: La Cintura del Libero Pensatore",
  desc = "Le tue credenze ci sono estranee, $Gpagano:pagana;. Gli antichi Zandalar un tempo furono bollati come eretici. Fu quando l'Impero Gurubashi era forte. I pagani osarono sfidare il sacerdote di Hakkar. I pagani allora furono braccati e uccisi come parassiti. Quei pagani non vacillarono mai nella lotta contro il Dio del Sangue. Noi onoriamo il prezzo che pagarono. Sono loro i liberi pensatori.$B$BDistruggi i servitori di Hakkar a Zul'Gurub. Portami i Modelli di Potere che cerco. Il successo sarà ricompensato con generosità.$B$BVai.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Shawl. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "La tua presenza significa vittoria? Hai i Modelli? Grondi dei resti dei tuoi nemici?",
  reward = "Il tuo onore nella tribù è assicurato. Mieti molte vite a Zul'Gurub. I nemici cadono davanti alle tue convinzioni. I nemici cadono davanti al tuo potere.$B$BQuesta è la cintura del libero pensatore. È un simbolo d'onore. È un mojo potente. Ora è tua.",
}
T[8055] = {
  title = "Modelli di Potere: Il Pettorale del Libero Pensatore",
  desc = "L'equipaggiamento da battaglia ti dà potere nella tribù. Così si onorano i liberi pensatori. Sono fanatici. Infondono nei loro pettorali un mojo potente. Se le loro convinzioni vacillano davanti al nemico, il loro pettorale non vacillerà.$B$BPer possedere un pettorale simile devi essere $Gvenerato:venerata; fra noi. Vai a Zul'Gurub. Prendi i Modelli di Potere che mi servono. Prendi i Modelli agli stolti là dentro, nel modo più doloroso. Portameli. Dimostra una volta per tutte quanto vali come $Glibero pensatore:libera pensatrice;.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Tabard. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Hai i Modelli? Hanno dentro il mojo. Dobbiamo averli. Tu ci aiuterai.",
  reward = "Hai fatto ciò che pochi avrebbero mai potuto. Hai messo in ginocchio i servitori di Hakkar. Hai mostrato loro che cosa può fare un libero pensatore. Hai mostrato a noi come un eretico possa essere venerato nella tribù. Hai più del vero potere. Tu SEI il vero potere.$B$BPrendi il pettorale, $Glibero pensatore:libera pensatrice;. Schiaccia chi ti si oppone.",
}
T[8056] = {
  title = "Modelli di Potere: I Bracciali dell'Augure",
  desc = "Gli auguri della nostra tribù sono venerati per i doni della vista divina, eh già, mon. Mica sono stregoni; passano il tempo a lanciare le ossa o a leggere le foglie per vederci chiaro — non a fare fatture alla gente. Da $Gsciamano:sciamana;, ne sai già qualcosa del potere della divinazione; noi Zandalar teniamo in gran conto le intuizioni che danno alla tribù.$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub e dimostraci quanto vali. Fallo per noi, e ti do dei bracciali che i nostri auguri apprezzano più di tutti gli altri!",
  obj = "Porta a Maywiki of Zuldazar un Primal Hakkari Armsplint. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Ce li hai i Modelli di Potere di Zul'Gurub che mi servono? Questi bracciali la valgono tutta, la fatica che ti tocca fare!",
  reward = "Mi sa che dentro di te c'è un po' dell'augure Zandalar. Lo sappiamo cosa stai facendo a Zul'Gurub per conto nostro, mon. Questi Modelli di Potere daranno una gran mano alla tribù Zandalar — una tribù, ci tengo a dirlo, su cui puoi contare come su degli amici. Prendi questi bracciali, $N; te li sei guadagnati, e con gli interessi!",
}
T[8057] = {
  title = "Modelli di Potere: I Bracciali dell'Aruspice",
  desc = "Un aruspice è un membro fondamentale della nostra tribù; farai bene a dar retta ai suoi presagi. Sta in comunione con gli animali e, quando serve, li offre agli spiriti: così ci dà una guida divina. In passato, l'intuito e la saggezza dell'aruspice ci hanno dato un vantaggio nelle guerre contro le tribù frammentate dei Gurubashi.$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub e dimostraci quanto vali. Fallo, e ti do dei bracciali che qualunque aruspice degli Zandalar vorrebbe.",
  obj = "Porta a Maywiki of Zuldazar un Primal Hakkari Stanchion. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Ce li hai i Modelli di Potere di Zul'Gurub? Questi bracciali valgono la fatica, $N. Fidati, mon!",
  reward = "Ah, lo sento il potere che viene da questi Modelli di Potere, $N. Hai dimostrato di essere qualcuno che noi della tribù possiamo chiamare \"$Gamico:amica;\". I patti sono patti, $N... ammira il potere dei bracciali dell'aruspice!",
}
T[8058] = {
  title = "Modelli di Potere: I Parabracci del Vendicatore",
  desc = "La vendetta è potere. Il vendicatore Zandalar è questo potere. La tribù ha molti nemici. Il vendicatore gliela fa pagare. Nessun crimine contro di noi resta impunito. È il vendicatore a infliggere la punizione. I nostri nemici temono la nostra vendetta. E fanno bene. La temeranno per sempre.$B$BDiventa $Guno dei nostri vendicatori:una delle nostre vendicatrici;. Cerca i Modelli di Potere dentro Zul'Gurub. Uccidi i servitori di Hakkar e compi la vendetta in nome della tribù. Sarai $Gricompensato:ricompensata;.",
  obj = "Porta un Primal Hakkari Armsplint a Jin'rokh the Breaker. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Hai portato i Modelli di Potere? La vendetta è stata compiuta in nome degli Zandalar?",
  reward = "Oggi hai compiuto una grande vendetta. Hai preso le sembianze del vendicatore. Hai messo in ginocchio i servitori del Dio del Sangue.$B$BPrendi questo. Alimenterà la tua vendetta in futuro. Ora sei $Gun amico:un'amica; degli Zandalar.",
}
T[8059] = {
  title = "Modelli di Potere: Le Fasce dell'Indemoniato",
  desc = "Gli stregoni camminano su un terreno pericoloso quando trattano con i demoni, ma i nostri indemoniati si spingono un passo più in là. Con un rituale antico e arcano lasciano che un demone entri dentro di loro. Invece di farsi possedere, però, rendono schiavo il demone dall'interno e assorbono il potere della bestia per averlo al proprio comando. È un'impresa che pochissimi riescono a padroneggiare.$B$BPerché tu conosca il potere dell'indemoniato, mi servono dei Modelli di Potere di Zul'Gurub. Vai là e recupera quello che cerchiamo.",
  obj = "Porta un Primal Hakkari Stanchion ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; con i Modelli di Potere? Sconfiggendo i diabolici servitori di Hakkar ci dimostrerai non solo quanto vali, ma anche che vuoi davvero imparare le vie dell'indemoniato.",
  reward = "Ben fatto... di sicuro l'hanno pagata tra atroci sofferenze, prima di cedere i Modelli di Potere. Prendi queste — le fasce dell'indemoniato. Sono fatte con il mojo potente usato per evocare le prede dell'indemoniato, e sono uno strumento potente per la tua conquista del potere.",
}
T[8060] = {
  title = "Modelli di Potere: Le Fasce dell'Illusionista",
  desc = "Nella nostra tribù i maghi sono chiamati illusionisti. Nei loro incantesimi usano un mojo potente, che spesso lascia i nemici della tribù frastornati e confusi!$B$B<Al'tabim fa una risata maligna.>$B$BÈ un vero spettacolo vedere all'opera un illusionista potente, che mette in ginocchio i nostri nemici con la loro stessa follia!$B$BPer conoscere la via dei nostri illusionisti, vai a Zul'Gurub e riportami alcuni Modelli di Potere scelti. In cambio ti darò le fasce per le braccia che i nostri illusionisti usano per tessere gli incantesimi.",
  obj = "Porta i Primal Hakkari Bindings ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "$N — sei già $Gtornato:tornata;? Sei $Griuscito:riuscita; a prendere i Modelli di Potere che mi servono?",
  reward = "Notevole... l'hai sentito, il mojo che li attraversa? I Modelli di Potere erano usati come una specie di moneta quando l'Impero Gurubashi dominava queste terre. Ora noi Zandalar useremo il mojo latente che contengono per combattere la seconda ascesa del Dio del Sangue Hakkar!$B$BOggi hai fatto un buon lavoro — sappi che negli Zandalar hai un amico. Per questo, ecco le fasce dell'illusionista che ti avevo promesso!",
}
T[8061] = {
  title = "Modelli di Potere: Le Fasce del Confessore",
  desc = "Noi Zandalar diamo potere a chi parla con l'autorità del divino. I nostri sacerdoti sono più che semplici guaritori — sono i nostri confessori. Il male viene sia dalle minacce esterne — come Hakkar — sia dall'interno della tribù. I nostri confessori sono i giudici in mezzo a noi, e ci preservano dallo stesso male che ha divorato i Gurubashi dall'interno.$B$BVai a Zul'Gurub e riporta i Modelli di Potere dei Gurubashi. Impara cosa significa essere il confessore, e preservaci dal male.",
  obj = "Porta un Primal Hakkari Stanchion ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "$GTornato:Tornata; da Zul'Gurub, eh? Sei $Griuscito:riuscita; a recuperare i Modelli di Potere dai servitori di Hakkar?",
  reward = "Eccezionale, $N! Portarmeli non è stata un'impresa da poco. Oggi hai senz'altro agito da confessore della nostra tribù, preservandoci dalla minaccia di Hakkar. Queste fasce si addicono a $Gun amico:un'amica; della tribù come te!",
}
T[8062] = {
  title = "Modelli di Potere: I Bracciali del Predatore",
  desc = "Nei tempi bui dopo la caduta dell'Impero Gurubashi, i predatori Zandalar usarono la loro abilità per dare sostentamento alla tribù. I cacciatori sostengono di somigliare molto ai predatori della nostra tribù — dedicarsi alla caccia è incarnare l'essenza del predatore, sì. La tua caccia a Zul'Gurub, però, ci mostrerà quanto vali davvero in confronto ai nostri predatori migliori.$B$BPortami una selezione dei Modelli di Potere che si trovano a Zul'Gurub. Fallo, e muoverai i primi passi per diventare $Gil predatore supremo:la predatrice suprema;.",
  obj = "Porta a Falthir the Sightless questi Modelli di Potere di Zul'Gurub: i Primal Hakkari Bindings. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Dai la caccia a quelli che a Zul'Gurub detengono i Modelli di Potere, $N. Sono loro le tue prede; possiedono ciò che tu e io dobbiamo avere.",
  reward = "Sì... non mi serve la vista per avvertire la presenza dei Modelli di Potere. Il tuo successo a Zul'Gurub ha colpito molti nella tribù. Non solo ti consideriamo $Gun amico:un'amica; degli Zandalar, ma ti riteniamo anche $Gdegno:degna; di possedere i bracciali del predatore — oggetti potenti, e un simbolo di cosa significa essere un predatore. Ben fatto, $N.",
}
T[8063] = {
  title = "Modelli di Potere: I Bracciali del Folle",
  desc = "I folli di Zandalar somigliano ai ladri, ma più di ogni altra cosa abbracciano la follia... il caos... l'imprevedibilità dell'esistenza. Terribili a vedersi sul campo di battaglia, seminarono confusione e scompiglio tra i nostri nemici nei tempi selvaggi dopo che le tribù si furono divise. Senza di loro oggi non saremmo qui.$B$BPortami i Modelli di Potere di Zul'Gurub che cerco, e ti concederò la prima delle preziose armature del folle. Abbraccia la follia!",
  obj = "Porta un Primal Hakkari Armsplint a Falthir the Sightless. Devi anche avere una reputazione pari o superiore a Friendly con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Cerca la follia dentro Zul'Gurub e mettila in ombra con la tua, $N! Riuscirci vuol dire successo, e successo vuol dire ricompensa! Non lasciare che il Dio del Sangue torni a regnare sovrano!",
  reward = "Ben fatto, $N... con le tue imprese a Zul'Gurub ti sei $Gguadagnato:guadagnata; il diritto di chiamare amica la tribù Zandalar. A cosa fare dei Modelli penserò io; per il tuo impegno, accetta questa ricompensa!",
}
T[8064] = {
  title = "Modelli di Potere: La Cintura dell'Aruspice",
  desc = "Noi Zandalar non sappiamo niente delle vie dei druidi; è la natura che va plasmata sui nostri bisogni, non il contrario. Però l'aruspice è quello di noi più in sintonia con la natura, e a ragione. Far esalare l'ultimo respiro a una bestiola è sapere cosa vuol dire essere una di loro. È quello il vero potere della natura.$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub, e dimostraci quanto vali. Fallo, e ti darò un oggetto potente — una cintura usata da molti aruspici degli Zandalar.$B$BMojo forte, eh già, mon!",
  obj = "Porta un Primal Hakkari Sash a Maywiki of Zuldazar. Maywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale. Devi anche essere Honored con gli Zandalar.",
  progress = "Ce li hai i Modelli di Potere di Zul'Gurub che mi servono? Se ce li hai, la cintura dell'aruspice è tua.",
  reward = "Ti ringrazio — il potere latente in questi oggetti sarà già un tesoro di per sé, ci puoi scommettere. Non solo hai fatto quello che ti avevo chiesto, ma hai anche dimostrato a noi della tribù di essere una persona d'onore. Come promesso, ecco la tua ricompensa!",
}
T[8065] = {
  title = "Modelli di Potere: La Tunica dell'Aruspice",
  desc = "Il simbolo supremo del potere di un aruspice è quello che indossa, $N. Fra questi indumenti, la tunica simboleggia il legame tra l'aruspice e la saggezza divina che cerca. Spesso nella tunica sono intessute parti delle bestiole che sacrifica; questo gli ricorda il legame che ha con i suoi doni.$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub e dimostraci quanto vali. Fallo, e una tunica intrisa del vero potere di un aruspice è tua.",
  obj = "Porta un Primal Hakkari Tabard a Maywiki of Zuldazar. Maywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale. Devi anche essere Revered con gli Zandalar.",
  progress = "Ce li hai i Modelli di Potere di Zul'Gurub che servono? La tunica dell'aruspice vale bene tutta la fatica che ti tocca fare.",
  reward = "Notevole... sei $Griuscito:riuscita; a raccogliere i Modelli di Potere richiesti, $N. Le tue imprese a Zul'Gurub per gli Zandalar sono leggendarie; d'ora in avanti nella tribù sarai $Griverito:riverita;. Ecco la tua tunica, potente $C!",
}
T[8066] = {
  title = "Modelli di Potere: La Cintura del Predatore",
  desc = "Un predatore sa come braccare la preda, ma un predatore vincente sa come colpirla una volta che le è arrivato vicino. Devi padroneggiare tutte e due le cose per avere qualche speranza di successo a Zul'Gurub... e qualche speranza di essere come i predatori Zandalar.$B$BPortami dei pezzi scelti dei Modelli di Potere di Zul'Gurub. La mia ricompensa sarà il potere che quei monili sprigionano, mentre la tua sarà la cintura del predatore Zandalar — un equipaggiamento che vale bene lo scambio.",
  obj = "Porta a Falthir the Sightless questi Modelli di Potere di Zul'Gurub: un Primal Hakkari Shawl. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Colpisci i servitori impazziti di Hakkar a Zul'Gurub — sono loro ad avere i Modelli di Potere, $N. Dimostra a loro — e alla tribù — il tuo successo come aspirante predatore.",
  reward = "Ho avvertito il tuo arrivo con qualche istante d'anticipo, $N, ma non senza fatica. A rivelarti a me sono stati i Modelli di Potere che hai portato. Ne sento il potere senza bisogno di vedere quei monili; il loro mojo latente — magia allo stato grezzo, se vuoi — continuerà ad alimentare i nostri sforzi per sventare i piani diabolici del Dio del Sangue Hakkar.$B$BPer il tuo successo meriti un elogio — e una ricompensa. Nella tribù sei $Gonorato:onorata;, e sei $Gdegno:degna; di indossare la cintura del predatore.",
}
T[8067] = {
  title = "Modelli di Potere: Il Coprispalla del Predatore",
  desc = "Noi Zandalar teniamo molto a ciò che indossiamo, come simbolo dei traguardi raggiunti. Non serve poter vedere quello che uno indossa per avvertire ciò che ne emana — il potere va oltre la vista. Gli indumenti del predatore Zandalar sono così, e quello a cui tiene di più è il coprispalla che porta. Lo aiuta a nascondersi alla vista... e a far notare la sua presenza quando lo desidera.$B$BI Modelli di Potere aspettano a Zul'Gurub che tu vada a recuperarli. Portami quello che cerco, e il coprispalla del predatore sarà tuo.",
  obj = "Porta a Falthir the Sightless questi Modelli di Potere di Zul'Gurub: un Primal Hakkari Aegis. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Le tue incursioni a Zul'Gurub hanno avuto successo, $N? Solo quando mi avrai portato quello che cerco — e avrai dato piena prova di te alla tribù — ti guadagnerai un coprispalla che fra gli Zandalar non è secondo a nessuno.",
  reward = "Ce l'hai fatta... nella tribù sarai $Griverito:riverita;, $N. Procurarsi i Modelli di Potere necessari per il coprispalla non è stata un'impresa da poco, ma te la sei cavata alla maniera dei più letali fra i nostri predatori. Ti sei $Gguadagnato:guadagnata; il tuo posto fra loro, e di certo ti sei $Gguadagnato:guadagnata; il diritto di indossare il loro coprispalla.",
}
T[8068] = {
  title = "Modelli di Potere: Il Coprispalla dell'Illusionista",
  desc = "La magia è una forza grezza e primordiale, e plasmarla spetta a chi è abbastanza forte da farlo. Il mojo è il modo in cui noi estendiamo questo potere; e una delle forme più potenti in cui lo si manipola è l'illusione. Come si può davvero sperare di vincere contro un nemico che in realtà non c'è nemmeno? Noi Zandalar ne conosciamo il potere, e per questo gli illusionisti hanno un posto d'onore nella tribù.$B$BPrendi a Zul'Gurub i Modelli di Potere necessari — in cambio avrai l'onore della tribù e un potente coprispalla usato dai nostri illusionisti migliori!",
  obj = "Porta un Primal Hakkari Shawl ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Com'è andata la tua incursione a Zul'Gurub? Hai fatto impazzire i nemici con il potere dell'illusione? Illusione o no, la loro morte — e i Modelli di Potere tolti loro — aiuteranno a fermare l'ascesa di Hakkar.",
  reward = "Ce l'hai fatta! D'ora in poi nella tribù sarai $Gonorato:onorata;! Oggi Zul'Gurub ha di certo assaggiato la forza degli Zandalar, grazie a te, $N.$B$BCon la benedizione della tribù, prendi il coprispalla dell'illusionista Zandalar. Possa esserti di grande aiuto.",
}
T[8069] = {
  title = "Modelli di Potere: Le Vesti dell'Illusionista",
  desc = "La tribù riconosce rango e potere da ciò che indossiamo. I nostri paramenti sono fatti con i materiali più pregiati, e intessuti del mojo che usiamo per renderci potenti. Gli illusionisti non fanno eccezione; si dice che le loro vesti incarnino nell'aspetto l'essenza dell'illusione. La leggenda narra che le loro vesti antiche non avessero mai due volte lo stesso aspetto.$B$BTi darò una veste da illusionista, $N... ma prima guadagnati il tuo posto fra chi la tribù riverisce! Portami i Modelli di Potere di Zul'Gurub!",
  obj = "Porta un Primal Hakkari Kossack ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; con i Modelli di Potere che ci servono? So che non sarà facile... ma da tempo ho predetto che qualcuno da fuori sarebbe venuto ad aiutarci nella lotta contro Hakkar. Che sia tu, dico io!",
  reward = "Finalmente qualcuno degno di indossare la veste dell'illusionista! Il tuo successo a Zul'Gurub ti ha assicurato la riverenza della tribù per i secoli a venire. Indossala con orgoglio, $N!",
}
T[8070] = {
  title = "Modelli di Potere: I Legacci del Confessore",
  desc = "Poco dopo la caduta dei Gurubashi, noi Zandalar per poco non soccombemmo a una sconfitta definitiva, per il male che c'era dentro la nostra stessa tribù. Fu allora che fra noi sorsero i confessori, che preservarono la tribù bandendo chi voleva distruggere la propria gente. Non solo ci tengono in sintonia con gli spiriti, ma preservano anche la carne.$B$BEntra a Zul'Gurub e guarda con i tuoi occhi la depravazione di Hakkar e dei Gurubashi. Strappa loro i Modelli di Potere che cerchiamo; il successo sarà ricompensato!",
  obj = "Porta un Primal Hakkari Sash ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "I Modelli di Potere... li hai? Solo quando li avremo potremo servirci del potere latente che racchiudono. Sarà bello ribaltare le sorti contro i servitori del Dio del Sangue...",
  reward = "Ce l'hai fatta! Questi ci aiuteranno molto ad accrescere il nostro potere contro l'ascesa di Hakkar. Con il tuo aiuto abbiamo fatto un passo importante per impedire che il Dio del Sangue ci distrugga tutti.$B$BOggi ti sei $Gguadagnato:guadagnata; l'onore della tribù, $N. Prendi questi — i legacci del confessore — come simbolo della nostra gratitudine.",
}
T[8071] = {
  title = "Modelli di Potere: Il Coprispalla del Confessore",
  desc = "I confessori degli Zandalar portano tutti un coprispalla particolare, che li distingue come coloro che preservano la tribù. In questi coprispalla è intessuto un mojo potente, che li aiuta a giudicare chi minaccia la nostra tribù. Anche tu, da $Gsacerdote:sacerdotessa;, devi passare il tempo a giudicare chi è degno e chi no; un coprispalla così sarebbe senz'altro una benedizione per te.$B$BSe combatterai i servitori di Hakkar a Zul'Gurub e mi porterai i Modelli di Potere che cerco, in cambio ti darò un coprispalla degno dei nostri confessori migliori.",
  obj = "Porta un Primal Hakkari Aegis ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Hai i Modelli di Potere di Zul'Gurub?",
  reward = "Ben fatto, $N — oggi i servitori di Hakkar hanno di certo sentito il castigo degli Zandalar, grazie a te. Con le tue azioni ti sei $Gguadagnato:guadagnata; per sempre un posto fra chi la tribù riverisce. Con la nostra benedizione, prendi questo coprispalla da confessore e fallo tuo!",
}
T[8072] = {
  title = "Modelli di Potere: Il Coprispalla del Folle",
  desc = "Uno dei folli leggendari di Zandalar fu Khar'vaxal lo Svitato. La leggenda narra che, quando affrontò per la prima volta i nemici della tribù, Khar'vaxal usò il suo coprispalla, intessuto apposta con \"la trama della follia\". La sua figura era velata non solo dal coprispalla, ma anche dalla velocità accecante dei suoi pugnali gemelli. Oggi i folli tengono molto al loro coprispalla, segno del loro posto nella tribù.$B$BPortami i Modelli di Potere che cerco, e un coprispalla così sarà tuo, per tessere la follia sui tuoi nemici.",
  obj = "Porta un Primal Hakkari Girdle a Falthir the Sightless. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Sei $Gtornato:tornata; — hai i Modelli di Potere che mi servono?$B$BLa leggenda di Khar'vaxal lo Svitato ci ricorda ancora oggi che nessun nemico — per quanto grande sia la minaccia — è impossibile da battere. Il caos metterà tutti in ginocchio, questo è certo... e forse gli elementi meno caotici del caos.",
  reward = "Oggi la vittoria è nostra, grazie alla follia che hai seminato fra i nostri nemici comuni! Fra gli Zandalar sarai $Gonorato:onorata;, e non c'è modo migliore di mostrarti gratitudine per le tue imprese che offrirti il coprispalla del folle!",
}
T[8073] = {
  title = "Modelli di Potere: La Tunica del Folle",
  desc = "Gli occhi mi hanno abbandonato molto tempo fa, ma non ne sento la mancanza. Perfino in una tribù come la nostra — dove i paramenti dicono il rango e lo scopo di ciascuno — gli abiti più potenti sprigionano un potere che i semplici occhi non possono vedere. La preziosa tunica del folle Zandalar non fa eccezione, e sprigiona il potere grezzo del caos e della follia che il folle sa incanalare.$B$BI Modelli di Potere che mi servono si trovano a Zul'Gurub; portami quello che cerco, e ti ricompenserò con una tunica leggendaria tutta tua... una tunica che si addice a chi tesse la follia.",
  obj = "Porta un Primal Hakkari Aegis a Falthir the Sightless. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BFalthir the Sightless si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "$GBentornato:Bentornata; sull'Isola, $N... sei $Gtornato:tornata; in trionfo, con i Modelli di Potere al seguito?",
  reward = "Notevole... oggi hai compiuto ciò che pochi credevano possibile. La riverenza della tribù ti è assicurata per tutta la vita, $N. Ti sei $Gguadagnato:guadagnata; il diritto di indossare la tunica del folle — fallo con la nostra benedizione.",
}
T[8074] = {
  title = "Modelli di Potere: La Cintura dell'Augure",
  desc = "Gli auguri conoscono il mojo degli elementi, mon. Lo usano per guidare la tribù alla gloria. Nei giorni bui dopo che l'Impero Gurubashi si fece a pezzi da solo, i nostri auguri ci guidarono al nostro rifugio sicuro nei Mari del Sud. E ci hanno anche riportati qui nella Vale, dritti nel cuore del male che cova a Zul'Gurub.$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub e dimostraci quanto vali. Fallo e ti darò una cintura che usano i nostri auguri — con dentro un mojo potente!",
  obj = "Porta un Primal Hakkari Girdle a Maywiki of Zuldazar. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Sono i Modelli di Potere che mi servono, mon — gli spremeremo fuori tutto il potere nella nostra lotta contro il male di Zul'Gurub. Ce li hai per me?",
  reward = "Ti sento addosso l'odore del male sconfitto, $N. È un odore dolce, mon... uno che mi sa che conosci bene.$B$BLo so che non è cosa da poco avermi portato i Modelli di Potere che servivano per la cintura. Le tue imprese non hanno solo fatto onore alla tribù, ma hanno fatto onore anche a te davanti alla mia tribù. Ecco qua — prendi la cintura dell'augure e indossala, è tua!",
}
T[8075] = {
  title = "Modelli di Potere: L'Usbergo dell'Augure",
  desc = "Gli auguri degli Zandalar portano tutti un pettorale particolare chiamato usbergo. È rivestito delle sete e delle stoffe più pregiate, intrecciate con una maglia robusta. È un simbolo non solo della loro divinità, ma anche della loro autorità, mon. Non è mai saggio mettersi contro uno che dedica la vita a parlare con gli spiriti...$B$BPortami un'offerta di Modelli di Potere da dentro Zul'Gurub e dimostraci quanto vali. Fallo e ti darò uno degli usberghi più belli che i nostri auguri possano mai sperare di indossare!",
  obj = "Porta un Primal Hakkari Tabard a Maywiki of Zuldazar. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BMaywiki of Zuldazar si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "I Modelli di Potere sono una fonte fondamentale di potere magico — lo stesso tipo di potere che serve per fare l'usbergo dell'augure. Portami quello che mi serve, e potrò farti avere il paramento più bello che un augure Zandalar possa volere per sé.",
  reward = "Lo so cosa hai dovuto passare per portarmi i Modelli di Potere, $N. Non è stato facile, mon — sconfiggere il male che cola fuori da Zul'Gurub come una melma schifosa — ma adesso che è tutto finito posso dire tranquillamente che fra gli Zandalar sarai $Griverito:riverita; per i secoli a venire!$B$BEcco — prendi l'usbergo dell'augure e indossalo con orgoglio!",
}
T[8076] = {
  title = "Modelli di Potere: Il Coprispalla dell'Indemoniato",
  desc = "L'indemoniato cerca di incarnare il potere in tutto e per tutto, non solo di possederlo. Più di uno dei nostri indemoniati ha perso la lotta con un demone; con i nemici che ci minacciano — soprattutto a Zul'Gurub — il potere che un indemoniato riesce a scatenare sui nostri avversari vale il sacrificio. Per sopravvivere dobbiamo schiacciare chi vuole distruggerci; ce l'ha insegnato la caduta dell'Impero Gurubashi.$B$BVai a Zul'Gurub e procurati i Modelli di Potere che ci servono. Fallo, e un prezioso oggetto da indemoniato sarà tuo.",
  obj = "Porta un Primal Hakkari Sash ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Hai recuperato i Modelli di Potere a Zul'Gurub? Noi prenderemo il potere latente di questi oggetti e li faremo nostri, ma se avrai successo daremo anche a te una ricompensa di potere...",
  reward = "Ben fatto, $N. I Modelli di Potere di Zul'Gurub dovrebbero servire a ricordare il potere sprecato. I Gurubashi al loro apice erano forti, ma dal potere si lasciarono consumare. Un indemoniato sa di giocare una partita molto simile, ma il potere che scatena è spesso proprio ciò che serve per sopravvivere.$B$BUsa questo coprispalla in quanto $Galleato onorato:alleata onorata; degli Zandalar... ti sarà molto utile.",
}
T[8077] = {
  title = "Modelli di Potere: Le Vesti dell'Indemoniato",
  desc = "Nella tribù il simbolo supremo del potere sono gli abiti che portiamo in battaglia. Nelle vesti di un indemoniato, pregiato runecloth e un mojo di potenza devastante sono fusi in un unico tessuto. Si dice che l'aspetto della veste incuta paura nella mente di chiunque la veda... soprattutto dei demoni che l'indemoniato finirà per dominare.$B$BDa Zul'Gurub devi portarmi un insieme ben preciso di Modelli di Potere. Sarà difficile... ma se avrai successo, una veste sarà di sicuro tua.",
  obj = "Porta un Primal Hakkari Kossack ad Al'tabim the All-Seeing. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BAl'tabim the All-Seeing si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "I Modelli di Potere... li hai riportati? Solo quando li avremo condivideremo con te il simbolo supremo del potere dell'indemoniato, $N.",
  reward = "Notevole — la tua vittoria a Zul'Gurub ha dato a noi — anzi, al mondo — la certezza che Hakkar non prevarrà. Potrebbe venire il momento in cui affronterai direttamente il Dio del Sangue... e se dovesse accadere, sappi che la riverenza della tribù Zandalar ti è assicurata.$B$BAh, e credo che anche questa semplice veste ti darà una mano.$B$B<Al'tabim ti fa l'occhiolino con aria complice.>",
}
T[8078] = {
  title = "Modelli di Potere: La Cintura del Vendicatore",
  desc = "La vendetta suprema attende dentro Zul'Gurub. Hakkar non deve risorgere. Hakkar distrusse l'Impero Gurubashi dall'interno. Nessun sacrificio bastava. I troll sono l'ombra delle glorie di un tempo. So che la colpa è di Hakkar.$B$BDiventa $Gil vendicatore:la vendicatrice; che eri $Gdestinato:destinata; a essere. Semina la rovina tra i servitori del male. Zul'Gurub deve assaggiare la vendetta degli Zandalar. Portami come prova i Modelli di Potere. Riceverai la cintura del vendicatore. Riceverai il vero potere.$B$BVai.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Girdle. Devi anche avere una reputazione pari o superiore a Honored con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "Hai portato i Modelli di Potere? Hai abbattuto i nemici della tribù? Hakkar deve conoscere l'ira del vendicatore!",
  reward = "Ora la via del vendicatore ti è nota. Hai portato onore alla tribù. Hai portato onore a te $Gstesso:stessa;. Hai portato dolore ai nostri nemici.$B$BLa cintura del vendicatore è tua. Stai senz'altro diventando una cosa sola con la via del vendicatore.",
}
T[8079] = {
  title = "Modelli di Potere: Il Pettorale del Vendicatore",
  desc = "Il simbolo del potere del vendicatore è il pettorale. È forgiato con un mojo potente. Viene affidato solo a chi veneriamo. È il simbolo della vendetta degli Zandalar.$B$BDiventare un vendicatore è diventare la vendetta. Prendi a Zul'Gurub i Modelli di Potere che ci servono. Portaceli. Ci riprenderemo il mojo che ci è stato rubato. La faremo pagare ai servitori di Hakkar. Ti ricompenseremo con il pettorale del vendicatore.$B$BVai. Sii la nostra vendetta, $N.",
  obj = "Porta a Jin'rokh the Breaker un Primal Hakkari Kossack. Devi anche avere una reputazione pari o superiore a Revered con la Zandalar Tribe.$B$BJin'rokh the Breaker si trova sull'Isola di Yojamba, a Stranglethorn Vale.",
  progress = "La tua presenza significa vittoria? Hai i Modelli di Potere? Raccontami della vendetta che hai compiuto oggi!",
  reward = "Le tue gesta meritano venerazione. La tribù ricompensa i suoi eroi. Zul'Gurub ha assaggiato la vendetta degli Zandalar come mai prima.$B$BLe tue gesta annunceranno quelle di altri che verranno. Guarderanno a te come a un segno del vero potere. Guarderanno a te come alla vendetta fatta persona!",
}
T[8080] = {
  title = "Contrassegno d'Onore di Arathi Basin!",
  desc = "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!$B$BEcco perché Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname — servono tutti, e tutti si possono ottenere lì.$B$BÈ questo che voglio da te, $N. Entra in Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear, a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? La League of Arathor non può combattere come si deve senza di essi...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle nostre truppe.$B$BGrazie, $N. È proprio portando a termine missioni come la tua che si vincono davvero le guerre.",
}
T[8101] = {
  title = "Il Ciottolo di Kajaro",
  reward = "$R, il ciottolo racchiuso nella montatura di questo talismano viene dal Monte Kajaro, nei Mari del Sud. Il Monte Kajaro è una zona tormentata dall'instabilità — segnata da eruzioni vulcaniche violente e spesso magiche.$B$BCome cresce il tuo legame con i troll di Zandalar, così crescerà il potere di questo ciottolo. Sfrutta il potere del ciottolo per abbattere i nostri nemici. Sii come la montagna: $GRapido:Rapida;, $Gesplosivo:esplosiva;, letale...",
}
T[8102] = {
  title = "Il Ciottolo di Kajaro",
  progress = "$GBentornato:Bentornata;, $C. Vedo che il ciottolo è stato usato molto. Molti dei nostri nemici sono caduti sotto i tuoi poteri ultraterreni. La loro sofferenza è stata grande. È ora che io accresca il potere del ciottolo. Dammelo.",
  reward = "Sii inarrestabile, come i fronti di lava di Kajaro.",
}
T[8103] = {
  title = "Il Ciottolo di Kajaro",
  progress = "Gli Hakkari ti temono, $N. Parlano di orrori che credevano potesse commettere solo il loro Dio senza volto. Li hai bruciati con la forza di Kajaro. Ora conoscono la paura su due fronti.$B$BÈ ora di rafforzare ancora il ciottolo. Dammi il talismano.",
  reward = "Continua a decimare i troll di Zul'Gurub. Hakkar deve vedere che il mondo non si piegherà sotto la sua volontà indomabile.",
}
T[8104] = {
  title = "Il Gioiello di Kajaro",
  progress = "Dammi il talismano, $N. Devo mostrarti una cosa.",
  reward = "<Al'tabim frantuma il ciottolo con una potente forza invisibile.>$B$BVedi? Il ciottolo è quello che noi chiamiamo un geode. Dentro il ciottolo ci sono potenti cristalli che si sono impregnati delle energie latenti del nostro mondo. Tagliando il ciottolo a metà, ho finalmente permesso al suo potenziale di esprimersi appieno. Usalo per annientare i nostri nemici.",
}
T[8105] = {
  title = "La Battaglia per Arathi Basin!",
  desc = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.$B$BAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!$B$BQuando l'avrai fatto con tutti e quattro i punti, torna da me.",
  obj = "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight, a Refuge Pointe.",
  progress = "$N, non hai ancora assaltato le quattro basi. Torna da me quando avrai completato i tuoi obiettivi.",
  reward = "Ho ricevuto rapporti sulle tue imprese in Arathi Basin, $N. Ben fatto! Con gente come te che viene a combattere qui, confido che un giorno riprenderemo le nostre terre d'origine.",
}
T[8106] = {
  title = "Marchio di Kezan",
  reward = "Accetta questo talismano, $C. Accettalo e usa il suo potere per abbattere i nostri nemici comuni.$B$BSappi che al collo porti un pezzo di storia. Kezan era un tempo un grandioso territorio dell'Impero di Zandalar. Ahimè, la corruzione dei principi mercanti goblin avrebbe poi scacciato i miei fieri fratelli e sorelle.$B$BOra Kezan ospita Undermine, la capitale dei goblin; ma sappi che prima della corruzione conobbe la grandezza. Ancora oggi Kezan è considerata terra sacra dal mio popolo.",
}
T[8107] = {
  title = "Marchio di Kezan",
  progress = "Fra i troll Zandalar l'onore si guadagna, $N. Con l'onore arriva la ricompensa — amicizia, alleanza...$B$BDammi il talismano, così che io possa accrescerne il potere.",
  reward = "Attingi dall'oscurità, $C. Abbraccia le ombre. Lascia che il Marchio di Kezan rafforzi i tuoi oscuri maneggi.",
}
T[8108] = {
  title = "Marchio di Kezan",
  progress = "Sono pronto per te, $C. Potenzierò il tuo talismano ancora una volta. Ti chiedo solo di continuare a distruggere Hakkar e i suoi servitori.$B$BDammi il talismano.",
  reward = "Solo unendo i nostri sforzi fermeremo il Soulflayer.",
}
T[8109] = {
  title = "Marchio Inarrestabile di Kezan",
  progress = "Evoca i tuoi demoni, $C. Lascia che si crogiolino nell'energia del Marchio di Kezan. Comandali sul campo di battaglia! Decima il nemico!$B$BSì... È giunto il momento dell'ultimo potenziamento del Marchio di Kezan. Dammi il talismano.",
  reward = "Strappa la carne dai loro cadaveri. Guarda le ombre consumare gli Hakkari. Trai potere dalla loro paura, $C. Lascia che il Marchio di Kezan accresca questo potere...",
}
T[8110] = {
  title = "Alga Incantata dei Mari del Sud",
  reward = "La vedi quest'alga qua, mon? Viene dai Mari del Sud. Noi ci mettiamo solo un po' di mojo e un po' di magia e lei prende le proprietà più adatte a chi ce l'ha.$B$BTu sei $Gun:una; $C, quindi è facile, mon. Te l'avvolgi intorno al collo e pensi alla natura, agli scoiattoli o a quello che piace a voialtri.",
}
T[8111] = {
  title = "Alga Incantata dei Mari del Sud",
  progress = "Ehi, mon! Che bello rivederti. La tribù parla di come ammazzi gli Hakkari e tutto il resto. Molthor mi ha detto di metterci altro mojo nel tuo talismano. Tu dammelo qua che Maywiki te lo fa meglio.",
  reward = "La collana mica è da fumare, mon! La devi usare per combattere il male.",
}
T[8112] = {
  title = "Alga Incantata dei Mari del Sud",
  progress = "Come sta quel talismano, mon? Mi sa che è ora di metterci ancora un po' di magia e di mojo nelle foglie. Gli serve una rifiorita, che è un po' appassito. Dammelo qua che Maywiki te lo sistema subito.",
  reward = "Adesso vai dai troll cattivi di Zul'Gurub e fagli vedere cosa sanno fare i tuoi poteri della natura, mon!",
}
T[8113] = {
  title = "Alga Incantata Immacolata dei Mari del Sud",
  progress = "$N! È da un pezzo che non ti vedo. Lo sapevi che Re Rastakhan in persona mi ha dato l'ordine di metterci l'ultimo po' di mojo e di magia nel tuo talismano? È vero, mon! Non ci credevo se non lo vedevo coi miei occhi. Dammelo qua.",
  reward = "$N, mon, è stato un bel viaggio. Tu continua ad ammazzare e a schiacciare Hakkar e i servitori suoi.",
}
T[8114] = {
  title = "Controlla Quattro Basi",
  desc = "$N, in Arathi Basin hai dato battaglia ai nostri nemici e su quel campo hai conquistato grandi onori. Ci hai mostrato quanto vali come $C, e hai mostrato ai nostri nemici che non ci piegheremo alla loro malvagità!$B$BPer noi il tuo valore è ormai provato, e per questo ho un compito difficile da affidarti. Voglio che tu conquisti e tenga almeno quattro delle basi di Arathi Basin. Se ci riuscirai, non solo ci assicureremo risorse fondamentali, ma mostreremo all'Orda la nostra supremazia!$B$BVa', $N, e buona fortuna.",
  obj = "Entra in Arathi Basin, conquista e controlla quattro basi contemporaneamente, poi torna da Field Marshal Oslight, a Refuge Pointe.",
  reward = "Davvero un buon lavoro, $N! Un esploratore tutto emozionato è venuto a riferirmi le tue imprese. Noi della League of Arathor siamo molto soddisfatti!$B$BFra i soldati della League stai diventando in fretta $Gun eroe locale:un'eroina locale;, e l'impresa di oggi conferma ancora una volta la tua ottima reputazione.",
}
T[8115] = {
  title = "Controlla Cinque Basi",
  desc = "$N, battersi per le risorse di Arathi Basin è un'impresa sanguinosa. I tuoi servigi alla League of Arathor sono tanto necessari quanto apprezzati.$B$BE abbiamo un altro compito per te.$B$BLa League vuole lanciare una grande offensiva contro i Defilers che occupano Arathi Basin. Vogliamo che vengano cacciati da ogni punto strategico del campo di battaglia!$B$BNon sarà facile, ma se c'è qualcuno che può farcela, sei tu.",
  obj = "Controlla 5 basi in Arathi Basin contemporaneamente, poi torna da Field Marshal Oslight, a Refuge Pointe.",
}
T[8116] = {
  title = "Visione di Voodress",
  reward = "Tu e Maywiki avete una cosa in comune, mon. Siamo sciamani tutti e due! Anche se Maywiki è più una mistica e tu sei più una schiappa. Però tutti e due sappiamo cosa portano i grandi spiriti.$B$BCome regalo ti do questa sfera da portare al collo. Guardaci bene dentro e vedrai il villaggio di Voodress, nei Mari del Sud! Lascia che ti sollevi lo spirito!",
}
T[8117] = {
  title = "Visione di Voodress",
  progress = "Buone notizie, $N. Molthor ultimamente non fa che cantare le tue lodi. Dice che stai diventando $Gun vero eroe:una vera eroina; di Zandalar.$B$BDice pure che Maywiki ti deve lucidare ancora un po' la sfera! Dammela qua, così Maywiki ti schiarisce la visione.",
  reward = "Occhio ai malvagi spiriti Hakkari, mon. Davvero, mettono i brividi.",
}
T[8118] = {
  title = "Visione di Voodress",
  progress = "Scia-mon! Maywiki ha fatto una battuta!$B$B<Maywiki ride.>$B$BAllora, hai usato gli spiriti e gli elementi contro i nostri nemici a Zul'Gurub, eh? Siano lodati gli spiriti!$B$BMaywiki adesso ti fa più luminosa la sfera. Dammela qua, $N.",
  reward = "Dacci un'occhiata adesso, $N. Voodress ora si vede ancora meglio, eh? Lascia che il potere primordiale ti scorra dentro, mon.",
}
T[8119] = {
  title = "La Visione Intatta di Voodress",
  progress = "<Maywiki indica il tuo talismano.>$B$BGuardalo, $N! Ha preso vita. Gli spiriti danzano intorno alla sfera.$B$BDallo a Maywiki, così gli dà un'ultima sistemata.",
  reward = "Un giorno, $N, potrai usare questa sfera per parlare direttamente con me. Quando questa battaglia con Hakkar sarà finita e Maywiki tornerà a casa. Invochiamo gli spiriti e chiediamogli che quel giorno arrivi presto.",
}
T[8120] = {
  title = "La Battaglia per Arathi Basin!",
  desc = "Come avrai senz'altro sentito, la League of Arathor sta mandando un gran numero di truppe in Arathi Basin. Avidi di cibo e provviste, questi stolti dell'Alleanza sono decisi a prendere e controllare le ricche risorse che si trovano lì. Dobbiamo dimostrargli che Arathi non sarà mai più una casa per gli umani!$B$BVa' in Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi dei nemici e rivendica quei territori per l'Orda.$B$BVa', $N. Torna a riferirmi quando avrai portato a termine questo compito.",
  obj = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire, a Hammerfall.",
  reward = "Un esploratore dei Defilers è venuto da me con un rapporto sul tuo successo, $N. Ben fatto.$B$BCome imparerai, per vincere la battaglia per Arathi Basin dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'Alleanza. Fa' questo, e la nostra vittoria qui è assicurata.",
}
T[8121] = {
  title = "Prendi Quattro Basi",
  desc = "$N, mentre infuriano le battaglie per Arathi Basin, la notizia delle tue azioni è giunta a molte orecchie. Fra noi sei $Gtenuto:tenuta; in grande considerazione, e per questo confido che porterai a termine la missione che ora ho per te.$B$BÈ ora di mandare un messaggio alla League of Arathor. Dobbiamo dimostrare loro che i possedimenti che hanno in Arathi Basin sono fragili e si perdono in fretta. Lo dimostreremo tenendo quattro punti strategici di Arathi Basin tutti nello stesso momento.$B$BSe ci riuscirai, $N, ti guadagnerai grande rispetto fra i Defilers.",
  obj = "Tieni quattro basi contemporaneamente in Arathi Basin, poi torna da Deathmaster Dwire, a Hammerfall.",
}
T[8122] = {
  title = "Prendi Cinque Basi",
  desc = "È difficile accorgersene, immersi come siamo nel conflitto, ma le nostre spie riferiscono che la determinazione della League of Arathor si sta indebolendo. Dobbiamo approfittare di questo spiraglio e sferrare loro un colpo brutale! Torna in Arathi Basin e scagliati contro i nostri nemici. Maledicili e uccidili e controlla tutte e cinque le basi strategiche! Fa' fuggire i loro soldati dal fronte, urlanti e sanguinanti, con i racconti della tua crudeltà sulle labbra piagnucolanti.$B$BFallo, e conquisterai una grande vittoria per i Defilers.",
  obj = "Tieni cinque basi in Arathi Basin contemporaneamente, poi torna da Deathmaster Dwire, a Hammerfall.",
}
T[8123] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "La League of Arathor non bada a spese nel tentativo di riprendersi Arathi. Loro e tutte le razze dell'Alleanza si stanno riversando in questa regione lontana, decisi ad allargare il loro dominio partendo da Refuge Pointe. Dobbiamo fermarli, e il modo migliore per farlo è prendere i loro rifornimenti.$B$BPuoi aiutarci, $N. Entra in Arathi Basin, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis, a Hammerfall.",
  progress = "Che c'è, $R? Hai i Contrassegni d'Onore? Torna in Arathi Basin, stermina i parassiti dell'Alleanza e impadronisciti delle sue risorse per la Signora Oscura!",
  reward = "<L'Inseguitore della Morte Mortis sorride>$B$BUn altro colpo decisivo è stato inferto ai nostri nemici, $N. Grazie alle tue imprese, Arathi Basin cadrà presto nelle mani dei Defilers.",
}
T[8141] = {
  title = "Talismano dell'Ombra Zandalari",
  reward = "Fai progressi in fretta, giovane $C. Forse è ora di iniziarti alla Shera Ali'kh — in Zandalari, la Mano della Morte. Per migliaia di anni abbiamo fatto da assassini per l'Impero di Zandalar. Troppo a lungo siamo rimasti a guardare, lasciando che gli Hakkari diventassero sempre più forti. Ancora una volta affrontiamo Hakkar, ma stavolta senza il sostegno di un fronte $R unito. Tocca a te e ai tuoi alleati contribuire a sconfiggere il Dio del Sangue e i suoi servitori!$B$BIndossa questo talismano, e che ti sia d'aiuto nei tuoi viaggi.",
}
T[8142] = {
  title = "Talismano dell'Ombra Zandalari",
  progress = "Notevole, $N. Hai un talento per uccidere che non sentivo in nessuno da molti anni. Perfino Molthor sa del lavoro che hai fatto per Zandalar. È ora di potenziare ancora il tuo talismano. Dammelo.",
  reward = "C'è un solo potenziamento che si può ancora applicare al talismano, $C. Quando sarà il momento, lo applicherò.",
}
T[8143] = {
  title = "Talismano dell'Ombra Zandalari",
  progress = "Sento che hai dato la morte a innumerevoli Hakkari, $N. Ti porti addosso il fetore del loro mojo.$B$BImmagino che il talismano dell'Ombra ti abbia aiutato a sfoltirli? Dammelo e lascia che ne accresca il potere.",
  reward = "Da $Gun assassino:un'assassina; del tuo calibro bisogna stare alla larga. I tuoi nemici devono imparare il rispetto! Ed è proprio quello che avrai quando il nemico vedrà il luccichio della Mano della Morte — ormai troppo tardi...",
}
T[8144] = {
  title = "Talismano della Maestria dell'Ombra Zandalari",
  progress = "Brama di crescere, $N. Il talismano ha assorbito tutto quello che hai fatto. Le migliaia di cadaveri di troll sparsi per Zul'Gurub ne hanno alimentato il potere. Consegnamelo e farò l'ultimo potenziamento.",
  reward = "Questa è l'ultima volta che parliamo sotto l'egida della Shera Ali'kh. Sai tutto quello che devi sapere. Prendi il talismano e continua a uccidere. A Hakkar non dev'essere mai permesso di lasciare Zul'Gurub.",
}
T[8145] = {
  title = "Il Tentacolo del Maelstrom",
  reward = "Fra gli Zandalari la professione del cacciatore è venerata. I nostri più grandi cacciatori si spingono fino al margine del Maelstrom per dare prova della loro determinazione.$B$BDal cuore del mare tirano su filamenti di alga chiamati Tentacoli del Maelstrom. L'alga viene poi intrecciata in un talismano, incantato per migliorare la loro precisione e la loro potenza.$B$BOra ti concedo un solo intreccio del Tentacolo del Maelstrom. Man mano che il tuo legame con Zandalar crescerà, intreccerò altro potere nel talismano.",
}
T[8146] = {
  title = "Il Tentacolo del Maelstrom",
  progress = "Ah, $N, che piacere sentire di nuovo il tuo odore.$B$B<Falthir fa un largo sorriso.>$B$BDevi scusare il mio senso dell'umorismo. A volte è davvero nauseabondo.$B$BSento che hai causato grandi sofferenze ai nostri nemici. Le forze di Hakkar gridano il tuo nome con rabbia. Eccellente, davvero.$B$BTi sei $Gguadagnato:guadagnata; un altro intreccio per il tuo talismano. Consegnamelo.",
  reward = "Che cerchino l'espiazione sotto i colpi delle tue munizioni.",
}
T[8147] = {
  title = "Il Tentacolo del Maelstrom",
  progress = "Ah, $N, che piacere sentire di nuovo il tuo odore.$B$B<Falthir fa un largo sorriso.>$B$BDevi scusare il mio senso dell'umorismo. A volte è davvero nauseabondo.$B$BSento che hai causato grandi sofferenze ai nostri nemici. Le forze di Hakkar gridano il tuo nome con rabbia. Eccellente, davvero.$B$BTi sei $Gguadagnato:guadagnata; un altro intreccio per il tuo talismano. Consegnamelo.",
  reward = "Che cerchino l'espiazione sotto i colpi delle tue munizioni.",
}
T[8148] = {
  title = "Ira del Maelstrom",
  progress = "Molthor porta notizie da Re Rastakhan, $N. La corte reale è molto colpita da come hai decimato le forze degli Hakkari. Ho l'incarico di concederti l'ultimo intreccio del tuo talismano. Consegnamelo.",
  reward = "Il tuo viaggio è appena cominciato, giovane $C. Forse un giorno visiterai il Maelstrom e getterai uno sguardo nel cuore del mondo.$B$BTi auguro potere e forza d'animo!",
}
T[8149] = {
  title = "In Onore di un Eroe",
  desc = "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici — in alcuni casi il sacrificio supremo — che hanno fatto per noi. L'Alleanza riconosce molti eroi, ma nessuno ha una storia più tragica di quella di Uther Lightbringer.$B$BAiutaci a onorare Uther portando questa offerta alla sua tomba, nelle Western Plaguelands. Mettila presso la sua statua, poi torna da me. Resterò qui solo fino alla fine della festa, quindi sbrigati a rendere omaggio a Uther.",
  obj = "Raggiungi il Sepolcro di Uther, nelle Western Plaguelands, usa l'Uther's Tribute presso la sua statua e poi torna da Wagner Hammerstrike, fuori da Ironforge, prima che l'Harvest Festival finisca.",
  progress = "Hai fatto il viaggio fino al Sepolcro di Uther e hai lasciato lì il tributo?$B$BPuò essere un viaggio pericoloso per gli avventurieri meno esperti; un modo relativamente più sicuro per arrivarci potrebbe essere partire dal fiume che attraversa Hillsbrad e andare verso nord, nelle Plaguelands. Il fiume nasce da un lago vicino alla Collina del Cordoglio; va' verso ovest su per le colline, tenendoti lontano dalla tomba vicina... che è infestata dal Flagello.",
  reward = "Era un eroe tra gli eroi, Uther. Non riesco nemmeno a immaginare l'angoscia che provò quando Arthas — il suo allievo migliore, che Uther amava come un figlio — tradì tutta l'umanità. Eppure si levò per cercare di fermare Arthas, e per questo sarà ricordato per sempre come un vero paladino. Combatté fino alla fine, pensando solo a coloro che poteva salvare.$B$BGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.",
  en_title = "Honoring a Hero",
  en_obj = "Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.",
}
T[8150] = {
  title = "In Onore di un Eroe",
  desc = "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici — in alcuni casi il sacrificio supremo — che hanno fatto per noi. L'Orda riconosce molti eroi, ma nessuno incarna la forza e il sacrificio più di Grom Hellscream.$B$BAiutaci a onorare Grom portando questa offerta al suo monumento, nel Canyon della Caduta Infernale di Ashenvale. Mettila alla base, poi torna da me. Resterò qui solo fino alla fine della festa, quindi sbrigati a rendere omaggio a Grom.",
  obj = "Raggiungi il Grom's Monument, nel Demon Fall Canyon di Ashenvale, e usa il Grom's Tribute alla base del monumento. Torna da Javnir Nashak, fuori da Orgrimmar, prima che l'Harvest Festival finisca.",
  progress = "Hai fatto il viaggio fino al Monumento a Grom e hai lasciato lì il suo tributo?$B$BIl luogo dove sorge il monumento è ancora segnato dalla corruzione della Legione Infuocata. Se hai poca esperienza nell'avventura, sta' in guardia quando ti avvicini al monumento.",
  reward = "Il nome completo di Grom — Grommash — significa \"Il Cuore del Gigante\"; ci volle questo e anche di più per affrontare da solo Mannoroth. Come ha detto il Capoguerra, meglio di chiunque altro, la maledizione degli orchi cominciò e finì con Grom. È giusto che il sacrificio di Grom — e forse la sua redenzione — sia la sorgente da cui l'Orda scaturisce oggi.$B$BGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.",
  en_title = "Honoring a Hero",
  en_obj = "Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument.  Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.",
}
T[8151] = {
  title = "L'Amuleto del Cacciatore",
  desc = "Ogtinc di Azshara ha lanciato un appello ai cacciatori esperti come te. È un cacciatore mezzorso che ha lasciato la sua tribù per aiutare il Cenarion Circle. I suoi insegnamenti servono ad arricchire la saggezza di quanti condividono la sua arte, e a guidarli a mantenere un equilibrio. Faresti bene a parlargli.$B$BOgtinc vive in cima alle scogliere di Azshara, a nord-est delle Rovine di Eldarath.",
  obj = "Parla con Ogtinc ad Azshara.",
  reward = "Il mio scopo non è più cacciare, ma istruire il cacciatore. È ciò che il destino mi ha riservato.$B$BCrea con me un amuleto del cacciatore — una raccolta di trofei di prede abbattute che ti ricorderà le prove e i trionfi del passato. Alla fine l'amuleto lo terrò io, ma ti ricompenserò con qualcos'altro.",
}
T[8153] = {
  title = "Palchi di Corsiero",
  desc = "Il corsiero porta i palchi più possenti delle terre conosciute. Questi palchi servono a difendere il corsiero, incornando l'aggressore e danneggiando spesso le punte. Palchi perfetti, naturali, sono il segno di uno spirito animale supremamente sicuro di sé.$B$BStringere fra le mani palchi simili infonderà in te la stessa sicurezza.$B$BCaccia il corsiero mosshoof, trova i palchi perfetti e portameli.",
  obj = "Porta un paio di Perfect Courser Antlers a Ogtinc, ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle Rovine di Eldarath.",
  progress = "Hai trovato i palchi?",
  reward = "Devi avere una vista acuta e una grande pazienza per esserteli procurati. Ben fatto.",
}
T[8154] = {
  title = "Contrassegno d'Onore di Arathi Basin!",
  desc = "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!$B$BEcco perché Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname — servono tutti, e tutti si possono ottenere lì.$B$BÈ questo che voglio da te, $N. Entra in Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear, a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? La League of Arathor non può combattere come si deve senza di essi...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle nostre truppe.$B$BGrazie, $N. È proprio portando a termine missioni come la tua che si vincono davvero le guerre.",
}
