T[8162] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "La League of Arathor non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'Alleanza, ora si riversano in questa regione lontana, decisi ad allargare il loro dominio a partire da Refuge Pointe. Dobbiamo fermarli, e il modo migliore per fermarli è prendere i loro rifornimenti.$B$BPuoi aiutarci, $N. Entra in Arathi Basin, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis, a Hammerfall.",
  progress = "Che c'è, $R? Hai i Contrassegni d'Onore? Torna in Arathi Basin, stermina i parassiti dell'Alleanza e impadronisciti delle sue risorse per la Signora Oscura!",
  reward = "<L'Inseguitore della Morte Mortis sorride>$B$BUn altro colpo decisivo è stato inferto ai nostri nemici, $N. Grazie alle tue imprese, Arathi Basin cadrà presto nelle mani dei Defilers.",
  en_title = "Cut Arathor Supply Lines",
  en_obj = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.",
}
T[8166] = {
  title = "La Battaglia per Arathi Basin!",
  desc = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.$B$BAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!$B$BQuando l'avrai fatto con tutti e quattro i punti, torna da me.",
  obj = "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight, a Refuge Pointe.",
  reward = "Ho ricevuto rapporti sulle tue imprese in Arathi Basin, $N. Ben fatto! Con gente come te che viene a combattere qui, confido che un giorno riprenderemo le nostre terre d'origine.",
}
T[8167] = {
  title = "La Battaglia per Arathi Basin!",
  desc = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.$B$BAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!$B$BQuando l'avrai fatto con tutti e quattro i punti, torna da me.",
  obj = "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight, a Refuge Pointe.",
  reward = "Ho ricevuto rapporti sulle tue imprese in Arathi Basin, $N. Ben fatto! Con gente come te che viene a combattere qui, confido che un giorno riprenderemo le nostre terre d'origine.",
  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.",
}
T[8168] = {
  title = "La Battaglia per Arathi Basin!",
  desc = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.$B$BAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!$B$BQuando l'avrai fatto con tutti e quattro i punti, torna da me.",
