T[8193] = {
  title = "Maestro Pescatore",
  progress = "Oggi, tra le 2 e le 4 del pomeriggio, c'è una gara per stabilire chi è il più grande pescatore di tutti! Basta essere la PRIMA PERSONA a portarmi 40 Pescigustosi pescati dai banchi di Pescigustosi lungo la costa di Stranglethorn, prima di chiunque altro, e sarai $Gproclamato Maestro Pescatore:proclamata Maestra Pescatrice;!$B$BSe non sei la prima persona a portarmi 40 pesci, la mia apprendista qui ti ricompenserà comunque con del denaro per ogni 5 Pescigustosi che le porterai.$B$BAh, e non perdere tempo, i Pescigustosi vanno a male in fretta!",
  reward = "Sbrigati a consegnarli, se vuoi essere $Gproclamato Maestro Pescatore:proclamata Maestra Pescatrice;! Sono qui da ORE senza niente da mangiare! Dammi quei cosi!",
  en_title = "Master Angler",
}
T[8195] = {
  title = "Monete Zulian, Razzashi e Hakkari",
  progress = "Cerco i Modelli di Potere noti come Monete delle Tribù. Sono la valuta usata dai vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BSe ne trovano nove tipi diversi. Alcune le cercano i miei compatrioti, per le varie armature che offrono agli eroi degli Zandalar. Se ne hai in più, ti darò uno dei nostri Emblemi dell'Onore in cambio di una serie di tre. Gli Emblemi puoi usarli con Rin'wosho il Mercante; in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà una bella aggiunta alla nostra collezione, che continua a crescere... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Ti sei $Gguadagnato:guadagnata; questo Emblema dell'Onore, $N, e anche la gratitudine della tribù!",
}
T[8196] = {
  title = "Manghi dell'Essenza",
  progress = "Il potentissimo mango dell'essenza cresce in molte isole dei Mari del Sud. Basta un solo mango per ristorare chi lo mangia, nel corpo e nella mente. Se non ne hai mai assaggiato uno, non sai cosa ti perdi!$B$BQui sull'isola ne abbiamo una scorta sufficiente per offrirtene una manciata in cambio di un Emblema dell'Onore degli Zandalar. Parla con Vinchaxa se ti serve sapere come ottenere gli emblemi; altrimenti, veniamo agli affari!",
  reward = "Uno scambio equo, $Gamico mio:amica mia; — goditi i succulenti frutti dei Mari del Sud, con la benedizione della tribù.",
}
T[8201] = {
  title = "Una Collezione di Teste",
  desc = "È vero. Hakkar ora dimora a Zul'Gurub e si bagna nel potere dei nostri dei. Sommi sacerdoti soggiogati ora incanalano le energie delle nostre divinità più sacre nel Soulflayer, che presto avrà una forza superiore a quella di qualsiasi essere di Azeroth. Va fermato!$B$BPrendi questa corda sacra e infilaci le teste dei sommi sacerdoti responsabili di incanalare l'energia dei nostri dei.$B$BQuando l'avrai fatto, torna da me.",
  obj = "Infila 5 Channeler's Heads, poi riporta la Collezione di Teste di Troll a Exzhal sull'Isola di Yojamba.",
  progress = "Hai la collezione di teste, $N? Dobbiamo impedire a Hakkar di acquisire altro potere!",
  reward = "Hai preso le teste! Hai fermato il saccheggio del potere dei nostri dei e indebolito Hakkar!$B$BLe tue azioni sono davvero eroiche, $N. Che le teste di questi schiavi troll ti implorino pietà ancora a lungo dopo che il loro sangue si sarà raffreddato.",
}
T[8223] = {
  title = "Altro Sangue di Scorpione Brillante",
  progress = "Quel sangue di scorpione sta funzionando alla grande, $N! È incredibile come un po' di luccichio e di splendore possa trasformare in un ninnolo ambito quello che altrimenti sarebbe solo un pezzo di ciarpame. I clienti amano quella roba, e alla fine è l'amore che conta, non credi...$B$BMi sei $Gstato:stata; di grande aiuto, $N, e anche se non ho un gran bisogno di altro sangue di scorpione brillante, se me ne porti ancora ti darò comunque dei biglietti in cambio.",
  reward = "Grazie ancora, $N. Ecco i tuoi biglietti!",
}
T[8227] = {
  title = "Nastro da Misura di Nat",
  desc = "Tra le esche e l'attrezzatura da pesca in frantumi c'è un nastro da misura di seta, arrotolato. Al nastro è attaccata un'etichetta che dice:$B$B\"Nat Pagle, Dustwallow Marsh.\"",
  obj = "Riporta Nat's Measuring Tape a Nat Pagle, a Dustwallow Marsh.",
  progress = "Ehilà, $Gragazzo:ragazza;. Qui per pescare un po'?",
  reward = "Ma guarda, hai trovato il mio nastro da misura preferito! Lo adoro, questo nastro! Ci ho misurato alcuni dei pesci più grossi che abbia mai preso...$B$BMa questo nastro l'ho perso a Zul'Gurub... sei $Gstato:stata; a Zul'Gurub? Hai visto il leggendario Gahz'ranka?$B$BBe'... vuoi prenderlo?",
}
T[8231] = {
  title = "Caccia ai Wavethrasher",
  desc = "Il wavethrasher è una bestia anfibia che vive solo qui ad Azshara. Sono potenti e resistenti.$B$BLe scaglie dure e riflettenti di un wavethrasher rispecchiano la forza del cacciatore.$B$BSegui le tracce dei wavethrasher lungo la costa di Azshara, cacciali e portami le loro scaglie.",
  obj = "Porta 6 Wavethrasher Scales a Ogtinc, ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle Rovine di Eldarath.",
  progress = "Ci sei $Griuscito:riuscita;?",
  reward = "I wavethrasher non si sconfiggono facilmente, tanto meno nel loro ambiente acquatico.$B$BHai dimostrato di essere $Gpronto:pronta; a cacciare prede ancora più letali.",
}
T[8232] = {
  title = "Il Draco Verde",
  desc = "Ora ti mando a una caccia pericolosa, per uccidere il draco verde, Morphaz, e portarmi il suo dente. Morphaz dimora nelle profondità del Temple of Atal'Hakkar, il cui ingresso si trova nella Swamp of Sorrows.$B$BSe vuoi sconfiggerlo, non devi andare $Gsolo:sola;. Questo draco è nemico di molti — cerca altri che vogliano distruggerlo.$B$BIl dente del draco rappresenta la forza che un cacciatore trova nella compagnia degli altri. Portamelo e avrai imparato molto.",
  obj = "Porta il Tooth of Morphaz a Ogtinc, ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle Rovine di Eldarath.",
  progress = "Vedo saggezza nei tuoi occhi, $N. La tua caccia è finita?",
  reward = "Hai imparato le antiche usanze, $N, e per questo ti offro un dono dei tempi in cui ero $C.",
}
T[8233] = {
  title = "Una Semplice Richiesta",
  desc = "Lord Jorach Ravenholdt richiede la tua presenza. La faccenda è segreta, e non posso dire altro.$B$BIl Maniero dei Ravenholdt si trova nelle Hillsbrad Foothills — cerca un sentiero fra le montagne a nord-ovest del Forte Durnholde.",
  obj = "Parla con Lord Jorach Ravenholdt, al Maniero dei Ravenholdt.",
  reward = "$GBenvenuto, benvenuto, benvenuto:Benvenuta, benvenuta, benvenuta;! Prego, $N, accomodati e parliamo di una questione semplice.$B$BVedi, $N, di recente ho perso una cosa a cui tengo molto e, per dirla senza giri di parole, la rivoglio a ogni costo. Ci guadagni qualcosa anche tu, non preoccuparti! Oh sì, qualcosa di molto bello.$B$BAllora, che ne dici, $N... ti va un po' d'avventura?",
}
T[8234] = {
  title = "Sacca Azzurra Chiusa",
  desc = "Andiamo con ordine. Quello che ho perso è una piccola sacca blu, e il suo contenuto è una faccenda privata.$B$BNon perdere tempo a inseguire i ladri, perché sono già morti. Quello che sappiamo è che quegli sciocchi non sono riusciti ad aprire la sacca, così l'hanno venduta come reliquia sacra a un qualche sciamano timbermaw di Azshara. Ingegnoso.$B$BDevi andare ad Azshara e riprenderla allo sciamano con l'astuzia... o con la forza. Scommetto che ti andrà meglio con il primo metodo. Quando l'avrai, portala all'Arcimago Xylem.",
  obj = "Recupera la Sealed Azure Bag dal Timbermaw Shaman, ad Azshara. Poi porta la sacca ad Archmage Xylem, che si trova anche lui ad Azshara.",
  progress = "Ci conosciamo?",
  reward = "Vedo che hai la sacca di Lord Ravenholdt. Perché non l'hai detto subito, $Gragazzo:ragazza;?",
}
T[8235] = {
  title = "Frammenti Codificati",
  desc = "Lord Ravenholdt ha chiesto un favore a tutti e due. Vuole togliere l'incantesimo da questa sacca.$B$BPurtroppo alcuni dei miei libri sulla dissoluzione degli incantesimi mi sono stati portati via di recente, per poi finire distrutti da alcuni selvaggi. Quello che resta dei miei libri ha ancora valore per me.$B$BSe mi porti abbastanza frammenti codificati, posso rimetterli insieme. La cosa migliore è uccidere le melme delle foreste, visto che tendono a raccogliere più o meno qualsiasi cosa. Le troverai nel nord-est di Azshara.",
  obj = "Porta 10 Encoded Fragments ad Archmage Xylem, ad Azshara.",
  progress = "Hai trovato abbastanza frammenti perché io possa continuare il mio lavoro?",
  reward = "A quanto pare hai raccolto alcuni dei frammenti migliori. Forse dopotutto non sei inutile.",
}
T[8236] = {
  title = "La Chiave Azzurra",
  desc = "Ci vorrà un po' per decifrare i frammenti e togliere l'incantesimo. Quando avrò finito, consegnerò la sacca a Lord Ravenholdt di persona.$B$BResta la questione della chiave, che si dice sia in mano a un draco verde noto come Morphaz. Il draco ha fatto la tana nelle profondità del Temple of Atal'Hakkar, il cui ingresso si trova nella Swamp of Sorrows.$B$BRaduna i tuoi amici e spingiti fino al suo covo. Lord Ravenholdt aspetterà il tuo ritorno con la chiave.",
  obj = "Riporta l'Azure Key a Lord Jorach Ravenholdt.",
  progress = "La sacca è già arrivata dall'Arcimago Xylem, hai trovato la chiave?",
  reward = "La chiave! La credevo perduta per sempre. Prego, prendi un indumento incantato dalle mie scorte — li riservo ai ladri di abilità e lealtà eccezionali. Tutti devono sapere che con $N non si scherza!$B$B<Jorach apre la sacca e un bagliore dorato che viene da dentro lo avvolge. Sgrana gli occhi e resta a fissare...>",
}
T[8238] = {
  title = "Monete Gurubashi, Vilebranch e Witherbark",
  progress = "Cerco i Modelli di Potere noti come Monete delle Tribù. Sono la valuta usata dai vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BSe ne trovano nove tipi diversi. Alcune le cercano i miei compatrioti, per le varie armature che offrono agli eroi degli Zandalar. Se ne hai in più, ti darò uno dei nostri Emblemi dell'Onore in cambio di una serie di tre. Gli Emblemi puoi usarli con Rin'wosho il Mercante; in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà una bella aggiunta alla nostra collezione, che continua a crescere... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Ti sei $Gguadagnato:guadagnata; questo Emblema dell'Onore, $N, e anche la gratitudine della tribù!",
}
T[8239] = {
  title = "Monete Sandfury, Skullsplitter e Bloodscalp",
  progress = "Cerco i Modelli di Potere noti come Monete delle Tribù. Sono la valuta usata dai vari abitanti di Zul'Gurub, e ognuna è intrisa di un mojo sottile ma potente.$B$BSe ne trovano nove tipi diversi. Alcune le cercano i miei compatrioti, per le varie armature che offrono agli eroi degli Zandalar. Se ne hai in più, ti darò uno dei nostri Emblemi dell'Onore in cambio di una serie di tre. Gli Emblemi puoi usarli con Rin'wosho il Mercante; in cambio offre ai nostri eroi oggetti speciali.",
  reward = "Eccellente — questa serie di monete sarà una bella aggiunta alla nostra collezione, che continua a crescere... e che useremo per difendere la tribù dall'ascesa del Dio del Sangue. Ti sei $Gguadagnato:guadagnata; questo Emblema dell'Onore, $N, e anche la gratitudine della tribù!",
}
T[8240] = {
  title = "Un Bijou per Zanza",
  desc = "La distruzione dei vari Bijou Hakkari è per noi della massima importanza, tanto che invitiamo gli estranei alla tribù a distruggerli di persona!$B$BPorta uno qualsiasi dei bijou che trovi a Zul'Gurub all'Altare di Zanza e distruggilo. Solo per questa volta ti darò un Emblema dell'Onore della nostra tribù in più; si aggiunge a quello che riceveresti di norma.$B$BGuarda con i tuoi occhi le benedizioni di Zanza!",
  obj = "Distruggi all'Altar of Zanza, sull'Isola di Yojamba, uno qualsiasi dei Bijou Hakkari che si trovano a Zul'Gurub. Fatto questo, parla con Vinchaxa lì vicino.",
  progress = "Hai distrutto il bijou all'Altare di Zanza? Fallo, e allora Zanza ti benedirà due volte!",
  reward = "Eccellente... ogni bijou che strappiamo ai servitori del Dio del Sangue ci avvicina tutti di un passo a sconfiggerli una volta per tutte. Porti onore agli Zandalar — e a te $Gstesso:stessa; — con le tue nobili azioni.$B$BRicorda, $N, puoi sempre distruggere all'altare i bijou che trovi a Zul'Gurub. Per ognuno otterrai riconoscimento e un Emblema dell'Onore! Ricordati solo di avere uno spazio libero nell'inventario, se non hai già uno degli emblemi.",
}
T[8241] = {
  title = "Ripristinare le scorte di Flussante Infuocato con il Ferro",
  progress = "Non sprechiamo in chiacchiere altro del mio tempo prezioso, $R. È ora di pensare a rimpinguare le nostre scorte di flussante infuocato, che si stanno assottigliando.$B$BEcco cosa mi serve da te:$B$B*Scaglie di Incendosaur.$B$B*Barre di ferro.$B$B*Carbone.$B$BPrendo tutto quello che riesci a darmi!$B$BE vedi di fare in fretta, se vuoi entrare nelle grazie della Brotherhood.",
  reward = "C'è sempre posto per altro flussante infuocato, $Gnovellino:novellina;. Continua a portarne... a meno che non ti dica io di smettere.",
}
T[8242] = {
  title = "Ripristinare le scorte di Flussante Infuocato con il Cuoio Pesante",
  progress = "Non sprechiamo in chiacchiere altro del mio tempo prezioso, $R. È ora di pensare a rimpinguare le nostre scorte di flussante infuocato, che si stanno assottigliando.$B$BEcco cosa mi serve da te:$B$B*Scaglie di Incendosaur.$B$B*Cuoio Pesante.$B$B*Carbone.$B$BPrendo tutto quello che riesci a darmi!$B$BE vedi di fare in fretta, se vuoi entrare nelle grazie della Brotherhood.",
  reward = "C'è sempre posto per altro flussante infuocato, $Gnovellino:novellina;. Continua a portarne... a meno che non ti dica io di smettere.",
}
T[8243] = {
  title = "Le Potenti Bevande di Zanza",
  progress = "Ora che la tua posizione nella tribù è cresciuta, hai accesso ad alcune delle nostre bevande più potenti. Guarda... questi infusi sono carichi di mojo — benedetti da Zanza e adatti ad avventurieri di ogni estrazione!$B$BTi lascerò sceglierne uno fra i tre che offro; in cambio chiedo un Emblema dell'Onore degli Zandalar. Bada che nel tuo spirito possono scorrere gli effetti di uno solo alla volta.$B$BFammi sapere quando sei $Gpronto:pronta; a barattare!",
  reward = "Uno scambio equo, $Gamico mio:amica mia; — goditi le benedizioni di Zanza, con i nostri omaggi!",
}
T[8246] = {
  title = "Sigilli degli Zandalar",
  progress = "$N — per chi è exalted fra gli Zandalar come te, ho qualcosa di molto speciale. Direttamente dalla nostra patria nei Mari del Sud... i Sigilli degli Zandalar! Questi sigilli servono a potenziare qualsiasi oggetto per le spalle in tuo possesso. Che tu cerchi potenza, mojo o serenità — ho quello che ti serve!$B$BChiedo quindici Emblemi dell'Onore degli Zandalar in cambio di un sigillo a tua scelta. Se hai gli emblemi pronti, io sono pronto a fare affari!",
  reward = "Uno scambio equo, $Gamico mio:amica mia; — accetta il tuo sigillo, con la benedizione della tribù!",
}
T[8249] = {
  title = "Servono Cofanetti",
  progress = "I miei ladri devono affinare la loro abilità nello scasso, e a me servono serrature di difficoltà adeguata — la roba che ci fabbrica Zan va bene giusto per gli ultimi dei novellini.$B$BSai che ti dico, se mi porti 5 Cofanetti Pesanti, ti do alcuni dei migliori coltelli da lancio che un ladro abbia mai visto.$B$BPuoi aprire i cofanetti e frugarci dentro, ma devi lasciarci almeno qualche moneta... anche un ladro in addestramento ha bisogno di motivazione.",
  reward = "Che questi coltelli trovino posto nel cuore di qualcuno.$B$BAlla lettera.",
}
T[8250] = {
  title = "Arte Magica",
  desc = "Negli ultimi tempi l'Arcimago Xylem va chiedendo in giro... di qualcuno con la tua esperienza.$B$BSe vuoi cercarlo, lo trovi ad Azshara. La sua torre sorge in cima alle scogliere, e l'unico modo per salire è un incantesimo di teletrasporto evocato dal suo arrogante servitore, Sanath Lim-yo.$B$BSanath è accampato sotto la torre del suo padrone. Per trovarlo, raggiungi il punto in cui la strada principale di Azshara si biforca, all'ingresso delle Rovine di Eldarath. Da lì, punta dritto a nord finché non arrivi alle scogliere.",
  obj = "Cerca Sanath Lim-yo e ottieni il passaggio per incontrare Archmage Xylem.",
  reward = "<Sanath ti rivolge un ghigno sprezzante.>$B$BL'Arcimago Xylem attende il tuo arrivo.",
}
T[8251] = {
  title = "Polvere Magica",
  desc = "Gli elfi del sangue di Azshara hanno messo a punto un metodo per polverizzare gli oggetti magici di cui entrano in possesso. Questa polvere risplendente che producono è diversa dai componenti che si ottengono di norma con un incantesimo di disincantamento.$B$BQuando ho mandato il mio apprendista a proporre uno scambio per la polvere, l'hanno ucciso senza esitare. Per questo devono pagare.$B$BIl tempo delle parole è finito, $N. Trova gli elfi del sangue lungo le scogliere di Azshara e usa metodi più \"persuasivi\" per ottenere la loro polvere risplendente.",
  obj = "Porta 10 Glittering Dust ad Archmage Xylem.",
  progress = "Hai la polvere?",
  reward = "Ben fatto, $N! Non smette mai di stupirmi quanto possa essere persuasiva una raffica di missili arcani.",
}
T[8252] = {
  title = "Il Corallo della Sirena",
  desc = "Guardati intorno. Le rovine e le spiagge sono invase dagli spitelash. Di recente quelle miserabili creature hanno imparato a riconoscere i componenti rari originari di Azshara.$B$BPer la precisione, parlo del corallo incantato — ne sono attratti per ragioni che ignoro. Ora nella baia è rimasto poco corallo, ed è essenziale per le mie ricerche. Ho bisogno che tu separi un po' di corallo incantato dalle sirene spitelash e me lo porti.",
  obj = "Raccogli 6 Enchanted Coral e portali ad Archmage Xylem.",
  progress = "Le sirene spitelash sono maghe sorprendentemente abili. Non quanto te, spero?",
  reward = "Questo è uno splendido esemplare di corallo, $N. Le tue capacità sono senza dubbio precise e letali.$B$BNon pensare che i tuoi sforzi siano passati inosservati. Forse sei $Gdegno:degna; di una vera prova della tua abilità...",
}
T[8253] = {
  title = "Distruggi Morphaz",
  desc = "Nelle profondità del tempio sommerso di Atal'Hakkar c'è un draco verde di nome Morphaz.$B$BAnni fa mi ha sopraffatto con un'imboscata audace e ha divorato il mio apprendista tutto intero. Perdere un apprendista non è una novità per me, ma quello in particolare aveva con sé una scheggia arcana di dimensioni e qualità ineguagliate.$B$BDevi radunare alleati potenti e addentrarti nel tempio. Distruggi Morphaz e recupera la scheggia arcana dal suo stomaco senza età.",
  obj = "Recupera l'Arcane Shard da Morphaz e torna da Archmage Xylem.",
  progress = "Hai ucciso la mia vecchia nemesi?",
  reward = "Incredibile. La scheggia è cresciuta, assorbendo l'energia del draco nel corso dei lunghi anni.$B$BOra non ho altro da chiederti. Con questa scheggia ho ritrovato appieno la capacità di forgiare l'arcano. La mia prima creazione è tua, $N, e non hai che da scegliere...",
}
T[8254] = {
  title = "Aiuto Cenarion",
  desc = "È proprio del divino aiutare chi è nel bisogno. Il come non ha importanza — conta solo il perché.$B$BIl Cenarion Circle si trova proprio nel bisogno. Parla con Ogtinc per dare una mano nella loro difficile situazione. Vive in cima alle scogliere a nord-est delle Rovine di Eldarath, ad Azshara.",
  obj = "Cerca Ogtinc ad Azshara.",
  reward = "Il tuo arrivo mi ha tolto un peso dalle spalle. Abbiamo molto da fare.",
}
T[8255] = {
  title = "Quel che Sappiamo dei Corsieri",
  desc = "I corsieri mosshoof di Azshara sono animali magnifici che un tempo vivevano a Felwood. Resistono per natura a malattie e veleni, e la corruzione di quel luogo non li ha toccati. Nella loro saggezza ancestrale, hanno semplicemente scelto di lasciare quel posto malato.$B$BMi si stringe il cuore, ma devo chiederti di cacciare per me queste possenti bestie. Raccogli quattro ghiandole di corsiero come primo ingrediente di un unguento risanatore — un unguento che useremo per guarire Felwood.",
  obj = "Procurati 4 Healthy Courser Glands e portale a Ogtinc, ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle Rovine di Eldarath.",
  progress = "Sei $Gtornato:tornata;. Ce l'hai fatta?",
  reward = "È un bene che la via del divino ti abbia condotto da noi, $N. Le tue convinzioni non sono d'ostacolo ai compiti che la creazione di questo unguento richiede.$B$BVedi, il corsiero è sacro per il Cenarion Circle, e ucciderlo per qualunque ragione, per quanto necessaria, indebolisce il loro spirito.",
}
T[8256] = {
  title = "L'Ichor della Non Morte",
  desc = "Per questo unguento risanatore devi seguire una formula semplice: una parte di veleno, due parti di rimedio. Un rimedio l'hai ottenuto, ora devi raccogliere il veleno.$B$BI non morti potenti, come gli alti nobili che ancora si aggirano fra le Rovine di Eldarath, sono a volte così intrisi di malvagità che questa si condensa in una melma verdastra e malsana. Fra i vivi, questa sostanza è nota come ichor della non morte.$B$BData la potenza di questo ignobile elemento, mi serve un solo ichor.",
  obj = "Procurati un Ichor of Undeath per Ogtinc, ad Azshara. Ogtinc vive in cima alle scogliere a nord-est delle Rovine di Eldarath.",
  progress = "Dobbiamo ottenere l'ichor in fretta. L'hai trovato?",
  reward = "Non posso dire di essere contento di ricevere una sostanza tanto ripugnante, ma è un male necessario. Grazie, $N.",
}
T[8257] = {
  title = "Sangue di Morphaz",
  desc = "Ora l'ultima parte, il secondo rimedio.$B$BSi sa che il draco verde Morphaz è immune a ogni forma di veleno e di malattia — molti druidi sono morti per portarci questa informazione. Non c'è dubbio che il suo sangue abbia la potenza che ci serve.$B$BUn corriere del Cenarion Circle prenderà le parti che hai già raccolto mentre tu ti procuri l'ultima. Chiama a raccolta i tuoi alleati e cerca la tana del draco nel tempio sommerso di Atal'Hakkar. Porta il suo sangue a Greta Mosshoof, a Felwood.",
  obj = "Uccidi Morphaz nel tempio sommerso di Atal'Hakkar e porta il suo sangue a Greta Mosshoof, a Felwood. L'ingresso del tempio sommerso si trova nella Swamp of Sorrows.",
  progress = "Hai il sangue di Morphaz?",
  reward = "Hai ucciso Morphaz e ci hai portato il suo sangue... Stento a credere a una notizia così bella!$B$BUniremo subito gli ingredienti e cominceremo a guarire gli alberi e le creature di Felwood. Ci vorrà una vita intera per rimediare a ciò che è successo qui, ma tu ci hai dato i mezzi per farlo.",
}
T[8258] = {
  title = "La Minaccia di Darkreaver",
  desc = "Il Cavaliere della Morte Darkreaver spadroneggia sul Grande Ossario di Scholomance. Minaccia di piegare il regno degli spiriti al suo volere, e va fermato! È qui che entra in gioco il veggente che hai contribuito a costruire.$B$BUsa il veggente della divinazione nel cuore del seminterrato del Grande Ossario per evocare gli spiriti al servizio di Darkreaver. Sconfiggi gli spiriti e apparirà il cavaliere della morte in persona. $N, portami la sua testa! Solo la sua fine potrà riparare il danno fatto al regno degli spiriti!",
  obj = "Usa il Divination Scryer nel cuore del seminterrato di Great Ossuary, a Scholomance. Così farai apparire gli spiriti che devi combattere. Sconfitti questi spiriti, verrà evocato Death Knight Darkreaver; sconfiggilo.$B$BPorta Darkreaver's Head a Sagorne Creststrider a Valley of Wisdom, a Orgrimmar.",
  progress = "Il tempo stringe, $N — sei $Griuscito:riuscita; a fermare la minaccia del Cavaliere della Morte Darkreaver?",
  reward = "È una vittoria da assaporare, $N! La fine di Darkreaver dovrebbe rinsaldare i fragili legami che tengono ancorato il regno degli spiriti.$B$BSei $Gandato:andata; ben oltre quello che ti era stato chiesto, anche quando non ti aspettavi né ricompense né compensi. Sei davvero $Guno Sciamano:una Sciamana; di valore, $Gamico mio:amica mia;.$B$BSo che agire per preservare il regno degli spiriti dovrebbe essere già un ringraziamento sufficiente, ma ti prego — accetta questo semplice dono con la mia gratitudine.",
}
T[8259] = {
  title = "Una Ricompensa Più Adeguata",
  reward = "Ah, $N... il tuo impegno contro Darkreaver è stato straordinario — un impegno, lasciamelo dire, che meritava una ricompensa ben migliore di quella che hai ricevuto. Ti prego, accetta quest'elmo come dono in più per quanto hai compiuto a Scholomance.$B$BAncora grazie.",
}
T[8260] = {
  title = "Pacco di Rifornimenti Base di Arathor",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! All'interno troverai razioni e bende che si possono usare solo in Arathi Basin.$B$BContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
  en_title = "Arathor Basic Care Package",
}
T[8261] = {
  title = "Pacco di Rifornimenti Standard di Arathor",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! All'interno troverai razioni e bende che si possono usare solo in Arathi Basin.$B$BContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
}
