T[8265] = {
  title = "Pacco di Rifornimenti Avanzato del Defiler",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! All'interno troverai razioni e bende che si possono usare solo in Arathi Basin.$B$BContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Honored con noi, le bende quando sei Revered.",
}
T[8266] = {
  title = "Coccarde del Sacrificio",
  progress = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.$B$BSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Coccarda del Sacrificio. Portamela, così le Sentinelle potranno ricompensarti per aver agito in nostro nome... anche se questa volta non sei $Griuscito:riuscita; a vincere.",
  reward = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Captain Shatterskull so that the Outriders may reward you for acting on our behalf.",
}
T[8268] = {
  title = "Coccarde del Sacrificio",
  progress = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.$B$BSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Coccarda del Sacrificio. Portamela, così gli Outriders potranno ricompensarti per aver agito in nostro nome... anche se questa volta non sei $Griuscito:riuscita; a vincere.",
  reward = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
}
T[8271] = {
  title = "Eroe degli Stormpike",
  reward = "In quanto $Geroe:eroina; degli Stormpike, puoi scegliere un oggetto fra questi tesori appena sacch... ehm, recuperati.",
}
T[8272] = {
  title = "Eroe dei Frostwolf",
  reward = "Che effetto fa, $N? Che effetto fa schiacciare i nemici e vedere le loro file andare in pezzi? È una bella sensazione, vero?$B$BMeriti una ricompensa per quest'impresa eroica, $Gsoldato:soldatessa;.",
}
T[8273] = {
  title = "La Gratitudine di Oran",
  reward = "Ma guarda un po', non è interessante? Dici di aver trovato questa tavoletta su una piccola isola deserta alla Scogliera Altosguardo, negli Hinterlands, $C? Davvero molto interessante. <Oran mette via con cura la tavoletta e si sfrega le mani.>$B$BTi ringrazio per il tuo impegno in questa faccenda. La nostra Signora Oscura sarà molto soddisfatta di questa scoperta. Ecco, permettimi di ricompensarti in misura adeguata.",
}
T[8275] = {
  title = "Riconquistare Silithus",
  desc = "Attenzione, eroi dell'Alleanza! La minaccia dei silithid è rimasta troppo a lungo senza freni. Senza una vera opposizione a ostacolarli, per tutto questo tempo si sono preparati a un'espansione su vasta scala.$B$BLe forze del Cenarion Circle si stanno radunando a Silithus per portare la battaglia in casa di queste miserabili creature, e con questo appello tutti gli avventurieri in grado di combattere sono chiamati a unirsi a noi!$B$BNon aspettate che sia troppo tardi! Aiutateci a difendere Azeroth! Presentatevi da Windcaller Proudhorn a Cenarion Hold per istruzioni precise!",
  obj = "Parla con Windcaller Proudhorn a Cenarion Hold, a Silithus.",
  reward = "Ottimo, una nuova recluta che risponde alla chiamata alle armi contro i silithid. $GBenvenuto:Benvenuta; a Cenarion Hold, $C. Sono lieta di vedere che le parole dei nostri emissari arrivano a eroi del tuo calibro. Qui non ti mancheranno le occasioni per aiutarci nei nostri sforzi, e mi aspetto che ti dimostri presto $Gun prezioso alleato:una preziosa alleata; della nostra causa.",
}
T[8276] = {
  title = "Riconquistare Silithus",
  desc = "Attenzione, campioni dell'Orda! C'è una minaccia che abbiamo lasciato indisturbata troppo a lungo. Le scosse nel terreno vicino agli alveari dei silithid in tutta Azeroth ci hanno avvertiti di grandi movimenti nelle loro schiere, che si preparano a espandersi.$B$BLe forze del Cenarion Circle si stanno radunando a Silithus per portare la battaglia ai silithid prima che sia troppo tardi! Non profaneranno più le nostre terre!$B$BTutti i combattenti abili devono presentarsi dall'Invocatrice del Vento Proudhorn a Cenarion Hold! I silithid saranno sconfitti!",
  obj = "Parla con Windcaller Proudhorn a Cenarion Hold, a Silithus.",
  reward = "Ottimo, una nuova recluta che risponde alla chiamata alle armi contro i silithid. $GBenvenuto:Benvenuta; a Cenarion Hold, $C. Sono lieta di vedere che le parole dei nostri emissari arrivano a eroi del tuo calibro. Qui non ti mancheranno le occasioni per aiutarci nei nostri sforzi, e mi aspetto che ti dimostri presto $Gun prezioso alleato:una preziosa alleata; della nostra causa.",
}
T[8277] = {
  title = "Veleno Mortale del Deserto",
  desc = "Beetix Ficklespragg, al tuo servizio! Mio cugino Noggle si guadagna da vivere raccogliendo erbe rare per gli alchimisti di Cenarion Hold. O almeno, se lo guadagnava. Dall'ultimo viaggio è tornato con un veleno potente che gli scorre nelle vene.$B$BSono riuscita a rallentare il veleno, ma per neutralizzarlo del tutto mi servono campioni del veleno della bestia che l'ha punto, qualunque sia.$B$BNoggle è arrivato da nord, quindi ci scommetto la camicia che sono stati gli scorpid stonelash o i saltatori delle sabbie. Portami un po' di pungiglioni e di zanne e proverò a preparargli un antidoto.",
  obj = "Beetix Ficklespragg, a Cenarion Hold a Silithus, vuole che tu raccolga 8 Stonelash Scorpid Stingers e 8 Sand Skitterer Fangs. Torna da lei quando hai finito.",
  progress = "Hai finito di raccogliere quei campioni? Potremmo perdere Noggle da un momento all'altro!",
  reward = "Incrocia le dita, $Gamico:amica;! Speriamo proprio di riuscire a salvare Noggle!",
}
T[8278] = {
  title = "L'Ultima Speranza di Noggle",
  desc = "Maledizione! L'antidoto non ha funzionato. Noggle dev'essere stato punto da una delle creature più forti dell'estremo sud.$B$BMi serve che tu vada laggiù a prendermi altri campioni, $N. La buona notizia è che il loro veleno è più forte, quindi me ne serviranno meno. La cattiva notizia è che nella zona meridionale strisciano più tipi di creature velenose, quindi dovrai attingere da più fonti.",
  obj = "Beetix Ficklespragg, a Cenarion Hold a Silithus, vuole che tu raccolga 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers e 3 Rock Stalker Fangs.",
  progress = "È la nostra ultima occasione di salvare Noggle! Sbrigati!",
  reward = "Sì! Sembra che funzioni, Noggle si sta riprendendo. Ti dobbiamo un favore grosso così!",
}
T[8279] = {
  title = "Il Dizionario del Crepuscolo",
  desc = "Il Martello del Crepuscolo non è tenero con chi lascia i suoi ranghi. Ancora oggi mi danno la caccia come se fossi una bestia! Inutile dire che un loro nemico è un mio amico!$B$BPer decifrare questa Tavoletta mi serve il libro che i loro scribi usano per mettere in codice i messaggi segreti: il Dizionario del Crepuscolo. È uno strumento così importante che ne tengono i tre capitoli in posti diversi! Gli ufficiali a cui è affidato il Dizionario sono chiamati Custodi del Crepuscolo, cercali negli accampamenti del Martello del Crepuscolo.",
  obj = "Porta i tre capitoli del Twilight Lexicon a Hermit Ortell, a Silithus.",
  progress = "Chi va là? Ah, sei tu! Hai già trovato tutti i capitoli del Dizionario?",
  reward = "Sì! Sono proprio le parti del libro! Mettiamoci al lavoro, allora, $N.$B$BScambiare una parola ogni tre con le parole del secondo capitolo... poi scambiare una parola sì e una no con le parole del primo capitolo... Aspetta, o era il contrario?",
}
T[8280] = {
  title = "Mettere al Sicuro le Linee di Rifornimento",
  desc = "Cenarion Hold è un luogo della massima importanza strategica. Sono convinta che, finché resta in mano nostra, la vittoria sui silithid sia garantita. Sempre che si riesca a mantenere l'afflusso dei rifornimenti, s'intende.$B$BI vermi del deserto si sono rivelati una minaccia per le nostre carovane di rifornimenti perfino più grande dei silithid stessi. Proprio stamattina un gruppo di assalitori del profondo ha devastato un grosso carico di morrowgrain. Ho bisogno che tu ne riduca il numero, perché i nostri rifornimenti non siano messi a rischio.",
  obj = "Windcaller Proudhorn, a Cenarion Hold a Silithus, vuole che tu uccida 15 Dredge Strikers.",
  progress = "Gli assalitori del profondo sono una minaccia seria e vanno eliminati in fretta!",
  reward = "Ti sono sinceramente grata. Con il tuo impegno per aiutare Cenarion Hold hai dimostrato vero coraggio.",
}
T[8281] = {
  title = "Rafforzare la Sicurezza",
  desc = "Finora il tuo operato è stato davvero esemplare, $N. Le nostre linee di rifornimento, però, non sono ancora del tutto sicure. Ora che mancano gli assalitori del profondo, i loro cugini più grossi del sud verranno di certo a prenderne il posto a nord.$B$BDovrai uccidere un bel po' di frantumatori del profondo per tenerli a bada, ma non possiamo lasciare al caso la sicurezza delle nostre linee di rifornimento.",
  obj = "Windcaller Proudhorn, a Cenarion Hold a Silithus, vuole che tu uccida 20 Dredge Crushers.",
  progress = "I frantumatori del profondo sono una minaccia seria e vanno eliminati subito!",
  reward = "Eccellente! Ti sei $Grivelato:rivelata; $Gun alleato prezioso:un'alleata preziosa; nei preparativi per la guerra contro i silithid.",
}
T[8282] = {
  title = "La Sacca Perduta di Noggle",
  desc = "Dove sono? Dov'è la mia borsa? *sussulta* Devo averla persa mentre scappavo da Deathclasp, lo scorpid gigante. Nella fretta di fuggire sono finito dritto in un nido di scorticatori stonelash.$B$BNella sacca che portavo c'era ogni sorta di reagenti rari. Senza quelli, io e Beetix non potremo preparare le pozioni che servono a Cenarion Hold. Sono ancora troppo debole per alzarmi, ma se mi riporti i reagenti saprò ricompensarti come si deve.$B$BMi sono imbattuto in Deathclasp nella catena montuosa meridionale, dietro l'accampamento di Bronzebeard.",
  obj = "Recupera Noggle's Satchel sulle montagne nel sud di Silithus e riportagliela a Cenarion Hold.",
  progress = "Non hai ancora trovato la mia borsa? Be', devo ringraziare la mia buona stella, almeno il veleno è stato eliminato.",
  reward = "Sì! Mi hai riportato la sacca. E i miei reagenti rari ci sono tutti! Sarò in debito con te per un bel pezzo.",
}
T[8283] = {
  title = "Ricercata — Deathclasp, Terrore delle Sabbie",
  desc = "Si ritiene che Deathclasp, il terribile scorpid, si sia ritirata sulla catena montuosa meridionale di fronte all'aumento dell'attività dei silithid. È una grave minaccia per le pattuglie e le spedizioni nelle regioni meridionali. Chi parteciperà alla sua eliminazione sarà lautamente ricompensato. Per la ricompensa rivolgersi al Capitano Vish Kozus, in cima alla Torre di Guardia di Cenarion Hold.",
  obj = "Porta Deathclasp's Pincer a Vish Kozus, Captain of the Guard.",
  progress = "Mi serve la chela della creatura come prova dell'impresa. Niente chela, niente ricompensa.",
  reward = "Eccellente! Ora che Deathclasp non c'è più siamo liberi di usare la catena montuosa meridionale come passaggio strategico per aggirare gli alveari dei silithid. Il tuo lavoro è molto apprezzato.",
}
T[8284] = {
  title = "Il Mistero del Crepuscolo",
  desc = "A nord-ovest di qui prosperava un tempo un accampamento di cultisti del Martello del Crepuscolo. Se ti avventurassi là adesso, troveresti la zona brulicante di elementali e nient'altro che pezzi sparsi di legno e di tela a segnare il punto dove sorgeva l'accampamento.$B$BSul posto ho recuperato alcuni frammenti di una tavoletta d'argilla, ma sono troppo pochi per ricomporre qualcosa di utile. Vedi se riesci a trovare i frammenti che mancano, così potremo fare un po' di luce sulla presenza del Martello del Crepuscolo qui a Silithus.",
  obj = "Geologist Larksbane, a Cenarion Hold a Silithus, vuole che tu raccolga 8 Twilight Tablet Fragments.",
  progress = "L'accampamento devastato si trova a nord-ovest di qui. Torna quando avrai tutti i frammenti.",
  reward = "Proprio come sospettavo. Riesco a decifrare singole parole delle tavolette, ma sembrano prive di qualsiasi logica o significato. Non è raro che le sette del Martello del Crepuscolo usino un codice per nascondere il significato dei loro testi; dovremo rivolgerci a qualcuno che ne sa di più su questo genere di cose.",
}
T[8285] = {
  title = "Il Disertore",
  desc = "Si dice che un membro del Martello del Crepuscolo di nome Ortell abbia disertato la sua setta. Corre voce che si sia nascosto sulle montagne a sud di Southwind Village, dove vive da eremita. Forse puoi convincerlo ad aiutarci a decifrare la tavoletta.$B$BPrendi con te la tavoletta ricostruita e vai a cercare Ortell.",
  obj = "Porta la tavoletta ricostruita a Hermit Ortell, a Silithus.",
  progress = "Tu! Come hai fatto a trovarmi? Chi sei? Non ti ha seguito nessuno, vero? Parla!",
  reward = "Vedo che conosci la mia vecchia organizzazione. Devi essere di Cenarion Hold.$B$BCerchi informazioni da usare contro di loro? Avvicinati, forse possiamo esserci utili a vicenda.",
}
T[8286] = {
  title = "Ciò che Porta il Domani",
  desc = "L'abbraccio della morte aveva quasi sopraffatto il mio essere quando lui intervenne. Alitò una sola volta sul mio corpo straziato, poi attese con pazienza che le sabbie del tempo purificassero le mie ferite.$B$B\"Per sempre resterai, se sarà necessario\", disse, e con quelle parole fui vincolato come Watcher.$B$BGuarda ora verso il deserto. La seconda guerra incombe su di noi. Devi cercare il luogo di riposo dei Bronze. Recati alle Caverns of Time e scopri se il padrone è tornato. Devo esserne certo prima di poter procedere.",
  obj = "Recati alle Caverns of Time a Tanaris e trova Anachronos, Brood of Nozdormu.",
  progress = "Anachronos è tornato?",
  reward = "È come deve essere — il grande si è destato. La mia veglia volge al termine...",
}
T[8287] = {
  title = "Uno Scopo Terribile",
  desc = "Ok, ci siamo... un'informazione bella preziosa, devo dire! Ho visto le forze del Cenarion Circle arrivare a Silithus. Vogliono scacciare il Martello del Crepuscolo, vero? Questo sarà d'aiuto.$B$BPorta questa pergamena al loro capo, il Comandante Mar'alith. Presto il Martello del Crepuscolo sarà sconfitto e io sarò fuori dalla loro portata una volta per tutte!",
  obj = "Porta la Decoded Tablet Transcription a Commander Mar'alith.",
  progress = "Cos'è che mi porti, $N?",
  reward = "Sono informazioni davvero molto interessanti, $N. Fanno un po' di luce sulla presenza del Martello del Crepuscolo a Silithus e ci aiuteranno senza dubbio nella lotta contro di loro. Il tuo impegno sarà lautamente ricompensato, $C.",
}
T[8288] = {
  title = "Solo Uno Potrà Emergere",
  desc = "Non c'è tempo da perdere! Bisogna trovare un eroe! Portare a termine il compito che affido richiederà un esercito, ma solo uno potrà emergere dalla folla degli aspiranti campioni per farsi carico del peso e della responsabilità di un alleato della Brood.$B$BNella tana del Signore di Blackrock c'è una bestia crudelissima. Il Signore della Progenie Lashlayer sorveglia le Sale del Conflitto e sbarra la via per il santuario interno di Nefarian. Uccidi quell'immonda aberrazione e portami la sua testa. Fallo, e potrai cominciare la prossima tappa del tuo viaggio.",
  obj = "Riporta la Head of the Broodlord Lashlayer a Baristolth of the Shifting Sands a Cenarion Hold, a Silithus.",
  progress = "È il favore della Brood of Nozdormu che devi guadagnarti.",
  reward = "Potresti essere tu $Gil primo:la prima;, in mille anni, a guadagnarti il favore del Bronze Flight?",
}
T[8290] = {
  title = "Sconfiggi gli Invasori",
  desc = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Rocca di Silverwing. Respingi le forze d'invasione dell'Orda!$B$BFallo, e ti guadagnerai un talismano al merito. Portamene uno, $N, e ti ricompenserò.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Boschetto dei Silverwing.",
  en_title = "Vanquish the Invaders",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[8291] = {
  title = "Sconfiggi gli Invasori!",
  desc = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo la vegetazione sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi la Rocca di Silverwing. Respingi le forze d'invasione dell'Orda!$B$BFallo, e ti guadagnerai un Contrassegno d'Onore. Portamelo, $N, e ti ricompenserò.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Boschetto dei Silverwing.",
  progress = "Hai combattuto in Warsong Gulch e difeso la Rocca di Silverwing?",
  reward = "Hai dimostrato il tuo valore nella nostra lotta in Warsong Gulch. Continua ad aiutare la causa e portami altri Contrassegni d'Onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.",
}
T[8294] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro volere sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BSenti l'orgoglio gonfiarti il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagnati un Contrassegno d'Onore. Torna da me con il Contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai, un contrassegno così?",
  reward = "<Il Capitano Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
}
T[8295] = {
  title = "Reprimi gli Usurpatori Silverwing",
  desc = "Le terre selvagge della foresta di Ashenvale cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro volere sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BSenti l'orgoglio gonfiarti il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinels e guadagnati un contrassegno d'onore di Warsong. Torna da me con il contrassegno, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[8297] = {
  title = "Contrassegno d'Onore di Arathi Basin!",
  desc = "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!$B$BEcco perché Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname — servono tutti, e tutti si possono ottenere lì.$B$BÈ questo che voglio da te, $N. Entra in Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Contrassegno d'Onore.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear, a Refuge Pointe.",
  progress = "Hai i Contrassegni d'Onore, $N? La League of Arathor non può combattere come si deve senza di essi...",
  reward = "Hai preso il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle nostre truppe.$B$BGrazie, $N. È proprio portando a termine missioni come la tua che si vincono davvero le guerre.",
}
T[8299] = {
  title = "Taglia le Linee di Rifornimento di Arathor",
  desc = "La League of Arathor non bada a spese nel tentativo di riprendersi Arathi. Loro e tutte le razze dell'Alleanza si stanno riversando in questa regione lontana, decisi ad allargare il loro dominio partendo da Refuge Pointe. Dobbiamo fermarli, e il modo migliore per farlo è prendere i loro rifornimenti.$B$BPuoi aiutarci, $N. Entra in Arathi Basin, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con il Contrassegno d'Onore che otterrai.",
  obj = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis, a Hammerfall.",
  progress = "Che c'è, $R? Hai i Contrassegni d'Onore? Torna in Arathi Basin, stermina i parassiti dell'Alleanza e impadronisciti delle sue risorse per la Signora Oscura!",
  reward = "<L'Inseguitore della Morte Mortis sorride>$B$BUn altro colpo decisivo è stato inferto ai nostri nemici, $N. Grazie alle tue imprese, Arathi Basin cadrà presto nelle mani dei Defilers.",
}
T[8301] = {
  title = "Il Sentiero del Giusto",
  desc = "La Brood of Nozdormu diffida per natura delle razze inferiori. È vero che mi hai dimostrato di avere la stoffa dell'eroe, ma è giunto il momento di dimostrarlo al mio padrone.$B$BHive'Ashi, Hive'Zora, Hive'Regal: Tutti brulicanti di attività e tutti una minaccia per la nostra esistenza. Uccidi i silithid in questi alveari e prendi da loro un frammento del carapace. Quando non potrai portarne altri, torna da me e rafforzerò la tua determinazione.",
  obj = "Raccogli 200 Silithid Carapace Fragments e torna da Baristolth of the Shifting Sands.",
  progress = "La loro diffidenza verso le razze mortali affonda le radici in una lunga storia; ma ahimè, è un racconto che è meglio lasciare alla Brood, quando sarà il momento.",
  reward = "Non sei $Gsolo:sola;, $Geroe:eroina;. Ora ti concederò la facoltà di delegare altri ad aiutarti nella tua missione. Se devi essere $Gil campione:la campionessa; del tuo popolo, avrai bisogno di aiuto nei tuoi compiti e nei tuoi doveri.",
}
T[8302] = {
  title = "La Mano del Giusto",
  desc = "Scegli con saggezza i tuoi delegati, mortale. Ogni volta che tornerai a compito ultimato, un nuovo delegato ti sarà concesso di scegliere.$B$BDetto questo, mi servono altri frammenti di carapace. Non perdere tempo!",
  obj = "Raccogli 200 Silithid Carapace Fragments e torna da Baristolth of the Shifting Sands.",
  progress = "Forse un giorno tutta Cenarion Hold lavorerà ai tuoi ordini.",
  reward = "Ben fatto, $Geroe:eroina;. Ora ti sarà concessa la facoltà di nominare un altro Agente di Nozdormu.",
}
T[8303] = {
  title = "Anachronos",
  desc = "È il momento, $N.$B$BDevo scusarmi per aver tenuto tante cose segrete. I nemici abbondano, perfino sotto il nostro naso. Ti prego, leggi questo tomo e impara. Prendi la conoscenza che ti do e cerca il nostro padrone.",
  obj = "Cerca Anachronos alle Caverns of Time, a Tanaris.",
  reward = "Tu sei la speranza di Kalimdor, $N.",
}
T[8304] = {
  title = "Carissima Natalia",
  desc = "La mia cara Natalia è scomparsa.$B$BA dire il vero, nelle settimane prima della scomparsa si comportava in modo strano. Più di una volta l'avevo sorpresa a parlare da sola quando non c'era nessuno. Insisteva che andava tutto bene e che doveva poter continuare le sue ricerche.$B$BL'ultima volta è stata vista dirigersi verso l'accampamento di Bronzebeard, a sud.$B$BI miei soldati sono già sparpagliati su troppi fronti, $N. Ho bisogno che tu vada all'accampamento di Bronzebeard a interrogare quei nani.",
  obj = "Commander Mar'alith, a Cenarion Hold a Silithus, vuole che tu interroghi gli abitanti dell'Accampamento di Bronzebeard. Troverai l'Accampamento di Bronzebeard a sud di Cenarion Hold.$B$BQuando avrai raccolto le informazioni richieste, torna da Commander Mar'alith.",
  progress = "Non perdere tempo, $N!",
  reward = "<Il Comandante Mar'alith china il capo in raccoglimento.>$B$BChe sia viva o morta, devo fare ciò che è giusto. Bisogna trovarla. Ahimè, il dovere mi lega a questo avamposto. Mi aiuterai ancora una volta, $N?",
}
T[8305] = {
  title = "Ricordi Dimenticati da Tempo",
  desc = "Nel deserto meridionale di Silithus, vicino alla sacra barriera, esiste un'unica lacrima cristallina. Questa lacrima è il simbolo delle grandi perdite che ci hanno colpito durante la Guerra delle Sabbie Mutevoli. Trovala e scruta nelle sue profondità per ricevere l'illuminazione.",
  obj = "Trova la Crystalline Tear a Silithus e scruta nelle sue profondità.",
  reward = "Senti un grande dolore aleggiare intorno a questo cristallo. È una forza così potente che ti sembra di essere sul punto di crollare e morire di tristezza.",
}
T[8306] = {
  title = "Nelle Fauci della Follia",
  desc = "Ho bisogno che tu ti avventuri a Hive'Regal e scopra che ne è stato della mia amatissima Natalia, $N. Non sarà un'impresa facile da affrontare $Gda solo:da sola;. Ti consiglio di portare con te qualche amico. Prima di gettarti a capofitto nelle fauci della follia, ricordati di tornare a parlare con quei nani. Forse possono darti qualche consiglio su come affrontare i silithid che abitano quell'alveare.$B$BE $N, se è davvero pazza come dicono... fa' quello che devi.$B$B<Il Comandante Mar'alith ti volta le spalle.>",
  obj = "Commander Mar'alith, a Cenarion Hold a Silithus, vuole che tu trovi la sua amata Natalia. Le informazioni che hai raccolto indicano Hive'Regal, a sud, come la zona in cui potresti trovare Mistress Natalia Mar'alith.$B$BNon dimenticare di passare dai nani all'accampamento di Bronzebeard prima di avventurarti nell'alveare. Potrebbero avere altro lavoro e qualche consiglio per te.$B$BE $N, ricorda le parole del Comandante: \"Fa' quello che devi...\"",
  progress = "Natalia?",
  reward = "<Il Comandante Mar'alith si porta le mani al petto.>$B$BC'Thun? COSA significa tutto questo? Cos'è C'Thun? Come ha potuto questo demonio trasformare la mia dolce Natalia nel mostro che hai descritto?",
}
T[8307] = {
  title = "Ricetta del Deserto",
  desc = "Adattarmi alla vita nel deserto è stato a dir poco difficile. Non solo mi mancano gli uccelli e gli alberi di Auberdine, ma questo ambiente arido limita moltissimo la nostra scelta di cibo. Sto cercando di conoscere le erbe del deserto, ma non ce ne sono molte.$B$BHo visto gruppi del Martello del Crepuscolo, dell'accampamento a ovest di qui, cacciare i vermi delle sabbie per mangiarli. La carne di verme delle sabbie però è così amara che non riesco a immaginare come la rendano gradevole. Tieni gli occhi aperti, se vai al loro accampamento, e fammi sapere se scopri qualcosa.",
  obj = "Cerca informazioni su come cucinare la Sandworm Meat nell'accampamento del Martello del Crepuscolo a ovest di Cenarion Hold.",
  reward = "Questo libro contiene diverse ricette comuni e alcune insolite. Dopo averlo sfogliato per qualche secondo, noti una ricetta che prevede la carne di verme delle sabbie.",
}
T[8308] = {
  title = "La Lettera Perduta di Brann Bronzebeard",
  desc = "A chi di dovere:$B$BSe stai leggendo questa lettera, sono morto o sto per esserlo. Difficile a dirsi. Tanto quasi tutta la squadra è morta.$B$BTrovate informazioni su un Titano. Grande battaglia tra lui e un Dio Antico. Sì, un Dio Antico vero e proprio. Trovato antico tunnel che porta ad Ahn'Qiraj. Lo prendo.$B$BPorta questa lettera al mio vecchio accampamento. Assicurati che la mia scimmia riceva cibo, acqua e abbracci a sufficienza.$B$B— Brann Bronzebeard, Esploratore Estremo$B$BP.S. Occhio a elfa della notte pazza, adoratrice di un Dio Antico.",
  obj = "Porta Brann Bronzebeard's Lost Letter all'Accampamento di Bronzebeard, nel sud di Silithus.",
  progress = "Oh cielo.",
  reward = "Be', questo spiega molte cose. Se mai trovi il modo di entrare ad Ahn'Qiraj, tieni gli occhi aperti, caso mai vedessi il vecchio Brann. Temo che senza la sua scimmia non possa fare niente.",
}
T[8309] = {
  title = "A Caccia di Glifi",
  desc = "Dopo la nostra prima incursione negli alveari e la follia che poi ha colpito la Signora Mar'alith, i tre alveari si sono messi a vomitare insetti! Tutta questa attività in più potrebbe essere legata ai glifi che ricoprono quegli strani cristalli.$B$BDobbiamo fare un ricalco dei cristalli di tutti e tre gli alveari. Se riusciamo ad avere quei ricalchi, forse potremo trovare un senso a questa follia.$B$BPrendi questo corredo da trascrizione e qualche amico e fiondati in quegli alveari, $N. Non tornare finché non hai una copia da ogni alveare.",
  obj = "Rutgar Glyphshaper, all'Accampamento di Bronzebeard a Silithus, vuole che tu vada a Hive'Ashi, Hive'Zora e Hive'Regal e recuperi i Ricalchi dei Glifi dai Cristalli con Glifi di ogni alveare.$B$BUsa Geologist's Transcription Kit per fare una copia accettabile degli antichi glifi. Quando hai finito, torna da Rutgar Glyphshaper.",
  progress = "Se in uno degli alveari trovi una ragazza elfa della notte fuori di testa, ricordati di darle un calcio nel sedere da parte nostra.",
  reward = "Di questi glifi non capisco un'acca. Mai visto niente di simile! Spero che le ricerche di Frankal facciano un po' di luce su questo pasticcio.",
}
T[8310] = {
  title = "Decifrare il Codice",
  desc = "Credo di poter mettere a punto un elisir che ci permetterà di decifrare più facilmente i glifi e la lingua dei silithid e dei Qiraji! Cosa mi serve? Meno male che me lo chiedi! Mi servono cervelli! Per la precisione, un cervello per ogni tipo di silithid che vive negli alveari. Portami dei cervelli e forse il lavoro di Rutgar non sarà stato inutile.",
  obj = "Frankal Stonebridge, all'Accampamento di Bronzebeard a Silithus, vuole che tu recuperi un Hive'Zora Silithid Brain, un Hive'Ashi Silithid Brain e un Hive'Regal Silithid Brain. Quando hai finito, torna da Frankal.",
  progress = "Va' a giocare con la scimmia, $Gragazzino:ragazzina;. Non ho tempo per queste cose.",
  reward = "Eccezionale! Non allontanarti troppo, $Gragazzino:ragazzina;. Potremmo aver bisogno di te per un altro incarico o due.",
}
T[8311] = {
  title = "Dolcetti della Veglia delle Ombre per Jesper!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu per me, ti scambio le caramelle che prendi con alcune che ho già! Credo che queste caramelle ti piacerebbero — ti trasformano in cose buffe e spaventose!$B$BTutti i locandieri delle grandi città hanno delle caramelle da regalare per la Veglia delle Ombre — parla con loro e fai gli scherzetti che ti chiedono! Anche un piccolo gnomo di nome Talvash, a Ironforge, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!",
  obj = "Parla con i locandieri di Stormwind, Ironforge e Darnassus, e con Talvash del Kissel a Ironforge. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.$B$BTorna da Jesper, all'Orfanotrofio di Stormwind, con un Darnassus Marzipan, una Gnomeregan Gumdrop, uno Stormwind Nougat e una Ironforge Mint.",
  progress = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malato, ma il fatto che mi aiuti mi fa sentire un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca — credo che ti piaceranno un sacco!$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Hallow's End Treats for Jesper!",
  en_obj = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.",
}
T[8312] = {
  title = "Dolcetti della Veglia delle Ombre per Spoops!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malata. Se ci vai tu per me, ti darei in cambio delle caramelle che ho già! Credo che queste caramelle ti piacerebbero — ti trasformano in cose buffe e spaventose!$B$BOgnuno dei locandieri delle grandi città ha delle caramelle che regala per la Veglia delle Ombre — parla con loro e fai gli scherzetti che ti chiedono! Anche un troll di nome Kali Remik, a Sen'jin Village, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!",
  obj = "Parla con i locandieri di Orgrimmar, di Undercity e di Thunder Bluff, e con Kali Remik a Sen'jin Village. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.$B$BTorna da Spoops, all'Orfanotrofio di Orgrimmar, con un Thunder Bluff Marzipan, una Darkspear Gumdrop, un Orgrimmar Nougat e una Undercity Mint.",
  progress = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malata, ma il fatto che mi aiuti mi fa sentire un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca — credo che ti piaceranno un sacco!$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Hallow's End Treats for Spoops!",
  en_obj = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.",
}
T[8313] = {
  title = "Condividere il Sapere",
  desc = "La ricetta per cucinare la carne di verme delle sabbie è leggibile, ma nomina erbe e spezie che non hai mai sentito. Forse Calandrath conosce abbastanza le piante che crescono nel deserto da riuscire a capirci qualcosa.",
  obj = "Porta la Torn Recipe Page a Calandrath, alla locanda di Cenarion Hold.",
  progress = "Hai imparato la ricetta? Non la terrai per te, spero!",
  reward = "Diamo un'occhiata...$B$BMi sembra abbastanza semplice. Per alcune erbe usano nomi loro, ma non è difficile capire quali sono. Ecco, ti faccio vedere!",
}
T[8314] = {
  title = "Svelare il Mistero",
  desc = "Siamo a un passo dalla svolta, $N! Grazie ai ricalchi che hai recuperato abbiamo potuto ricreare i glifi su questo prisma cristallino. A quanto pare sono un mezzo con cui i Qiraji e altre entità sconosciute comunicano vari messaggi ai silithid.$B$BPurtroppo dai glifi non siamo riusciti a ricavare altro. Dobbiamo trovare il modo di sbloccare i messaggi nascosti nei cristalli.$B$BPorta il prisma di cristallo con glifi alla Geologa Larksbane, a Cenarion Hold. Forse lei può aiutarci.",
  obj = "Rutgar Glyphshaper, all'Accampamento di Bronzebeard, vuole che tu consegni il Glyphed Crystal Prism a Geologist Larksbane, a Cenarion Hold a Silithus.",
  progress = "Santo cielo! Cos'hai lì, $N?",
  reward = "Il motivo per cui i nani non sono riusciti a decifrare i glifi è che non c'è niente da decifrare. Lo strato esterno del prisma, che è mobile, deve allinearsi nel modo giusto con i segni del cristallo interno perché il messaggio venga trasmesso. Ingegnoso...$B$BQuesti dati dovremmo riuscire a tradurli, ma prima dobbiamo sbloccare il codice. Sulla superficie del prisma c'è un solo indizio — sempre che i ricalchi siano stati riportati correttamente — e non promette niente di buono.",
}
T[8315] = {
  title = "Il Richiamo",
  desc = "I glifi raffigurano un emissario dei Qiraji che incontra tre silithid presso le ossa di un grande drago. Sopra i glifi c'è quello che posso solo supporre sia un codice di qualche tipo. Questo codice potrebbe benissimo essere la chiave per evocare l'emissario.$B$BCreerò una copia del codice dei glifi, che dovrai usare nella sabbia alle Ossa di Grakkarond. Se ho ragione, i Signori Supremi arriveranno convinti che ci siano nuovi dati pronti per la trasmissione. Abbattili e affronta l'emissario. È lui ad avere la chiave dei cristalli...",
  obj = "Geologist Larksbane, a Cenarion Hold a Silithus, vuole che tu recuperi il Crystal Unlocking Mechanism dal Qiraji Emissary.$B$BTi è stato detto di portare i Glyphs of Calling alle Ossa di Grakkarond, a sud di Cenarion Hold, e di disegnarli nella sabbia. Se compare il Qiraji Emissary, uccidilo e recupera il Crystal Unlocking Mechanism. Se ci riesci, torna da Geologist Larksbane.$B$BRaduna un esercito per questa impresa, $N!",
  progress = "Devi cogliere l'occasione quando si presenta e colpire!",
  reward = "Ho fra le mani 20.000 anni di storia, $N!",
}
T[8316] = {
  title = "Armamenti di Guerra",
  reward = "La guerra è in arrivo, $N, e porta con sé orrori indicibili. Hai fatto tutto quello che ti si poteva chiedere, e per questo meriti una ricompensa.$B$BSe questa... questa profezia dovesse mai avverarsi...$B$B<La Geologa Larksbane impallidisce.>$B$BPer tutti noi potrebbe non esserci più un futuro.$B$BQuesti armamenti si riveleranno preziosissimi per la tua campagna in questo deserto.",
}
T[8317] = {
  title = "Aiuto in Cucina",
  desc = "Quella ricetta mi tornerà proprio utile. Sarà meglio che mi metta al lavoro, così per oggi avrò pronti degli gnocchi affumicati del deserto. Mi farebbe comodo una mano a prepararli, e saprò ricompensarti.",
  obj = "A Calandrath, a Cenarion Hold, servono 10 Smoked Desert Dumplings.",
  progress = "Come procedono quegli gnocchi?",
  reward = "Eccellente! Sei la mia salvezza. Questi gnocchi sono venuti davvero buoni. Non mi aspettavo proprio tanto buon gusto dal Martello del Crepuscolo.",
}
T[8318] = {
  title = "Comunicazione Segreta",
  desc = "Alcuni cultisti del Martello del Crepuscolo si portano dietro dei foglietti con sopra frasi senza senso. Voglio che me ne porti una pila, $C.$B$BNon riesco a capire cosa vogliano dire quelle frasi senza senso, ma non è questo il punto! Quei foglietti sono il modo in cui i loro vari gruppi comunicano in segreto. Più testi togliamo dalla circolazione, meno potranno comunicare!",
  obj = "Porta 10 Encrypted Twilight Texts a Bor Wildmane, a Cenarion Hold.",
  progress = "Mi hai portato dei testi?",
  reward = "Ottimo! Questi li metto da parte, magari più avanti tornano utili.",
}
T[8319] = {
  title = "Testi Crepuscolari Codificati",
  progress = "Continua a portarmi testi. Presto cacceremo il Martello del Crepuscolo da Silithus.",
  reward = "Ottimo lavoro! Metterò una buona parola per te.",
}
T[8320] = {
  title = "Geosignori del Crepuscolo",
  desc = "Il Martello del Crepuscolo, un culto folle votato alla distruzione, ha allestito degli accampamenti a Silithus e celebra rituali giorno e notte. Non conosciamo ancora i loro piani, ma pensiamo che siano in qualche modo legati ai cristalli rossi pulsanti sparsi per il deserto.$B$BUn giorno forse il loro mistero sarà svelato, ma prima dobbiamo occuparci della minaccia immediata che rappresentano. Va' nei loro accampamenti a ovest e cerca i geosignori del Crepuscolo. Sono loro le teste di questi serpenti; è lì che dobbiamo colpire!",
  obj = "Uccidi 10 Twilight Geolords, poi torna da Huum Wildmane a Cenarion Hold.",
  progress = "Addentrati nel deserto e trova i geosignori del Crepuscolo, $N. Torna da me quando saranno stati uccisi.",
  reward = "Hai svolto bene il tuo compito, $N. Uccidendo i geosignori del Crepuscolo devi aver inferto un duro colpo al culto. Speriamo che questo rallenti i loro piani...",
}
T[8321] = {
  title = "Vyral il Vile",
  desc = "Abbiamo scoperto un'altra base operativa del Martello del Crepuscolo. Si chiama Grotta del Crepuscolo; è una caverna nascosta nell'angolo nord-orientale di Silithus. Il capo locale del culto, Vyral il Vile, si aggira in quella caverna — è lui il prossimo che devi sconfiggere. Quando l'avrai fatto, portami il suo anello con sigillo.$B$BBuona fortuna, $N. Gli orrori della Grotta del Crepuscolo sono davvero temibili.",
  obj = "Porta Vyral's Signet Ring a Huum Wildmane, a Cenarion Hold.",
  progress = "$N, hai già sconfitto Vyral il Vile? Hai il suo anello con sigillo?",
  reward = "Ce l'hai fatta! Vyral è stato ucciso! Questo può significare solo la rovina per le operazioni del Martello del Crepuscolo a Silithus. Forse ce ne sono altri che scorrazzano in giro, ma dal colpo che hai inferto oggi al culto non si riprenderanno facilmente.",
}
T[8322] = {
  title = "Uova Marce",
  desc = "Gli umani di Southshore adorano la loro birra, e per questo tengono moltissimo alla birra servita alla Locanda di Southshore. Ora che il caos della Veglia delle Ombre si è abbattuto su di loro, possiamo approfittarne per rovinare le loro prossime partite di birra per settimane — se non per mesi!$B$BPrendi queste uova marce e mettile nel barile principale della birra, dentro la Locanda di Southshore. La tua sola presenza scatenerà lo scompiglio, quindi preparati a difenderti!$B$BQuando avrai fatto assaggiare a Southshore qualcosa che non dimenticherà presto, torna da me qui alla festa!",
  obj = "Metti le Rotten Eggs nel barile principale della birra, dentro la Locanda di Southshore.",
  progress = "Il barile è pieno di birra.",
  reward = "Dopo esserti $Gfatto:fatta; strada a forza dentro la locanda, metti le uova nel barile. Senti il fetore che impregna l'aria...",
  en_title = "Rotten Eggs",
  en_obj = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.",
}
T[8323] = {
  title = "Veri Credenti",
  desc = "Ora che il Dizionario del Crepuscolo è in mano mia, c'è un piccolo favore che vorrei chiederti.$B$BLa mia vecchia organizzazione ha un bollettino segreto in codice che fa circolare ogni mese.$B$BSe fanno progressi nel darmi la caccia, o se rinunciano alle ricerche, la notizia uscirà sul Vero Credente.$B$BQueste informazioni sono ovviamente preziose per me, ma la pubblicazione contiene anche altre notizie utili che posso condividere. Portami tutti i testi in codice che trovi addosso ai membri del Martello del Crepuscolo.",
  obj = "Hermit Ortell vuole che tu gli porti 10 Encrypted Twilight Texts",
  progress = "Hai trovato qualche testo cifrato? Sono proprio curioso di leggere il Vero Credente di questo mese.",
  reward = "Eccellente! Mi metterò a decifrarli il prima possibile. Se ci trovo qualcosa d'interessante, troverò il modo di fartelo sapere.",
}
T[8324] = {
  title = "Credere Ancora",
  progress = "Trovati altri testi cifrati? Portamene una bella quantità, questo lavoro di decifrazione richiede tempo.",
  reward = "Eccellente! Non vedo l'ora di leggerli. Mi raccomando, continua a portare qui i testi cifrati, se ne trovi.",
}
T[8331] = {
  title = "Aurel Goldleaf",
  desc = "$N, anche se speravamo che le operazioni del Martello del Crepuscolo a Silithus stessero rallentando... purtroppo ci sbagliavamo. Continuando le incursioni contro il culto, abbiamo scoperto che un potere ancora più oscuro, l'Abyssal Council, controlla il Martello attraverso le arcane pietre del vento disseminate fra gli accampamenti del culto. La tua prossima azione, $N, sarà contro l'Abyssal Council.$B$BParla con l'artigiana Aurel Goldleaf, nella parte orientale di Cenarion Hold. La sua abilità servirà per questa prossima mossa.",
  obj = "Parla con Aurel Goldleaf a Cenarion Hold.",
  reward = "$N, buongiorno. Mi hanno detto che ti scontrerai con l'Abyssal Council? Se è così, ascolta bene quello che sto per dirti...",
}
T[8332] = {
  title = "Duchi del Council",
  desc = "Pensiamo che sia possibile usare una pietra del vento per tendere un'imboscata a un duca dell'Abyssal Council. Per farlo, però, bisogna entrare in comunione attraverso la pietra del vento e convincere il concilio di essere un capo di medio rango del Martello del Crepuscolo.$B$BUna mossa del genere richiede una replica del medaglione di rango del culto. Il medaglione posso crearlo io, ma mi serviranno un grosso frammento splendente e gli stemmi portati dai Templari Abissali.$B$BPortameli e al resto penserò io.",
  obj = "Porta 1 Large Brilliant Shard e 3 Abyssal Crests ad Aurel Goldleaf, a Cenarion Hold.",
  progress = "Hai il frammento e gli stemmi, $N? Mi serviranno per fare il medaglione di rango da cultista del crepuscolo.",
  reward = "Ah, molto bene. Stavo lavorando al medaglione — ora, con questi ultimi ingredienti, mi bastano pochi istanti per finirlo...$B$BEcco fatto. Questo è il medaglione, $N.$B$BDovrai indossarlo quando attiverai una delle pietre del vento del Martello del Crepuscolo. Mettilo, insieme al resto dei paramenti del crepuscolo, e l'Abyssal Council ti scambierà per $Guno dei suoi cultisti sottoposti:una delle sue cultiste sottoposte;.",
}
T[8333] = {
  title = "Medaglione di Rango",
  progress = "Se ti serve un altro medaglione di rango da cultista del Crepuscolo, te lo faccio volentieri. Però mi serviranno un altro frammento splendente e qualche stemma abissale...",
  reward = "Ecco a te, $N. Un altro medaglione di rango del Crepuscolo. Fanne buon uso, e buona fortuna contro l'Abyssal Council!",
}
T[8341] = {
  title = "Signori del Council",
  desc = "I Signori dell'Abyssal Council si possono evocare solo attraverso le pietre del vento superiori, e solo i membri di più alto rango del Martello del Crepuscolo possono parlare con loro. Ma... ho trovato il modo di migliorare il tuo travestimento e ingannare i Signori Abissali!$B$BIl travestimento richiede un anello di signoria, portato solo dai più alti in grado del culto. Te ne fabbricherò uno, se riesci a portarmi dei grossi frammenti splendenti e dei sigilli abissali.",
  obj = "Porta 5 Large Brilliant Shards e 3 Abyssal Signets ad Aurel Goldleaf, a Cenarion Hold.",
  progress = "Hai i frammenti e i sigilli, $N? Mi serviranno per creare l'anello di signoria.",
  reward = "Grazie. Solo un momento e l'anello sarà pronto...$B$BEccolo. Ora sei $Gpronto:pronta;.$B$BRicordati di indossare questo anello, insieme a un medaglione di rango e al resto dei paramenti del crepuscolo, quando attivi una pietra del vento superiore. Fallo, e l'Abyssal Council ti crederà $Guno dei suoi servitori:una delle sue servitrici;. A quel punto, forse, potrai attirarne uno in un'imboscata!",
}
T[8342] = {
  title = "Anello di Signoria del Crepuscolo",
  progress = "$N, se hai intenzione di dare di nuovo la caccia all'Abyssal High Council, ti servirà un altro anello di signoria del Crepuscolo. Portami altri frammenti e altri sigilli e te ne farò uno.",
  reward = "Ah, vedo che le tue convinzioni sono forti. Non sono in molti a voler affrontare quel concilio di demoni!$B$BEcco il tuo anello, $N. Che la tua volontà, e la tua fortuna, restino salde.",
}
T[8343] = {
  title = "La Scoperta di Goldleaf",
  desc = "$N, Aurel Goldleaf pensa di aver trovato il modo di evocare e sconfiggere uno dei membri al comando dell'Abyssal Council! Sarà un'impresa pericolosa, ma hai conquistato grande rispetto nel Cenarion Circle. Sappiamo che se c'è qualcuno che può farcela, sei tu.$B$BChe la fortuna ti accompagni, $N. Parla con Aurel quando sei $Gpronto:pronta;.",
  obj = "Parla con Aurel Goldleaf a Cenarion Hold.",
  reward = "Quello che dice Huum è vero. Credo di sapere come evocare un signore dell'Abyssal Council! Resta ad ascoltare, e ti spiegherò...",
}
T[8348] = {
  title = "Il Sigillo dei Duchi",
  desc = "Huum mi dice che hai capito come evocare i Duchi Abissali! È un bel risultato.$B$BSai cos'altro sarebbe un gran bel risultato? Fare a pezzi per bene uno di quei cosi. Farà una certa impressione sui loro sottoposti, non so se mi spiego. Portami il suo sigillo come prova dell'impresa.",
  obj = "Porta l'Abyssal Signet a Bor Wildmane, a Cenarion Hold.",
  progress = "Com'è andata con il Duca Abissale? Picchiava forte?",
  reward = "L'ho capito che eri $Gun:una; $C $Gtosto:tosta; appena ti ho visto entrare a Cenarion Hold. Continua così!",
}
T[8349] = {
  title = "Bor Wildmane",
  desc = "Ora che hai un medaglione e puoi evocare un Duca Abissale, parla con Bor Wildmane. Ti affiderà un incarico contro l'Abyssal Council.$B$BBuona fortuna, $N. E se mai ti servissero altri medaglioni, torna da me.",
  obj = "Parla con Bor Wildmane a Cenarion Hold.",
  reward = "È bello rivederti, $C! E così ti sei $Gfatto:fatta; fare un medaglione? Bene — ti servirà per la tua prossima missione...",
}
T[8351] = {
  title = "Bor Vuole Parlarti",
  desc = "Ora che puoi travestirti da uno dei capi del Twilight Council, sono certa che Bor Wildmane vorrà parlarti. Va' da lui, e preparati a una missione molto difficile...",
  obj = "Parla con Bor Wildmane a Cenarion Hold.",
  reward = "Sì, esatto, $N. Ho davanti un compito molto duro...",
}
T[8352] = {
  title = "Scettro del Council",
  desc = "Io e Huum stavamo giusto parlando di te. Mi dice che sei quasi $Gpronto:pronta; per provare ad affrontare un Signore Abissale!$B$BDevo avvertirti che è un'impresa molto pericolosa. Ti conviene portare rinforzi. E non intendo uno o due dei tuoi amici, parlo di una forza da combattimento di prim'ordine, pronta alla battaglia. Se i tuoi amici sono in gamba quanto te, potresti perfino sconfiggerlo!$B$BSe ci riesci — e vorrò le prove, come sempre — ti darò una ricompensa davvero magnifica.",
  obj = "Porta un Abyssal Scepter a Bor Wildmane a Cenarion Hold.",
  progress = "Allora, com'è andata? Darei qualsiasi cosa per lasciare il mio posto e azzuffarmi di persona con uno di quei cosi!",
  reward = "Ce... ce l'hai fatta! Ce l'hai fatta, $N! Ecco! Prendi questo. È il forziere più grosso che avevamo sottomano, e l'ho riempito con alcune delle cose migliori che abbiamo trovato.",
}
T[8353] = {
  title = "Chiocciare per una Mentina",
  desc = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...$B$BBe', per il mio dolcetto — una Mentina di Ironforge — dovrai... chiocciare come una gallina! Sì, le galline adorano le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!$B$BAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!",
  obj = "Fai l'emote /chicken davanti a Innkeeper Firebrew, e in cambio riceverai una Ironforge Mint!",
  progress = "Sto aspettando...",
  reward = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!",
}
T[8354] = {
  title = "Chiocciare per una Mentina",
  desc = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...$B$BBe', per il mio dolcetto — una Mentina di Undercity — dovrai... chiocciare come una gallina! Sì, le galline adorano le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!$B$BAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!",
  obj = "Fai l'emote /chicken davanti a Innkeeper Norman, e in cambio riceverai una Undercity Mint!",
  progress = "Sto aspettando...",
  reward = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!",
}
T[8355] = {
  title = "Arriva la Caramella Gommosa",
  desc = "$GUno:Una; che fa dolcetto o scherzetto! Evviva!$B$BBe', anche se stai facendo una cosa nobile raccogliendo caramelle per un bambino malato, non posso lasciarti andare così facilmente. Ho una deliziosa Caramella Gommosa di Gnomeregan da dare al bambino malato... se fai il verso di un treno per me! Ahah, sì, sarà questo lo scherzetto! Il prezzo di questa caramella è un verso da treno!$B$BCiuf ciuf, $C!",
  obj = "Fai l'emote /train davanti a Talvash del Kissel, e in cambio riceverai una Gnomeregan Gumdrop!",
  progress = "Be', forza...",
  reward = "Tuu tuu! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Incoming Gumdrop",
  en_obj = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!",
}
T[8356] = {
  title = "Muscoli in Cambio di Torrone",
  desc = "È un costume... interessante, quello che indossi. Anche se sei gentile e quest'anno aiuti un bambino malato a fare dolcetto o scherzetto, temo che dovrò chiederti di fare uno scherzetto per me!$B$BVediamo... sembri così forte e $Gmuscoloso:muscolosa; con quel... costume... fammi vedere i muscoli! Sì, forza, mostrami i muscoli, $Guomo:donna; forte!$B$BQuando, e solo quando, mi mostrerai i muscoli, ti darò un po' di buonissimo Torrone di Stormwind. È un ottimo dolcetto della Veglia delle Ombre.",
  obj = "Fai l'emote /flex davanti a Innkeeper Allison, e in cambio riceverai lo Stormwind Nougat!",
  progress = "Niente caramelle finché non mi mostri i muscoli, $N...",
  reward = "Sei davvero potente, ahah! Ben fatto, e grazie per essere $Gstato:stata; al gioco. Ecco la tua caramella.$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Flexing for Nougat",
  en_obj = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!$B",
}
T[8357] = {
  title = "Ballare per il Marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, ti pare...$B$BCredo che di questi tempi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!",
  obj = "Fai l'emote /dance davanti a Innkeeper Saelienne, e in cambio riceverai il Darnassus Marzipan!",
  progress = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo per bene...",
  reward = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!$B$BEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!",
}
T[8360] = {
  title = "Ballare per il Marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, ti pare...$B$BCredo che di questi tempi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!",
  obj = "Fai l'emote /dance davanti a Innkeeper Pala, e in cambio riceverai il Thunder Bluff Marzipan!",
  progress = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo per bene...",
  reward = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!$B$BEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!",
}
T[8361] = {
  title = "Contatti Abissali",
  desc = "Abbiamo visto i cultisti del Martello del Crepuscolo compiere rituali per evocare potenti nobili elementali. Non sappiamo se siano questi gli esseri che i cultisti venerano o se facciano da intermediari con forze ancora più potenti. Una cosa è certa: è da questi elementali che ricevono gli ordini.$B$BVoglio che trovi il modo di contattare un Templare Abissale e che gliele suoni come si deve! Niente getta le truppe nello scompiglio come far fuori la catena di comando. E già che ci sei, portami una prova.",
  obj = "Bor Wildmane, a Cenarion Hold, a Silithus, vuole che tu distrugga un Templare Abissale e gli porti un Abyssal Crest come prova dell'impresa.",
  progress = "Hai portato a termine il lavoro?",
  reward = "Ah! Ce l'hai fatta, $N! Presto il Martello del Crepuscolo sarà schiacciato!",
}
T[8362] = {
  title = "Amuleti Abissali",
  progress = "Hai dimostrato di sapertela cavare in combattimento, $N. Continuiamo a tenere sotto pressione il Martello del Crepuscolo. Va' a combattere altri Templari Abissali, ti ricompenserò con un po' della roba che io e Huum abbiamo trovato in battaglia.",
  reward = "Hai fatto un buon lavoro! Sono Templari in meno di cui devo preoccuparmi.$B$BEcco a te, $N. Spero che lì dentro ci sia qualcosa che ti possa servire.",
}
T[8363] = {
  title = "Sigilli Abissali",
  progress = "Hai dimostrato di essere più che capace di affrontare un Duca Abissale, $N. Io sono uno che le buone abitudini le incoraggia sempre. Portami altri sigilli e ti darò una ricompensa.",
  reward = "Eccellente, $N! Sconfiggere quei Duchi lascerà il Martello del Crepuscolo tramortito per un po'. Come promesso, ecco la tua ricompensa. È un po' della roba migliore che io e Huum abbiamo trovato.",
}
T[8364] = {
  title = "Scettri Abissali",
  progress = "Hai davvero superato ogni mia aspettativa, $N. Stai affrontando avversari che io e Huum attaccheremmo solo dopo averci pensato a lungo.$B$BA questo punto il meglio che posso fare è continuare a ricompensare i tuoi sforzi nella lotta contro il Martello del Crepuscolo e i suoi padroni.$B$BPortami altri scettri abissali e farò del mio meglio per darti una ricompensa adeguata.",
  reward = "Sapevo che ce l'avresti fatta, $N! Ecco la tua ricompensa.",
}
T[8365] = {
  title = "Cappelli da Pirata in Vista!",
  desc = "Sei tu l'aiuto mandato dal Cartel? Immagino che andrai bene. Ascolta attentamente, $C. Come sai, sono una fornitrice di abiti alla moda per l'élite della società di Azeroth. Re e Regine, Capoguerra e, be', comunque l'Orda chiami le sue regine, tutti indossano quello che io decido che va di moda. E lo pagano un occhio della testa, che è la parte migliore.$B$BQuindi ecco cosa succederà. Tu scendi alla Cala del Sartiame e ti procuri un bel po' di cappelli da pirata, con qualunque mezzo. Pensi di farcela?",
  obj = "Haughty Modiste vuole che tu raccolga 20 Southsea Pirate Hats e glieli riporti a Steamwheedle Port, a Tanaris.",
  progress = "Hai tutti e 20 i cappelli? Non ti credo, fammeli vedere. Sarà meglio che siano in condizioni impeccabili!",
  reward = "Oh, sei un tesoro, anche se ci hai messo più tempo di quello a cui sono abituata. Questo carico dovrebbe farmi guadagnare un bel po', una volta che avrò pulito e personalizzato questi cappelli. E visto che sono sempre disposta a premiare un lavoro ben fatto, ecco un pensierino per te. Ti suggerisco di spenderne una parte per un bagno, dolcezza.",
}
T[8366] = {
  title = "Strigliata ai Southsea",
  desc = "Argh! Vogliono l'impossibile da me!$B$BLo Steamwheedle Cartel vuole che io dia una lezione ai pirati Southsea. Il problema è che non posso essere in due posti contemporaneamente; devo restare qui a mantenere l'ordine.$B$BUltimamente i pirati se ne infischiano del pizzo che il cartello sborsa regolarmente. Perciò vorrei nominarti temporaneamente $Gmio:mia; vice e mandarti laggiù a fargliela vedere.$B$BLi troverai alla Cala del Sartiame, che non è troppo lontana, a sud. Grazie, $N, ti devo un favore!",
  obj = "Security Chief Bilgewhizzle di Steamwheedle Port, a Tanaris, vuole che tu uccida 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers e 10 Southsea Swashbucklers.",
  progress = "Già di ritorno? Spero che tu abbia dato a quei teppisti Southsea una lezione che non scorderanno tanto presto.",
  reward = "$N! Sei $Gun grande:una grande;!!!$B$BSono sicuro che il Cartel mi darà tregua, ora che hai sistemato quella feccia dei Southsea. Vediamo, cosa posso darti come ricompensa? Che ne dici di qualche moneta e di uno di questi a tua scelta, per il disturbo?",
}
T[8367] = {
  title = "Per un Grande Onore",
  desc = "Servire l'Orda in una delle grandi battaglie contro l'Alleanza è fonte di grande onore! Ma i pochi che hanno servito l'Orda su TUTTI i nostri fronti aperti sono i nostri veri grandi combattenti. Sconfiggeremo i nostri avversari non combattendo scaramucce isolate, ma conducendo una guerra ben coordinata.$B$BVa' e schiaccia l'Alleanza ad Arathi Basin, ad Alterac Valley e a Warsong Gulch! Per l'Onore! Per l'Orda!",
  obj = "Porta 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor e 3 Warsong Gulch Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Arathi è ancora bagnata dal sangue di grandi guerrieri, e il clangore dell'acciaio risuona ancora per tutta Alterac. Non farmi perdere tempo, a meno che tu non porti notizie dal fronte!",
  reward = "Le tue prove non sono state facili, ma il coraggio non ti ha abbandonato e la forza non ti è venuta meno. Separati dai vecchi simboli di vittoria, $C. Nessuno ne avrà bisogno per ricordarsi del tuo valore. Sta' $Gdritto:dritta;, $N. Oggi camminerai con grande orgoglio, perché sei $Gun eroe:un'eroina;!",
}
T[8368] = {
  title = "La Battaglia di Warsong Gulch",
  desc = "La battaglia in Warsong Gulch contro le Silverwing Sentinels è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre principali fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito degnamente l'Orda!",
  obj = "Porta 3 Warsong Gulch Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Porti notizie da Warsong Gulch, $N?",
  reward = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Possa la fama del tuo onore diffondersi in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8369] = {
  title = "Invasori di Alterac Valley",
  desc = "Ascoltami bene, $N. Qualunque cosa tu abbia sentito sulla battaglia che infuria ad Alterac Valley, una cosa resta vera: la Stormpike Expedition ha invaso il Territorio dei Frostwolf. Il giorno in cui permetteremo all'Alleanza di invadere le terre dell'Orda senza una risposta dura sarà il giorno in cui appenderò l'ascia al chiodo e vivrò nella vergogna il resto dei miei giorni. Va' e scaccia gli invasori!",
  obj = "Porta 3 Alterac Valley Marks of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Che notizie porti dalle terre dei Frostwolf? Come va la battaglia per Alterac Valley?",
  reward = "Hai dimostrato grande coraggio nel proteggere le nostre terre ad Alterac Valley! Riferirò le tue gesta ai miei superiori.",
}
T[8370] = {
  title = "Conquistare Arathi Basin",
  desc = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. A questo punto nessuna delle due parti usa più, né si aspetta, falsi pretesti per scendere in battaglia.$B$BLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per sostenere il nostro sforzo di guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie da Arathi, $C?",
  reward = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8371] = {
  title = "Sforzi Congiunti",
  desc = "Non combattiamo più battaglie isolate contro l'Orda, $Gragazzo:ragazza;.$B$BVincere su un fronte vuol dire togliere all'Orda risorse che userebbe contro di noi in un'altra battaglia. Allo stesso modo, perdere una battaglia qualsiasi potrebbe dare il vantaggio all'avversario da qualche altra parte del mondo.$B$BAll'Alleanza servono più combattenti con questa visione d'insieme del mondo... veterani davvero navigati! $N, torna da me dopo aver prestato servizio contro l'Orda su tutti i nostri campi di battaglia attivi.",
  obj = "Porta 3 Alterac Valley Mark of Honor, 3 Arathi Basin Mark of Honor e 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Come ti vanno i viaggi, $Gragazzo:ragazza;?",
  reward = "Non sei tipo da deludere, $N! Quello che hai imparato va oltre misere medaglie ed encomi. Quello che hai imparato lo possono dare soltanto l'esperienza e il carattere che si tempra sul campo di battaglia.$B$BSei $Gstato bravo:stata brava;, $C. Sei $Gun vero eroe:una vera eroina; dell'Alleanza!",
}
T[8372] = {
  title = "Combatti per Warsong Gulch",
  desc = "Le Silverwing Sentinels sono in guerra con i Warsong Outriders per la distruzione che gli Orchi stanno causando alla foresta. Ma per difendere proprio questa foresta ci sono ragioni che vanno oltre il semplice amore per la natura.$B$BLa foresta costituisce una barriera strategica che permette di difendere Ashenvale da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle Barrens.$B$BFa' la tua parte combattendo i Warsong Outriders, $N! Per l'Alleanza!",
  obj = "Porta 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie dal fronte, $N?",
  reward = "Ben fatto, $N! Hai servito bene l'Alleanza.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8373] = {
  title = "Il Potere del Pino",
  desc = "Quello che odio di più della Veglia delle Ombre sono le bombe puzzolenti che i Reietti usano su Southshore. Chi l'avrebbe mai detto che festeggiare la liberazione comportasse un tale pasticcio puzzolente?$B$BDurante la Veglia delle Ombre, usa questo detergente per eliminare le schifose bombe puzzolenti che l'Orda lancia qui nel villaggio. Combatte i cattivi odori con il potere del pino.$B$BFai la tua parte per tenere pulita Southshore, e ti darò qualche dolcetto della Veglia delle Ombre che di sicuro ti piacerà. Affare fatto?",
  obj = "Usa uno Stink Bomb Cleaner per eliminare ogni Forsaken Stink Bomb lanciata su Southshore. Quando hai finito, torna da Sergeant Hartman a Southshore.",
  progress = "Quei maledetti Reietti... è già abbastanza brutto che siano non morti, ma poi si scatenano e cominciano a creare problemi nel MIO villaggio!",
  reward = "Ah, qui intorno si sente già quasi un odore migliore. Quasi.$B$BGrazie a te, $N, Southshore potrebbe superare anche questa Veglia delle Ombre. Ecco i tuoi dolcetti, e grazie di tutto! Se finisci le caramelle, credo che a Ironforge ci sia una gnoma di nome Katrina Shimmerstar che può vendertene altre; mi pare che ci sia solo durante la Veglia delle Ombre.",
  en_title = "The Power of Pine",
  en_obj = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.",
}
T[8374] = {
  title = "Rivendicare Arathi Basin",
  desc = "Vincere una guerra non vuol dire solo superare l'avversario in astuzia e in combattimento. Spesso la vittoria si riduce semplicemente a produrre più del nemico.$B$BQuello che abbiamo in Arathi Basin è una notevole riserva di risorse per la parte che riuscirà a impadronirsene per prima.$B$BSe sarà l'Alleanza a vincere, vorrà dire più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e quelle picche verrebbero fabbricate lo stesso, solo che sarebbero puntate contro di noi! È il momento di aiutare l'Alleanza in Arathi Basin, $N.",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Dimmi, che notizie ci sono dal fronte?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8375] = {
  title = "Ricordate l'Alterac Valley!",
  desc = "Sia ben chiaro, $N. L'Orda ha perfettamente ragione quando dice che l'Alterac Valley è Territorio dei Frostwolf.$B$BVedi, la Stormpike Expedition era arrivata nella zona in visita pacifica, in cerca di minerali e reliquie. I Frostwolf hanno reagito con l'aggressione più brutale e incivile che l'Alleanza abbia mai subito.$B$BNon dimentichiamo mai i nani coraggiosi caduti in quel vile attacco sferrato senza preavviso. Ora va', $C, fai la tua parte nella battaglia per l'Alterac Valley. Per l'Alleanza!",
  obj = "Porta 3 Alterac Valley Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Che notizie porti, $N?",
  reward = "Hai fatto la tua parte, $N. L'Alleanza non può lasciare senza risposta gli atti incivili dell'Orda!",
}
T[8376] = {
  title = "Armamenti di Guerra",
  reward = "La guerra arriva, $N, e con lei arrivano orrori indicibili. Hai fatto tutto ciò che ti si poteva chiedere, e per questo è giusto che tu riceva una ricompensa.$B$BSe questa... questa profezia dovesse mai avverarsi...$B$B<La Geologa Larksbane impallidisce.>$B$BPer tutti noi potrebbe non esserci più alcun futuro.$B$BQuesti armamenti si riveleranno preziosissimi per la tua campagna in questo deserto.",
}
