T[8383] = {
  title = "Ricordate l'Alterac Valley!",
  progress = "La Battaglia nell'Alterac Valley infuria ancora, $N! Hai fatto la tua parte negli ultimi tempi, $N?",
  reward = "Continui a fare onore all'Alleanza, $N. Se manteniamo questo impegno, presto l'Orda sarà schiacciata.",
}
T[8384] = {
  title = "Rivendicare Arathi Basin",
  progress = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8385] = {
  title = "Sforzi Congiunti",
  progress = "Ah, $N. Spero che tu continui a mettere la tua esperienza al servizio dei vari fronti. Tanti dei nostri ragazzi e delle nostre ragazze sul campo prendono a modello i veterani navigati come te.",
  reward = "Sei all'altezza della tua fama, $N. Senza gente come te, l'Alleanza non avrebbe speranze contro le forze selvagge dell'Orda.",
}
T[8386] = {
  title = "Combatti per Warsong Gulch",
  progress = "Non dimenticare che la lotta per Warsong Gulch non riguarda solo la difesa degli alberi. Si tratta di mantenere una barriera naturale tra Ashenvale e le Barrens. Porti notizie dal campo di battaglia, $N?",
  reward = "Ben fatto, $N! Hai servito bene l'Alleanza.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8387] = {
  title = "Invasori dell'Alterac Valley",
  progress = "La battaglia per Alterac infuria ancora! Devi tornare nell'Alterac Valley e cacciare ancora una volta gli invasori dal territorio dei Frostwolf, $N!",
  reward = "Ottimo lavoro, $N! Puoi andare $Gfiero:fiera; di te. Gli invasori dell'Alleanza vanno cacciati da Alterac!",
}
T[8388] = {
  title = "Per un Grande Onore",
  progress = "Molti combattenti valorosi ti ammirano, $N. Continui a essere un esempio per tutti nella lotta contro l'Alleanza. Che notizie porti dai tuoi viaggi?",
  reward = "Continui a rendere onore all'Orda, $N. Sono contento di vedere che non ti sei $Grammollito:rammollita;.",
}
T[8389] = {
  title = "La Battaglia di Warsong Gulch",
  progress = "La battaglia in Warsong Gulch continua a infuriare, $N. Fa' la tua parte per cacciare le Silverwing Sentinels dalle nostre terre!",
  reward = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Possa la fama del tuo onore diffondersi in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8390] = {
  title = "Conquistare Arathi Basin",
  progress = "La guerra contro la feccia dell'Alleanza richiede risorse, $N! Non possiamo permettere che le nostre scorte si esauriscano nel bel mezzo di una battaglia. Continua a fare in modo che Arathi Basin resti nelle nostre mani!",
  reward = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8391] = {
  title = "Rivendicare Arathi Basin",
  progress = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8392] = {
  title = "Rivendicare Arathi Basin",
  progress = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?",
  reward = "Ottimo lavoro, $C! Il tuo impegno aiuterà l'Alleanza ad avere le risorse di cui ha bisogno.",
}
T[8393] = {
  title = "Rivendicare Arathi Basin",
  desc = "Vincere una guerra non vuol dire solo superare l'avversario in astuzia e in combattimento. Spesso la vittoria si riduce semplicemente a produrre più del nemico.$B$BIn Arathi Basin c'è una notevole riserva di risorse, e andrà alla parte che riuscirà a impadronirsene per prima.$B$BSe sarà l'Alleanza a vincere, vorrà dire più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e quelle picche verrebbero fabbricate lo stesso, solo che sarebbero puntate contro di noi! È il momento di aiutare l'Alleanza in Arathi Basin, $N.",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Dimmi, che notizie ci sono dal fronte?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
