T[8409] = {
  title = "Barili Rovinati",
  desc = "Le uova marce sono state messe nel barile. Le prossime partite di birra della Locanda di Southshore saranno di sicuro rovinate!$B$BOra dovresti tornare da Darkcaller Yanka, al Wickerman Festival nella Tirisfal Glade, per riferire il tuo successo.",
  obj = "Torna da Darkcaller Yanka, al Wickerman Festival nella Tirisfal Glade.",
  reward = "Ah, ce l'hai fatta! Hai mostrato il vero spirito della Veglia delle Ombre — lo spirito dei REIETTI, dovrei dire!$B$B<Darkcaller Yanka ride e si sfrega le mani.>$B$BMi rallegra sapere che Southshore ora dovrà festeggiare con birra cattiva o farne a meno! Quanto a te, prendi questi dolcetti. Credo che ne farai buon uso!",
  en_title = "Ruined Kegs",
  en_obj = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
T[8410] = {
  title = "Padronanza degli Elementi",
  desc = "Bath'rah the Windwatcher ha mandato a chiamare $Guno sciamano:una sciamana; della tua saggezza. Chiede che tu gli porti un campione di ciascun elemento per dimostrare che sei $Gpronto:pronta;.$B$BPer trovare Bath'rah, vai al fiume a est di Tarren Mill. Segui il fiume verso nord finché non arrivi alle rovine dove risiede Bath'rah.",
  obj = "Raccogli un campione di aria, fuoco, terra e acqua per Bath'rah the Windwatcher.",
  progress = "Che c'hai per me, $C?",
  reward = "Ottimo, mon. Adesso sì che si ragiona.",
}
T[8411] = {
  title = "Padroneggiare gli Elementi",
  desc = "$GBenvenuto:Benvenuta;, mon. Tu mi porti gli elementi e poi si parla.",
  obj = "Porta gli elementi terra, aria, fuoco e acqua a Bath'rah the Windwatcher.",
  progress = "Dove stanno gli elementi, mon?",
  reward = "Eccoli, gli elementi che mi servono. Adesso si parla.",
}
T[8412] = {
  title = "Totem dello Spirito",
  desc = "Agli spiriti elementali di questo posto io non gli vado più a genio.$B$BTu di totem ne sai più di chiunque, e a me serve un totem dello spirito che mi protegga. Gli elementi ce li abbiamo già, adesso ci serve qualcosa in più, con più natura dentro. Più primordiale.$B$BNelle Western Plaguelands puoi ammazzare gli orsi per gli artigli e i ragni per gli occhi. Gli uccelli mangiacarogne mangiano di tutto, quindi magari hanno gli uni o gli altri.",
  obj = "Porta i pezzi per il totem dello spirito a Bath'rah the Windwatcher.",
  progress = "Gli spiriti lo sanno cosa stiamo combinando, e stanno cercando di farmi fuori! Spero che i pezzi ce li hai.",
  reward = "Grande, mon! Proviamolo....",
}
T[8413] = {
  title = "Il Vudù",
  desc = "Il totem dello spirito da solo non basta. Ci serve un po' di magia vudù per farlo funzionare proprio come si deve.$B$BI troll del tempio sommerso hanno piume cariche di magie vudù. Vai là e ammazza Gasher, Mijan, Zolo, Hukku, Zul'Lor e Loro. Così avremo magia a sufficienza per un vero totem dello spirito.",
  obj = "Porta le piume vudù a Bath'rah the Windwatcher.",
  progress = "Dove stanno le piume, mon?",
  reward = "Era ora che questo troll si facesse una notte intera di sonno! Il totem dello spirito veglierà su di me.$B$BÈ da tanto che metto da parte roba, magari vuoi qualcosa per tutto il disturbo?",
}
T[8414] = {
  title = "Scacciare il Male",
  desc = "Salute, $C. È bello vedere crociati come te in queste lande desolate.$B$BC'è bisogno della tua forza sacra per combattere i non morti, che qui non finiscono mai. Devi raccogliere un gran numero di pietre del flagello e portarle al Sommo Sacerdote Thel'danis. Il sommo sacerdote monta la guardia al Sepolcro di Uther, sulla Collina del Cordoglio, non lontano da qui.$B$BSolo chi ha un Distintivo dell'Argent Dawn può sperare di trovare le pietre del flagello, quindi parla con l'Ufficiale Pureheart, se non l'hai già fatto.",
  obj = "Raccogli 20 Minion's Scourgestones e portale a High Priest Thel'danis, nelle Western Plaguelands.",
  progress = "Quale male mi hai portato?",
  reward = "Scacciare il male da una pietra del flagello è rischioso, perché attira l'attenzione dei non morti per miglia e miglia. Ma tu sei forte nella Luce, $N, e non temo per te...",
}
T[8415] = {
  title = "Chillwind Point",
  desc = "Il Comandante Ashlam Valorfist ha lanciato un appello per un paladino della tua purezza e del tuo valore, $N. Lo trovi a Chillwind Point, nella parte meridionale delle Western Plaguelands. Cercalo e aiutalo nella sua causa per la Luce!",
  obj = "Parla con Commander Ashlam Valorfist, a Chillwind Point.",
  reward = "Molto bene, $C! Vediamo di che pasta sei $Gfatto:fatta;.",
}
T[8416] = {
  title = "Pietre del Flagello Inerti",
  desc = "Il male è stato estirpato dalle pietre, $N.$B$BConosco i piani del Comandante Ashlam, e gli servirà una sola pietra inerte. Portagliela, così potremo immergere il Flagello nel fuoco della giustizia.",
  obj = "Porta l'Inert Scourgestone a Commander Ashlam Valorfist, a Chillwind Point.",
  progress = "Thel'danis è riuscito a purificare le pietre del flagello?",
  reward = "Hai fatto quello che ti ho chiesto senza fare domande, $N.$B$BA quanto pare la fiducia è conquistata. Forse ora posso rivelarti il nostro piano più nel dettaglio.",
}
T[8417] = {
  title = "Uno Spirito Tormentato",
  desc = "Nelle Blasted Lands c'è uno spirito tormentato che un tempo è stato un grande eroe dell'orda. L'onore di un guerriero non muore con il corpo, e faresti bene a parlare con lui.",
  obj = "Parla con il Fallen Hero of the Horde all'ingresso delle Blasted Lands.",
  progress = "Stoley ha sganciato il mio liquore?",
  reward = "Dunque sei $Gvenuto:venuta; ad alleviare il mio dolore. Vorrei che bastasse abbattermi, ma non è così semplice...",
}
T[8418] = {
  title = "Forgiare la Pietragrossa",
  desc = "Ora dobbiamo unire le pietre del flagello inerti e creare un'arma che spezzi le file dei non morti. Non è un compito da poco, $N. Solo i troll del tempio sommerso possiedono quel genere di magia rara capace di rivolgere il male di una cosa contro sé stesso.$B$BNel tempio, i troll sono noti come Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Non provare rimorso per le loro anime corrotte... non sono privi di malvagità.",
  obj = "Porta le piume vudù a Commander Ashlam Valorfist.",
  progress = "Hai ucciso quei miserabili troll?",
  reward = "Eccellente, $N. Direi che sono sorpreso, ma sapevo senza ombra di dubbio che non ci avresti delusi.$B$BÈ un onore per me conferirti una delle Pietregrosse Sacre. Usala bene.",
}
T[8419] = {
  title = "La Richiesta di un Imp",
  desc = "$N, un imp di Felwood che si chiama Impsy ha chiesto di vederti. È un po' strano, perché vuole che tu gli porti un pezzo di felcloth come prova di buona fede. Visto il potere che già possiedi come $Gstregone:strega;, immagino tu sappia che questo felcloth ce l'hanno i satiri di Felwood.$B$BTroverai Impsy appena a nord delle Cascate Sanguemarcio, che a quanto ho sentito sono incantevoli in questo periodo dell'anno.",
  obj = "Porta un pezzo di Felcloth a Impsy a Felwood.",
  progress = "Hai il mio felcloth?",
  reward = "Che $Gsplendido:splendida; $C sei!$B$B<Impsy si porta il felcloth al viso.>$B$BOh, quanto mi piace toccarlo, sentire come brucia la pelle e intesse pensieri malvagi nella mente...",
}
T[8420] = {
  title = "Brucia e Prude",
  desc = "Detto da un imp forse suona strano, ma vorrei un famiglio tutto mio. Lo vorrei davvero. Non è giusto che Niby abbia me e io niente!$B$BAnzi, non serve nemmeno che sia un famiglio vivo. Mi servirebbe qualcosa con cui cominciare a fabbricarlo, tipo un po' di felcloth. I satiri qui a Felwood a volte ne hanno, quindi ti basterebbe ucciderne abbastanza da trovarne un po'. Non sembra poi così male, vero?",
  obj = "Porta un pezzo di Felcloth a Impsy a Felwood.",
  progress = "Hai il mio felcloth?",
  reward = "Uau! Sei troppo gentile. Soprattutto per $Guno stregone:una strega;!$B$B<Impsy si porta il felcloth al viso.>$B$BOh, quanto mi piace toccarlo, sentire come brucia la pelle e intesse pensieri malvagi nella mente...",
}
T[8421] = {
  title = "La Stoffa Sbagliata",
  desc = "Ora che ho il mio felcloth, posso cominciare davvero a fabbricare il *mio* famiglio.$B$BGli serviranno degli occhi, però. Magari potresti strappare per me un po' di legno marcio alle creature irontree, così ci intaglio dei begli occhi. Stanno su a nord, nel Bosco di Irontree.$B$BMi servirà anche un po' di essenza di bloodvenom, per dargli quell'odore di demone nuovo. L'essenza ce l'hanno le melme corrotte, che bazzicano proprio qui, vicino a Niby e a me.",
  obj = "Porta 10 Rotting Wood e 4 Bloodvenom Essence a Impsy a Felwood.",
  progress = "Hai la roba?",
  reward = "Andrà proprio a meraviglia.",
}
T[8422] = {
  title = "Troll della Stessa Piuma",
  desc = "Il mio famiglio è quasi finito. Ora mi serve solo qualcosa con cui imbottirlo.$B$BVanno bene solo le piume vudù dei troll del tempio sommerso. Si chiamano Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Uccidili. Uccidili tutti.$B$BNon è un compito da poco, $N, quindi ti ripagherò come si deve dandoti qualcosa di Niby — tanto, probabilmente, a lui non serve.",
  obj = "Porta in tutto 6 Voodoo Feathers prese ai troll del tempio sommerso.",
  progress = "Hai portato le piume? Questa bambola va imbottita!",
  reward = "Magnifico, ora il mio famiglio è completo!$B$B<Impsy imbottisce in fretta la bambola e le dà un abbraccio demoniaco.>$B$BOh, che strano effetto collaterale hanno queste piume vudù...",
}
T[8423] = {
  title = "Fratellanza tra Guerrieri",
  desc = "<L'Eroe ti squadra.>$B$BSei $Gun:una; $C, non c'è dubbio. Vorrei affidarti un compito onorevole, ma devo mettere alla prova la tua forza.$B$BSi dice che Rexxar misurasse il filo delle sue lame uccidendo un cinghiale infernale con un solo colpo fulmineo. Ora io misurerò la tua forza facendoti uccidere quei cinghiali.",
  obj = "Uccidi 7 Helboar nelle Blasted Lands e torna dal Fallen Hero of the Horde.",
  progress = "Gli aculei ardenti dei cinghiali infernali lasciano cicatrici orribili. Non temere il dolore e le deturpazioni, $Gguerriero:guerriera;, non sono nulla in confronto alla prigione a cui sono legato.",
  reward = "Non mi servono prove per sapere cosa hai fatto, $C. Vedo la determinazione scolpita sul tuo viso.",
}
T[8424] = {
  title = "Guerra agli Shadowsworn",
  desc = "La presenza costante degli shadowsworn nelle Blasted Lands mi provoca un grande dolore. I loro rituali oscuri e i loro incantesimi mi causano un tormento che da vivo non ho mai provato.$B$BAttraverso di te posso portare il mio messaggio di dolore. Va' e porta la mia ira.",
  obj = "Massacra gli Shadowsworn nelle Blasted Lands e torna dal Fallen Hero of the Horde.",
  progress = "Gli shadowsworn non si sconfiggono facilmente, vero? Ma tu sei $Gun guerriero:una guerriera;, e trionferai o morirai provandoci.",
  reward = "Hai già placato il mio dolore e mi hai reso onore. Grazie, $C.",
}
T[8425] = {
  title = "Piume Vudù",
  desc = "Il tuo onore mi ha portato un po' di pace. È giusto che ti offra qualcosa in cambio.$B$BIn vita le mie armi e la mia armatura erano splendide, eppure ora non mi servono a nulla. Starebbero meglio nelle tue mani.$B$BRaggiungi il tempio sommerso e distruggi i guardiani troll Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Portano con sé piume magiche che possono ricomporre il mio corpo fisico quel tanto che basta per darti una ricompensa.",
  obj = "Porta le Voodoo Feathers dei troll del Sunken Temple al Fallen Hero of the Horde.",
  progress = "Sei già di ritorno? Per me il tempo non è più lo stesso, forse per te è stato davvero un lungo viaggio...",
  reward = "Finalmente posso sentire di nuovo il freddo tocco dell'acciaio, anche se solo per un momento.",
}
T[8426] = {
  title = "La Battaglia di Warsong Gulch",
  desc = "La battaglia in Warsong Gulch contro le Silverwing Sentinels è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito degnamente l'Orda!",
  obj = "Porta 3 Warsong Gulch Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "La battaglia in Warsong Gulch contro le Silverwing Sentinels è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito degnamente l'Orda!",
  reward = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che del tuo onore si parli in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
