T[8436] = {
  title = "Conquistare Arathi Basin",
  desc = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. Ormai nessuna delle due parti ricorre più a falsi pretesti per scendere in battaglia, né se li aspetta.$B$BLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per mandare avanti la guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie da Arathi, $C?",
  reward = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
