T[8446] = {
  title = "Avvolto nell'Incubo",
  desc = "Da questo oggetto trasuda corruzione.$B$BPotrebbe esserci un legame tra questo oggetto e i draghi che escono dal Sogno. Devi trovare qualcuno in grado di decifrarne il significato. Forse i druidi di Moonglade o di Cenarion Hold potrebbero aiutarti a proseguire.",
  obj = "Trova qualcuno capace di decifrare il significato che si cela dietro il Nightmare Engulfed Object.$B$BForse un druido di grande potere potrebbe aiutarti.",
  progress = "Sì, $R?",
  reward = "Devo rimuovere la corruzione da questo oggetto. Potrebbe fare un po' di luce sui miei recenti tentativi falliti di addentrarmi nel Sogno. Dammelo.",
}
T[8447] = {
  title = "Leggende che si Risvegliano",
  desc = "Le acque del Lago Elune'ara dovrebbero dissolvere gli incubi che avviluppano questo oggetto. Dammi un momento per compiere la purificazione, $N.",
  obj = "Aspetta che Keeper Remulos, a Moonglade, purifichi il Nightmare Engulfed Object.",
  reward = "Prendi il suo anello, $N. Per Malfurion ha assolto il suo compito. Ora ne assolverà uno nuovo per te...",
}
T[8460] = {
  title = "Alleato dei Timbermaw",
  desc = "I Timbermaw sono l'unica tribù di mezzorsi sfuggita alla corruzione. Eppure ormai molte altre razze uccidono i mezzorsi alla cieca, senza darsi la pena di capire se sono amici o nemici. Per questo i mezzorsi Timbermaw si fidano di pochissimi.$B$BTi interessa dimostrare quanto vali? Respingi la tribù corrotta dei Deadwood di Felwood e un giorno potremmo considerarti $Gun alleato:un'alleata;. La prima tribù Deadwood — guerrieri, ricognitori e giardinieri — la trovi a ovest di qui.",
  obj = "Grazle vuole che tu dimostri quanto vali uccidendo 6 Deadwood Warriors, 6 Deadwood Pathfinders e 6 Deadwood Gardeners. Quando hai finito, torna da lui nel sud di Felwood, vicino a Emerald Sanctuary.",
  progress = "Continua così, $N. Se vuoi guadagnarti la nostra fiducia, dovrai dimostrarci quanto vali.",
  reward = "Soffriamo molto per gli eventi del passato. Grazie di quello che hai fatto per aiutare a proteggere i Timbermaw. In segno della nostra crescente amicizia, ti prego di accettare questa umile offerta.",
}
T[8461] = {
  title = "I Deadwood del Nord",
  desc = "Subito a sud-ovest di qui c'è un accampamento di mezzorsi Deadwood. La corruzione lo pervade, e voglio porvi fine prima che diventino un problema.$B$BLa tribù Deadwood è malvagia, ma sono gli effetti della vilenergia a contaminare le loro menti. La loro ostilità non è davvero innata, eppure per loro non si può fare niente. Mi rattrista dover combattere contro i nostri stessi fratelli.$B$BTi prego, $N — ti chiedo di fare ciò che va fatto. Risparmiami solo i particolari; immagini così penose mi turbano fin troppo.",
  obj = "Nafien vorrebbe che uccidessi 6 Deadwood Den Watchers, 6 Deadwood Avengers e 6 Deadwood Shamans. Torna da lui nella parte settentrionale di Felwood, vicino all'ingresso di Timbermaw Hold.",
  progress = "Quando avrai conquistato la fiducia dei Timbermaw, sono certo che potremo fare qualcosa per te. I Timbermaw non dimenticano i loro alleati, soprattutto in tempi bui come questi.",
  reward = "Sento che hai ottenuto la vittoria. Vittoria... una parola così vuota, se si pensa a ciò che è stato necessario fare. In ogni caso, hai dimostrato di essere $Gdegno:degna; della nostra fiducia.$B$BPotrebbe volerci del tempo prima che i Timbermaw ti accolgano senza ostilità all'interno dell'Hold. Tuttavia, la tua perseveranza eroderà ogni sospetto che i miei fratelli possano nutrire su di te. Finché non ci tradirai e non alzerai le armi contro di noi, troveremo un punto d'incontro.",
}
T[8462] = {
  title = "Parla con Nafien",
  desc = "Forse sei in grado di affrontare una minaccia più grande che incombe su noi Timbermaw. Qui di certo hai dimostrato di cosa sei capace...$B$BUn altro della mia specie fa la guardia fuori dall'ingresso di Timbermaw Hold, lungo questa strada, molto più a nord. Si chiama Nafien; anche se può sembrare una bestia feroce e poco raccomandabile, non temerlo. Cerca soltanto aiuto contro le forze maligne che minacciano la nostra casa.",
  obj = "Segui verso nord la strada principale di Felwood e parla con il mezzorso di nome Nafien. Fa la guardia fuori dall'ingresso di Timbermaw Hold.",
  reward = "Ah... il vento mi ha portato voci su chi, pur non essendo della nostra tribù, cerca di allearsi con i mezzorsi Timbermaw. Ti do il benvenuto, ma devi sapere che la mia tribù reagisce male agli estranei.$B$BSono tempi difficili, e possiamo fidarci solo di chi sceglie di combattere al nostro fianco la corruzione della terra... e ce ne ha dato prova. Chi non l'ha fatto, se entra nell'Hold, sarà accolto con aperta ostilità.",
}
T[8464] = {
  title = "Attività dei Winterfall",
  desc = "I Timbermaw tendono a starsene per conto loro, $N. Anche se concediamo un passaggio sicuro a chi gode della nostra fiducia, cerchiamo di evitare le altre tribù di mezzorsi, per quanto possibile.$B$BNegli ultimi tempi la tribù Winterfall è diventata sempre più ostile nei nostri confronti. Sembrano in preda alla rabbia, del tutto sopraffatti dalla paura e dall'odio per tutto ciò che non capiscono.$B$BDevo chiederti di sfoltire le loro file, così da ridurre la minaccia che incombe su di noi. Cercali al Villaggio dei Winterfall, molto più a est di qui.",
  obj = "Salfa vuole che tu uccida 8 Winterfall Shaman, 8 Winterfall Den Watchers e 8 Winterfall Ursa. Salfa si trova appena fuori dall'ingresso di Timbermaw Hold, a Winterspring.",
  progress = "Ti siamo molto grati per quello che hai fatto per i Timbermaw, $N. Se continuerai a impegnarti così, ti guadagnerai di certo la fiducia e il rispetto della mia tribù.",
  reward = "Grazie per quello che hai fatto, per quanto sia triste. Accetta questo in segno di gratitudine.$B$BTi chiedo, per favore, di continuare ad aiutarci, $N. Abbiamo pochissimi alleati a cui rivolgerci, e senza il tuo aiuto le minacce contro la mia tribù sarebbero di certo troppe perché possiamo affrontarle da soli.",
}
T[8465] = {
  title = "Parla con Salfa",
  desc = "La minaccia della corruzione non viene soltanto dai mezzorsi Deadwood a sud, ma anche da est, dai mezzorsi Winterfall di Winterspring. Se vuoi aiutarci ancora, parla con Salfa dall'altra parte dell'Hold, all'ingresso di Winterspring. Per arrivarci segui il sentiero a sinistra.$B$BTi avverto — se i miei simili là dentro ti considerano ostile o $Godiato:odiata;, ti attaccheranno. Attraversa più in fretta che puoi, evitando gli scontri. Uccidere un Timbermaw — anche per legittima difesa — non farà che renderteli ancora più ostili.",
  obj = "Attraversa Timbermaw Hold ed esci a Winterspring. Parla con Salfa, che fa la guardia fuori dall'ingresso di Timbermaw Hold.",
  reward = "Salute, $C — sono qui di guardia sia come portavoce dei Timbermaw a Winterspring, sia come $Gdifensore:difenditrice; della tribù.$B$BI nostri fratelli Winterfall, in questa terra gelida, sono caduti sotto lo stesso influsso corruttore dei mezzorsi di Felwood. Se sei $Gvenuto:venuta; a offrire aiuto ai mezzorsi Timbermaw, siamo pronti ad accettarlo.",
}
T[8466] = {
  title = "Piume per Grazle",
  progress = "A me hai già dimostrato quanto vali, ma può darsi che tu debba darti ancora da fare per dimostrarlo ai diffidenti fratelli della mia tribù. In questo, forse posso continuare ad aiutarti.$B$BAlcuni mezzorsi Deadwood portano un copricapo inconfondibile, che può servire da prova che ne hai sfoltito le file. Portami una piuma da ogni copricapo che riesci a procurarti; per ogni gruppo di cinque che mi porti, ti guadagnerai considerazione fra i Timbermaw.",
  reward = "Ben fatto, $N! Farò in modo che i miei simili vengano a sapere delle tue imprese.$B$BRicordati di portarmi tutte le piume che trovi. Continuerò ad accettarle finché sarà necessario.",
}
T[8467] = {
  title = "Piume per Nafien",
  progress = "A me hai già dimostrato quanto vali, ma può darsi che tu debba darti ancora da fare per dimostrarlo ai diffidenti fratelli della mia tribù. In questo, forse posso continuare ad aiutarti.$B$BAlcuni mezzorsi Deadwood portano un copricapo inconfondibile, che può servire da prova che ne hai sfoltito le file. Portami una piuma da ogni copricapo che riesci a procurarti; per ogni gruppo di cinque che mi porti, ti guadagnerai considerazione fra i Timbermaw.",
  reward = "Ben fatto, $N! Farò in modo che i miei simili vengano a sapere delle tue imprese.$B$BRicordati di portarmi tutte le piume che trovi. Continuerò ad accettarle finché sarà necessario.",
}
T[8469] = {
  title = "Perle per Salfa",
  progress = "La mia fiducia te la sei senz'altro guadagnata, $N, ma può darsi che tu debba continuare a guadagnarti quella della mia diffidente tribù. C'è qualcosa che puoi fare per conquistarla.$B$BSi sa che i Winterfall portano con sé perle degli spiriti per tenere lontani gli spiriti immondi. È evidente che queste perle hanno mancato il loro scopo, visto che sono proprio i Winterfall gli agenti della corruzione. Portami le perle degli spiriti dei mezzorsi Winterfall caduti; per ogni gruppo di cinque che mi porti, ti guadagnerai considerazione fra i Timbermaw.",
  reward = "Ancora una volta ci dai prova del tuo onore! Farò in modo che i miei simili vengano a sapere delle tue imprese.$B$BRicordati di portarmi tutte le perle dei Winterfall che trovi. Per ogni gruppo che continuerai a portarmi, parlerò in tuo favore alla tribù.",
}
T[8470] = {
  title = "Totem Rituale dei Deadwood",
  desc = "Hai trovato uno dei totem rituali dei mezzorsi Deadwood. Il totem in sé è di fattura anonima, ma ne emana un palpabile senso di disperazione. Se esistesse un oggetto capace di rappresentare meglio di ogni altro la corruzione che affligge i mezzorsi Deadwood, sarebbe senz'altro questo.$B$BA uno dei mezzorsi dentro Timbermaw Hold un oggetto del genere potrebbe servire... sempre che tu abbia guadagnato la loro fiducia quanto basta perché ti rivolgano la parola.",
  obj = "Porta il Deadwood Ritual Totem dentro Timbermaw Hold e vedi se a uno dei mezzorsi di lì può servire. I Timbermaw non ti parleranno se la tua reputazione con loro non è almeno Neutral.",
  progress = "Sì, $C, in cosa posso aiutarti? Cammini fra noi in pace, eppure c'è di sicuro qualcosa che non va. Avverto qualcosa... qualcosa di inquietante...",
  reward = "Questo totem... lo riconosco, è uno di quelli dei Deadwood, ma è impregnato del lezzo della putrefazione. Qualunque sia l'immondo male che ha rivoltato i nostri fratelli contro di noi, è di sicuro presente in questo oggetto.$B$BSei $Gstato saggio:stata saggia; a portarcelo, $N. Forse, con lo studio e i rituali, riusciremo a scoprire cos'è che inquina la mente dei nostri fratelli. Grazie, $Gamico:amica; — ti prego, accetta questi doni in cambio di ciò che hai trovato.",
}
T[8471] = {
  title = "Totem Rituale dei Winterfall",
  desc = "Hai trovato uno dei totem rituali dei mezzorsi Winterfall. Il totem in sé è di fattura anonima, ma sembra emanare un senso quasi tangibile di terrore e disperazione. Se davvero molti mezzorsi Winterfall ne portano uno con sé, questo spiegherebbe in buona parte la loro condizione attuale.$B$BUno dei mezzorsi dentro Timbermaw Hold potrebbe sapere cosa farsene di un oggetto simile... sempre che tu abbia conquistato la loro fiducia quanto basta perché ti rivolgano la parola.",
  obj = "Porta il Winterfall Ritual Totem dentro Timbermaw Hold e vedi se uno dei mezzorsi del posto sa cosa farsene. I Timbermaw non ti rivolgeranno la parola se la tua reputazione con loro non è almeno Neutral.",
  progress = "$C — ti avvicini a noi in pace, ma sento che sei qui per questioni gravi e serie... tanto per il mezzorso quanto per $Gil:la; $R. Cosa sei $Gvenuto:venuta; a dirci?",
  reward = "Questa cosa... ha la forma di un Totem Rituale dei Winterfall, ma è stata stravolta da forze che non riesco neppure a comprendere. Qualunque sia la corruzione che ha messo i Winterfall contro di noi, in questo oggetto è sicuramente presente.$B$BÈ stata la saggezza divina a portare da noi sia questo oggetto sia te, $N. Lo studieremo con attenzione; forse un giorno i Winterfall smetteranno di infuriare contro di noi.$B$BGrazie, $Gamico:amica; — ti prego, accetta queste offerte in cambio della tua benevolenza.",
}
T[8481] = {
  title = "La Radice di Ogni Male",
  desc = "$N, grazie a te abbiamo escogitato un modo per evocare la radice di ogni male della tribù Winterfall — il demone corruttore che la domina!$B$BPorta questa torcia all'imboccatura della caverna personale del Gran Capo Winterfall e piantala lì. Così il demone sarà costretto a mostrarsi per venire a vedere cosa succede. È allora che tu e i tuoi alleati dovrete abbatterlo! Solo l'essenza del demone caduto darà inizio al lungo processo di guarigione della tribù Winterfall... e alla salvezza di Timbermaw Hold.",
  obj = "Pianta la Demon Summoning Torch all'imboccatura della caverna di High Chief Winterfall, nel villaggio dei mezzorsi Winterfall. Sconfiggi il demone e recupera l'Essence of Xandivious per Gorn One Eye a Timbermaw Hold.",
  progress = "Sei $Gtornato:tornata; da noi, $N... vuol dire che il demone è stato ucciso?",
  reward = "Ci... ci hai salvati! Sconfiggendo il demone Xandivious hai garantito la sicurezza di Timbermaw Hold per gli anni a venire. Per la nostra gente sei $Gun vero eroe:una vera eroina;.$B$BTi prego, accetta questo con la nostra benedizione. Anche se fra i mezzorsi la guarigione sarà lenta — e il conflitto continuerà — hai dato ai Winterfall qualcosa che fino a oggi non avevano mai avuto.$B$BHanno una possibilità di sopravvivere.",
}
T[8484] = {
  title = "Il Negoziato di Pace",
  desc = "Le tue imprese vanno oltre la storia di un semplice eroe, $N. Se tu rappresenti il tuo popolo, allora il tuo è un popolo con cui siamo pronti a lavorare per la pace.$B$BTi prego — porta questa offerta al re dei nani che dimora in una montagna di ferro; credo che voi chiamiate questa città Ironforge. In passato aveva cercato di mettersi in contatto con noi a nome della sua Alleanza. Ora è più che giusto riconoscere in te la chiave degli sforzi della tua Alleanza per negoziare la pace.",
  obj = "Porta la Timbermaw Offering of Peace a King Magni Bronzebeard, a Ironforge.",
  progress = "$C, sei $Gil benvenuto:la benvenuta; nei miei domini. $GUn eroe:Un'eroina; come te dovrebbe sempre considerare Ironforge casa sua. Allora, che cosa ti porta da me?",
  reward = "Questa è davvero una svolta quanto mai fortunata. Se si arrivasse a una pace duratura con queste creature, avremmo di certo un vantaggio nelle faccende di Kalimdor... un vantaggio che gli Elfi della Notte non possono mantenere da soli. Informerò subito gli altri capi dell'Alleanza, e verranno inviati altri diplomatici!$B$BQuanto a te, $N... hai dimostrato coraggio tanto nella diplomazia quanto nell'azione. Ti ringrazio, e con me tutta l'Alleanza.",
}
T[8485] = {
  title = "Il Negoziato di Pace",
  desc = "Le tue imprese vanno oltre la storia di un semplice eroe, $N. Se tu rappresenti il tuo popolo, allora il tuo è un popolo con cui siamo pronti a lavorare per la pace.$B$BTi prego — porta questa offerta al capoguerra degli orchi che dimora nelle terre di Durotar; credo che voi chiamiate questa città Orgrimmar. In passato aveva cercato di mettersi in contatto con noi a nome della sua Orda. Ora è più che giusto riconoscere in te la chiave degli sforzi della tua Orda per negoziare la pace.",
  obj = "Porta la Timbermaw Offering of Peace a Thrall, a Orgrimmar.",
  progress = "Il capoguerra ti porge i suoi saluti, $C. Le tue imprese rendono l'Orda più forte in questi tempi travagliati. Allora, che cosa ti porta da me?",
  reward = "Questa è davvero una svolta quanto mai fortunata. Se si arrivasse a una pace duratura con queste creature, avremmo di certo un vantaggio nel proteggere Kalimdor dalle minacce esterne. Informerò subito gli altri capi dell'Orda, e verranno inviati altri diplomatici!$B$BQuanto a te, $N... hai dimostrato coraggio tanto nella diplomazia quanto nell'azione. Ti ringrazio, e con me l'Orda intera.",
}
T[8492] = {
  title = "L'Alleanza Ha Bisogno di Barre di Rame!",
  desc = "Ehi, $C, mi sembri abbastanza in forma per contribuire allo sforzo bellico! Qui ci serve tutto l'aiuto possibile per mettere insieme il materiale bellico per la guerra di Ahn'Qiraj, ed è il tuo giorno fortunato.$B$BRaccolgo barre di rame in pile da venti. È per una buona causa, che ne dici? Pensi di poter dare una mano all'Alleanza?",
  obj = "Porta 20 Copper Bar a Sergeant Stonebrow, in Military Ward di Ironforge.",
  progress = "Hai già raccolto quelle venti barre di rame, $Gsoldato:soldatessa;?",
  reward = "Ce l'hai fatta, $Gragazzo:ragazza;! Metteremo subito quelle barre di rame sul mucchio e le useremo per fare il materiale bellico. Sono gli sforzi di gente come te che mi rendono orgoglioso di servire l'Alleanza. Bel lavoro, $Gsoldato:soldatessa;!$B$BE se ti capita di trovare altre barre di rame, fa' in modo che arrivino a me.",
  en_title = "The Alliance Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.",
}
T[8493] = {
  title = "L'Alleanza Ha Bisogno di Altre Barre di Rame!",
  desc = "Di nuovo qui, $C? Magnifico! Ci servono ancora pile di barre di rame, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?",
  obj = "Porta 20 Copper Bar a Sergeant Stonebrow, all'aerodromo di Dun Morogh.",
  progress = "Di nuovo qui, $C? Magnifico! Le barre che ci hai portato finora saranno davvero utili per fabbricare ogni genere di cose per la guerra. So, per esempio, che il rame servirà per i pezzi dei carri a vapore in costruzione, e per una piccola flotta di girocotteri che contiamo di schierare, se ci sarà tempo.$B$BMa non farti ingannare dalle pile che vedi qui: ci servono ancora barre di rame, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?",
  reward = "Ottimo lavoro! Scavare per trovare quel rame e fonderlo dev'essere stata una bella avventura. A meno che tu non abbia comprato le barre alla casa d'aste. In ogni caso, a me va bene. Meriti un encomio per il tuo contributo allo sforzo bellico, $C. E non esitare a portarmi altre barre di rame, se ne hai.",
  en_title = "The Alliance Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.",
}
T[8494] = {
  title = "L'Alleanza Ha Bisogno di Barre di Ferro!",
  desc = "Ma guarda chi si vede, $Gsignor Elegantone:signorina Elegantona;, che piacere vederti. Nel caso non l'avessi sentito dire mentre eri là fuori a \"fare avventure\", l'Alleanza si sta preparando a una guerra ad Ahn'Qiraj e ha bisogno di barre di ferro... un mucchio enorme. Portamele in pile da venti. Possiamo contare su di te, vero, $C?",
  obj = "Porta 20 Iron Bar a Corporal Carnes, in Military Ward di Ironforge.",
  progress = "Se hai quelle venti barre di ferro, non voglio sapere dove le tieni nascoste!",
  reward = "Bene, bene, guarda chi c'è: $N. E ce l'hai fatta. Immagino che adesso dovrò tenerti d'occhio. Mi costa dirlo, ma grazie per i tuoi sforzi. L'Alleanza non lo dimenticherà, e nemmeno io. Ora torna là fuori e sgobba per raccogliere qualsiasi altra cosa serva.",
  en_title = "The Alliance Needs Iron Bars!",
  en_obj = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.",
}
T[8495] = {
  title = "L'Alleanza Ha Bisogno di Altre Barre di Ferro!",
  desc = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza barre di ferro per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti barre di ferro, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?",
  obj = "Porta 20 Iron Bar a Corporal Carnes, all'aerodromo di Dun Morogh.",
  progress = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza barre di ferro per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti barre di ferro, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?",
  reward = "Dev'essere una giornata fredda nelle Burning Steppes. Guarda un po', c'è $N, ed è $Gvenuto:venuta; a portarmi un regalo. Venti barre di ferro! Proprio quello che ho sempre desiderato.$B$BMa scherzi a parte, grazie, $N. Fai onore a te $Gstesso:stessa; e all'Alleanza. Ora torna là fuori e porta altra roba per lo sforzo bellico!",
  en_title = "The Alliance Needs More Iron Bars!",
  en_obj = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.",
}
T[8496] = {
  title = "Bende per il Campo di Battaglia",
  desc = "Dopo le perdite che abbiamo subito di recente, le nostre scorte di bende sul campo di battaglia si stanno riducendo in modo pericoloso. Procurati una partita di materiale di primo soccorso e consegnala all'Invocatrice del Vento Proudhorn a Cenarion Hold.",
  obj = "Porta 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages e 30 Heavy Mageweave Bandages a Windcaller Proudhorn a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing X.",
}
T[8497] = {
  title = "Kit di Sopravvivenza nel Deserto",
  desc = "Con l'arrivo di nuove reclute a Cenarion Hold nasce il problema di tenerle in vita nel deserto. La disidratazione e le numerose creature velenose sono una seria minaccia per i volontari inesperti. Raccogli il materiale necessario per un kit di sopravvivenza nel deserto e portalo a Calandrath a Cenarion Hold.",
  obj = "Porta 4 Globes of Water, 4 Powerful Anti-Venom e 4 Smoked Desert Dumplings a Calandrath, alla locanda di Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing I.",
}
T[8498] = {
  title = "Ordini di Battaglia del Crepuscolo",
  desc = "I nostri esploratori riferiscono che i capi del Martello del Crepuscolo stanno diramando nuovi ordini di battaglia. A distribuirli sono i Profeti del Crepuscolo, sotto una scorta massiccia. Intercetta gli ordini e portali al Comandante Mar'alith.",
  obj = "Recupera i Twilight Battle Orders e portali a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Tactical Task Briefing X.",
  progress = "Mi hai portato qualcosa?",
  reward = "Eccellente. È importante giocare d'anticipo sulla prossima mossa del nemico. Queste informazioni ci permetteranno di prevedere gli attacchi del Martello del Crepuscolo.",
}
T[8499] = {
  title = "L'Alleanza Ha Bisogno di Barre di Torio!",
  desc = "È molto gentile da parte tua informarti su ciò di cui l'Alleanza ha bisogno. Oltre a tutte le altre raccolte in corso, ci serve una grande quantità di barre di torio, ed è questo il compito di cui sono responsabile. Il torio servirà a creare molte cose diverse per la guerra, prima fra tutte un battaglione di carri a vapore da trasportare per via aerea a Silithus appena saranno pronti. Puoi aiutarci in questa impresa, $C?",
  obj = "Porta 20 Thorium Bar a Dame Twinbraid, in Military Ward di Ironforge.",
  progress = "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!",
  reward = "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...",
  en_title = "The Alliance Needs Thorium Bars!",
  en_obj = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.",
}
T[8500] = {
  title = "L'Alleanza Ha Bisogno di Altre Barre di Torio!",
  desc = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di barre di torio. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.",
  obj = "Porta 20 Thorium Bar a Dame Twinbraid, all'aerodromo di Dun Morogh.",
  progress = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di barre di torio. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.",
  reward = "Eccellente, $C! Un lavoro ben fatto. Mi assicurerò che quelle barre finiscano sul bancale e nelle mani dei fabbri e degli ingegneri che lavorano sodo per preparare i rifornimenti del nostro esercito. Grazie ancora, e se trovi altre barre di torio, passa pure da me.",
  en_title = "The Alliance Needs More Thorium Bars!",
  en_obj = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.",
}
T[8501] = {
  title = "Bersaglio: Pungitori Hive'Ashi",
  desc = "Man mano che lo sforzo bellico si intensifica, la presenza dei silithid nella zona è una minaccia sempre più grave per le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, dove il tuo bersaglio principale saranno i pungitori volanti Hive'Ashi.$B$BA compito concluso, torna a fare rapporto al Comandante Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Stingers e torna a fare rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Combat Task Briefing XII.",
  progress = "Desideri dirmi qualcosa, $N?",
  reward = "Ottimo lavoro, $N. Il tuo contributo all'attacco a Hive'Ashi è stato registrato.",
}
T[8502] = {
  title = "Bersaglio: Operaie Hive'Ashi",
  desc = "Man mano che lo sforzo bellico si intensifica, la presenza dei silithid nella zona è una minaccia sempre più grave per le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, dove il tuo bersaglio principale saranno le operaie Hive'Ashi.$B$BA compito concluso, torna a fare rapporto al Comandante Mar'alith.",
  obj = "Abbatti 30 Hive'Ashi Workers e torna a fare rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Combat Task Briefing III.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Senza le loro operaie, i silithid faticheranno a riparare qualsiasi danno inflitto alla struttura del loro alveare.",
}
T[8503] = {
  title = "L'Alleanza Ha Bisogno di Algatorta!",
  desc = "Allora, $C, ti ho già parlato di tutti i favolosi usi dell'algatorta? Sì? Be', pazienza... comunque ce ne serve tanta, e quando dico tanta intendo TANTISSIMA! Pensi di poterci dare una mano? So che significa rinunciare a tutte le cose meravigliose che ci puoi fare, ma è per una buona causa!",
  obj = "Porta 20 Stranglekelp a Private Draxlegauge, in Military Ward di Ironforge.",
  progress = "Non è vero! Non prenderei mai di nascosto un po' di algatorta dalle pile che ho qui. Anche se la tentazione ci sarebbe, visto che è praticamente una panacea di utilità pratica. *coff* Non è che per caso hai l'algatorta di cui parlavamo prima?",
  reward = "Evviva! Altre venti sistemate. Sei $Gil migliore:la migliore;. Immagino che dovrei impacchettarle tutte prima che appassiscano. Tanta algatorta, così poco tempo!$B$BGrazie ancora, $C!",
  en_title = "The Alliance Needs Stranglekelp!",
  en_obj = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.",
}
T[8504] = {
  title = "L'Alleanza Ha Bisogno di Altra Algatorta!",
  desc = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora algatorta, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?",
  obj = "Porta 20 Stranglekelp a Private Draxlegauge, all'aerodromo di Dun Morogh.",
  progress = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora algatorta, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?",
  reward = "Oh, santo cielo, che carico di algatorta hai lì! Presto, mettiamola in una cassa per tenerla fresca. Portando questa partita hai fatto a me... cioè, a noi, all'Alleanza, un grande favore. Farò in modo che tutti sappiano che sei $Gstato:stata; tu, $Gil grande:la grande; $N, ad aiutare a far pendere la bilancia nello sforzo bellico di Ahn'Qiraj con il tuo contributo di algatorta!",
  en_title = "The Alliance Needs More Stranglekelp!",
  en_obj = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.",
}
T[8505] = {
  title = "L'Alleanza Ha Bisogno di Fiori di Loto Purpureo!",
  desc = "$C, il loto purpureo è un fiore dai molteplici usi. Sono qui su richiesta dell'Alleanza come autorità in materia, per conservare le erbe raccolte e assicurarmi che il suo sforzo bellico ottenga abbastanza loto purpureo per qualunque impiego abbia in mente.$B$BVorrei che tu viaggiassi per il mondo e tornassi da me con alcuni di questi fiori. Puoi farlo?",
  obj = "Porta 20 Purple Lotus a Master Nightsong, in Military Ward di Ironforge.",
  progress = "Hai le erbe di loto purpureo che ti ho chiesto?",
  reward = "Il tuo contributo è molto apprezzato, $C. Solo con gli sforzi uniti di tutti potremo respingere l'avanzata spietata dei silitidi e di qualunque forza li stia spingendo avanti. Anche l'Orda sta ammassando la sua scorta di loto purpureo. Se ne trovi altro, ti prego, torna da me.",
  en_title = "The Alliance Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.",
}
T[8506] = {
  title = "L'Alleanza Ha Bisogno di Altri Fiori di Loto Purpureo!",
  desc = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro loto purpureo. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.",
  obj = "Porta 20 Purple Lotus a Master Nightsong, all'aerodromo di Dun Morogh.",
  progress = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro loto purpureo. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.",
  reward = "Accetto con piacere il tuo contributo a nome dell'Alleanza, $N. I tuoi sforzi porteranno direttamente alla creazione di varie pozioni e oli a sostegno dei nostri uomini e delle nostre donne sul campo. Grazie, e se ne trovassi altro, pensa a tornare da me.",
  en_title = "The Alliance Needs More Purple Lotus!",
  en_obj = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.",
}
T[8507] = {
  title = "Servizio sul Campo",
  desc = "Salute, $N. Prima che io ti assegni compiti più impegnativi in questa guerra, dovrai fare la tua parte di servizio sul campo.$B$BTroverai la Ironforge Brigade del Capitano Blackanvil fuori da Hive'Zora.$B$BPresentati a lui o alla sua tenente, Janela Stouthammer, e torna da me. Avrò pronto per te un incarico più avanzato.$B$BAh, e per favore, facci una cortesia: stai alla larga dalla Legione di Orgrimmar. Siamo stati costretti a tenere le due forze ben lontane l'una dall'altra per via dell'ostilità reciproca.",
  obj = "Presentati a rapporto alla postazione della Ironforge Brigade vicino a Hive'Zora. Prepara i tuoi Unsigned Field Duty Papers, fatti dare i Signed Field Duty Papers da Captain Blackanvil e torna da Windcaller Kaldon a Cenarion Hold, a Silithus.$B$BNota: curare un membro della Ironforge Brigade o lanciare su di lui incantesimi benefici ti attiverà il PvP.",
  progress = "Troverai le forze del Capitano Blackanvil di stanza fuori da Hive'Zora. Se non lo trovi, parla con la sua tenente, Janela Stouthammer.",
  reward = "Molto bene, $N. Ho preparato una serie di incarichi che dovrebbero sfruttare al meglio le tue capacità.$B$BGrazie all'impegno costante tuo e di quelli come te, il nostro nemico sarà presto sconfitto una volta per tutte!$B$BSe ti servono nuove istruzioni di missione, torna dal Capitano Blackanvil.",
}
T[8508] = {
  title = "Documenti di Servizio sul Campo",
  progress = "Immagino tu voglia farti firmare quei documenti, $Gragazzo:ragazza;?",
  reward = "Già, di questi tempi quella piccola scaramuccia passerà pure per servizio sul campo, immagino. Riportali a Cenarion Hold, di sicuro avranno pronto per te un incarico bello comodo.$B$BForza, vai!",
}
T[8509] = {
  title = "L'Alleanza Ha Bisogno di Lacrime di Arthas!",
  desc = "Sarò semplice e diretta, $C. L'Alleanza deve raccogliere una grande quantità di Lacrime di Arthas per lo sforzo bellico di Ahn'Qiraj. Non chiedermi a cosa servano: io eseguo solo gli ordini. Ma vorrei che tu raccogliessi quante più di queste erbe puoi e me le riportassi qui. Sei $Gdisposto:disposta; a farlo?",
  obj = "Porta 20 Arthas' Tears a Sergeant Major Germaine, in Military Ward di Ironforge.",
  progress = "Come dici? Parla più forte, $C! Hai quel carico di Lacrime di Arthas che ti ho chiesto?",
  reward = "Bel lavoro, $C. Devo dire che sono piacevolmente sorpresa. Non crederesti a quanta gente è passata di qui offrendosi di aiutare, senza poi tornare mai. Lasciami mettere queste in una cassa e registrarle a tuo nome, poi potremo riparlarne, per vedere se mi servono altre di queste piante.",
  en_title = "The Alliance Needs Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.",
}
T[8510] = {
  title = "L'Alleanza Ha Bisogno di Altre Lacrime di Arthas!",
  desc = "Ok, a quanto pare mi servono ancora Lacrime di Arthas. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $C?",
  obj = "Porta 20 Arthas' Tears a Sergeant Major Germaine, all'aerodromo di Dun Morogh.",
  progress = "Ok, a quanto pare mi servono ancora Lacrime di Arthas, $C. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Lo sforzo bellico procede bene, ma prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $N?",
  reward = "Semplicemente eccezionale, $N! Fai davvero onore all'Alleanza. Metterò via queste erbe finché qualcuno non verrà a trasformarle in qualcosa di utile per la guerra. Torna pure quando vuoi, soprattutto se hai altre Lacrime di Arthas per me.",
  en_title = "The Alliance Needs More Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the airfield in Dun Morogh.",
}
T[8511] = {
  title = "L'Alleanza Ha Bisogno di Cuoio Leggero!",
  desc = "Noi Stoneflayer abbiamo una lunga tradizione di scuoiatori, $C. Per questo l'Alleanza ha chiesto alla mia famiglia di aiutare a raccogliere cuoio leggero per lo sforzo bellico di Ahn'Qiraj. Sono qui per assicurarmi che il cuoio venga conciato come si deve, qualunque sia l'uso che vogliono farne. Ma ci serve il tuo aiuto.$B$BVisto che devo restare qui a fare questo, ho bisogno che tu vada a raccogliere le pelli e me le riporti qui. Che ne dici, $Gragazzo:ragazza;, ci provi?",
  obj = "Porta 10 Light Leather a Bonnie Stoneflayer, in Military Ward di Ironforge.",
  progress = "$C, spero proprio che quello sia il cuoio leggero che mi avevi promesso.",
  reward = "Direi che l'Alleanza sarà molto contenta di queste tue pelli, $C. Farò in modo che non se ne sprechi nemmeno una. Grazie, e ripassa da me quando le avrò contate, per vedere se ce ne servono altre.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.",
}
T[8512] = {
  title = "L'Alleanza Ha Bisogno di Altro Cuoio Leggero!",
  desc = "Che piacere rivederti, $N. Sembra proprio che ci serva altro cuoio leggero per fabbricare i vari materiali bellici. Se mi portassi una pila da dieci, sarebbe perfetto.",
  obj = "Porta 10 Light Leather a Bonnie Stoneflayer, all'aerodromo di Dun Morogh.",
  progress = "Che piacere rivederti, $N. Sembra proprio che ci serva altro cuoio leggero per fabbricare i vari materiali bellici. Se mi portassi una pila da dieci, sarebbe perfetto.",
  reward = "Grazie per la tua generosa donazione, $N. Lo metto subito sul mucchio, e vedrai che in un attimo diventerà una bella armatura, qualche toppa di cuoio o qualcos'altro per i nostri preparativi. Pare che il cuoio leggero non basti mai. Torna a trovarmi presto.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.",
}
T[8513] = {
  title = "L'Alleanza Ha Bisogno di Cuoio Medio!",
  desc = "Sì, $Gsignore:signora;, mi hanno incaricato di raccogliere e registrare tutto il cuoio medio che si mette insieme per lo sforzo bellico. Se hai modo di procurarti del cuoio medio, da qualunque fonte, per favore portalo qui da me. Mi farebbe davvero comodo una mano, se hai un po' di tempo.",
  obj = "Porta 10 Medium Leather a Private Porter, a Military Ward di Ironforge.",
  progress = "Sì, $Gsignore:signora;, mi ricordo di te. È cuoio medio quello che hai lì con te?",
  reward = "Caspita! Mi sa che eri qui giusto poco fa a offrirti di aiutare. Grazie mille per la donazione. Adesso impacchetto e conto tutto. Sai proprio come rallegrare la giornata a uno come me.",
  en_title = "The Alliance Needs Medium Leather!",
  en_obj = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.",
}
T[8514] = {
  title = "L'Alleanza Ha Bisogno di Altro Cuoio Medio!",
  desc = "Sì, $Gsignore:signora;, pare che finora abbiamo raccolto un sacco di pezzi di cuoio medio. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.",
  obj = "Porta 10 Medium Leather a Private Porter, all'aerodromo di Dun Morogh.",
  progress = "Sì, $Gsignore:signora;, pare che abbiamo raccolto un sacco di pezzi di cuoio medio, ma ce ne servono altri. Ti assicuro che sarà tutto usato bene: non se ne sprecherà nemmeno un pezzo. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.",
  reward = "Accidenti, che quantità di cuoio medio mi hai portato, $Gsignore:signora;! Farò in modo che venga usato tutto come si deve, eccome se lo farò. Con il tuo aiuto raggiungeremo in un baleno la quantità di cuoio medio che avevamo previsto!$B$BGrazie, $N!",
  en_title = "The Alliance Needs More Medium Leather!",
  en_obj = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.",
}
T[8515] = {
  title = "L'Alleanza Ha Bisogno di Cuoio Spesso!",
  desc = "Oh, che bello, sarà fantastico! $C, lo sforzo bellico di Ahn'Qiraj è in pieno svolgimento, e mi hanno incaricato di tenere il conto di tutto il cuoio spesso che arriva. Ci faremo un sacco di cose, ma prima dobbiamo raccoglierne una tonnellata. E lo dico alla lettera! Ed è qui che entri in gioco tu.$B$BAllora, pensi di poter andare là fuori e riportarmi una pila bella grossa di cuoio spesso? Ce la fai? Ce la fai?!",
  obj = "Porta 10 Thick Leather a Marta Finespindle, a Military Ward di Ironforge.",
  progress = "È cuoio spesso quello che hai lì nello zaino, $C? Vero? Non vedo l'ora che me lo consegni! Saranno tutti così contenti di noi, non credi?",
  reward = "Oh, lo sapevo che ce l'avresti fatta, $C, lo sapevo! Lo metterò nelle mani giuste il prima possibile. Allora, vediamo un po'. Mmm, pare che il conto stia procedendo piuttosto bene. Ripassa da me tra un attimo, quando avrò finito di contare, per vedere se ce ne serve altro. Perché se è così, voglio che sia tu ad andare a raccoglierlo per me!",
  en_title = "The Alliance Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.",
}
T[8516] = {
  title = "L'Alleanza Ha Bisogno di Altro Cuoio Spesso!",
  desc = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di cuoio spesso. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! Occhiali d'ingegneria, e scommetto che se finiamo per raccoglierne troppo potremmo dare il resto all'Orda per i suoi zeppelin!$B$BMi riporti altro cuoio spesso?",
  obj = "Porta 10 Thick Leather a Marta Finespindle, all'aerodromo di Dun Morogh.",
  progress = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di cuoio spesso. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! E occhiali d'ingegneria, che sono sempre divertenti!$B$BMi riporti altro cuoio spesso?",
  reward = "Ce l'hai fatta di nuovo! È semplicemente incredibile come tu vada là fuori, raccolga tutta questa roba e poi la riporti qui a consegnarla. Te lo dico io: quando scopriranno quanto hai aiutato qui, non potrai fare due passi per strada senza che la gente ti chieda l'autografo!$B$BGrazie ancora per la tua generosissima donazione di cuoio spesso, $N.",
  en_title = "The Alliance Needs More Thick Leather!",
  en_obj = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.",
}
T[8517] = {
  title = "L'Alleanza Ha Bisogno di Bende di Linen!",
  desc = "La guerra ad Ahn'Qiraj sarà lunga e sanguinosa. L'Alleanza fa una cosa molto saggia a chiedere aiuto a te e a quelli come te per accumulare il materiale bellico necessario, prima di gettarsi a capofitto nel conflitto.$B$BMi è stato chiesto di dirigere la raccolta di bende di linen per la guerra, e spero che tu mi aiuterai a radunarne quante ne servono. Non è una questione da poco, ma almeno le bende di linen sono le meno difficili da preparare. Sei con noi, $C?",
  obj = "Porta 20 Linen Bandage a Sentinel Silversky, a Military Ward di Ironforge.",
  progress = "Hai le venti bende di linen che mi servono, $C?",
  reward = "Molti sono i soldati che trarranno beneficio dal contributo che hai dato oggi, $C. Mi assicurerò di persona che l'Alleanza venga a sapere dei tuoi sforzi. Concedimi un momento per riporre come si deve queste bende e aggiornare il conto, poi ripassa da me per vedere se me ne servono altre.$B$BChe la Luce di Elune risplenda su di te, $R!",
  en_title = "The Alliance Needs Linen Bandages!",
  en_obj = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.",
}
T[8518] = {
  title = "L'Alleanza Ha Bisogno di Altre Bende di Linen!",
  desc = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di bende di linen prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?",
  obj = "Porta 20 Linen Bandage a Sentinel Silversky, all'aerodromo di Dun Morogh.",
  progress = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di bende di linen prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?",
  reward = "Meriti un encomio, $N. Mentre c'è chi approfitta dell'economia di guerra per riempirsi le tasche in preda all'avidità, tu hai dimostrato più e più volte che la tua devozione all'Alleanza, e anzi a tutta Azeroth, viene prima di tutto.$B$BChe le benedizioni di Elune siano sempre con te!",
  en_title = "The Alliance Needs More Linen Bandages!",
  en_obj = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.",
}
T[8519] = {
  title = "Una Pedina sulla Scacchiera Eterna",
  desc = "Mentre ti ricomponi e metti a fuoco lo sguardo, noti che nel cristallo qualcosa si muove. Guardando meglio, capisci che stai osservando il passato... un ricordo... dimenticato da tempo.",
  obj = "Scopri tutto quello che puoi sul passato, poi parla con Anachronos alle Caverns of Time, a Tanaris.",
  reward = "Dopo il tradimento di Staghelm raccolsi i frammenti dello Scettro delle Sabbie Mutevoli e tornai qui. Ero deciso a proteggere lo scettro da chi avrebbe cercato di usarlo per fare del male al nostro mondo — così nacque l'incarico degli Stormi dei Draghi.$B$BUno scettro diviso fra i quattro potenti Aspetti sarebbe stato quasi impossibile da ricomporre per chi cerca deliberatamente il caos... o così credevo. Che sciocco sono stato. Ancora oggi quello stormo maledetto mi dà la caccia.",
}
T[8520] = {
  title = "L'Alleanza Ha Bisogno di Bende di Silk!",
  desc = "Con la guerra di Ahn'Qiraj alle porte, dobbiamo fare tutto il possibile perché i nostri soldati abbiano tutto ciò che serve. Ed è proprio quello che facciamo qui. Per quanto mi riguarda, mi hanno affidato il compito di raccogliere abbastanza bende di silk.$B$BPensi di potermi aiutare, $C?",
  obj = "Porta 20 Silk Bandage a Nurse Stonefield, a Military Ward di Ironforge.",
  progress = "Ciao, $C, sei già $Griuscito:riuscita; a procurarti quelle venti bende di silk?",
  reward = "$C, ce l'hai fatta! Grazie a te siamo un altro passo più vicini al nostro obiettivo di bende di silk. Le metto via, e poi, se vuoi, possiamo parlare ancora.",
  en_title = "The Alliance Needs Silk Bandages!",
  en_obj = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.",
}
T[8521] = {
  title = "L'Alleanza Ha Bisogno di Altre Bende di Silk!",
  desc = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero di bende di silk, ma ce ne serviranno altre.",
  obj = "Porta 20 Silk Bandage a Nurse Stonefield, all'aerodromo di Dun Morogh.",
  progress = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero delle bende di silk che ci hanno chiesto, ma ce ne servono ancora. $N, c'è modo che tu riesca a mettere insieme un altro fascio e a riportarmelo qui? L'Alleanza e io te ne saremo molto grate.",
  reward = "Sei una persona davvero altruista. Grazie mille per il tuo contributo allo sforzo bellico. Sono le persone come te che faranno la differenza tra il successo e la sconfitta ad Ahn'Qiraj. Spero solo che tutto questo basti.$B$BGrazie ancora, $N.",
  en_title = "The Alliance Needs More Silk Bandages!",
  en_obj = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.",
}
T[8522] = {
  title = "L'Alleanza Ha Bisogno di Bende di Runecloth!",
  desc = "Discuti pure sull'opportunità della guerra, se vuoi, $C, ma ormai è stata avviata. Guardati intorno, guarda la tua famiglia e i tuoi amici, e poi chiediti che cosa puoi fare perché, se saranno coinvolti, abbiano ogni vantaggio per sopravvivere alla conflagrazione.$B$BPer questo raccolgo qui bende di runecloth, da qualunque fonte vengano. Vuoi fare una donazione?",
  obj = "Porta 20 Runecloth Bandage a Keeper Moonshade, a Military Ward di Ironforge.",
  progress = "I giorni passano uno dopo l'altro, e noi andiamo ancora avanti. $C, hai quelle bende di runecloth?",
  reward = "Meriti un encomio per la tua perseveranza in questo compito, $C. Metterò via queste bende, e poi vorrei parlarti di nuovo della possibilità che tu raccolga ancora altre bende di runecloth.",
  en_title = "The Alliance Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.",
}
T[8523] = {
  title = "L'Alleanza Ha Bisogno di Altre Bende di Runecloth!",
  desc = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.$B$B$N, raccoglierai ancora una volta bende di runecloth e me le riporterai qui?",
  obj = "Porta 20 Runecloth Bandage a Keeper Moonshade, all'aerodromo di Dun Morogh.",
  progress = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.$B$B$N, raccoglierai ancora una volta bende di runecloth e me le riporterai qui?",
  reward = "È una bella strada quella che percorriamo insieme, $N. Sei $Gun ottimo compagno:un'ottima compagna; di lavoro. Ancora una volta ti ringrazio per i tuoi sforzi a nome di tutta l'Alleanza. Torna presto a parlare con me.",
  en_title = "The Alliance Needs More Runecloth Bandages!",
  en_obj = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.",
}
T[8524] = {
  title = "L'Alleanza Ha Bisogno di Alborella Iridata in Carpione!",
  desc = "Ehi, $Gamico:amica;! Se ti chiedessi: \"Non pensi che i soldati debbano avere da mangiare come tutti gli altri?\", ovviamente risponderesti: \"Sì\". Sono d'accordo con te al 110%! Sono contento che la pensiamo allo stesso modo. Tutto quello che devi fare è andare là fuori, pescare un bel mucchio di alborella iridata cruda, cucinarla tutta e riportarmela proprio qui. Mmm, mmm, ne sento già il sapore.",
  obj = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, a Military Ward di Ironforge.",
  progress = "Scommetto che sei $Gtornato:tornata; con tutta quell'alborella iridata di cui parlavamo prima, vero, $C?",
  reward = "Due per l'Alleanza, uno per me, due per l'Alleanza, uno per me. Ehi, $Gpescivendolo:pescivendola;, ottimo lavoro. Vedo che farai onore al club. Mi sa però che ci serve altra alborella. Perché non vai là fuori a rimediarne ancora un po'? Sento già lo stomaco che brontola.",
  en_title = "The Alliance Needs Rainbow Fin Albacore!",
  en_obj = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.",
}
T[8525] = {
  title = "L'Alleanza Ha Bisogno di Altra Alborella Iridata in Carpione!",
  desc = "Cosa! Ancora tu? Be', resto di sasso... anzi no, resto uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altra alborella iridata!",
  obj = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, all'aerodromo di Dun Morogh.",
  progress = "Cosa! Ancora tu? Be', resto di sasso... anzi no, resto uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altra alborella iridata!",
  reward = "Lo sapevo che ne eri capace, $Gragazzo:ragazza;. Hai l'aria di $Guno che sa cosa gli piace:una che sa cosa le piace;. In particolare, che ti piace fare contento me e chi comanda. E ci sei $Griuscito:riuscita;, te lo garantisco.$B$BAhah, ok, metto via questi pesci come si deve, e poi io e te facciamo due chiacchiere su altre venti alborelle da raccogliere.",
  en_title = "The Alliance Needs More Rainbow Fin Albacore!",
  en_obj = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.",
}
T[8526] = {
  title = "L'Alleanza Ha Bisogno di Raptor Arrosto!",
  desc = "Oh, come va, $C? Vedo che forse ti interessa raccogliere cibo per la guerra che sta per scoppiare ad Ahn'Qiraj? Chissà perché mio padre ha pensato che offrirmi volontaria qui sarebbe stata un'esperienza educativa. Grosso errore. A me la carne non piace nemmeno.$B$BComunque, se ti va, potresti riportarmi un sacco di raptor arrosto. A quanto pare è quello che vorranno tutti i soldati.",
  obj = "Porta 20 Roast Raptor a Sarah Sadwhistle, a Military Ward di Ironforge.",
  progress = "Allora, ce l'hai tutto quel raptor arrosto?",
  reward = "Uh, fantastico. Grazie di avermi portato tutta questa carne di animale bruciata, $C. La metto sul mucchio laggiù. Qualcuno se ne occuperà di sicuro. Immagino che, se hai un po' di tempo libero, vorrai portarmene altra?",
  en_title = "The Alliance Needs Roast Raptor!",
  en_obj = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.",
}
T[8527] = {
  title = "L'Alleanza Ha Bisogno di Altro Raptor Arrosto!",
  desc = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti raptor arrosto. Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.",
  obj = "Porta 20 Roast Raptor a Sarah Sadwhistle, all'aerodromo di Dun Morogh.",
  progress = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti raptor arrosto? Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.",
  reward = "Wow, sei proprio una persona intraprendente. Mi stanchi solo a guardarti. Comunque, grazie da parte dell'Alleanza e via dicendo. Farò in modo che tutta quella carne morta venga impacchettata. Immagino che potresti ripassare più tardi per vedere se ce ne serve ancora, anche se, a dirla tutta, qui comincia a esserci puzza.",
  en_title = "The Alliance Needs More Roast Raptor!",
  en_obj = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.",
}
T[8528] = {
  title = "L'Alleanza Ha Bisogno di Pinnagialla Maculato!",
  desc = "Raccogliere pesce cotto può non sembrare eroico, ma non sottovalutare il valore della preparazione, giovane $C. I soldati devono mangiare come tutti gli altri, e noi siamo qui a fare la nostra parte perché abbiano ciò che serve quando comincerà la guerra ad Ahn'Qiraj.$B$BPer questo sto facendo scorta di pinnagialla maculato, una fonte di nutrimento versatile che si conserva bene e si può usare in molti piatti diversi. E non ha nemmeno l'odore di certi altri pesci di mare. Sei $Gdisposto:disposta; ad aiutarmi in questa impresa?",
  obj = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, nel Military Ward di Ironforge.",
  progress = "Sono sicura che, se torni così presto, è perché hai il pinnagialla maculato di cui abbiamo parlato.",
  reward = "Grazie per questo dono, $C, e per giunta così tempestivo. Ai nostri soldati di certo non mancherà da mangiare. Lasciami riporre come si deve questi pesci, e poi, se sei $Gdisposto:disposta;, possiamo parlare di una seconda pescata.",
  en_title = "The Alliance Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.",
}
T[8529] = {
  title = "L'Alleanza Ha Bisogno di Altro Pinnagialla Maculato!",
  desc = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di pinnagialla maculato, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  obj = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, all'aerodromo di Dun Morogh.",
  progress = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di pinnagialla maculato, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  reward = "Sei un vero membro dell'Alleanza, $N. I tuoi sforzi non passeranno inosservati, né saranno dati per scontati. E grazie anche per aver cucinato il pesce. Farò in modo che venga riposto come si deve, e poi dovrò aggiornare il conto. Ogni pesce ci avvicina un po' di più alla nostra meta.",
  en_title = "The Alliance Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.",
}
T[8530] = {
  title = "L'Alleanza Ha Bisogno di Corestone Carbonizzate!",
  desc = "$C, ho bisogno del tuo aiuto. Nel Molten Core ci sono delle pietre, le Corestone carbonizzate per la precisione, che dobbiamo raccogliere per lo sforzo bellico di Ahn'Qiraj. Mi dicono che i nostri fabbri e ingegneri sapranno farne buon uso, ed è qui che entri in gioco tu. Ho bisogno che tu vada nel Molten Core e raccolga quante più corestone puoi. Naturalmente vorrai portarti dietro trentanove dei tuoi amici più cari.",
  obj = "Porta 50 Singed Corestone a Commander Stronghammer, all'aerodromo di Dun Morogh.",
}
T[8532] = {
  title = "L'Orda Ha Bisogno di Barre di Rame!",
  desc = "Sono davvero contento che tu abbia deciso di dare una mano. Non tutti lo farebbero, quindi devo essere sicuro che tu abbia capito bene cosa mi serve. Barre di rame, non minerale di rame. Non abbiamo né il tempo né la gente per fondere tutto noi, quindi se fossi così gentile da occupartene tu, i tuoi sforzi verranno debitamente annotati. Pensi di farcela, $C?",
  obj = "Porta 20 Copper Bar a Miner Cromwell, nella Valley of Spirits di Orgrimmar.",
  progress = "Spero che quelle che hai con te siano le venti barre di rame, $C.",
  reward = "Queste barre andranno bene, e grazie per non averle lucidate. Non ha senso farle belle, se poi verranno maltrattate per fabbricare il materiale bellico che serve per la guerra. Le metterò io sulle pile e farò in modo che vengano usate come si deve. Parlami di nuovo se ti interessa portarne altre venti.",
  en_title = "The Horde Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.",
}
T[8533] = {
  title = "L'Orda Ha Bisogno di Altre Barre di Rame!",
  desc = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di minerale di rame, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?",
  obj = "Porta 20 Copper Bar a Miner Cromwell, a Durotar.",
  progress = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di minerale di rame, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?",
  reward = "Mi hai dimostrato di nuovo il tuo valore, $C. Farò in modo che questo rame venga usato a suo tempo. Per ora, però, devo mettere queste barre di rame sul bancale e contarle. Se te la senti ancora, probabilmente mi farebbe comodo il tuo aiuto per raccogliere altre barre di rame.",
  en_title = "The Horde Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Miner Cromwell in Durotar.",
}
T[8534] = {
  title = "Rapporto dell'Esploratore di Hive'Zora",
  desc = "Abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid a raccogliere informazioni. L'Esploratrice Azenel osserva da diversi giorni i movimenti dei silithid a Hive'Zora. Trovala e fatti dare un rapporto scritto. Dobbiamo poter agire in base a quelle informazioni il prima possibile, $N.",
  obj = "Contatta Cenarion Scout Azenel dentro Hive'Zora e riporta l'Hive'Zora Scout Report a Windcaller Proudhorn, a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing VI.",
  progress = "Troverai l'Esploratrice Azenel dentro Hive'Zora. Sbrigati, $N! Non c'è tempo da perdere.",
  reward = "Apprezziamo molto il tuo impegno, $N. Leggo subito questi rapporti di esplorazione, tu intanto dai pure un'occhiata al tuo prossimo incarico.",
}
T[8535] = {
  title = "Templare Hoary",
  desc = "Il Martello del Crepuscolo e i nobili elementali che venera sono una minaccia temibile per le nostre operazioni a Silithus. Con i nuovi nemici che stiamo affrontando dentro Ahn'Qiraj, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare e distruggere un Templare Hoary e fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Hoary Templar, poi fai rapporto a Bor Wildmane a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing IV.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Bel lavoro, $N. Ecco il tuo prossimo incarico.",
}
T[8536] = {
  title = "Templare Terrigeno",
  desc = "Il Martello del Crepuscolo e i nobili elementali che venera sono una minaccia temibile per le nostre operazioni a Silithus. Con i nuovi nemici che stiamo affrontando dentro Ahn'Qiraj, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare e distruggere un Templare Terrigeno e fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Earthen Templar, poi fai rapporto a Bor Wildmane a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing III.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Bel lavoro, $N. Ecco il tuo prossimo incarico.",
}
T[8537] = {
  title = "Templare Cremisi",
  desc = "Il Martello del Crepuscolo e i nobili elementali che venera sono una minaccia temibile per le nostre operazioni a Silithus. Con i nuovi nemici che stiamo affrontando dentro Ahn'Qiraj, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare e distruggere un Templare Cremisi e fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Crimson Templar, poi fai rapporto a Bor Wildmane a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing II.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Bel lavoro, $N. Ecco il tuo prossimo incarico.",
}
T[8538] = {
  title = "I Quattro Duchi",
  desc = "I legami fra il Martello del Crepuscolo e l'Abyssal Council si stanno rivelando più importanti di quanto pensassimo.$B$BCrediamo che i nobili elementali noti come Duchi Abissali siano una delle forze principali che organizzano i cultisti del Martello del Crepuscolo. Trova il modo di attirare i quattro Duchi Abissali sul nostro piano di esistenza e distruggili!$B$BLa dedizione e il valore che hai dimostrato negli incarichi passati ci hanno portato a scegliere te per questo incarico in particolare. Siamo certi che riuscirai nell'impresa.",
  obj = "Trova il modo di evocare e uccidere il Duke of Cynders, il Duke of Fathoms, il Duke of Zephyrs e il Duke of Shards, poi fai rapporto a Commander Mar'alith a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing V.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Oggi hai compiuto una grande impresa per la nostra causa, $N. Hai sconfitto alcuni dei nostri nemici più potenti. Per questo hai il mio più vivo elogio.",
}
T[8539] = {
  title = "Bersaglio: Sorelle dell'Alveare di Hive'Zora",
  desc = "I rinforzi sono stati chiamati a unirsi all'assalto contro Hive'Zora. Sei $Gstato scelto:stata scelta; per colpire le sorelle dell'alveare di Hive'Zora. A compito concluso, fai rapporto al Comandante Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Hive Sisters, poi fai rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Combat Task Briefing V.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Sei $Gun degno alleato:una degna alleata;.",
}
T[8540] = {
  title = "Stivali per la Guardia",
  desc = "Alla divisione a cavallo della guardia di Cenarion Hold scarseggiano gli stivali di mithril decorati. Procuratene una partita e consegnala subito al Capitano Vish Kozus, a Cenarion Hold.",
  obj = "Porta 3 Ornate Mithril Boots a Vish Kozus, Capitano della Guardia di Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing II.",
}
T[8541] = {
  title = "Pietre da Molatura per la Guardia",
  desc = "Alla guardia di Cenarion Hold scarseggiano le pietre da molatura. Procuratene una partita e consegnala subito al Capitano Vish Kozus, a Cenarion Hold.",
  obj = "Porta 10 Dense Grinding Stones, 10 Solid Grinding Stones e 10 Heavy Grinding Stones a Vish Kozus, Capitano della Guardia di Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing III.",
}
T[8542] = {
  title = "L'Orda Ha Bisogno di Barre di Stagno!",
  desc = "Lok'tar, $R, sono sicuro che sai già che andremo in guerra ad Ahn'Qiraj contro gli insetti. Ma prima il Capoguerra ha deciso che faremo una cosa chiamata \"prepararsi\". Anche se preferirei affilare armi e martellare armature, sono fiero di essere stato scelto per occuparmi della raccolta di barre di stagno qui. Ma non posso farlo senza il tuo aiuto.$B$BQuindi ho bisogno che tu vada a fare delle barre di stagno e me le riporti qui. Credo che me ne serviranno più di quante ne so contare.",
  obj = "Porta 20 Tin Bar a Grunt Maug, nella Valley of Spirits di Orgrimmar.",
  progress = "Quante barre di stagno hai lì, $C? Dopo la guerra credo che mi servirà qualcuno che mi insegni a contare.",
  reward = "Be', mi pare che questo sia il numero giusto di barre di stagno. Non provare a imbrogliarmi, $C! Contare mi fa male al cranio. Ora io vado a mettere queste barre sulla pila e tu vai là fuori a riportarmene altre uguali.",
  en_title = "The Horde Needs Tin Bars!",
  en_obj = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.",
}
T[8543] = {
  title = "L'Orda Ha Bisogno di Altre Barre di Stagno!",
  desc = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, il che vuol dire che mi arrabbierò se non inizi a portare la roba più in fretta. Magari potrei esercitarmi su di te, invece.$B$BHar! Forse no, perché poi chi mi riporterebbe le barre di stagno?",
  obj = "Porta 20 Tin Bar a Grunt Maug, a Durotar.",
  progress = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, e sono sicuro che lo sei anche tu, $C. Sarà gloriosa, quando comincerà. L'Orda che corre sulle sabbie del deserto di Silithus, armi in pugno, e si lancia a capofitto contro le masse di insetti. Quel giorno ci sarà grande onore per tutti!$B$BHar! Ma prima ci servono altre barre di stagno. Buffo come una cosa così piccola possa fare una differenza così grande, non trovi?",
  reward = "Throm'ka, $N. Onori me e l'Orda con le tue barre di stagno. Le metterò sulla pila, e poi verranno a farne delle cose. E quando sarà tutto fatto andremo in guerra e mostreremo a quella misera Alleanza come si combattono gli insetti.$B$BOra riportami altre barre di stagno!",
  en_title = "The Horde Needs More Tin Bars!",
  en_obj = "Bring 20 tin bars to Grunt Maug in Durotar.",
}
T[8545] = {
  title = "L'Orda Ha Bisogno di Barre di Mithril!",
  desc = "$C, la guerra sta arrivando e l'unica cosa che possiamo fare è prepararci. È lì che tu e io possiamo aiutarci a vicenda, mon. Vedi, mi hanno messo a capo della raccolta di tutte le barre di mithril che ci servono per costruire tutte le cose di cui avremo bisogno. E me ne servono ancora!$B$BQuindi spero che tu possa andare là fuori a estrarci un po' di mithril e poi fonderlo in barre. Ti sembra una cosa che puoi fare per noi?",
  obj = "Porta 20 Mithril Bar a Senior Sergeant T'kelah, nella Valley of Spirits di Orgrimmar.",
  progress = "Sarebbe proprio bello avere tutte le barre di mithril che ci servono per lo sforzo bellico di Ahn'Qiraj. È per questo che sei $Gtornato:tornata;, mon? Hai le mie barre?",
  reward = "Questo è un buon inizio per te e per me, $C. Sono altre venti barre di mithril che posso mettere sulle pile e spuntare dalla lista. Verrà tutto usato bene per fare il materiale bellico.$B$BAssicurati di ripassare da me, perché mi sa proprio che ci serviranno ancora più barre di mithril.",
  en_title = "The Horde Needs Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8546] = {
  title = "L'Orda Ha Bisogno di Altre Barre di Mithril!",
  progress = "Già, sono contenta che tu sia qui, mon. Mi hai aiutato prima, e ora ho di nuovo bisogno del tuo aiuto. Stiamo ancora cercando di raccogliere altre barre di mithril per lo sforzo bellico; ci faremo un sacco di armature, armi e altre cose per andare a schiacciare quegli insetti ad Ahn'Qiraj.$B$BQuindi, se sei $Gun vero amico:una vera amica;, riportami altre pile di barre di mithril. Prendo tutte quelle che hai finché non raggiungiamo la quota. Ne hai qualcuna per me adesso?",
  reward = "Bel lavoro, $N! Altre venti barre ci portano un po' più vicino all'obiettivo, e ci danno altro materiale bellico. Mi occupo io di metterle via. E se ti procuri un'altra pila di barre di mithril, mon, assicurati di portarla qui da me.",
  en_title = "The Horde Needs More Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8548] = {
  title = "Equipaggiamento da Battaglia del Volontario",
  desc = "I distintivi che raccogli svolgendo incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a conservarli. Man mano che dimostri la tua lealtà alla nostra organizzazione, in cambio di quei distintivi posso offrirti parte dell'equipaggiamento che riserviamo ai nostri alleati più stretti.",
  obj = "Porta 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges e 7 Cenarion Tactical Badges a Vargus a Cenarion Hold, a Silithus. Per poter completare la missione devi anche raggiungere la reputazione Friendly con il Cenarion Circle.",
  progress = "È nel nostro interesse che i nostri alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Ti prego, accetta questo da parte del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8549] = {
  title = "L'Orda Ha Bisogno di Peacebloom!",
  desc = "Si dice che ogni generazione debba affrontare una prova decisiva. Temo che la guerra di Ahn'Qiraj sarà il crogiolo in cui verrà messa alla prova la nostra tempra. Così ci prepariamo, e nel farlo scopriamo di che pasta siamo fatti.$B$BMi sono offerta volontaria per aiutare l'Orda raccogliendo più peacebloom possibile, perché se ne possano fare pozioni per la guerra. Spero che tu sia qui per darmi il tuo aiuto. Se è così, ho bisogno che tu mi riporti una buona quantità di quest'erba. Mi aiuterai, $C?",
  obj = "Porta 20 Peacebloom a Herbalist Proudfeather, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con la peacebloom, $C?",
  reward = "E così i nostri sforzi ci spingono un po' più vicino alla guerra. Grazie per il duro lavoro che hai fatto per raccogliere questa peacebloom, $C. Ti assicuro che verrà usata bene, e che il tuo contributo è stato annotato, $N. Se te la senti, torna da me con altri di questi fiori. Fino ad allora, che la Madre Terra ti guidi.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8550] = {
  title = "L'Orda Ha Bisogno di Altra Peacebloom!",
  progress = "Ciao di nuovo, Abyssmal. Sono contenta che tu voglia parlarmi ancora del nostro bisogno senza fine di peacebloom. Lo sforzo bellico continua, e con esso la nostra produzione di pozioni ed elisir per le battaglie che verranno. Ci aiuterai di nuovo, $C? Mi serve la stessa quantità di peacebloom di prima, quindi se puoi raccoglierla e riportarmela qui te ne sarò molto grata. Naturalmente, se ce l'hai già con te, sarò più che felice di prenderla subito",
  reward = "Grazie per il tuo impegno costante, $N. Con la tua generosità disinteressata porti grande onore a te e ai tuoi antenati, e tutti lo sapranno! Metterò via queste erbe perché restino fresche finché non serviranno. Ancora una volta mostri il vero spirito dell'Orda: la lotta per superare le difficoltà e la promessa che possiamo farlo insieme.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8551] = {
  title = "Il Forziere del Capitano",
  desc = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.$B$BFinché...$B$BQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il Forziere del Capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!$B$BHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.",
  obj = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.",
  progress = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!",
  reward = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.$B$BMa la mia vendetta non è completa...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[8552] = {
  title = "La Fascia con il Monogramma",
  desc = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.",
  obj = "Riporta la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Hai affari da trattare con me?",
  reward = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!$B$BSono contento che quel lurido farabutto sia morto — Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
  en_title = "The Monogrammed Sash",
  en_obj = "Return the Monogrammed Sash to its owner.",
}
T[8553] = {
  title = "La Sciabola del Capitano",
  desc = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.$B$BStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.$B$BAffronta Negolash e riportami la mia sciabola!$B$BParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[8554] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Ali di Condor alla Griglia. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di ali di condor. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.$B$BUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.",
  progress = "Hai recuperato la mia sciabola, $N?",
  reward = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha cambiato in meglio la mia sorte, puoi starne certo!$B$BGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[8555] = {
  title = "L'Incarico dei Dragonflight",
  reward = "Eranikus, Vaelastrasz e Azuregos... Senza dubbio conosci questi draghi, mortale. Non è un caso, dunque, che abbiano avuto un ruolo così influente come custodi del nostro mondo.$B$BPurtroppo (e in parte la colpa è della mia ingenuità), per mano di agenti degli Dei Antichi o per il tradimento di chi si diceva loro amico, ogni guardiano è andato incontro alla tragedia. Una tragedia la cui portata ha alimentato la mia sfiducia verso la tua specie.$B$BCercali... E tu, $R, preparati al peggio.",
}
T[8556] = {
  title = "Sigillo della Forza Inflessibile",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji conferiscano loro capacità formidabili. Le gemme corrotte che li adornano si potrebbero, in teoria, sostituire con materiali più puri per creare versioni non corrotte degli anelli.$B$BLe gemme che adornano gli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e creerò un anello potente per te, $C.",
  obj = "Porta 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs e 5 Ivory Scarabs a Windcaller Yessendra a Silithus. Per completare questa missione devi anche raggiungere la reputazione Honored con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai che l'effetto è molto più... gradevole.",
}
T[8557] = {
  title = "Drappo della Forza Inflessibile",
  desc = "Sono lieto di sapere che ci stai aiutando nell'attacco ad Ahn'Qiraj, $N. Posso farti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, $C.$B$BMi servirà un drappo Qiraji, che naturalmente adatterò alla tua taglia. Mi serviranno anche degli idoli e degli scarabei, con cui creerò un fermaglio adatto.$B$BTi prometto che non resterai $Gdeluso:delusa;.",
  obj = "Porta 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs e 5 Bone Scarabs a Keyl Swiftclaw a Silithus. Per completare questa missione devi anche ottenere la reputazione Revered con il Cenarion Circle.",
  progress = "Hai portato i materiali per il mantello, $N?",
  reward = "Ah, sì... questo drappo è immacolato.$B$BPrendi questo mantello, $N. Che ti protegga dalla magia immonda dei Qiraji.",
}
T[8558] = {
  title = "Falcetto della Forza Inflessibile",
  desc = "I Qiraji e i loro servitori usano oggetti fatti con i materiali più rari e pregiati: ossa di gigantesche creature antiche, gemme dalle profondità della terra, metalli puri e resistenti.$B$BSolo a vedere i manufatti dei Qiraji mi viene voglia di mettermi all'opera sui loro frammenti, spezzati e fusi. Dimostra la tua fedeltà al Circle, $N, e con i migliori materiali dei Qiraji ti creerò un'arma potente.",
  obj = "Porta 1 Qiraji Spiked Hilt, 2 Alabaster Idols, 5 Crystal Scarabs e 5 Stone Scarabs a Warden Haro, a Silithus. Per completare questa missione devi anche raggiungere la reputazione Exalted con il Cenarion Circle.",
  progress = "Mi hai portato i componenti che mi servono, $N?",
  reward = "Hai fatto un buon lavoro, $C. Quest'elsa è un capolavoro... il bilanciamento è perfetto.$B$BPrendi la tua arma, $N. Impugnala con grande sicurezza e sconfiggi i nostri nemici!",
}
T[8572] = {
  title = "Equipaggiamento da Battaglia del Veterano",
  desc = "I distintivi che raccogli svolgendo incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a conservarli. Man mano che dimostri la tua lealtà alla nostra organizzazione, in cambio di quei distintivi posso offrirti parte dell'equipaggiamento che riserviamo ai nostri alleati più stretti.",
  obj = "Porta 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges e 4 Cenarion Tactical Badges a Vargus a Cenarion Hold, a Silithus. Per poter completare la missione devi anche raggiungere la reputazione Honored con il Cenarion Circle.",
  progress = "È nel nostro interesse che i nostri alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Ti prego, accetta questo da parte del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8573] = {
  title = "Equipaggiamento da Battaglia del Campione",
  desc = "I distintivi che raccogli svolgendo incarichi di combattimento, logistici e tattici per Cenarion Hold non servono solo a fare scena, $N.$B$BFaresti bene a conservarli. Man mano che dimostri la tua lealtà alla nostra organizzazione, in cambio di quei distintivi posso offrirti parte dell'equipaggiamento che riserviamo ai nostri alleati più stretti.",
  obj = "Porta 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges e 1 Mark of Cenarius a Vargus a Cenarion Hold, a Silithus. Per poter completare la missione devi anche raggiungere la reputazione Exalted con il Cenarion Circle.",
  progress = "È nel nostro interesse che i nostri alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Ti prego, accetta questo da parte del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8574] = {
  title = "Equipaggiamento da Battaglia del Valoroso",
  desc = "I distintivi che raccogli svolgendo incarichi di combattimento, logistici e tattici per l'Invocatrice del Vento Proudhorn non servono solo a fare scena, $N.$B$BFaresti bene a conservarli. Man mano che dimostri la tua lealtà alla nostra organizzazione, in cambio di quei distintivi posso offrirti parte dell'equipaggiamento che riserviamo ai nostri alleati più stretti.",
  obj = "Porta 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges e 1 Mark of Remulos a Vargus a Cenarion Hold, a Silithus. Per poter completare la missione devi anche raggiungere la reputazione Revered con il Cenarion Circle.",
  progress = "È nel nostro interesse che i nostri alleati più fedeli siano ben equipaggiati, $N.",
  reward = "Ottimo lavoro, $N. Ti prego, accetta questo da parte del Cenarion Circle. Te lo sei proprio meritato, $Gamico:amica;!",
}
T[8575] = {
  title = "Il Libro Mastro Magico di Azuregos",
  desc = "Non riesci a capire una sola parola di questo libro mastro. Non sai nemmeno in che lingua è scritto!",
  obj = "Consegna il Magical Ledger di Azuregos a Narain Soothfancy a Tanaris.",
  progress = "Ooooh! Un cosino magico che pulsa! Per me?",
  reward = "<Narain esamina il libro mastro con entusiasmo.>$B$BEccezionale, $R! Che cos'è? Non so leggere un'acca di Draconico.",
}
T[8576] = {
  title = "Tradurre il Libro Mastro",
  reward = "Andiamo con ordine, $N! Dobbiamo capire cosa ha scritto Azuregos in questo libro mastro.$B$BDici che ti ha detto di costruire una boa d'arcanite e che questo è il progetto? Strano che l'abbia scritto in Draconico. Quel vecchio caprone lo sa che io questa roba senza senso non la so leggere.$B$BPerché la cosa funzioni, mi servono i miei occhialoni da divinazione, un pollo da cinquecento libbre e il volume II di \"Draconico per Negati\". Non per forza in quest'ordine.",
}
T[8577] = {
  title = "Stewvul, Ex Migliore Amico per Sempre.",
  desc = "Se devo tradurre qualcosa, mi servono i miei occhialoni da divinazione. Purtroppo me li ha rubati parecchio tempo fa il mio ex migliore amico per sempre, Stewvul. Mi ha spezzato il cuore in cinque punti e poi mi ha lasciato qui a marcire.$B$BCon l'aiuto della mia fidata sfera di cristallo, ho ristretto i posti in cui può trovarsi a due: il Muro di Greymane a Silverpine, oppure quello che sembra un mondo portale nell'Outland, che in questo momento la Legione Infuocata sta invadendo. Dovrai rintracciarlo e recuperare i miei occhialoni, $N!",
  obj = "Narain Soothfancy vuole che trovi il suo ex migliore amico per sempre (BFF), Stewvul, e che recuperi gli occhialoni da divinazione che Stewvul gli ha rubato.",
  reward = "Non ci posso credere, mi ha trovato. Ero sicuro di averlo seminato quando ero nell'Outland. Io là non ci torno, $R! Non se ne parla, neanche per sogno! Ho chiuso con il fargli da migliore amico per sempre part-time e da schiavo a tempo pieno.",
}
T[8578] = {
  title = "Occhialoni da Divinazione? Nessun Problema!",
  desc = "<Dalla cassa senti uscire un sospiro di sollievo.>$B$BVuoi solo i suoi occhialoni da divinazione? Ottimo! Nessun problema... Dammi solo un minuto per... Ehi! Ma dove... Accidempoli!$B$BBe', c'è una brutta notizia e una ancora peggiore. Quella brutta è che ho perso gli occhialoni. Quella peggiore è che li ho persi il mese scorso, mentre ficcavo il naso nel Molten Core. Già, il Molten Core... Direi che i nostri affari si chiudono qui! Ciao!",
  obj = "Trova Narain's Scrying Goggles e riportali a Narain Soothfancy a Tanaris.",
  progress = "Il Molten Core, eh? Spero che i miei occhialoni siano ancora tutti interi!",
  reward = "Eccezionale! E adesso dove ho messo quel pollo da 500 libbre e il Volume II di \"Draconico per Negati???\" Ah, ed ecco un pensierino per tutto il tuo duro lavoro!",
}
T[8579] = {
  title = "Campioni Mortali",
  progress = "Più all'interno di Ahn'Qiraj percepiamo la presenza dei nostri fratelli ridotti in schiavitù; eppure nemmeno un esercito di draghi basterebbe a salvarli, $R.$B$BLo stesso incantesimo che li ha imprigionati ci metterebbe saldamente sotto il controllo di C'Thun, se ci avvicinassimo ancora a lui.$B$BIl Dio Antico ha previsto il nostro arrivo. Ogni speranza è perduta. Che differenza potrebbe mai fare $Gun:una; semplice mortale come te?",
  reward = "Vedo che non sei $Gun:una; mortale qualunque, $N. Le tue possibilità contro il Dio Antico, per quanto infinitamente piccole, a questo punto sono maggiori delle nostre. Dopotutto lui si aspetta dei draghi alla sua porta, ma non è preparato a qualcuno come te.$B$BCome Anachronos e Staghelm sconfissero i Qiraji mille anni fa grazie all'alleanza fra le razze mortali e quelle dei draghi, anche noi stringeremo un patto. Conquista la fiducia del Bronze Dragonflight e conquisterai la nostra. Solo allora faremo di te $Gun vero campione:una vera campionessa;.",
}
T[8580] = {
  title = "L'Orda Ha Bisogno di Firebloom!",
  desc = "Ehi, $C. Sì, proprio tu, mon! L'Orda pensa che le serve un bel mucchio di firebloom per 'sto sforzo bellico di Ahn'Qiraj. Magari la mettono in belle cose che fanno bum? Magari la danno all'Alleanza come combustibile per i suoi carri a vapore? Chi lo sa? Non Pele'keiki!$B$BPerò Pele'keiki sa questo... lui sa che tu lo aiuti e gli riporti tanta firebloom, vero, mon?",
  obj = "Porta 20 Firebloom a Batrider Pele'keiki, nella Valley of Spirits di Orgrimmar.",
  progress = "Tu non vuoi far arrabbiare Pele'keiki. Tu rendi felice Pele'keiki portandogli tanta firebloom, e alla svelta.",
  reward = "$C! Pele'keiki felice, per ora. Pele'keiki prende tutta 'sta firebloom e la mette in una cassa, così resta fresca. Pele'keiki si assicura che tutta la firebloom diventa roba buona per la guerra. E se ne trovi ancora, tu vieni subito da Pele'keiki. A Pele'keiki forse ne serve altra.",
  en_title = "The Horde Needs Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8581] = {
  title = "L'Orda Ha Bisogno di Altra Firebloom!",
  progress = "Pele'keiki sa che sei qui per aiutare. Porta tanta firebloom e lo renderai molto felice. Pele'keiki potrebbe fare grosse bombe con la firebloom. E sganciarle sugli insetti dal suo pipistrello sopra Ahn'Qiraj, quando arriva la guerra. Ma a Pele'keiki serve altra firebloom, $C!$B$BTu porti quella firebloom a Pele'keiki, e alla svelta. Torna con almeno la stessa quantità dell'ultima volta, e Pele'keiki sarà contento.",
  reward = "Non è uno scherzo, $C? Porti a Pele'keiki la firebloom così in fretta? Pele'keiki la conta subito, mon! Tu rendi Pele'keiki così felice che lui dice a tutti: $N $Gil miglior raccoglitore:la miglior raccoglitrice; di firebloom di sempre! Pele'keiki non vede l'ora che comincia la guerra. Adesso sì che illuminiamo il cielo sopra Silithus, vero, $Gfratello:sorella;?!",
  en_title = "The Horde Needs More Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8582] = {
  title = "L'Orda Ha Bisogno di Fiori di Loto Purpureo!",
  desc = "Il loto purpureo, $C, è un reagente di moltissime pozioni, elisir e oli, alcuni dei quali ci saranno utili ad Ahn'Qiraj. Dovremo preparare un numero enorme di queste pozioni per lo sforzo bellico. E farò anche degli esperimenti per trovare altri usi per il loto. Ma per fare tutto questo mi servirà una grande quantità di questo fiore.$B$BEd è qui che entri in gioco tu. Va' sul campo e raccogli quanti più fiori di loto purpureo puoi. È una cosa che sei $Gdisposto:disposta; a fare per noi?",
  obj = "Porta 20 Purple Lotus ad Apothecary Jezel, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con il loto purpureo che ti ho chiesto, $C? È fondamentale che tu lo faccia il più tempestivamente possibile, se non vuoi che tutto ciò che sto tentando qui finisca nel nulla.",
  reward = "Uno sforzo encomiabile, $C. Misurerò questi campioni per stabilirne l'uso più adatto e annoterò il tuo contributo. Poi il loto purpureo andrà conservato come si deve finché non sarò pronta a usarlo. Quanto a te, se sei ancora disponibile, immagino che mi servirà altro loto purpureo. Ripassa da me tra un momento.",
  en_title = "The Horde Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8583] = {
  title = "L'Orda Ha Bisogno di Altri Fiori di Loto Purpureo!",
  progress = "In effetti pare proprio che ci serva ancora altro loto purpureo, $C. Anche se i miei studi non hanno ancora individuato un nuovo impiego utile per quest'erba, ci sono metodi collaudati ancora da applicare.$B$BHo bisogno che tu vada di nuovo sul campo a raccogliere almeno venti campioni di loto purpureo. Riportali qui da me.",
  reward = "Un lavoro eccellente e preciso, $N. La tua diligenza merita un encomio, e così la tua rapidità. Mi assicurerò di persona che nessuno di questi fiori di loto purpureo vada sprecato.$B$BGrazie ancora, e se ti capita di trovare altro loto purpureo, non esitare a portarmelo con la massima urgenza.",
  en_title = "The Horde Needs More Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8584] = {
  title = "Non Chiedermi Mai dei Miei Affari",
  desc = "Se c'è una cosa che devi sapere di me, è questa: non chiedermi MAI dei miei affari! Io lavoro con cose che tu non puoi proprio capire. Per esempio: lo sai cos'è un muzzledorf psicotronico? Certo che no! Ed è per questo che a fare i piani ci penso io e ad andare a prendere le cose ci pensi tu.$B$BCome ho già detto, perché la cosa funzioni ci serve un pollo da 500 libbre.$B$BVai a Gadgetzan e parla con Dirge Quikcleave — ti aiuterà lui a cominciare la ricerca di un esemplare adatto.",
  obj = "Narain Soothfancy, a Tanaris, vuole che parli con Dirge Quikcleave a Gadgetzan.",
  reward = "<Dirge si gratta la testa.>$B$BUn pollo da 500 libbre? Non esiste! Non più, almeno. Di un pollo così avevo sentito parlare... Il Pollo Nero della Morte...$B$B<La voce di Dirge si spegne.>$B$BMa sì, nessuno che abbia visto quel pollo è vissuto per raccontarlo. Ho un'idea che potrebbe far comodo a tutti e due, $Gragazzo:ragazza;.",
}
T[8585] = {
  title = "L'Isola del Terrore!",
  desc = "La leggenda narra che i chimaerok dell'Isola del Terrore, a Feralas, abbiano la ciccia più succulenta e tenera che esista! Ora, questi chimaerok hanno anche un paparino che, preparato a dovere, potrebbe anche somigliare, o forse no, a un pollo da 500 libbre.$B$BVai sull'Isola del Terrore, uccidi Lord Lakmaeran e portami la sua carcassa fresca. Questo dovrebbe accontentare lo gnomo. Per accontentare me, dovrai mettere le mani su un po' di filetto di chimaerok.$B$BFallo e avrai il tuo pollo da 500 libbre e qualcosina in più.",
  obj = "Recupera Lakmaeran's Carcass e 20 Chimaerok Tenderloins per Dirge Quikcleave a Tanaris.",
  progress = "Mmmmm... Chimaerok...",
  reward = "Guarda che marezzatura hanno questi filetti! Fantastico!$B$BOra, quanto a quel pollo... Hmm, fammi pensare. Mi servono alcuni minuti per mettere a punto la ricetta.",
}
T[8586] = {
  title = "Braciole Caustiche di Chimaerok alla Dirge",
  desc = "La mia ricetta è completa! Adesso da te mi servono del carburante per razzi e del sale di rocciafonda. Alle spezie ci penso io, e per il resto basta la carne che mi hai portato.$B$BQuando mi avrai portato quello che ti ho chiesto, il pollo sarà pronto per essere riportato a Narain.",
  obj = "Dirge Quikcleave, a Gadgetzan, vuole che gli porti 20 Goblin Rocket Fuel e 20 Deeprock Salt.",
  progress = "Sbrigati, $Gragazzo:ragazza;. Non vogliamo che questa carne vada a male.",
  reward = "È pronto! Ti presento la mia più grande creazione: le Braciole Caustiche di Chimaerok alla Dirge!",
}
T[8587] = {
  title = "Ritorno da Narain",
  desc = "Sono un goblin di parola, $Gragazzo:ragazza;. Ecco il tuo pollo da 500 libbre.$B$BCosa se ne faccia uno gnomo di un pollo da 500 libbre, non lo saprò mai...$B$B<Dirge borbotta qualcosa di incomprensibile.>$B$BPer dormirci dentro, probabilmente... Luridi gnomi...",
  obj = "Consegna il 500 Pound Chicken a Narain Soothfancy a Tanaris.",
  progress = "Cos'è questo profumino delizioso?",
  reward = "<Narain affonda entrambi i pugni nell'enorme pollo e si riempie la bocca con la deliziosa prelibatezza di Dirge.>$B$BMMmmm... È incredibile! Il miglior pollo che abbia mai mangiato!",
}
T[8588] = {
  title = "L'Orda Ha Bisogno di Cuoio Pesante!",
  desc = "Visto che ci stiamo preparando alla guerra, forse è meglio procurarci prima tutta la roba che ci serve, non credi, mon? Uno dei materiali base delle forniture belliche che stiamo producendo è il cuoio pesante. Lo useremo praticamente per tutto, dai rinforzi alle armature, fino ai buoni vecchi teloni.$B$BMa prima dobbiamo procurarcene dell'altro. E questo è compito tuo, $C. Affila il coltello e riportamene un fascio. Poi ne riparleremo.",
  obj = "Porta 10 Heavy Leather a Skinner Jamani, nella Valley of Spirits di Orgrimmar.",
  progress = "Non ho tempo per i giochetti, se sei qui solo per chiacchierare, $C. Ci sono troppe pile di cuoio pesante da conciare. Torna quando ne avrai almeno dieci per me.",
  reward = "Oh, allora ce l'hai davvero il cuoio pesante che mi serviva. La tua lama è proprio affilata, $C: queste sono belle pelli! Ora che siamo partiti con il piede giusto, farò in modo che il tuo contributo venga usato bene. E se ti capita di trovare altro cuoio pesante, portalo da me.",
  en_title = "The Horde Needs Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8589] = {
  title = "L'Orda Ha Bisogno di Altro Cuoio Pesante!",
  progress = "È vero, $C, mi serve ancora altro cuoio pesante. Le richieste dei generali e dei loro furieri sembrano non finire mai. E non è niente in confronto a quello che chiedono i maestri degli zeppelin!$B$BDevo mettere insieme la mia quota in fretta. $N, portami altre pile di cuoio pesante il prima possibile!",
  reward = "Sei $Gil migliore:la migliore;, mon! Grazie mille per il cuoio pesante. Anche il più piccolo contributo ci avvicina un po' di più. Lo metto subito in pila, così gli altri conciatori possono metterci mano.$B$BGrazie ancora, $N, e se trovi altre pile di cuoio pesante, sai dove trovarmi.",
  en_title = "The Horde Needs More Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8590] = {
  title = "L'Orda Ha Bisogno di Cuoio Spesso!",
  desc = "Sono contenta che tu abbia deciso di parlarmi di questa faccenda, $C. Pare che i preparativi dell'Orda per la guerra di Ahn'Qiraj siano in pieno svolgimento. Ma tu e io dobbiamo ancora fare la nostra parte.$B$BMi hanno chiesto di raccogliere una gran quantità di pelli di cuoio spesso da usare per ogni genere di materiale bellico, e ho bisogno che tu mi aiuti andando là fuori a raccoglierle. Se deciderai di aiutarmi, ne avrai in cambio onore e la gratitudine dell'Orda. Lo farai?",
  obj = "Porta 10 Thick Leather a Sergeant Umala, nella Valley of Spirits di Orgrimmar.",
  progress = "$C, sei già $Gtornato:tornata; con i dieci pezzi di cuoio spesso di cui avevamo parlato?",
  reward = "Bel lavoro, $C. Sono sicura che queste pelli di cuoio spesso serviranno a rinforzare gli zeppelin e a fare ogni genere di armature e armi. Ti ringrazio, a nome mio e dell'Orda. Torna ancora se nei tuoi viaggi trovi altro cuoio spesso, e che la fortuna sia con te.",
  en_title = "The Horde Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8591] = {
  title = "L'Orda Ha Bisogno di Altro Cuoio Spesso!",
  progress = "$C, come vedi devo ancora raccogliere altro cuoio spesso. Ancora una volta ti chiedo aiuto in questo compito, e ti prometto che, se lo porterai a termine, i tuoi sforzi saranno riconosciuti.$B$BIl tempo stringe! Torna da me con il cuoio spesso, così potremo finire i preparativi e andare in guerra, $Geroe:eroina;!",
  reward = "Ce l'hai fatta, $N, lo sapevo! Ancora una volta, grazie a nome di tutta l'Orda. Ho preso nota dei tuoi sforzi, e sono molto apprezzati. E se ti ritrovi con altro cuoio spesso da donare, portalo qui da me.$B$BLok'tar Ogar, $C!",
  en_title = "The Horde Needs More Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8595] = {
  title = "Campioni Mortali",
  progress = "Uccidere un signore Qiraji è un'impresa notevole per un mortale, $N. Sono però numerosi e potenti. Continua a sconfiggerli per dimostrare il tuo valore come $Gnostro campione:nostra campionessa;.",
  reward = "Continui a servirci bene, $N. Il nostro patto resta in vigore.",
}
T[8597] = {
  title = "Draconico per Negati",
  desc = "Lo sapevo che quel libro prima o poi sarebbe tornato utile! Per fortuna ho avuto l'intelligenza e la lungimiranza di metterlo al sicuro.$B$BNon preoccuparti, è in un posto dove nessuno potrebbe mai sperare di trovarlo! La prima volta mi è servito un girocottero solo per arrivarci. Purtroppo sulla via del ritorno l'ho fatto schiantare sulla spiaggia. È stato grazie a quell'incidente che ho acquisito questi poteri psichici sovragnomici!$B$BCerca il mio girocottero schiantato da qualche parte sull'Ultima Spiaggia e da lì nuota verso sud! Riconoscerai il punto quando lo vedrai!",
  obj = "Trova il libro di Narain Soothfancy, sepolto su un'isola nei South Seas.",
  reward = "Il libro è sparito! In cima al mucchio di terra c'è un biglietto.",
}
T[8598] = {
  title = "rIsCaTt0",
  desc = "<Il testo di questo biglietto è composto da caratteri di vario tipo incollati sulla pergamena.>$B$BAbbiamo il tuo prezioso libro, gnomo. Se vuoi rivederlo, farai esattamente quello che ti chiediamo.$B$B<Segue un elenco dettagliato di istruzioni, lungo 3 pagine.>$B$BPorta i soldi e vieni da solo!",
  obj = "Riporta la Ransom Letter a Narain Soothfancy a Tanaris.",
  progress = "Di' un po', cosa c'è che non va?",
  reward = "<La faccia di Narain si accende di un rosso vivo.>$B$BMi librapiscono il... libro, eh!? Gli insegno io cosa vuol dire mettersi contro uno gnomo sensitivo!",
}
T[8599] = {
  title = "Canzone d'Amore per Narain",
  desc = "Non mi capita spesso di ricevere visite. Anzi, l'ultima volta che ho avuto una visita è stata quando ho salvato quel caro, dolce gnomo dai rottami della macchina volante precipitata.$B$B<Meridith fissa il vuoto, persa in un ricordo.>$B$BLo conosci? Narain? Narain Soothfancy? Oh, per me significherebbe tantissimo se qualcuno gli portasse un messaggio da parte mia. Devo dirgli cosa provo! Lo so che è amore! Lo so e basta!$B$BPotresti portare tu un messaggio a Narain? Ti sarei debitrice per sempre!",
  obj = "Porta Meridith's Love Letter a Narain Soothfancy a Tanaris.",
  progress = "Puzzi di pesce!",
  reward = "Cosa!?$B$B<Narain comincia ad agitarsi.>$B$BBe', ehm... Cosa vuoi che faccia??? È un pesce! Un PESCE, ti dico! E io sono uno gnomo. Non potrebbe mai funzionare.",
}
T[8600] = {
  title = "L'Orda Ha Bisogno di Cuoio Duro!",
  desc = "Trovo che il modo in cui il coltello si adatta al palmo conti più del suo filo. Anche la lama più smussata può tagliare, se la pressione viene applicata nel modo giusto, non credi, $C? Ma tu e io non abbiamo di questi problemi, visto che teniamo le lame più affilate, vero?$B$BBe', non importa, ho un compito per te. Al servizio dell'Orda, e per fare la tua parte nello sforzo bellico di Ahn'Qiraj, voglio che tu torni da me con un certo numero di pelli di cuoio duro. È una cosa che farai, no?",
  obj = "Porta 10 Rugged Leather a Doctor Serratus, nella Valley of Spirits di Orgrimmar.",
  progress = "Non è possibile che ti ci voglia tanto per tagliarmi dieci pezzi di cuoio duro! Forse dovresti affilare il coltello da scuoiatura? O forse mi sbaglio e ce li hai lì nello zaino?",
  reward = "Molto bene, pare che tu abbia fatto un lavoro abbastanza decente, anche se alcune di quelle pelli sono un po' sfilacciate ai bordi. Non importa, il compito è fatto, e ti sei $Gguadagnato:guadagnata; la ricompensa. Se ti capita di trovare un'altra pila di cuoio duro, portamela senza indugio.",
  en_title = "The Horde Needs Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8601] = {
  title = "L'Orda Ha Bisogno di Altro Cuoio Duro!",
  progress = "I preparativi per l'imminente guerra ad Ahn'Qiraj procedono, $C. Tuttavia, per essere sicuri di non restare indietro, o almeno per non essere io quello che ci fa restare indietro, voglio che tu mi riporti un'altra pila di cuoio duro. Ti sarò molto grato se te ne occuperai subito, $N.",
  reward = "Esercizio, esercizio, esercizio. Un coltello ben affilato e l'abilità di usarlo ti porteranno lontano in questo mondo, $N. Mi sembra che queste pelli abbiano i bordi migliori dell'ultima volta. Ti sei $Gcomprato:comprata; un coltello nuovo?$B$BIn ogni caso, ti ringraziamo per i tuoi sforzi. Abbiamo preso nota della tua donazione, e ti assicuro che verrà usata bene. Se ti ritrovi con altro cuoio duro, torna pure a parlarmi, perché probabilmente mi servirà.",
  en_title = "The Horde Needs More Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8604] = {
  title = "L'Orda Ha Bisogno di Bende di Wool!",
  desc = "Salve, $C. In vista della guerra ad Ahn'Qiraj, sono qui a coordinare gli sforzi dell'Orda per raccogliere bende di wool. Purtroppo, sul campo, i nostri soldati non possono contare sulla presenza di un guaritore che li tenga in vita. Credimi, lo so per esperienza. Per questo stiamo preparando per loro tutte queste cassette di pronto soccorso.$B$BSe hai tempo, mi servono molte bende di wool. Riportamele qui e farò in modo che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Wool Bandage a Healer Longrunner, nella Valley of Spirits di Orgrimmar.",
  progress = "Ah, $C, sei già $Gtornato:tornata; con le bende di wool?",
  reward = "Ti ringrazio, a nome mio e dell'Orda, $C. Se trovi altre bende di wool e vuoi contribuire ancora allo sforzo bellico, portamele qui. Fino ad allora, che i tuoi antenati veglino su di te!",
  en_title = "The Horde Needs Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8605] = {
  title = "L'Orda Ha Bisogno di Altre Bende di Wool!",
  progress = "Che piacere rivederti, $C. Stiamo ancora lavorando ai preparativi per lo sforzo bellico, e mi fa ancora comodo tutto l'aiuto che puoi darmi per raccogliere bende di wool. Qualsiasi aiuto sarà molto apprezzato. Spero solo che i nostri sforzi bastino. Ho perso troppe anime nobili sui campi di battaglia del passato per non fare tutto quello che posso perché non succeda di nuovo.",
  reward = "Sei $Gun:una; $C d'onore, $N! Farò in modo che queste bende arrivino nelle mani giuste. Ti ringrazio, a nome mio e dell'Orda.$B$BVa' in pace, e torna da me se ti ritrovi con bende di wool in più. Qui ci serve tutto l'aiuto possibile.",
  en_title = "The Horde Needs More Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8606] = {
  title = "Esca!",
  desc = "Ci sono! Ecco cosa faremo. Io riempio un sacco di sassi e tu fai la consegna. Lo so che c'era scritto che la consegna dovevo farla io, e la farò — più o meno.$B$B<Narain ti squadra da capo a piedi.>$B$BSì, andrai benissimo. Prendi questo turbante, questa veste e il sacco di sassi e vai al punto di consegna a Winterspring.$B$BIn questo kit speciale ho messo tutto quello che ti serve. Quando si presentano a ritirare la merce, falli fuori! Così imparano a mettersi contro Narain!",
  obj = "Narain Soothfancy, a Tanaris, vuole che tu vada a Winterspring e metta la Bag of Gold nel punto di consegna indicato dai librapitori.",
  reward = "Mi sa che abbiamo sottovalutato questi librapitori.",
}
T[8607] = {
  title = "L'Orda Ha Bisogno di Bende di Mageweave!",
  desc = "Confido che tu mi stia parlando perché intendi aiutarmi con la raccolta che mi è stata affidata? Bene! Con qualunque mezzo, e intendo davvero qualunque, desidero che tu raccolga un buon numero di bende di mageweave. Meglio se fresche, ma non è indispensabile. Riportamele qui, $C, e mi assicurerò di persona che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Mageweave Bandage a Lady Callow, nella Valley of Spirits di Orgrimmar.",
  progress = "Non fallire e non farmi fare brutta figura, $C! Torna qui il prima possibile con le bende di mageweave di cui abbiamo parlato.",
  reward = "Sorprendente, eppure accettabile. Forse ho sottovalutato le tue \"capacità\", $C. Forse. Hai portato a termine un compito molto semplice, e per questo verrai $Gricompensato:ricompensata; in modo sproporzionato. Ma non montarti la testa. Se vuoi davvero dimostrare il tuo valore, dovresti andare là fuori e portarmi un altro fascio di bende di mageweave.",
  en_title = "The Horde Needs Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8608] = {
  title = "L'Orda Ha Bisogno di Altre Bende di Mageweave!",
  progress = "Sei $Gtornato:tornata;? Interessante. Come vedi, sto ancora raccogliendo per lo \"sforzo bellico\" di Ahn'Qiraj. Il che significa che ho bisogno che tu vada di nuovo a raccogliere una pila di bende di mageweave per me. Attendo il tuo ritorno, $C.",
  reward = "Stupefacente, $C, ce l'hai fatta davvero di nuovo! Be', dicono che ho buon gusto nello scegliere chi mettere al mio servizio. Molto bene, il tuo contributo è stato annotato e riceverai i vantaggi sociali che i tuoi sforzi ti hanno procurato. Ti suggerisco però di tornare là fuori a raccogliere un altro fascio ancora di bende di mageweave, se vuoi davvero dimostrare quanto vali.",
  en_title = "The Horde Needs More Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8609] = {
  title = "L'Orda Ha Bisogno di Bende di Runecloth!",
  desc = "Pare inevitabile che l'Orda e l'Alleanza siano in rotta verso la guerra ad Ahn'Qiraj. Sorprendentemente, non è una guerra tra loro, ma contro i silitidi e qualunque forza li controlli. E, cosa altrettanto sorprendente, entrambi gli schieramenti stanno facendo la loro parte per raccogliere le risorse necessarie a combattere una guerra vittoriosa.$B$BRaccolgo bende di runecloth da distribuire ai soldati, ma senza aiuto non ci riuscirò, e spero che sia il tuo. Puoi aiutarmi in questo, $C?",
  obj = "Porta 20 Runecloth Bandage a Stoneguard Clayhoof, nella Valley of Spirits di Orgrimmar.",
  progress = "La guerra arriverà presto, credo, $C. Ti ringrazio per il tempo e l'impegno che dedichi ad aiutarci nelle raccolte. Sei $Gtornato:tornata; perché hai trovato le bende di runecloth di cui abbiamo parlato?",
  reward = "Fai onore all'Orda, $C. Grazie per i tuoi sforzi: sono apprezzati! Dovrò mettere via queste bende fresche e rifare il conto per vedere quanto siamo vicini al nostro obiettivo. Se vuoi, puoi raccogliere altre bende di runecloth e riportarmele qui.",
  en_title = "The Horde Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8610] = {
  title = "L'Orda Ha Bisogno di Altre Bende di Runecloth!",
  progress = "Si avvicina sempre di più il momento in cui ci getteremo a capofitto nella conflagrazione di Ahn'Qiraj, $Gsacerdote:sacerdotessa;. Ma prima dobbiamo raccogliere le forze e prepararci, per poter sopravvivere all'assalto degli insetti e dei loro padroni.$B$BSe sei di nuovo qui, di certo vuoi fare un'altra donazione di bende di runecloth allo sforzo bellico? Ti prego, fallo appena puoi e torna ancora da me.",
  reward = "Il tuo è un gesto di generosità davvero disinteressato, $N. Un gesto che probabilmente salverà la vita a molti combattenti ad Ahn'Qiraj. Grazie, e sappi che l'Orda ti è grata per la tua donazione. Se prepari, o trovi, altre bende di runecloth, ti prego, pensa a portarmele qui.",
  en_title = "The Horde Needs More Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8611] = {
  title = "L'Orda Ha Bisogno di Controfiletti di Lupo!",
  desc = "Non sto qui solo per prendere un po' di sole, $C. Ci sono dei preparativi di guerra da fare. Se vogliamo schiacciare quegli insetti ad Ahn'Qiraj, dobbiamo essere pronti, e questo vale anche per il cibo!$B$BMi hanno messo qui a raccogliere e salare bistecche magre di lupo per la guerra in arrivo. Ma visto che devo restare qui a occuparmi di tutto questo, ho bisogno che tu vada là fuori, uccida qualche lupo, cucini la carne per farne bistecche magre di lupo e me le riporti qui. Tutto chiaro?",
  obj = "Porta 20 Lean Wolf Steak a Bloodguard Rawtar, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con quelle bistecche magre di lupo, $C? Non m'importa se sono troppo cotte o crude, basta che siano saporite e che me le porti in fretta!",
  reward = "Ok, questa pila di carne mi sembra buona. Salerò le bistecche, poi le metterò via, e speriamo che restino abbastanza fresche da essere mangiabili quando sarà il momento.$B$BGrazie per il contributo, $C. Pensi di potermene portare un'altra infornata?",
  en_title = "The Horde Needs Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8612] = {
  title = "L'Orda Ha Bisogno di Altri Controfiletti di Lupo!",
  progress = "Come vedi, $C, dobbiamo ancora mettere via altro cibo per i soldati. Non so se tu sia mai $Gstato:stata; in guerra, ma una volta superato lo shock iniziale del campo di battaglia, può venire una gran fame. L'ultima volta hai fatto un buon lavoro, quindi mi aspetto che farai altrettanto bene, se non un po' più in fretta, portandomi un'altra pila di quelle bistecche magre di lupo.",
  reward = "Dall'odore, tu, o qualcuno che conosci, ci sai proprio fare ai fornelli, $N. Queste bistecche magre di lupo mi fanno venire l'acquolina in bocca; immagino che se ne sparisce qualcuna nessuno se ne accorgerà. Comunque, bel lavoro. Farò in modo che qualcuno le metta via come si deve, così non si guasteranno troppo.$B$BSe ne trovi altre, sai dove trovarmi.",
  en_title = "The Horde Needs More Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8613] = {
  title = "L'Orda Ha Bisogno di Pinnagialla Maculato al Vapore!",
  desc = "È proprio una bella giornata per pescare, non trovi, mon? Meno male, perché a me mi sa che mi serve un sacco di pesce. L'Orda, loro mi chiedono di pensarci io a raccogliere una montagna di pinnagialla maculato per loro. Dicono che gli serve per la guerra che si stanno preparando ad Ahn'Qiraj. Io gli dico che faccio del mio meglio. Allora mi serve un po' d'aiuto. Tu mi aiuti, $C?",
  obj = "Porta 20 Spotted Yellowtail a Fisherman Lin'do, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno col pinnagialla maculato, $C? Ti sei $Gricordato:ricordata; di cucinarlo bello per bene? Noi pesce crudo ai soldati sotto il sole caldo del deserto non lo serviamo mica, sicuro.",
  reward = "Oh sì, questa è roba buona. Io lo impacchetto bello per bene, così non va sprecato. Grazie a te che mi aiuti così. Io dico che tu sei $Gun pescatore:una pescatrice; numero uno, con tutto questo pinnagialla maculato. E se ti capita di pescarne e cucinarne ancora, tu portalo qui da me: io faccio sapere a tutti che sei $Gstato:stata; tu!",
  en_title = "The Horde Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8614] = {
  title = "L'Orda Ha Bisogno di Altro Pinnagialla Maculato!",
  progress = "Come vedi, a noi ci servono ancora un sacco di pescetti. Quelli che combattono nella Guerra di Ahn'Qiraj che sta per arrivare avranno bisogno di tanta roba da mangiare, così io devo prendere tutti i pinnagialla maculati che posso. Tu li peschi, li cucini e me li riporti qua, e io ti dico grazie, e con me ti dice grazie pure l'Orda.",
  reward = "È la pescata migliore finora, $N! Questo sì che è lavoro buono e onesto. E niente lische, pure! Tante grazie a te per questo pinnagialla maculato, mon. Torna presto, se ne cucini ancora!",
  en_title = "The Horde Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8615] = {
  title = "L'Orda Ha Bisogno di Salmone Impanato!",
  desc = "Lo sforzo bellico di Ahn'Qiraj è un'impresa immensa, $C. Tutti i materiali che si raccolgono qui, che siano metallo per le armi o cibo da mangiare, sono importanti allo stesso modo. Perché, se non mangi da giorni, non avrai la forza di sollevare l'ascia quando conta.$B$BPer questo raccogliamo tutto il cibo che possiamo. Io raccolgo salmone al forno, un piatto scelto perché è nutriente e perché si conserva bene. Puoi aiutarmi in questo compito, $C?",
  obj = "Porta 20 Baked Salmon a Chief Sharpclaw, a Valley of Spirits di Orgrimmar.",
  progress = "Gli spiritelli sfreccianti possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi di solito si rintanano anche loro nelle foreste.$B$BQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne $Gcerto:certa;!",
  reward = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.$B$BIl viaggio non è stato troppo pericoloso, spero? La zona di Feralas non è famosa per la sua clemenza, ma è chiaro che te la sei cavata bene.$B$BGrazie ancora, $C.",
  en_title = "The Horde Needs Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8616] = {
  title = "L'Orda Ha Bisogno di Altro Salmone Impanato!",
  progress = "L'ultima partita di salmone al forno che hai donato allo sforzo bellico aveva un aspetto davvero delizioso, $C. Devo ammettere che sono stato tentato di prenderne un po' per me. Come vedi, non abbiamo ancora raggiunto la nostra quota. Spero che tu sia $Gtornato:tornata; perché hai con te un altro carico di salmone al forno",
  reward = "Il tempo e l'energia che doni allo sforzo bellico vanno ben oltre il dovuto, $N. Ti assicuro che le tue fatiche non sono passate inosservate. Ti ringrazio, a nome mio e dell'Orda. Torna ancora da me se ne cucini un'altra partita.",
  en_title = "The Horde Needs More Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8617] = {
  title = "L'Orda Ha Bisogno di Corestone Carbonizzate!",
  desc = "È arrivato il momento che tu contribuisca allo sforzo bellico di Ahn'Qiraj, $C. Sono finiti i giorni sereni passati a oziare. Ora è il momento di servire me e l'Orda, e ti assicuro che non sono indulgente quanto il Capoguerra.$B$BRadunerai le tue forze, una gilda se ne hai una, e invaderai il Molten Core. Lì dentro scoprirai che chi lo abita ha delle corestone carbonizzate. Riportamele in grandi quantità.",
  obj = "Porta 50 Singed Corestone a General Zog, a Durotar.",
}
T[8619] = {
  title = "Morndeep l'Anziano",
  reward = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Morndeep the Elder",
}
T[8620] = {
  title = "L'Unica Cura",
  desc = "Avrei dovuto saperlo. Il mio arcinemico, il Dottor Weavil, che ne combina un'altra delle sue! E adesso, grazie al tuo fallimento a Winterspring, il Dottor Weavil ha distrutto il mio libro! E ora come lo salvi il mondo, $Geroe:eroina;?$B$BNel biglietto che ho ricevuto c'era scritto che l'unica copia conosciuta di \"Draconico per Negati: Volume II\" è stata strappata in 8 parti, sparse ai quattro venti! Se in qualche modo riesci a trovare quei capitoli mancanti, usa questa rilegatura magica per rimetterli insieme e torna da me.",
  obj = "Recupera gli 8 capitoli perduti di Draconic for Dummies, uniscili con la Magical Book Binding e riporta il libro completo, Draconic For Dummies: Volume II, a Narain Soothfancy a Tanaris.",
  progress = "I pantaloni me li infilo proprio come te — una gamba alla volta. Solo che io, una volta infilati i pantaloni, costruisco boe d'arcanite. Boe d'arcanite, baby!",
  reward = "Fantastico! Non ci credo che ti sei $Gpreso:presa; tutto questo disturbo! Sei una specie di macchina? Fossi stato io, probabilmente avrei lasciato implodere il mondo e basta.$B$BTanto di turbante, $Gsignore:signora;. E nessuna buona azione dovrebbe restare senza ricompensa.",
}
T[8635] = {
  title = "Splitrock l'Anziano",
  reward = "Le battaglie delle ere passate sono semi da cui crescono le leggende. La tua è un'epoca di eroi, giovane. Che la tua leggenda metta radici e prosperi.$B$BTi auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Splitrock the Elder",
}
T[8636] = {
  title = "Rumblerock l'Anziano",
  reward = "Ciò che appartiene alla vita è destinato a morire e a tornare alla terra, ma ciò che appartiene allo spirito vive in eterno. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Rumblerock the Elder",
}
