T[8687] = {
  title = "Bersaglio: Perforatori di Hive'Zora",
  desc = "I rinforzi sono stati chiamati a unirsi all'assalto contro Hive'Zora. Sei $Gstato scelto:stata scelta; per colpire i perforatori di Hive'Zora. A compito concluso, fai rapporto al Comandante Mar'alith.",
  obj = "Uccidi 30 Hive'Zora Tunnelers, poi fai rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Combat Task Briefing VII.",
  progress = "Hai qualcosa da dirmi, $C?",
}
T[8688] = {
  title = "Windrun l'Anziano",
  reward = "Nelle loro innumerevoli stelle, i cieli custodiscono le risposte ai misteri della terra, $N. Potranno allora i saggi, e i fortunati, alzare lo sguardo e trovare la verità?",
  en_title = "Windrun the Elder",
}
T[8689] = {
  title = "Manto della Saggezza Infinita",
  desc = "Sono lieto di sapere che ci stai aiutando nell'attacco ad Ahn'Qiraj, $N. Posso farti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, $C.$B$BMi servirà un drappo Qiraji, che naturalmente adatterò alla tua taglia. Mi serviranno anche degli idoli e degli scarabei, con cui creerò un fermaglio adatto.$B$BTi prometto che non resterai $Gdeluso:delusa;.",
  obj = "Porta 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs e 5 Clay Scarabs a Keyl Swiftclaw a Silithus. Per completare questa missione devi anche ottenere la reputazione Revered con il Cenarion Circle.",
  progress = "Hai portato i materiali per il mantello, $N?",
  reward = "Ah, sì... questo drappo è immacolato.$B$BPrendi questo mantello, $N. Che ti protegga dalla magia immonda dei Qiraji.",
}
T[8690] = {
  title = "Mantello della Tempesta Crescente",
  desc = "Sono lieto di sapere che ci stai aiutando nell'attacco ad Ahn'Qiraj, $N. Posso farti un oggetto protettivo che ti sarà d'aiuto nella lotta contro il nostro nemico, $C.$B$BMi servirà un drappo Qiraji, che naturalmente adatterò alla tua taglia. Mi serviranno anche degli idoli e degli scarabei, con cui creerò un fermaglio adatto.$B$BTi prometto che non resterai $Gdeluso:delusa;.",
  obj = "Porta 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs e 5 Gold Scarabs a Keyl Swiftclaw a Silithus. Per completare questa missione devi anche ottenere la reputazione Revered con il Cenarion Circle.",
  progress = "Hai portato i materiali per il mantello, $N?",
