T[8697] = {
  title = "Anello della Saggezza Infinita",
  desc = "Si dice che gli anelli portati dai luogotenenti Qiraji conferiscano loro capacità formidabili. Le gemme corrotte che li adornano si potrebbero, in teoria, sostituire con materiali più puri per creare versioni non corrotte degli anelli.$B$BLe gemme che adornano gli idoli Qiraji andrebbero benissimo, perché sono di qualità superiore.$B$BPortami l'anello e gli idoli e creerò un anello potente per te, $C.",
  obj = "Porta 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs e 5 Bone Scarabs a Windcaller Yessendra a Silithus. Per completare questa missione devi anche raggiungere la reputazione Honored con il Cenarion Circle.",
  progress = "Mi hai portato l'anello e i materiali, $N?",
  reward = "Sostituirò per te la gemma dell'anello. Vedrai che l'effetto è molto più... gradevole.",
}
