T[8705] = {
  title = "Martelletto della Saggezza Infinita",
  desc = "I Qiraji e i loro servitori usano oggetti fatti con i materiali più rari e pregiati: ossa di gigantesche creature antiche, gemme dalle profondità della terra, metalli puri e resistenti.$B$BSolo a vedere i manufatti dei Qiraji mi viene voglia di mettermi all'opera sui loro frammenti, spezzati e fusi. Dimostra la tua fedeltà al Circle, $N, e con i migliori materiali dei Qiraji ti creerò un'arma potente.",
  obj = "Porta 1 Qiraji Ornate Hilt, 2 Lambent Idols, 5 Bronze Scarabs e 5 Ivory Scarabs a Warden Haro, a Silithus. Per completare questa missione devi anche raggiungere la reputazione Exalted con il Cenarion Circle.",
  progress = "Mi hai portato i componenti che mi servono, $N?",
  reward = "Hai fatto un buon lavoro, $C. Quest'elsa è un capolavoro... il bilanciamento è perfetto.$B$BPrendi la tua arma, $N. Impugnala con grande sicurezza e sconfiggi i nostri nemici!",
}
