T[8728] = {
  title = "La Buona Notizia e La Cattiva Notizia",
  desc = "Be', c'è voluto un po' più del previsto. Ora vediamo cosa dice questo libro mastro.$B$B<Narain legge il libro mastro in silenzio, borbottando ogni tanto sottovoce.>$B$B La buona notizia è che sono sicuro al 99% di essere in grado di creare una boa d'arcanite che funzioni secondo le tue specifiche. Questo, naturalmente, dipende in tutto e per tutto dalla cattiva notizia.$B$BLa cattiva notizia è che mi serviranno un sacco di arcanite, minerale di elementium e gemme rare.$B$BPortami quello che mi serve e costruirò la boa.",
  obj = "Narain Soothfancy, a Tanaris, vuole che gli porti 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds e 10 Blue Sapphires.",
  progress = "Le boe d'arcanite non si fanno mica da sole, $N. E NO, non puoi farti prestare dei soldi.",
  reward = "Un patto è un patto. Spero proprio che tu sappia in cosa ti stai cacciando, $N. È una fatica tremenda per andare un po' a pescare.",
}
T[8729] = {
  title = "L'Ira di Neptulon",
  desc = "Ti ho già detto della brutta notizia? Si chiama Maws: 100 piedi di morte e distruzione. Mi sa che quel dettaglino l'avevo dimenticato.$B$BSecondo la mia superiore chiaroveggenza psico-psionica, il punto migliore per lanciare questa boa è al largo della costa di Azshara, nella Baia delle Tempeste.$B$BCerca un maelstrom vorticoso, molto probabilmente pieno di relitti.$B$BA proposito, spero che tu abbia degli amici.$B$BE se per qualche miracolo dovessi farcela, porta il frammento dello scettro ad Anachronos.",
  obj = "Usa l'Arcanite Buoy allo Swirling Maelstrom a Bay of Storms, ad Azshara.",
  progress = "Il tempo sta per scadere, $Gcampione:campionessa;.",
  reward = "Ben fatto, $N. Presto potrò ricomporre lo Scettro delle Sabbie Mutevoli.",
}
T[8730] = {
  title = "La Corruzione di Nefarius",
  desc = "$GCampione:Campionessa;, sei tu? Sono passati mille anni da quando mi è stato affidato il frammento, ed è proprio nella mia ora più buia che qualcuno si fa avanti per liberarmene... Ma cosa sarebbe la tragedia senza la crudeltà?$B$B<Vaelastrasz tossisce debolmente.>$B$BNe... Nefarius ora ha il frammento dello scettro.$B$BIl tempo stringe. Nefarius vuole distruggere il frammento. Devi sbrigarti!",
  obj = "Uccidi Nefarian e recupera il Red Scepter Shard. Riporta il Red Scepter Shard ad Anachronos alle Caverns of Time, a Tanaris. Hai 5 ore per portare a termine questo incarico.",
  progress = "Un altro dei nostri eroi perduto per mano della progenie di Deathwing. Saremo condannati a questa sofferenza per sempre...",
  reward = "L'anima di Vaelastrasz è in pace, $Gcampione:campionessa;. Tutti gli Aspetti seguono i tuoi progressi con grande interesse. Sappi che hai alleati potenti.$B$BMi è stato ordinato di concederti qualcosa che ti aiuti in questa lotta. Fanne buon uso...",
}
T[8731] = {
  title = "Servizio sul Campo",
  desc = "Salute, $N. Prima di assegnarti compiti più impegnativi in questa guerra, dovrai fare la tua parte di servizio sul campo.$B$BTroverai la Legione di Orgrimmar del Capitano Skullsplit fuori da Hive'Regal.$B$BPresentati a lui e torna da me con la prova del tuo servizio sul campo. Avrò pronto per te un incarico più avanzato.$B$BAh, ti prego, fai del tuo meglio per stare alla larga dall'Ironforge Brigade. C'è molta tensione fra i nostri volontari dell'Alleanza e dell'Orda.",
  obj = "Presentati a Krug Skullsplit alla postazione della Legione di Orgrimmar davanti a Hive'Regal. Prepara i tuoi Unsigned Field Duty Papers, ottieni i Signed Field Duty Papers e portali a Windcaller Kaldon a Cenarion Hold.$B$BNota: curare un membro della Legione di Orgrimmar o lanciargli incantesimi benefici ti attiverà il PvP.",
  progress = "Hai completato il tuo servizio sul campo, $N? Il Capitano Skullsplit si trova fuori da Hive'Regal.",
  reward = "Si vede che Krug non sa che farsene delle scartoffie. Questo l'ha firmato col sangue di silithid!$B$BMolto bene, $N. Ho preparato una serie di compiti che dovrebbero mettere a frutto le tue capacità da $C.$B$BCon l'impegno costante tuo e di quelli come te, il nostro nemico sarà presto schiacciato!",
}
T[8732] = {
  title = "Documenti di Servizio sul Campo",
  progress = "Immagino che tu voglia farti firmare quei documenti, $Gragazzo:ragazza;?",
  reward = "Sì, immagino che di questi tempi quella scaramuccia da niente possa passare per servizio sul campo. Riporta questi a Cenarion Hold, di sicuro avranno pronto per te un lavoretto comodo.$B$BE ora fila!",
}
T[8733] = {
  title = "Eranikus, Tiranno del Sogno",
  desc = "Questo è un viaggio di redenzione, $Geroe:eroina;. Se anche oggi venissi ucciso, sarei morto per una causa giusta e retta. Devi recuperare il frammento di scettro verde. Devi purificare Eranikus dalla corruzione che gli Dei Antichi hanno gettato su di lui.$B$BRecati a Darnassus. Appena fuori dalle mura della città troverai uno dei miei agenti. Questo agente metterà in moto le cose per noi e informerà Tyrande dei nostri piani senza mettere in allarme Staghelm.$B$B<Malfurion sospira.>$B$BUna caduta in disgrazia maturata in mille anni...",
  obj = "Recati nel continente di Teldrassil e trova l'agente di Malfurion da qualche parte fuori dalle mura di Darnassus.",
  reward = "Il fuoco fatuo tace, a parte un ronzio sommesso. Stranamente, riesce a comunicare con te attraverso i pensieri.",
}
T[8734] = {
  title = "Tyrande e Remulos",
  desc = "Tyrande sarà avvisata, mortale. Shan'do Stormrage mi ha $Gpreparato:preparata; per questa evenienza.$B$BOra devi andare nel Moonglade a parlare con Remulos. Ti darà altre istruzioni per l'evocazione di Eranikus.$B$BTi auguriamo tutti buona fortuna.",
  obj = "Raggiungi il Moonglade e parla con Keeper Remulos.",
  reward = "Sarebbe impossibile strappare Eranikus al Sogno, se si rifiutasse. Però le sue intenzioni lo obbligano a entrare nel nostro mondo. Cerca di distruggere la manifestazione vivente di Malfurion. Se ci riuscisse, sarebbe la fine di uno dei più potenti alleati del Sogno. Se Malfurion cadesse, l'Incubo consumerebbe completamente tutto ciò che resterebbe...",
  en_title = "Tyrande and Remulos",
  en_obj = "Travel to the Moonglade and speak to Keeper Remulos. ",
}
T[8735] = {
  title = "La Corruzione dell'Incubo",
  desc = "Devi recarti ai quattro portali del sogno di Azeroth. Da ognuno devi estrarre un frammento della corruzione dell'Incubo. I dragonkin che abitano quelle zone avranno con sé questi frammenti. Torna da me quando avrai raccolto questi frammenti.",
  obj = "Recati ai quattro portali dell'Emerald Dream ad Azeroth e raccogli un Fragment of the Nightmare's Corruption da ognuno. Torna da Keeper Remulos a Moonglade quando avrai completato questo incarico.",
  progress = "<Remulos è profondamente assorto nei suoi pensieri.>",
  reward = "Sei $Gpronto:pronta;? Il mondo è pronto per ciò che stiamo per evocare? Non lo so... Sono legato a Malfurion dal dovere. Dovere e onore...",
}
T[8736] = {
  title = "L'Incubo si Manifesta",
  desc = "Con Eranikus dobbiamo trattenerci. Dobbiamo redimerlo, non distruggerlo.$B$BTyrande è già in viaggio per aiutarci in questo compito. Dobbiamo resistere ai colpi del drago e salvare Nighthaven da una distruzione certa.$B$BIn guardia! Tu e i tuoi alleati siete la nostra unica speranza.",
  obj = "Difendi Nighthaven da Eranikus. Non lasciare che Keeper Remulos muoia. Non uccidere Eranikus. Difenditi. Attendi Tyrande.",
  reward = "È redento, $N. Ora torna nel Sogno per riparare ai torti che lui solo ha commesso. Eranikus sarà un potente alleato per Malfurion e per mio padre.$B$BQuesti armamenti sono per te, $N; mi sono stati dati da Ysera in persona. Faresti bene a servirtene nelle tue battaglie contro i Qiraji.",
}
T[8737] = {
  title = "Templare di Zaffiro",
  desc = "Il Martello del Crepuscolo e i nobili elementali che venera sono una minaccia temibile per le nostre operazioni a Silithus. Con i nuovi nemici che stiamo affrontando dentro Ahn'Qiraj, non possiamo permetterci di abbassare la guardia con quelli che stanno fuori.$B$BTrova il modo di evocare e distruggere un Templare di Zaffiro e fai rapporto a Bor Wildmane.",
  obj = "Evoca e uccidi un Azure Templar, poi fai rapporto a Bor Wildmane a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing I.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Bel lavoro, $N. Ecco il tuo prossimo incarico.",
}
T[8738] = {
  title = "Rapporto dell'Esploratore di Hive'Regal",
  desc = "Abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid a raccogliere informazioni. L'Esploratore Landion osserva da diversi giorni i movimenti dei silithid a Hive'Regal. Trovalo e fatti dare un rapporto scritto. Dobbiamo poter agire in base a quelle informazioni il prima possibile, $N.",
  obj = "Contatta Cenarion Scout Landion dentro Hive'Regal e riporta l'Hive'Regal Scout Report a Windcaller Proudhorn, a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing VII.",
  progress = "Troverai l'Esploratore Landion dentro Hive'Regal. Sbrigati, $N! Non c'è tempo da perdere.",
  reward = "Apprezziamo molto il tuo impegno, $N. Leggo subito questi rapporti di esplorazione, tu intanto dai pure un'occhiata al tuo prossimo incarico.",
}
T[8739] = {
  title = "Rapporto dell'Esploratore di Hive'Ashi",
  desc = "Abbiamo mandato i nostri esploratori migliori nel cuore degli alveari dei silithid a raccogliere informazioni. L'Esploratrice Jalia osserva da diversi giorni i movimenti dei silithid a Hive'Ashi. Trovala e fatti dare un rapporto scritto. Dobbiamo poter agire in base a quelle informazioni il prima possibile, $N.",
  obj = "Contatta Cenarion Scout Jalia dentro Hive'Ashi e riporta l'Hive'Ashi Scout Report a Windcaller Proudhorn, a Cenarion Hold. Per completare la missione devi portare anche il Tactical Task Briefing VIII.",
  progress = "Troverai l'Esploratrice Jalia dentro Hive'Ashi. Sbrigati, $N! Non c'è tempo da perdere.",
  reward = "Apprezziamo molto il tuo impegno, $N. Leggo subito questi rapporti di esplorazione, tu intanto dai pure un'occhiata al tuo prossimo incarico.",
}
T[8740] = {
  title = "Predoni del Crepuscolo",
  desc = "Sono state avvistate bande di cultisti del Martello del Crepuscolo a cavallo, che si tengono fuori dalla portata delle nostre forze di Cenarion Hold ed eliminano una alla volta le nostre pattuglie e carovane più piccole.$B$BTrova e sconfiggi i predoni del crepuscolo insieme al loro capo, una terribile guerriera di nome Morna. A compito concluso, fai rapporto all'Invocatrice del Vento Proudhorn.",
  obj = "Uccidi Twilight Marauder Morna e 5 Twilight Marauders. A compito finito, fai rapporto a Windcaller Proudhorn. Per completare la missione devi portare anche il Tactical Task Briefing IX.",
  progress = "Hai già portato a termine il tuo compito, $N?",
  reward = "Ben fatto, $N. I predoni del crepuscolo stavano causando alle nostre pattuglie un numero inaccettabile di perdite. Ecco il tuo prossimo incarico.",
}
T[8741] = {
  title = "Il Campione Ritorna",
  desc = "Il custode attende il tuo ritorno, $N. Porta il frammento di scettro verde ad Anachronos, alle Caverns of Time.",
  obj = "Porta il Green Scepter Shard ad Anachronos alle Caverns of Time, a Tanaris.",
}
T[8742] = {
  title = "La Potenza di Kalimdor",
  progress = "Mille anni sono passati e, proprio come era destino, qualcuno è qui davanti a me. Qualcuno che guiderà il suo popolo verso una nuova era.$B$BIl Dio Antico trema, $N. Oh sì, teme la tua fede. Manda in frantumi la profezia di C'Thun.$B$BSa che stai arrivando, $Gcampione:campionessa; — e con te arriva la potenza di Kalimdor. Devi solo farmi sapere quando sei $Gpronto:pronta; e io ti concederò lo Scettro delle Sabbie Mutevoli.",
  reward = "Lo Scettro delle Sabbie Mutevoli è di nuovo integro, $N.$B$BDevi essere tu a usare lo scettro. Devi essere tu ad annunciare la prossima era del tuo popolo.$B$BDevi aspettare che gli eserciti dell'Orda e dell'Alleanza arrivino a Silithus prima di poter suonare il Gong dello Scarabeo.",
}
T[8743] = {
  title = "Suona il Gong!",
  progress = "Il Gong dello Scarabeo incombe minaccioso davanti a te. Fatti forza, $N; perché quando il Gong dello Scarabeo verrà suonato, i cancelli di Ahn'Qiraj si apriranno.$B$BDalle fauci dischiuse della bestia non possono uscire che caos e distruzione. Difendi il tuo popolo!",
  reward = "Dal terreno vicino al gong spunta un cristallo speciale. Forse un favore della Brood.",
}
T[8744] = {
  title = "Un Regalo Incartato con Cura",
  reward = "Sul biglietto di questo regalo c'è scritto:$B$BPer $N,$B$BChe la tua festa di Grande Inverno sia allegra e luminosa!",
  en_title = "A Carefully Wrapped Present",
}
T[8745] = {
  title = "Tesoro dell'Eterno",
  reward = "Salute, $Gcampione:campionessa;. Sono Jonathan, custode del gong sacro e guardiano eterno del Bronze Flight.$B$BL'Eterno in persona mi ha dato il potere di concederti un oggetto a tua scelta dal suo tesoro senza tempo. Che ti sia d'aiuto nelle tue battaglie contro C'Thun.",
}
T[8746] = {
  title = "Metzen la Renna",
  desc = "È successo un DISASTRO! Hanno rapito Metzen la Renna!$B$BMetzen è una delle otto renne di Great-father Winter — ed è proprietà della Smokywood Pastures. Abbiamo ricevuto non una ma DUE lettere di riscatto, da gruppi che sostengono di avere Metzen. Con la stagione delle feste ormai nel vivo, qui non possiamo staccarci dalla cassa! Ti prego — trova Metzen e riportacelo!$B$BCerca degli indizi nelle lettere di riscatto, e cospargilo di questa polvere di renna — lo libererà da qualunque cosa lo tenga legato!$B$BTi prego, fai presto!",
  obj = "Trova Metzen the Reindeer. Cerca nei biglietti che ti sono stati dati degli indizi sul luogo in cui è tenuto prigioniero.$B$BQuando trovi Metzen, devi avere con te il Pouch of Reindeer Dust per cospargerlo con un po' di polvere; questo dovrebbe liberare Metzen dai legami che lo tengono prigioniero.$B$BUna volta liberato Metzen, riporta il Pouch of Reindeer Dust a Kaymard Copperpinch a Orgrimmar.",
  progress = "$N! L'hai trovato? I biglietti nella borsa che ti ho dato bastavano per rintracciare Metzen? Non voglio neanche pensare a cosa potrebbero fargli quei crudeli delinquenti... ma un riscatto così esorbitante non possiamo proprio permetterci di pagarlo!",
  reward = "Ce l'hai fatta! Urrà!$B$BMetzen è tornato in volo alle stalle di Great-father Winter — sì, Metzen sa volare davvero — proprio poco fa! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Vigilia di Grande Inverno e anche la Smokywood Pastures. Grazie, $N.$B$BSenti... per quello che hai fatto, voglio darti questo. È una cosa DAVVERO speciale; se hai una cavalcatura, secondo me ti divertirai un mondo. Buona Vigilia di Grande Inverno!",
}
T[8747] = {
  title = "La Via del Protettore",
  reward = "Notevole, $Gpiccolo:piccola;. Hai affrontato molte fatiche per guadagnarti il favore del Bronze Flight. La tua dedizione non è passata inosservata.$B$BL'anello con sigillo del difensore offrirà una protezione superiore contro le forze del male.$B$BSappi che, una volta scelta la tua via, non ci sarà rimedio se dovessi cambiare idea.",
}
T[8748] = {
  title = "La Via del Protettore",
  progress = "La tua costante difesa dei figli di Kalimdor è stata riconosciuta. Dammi il tuo anello con sigillo, così che io possa accrescerne i poteri.",
  reward = "La tua ascesa tra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del protettore!",
}
T[8749] = {
  title = "La Via del Protettore",
  progress = "Tu onori la mia stirpe, $N. Abbatti i nemici di Kalimdor! Mostra loro cosa significa sfregiare la terra dell'eterna luce stellare.$B$BHai meritato un altro potenziamento. Dammi il tuo anello con sigillo, così che io possa rafforzarne il potere.",
  reward = "La tua ascesa tra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del protettore!",
}
T[8750] = {
  title = "La Via del Protettore",
  progress = "Una dedizione di questa portata è cosa rara. Hai dimostrato che la tua volontà è incrollabile, $N. Sarai $Gricompensato:ricompensata; generosamente per la tua salda vigilanza sul nostro mondo.$B$BDammi il tuo anello con sigillo, così che io possa rinforzarne l'incantamento.",
  reward = "La tua ascesa tra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del protettore!",
}
T[8751] = {
  title = "Il Protettore di Kalimdor",
  progress = "Non ho mai visto una simile tenacia! Il Bronze Flight ti concede un ultimo incantamento. Lo ha chiesto l'Eterno in persona!$B$BDammi il tuo anello con sigillo, così che io possa apportare le modifiche necessarie.",
  reward = "Alzati, $GProtettore:Protettrice; di Kalimdor! Alzati e ricevi gli onori!",
}
T[8752] = {
  title = "La Via del Conquistatore",
  reward = "Notevole, $Gpiccolo:piccola;. Hai affrontato molte fatiche per guadagnarti il favore del Bronze Flight. La tua dedizione non è passata inosservata.$B$BL'anello con sigillo del conquistatore potenzierà notevolmente i tuoi attacchi fisici.$B$BSappi che, una volta scelta la tua via, non ci sarà rimedio se dovessi cambiare idea.",
}
T[8753] = {
  title = "La Via del Conquistatore",
  progress = "La tua costante difesa dei figli di Kalimdor è stata riconosciuta. Dammi il tuo anello con sigillo, così che io possa accrescerne i poteri.",
  reward = "La tua ascesa tra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del conquistatore!",
}
T[8754] = {
  title = "La Via del Conquistatore",
  progress = "Onori la mia stirpe, $N. Abbatti i nemici di Kalimdor! Mostra loro cosa significa deturpare la terra dell'eterna luce stellare.$B$BHai meritato un altro potenziamento. Porgimi il tuo anello con sigillo, così potrò rafforzarne il potere.",
  reward = "La tua ascesa fra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del conquistatore!",
}
T[8755] = {
  title = "La Via del Conquistatore",
  progress = "Una dedizione così grande è cosa rara. Hai dimostrato che la tua volontà è incrollabile, $N. Riceverai una grande ricompensa per aver vegliato con fermezza sul nostro mondo.$B$BPorgimi il tuo anello con sigillo, così potrò potenziarne l'incantamento.",
  reward = "La tua ascesa fra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via del conquistatore!",
}
T[8756] = {
  title = "Il Conquistatore dei Qiraji",
  progress = "Non ho mai visto una simile tenacia! Il Bronze Flight ti concede un ultimo incantamento. Lo ha chiesto l'Eterno in persona!$B$BPorgimi il tuo anello con sigillo, così potrò apportare le modifiche necessarie.",
  reward = "Alzati, $GConquistatore:Conquistatrice; dei Qiraji! Alzati e ricevi il tuo riconoscimento!",
}
T[8757] = {
  title = "La Via dell'Invocatore",
  reward = "Notevole, $Gpiccolo:piccola;. Hai faticato molto per ottenere il favore del Bronze Flight. La tua dedizione non è passata inosservata.$B$BL'anello con sigillo dell'invocatore accrescerà di molto le tue capacità magiche e naturali.$B$BTi avverto, una volta scelta la tua via, non ci sarà rimedio se cambierai idea.",
}
T[8758] = {
  title = "La Via dell'Invocatore",
  progress = "La costanza con cui difendi i figli di Kalimdor è stata riconosciuta. Porgimi il tuo anello con sigillo, così potrò accrescerne i poteri.",
  reward = "La tua ascesa fra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via dell'invocatore!",
}
T[8759] = {
  title = "La Via dell'Invocatore",
  progress = "Onori la mia stirpe, $N. Abbatti i nemici di Kalimdor! Mostra loro cosa significa deturpare la terra dell'eterna luce stellare.$B$BHai meritato un altro potenziamento. Porgimi il tuo anello con sigillo, così potrò rafforzarne il potere.",
  reward = "La tua ascesa fra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via dell'invocatore!",
}
T[8760] = {
  title = "La Via dell'Invocatore",
  progress = "Una dedizione così grande è cosa rara. Hai dimostrato che la tua volontà è incrollabile, $N. Riceverai una grande ricompensa per aver vegliato con fermezza sul nostro mondo.$B$BPorgimi il tuo anello con sigillo, così potrò potenziarne l'incantamento.",
  reward = "La tua ascesa fra i ranghi della Brood è davvero notevole, $N. Possa tu non allontanarti mai dalla via dell'invocatore!",
}
T[8761] = {
  title = "Il Grande Invocatore",
  progress = "Non ho mai visto una simile tenacia! Il Bronze Flight ti concede un ultimo incantamento. Lo ha chiesto l'Eterno in persona!$B$BPorgimi il tuo anello con sigillo, così potrò apportare le modifiche necessarie.",
  reward = "Alzati, Grande $GInvocatore:Invocatrice;! Alzati e ricevi il tuo riconoscimento!",
}
T[8762] = {
  title = "Metzen la Renna",
  desc = "È successo un DISASTRO! Hanno rapito Metzen la Renna!$B$BMetzen è una delle otto renne di Greatfather Winter — ed è proprietà della Smokywood Pastures. Abbiamo ricevuto non una ma DUE lettere di riscatto, da gruppi che sostengono di avere Metzen. Con la stagione delle feste ormai nel vivo, qui non possiamo staccarci dalla cassa! Ti prego — trova Metzen e riportacelo!$B$BCerca degli indizi nelle lettere di riscatto, e cospargilo di questa polvere di renna — lo libererà da qualunque cosa lo tenga legato!$B$BTi prego, fai presto!",
  obj = "Trova Metzen the Reindeer. Cerca nei biglietti che ti sono stati dati degli indizi sul luogo in cui è tenuto prigioniero.$B$BQuando trovi Metzen, devi avere con te il Pouch of Reindeer Dust per cospargerlo con un po' di polvere; questo dovrebbe liberare Metzen dai legami che lo tengono prigioniero.$B$BUna volta liberato Metzen, riporta il Pouch of Reindeer Dust a Wulmort Jinglepocket a Ironforge.",
  progress = "$N! I biglietti nella borsa che ti ho dato bastavano per rintracciare Metzen? Non voglio neanche pensare a cosa potrebbero fargli quei crudeli delinquenti... ma un riscatto così esorbitante non possiamo proprio permetterci di pagarlo!",
  reward = "Ce l'hai fatta! Urrà!$B$BMetzen è tornato in volo alle stalle di Greatfather Winter — sì, Metzen sa volare davvero — proprio poco fa! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Vigilia di Grande Inverno e anche la Smokywood Pastures. Grazie, $N.$B$BSenti... per quello che hai fatto, voglio darti questo. È una cosa DAVVERO speciale; se hai una cavalcatura, secondo me ti divertirai un mondo. Buona Vigilia di Grande Inverno!",
}
T[8763] = {
  title = "L'Eroe del Giorno",
  desc = "Senti... non dovrei proprio dirtelo, ma visto che sei $Gl'eroe:l'eroina; del giorno e tutto il resto...$B$BIn questo periodo dell'anno l'agrifoglio fresco è dappertutto, ma non dura mai. Noi abbiamo una macchina che conserva l'agrifoglio — non va mai a male! Lo usiamo per ravvivare la festa... e i guadagni d'estate!$B$BTi lascio usare il conservatore, ma solo se sei $Gun maestro cuoco:una maestra cuoca;. Ti serviranno del sale di rocciafonda e due, tre, oh, diciamo cinque monete d'oro. Ne ricaverai una bella partita, tutta per te.",
  obj = "Porta 1 Deeprock Salt e 5 monete d'oro a una qualsiasi macchina Holly Preserver, e riceverai 5 Preserved Holly.",
  progress = "A prima vista la macchina \"Conservatore di Agrifoglio\" sembra una specie di alambicco, ma a guardarla con attenzione si notano alcune modifiche in stile goblin. Comunque, la tua abilità in cucina sembra permetterti di capire come funziona la macchina.$B$BNella macchina c'è già dell'agrifoglio fresco — ti basta aggiungere del sale di rocciafonda e cinque monete d'oro per metterla in funzione.",
  reward = "La macchina si mette in moto con un piccolo brontolio e un po' di vapore. Non passa molto prima che si fermi, e ad annunciarlo è un altro piccolo getto di vapore che ne esce. Uno sportello si apre e rivela una partita di agrifoglio conservato!",
}
T[8764] = {
  title = "Il Cambio di Cammino — Non Più Protettore",
  progress = "$GCampione:Campionessa;, se dovessi decidere di percorrere un altro cammino, consegnami il tuo anello con sigillo e una montagna di scarabei sottratti ai nostri nemici di Ahn'Qiraj.",
  reward = "Abbi cura di te, $N. Se cambierai idea, sarò qui per aiutarti.",
}
