}
T[8770] = {
  title = "Obiettivo: Difensori Hive'Ashi",
  desc = "Mentre lo sforzo bellico si intensifica, la presenza dei silitidi nella zona rappresenta una minaccia sempre più grave per le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, dove il tuo obiettivo principale saranno i difensori Hive'Ashi.$B$BA compito concluso, fai rapporto al Comandante Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Defenders e fai rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Combat Task Briefing I.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. La tua diligenza è degna di nota, come sempre.",
}
T[8771] = {
  title = "Obiettivo: Inseguitori delle Sabbie Hive'Ashi",
  desc = "Mentre lo sforzo bellico si intensifica, la presenza dei silitidi nella zona rappresenta una minaccia sempre più grave per le nostre operazioni. Sei $Gstato scelto:stata scelta; per partecipare a un assalto a Hive'Ashi, dove il tuo obiettivo principale saranno gli inseguitori delle sabbie Hive'Ashi.$B$BA compito concluso, fai rapporto al Comandante Mar'alith.",
  obj = "Uccidi 30 Hive'Ashi Sandstalkers e fai rapporto a Commander Mar'alith a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Combat Task Briefing II.",
  progress = "Hai qualcosa da dirmi, $C?",
  reward = "Ottimo lavoro, $N. Il tuo contributo all'attacco a Hive'Ashi è stato registrato.",
}
T[8772] = {
  title = "Obiettivo: Vigilanti Hive'Zora",
  desc = "Sono stati chiamati rinforzi per unirsi all'assalto a Hive'Zora. Sei $Gstato scelto:stata scelta; per colpire i vigilanti Hive'Zora. A compito concluso, fai rapporto al Comandante Mar'alith.",
