T[8778] = {
  title = "L'Ironforge Brigade Ha Bisogno di Esplosivi!",
  desc = "L'Ironforge Brigade ha presentato un'insolita richiesta di componenti altamente... volatili... Raccoglili e portali al Signor Nozzlespring dell'Ironforge Brigade.",
  obj = "Porta 6 Oils of Immolation, 5 Goblin Rocket Fuel e 10 Dense Blasting Powder ad Arcanist Nozzlespring, vicino a Hive'Zora, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing IV.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ah, sì! Questi faranno comodo! Obbligatissimo, $N!",
}
T[8779] = {
  title = "Materiali per la Divinazione",
  desc = "Gli studi della Geologa Larksbane si sono rivelati di enorme valore per le nostre operazioni a Silithus. Di recente ha richiesto dei materiali per la divinazione da usare nelle sue ricerche.$B$BTi preghiamo di raccogliere questi materiali e di consegnarli direttamente a lei, così che possa proseguire le sue ricerche.",
  obj = "Porta 1 Large Brilliant Shard, 1 Large Radiant Shard e 1 Huge Emerald a Geologist Larksbane a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing V.",
}
T[8780] = {
  title = "Potenziamenti d'Armatura per il Fronte",
  desc = "Sul campo di battaglia le scorte di potenziamenti d'armatura dell'Ironforge Brigade si stanno riducendo pericolosamente. Procurane una partita e consegnala a Janela Stouthammer, all'avamposto dell'Ironforge Brigade fuori da Hive'Zora.",
  obj = "Porta 8 Rugged Armor Kits e 8 Heavy Armor Kits a Janela Stouthammer all'Avamposto dell'Ironforge Brigade, vicino a Hive'Zora, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing VII.",
}
T[8781] = {
  title = "Armi per il Fronte",
  desc = "L'Ironforge Brigade è stata un'alleata di valore nella nostra lotta a Silithus. Purtroppo molti dei suoi rifornimenti sono andati persi durante il viaggio fin qui. Procurati una partita di armi e consegnala a Janela Stouthammer, vicino a Hive'Zora.",
  obj = "Porta 2 Moonsteel Broadswords a Janela Stouthammer all'Avamposto dell'Ironforge Brigade, fuori da Hive'Zora. Per completare la missione devi portare anche il Logistics Task Briefing VI.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Oh, benissimo! Così non mi toccherà più sentire lamentele per le lame smussate. Grazie, $N.",
}
T[8782] = {
  title = "Forniture per le Uniformi",
  desc = "L'ultimo afflusso di volontari ha causato una carenza di uniformi. Procurati una partita di materiali per le uniformi e portala all'Invocatrice del Vento Proudhorn.",
  obj = "Porta 1 Mooncloth, 2 Bolts of Runecloth e 1 Ironweb Spider Silk a Windcaller Proudhorn a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing VIII.",
}
T[8783] = {
  title = "Materiali Straordinari",
  desc = "Vargus, il fabbro di Cenarion Hold, ha richiesto dei materiali incantati da usare per fabbricare armi potenti per le nostre forze. Procurali e portali direttamente a Vargus, così che le truppe di Cenarion Hold continuino a essere ben equipaggiate.",
  obj = "Porta 2 Enchanted Thorium Bars e 2 Enchanted Leather a Vargus a Cenarion Hold, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing IX.",
}
T[8784] = {
  title = "I Segreti dei Qiraji",
  desc = "Hai scoperto un antico manufatto Qiraji! Forse a uno dei draghi vicino all'ingresso del tempio questa reliquia potrebbe servire.",
  obj = "Porta l'Ancient Qiraji Artifact ai draghi nascosti vicino all'ingresso del tempio.",
  progress = "Stai brillando! So cosa vuol dire...",
  reward = "Una scoperta eccezionale, $N. Davvero magnifica! Ci farà di sicuro capire qualcosa delle menti contorte del nostro nemico.",
}
T[8785] = {
  title = "La Legione di Orgrimmar Ha Bisogno di Mojo!",
  desc = "La Legione di Orgrimmar ha fatto richiesta di diversi ingredienti insoliti. Visti i risultati che sta ottenendo a Silithus, vorremmo accontentarla il prima possibile. Raccogli i materiali e portali alla troll di nome Shai.",
  obj = "Porta 6 Powerful Mojo, 6 Flasks of Big Mojo e 8 Oils of Immolation a Shadow Priestess Shai, vicino a Hive'Regal, a Silithus. Per completare la missione devi portare anche il Logistics Task Briefing IV.",
  progress = "Ce li hai i miei materiali, $N?",
  reward = "Ah, sì. Proprio quello che mi serviva! Con questo preparerò un intruglio speciale. Ai silitidi non piacerà per niente!",
}
T[8786] = {
  title = "Armi per il Fronte",
  desc = "La Legione di Orgrimmar ha fatto richiesta di altre armi, che al momento non siamo riusciti a fornire. Procurati le armi richieste e portale a Merok Longstride, fuori da Hive'Regal.",
  obj = "Porta 3 Massive Iron Axes a Merok Longstride all'accampamento della Legione di Orgrimmar, fuori da Hive'Regal. Per completare la missione devi portare anche il Logistics Task Briefing VI.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ottimo lavoro. Di queste eravamo a corto, $N.",
}
T[8787] = {
  title = "Potenziamenti d'Armatura per il Fronte",
  desc = "I coraggiosi volontari della Legione di Orgrimmar sono arrivati a Silithus per sostenere la nostra causa. Le loro scorte di potenziamenti d'armatura sono andate perse, chissà come, durante il viaggio. Procurati una partita di potenziamenti d'armatura e consegnala a Merok Longstride, presso l'accampamento della Legione di Orgrimmar.",
  obj = "Porta 8 Rugged Armor Kits e 8 Heavy Armor Kits a Merok Longstride, vicino a Hive'Regal. Per completare la missione devi portare anche il Logistics Task Briefing VII.",
  progress = "Hai qualcosa per me, $N?",
  reward = "Ah, sì... Li distribuirò alle truppe, $N. La Legione di Orgrimmar ti ringrazia!",
}
T[8788] = {
  title = "Un Regalo Scosso Delicatamente",
  reward = "Sembra che questo regalo sia stato scosso un paio di volte. Sul biglietto c'è scritto:$B$BPer $Gun:una; $R $C davvero speciale.",
  en_title = "A Gently Shaken Gift",
}
T[8789] = {
  title = "Equipaggiamento Imperiale Qiraji",
  desc = "Per un millennio non siamo rimasti con le mani in mano, $N.$B$BAbbiamo osservato queste bestie divorare i propri simili una volta che non servivano più. Le abbiamo ascoltate tramare e complottare per distruggere il nostro mondo. E abbiamo saputo dei tradimenti al loro interno.$B$BI punti deboli esistono, e noi sappiamo come sfruttarli a nostro vantaggio.$B$BTrova i loro armamenti cerimoniali e portameli: uniti all'elemento nato dall'instabilità del loro stesso Dio, diventeranno una forza con cui fare i conti.",
  obj = "Arygos, nel Temple of Ahn'Qiraj, creerà per te degli Armamenti Infusi di Elementium se gli porti gli Imperial Qiraji Armaments e 3 Elementium Ore.",
  progress = "Cerca quello che ti ho chiesto. Diventerai più della somma delle tue parti, $Gcampione:campionessa;.",
  reward = "Infuse di Elementium, queste armi squarceranno i Qiraji e il loro Dio con incredibile facilità.",
}
T[8790] = {
  title = "Vessillo Imperiale Qiraji",
  desc = "Secondo la teoria di Arygos, l'elemento che nasce dai conflitti tra gli Dei Antichi e i loro servi è anche, nelle giuste condizioni, estremamente letale per loro. Parlo dell'Elementium, mortale.$B$BTrova e portami il Vessillo Imperiale Qiraji e l'elemento tossico, e io lo infonderò in armi di grande potere.",
  obj = "Merithra of the Dream, nel Temple of Ahn'Qiraj, creerà per te degli Armamenti Infusi di Elementium se le porti gli Imperial Qiraji Regalia e 3 Elementium Ore.",
  progress = "Li abbatterai e ci libererai da questi vincoli.",
  reward = "Fai buon uso di quest'oggetto, $N. Che provino il dolore che tanto bramano infliggere agli altri.",
}
T[8791] = {
  title = "La Caduta di Ossirian",
  desc = "Una terribile minaccia è stata sepolta. Il crudele Ossirian è stato sconfitto.$B$BGli abitanti di Kalimdor sarebbero sollevati nel sapere di questa vittoria. Prendi la testa di Ossirian e presentala al Comandante Mar'alith di Cenarion Hold.",
  obj = "Consegna la Head of Ossirian the Unscarred a Commander Mar'alith a Cenarion Hold, nel Silithus.",
  progress = "Ah, $N, sei $Gtornato:tornata;! E $Gtutto intero:tutta intera;, aggiungerei. Che notizie porti da Ahn'Qiraj?",
  reward = "Ti offro il mio più alto encomio e un oggetto di potere a tua scelta, $N. Hai reso un grande servizio alla gente di Kalimdor.",
}
T[8792] = {
  title = "L'Orda Ha Bisogno del Tuo Aiuto!",
  desc = "Ciao, sono $Gcontento:contenta; che tu abbia deciso di ascoltarmi. L'Orda ha bisogno di tutto l'aiuto possibile per prepararsi alla Guerra di Ahn'Qiraj, e questo vuol dire che abbiamo bisogno di te! Proprio mentre parliamo, i raccoglitori ufficiali stanno radunando il materiale necessario per la guerra in arrivo, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con chi comanda, il Signore della Guerra Gorchuk. Che ne dici, $C? Darai una mano con i preparativi indispensabili?",
  obj = "Parla con Warlord Gorchuk a Valley of Spirits di Orgrimmar.",
  reward = "Throm'ka, $C! È bello vedere così tanti membri dell'Orda, come te, $N, venire a dare il loro sostegno per gettare le basi della Guerra di Ahn'Qiraj in arrivo. Lo sforzo che facciamo qui ci garantirà la vittoria contro i Silitidi e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BAllora, ora che sei qui, assicurati di parlare con i vari raccoglitori e di offrire il tuo aiuto per procurare i materiali più adatti a te.",
  en_title = "The Horde Needs Your Help!",
  en_obj = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
}
