T[8798] = {
  title = "Uno Yeti Tutto Tuo",
  reward = "Senti! Sai una cosa?! Sei $Gun ingegnere:un'ingegnera; anche tu! Quindi, visto che mi hai aiutata a dare una lezione ai miei amici, ti insegno a costruire uno yeti meccanico tutto tuo! Così il divertimento non finisce mai e poi mai, e puoi spaventare chi ti pare! Sempre che tu riesca a scovare i componenti per costruirlo, s'intende.$B$BChe ne dici, $N? Vuoi imparare il segreto per costruire uno yeti meccanico?",
}
T[8799] = {
  title = "L'Eroe del Giorno",
  desc = "Senti... non dovrei proprio dirtelo, ma visto che sei $Gl'eroe:l'eroina; del giorno e tutto il resto...$B$BIn questo periodo dell'anno l'agrifoglio fresco è dappertutto, ma non dura mai. Noi abbiamo una macchina che conserva l'agrifoglio — non va mai a male! Lo usiamo per ravvivare la festa... e i guadagni d'estate!$B$BTi lascio usare il conservatore, ma solo se sei $Gun maestro cuoco:una maestra cuoca;. Ti serviranno del sale di rocciafonda e due, tre, oh, diciamo cinque monete d'oro. Ne ricaverai una bella partita, tutta per te.",
  obj = "Porta 1 Deeprock Salt e 5 monete d'oro alla macchina Holly Preserver, e riceverai 5 Preserved Holly.",
  progress = "A prima vista la macchina \"Conservatore di Agrifoglio\" sembra una specie di alambicco, ma a guardarla con attenzione si notano alcune modifiche in stile goblin. Comunque, la tua abilità in cucina sembra permetterti di capire come funziona la macchina.$B$BNella macchina c'è già dell'agrifoglio fresco — ti basta aggiungere del sale di rocciafonda e cinque monete d'oro per metterla in funzione.",
  reward = "La macchina si mette in moto con un piccolo brontolio e un po' di vapore. Non passa molto prima che si fermi, e ad annunciarlo è un altro piccolo getto di vapore che ne esce. Uno sportello si apre e rivela una partita di agrifoglio conservato!",
}
T[8800] = {
  title = "Equipaggiamento da Battaglia Cenarion",
  desc = "Man mano che porti a termine i compiti che ti vengono assegnati in guerra, ti conviene parlare con Vargus, il fabbro. Mostragli i distintivi che hai guadagnato strada facendo. Ti fornirà un equipaggiamento all'altezza del tuo impegno per la nostra causa.",
  obj = "Parla con Vargus a Cenarion Hold, a Silithus.",
  reward = "Ti manda Kaldon? Molto bene, vediamo cosa possiamo fare per te.",
}
T[8801] = {
  title = "L'Eredità di C'Thun",
  desc = "Le mura di Ahn'Qiraj tremano. Una forza malvagia, più antica del mondo stesso, è stata distrutta.$B$BMentre guardi i resti del colossale abominio, il cuore quasi ti si gela. Anche nella morte senti intorno a te l'eredità del male di C'Thun.$B$BHai fatto ciò che si credeva impossibile.$B$BAfferri un peduncolo oculare del mostro e lo riponi al sicuro nello zaino.$B$BPorta l'Occhio di C'Thun ai draghi nella sala accanto.",
  obj = "Porta l'Eye of C'Thun a Caelestrasz, nel Temple of Ahn'Qiraj.",
  progress = "$GLord:Lady; $N, ci hai liberati dalla sua stretta.",
  reward = "Lasceremo questo luogo per conto nostro,$GSignore:Signora; $N — quando saremo certi che il male al suo interno sia stato distrutto del tutto. Il tuo viaggio leggendario è quasi giunto al termine.",
}
T[8802] = {
  title = "$GIl Salvatore:La Salvatrice; di Kalimdor",
  desc = "Ora vai alle Caverns of Time, $GSignore:Signora; $N. Anachronos attende il tuo ritorno. Dagli l'occhio di C'Thun, perché vorrà senz'altro metterlo nella collezione del suo padrone.",
  obj = "Porta l'Eye of C'Thun ad Anachronos, alle Caverns of Time.",
  progress = "$GSignore:Signora; $N! È finita...",
  reward = "Il Padrone ti ha lasciato questi,$Gcampione:campionessa;. Dalla riserva senza tempo: una collezione di manufatti che abbraccia migliaia di anni — a te la scelta.",
}
T[8803] = {
  title = "Un Regalo di Festa",
  reward = "Sul biglietto di questo regalo c'è scritto:$B$BPer $N,$B$BCon la speranza che ti aiuti a portare calorosi auguri e allegria festiva a tutta Azeroth.$B$BDa Greatfather Winter",
  en_title = "A Festive Gift",
}
T[8804] = {
  title = "Kit di Sopravvivenza nel Deserto",
  desc = "Con l'arrivo di nuove reclute a Cenarion Hold nasce il problema di tenerle in vita nel deserto. La disidratazione e le numerose creature velenose sono una seria minaccia per i volontari inesperti. Raccogli il materiale necessario per un kit di sopravvivenza nel deserto e portalo a Calandrath a Cenarion Hold.",
  obj = "Porta 4 Globes of Water, 4 Powerful Anti-Venom e 4 Smoked Desert Dumplings a Calandrath, alla locanda di Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing I.",
}
T[8805] = {
  title = "Stivali per la Guardia",
  desc = "Alla divisione a cavallo della guardia di Cenarion Hold scarseggiano gli stivali di mithril decorati. Procuratene una partita e consegnala subito al Capitano Vish Kozus a Cenarion Hold.",
  obj = "Porta 3 Ornate Mithril Boots a Vish Kozus, Capitano della Guardia di Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing II.",
}
T[8806] = {
  title = "Pietre da Molatura per la Guardia",
  desc = "Alla guardia di Cenarion Hold scarseggiano le pietre da molatura. Procuratene una partita e consegnala subito al Capitano Vish Kozus a Cenarion Hold.",
  obj = "Porta 10 Dense Grinding Stones, 10 Solid Grinding Stones e 10 Heavy Grinding Stones a Vish Kozus, Capitano della Guardia di Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing III.",
}
T[8807] = {
  title = "Materiali per la Divinazione",
  desc = "Gli studi della Geologa Larksbane si sono rivelati preziosissimi per le nostre operazioni a Silithus. Di recente ha chiesto dei materiali per la divinazione da usare nelle sue ricerche.$B$BPer favore, raccogli questi materiali e consegnali direttamente a lei, così potrà proseguire le sue ricerche.",
  obj = "Porta 1 Large Brilliant Shard, 1 Large Radiant Shard e 1 Huge Emerald a Geologist Larksbane a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing V.",
}
T[8808] = {
  title = "Forniture per le Uniformi",
  desc = "L'ultima ondata di volontari ha provocato una carenza di uniformi. Procurati una partita di materiali per le uniformi e portala all'Invocatrice del Vento Proudhorn.",
  obj = "Porta 1 Mooncloth, 2 Bolts of Runecloth e 1 Ironweb Spider Silk a Windcaller Proudhorn a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing VIII.",
}
T[8809] = {
  title = "Materiali Straordinari",
  desc = "Vargus, il fabbro di Cenarion Hold, ha chiesto dei materiali incantati da usare per fabbricare armi potenti per le nostre forze. Procurateli e portali direttamente a Vargus, così le truppe di Cenarion Hold continueranno a essere ben equipaggiate.",
  obj = "Porta 2 Enchanted Thorium Bars e 2 Enchanted Leather a Vargus a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing IX.",
}
T[8810] = {
  title = "Bende per il Campo di Battaglia",
  desc = "Dopo le perdite che abbiamo subito di recente, le nostre scorte di bende sul campo di battaglia si stanno riducendo in modo pericoloso. Procurati una partita di materiale di primo soccorso e consegnala all'Invocatrice del Vento Proudhorn a Cenarion Hold.",
  obj = "Porta 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages e 30 Heavy Mageweave Bandages a Windcaller Proudhorn a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing X.",
}
T[8811] = {
  title = "Un Sigillo d'Encomio",
  progress = "Se un avventuriero ha un solo sigillo d'encomio, glielo cambio con un piccolo riconoscimento da parte di Darnassus.$B$BTieni presente che è meglio consegnare una pila di dieci sigilli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa da dieci.$B$BDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.",
  reward = "Molto bene — le tue gesta sono state messe agli atti, e i tuoi sforzi ti vengono debitamente riconosciuti. Continua così, $C.$B$BSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
