T[8819] = {
  title = "Dieci Sigilli d'Encomio",
  progress = "Accetto i sigilli d'encomio dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, mi assicurerò che le tue gesta ricevano un riconoscimento significativo da parte di Darnassus. Accetto anche i sigilli singoli, ma con un riconoscimento molto ridotto. A noi interessano molto di più le imprese di maggior valore, anche se nessuna impresa verrà ignorata.$B$BDetto questo, prenderò volentieri i tuoi sigilli, se sei $Gpronto:pronta; a consegnarne un gruppo.",
  reward = "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, $N, a fare davvero la differenza.$B$BFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri a cambiare tutti quelli che vuoi.",
  en_title = "Ten Commendation Signets",
}
T[8820] = {
  title = "Dieci Anelli d'Encomio",
  progress = "Accetto gli anelli d'encomio dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, mi assicurerò che le tue gesta ricevano un riconoscimento significativo da parte degli Gnomeregan Exiles. Accetto anche gli anelli singoli, ma con un riconoscimento molto ridotto. A noi interessano molto di più le imprese di maggior valore, anche se nessuna impresa verrà ignorata.$B$BDetto questo, prenderò volentieri i tuoi anelli, se sei $Gpronto:pronta; a consegnarne un gruppo.",
  reward = "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi anelli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, $N, a fare davvero la differenza.$B$BFammi sapere se hai altri anelli da consegnare; ti aiuterò volentieri a cambiare tutti quelli che vuoi.",
  en_title = "Ten Commendation Signets",
}
