T[8823] = {
  title = "Dieci Anelli d'Encomio",
  progress = "Accetto gli anelli d'encomio dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, mi assicurerò che le tue gesta ricevano un riconoscimento significativo da parte di Orgrimmar. Accetto anche gli anelli singoli, ma con un riconoscimento molto ridotto. A noi interessano molto di più le imprese di maggior valore, anche se nessuna impresa verrà ignorata.$B$BDetto questo, prenderò volentieri i tuoi anelli, se sei $Gpronto:pronta; a consegnarne un gruppo.",
  reward = "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi anelli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, $N, a fare davvero la differenza.$B$BFammi sapere se hai altri anelli da consegnare; ti aiuterò volentieri a cambiare tutti quelli che vuoi.",
  en_title = "Ten Commendation Signets",
}
