T[8827] = {
  title = "I Regali dell'Inverno",
  desc = "Ho sentito che Greatfather Winter — con il generoso sostegno della Smokeywood Pastures — ha messo dei regali per tutti sotto l'albero a Ironforge. Vorrei tanto andarci, ma devo tenere d'occhio il Wondervolt Invernale PX-238.$B$BMa tu dovresti proprio andare a vedere. Sono sicuro che Greatfather Winter ha dei regali con sopra il tuo nome.",
  obj = "Parla con Greatfather Winter. Si trova vicino ai banchi della Smokywood Pastures, a Ironforge.",
  reward = "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali della Vigilia di Grande Inverno.$B$BOra, non preoccuparti: Greatfather Winter non si è dimenticato $Gdel suo:della sua; $R $C $Gpreferito:preferita;. Guarda sotto l'albero e troverai i tuoi regali.$B$BIn questo periodo di doni, magari anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti della Smokeywood Pasture?",
  en_title = "Winter's Presents",
  en_obj = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.",
}
T[8828] = {
  title = "I Regali dell'Inverno",
  desc = "Ho sentito che Great-father Winter — con il generoso sostegno della Smokeywood Pastures — ha messo dei regali per tutti sotto l'albero a Orgrimmar. Vorrei tanto andarci, ma devo tenere d'occhio il Wondervolt Invernale PX-238.$B$BMa tu dovresti proprio andare a vedere. Sono sicuro che Great-father Winter ha dei regali con sopra il tuo nome.",
  obj = "Parla con Great-father Winter. Si trova vicino ai banchi della Smokywood Pastures, a Orgrimmar.",
  reward = "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali della Vigilia di Grande Inverno.$B$BOra, non preoccuparti: Great-father Winter non si è dimenticato $Gdel suo:della sua; $R $C $Gpreferito:preferita;. Guarda sotto l'albero e troverai i tuoi regali.$B$BIn questo periodo di doni, magari anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti della Smokeywood Pasture?",
  en_title = "Winter's Presents",
  en_obj = "Speak with Great-father Winter. He is located near the Smokywood Pastures vendor area in Orgrimmar.",
}
T[8829] = {
  title = "L'Inganno Supremo",
  desc = "Il Martello del Crepuscolo agisce dietro innumerevoli strati di segretezza e inganno. Le sue azioni si compiono nel nostro mondo, ma vengono pianificate in un luogo che non siamo ancora riusciti a raggiungere.$B$BCi siamo convinti che le pietre con cui il Martello del Crepuscolo evoca i suoi superiori permettano di viaggiare nei due sensi. Per provare a usarle in questo modo dobbiamo riprodurre — fin nell'ultimo dettaglio — la tunica di un emissario del crepuscolo.$B$BRaccogli i materiali necessari e portali ad Aurel Goldleaf, $N.",
  obj = "Porta una Skin of Shadow, 3 Frayed Abomination Stitchings e 1 Twilight Cultist Robe ad Aurel Goldleaf a Cenarion Hold, a Silithus. Per completare la missione devi portare anche Logistics Task Briefing XI.",
}
T[8830] = {
  title = "Un Anello d'Encomio",
  progress = "Se un avventuriero ha un solo anello d'encomio, glielo cambio con un piccolo riconoscimento da parte di Darnassus.$B$BTieni presente che è meglio consegnare un gruppo di dieci anelli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo anello come servizio per chi non ne ha abbastanza per un gruppo completo da dieci.$B$BDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo anello.",
  reward = "Molto bene — le tue gesta sono state messe agli atti, e i tuoi sforzi ti vengono debitamente riconosciuti. Continua così, $C.$B$BSe hai altri anelli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
