T[8857] = {
  title = "Segreti del Colosso — Ashi",
  desc = "Cerco avventurieri temprati dalla battaglia che vogliano e sappiano portare a Oglethorpe, a Booty Bay, un campione fresco del guscio del Colosso di Ashi caduto. No, no, non vorrei mai che ti avvicinassi al cadavere di quel coso. Prendi solo uno dei miei campioni, e sbrigati. Da marci non gli servono a niente!",
  obj = "Porta il Colossus of Ashi's Husk a Oglethorpe Obnoticus, a Booty Bay.",
  progress = "Sì? Cos'hai lì?",
  reward = "Oh, i polli che costruirò con questo guscio prodigioso! Ottimo lavoro, $Gragazzo mio:ragazza mia;!",
}
T[8858] = {
  title = "Segreti del Colosso — Regal",
  desc = "Non c'è niente che mi piacerebbe di più che ficcare 'sto guscio d'insetto giù per la gola di quel faccione di Oilfist... Solo che sono bloccato qui a raccogliere campioni da quello scarafaggio troppo cresciuto. Resterò qui fino alle ore piccole, grosso com'è quel coso.$B$BPorta 'sto campione a Oilfist da parte mia, e fai alla svelta, $C. Paga ALLA GRANDE!$B$BGià, Thorium Point — sta nella Searing Gorge.",
  obj = "Porta il Colossus of Regal's Husk a Overseer Oilfist, nella Searing Gorge.",
  progress = "Hmmm...",
  reward = "Eccellente. Da questa chitina potremmo di certo ricavare un'armatura incredibilmente potente. Ecco le ricchezze che ti erano state promesse.",
}
T[8859] = {
  title = "Segreti del Colosso — Zora",
  desc = "I miei servitori ci hanno quasi rimesso la vita per recuperare questo campione. Devi assolutamente sbrigarti! Lord Maxwell Tyrosus aspetta con impazienza un campione fresco del guscio. È convinto che i segreti di questo Colosso possano aiutarci nella guerra contro il Flagello!$B$BPerché sei ancora qui!? A Light's Hope! Sì, i tuoi sforzi saranno ricompensati profumatamente...",
  obj = "Porta il Colossus of Zora's Husk a Lord Maxwell Tyrosus a Light's Hope Chapel, nelle Eastern Plaguelands.",
  progress = "Hai il passo un po' pesante, $Gamico:amica;.",
  reward = "Ottimo, e giusto in tempo! Ben fatto, $Gragazzo:ragazza;.",
}
T[8860] = {
  title = "Festeggiamenti per il Nuovo Anno!",
  desc = "Stormwind organizza una festa per il nuovo anno! Per tutta la giornata di oggi puoi avere da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio! Dovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!$B$BComunque, alla Locandiera Allison, a Stormwind, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Fammi il favore di consegnargliela!$B$BGrazie, $N! La Locandiera Allison è alla Gilded Rose, nel Quartiere Commerciale di Stormwind.",
  obj = "Porta le Smokywood Supplies a Innkeeper Allison, a Stormwind.",
  progress = "Salve! Sei qui per la festa? O forse devi solo far riposare quei tuoi piedi stanchi...",
  reward = "Oh, le mie provviste della Smokywood! Splendido! Mi serviranno per sfamare tutta la città durante la festa!$B$BGrazie, $N. Prendi questo come pagamento, e non dimenticare di bere e ballare con i festaioli qui fuori!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.",
}
T[8861] = {
  title = "Festeggiamenti per il Nuovo Anno!",
  desc = "Thunder Bluff organizza una festa per il nuovo anno! Per tutto il giorno lì troverai da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio!$B$BDovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!$B$BComunque, alla Locandiera Pala, a Thunder Bluff, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Fammi il favore di consegnargliela!$B$BGrazie, $N! La Locandiera Pala è nella locanda vicino al ponte per l'Altura dei Cacciatori.",
  obj = "Porta le Smokywood Supplies a Innkeeper Pala, a Thunder Bluff.",
  progress = "Buongiorno, $C! Sei $Gvenuto:venuta; a Thunder Bluff per i nostri festeggiamenti? O sei qui per far riposare uno zoccolo stanco tra una caccia e l'altra?",
  reward = "Oh, molto bene! Queste provviste aiuteranno a sfamare tutta la nostra gente, qui per festeggiare il nuovo anno!$B$BTi ringrazio, $N. Sei in debito con me. Ti prego, prendi queste monete... e segui il mio consiglio — bevi a volontà dai barili qui fuori, e unisciti ai festaioli in una danza di festa!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.",
}
T[8862] = {
  title = "Candela di Elune",
  progress = "La candela di Elune è un manufatto molto venerato dai discepoli della Celebrazione della Luna. Nella candela è racchiusa la vera luce lunare, pronta a essere liberata!$B$BQuesta luce è innocua per la maggior parte delle creature, ma scoprirai che Omen e i suoi servitori ne vengono bruciati e abbagliati.",
  reward = "Molto bene, allora — accetto queste monete degli avi. Prendi la candela di Elune, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BChe la tua Celebrazione della Luna sia gioiosa e piena di allegria, $N.$B$BE se sceglierai di affrontare Omen e i suoi servitori, vedrai che la candela di Elune ti sarà molto utile...",
  en_title = "Elune's Candle",
}
T[8863] = {
  title = "Gnocchi della Celebrazione della Luna",
  progress = "Se hai fame, sei $Gcapitato:capitata; nel posto giusto, $Gamico mio:amica mia;!$B$BGli gnocchi sono il cibo tradizionale della Celebrazione della Luna; si servono fin dai tempi della prima Celebrazione della Luna, e mi fa piacere poterli offrire anche in questa. In cambio di una sola moneta degli avi, ti farò assaggiare uno dei piatti più gustosi che ti capiterà mai di provare!",
  reward = "Eccellente — goditi questi gnocchi, offerti da me. Sono solo un piccolo segno di apprezzamento per l'onore che ti sei $Gguadagnato:guadagnata; con le tue azioni, ma credo che ti piaceranno lo stesso.$B$BSe hai altre monete degli avi, sono pronto a offrirti in cambio un'ampia scelta di oggetti.",
  en_title = "Festival Dumplings",
}
T[8864] = {
  title = "Abiti Festivi Lunari",
  progress = "Ho una selezione di abiti che potrebbe interessarti. Abiti come questi si indossavano un tempo durante la Celebrazione della Luna, e la selezione che ho oggi è forse la più bella che abbia mai visto. Ognuno è fatto a mano solo con i materiali più pregiati e morbidi.$B$BIn cambio di qualche moneta degli avi, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?",
  reward = "Molto bene, allora — accetto queste monete degli avi. Prendi il tuo abito, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BCome hai onorato i tuoi anziani, così onori me con la tua sola presenza. Grazie, e che la tua Celebrazione della Luna sia gioiosa.",
  en_title = "Festive Lunar Dresses",
}
T[8865] = {
  title = "Completi Pantalone Festivi Lunari",
  progress = "Ho il piacere di informarti che ho una bella selezione di completi pantalone festivi che possono diventare tuoi... ma solo in cambio di monete degli antenati. Se tieni alla moda, sono proprio quello che cerchi! Ti assicuro che completi come questi non li troverai da nessun'altra parte.$B$BIn cambio di qualche Moneta degli Antenati, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?",
  reward = "Molto bene, allora — accetto queste monete degli antenati. Prendi il tuo completo pantalone, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BSe hai altre monete degli antenati da scambiare, torna a parlarmi. Offrirò vari oggetti per tutta la durata della Celebrazione della Luna.",
  en_title = "Festive Lunar Pant Suits",
}
T[8866] = {
  title = "Bronzebeard l'Anziano",
  reward = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo dono...",
  en_title = "Bronzebeard the Elder",
}
T[8867] = {
  title = "Fuochi d'Artificio Lunari",
  desc = "Ogni anno i druidi di Moonglade celebrano il grande trionfo della nostra città su un antico male.$B$BCelebriamo la saggezza dei nostri anziani, partecipiamo a banchetti magnifici e, naturalmente... lanciamo fuochi d'artificio!$B$BCon una piccola offerta puoi comprare dei razzi colorati dal nostro venditore. Prova a usare qualcuno dei lanciarazzi qui intorno, $N.",
  obj = "Lancia 8 Lunar Fireworks e 2 Cluster Fireworks, poi torna da una Lunar Festival Harbinger in una qualsiasi capitale.",
  progress = "Hai trovato i lanciarazzi, $N?",
  reward = "Ben fatto, $N.$B$BOra che sei $Gentrato:entrata; nello spirito della festa, prendi pure questo invito ai festeggiamenti di Moonglade.$B$BÈ una celebrazione davvero piacevole, se hai tempo. Condividiamo cibo, bevande, storie e, naturalmente... altri fuochi d'artificio!$B$BApri l'invito stando dentro il cerchio di luce lunare più intensa e verrai $Gtrasportato:trasportata; a Moonglade.",
  en_title = "Lunar Fireworks",
  en_obj = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.",
}
T[8868] = {
  title = "La Benedizione di Elune",
  desc = "La bestia Omen era un tempo un eroe di questo mondo. Lupo di grande forza e fortuna, Omen combatté al fianco degli eroi della Guerra degli Antichi finché non cedette alle magie demoniache. Rivoltatosi contro i suoi alleati, imperversò per Azeroth seminando morte e terrore al suo passaggio.$B$BSconfitto infine qui, a Moonglade, Omen ora dorme nel limo del Lago Elune'ara. Ma a ogni nuovo anno, durante la festa, si agita...$B$BRaduna dei compagni, $N, poi evoca e sconfiggi la bestia Omen. Guadagnati la benedizione di Elune!",
  obj = "Evoca Omen, sconfiggilo e ottieni Elune's Blessing. Torna da Valadar Starsong a Nighthaven",
  progress = "Omen si agita ancora sotto il Lago Elune'ara, $N...",
  reward = "Ottimo lavoro, $N. La sconfitta di Omen ha rimandato il suo spirito alle acque di Elune'ara. Benché la bestia stessa sia benedetta da Elune e dunque non possa morire, la sua ira si placherà per un altro anno.$B$BLa tua vittoria è una celebrazione, $N — una celebrazione della potenza di Omen, di te e dei tuoi alleati, e della pace che hai dato a questo tragico eroe del nostro passato.",
}
T[8869] = {
  title = "Dolce Serenità",
  desc = "Fra le mura del Bastione Scarlatto si trova la dolce Serenità. Il Battimartello Cremisi ne custodisce la ricetta a costo della vita. Sconfiggilo e portami il suo grembiule. In cambio ti addestrerò a diventare $Gun forgiatore:una forgiatrice; di martelli.$B$BSappi questo: una volta scelta la via del forgiatore di martelli, quelle del forgiatore di spade e del forgiatore d'asce ti saranno precluse.",
  obj = "Vai a Stratholme e uccidi il Crimson Hammersmith. Recupera il Crimson Hammersmith's Apron e torna da Lilith.",
}
T[8870] = {
  title = "La Celebrazione della Luna",
  desc = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Messaggera della Celebrazione della Luna proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.",
  obj = "Parla con la Lunar Festival Harbinger nel Quartiere Mystic di Ironforge. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
