}
T[8876] = {
  title = "Razzi Piccoli",
  progress = "Custodisco i segreti per creare i razzi della Celebrazione della Luna, e mi fa piacere condividere il mio sapere con chi è degno di onore.$B$BIn cambio di monete degli antenati, posso offrirti la ricetta per fare un razzo piccolo...",
  reward = "Ah, molto bene. Ecco le tue ricette, $N, e che Elune ti benedica.",
  en_title = "Small Rockets",
}
T[8877] = {
  title = "Mortaio per Fuochi d'Artificio",
  progress = "I razzi sono un modo meraviglioso di festeggiare, ma per vederli in tutto il loro splendore... vanno lanciati da un mortaio.$B$BPortami delle monete degli antenati e potrò offrirti il sapere per costruire mortai per razzi come quelli che vedi a Moonglade.",
  reward = "Ecco a te, $N. Questo è il progetto per costruire un mortaio per fuochi d'artificio. Piazza i mortai dove desideri festeggiare, e poi invita i tuoi amici a unirsi a te!",
}
T[8878] = {
  title = "Ricette Festive",
  progress = "Gli abiti e i completi con i pantaloni che vedi sono vesti tradizionali di molti anni fa. Si indossano in onore delle antiche usanze e dei cari che non ci sono più.$B$BSe mi porti delle monete degli antenati, $N, ti darò il modello per confezionare i tradizionali abiti o completi rossi.",
  reward = "Ecco i modelli, $N. Sono certa che troverai davvero bello il frutto di questo sapere.",
}
T[8879] = {
  title = "Grandi Razzi",
  progress = "I grandi razzi della Celebrazione illuminano il cielo di una luce splendida — solo i fasci pirotecnici ne eguagliano la magnificenza!$B$BPortami delle monete degli antenati, $N, e condividerò con te il sapere necessario a crearli.",
  reward = "Molto bene — accetto queste monete degli antenati. Ecco le tue ricette, $N. Che tu possa usarle per diffondere la gloria di Elune!",
}
T[8880] = {
  title = "Fasci Pirotecnici",
  progress = "I fasci pirotecnici sono un insieme di singoli razzi, e la loro bellezza lascia senza fiato! Portami delle monete degli antenati e condividerò con te il sapere necessario a crearli...",
  reward = "Ecco a te, $N. Prendi queste ricette e imparane i segreti. Ti auguro buona fortuna, e sarò lieta di vedere le tue magnifiche creazioni.",
}
T[8881] = {
  title = "Grandi Fasci Pirotecnici",
  progress = "Per creare i grandi fasci pirotecnici servono enormi risorse e grande abilità, ma il loro splendore e la loro bellezza valgono lo sforzo! Portami delle monete degli antenati e ti concederò il sapere necessario a fabbricarli.",
  reward = "Grazie, $N. Ecco la ricetta dei grandi fasci pirotecnici. Che le tue opere portino gioia e fortuna a tutti coloro che alzeranno gli occhi a guardarle.",
}
T[8882] = {
  title = "Mortaio per Fasci Pirotecnici",
  progress = "Gli spettacoli di fuochi d'artificio più splendidi devono comprendere i fasci pirotecnici, e quei fasci pirotecnici vanno lanciati dai mortai per fasci pirotecnici! Non è dunque logico che tu impari i segreti per costruire questi mortai? Portami delle monete degli antenati e ti darò questo sapere.",
  reward = "Ecco il tuo progetto. Studialo con attenzione, e impara...$B$BBuona fortuna, $N. Che i tuoi festeggiamenti possano rivaleggiare con quelli della Celebrazione della Luna stessa!",
}
T[8883] = {
  title = "Valadar Starsong",
  desc = "Ora che hai il tuo invito alla Celebrazione della Luna, puoi raggiungere Moonglade! Lì troverai molti festeggianti e, nel villaggio di Nighthaven, Valadar Starsong e sua sorella Fariel aspettano chi non vede l'ora di partecipare alla celebrazione.$B$BRaggiungi Moonglade attraverso la luce lunare più intensa e parla con Valadar Starsong; scopri quali premi potresti ottenere durante la festa!",
  obj = "Usa la tua Lunar Festival Invitation nella luce lunare per raggiungere Moonglade. Quando arrivi, parla con Valadar Starsong a Nighthaven.",
  reward = "$N, $Gbenvenuto:benvenuta; a Nighthaven, che ospita la Celebrazione della Luna! Anche se di solito il nostro villaggio è remoto e isolato dai popoli di Azeroth, in questo periodo di festa apriamo a tutti le braccia e il cuore.$B$BGoditi la visita, $N, e torna a parlare con me o con mia sorella quando sarai $Gpronto:pronta;.",
  en_title = "Valadar Starsong",
  en_obj = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.",
}
T[8893] = {
  title = "Il Super Egg-O-Matic",
  progress = "Il Super Egg-O-Matic è l'ultima delle invenzioni di Curgle Cranklehop. È un macchinario davvero notevole.$B$BMentre ti avvicini al pannello di controllo, il Super Egg-O-Matic si mette a scoppiettare all'impazzata.",
  reward = "Metti l'uovo di ippogrifo nella macchina. Segue una serie di bip, insieme a strani rumori meccanici.$B$BA quanto pare l'Eggometer ha pesato, misurato e impacchettato il tuo uovo. Questo sì che è un servizio rapido!",
}
T[8897] = {
  title = "Carissima Colara,",
  desc = "Devo fare la guardia qui al cancello, ma sono sempre in pensiero per la mia amata, Colara. Riesco a vederla solo per qualche ora, se mi va bene, e poi... guardami. Ho la paga di un ufficiale di basso grado e potrei essere chiamato al fronte da un giorno all'altro.$B$BE se si dimenticasse di me? In città ci sono tanti uomini. Tanti uomini ricchi.$B$BComunque, ho buttato giù qualcosa... niente di che, ma se potessi portarglielo tu, sarebbe fantastico.",
  obj = "Consegna Lieutenant Heldric's Carefully Penned Note a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "$GCiao, bel ragazzo. Posso aiutarti in qualcosa?:Oh, cielo! Posso aiutarti in qualcosa?;",
  reward = "Oh, che dolce! È la prima volta che mi manda qualcosa. Pensi che stia facendo sul serio?$B$BColara Heldric? Non suona male. Oh, ma sto correndo troppo. Grazie.",
  en_title = "Dearest Colara,",
  en_obj = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.",
}
T[8898] = {
  title = "Carissima Colara,",
  desc = "Ho conosciuto una ragazza a Stormwind, l'ultima volta che ci sono stato per affari della banca. Mi ha rubato il cuore. E adesso non riesco a smettere di pensare a lei! Vorrei mandarle questo messaggio — l'ho riscritto dodici volte!$B$BIn questo periodo la posta è così intasata, e voglio essere sicuro che arrivi.$B$BSe vai da quelle parti, potresti aiutarmi?",
  obj = "Consegna la Creased Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?",
  reward = "Tormek? Oh sì, me lo ricordo. Aveva una gran bella barba, e sotto un bel sorriso.$B$BAh, non posso credere che si sia ricordato di me!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.",
}
T[8899] = {
  title = "Carissima Colara,",
  desc = "Come descrivere la sua bellezza? Migliaia di anni di parole, e non trovo le mie.$B$BQuesti mortali confondono la mente e ci riducono a sciocchi balbettanti.$B$BHo fissato queste parole troppo a lungo. Non riesco a spremerne un significato più eloquente. No, deve riceverle adesso, o qualche altro corteggiatore attirerà di sicuro il suo sguardo.",
  obj = "Consegna l'Immaculate Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?",
  reward = "Non avevo mai ricevuto niente del genere. Che bello!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.",
}
T[8900] = {
  title = "Carissima Elenia,",
  desc = "Era così triste. L'ho capito quando sono riuscito a guardare oltre la sua condizione. Voglio dire, sembrava triste — non lo saresti anche tu?$B$BMa parlandole ho sentito un legame. Non pensavo che qualcuno potesse capire quello che pensavo, ma lei ci riusciva.$B$BQuando l'ho detto agli altri, hanno riso di me, e così non le ho più parlato. Ma mi manca. Puoi portarle questa lettera per me? Voglio essere sicuro che arrivi nelle sue mani.",
  obj = "Consegna la Slightly Creased Note a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Non ti aspetteresti tanta eloquenza da un orco. Certo, finora non abbiamo mai avuto davvero l'occasione di conoscerli. Grazie di avermela portata.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.",
}
T[8901] = {
  title = "Carissima Elenia,",
  desc = "Hai mai conosciuto l'amore, giovane? Per me era una cosa sconosciuta fino a poco tempo fa, quando ho incontrato una ragazza dell'Undercity, Elenia. È già raro che uno della mia specie si interessi a qualcuno che non sia dei nostri, figuriamoci a una Reietta.$B$BMa ora il pensiero di lei mi occupa la mente giorno e notte.$B$BSe puoi, potresti portarle questa lettera? Vorrei che venisse qui a Mulgore. Spero che dica di sì.",
  obj = "Consegna la Carefully Written Letter a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Che parole gentili mi scrive Temma. Ma per quanto le sue parole mi commuovano, non posso prendere in considerazione l'amore di un tauren. Nei pensieri, nel corpo e nella mente siamo troppo diversi.$B$BMeno male che non devo ricevere di persona questi suoi pensieri. Non sopporterei di spezzargli il cuore.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8902] = {
  title = "Carissima Elenia,",
  desc = "Una vita fa ero promesso sposo di Elenia, la mia fidanzatina d'infanzia. Erano anni che non pensavo a lei, ma ultimamente occupa spesso i miei pensieri.$B$BForse, nonostante tutto quello che è successo, nelle nostre vite può esserci ancora un po' di spazio per il nostro amore.$B$BSono sicuro che anche lei sarà cambiata. Puoi consegnarle questa lettera per me? Sono troppo nervoso per dargliela di persona.",
  obj = "Consegna la Lovingly Composed Letter a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Questo mi riporta alla mente ricordi di una vita fa, $N. Elenia Tor. Sarebbe stato il mio nome, sai. Avremmo fatto una bellissima cerimonia sulle rive del lago. Quando lui si fosse ritirato, avremmo trovato una fattoria dove passare la vecchiaia.$B$BSogni semplici, a quei tempi.$B$BMa se mi vedesse adesso, dubito che vedrebbe in me Elenia. Solo carne fredda e un cuore morto...",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8903] = {
  title = "Amore Pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. Non è decoroso, è uno spettacolo indecente e, nel peggiore dei casi, potrebbe essere una minaccia per la sicurezza stessa dell'Alleanza.$B$BPensaci: e se anche le guardie fossero state colpite da questo strano male? Bisogna fare qualcosa.$B$BVa' da una delle guardie qui a Stormwind e vedi se anche loro sono state prese da questa follia.",
  obj = "Procurati una Stormwind Guard's Card e riportala ad Aristan Mottar, a Stormwind.",
  progress = "Avevo ragione a preoccuparmi? Le guardie sono state colpite da questo mal d'amore?",
  reward = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.",
  en_title = "Dangerous Love",
  en_obj = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.",
}
T[8904] = {
  title = "Amore Pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. È disgustosa e, abbassando le nostre difese, potrebbe essere una minaccia per tutti noi.$B$BÈ già abbastanza grave che tanti dei nostri si siano lasciati andare a questo comportamento ridicolo. Ma credo che si sia diffuso persino tra i nostri guardiani, che dovrebbero essere immuni a cose del genere.$B$BTrova uno dei nostri guardiani e vedi se anche loro sono stati presi da questa follia.",
  obj = "Procurati una Guardian's Moldy Card e portala a Fenstad Argyle, nell'Undercity.",
  progress = "Avevo ragione a preoccuparmi? Quegli idioti dei nostri guardiani hanno ceduto?",
  reward = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.",
  en_title = "Dangerous Love",
  en_obj = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.",
}
T[8905] = {
  title = "Una Proposta Seria",
  desc = "Ben $Gtrovato:trovata;, $C. Ho qualcosa che potrebbe interessarti.$B$BSono in possesso di un'armatura molto simile a quella che indossano quelli della tua professione, ma di qualità molto superiore. Sarei disposta a scambiarne i bracciali con un paio comune, in cambio di un piccolo favore.$B$BIl sangue dei frostsabers e degli orsi che vivono a Winterspring ha proprietà di cui ho bisogno in questo momento. Portamene un campione abbondante, insieme ai bracciali e a una piccola somma d'oro. Vedrai che la fatica sarà ben ripagata.",
  obj = "Procurati 15 Winterspring Blood Samples e 20 monete d'oro e portali, insieme a un paio di Wildheart Bracers, a Deliana, a Ironforge.",
  progress = "Mi hai portato quello che ti ho chiesto, $N?",
  reward = "Eccellente! Facciamo lo scambio, allora. È difficile separarsi da quest'armatura eccellente, ma temo che non ne avrò bisogno tanto presto.$B$BSe ti interessa fare altri lavori per me, potrei essere disposta a rinunciare agli altri pezzi.",
}
