T[8920] = {
  title = "Una Proposta Seria",
  desc = "Salute, $C! Dal tuo portamento si capisce che in questo mondo ne hai viste e fatte tante. Eppure scommetto che un pezzo d'armatura come questo non l'hai mai visto.$B$BFammi un piccolo favore e sarò disposto a dartelo in cambio di un normale paio di bracciali.$B$BMi serve un campione consistente di veleno estratto dai ragni e dagli scorpioni che vivono a Silithus. Portamelo insieme a qualche moneta d'oro e faremo lo scambio.",
  obj = "Procurati 15 Silithus Venom Samples e 20 monete d'oro e portali, insieme a un paio di Bracers of Valor, a Mokvar a Orgrimmar.",
  progress = "Ti sei $Gprocurato:procurata; gli oggetti che mi servono, $N?",
  reward = "Ah, sì. Mux ne sarà ben contento.$B$BQuei bracciali facevano parte di un completo d'armatura più ampio. Se ti interessa darmi ancora una mano, potrei prendere in considerazione l'idea di separarmi anche dal resto.",
}
T[8921] = {
  title = "Il Distillatore Ectoplasmatico",
  desc = "Ah, ti serve il mio ultimo progetto... il rivelatore di fantasmi extradimensionale! Purtroppo sono rimasto senza fondi e senza manodopera.$B$BVuoi darmi una mano? Ottimo! Per prima cosa dobbiamo costruire un congegno che raccolga il tessuto stesso della morte! Costruire un distillatore ectoplasmatico non sarà un'impresa facile, $N.$B$BDovrai portarmi un convertitore d'arcanite, qualche essenza eterna superiore e dell'olio di stonescale. Mi servirà anche della cenere vulcanica delle pozze di lava delle Burning Steppes, per costruire un filtro.",
  obj = "Torna da Mux Manascrambler a Gadgetzan con 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash e 40 monete d'oro.",
  progress = "Capisco che i materiali siano un po' cari... ma ti assicuro che serviranno tutti, dal primo all'ultimo!",
  reward = "Sono proprio i materiali che mi servivano. E arrivano anche al momento giusto, $N!$B$BIl tuo distillatore sarà pronto in pochi istanti! Nel frattempo, prendi questo come ricompensa per avermi aiutato nel mio progetto.",
}
T[8922] = {
  title = "Un Congegno Soprannaturale",
  desc = "Devo trovare il modo di parlare con Anthion Harmon... o meglio, con il suo fantasma!$B$BSo di un ingegnere con un bizzarro interesse per il soprannaturale. Sostiene di saper costruire una macchina che gli permette di parlare con i morti!$B$BIl sangue che hai raccolto era destinato a lui; va' a Gadgetzan e portaglielo come pagamento per i suoi servigi!",
  obj = "Porta il Sealed Blood Container a Mux Manascrambler, dentro Gadgetzan, a Tanaris.",
  progress = "Hai qualcosa per me?",
  reward = "Ottimo! Proprio quando stavo per rimanere senza!$B$BDici che ti manda Deliana?",
}
T[8923] = {
  title = "Un Congegno Soprannaturale",
  desc = "Devi avere un bel coraggio per essere $Grimasto:rimasta; dopo una cosa del genere. Oppure ho stuzzicato il tuo interesse con il pezzo d'armatura che ti ho dato. Ce ne sono altri come quello, se ti interessa ancora aiutarmi.$B$BI campioni di veleno che hai raccolto sono per un mio conoscente, Mux Manascrambler, un ingegnere che si interessa di soprannaturale. Il suo ultimo progetto è un congegno che permette di comunicare con i morti! La mia ultima speranza è contattare Anthion e scoprire qualcosa di più sulla mia situazione.",
  obj = "Porta il Sealed Venom Container a Mux Manascrambler a Gadgetzan.",
  progress = "Vuoi parlare con me?",
  reward = "Ottimo! Proprio quando stavo per rimanere senza!$B$BDici che ti manda Mokvar?",
}
T[8924] = {
  title = "A Caccia di Ectoplasma",
  desc = "Un bel lavoro di ingegneria, modestia a parte! Temo che dovrai viaggiare un po' per trovare i non morti incorporei che ci servono.$B$BVedi, climi diversi danno consistenze diverse al tessuto spettrale dei morti. Gli elfi della notte tormentati di Silithus, gli spiriti degli alti nobili di Winterspring e i fantasmi e le banshee delle Eastern Plaguelands dovrebbero darci i diversi tipi di ectoplasma che ci servono. Ricordati di piazzare il distillatore lì vicino prima di raccoglierli!",
  obj = "Usa l'Ectoplasmic Distiller vicino ai non morti incorporei per raccogliere 12 Scorched Ectoplasms a Silithus, 12 Frozen Ectoplasms a Winterspring e 12 Stable Ectoplasms nelle Eastern Plaguelands. Riportali, insieme all'Ectoplasmic Distiller, a Mux Manascrambler a Gadgetzan.",
  progress = "Hai già raccolto l'ectoplasma, $R?",
  reward = "Sì, questi andranno benissimo!$B$BAttingendo alle energie ultraterrene racchiuse in queste sostanze potremo metterci in contatto con coloro le cui anime non hanno ancora lasciato del tutto questo mondo!",
}
T[8925] = {
  title = "Una Fonte di Energia Portatile",
  desc = "Ora dovremo trovare una fonte di energia stabile e portatile per tenere attivo l'ectoplasma. Ho sentito delle voci su un possente elementale chiamato Signore del Magma Bokk, che per cuore ha un potente nucleo di magma — una riserva inesauribile di calore!$B$BSi dice che si trovi nelle Burning Steppes, a sud del Massiccio Blackrock. Portami il nucleo di magma e avremo abbastanza carica per alimentare il rivelatore di fantasmi extradimensionale!",
  obj = "Trova Magma Lord Bokk nelle Burning Steppes, procurati il suo Magma Core e portalo a Mux Manascrambler a Gadgetzan.",
  progress = "Hai trovato il Signore del Magma, $N?",
  reward = "Ce l'hai fatta! Questo fornirà di sicuro abbastanza energia per alimentare il rivelatore di fantasmi extradimensionale!",
}
T[8926] = {
  title = "Giusto Compenso",
  desc = "Hai mantenuto la parola e hai portato il congegno costruito da Mux. Credo che una ricompensa sia d'obbligo, se voglio che salvarmi la pelle continui a interessarti. Portami la cintura e il paio di guanti che vuoi migliorare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.",
  obj = "Porta una Wildheart Belt e un paio di Wildheart Gloves a Deliana, a Ironforge.",
  progress = "Sei $Gpronto:pronta; a fare lo scambio?",
  reward = "Tu hai rispettato la tua parte dell'accordo, io rispetterò la mia.$B$BRicorda soltanto che terrò per me i pezzi migliori finché non avrai finito il tuo lavoro.",
}
T[8927] = {
  title = "Giusto Compenso",
  desc = "Hai dimostrato di essere una persona molto affidabile, $N. Per quanto sia sicuro che mi aiuterai a uscire da questo guaio, farei bene a ricompensarti in base ai risultati.$B$BPer ora ti cambierò la cintura e i guanti. Se arriveremo entrambi in fondo a questa storia, ti metterò a disposizione il resto dei pezzi.",
  obj = "Porta una Wildheart Belt e un paio di Wildheart Gloves a Mokvar a Orgrimmar.",
  progress = "Sei $Gpronto:pronta; per lo scambio?",
  reward = "Il nostro accordo resta valido. Ricordati solo che questo è appena un assaggio di quello che ti aspetta. Liberami da questo destino maledetto e ti ricompenserò con oggetti di un potere davvero grande.",
}
T[8928] = {
  title = "Un Mercante Losco",
  desc = "Il nucleo ci darà abbastanza carica per alimentare il nostro congegno; ora dobbiamo solo costruire una verga che possa incanalare quell'energia senza fondersi.$B$BA Winterspring ho incontrato un imp che vendeva merci esotiche di ogni genere. Aveva una verga elementale che andrebbe alla perfezione. Mi prenderei a calci da solo per non averla comprata.$B$BVive dentro una caverna all'ingresso della Gola di Darkwhisper. Intrufolati là dentro e cerca di trovarlo.$B$BBada che ti chieda solo quaranta monete d'oro; è il prezzo che ha fatto a me!",
  obj = "Cerca un imp dentro una caverna all'ingresso della Gola di Darkwhisper, nel sud di Winterspring, compra una Fel Elemental Rod e torna da Mux Manascrambler a Gadgetzan.",
  progress = "Sei $Griuscito:riuscita; a trovare l'imp alla Gola di Darkwhisper?",
  reward = "Ce l'hai fatta! Questa verga andrà alla perfezione. Ora bisogna mettere tutto insieme...",
}
T[8929] = {
  title = "Alla Ricerca di Anthion",
  desc = "Be', non ci resta altro da fare che provare l'invenzione del goblin. Si dice che Anthion sia stato falciato dalle legioni di non morti di Stratholme mentre cercava di varcarne le porte.$B$BProva a usare il congegno lì e scopri quello che sapeva Anthion, qualunque cosa fosse.",
  obj = "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.",
  reward = "È stata Deliana a metterti in contatto con me? Farò del mio meglio per aiutarti, ma prima devo chiederti un grande favore.",
}
T[8930] = {
  title = "Alla Ricerca di Anthion",
  desc = "Molto bene, $N. Non resta che mettere alla prova l'invenzione del goblin. Si dice che Anthion sia stato ucciso dalle legioni di non morti di Stratholme mentre cercava di varcarne le porte.$B$BProva a usare il congegno lì e vedi se puoi, davvero, parlare con i morti!",
  obj = "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.",
  reward = "È stato Mokvar a metterti in contatto con me? Farò del mio meglio per aiutarti, ma prima devo chiederti un grande favore.",
}
