T[8945] = {
  title = "La Supplica di un Morto",
  desc = "Ti darò le informazioni che chiedi, $N. Ma ci sono questioni più urgenti.$B$BLa mia amata moglie è stata fatta prigioniera dalla feccia non morta di Rivendare.$B$BEro fermamente contrario al fatto che si unisse alla sciocca crociata dell'Argent Dawn, ma ormai non ha più importanza. Devi portare a termine ciò che ho tentato di fare io, devi salvare Ysida dalle grinfie del Barone!",
  obj = "Entra a Stratholme e salva Ysida Harmon da Baron Rivendare.",
  progress = "Dimmi, Ysida è viva?",
  reward = "Grazie per avermi salvata... Ho temuto per la mia vita. Ti prego, accetta questo come piccolo segno della mia gratitudine.$B$BAnthion è... no... non può essere...",
}
T[8946] = {
  title = "Prova di Vita",
  desc = "È il più crudele dei destini che il mio amato sia morto nel tentativo di salvarmi. Eppure, tu sostieni di poter conversare con lui.$B$BPortagli questo medaglione come prova che sto bene. Non deve restare in questo mondo; il mio cuore non lo sopporterebbe.$B$BAddio, $N. Ti sarò debitrice per sempre.",
  obj = "Porta Ysida's Locket ad Anthion Harmon nelle Eastern Plaguelands.",
  progress = "Ysida... è viva?",
  reward = "Quel medaglione... l'hai trovata! Finalmente posso riposare in pace.$B$BOra risponderò a tutte le domande che vorrai farmi, $N. Ma fa' presto, non mi resta molto tempo in questo mondo.",
}
T[8947] = {
  title = "La Strana Richiesta di Anthion",
  desc = "Non ci eravamo resi conto dell'importanza del medaglione di Valthalak, così è stato diviso insieme al resto del bottino. Il primo pezzo l'ha preso un nano di nome Theldren. Ho provato a riprenderglielo e mi ha quasi ammazzato di botte. Dovrai prenderti il frammento con la forza.$B$BL'ultima volta che ho avuto sue notizie, era diventato un gladiatore al servizio dei nani Dark Iron. Convincerlo a battersi con te, però, sarà un po' un'impresa.$B$BProcurami i materiali che seguono. Ti serviranno.",
  obj = "Porta 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth e 4 Cured Rugged Hides ad Anthion Harmon nelle Eastern Plaguelands.",
  progress = "Ti sei $Gprocurato:procurata; i materiali che ti ho chiesto, $N?",
  reward = "Eccellente. Li trasmuterò in qualcosa di più adatto alle nostre esigenze.",
}
T[8948] = {
  title = "Il Vecchio Amico di Anthion",
  desc = "Theldren non è tipo da accettare di buon grado uno scontro leale. Ho modellato questo stendardo perché mostri i colori della sua famiglia.$B$BCon un altro po' di stregoneria, questo stendardo lo provocherà in un modo a cui non saprà resistere.$B$BUn mio vecchio conoscente di nome Falrin sa esattamente come si procede. Ha un modo tutto suo di... irritare la gente. Lo troverai nella biblioteca di Dire Maul.",
  obj = "Porta l'Incomplete Banner of Provocation a Falrin Treeshaper nella biblioteca di Dire Maul.",
  progress = "Su, parla, $Gstraniero:straniera;, non vedi che sono occupato?",
  reward = "Ti manda Anthion, dici? Lo credevo morto. Del resto, in vita mia ne ho sentite di più strane.$B$BE va bene, allora. Cosa vuoi che faccia con questo stendardo?",
}
T[8949] = {
  title = "La Vendetta di Falrin",
  desc = "Sì, è vero che conosco l'incantamento che ti serve, $C. Ma non sono tipo da fare favori gratis, nemmeno se a mandarti qui è stato un vecchio amico.$B$BPer quei bruti dei nostri vicini ogre provo soltanto odio e disprezzo. E non solo per loro: odio i seguaci di Omokk tanto quanto quelli che seguono Re Gordok.$B$BVoglio che tu li uccida. Uccidine tanti! Portami le perline che tengono al collo come prova del tuo lavoro. Fallo, e parleremo della tua richiesta.",
  obj = "Raccogli 25 Ogre Warbeads dagli Ogre dentro Dire Maul o Blackrock Spire e torna da Falrin Treeshaper nell'Athenaeum a Dire Maul.",
  progress = "Hai fatto il favore che ti ho chiesto, $N?",
  reward = "Hmmm... stranamente non mi sento affatto meglio per la morte di mio fratello per mano di quei bruti.$B$BBeh, tu hai rispettato la tua parte dell'accordo. Vediamo cosa posso fare per te.",
}
T[8950] = {
  title = "L'Incantamento dell'Istigatore",
  desc = "Posso applicare allo stendardo l'incantamento che ti serve senza alcuna difficoltà, $N. Purtroppo non ho i materiali necessari, perché è molto raro che qualcuno chieda un sortilegio del genere.$B$BMi serviranno l'essenza di uno dei fantasmi Eldreth che infestano queste sale, una manciata di rune oscure di Scholomance e alcuni grossi frammenti splendenti. Portami questi reagenti e me ne occuperò io per te.",
  obj = "Porta questi oggetti a Falrin Treeshaper dentro Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes e 8 Large Brilliant Shards.",
  progress = "Hai raccolto i materiali che mi servono, $N?",
  reward = "Sì, questi andranno benissimo. Quando avrò finito, nessuna forza al mondo potrà impedire alla tua vittima di accettare la tua sfida.",
}
T[8951] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità, da sciocchi, l'abbiamo diviso in tre parti, senza sapere della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza di trovare i pezzi che mancano. Parla con lei delle ricompense che hai pattuito.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta!",
  obj = "Torna da Deliana a Ironforge con un paio di Wildheart Boots, un Wildheart Kilt e dei Wildheart Spaulders.",
  progress = "Sei $Gtornato:tornata;, $N. Mi devi raccontare tutto quello che hai scoperto. Ma prima pensiamo alla tua ricompensa.",
  reward = "Non riesco a credere che siamo praticamente spacciati, e tutto per colpa di uno stupido medaglione! E sei $Gsicuro:sicura; che Anthion abbia nominato Bodley?$B$BBe', tu il tuo lavoro l'hai fatto, quindi togliamoci il pensiero della tua ricompensa.",
}
T[8952] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità, da sciocchi, l'abbiamo diviso in tre parti, senza sapere della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza di trovare i pezzi che mancano. Parla con lei delle ricompense che hai pattuito.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta!",
