}
T[8959] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità, da sciocchi, l'abbiamo diviso in tre parti, senza sapere della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza di trovare i pezzi che mancano. Parla con lei delle ricompense che hai pattuito.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta!",
  obj = "Torna da Deliana a Ironforge con un paio di Boots of Valor, dei Legplates of Valor e degli Spaulders of Valor.",
  progress = "Sei $Gtornato:tornata;, $N. Mi devi raccontare tutto quello che hai scoperto. Ma prima pensiamo alla tua ricompensa.",
  reward = "Non riesco a credere che siamo praticamente spacciati, e tutto per colpa di uno stupido medaglione! E sei $Gsicuro:sicura; che Anthion abbia nominato Bodley?$B$BBe', tu il tuo lavoro l'hai fatto, quindi togliamoci il pensiero della tua ricompensa.",
}
T[8960] = {
  title = "Lo Sfortunato Destino di Bodley",
  desc = "Quindi dobbiamo recuperare il resto del medaglione? Trovare Bodley sarà un bel grattacapo. È tornato a Blackrock Mountain per provare a rientrare a Blackrock Spire e non ha più fatto ritorno.$B$BTi consiglio di portare con te il congegno del goblin che rivela i fantasmi, perché temo che sia successo il peggio.",
  obj = "Raggiungi Blackrock Mountain e usa l'Extra-Dimensional Ghost Revealer per trovare Bodley vicino a Blackrock Spire.",
  reward = "Sono così contento che tu riesca a vedermi. Finalmente qualcuno con cui parlare!$B$BCi aiuterai, $N? Ci aiuterai a riparare al torto che abbiamo commesso e a rimettere le cose a posto? Se è vero che hai già il Frammento Superiore dell'Amuleto di Sire Valthalak, allora credo di poterti indicare la strada giusta per procurarti le altre due parti, riunirle e mettere fine a tutto questo.$B$BAh, a proposito, ciao, mi chiamo Bodley. Piacere di conoscerti!",
}
T[8961] = {
  title = "Tre Re della Fiamma",
  desc = "Per evocare Lord Valthalak dovremo prima raccogliere gli altri due terzi dell'amuleto. Per farlo ci servono un braciere e dei carboni speciali da bruciarci dentro.$B$BCi sono tre nobili del fuoco, Lord Incendius a Blackrock Depths, Piroguardia Emberseer a Blackrock Spire e il Duca di Cynders a Silithus, che hanno quello che ci serve. Prendi da ognuno un pezzo dei suoi resti, poi torna da me con un Braciere Benedetto, che si può comprare dall'Argent Dawn se sei honored presso di loro.",
  obj = "Raccogli l'Incendicite of Incendius, l'Ember of Emberseer e il Cinder of Cynders, insieme a un Hallowed Brazier, e portali a Bodley dentro Blackrock Mountain.",
  progress = "È stata la nostra follia... la nostra rovina, accettare quell'ultimo lavoro. Se solo non avessimo rubato senza volerlo lo spirito di Lord Valthalak, che era racchiuso nell'amuleto; se solo nel nostro gruppo di mercenari non ci fossero stati quelli così avidi da spartirselo. Oggi sarei vivo, magari a buttare giù una birra, o a lanciare in aria uno dei miei figli.$B$B$N, non lasciare che l'avidità degli ignobili della nostra vecchia compagnia di mercenari sia anche la tua rovina.",
  reward = "Sono colpito, $C, ma non c'è tempo da perdere. Ti affiderò il prossimo compito, perché dovrai procurarti ancora qualche componente importante prima che possiamo procedere.$B$BParlami di nuovo quando ti sentirai $Gpronto:pronta; per la sfida che ti aspetta.",
}
T[8962] = {
  title = "Componenti Importanti",
  desc = "$C, ascolta bene. Ora che abbiamo il braciere, e il modo di accenderlo, ci serve ancora un altro componente di cui impregnarlo; qualcosa che offra un fulcro abbastanza forte da attirare lo spirito del mio vecchio compagno defunto.$B$BMor Grayhoof, il nostro druido più illustre, aveva molti amici intimi nel Cenarion Circle, alcuni dei quali sono caduti sotto i colpi dei silithid. Ho bisogno che tu recuperi dei Resti Druidici dai silithid che popolano i dintorni di Hive'Regal, nel sud-est di Silithus.",
  obj = "Procurati dei Druidical Remains e portali a Bodley dentro Blackrock Mountain.",
  progress = "Sei già $Gtornato:tornata;, dunque, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò nel braciere l'essenza dei resti.$B$BOra non resta che andare nella parte bassa di Blackrock Spire, nella sala di Tazz'Alaor dove risiede il Maestro di Guerra Voone, e usare il braciere per evocare lo spirito corrotto del mio vecchio compagno, Mor Grayhoof. Non potrà riposare finché non gli verrà tolto il pezzo dell'amuleto.",
}
T[8963] = {
  title = "Componenti Importanti",
  desc = "$C, ascolta bene. Ora che abbiamo il braciere, e il modo di accenderlo, ci serve ancora un altro componente di cui impregnarlo; qualcosa che offra un fulcro abbastanza forte da attirare lo spirito della mia vecchia compagna defunta.$B$BIsalien, la nostra sacerdotessa, è cresciuta a Winterspring, a Starbreeze Village. Ho bisogno che tu prenda una Reliquia di Starbreeze Village ai giganti Frostmaul della Gola di Frostwhisper, nel sud di Winterspring, noti per le razzie che ogni tanto compiono verso nord.",
  obj = "Procurati una Starbreeze Village Relic e portala a Bodley dentro Blackrock Mountain.",
  progress = "Sei già $Gtornato:tornata;, dunque, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò nel braciere l'essenza della reliquia.$B$BOra non resta che andare al Santuario di Eldretharr, nell'ala est di Dire Maul, e usare il braciere per evocare lo spirito della mia vecchia compagna, Isalien. Il suo spirito è stato corrotto dal pezzo dell'amuleto di Valthalak in suo possesso, e dalla porzione dell'anima di lui che contiene.",
}
T[8964] = {
  title = "Componenti Importanti",
  desc = "$C, ascolta bene. Ora che abbiamo il braciere, e il modo di accenderlo, ci serve ancora un altro componente di cui impregnarlo; qualcosa che faccia da catalizzatore, abbastanza potente da evocare i resti dei miei vecchi compagni defunti.$B$BI fratelli, Jarien e Sothos, credevano nella via della Crociata Scarlatta. Aspiravano a diventare cavalieri in quella vile organizzazione. Vai a Tyr's Hand, nelle Eastern Plaguelands, e recupera una Spada del Fanatismo Brillante dai pretoriani che si trovano lì.",
  obj = "Recupera una Brilliant Sword of Zealotry e portala a Bodley dentro Blackrock Mountain.",
  progress = "Sei già $Gtornato:tornata;, dunque, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò nel braciere l'essenza della spada.$B$BOra non resta che entrare nel Trono Cremisi, dentro il Bastione Scarlatto a Stratholme, e usare il braciere per evocare i resti dei miei vecchi compagni, Jarien e Sothos. Le loro anime sono state distorte ancora di più dal pezzo dell'amuleto di Valthalak in loro possesso e dallo spirito di lui che contiene.",
}
T[8965] = {
  title = "Componenti Importanti",
  desc = "$C, ascolta bene. Ora che abbiamo il braciere, e il modo di accenderlo, ci serve ancora un altro componente di cui impregnarlo; qualcosa che faccia da catalizzatore, abbastanza potente da attirare lo spirito del mio vecchio compagno defunto.$B$BUn ogre negromante che viaggiava con noi, Kormok, si dilettava a evocare le anime dei morti esiliati dell'Isola della Purificazione, al largo della costa meridionale delle Hillsbrad Foothills. Vai lì e recupera dai loro resti delle Ceneri d'Anima dell'Esiliato.",
  obj = "Procurati delle Soul Ashes of the Banished e portale a Bodley dentro Blackrock Mountain.",
  progress = "Sei già $Gtornato:tornata;, dunque, $C, con quello che ti ho mandato a raccogliere?",
  reward = "Ottimo lavoro, $N. Infonderò nel braciere l'essenza delle ceneri.$B$BOra non resta che entrare a Scholomance, nella sala di Ras Frostwhisper, e usare il braciere per evocare lo spirito del mio vecchio compagno, Kormok. Il pezzo dell'amuleto, con lo spirito di Valthalak che contiene, lo ha corrotto ancora di più, e non avrà pace finché non glielo strapperai con la forza.",
}
T[8966] = {
  title = "Il Frammento Sinistro dell'Amuleto di Sire Valthalak",
  desc = "Il mio amico, Mor Grayhoof, fu il primo a cadere vittima del possesso di un pezzo dell'amuleto di Lord Valthalak, e del frammento di spirito corruttore che contiene. Dopo aver rubato il libro degli incantesimi e l'amuleto di Valthalak, fuggimmo dalla parte superiore di Blackrock Spire per salvarci la vita. Lungo la strada, Mor precipitò nella parte inferiore della guglia.$B$BPiù tardi scoprimmo che era sopravvissuto alla caduta, ma solo per finire catturato e torturato dal Maestro di Guerra Voone. Alcuni assassini spettrali si intrufolarono e lo uccisero proprio davanti a Voone.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley, dentro Blackrock Mountain, con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Allora è fatta? Hai recuperato il pezzo sinistro dell'amuleto di Lord Valthalak e hai finalmente dato pace allo spirito del mio vecchio compagno, Mor Grayhoof?",
  reward = "Hai fatto una grande cosa, $N. Uno spirito riposa in pace, ma c'è ancora molto lavoro da fare prima di poterci lasciare tutto questo alle spalle.$B$BPurtroppo non so dove si trovi chi è morto con il pezzo destro dell'amuleto in suo possesso. Ma non temere; in vita mi dilettavo nell'arte della divinazione, perciò ho un altro compito per te, che ci permetterà di scovare l'ultimo pezzo.",
}
T[8967] = {
  title = "Il Frammento Sinistro dell'Amuleto di Sire Valthalak",
  desc = "In seguito, mentre anche noi facevamo il possibile per sopravvivere, venimmo a sapere che Isalien, una sacerdotessa elfa della notte della nostra compagnia, era andata nella città ancestrale degli elfi della notte, oggi nota come Dire Maul. Da quanto capimmo, c'era andata sia per ragioni personali sia per svelare i segreti del frammento dell'amuleto in suo possesso.$B$BNon ce la fece, però. Ci giunse voce che al Santuario di Eldretharr le avevano teso un'imboscata Alzzin il Selvatico e le sue forze.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Isalien e uccidila. Torna da Bodley dentro Blackrock Mountain con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Non mi dirai che hai già provveduto alla salvezza dello spirito di Isalien e al recupero del frammento sinistro dell'amuleto di Lord Valthalak, $N?",
  reward = "Grazie, $N, per aver dato riposo allo spirito di Isalien. Ora, forse, troverà pace presso la sua dea. Ma ci aspetta ancora molto lavoro, se vogliamo tirarci fuori da questo bel pasticcio in cui ci troviamo.$B$BPurtroppo non so dove si trovi chi è morto con il frammento destro dell'amuleto in suo possesso. Ma non temere; in vita mi dilettavo nell'arte della divinazione, perciò ho un altro compito per te, che ci permetterà di scovare l'ultimo frammento.",
}
T[8968] = {
  title = "Il Frammento Sinistro dell'Amuleto di Sire Valthalak",
  desc = "I fratelli Jarien e Sothos hanno deciso di unirsi alla Crociata Scarlatta quando la nostra compagnia di mercenari si è sciolta. Si sono portati via il Frammento Sinistro dell'Amuleto di Sire Valthalak. Meglio perderli che trovarli, dico io, ma quel frammento ci serve.$B$BDa quel che siamo riusciti a sapere, li ha uccisi addirittura il Gran Crociato Dathrohan in persona, perché non avevano superato i riti d'iniziazione nella sua sala al Bastione Scarlatto.$B$BIn ogni caso noi... cioè tu, dovrai comunque recuperare quel frammento dell'amuleto.",
  obj = "Usa il Brazier of Beckoning per evocare Jarien e Sothos e uccidili. Torna da Bodley dentro Blackrock Mountain con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Vuol dire allora, $C, che hai già dato pace alle anime di quei due sciocchi e recuperato il frammento sinistro dell'amuleto di Lord Valthalak?",
  reward = "Immagino sia meglio così, che le anime di quei due abbiano finalmente trovato pace, anche se da vivi non mi piacevano. In ogni caso abbiamo quello che cercavamo, e questa è senz'altro una buona cosa!$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo nell'arte della divinazione, quindi ho un altro incarico per te, che ci permetterà di scovare l'ultimo frammento.",
}
T[8969] = {
  title = "Il Frammento Sinistro dell'Amuleto di Sire Valthalak",
  desc = "Ora abbiamo quello che ci serve, quindi è il momento di parlare di chi dovrai evocare.$B$BKormok era a posto, per essere un ogre, almeno finché non si è dato alla negromanzia. Da allora, le cose si sono fatte inquietanti più o meno per tutti nella compagnia. Nessuno si è sorpreso, quindi, quando ha preso il suo frammento dell'amuleto e se n'è tornato nella sua nuova casa, Scholomance.$B$BMa neanche lì, o forse soprattutto lì, era al sicuro dagli assassini spettrali. Lo hanno ucciso proprio davanti al suo padrone, Ras Frostwhisper.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Kormok e uccidilo. Torna da Bodley dentro Blackrock Mountain con il Left Piece of Lord Valthalak's Amulet e il Brazier of Beckoning.",
  progress = "Ti faccio i miei complimenti, $N, se sei tornat$Go:a; con il frammento sinistro dell'amuleto. Se invece non è così, provvedi, per favore, perché non c'è tempo da perdere, te lo assicuro!",
  reward = "Ottimo lavoro, $N! Kormok non era poi così male per essere un ogre, almeno finché era vivo, quindi spero che trovi il riposo che merita. Ma ci aspetta altro lavoro.$B$BPurtroppo non so dove si trovi chi è morto con addosso il frammento destro dell'amuleto. Ma non temere; in vita mi dilettavo nell'arte della divinazione, quindi ho un altro compito per te, che ci permetterà di scovare l'ultimo frammento.",
}
T[8970] = {
  title = "Vedo l'Isola di Alcaz nel Tuo Futuro...",
  desc = "Come dicevo, $C, quand'ero in vita ho accarezzato l'idea di diventare un divinatore. Ma non c'era poi tutto il guadagno che potresti immaginare, soprattutto perché è pericoloso e i reagenti sono rari e costosi. Ne so comunque abbastanza da riuscire a individuare l'ultimo frammento dell'amuleto, e con esso lo spirito del mio vecchio compagno.$B$BÈ qui che entri in gioco tu, $N. Ho bisogno che tu vada sull'Isola di Alcaz, al largo della costa di Dustwallow Marsh, e raccolga dell'Alga Sanguigna dai naga Strashaz che ci vivono.",
  obj = "Raccogli 20 Bloodkelp dai naga Strashaz, poi torna da Bodley dentro Blackrock Mountain.",
  progress = "Alga Sanguigna, $N, un bel mucchio, ecco cosa mi serve per alimentare i miei incantesimi di divinazione. Probabilmente dovrai portarti almeno un paio di amici sull'Isola di Alcaz per raccoglierla... quegli Strashaz sono una brutta razza!",
  reward = "A dire il vero, $N, mi sorprende che tu sia tornat$Go:a; tutt$Go:a; inter$Go:a;. D'altra parte, immagino che l'Isola di Alcaz sia l'ultimo dei tuoi problemi, in questo momento.$B$BOk, dammi un momento... la divinazione non è una cosa da cui puoi aspettarti risposte precise con uno schiocco di dita.",
}
T[8977] = {
  title = "Torna da Deliana",
  desc = "È stato fantastico lavorare con te, $N. Ecco il prodotto finito.$B$BSpero che ti sia utile in quello che stai facendo. E senti, se non ti dispiace, aiutami a spargere la voce. Qualche cliente in più non mi dispiacerebbe!",
  obj = "Porta l'Extra-Dimensional Ghost Revealer a Deliana, a Ironforge.",
  progress = "Sei $Gtornato:tornata;?",
  reward = "Ottimo! Sei $Gstato:stata; $Gbravo:brava;, $N. Non sono sicura di potermi fidare del lavoro del goblin, ma non mi resta altra scelta.",
}
T[8978] = {
  title = "Torna da Mokvar",
  desc = "È stato fantastico lavorare con te, $N. Ecco il prodotto finito.$B$BSpero che ti sia utile in quello che stai facendo. E senti, se non ti dispiace, aiutami a spargere la voce. Qualche cliente in più non mi dispiacerebbe!",
  obj = "Torna da Mokvar a Orgrimmar con l'Extra-Dimensional Ghost Revealer.",
  progress = "Sei $Gtornato:tornata; con il congegno?",
  reward = "Sei $Gtornato:tornata; con il congegno! La tua dedizione mi ha colpito, $N. Ottimo lavoro.",
}
T[8979] = {
  title = "L'Intuizione di Fenstad",
  desc = "Credo di conoscere la causa di questo comportamento degli ultimi tempi. Hai sentito, nonostante la puzza dei canali, il nuovo profumo nell'aria? Le nuove acque di colonia e i profumi che sono diventati di moda?$B$BLe nostre menti sono state annebbiate da qualche alchimia immonda.$B$BC'è un solo modo per esserne sicuri — porta una bottiglia di acqua di colonia e una di profumo alla mia amica, la Speziale Zinge. La Royal Apothecary Society scoprirà la verità.$B$BTi rimborserò l'acquisto quando tornerai.",
  obj = "Porta 1 Cologne Bottle e 1 Perfume Bottle ad Apothecary Zinge, nell'Apothecarium dell'Undercity.",
  progress = "Come posso servirti?",
  reward = "Un'altra delle fissazioni di Fenstad, vedo. Crede forse che la Royal Apothecary Society non abbia niente di meglio da fare che portare avanti le sue piccole indagini?$B$BE va bene, lo accontenterò ancora una volta.",
  en_title = "Fenstad's Hunch",
  en_obj = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.",
}
T[8980] = {
  title = "La Valutazione di Zinge",
  desc = "Questo non me l'aspettavo. Sembra che Fenstad, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nelle pozioni per il controllo della mente.$B$BNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Questa è alchimia seria, all'altezza di un membro della Royal Apothecary Society.",
  obj = "Torna da Fenstad Argyle, fuori dalla banca dell'Undercity.",
  reward = "Allora avevo ragione. Non dobbiamo perdere tempo. Dobbiamo scoprire da dove vengono queste fragranze corrotte.$B$BEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.",
  en_title = "Zinge's Assessment",
  en_obj = "Return to Fenstad Argyle outside the bank in the Undercity.",
}
T[8981] = {
  title = "Fare Regali",
  progress = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e di adorazione al tuo capo preferito?",
  reward = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.$B$BNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.$B$BOra, fammene aggiungere un altro al conteggio...",
  en_title = "Gift Giving",
}
T[8982] = {
  title = "Risalire alla Fonte",
  desc = "Dobbiamo scoprire chi è il fornitore. Ho notato che la Speziale Katrina aveva una bottiglia di quel profumo infilata nella borsa. Mi ha detto di averla comprata da Norman, il locandiere.",
  obj = "Parla con Innkeeper Norman, nell'Undercity.",
  reward = "Ah sì, ho ricevuto da poco una fornitura di profumo e acqua di colonia. Non so quanto riuscirò a tenerla sugli scaffali — sembra che nessuno ne abbia mai abbastanza.$B$BSe vuoi il mio parere, non capisco tutto questo clamore.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Innkeeper Norman in the Undercity.",
}
T[8983] = {
  title = "Risalire alla Fonte",
  desc = "C'è qualcosa che non va nella mia merce? Be', non ho mai visto tanta gente desiderare così tanto qualcosa.$B$BHo comprato la mia scorta da una mercante di nome Mara Rennick. È nuova in città.$B$BHa detto che doveva consegnare della merce al sarto del Quartiere dei Maghi.",
  obj = "Parla con Mara Rennick, alla bottega del sarto nel Mage Quarter dell'Undercity.",
  reward = "Purtroppo ho venduto tutta la mia scorta di profumo e acqua di colonia a Norman, il locandiere. Se ne vuoi un po', dovresti parlare con lui — sempre che gliene sia rimasta.$B$BPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.",
}
T[8984] = {
  title = "La Fonte Svelata",
  desc = "Senti, le azioni di uno speziale rinnegato non mi riguardano. Se sta sabotando i nostri sforzi, lascia che sia io la prima a indicarti la strada giusta.$B$BSe è innocente, allora non ha niente da nascondere, giusto?$B$BHo comprato la merce dallo Speziale Staffron Lerent. Lavora in un posto isolato oltre il Maniero di Ravenholdt, sulle colline sopra Hillsbrad. A dire il vero, mi è sembrato un po' strano.",
  obj = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, oltre il Maniero di Ravenholdt.",
  reward = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.$B$BUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.$B$BSaranno indeboliti, impreparati. Preoccupati per i loro cari, perderanno il loro smalto.$B$BLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.",
  en_title = "The Source Revealed",
  en_obj = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.",
}
T[8985] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dov'è l'ultimo pezzo dell'amuleto, ci serve ancora un componente di cui impregnare il braciere; qualcosa che faccia da catalizzatore, abbastanza potente da attirare lo spirito della mia defunta ex compagna.$B$BIsalien, la nostra sacerdotessa, è cresciuta a Winterspring, a Starbreeze Village. Devi recuperare una Reliquia di Starbreeze Village dai giganti Frostmaul della Gola di Frostwhisper, nel sud di Winterspring, noti per le razzie che ogni tanto fanno verso nord.",
  obj = "Procurati una Starbreeze Village Relic e portala a Bodley dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a prendere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza della reliquia nel braciere.$B$BOra non resta che andare al Santuario di Eldretharr, nell'ala est di Dire Maul, e usare il braciere per evocare lo spirito della mia ex compagna, Isalien. Il suo spirito è stato corrotto dal pezzo dell'amuleto di Valthalak in suo possesso, e dalla parte di anima di lui che vi è racchiusa.$B$BAh, a proposito, mi era avanzata un po' di alga sanguigna dal tuo viaggio all'Isola di Alcaz, così ne ho fatto qualche pozione per te. Scegli quella che vuoi!",
}
T[8986] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dov'è l'ultimo pezzo dell'amuleto, ci serve ancora un componente di cui impregnare il braciere; qualcosa che faccia da catalizzatore, abbastanza potente da attirare lo spirito del mio defunto ex compagno.$B$BMor Grayhoof, il nostro druido più illustre, aveva molti amici stretti nel Cenarion Circle, e alcuni di loro sono caduti per mano dei silithid. Devi recuperare dei Resti Druidici dai silithid che vivono nei dintorni di Hive'Regal, nel sud-est di Silithus.",
  obj = "Procurati dei Druidical Remains e portali a Bodley dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a prendere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza dei resti nel braciere.$B$BOra non resta che andare nella parte bassa di Blackrock Spire, nella sala in cui risiede il Maestro di Guerra Voone, a Tazz'Alaor, e usare il braciere per evocare lo spirito corrotto del mio ex compagno, Mor Grayhoof. Non potrà trovare pace finché non gli verrà tolto il pezzo dell'amuleto.$B$BAh, a proposito, mi era avanzata un po' di alga sanguigna dal tuo viaggio all'Isola di Alcaz, così ne ho fatto qualche pozione per te. Scegli quella che vuoi!",
}
T[8987] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dov'è l'ultimo pezzo dell'amuleto, ci serve ancora un componente di cui impregnare il braciere; qualcosa che faccia da catalizzatore, abbastanza potente da evocare i resti dei miei defunti ex compagni.$B$BI fratelli Jarien e Sothos credevano nella via della Crociata Scarlatta. Aspiravano a diventare cavalieri di quell'ignobile organizzazione. Vai a Tyr's Hand, nelle Eastern Plaguelands, e recupera una Spada del Fanatismo Brillante dai pretoriani che si trovano lì.",
  obj = "Recupera una Brilliant Sword of Zealotry e portala a Bodley dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a prendere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza della spada nel braciere.$B$BOra non resta che entrare nel Trono Cremisi, dentro il Bastione Scarlatto a Stratholme, e usare il braciere per evocare i resti dei miei ex compagni, Jarien e Sothos. Le loro anime sono state stravolte ancora di più dal pezzo dell'amuleto di Valthalak in loro possesso e dallo spirito di lui che vi è racchiuso.$B$BAh, a proposito, mi era avanzata un po' di alga sanguigna dal tuo viaggio all'Isola di Alcaz, così ne ho fatto qualche pozione per te. Scegli quella che vuoi!",
}
T[8988] = {
  title = "Altri Componenti Importanti",
  desc = "$C, ascolta bene. Ora che sappiamo dov'è l'ultimo pezzo dell'amuleto, ci serve ancora un componente di cui impregnare il braciere; qualcosa che faccia da catalizzatore, abbastanza potente da attirare lo spirito del mio defunto ex compagno.$B$BKormok, un negromante ogre che viaggiava con noi, si divertiva a evocare le anime dei morti esiliati dell'Isola della Purificazione, al largo della costa meridionale delle Hillsbrad Foothills. Vai lì e recupera delle Ceneri d'Anima dell'Esiliato dai loro resti.",
  obj = "Procurati delle Soul Ashes of the Banished e portale a Bodley dentro Blackrock Mountain.",
  progress = "Allora sei già $Gtornato:tornata;, $C, con quello che ti ho mandato a prendere?",
  reward = "Ottimo lavoro, $N. Infonderò l'essenza delle ceneri nel braciere.$B$BOra non resta che entrare a Scholomance, nella stanza di Ras Frostwhisper, e usare il braciere per evocare lo spirito del mio ex compagno, Kormok. Il pezzo dell'amuleto, e lo spirito di Valthalak al suo interno, lo hanno corrotto ancora di più, e non troverà pace finché non glielo toglierai con la forza.$B$BAh, a proposito, mi era avanzata un po' di alga sanguigna dal tuo viaggio all'Isola di Alcaz, così ne ho fatto qualche pozione per te. Scegli quella che vuoi!",
}
T[8989] = {
  title = "Il Frammento Destro dell'Amuleto di Sire Valthalak",
  desc = "Il mio amico, Mor Grayhoof, fu il primo a cadere vittima del possesso di un pezzo dell'amuleto di Lord Valthalak, e del frammento di spirito corruttore che contiene. Dopo aver rubato il libro degli incantesimi e l'amuleto di Valthalak, fuggimmo dalla parte superiore di Blackrock Spire per salvarci la vita. Lungo la strada, Mor precipitò nella parte inferiore della guglia.$B$BPiù tardi scoprimmo che era sopravvissuto alla caduta, ma solo per finire catturato e torturato dal Maestro di Guerra Voone. Alcuni assassini spettrali si intrufolarono e lo uccisero proprio davanti a Voone.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley, dentro Blackrock Mountain, con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Allora è fatta? Hai recuperato il pezzo destro dell'amuleto di Lord Valthalak, hai ricomposto l'amuleto in un pezzo solo e hai finalmente dato pace allo spirito del mio vecchio compagno, Mor Grayhoof?",
  reward = "Grazie per aver aiutato Mor Grayhoof, $N. Un altro spirito riposa in pace, e ora abbiamo l'amuleto ricomposto! Ma la prova più dura ci aspetta ancora.$B$BPerché il braciere si sintonizzi sull'evocazione di Lord Valthalak, ci sono ancora alcuni oggetti da raccogliere e da riportarmi qui.",
}
T[8990] = {
  title = "Il Frammento Destro dell'Amuleto di Sire Valthalak",
  desc = "In seguito, mentre anche noi facevamo il possibile per sopravvivere, venimmo a sapere che Isalien, una sacerdotessa elfa della notte della nostra compagnia, era andata nella città ancestrale degli elfi della notte, oggi nota come Dire Maul. Da quanto capimmo, c'era andata sia per ragioni personali sia per svelare i segreti del frammento dell'amuleto in suo possesso.$B$BNon ce la fece, però. Ci giunse voce che al Santuario di Eldretharr le avevano teso un'imboscata Alzzin il Selvatico e le sue forze.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Isalien e uccidila. Torna da Bodley dentro Blackrock Mountain con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Non mi dirai che hai già provveduto alla salvezza dello spirito di Isalien e al recupero del frammento destro dell'amuleto di Lord Valthalak, $N? Ricordati di ricomporre i frammenti dell'amuleto prima di consegnarmelo.",
  reward = "Grazie, $N, per aver dato riposo allo spirito di Isalien. Ora, forse, troverà pace presso la sua dea. E abbiamo anche l'amuleto ricomposto! Ma la prova più dura è ancora davanti a noi.$B$BPerché il braciere sia accordato per evocare Lord Valthalak, ci sono ancora alcuni oggetti da raccogliere e riportarmi qui.",
}
T[8991] = {
  title = "Il Frammento Destro dell'Amuleto di Sire Valthalak",
  desc = "I fratelli Jarien e Sothos hanno deciso di unirsi alla Crociata Scarlatta quando la nostra compagnia di mercenari si è sciolta. Si sono portati via il Frammento Destro dell'Amuleto di Sire Valthalak. Meglio perderli che trovarli, dico io, ma quel frammento ci serve.$B$BDa quel che siamo riusciti a sapere, li ha uccisi addirittura il Gran Crociato Dathrohan in persona, perché non avevano superato i riti d'iniziazione nella sua sala al Bastione Scarlatto.$B$BIn ogni caso noi... cioè tu, dovrai comunque recuperare quel frammento dell'amuleto.",
  obj = "Usa il Brazier of Beckoning per evocare Jarien e Sothos e uccidili. Torna da Bodley dentro Blackrock Mountain con Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Vuol dire allora, $C, che hai già dato pace alle anime di quei due sciocchi e ricomposto i frammenti dell'amuleto di Lord Valthalak?",
  reward = "Immagino sia meglio così, che le anime di quei due abbiano finalmente trovato pace, anche se da vivi non mi piacevano. In ogni caso abbiamo quello che cercavamo, e ora l'amuleto è ricomposto! Ma la prova più dura ci aspetta ancora.$B$BPerché il braciere si sintonizzi sull'evocazione di Lord Valthalak, ci sono ancora alcuni oggetti da raccogliere e da portarmi qui.",
}
T[8992] = {
  title = "Il Frammento Destro dell'Amuleto di Sire Valthalak",
  desc = "Ora abbiamo quello che ci serve, quindi è il momento di parlare di chi dovrai evocare adesso.$B$BKormok era a posto, per essere un ogre, almeno finché non si è dato alla negromanzia. Da allora, le cose si sono fatte inquietanti più o meno per tutti nella compagnia. Nessuno si è sorpreso, quindi, quando ha preso il suo frammento dell'amuleto e se n'è tornato nella sua nuova casa, Scholomance.$B$BMa neanche lì, o forse soprattutto lì, era al sicuro dagli assassini spettrali. Lo hanno ucciso proprio davanti al suo padrone, Ras Frostwhisper.",
  obj = "Usa il Brazier of Beckoning per evocare lo spirito di Kormok e uccidilo. Torna da Bodley dentro Blackrock Mountain con il Lord Valthalak's Amulet ricomposto e il Brazier of Beckoning.",
  progress = "Ti faccio i miei complimenti, $N, se sei tornat$Go:a; con l'amuleto completo. Se invece non è così, provvedi, per favore, perché non c'è tempo da perdere, te lo assicuro!",
  reward = "Ottimo lavoro, $N! Kormok non era poi così male per essere un ogre, almeno finché era vivo, quindi spero che trovi il riposo che merita. E ora abbiamo l'amuleto completo! Ma la prova più dura deve ancora venire.$B$BPerché il braciere si sintonizzi sul richiamo di Lord Valthalak, ci sono ancora alcuni oggetti da raccogliere e riportare qui da me.",
}
T[8993] = {
  title = "Fare Regali",
  progress = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e di adorazione al tuo capo preferito?",
  reward = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.$B$BNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.$B$BOra, fammene aggiungere un altro al conteggio...",
  en_title = "Gift Giving",
}
T[8994] = {
  title = "Ultimi Preparativi",
  desc = "Ci siamo quasi, $C. Non resta che recuperare qualche altro componente, così potrò sintonizzare il braciere e metterlo in grado di richiamare Lord Valthalak.$B$BPer cominciare devo chiederti di addentrarti in Blackrock Spire e uccidere gli orchi che vi si trovano. Portano bracciali che contengono tracce di metalli di cui ho bisogno, quindi me ne serviranno parecchi per estrarne la quantità giusta. Poi, per completare l'infusione, dovrai portarmi un Tonico della Potenza Suprema.$B$BBuona fortuna, $N!",
  obj = "Raccogli 40 Blackrock Bracers e procurati un Flask of Supreme Power. Portali a Bodley dentro Blackrock Mountain.",
  progress = "Ne abbiamo fatta di strada, $N, e volevo solo dirti che, comunque vada, ti ringrazio! Hai messo a rischio la vita per cercare di aiutare i superstiti della nostra compagnia di mercenari, The Veiled Blade, e per quanto mi riguarda ormai sei $Guno:una; di noi.",
  reward = "Ecco fatto, allora. Estrarrò il metallo dai bracciali e infonderò nel braciere questi ultimi componenti. Poi sarà pronto, e potrai evocare Lord Valthalak e restituirgli finalmente il suo amuleto dello spirito.$B$BHai fatto tanta strada, $N, non cedere proprio ora che la fine è vicina!",
}
T[8995] = {
  title = "Mea Culpa, Lord Valthalak",
  desc = "Ora è tutto pronto, $N.$B$BDa vivo, Lord Valthalak abitava in quella che oggi è la sala della Bestia. Vai lì e usa il Braciere del Richiamo per evocare Lord Valthalak. Lo farà tornare in carne e ossa, perciò bisognerà ucciderlo di nuovo. Io prima mi occuperei della Bestia, e bada di portarti abbastanza amici da sopravvivere alla parte superiore di Blackrock Spire.$B$BQuando avrai eliminato Valthalak, usa l'amuleto sul suo cadavere. Con lo spirito di nuovo intero, è probabile che rivoglia anche il suo amuleto.$B$BBuona fortuna!",
  obj = "Usa il Brazier of Beckoning per evocare Lord Valthalak. Eliminalo e usa Lord Valthalak's Amulet sul cadavere. Poi restituisci Lord Valthalak's Amulet allo Spirit of Lord Valthalak.",
  progress = "$C, osi disturbare il mio riposo!",
  reward = "Buon per te che io sappia che non fai parte del gruppo che a suo tempo me l'ha rubato.$B$BOra mi riprendo ciò che è mio, mortale! Dammi l'amuleto!",
}
T[8996] = {
  title = "Torna da Bodley",
  desc = "Per questa volta ignorerò la tua impertinenza, $C, perché oggi hai compiuto un gesto nobile; mi hai restituito il resto dello spirito che mi era stato rubato. Nonostante la tua natura palesemente debole, $R, hai dimostrato coraggio là dove chi mi ha derubato non l'ha avuto, e probabilmente non potrebbe averlo mai!$B$BTorna da loro, prima che io cambi idea e ti uccida lì dove ti trovi. Torna indietro e di' loro che sono al sicuro... per ora.",
  obj = "Torna da Bodley dentro Blackrock Mountain e dagli il Brazier of Beckoning.",
  progress = "$N, sei $Gtornato:tornata; e sei ancora $Gvivo:viva;! Be', almeno uno di noi due lo è.$B$BMi devi raccontare tutto!",
  reward = "Ha detto davvero tutto questo? Caspita, non riesco a credere che ritirerà gli assassini e gli inseguitori spettrali, anche se ha lasciato intendere che in futuro farà ancora del male ai miei compagni rimasti in vita.$B$BÈ un gran giorno, $N! Sei $Griuscito:riuscita; in un'impresa alla portata di pochi, e ci hai assolti, almeno in parte, da alcuni dei nostri peccati passati.$B$BGrazie! In segno di riconoscenza, vorrei darti questo. Puoi usarlo per evocare gli spiriti negli stessi luoghi infestati dove l'hai già fatto, e anche in qualche altro.",
}
T[8997] = {
  title = "Ritorno all'Inizio",
  desc = "Allora immagino che questo sia un addio, $Gamico mio:amica mia;. Però io sarò sempre qui, se ogni tanto vorrai tornare a parlare con me. Probabilmente mentre ciondoli qui intorno in attesa che i tuoi amici ti raggiungano per un'incursione a Blackrock Spire.$B$BVai, prima che mi metta a piangere. Torna da Deliana a Ironforge e raccontale cos'è successo.",
  obj = "Parla con Deliana a The High Seat, a Ironforge.",
  reward = "Sono molto felice che tu sia $Gtornato:tornata; da me $Gsano e salvo:sana e salva;, $N. Ti trovo bene, anche se un po' $Gprovato:provata;.$B$BVieni, raccontami tutto quello che è successo.",
}
T[8998] = {
  title = "Ritorno all'Inizio",
  desc = "Allora immagino che questo sia un addio, $Gamico mio:amica mia;. Ma io sarò sempre qui, se ogni tanto vorrai tornare a fare due chiacchiere con me. Probabilmente mentre ciondoli qui intorno aspettando che i tuoi amici ti raggiungano per un'incursione a Blackrock Spire.$B$BVai, prima che mi metta a piangere. Torna da Mokvar a Orgrimmar e raccontagli cos'è successo.",
  obj = "Parla con Mokvar alla Fortezza di Grommash, nella Valley of Wisdom di Orgrimmar.",
  reward = "Sono lieto di vedere che sei $Gsopravvissuto:sopravvissuta;, $N. Ti trovo bene, forse solo un po' più $Gtemprato:temprata;.$B$BVieni, raccontami tutto quello che è successo.",
}
T[8999] = {
  title = "Il Meglio per Ultimo",
  desc = "È una storia incredibile, $N! Ti ringrazio io, e ti ringraziano di cuore tutti quelli che erano coinvolti. Forse adesso riuscirò a dormire la notte con tutti e due gli occhi chiusi.$B$BQuanto alla tua ricompensa, credo di avere alcune cose che ti piaceranno davvero.",
  obj = "Dai a Deliana il tuo Wildheart Cowl e la tua Wildheart Vest.",
  progress = "Come da accordi, sei $Gpronto:pronta; a consegnare i tuoi pezzi Wildheart in cambio del tuo nuovo Copricapo e della tua nuova Veste del Cuore Ferino?",
  reward = "Mi mancherai, $N. Ho con te un debito di gratitudine enorme; credo che non riuscirò mai a ripagarlo.$B$BSpero che la tua nuova armatura per la testa e per il petto ti piaccia, e che ti protegga ancora a lungo.",
}
