T[9007] = {
  title = "Il Meglio per Ultimo",
  desc = "Una storia davvero incredibile, $N! Ti ringrazio, e ti assicuro che hai la sincera gratitudine di tutti quelli che sono stati coinvolti. Grazie ai tuoi sforzi ci siamo liberati dagli errori del nostro passato.$B$BQuanto alla tua ricompensa, credo di avere alcune cose che hai senz'altro meritato e che apprezzerai davvero.",
  obj = "Consegna a Mokvar il tuo Wildheart Cowl e la tua Wildheart Vest.",
