T[9015] = {
  title = "La Sfida",
  desc = "Ascoltami bene, $N. Perché lo stendardo funzioni nel modo voluto, dovrai entrare nell'Anello della Legge, nelle Blackrock Depths. Lasciati condannare dal Gran Giudice Grimstone e pianta saldamente lo stendardo a terra in segno di sfida.$B$BLa tua vittima non riuscirà a trattenersi e si getterà nella mischia con una gran voglia di combatterti. Quando avrai ottenuto ciò che cerchi, torna da Anthion.",
  obj = "Raggiungi il Ring of the Law nelle Blackrock Depths e pianta il Banner of Provocation al centro mentre High Justice Grimstone ti condanna. Uccidi Theldren e i suoi gladiatori e torna da Anthion Harmon nelle Eastern Plaguelands con il primo pezzo dell'amuleto di Lord Valthalak.",
  progress = "Sei $Gtornato:tornata;, $N!",
  reward = "Hai recuperato una parte del medaglione, $N?",
}
T[9016] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità siamo stati così sciocchi da dividerlo in tre parti, ignari della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i pezzi che mancano. Quanto alle ricompense che avete pattuito, parlane con lui.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta quanta!",
  obj = "Torna da Mokvar a Orgrimmar con un paio di Wildheart Boots, un Wildheart Kilt e dei Wildheart Spaulders.",
  progress = "Sei $Gtornato:tornata;, e ti leggo negli occhi che hai molto da raccontarmi, $N. Prima pensiamo alla tua ricompensa.",
  reward = "Questa maledizione ci è stata inflitta per un semplice medaglione. Lord Valthalak sa di certo come portare rancore.$B$BFaremo il possibile per trovare i pezzi che mancano — prima che io vada incontro a una fine prematura, si spera. Prima, però, occupiamoci della tua ricompensa.",
}
T[9017] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità siamo stati così sciocchi da dividerlo in tre parti, ignari della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i pezzi che mancano. Quanto alle ricompense che avete pattuito, parlane con lui.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta quanta!",
  obj = "Torna da Mokvar a Orgrimmar con un paio di Beaststalker's Boots, Beaststalker's Pants e Beaststalker's Mantle.",
  progress = "Sei $Gtornato:tornata;, e ti leggo negli occhi che hai molto da raccontarmi, $N. Prima pensiamo alla tua ricompensa.",
  reward = "Questa maledizione ci è stata inflitta per un semplice medaglione. Lord Valthalak sa di certo come portare rancore.$B$BFaremo il possibile per trovare i pezzi che mancano — prima che io vada incontro a una fine prematura, si spera. Prima, però, occupiamoci della tua ricompensa.",
}
