  obj = "Torna da Mokvar a Orgrimmar con un paio di Magister's Boots, Magister's Leggings e Magister's Mantle.",
  progress = "Sei $Gtornato:tornata;, e ti leggo negli occhi che hai molto da raccontarmi, $N. Prima pensiamo alla tua ricompensa.",
  reward = "Questa maledizione ci è stata inflitta per un semplice medaglione. Lord Valthalak sa di certo come portare rancore.$B$BFaremo il possibile per trovare i pezzi che mancano — prima che io vada incontro a una fine prematura, si spera. Prima, però, occupiamoci della tua ricompensa.",
}
T[9019] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Per avidità siamo stati così sciocchi da dividerlo in tre parti, ignari della maledizione che ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i pezzi che mancano. Quanto alle ricompense che avete pattuito, parlane con lui.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna del mondo; ti servirà tutta quanta!",
  obj = "Torna da Mokvar a Orgrimmar con un paio di Devout Sandals, una Devout Skirt e un Devout Mantle.",
  progress = "Sei $Gtornato:tornata;, e ti leggo negli occhi che hai molto da raccontarmi, $N. Prima pensiamo alla tua ricompensa.",
  reward = "Questa maledizione ci è stata inflitta per un semplice medaglione. Lord Valthalak sa di certo come portare rancore.$B$BFaremo il possibile per trovare i pezzi che mancano — prima che io vada incontro a una fine prematura, si spera. Prima, però, occupiamoci della tua ricompensa.",
}
