}
T[9023] = {
  title = "Il Veleno Perfetto",
  desc = "Io e mio fratello gestiamo le attività legate ai veleni dal maniero di Ravenholdt.$B$BLord Ravenholdt mi ha incaricato di rintracciare un nuovo composto velenoso, estremamente efficace, che si può ricavare dalle sacche di veleno degli abitanti di Zul'Gurub e delle Ruins of Ahn'Qiraj.$B$BIn quelle maledette rovine vivono due bestie particolarmente velenose che hanno quello che forse stiamo cercando, $C. Portami una sacca di veleno delle bestie Kurinnaxx e Venoxis e te ne saremo eternamente grati.",
  obj = "Dirk Thunderwood, a Cenarion Hold, vuole che tu gli porti Venoxis's Venom Sac e Kurinnaxx's Venom Sac.",
  progress = "Non è mica un colpo da arraffa e scappa, $N. Ti toccherà portare degli amici.",
  reward = "Ravenholdt ti ringrazia, $Geroe:eroina;! Scegli pure!",
}
T[9024] = {
  title = "L'Intuizione di Aristan",
  desc = "Ci sono! Hai sentito il nuovo profumo nell'aria? Le nuove acque di colonia e i profumi che sono diventati di moda? Le nostre guardie non trascurerebbero i loro doveri così facilmente.$B$BA meno che la loro mente non sia stata annebbiata da qualche alchimia immonda.$B$BC'è un solo modo per esserne sicuri — porta una bottiglia di acqua di colonia e una di profumo a Morgan Pestle, e riferiscigli i miei sospetti. Ti rimborserò l'acquisto quando tornerai.",
  obj = "Porta 1 Cologne Bottle e 1 Perfume Bottle a Morgan Pestle, nel Trade District di Stormwind.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Capisco le preoccupazioni di Aristan, ma credo davvero che stia esagerando. Lascia che i ragazzi e le ragazze facciano quello che vogliono. Credo che Aristan abbia dimenticato cosa vuol dire essere giovani e innamorati.$B$BMa sarà meglio non dirglielo. Lo accontenteremo.",
  en_title = "Aristan's Hunch",
  en_obj = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind.",
}
T[9025] = {
  title = "La Scoperta di Morgan",
  desc = "Ma guarda un po'. Sembra che Aristan, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nei filtri d'amore e in subdole pozioni che alterano la mente.$B$BNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Hanno un odore strano.",
  obj = "Torna da Aristan Mottar, fuori dalla banca nel Trade District di Stormwind.",
  reward = "Anche se pensavo che sarebbe andata così, scoprire che i miei sospetti erano fondati è comunque inquietante. Dobbiamo valutare con attenzione la nostra prossima mossa.$B$BEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.",
  en_title = "Morgan's Discovery",
  en_obj = "Return to Aristan Mottar outside the bank in Stormwind's Trade District.",
}
T[9026] = {
  title = "Risalire alla Fonte",
  desc = "Dobbiamo trovare la fonte. Ho visto molta più gente del solito — guardie comprese — entrare e uscire dalla Gilded Rose. Parla con Allison. Se è lei a venderli, può dirti da dove vengono.",
  obj = "Parla con Innkeeper Allison a Gilded Rose, nel Trade District di Stormwind.",
  reward = "Oh sì, ho ricevuto da poco il profumo e l'acqua di colonia. Si vendono così bene che non so quanto riuscirò a tenerli sugli scaffali.$B$BSe vuoi il mio parere, è un po' noioso. Tutti con lo stesso odore? Profuma benissimo, ma insomma.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District.",
}
T[9027] = {
  title = "Risalire alla Fonte",
  desc = "C'è qualcosa di strano nell'acqua di colonia? È possibile. Non ho mai visto così tanta gente cercare un prodotto in questo modo.$B$BSenti, se c'è qualcosa che non va, voglio saperlo anch'io. Ho comprato la mia scorta da un mercante di nome Evert Sorisam. È nuovo in città.$B$BHa detto che aveva della merce da consegnare a The Finest Thread.",
  obj = "Parla con Evert Sorisam a The Finest Thread, lungo i Canals di Stormwind.",
  reward = "Sì, certo. Quelle fragranze sono gli articoli più richiesti della stagione. Sarai la quinta o sesta persona che me ne chiede nell'ultima ora.$B$BPurtroppo ho esaurito tutte le scorte. Se ne vuoi un po', dovresti parlare con Allison, la locandiera della Gilded Rose.$B$BPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Evert Sorisam at The Finest Thread along Stormwind's Canals.",
}
T[9028] = {
  title = "La Fonte Svelata",
  desc = "Cosa? Tradimento? No, no. Ti assicuro che le mie intenzioni sono del tutto innocue.$B$BÈ così sbagliato aiutare chi vuole alleviare il doloroso rituale del corteggiamento? Andiamo, non è un crimine.$B$BE per dimostrare che non ho cattive intenzioni, ti dirò persino chi è il mio fornitore.$B$BMe li ha spediti un certo Staffron Lerent, una specie di speziale. Non ci ho mai parlato.$B$BIl nostro intermediario goblin ha detto che lavorava sulle colline sopra Hillsbrad, oltre quel misterioso Maniero dei Ravenholdt. Ti auguro buona fortuna nel trovarlo.",
  obj = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, dietro il Maniero dei Ravenholdt.",
  reward = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.$B$BUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.$B$BSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno il mordente.$B$BLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.",
  en_title = "The Source Revealed",
  en_obj = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor.",
}
T[9029] = {
  title = "Un Calderone Gorgogliante",
  reward = "Un profumo gradevole si leva dal calderone.",
  en_title = "A Bubbling Cauldron",
}
T[9030] = {
  title = "Le Parole d'Addio di Anthion",
  desc = "L'anima di Valthalak era custodita in questo amuleto. Nella nostra avidità lo abbiamo stupidamente diviso in tre parti, senza sapere quale maledizione ci attendeva.$B$BL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza di trovare i frammenti rimasti.$B$BIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna possibile, e ne avrai bisogno!",
  obj = "Parla con Deliana a Ironforge.",
}
T[9032] = {
  title = "La Triste Sorte di Bodley",
  desc = "Il medaglione conteneva l'anima di Valthalak? Non c'è da stupirsi che fosse protetto da una maledizione così potente.$B$BTrovare Bodley è un po' un problema. L'ultima volta che ho avuto sue notizie, si preparava a tornare a Blackrock Spire. Da allora non se n'è saputo più nulla.$B$BCercalo a Blackrock Mountain, anche se, mi spiace dirlo, probabilmente ormai è morto. Ti consiglio di portare con te il congegno del goblin, $Gamico:amica;.",
  obj = "Vai a Blackrock Mountain e usa l'Extra-Dimensional Ghost Revealer per trovare Bodley vicino a Blackrock Spire.",
  reward = "Sono così contento che tu riesca a vedermi. Finalmente qualcuno con cui parlare!$B$BCi aiuterai, $N? Ci aiuterai a riparare al torto che abbiamo commesso e a rimettere le cose a posto? Se è vero che hai già la Parte Superiore dell'Amuleto di Sire Valthalak, allora credo di poterti indicare la strada giusta per trovare le altre due parti, riunirle e mettere fine a tutta questa storia.$B$BAh, a proposito, ciao, mi chiamo Bodley. Piacere di conoscerti!",
}
T[9033] = {
  title = "Echi di Guerra",
  desc = "Cinque anni dall'ultima guerra...$B$BSono andate perdute decine di migliaia di vite, e per cosa? La minaccia non è mai stata debellata del tutto.$B$BE così il Re dei Lich si ridesta ancora una volta... Il suo tirapiedi, Kel'Thuzad, raduna le forze per un altro attacco alle nostre terre.$B$BNon lo permetteremo! Dimostra la tua dedizione. Dimostra che sei $Gdisposto:disposta; a mettere a repentaglio la vita per fermare questa follia, e la forza unita della Dawn e della Crociata sarà a tua completa disposizione.$B$BEntra a Naxxramas e distruggi il Flagello al suo interno...",
  obj = "Commander Eligor Dawnbringer, a Light's Hope Chapel nelle Eastern Plaguelands, vuole che tu uccida 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains e 3 Venom Stalkers.",
  progress = "Dovere, onore, dedizione... Cosa significano per te queste parole?",
  reward = "Ottimo lavoro! Sarai $Gricompensato:ricompensata; con i servizi degli uomini e delle donne della Cappella della Luce.",
}
T[9051] = {
  title = "La Prova della Tossina",
  desc = "La tossina che mi hai aiutato a creare ha uno scopo particolare. Per colpa dei grandi gigantosauri del cratere cacciare è pericoloso, e per me è difficile sopravvivere. Anche se ne avessi la forza, uccidere un gigantosauro non farebbe che lasciare il suo territorio a un altro.$B$BPrendi questa punta avvelenata e conficcala a fondo in un gigantosauro vivo. La tossina dovrebbe placare la creatura, anche se non so in quanto tempo...",
  obj = "Trafiggi un Devilsaur con il Devilsaur Barb. Torna da Torwa Pathfinder, a Un'Goro Crater, quando avrai portato a termine questo compito.",
  progress = "Sei $Griuscito:riuscita; a placare la grande bestia?",
  reward = "Grazie, $N. Sei $Gcoraggioso e saggio:coraggiosa e saggia;.$B$BDimmi, come ha reagito il gigantosauro alla tossina?",
}
T[9052] = {
  title = "Veleno di Bloodpetal",
  desc = "Vorrei chiederti di aiutarmi a creare una specie di tossina, per placare una grande creatura che vive qui nel cratere. Non è mortale, e solo gli occhi acuti di $Gun:una; $C possono sperare di raccogliere gli ingredienti.$B$BI funghi testasangue crescono dentro i germogli di bloodpetal, in tutto il cratere. I pungiglioni dei Gorishi vengono dalle gigantesche vespe volanti che stanno dentro e intorno all'Anfratto Brulicante, nella parte meridionale del cratere.",
  obj = "Raccogli 8 Bloodcap e 8 Gorishi Stings, poi torna da Torwa Pathfinder, a Un'Goro Crater.",
  progress = "Ci sei $Griuscito:riuscita;?",
  reward = "Finalmente gli ingredienti!$B$BCon il terreno di Un'Goro che ho raccolto, la tossina si prepara facilmente...",
}
T[9053] = {
  title = "Un Ingrediente Migliore",
  desc = "È come temevo — la tossina è semplicemente troppo debole per una creatura così potente.$B$BSe vogliamo creare una tossina abbastanza forte, devi spingerti fino in fondo al Temple of Atal'Hakkar, svelare i segreti dell'altare e recuperare una vite putrida dal guardiano che si trova lì. Il tempio è pericoloso, e faresti bene a portare degli amici.$B$BTorna da me quando avrai finito.",
  obj = "Recupera una Putrid Vine dal guardiano in fondo al Sunken Temple e torna da Torwa Pathfinder.",
  progress = "Hai recuperato la vite?",
  reward = "Finalmente si può creare la tossina completa. Non oso chiederti di infliggerla di nuovo alla creatura, perché ti ho già chiesto troppo.$B$BTi ringrazio, e hai il mio rispetto. Che i tuoi viaggi siano sereni, $N.",
}
T[9063] = {
  title = "Torwa Pathfinder",
  desc = "Un cacciatore di nome Torwa Pathfinder ha chiesto l'aiuto di un druido. Ha detto che solo noi abbiamo le capacità e il rispetto per la natura necessari per aiutarlo.$B$BC'è una strada che collega l'Un'Goro Crater al deserto di Tanaris. Troverai Torwa lì vicino, nel punto in cui la strada entra nel cratere.",
  obj = "Parla con Torwa Pathfinder, a Un'Goro Crater.",
  reward = "Hai fatto molta strada per incontrarmi, $C, e sei $Garrivato:arrivata; appena in tempo.",
}
T[9085] = {
  title = "Ombre della Rovina",
  desc = "Quando avrai abbattuto le difese dei cerchi di evocazione del Flagello comparsi nelle zone sotto attacco, potrai affrontare gli accoliti che li proteggono.$B$BIn realtà non sono uomini. Sono ombre, fra le creature più spaventose del Re dei Lich. Si possono rivelare con le rune necrotiche che portano con sé, e poi distruggere con la magia o con la forza delle armi.",
  obj = "Vai a un cerchio di evocazione e uccidi una Shadow of Doom, poi torna da Commander Thomas Helleran a Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Com'è andata, $N?",
  reward = "Ottimo lavoro, $N. Ora che le ombre sono distrutte, è solo questione di tempo prima che il Re dei Lich decida di richiamare le sue necropoli e di lasciarci in pace.",
}
T[9094] = {
  title = "Guanti dell'Argent Dawn",
  progress = "Se mi porti trenta rune necrotiche, in cambio ti darò delle protezioni per le mani a tua scelta. Dovrebbero rivelarsi preziose nella nostra lotta contro i non morti del Flagello.",
  reward = "Hai fatto un buon lavoro, $N. Scegli la protezione per le mani che preferisci, come ringraziamento per il tuo impegno.",
}
T[9120] = {
  title = "La Caduta di Kel'Thuzad",
  desc = "Il filatterio è tutto ciò che resta del padrone di Naxxramas. Il buon senso ti impone di distruggerlo, così che il lich non possa riformarsi mai più. Per fortuna, dai retta di rado a quella voce interiore della ragione.$B$BQualcuno alla Cappella della Luce ti pagherà profumatamente per questo artefatto. Che importa se Kel'Thuzad si rigenera e torna al pieno della sua potenza?",
  obj = "Porta il Phylactery of Kel'Thuzad a Light's Hope Chapel nelle Eastern Plaguelands.",
}
T[9121] = {
  title = "La Terribile Cittadella — Naxxramas",
  desc = "Nel folto di Plaguewood si trova l'ingresso della terribile cittadella di Naxxramas. In passato, ogni tentativo di entrarvi è stato bloccato dalle difese magiche poste sul portale runico. Almeno fino a oggi.$B$BAbbiamo escogitato un modo per entrare grazie all'occultamento arcano — un vecchio trucchetto del Kirin Tor con qualche modifica mia. Poiché la tua dedizione alla causa della Dawn lascia un po' a desiderare, $N, il prezzo sarà alto. Puoi rifiutare e decidere di tornare quando sarai revered o exalted, per avere uno sconto.",
  obj = "Archmage Angela Dosantos, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb e 60 monete d'oro. Devi anche essere Honored presso l'Argent Dawn.",
  progress = "Nessuno è entrato a Naxxramas ed è tornato vivo per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N. Quella sensazione vuol dire che sta funzionando. Una volta completato, potrai entrare a Naxxramas salendo sul portale runico di Plaguewood.",
}
T[9122] = {
  title = "La Terribile Cittadella — Naxxramas",
  desc = "Nel folto di Plaguewood si trova l'ingresso della terribile cittadella di Naxxramas. In passato, ogni tentativo di entrarvi è stato bloccato dalle difese magiche poste sul portale runico. Almeno fino a oggi.$B$BAbbiamo escogitato un modo per entrare grazie a una specie di occultamento arcano permanente — un vecchio trucchetto del Kirin Tor con qualche modifica mia. Detto questo, l'occultamento è costoso. Poiché la tua dedizione alla causa della Dawn è ammirevole, siamo disposti a farci carico di una parte di quei costi.",
  obj = "Archmage Angela Dosantos, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 2 Arcane Crystals, 1 Nexus Crystal e 30 monete d'oro. Devi anche essere Revered presso l'Argent Dawn.",
  progress = "Nessuno è entrato a Naxxramas ed è tornato vivo per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N. Quella sensazione vuol dire che sta funzionando. Una volta completato, potrai entrare a Naxxramas salendo sul portale runico di Plaguewood.",
}
T[9123] = {
  title = "La Terribile Cittadella — Naxxramas",
  desc = "Nel folto di Plaguewood si trova l'ingresso della terribile cittadella di Naxxramas. In passato, ogni tentativo di entrarvi è stato bloccato dalle difese magiche poste sul portale runico. Almeno fino a oggi.$B$BAbbiamo escogitato un modo per entrare grazie a una specie di occultamento arcano permanente — un vecchio trucchetto del Kirin Tor con qualche modifica mia. Detto questo, l'occultamento è costoso; la tua dedizione alla causa della Dawn, però, è incrollabile! Non ti faremo pagare niente.",
  obj = "Archmage Angela Dosantos, a Light's Hope Chapel nelle Eastern Plaguelands, ti concederà l'Arcane Cloaking gratuitamente. Devi essere Exalted presso l'Argent Dawn.",
  progress = "Nessuno è entrato a Naxxramas ed è tornato vivo per raccontarlo.",
  reward = "Sentirai un leggero formicolio, $N. Quella sensazione vuol dire che sta funzionando. Una volta completato, potrai entrare a Naxxramas salendo sul portale runico di Plaguewood.",
}
T[9124] = {
  title = "L'Armatura Cryptstalker Non si Fa da Sola...",
  desc = "Ti andrebbe di guadagnarti una di queste monete luccicanti?$B$B<Leopold solleva un fregio della Crociata.>$B$BHo un problemino con cui forse puoi darmi una mano, $N. Vedi, io faccio armature Cryptstalker per chi è tanto matto da avventurarsi a Naxxramas. I materiali di base per l'armatura me li portano loro, ma resto sempre senza parti di demonio delle cripte. Portami un carico di parti e ti pagherò con un fregio — lo puoi usare dal quartiermastro.",
  obj = "Huntsman Leopold, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 30 Crypt Fiend Parts.",
  progress = "Come va la caccia?",
  reward = "Ah, così va benissimo, $N. Ricorda che di parti ne accetto sempre altre. Per ogni carico che mi porti, ti ricompenserò con un fregio.",
}
T[9125] = {
  title = "Parti di Demonio delle Cripte",
  progress = "Con il primo carico hai fatto un lavoro esemplare, $N. Se hai altre parti, le prendo subito. Per ogni carico che consegni, ti ricompenserò con un altro fregio.",
  reward = "Eccellente davvero, $N! Queste torneranno sicuramente utili.",
}
T[9126] = {
  title = "Scavi per la Bonescythe",
  desc = "Lo schema dell'armatura Bonescythe di Don Julio richiede frammenti d'osso — tanti frammenti d'osso. Chi è abbastanza pazzo da avventurarsi a Naxxramas mi porta materiali di base a sufficienza per fare l'armatura, ma io sono sempre in cerca di altri frammenti d'osso del Flagello.$B$BAllora, che ne dici? Ti va di sporcarti le mani e intanto distruggere un po' di Flagello? Ci guadagniamo tutti e due.",
  obj = "Rohan the Assassin, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 30 Bone Fragments.",
  progress = "Posso indicarti dei posti infestati dagli scheletri, $C.",
  reward = "Lavori in fretta, $N. Veloce come una volpe... Senti, ti ho mai raccontato di quando cantavo in un quartetto barbershop?$B$BRicordami di raccontarti quella storia, uno di questi giorni.",
}
T[9127] = {
  title = "Frammenti d'Osso",
  progress = "Per un uomo che fa il mio mestiere i frammenti d'osso non sono mai troppi, $N. Ogni volta che ne hai in più, portameli e ti ricompenserò con un altro fregio.",
  reward = "Il mio sogno di diventare ballerino a tempo pieno nella discoteca di Gadgetzan sta per diventare realtà! Continua così, $N.",
}
T[9128] = {
  title = "L'Equazione Elementale",
  desc = "Salute, $Gavventuriero:avventuriera;! Ti interessa un lavoro? Chi lavora per me lo pago in fregi. Questi fregi si possono usare dal Quartiermastro per acquistare oggetti di potere.$B$BDevi solo portarmi tutti i nuclei di elementi che riesci a trasportare. Più sono, meglio è!$B$BLi troverai sugli elementali di varie forme e dimensioni che esistono in tutto il nostro mondo.",
  obj = "Archmage Angela Dosantos, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 30 Core of Elements.",
  progress = "Io posso solo indicarti la direzione giusta, $N.",
  reward = "Ottimo lavoro, $N! Come promesso, il fregio è tuo. Ricorda solo che ce ne sono ancora tanti altri...",
}
T[9129] = {
  title = "Nucleo di Elementi",
  progress = "A dire il vero, i nuclei li uso per creare l'armatura Frostfire. È l'armatura usata dai maghi che combattono a Naxxramas. Senza di te e senza altri come te, questa guerra la staremmo sicuramente perdendo.$B$BDetto questo, portami altri nuclei e ti darò altri fregi.",
  reward = "Ci rendi un grande servizio, $N. $GBravo:Brava;!",
}
T[9131] = {
  title = "Assemblare la Dreadnaught",
  desc = "Hai mai visto un'armatura Dreadnaught, $C? No, certo che no. Sei ancora $Gun ragazzino:una ragazzina; — $Gun marmocchio:una marmocchia;. Te lo dico io, è magnifica.$B$BTi starai chiedendo cosa c'entri tu in tutto questo, vero? Te lo dico subito, $Gpivello:pivella;; mi servono brandelli dei Dark Iron e sono disposto a pagare per mettere le mani su tutti quelli che posso.$B$BI brandelli mi servono per mettere insieme i completi Dreadnaught per i nostri campioni. Portami i brandelli e ti pago.",
  obj = "Korfax, Champion of the Light, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 30 Dark Iron Scraps.",
  progress = "<Korfax ti ringhia contro.>$B$BChe vuoi? Indicazioni? Quelle te le posso dare...",
  reward = "Può bastare, per ora. Se te ne procuri altri, sai dove trovarmi.",
}
T[9132] = {
  title = "Brandelli dei Dark Iron",
  progress = "Per ogni bracciata di brandelli ti do un fregio — più sono, meglio è. E adesso sparisci dalla mia vista, prima che ti spacchi in due!",
  reward = "È tutto qui quello che mi hai portato? Forse la prima volta non mi hai sentito. Me ne servono DI PIÙ!",
}
T[9136] = {
  title = "Flora Selvaggia",
  desc = "Per i coraggiosi eroi che entrano a Naxxramas creo un tipo speciale di armatura, chiamato Dreamwalker. Loro riescono a fornirmi quasi tutti i materiali che mi occorrono, ma io sono sempre in cerca di qualcuno capace di recuperare fronde selvagge dalla flora del nostro mondo.$B$BForse consideri questo lavoro indegno di te, ma senza le fronde l'armatura non si potrebbe fare.$B$BInoltre la mia posizione è unica: posso pagarti con un fregio a tua scelta, perché sia la Dawn sia la Crociata mi forniscono fondi.",
  obj = "Rayne, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 30 Savage Fronds.",
  progress = "Conosco a fondo la flora del nostro mondo. Ti servono indicazioni?",
  reward = "Ti sono molto grata, $N.$B$B<Rayne si inchina.>$B$BRicorda, ti prego, che di fronde ne accetto sempre.",
}
T[9137] = {
  title = "Fronde Selvagge",
  progress = "Per ogni fascio di fronde che mi consegnerai, ti pagherò con un fregio della Dawn o della Crociata, a tua scelta.$B$BI fregi si possono consegnare al Quartiermastro in cambio di varie ricompense.",
  reward = "Grazie, $N. Il tuo lavoro è vitale per il successo della nostra campagna contro il Flagello.",
}
T[9141] = {
  title = "Mi Chiamano \"Il Gallo\"",
  desc = "Vuoi un mandato? Cosa? Ti aspetti che ti consegni un ordine di lavoro ambitissimo solo perché ti sei $Gpresentato:presentata; qui? Non credo proprio, $Gpivello:pivella;. Artigiani di tutto il mondo fanno a gara per accaparrarsi gli incarichi qui in prima linea.$B$BSe vuoi un ordine di lavoro, dovrai dimostrarmi che sei $Gdisposto:disposta; a versare sangue per la causa. Portami un emblema del valore e ne parliamo.$B$BE per metterci sopra quelle tue manine luride da $Gpivello:pivella; c'è un solo modo — mettiti ad ammazzare.",
  obj = "Dispatch Commander Metz, a Light's Hope Chapel nelle Eastern Plaguelands, vuole un Argent Dawn Valor Token.",
  progress = "<Il Comandante Metz mastica il sigaro.>$B$BChe c'è? Sono un uomo impegnato.",
  reward = "Va bene, funziona così: per ogni emblema del valore che consegni, ti do un altro mandato. Tu completi l'ordine di quel mandato e lo consegni al Mastro delle Salmerie Stonebruiser. Chiaro? Bene. Ora fuori di qui.",
}
T[9142] = {
  title = "Mandato dell'Artigiano",
  progress = "Sai come funziona, $Gragazzo:ragazza;. Un emblema del valore ti vale un mandato dell'artigiano.",
  reward = "Te lo sei guadagnato, $Gpivello:pivella;. E adesso non frignare per gli ordini. O li completi o li distruggi.",
}
T[9153] = {
  title = "Sotto l'Ombra",
  desc = "Le necropoli fluttuanti del Flagello tormentano le terre dell'Orda come quelle dell'Alleanza. Tanaris, le Blasted Lands, Winterspring e le Burning Steppes sono coperte dalle ombre delle fortezze volanti.$B$BSolo unendo le forze riusciremo a respingerle.$B$BLe necropoli sono sostenute da cerchi magici, in vari punti delle zone invase. Abbiamo appurato che, distruggendo le orde senza mente che circondano questi cerchi, se ne distruggono le difese.",
  obj = "Controlla la mappa per trovare una zona attaccata dal Flagello. Vai lì e danneggia una necropoli sconfiggendo il Flagello che le sta intorno. Riporta 10 delle loro Necrotic Runes a Commander Thomas Helleran a Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Ci vorrà tempo per avere la meglio su questa minaccia. Com'è andata, $N?",
  reward = "Hai fatto un buon lavoro, $N. Con queste sconfitte, una dopo l'altra, avremo la meglio su questa nuova minaccia del Flagello.$B$BRiposa e recupera le forze, ma poi dovrai tornare al fronte, o perderemo il terreno guadagnato oggi.$B$BPer aiutarti nelle prossime battaglie, ti metteremo a disposizione alcuni dei nostri oggetti speciali in cambio di altre rune necrotiche.",
}
T[9154] = {
  title = "Cappella della Luce",
  desc = "Il Flagello è tornato, più numeroso di quanto l'avessimo mai visto. L'Argent Dawn sta reclutando tutti gli uomini e le donne capaci e volenterosi per difendere le nostre terre.$B$BSe la nostra causa è anche la tua, porta questo documento al Custode dei Registri alla Cappella della Luce, nelle Eastern Plaguelands.",
  obj = "Consegna il Call to Arms Announcement al Keeper of the Rolls a Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "Sei $Gvenuto:venuta; per unirti al nostro ordine, non è così?",
  reward = "L'Argent Dawn ha chiesto aiuto e tu, insieme ad altri, hai risposto. Non abbiamo il tempo di addestrarti. Confidiamo nelle tue capacità, e nel fatto che ti unirai a noi per respingere questa minaccia del Flagello.",
}
T[9208] = {
  title = "La Guardia Selvaggia — Arcanum della Protezione",
  desc = "Zanza può creare molti antichi incantamenti dei troll con i componenti adatti! Hai mai sentito parlare della Guardia Selvaggia? No, certo che no. Hai la mente annebbiata dalla scadente magia elfica.$B$BPortami un arcanum di fattura elfica, così che io possa distruggere quell'aberrazione. Fallo e la Guardia Selvaggia sarà tua.",
  obj = "Zanza the Restless a Zul'Gurub vuole un Arcanum of Protection.",
  progress = "Hai l'arcanum?",
  reward = "La magia senza valore di questi incantamenti alimenta la mia rabbia. La mia rabbia mi dà forza.$B$BPortamene altri e riceverai un'altra Guardia Selvaggia.",
}
