T[9211] = {
  title = "La Guardia di Ghiaccio",
  desc = "Ah, la Guardia di Ghiaccio. È una sottile patina di magia protettiva che ricopre certi pezzi di equipaggiamento. Chi combatte contro creature di gelo e ghiaccio, usando la Guardia di Ghiaccio, sarà più protetto dai loro attacchi.$B$BCome per tutto ciò che crea il Wrathcaster, c'è un prezzo — un prezzo che non abbasserò, per quanto tu possa piagnucolare. Ti interessa?",
  obj = "Mataus the Wrathcaster, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 10 Insignia of the Crusade e 30 monete d'oro.",
  progress = "Se non fosse per queste guardie dell'Argent Dawn, saresti una macchia su questo pavimento.",
  reward = "<Mataus intasca l'oro.>$B$BGoditi i costi di riparazione, $R. Naxxramas è 'poco gentile' con i novellini.",
}
T[9213] = {
  title = "La Guardia d'Ombra",
  desc = "Una creazione geniale! Proprio come la Guardia di Ghiaccio, la Guardia d'Ombra si serve di una sottile patina di magia protettiva che ricopre certi pezzi di equipaggiamento. E come la Guardia di Ghiaccio, la Guardia d'Ombra ti costerà un bel po' di soldi.$B$B<Mataus tende la mano e sfrega le dita fra loro.>$B$BTi interessa?",
  obj = "Mataus the Wrathcaster, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 10 Insignia of the Crusade e 30 monete d'oro.",
  progress = "<Mataus sbadiglia.>$B$BSparisci, insetto, a meno che tu non abbia qualcosa per me.",
  reward = "<Mataus si infila l'oro nella veste.>$B$BCosa stai ancora lì a fare, $R? Il nostro affare è concluso.",
}
T[9221] = {
  title = "Armamenti da Battaglia Superiori — $GAmico:Amica; della Dawn",
  desc = "Salute, $Gamico:amica;. Hai dei fregi della Dawn o della Crociata che vorresti scambiare con oggetti di potere?$B$BDevo avvertirti; gli acquisti fatti con una reputazione friendly presso la Dawn comportano un forte sovrapprezzo. Ti consiglierei di farti una reputazione migliore presso la Dawn prima di andare avanti con i tuoi piani.",
  obj = "Per 30 Insignias of the Dawn e 30 Insignias of the Crusade puoi scegliere un oggetto dalla riserva di tesori dell'Argent Dawn.",
  progress = "Scegli con cura. Non si fanno rimborsi.",
  reward = "Buona giornata, $N. È stato un piacere fare affari con te.",
}
T[9222] = {
  title = "Armamenti da Battaglia Epici — $GAmico:Amica; della Dawn",
  desc = "Salute, $Gamico:amica;. Hai dei fregi della Dawn o della Crociata che vorresti scambiare con oggetti di grande potere?$B$BDevo avvertirti; gli acquisti fatti con una reputazione friendly presso la Dawn comportano un sovrapprezzo fortissimo. Ti consiglierei di farti una reputazione migliore presso la Dawn prima di andare avanti con i tuoi piani.",
  obj = "Per 110 Insignias of the Dawn e 110 Insignias of the Crusade puoi scegliere un oggetto dalla riserva di tesori dell'Argent Dawn.",
  progress = "Scegli con cura. Non si fanno rimborsi.",
  reward = "Buona giornata, $N. È stato un piacere fare affari con te.",
}
