T[9229] = {
  title = "Il Destino di Ramaladni",
  desc = "Ramaladni era un guerriero della Brotherhood — un allievo del Gran Signore Mograine prima ancora che la Dawn esistesse! Quando gli giunse la notizia della morte di Mograine, l'odio e la rabbia presero il sopravvento.$B$BSappi questo, $N, quando l'ira e la vendetta prendono le redini, un uomo smette di essere un uomo. Diventa invece l'incarnazione delle emozioni che lo dominano. E fu così che Ramaladni, lo spirito della vendetta, entrò a Naxxramas per vendicarsi... e non fece più ritorno.$B$BEntra a Naxxramas e scopri che ne è stato di Ramaladni.",
  obj = "Entra a Naxxramas e scopri il Fate of Ramaladni.",
  progress = "Ci sono notizie di Ramaladni?",
  reward = "È il suo anello! Ma è distrutto. Non è stata trovata nessun'altra traccia di Ramaladni?$B$B<Korfax fa una smorfia.>$B$BNon promette niente di buono per Ramaladni. L'anello, però... forse si può recuperare.",
}
T[9230] = {
  title = "La Morsa Gelida di Ramaladni",
  desc = "Riparare questo anello potrebbe rivelarsi piuttosto difficile, $N. Vedi, è stato fatto proprio con le rune che si formano dentro le strutture del Flagello — come Naxxramas. Servono anche altri materiali, ma devi pensare soprattutto a procurarti quelle rune congelate. Portami quello che mi serve e riporterò l'anello al suo antico splendore.",
  obj = "Korfax, Champion of the Light, a Light's Hope Chapel nelle Eastern Plaguelands, vuole che tu gli porti 1 Frozen Rune, 1 Blue Sapphire e 1 Arcanite Bar.",
  progress = "Probabilmente le rune congelate si trovano dentro Naxxramas.",
  reward = "Nemmeno Ramaladni in persona avrebbe saputo fare di meglio! Ecco l'anello, come promesso.",
}
T[9232] = {
  title = "L'Unica Canzone che Conosco...",
  desc = "Ti credi $Gun eroe:un'eroina; della Dawn, eh? Ho visto i nostri soldati migliori farsi travolgere dalla marmaglia di Kel'Thuzad! Come potrebbe mai cavarsela a Naxxramas qualcuno di così sprovveduto?$B$B<Wilhelm sospira.>$B$BBah, che scelta c'ho? Sei il meglio che riesco a trovare; tanto vale che ti aiuti.$B$BOmarion mi ha lasciato una ricetta sola. È l'unica canzone che conosco... Di questi pantaloni posso fare qualche variante; tu devi solo procurare i materiali.",
  obj = "Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands, vuole che tu gli porti 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires e 30 monete d'oro.",
  progress = "Non hai mica incontrato Omarion, vero?",
  reward = "<Wilhelm si asciuga il sudore dalla fronte.>$B$BChe faticaccia! Goditi i pantaloni, $C. Almeno adesso morirai con un paio pulito addosso.",
}
T[9233] = {
  title = "Manuale di Omarion",
  desc = "Wilhelm,$B$BSe stai leggendo queste righe, sono morto — finalmente. Voglio che tu sappia che i miei ultimi pensieri ruotavano intorno a te e alla tua inettitudine in fatto di professioni. Purtroppo, quanto a fabbricare oggetti, chi porta questo manuale è messo perfino peggio di te.$B$BRiguardo al libro: queste sono le altre mie ricette. Fabbrica tutto quello che ti chiede chi porta questo libro. Sono sicuro che ti farai pagare profumatamente per i tuoi servizi perché, in fin dei conti, sei un bastardo.$B$BCon disprezzo,$B$BOmarion",
  obj = "Porta Omarion's Handbook a Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands.",
  progress = "È quello che penso?$B$B<Sembra che Wilhelm stia sbavando.>",
  reward = "Doveva esser proprio uscito di testa quando l'ha scritto! Io e Omarion — eravamo culo e camicia!$B$BComunque, questo apre di sicuro qualche possibilità nuova, $N. Adesso posso fabbricare altri oggetti — in cambio di un piccolo compenso e del costo dei materiali, s'intende.",
}
T[9234] = {
  title = "Guanti Lunghi della Rovina dei Ghiacci",
  desc = "Grazie a te e a Omarion, che riposi in pace, adesso sono in grado di creare guanti lunghi della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.",
  obj = "Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water e 200 monete d'oro.",
  progress = "Hai portato i materiali?",
  reward = "Ecco il tuo ordine, $N. Consegnato come promesso!",
}
T[9235] = {
  title = "Bracciali della Rovina dei Ghiacci",
  desc = "Grazie a te e a Omarion (Che riposi in pace), adesso sono in grado di creare bracciali della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.",
  obj = "Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water e 200 monete d'oro.",
  progress = "Hai portato i materiali?",
  reward = "Ecco il tuo ordine, $N. Consegnato come promesso!",
}
T[9236] = {
  title = "Pettorale Corazzato della Rovina dei Ghiacci",
  desc = "Grazie a te e a Omarion (Che riposi in pace), adesso sono in grado di creare un pettorale corazzato della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.",
  obj = "Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water e 300 monete d'oro. Dovrai anche avere reputazione Exalted con l'Argent Dawn.",
  progress = "Hai portato i materiali?",
  reward = "Ecco il tuo ordine, $N. Consegnato come promesso!",
}
T[9237] = {
  title = "Mantello Glaciale",
  desc = "Grazie a te e a Omarion, che riposi in pace, adesso sono in grado di creare un mantello Glaciale. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.",
  obj = "Craftsman Wilhelm, a Light's Hope Chapel nelle Eastern Plaguelands, vuole 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks e 200 monete d'oro. Devi anche avere reputazione Exalted con l'Argent Dawn.",
  progress = "Hai portato i materiali?",
  reward = "Ecco il tuo ordine, $N. Consegnato come promesso!",
}
