T[9247] = {
  title = "La Chiamata del Custode",
  desc = "$N,$B$BIn passato hai servito gli interessi dell'Argent Dawn, sempre al meglio delle tue capacità. Ora, ancora una volta, suoniamo la chiamata alle armi nel momento del nostro più grande bisogno.$B$B$N, ti preghiamo di presentarti al Custode dei Registri, alla Cappella della Luce negli Eastern Plaguelands, se sei $Gdisposto:disposta; ad aiutarci ancora una volta.",
  obj = "Porta la Letter from the Keeper of the Rolls al suo mittente, alla Light's Hope Chapel negli Eastern Plaguelands.",
  en_title = "The Keeper's Call",
  en_obj = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.",
}
T[9248] = {
  title = "Un'Umile Offerta",
  desc = "Ishnu-alah, $R. Mostrami la prova della fine di un Signore dell'Abyssal Council e ti ricompenserò con un oggetto che dovrebbe aiutarti nelle tue battaglie contro i Qiraji.",
  obj = "Aurel Goldleaf, a Cenarion Hold, a Silithus, vuole che tu le porti 1 Abyssal Scepter. Devi inoltre essere Honored presso il Cenarion Circle.",
  progress = "Fandu-dath-belore? Oh, perdonami, $N. Non ti avevo riconosciuto. Hai lo scettro?",
  reward = "Ande'thoras-ethil. Significa: 'Che i tuoi affanni siano alleviati', nella mia lingua natia.$B$BIndossa l'anello con orgoglio, e che ti porti salute, $N.",
}
T[9250] = {
  title = "Corpo di Atiesh",
  desc = "Formato il corpo, Atiesh è quasi completo. Ora mancano solo la testa e la base del bastone. C'è anche il piccolo problema del bastone che fa da tramite al male di Sargeras.$B$BTrova qualcuno che possa aiutarti a rintracciare i pezzi rimasti e a esorcizzare il male dal bastone.",
  obj = "Trova qualcuno che ti aiuti a recuperare gli ultimi due pezzi del bastone e a liberarlo dal male.",
  progress = "Era giunta la sua ora, mortale.",
  reward = "Gli arcimaghi sono morti.$B$BNon piangere la loro scomparsa, $N. Tutte queste cose sono scritte nel destino. Proprio come era scritto che tu impugnassi il bastone del Guardiano...",
}
T[9251] = {
  title = "Atiesh, il Granbastone Contaminato",
  desc = "Ti chiedi perché sei ancora in vita. Dopotutto, hai con te un oggetto di grande malvagità. La risposta non è chiara, $N. Io faccio solo ciò che devo.$B$BKel'Thuzad siede sul suo trono a Naxxramas, e trama... Cerca ciò che tu hai e ha ciò che tu cerchi.$B$BQuanto alla base del bastone; il nano, Brann Bronzebeard, l'aveva con sé quando è entrato ad Ahn'Qiraj. Ha lasciato Ahn'Qiraj, ma la base di Atiesh è rimasta lì.$B$BSe riuscirai a recuperare i pezzi, portameli.",
  obj = "Anachronos, alle Caverns of Time a Tanaris, vuole la Staff Head of Atiesh e la Base of Atiesh.",
  progress = "Nella sua forma attuale, il bastone è fin troppo pericoloso per stare nelle mani di un mortale.",
  reward = "C'è un essere al suo interno... un essere che non è di questo mondo.",
}
T[9257] = {
  title = "Atiesh, Granbastone del Guardiano",
  desc = "Quest'ultimo compito sarà il più difficile di tutti, $N. Hai affrontato e sconfitto sia un Dio Antico sia il Generale del Re dei Lich, ma ora devi affrontare la mano di Sargeras.$B$BPorta il bastone a Stratholme. È lì che troverai un lembo di terra consacrata: il suolo su cui furono assassinati i più grandi cavalieri di Lordaeron. Posa il bastone contaminato sul terreno sacro e preparati a veder erompere dal suo interno un'entità dal potere immenso... Sconfiggi l'essere demoniaco che controlla il bastone e torna da me.",
  obj = "Anachronos, alle Caverns of Time a Tanaris, vuole che porti Atiesh, Greatstaff of the Guardian a Stratholme e lo usi sulla Consecrated Earth. Sconfiggi l'entità esorcizzata dal bastone e torna da lui.",
  progress = "Non devo interferire, $R.",
  reward = "La portata di quest'impresa non va sminuita, $N. Hai fatto ciò che i più avrebbero ritenuto impossibile. Ahimè, era destino. Il bastone ha fatto la sua scelta...",
}
T[9259] = {
  title = "Traditore dei Bloodsail",
  progress = "Quel cane rognoso di Revilgaz ha offerto il perdono a tutti gli ex Bloodsail disposti a rivoltarsi contro il loro capitano! Quel succhiasentina mi ha chiesto di far fuori i miei vecchi compagni e di riportargli le loro bandane come prova.$B$BNon ho il cuore di farlo, e non lo chiederò nemmeno a te. Portami un po' di silk cloth e di tintura rossa e farò delle copie credibili. Dirò al Barone che hai cambiato bandiera, ma sappi che... ai Bloodsail non piacerà per niente!",
  reward = "Osserviamo un minuto di silenzio per i nostri compagni caduti, $N.$B$B<Il Traditore dei Bloodsail ti sorride e ti fa l'occhiolino.>$B$BEssere un traditore è una cosa, ma ammazzare i propri compari... quello sì che sarebbe davvero spregevole, eh!",
  en_title = "Traitor to the Bloodsail",
}
T[9260] = {
  title = "Indaga sul Flagello di Stormwind",
  desc = "Il Flagello si è accampato proprio alle nostre porte; non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Stormwind da questi invasori maledetti?$B $BFuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli là in alto. Hanno un significato, non ho dubbi, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quelle aberrazioni; portami la prova della loro morte insieme ai risultati delle tue indagini, e ti ricompenserò. Va'!",
  obj = "Raccogli tre Dim Necrotic Stone dal Flagello fuori da Stormwind e indaga sui cerchi runici luminosi vicino al suo accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne $Guscito tutto intero e sano di mente:uscita tutta intera e sana di mente;. L'Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of Stormwind",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.",
}
