T[9266] = {
  title = "Fare Ammenda",
  progress = "Devi averla combinata proprio grossa a noi o ai nostri amici, $N. Comunque, sono qui per offrirti un modo di riguadagnarti le nostre simpatie.$B$BCome sai, Winterspring è piuttosto fredda. Con tanti di noi goblin che arrivano da altre città, ci farebbe comodo un aiuto per stare al caldo. Portami un po' di runecloth e di carbone, e metterò una buona parola per te. Ma sta' $Gattento:attenta;: ai nostri nemici non piacerà che tu ci aiuti.",
  reward = "Grazie, $N. Sei sulla buona strada per riscattarti agli occhi della nostra bella città.",
  en_title = "Making Amends",
}
T[9267] = {
  title = "Rimarginare Vecchie Ferite",
  progress = "Faresti meglio a pensarci due volte prima di mettere piede a Ratchet, $N! Si è sparsa la voce delle tue malefatte.$B$BSei $Gfortunato:fortunata;, però: è appena arrivata una nave con molti feriti da uno scontro con i Bloodsail Buccaneers. È la tua occasione per dimostrare che non sei del tutto una canaglia. Dacci una mano portando linen cloth per le bende e fiale vuote per le pozioni.",
  reward = "Mi fa piacere che ti stia rendendo conto dei tuoi errori, $N. Continua a portare rifornimenti: non ci dimenticheremo di te così facilmente, $Gsignore:signorina;!",
  en_title = "Mending Old Wounds",
}
T[9268] = {
  title = "Guerra in Mare",
  progress = "Vuoi tornare in buoni rapporti con i goblin di Tanaris, $N? Ci servono materiali per vele e cannoni, per respingere i nostri vecchi nemici, i Bloodsail Buccaneers. Portami del mageweave e del flussante forte, e saremo sulla buona strada per perdonare le tue colpe.",
  reward = "Continua a portarne, $N. Noialtri goblin non dimentichiamo mica così facilmente!",
}
T[9269] = {
  title = "Atiesh, Gran Bastone del Guardiano",
  desc = "Quest'ultimo compito sarà il più difficile di tutti, $N. Hai affrontato e sconfitto sia un Dio Antico sia il Generale del Re dei Lich, ma ora devi affrontare la mano di Sargeras.$B$BPorta il bastone a Stratholme. È lì che troverai un lembo di terra consacrata: il suolo su cui furono assassinati i più grandi cavalieri di Lordaeron. Posa il bastone contaminato sul suolo sacro e preparati a veder erompere dal suo interno un'entità di potere immenso... Sconfiggi l'essere demoniaco che controlla il bastone e torna da me.",
  obj = "Anachronos, alle Caverns of Time di Tanaris, vuole che porti Atiesh, Greatstaff of the Guardian a Stratholme e lo usi sulla Consecrated Earth. Sconfiggi l'entità esorcizzata che esce dal bastone e torna da lui.",
  progress = "Non devo interferire, $R.",
  reward = "La portata di questa impresa non va sminuita, $N. Hai compiuto ciò che i più avrebbero ritenuto impossibile. Ahimè, era destino. Il bastone ha fatto la sua scelta...",
}
